--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
    raise debug 'PgBouncer auth request: %', p_usename;

    return query
    select 
        rolname::text, 
        case when rolvaliduntil < now() 
            then null 
            else rolpassword::text 
        end 
    from pg_authid 
    where rolname=$1 and rolcanlogin;
end;
$_$;


--
-- Name: activate_fixed_asset(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_fixed_asset(p_asset_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user  uuid := auth.uid();
  v_asset record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner')
          OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may activate fixed assets';
  END IF;

  SELECT * INTO v_asset FROM public.fixed_assets WHERE id = p_asset_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fixed asset not found';
  END IF;

  IF v_asset.status <> 'DRAFT' THEN
    RAISE EXCEPTION 'Asset % is already in status %', v_asset.asset_code, v_asset.status;
  END IF;

  UPDATE public.fixed_assets
     SET status = 'ACTIVE'
   WHERE id = p_asset_id;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'fixed_asset.activated', 'fixed_asset', p_asset_id,
          jsonb_build_object('asset_code', v_asset.asset_code, 'purchase_cost', v_asset.purchase_cost));

  RETURN true;
END $$;


--
-- Name: activate_prepaid_contract(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_prepaid_contract(p_contract_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_rec  record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner')
          OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may activate prepaid contracts';
  END IF;

  SELECT * INTO v_rec FROM public.prepaid_and_deferred_contracts WHERE id = p_contract_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contract not found';
  END IF;

  IF v_rec.status <> 'DRAFT' THEN
    RAISE EXCEPTION 'Contract % is already in status %', v_rec.contract_number, v_rec.status;
  END IF;

  UPDATE public.prepaid_and_deferred_contracts
     SET status = 'ACTIVE'
   WHERE id = p_contract_id;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'prepaid_contract.activated', 'prepaid_contract', p_contract_id,
          jsonb_build_object('contract_number', v_rec.contract_number, 'total_amount', v_rec.total_amount));

  RETURN true;
END $$;


--
-- Name: adjust_loyalty(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_loyalty(_customer uuid, _points numeric, _kind text, _note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id UUID; v_user UUID := auth.uid();
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_staff(v_user) THEN RAISE EXCEPTION 'Forbidden'; END IF;
  IF _kind NOT IN ('earn','redeem','adjust') THEN RAISE EXCEPTION 'Invalid kind'; END IF;

  INSERT INTO public.loyalty_transactions(customer_id, points, kind, note, created_by)
  VALUES (_customer, _points, _kind, _note, v_user)
  RETURNING id INTO v_id;

  UPDATE public.customers
    SET loyalty_points = GREATEST(loyalty_points + (CASE WHEN _kind='redeem' THEN -ABS(_points) ELSE ABS(_points) END), 0),
        updated_at = now()
    WHERE id = _customer;

  RETURN v_id;
END $$;


--
-- Name: apply_cost_movement(uuid, uuid, numeric, numeric, text, uuid, text, public.owner_type, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_cost_movement(p_product_id uuid, p_warehouse_id uuid, p_signed_qty numeric, p_incoming_cost numeric DEFAULT NULL::numeric, p_source_type text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_owner_type public.owner_type DEFAULT 'COMPANY'::public.owner_type, p_owner_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user     uuid := auth.uid();
  v_method   public.costing_method := public.company_costing_method();
  v_qty0     numeric := 0;
  v_val0     numeric := 0;
  v_in_cost  numeric;
  v_out_cost numeric;
  v_qty1     numeric;
  v_val1     numeric;
  v_standard numeric;
  v_pending  integer;
BEGIN
  IF p_signed_qty IS NULL OR p_signed_qty = 0 THEN
    RETURN;  -- nothing to value; not an error
  END IF;
  IF p_product_id IS NULL OR p_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'Item and location are required to value a movement';
  END IF;

  SELECT cl.quantity, cl.total_value
    INTO v_qty0, v_val0
    FROM public.item_cost_layers cl
   WHERE cl.product_id   = p_product_id
     AND cl.warehouse_id = p_warehouse_id
     AND cl.owner_type   = p_owner_type
     AND cl.owner_id IS NOT DISTINCT FROM p_owner_id
   FOR UPDATE;

  v_qty0 := coalesce(v_qty0, 0);
  v_val0 := coalesce(v_val0, 0);
  v_qty1 := round(v_qty0 + p_signed_qty, 3);

  IF p_signed_qty > 0 THEN
    IF v_method = 'STANDARD' THEN
      SELECT p.standard_cost INTO v_standard
        FROM public.products p WHERE p.id = p_product_id;

      IF v_standard IS NULL OR v_standard = 0 THEN
        -- Name how many items are blocking, so the operator is not left with
        -- one error per receipt and no idea of the size of the job.
        SELECT count(*)::int INTO v_pending
          FROM public.standard_cost_readiness;
        RAISE EXCEPTION
          'Standard cost is not set for this item (%). % more tracked item(s) also lack one - see standard_cost_readiness.',
          p_product_id, v_pending;
      END IF;

      v_in_cost := v_standard;
    ELSE
      v_in_cost := coalesce(
        p_incoming_cost,
        CASE WHEN v_qty0 > 0 THEN round(v_val0 / v_qty0, 4) END,
        (SELECT p.cost_price FROM public.products p WHERE p.id = p_product_id),
        0
      );
    END IF;

    v_val1 := v_val0 + round(p_signed_qty * v_in_cost, 2);

  ELSE
    IF v_qty0 <= 0 THEN
      v_out_cost := coalesce(
        (SELECT p.standard_cost FROM public.products p
          WHERE p.id = p_product_id AND v_method = 'STANDARD'),
        (SELECT p.cost_price FROM public.products p WHERE p.id = p_product_id),
        0
      );
    ELSE
      v_out_cost := round(v_val0 / v_qty0, 4);
    END IF;

    v_val1 := v_val0 - round(abs(p_signed_qty) * v_out_cost, 2);
    IF v_qty1 <= 0 OR v_val1 < 0 THEN
      v_val1 := 0;
    END IF;
  END IF;

  INSERT INTO public.item_cost_layers
    (product_id, warehouse_id, owner_type, owner_id, quantity, total_value,
     valuation_method, last_unit_cost, last_movement_at, updated_at)
  VALUES
    (p_product_id, p_warehouse_id, p_owner_type, p_owner_id, v_qty1, v_val1,
     v_method,
     coalesce(p_incoming_cost, v_in_cost, v_out_cost, 0),
     now(), now())
  ON CONFLICT (product_id, warehouse_id, owner_type, owner_id)
  DO UPDATE SET quantity         = EXCLUDED.quantity,
                total_value      = EXCLUDED.total_value,
                valuation_method = EXCLUDED.valuation_method,
                last_unit_cost   = EXCLUDED.last_unit_cost,
                last_movement_at = now(),
                updated_at       = now();

  -- The ledger records what was ACTUALLY paid, never the valuation it was
  -- given. Under STANDARD the two differ, and that gap IS the variance the
  -- method exists to expose.
  INSERT INTO public.item_cost_transactions
    (product_id, warehouse_id, owner_type, owner_id, direction, quantity,
     unit_cost, value, method, quantity_before, value_before,
     quantity_after, value_after, source_type, source_id, note)
  VALUES
    (p_product_id, p_warehouse_id, p_owner_type, p_owner_id,
     CASE WHEN p_signed_qty > 0 THEN 'IN' ELSE 'OUT' END,
     abs(p_signed_qty),
     coalesce(p_incoming_cost, 0),
     round(abs(p_signed_qty) * coalesce(p_incoming_cost, 0), 2),
     v_method, v_qty0, v_val0, v_qty1, v_val1,
     p_source_type, p_source_id, p_note);

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'cost.movement_applied', 'product', p_product_id,
    jsonb_build_object(
      'warehouse_id', p_warehouse_id, 'method', v_method,
      'direction', CASE WHEN p_signed_qty > 0 THEN 'IN' ELSE 'OUT' END,
      'quantity', abs(p_signed_qty),
      'actual_cost', coalesce(p_incoming_cost, 0),
      'valuation_cost', coalesce(v_in_cost, v_out_cost, 0),
      'quantity_after', v_qty1, 'value_after', v_val1,
      'source_type', p_source_type, 'source_id', p_source_id));
END $$;


--
-- Name: approve_item_policy_change(uuid, public.item_nature, public.inventory_policy, public.costing_method, public.item_tracking, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_item_policy_change(_item_id uuid, _new_nature public.item_nature, _new_policy public.inventory_policy, _new_costing public.costing_method, _new_tracking public.item_tracking, _reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user    uuid := auth.uid();
  v_before  jsonb;
  v_after   jsonb;
  v_product public.products%ROWTYPE;
  v_balance numeric;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN
    RAISE EXCEPTION 'Only an owner or manager may approve an item policy change';
  END IF;

  IF coalesce(btrim(_reason), '') = '' THEN
    RAISE EXCEPTION 'A written reason is required for every policy change';
  END IF;

  SELECT * INTO v_product FROM public.products WHERE id = _item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item % does not exist', _item_id;
  END IF;

  -- ------------------------------------------------------------------ rules
  -- Rule 2: a SERVICE is not a way to switch stock off, and it can never hold
  -- a stock balance. Allowing SERVICE + TRACKED would resurrect the exact
  -- workaround this project is removing.
  IF _new_nature = 'SERVICE' AND _new_policy <> 'UNTRACKED' THEN
    RAISE EXCEPTION 'A SERVICE can only be UNTRACKED';
  END IF;

  IF _new_policy = 'UNTRACKED' AND _new_tracking <> 'NONE' THEN
    RAISE EXCEPTION 'An UNTRACKED item cannot require batch or serial tracking';
  END IF;

  IF _new_costing = 'NONE' AND _new_policy <> 'UNTRACKED' THEN
    RAISE EXCEPTION 'Costing method NONE is only valid for an UNTRACKED item';
  END IF;

  -- Moving a good OUT of tracking while it still holds stock would orphan that
  -- stock. The operator must clear the balance first (sell it, adjust it to
  -- zero, or move it to a customer-owned position) so the numbers stay honest.
  SELECT coalesce(sum(i.quantity), 0)
    INTO v_balance
  FROM public.inventory i
  WHERE i.product_id = _item_id
    AND i.owner_type = 'COMPANY'
    AND i.owner_id IS NULL;

  IF _new_policy <> 'TRACKED'
     AND v_product.inventory_policy = 'TRACKED'
     AND v_balance <> 0 THEN
    RAISE EXCEPTION
      'Item % still holds % units. Clear the balance with an adjustment before leaving TRACKED.',
      _item_id, v_balance;
  END IF;

  -- A tracked item needs a costing method that can actually value it.
  IF _new_policy = 'TRACKED' AND _new_costing = 'NONE' THEN
    RAISE EXCEPTION 'A TRACKED item requires a costing method other than NONE';
  END IF;

  v_before := jsonb_build_object(
    'item_nature', v_product.item_nature,
    'inventory_policy', v_product.inventory_policy,
    'costing_method', v_product.costing_method,
    'tracking', v_product.tracking
  );
  v_after := jsonb_build_object(
    'item_nature', _new_nature,
    'inventory_policy', _new_policy,
    'costing_method', _new_costing,
    'tracking', _new_tracking
  );

  -- Open the guard for this transaction only. set_config(..., true) is
  -- transaction-scoped, so the exemption cannot leak to another statement.
  PERFORM set_config('app.allow_policy_change', 'on', true);

  UPDATE public.products
  SET item_nature      = _new_nature,
      inventory_policy = _new_policy,
      costing_method   = _new_costing,
      tracking         = _new_tracking,
      updated_at       = now()
  WHERE id = _item_id;

  -- ⚠️ كان الوسيط الخامس هو نص السبب (btrim(_reason)) بينما توقيع الدالة
  --    p_source text — أي أن "المصدر" يُكتب داخل payload.source_document
  --    ويضيع السبب. أُصلح ليمرّر السبب في مكانه الصحيح، والمصدر ثابت.
  RETURN public.audit_item_policy_snapshot(
    _item_id,
    'item_policy.changed',
    v_before,
    v_after,
    'approval:' || btrim(_reason)
  );
END $$;


--
-- Name: assert_payment_splits_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_payment_splits_balance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_split_total numeric := 0;
  v_paid numeric;
  v_total numeric;
  v_document_type text;
  v_document_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_document_type := OLD.document_type;
    v_document_id := OLD.document_id;
  ELSE
    v_document_type := NEW.document_type;
    v_document_id := NEW.document_id;
  END IF;

  SELECT round(coalesce(sum(amount), 0), 2) INTO v_split_total
    FROM public.payment_splits
   WHERE document_type = v_document_type AND document_id = v_document_id;

  IF v_document_type = 'purchase_invoice' THEN
    SELECT pi.paid, pi.total INTO v_paid, v_total
      FROM public.purchase_invoices pi WHERE pi.id = v_document_id;
  ELSE
    SELECT si.paid, si.total
      INTO v_paid, v_total
      FROM public.milling_service_documents d
      JOIN public.sales_invoices si ON si.id = d.sales_invoice_id
     WHERE d.id = v_document_id;
  END IF;

  IF v_total IS NULL THEN
    RAISE EXCEPTION 'Record the document before its payment split';
  END IF;
  IF v_split_total > round(v_total, 2) THEN
    RAISE EXCEPTION 'Payment split total (%) exceeds the document total (%)',
      v_split_total, round(v_total, 2);
  END IF;
  IF v_split_total <> round(coalesce(v_paid, 0), 2) THEN
    RAISE EXCEPTION 'Payment split total (%) does not match the paid amount (%)',
      v_split_total, round(coalesce(v_paid, 0), 2);
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: assert_period_open(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_period_open(p_date date) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  IF p_date IS NULL THEN
    RETURN;
  END IF;

  SELECT status INTO v_status
    FROM public.fiscal_periods
   WHERE p_date BETWEEN start_date AND end_date
   LIMIT 1;

  -- تاريخ خارج أي فترة مُعرَّفة: يُسمح به (فترة غير مفتوحة بعد). القفل يُطبَّق
  -- على الفترات المُعرَّفة والمقفلة فقط، لا على تاريخ لا تنظيم له.
  IF v_status IS NULL THEN
    RETURN;
  END IF;

  IF v_status = 'CLOSED' THEN
    RAISE EXCEPTION
      'الفترة المالية المحتوية على % مقفلة. لا يمكن الترحيل بتاريخ مقفول.',
      to_char(p_date, 'YYYY-MM-DD');
  END IF;
END $$;


--
-- Name: FUNCTION assert_period_open(p_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.assert_period_open(p_date date) IS 'T-19: يرفض الترحيل داخل فترة مقفلة. التواريخ خارج الفترات المُعرَّفة تُسمح.';


--
-- Name: audit_item_policy_snapshot(uuid, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_item_policy_snapshot(p_item_id uuid, p_action text, p_before jsonb, p_after jsonb, p_source text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  -- ⚠️ audit_logs.action و entity_type هما NOT NULL: تمرير NULL كان يرمي
  --    23502 بدل تسجيل الحدث. نضع قيمًا افتراضية صريحة حتى لو نادت الدالة
  --    دالة جديدة بنفس العقد بلا وسيط.
  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (
    auth.uid(),
    coalesce(nullif(btrim(p_action), ''), 'item_policy.updated'),
    'product_policy',
    p_item_id,
    jsonb_build_object(
      'before', p_before,
      'after', p_after,
      'source_document', p_source,
      'recorded_at', now()
    )
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END $$;


--
-- Name: backup_export_all(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backup_export_all(p_max_log_rows integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  tbl record;
  v_result jsonb;
  v_tables_payload jsonb := '{}'::jsonb;
  v_row_count bigint;
  v_total_rows bigint := 0;
  v_table_count integer := 0;
  v_capped integer := 0;
  v_q text;
  v_rows jsonb;
BEGIN
  -- ⚠️ superadmin المنصة (المستخدمون في platform_admins) يملكون دور متجر 'owner'
  --    من البذرة، لكن لو أُنشئ حساب سوبر أدمن جديد بلا دور المتجر لُحجب عنه
  --    التصدير رغم أن كل صلاحيات المنصة له. القاعدة: إما دور مالك/مدير،
  --    أو سوبر أدمن منصة. (backup_restore_all يشترط owner فقط — بقصد الاستعادة.)
  IF v_caller IS NULL
     OR NOT (public.has_role(v_caller, 'owner')
             OR public.has_role(v_caller, 'manager')
             OR public.is_platform_superadmin(v_caller)) THEN
    RAISE EXCEPTION 'BACKUP_AUTH: backup export requires owner, manager or platform superadmin'
      USING HINT = 'لا يملك المستدعي صلاحية تصدير النسخ الاحتياطية';
  END IF;

  FOR tbl IN
    SELECT t.table_name
    FROM information_schema.tables t
    WHERE t.table_schema = 'public' AND t.table_type = 'BASE TABLE'
    ORDER BY t.table_name
  LOOP
    DECLARE
      v_cap integer := NULL;
    BEGIN
      -- جداول السجل الضخمة: أحدث N صفًا فقط (بترتيب created_at) لتجنب نفاد الذاكرة.
      IF tbl.table_name IN ('audit_logs', 'backup_logs', 'idempotency_keys') THEN
        v_cap := p_max_log_rows;
        v_capped := v_capped + 1;
      END IF;

      IF v_cap IS NOT NULL THEN
        v_q := format(
          'SELECT count(*)::bigint AS cnt, coalesce(jsonb_agg(to_jsonb(s)), ''[]''::jsonb) AS rows
           FROM (SELECT * FROM public.%I ORDER BY created_at DESC LIMIT %s) s',
          tbl.table_name, v_cap
        );
      ELSE
        v_q := format(
          'SELECT count(*)::bigint AS cnt, coalesce(jsonb_agg(to_jsonb(s)), ''[]''::jsonb) AS rows
           FROM public.%I s',
          tbl.table_name
        );
      END IF;

      EXECUTE v_q INTO v_row_count, v_rows;

      v_tables_payload := jsonb_set(v_tables_payload, ARRAY[tbl.table_name], v_rows);
      v_total_rows := v_total_rows + v_row_count;
      v_table_count := v_table_count + 1;
    END;
  END LOOP;

  v_result := jsonb_build_object(
    'kind', 'server_dynamic_export',
    'exported_at', now(),
    'schema_fingerprint', public.backup_schema_fingerprint(),
    'table_count', v_table_count,
    'total_rows', v_total_rows,
    'capped_log_tables', v_capped,
    'tables', v_tables_payload
  );

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION backup_export_all(p_max_log_rows integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.backup_export_all(p_max_log_rows integer) IS 'Server-side dynamic full backup: reads every public base table from information_schema at call time (adapts to any migration), guarded to owner/manager.';


--
-- Name: backup_restore_all(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backup_restore_all(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_caller uuid := auth.uid();
  v_tables jsonb;
  v_t text;
  v_rows jsonb;
  v_inserted bigint;
  v_total bigint := 0;
  v_skipped jsonb := '[]'::jsonb;
  v_payload_fingerprint text;
  v_current_fingerprint text;
  v_fingerprint_mismatch boolean := false;
  v_q text;
BEGIN
  IF v_caller IS NULL OR NOT public.has_role(v_caller, 'owner') THEN
    RAISE EXCEPTION 'BACKUP_AUTH: backup restore requires owner role'
      USING HINT = 'الاستعادة متاحة لمالك المتجر فقط';
  END IF;

  IF p_payload->>'kind' IS DISTINCT FROM 'server_dynamic_export'
     OR jsonb_typeof(p_payload->'tables') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'BACKUP_FORMAT: payload is not a server_dynamic_export backup'
      USING HINT = 'صيغة الحمولة غير صالحة — استخدم نسخة من backup_export_all';
  END IF;

  v_payload_fingerprint := p_payload->>'schema_fingerprint';
  v_current_fingerprint := public.backup_schema_fingerprint();
  IF v_payload_fingerprint IS NOT NULL
     AND v_current_fingerprint IS NOT NULL
     AND v_payload_fingerprint <> v_current_fingerprint THEN
    v_fingerprint_mismatch := true;  -- تحذير لا إيقاف: قد تكون مهاجرة جديدة بعد النسخة
    RAISE NOTICE 'BACKUP_SCHEMA_DRIFT: backup fingerprint % != current % (tables/columns changed since backup)',
      v_payload_fingerprint, v_current_fingerprint;
  END IF;

  v_tables := p_payload->'tables';

  -- (ج) تعطيل مفاتيح التحقق مؤقتًا داخل الجلسة
  EXECUTE 'SET LOCAL session_replication_role = replica';

  -- (د-1) تفريغ كل جداول public الأساسية — حتى غير المذكورة في الحمولة
  EXECUTE format(
    'TRUNCATE TABLE %s RESTART IDENTITY CASCADE',
    (
      SELECT string_agg(quote_ident(t.table_name), ', ' ORDER BY t.table_name)
      FROM information_schema.tables t
      WHERE t.table_schema = 'public' AND t.table_type = 'BASE TABLE'
    )
  );

  -- (د-2) إدراج الصفوف، جدولًا جدولًا، بالاسم لا بالترتيب
  FOR v_t, v_rows IN
    SELECT key, value FROM jsonb_each(v_tables)
  LOOP
    -- تجاهل الجداول غير الموجودة في المخطط الحالي (حُذف جدول بعد النسخة)
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.tables t
      WHERE t.table_schema = 'public' AND t.table_name = v_t AND t.table_type = 'BASE TABLE'
    ) THEN
      RAISE NOTICE 'BACKUP_SKIP_TABLE: % not found in current schema', v_t;
      v_skipped := v_skipped || to_jsonb(v_t);
      CONTINUE;
    END IF;

    IF jsonb_typeof(v_rows) = 'array' AND jsonb_array_length(v_rows) > 0 THEN
      v_q := format(
        'INSERT INTO public.%I SELECT * FROM jsonb_populate_recordset(NULL::public.%I, $1)',
        v_t, v_t
      );
      EXECUTE v_q USING v_rows;
      GET DIAGNOSTICS v_inserted = ROW_COUNT;
      v_total := v_total + v_inserted;
    END IF;
  END LOOP;

  -- (ج) إعادة المفاتيح
  EXECUTE 'SET LOCAL session_replication_role = DEFAULT';

  -- (هـ) إعادة ضبط sequences (serial/bigserial) لقيم الأعمدة المدرجة
  DECLARE
    v_col text;
  BEGIN
    FOR v_t, v_col IN
      SELECT c.table_name, c.column_name
      FROM information_schema.columns c
      JOIN information_schema.sequences s
        ON s.sequence_schema = 'public'
      WHERE c.table_schema = 'public'
        AND c.column_default LIKE 'nextval(%'
    LOOP
      EXECUTE format(
        'SELECT setval(pg_get_serial_sequence(%L::text, %L::text),
                       coalesce((SELECT max(%I) FROM public.%I), 1))',
        'public.' || v_t, v_col, v_col, v_t
      );
    END LOOP;
  END;

  RETURN jsonb_build_object(
    'restored_at', now(),
    'inserted_rows', v_total,
    'skipped_tables', v_skipped,
    'schema_fingerprint_mismatch', v_fingerprint_mismatch,
    'current_fingerprint', v_current_fingerprint
  );
END;
$_$;


--
-- Name: FUNCTION backup_restore_all(p_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.backup_restore_all(p_payload jsonb) IS 'Server-side full restore in a single transaction: truncates all public tables, reinserts by column name, resets sequences. Owner-only.';


--
-- Name: backup_schema_fingerprint(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backup_schema_fingerprint() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT encode(sha256(
    convert_to(
      coalesce(string_agg(
      t.table_name || '(' ||
      (
        SELECT string_agg(c.column_name || ':' || c.data_type, ',' ORDER BY c.ordinal_position)
        FROM information_schema.columns c
        WHERE c.table_schema = 'public' AND c.table_name = t.table_name
      ) || ')'
    , '|' ORDER BY t.table_name), ''), 'UTF8')
  ), 'hex')
  FROM information_schema.tables t
  WHERE t.table_schema = 'public'
    AND t.table_type = 'BASE TABLE';
$$;


--
-- Name: FUNCTION backup_schema_fingerprint(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.backup_schema_fingerprint() IS 'SHA-256 fingerprint of the public schema (tables + columns + types). Differing fingerprints between backup and restore signal schema drift.';


--
-- Name: balance_and_post_return(text, date, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.balance_and_post_return(p_memo text, p_date date, p_source_type text, p_source_id uuid, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_d numeric := 0;
  v_c numeric := 0;
  v_diff numeric;
  r jsonb;
  v_lines jsonb := p_lines;
BEGIN
  FOR r IN SELECT * FROM jsonb_array_elements(v_lines) LOOP
    v_d := v_d + coalesce((r->>'debit')::numeric, 0);
    v_c := v_c + coalesce((r->>'credit')::numeric, 0);
  END LOOP;

  v_diff := round(v_d - v_c, 2);
  IF v_diff <> 0 THEN
    -- فرق الهامش (سعر البيع مقابل التكلفة) في المرتجع. يُكتب على 5911 —
    -- الحساب المخصص للتسويات في الدليل — فيظهر في ميزان المراجعة ولا يُخفى.
    IF v_diff > 0 THEN
      v_lines := v_lines || jsonb_build_object(
        'account_code', '5911', 'credit', v_diff, 'memo', 'فارق قيمة المرتجع');
    ELSE
      v_lines := v_lines || jsonb_build_object(
        'account_code', '5911', 'debit', -v_diff, 'memo', 'فارق قيمة المرتجع');
    END IF;
  END IF;

  RETURN public.create_journal_entry(p_memo, p_date, p_source_type, p_source_id, true, v_lines);
END $$;


--
-- Name: FUNCTION balance_and_post_return(p_memo text, p_date date, p_source_type text, p_source_id uuid, p_lines jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.balance_and_post_return(p_memo text, p_date date, p_source_type text, p_source_id uuid, p_lines jsonb) IS 'توازن سطور قيد مرتجع (يكتب فرق الهامش على 5911) ثم يسجّل قيدًا مزدوجًا.';


--
-- Name: bounce_cheque(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bounce_cheque(p_cheque_id uuid, p_reason text DEFAULT 'عدم كفاية الرصيد'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_cheque record;
  v_lines jsonb := '[]'::jsonb;
  v_journal uuid;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (
    public.has_role(v_user, 'owner')
    OR public.has_role(v_user, 'manager')
    OR public.has_role(v_user, 'accountant')
  ) THEN
    RAISE EXCEPTION 'Only accountant, manager or owner may mark cheques as bounced';
  END IF;

  SELECT * INTO v_cheque
  FROM public.cheques_register
  WHERE id = p_cheque_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cheque not found';
  END IF;

  IF v_cheque.status <> 'UNDER_COLLECTION' THEN
    RAISE EXCEPTION 'Cannot bounce cheque in status %', v_cheque.status;
  END IF;

  -- قيد الارتداد: إعادة المديونية للعميل وإلغاء ورقة القبض
  -- Dr 1211 (ذمم العملاء) / Cr 1221 (أوراق قبض)
  IF v_cheque.customer_id IS NOT NULL THEN
    v_lines := v_lines
      || jsonb_build_object(
        'account_code', '1211',
        'debit', v_cheque.amount,
        'memo', 'ارتداد شيك رقم ' || v_cheque.cheque_number || ' — ' || coalesce(p_reason, '')
      )
      || jsonb_build_object(
        'account_code', '1221',
        'credit', v_cheque.amount,
        'memo', 'إلغاء ورقة قبض لشيك مرتد رقم ' || v_cheque.cheque_number
      );

    v_journal := public.create_journal_entry(
      'ارتداد شيك رقم ' || v_cheque.cheque_number || ' — ' || coalesce(p_reason, ''),
      CURRENT_DATE,
      'cheque_bounce',
      v_cheque.id,
      true,
      v_lines
    );

    -- تسجيل حركة مدينة في كشف حساب العميل
    INSERT INTO public.customer_ledger(
      customer_id, entry_type, debit, reference_id, reference_type, occurred_at, created_by, source_key, note
    )
    VALUES (
      v_cheque.customer_id, 'adjustment', v_cheque.amount, v_cheque.id, 'cheque_bounce',
      now(), v_user, 'cheque_bounce:' || v_cheque.id, 'ارتداد شيك رقم ' || v_cheque.cheque_number
    )
    ON CONFLICT (source_key) DO NOTHING;
  END IF;

  UPDATE public.cheques_register
  SET status = 'BOUNCED',
      notes = coalesce(notes || ' | ', '') || 'مرتد: ' || coalesce(p_reason, ''),
      updated_at = now()
  WHERE id = p_cheque_id;

  RETURN jsonb_build_object(
    'cheque_id', p_cheque_id,
    'cheque_number', v_cheque.cheque_number,
    'status', 'BOUNCED',
    'journal_id', v_journal
  );
END;
$$;


--
-- Name: can_author_payment_methods(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_author_payment_methods() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
