      OR public.has_role(auth.uid(), 'owner')
      OR public.has_role(auth.uid(), 'manager');
$$;


--
-- Name: FUNCTION can_author_payment_methods(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_author_payment_methods() IS 'هل يملك المستخدم الحالي حق تسمية/أيقنة/إنشاء طرق دفع؟ صاحب المنشأة والمدير وسوبر أدمن المنصة.';


--
-- Name: can_operate_milling(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_operate_milling() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.is_staff(auth.uid())
     AND EXISTS (
       SELECT 1
       FROM public.user_roles ur
       WHERE ur.user_id = auth.uid()
         AND ur.role IN ('owner', 'manager', 'warehouse', 'cashier')
     );
$$;


--
-- Name: can_read_expense_entry(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_expense_entry(p_entry_id uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.can_read_finance(p_user)
      OR (public.is_staff(p_user) AND EXISTS (
            SELECT 1 FROM public.expense_entries e
            WHERE e.id = p_entry_id AND e.created_by = p_user))
$$;


--
-- Name: can_read_finance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_finance(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.is_staff(p_user) AND public.expense_role_rank(p_user) >= 30
$$;


