    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.is_staff(auth.uid())
     AND EXISTS (
       SELECT 1
       FROM public.user_roles ur
       WHERE ur.user_id = auth.uid()
         AND ur.role IN ('owner', 'manager', 'accountant', 'warehouse', 'cashier')
     );
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: expense_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.expense_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reference text NOT NULL,
    entry_type public.expense_entry_type DEFAULT 'DIRECT'::public.expense_entry_type NOT NULL,
    status public.expense_status DEFAULT 'DRAFT'::public.expense_status NOT NULL,
    source_kind public.expense_source_kind DEFAULT 'MANUAL'::public.expense_source_kind NOT NULL,
    payee_type public.expense_payee_type DEFAULT 'NONE'::public.expense_payee_type NOT NULL,
    payee_name text,
    supplier_id uuid,
    employee_id uuid,
    warehouse_id uuid,
    cost_center_id uuid,
    project_id uuid,
    expense_date date DEFAULT CURRENT_DATE NOT NULL,
    due_date date,
    posting_date date,
    description text,
    note text,
    total_amount numeric(18,2) DEFAULT 0 NOT NULL,
    paid_amount numeric(18,2) DEFAULT 0 NOT NULL,
    remaining_amount numeric(18,2) GENERATED ALWAYS AS ((total_amount - paid_amount)) STORED,
    tax_mode public.expense_tax_mode DEFAULT 'NONE'::public.expense_tax_mode NOT NULL,
    currency text DEFAULT 'YER'::text NOT NULL,
    currency_symbol text DEFAULT '﷼'::text NOT NULL,
    line_count integer DEFAULT 0 NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_by uuid,
    submitted_by uuid,
    submitted_at timestamp with time zone,
    approved_by uuid,
    approved_at timestamp with time zone,
    rejected_by uuid,
    rejected_at timestamp with time zone,
    rejection_reason text,
    posted_by uuid,
    posted_at timestamp with time zone,
    cancelled_by uuid,
    cancelled_at timestamp with time zone,
    cancel_reason text,
    reversal_of uuid,
    reversed_by_id uuid,
    legacy_expense_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT expense_entries_dates_ordered CHECK (((posting_date IS NULL) OR (posting_date >= (expense_date - 366)))),
    CONSTRAINT expense_entries_due_after_expense CHECK (((due_date IS NULL) OR (due_date >= expense_date))),
    CONSTRAINT expense_entries_paid_non_negative CHECK ((paid_amount >= (0)::numeric)),
    CONSTRAINT expense_entries_paid_requires_post CHECK (((paid_amount = (0)::numeric) OR (status = ANY (ARRAY['POSTED'::public.expense_status, 'PARTIALLY_PAID'::public.expense_status, 'PAID'::public.expense_status, 'CLOSED'::public.expense_status, 'REVERSED'::public.expense_status])))),
    CONSTRAINT expense_entries_paid_within_total CHECK ((paid_amount <= (total_amount + 0.005))),
    CONSTRAINT expense_entries_payee_consistent CHECK ((((payee_type = 'SUPPLIER'::public.expense_payee_type) AND (supplier_id IS NOT NULL) AND (employee_id IS NULL)) OR ((payee_type = 'EMPLOYEE'::public.expense_payee_type) AND (employee_id IS NOT NULL) AND (supplier_id IS NULL)) OR ((payee_type = ANY (ARRAY['NONE'::public.expense_payee_type, 'OTHER'::public.expense_payee_type])) AND (supplier_id IS NULL) AND (employee_id IS NULL)))),
    CONSTRAINT expense_entries_reference_not_blank CHECK ((btrim(reference) <> ''::text)),
    CONSTRAINT expense_entries_total_non_negative CHECK ((total_amount >= (0)::numeric))
);


--
-- Name: cancel_expense(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_expense(p_entry_id uuid, p_reason text, p_expected_version integer DEFAULT NULL::integer) RETURNS public.expense_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user  uuid := public.expense_actor();
  v_entry public.expense_entries;
  v_from  public.expense_status;
BEGIN
  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';
  END IF;

  v_from := v_entry.status;

  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A reason is required when cancelling an expense' USING ERRCODE = '22023';
  END IF;

  IF v_from IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED', 'REVERSED') THEN
    RAISE EXCEPTION 'A posted expense cannot be cancelled — reverse it instead'
      USING ERRCODE = '55000';
  END IF;

  IF v_from = 'CANCELLED' THEN
    RETURN v_entry;   -- idempotent
  END IF;

  IF v_from NOT IN ('DRAFT', 'REJECTED', 'SUBMITTED', 'APPROVED') THEN
    RAISE EXCEPTION 'This expense cannot be cancelled from status %', v_from
      USING ERRCODE = '55000';
  END IF;

  -- Cancelling someone else's submitted document is a management decision, not
  -- a data-entry correction.
  IF NOT (v_entry.created_by = v_user AND v_from IN ('DRAFT', 'REJECTED')) THEN
    PERFORM public.expense_assert_capability(v_user, 'expense.cancel');
  ELSE
    PERFORM public.expense_assert_capability(v_user, 'expense.edit');
  END IF;

  IF p_expected_version IS NOT NULL AND p_expected_version <> v_entry.version THEN
    RAISE EXCEPTION 'This expense was changed by someone else. Reload it and try again.'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.expense_entries
     SET status        = 'CANCELLED',
         cancelled_by  = v_user,
         cancelled_at  = now(),
         cancel_reason = nullif(btrim(p_reason), ''),
         version       = version + 1
   WHERE id = p_entry_id
  RETURNING * INTO v_entry;

  PERFORM public.expense_log_action(p_entry_id, 'cancelled', v_from, 'CANCELLED', p_reason, v_user);

  RETURN v_entry;
END $$;


--
-- Name: clear_cheque(uuid, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_cheque(p_cheque_id uuid, p_clearing_bank_account_id uuid, p_cleared_date date DEFAULT CURRENT_DATE, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_cheque record;
  v_bank_code text;
  v_lines jsonb := '[]'::jsonb;
  v_journal uuid;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (
    public.has_role(v_user, 'owner')
    OR public.has_role(v_user, 'manager')
    OR public.has_role(v_user, 'accountant')
  ) THEN
    RAISE EXCEPTION 'Only accountant, manager or owner may clear cheques';
  END IF;

  SELECT * INTO v_cheque
  FROM public.cheques_register
  WHERE id = p_cheque_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cheque not found';
  END IF;

  IF v_cheque.status <> 'UNDER_COLLECTION' THEN
    RAISE EXCEPTION 'Cheque % is already %', v_cheque.cheque_number, v_cheque.status;
  END IF;

  -- كود الحساب البنكي المودع فيه
  SELECT a.code INTO v_bank_code
  FROM public.company_bank_accounts b
  JOIN public.accounts a ON a.id = b.account_id
  WHERE b.id = p_clearing_bank_account_id;

  IF v_bank_code IS NULL THEN
    RAISE EXCEPTION 'Selected clearing bank account has no valid ledger account';
  END IF;

  -- قيد التحصيل: من حـ/ البنك إلى حـ/ أوراق قبض
  v_lines := v_lines
    || jsonb_build_object(
      'account_code', v_bank_code,
      'debit', v_cheque.amount,
      'memo', 'تحصيل وإيداع شيك رقم ' || v_cheque.cheque_number
    )
    || jsonb_build_object(
      'account_code', '1221',
      'credit', v_cheque.amount,
      'memo', 'إقفال أوراق قبض — شيك رقم ' || v_cheque.cheque_number
    );

  v_journal := public.create_journal_entry(
    'تحصيل شيك مصرفي رقم ' || v_cheque.cheque_number || ' — ' || coalesce(p_notes, ''),
    coalesce(p_cleared_date, CURRENT_DATE),
    'cheque_clearing',
    v_cheque.id,
    true,
    v_lines
  );

  UPDATE public.cheques_register
  SET status = 'CLEARED',
      clearing_bank_account_id = p_clearing_bank_account_id,
      clearing_journal_entry_id = v_journal,
      cleared_at = coalesce(p_cleared_date, CURRENT_DATE)::timestamptz,
      notes = coalesce(notes || ' | ', '') || coalesce(p_notes, 'تم التحصيل بالبنك'),
      updated_at = now()
  WHERE id = p_cheque_id;

  RETURN jsonb_build_object(
    'cheque_id', p_cheque_id,
    'cheque_number', v_cheque.cheque_number,
    'status', 'CLEARED',
    'journal_id', v_journal
  );
END;
$$;


--
-- Name: close_expense(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_expense(p_entry_id uuid) RETURNS public.expense_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user  uuid := public.expense_actor();
  v_entry public.expense_entries;
BEGIN
  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.expense_assert_capability(v_user, 'expense.post');

  IF v_entry.status = 'CLOSED' THEN
    RETURN v_entry;
  END IF;
  IF v_entry.status NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID') THEN
    RAISE EXCEPTION 'Only a posted expense can be closed (current: %)', v_entry.status
      USING ERRCODE = '55000';
  END IF;
  IF v_entry.remaining_amount > 0.005 THEN
    RAISE EXCEPTION 'This expense still has % outstanding', v_entry.remaining_amount
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.expense_entries
     SET status = 'CLOSED', version = version + 1
   WHERE id = p_entry_id
  RETURNING * INTO v_entry;

  PERFORM public.expense_log_action(p_entry_id, 'closed', 'PAID', 'CLOSED', NULL, v_user);

  RETURN v_entry;
END $$;


--
-- Name: close_fiscal_year(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_fiscal_year(p_year integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user      uuid := auth.uid();
  v_close_date date;
  v_period    record;
  v_lines     jsonb;
  v_entry_id  uuid;
  v_net       numeric;
  v_existing  uuid;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT (public.has_role(v_user, 'owner')
          OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may close a fiscal year';
  END IF;

  v_close_date := make_date(p_year, 12, 31);

  -- فترة الإقفال يجب أن تكون مفتوحة: الإقفال يكتب قيدًا داخلها.
  SELECT * INTO v_period
    FROM public.fiscal_periods
   WHERE v_close_date BETWEEN start_date AND end_date;
  IF FOUND AND v_period.status = 'CLOSED' THEN
    RAISE EXCEPTION
      'فترة % مقفلة. لا يمكن إقفال سنة مقفلة بالفعل، أو فتح السنة قبل إقفالها.',
      v_period.code;
  END IF;

  -- لا إقفال مزدوج: قيد إقفال قائم لنفس السنة يُرفض.
  SELECT id INTO v_existing
    FROM public.journal_entries
   WHERE source_type = 'fiscal_year_close'
     AND source_id IS NULL
     AND memo LIKE '%' || p_year::text || '%'
     AND status = 'POSTED'
   LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RAISE EXCEPTION 'السنة % أُقفلت بالفعل (قيد %).', p_year, v_existing;
  END IF;

  -- قيد الإقفال: عكس طبيعة كل حساب 4xxx/5xxx لجعل رصيده صفرًا.
  -- الإيراد (رصيده دائن) يُمدَّن؛ المصروف (رصيده مدين) يُدان.
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'account_code', a.code,
           'debit',  CASE WHEN a.account_type = 'REVENUE' THEN t.bal ELSE 0 END,
           'credit', CASE WHEN a.account_type = 'EXPENSE' THEN -t.bal ELSE 0 END,
           'memo',   'إقفال سنة ' || p_year::text || ' — ' || a.name_ar
         )), '[]'::jsonb)
    INTO v_lines
    FROM (
      SELECT jl.account_id,
             sum(jl.debit - jl.credit) AS bal
        FROM public.journal_lines jl
        JOIN public.journal_entries je
          ON je.id = jl.entry_id AND je.status = 'POSTED'
       WHERE je.entry_date BETWEEN make_date(p_year, 1, 1) AND v_close_date
       GROUP BY jl.account_id
      HAVING sum(jl.debit - jl.credit) <> 0
    ) AS t
    JOIN public.accounts a ON a.id = t.account_id
   WHERE a.account_type IN ('REVENUE','EXPENSE');

  -- لا شيء يُقفل: سنة بلا حركة 4xxx/5xxx. لا قيد فارغ.
  IF v_lines IS NULL OR jsonb_array_length(v_lines) = 0 THEN
    RAISE EXCEPTION 'لا توجد أرصدة إيراد أو مصروف لسنة % لإقفالها.', p_year;
  END IF;

  -- صافي الربح = مجموع (دائن الإيراد − مدين المصروف) = سالب مجموع bal لكل 4xxx/5xxx.
  SELECT -sum(t.bal) INTO v_net
    FROM (
      SELECT sum(jl.debit - jl.credit) AS bal
        FROM public.journal_lines jl
        JOIN public.journal_entries je
          ON je.id = jl.entry_id AND je.status = 'POSTED'
       WHERE je.entry_date BETWEEN make_date(p_year, 1, 1) AND v_close_date
       GROUP BY jl.account_id
    ) AS t
    JOIN public.accounts a ON a.id = t.account_id
   WHERE a.account_type IN ('REVENUE','EXPENSE');

  -- سطر 3911 يقابل الصافي: ربح → دائن، خسارة → مدين.
  v_lines := v_lines || jsonb_build_array(
    jsonb_build_object(
      'account_code', '3911',
      'debit',  CASE WHEN v_net < 0 THEN -v_net ELSE 0 END,
      'credit', CASE WHEN v_net > 0 THEN v_net ELSE 0 END,
      'memo',   'أرباح محتجزة — نتيجة سنة ' || p_year::text
    )
  );

  v_entry_id := public.create_journal_entry(
    'إقفال السنة المالية ' || p_year::text ||
      ' — ترحيل الإيرادات والمصروفات إلى الأرباح المحتجزة',
    v_close_date, 'fiscal_year_close', NULL, true, v_lines, true  -- قيد نظامي؛ يُسمح داخل فترة مقفلة
  );

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'fiscal_year.closed', 'fiscal_year', v_entry_id,
          jsonb_build_object('year', p_year, 'net_result', v_net,
                             'entry_id', v_entry_id));

  RETURN v_entry_id;
END $$;


--
-- Name: FUNCTION close_fiscal_year(p_year integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.close_fiscal_year(p_year integer) IS 'T-20: يقفل سنة مالية — 4xxx/5xxx تُصفَّر والنتيجة تُرحَّل إلى 3911 بتاريخ 31/12.';


--
-- Name: company_costing_method(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.company_costing_method() RETURNS public.costing_method
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    (SELECT costing_method FROM public.company_costing_settings WHERE id = 1),
    'MOVING_AVERAGE'::public.costing_method
  );
$$;


--
-- Name: consume_internal_supplies(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_internal_supplies(_warehouse_id uuid, _lines jsonb, _notes text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_ref text;
  v_doc_id uuid := gen_random_uuid();
  r record;
  v_unit_cost numeric;
  v_line_cost numeric;
  v_total_cost numeric := 0;
  v_journal_lines jsonb := '[]'::jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to issue internal consumables';
  END IF;
  IF _warehouse_id IS NULL THEN
    RAISE EXCEPTION 'Warehouse is required';
  END IF;
  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN
    RAISE EXCEPTION 'At least one consumable line is required';
  END IF;

  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, qty numeric)
  LOOP
    IF r.item_id IS NULL OR coalesce(r.qty, 0) <= 0 THEN
      RAISE EXCEPTION 'Every line needs an item and a positive quantity';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.products
      WHERE id = r.item_id AND item_class IN ('NON_STOCK_ITEM', 'PACKAGING') AND is_active
    ) THEN
      RAISE EXCEPTION 'Only consumable (NON_STOCK_ITEM / PACKAGING) items may be issued here';
    END IF;
  END LOOP;

  v_ref := 'CS-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');

  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, qty numeric)
  LOOP
    SELECT coalesce(
      (SELECT sum(cl.quantity * cl.last_unit_cost) / nullif(sum(cl.quantity), 0)
         FROM public.item_cost_layers cl
        WHERE cl.product_id = r.item_id AND cl.quantity > 0
          AND cl.owner_type = 'COMPANY'),
      (SELECT cost_price FROM public.products WHERE id = r.item_id),
      0
    ) INTO v_unit_cost;

    v_line_cost := round(coalesce(r.qty, 0) * coalesce(v_unit_cost, 0), 2);
    v_total_cost := v_total_cost + v_line_cost;

    PERFORM public.post_stock_delta(
      p_product_id => r.item_id,
      p_warehouse_id => _warehouse_id,
      p_signed_qty => -coalesce(r.qty, 0),
      p_unit_cost => v_unit_cost,
      p_movement_kind => 'ISSUE'::public.stock_movement_kind,
      p_source_type => 'internal_consumables',
      p_source_id => v_doc_id,
      p_note => 'صرف مستهلكات داخلي ' || v_ref || coalesce(' — ' || _notes, ''),
      p_owner_type => 'COMPANY'::public.owner_type,
      p_owner_id => NULL,
      p_movement_type_legacy => 'adjustment'::public.movement_type);
    -- شرط stock_movements_adjustment_reason_required: سبب الحركة إلزامي.
    UPDATE public.stock_movements
       SET adjustment_reason = coalesce(adjustment_reason, 'Internal consumables ' || v_ref)
     WHERE source_type = 'internal_consumables' AND source_id = v_doc_id
       AND adjustment_reason IS NULL;
  END LOOP;

  IF v_total_cost > 0 THEN
    v_journal_lines := jsonb_build_array(
      jsonb_build_object(
        'account_code', '5316',
        'debit', v_total_cost,
        'credit', 0,
        'memo', 'مصروف مواد تعبئة وتغليف مستهلكة (' || v_ref || ')'
      ),
      jsonb_build_object(
        'account_code', '1315',
        'debit', 0,
        'credit', v_total_cost,
        'memo', 'منصرف مخزون مواد التعبئة (' || v_ref || ')'
      )
    );

    PERFORM public.create_journal_entry(
      p_memo => 'صرف مستهلكات تعبئة وتشغيل ' || v_ref || coalesce(' — ' || _notes, ''),
      p_entry_date => CURRENT_DATE,
      p_source_type => 'consume_internal_supplies',
      p_source_id => v_doc_id,  -- P0-2: معرّف العملية لا معرّف المستودع
      p_is_system => true,
      p_lines => v_journal_lines
    );
  END IF;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'consumables.issued', 'stock_movement', v_doc_id,
    jsonb_build_object(
      'doc_id', v_doc_id,
      'ref', v_ref,
      'warehouse_id', _warehouse_id,
      'lines', _lines,
      'total_cost', v_total_cost,
      'notes', _notes
    ));

  RETURN v_ref;
END $$;


--
-- Name: convert_stock(uuid, uuid, numeric, jsonb, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_stock(_warehouse_id uuid, _source_item_id uuid, _source_qty numeric, _outputs jsonb, _loss_qty numeric, _notes text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_ref text;
  v_doc_id uuid := gen_random_uuid();
  v_total_output_qty numeric := 0;
  r record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to run stock conversions';
  END IF;
  IF _warehouse_id IS NULL OR _source_item_id IS NULL THEN
    RAISE EXCEPTION 'Warehouse and source item are required';
  END IF;
  IF coalesce(_source_qty, 0) <= 0 THEN
    RAISE EXCEPTION 'Source quantity must be positive';
  END IF;
  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN
    RAISE EXCEPTION 'At least one output line is required';
  END IF;
  IF coalesce(_loss_qty, 0) < 0 THEN
    RAISE EXCEPTION 'Loss quantity cannot be negative';
  END IF;

  -- المصدر: أي منتج نشط (حبوب خام أو غيرها — التحويل لا يقيد فئة المصدر)
  IF NOT EXISTS (
    SELECT 1 FROM public.products
    WHERE id = _source_item_id AND is_active
  ) THEN
    RAISE EXCEPTION 'Source item is not an active product';
  END IF;

  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)
  LOOP
    IF r.item_id IS NULL OR coalesce(r.qty, 0) <= 0 THEN
      RAISE EXCEPTION 'Every output line needs an item and a positive quantity';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.products
      WHERE id = r.item_id AND is_active
    ) THEN
      RAISE EXCEPTION 'Output item % is not an active product', r.item_id;
    END IF;
    v_total_output_qty := v_total_output_qty + coalesce(r.qty, 0);
  END LOOP;

  -- القاعدة الرياضيّة الوحيدة: النواتج + الفاقد = المصدر (العدّ بوحدة المنتج)
  IF v_total_output_qty + coalesce(_loss_qty, 0) <> coalesce(_source_qty, 0) THEN
    RAISE EXCEPTION
      'Outputs + loss (%) must equal the source quantity (%)',
      v_total_output_qty + coalesce(_loss_qty, 0), coalesce(_source_qty, 0);
  END IF;

  v_ref := 'CV-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');

  -- 1) صادر المصدر — تكلفة المنتج تبقى كما هي (لا توزيع)
  PERFORM public.post_stock_delta(
    p_product_id => _source_item_id,
    p_warehouse_id => _warehouse_id,
    p_signed_qty => -coalesce(_source_qty, 0),
    p_unit_cost => NULL,
    p_movement_kind => 'PRODUCTION'::public.stock_movement_kind,
    p_source_type => 'stock_conversion',
    p_source_id => v_doc_id,
    p_note => 'تحويل مخزون ' || v_ref || coalesce(' — ' || _notes, ''),
    p_owner_type => 'COMPANY'::public.owner_type,
    p_owner_id => NULL,
    p_movement_type_legacy => 'production_out'::public.movement_type);

  -- 2) وارد النواتج — بلا توزيع تكلفة (تكلفة كل منتج ثابتة يدوياً)
  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)
  LOOP
    PERFORM public.post_stock_delta(
      p_product_id => r.item_id,
      p_warehouse_id => _warehouse_id,
      p_signed_qty => coalesce(r.qty, 0),
      p_unit_cost => NULL,
      p_movement_kind => 'PRODUCTION'::public.stock_movement_kind,
      p_source_type => 'stock_conversion',
      p_source_id => v_doc_id,
      p_note => 'تحويل مخزون ' || v_ref || coalesce(' — ' || _notes, ''),
      p_owner_type => 'COMPANY'::public.owner_type,
      p_owner_id => NULL,
      p_movement_type_legacy => 'production_in'::public.movement_type);
  END LOOP;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'stock.conversion', 'stock_movements', v_doc_id,
    jsonb_build_object(
      'doc_id', v_doc_id,
      'ref', v_ref,
      'warehouse_id', _warehouse_id,
      'source_item_id', _source_item_id,
      'source_qty', coalesce(_source_qty, 0),
      'outputs', _outputs,
      'loss_qty', coalesce(_loss_qty, 0),
      'cost_model', 'FIXED_MANUAL — no allocation, no journal',
      'notes', _notes
    ));

  RETURN v_ref;
END $$;


--
-- Name: create_expense(jsonb, date, date, public.expense_entry_type, public.expense_payee_type, text, uuid, uuid, uuid, uuid, uuid, text, text, public.expense_tax_mode, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_expense(p_lines jsonb, p_expense_date date DEFAULT CURRENT_DATE, p_due_date date DEFAULT NULL::date, p_entry_type public.expense_entry_type DEFAULT 'DIRECT'::public.expense_entry_type, p_payee_type public.expense_payee_type DEFAULT 'NONE'::public.expense_payee_type, p_payee_name text DEFAULT NULL::text, p_supplier_id uuid DEFAULT NULL::uuid, p_employee_id uuid DEFAULT NULL::uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_tax_mode public.expense_tax_mode DEFAULT 'NONE'::public.expense_tax_mode, p_reference text DEFAULT NULL::text, p_submit boolean DEFAULT false) RETURNS public.expense_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user   uuid := public.expense_actor();
  v_entry  public.expense_entries;
  v_total  numeric;
  v_count  integer;
  v_ref    text;
  v_status public.expense_status;
  v_currency text;
  v_symbol   text;
BEGIN
  PERFORM public.expense_assert_capability(v_user, 'expense.create');

  IF p_expense_date IS NULL THEN
    RAISE EXCEPTION 'Expense date is required' USING ERRCODE = '22023';
  END IF;
  -- Plan §10: the three dates are distinct concepts; a due date before the
  -- occurrence would make the ageing report negative from day one.
  IF p_due_date IS NOT NULL AND p_due_date < p_expense_date THEN
    RAISE EXCEPTION 'Due date cannot precede the expense date' USING ERRCODE = '22023';
  END IF;

  -- The payee triple is validated in SQL as well as by the table constraint, so
  -- the caller gets a readable message instead of a constraint name.
  IF p_payee_type = 'SUPPLIER' AND p_supplier_id IS NULL THEN
    RAISE EXCEPTION 'A supplier payee requires a supplier' USING ERRCODE = '22023';
  END IF;
  IF p_payee_type = 'EMPLOYEE' AND p_employee_id IS NULL THEN
    RAISE EXCEPTION 'An employee payee requires a staff member' USING ERRCODE = '22023';
  END IF;

  -- Currency is snapshotted at creation (Phase 1 rationale): a later change to
  -- the company currency must not re-label a historical voucher.
  SELECT COALESCE(NULLIF(btrim(currency), ''), 'YER'),
         COALESCE(NULLIF(btrim(currency_symbol), ''), '﷼')
    INTO v_currency, v_symbol
  FROM public.company_settings
  ORDER BY id
  LIMIT 1;
  v_currency := COALESCE(v_currency, 'YER');
  v_symbol   := COALESCE(v_symbol, '﷼');

  -- `submit` is offered as a flag because the common real-world action is
  -- "record it and send it for approval", and doing that in two round-trips is
  -- how a document ends up stranded in DRAFT.
  v_status := CASE WHEN p_submit THEN 'SUBMITTED'::public.expense_status
                   ELSE 'DRAFT'::public.expense_status END;

  v_ref := COALESCE(
    NULLIF(btrim(COALESCE(p_reference, '')), ''),
    public.next_expense_reference()
  );

  INSERT INTO public.expense_entries (
    reference, entry_type, status, source_kind,
    payee_type, payee_name, supplier_id, employee_id,
    warehouse_id, cost_center_id, project_id,
    expense_date, due_date,
    description, note,
    tax_mode, currency, currency_symbol,
    created_by, submitted_by, submitted_at
  )
  VALUES (
    v_ref, p_entry_type, v_status, 'MANUAL',
    p_payee_type,
    nullif(btrim(coalesce(p_payee_name, '')), ''),
    CASE WHEN p_payee_type = 'SUPPLIER' THEN p_supplier_id END,
    CASE WHEN p_payee_type = 'EMPLOYEE' THEN p_employee_id END,
    p_warehouse_id, p_cost_center_id, p_project_id,
    p_expense_date, p_due_date,
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_note, '')), ''),
    p_tax_mode, v_currency, v_symbol,
    v_user,
    CASE WHEN p_submit THEN v_user END,
    CASE WHEN p_submit THEN now() END
  )
  RETURNING * INTO v_entry;

  SELECT o_total, o_count INTO v_total, v_count
  FROM public.expense_write_lines(v_entry.id, p_lines, p_tax_mode);

  -- The line trigger already synced these; the assignment is explicit so the
  -- RETURNING value below is correct without a second read.
  UPDATE public.expense_entries
     SET total_amount = v_total,
         line_count   = v_count
   WHERE id = v_entry.id
  RETURNING * INTO v_entry;

  PERFORM public.expense_log_action(
    v_entry.id, 'created', NULL, v_status,
    CASE WHEN p_submit THEN 'Created and submitted' ELSE 'Created as draft' END, v_user);

  RETURN v_entry;
END $$;


--
-- Name: create_journal_entry(text, date, text, uuid, boolean, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_journal_entry(p_memo text, p_entry_date date DEFAULT CURRENT_DATE, p_source_type text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_is_system boolean DEFAULT false, p_lines jsonb DEFAULT '[]'::jsonb, p_is_reversal boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_id   uuid;
  v_num  text;
  v_d    numeric := 0;
  v_c    numeric := 0;
  src    jsonb;
  v_missing integer;
  v_blocked integer;
  v_sideless text;
  v_system_accounts integer;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- T-03: فحص الدور — القيد اليدوي (p_is_system=false) للمحاسبة فقط.
  -- القيد النظامي (من دوال الترحيل SECURITY DEFINER) مسموح لأي موظف مصادق:
  -- فالكاشير يبيع عبر create_sale، وترحيل فاتورته جزء من نفس العملية
  -- (قرار T-06-b المعتمد: مسار POS يستمر مع الترحيل التلقائي).
  IF NOT coalesce(p_is_system, false) THEN
    IF NOT (public.has_role(v_user, 'owner')
            OR public.has_role(v_user, 'manager')
            OR public.has_role(v_user, 'accountant')) THEN
      RAISE EXCEPTION 'Only an owner, manager or accountant may create manual journal entries';
    END IF;
  END IF;

  IF p_memo IS NULL OR btrim(p_memo) = '' THEN
    RAISE EXCEPTION 'A journal entry needs a description';
  END IF;
  IF p_lines IS NULL OR jsonb_array_length(p_lines) < 2 THEN
    RAISE EXCEPTION 'A journal entry needs at least two lines - one to debit and one to credit';
  END IF;

  -- A line must carry exactly one side. Checked up front, before the entry
  -- header is written, so a rejected line never leaves a DRAFT entry behind
  -- in the table for someone to find later and wonder about.
  SELECT string_agg(coalesce(ln->>'account_code', '?'), '، ') INTO v_sideless
    FROM jsonb_array_elements(p_lines) AS ln
   WHERE coalesce((ln->>'debit')::numeric, 0) = 0
     AND coalesce((ln->>'credit')::numeric, 0) = 0;
  IF v_sideless IS NOT NULL THEN
    RAISE EXCEPTION
      'Line(s) % carry neither a debit nor a credit. Every line must have exactly one side.',
      v_sideless;
  END IF;

  -- T-03: اليدوي لا يلمس حسابات النظام. دوال الترحيل تمرر p_is_system = true
  -- فتعمل كما كانت؛ النداء اليدوي (false) يُرفض إن كان أي حساب هدفه نظاميًا.
  IF NOT coalesce(p_is_system, false) THEN
    SELECT count(*) INTO v_system_accounts
      FROM jsonb_array_elements(p_lines) AS ln
      JOIN public.accounts a ON a.code = ln->>'account_code'
     WHERE a.is_system;
    IF v_system_accounts > 0 THEN
      RAISE EXCEPTION
        '% line(s) target a system account. Manual entries cannot post to system accounts.',
        v_system_accounts;
    END IF;
  END IF;

  -- T-19: لا قيد جديد بتاريخ فترة مقفلة. القيد العكسي مستثنى: هو يُلغي قيدًا
  -- قائمًا ولا ينشئ رقمًا جديدًا، ومنعُه يترك خطأً لا يمكن تصحيحه.
  IF NOT coalesce(p_is_reversal, false) THEN
    PERFORM public.assert_period_open(coalesce(p_entry_date, CURRENT_DATE));
  END IF;

  v_num := public.next_journal_number(coalesce(p_entry_date, CURRENT_DATE));

  INSERT INTO public.journal_entries
    (entry_number, entry_date, memo, source_type, source_id, is_system, created_by)
  VALUES (v_num, coalesce(p_entry_date, CURRENT_DATE), btrim(p_memo),
          p_source_type, p_source_id, p_is_system, v_user)
  RETURNING id INTO v_id;

  FOR src IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_d := v_d + coalesce((src->>'debit')::numeric, 0);
    v_c := v_c + coalesce((src->>'credit')::numeric, 0);
  END LOOP;

  IF v_d <> v_c THEN
    RAISE EXCEPTION
      'Entry does not balance: debits % vs credits % (difference %). An entry that cannot balance is not an entry.',
      round(v_d, 2)::text, round(v_c, 2)::text, round(v_d - v_c, 2)::text;
  END IF;
  IF v_d <= 0 THEN
    RAISE EXCEPTION 'Entry total must be greater than zero';
  END IF;

  -- The two failure modes are reported separately: "code does not exist" sends
  -- the operator hunting for a typo when the code was real and simply not
  -- postable, and that misdirection costs more than the extra check.
  SELECT count(*) FILTER (WHERE a.id IS NULL),
         count(*) FILTER (WHERE a.id IS NOT NULL AND NOT a.is_postable)
    INTO v_missing, v_blocked
    FROM jsonb_array_elements(p_lines) AS ln
    LEFT JOIN public.accounts a ON a.code = ln->>'account_code';

  IF v_missing > 0 THEN
    RAISE EXCEPTION 'One or more account codes do not exist. Check the code before posting.';
  END IF;
  IF v_blocked > 0 THEN
    RAISE EXCEPTION
      'One or more accounts is not postable directly (a contra or clearing account). Post through the account that moves it.';
  END IF;

  INSERT INTO public.journal_lines (entry_id, account_id, debit, credit, memo, partner_type, partner_id)
  SELECT v_id, a.id,
         coalesce((ln->>'debit')::numeric, 0),
         coalesce((ln->>'credit')::numeric, 0),
         nullif(btrim(coalesce(ln->>'memo','')), ''),
         nullif(btrim(coalesce(ln->>'partner_type','')), ''),
         (ln->>'partner_id')::uuid
    FROM jsonb_array_elements(p_lines) AS ln
    JOIN public.accounts a ON a.code = ln->>'account_code'
   WHERE (ln->>'debit')::numeric IS DISTINCT FROM 0
      OR (ln->>'credit')::numeric IS DISTINCT FROM 0;

  IF (SELECT count(*) FROM public.journal_lines WHERE entry_id = v_id)
     <> jsonb_array_length(p_lines) THEN
    RAISE EXCEPTION 'One or more lines could not be written';
  END IF;

  UPDATE public.journal_entries
     SET total_debit = v_d, total_credit = v_c, status = 'POSTED',
         posted_by = v_user, posted_at = now()
   WHERE id = v_id;

  -- T-03: كل قيد له أثر في سجل التدقيق.
  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'journal_entry.posted', 'journal_entry', v_id,
          jsonb_build_object('entry_number', v_num,
                             'entry_date', coalesce(p_entry_date, CURRENT_DATE),
                             'source_type', p_source_type,
                             'source_id', p_source_id,
                             'total', v_d,
                             'is_reversal', coalesce(p_is_reversal, false)));

  RETURN v_id;
END $$;


--
-- Name: FUNCTION create_journal_entry(p_memo text, p_entry_date date, p_source_type text, p_source_id uuid, p_is_system boolean, p_lines jsonb, p_is_reversal boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_journal_entry(p_memo text, p_entry_date date, p_source_type text, p_source_id uuid, p_is_system boolean, p_lines jsonb, p_is_reversal boolean) IS 'T-03/T-19: إنشاء قيد مزدوج مع فحص الدور، ومنع اليدوي على حسابات النظام، وسجل تدقيق، ومنع الترحيل في فترة مقفلة.';


--
-- Name: create_milling_service_document(uuid, uuid, uuid, numeric, numeric, uuid, numeric, numeric, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_milling_service_document(_customer_id uuid, _warehouse_id uuid, _grain_item_id uuid, _bags numeric, _kg numeric, _service_item_id uuid, _service_unit_price numeric, _discount numeric, _payment_method text, _paid numeric, _notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_document_id uuid;
  v_document_number text;
  v_invoice_id uuid;
  v_invoice_number text;
  v_subtotal numeric;
  v_total numeric;
  v_paid numeric;
  v_outstanding numeric;
  v_customer_balance numeric;
  v_credit_limit numeric;
  v_period text := to_char(coalesce(current_date, now()::date), 'MM-YYYY');
  v_basis text;
  v_fee_qty numeric;
  v_fee_per_unit numeric;
  v_description text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT (
    public.has_role(v_user, 'owner')
    OR public.has_role(v_user, 'manager')
    OR public.has_role(v_user, 'cashier')
  ) THEN
    RAISE EXCEPTION 'You are not permitted to create milling service documents';
  END IF;
  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _grain_item_id IS NULL
     OR _service_item_id IS NULL THEN
    RAISE EXCEPTION 'Customer, warehouse, grain and service are required';
  END IF;
  IF coalesce(_bags, 0) <= 0 AND coalesce(_kg, 0) <= 0 THEN
    RAISE EXCEPTION 'Record at least one bag or a positive weight';
  END IF;
  IF coalesce(_bags, 0) < 0 OR coalesce(_kg, 0) < 0 THEN
    RAISE EXCEPTION 'Quantities cannot be negative';
  END IF;
  IF coalesce(_service_unit_price, 0) < 0 OR coalesce(_discount, 0) < 0
     OR coalesce(_paid, 0) < 0 THEN
    RAISE EXCEPTION 'Service price, discount and paid amount cannot be negative';
  END IF;
  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN
    RAISE EXCEPTION 'Unsupported payment method';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.products
    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active
  ) THEN
    RAISE EXCEPTION 'Intake item must be an active RAW_MATERIAL grain';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.products
    WHERE id = _service_item_id AND item_class = 'SERVICE' AND is_active AND is_sellable
  ) THEN
    RAISE EXCEPTION 'Milling fee item must be an active sellable SERVICE';
  END IF;

  SELECT balance, credit_limit
    INTO v_customer_balance, v_credit_limit
  FROM public.customers
  WHERE id = _customer_id AND is_active = true
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Selected customer is unavailable';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = _warehouse_id AND is_active) THEN
    RAISE EXCEPTION 'Selected warehouse is unavailable';
  END IF;

  v_subtotal := round(coalesce(_service_unit_price, 0), 2);
  v_total := round(v_subtotal - coalesce(_discount, 0), 2);
  IF v_total < 0 THEN
    RAISE EXCEPTION 'Discount cannot exceed the service fee';
  END IF;
  v_paid := least(round(coalesce(_paid, 0), 2), v_total);
  v_outstanding := round(v_total - v_paid, 2);
  IF _payment_method = 'credit' AND v_paid <> 0 THEN
    RAISE EXCEPTION 'Credit payment method requires zero paid amount';
  END IF;
  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN
    RAISE EXCEPTION
      'Credit limit exceeded: current balance %, requested debt %, limit %',
      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);
  END IF;

  -- P1-1: أساس التسعير يُخزَّن بدل دفنه في كمية 1 وسعر إجمالي.
  IF coalesce(_bags, 0) > 0 THEN
    v_basis       := 'PER_BAG';
    v_fee_qty     := round(_bags, 3);
    v_fee_per_unit := round(v_subtotal / _bags, 2);
    v_description := format(
      'أجور طحن وتجهيز — %s كيس × %s (فترة الاستلام %s)',
      trim(to_char(_bags, 'FM999999990.###')),
      trim(to_char(v_fee_per_unit, 'FM999999990.00')),
      v_period);
  ELSE
    v_basis       := 'PER_KG';
    v_fee_qty     := round(_kg, 3);
    v_fee_per_unit := round(v_subtotal / nullif(_kg, 0), 2);
    v_description := format(
      'أجور طحن وتجهيز — %s كجم × %s (فترة الاستلام %s)',
      trim(to_char(_kg, 'FM999999990.###')),
      trim(to_char(v_fee_per_unit, 'FM999999990.00')),
      v_period);
  END IF;

  v_invoice_number := public.next_invoice_number();
  INSERT INTO public.sales_invoices (
    invoice_number, customer_id, warehouse_id, status, payment_status,
    subtotal, discount, tax, total, paid, payment_method, note, created_by
  ) VALUES (
    v_invoice_number, _customer_id, _warehouse_id, 'confirmed',
    public.derive_payment_status(v_paid, v_total),
    v_subtotal, round(coalesce(_discount, 0), 2), 0, v_total, v_paid,
    _payment_method::public.payment_method, nullif(btrim(_notes), ''), v_user
  ) RETURNING id INTO v_invoice_id;

  INSERT INTO public.sales_invoice_items (
    invoice_id, product_id, description, quantity, unit_price, discount, tax, total,
    line_type, stock_effect
  ) VALUES (
    v_invoice_id, _service_item_id, v_description, v_fee_qty, v_fee_per_unit,
    0, 0, v_subtotal, 'SERVICE', 'NONE'
  );

  IF v_outstanding > 0 THEN
    UPDATE public.customers
    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()
    WHERE id = _customer_id;

    INSERT INTO public.customer_ledger (
      customer_id, entry_type, debit, reference_id, reference_type,
      occurred_at, created_by, source_key, note
    ) VALUES (
      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',
      now(), v_user, 'sale:' || v_invoice_id, 'قيد أجور طحن آجل'
    ) ON CONFLICT (source_key) DO NOTHING;
  END IF;

  PERFORM public.post_sales_invoice(v_invoice_id);

  v_document_number := 'MT-' || to_char(now(), 'YYYYMM') || '-' ||
    lpad(nextval('public.milling_document_seq')::text, 4, '0');
  INSERT INTO public.milling_service_documents (
    document_number, customer_id, warehouse_id, sales_invoice_id, created_by,
    billing_basis, fee_per_unit, fee_quantity
  ) VALUES (
    v_document_number, _customer_id, _warehouse_id, v_invoice_id, v_user,
    v_basis, v_fee_per_unit, v_fee_qty
  ) RETURNING id INTO v_document_id;

  INSERT INTO public.custody_ledger (
    customer_id, warehouse_id, entry_type, item_id, doc_number,
    bags_in, kg_in, milling_document_id, notes, created_by
  ) VALUES (
    _customer_id, _warehouse_id, 'INTAKE', _grain_item_id, v_document_number,
    coalesce(_bags, 0), coalesce(_kg, 0), v_document_id, _notes, v_user
  );

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'milling.service_document.created', 'milling_service_documents', v_document_id,
    jsonb_build_object(
      'document_number', v_document_number,
      'invoice_id', v_invoice_id,
      'invoice_number', v_invoice_number,
      'customer_id', _customer_id,
      'grain_item_id', _grain_item_id,
      'bags', coalesce(_bags, 0),
      'kg', coalesce(_kg, 0),
      'billing_basis', v_basis,
      'fee_per_unit', v_fee_per_unit,
      'fee_quantity', v_fee_qty,
      'service_total', v_total,
      'paid', v_paid,
      'outstanding', v_outstanding,
      'stock_impact', 'NONE — customer custody'
    ));

  RETURN jsonb_build_object(
    'document_id', v_document_id,
    'document_number', v_document_number,
    'invoice_id', v_invoice_id,
    'invoice_number', v_invoice_number,
    'billing_basis', v_basis,
    'fee_per_unit', v_fee_per_unit,
    'fee_quantity', v_fee_qty
  );
END $$;


--
-- Name: create_milling_service_document_multi(uuid, uuid, jsonb, uuid, numeric, numeric, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_milling_service_document_multi(_customer_id uuid, _warehouse_id uuid, _grains jsonb, _service_item_id uuid, _service_unit_price numeric, _discount numeric, _payment_method text, _paid numeric, _notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN public.create_milling_service_document_multi(
    _customer_id, _warehouse_id, _grains, _service_item_id, _service_unit_price,
    _discount, _payment_method, _paid, _notes, '[]'::jsonb
  );
END $$;


--
-- Name: create_milling_service_document_multi(uuid, uuid, jsonb, uuid, numeric, numeric, text, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_milling_service_document_multi(_customer_id uuid, _warehouse_id uuid, _grains jsonb, _service_item_id uuid, _service_unit_price numeric, _discount numeric, _payment_method text, _paid numeric, _notes text, _payment_splits jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_document_id uuid;
  v_document_number text;
  v_invoice_id uuid;
  v_invoice_number text;
  v_subtotal numeric;
  v_total numeric;
  v_paid numeric;
  v_outstanding numeric;
  v_customer_balance numeric;
  v_credit_limit numeric;
  v_is_system boolean := false;
  v_split record;
  v_split_total numeric := 0;
  v_split_count integer := 0;
  v_recorded_method text := coalesce(_payment_method, 'cash');
  r record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT (
    public.has_role(v_user, 'owner')
    OR public.has_role(v_user, 'manager')
    OR public.has_role(v_user, 'cashier')
  ) THEN
    RAISE EXCEPTION 'You are not permitted to create milling service documents';
  END IF;
  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _service_item_id IS NULL THEN
    RAISE EXCEPTION 'Customer, warehouse and service are required';
  END IF;
  IF _grains IS NULL OR jsonb_typeof(_grains) <> 'array' OR jsonb_array_length(_grains) = 0 THEN
    RAISE EXCEPTION 'At least one grain line is required';
  END IF;
  IF coalesce(_service_unit_price, 0) < 0 OR coalesce(_discount, 0) < 0
     OR coalesce(_paid, 0) < 0 THEN
    RAISE EXCEPTION 'Service price, discount and paid amount cannot be negative';
  END IF;
  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN
    RAISE EXCEPTION 'Unsupported payment method';
  END IF;

  -- تجزئة الدفع: طرق تحصيل فقط، بمبالغ موجبة
  IF coalesce(jsonb_typeof(_payment_splits), '') = 'array'
     AND jsonb_array_length(_payment_splits) > 0 THEN
    FOR v_split IN
      SELECT part ->> 'method' AS method,
             coalesce((part ->> 'amount')::numeric, 0) AS amount,
             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,
             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,
             nullif(part ->> 'payment_method_id', '') AS payment_method_id,
             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference
        FROM jsonb_array_elements(_payment_splits) AS part
    LOOP
      IF v_split.method IS NULL
         OR v_split.method NOT IN ('cash', 'card', 'bank_transfer', 'mobile_money', 'cheque') THEN
        RAISE EXCEPTION 'Unsupported milling split method: %', v_split.method;
      END IF;
      IF public.resolve_writable_payment_method(
           coalesce(v_split.payment_method_id, v_split.method), 'pos', true
         ) IS DISTINCT FROM v_split.method THEN
        RAISE EXCEPTION 'Payment method id does not match milling tender %', v_split.method;
      END IF;
      IF v_split.amount <= 0 THEN
        RAISE EXCEPTION 'Every milling payment tender requires a positive amount';
      END IF;
      v_split_total := v_split_total + v_split.amount;
      v_split_count := v_split_count + 1;
    END LOOP;
    IF v_split_count > 1 THEN
      v_recorded_method := 'split';
    END IF;
  END IF;

  -- تحقق أسطر الحبوب: منتج أمانات + كمية موجبة
  FOR r IN SELECT * FROM jsonb_to_recordset(_grains) AS g(item_id uuid, bags numeric, kg numeric)
  LOOP
    IF r.item_id IS NULL THEN
      RAISE EXCEPTION 'Every grain line needs an item';
    END IF;
    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN
      RAISE EXCEPTION 'Grain quantities cannot be negative';
    END IF;
    IF coalesce(r.bags, 0) = 0 AND coalesce(r.kg, 0) = 0 THEN
      RAISE EXCEPTION 'Every grain line needs a positive quantity';
    END IF;
  END LOOP;

  SELECT balance, credit_limit, is_system
    INTO v_customer_balance, v_credit_limit, v_is_system
    FROM public.customers
   WHERE id = _customer_id AND is_active = true
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Selected customer is unavailable';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = _warehouse_id AND is_active) THEN
    RAISE EXCEPTION 'Selected warehouse is unavailable';
  END IF;

  v_subtotal := round(coalesce(_service_unit_price, 0), 2);
  v_total := round(v_subtotal - coalesce(_discount, 0), 2);
  IF v_total < 0 THEN
    RAISE EXCEPTION 'Discount cannot exceed the service fee';
  END IF;

  IF v_split_count > 0 THEN
    IF round(v_split_total, 2) > v_total THEN
      RAISE EXCEPTION 'Milling payment split total (%) exceeds the fee total (%)',
        round(v_split_total, 2), v_total;
    END IF;
    v_paid := round(v_split_total, 2);
  ELSE
    v_paid := least(round(coalesce(_paid, 0), 2), v_total);
  END IF;

  v_outstanding := round(v_total - v_paid, 2);
  IF _payment_method = 'credit' AND v_split_count = 0 AND v_paid <> 0 THEN
    RAISE EXCEPTION 'Credit payment method requires zero paid amount';
  END IF;
  IF v_outstanding > 0 AND v_is_system THEN
    RAISE EXCEPTION
      'The system cash customer cannot carry credit — select a real customer for a deferred ticket'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN
    RAISE EXCEPTION
      'Credit limit exceeded: current balance %, requested debt %, limit %',
      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);
  END IF;

  v_invoice_number := public.next_invoice_number();
  INSERT INTO public.sales_invoices (
    invoice_number, customer_id, warehouse_id, status, payment_status,
    subtotal, discount, tax, total, paid, payment_method, note, created_by
  ) VALUES (
    v_invoice_number, _customer_id, _warehouse_id, 'confirmed',
    public.derive_payment_status(v_paid, v_total),
    v_subtotal, round(coalesce(_discount, 0), 2), 0, v_total, v_paid,
    v_recorded_method::public.payment_method, nullif(btrim(_notes), ''), v_user
  ) RETURNING id INTO v_invoice_id;

  INSERT INTO public.sales_invoice_items (
    invoice_id, product_id, description, quantity, unit_price, discount, tax, total,
    line_type, stock_effect
  ) VALUES (
    v_invoice_id, _service_item_id, 'أجور طحن وتجهيز', 1, v_subtotal,
    0, 0, v_subtotal, 'SERVICE', 'NONE'
  );

  IF v_outstanding > 0 THEN
    UPDATE public.customers
    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()
    WHERE id = _customer_id;

    INSERT INTO public.customer_ledger (
      customer_id, entry_type, debit, reference_id, reference_type,
      occurred_at, created_by, source_key, note
    ) VALUES (
      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',
      now(), v_user, 'sale:' || v_invoice_id, 'قيد أجور طحن آجل'
    ) ON CONFLICT (source_key) DO NOTHING;
  END IF;

  v_document_number := 'MT-' || to_char(now(), 'YYYYMM') || '-' ||
    lpad(nextval('public.milling_document_seq')::text, 4, '0');
  INSERT INTO public.milling_service_documents (
    document_number, customer_id, warehouse_id, sales_invoice_id, created_by
  ) VALUES (
    v_document_number, _customer_id, _warehouse_id, v_invoice_id, v_user
  ) RETURNING id INTO v_document_id;

  -- أجزاء الدفع تُسجّل قبل الترحيل ليقرأها post_sales_invoice ويوزّعها على الحسابات.
  IF v_split_count > 0 THEN
    FOR v_split IN
      SELECT part ->> 'method' AS method,
             coalesce((part ->> 'amount')::numeric, 0) AS amount,
             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,
             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,
             nullif(part ->> 'payment_method_id', '') AS payment_method_id,
             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference
        FROM jsonb_array_elements(_payment_splits) AS part
    LOOP
      INSERT INTO public.payment_splits (
        document_type, document_id, method, amount, reference, created_by,
        cashbox_id, bank_account_id, payment_method_id
      ) VALUES (
        'milling_service_document', v_document_id,
        v_split.method::public.payment_method, round(v_split.amount, 2),
        v_split.reference, v_user, v_split.cashbox_id, v_split.bank_account_id,
        coalesce(v_split.payment_method_id, v_split.method)
      );
      INSERT INTO public.customer_payment_splits (
        customer_id, invoice_id, method, amount, occurred_at, created_by,
        cashbox_id, bank_account_id, payment_method_id, reference_no
      ) VALUES (
        _customer_id, v_invoice_id, v_split.method::public.payment_method,
        round(v_split.amount, 2), now(), v_user, v_split.cashbox_id,
        v_split.bank_account_id, coalesce(v_split.payment_method_id, v_split.method),
        v_split.reference
      );
    END LOOP;
  END IF;

  PERFORM set_config('app.payment_split_internal_post', 'on', true);
  PERFORM public.post_sales_invoice(v_invoice_id);
  PERFORM set_config('app.payment_split_internal_post', 'off', true);

  FOR r IN SELECT * FROM jsonb_to_recordset(_grains) AS g(item_id uuid, bags numeric, kg numeric)
  LOOP
    INSERT INTO public.custody_ledger (
      customer_id, warehouse_id, entry_type, item_id, doc_number,
      bags_in, kg_in, milling_document_id, notes, created_by
    ) VALUES (
      _customer_id, _warehouse_id, 'INTAKE', r.item_id, v_document_number,
      coalesce(r.bags, 0), coalesce(r.kg, 0), v_document_id, _notes, v_user
    );
  END LOOP;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'milling.service_document.created', 'milling_service_documents', v_document_id,
    jsonb_build_object(
      'document_number', v_document_number,
      'invoice_id', v_invoice_id,
      'grains', _grains,
      'service_total', v_total,
      'paid', v_paid,
      'outstanding', v_outstanding,
      'has_splits', v_split_count > 0,
      'split_count', v_split_count,
      'stock_impact', 'NONE — customer custody'
    ));

  RETURN jsonb_build_object(
    'document_id', v_document_id,
    'document_number', v_document_number,
    'invoice_id', v_invoice_id,
    'invoice_number', v_invoice_number
  );
END $$;


--
-- Name: create_opening_balance(date, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_opening_balance(_effective_date date, _lines jsonb, _notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_id uuid;
  v_num text;
  l jsonb;
  v_side text;
  v_section text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may open the books';
  END IF;
  IF _effective_date IS NULL THEN
    RAISE EXCEPTION 'Effective date is required';
  END IF;
  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN
    RAISE EXCEPTION 'An opening entry needs at least one line';
  END IF;

  v_num := 'OB-' || to_char(_effective_date, 'YYYYMMDD') || '-' ||
           lpad(nextval('public.opening_balance_seq')::text, 3, '0');
  INSERT INTO public.opening_balance_documents
    (document_number, effective_date, status, fiscal_year, notes, created_by)
  VALUES
    (v_num, _effective_date, 'DRAFT', EXTRACT(YEAR FROM _effective_date)::int,
     nullif(btrim(coalesce(_notes, '')), ''), v_user)
  RETURNING id INTO v_id;

  FOR l IN SELECT * FROM jsonb_array_elements(_lines)
  LOOP
    v_section := l->>'section';
    IF v_section NOT IN ('STOCK','RECEIVABLE','PAYABLE','CASH','BANK','ASSET','LIABILITY','CAPITAL') THEN
      RAISE EXCEPTION 'Unknown opening section: %', v_section;
    END IF;
    v_side := CASE WHEN v_section IN ('STOCK','RECEIVABLE','CASH','BANK','ASSET')
                   THEN 'DEBIT' ELSE 'CREDIT' END;
    IF coalesce((l->>'amount')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION 'Line amount must be greater than zero (section %)', v_section;
    END IF;
    IF v_section = 'STOCK' AND ((l->>'product_id') IS NULL OR (l->>'warehouse_id') IS NULL
       OR coalesce((l->>'quantity')::numeric, 0) <= 0) THEN
      RAISE EXCEPTION 'Stock opening line requires an item, warehouse and positive quantity';
    END IF;
    IF v_section = 'RECEIVABLE' AND (l->>'customer_id') IS NULL THEN
      RAISE EXCEPTION 'Receivable opening line requires a customer';
    END IF;
    IF v_section = 'PAYABLE' AND (l->>'supplier_id') IS NULL THEN
      RAISE EXCEPTION 'Payable opening line requires a supplier';
    END IF;

    INSERT INTO public.opening_balance_lines
      (document_id, section, side, ref_type, ref_id, product_id, warehouse_id,
       customer_id, supplier_id, description, quantity, unit_cost, amount, ledger_account_code)
    VALUES
      (v_id, v_section, v_side, l->>'ref_type', (l->>'ref_id')::uuid,
       (l->>'product_id')::uuid, (l->>'warehouse_id')::uuid,
       (l->>'customer_id')::uuid, (l->>'supplier_id')::uuid,
       coalesce(nullif(btrim(coalesce(l->>'description', '')), ''), v_section),
       (l->>'quantity')::numeric, (l->>'unit_cost')::numeric,
       (l->>'amount')::numeric, nullif(btrim(l->>'ledger_account_code'), ''));
  END LOOP;
  RETURN v_id;
END;
$$;


--
-- Name: create_purchase(uuid, uuid, text, numeric, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase(_warehouse_id uuid, _supplier_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.create_purchase(
    _warehouse_id, _supplier_id, _payment_method, _paid, _discount, _note, _items,
    '[]'::jsonb
  );
$$;


--
-- Name: FUNCTION create_purchase(_warehouse_id uuid, _supplier_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_purchase(_warehouse_id uuid, _supplier_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb) IS 'T-06: إنشاء فاتورة مشتريات وترحيلها تلقائيًا للأستاذ في نفس المعاملة.';


--
-- Name: create_purchase(uuid, uuid, text, numeric, numeric, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase(_warehouse_id uuid, _supplier_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb, _payment_splits jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice_id       uuid;
  v_invoice_no       text;
  v_user             uuid := auth.uid();
  v_item             jsonb;
  v_subtotal         numeric := 0;
  v_tax_total        numeric := 0;
  v_total            numeric := 0;
  v_qty              numeric;
  v_cost             numeric;
  v_tax_rate         numeric;
  v_line_total       numeric;
  v_line_tax         numeric;
  v_product          uuid;
  v_effect           text;
  v_type             text;
  v_purchasable      boolean;
  v_system           boolean := false;
  v_supplier_balance numeric;
  v_paid             numeric;
  v_split            record;
  v_split_total      numeric := 0;
  v_split_count      integer := 0;
  v_recorded_method  text := coalesce(_payment_method, 'cash');
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.is_staff(v_user) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  IF _warehouse_id IS NULL THEN
    RAISE EXCEPTION 'Warehouse required';
  END IF;
  IF _supplier_id IS NULL THEN
    RAISE EXCEPTION 'Supplier required';
  END IF;
  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN
    RAISE EXCEPTION 'No items';
  END IF;

  ------------------------------------------------------------------ validate
  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP
    v_qty      := (v_item ->> 'quantity')::numeric;
    v_cost     := (v_item ->> 'unit_cost')::numeric;
    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);

    IF v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'Invalid quantity';
    END IF;
    IF v_cost IS NULL OR v_cost < 0 THEN
      RAISE EXCEPTION 'Invalid unit cost';
    END IF;
    IF v_tax_rate < 0 OR v_tax_rate > 100 THEN
      RAISE EXCEPTION 'Invalid tax rate';
    END IF;
    IF (v_item ->> 'product_id') IS NOT NULL THEN
      SELECT p.is_purchasable INTO v_purchasable
      FROM public.products p WHERE p.id = (v_item ->> 'product_id')::uuid;

      IF v_purchasable IS NOT TRUE THEN
        RAISE EXCEPTION 'Item % is not marked as purchasable', v_item ->> 'product_id';
      END IF;
    END IF;

    v_line_total := v_qty * v_cost;
    v_line_tax   := v_line_total * v_tax_rate / 100;
    v_subtotal   := v_subtotal + v_line_total;
    v_tax_total  := v_tax_total + v_line_tax;
  END LOOP;

  v_total := v_subtotal + v_tax_total - coalesce(_discount, 0);

  -- ── التحقق من تجزئة الدفع قبل أي إدراج ──
  IF coalesce(jsonb_typeof(_payment_splits), '') = 'array'
     AND jsonb_array_length(_payment_splits) > 0 THEN
    FOR v_split IN
      SELECT part ->> 'method' AS method,
             coalesce((part ->> 'amount')::numeric, 0) AS amount,
             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,
             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,
             nullif(part ->> 'payment_method_id', '') AS payment_method_id,
             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference
        FROM jsonb_array_elements(_payment_splits) AS part
    LOOP
      IF v_split.method IS NULL
         OR v_split.method NOT IN ('cash', 'card', 'bank_transfer', 'mobile_money', 'cheque') THEN
        RAISE EXCEPTION 'Unsupported purchase split method: %', v_split.method;
      END IF;
      IF public.resolve_writable_payment_method(
           coalesce(v_split.payment_method_id, v_split.method), 'purchases', true
         ) IS DISTINCT FROM v_split.method THEN
        RAISE EXCEPTION 'Payment method id does not match purchase tender %', v_split.method;
      END IF;
      IF v_split.amount <= 0 THEN
        RAISE EXCEPTION 'Every purchase payment tender requires a positive amount';
      END IF;
      v_split_total := v_split_total + v_split.amount;
      v_split_count := v_split_count + 1;
    END LOOP;

    IF round(v_split_total, 2) > round(v_total, 2) THEN
      RAISE EXCEPTION 'Purchase payment split total (%) exceeds the invoice total (%)',
        round(v_split_total, 2), round(v_total, 2);
    END IF;

    IF v_split_count > 1 THEN
      v_recorded_method := 'split';
    END IF;
  END IF;

  SELECT balance, is_system INTO v_supplier_balance, v_system
    FROM public.suppliers WHERE id = _supplier_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Selected supplier is unavailable';
  END IF;

  -- مع التجزئة، المدفوع هو مجموع الأجزاء نفسها، لا رقم يخمّنه العميل.
  v_paid := CASE
              WHEN v_split_count > 0 THEN round(v_split_total, 2)
              ELSE least(coalesce(_paid, 0), v_total)
            END;

  IF v_paid < 0 OR v_paid > v_total THEN
    RAISE EXCEPTION 'Paid amount (%) must be between zero and the invoice total (%)', v_paid, v_total;
  END IF;

  IF v_paid < v_total AND v_system THEN
    RAISE EXCEPTION
      'The system cash supplier cannot carry a payable balance — record a paid purchase or choose a real supplier'
      USING ERRCODE = 'check_violation';
  END IF;

  v_invoice_no := public.next_purchase_number();

  INSERT INTO public.purchase_invoices (
    invoice_number, supplier_id, warehouse_id, status, payment_status,
    subtotal, discount, tax, total, paid, payment_method, note, created_by
  )
  VALUES (
    v_invoice_no, _supplier_id, _warehouse_id,
    'confirmed'::public.invoice_status,
    public.derive_payment_status(v_paid, v_total),
    v_subtotal, coalesce(_discount, 0), v_tax_total, v_total, v_paid,
    v_recorded_method::public.payment_method, nullif(btrim(_note), ''), v_user
  )
  RETURNING id INTO v_invoice_id;

  --------------------------------------------------------------------- post
  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP
    v_product  := (v_item ->> 'product_id')::uuid;
    v_qty      := (v_item ->> 'quantity')::numeric;
    v_cost     := (v_item ->> 'unit_cost')::numeric;
    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);

    v_line_total := v_qty * v_cost;
    v_line_tax   := v_line_total * v_tax_rate / 100;

    SELECT r.o_line_type, r.o_stock_effect
      INTO v_type, v_effect
    FROM public.resolve_purchase_line(v_item) AS r;

    INSERT INTO public.purchase_invoice_items (
      invoice_id, product_id, quantity, unit_cost, discount, tax, total,
      line_type, stock_effect
    )
    VALUES (
      v_invoice_id, v_product, v_qty, v_cost, 0, v_line_tax, v_line_total + v_line_tax,
      v_type, v_effect
    );

    IF v_effect = 'STOCK_RECEIPT' AND v_product IS NOT NULL THEN
      PERFORM public.post_stock_delta(
        v_product,
        _warehouse_id,
        v_qty,
        v_cost,
        'RECEIPT'::public.stock_movement_kind,
        'purchase_invoice',
        v_invoice_id,
        'Purchase receipt',
        'COMPANY'::public.owner_type,
        NULL,
        'purchase'::public.movement_type
      );
    END IF;
  END LOOP;

  -- سجلات التجزئة — الحارس المؤجل يتحقق من مطابقة المدفوع عند الالتزام.
  IF v_split_count > 0 THEN
    FOR v_split IN
      SELECT part ->> 'method' AS method,
             coalesce((part ->> 'amount')::numeric, 0) AS amount,
             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference,
             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,
             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,
             nullif(part ->> 'payment_method_id', '') AS payment_method_id
        FROM jsonb_array_elements(_payment_splits) AS part
    LOOP
      INSERT INTO public.payment_splits (
        document_type, document_id, method, amount, reference, created_by,
        cashbox_id, bank_account_id, payment_method_id
      )
      VALUES (
        'purchase_invoice', v_invoice_id,
        v_split.method::public.payment_method,
        round(v_split.amount, 2), v_split.reference, v_user,
        v_split.cashbox_id, v_split.bank_account_id,
        coalesce(v_split.payment_method_id, v_split.method)
      );
    END LOOP;
  END IF;

  IF v_paid < v_total THEN
    UPDATE public.suppliers
    SET balance = balance + (v_total - v_paid), updated_at = now()
    WHERE id = _supplier_id;
  END IF;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'purchase.posted', 'purchase_invoice', v_invoice_id,
    jsonb_build_object(
      'invoice_number', v_invoice_no,
      'supplier_id', _supplier_id,
      'warehouse_id', _warehouse_id,
      'total', v_total,
      'paid', v_paid,
      'line_count', jsonb_array_length(_items),
      'has_splits', v_split_count > 0,
      'split_count', v_split_count
    ));

  PERFORM set_config('app.payment_split_internal_post', 'on', true);
  PERFORM public.post_purchase_invoice(v_invoice_id);
  PERFORM set_config('app.payment_split_internal_post', 'off', true);

  RETURN v_invoice_id;
END $$;


--
-- Name: create_purchase(uuid, uuid, text, numeric, numeric, text, jsonb, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase(_warehouse_id uuid, _supplier_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb, _cashbox_id uuid DEFAULT NULL::uuid, _bank_account_id uuid DEFAULT NULL::uuid, _payment_reference text DEFAULT NULL::text, _payment_method_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice_id uuid;
  v_resolved_cashbox uuid := _cashbox_id;
  v_split_method text;
  v_payment_splits jsonb := '[]'::jsonb;
BEGIN
  -- نفس سلوك النسخة السابقة: الصندوق الافتراضي للدفع النقدي عند غيابه.
  IF _payment_method = 'cash' AND v_resolved_cashbox IS NULL THEN
    SELECT id INTO v_resolved_cashbox
      FROM public.cashboxes
     WHERE is_active = true AND is_default = true
     LIMIT 1;
    IF v_resolved_cashbox IS NULL THEN
      SELECT id INTO v_resolved_cashbox FROM public.cashboxes
       WHERE is_active = true ORDER BY created_at ASC LIMIT 1;
    END IF;
  END IF;

  IF coalesce(_paid, 0) > 0 AND _payment_method <> 'credit' THEN
    v_split_method := public.resolve_writable_payment_method(
      coalesce(_payment_method_id, _payment_method), 'purchases', true
    );
    IF v_split_method IS DISTINCT FROM _payment_method THEN
      RAISE EXCEPTION 'Payment method id does not match purchase method %', _payment_method;
    END IF;
    v_payment_splits := jsonb_build_array(jsonb_build_object(
      'method', v_split_method,
      'amount', round(_paid, 2),
      'payment_method_id', coalesce(_payment_method_id, _payment_method),
      'cashbox_id', v_resolved_cashbox,
      'bank_account_id', _bank_account_id,
      'reference', _payment_reference
    ));
  END IF;

  v_invoice_id := public.create_purchase(
    _warehouse_id, _supplier_id, _payment_method, _paid, _discount, _note, _items,
    v_payment_splits
  );

  UPDATE public.purchase_invoices
     SET cashbox_id = v_resolved_cashbox,
         bank_account_id = _bank_account_id,
         payment_reference = nullif(btrim(_payment_reference), ''),
         payment_method_id = _payment_method_id
   WHERE id = v_invoice_id;

  RETURN v_invoice_id;
END $$;


--
-- Name: create_purchase_return(uuid, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_return(_invoice_id uuid, _warehouse_id uuid, _supplier_id uuid, _refund_method text, _note text, _items jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id     uuid;
  v_no     text;
  v_user   uuid := auth.uid();
  v_item   jsonb;
  v_sub    numeric := 0;
  v_tax    numeric := 0;
  v_tot    numeric := 0;
  v_qty    numeric;
  v_cost   numeric;
  v_tr     numeric;
  v_lt     numeric;
  v_ltax   numeric;
  v_p      uuid;
  v_effect text;
  v_type   text;
  v_avail  numeric;
  v_entry  uuid;
  v_lines  jsonb := '[]'::jsonb;
  v_cash_acct text;
  r        record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.is_staff(v_user) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN
    RAISE EXCEPTION 'No items';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP
    v_p    := (v_item ->> 'product_id')::uuid;
    v_qty  := (v_item ->> 'quantity')::numeric;
    v_cost := (v_item ->> 'unit_cost')::numeric;
    v_tr   := coalesce((v_item ->> 'tax_rate')::numeric, 0);

    v_effect := public.item_stock_effect(v_p, 'out');

    -- Only a tracked good has stock to send back.
    IF v_effect = 'STOCK_ISSUE' THEN
      SELECT i.quantity INTO v_avail
      FROM public.inventory i
      WHERE i.product_id = v_p
        AND i.warehouse_id = _warehouse_id
        AND i.owner_type = 'COMPANY'
        AND i.owner_id IS NULL;

      IF coalesce(v_avail, 0) < v_qty THEN
        RAISE EXCEPTION 'Insufficient stock for item %', v_p;
      END IF;
    END IF;

    v_lt   := v_qty * v_cost;
    v_ltax := v_lt * v_tr / 100;
    v_sub  := v_sub + v_lt;
    v_tax  := v_tax + v_ltax;
  END LOOP;
  v_tot := v_sub + v_tax;
  v_no  := public.next_purchase_return_number();

  INSERT INTO public.purchase_returns (
    return_number, invoice_id, supplier_id, warehouse_id,
    subtotal, tax, total, refund_method, note, created_by
  )
  VALUES (
    v_no, _invoice_id, _supplier_id, _warehouse_id,
    v_sub, v_tax, v_tot, _refund_method::public.payment_method,
    nullif(btrim(_note), ''), v_user
  )
  RETURNING id INTO v_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP
    v_p    := (v_item ->> 'product_id')::uuid;
    v_qty  := (v_item ->> 'quantity')::numeric;
    v_cost := (v_item ->> 'unit_cost')::numeric;
    v_tr   := coalesce((v_item ->> 'tax_rate')::numeric, 0);
    v_lt   := v_qty * v_cost;
    v_ltax := v_lt * v_tr / 100;

    v_type   := public.item_line_type(v_p, false);
    v_effect := public.item_stock_effect(v_p, 'out');

    INSERT INTO public.purchase_return_items (
      return_id, product_id, quantity, unit_cost, tax, total, line_type
    )
    VALUES (v_id, v_p, v_qty, v_cost, v_ltax, v_lt + v_ltax, v_type);

    IF v_effect = 'STOCK_ISSUE' THEN
      PERFORM public.post_stock_delta(
        v_p,
        _warehouse_id,
        -v_qty,
        v_cost,
        'ISSUE'::public.stock_movement_kind,
        'purchase_return',
        v_id,
        'Purchase return',
        'COMPANY'::public.owner_type,
        NULL,
        'purchase_return'::public.movement_type
      );
    END IF;
  END LOOP;

  -- T-12: رصيد المورد يتغير فعليًا ويمكن أن يصير سالبًا (دائنًا لنا —
  -- مبلغ مسترد مستحق) بدل إخفاء الفرق بـ greatest(...,0).
  IF _supplier_id IS NOT NULL THEN
    UPDATE public.suppliers
    SET balance = round(coalesce(balance, 0) - v_tot, 2), updated_at = now()
    WHERE id = _supplier_id;
  END IF;

  -- ── T-08(ب): قيد المرتجع — أطراف قيد المشتريات المقلوبة ──────────────────
  IF v_tot <> 0 THEN
    -- عكس المخزون/مصروف المشتريات (صافي ضريبة البند)، مجمّعًا حسب النوع.
    FOR r IN
      SELECT p.item_class,
             sum(ri.total - coalesce(ri.tax, 0)) AS net_amount
        FROM public.purchase_return_items ri
        LEFT JOIN public.products p ON p.id = ri.product_id
       WHERE ri.return_id = v_id
       GROUP BY p.item_class
      HAVING sum(ri.total - coalesce(ri.tax, 0)) <> 0
    LOOP
      v_lines := v_lines || jsonb_build_object(
        'account_code', CASE r.item_class
                          WHEN 'RAW_MATERIAL' THEN '1311'
                          WHEN 'BY_PRODUCT'   THEN '1314'
                          WHEN 'SERVICE'      THEN '5911'
                          ELSE '1313' END,
        'credit', round(r.net_amount, 2),
        'memo', 'مرتجع مشتريات ' || coalesce(r.item_class, 'GOOD'));
    END LOOP;

    IF v_tax <> 0 THEN
      v_lines := v_lines || jsonb_build_object(
        'account_code', '1316', 'credit', round(v_tax, 2),
        'memo', 'عكس ضريبة المدخلات');
    END IF;

    -- الطرف المدين: إن كان الاسترداد نقدًا/بنكًا فهو مدين نقدًا (استرِدّ فعلاً)،
    -- وإلا فهو عكس ذمة المورد (مدين على 2111).
    v_cash_acct := public.payment_method_ledger_account(_refund_method);
    IF v_cash_acct IS NOT NULL THEN
      v_lines := v_lines || jsonb_build_object(
        'account_code', v_cash_acct, 'debit', round(v_tot, 2),
        'memo', 'استرداد من المورد');
    ELSE
      v_lines := v_lines || jsonb_build_object(
        'account_code', '2111', 'debit', round(v_tot, 2),
        'memo', 'عكس ذمة المورد');
    END IF;

    v_entry := public.balance_and_post_return(
      'مرتجع مشتريات ' || v_no, CURRENT_DATE, 'purchase_return', v_id, v_lines);
  END IF;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'purchase_return.posted', 'purchase_return', v_id,
    jsonb_build_object(
      'return_number', v_no,
      'invoice_id', _invoice_id,
      'supplier_id', _supplier_id,
      'total', v_tot,
      'journal_entry_id', v_entry
    ));

  RETURN v_id;
END $$;


--
-- Name: FUNCTION create_purchase_return(_invoice_id uuid, _warehouse_id uuid, _supplier_id uuid, _refund_method text, _note text, _items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_purchase_return(_invoice_id uuid, _warehouse_id uuid, _supplier_id uuid, _refund_method text, _note text, _items jsonb) IS 'T-08/T-12: مرتجع مشتريات بقيد أستاذ عكسي ورصيد مورد فعلي (قد يكون سالبًا).';


--
-- Name: create_sale(uuid, uuid, text, numeric, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN public.create_sale(
    _warehouse_id, _customer_id, _payment_method, _paid, _discount, _note, _items, current_date, '[]'::jsonb
  );
END;
$$;


--
-- Name: FUNCTION create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb) IS 'T-06 + P0-3: إنشاء فاتورة مبيعات وتقييم مخزونها وترحيلها للأستاذ في نفس المعاملة.';


--
-- Name: create_sale(uuid, uuid, text, numeric, numeric, text, jsonb, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb, _sale_date date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN public.create_sale(
    _warehouse_id, _customer_id, _payment_method, _paid, _discount, _note, _items, _sale_date, '[]'::jsonb
  );
END;
$$;


--
-- Name: create_sale(uuid, uuid, text, numeric, numeric, text, jsonb, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb, _sale_date date, _payment_splits jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice_id     uuid;
  v_invoice_number text;
  v_user           uuid := auth.uid();
  v_line           record;
  v_subtotal       numeric := 0;
  v_tax_total      numeric := 0;
  v_discount       numeric := coalesce(_discount, 0);
  v_total          numeric := 0;
  v_paid           numeric := 0;
  v_outstanding    numeric := 0;
  v_price          numeric;
  v_tax_rate       numeric;
  v_customer_balance numeric;
  v_credit_limit   numeric;
  v_line_total     numeric;
  v_line_tax       numeric;
  v_effect         text;
  v_line_type      text;
  v_sellable       boolean;
  v_status         public.invoice_status;
  v_last_item_id   uuid;
  v_available      numeric;
  v_system         boolean := false;
  v_posted_at      timestamptz;
  v_split          record;
  v_split_total    numeric := 0;
  v_distinct_methods integer := 0;
  v_recorded_method text := _payment_method;
  v_has_splits     boolean := false;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (
    public.has_role(v_user, 'owner')
    OR public.has_role(v_user, 'manager')
    OR public.has_role(v_user, 'cashier')
  ) THEN
    RAISE EXCEPTION 'You are not permitted to post sales';
  END IF;

  IF _warehouse_id IS NULL THEN
    RAISE EXCEPTION 'Warehouse is required';
  END IF;

  IF coalesce(jsonb_typeof(_items), '') <> 'array'
     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN
    RAISE EXCEPTION 'Cart is empty';
  END IF;

  IF v_discount < 0 THEN
    RAISE EXCEPTION 'Discount cannot be negative';
  END IF;

  IF coalesce(_paid, 0) < 0 THEN
    RAISE EXCEPTION 'Paid amount cannot be negative';
  END IF;

  -- ── التحقق من صحة سجلات الدفع المجزأ إن وجدت ──
  IF coalesce(jsonb_typeof(_payment_splits), 'jsonb') = 'array'
     AND coalesce(jsonb_array_length(_payment_splits), 0) > 0 THEN
    v_has_splits := true;

    FOR v_split IN
      SELECT part ->> 'method' AS method,
             coalesce((part ->> 'amount')::numeric, 0) AS amount,
             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,
             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,
             nullif(part ->> 'payment_method_id', '') AS payment_method_id,
             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference
      FROM jsonb_array_elements(_payment_splits) AS part
    LOOP
      IF v_split.method IS NULL
         OR v_split.method NOT IN ('cash', 'card', 'bank_transfer', 'mobile_money', 'cheque') THEN
        RAISE EXCEPTION 'Unsupported split payment method: %', v_split.method;
      END IF;
      IF public.resolve_writable_payment_method(
           coalesce(v_split.payment_method_id, v_split.method), 'pos', true
         ) IS DISTINCT FROM v_split.method THEN
        RAISE EXCEPTION 'Payment method id does not match split tender %', v_split.method;
      END IF;
      IF v_split.amount <= 0 THEN
        RAISE EXCEPTION 'Every payment tender component requires a positive amount';
      END IF;
      v_split_total := v_split_total + v_split.amount;
    END LOOP;

    SELECT count(DISTINCT part ->> 'method') INTO v_distinct_methods
    FROM jsonb_array_elements(_payment_splits) AS part;

    IF v_distinct_methods <> jsonb_array_length(_payment_splits) THEN
      RAISE EXCEPTION 'A payment method may only be included once in a split';
    END IF;

    IF v_distinct_methods > 1 THEN
      v_recorded_method := 'split';
    END IF;
  ELSE
    IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'cheque') THEN
      RAISE EXCEPTION 'Unsupported payment method: %', _payment_method;
    END IF;
  END IF;

  -- ── التحقق من رصيد المخزون لجميع البنود ──
  FOR v_line IN
    SELECT r.o_product_id AS product_id, sum(r.o_quantity) AS quantity
    FROM jsonb_array_elements(_items) AS line
    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r
    WHERE r.o_stock_effect = 'STOCK_ISSUE'
    GROUP BY r.o_product_id
    ORDER BY r.o_product_id
  LOOP
    SELECT i.quantity INTO v_available
    FROM public.inventory i
    WHERE i.product_id = v_line.product_id
      AND i.warehouse_id = _warehouse_id
      AND i.owner_type = 'COMPANY'
      AND i.owner_id IS NULL
    FOR UPDATE;

    v_available := coalesce(v_available, 0);

    IF v_available < v_line.quantity THEN
      RAISE EXCEPTION
        'Insufficient stock for item %: available %, requested %',
        v_line.product_id, v_available, v_line.quantity
        USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;

  -- ── حساب المجاميع والأسعار ──
  FOR v_line IN
    SELECT r.o_product_id    AS product_id,
           r.o_quantity      AS quantity,
           r.o_service_name  AS service_name,
           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,
           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax
    FROM jsonb_array_elements(_items) AS line
    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r
  LOOP
    IF v_line.quantity IS NULL OR v_line.quantity <= 0 THEN
      RAISE EXCEPTION 'Every sale line requires a positive quantity';
    END IF;

    IF v_line.product_id IS NULL THEN
      IF coalesce(v_line.service_name, '') = '' THEN
        RAISE EXCEPTION 'Every service line requires a description';
      END IF;
      IF v_line.input_price < 0 OR v_line.input_tax < 0 OR v_line.input_tax > 100 THEN
        RAISE EXCEPTION 'Service line "%" has an invalid price or tax rate', v_line.service_name;
      END IF;
      v_price    := v_line.input_price;
      v_tax_rate := v_line.input_tax;
    ELSE
      SELECT p.sale_price, p.tax_rate, p.is_sellable
        INTO v_price, v_tax_rate, v_sellable
      FROM public.products p
      WHERE p.id = v_line.product_id AND p.is_active = true
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Item % is not available for sale', v_line.product_id;
      END IF;

      IF v_sellable IS NOT TRUE THEN
        RAISE EXCEPTION 'Item % is not marked as sellable', v_line.product_id;
      END IF;

      IF v_price < 0 OR v_tax_rate < 0 OR v_tax_rate > 100 THEN
        RAISE EXCEPTION 'Item % has invalid pricing or tax configuration', v_line.product_id;
      END IF;
    END IF;

    v_line_total := round(v_line.quantity * v_price, 2);
    v_subtotal   := v_subtotal + v_line_total;
    v_tax_total  := v_tax_total + round(v_line_total * v_tax_rate / 100, 2);
  END LOOP;

  v_total := round(v_subtotal + v_tax_total - v_discount, 2);
  IF v_discount > v_subtotal + v_tax_total OR v_total < 0 THEN
    RAISE EXCEPTION 'Discount cannot exceed the invoice amount';
  END IF;

  IF _customer_id IS NOT NULL THEN
    SELECT balance, credit_limit, is_system
      INTO v_customer_balance, v_credit_limit, v_system
    FROM public.customers
    WHERE id = _customer_id AND is_active = true
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Selected customer is unavailable';
    END IF;
  END IF;

  -- مطابقة مبالغ الدفع
  v_paid := least(coalesce(_paid, 0), v_total);
  v_outstanding := round(v_total - v_paid, 2);

  IF v_has_splits THEN
    IF round(v_split_total, 2) <> round(v_paid, 2) THEN
      RAISE EXCEPTION 'Split breakdown total (%) does not match paid amount (%)',
        round(v_split_total, 2), round(v_paid, 2);
    END IF;
  END IF;

  IF v_outstanding > 0 AND _customer_id IS NULL THEN
    RAISE EXCEPTION 'A customer is required when the sale has an unpaid amount';
  END IF;

  IF v_outstanding > 0 AND v_system THEN
    RAISE EXCEPTION
      'The system cash customer cannot carry credit — select a real customer for a deferred sale'
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN
    RAISE EXCEPTION
      'Credit limit exceeded: current balance %, requested debt %, limit %',
      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);
  END IF;

  v_status := 'confirmed'::public.invoice_status;
  v_invoice_number := public.next_invoice_number();
  v_posted_at := coalesce(_sale_date, current_date)::timestamp + localtime;

  -- ── إدراج رأس الفاتورة ──
  INSERT INTO public.sales_invoices (
    invoice_number, customer_id, warehouse_id, status, payment_status,
    subtotal, discount, tax, total, paid, payment_method, note, created_by,
    created_at, updated_at
  )
  VALUES (
    v_invoice_number, _customer_id, _warehouse_id, v_status,
    public.derive_payment_status(v_paid, v_total),
    v_subtotal, v_discount, v_tax_total, v_total, v_paid,
    v_recorded_method::public.payment_method, nullif(btrim(_note), ''), v_user,
    v_posted_at, now()
  )
  RETURNING id INTO v_invoice_id;

  -- ── إدراج سطور الفاتورة وحركات المخزون ──
  FOR v_line IN
    SELECT r.o_product_id   AS product_id,
           r.o_quantity     AS quantity,
           r.o_stock_effect AS stock_effect,
           r.o_service_name AS service_name,
           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,
           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax,
           nullif(btrim(coalesce(line ->> 'uom_id', '')), '')::uuid AS uom_id
    FROM jsonb_array_elements(_items) AS line
    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r
  LOOP
    IF v_line.product_id IS NULL THEN
      v_price     := v_line.input_price;
      v_tax_rate  := v_line.input_tax;
      v_line_type := 'AD_HOC_SERVICE';
      v_effect    := 'NONE';
    ELSE
      SELECT p.sale_price, p.tax_rate
        INTO v_price, v_tax_rate
      FROM public.products p WHERE p.id = v_line.product_id;

      v_line_type := public.item_line_type(v_line.product_id, false);
      v_effect    := public.item_stock_effect(v_line.product_id, 'out');

      IF v_effect = 'STOCK_ISSUE' THEN
        PERFORM public.post_stock_delta(
          p_product_id => v_line.product_id,
          p_warehouse_id => _warehouse_id,
          p_signed_qty => -v_line.quantity,
          p_unit_cost => NULL,
          p_movement_kind => 'ISSUE'::public.stock_movement_kind,
          p_source_type => 'sales_invoice',
          p_source_id => v_invoice_id,
          p_note => 'POS sale',
          p_owner_type => 'COMPANY'::public.owner_type,
          p_owner_id => NULL,
          p_movement_type_legacy => 'sale'::public.movement_type
        );
      END IF;
    END IF;

    v_line_total := round(v_line.quantity * v_price, 2);
    v_line_tax   := round(v_line_total * v_tax_rate / 100, 2);

    INSERT INTO public.sales_invoice_items (
      invoice_id, product_id, description, quantity, unit_price, discount, tax, total,
      line_type, stock_effect, uom_id
    )
    VALUES (
      v_invoice_id,
      v_line.product_id,
      CASE WHEN v_line.product_id IS NULL THEN v_line.service_name ELSE NULL END,
      v_line.quantity, v_price, 0, v_line_tax, v_line_total + v_line_tax,
      v_line_type, v_effect, v_line.uom_id
    )
    RETURNING id INTO v_last_item_id;

    IF v_line_type = 'AD_HOC_SERVICE' THEN
      INSERT INTO public.ad_hoc_service_lines (
        invoice_id, invoice_item_id, description, quantity, unit_price,
        discount, tax, total, created_by
      )
      VALUES (
        v_invoice_id, v_last_item_id, v_line.service_name, v_line.quantity,
        v_price, 0, v_line_tax, v_line_total + v_line_tax, v_user
      );
    END IF;
  END LOOP;

  -- مزامنة تواريخ حركات المخزون مع تاريخ البيع
  PERFORM set_config('app.stock_engine', 'on', true);
  UPDATE public.stock_movements
  SET created_at = v_posted_at
  WHERE source_type = 'sales_invoice' AND source_id = v_invoice_id;
  PERFORM set_config('app.stock_engine', 'off', true);

  -- ── تحديث ذمة العميل للآجل إن وجد ──
  IF v_outstanding > 0 THEN
    UPDATE public.customers
    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()
    WHERE id = _customer_id;

    INSERT INTO public.customer_ledger (
      customer_id, entry_type, debit, reference_id, reference_type,
      occurred_at, created_by, source_key, note
    )
    VALUES (
      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',
      v_posted_at, v_user, 'sale:' || v_invoice_id, 'قيد بيع آجل'
    )
    ON CONFLICT (source_key) DO NOTHING;
  END IF;

  -- ── إدراج سجلات الدفع المجزأ قبل الترحيل المحاسبي ──
  IF v_has_splits THEN
    FOR v_split IN
      SELECT part ->> 'method' AS method,
             coalesce((part ->> 'amount')::numeric, 0) AS amount,
             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,
             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,
             nullif(part ->> 'payment_method_id', '') AS payment_method_id,
             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference
      FROM jsonb_array_elements(_payment_splits) AS part
    LOOP
      IF v_split.amount > 0 THEN
        INSERT INTO public.customer_payment_splits (
          customer_id, invoice_id, method, amount, occurred_at, created_by,
          cashbox_id, bank_account_id, payment_method_id, reference_no
        )
        VALUES (
          _customer_id,
          v_invoice_id,
          v_split.method::public.payment_method,
          round(v_split.amount, 2),
          v_posted_at,
          v_user,
          v_split.cashbox_id,
          v_split.bank_account_id,
          coalesce(v_split.payment_method_id, v_split.method),
          v_split.reference
        );
      END IF;
    END LOOP;
  END IF;

  -- ── سجل التدقيق ──
  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'sale.posted', 'sales_invoice', v_invoice_id,
    jsonb_build_object(
      'invoice_number', v_invoice_number,
      'warehouse_id', _warehouse_id,
      'customer_id', _customer_id,
      'payment_method', v_recorded_method,
      'total', v_total,
      'paid', v_paid,
      'outstanding', v_outstanding,
      'has_splits', v_has_splits,
      'split_count', CASE WHEN v_has_splits THEN jsonb_array_length(_payment_splits) ELSE 0 END,
      'line_count', jsonb_array_length(_items)
    ));

  -- ── الترحيل المحاسبي المتوازن التلقائي ──
  PERFORM set_config('app.payment_split_internal_post', 'on', true);
  PERFORM public.post_sales_invoice(v_invoice_id);
  PERFORM set_config('app.payment_split_internal_post', 'off', true);

  RETURN v_invoice_id;
END;
$$;


--
-- Name: create_sales_return(uuid, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sales_return(_invoice_id uuid, _warehouse_id uuid, _customer_id uuid, _refund_method text, _note text, _items jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id        uuid;
  v_no        text;
  v_user      uuid := auth.uid();
  v_item      jsonb;
  v_sub       numeric := 0;
  v_tax       numeric := 0;
  v_tot       numeric := 0;
  v_qty       numeric;
  v_price     numeric;
  v_tr        numeric;
  v_lt        numeric;
  v_ltax      numeric;
  v_p         uuid;
  v_effect    text;
  v_type      text;
  v_entry     uuid;
  v_lines     jsonb := '[]'::jsonb;
  v_cash_acct text;
  r           record;
  v_debits    numeric := 0;
  v_credits   numeric := 0;
  v_inv       record;
  v_sold      numeric;
  v_returned  numeric;
  v_bad       record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.is_staff(v_user) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  IF _invoice_id IS NULL THEN
    RAISE EXCEPTION 'A sales return must be linked to its original invoice';
  END IF;
  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN
    RAISE EXCEPTION 'No items';
  END IF;
  IF _refund_method IS NULL
     OR NOT (_refund_method::public.payment_method = ANY (ARRAY['cash','card','bank_transfer','mobile_money','split']::public.payment_method[])) THEN
    RAISE EXCEPTION 'A return refund method cannot be credit — pick the account the money leaves from';
  END IF;

  -- ── الفاتورة الأصلية: مقفولة، مؤكدة، وبطرفيها ───────────────────────────
  SELECT * INTO v_inv FROM public.sales_invoices WHERE id = _invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Original invoice % does not exist', _invoice_id;
  END IF;
  IF v_inv.status IN ('draft', 'cancelled') THEN
    RAISE EXCEPTION 'Invoice % is % - a return needs a confirmed sale', v_inv.invoice_number, v_inv.status;
  END IF;
  IF _customer_id IS NOT NULL AND v_inv.customer_id IS DISTINCT FROM _customer_id THEN
    RAISE EXCEPTION 'The return customer does not match the invoice customer';
  END IF;
  IF _warehouse_id IS NOT NULL AND v_inv.warehouse_id IS DISTINCT FROM _warehouse_id THEN
    RAISE EXCEPTION 'A return must go back to the invoice warehouse (%)', v_inv.warehouse_id;
  END IF;

  -- ── السعر والضريبة من بند الفاتورة، والكمية ضد المتبقي القابل للمرتجع ───
  FOR r IN
    SELECT (src.item ->> 'product_id')::uuid AS product_id,
           sum(coalesce((src.item ->> 'quantity')::numeric, 0)) AS quantity
      FROM jsonb_array_elements(_items) AS src(item)
     GROUP BY (src.item ->> 'product_id')::uuid
  LOOP
    IF r.product_id IS NULL THEN
      RAISE EXCEPTION 'A sales return line must reference a catalogue item';
    END IF;
    IF coalesce(r.quantity, 0) <= 0 THEN
      RAISE EXCEPTION 'Every returned line needs a positive quantity';
    END IF;

    SELECT coalesce(sum(it.quantity), 0) INTO v_sold
      FROM public.sales_invoice_items it
     WHERE it.invoice_id = _invoice_id AND it.product_id = r.product_id;

    IF v_sold <= 0 THEN
      RAISE EXCEPTION 'Item % is not on invoice %', r.product_id, v_inv.invoice_number;
    END IF;

    SELECT coalesce(sum(ri.quantity), 0) INTO v_returned
      FROM public.sales_return_items ri
      JOIN public.sales_returns sr ON sr.id = ri.return_id
     WHERE sr.invoice_id = _invoice_id AND ri.product_id = r.product_id;

    IF v_returned + r.quantity > v_sold THEN
      RAISE EXCEPTION
        'Return exceeds what was sold for item %: sold %, already returned %, requested %',
        r.product_id, v_sold, v_returned, r.quantity
        USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;

  -- ── المجاميع من بنود الفاتورة، لا من الطلب ─────────────────────────────
  FOR r IN
    WITH req AS (
      SELECT (src.item ->> 'product_id')::uuid AS product_id,
             sum(coalesce((src.item ->> 'quantity')::numeric, 0)) AS quantity
        FROM jsonb_array_elements(_items) AS src(item)
       GROUP BY (src.item ->> 'product_id')::uuid
    ),
    sold AS (
      SELECT sit.product_id,
             sum(sit.unit_price * sit.quantity) / nullif(sum(sit.quantity), 0) AS unit_price,
             sum(sit.tax) / nullif(sum(sit.quantity), 0) AS unit_tax
        FROM public.sales_invoice_items sit
       WHERE sit.invoice_id = _invoice_id
       GROUP BY sit.product_id
    )
    SELECT req.product_id, req.quantity, sold.unit_price, sold.unit_tax
      FROM req LEFT JOIN sold ON sold.product_id = req.product_id
  LOOP
    v_sub := v_sub + round(coalesce(r.unit_price, 0) * r.quantity, 2);
    v_tax := v_tax + round(coalesce(r.unit_tax, 0) * r.quantity, 2);
  END LOOP;

  -- خصم الفاتورة موزّعاً بنسبة قيمة المرتجع، فلا يعود العميل مديناً بخصم لم يُعَد.
  IF coalesce(v_inv.subtotal, 0) > 0 AND coalesce(v_inv.discount, 0) > 0 THEN
    v_tot := round(v_sub * (1 - least(1, v_inv.discount / v_inv.subtotal)) + v_tax, 2);
  ELSE
    v_tot := round(v_sub + v_tax, 2);
  END IF;
  IF v_tot <= 0 THEN
    RAISE EXCEPTION 'The return value must be greater than zero';
  END IF;

  v_no := public.next_sales_return_number();

  INSERT INTO public.sales_returns (
    return_number, invoice_id, customer_id, warehouse_id,
    subtotal, tax, total, refund_method, note, created_by
  )
  VALUES (
    v_no, _invoice_id, coalesce(_customer_id, v_inv.customer_id), v_inv.warehouse_id,
    round(v_sub, 2), round(v_tax, 2), v_tot, _refund_method::public.payment_method,
    nullif(btrim(_note), ''), v_user
  )
  RETURNING id INTO v_id;

  FOR r IN
    SELECT (src.item ->> 'product_id')::uuid AS product_id,
           sum(coalesce((src.item ->> 'quantity')::numeric, 0)) AS quantity
      FROM jsonb_array_elements(_items) AS src(item)
     GROUP BY (src.item ->> 'product_id')::uuid
  LOOP
    v_p   := r.product_id;
    v_qty := r.quantity;

    SELECT sum(it.unit_price * it.quantity) / nullif(sum(it.quantity), 0),
           sum(it.tax) / nullif(sum(it.quantity), 0)
      INTO v_price, v_ltax
      FROM public.sales_invoice_items it
     WHERE it.invoice_id = _invoice_id AND it.product_id = v_p;

    v_price := round(coalesce(v_price, 0), 2);
    v_lt    := round(v_qty * v_price, 2);
    v_ltax  := round(coalesce(v_ltax, 0) * v_qty, 2);

    v_type   := public.item_line_type(v_p, false);
    v_effect := public.item_stock_effect(v_p, 'in');

    INSERT INTO public.sales_return_items (
      return_id, product_id, quantity, unit_price, tax, total, line_type
    )
    VALUES (v_id, v_p, v_qty, v_price, v_ltax, v_lt + v_ltax, v_type);

    IF v_effect = 'STOCK_RECEIPT' THEN
      PERFORM public.post_stock_delta(
        p_product_id => v_p,
        p_warehouse_id => v_inv.warehouse_id,
        p_signed_qty => v_qty,
        p_unit_cost => NULL,   -- التقييم بمتوسط الطبقة (P0-3)
        p_movement_kind => 'RECEIPT'::public.stock_movement_kind,
        p_source_type => 'sales_return',
        p_source_id => v_id,
        p_note => 'Sales return ' || v_no,
        p_owner_type => 'COMPANY'::public.owner_type,
        p_owner_id => NULL,
        p_movement_type_legacy => 'sale_return'::public.movement_type
      );
    END IF;
  END LOOP;

  -- العميل فقط إن كان للفاتورة عميل. النقدي يُسوّى على الصندوق/البنك في القيد.
  IF v_inv.customer_id IS NOT NULL THEN
    UPDATE public.customers
    SET balance = round(coalesce(balance, 0) - v_tot, 2), updated_at = now()
    WHERE id = v_inv.customer_id;

    INSERT INTO public.customer_ledger (
      customer_id, entry_type, credit, reference_id, reference_type,
      occurred_at, created_by, source_key, note
    )
    VALUES (
      v_inv.customer_id, 'return', round(v_tot, 2), v_id, 'sales_return',
      now(), v_user, 'return:' || v_id, 'مرتجع مبيعات'
    )
    ON CONFLICT (source_key) DO NOTHING;
  END IF;

  -- ── القيد: يعكس إيراد البيع وضريبته وCOGS، وللفاتورة النقدية يخرج نقداً ──
  FOR r IN
    SELECT coalesce(p.item_class::text, 'UNCLASSIFIED') AS bucket,
           sum(ri.total - coalesce(ri.tax, 0)) AS net_amount
      FROM public.sales_return_items ri
      LEFT JOIN public.products p ON p.id = ri.product_id
     WHERE ri.return_id = v_id
     GROUP BY coalesce(p.item_class::text, 'UNCLASSIFIED')
    HAVING sum(ri.total - coalesce(ri.tax, 0)) <> 0
  LOOP
    v_lines := v_lines || jsonb_build_object(
      'account_code', CASE r.bucket
                        WHEN 'BY_PRODUCT' THEN '4211'
                        WHEN 'SERVICE'    THEN '4311'
                        ELSE '4111' END,
      'debit', round(r.net_amount, 2),
      'memo', 'مرتجع إيراد ' || r.bucket);
  END LOOP;

  IF v_tax <> 0 THEN
    v_lines := v_lines || jsonb_build_object(
      'account_code', '2311', 'debit', round(v_tax, 2),
      'memo', 'عكس ضريبة القيمة المضافة');
  END IF;

  v_cash_acct := public.payment_method_ledger_account(_refund_method::text);
  IF v_cash_acct IS NOT NULL THEN
    v_lines := v_lines || jsonb_build_object(
      'account_code', v_cash_acct, 'credit', round(v_tot, 2),
      'memo', 'استرداد للعميل');
  ELSE
    v_lines := v_lines || jsonb_build_object(
      'account_code', '1211', 'credit', round(v_tot, 2),
      'partner_type', 'customer', 'partner_id', v_inv.customer_id,
      'memo', 'عكس ذم العميل');
  END IF;

  -- عكس COGS بقيمة الحركة الفعلية التي أعادتها post_stock_delta.
  FOR r IN
    SELECT p.item_class,
           sum(coalesce(sm.total_cost, 0)) AS cost
      FROM public.sales_return_items ri
      JOIN public.products p ON p.id = ri.product_id
      LEFT JOIN public.stock_movements sm
        ON sm.product_id = ri.product_id
       AND sm.source_type = 'sales_return'
       AND sm.source_id = v_id
       AND sm.warehouse_id = v_inv.warehouse_id
     WHERE ri.return_id = v_id
       AND public.item_stock_effect(ri.product_id, 'in') = 'STOCK_RECEIPT'
     GROUP BY p.item_class
  LOOP
    IF r.cost IS NULL OR r.cost = 0 THEN
      CONTINUE;
    END IF;
    v_lines := v_lines || jsonb_build_object(
      'account_code', CASE r.item_class
                        WHEN 'RAW_MATERIAL' THEN '1311'
                        WHEN 'BY_PRODUCT'   THEN '1314'
                        ELSE '1313' END,
      'debit', round(r.cost, 2),
      'memo', 'مرتجع مخزون ' || r.item_class);
    v_lines := v_lines || jsonb_build_object(
      'account_code', '5111', 'credit', round(r.cost, 2),
      'memo', 'عكس تكلفة البضاعة المباعة');
  END LOOP;

  SELECT coalesce(sum((ln->>'debit')::numeric), 0),
         coalesce(sum((ln->>'credit')::numeric), 0)
    INTO v_debits, v_credits
    FROM jsonb_array_elements(v_lines) AS ln;

  IF v_debits > 0 OR v_credits > 0 THEN
    v_entry := public.balance_and_post_return(
      p_memo => 'مرتجع مبيعات ' || v_no,
      p_date => CURRENT_DATE,
      p_source_type => 'sales_return',
      p_source_id => v_id,
      p_lines => v_lines);
  END IF;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'sales_return.posted', 'sales_return', v_id,
    jsonb_build_object(
      'return_number', v_no,
      'invoice_id', _invoice_id,
      'customer_id', v_inv.customer_id,
      'total', v_tot,
      'journal_entry_id', v_entry
    ));

  RETURN v_id;
END $$;


--
-- Name: FUNCTION create_sales_return(_invoice_id uuid, _warehouse_id uuid, _customer_id uuid, _refund_method text, _note text, _items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_sales_return(_invoice_id uuid, _warehouse_id uuid, _customer_id uuid, _refund_method text, _note text, _items jsonb) IS 'P0-1: مرتجع مبيعات مربوط بفاتورته الأصلية — بنود مقفولة، كميات مرتجعة محسوبة، وسعر وضريبة من الفاتورة.';


--
-- Name: create_stock_transfer(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stock_transfer(_from uuid, _to uuid, _note text, _items jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id     uuid;
  v_no     text;
  v_user   uuid := auth.uid();
  v_item   jsonb;
  v_p      uuid;
  v_qty    numeric;
  v_stock  numeric;
  v_nature public.item_nature;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.is_staff(v_user) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  IF _from = _to THEN
    RAISE EXCEPTION 'Source and destination must differ';
  END IF;
  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN
    RAISE EXCEPTION 'No items';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP
    v_p   := (v_item ->> 'product_id')::uuid;
    v_qty := (v_item ->> 'quantity')::numeric;

    IF v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'Invalid transfer quantity';
    END IF;

    SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = v_p;
    IF v_nature = 'SERVICE' THEN
      RAISE EXCEPTION 'Item % is a SERVICE and cannot be transferred', v_p;
    END IF;
    IF public.item_effective_policy(v_p) <> 'TRACKED' THEN
      RAISE EXCEPTION 'Item % is not a tracked item and cannot be transferred between warehouses', v_p;
    END IF;

    SELECT i.quantity INTO v_stock
    FROM public.inventory i
    WHERE i.product_id = v_p
      AND i.warehouse_id = _from
      AND i.owner_type = 'COMPANY'
      AND i.owner_id IS NULL;

    IF coalesce(v_stock, 0) < v_qty THEN
      RAISE EXCEPTION 'Insufficient stock for item %', v_p;
    END IF;
  END LOOP;

  v_no := public.next_transfer_number();

  INSERT INTO public.stock_transfers (transfer_number, from_warehouse_id, to_warehouse_id, note, created_by)
  VALUES (v_no, _from, _to, nullif(btrim(_note), ''), v_user)
  RETURNING id INTO v_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP
    v_p   := (v_item ->> 'product_id')::uuid;
    v_qty := (v_item ->> 'quantity')::numeric;

    INSERT INTO public.stock_transfer_items (transfer_id, product_id, quantity)
    VALUES (v_id, v_p, v_qty);

    PERFORM public.post_stock_delta(
      v_p, _from, -v_qty, NULL,
      'TRANSFER_OUT'::public.stock_movement_kind, 'stock_transfer', v_id,
      'Transfer out', 'COMPANY'::public.owner_type, NULL,
      'transfer_out'::public.movement_type
    );

    PERFORM public.post_stock_delta(
      v_p, _to, v_qty, NULL,
      'TRANSFER_IN'::public.stock_movement_kind, 'stock_transfer', v_id,
      'Transfer in', 'COMPANY'::public.owner_type, NULL,
      'transfer_in'::public.movement_type
    );
  END LOOP;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'stock_transfer.posted', 'stock_transfer', v_id,
    jsonb_build_object(
      'transfer_number', v_no,
      'from_warehouse_id', _from,
      'to_warehouse_id', _to,
      'line_count', jsonb_array_length(_items)
    ));

  RETURN v_id;
END $$;


--
-- Name: create_tenant_payment_method(text, text, text, text, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tenant_payment_method(p_name_ar text, p_name_en text, p_icon_key text, p_legacy_id text, p_ledger_kind text, p_contexts text[] DEFAULT NULL::text[], p_requires_reference boolean DEFAULT true) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user        uuid := auth.uid();
  v_name        text;
  v_name_en     text;
  v_legacy      text;
  v_kind        text;
  v_contexts    text[];
  v_base        text;
  v_next_order  integer;
  v_auto_id     text;
BEGIN
  IF NOT public.can_author_payment_methods() THEN
    RAISE EXCEPTION 'لا تملك صلاحية إضافة طرق دفع — هذه الصلاحية لصاحب المنشأة والمدير وسوبر أدمن المنصة'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_name := public.payment_method_clean_label(p_name_ar);
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'اسم طريقة الدفع مطلوب' USING ERRCODE = 'check_violation';
  END IF;
  IF length(v_name) > 60 THEN
    RAISE EXCEPTION 'اسم طريقة الدفع طويل جداً (الحد 60 حرفاً)'
      USING ERRCODE = 'check_violation';
  END IF;
  v_name_en := public.payment_method_clean_label(p_name_en);
  IF v_name_en IS NOT NULL AND length(v_name_en) > 60 THEN
    RAISE EXCEPTION 'الاسم الإنجليزي طويل جداً (الحد 60 حرفاً)'
      USING ERRCODE = 'check_violation';
  END IF;

  -- القيمة المخزّنة. لا يجوز للمنشأة إدخال قيمة لا يحملها النوع، ولا اختيار
  -- 'split' — فتلك القيمة تعني «سُدّدت بأكثر من وسيلة» وتكتبها محرّك الدفع المجزأ،
  -- لا يختارها مشغّل.
  v_legacy := lower(btrim(coalesce(p_legacy_id, '')));
  IF v_legacy NOT IN ('cash','card','bank_transfer','mobile_money','cheque') THEN
    RAISE EXCEPTION
      'القيمة المخزّنة "%" غير متاحة لطريقة تنشئها المنشأة (المتاح: cash, card, bank_transfer, mobile_money, cheque)',
      coalesce(p_legacy_id, '(فارغ)')
      USING ERRCODE = 'check_violation';
  END IF;

  -- عائلة الحساب تتبع القيمة المخزّنة. واشتقاقها بدل قبولها يعني أن المنشأة لا
  -- تستطيع جعل محفظة تُرحّل إلى الصندوق: فالمزاوجة حقيقة عن النوع لا تفضيل.
  --
  -- و`p_ledger_kind` **مُتجاهَل** عن قصد. هو موجود في التوقيع ليتمكن أدوات المنصة
  -- من تمرير إرشاد، لكن مستدعيًا يرسل 'CASH' لمحفظة لا يحصل عليه: فـ CASE أدناه
  -- هو الجواب الوحيد.
  v_kind := CASE v_legacy
              WHEN 'cash'         THEN 'CASH'
              WHEN 'card'         THEN 'CARD'
              WHEN 'bank_transfer' THEN 'BANK'
              WHEN 'cheque'       THEN 'BANK'
              WHEN 'mobile_money' THEN 'WALLET'
            END;

  -- الأقسام افتراضيًا كل ما يمكن للعائلة أن تظهر فيه بشكل مشروع. و`credit` ليس
  -- في القائمة عن قصد: فطريقة المنشأة وسيلة **تحصيل** أموال، و«آجل» ليست كذلك.
  v_contexts := coalesce(
    p_contexts,
    ARRAY['pos','sales','purchases','expenses','customer_collection']::text[]
  );
  IF NOT (v_contexts <@ ARRAY[
    'pos','sales','purchases','expenses','customer_collection',
    'sales_returns','purchase_returns']::text[]) THEN
    RAISE EXCEPTION 'أحد الأقسام المختارة غير معروف'
      USING ERRCODE = 'check_violation';
  END IF;

  -- معرّف ثابت مقروء مشتق من الاسم. والعربي يُنقل إلى slug؛ وأي شيء لا يترك
  -- محارف صالحة يسقط إلى بادئة، فيبقى المعرّف غير فارغ أبدًا ومطابقًا لقيد الجدول
  -- دائمًا.
  --
  -- وإن لم يُمرَّر اسم إنجليزي، يُؤخذ الـslug من الكتالوج **المولَّد** من المعرّف
  -- العربي، لا من النص العربي الحرفي: فقيد الجدول يشترط `id = lower(btrim(id))`،
  -- والعربية بلا حالة أحرف، فقاعدة عربية خام تنجح اليوم وتنكسر لحظة إضافة كلمة
  -- لاتينية.
  v_base := regexp_replace(lower(coalesce(v_name_en, '')), '[^a-z0-9]+', '_', 'g');
  v_base := btrim(coalesce(v_base, ''), '_');

  IF v_base = '' THEN
    SELECT regexp_replace(lower(m.id), '[^a-z0-9]+', '_', 'g')
      INTO v_base
    FROM public.payment_methods m
    WHERE m.id = public.payment_method_resolve_id(v_legacy);

    v_base := btrim(coalesce(v_base, ''), '_');
  END IF;

  IF v_base = '' THEN
    v_base := 'tenant_' || nullif(btrim(v_legacy, '_'), '');
  END IF;

  -- معرّف واحد يُسنَد قبل الـINSERT، فلا تشير الجملة أدناه إلا إلى متغيرات محلية
  -- عادية. وترك PostgreSQL يختار اللاحقة الحرة التالية ضمنيًا ممكن، لكنه يجعل
  -- تفرّد `id` معتمدًا على صورة استعلام فرعي لا على حلقة على الجدول الحيّ.
  v_auto_id := v_base;
  WHILE EXISTS (SELECT 1 FROM public.payment_methods m WHERE m.id = v_auto_id) LOOP
    v_auto_id := v_base || '_' || (2 + (SELECT count(*) FROM public.payment_methods m
                                       WHERE m.id LIKE v_base || '\_%'))::text;
  END LOOP;

  -- يُرتَّب بعد آخر صف قائم، فتظهر الطريقة المضافة حديثًا في نهاية ترتيب المشغّل
  -- لا في وسطه.
  SELECT coalesce(max(m.sort_order), 100) + 10
    INTO v_next_order
  FROM public.payment_methods m;

  INSERT INTO public.payment_methods (
    id, name_ar, name_en, icon_key, is_active, sort_order, allowed_contexts,
    ledger_kind, default_account_code, is_credit_term, requires_reference,
    legacy_ids, legacy_id, default_ledger_kind, is_system, created_by, notes
  ) VALUES (
    v_auto_id,
    v_name,
    v_name_en,
    coalesce(public.payment_method_clean_label(p_icon_key), 'wallet'),
    true,
    v_next_order,
    v_contexts,
    v_kind,
    public.payment_method_ledger_account(v_legacy),
    false,
    coalesce(p_requires_reference, true),
    ARRAY[]::text[],
    v_legacy,
    v_kind,
    false,
    v_user,
    'طريقة دفع أنشأتها المنشأة.'
  );

  -- صف في الإعدادات أيضًا، فتصير الطريقة الجديدة قابلة للتعديل فورًا وتحمل
  -- الأقسام نفسها التي حصل عليها صف الكتالوج.
  INSERT INTO public.payment_method_settings (
    payment_method_id, enabled, sort_order, enabled_contexts, created_by
  )
  SELECT m.id, true, m.sort_order, m.allowed_contexts, v_user
  FROM public.payment_methods m
  WHERE m.id = v_auto_id
  ON CONFLICT (payment_method_id) DO NOTHING;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, payload)
  VALUES (
    v_user, 'payment_method.created', 'payment_method',
    jsonb_build_object(
      'id', v_auto_id, 'name_ar', v_name, 'legacy_id', v_legacy,
      'ledger_kind', v_kind, 'contexts', v_contexts,
      'by_platform', public.is_platform_superadmin(v_user)
    ));

  RETURN v_auto_id;
END $$;


--
-- Name: FUNCTION create_tenant_payment_method(p_name_ar text, p_name_en text, p_icon_key text, p_legacy_id text, p_ledger_kind text, p_contexts text[], p_requires_reference boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_tenant_payment_method(p_name_ar text, p_name_en text, p_icon_key text, p_legacy_id text, p_ledger_kind text, p_contexts text[], p_requires_reference boolean) IS 'إضافة طريقة دفع لم يشحنها المطورون: تُشتق قيمتها المخزّنة ونوع حسابها من اختيار المنشأة، والمعرّف يُولَّد ولا يأتي من المتصفح.';


--
-- Name: custody_adjustment(uuid, uuid, uuid, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_adjustment(_customer_id uuid, _warehouse_id uuid, _item_id uuid, _bags_delta numeric, _kg_delta numeric, _reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_id uuid;
  v_doc text;
  v_balance_bags numeric;
  v_balance_kg numeric;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to record custody adjustments';
  END IF;
  IF nullif(btrim(coalesce(_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A reason is required for a custody adjustment';
  END IF;
  IF coalesce(_bags_delta, 0) = 0 AND coalesce(_kg_delta, 0) = 0 THEN
    RAISE EXCEPTION 'An adjustment needs a non-zero bags or kg change';
  END IF;

  SELECT * FROM public.custody_balance(_customer_id, _warehouse_id, _item_id)
    INTO v_balance_bags, v_balance_kg;

  IF coalesce(_bags_delta, 0) < 0 AND abs(_bags_delta) > v_balance_bags THEN
    RAISE EXCEPTION 'Bags balance (%) cannot go below zero', v_balance_bags;
  END IF;
  IF coalesce(_kg_delta, 0) < 0 AND abs(_kg_delta) > v_balance_kg THEN
    RAISE EXCEPTION 'Kg balance (%) cannot go below zero', v_balance_kg;
  END IF;

  v_doc := 'CA-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');

  INSERT INTO public.custody_ledger
    (customer_id, warehouse_id, entry_type, item_id, doc_number,
     bags_in, bags_out, kg_in, kg_out,
     notes, created_by)
  VALUES
    (_customer_id, _warehouse_id, 'ADJUSTMENT', _item_id, v_doc,
     CASE WHEN coalesce(_bags_delta, 0) > 0 THEN _bags_delta ELSE 0 END,
     CASE WHEN coalesce(_bags_delta, 0) < 0 THEN abs(_bags_delta) ELSE 0 END,
     CASE WHEN coalesce(_kg_delta, 0) > 0 THEN _kg_delta ELSE 0 END,
     CASE WHEN coalesce(_kg_delta, 0) < 0 THEN abs(_kg_delta) ELSE 0 END,
     'سبب التعديل: ' || btrim(_reason), v_user)
  RETURNING id INTO v_id;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'custody.adjustment', 'custody_ledger', v_id,
    jsonb_build_object(
      'doc_number', v_doc,
      'bags_delta', coalesce(_bags_delta, 0),
      'kg_delta', coalesce(_kg_delta, 0),
      'reason', btrim(_reason),
      'stock_impact', 'NONE — customer custody'
    ));

  RETURN v_id;
END $$;


--
-- Name: custody_balance(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_balance(_customer_id uuid, _warehouse_id uuid, _item_id uuid) RETURNS TABLE(bags numeric, kg numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(sum(bags_in - bags_out), 0) AS bags,
         coalesce(sum(kg_in - kg_out), 0) AS kg
  FROM public.custody_ledger
  WHERE customer_id = _customer_id
    AND warehouse_id = _warehouse_id
    AND item_id = _item_id
$$;


--
-- Name: custody_delivery(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_delivery(_customer_id uuid, _warehouse_id uuid, _lines jsonb, _notes text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_doc text;
  v_balance_bags numeric;
  v_balance_kg numeric;
  v_batch_bags numeric;
  v_batch_kg numeric;
  r record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to record custody deliveries';
  END IF;
  IF _customer_id IS NULL OR _warehouse_id IS NULL THEN
    RAISE EXCEPTION 'Customer and warehouse are required';
  END IF;
  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN
    RAISE EXCEPTION 'At least one delivery line is required';
  END IF;

  -- تحقق مسبق لكل صنف: الرصيد بعد الدفعة كاملة ≥ 0.
  FOR r IN SELECT * FROM jsonb_to_recordset(_lines)
             AS l(item_id uuid, bags numeric, kg numeric)
  LOOP
    IF r.item_id IS NULL THEN
      RAISE EXCEPTION 'Every delivery line needs an item';
    END IF;
    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN
      RAISE EXCEPTION 'Every delivery line needs bags or a positive weight';
    END IF;
    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN
      RAISE EXCEPTION 'Delivery quantities cannot be negative';
    END IF;

    SELECT * FROM public.custody_balance(_customer_id, _warehouse_id, r.item_id)
      INTO v_balance_bags, v_balance_kg;

    SELECT coalesce(sum(bags), 0), coalesce(sum(kg), 0)
      INTO v_batch_bags, v_batch_kg
    FROM jsonb_to_recordset(_lines) AS l2(item_id uuid, bags numeric, kg numeric)
    WHERE l2.item_id = r.item_id;

    IF coalesce(r.bags, 0) + (v_batch_bags - coalesce(r.bags, 0)) > v_balance_bags
       OR coalesce(r.bags, 0) > v_balance_bags THEN
      RAISE EXCEPTION 'Bags balance (%) for this item is less than the delivery (%)',
        v_balance_bags, v_batch_bags;
    END IF;
    IF coalesce(r.kg, 0) + (v_batch_kg - coalesce(r.kg, 0)) > v_balance_kg
       OR coalesce(r.kg, 0) > v_balance_kg THEN
      RAISE EXCEPTION 'Kg balance (%) for this item is less than the delivery (%)',
        v_balance_kg, v_batch_kg;
    END IF;
  END LOOP;

  v_doc := 'CD-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_delivery_seq')::text, 4, '0');

  FOR r IN SELECT * FROM jsonb_to_recordset(_lines)
             AS l(item_id uuid, bags numeric, kg numeric)
  LOOP
    INSERT INTO public.custody_ledger
      (customer_id, warehouse_id, entry_type, item_id, doc_number,
       bags_out, kg_out, notes, created_by)
    VALUES
      (_customer_id, _warehouse_id, 'DELIVERY', r.item_id, v_doc,
       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);
  END LOOP;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'custody.delivery', 'custody_ledger', _customer_id,
    jsonb_build_object(
      'doc_number', v_doc,
      'lines', _lines,
      'stock_impact', 'NONE — customer custody'
    ));

  RETURN v_doc;
END $$;


--
-- Name: custody_grain_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_grain_items() RETURNS TABLE(id uuid, sku text, name text, name_ar text, item_class public.item_class, sale_price numeric, cost_price numeric, package_weight_kg numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id, p.sku, p.name, p.name_ar, p.item_class, p.sale_price, p.cost_price, p.package_weight_kg
  FROM public.products p
  WHERE p.item_class = 'RAW_MATERIAL' AND p.is_active AND p.is_custody_item
  ORDER BY p.name_ar NULLS LAST, p.name;
$$;


--
-- Name: custody_intake(uuid, uuid, uuid, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_intake(_customer_id uuid, _warehouse_id uuid, _item_id uuid, _bags numeric, _kg numeric, _notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_id uuid;
  v_doc text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to record custody intakes';
  END IF;
  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _item_id IS NULL THEN
    RAISE EXCEPTION 'Customer, warehouse and item are required';
  END IF;
  IF coalesce(_bags, 0) <= 0 AND coalesce(_kg, 0) <= 0 THEN
    RAISE EXCEPTION 'Record at least one bag or a positive weight';
  END IF;
  IF coalesce(_bags, 0) < 0 OR coalesce(_kg, 0) < 0 THEN
    RAISE EXCEPTION 'Quantities cannot be negative';
  END IF;

  -- صنف الاستلام حبوب خام فقط — من القاعدة لا من الواجهة.
  IF NOT EXISTS (
    SELECT 1 FROM public.products
    WHERE id = _item_id AND item_class = 'RAW_MATERIAL' AND is_active
  ) THEN
    RAISE EXCEPTION 'Intake item must be an active RAW_MATERIAL grain';
  END IF;

  v_doc := 'CI-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_intake_seq')::text, 4, '0');

  INSERT INTO public.custody_ledger
    (customer_id, warehouse_id, entry_type, item_id, doc_number,
     bags_in, kg_in, notes, created_by)
  VALUES
    (_customer_id, _warehouse_id, 'INTAKE', _item_id, v_doc,
     coalesce(_bags, 0), coalesce(_kg, 0), _notes, v_user)
  RETURNING id INTO v_id;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'custody.intake', 'custody_ledger', v_id,
    jsonb_build_object(
      'doc_number', v_doc,
      'customer_id', _customer_id,
      'item_id', _item_id,
      'bags', coalesce(_bags, 0),
      'kg', coalesce(_kg, 0),
      'stock_impact', 'NONE — customer custody'
    ));

  RETURN v_id;
END $$;


--
-- Name: custody_intake_multi(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_intake_multi(_customer_id uuid, _warehouse_id uuid, _lines jsonb, _notes text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_doc text;
  r record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to record custody intakes';
  END IF;
  IF _customer_id IS NULL OR _warehouse_id IS NULL THEN
    RAISE EXCEPTION 'Customer and warehouse are required';
  END IF;
  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN
    RAISE EXCEPTION 'At least one intake line is required';
  END IF;

  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, bags numeric, kg numeric)
  LOOP
    IF r.item_id IS NULL THEN
      RAISE EXCEPTION 'Every intake line needs an item';
    END IF;
    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN
      RAISE EXCEPTION 'Every intake line needs bags or a positive weight';
    END IF;
    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN
      RAISE EXCEPTION 'Quantities cannot be negative';
    END IF;
    -- صنف الاستلام حبوب خام فقط — منتجات الأمانات (is_custody_item).
    IF NOT EXISTS (
      SELECT 1 FROM public.products
      WHERE id = r.item_id AND item_class = 'RAW_MATERIAL' AND is_active AND is_custody_item
    ) THEN
      RAISE EXCEPTION 'Intake items must be active custody grain products (is_custody_item)';
    END IF;
  END LOOP;

  v_doc := 'CI-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_intake_seq')::text, 4, '0');

  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, bags numeric, kg numeric)
  LOOP
    INSERT INTO public.custody_ledger
      (customer_id, warehouse_id, entry_type, item_id, doc_number,
       bags_in, kg_in, notes, created_by)
    VALUES
      (_customer_id, _warehouse_id, 'INTAKE', r.item_id, v_doc,
       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);
  END LOOP;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'custody.intake', 'custody_ledger', _customer_id,
    jsonb_build_object(
      'doc_number', v_doc,
      'customer_id', _customer_id,
      'lines', _lines,
      'stock_impact', 'NONE — customer custody'
    ));

  RETURN v_doc;
END $$;


--
-- Name: custody_link_invoice(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_link_invoice(_custody_entry_id uuid, _invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to link custody invoices';
  END IF;
  IF _custody_entry_id IS NULL OR _invoice_id IS NULL THEN
    RAISE EXCEPTION 'Custody entry and invoice are required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.sales_invoices WHERE id = _invoice_id) THEN
    RAISE EXCEPTION 'Invoice does not exist';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.custody_ledger
    WHERE service_invoice_id = _invoice_id AND id <> _custody_entry_id
  ) THEN
    RAISE EXCEPTION 'This invoice is already linked to another custody entry';
  END IF;

  UPDATE public.custody_ledger
     SET service_invoice_id = _invoice_id
   WHERE id = _custody_entry_id;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'custody.invoice_linked', 'custody_ledger', _custody_entry_id,
    jsonb_build_object('invoice_id', _invoice_id, 'stock_impact', 'NONE'));
END $$;


--
-- Name: custody_milling(uuid, uuid, uuid, numeric, numeric, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_milling(_customer_id uuid, _warehouse_id uuid, _grain_item_id uuid, _bags_out numeric, _kg_out numeric, _outputs jsonb, _notes text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_doc text;
  v_balance_bags numeric;
  v_balance_kg numeric;
  v_total_out_bags numeric := 0;
  v_total_out_kg numeric := 0;
  r record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to record custody milling';
  END IF;
  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _grain_item_id IS NULL THEN
    RAISE EXCEPTION 'Customer, warehouse and grain item are required';
  END IF;
  IF coalesce(_bags_out, 0) <= 0 AND coalesce(_kg_out, 0) <= 0 THEN
    RAISE EXCEPTION 'Milling must consume at least one bag or a positive weight of grain';
  END IF;
  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN
    RAISE EXCEPTION 'At least one output line is required';
  END IF;

  -- صنف الحبوب خام، وأصناف النواتج منتجات/نواتج جانبية — من القاعدة.
  IF NOT EXISTS (
    SELECT 1 FROM public.products
    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active
  ) THEN
    RAISE EXCEPTION 'Milling input must be an active RAW_MATERIAL grain';
  END IF;

  SELECT * FROM public.custody_balance(_customer_id, _warehouse_id, _grain_item_id)
    INTO v_balance_bags, v_balance_kg;

  IF coalesce(_bags_out, 0) > v_balance_bags THEN
    RAISE EXCEPTION 'Grain bags balance (%) is less than the requested milling amount (%)',
      v_balance_bags, coalesce(_bags_out, 0);
  END IF;
  IF coalesce(_kg_out, 0) > v_balance_kg THEN
    RAISE EXCEPTION 'Grain kg balance (%) is less than the requested milling amount (%)',
      v_balance_kg, coalesce(_kg_out, 0);
  END IF;

  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs)
             AS o(item_id uuid, bags numeric, kg numeric)
  LOOP
    IF r.item_id IS NULL THEN
      RAISE EXCEPTION 'Every output line needs an item';
    END IF;
    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN
      RAISE EXCEPTION 'Every output line needs bags or a positive weight';
    END IF;
    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN
      RAISE EXCEPTION 'Output quantities cannot be negative';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.products
      WHERE id = r.item_id AND item_class IN ('FINISHED_GOOD', 'BY_PRODUCT') AND is_active
    ) THEN
      RAISE EXCEPTION 'Milling outputs must be FINISHED_GOOD or BY_PRODUCT items';
    END IF;
    v_total_out_bags := v_total_out_bags + coalesce(r.bags, 0);
    v_total_out_kg   := v_total_out_kg + coalesce(r.kg, 0);
  END LOOP;

  v_doc := 'CM-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');

  -- صادر الحبوب
  INSERT INTO public.custody_ledger
    (customer_id, warehouse_id, entry_type, item_id, doc_number,
     bags_out, kg_out, notes, created_by)
  VALUES
    (_customer_id, _warehouse_id, 'MILLING', _grain_item_id, v_doc,
     coalesce(_bags_out, 0), coalesce(_kg_out, 0), _notes, v_user);

  -- وارد النواتج: سطر لكل ناتج
  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs)
             AS o(item_id uuid, bags numeric, kg numeric)
  LOOP
    INSERT INTO public.custody_ledger
      (customer_id, warehouse_id, entry_type, item_id, doc_number,
       bags_in, kg_in, notes, created_by)
    VALUES
      (_customer_id, _warehouse_id, 'MILLING', r.item_id, v_doc,
       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);
  END LOOP;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'custody.milling', 'custody_ledger', _customer_id,
    jsonb_build_object(
      'doc_number', v_doc,
      'grain_item_id', _grain_item_id,
      'grain_bags', coalesce(_bags_out, 0),
      'grain_kg', coalesce(_kg_out, 0),
      'outputs', _outputs,
      'stock_impact', 'NONE — customer custody'
    ));

  RETURN v_doc;
END $$;


--
-- Name: custody_milling(uuid, uuid, uuid, numeric, numeric, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_milling(_customer_id uuid, _warehouse_id uuid, _grain_item_id uuid, _bags_out numeric, _kg_out numeric, _outputs jsonb, _notes text, _grain_type_id uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_doc text;
  v_balance_bags numeric;
  v_balance_kg numeric;
  v_total_out_bags numeric := 0;
  v_total_out_kg numeric := 0;
  v_grain_type_name text := NULL;
  v_grain_type_loss numeric := NULL;
  r record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to record custody milling';
  END IF;
  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _grain_item_id IS NULL THEN
    RAISE EXCEPTION 'Customer, warehouse and grain item are required';
  END IF;
  IF coalesce(_bags_out, 0) <= 0 AND coalesce(_kg_out, 0) <= 0 THEN
    RAISE EXCEPTION 'Milling must consume at least one bag or a positive weight of grain';
  END IF;
  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN
    RAISE EXCEPTION 'At least one output line is required';
  END IF;

  -- نوع الحبة المرجعي: يجب أن يكون نشطاً إن مُرِّر.
  IF _grain_type_id IS NOT NULL THEN
    SELECT gt.name_ar, gt.default_loss_rate_pct
      INTO v_grain_type_name, v_grain_type_loss
      FROM public.grain_types gt
     WHERE gt.id = _grain_type_id AND gt.is_active;
    IF v_grain_type_name IS NULL THEN
      RAISE EXCEPTION 'Grain type is not active or does not exist';
    END IF;
  END IF;

  -- صنف الحبوب خام، وأصناف النواتج منتجات/نواتج جانبية — من القاعدة.
  IF NOT EXISTS (
    SELECT 1 FROM public.products
    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active
  ) THEN
    RAISE EXCEPTION 'Milling input must be an active RAW_MATERIAL grain';
  END IF;

  SELECT * FROM public.custody_balance(_customer_id, _warehouse_id, _grain_item_id)
    INTO v_balance_bags, v_balance_kg;

  IF coalesce(_bags_out, 0) > v_balance_bags THEN
    RAISE EXCEPTION 'Grain bags balance (%) is less than the requested milling amount (%)',
      v_balance_bags, coalesce(_bags_out, 0);
  END IF;
  IF coalesce(_kg_out, 0) > v_balance_kg THEN
    RAISE EXCEPTION 'Grain kg balance (%) is less than the requested milling amount (%)',
      v_balance_kg, coalesce(_kg_out, 0);
  END IF;

  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs)
             AS o(item_id uuid, bags numeric, kg numeric)
  LOOP
    IF r.item_id IS NULL THEN
      RAISE EXCEPTION 'Every output line needs an item';
    END IF;
    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN
      RAISE EXCEPTION 'Every output line needs bags or a positive weight';
    END IF;
    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN
      RAISE EXCEPTION 'Output quantities cannot be negative';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.products
      WHERE id = r.item_id AND item_class IN ('FINISHED_GOOD', 'BY_PRODUCT') AND is_active
    ) THEN
      RAISE EXCEPTION 'Milling outputs must be FINISHED_GOOD or BY_PRODUCT items';
    END IF;
    v_total_out_bags := v_total_out_bags + coalesce(r.bags, 0);
    v_total_out_kg   := v_total_out_kg + coalesce(r.kg, 0);
  END LOOP;

  v_doc := 'CM-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');

  -- صادر الحبوب — يوثّق نوع الحبة المرجعي في الملاحظات إن مُرِّر
  INSERT INTO public.custody_ledger
    (customer_id, warehouse_id, entry_type, item_id, doc_number,
     bags_out, kg_out, notes, created_by)
  VALUES
    (_customer_id, _warehouse_id, 'MILLING', _grain_item_id, v_doc,
     coalesce(_bags_out, 0), coalesce(_kg_out, 0),
     CASE WHEN v_grain_type_name IS NOT NULL
          THEN coalesce(_notes, '') || CASE WHEN coalesce(_notes, '') = '' THEN '' ELSE ' — ' END
               || '[نوع الحبة: ' || v_grain_type_name || ']'
          ELSE _notes END,
     v_user);

  -- وارد النواتج: سطر لكل ناتج
  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs)
             AS o(item_id uuid, bags numeric, kg numeric)
  LOOP
    INSERT INTO public.custody_ledger
      (customer_id, warehouse_id, entry_type, item_id, doc_number,
       bags_in, kg_in, notes, created_by)
    VALUES
      (_customer_id, _warehouse_id, 'MILLING', r.item_id, v_doc,
       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);
  END LOOP;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'custody.milling', 'custody_ledger', _customer_id,
    jsonb_build_object(
      'doc_number', v_doc,
      'grain_item_id', _grain_item_id,
      'grain_type_id', _grain_type_id,
      'grain_type_name', v_grain_type_name,
      'grain_type_default_loss_pct', v_grain_type_loss,
      'grain_bags', coalesce(_bags_out, 0),
      'grain_kg', coalesce(_kg_out, 0),
      'outputs', _outputs,
      'stock_impact', 'NONE — customer custody'
    ));

  RETURN v_doc;
END $$;


--
-- Name: custody_milling_multi(uuid, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_milling_multi(_customer_id uuid, _warehouse_id uuid, _grains jsonb, _outputs jsonb, _notes text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_doc text;
  v_balance_bags numeric;
  v_balance_kg numeric;
  v_total_out_bags numeric := 0;
  v_total_out_kg numeric := 0;
  r record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to record custody milling';
  END IF;
  IF _customer_id IS NULL OR _warehouse_id IS NULL THEN
    RAISE EXCEPTION 'Customer and warehouse are required';
  END IF;
  IF _grains IS NULL OR jsonb_typeof(_grains) <> 'array' OR jsonb_array_length(_grains) = 0 THEN
    RAISE EXCEPTION 'At least one grain line is required';
  END IF;
  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN
    RAISE EXCEPTION 'At least one output line is required';
  END IF;

  -- تحقق أسطر الحبوب: صنف خام + رصيد كافٍ
  FOR r IN SELECT * FROM jsonb_to_recordset(_grains) AS g(item_id uuid, bags numeric, kg numeric)
  LOOP
    IF r.item_id IS NULL THEN
      RAISE EXCEPTION 'Every grain line needs an item';
    END IF;
    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN
      RAISE EXCEPTION 'Every grain line needs bags or a positive weight';
    END IF;
    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN
      RAISE EXCEPTION 'Quantities cannot be negative';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.products
      WHERE id = r.item_id AND item_class = 'RAW_MATERIAL' AND is_active AND is_custody_item
    ) THEN
      RAISE EXCEPTION 'Milling input must be active custody grain products (is_custody_item)';
    END IF;

    SELECT * FROM public.custody_balance(_customer_id, _warehouse_id, r.item_id)
      INTO v_balance_bags, v_balance_kg;
    IF coalesce(r.bags, 0) > v_balance_bags THEN
      RAISE EXCEPTION 'Grain bags balance (%) is less than the requested milling amount (%)',
        v_balance_bags, coalesce(r.bags, 0);
    END IF;
    IF coalesce(r.kg, 0) > v_balance_kg THEN
      RAISE EXCEPTION 'Grain kg balance (%) is less than the requested milling amount (%)',
        v_balance_kg, coalesce(r.kg, 0);
    END IF;
  END LOOP;

  -- تحقق أسطر النواتج
  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, bags numeric, kg numeric)
  LOOP
    IF r.item_id IS NULL THEN
      RAISE EXCEPTION 'Every output line needs an item';
    END IF;
    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN
      RAISE EXCEPTION 'Every output line needs bags or a positive weight';
    END IF;
    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN
      RAISE EXCEPTION 'Output quantities cannot be negative';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.products
      WHERE id = r.item_id AND item_class IN ('FINISHED_GOOD', 'BY_PRODUCT')
        AND is_active AND is_custody_item
    ) THEN
      RAISE EXCEPTION 'Milling outputs must be active custody output products (is_custody_item)';
    END IF;
    v_total_out_bags := v_total_out_bags + coalesce(r.bags, 0);
    v_total_out_kg   := v_total_out_kg + coalesce(r.kg, 0);
  END LOOP;

  v_doc := 'CM-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');

  -- صادر الحبوب: سطر لكل صنف
  FOR r IN SELECT * FROM jsonb_to_recordset(_grains) AS g(item_id uuid, bags numeric, kg numeric)
  LOOP
    INSERT INTO public.custody_ledger
      (customer_id, warehouse_id, entry_type, item_id, doc_number,
       bags_out, kg_out, notes, created_by)
    VALUES
      (_customer_id, _warehouse_id, 'MILLING', r.item_id, v_doc,
       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);
  END LOOP;

  -- وارد النواتج: سطر لكل ناتج
  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, bags numeric, kg numeric)
  LOOP
    INSERT INTO public.custody_ledger
      (customer_id, warehouse_id, entry_type, item_id, doc_number,
       bags_in, kg_in, notes, created_by)
    VALUES
      (_customer_id, _warehouse_id, 'MILLING', r.item_id, v_doc,
       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);
  END LOOP;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'custody.milling', 'custody_ledger', _customer_id,
    jsonb_build_object(
      'doc_number', v_doc,
      'grains', _grains,
      'outputs', _outputs,
      'output_bags', v_total_out_bags,
      'output_kg', v_total_out_kg,
      'stock_impact', 'NONE — customer custody'
    ));

  RETURN v_doc;
END $$;


--
-- Name: custody_output_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custody_output_items() RETURNS TABLE(id uuid, sku text, name text, name_ar text, item_class public.item_class, sale_price numeric, cost_price numeric, package_weight_kg numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id, p.sku, p.name, p.name_ar, p.item_class, p.sale_price, p.cost_price, p.package_weight_kg
  FROM public.products p
  WHERE p.item_class IN ('FINISHED_GOOD', 'BY_PRODUCT') AND p.is_active AND p.is_custody_item
  ORDER BY p.name_ar NULLS LAST, p.name;
$$;


--
-- Name: customer_credit_limit_allows(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_credit_limit_allows(p_customer_id uuid, p_new_due numeric) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.customers AS c
    CROSS JOIN public.company_settings AS s
    WHERE c.id = p_customer_id
      AND (
        NOT s.enforce_customer_credit_limit
        OR coalesce(c.credit_limit, 0) = 0
        OR coalesce(c.balance, 0) + greatest(coalesce(p_new_due, 0), 0) <= c.credit_limit
      )
  )
$$;


--
-- Name: customer_ledger_balance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_ledger_balance(p_customer_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT round(coalesce(sum(l.debit - l.credit), 0), 2)
  FROM public.customer_ledger AS l
  WHERE l.customer_id = p_customer_id
$$;


--
-- Name: decide_expense(uuid, boolean, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_expense(p_entry_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer) RETURNS public.expense_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user   uuid := public.expense_actor();
  v_entry  public.expense_entries;
  v_action text := CASE WHEN p_approve THEN 'approve' ELSE 'reject' END;
  v_target public.expense_status := CASE WHEN p_approve
                                          THEN 'APPROVED'::public.expense_status
                                          ELSE 'REJECTED'::public.expense_status END;
BEGIN
  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';
  END IF;

  -- Only a submitted document is awaiting a decision. This is what stops a
  -- double-click — or two approvers acting at the same moment — from producing
  -- two approvals: the second caller finds APPROVED, not SUBMITTED.
  IF v_entry.status <> 'SUBMITTED' THEN
    RAISE EXCEPTION 'This expense is not awaiting approval (current: %)', v_entry.status
      USING ERRCODE = '55000';
  END IF;

  PERFORM public.expense_assert_capability(v_user, 'expense.' || v_action);

  IF p_expected_version IS NOT NULL AND p_expected_version <> v_entry.version THEN
    RAISE EXCEPTION 'This expense was changed by someone else. Reload it and try again.'
      USING ERRCODE = '40001';
  END IF;

  -- Plan §17: separation of duties. The person who typed the expense is not the
  -- person who authorises it. An owner is the single documented exception, since
  -- in a one-person company refusing self-approval would make the module
  -- unusable — but the exception is explicit and auditable rather than silent.
  IF v_entry.created_by = v_user AND NOT public.has_role(v_user, 'owner') THEN
    RAISE EXCEPTION 'You cannot approve an expense you created yourself'
      USING ERRCODE = '42501';
  END IF;

  IF v_entry.created_by = v_user AND public.has_role(v_user, 'owner') THEN
    -- Recorded in the trail, not merely allowed: an owner reviewing their own
    -- work should be visible to an auditor.
    p_reason := COALESCE(NULLIF(btrim(COALESCE(p_reason, '')), ''),
                         'Self-approved by owner (no other approver available)');
  END IF;

  IF NOT p_approve AND NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A reason is required when rejecting an expense' USING ERRCODE = '22023';
  END IF;

  UPDATE public.expense_entries
     SET status      = v_target,
         version     = version + 1,
         approved_by = CASE WHEN p_approve THEN v_user END,
         approved_at = CASE WHEN p_approve THEN now() END,
         rejected_by = CASE WHEN NOT p_approve THEN v_user END,
         rejected_at = CASE WHEN NOT p_approve THEN now() END,
         rejection_reason = CASE WHEN NOT p_approve
                                 THEN nullif(btrim(coalesce(p_reason, '')), '') END
   WHERE id = p_entry_id
  RETURNING * INTO v_entry;

  PERFORM public.expense_log_action(p_entry_id, v_action, 'SUBMITTED', v_target, p_reason, v_user);

  RETURN v_entry;
END $$;


--
-- Name: expense_categories; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.expense_categories (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    name_ar text,
    account_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    notes text,
    created_by uuid
);


--
-- Name: delete_expense_category(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_expense_category(p_id uuid) RETURNS public.expense_categories
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user  uuid := public.expense_actor();
  v_used  bigint;
  v_row   public.expense_categories;
BEGIN
  PERFORM public.expense_assert_capability(v_user, 'expense.category.manage');

  SELECT count(*) INTO v_used FROM public.expense_lines WHERE category_id = p_id;

  IF v_used > 0 THEN
    UPDATE public.expense_categories SET is_active = false WHERE id = p_id
    RETURNING * INTO v_row;

    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
    VALUES (v_user, 'expense.category.archived', 'expense_category', p_id,
            jsonb_build_object('reason', 'in_use', 'usage_count', v_used));
  ELSE
    DELETE FROM public.expense_categories WHERE id = p_id
    RETURNING * INTO v_row;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Category not found' USING ERRCODE = 'P0002';
    END IF;

    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
    VALUES (v_user, 'expense.category.deleted', 'expense_category', p_id,
            jsonb_build_object('name', v_row.name));
  END IF;

  RETURN v_row;
END $$;


--
-- Name: delete_product_batch(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_product_batch(p_batch_id uuid, p_sync_inventory boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_prod uuid;
  v_wh   uuid;
  v_qty  numeric;
  v_cost numeric;
  v_batch_no text;
  v_tracked boolean;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT product_id, warehouse_id, quantity, unit_cost, batch_number
    INTO v_prod, v_wh, v_qty, v_cost, v_batch_no
  FROM public.product_batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  SELECT (inventory_policy = 'TRACKED') INTO v_tracked
  FROM public.products WHERE id = v_prod;

  DELETE FROM public.product_batches WHERE id = p_batch_id;

  IF p_sync_inventory AND v_qty > 0 AND coalesce(v_tracked, true) THEN
    PERFORM public.post_stock_delta(
      v_prod,
      v_wh,
      -v_qty,
      v_cost,
      'ADJUSTMENT'::public.stock_movement_kind,
      'product_batch',
      p_batch_id,
      'حذف دفعة رقم: ' || v_batch_no,
      'COMPANY'::public.owner_type,
      NULL,
      'adjustment'::public.movement_type
    );
  END IF;

  RETURN true;
END $$;


--
-- Name: derive_payment_status(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_payment_status(p_paid numeric, p_total numeric) RETURNS public.payment_status
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN coalesce(p_total, 0) <= 0            THEN 'unpaid'::public.payment_status
    WHEN coalesce(p_paid, 0) <= 0             THEN 'unpaid'::public.payment_status
    WHEN p_paid >= p_total - 0.005            THEN 'paid'::public.payment_status
    ELSE 'partial'::public.payment_status
  END
$$;


--
-- Name: FUNCTION derive_payment_status(p_paid numeric, p_total numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.derive_payment_status(p_paid numeric, p_total numeric) IS 'يشتقّ حالة السداد من (المدفوع مقابل الإجمالي). نقطة الحقيقة الواحدة — لا تُكتب الحالة يدويًا.';


--
-- Name: dispose_fixed_asset(uuid, date, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispose_fixed_asset(p_asset_id uuid, p_disposal_date date, p_proceeds numeric DEFAULT 0, p_proceeds_account text DEFAULT '1101'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user        uuid := auth.uid();
  v_asset       record;
  v_lines       jsonb := '[]'::jsonb;
  v_entry_id    uuid;
  v_gain_loss   numeric(18,2);
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner')
          OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may dispose fixed assets';
  END IF;

  PERFORM public.assert_period_open(p_disposal_date);

  SELECT * INTO v_asset FROM public.fixed_assets WHERE id = p_asset_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fixed asset not found';
  END IF;

  IF v_asset.status NOT IN ('ACTIVE', 'FULLY_DEPRECIATED') THEN
    RAISE EXCEPTION 'Asset % cannot be disposed (current status: %)', v_asset.asset_code, v_asset.status;
  END IF;

  -- حساب الأرباح أو الخسائر الرأسمالية: الحصيلة - القيمة الدفترية
  v_gain_loss := coalesce(p_proceeds, 0) - v_asset.current_book_value;

  -- 1) إقفال مجمع الإهلاك (مدين 1491)
  IF v_asset.accumulated_depreciation > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', v_asset.accumulated_depreciation_account_code, -- 1491
        'debit', v_asset.accumulated_depreciation,
        'credit', 0,
        'memo', 'إقفال مجمع إهلاك الأصل المستبعد — ' || v_asset.name_ar
      )
    );
  END IF;

  -- 2) إثبات حصيلة البيع إن وجدت (مدين نقدية/بنك)
  IF coalesce(p_proceeds, 0) > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', coalesce(p_proceeds_account, '1101'),
        'debit', p_proceeds,
        'credit', 0,
        'memo', 'حصيلة بيع الأصل — ' || v_asset.name_ar
      )
    );
  END IF;

  -- 3) إثبات الخسارة الرأسمالية إن وجدت (مدين 5811 خسائر شطب أصول)
  IF v_gain_loss < 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', '5811',
        'debit', -v_gain_loss,
        'credit', 0,
        'memo', 'خسائر بيع/شطب أصل — ' || v_asset.name_ar
      )
    );
  END IF;

  -- 4) إقفال التكلفة التاريخية للأصل (دائن 14xx)
  v_lines := v_lines || jsonb_build_array(
    jsonb_build_object(
      'account_code', v_asset.asset_account_code,
      'debit', 0,
      'credit', v_asset.purchase_cost,
      'memo', 'استبعاد تكلفة الأصل — ' || v_asset.name_ar
    )
  );

  -- 5) إثبات الأرباح الرأسمالية إن وجدت (دائن 4911 إيرادات أخرى)
  IF v_gain_loss > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', '4911',
        'debit', 0,
        'credit', v_gain_loss,
        'memo', 'أرباح بيع أصل رأسمالي — ' || v_asset.name_ar
      )
    );
  END IF;

  v_entry_id := public.create_journal_entry(
    'استبعاد وشطب الأصل الثابت ' || v_asset.asset_code || ' — ' || v_asset.name_ar,
    p_disposal_date,
    'fixed_asset_disposal',
    p_asset_id,
    true,
    v_lines,
    false
  );

  UPDATE public.fixed_assets
     SET status = 'DISPOSED',
         disposal_date = p_disposal_date,
         disposal_amount = coalesce(p_proceeds, 0)
   WHERE id = p_asset_id;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'fixed_asset.disposed', 'fixed_asset', p_asset_id,
          jsonb_build_object('asset_code', v_asset.asset_code, 'proceeds', p_proceeds,
                             'gain_loss', v_gain_loss, 'entry_id', v_entry_id));

  RETURN v_entry_id;
END $$;


--
-- Name: expense_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_actor() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  RETURN v_user;
END $$;


--
-- Name: expense_assert_capability(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_assert_capability(p_user uuid, p_capability text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.expense_can(p_user, p_capability) THEN
    RAISE EXCEPTION 'Forbidden: % requires a higher role', p_capability
      USING ERRCODE = '42501';
  END IF;
END $$;


--
-- Name: expense_can(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_can(p_user uuid, p_capability text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    -- Every capability requires an active staff account. `is_staff` fails
    -- closed on a missing profile row, which is the behaviour we want here.
    public.is_staff(p_user)
    AND CASE p_capability
      -- Reading the register is the baseline every operational role needs.
      WHEN 'expense.view'            THEN public.expense_role_rank(p_user)            >= 10
      -- Typing a draft is a cashier/warehouse action: it commits nothing.
      WHEN 'expense.create'          THEN public.expense_role_rank(p_user)            >= 10
      WHEN 'expense.edit'            THEN public.expense_role_rank(p_user)            >= 10
      WHEN 'expense.submit'          THEN public.expense_role_rank(p_user)            >= 10
      -- Approval is a control, not a data-entry step.
      WHEN 'expense.approve'         THEN public.expense_role_rank(p_user)            >= 40
      WHEN 'expense.reject'          THEN public.expense_role_rank(p_user)            >= 40
      WHEN 'expense.post'            THEN public.expense_role_rank(p_user)            >= 30
      -- Money leaving the drawer needs the same bar as posting.
      WHEN 'expense.pay'             THEN public.expense_role_rank(p_user)            >= 20
      WHEN 'expense.reverse'         THEN public.expense_role_rank(p_user)            >= 30
      WHEN 'expense.cancel'          THEN public.expense_role_rank(p_user)            >= 40
      WHEN 'expense.category.manage' THEN public.expense_role_rank(p_user)            >= 40
      WHEN 'expense.dimension.manage' THEN public.expense_role_rank(p_user)           >= 40
      WHEN 'expense.report'          THEN public.expense_role_rank(p_user)            >= 30
      WHEN 'expense.payment.reverse' THEN public.expense_role_rank(p_user)            >= 30
      ELSE false
    END
$$;


--
-- Name: expense_can_write_document(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_can_write_document(p_entry_id uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.expense_entries e
    WHERE e.id = p_entry_id
      AND (
        -- An approver or accountant can act on any document.
        public.expense_role_rank(p_user) >= 30
        -- Everyone else can act only on a document they own, and only while it
        -- is still theirs to change. Posted documents are frozen for all.
        OR (e.created_by = p_user AND e.status IN ('DRAFT', 'REJECTED'))
      )
  )
$$;


--
-- Name: expense_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_detail(p_entry_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'entry', to_jsonb(e) || jsonb_build_object(
      'supplier_name',    s.name,
      'employee_name',    pr.full_name,
      'warehouse_name',   w.name,
      'cost_center_name', cc.name,
      'project_name',     pj.name,
      'created_by_name',  cb.full_name,
      'approved_by_name', ab.full_name,
      'posted_by_name',   pb.full_name,
      -- The capability set is computed server-side so the UI does not have to
      -- re-derive the role matrix in JavaScript and drift from the database.
      'can_edit',    (e.status IN ('DRAFT', 'REJECTED'))
                     AND (e.created_by = auth.uid() OR public.expense_role_rank(auth.uid()) >= 30),
      'can_submit',  (e.status IN ('DRAFT', 'REJECTED'))
                     AND (e.created_by = auth.uid() OR public.expense_role_rank(auth.uid()) >= 30),
      'can_approve', (e.status = 'SUBMITTED') AND public.expense_can(auth.uid(), 'expense.approve'),
      'can_post',    (e.status IN ('APPROVED', 'DRAFT')) AND public.expense_can(auth.uid(), 'expense.post'),
      'can_pay',     (e.status IN ('POSTED', 'PARTIALLY_PAID')) AND public.expense_can(auth.uid(), 'expense.pay'),
      'can_cancel',  (e.status IN ('DRAFT', 'REJECTED', 'SUBMITTED', 'APPROVED'))
                     AND public.expense_can(auth.uid(), 'expense.cancel'),
      'can_reverse', (e.status IN ('POSTED', 'PARTIALLY_PAID', 'PAID'))
                     AND public.expense_can(auth.uid(), 'expense.reverse')
    ),
    'lines', COALESCE((
      SELECT jsonb_agg(
        to_jsonb(l) || jsonb_build_object(
          'category_name',    c.name,
          'category_name_ar', c.name_ar,
          'cost_center_name', cc.name,
          'project_name',     pj.name
        ) ORDER BY l.line_no
      )
      FROM public.expense_lines l
      LEFT JOIN public.expense_categories c   ON c.id  = l.category_id
      LEFT JOIN public.expense_cost_centers cc ON cc.id = l.cost_center_id
      LEFT JOIN public.expense_projects pj    ON pj.id = l.project_id
      WHERE l.entry_id = e.id
    ), '[]'::jsonb),
    'payments', COALESCE((
      SELECT jsonb_agg(to_jsonb(p) || jsonb_build_object('created_by_name', pc.full_name)
                       ORDER BY p.payment_date, p.created_at)
      FROM public.expense_payments p
      LEFT JOIN public.profiles pc ON pc.id = p.created_by
      WHERE p.entry_id = e.id
    ), '[]'::jsonb),
    'approvals', COALESCE((
      SELECT jsonb_agg(to_jsonb(a) || jsonb_build_object('actor_name', ac.full_name)
                       ORDER BY a.sequence)
      FROM public.expense_approvals a
      LEFT JOIN public.profiles ac ON ac.id = a.actor_id
      WHERE a.entry_id = e.id
    ), '[]'::jsonb),
    'attachments', COALESCE((
      SELECT jsonb_agg(to_jsonb(t) || jsonb_build_object('uploaded_by_name', tc.full_name)
                       ORDER BY t.created_at)
      FROM public.expense_attachments t
      LEFT JOIN public.profiles tc ON tc.id = t.uploaded_by
      WHERE t.entry_id = e.id
    ), '[]'::jsonb)
  )
  FROM public.expense_entries e
  LEFT JOIN public.suppliers s  ON s.id  = e.supplier_id
  LEFT JOIN public.profiles  pr ON pr.id = e.employee_id
  LEFT JOIN public.profiles  cb ON cb.id = e.created_by
  LEFT JOIN public.profiles  ab ON ab.id = e.approved_by
  LEFT JOIN public.profiles  pb ON pb.id = e.posted_by
  LEFT JOIN public.warehouses w ON w.id  = e.warehouse_id
  LEFT JOIN public.expense_cost_centers cc ON cc.id = e.cost_center_id
  LEFT JOIN public.expense_projects pj      ON pj.id = e.project_id
  WHERE e.id = p_entry_id
$$;


--
-- Name: expense_ledger_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_ledger_summary(p_entry_id uuid, OUT o_net numeric, OUT o_tax numeric, OUT o_account_code text) RETURNS record
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    round(COALESCE(sum(l.net_amount), 0), 2) AS o_net,
    round(COALESCE(sum(l.tax_amount), 0), 2) AS o_tax,
    COALESCE((SELECT a.code
                FROM public.expense_categories c
                JOIN public.accounts a ON a.id = c.account_id
               WHERE c.id = (SELECT category_id
                               FROM public.expense_lines
                              WHERE entry_id = p_entry_id
                              ORDER BY line_no LIMIT 1)
                 AND c.account_id IS NOT NULL), '5911') AS o_account_code
  FROM public.expense_lines l
  WHERE l.entry_id = p_entry_id;
$$;


--
-- Name: FUNCTION expense_ledger_summary(p_entry_id uuid, OUT o_net numeric, OUT o_tax numeric, OUT o_account_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.expense_ledger_summary(p_entry_id uuid, OUT o_net numeric, OUT o_tax numeric, OUT o_account_code text) IS 'T-07: صافي المصروف وضريبته وحسابه من التصنيف — مصدر وحيد لقيد المصروف.';


--
-- Name: expense_line_net(numeric, numeric, public.expense_tax_mode); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_line_net(p_gross numeric, p_tax_rate numeric, p_mode public.expense_tax_mode) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_gross IS NULL THEN NULL
    WHEN p_tax_rate IS NULL OR p_tax_rate <= 0 THEN public.expense_round(p_gross)
    WHEN p_mode = 'EXCLUSIVE' THEN public.expense_round(p_gross)
    ELSE public.expense_round(p_gross / (1 + (p_tax_rate / 100)))
  END
$$;


--
-- Name: expense_line_tax(numeric, numeric, public.expense_tax_mode); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_line_tax(p_gross numeric, p_tax_rate numeric, p_mode public.expense_tax_mode) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_gross IS NULL THEN NULL
    WHEN p_tax_rate IS NULL OR p_tax_rate <= 0 THEN 0::numeric
    ELSE public.expense_round(p_gross - public.expense_line_net(p_gross, p_tax_rate, p_mode))
  END
$$;


--
-- Name: expense_log_action(uuid, text, public.expense_status, public.expense_status, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_log_action(p_entry_id uuid, p_action text, p_from public.expense_status, p_to public.expense_status, p_reason text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor    uuid := COALESCE(p_actor, auth.uid());
  v_sequence integer;
BEGIN
  SELECT COALESCE(max(sequence), 0) + 1
    INTO v_sequence
  FROM public.expense_approvals
  WHERE entry_id = p_entry_id;

  INSERT INTO public.expense_approvals (
    entry_id, sequence, action, from_status, to_status, actor_id, reason
  )
  VALUES (p_entry_id, v_sequence, p_action, p_from, p_to, v_actor,
          nullif(btrim(coalesce(p_reason, '')), ''));

  -- The generic audit log keeps the expense trail discoverable from the same
  -- screen an owner already uses for every other module.
  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_actor, 'expense.' || p_action, 'expense_entry', p_entry_id,
          jsonb_build_object('from', p_from, 'to', p_to, 'reason', p_reason));
END $$;


--
-- Name: expense_lookups(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_lookups(p_include_archived boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'categories', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'id', c.id,
               'name', c.name,
               'name_ar', c.name_ar,
               'is_active', c.is_active,
               'sort_order', c.sort_order,
               'usage_count', (SELECT count(*) FROM public.expense_lines l WHERE l.category_id = c.id),
               'account_id', c.account_id,
               'account_code', a.code,
               'account_name_ar', a.name_ar
             ) ORDER BY c.sort_order, c.name)
      FROM public.expense_categories c
      LEFT JOIN public.accounts a ON a.id = c.account_id
      WHERE p_include_archived OR c.is_active
    ), '[]'::jsonb),
    'warehouses', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'id', w.id, 'name', w.name, 'name_ar', w.name_ar, 'is_default', w.is_default
             ) ORDER BY w.name)
      FROM public.warehouses w
      WHERE w.is_active IS NOT FALSE
    ), '[]'::jsonb),
    'cost_centers', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'id', cc.id, 'code', cc.code, 'name', cc.name, 'name_ar', cc.name_ar
             ) ORDER BY cc.name)
      FROM public.expense_cost_centers cc
      WHERE cc.is_active
    ), '[]'::jsonb),
    'projects', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'id', pj.id, 'code', pj.code, 'name', pj.name, 'name_ar', pj.name_ar
             ) ORDER BY pj.name)
      FROM public.expense_projects pj
      WHERE pj.is_active
    ), '[]'::jsonb),
    'suppliers', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name) ORDER BY s.name)
      FROM public.suppliers s
      WHERE s.is_active IS NOT FALSE
    ), '[]'::jsonb),
    'employees', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) ORDER BY p.full_name)
      FROM public.profiles p
      WHERE p.is_active IS NOT FALSE
        AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = p.id)
        AND NOT EXISTS (SELECT 1 FROM public.platform_admins pa WHERE pa.user_id = p.id)
        AND p.full_name NOT ILIKE '%سوبر%'
        AND p.full_name NOT ILIKE '%superadmin%'
    ), '[]'::jsonb),
    'financial_accounts', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'id', a.id, 'code', a.code, 'name_ar', a.name_ar,
               'account_type', a.account_type,
               'requires_reconciliation', a.requires_reconciliation
             ) ORDER BY a.code)
      FROM public.accounts a
      WHERE a.is_active IS NOT FALSE
        AND (a.requires_reconciliation IS TRUE OR a.code LIKE '11%')
    ), '[]'::jsonb)
  )
$$;


--
-- Name: expense_report(text, date, date, public.expense_status[], uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_report(p_group_by text DEFAULT 'category'::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_status public.expense_status[] DEFAULT NULL::public.expense_status[], p_warehouse_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS TABLE(group_key text, label text, label_ar text, entry_count bigint, total_amount numeric, paid_amount numeric, outstanding numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
BEGIN
  -- Status default: only documents that actually affect the books. A report
  -- that silently included drafts would disagree with the ledger.
  IF p_status IS NULL THEN
    p_status := ARRAY['POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED']::public.expense_status[];
  END IF;

  IF p_group_by = 'category' THEN
    RETURN QUERY
    SELECT
      COALESCE(l.category_id::text, 'none'),
      COALESCE(c.name, 'Uncategorised'),
      COALESCE(c.name_ar, c.name, 'غير مصنّف'),
      count(DISTINCT e.id),
      COALESCE(sum(l.gross_amount), 0),
      -- Paid is allocated pro-rata by line share, because a payment settles the
      -- document, not a line. Allocating it any other way (e.g. by category
      -- order) would make the report disagree with the header totals.
      COALESCE(sum(l.gross_amount * CASE
        WHEN e.total_amount > 0 THEN e.paid_amount / e.total_amount ELSE 0 END), 0),
      COALESCE(sum(l.gross_amount * CASE
        WHEN e.total_amount > 0 THEN e.remaining_amount / e.total_amount ELSE 0 END), 0)
    FROM public.expense_lines l
    JOIN public.expense_entries e ON e.id = l.entry_id
    LEFT JOIN public.expense_categories c ON c.id = l.category_id
    WHERE e.status = ANY (p_status)
      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)
      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)
      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)
      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)
      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)
    GROUP BY l.category_id, c.name, c.name_ar
    ORDER BY 5 DESC
    LIMIT v_limit;

  ELSIF p_group_by = 'month' THEN
    RETURN QUERY
    SELECT
      to_char(date_trunc('month', e.expense_date), 'YYYY-MM'),
      to_char(date_trunc('month', e.expense_date), 'YYYY-MM'),
      to_char(date_trunc('month', e.expense_date), 'YYYY-MM'),
      count(*),
      COALESCE(sum(e.total_amount), 0),
      COALESCE(sum(e.paid_amount), 0),
      COALESCE(sum(e.remaining_amount), 0)
    FROM public.expense_entries e
    WHERE e.status = ANY (p_status)
      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)
      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)
      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)
      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)
      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)
    GROUP BY date_trunc('month', e.expense_date)
    -- Oldest first: a trend chart reads left to right, unlike a ranking table.
    ORDER BY 1 ASC
    LIMIT v_limit;

  ELSIF p_group_by = 'warehouse' THEN
    RETURN QUERY
    SELECT
      COALESCE(e.warehouse_id::text, 'none'),
      COALESCE(w.name, 'Unassigned'),
      COALESCE(w.name_ar, w.name, 'غير محدد'),
      count(*), COALESCE(sum(e.total_amount), 0),
      COALESCE(sum(e.paid_amount), 0), COALESCE(sum(e.remaining_amount), 0)
    FROM public.expense_entries e
    LEFT JOIN public.warehouses w ON w.id = e.warehouse_id
    WHERE e.status = ANY (p_status)
      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)
      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)
      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)
      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)
      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)
    GROUP BY e.warehouse_id, w.name, w.name_ar
    ORDER BY 5 DESC
    LIMIT v_limit;

  ELSIF p_group_by = 'cost_center' THEN
    RETURN QUERY
    SELECT
      COALESCE(e.cost_center_id::text, 'none'),
      COALESCE(cc.name, 'Unassigned'),
      COALESCE(cc.name_ar, cc.name, 'غير محدد'),
      count(*), COALESCE(sum(e.total_amount), 0),
      COALESCE(sum(e.paid_amount), 0), COALESCE(sum(e.remaining_amount), 0)
    FROM public.expense_entries e
    LEFT JOIN public.expense_cost_centers cc ON cc.id = e.cost_center_id
    WHERE e.status = ANY (p_status)
      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)
      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)
      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)
      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)
      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)
    GROUP BY e.cost_center_id, cc.name, cc.name_ar
    ORDER BY 5 DESC
    LIMIT v_limit;

  ELSIF p_group_by = 'project' THEN
    RETURN QUERY
    SELECT
      COALESCE(e.project_id::text, 'none'),
      COALESCE(pj.name, 'Unassigned'),
      COALESCE(pj.name_ar, pj.name, 'غير محدد'),
      count(*), COALESCE(sum(e.total_amount), 0),
      COALESCE(sum(e.paid_amount), 0), COALESCE(sum(e.remaining_amount), 0)
    FROM public.expense_entries e
    LEFT JOIN public.expense_projects pj ON pj.id = e.project_id
    WHERE e.status = ANY (p_status)
      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)
      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)
      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)
      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)
      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)
    GROUP BY e.project_id, pj.name, pj.name_ar
    ORDER BY 5 DESC
    LIMIT v_limit;

  ELSIF p_group_by = 'payee' THEN
    RETURN QUERY
    SELECT
      COALESCE(e.supplier_id::text, e.employee_id::text, e.payee_name, 'none'),
      COALESCE(s.name, pr.full_name, e.payee_name, 'Unnamed payee'),
      COALESCE(s.name, pr.full_name, e.payee_name, 'بدون جهة'),
      count(*), COALESCE(sum(e.total_amount), 0),
      COALESCE(sum(e.paid_amount), 0), COALESCE(sum(e.remaining_amount), 0)
    FROM public.expense_entries e
    LEFT JOIN public.suppliers s ON s.id = e.supplier_id
    LEFT JOIN public.profiles  pr ON pr.id = e.employee_id
    WHERE e.status = ANY (p_status)
      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)
      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)
      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)
      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)
      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)
    GROUP BY e.supplier_id, s.name, e.employee_id, pr.full_name, e.payee_name
    ORDER BY 5 DESC
    LIMIT v_limit;

  ELSIF p_group_by = 'status' THEN
    RETURN QUERY
    SELECT
      e.status::text, e.status::text, e.status::text,
      count(*), COALESCE(sum(e.total_amount), 0),
      COALESCE(sum(e.paid_amount), 0), COALESCE(sum(e.remaining_amount), 0)
    FROM public.expense_entries e
    WHERE (p_date_from IS NULL OR e.expense_date >= p_date_from)
      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)
      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)
      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)
      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)
      AND (p_status IS NULL OR e.status = ANY (p_status))
    GROUP BY e.status
    ORDER BY 5 DESC
    LIMIT v_limit;

  ELSE
    RAISE EXCEPTION
      'Unsupported group_by: %. Allowed: category, month, warehouse, cost_center, project, payee, status',
      p_group_by
      USING ERRCODE = '22023';
  END IF;
END $$;


--
-- Name: expense_role_rank(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_role_rank(p_user uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN public.has_role(p_user, 'owner')      THEN 50
    WHEN public.has_role(p_user, 'manager')    THEN 40
    WHEN public.has_role(p_user, 'accountant') THEN 30
    WHEN public.has_role(p_user, 'cashier')    THEN 20
    WHEN public.has_role(p_user, 'warehouse')  THEN 10
    ELSE 0
  END
$$;


--
-- Name: expense_round(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_round(p_value numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  -- numeric لا float: الـ 0.005 يجب أن تُدوَّر كما يتوقّع المحاسب، ومجموع مليون
  -- صف لا يجب أن يراكم انزلاق الفاصلة العائمة.
  SELECT round(coalesce(p_value, 0)::numeric, 2)
$$;


--
-- Name: expense_settlement_status(public.expense_status, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_settlement_status(p_current public.expense_status, p_paid numeric, p_total numeric) RETURNS public.expense_status
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_current NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID') THEN p_current
    WHEN coalesce(p_total, 0) <= 0 THEN p_current
    WHEN coalesce(p_paid, 0) <= 0 THEN 'POSTED'::public.expense_status
    -- Deliberately `>=` on the paid side and `>` on the zero side: a rounding
    -- remainder of less than half a unit must settle as fully paid rather than
    -- leaving a document permanently "partially paid".
    WHEN coalesce(p_paid, 0) >= coalesce(p_total, 0) - 0.005 THEN 'PAID'::public.expense_status
    ELSE 'PARTIALLY_PAID'::public.expense_status
  END
$$;


--
-- Name: expense_summary(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_summary(p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_warehouse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH scoped AS (
    SELECT e.*
    FROM public.expense_entries e
    WHERE (p_date_from IS NULL OR e.expense_date >= p_date_from)
      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)
      AND (p_warehouse_id IS NULL OR e.warehouse_id = p_warehouse_id)
      AND e.status NOT IN ('CANCELLED', 'REVERSED')
  )
  SELECT jsonb_build_object(
    'period_total',      COALESCE(sum(total_amount), 0),
    'posted_total',      COALESCE(sum(total_amount) FILTER (
                           WHERE status IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED')), 0),
    'paid_total',        COALESCE(sum(paid_amount), 0),
    'outstanding_total', COALESCE(sum(remaining_amount) FILTER (
                           WHERE status IN ('POSTED', 'PARTIALLY_PAID') AND remaining_amount > 0.005), 0),
    'pending_total',     COALESCE(sum(total_amount) FILTER (WHERE status = 'SUBMITTED'), 0),
    'draft_total',       COALESCE(sum(total_amount) FILTER (WHERE status IN ('DRAFT', 'REJECTED')), 0),
    'total_count',       count(*),
    'pending_count',     count(*) FILTER (WHERE status = 'SUBMITTED'),
    'unpaid_count',      count(*) FILTER (WHERE status = 'POSTED'),
    'partial_count',     count(*) FILTER (WHERE status = 'PARTIALLY_PAID'),
    'paid_count',        count(*) FILTER (WHERE status IN ('PAID', 'CLOSED')),
    'draft_count',       count(*) FILTER (WHERE status IN ('DRAFT', 'REJECTED')),
    'overdue_count',     count(*) FILTER (
                           WHERE status IN ('POSTED', 'PARTIALLY_PAID')
                             AND due_date IS NOT NULL
                             AND due_date < CURRENT_DATE
                             AND remaining_amount > 0.005),
    'overdue_total',     COALESCE(sum(remaining_amount) FILTER (
                           WHERE status IN ('POSTED', 'PARTIALLY_PAID')
                             AND due_date IS NOT NULL
                             AND due_date < CURRENT_DATE
                             AND remaining_amount > 0.005), 0)
  )
  FROM scoped$$;


--
-- Name: expense_write_lines(uuid, jsonb, public.expense_tax_mode); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_write_lines(p_entry_id uuid, p_lines jsonb, p_tax_mode public.expense_tax_mode, OUT o_total numeric, OUT o_count integer) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_line        jsonb;
  v_index       integer := 0;
  v_qty         numeric;
  v_price       numeric;
  v_rate        numeric;
  v_gross       numeric;
  v_net         numeric;
  v_tax         numeric;
BEGIN
  o_total := 0;
  o_count := 0;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'At least one expense line is required' USING ERRCODE = '22023';
  END IF;

  -- Replacing the whole set is intentional: a partial update would need a line
  -- identity from the client, and clients do not own line identity here.
  DELETE FROM public.expense_lines WHERE entry_id = p_entry_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    v_index := v_index + 1;

    v_qty   := COALESCE((v_line ->> 'quantity')::numeric, 1);
    v_price := COALESCE((v_line ->> 'unit_price')::numeric, 0);
    v_rate  := COALESCE((v_line ->> 'tax_rate')::numeric, 0);

    IF v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'Line %: quantity must be greater than zero', v_index USING ERRCODE = '22023';
    END IF;
    IF v_price IS NULL OR v_price < 0 THEN
      RAISE EXCEPTION 'Line %: unit price cannot be negative', v_index USING ERRCODE = '22023';
    END IF;
    IF v_rate < 0 OR v_rate > 100 THEN
      RAISE EXCEPTION 'Line %: tax rate must be between 0 and 100', v_index USING ERRCODE = '22023';
    END IF;

    -- The client sends what the operator typed — the gross figure on the paper
    -- bill. Net and tax are derived here so the two can never disagree, and so
    -- the arithmetic is identical for a JS client and a future import script.
    v_gross := public.expense_round(v_qty * v_price);
    v_net   := public.expense_line_net(v_gross, v_rate, p_tax_mode);
    v_tax   := public.expense_line_tax(v_gross, v_rate, p_tax_mode);

    INSERT INTO public.expense_lines (
      entry_id, line_no, description, category_id, quantity, unit_price,
      net_amount, tax_rate, tax_amount, gross_amount,
      cost_center_id, project_id, note
    )
    VALUES (
      p_entry_id,
      v_index,
      nullif(btrim(coalesce(v_line ->> 'description', '')), ''),
      nullif(btrim(coalesce(v_line ->> 'category_id', '')), '')::uuid,
      v_qty,
      v_price,
      v_net,
      v_rate,
      v_tax,
      v_gross,
      nullif(btrim(coalesce(v_line ->> 'cost_center_id', '')), '')::uuid,
      nullif(btrim(coalesce(v_line ->> 'project_id', '')), '')::uuid,
      nullif(btrim(coalesce(v_line ->> 'note', '')), '')
    );

    o_total := o_total + v_gross;
    o_count := o_count + 1;
  END LOOP;

  o_total := public.expense_round(o_total);

  IF o_total <= 0 THEN
    RAISE EXCEPTION 'Expense total must be greater than zero' USING ERRCODE = '22023';
  END IF;
END $$;


--
-- Name: fn_document_numbering_sequence_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_document_numbering_sequence_name(p_document_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE p_document_type
    WHEN 'sales_invoice'      THEN 'public.sales_invoice_seq'
    WHEN 'purchase_invoice'   THEN 'public.purchase_invoice_seq'
    WHEN 'sales_return'       THEN 'public.sales_return_seq'
    WHEN 'purchase_return'    THEN 'public.purchase_return_seq'
    WHEN 'stock_transfer'     THEN 'public.stock_transfer_seq'
    WHEN 'expense'            THEN 'public.expense_reference_seq'
    WHEN 'quotation'          THEN 'public.quotation_seq'
    WHEN 'purchase_order'     THEN 'public.purchase_order_seq'
    WHEN 'goods_receipt'      THEN 'public.goods_receipt_seq'
    WHEN 'sales_order'        THEN 'public.sales_order_seq'
    WHEN 'customer_payment'   THEN 'public.customer_payment_seq'
    WHEN 'supplier_payment'   THEN 'public.supplier_payment_seq'
    WHEN 'stock_adjustment'   THEN 'public.stock_adjustment_seq'
    WHEN 'milling_intake'     THEN 'public.milling_intake_seq'
    WHEN 'milling_service'    THEN 'public.milling_service_seq'
    WHEN 'journal_entry'      THEN 'public.journal_entry_seq'
    ELSE NULL
  END;
$$;


--
-- Name: fn_format_document_number(text, bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_format_document_number(p_document_type text, p_sequence bigint, p_at timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
BEGIN
  SELECT * INTO r FROM public.fn_resolve_document_numbering(p_document_type);
  IF NOT FOUND THEN
    RETURN p_sequence::text;
  END IF;
  RETURN public.fn_format_document_number(
    p_sequence, r.prefix, r.format_tokens, r.padding, r.separator, r.date_part, p_at
  );
END $$;


--
-- Name: fn_format_document_number(bigint, text, text, smallint, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_format_document_number(p_sequence bigint, p_prefix text, p_format text, p_padding smallint, p_separator text, p_date_part text, p_at timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_seq_text   text;
  v_padding    smallint := GREATEST(0, LEAST(COALESCE(p_padding, 0), 8));
  v_sep        text := COALESCE(NULLIF(p_separator, ''), '-');
  v_prefix     text := COALESCE(p_prefix, '');
  v_format     text := COALESCE(NULLIF(btrim(p_format), ''), '{PREFIX}{SEQ}');
  v_result     text;
BEGIN
  -- Padding is OPTIONAL. padding = 0 means "no leading zeros".
  v_seq_text := CASE
    WHEN v_padding = 0 THEN p_sequence::text
    WHEN length(p_sequence::text) < v_padding THEN lpad(p_sequence::text, v_padding, '0')
    ELSE p_sequence::text
  END;

  v_result := v_format;
  v_result := replace(v_result, '{PREFIX}',    v_prefix);
  v_result := replace(v_result, '{YYYY}',      to_char(p_at, 'YYYY'));
  v_result := replace(v_result, '{YY}',        to_char(p_at, 'YY'));
  v_result := replace(v_result, '{MM}',        to_char(p_at, 'MM'));
  v_result := replace(v_result, '{DD}',        to_char(p_at, 'DD'));
  v_result := replace(v_result, '{SEQ}',       v_seq_text);

  -- A separator written as "-" inside the template is normalised so an empty
  -- separator really collapses the parts instead of leaving stray dashes.
  IF v_sep <> '-' THEN
    v_result := replace(v_result, '-', v_sep);
  END IF;

  -- If the template mentions a date token that is empty (e.g. a preset with
  -- no date), collapse duplicated separators and trim stray edges.
  WHILE position(v_sep || v_sep IN v_result) > 0 LOOP
    v_result := replace(v_result, v_sep || v_sep, v_sep);
  END LOOP;
  v_result := btrim(v_result, v_sep || ' ');
  v_result := btrim(v_result);

  IF v_result = '' THEN
    v_result := v_seq_text;
  END IF;

  RETURN v_result;
END $$;


--
-- Name: fn_next_document_number(text, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_next_document_number(p_document_type text, p_company_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_pos_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_seq_name text := public.fn_document_numbering_sequence_name(p_document_type);
  v_cfg      record;
  v_number   bigint;
  v_result   text;
BEGIN
  IF v_seq_name IS NULL THEN
    RAISE EXCEPTION 'Unknown document type: %', p_document_type;
  END IF;

  SELECT * INTO v_cfg
  FROM public.fn_resolve_document_numbering(p_document_type, p_company_id, p_branch_id, p_pos_id);

  -- Atomic allocation. The sequence guarantees uniqueness even when two
  -- cashiers create the same document type in the same millisecond.
  EXECUTE format('SELECT nextval(%L)', v_seq_name) INTO v_number;

  IF v_cfg IS NULL THEN
    -- Engine row missing: still return a safe, unique number.
    RETURN v_number::text;
  END IF;

  v_result := public.fn_format_document_number(
    v_number, v_cfg.prefix, v_cfg.format_tokens, v_cfg.padding,
    v_cfg.separator, v_cfg.date_part, p_at
  );

  -- Keep the informational counter in sync (never used for allocation).
  UPDATE public.document_numbering
    SET current_value = GREATEST(current_value, v_number),
        updated_at = now()
    WHERE id = v_cfg.id;

  RETURN v_result;
END $$;


--
-- Name: document_numbering; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.document_numbering (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_type text NOT NULL,
    scope text DEFAULT 'global'::text NOT NULL,
    scope_id uuid,
    section text DEFAULT 'general'::text NOT NULL,
    label_ar text DEFAULT ''::text NOT NULL,
    label_en text DEFAULT ''::text NOT NULL,
    prefix text DEFAULT ''::text NOT NULL,
    separator text DEFAULT '-'::text NOT NULL,
    format_tokens text DEFAULT '{PREFIX}-{SEQ}'::text NOT NULL,
    padding smallint DEFAULT 0 NOT NULL,
    date_part text DEFAULT 'none'::text NOT NULL,
    reset_policy text DEFAULT 'never'::text NOT NULL,
    current_value bigint DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT document_numbering_date_check CHECK ((date_part = ANY (ARRAY['none'::text, 'year'::text, 'year_month'::text, 'full'::text]))),
    CONSTRAINT document_numbering_padding_check CHECK (((padding >= 0) AND (padding <= 8))),
    CONSTRAINT document_numbering_reset_check CHECK ((reset_policy = ANY (ARRAY['never'::text, 'yearly'::text, 'monthly'::text, 'daily'::text]))),
    CONSTRAINT document_numbering_scope_check CHECK ((scope = ANY (ARRAY['global'::text, 'company'::text, 'branch'::text, 'pos'::text])))
);


--
-- Name: TABLE document_numbering; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.document_numbering IS 'Central Document Numbering Engine configuration. The numeric sequence is kept in a PostgreSQL sequence (atomic, gap tolerant); this table stores how that number is presented. Document numbers are frozen on the document row when it is created, so editing this table never rewrites history.';


--
-- Name: fn_resolve_document_numbering(text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_resolve_document_numbering(p_document_type text, p_company_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_pos_id uuid DEFAULT NULL::uuid) RETURNS public.document_numbering
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT d.*
  FROM public.document_numbering d
  WHERE d.document_type = p_document_type
    AND (
      (d.scope = 'pos'     AND p_pos_id     IS NOT NULL AND d.scope_id = p_pos_id)
      OR (d.scope = 'branch'  AND p_branch_id  IS NOT NULL AND d.scope_id = p_branch_id)
      OR (d.scope = 'company' AND p_company_id IS NOT NULL AND d.scope_id = p_company_id)
      OR (d.scope = 'global'  AND d.scope_id IS NULL)
    )
  ORDER BY CASE d.scope
             WHEN 'pos'     THEN 1
             WHEN 'branch'  THEN 2
             WHEN 'company' THEN 3
             ELSE 4
           END
  LIMIT 1;
$$;


--
-- Name: fn_set_document_numbering(text, text, text, smallint, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_set_document_numbering(p_document_type text, p_prefix text DEFAULT NULL::text, p_format_tokens text DEFAULT NULL::text, p_padding smallint DEFAULT NULL::smallint, p_date_part text DEFAULT NULL::text, p_separator text DEFAULT NULL::text, p_reset_policy text DEFAULT NULL::text, p_next_value bigint DEFAULT NULL::bigint) RETURNS public.document_numbering
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_seq     text := public.fn_document_numbering_sequence_name(p_document_type);
  v_row     public.document_numbering;
  v_max     bigint := 0;
  v_is_called boolean;
  v_expected bigint;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT (public.has_role(v_uid, 'owner') OR public.has_role(v_uid, 'manager')) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  IF v_seq IS NULL THEN
    RAISE EXCEPTION 'Unknown document type: %', p_document_type;
  END IF;

  SELECT * INTO v_row
  FROM public.document_numbering
  WHERE document_type = p_document_type AND scope = 'global'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No numbering configuration for %', p_document_type;
  END IF;

  -- ── Guard: never allow a starting value that would duplicate a number that
  --    has already been issued for this document type.
  IF p_next_value IS NOT NULL THEN
    IF p_next_value < 0 THEN
      RAISE EXCEPTION 'Starting number cannot be negative';
    END IF;

    -- Highest number actually visible in the documents, parsed from the tail
    -- of the stored text ("INV-202610-0125" -> 125).
    v_max := CASE p_document_type
      WHEN 'sales_invoice'    THEN (SELECT COALESCE(MAX(NULLIF(regexp_replace(invoice_number, '\D', '', 'g'), '')::bigint), 0) FROM public.sales_invoices)
      WHEN 'purchase_invoice' THEN (SELECT COALESCE(MAX(NULLIF(regexp_replace(invoice_number, '\D', '', 'g'), '')::bigint), 0) FROM public.purchase_invoices)
      WHEN 'sales_return'     THEN (SELECT COALESCE(MAX(NULLIF(regexp_replace(return_number, '\D', '', 'g'), '')::bigint), 0) FROM public.sales_returns)
      WHEN 'purchase_return'  THEN (SELECT COALESCE(MAX(NULLIF(regexp_replace(return_number, '\D', '', 'g'), '')::bigint), 0) FROM public.purchase_returns)
      WHEN 'stock_transfer'   THEN (SELECT COALESCE(MAX(NULLIF(regexp_replace(transfer_number, '\D', '', 'g'), '')::bigint), 0) FROM public.stock_transfers)
      ELSE 0
    END;

    IF p_next_value <= v_max THEN
      RAISE EXCEPTION
        'Starting number % is not greater than an existing number (%). Choose a value above %.',
        p_next_value, v_max, v_max;
    END IF;

    SELECT is_called, last_value INTO v_is_called, v_expected
      FROM public.document_numbering WHERE id = v_row.id; -- placeholder, replaced below

    -- is_called is read from the real sequence.
    EXECUTE format('SELECT is_called, last_value FROM %s', v_seq) INTO v_is_called, v_expected;

    -- setval(seq, n, false) -> the NEXT nextval() returns exactly n.
    EXECUTE format('SELECT setval(%L, %s, false)', v_seq, p_next_value);
  END IF;

  UPDATE public.document_numbering SET
    prefix        = COALESCE(p_prefix,        prefix),
    format_tokens = COALESCE(p_format_tokens, format_tokens),
    padding       = COALESCE(p_padding,       padding),
    date_part     = COALESCE(p_date_part,     date_part),
    separator     = COALESCE(p_separator,     separator),
    reset_policy  = COALESCE(p_reset_policy,  reset_policy),
    current_value = CASE
                      WHEN p_next_value IS NOT NULL THEN p_next_value - 1
                      ELSE current_value
                    END,
    updated_at    = now()
  WHERE id = v_row.id
  RETURNING * INTO v_row;

  -- Audit trail (best effort: projects without the log table stay silent).
  BEGIN
    INSERT INTO public.backup_logs (log_type, status, message, details)
    VALUES (
      'settings',
      'success',
      'Document numbering updated: ' || p_document_type,
      jsonb_build_object(
        'document_type', p_document_type,
        'next_value',    p_next_value,
        'prefix',        v_row.prefix,
        'format_tokens', v_row.format_tokens,
        'padding',       v_row.padding,
        'date_part',     v_row.date_part,
        'actor',         v_uid
      )
    );
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    NULL;
  END;

  RETURN v_row;
END $$;


--
-- Name: generate_tax_declaration(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_tax_declaration(p_start_date date, p_end_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user          uuid := auth.uid();
  v_sales_taxable numeric(18,2) := 0;
  v_output_tax    numeric(18,2) := 0;
  v_purch_taxable numeric(18,2) := 0;
  v_input_tax     numeric(18,2) := 0;
  v_net_tax       numeric(18,2) := 0;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'Tax declaration needs both start_date and end_date'
      USING ERRCODE = '22023';
  END IF;
  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'Tax declaration end_date (%) is before start_date (%)', p_end_date, p_start_date
      USING ERRCODE = '22023';
  END IF;

  -- 1) ضريبة المخرجات من القيود المرحلة لحساب 2311 (رصيد دائن)
  SELECT coalesce(sum(jl.credit - jl.debit), 0)
    INTO v_output_tax
    FROM public.journal_lines jl
    JOIN public.journal_entries je ON je.id = jl.entry_id
    JOIN public.accounts a ON a.id = jl.account_id
   WHERE a.code = '2311'
     AND je.status = 'POSTED'
     AND je.source_type <> 'tax_settlement'
     AND je.entry_date BETWEEN p_start_date AND p_end_date;

  -- 2) ضريبة المدخلات من القيود المرحلة لحساب 1316 (رصيد مدين)
  SELECT coalesce(sum(jl.debit - jl.credit), 0)
    INTO v_input_tax
    FROM public.journal_lines jl
    JOIN public.journal_entries je ON je.id = jl.entry_id
    JOIN public.accounts a ON a.id = jl.account_id
   WHERE a.code = '1316'
     AND je.status = 'POSTED'
     AND je.source_type <> 'tax_settlement'
     AND je.entry_date BETWEEN p_start_date AND p_end_date;

  -- 3) إجمالي المبيعات الخاضعة للضريبة.
  --    ⚠️ sales_invoices ليس فيها invoice_date. التاريخ التشغيلي هو created_at
  --    (نفس ما تعتمده تقارير 12 ويومية الترحيل). المقارنة نصف مفتوحة كي لا
  --    تسقط فواتير آخر يوم في الفترة.
  SELECT coalesce(sum(subtotal), 0)
    INTO v_sales_taxable
    FROM public.sales_invoices
   WHERE status = 'confirmed'
     AND created_at >= p_start_date::timestamptz
     AND created_at <  (p_end_date + 1)::timestamptz;

  -- 4) إجمالي المشتريات في الفترة
  SELECT coalesce(sum(subtotal), 0)
    INTO v_purch_taxable
    FROM public.purchase_invoices
   WHERE status = 'confirmed'
     AND created_at >= p_start_date::timestamptz
     AND created_at <  (p_end_date + 1)::timestamptz;

  v_net_tax := v_output_tax - v_input_tax;

  RETURN jsonb_build_object(
    'start_date', p_start_date,
    'end_date', p_end_date,
    'taxable_sales', v_sales_taxable,
    'output_tax', v_output_tax,
    'taxable_purchases', v_purch_taxable,
    'input_tax', v_input_tax,
    'net_tax_payable', v_net_tax
  );
END $$;


--
-- Name: FUNCTION generate_tax_declaration(p_start_date date, p_end_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_tax_declaration(p_start_date date, p_end_date date) IS 'T-23: أرقام الإقرار الضريبي للفترة. تاريخ الفواتير = created_at (لا يوجد invoice_date في المخطط).';


--
-- Name: get_batch_kpis(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_batch_kpis(p_warning_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := CURRENT_DATE;
  v_soon_limit date := CURRENT_DATE + (coalesce(p_warning_days, 30) || ' days')::interval;
  v_total bigint;
  v_expired bigint;
  v_soon bigint;
  v_valid bigint;
  v_none bigint;
BEGIN
  SELECT
    count(*),
    count(*) FILTER (WHERE expiry_date IS NOT NULL AND expiry_date <= v_today),
    count(*) FILTER (WHERE expiry_date IS NOT NULL AND expiry_date > v_today AND expiry_date <= v_soon_limit),
    count(*) FILTER (WHERE expiry_date IS NOT NULL AND expiry_date > v_soon_limit),
    count(*) FILTER (WHERE expiry_date IS NULL)
  INTO
    v_total, v_expired, v_soon, v_valid, v_none
  FROM public.product_batches;

  RETURN jsonb_build_object(
    'total', coalesce(v_total, 0),
    'expired', coalesce(v_expired, 0),
    'soon', coalesce(v_soon, 0),
    'valid', coalesce(v_valid, 0),
    'none', coalesce(v_none, 0),
    'at_risk', coalesce(v_expired, 0) + coalesce(v_soon, 0)
  );
END $$;


--
-- Name: get_batch_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_batch_settings() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    batch_settings,
    '{
      "dispatch_strategy": "FEFO",
      "prevent_selling_expired": true,
      "warning_days": 30,
      "enforce_on_purchase": false,
      "enforce_batch_selection_on_pos": false,
      "auto_sync_inventory": true
    }'::jsonb
  )
  FROM public.company_settings
  LIMIT 1;
$$;


--
-- Name: get_chart_of_accounts_tree(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_chart_of_accounts_tree() RETURNS TABLE(id uuid, code character varying, name_ar text, account_type public.account_type, parent_id uuid, parent_code character varying, level integer, is_postable boolean, is_system boolean, is_active boolean, notes text, total_debit numeric, total_credit numeric, current_balance numeric, children_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE coa_tree AS (
    -- الجذور (المستوى 1: الأصول، الخصوم، حقوق الملكية، الإيرادات، المصروفات)
    SELECT
      a.id,
      a.code,
      a.name_ar,
      a.account_type,
      a.parent_id,
      CAST(NULL AS varchar(20)) AS parent_code,
      1 AS level,
      a.is_postable,
      a.is_system,
      a.is_active,
      a.notes,
      ARRAY[a.code::text] AS path
    FROM public.accounts a
    WHERE a.parent_id IS NULL

    UNION ALL

    -- الأبناء بالتكرار
    SELECT
      c.id,
      c.code,
      c.name_ar,
      c.account_type,
      c.parent_id,
      p.code AS parent_code,
      p.level + 1 AS level,
      c.is_postable,
      c.is_system,
      c.is_active,
      c.notes,
      p.path || c.code::text AS path
    FROM public.accounts c
    JOIN coa_tree p ON c.parent_id = p.id
  ),
  account_balances AS (
    -- مجاميع القيود المرحلة من دفتر اليومية لكل حساب
    SELECT
      jl.account_id,
      round(coalesce(sum(jl.debit), 0), 2) AS debit,
      round(coalesce(sum(jl.credit), 0), 2) AS credit
    FROM public.journal_lines jl
    JOIN public.journal_entries je ON je.id = jl.entry_id AND je.status = 'POSTED'
    GROUP BY jl.account_id
  ),
  children_counts AS (
    SELECT parent_id, count(*) AS cnt
    FROM public.accounts
    WHERE parent_id IS NOT NULL
    GROUP BY parent_id
  )
  SELECT
    t.id,
    t.code,
    t.name_ar,
    t.account_type,
    t.parent_id,
    t.parent_code,
    t.level,
    t.is_postable,
    t.is_system,
    t.is_active,
    t.notes,
    coalesce(ab.debit, 0) AS total_debit,
    coalesce(ab.credit, 0) AS total_credit,
    CASE
      -- طبيعة مدينة للأصول والمصروفات: مدين - دائن
      WHEN t.account_type IN ('ASSET', 'EXPENSE') THEN
        round(coalesce(ab.debit, 0) - coalesce(ab.credit, 0), 2)
      -- طبيعة دائنة للخصوم وحقوق الملكية والإيرادات: دائن - مدين
      ELSE
        round(coalesce(ab.credit, 0) - coalesce(ab.debit, 0), 2)
    END AS current_balance,
    coalesce(cc.cnt, 0) AS children_count
  FROM coa_tree t
  LEFT JOIN account_balances ab ON ab.account_id = t.id
  LEFT JOIN children_counts cc ON cc.parent_id = t.id
  ORDER BY t.code ASC;
$$;


--
-- Name: FUNCTION get_chart_of_accounts_tree(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_chart_of_accounts_tree() IS 'T-25: استخراج الشجرة الهرمية الكاملة لدليل الحسابات مع مستويات التفرع، ومجاميع القيود، والأرصدة حسب طبيعة الحساب.';


--
-- Name: get_supplier_statement(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supplier_statement(p_supplier_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(id uuid, occurred_at timestamp with time zone, entry_type text, debit numeric, credit numeric, running_balance numeric, reference_type text, reference_id uuid, due_date date, note text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.can_read_finance(auth.uid()) THEN
    RAISE EXCEPTION 'Only finance roles may read supplier statements'
      USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    WITH ordered_entries AS (
      SELECT sl.id, sl.occurred_at, sl.entry_type, sl.debit, sl.credit,
        SUM(sl.credit - sl.debit) OVER (ORDER BY sl.occurred_at ASC, sl.id ASC) AS running_balance,
        sl.reference_type, sl.reference_id, sl.due_date, sl.note
      FROM public.supplier_ledger sl
      WHERE sl.supplier_id = p_supplier_id
    )
    SELECT oe.id, oe.occurred_at, oe.entry_type, oe.debit, oe.credit, oe.running_balance,
      oe.reference_type, oe.reference_id, oe.due_date, oe.note
    FROM ordered_entries oe
    WHERE (p_start_date IS NULL OR oe.occurred_at >= p_start_date)
      AND (p_end_date IS NULL OR oe.occurred_at <= p_end_date)
    ORDER BY oe.occurred_at DESC, oe.id DESC;
END;
$$;


--
-- Name: FUNCTION get_supplier_statement(p_supplier_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_supplier_statement(p_supplier_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone) IS 'T-24: جلب كشف حساب المورد التفصيلي مع احتساب الرصيد التراكمي المستحق للمورد عبر الفترات.';


--
-- Name: grain_types_output_map_ratio_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grain_types_output_map_ratio_is_valid(p_output_map jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN jsonb_typeof(p_output_map) <> 'array' THEN false
    ELSE COALESCE((
      SELECT SUM((entry->>'ratio')::numeric)
      FROM jsonb_array_elements(p_output_map) AS entry
    ), 0) <= 100
  END;
$$;


--
-- Name: guard_four_payment_method_catalogue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_four_payment_method_catalogue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.is_active AND NEW.id NOT IN (
    'cash', 'credit', 'bank_transfer', 'mobile_money', 'split'
  ) THEN
    RAISE EXCEPTION 'Only four payment methods and the split document state may remain active: %', NEW.id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_four_payment_method_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_four_payment_method_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_method text := nullif(lower(btrim(to_jsonb(NEW) ->> TG_ARGV[0])), '');
  v_method_id text;
  v_context text := TG_ARGV[2];
  v_old_method text;
  v_old_id text;
  v_allow_split boolean := coalesce(TG_ARGV[3], 'false')::boolean;
  v_allow_credit boolean := coalesce(TG_ARGV[4], 'false')::boolean;
  v_resolved text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    v_old_method := nullif(lower(btrim(to_jsonb(OLD) ->> TG_ARGV[0])), '');
    IF TG_ARGV[1] <> '' THEN
      v_old_id := nullif(to_jsonb(OLD) ->> TG_ARGV[1], '');
    END IF;
  END IF;
  IF TG_ARGV[1] <> '' THEN
    v_method_id := nullif(to_jsonb(NEW) ->> TG_ARGV[1], '');
  END IF;
  IF TG_OP = 'UPDATE'
     AND v_method IS NOT DISTINCT FROM v_old_method
     AND v_method_id IS NOT DISTINCT FROM v_old_id THEN
    RETURN NEW;
  END IF;
  IF v_method IS NULL THEN
    RETURN NEW;
  END IF;
  IF v_method = 'split' AND v_allow_split THEN
    RETURN NEW;
  END IF;
  IF v_method = 'credit' AND NOT v_allow_credit THEN
    RAISE EXCEPTION 'Credit is not a tender for this transaction type'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_context = 'document' THEN
    v_context := CASE to_jsonb(NEW) ->> 'document_type'
      WHEN 'purchase_invoice' THEN 'purchases'
      WHEN 'milling_service_document' THEN 'sales'
      ELSE NULL
    END;
  END IF;
  v_resolved := public.resolve_writable_payment_method(
    coalesce(v_method_id, v_method), v_context, true
  );
  IF v_resolved IS DISTINCT FROM v_method THEN
    RAISE EXCEPTION 'Payment method identity does not match stored value (%)', v_method
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.profiles (id, full_name, avatar_url, language, theme)
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),
    NEW.raw_user_meta_data->>'avatar_url',
    'ar',
    'dark'
  )
  ON CONFLICT (id) DO UPDATE
    SET full_name = COALESCE(EXCLUDED.full_name, public.profiles.full_name);

  RETURN NEW;
END;
$$;


--
-- Name: has_role(uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role)
$$;


--
-- Name: FUNCTION has_role(_user_id uuid, _role public.app_role); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_role(_user_id uuid, _role public.app_role) IS 'تُستدعى من سياسات RLS. التنفيذ لـ authenticated و service_role فقط.';


--
-- Name: is_platform_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_platform_admin(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.platform_admins
    WHERE user_id = p_user_id
      AND is_active = true
  );
$$;


--
-- Name: is_platform_superadmin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_platform_superadmin(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- 'superadmin' only — not 'admin'. The table's CHECK constraint allows
  -- exactly two roles, superadmin and support, so a predicate accepting
  -- 'admin' could never be satisfied by a stored row: it was dead code that
  -- read as if a third role existed. 'support' is deliberately excluded —
  -- it is read-only and must not satisfy superadmin-only policies.
  SELECT EXISTS (
    SELECT 1
    FROM public.platform_admins
    WHERE user_id = p_user_id
      AND role = 'superadmin'
      AND is_active = true
  );
$$;


--
-- Name: is_staff(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id)
    AND COALESCE((SELECT is_active FROM public.profiles WHERE id = _user_id), false)
$$;


--
-- Name: FUNCTION is_staff(_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_staff(_user_id uuid) IS 'تُستدعى من سياسات RLS. التنفيذ لـ authenticated و service_role فقط.';


