--
-- Name: run_batch_amortization(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_batch_amortization(p_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user    uuid := auth.uid();
  r         record;
  v_entry   uuid;
  v_count   integer := 0;
  v_skipped integer := 0;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner')
          OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may run batch amortization';
  END IF;

  FOR r IN
    SELECT id, contract_number FROM public.prepaid_and_deferred_contracts
     WHERE status = 'ACTIVE'
     ORDER BY start_date ASC
  LOOP
    BEGIN
      v_entry := public.run_contract_amortization(r.id, p_date);
      IF v_entry IS NOT NULL THEN
        v_count := v_count + 1;
      ELSE
        v_skipped := v_skipped + 1;
      END IF;
    EXCEPTION WHEN others THEN
      v_skipped := v_skipped + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'date', p_date,
    'amortized_count', v_count,
    'skipped_count', v_skipped
  );
END $$;


--
-- Name: run_batch_depreciation(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_batch_depreciation(p_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user      uuid := auth.uid();
  r           record;
  v_entry     uuid;
  v_count     integer := 0;
  v_total     numeric(18,2) := 0;
  v_skipped   integer := 0;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner')
          OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may run batch depreciation';
  END IF;

  FOR r IN
    SELECT id, asset_code FROM public.fixed_assets
     WHERE status = 'ACTIVE'
     ORDER BY purchase_date ASC
  LOOP
    BEGIN
      v_entry := public.run_depreciation(r.id, p_date);
      IF v_entry IS NOT NULL THEN
        v_count := v_count + 1;
      ELSE
        v_skipped := v_skipped + 1;
      END IF;
    EXCEPTION WHEN others THEN
      -- تخطي ما تم إهلاكه سابقاً في نفس اليوم
      v_skipped := v_skipped + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'date', p_date,
    'depreciated_count', v_count,
    'skipped_count', v_skipped
  );
END $$;


--
-- Name: run_contract_amortization(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_contract_amortization(p_contract_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user        uuid := auth.uid();
  v_rec         record;
  v_period_amt  numeric(18,2);
  v_amount      numeric(18,2);
  v_new_amort   numeric(18,2);
  v_new_rem     numeric(18,2);
  v_entry_id    uuid;
  v_memo        text;
  v_lines       jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner')
          OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may amortize prepaid contracts';
  END IF;

  -- فحص الفترة المالية
  PERFORM public.assert_period_open(p_date);

  SELECT * INTO v_rec FROM public.prepaid_and_deferred_contracts WHERE id = p_contract_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contract not found';
  END IF;

  IF v_rec.status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'Contract % is not active (status: %)', v_rec.contract_number, v_rec.status;
  END IF;

  -- منع تكرار الاستهلاك لنفس العقد في نفس التاريخ
  IF EXISTS (
    SELECT 1 FROM public.amortization_lines
     WHERE contract_id = p_contract_id AND period_date = p_date
  ) THEN
    RAISE EXCEPTION 'Contract % has already been amortized on %', v_rec.contract_number, p_date;
  END IF;

  IF v_rec.remaining_amount <= 0 THEN
    UPDATE public.prepaid_and_deferred_contracts
       SET status = 'COMPLETED'
     WHERE id = p_contract_id;
    RETURN NULL;
  END IF;

  v_period_amt := round(v_rec.total_amount / v_rec.total_periods, 2);
  v_amount     := least(v_period_amt, v_rec.remaining_amount);

  IF v_amount <= 0 THEN
    RETURN NULL;
  END IF;

  v_new_amort := v_rec.amortized_amount + v_amount;
  v_new_rem   := v_rec.total_amount - v_new_amort;

  -- بناء القيد المحاسبي المتوازن حسب نوع العقد
  IF v_rec.contract_type IN ('PREPAID_EXPENSE', 'DEFERRED_EXPENSE') THEN
    -- استهلاك مصروف مقدم: Dr حساب المصروف الفعلي / Cr حساب المصروف المقدم (1511/1512)
    v_memo := 'استهلاك قسط مصروف مقدم — ' || v_rec.title || ' (' || v_rec.contract_number || ')';
    v_lines := jsonb_build_array(
      jsonb_build_object(
        'account_code', v_rec.target_account_code,
        'debit', v_amount,
        'credit', 0,
        'memo', 'تحميل مصروف الفترة — ' || v_rec.title
      ),
      jsonb_build_object(
        'account_code', v_rec.balance_account_code,
        'debit', 0,
        'credit', v_amount,
        'memo', 'تخفيض المصروف المقدم — ' || v_rec.title
      )
    );
  ELSE
    -- تحقق إيراد مؤجل: Dr حساب الإيراد المؤجل (2231) / Cr حساب الإيراد الفعلي (4xxx)
    v_memo := 'اعتراف بقسط إيراد مؤجل — ' || v_rec.title || ' (' || v_rec.contract_number || ')';
    v_lines := jsonb_build_array(
      jsonb_build_object(
        'account_code', v_rec.balance_account_code,
        'debit', v_amount,
        'credit', 0,
        'memo', 'تخفيض التزام الإيراد المؤجل — ' || v_rec.title
      ),
      jsonb_build_object(
        'account_code', v_rec.target_account_code,
        'debit', 0,
        'credit', v_amount,
        'memo', 'تحقق إيراد الفترة — ' || v_rec.title
      )
    );
  END IF;

  v_entry_id := public.create_journal_entry(
    v_memo,
    p_date,
    'prepaid_amortization',
    p_contract_id,
    true,
    v_lines,
    false
  );

  -- تسجيل في سجل الاستهلاك
  INSERT INTO public.amortization_lines (
    contract_id, period_date, amount, remaining_after, journal_entry_id
  )
  VALUES (
    p_contract_id, p_date, v_amount, v_new_rem, v_entry_id
  );

  -- تحديث العقد
  UPDATE public.prepaid_and_deferred_contracts
     SET amortized_amount       = v_new_amort,
         remaining_amount       = v_new_rem,
         last_amortization_date = p_date,
         status                 = CASE WHEN v_new_rem <= 0 THEN 'COMPLETED' ELSE 'ACTIVE' END
   WHERE id = p_contract_id;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'prepaid_contract.amortized', 'prepaid_contract', p_contract_id,
          jsonb_build_object('contract_number', v_rec.contract_number, 'amount', v_amount,
                             'journal_entry_id', v_entry_id, 'remaining', v_new_rem));

  RETURN v_entry_id;
END $$;


--
-- Name: FUNCTION run_contract_amortization(p_contract_id uuid, p_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.run_contract_amortization(p_contract_id uuid, p_date date) IS 'T-22: توزيع واستهلاك قسط المصروف أو الإيراد المقدم بقيد مزدوج متوازن مع منع التكرار وتحديث الأرصدة.';


--
-- Name: run_depreciation(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_depreciation(p_asset_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user        uuid := auth.uid();
  v_asset       record;
  v_monthly     numeric(18,2);
  v_depreciable numeric(18,2);
  v_remaining   numeric(18,2);
  v_amount      numeric(18,2);
  v_new_acc     numeric(18,2);
  v_new_book    numeric(18,2);
  v_entry_id    uuid;
  v_memo        text;
  v_lines       jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner')
          OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may run asset depreciation';
  END IF;

  -- فحص الفترة المالية
  PERFORM public.assert_period_open(p_date);

  SELECT * INTO v_asset FROM public.fixed_assets WHERE id = p_asset_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fixed asset not found';
  END IF;

  IF v_asset.status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'Asset % is not active (status: %)', v_asset.asset_code, v_asset.status;
  END IF;

  -- منع تكرار الإهلاك في نفس التاريخ المحدد للأصل
  IF EXISTS (
    SELECT 1 FROM public.asset_depreciation_lines
     WHERE asset_id = p_asset_id AND depreciation_date = p_date
  ) THEN
    RAISE EXCEPTION 'Asset % has already been depreciated on %', v_asset.asset_code, p_date;
  END IF;

  -- حساب الإهلاك بالقسط الثابت: (التكلفة - قيمة الخردة) / العمر الإنتاجي
  v_depreciable := v_asset.purchase_cost - v_asset.salvage_value;
  v_monthly     := round(v_depreciable / v_asset.useful_life_months, 2);
  v_remaining   := v_depreciable - v_asset.accumulated_depreciation;

  IF v_remaining <= 0 THEN
    UPDATE public.fixed_assets
       SET status = 'FULLY_DEPRECIATED'
     WHERE id = p_asset_id;
    RETURN NULL;
  END IF;

  v_amount := least(v_monthly, v_remaining);
  IF v_amount <= 0 THEN
    RETURN NULL;
  END IF;

  v_new_acc  := v_asset.accumulated_depreciation + v_amount;
  v_new_book := v_asset.purchase_cost - v_new_acc;

  -- بناء القيد المحاسبي المتوازن: Dr 5611 / Cr 1491
  v_memo := 'إهلاك أصل ثابت ' || v_asset.asset_code || ' (' || v_asset.name_ar || ') بتاريخ ' || to_char(p_date, 'YYYY-MM-DD');
  v_lines := jsonb_build_array(
    jsonb_build_object(
      'account_code', v_asset.depreciation_expense_account_code, -- 5611
      'debit', v_amount,
      'credit', 0,
      'memo', 'مصروف إهلاك — ' || v_asset.name_ar
    ),
    jsonb_build_object(
      'account_code', v_asset.accumulated_depreciation_account_code, -- 1491
      'debit', 0,
      'credit', v_amount,
      'memo', 'مجمع إهلاك — ' || v_asset.name_ar
    )
  );

  v_entry_id := public.create_journal_entry(
    v_memo,
    p_date,
    'fixed_asset_depreciation',
    p_asset_id,
    true, -- قيد نظامي
    v_lines,
    false
  );

  -- تسجيل في سجل الإهلاك
  INSERT INTO public.asset_depreciation_lines (
    asset_id, depreciation_date, depreciation_amount, book_value_before, book_value_after, journal_entry_id
  )
  VALUES (
    p_asset_id, p_date, v_amount, v_asset.current_book_value, v_new_book, v_entry_id
  );

  -- تحديث الأصل
  UPDATE public.fixed_assets
     SET accumulated_depreciation = v_new_acc,
         current_book_value       = v_new_book,
         last_depreciation_date   = p_date,
         status                   = CASE WHEN v_new_acc >= v_depreciable THEN 'FULLY_DEPRECIATED' ELSE 'ACTIVE' END
   WHERE id = p_asset_id;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'fixed_asset.depreciated', 'fixed_asset', p_asset_id,
          jsonb_build_object('asset_code', v_asset.asset_code, 'amount', v_amount,
                             'journal_entry_id', v_entry_id, 'new_book_value', v_new_book));

  RETURN v_entry_id;
END $$;


--
-- Name: FUNCTION run_depreciation(p_asset_id uuid, p_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.run_depreciation(p_asset_id uuid, p_date date) IS 'T-21: ترحيل قسط الإهلاك الدوري للأصل الثابت بالقيد المتوازن Dr 5611 / Cr 1491 مع تحديث القيمة الدفترية ومنع التكرار.';


--
-- Name: sale_line_unit_cost(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sale_line_unit_cost(p_product_id uuid, p_warehouse_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    public.resolve_unit_cost(p_product_id, p_warehouse_id),
    (SELECT p.cost_price FROM public.products p WHERE p.id = p_product_id),
    0
  );
$$;


--
-- Name: sales_invoice_tender_breakdown(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_invoice_tender_breakdown(_invoice_id uuid) RETURNS TABLE(method text, amount numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT s.method::text, s.amount
  FROM public.customer_payment_splits AS s
  WHERE s.invoice_id = _invoice_id
  ORDER BY s.amount DESC;
$$;


--
-- Name: sales_line_cost(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_line_cost(p_item_id uuid, p_invoice_id uuid, p_quantity numeric, p_line_type text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_movement_cost numeric;
  v_costing       public.costing_method;
  v_reference     numeric;
BEGIN
  -- A service line carries no inventory cost. That is not a missing value.
  IF p_item_id IS NULL OR p_line_type IN ('SERVICE', 'AD_HOC_SERVICE') THEN
    RETURN 0;
  END IF;

  -- (a) The real cost of what actually left the warehouse for this invoice.
  SELECT m.unit_cost
    INTO v_movement_cost
  FROM public.stock_movements m
  WHERE m.product_id = p_item_id
    AND m.reference_id = p_invoice_id
    AND m.reference_type = 'sales_invoice'
    AND m.movement_kind = 'ISSUE'
    AND m.unit_cost IS NOT NULL
  ORDER BY m.created_at DESC
  LIMIT 1;

  IF v_movement_cost IS NOT NULL THEN
    RETURN round(coalesce(p_quantity, 0) * v_movement_cost, 2);
  END IF;

  -- (b) No movement cost. Only a declared STANDARD cost is a legitimate
  -- fallback, because the business chose that policy explicitly.
  SELECT COALESCE(ci.costing_method, p.costing_method),
         COALESCE(ci.default_cost, p.cost_price)
    INTO v_costing, v_reference
  FROM public.products p
  LEFT JOIN public.company_items ci
    ON ci.item_id = p.id AND ci.company_id = 1 AND ci.is_active
  WHERE p.id = p_item_id;

  IF v_costing = 'STANDARD' AND v_reference IS NOT NULL THEN
    RETURN round(coalesce(p_quantity, 0) * v_reference, 2);
  END IF;

  -- (c) Unknown. Deliberately NULL, never a guess.
  RETURN NULL;
END $$;


--
-- Name: save_batch_settings(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_batch_settings(p_settings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_merged jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN
    RAISE EXCEPTION 'Not authorized to change company settings';
  END IF;

  UPDATE public.company_settings
  SET batch_settings = coalesce(batch_settings, '{}'::jsonb) || p_settings,
      updated_at = now()
  RETURNING batch_settings INTO v_merged;

  RETURN v_merged;
END $$;


--
-- Name: save_expense_category(uuid, text, text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_expense_category(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_name_ar text DEFAULT NULL::text, p_sort_order integer DEFAULT NULL::integer, p_notes text DEFAULT NULL::text, p_is_active boolean DEFAULT NULL::boolean) RETURNS public.expense_categories
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user     uuid := public.expense_actor();
  v_category public.expense_categories;
  v_name     text := nullif(btrim(coalesce(p_name, '')), '');
BEGIN
  PERFORM public.expense_assert_capability(v_user, 'expense.category.manage');

  IF p_id IS NULL THEN
    IF v_name IS NULL THEN
      RAISE EXCEPTION 'A category needs a name' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.expense_categories (name, name_ar, sort_order, notes, created_by, is_active)
    VALUES (
      v_name,
      nullif(btrim(coalesce(p_name_ar, '')), ''),
      COALESCE(p_sort_order, 100),
      nullif(btrim(coalesce(p_notes, '')), ''),
      v_user,
      COALESCE(p_is_active, true)
    )
    RETURNING * INTO v_category;

    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
    VALUES (v_user, 'expense.category.created', 'expense_category', v_category.id,
            jsonb_build_object('name', v_category.name));
  ELSE
    -- The UNIQUE(name) constraint from the original migration would raise a raw
    -- 23505 the operator cannot read; checked explicitly so the message is
    -- usable and names the clash.
    IF v_name IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.expense_categories c
      WHERE upper(btrim(c.name)) = upper(v_name) AND c.id <> p_id
    ) THEN
      RAISE EXCEPTION 'A category named "%" already exists', v_name USING ERRCODE = '23505';
    END IF;

    UPDATE public.expense_categories
       SET name       = COALESCE(v_name, name),
           name_ar    = CASE WHEN p_name_ar IS NULL THEN name_ar
                             ELSE nullif(btrim(p_name_ar), '') END,
           sort_order = COALESCE(p_sort_order, sort_order),
           notes      = CASE WHEN p_notes IS NULL THEN notes
                             ELSE nullif(btrim(p_notes), '') END,
           is_active  = COALESCE(p_is_active, is_active)
     WHERE id = p_id
    RETURNING * INTO v_category;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Category not found' USING ERRCODE = 'P0002';
    END IF;

    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
    VALUES (v_user, 'expense.category.updated', 'expense_category', v_category.id,
            jsonb_build_object('name', v_category.name, 'is_active', v_category.is_active));
  END IF;

  RETURN v_category;
END $$;


--
-- Name: save_expense_dimension(text, uuid, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_expense_dimension(p_kind text, p_id uuid DEFAULT NULL::uuid, p_code text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_name_ar text DEFAULT NULL::text, p_is_active boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := public.expense_actor();
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_code text := nullif(btrim(coalesce(p_code, '')), '');
  v_row  jsonb;
BEGIN
  PERFORM public.expense_assert_capability(v_user, 'expense.dimension.manage');

  IF p_kind NOT IN ('cost_center', 'project') THEN
    RAISE EXCEPTION 'Unknown dimension kind: %', p_kind USING ERRCODE = '22023';
  END IF;
  IF p_id IS NULL AND v_name IS NULL THEN
    RAISE EXCEPTION 'A name is required' USING ERRCODE = '22023';
  END IF;

  IF p_kind = 'cost_center' THEN
    IF p_id IS NULL THEN
      INSERT INTO public.expense_cost_centers (code, name, name_ar, is_active, created_by)
      VALUES (v_code, v_name, nullif(btrim(coalesce(p_name_ar, '')), ''),
              COALESCE(p_is_active, true), v_user)
      RETURNING to_jsonb(expense_cost_centers.*) INTO v_row;
    ELSE
      UPDATE public.expense_cost_centers
         SET code      = CASE WHEN p_code IS NULL THEN code ELSE v_code END,
             name      = COALESCE(v_name, name),
             name_ar   = CASE WHEN p_name_ar IS NULL THEN name_ar
                              ELSE nullif(btrim(p_name_ar), '') END,
             is_active = COALESCE(p_is_active, is_active)
       WHERE id = p_id
      RETURNING to_jsonb(expense_cost_centers.*) INTO v_row;

      IF v_row IS NULL THEN
        RAISE EXCEPTION 'Cost centre not found' USING ERRCODE = 'P0002';
      END IF;
    END IF;
  ELSE
    IF p_id IS NULL THEN
      INSERT INTO public.expense_projects (code, name, name_ar, is_active, created_by)
      VALUES (v_code, v_name, nullif(btrim(coalesce(p_name_ar, '')), ''),
              COALESCE(p_is_active, true), v_user)
      RETURNING to_jsonb(expense_projects.*) INTO v_row;
    ELSE
      UPDATE public.expense_projects
         SET code      = CASE WHEN p_code IS NULL THEN code ELSE v_code END,
             name      = COALESCE(v_name, name),
             name_ar   = CASE WHEN p_name_ar IS NULL THEN name_ar
                              ELSE nullif(btrim(p_name_ar), '') END,
             is_active = COALESCE(p_is_active, is_active)
       WHERE id = p_id
      RETURNING to_jsonb(expense_projects.*) INTO v_row;

      IF v_row IS NULL THEN
        RAISE EXCEPTION 'Project not found' USING ERRCODE = 'P0002';
      END IF;
    END IF;
  END IF;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'expense.' || p_kind || '.' || CASE WHEN p_id IS NULL THEN 'created' ELSE 'updated' END,
          'expense_' || p_kind, (v_row ->> 'id')::uuid, v_row);

  RETURN v_row;
END $$;


--
-- Name: save_item_policy(uuid, public.item_nature, public.inventory_policy, public.costing_method, public.item_tracking, boolean, boolean, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_item_policy(_item_id uuid, _item_nature public.item_nature, _inventory_policy public.inventory_policy, _costing_method public.costing_method, _tracking public.item_tracking, _is_sellable boolean, _is_purchasable boolean, _base_uom_id uuid DEFAULT NULL::uuid, _sales_uom_id uuid DEFAULT NULL::uuid, _purchase_uom_id uuid DEFAULT NULL::uuid, _uom_conversions jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user    uuid := auth.uid();
  v_product public.products%ROWTYPE;
  v_before  jsonb;
  v_after   jsonb;
  v_policy_changed boolean;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (
    public.has_role(v_user, 'owner')
    OR public.has_role(v_user, 'manager')
    OR public.has_role(v_user, 'warehouse')
  ) THEN
    RAISE EXCEPTION 'You are not permitted to edit item policy';
  END IF;

  SELECT * INTO v_product FROM public.products WHERE id = _item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item % does not exist', _item_id;
  END IF;

  IF _item_nature = 'SERVICE' AND _inventory_policy <> 'UNTRACKED' THEN
    RAISE EXCEPTION 'A SERVICE can only be UNTRACKED';
  END IF;
  IF _inventory_policy = 'TRACKED' AND _costing_method = 'NONE' THEN
    RAISE EXCEPTION 'A TRACKED item requires a costing method other than NONE';
  END IF;
  IF _inventory_policy = 'UNTRACKED' AND _tracking <> 'NONE' THEN
    RAISE EXCEPTION 'An UNTRACKED item cannot require batch or serial tracking';
  END IF;
  IF NOT _is_sellable AND NOT _is_purchasable THEN
    RAISE EXCEPTION 'An item must be usable for selling, purchasing, or both';
  END IF;

  IF _uom_conversions IS NOT NULL AND jsonb_typeof(_uom_conversions) <> 'array' THEN
    RAISE EXCEPTION 'UOM conversions must be a JSON array';
  END IF;

  v_policy_changed :=
    _item_nature      IS DISTINCT FROM v_product.item_nature
    OR _inventory_policy IS DISTINCT FROM v_product.inventory_policy
    OR _costing_method   IS DISTINCT FROM v_product.costing_method
    OR _tracking         IS DISTINCT FROM v_product.tracking;

  -- When only the commercial flags or units change, no policy transition is
  -- happening and the plain path is enough.
  IF NOT v_policy_changed THEN
    UPDATE public.products
    SET is_sellable      = _is_sellable,
        is_purchasable   = _is_purchasable,
        base_uom_id      = _base_uom_id,
        sales_uom_id     = _sales_uom_id,
        purchase_uom_id  = _purchase_uom_id,
        uom_conversions  = coalesce(_uom_conversions, uom_conversions),
        updated_at       = now()
    WHERE id = _item_id;

    RETURN _item_id;
  END IF;

  -- A policy change is a governed transition. If the item has no history yet,
  -- the trigger allows the direct write; if it has history, the owner/manager
  -- rule applies and the change is audited.
  IF public.item_has_stock_history(_item_id) THEN
    IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN
      RAISE EXCEPTION
        'Item % has inventory history; only an owner or manager may change its policy',
        _item_id;
    END IF;

    v_before := jsonb_build_object(
      'item_nature', v_product.item_nature,
      'inventory_policy', v_product.inventory_policy,
      'costing_method', v_product.costing_method,
      'tracking', v_product.tracking
    );

    PERFORM set_config('app.allow_policy_change', 'on', true);
  END IF;

  UPDATE public.products
  SET item_nature      = _item_nature,
      inventory_policy = _inventory_policy,
      costing_method   = _costing_method,
      tracking         = _tracking,
      is_sellable      = _is_sellable,
      is_purchasable   = _is_purchasable,
      base_uom_id      = _base_uom_id,
      sales_uom_id     = _sales_uom_id,
      purchase_uom_id  = _purchase_uom_id,
      uom_conversions  = coalesce(_uom_conversions, uom_conversions),
      updated_at       = now()
  WHERE id = _item_id;

  IF v_before IS NOT NULL THEN
    v_after := jsonb_build_object(
      'item_nature', _item_nature,
      'inventory_policy', _inventory_policy,
      'costing_method', _costing_method,
      'tracking', _tracking
    );

    PERFORM public.audit_item_policy_snapshot(
      _item_id,
      'item_policy.changed',
      v_before,
      v_after,
      'item_editor'
    );
  END IF;

  RETURN _item_id;
END $$;


--
-- Name: save_product_batch(uuid, uuid, text, date, numeric, numeric, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_product_batch(p_product_id uuid, p_warehouse_id uuid, p_batch_number text, p_expiry_date date DEFAULT NULL::date, p_quantity numeric DEFAULT 0, p_unit_cost numeric DEFAULT 0, p_note text DEFAULT NULL::text, p_sync_inventory boolean DEFAULT true, p_batch_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_id   uuid;
  v_old_qty numeric := 0;
  v_delta numeric := 0;
  v_product_tracked boolean;
  v_cost numeric := coalesce(p_unit_cost, 0);
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_product_id IS NULL THEN
    RAISE EXCEPTION 'Product is required for batch';
  END IF;
  IF p_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'Warehouse is required for batch';
  END IF;
  IF p_batch_number IS NULL OR btrim(p_batch_number) = '' THEN
    RAISE EXCEPTION 'Batch number is required';
  END IF;
  IF p_quantity < 0 THEN
    RAISE EXCEPTION 'Batch quantity cannot be negative';
  END IF;
  IF v_cost < 0 THEN
    RAISE EXCEPTION 'Batch unit cost cannot be negative';
  END IF;

  SELECT (inventory_policy = 'TRACKED') INTO v_product_tracked
  FROM public.products WHERE id = p_product_id;

  IF p_batch_id IS NOT NULL THEN
    -- Editing existing batch
    SELECT id, quantity INTO v_id, v_old_qty
    FROM public.product_batches
    WHERE id = p_batch_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Batch % not found', p_batch_id;
    END IF;

    UPDATE public.product_batches
    SET product_id = p_product_id,
        warehouse_id = p_warehouse_id,
        batch_number = btrim(p_batch_number),
        expiry_date = p_expiry_date,
        quantity = p_quantity,
        unit_cost = v_cost,
        note = nullif(btrim(p_note), ''),
        updated_at = now()
    WHERE id = v_id;

    v_delta := p_quantity - v_old_qty;
  ELSE
    -- Creating new batch
    SELECT id, quantity INTO v_id, v_old_qty
    FROM public.product_batches
    WHERE product_id = p_product_id
      AND warehouse_id = p_warehouse_id
      AND batch_number = btrim(p_batch_number)
    FOR UPDATE;

    IF FOUND THEN
      -- Existing batch number for same product and warehouse
      UPDATE public.product_batches
      SET quantity = round(quantity + p_quantity, 3),
          unit_cost = CASE WHEN v_cost > 0 THEN v_cost ELSE unit_cost END,
          expiry_date = coalesce(p_expiry_date, expiry_date),
          note = coalesce(nullif(btrim(p_note), ''), note),
          updated_at = now()
      WHERE id = v_id;

      v_delta := p_quantity;
    ELSE
      INSERT INTO public.product_batches (
        product_id, warehouse_id, batch_number, expiry_date, quantity, unit_cost, note, created_by
      )
      VALUES (
        p_product_id, p_warehouse_id, btrim(p_batch_number), p_expiry_date,
        p_quantity, v_cost, nullif(btrim(p_note), ''), v_user
      )
      RETURNING id INTO v_id;

      v_delta := p_quantity;
    END IF;
  END IF;

  -- Sync with inventory ledger if enabled
  IF p_sync_inventory AND v_delta <> 0 AND coalesce(v_product_tracked, true) THEN
    PERFORM public.post_stock_delta(
      p_product_id,
      p_warehouse_id,
      v_delta,
      v_cost,
      CASE WHEN v_delta > 0 THEN 'RECEIPT'::public.stock_movement_kind ELSE 'ADJUSTMENT'::public.stock_movement_kind END,
      'product_batch',
      v_id,
      CASE WHEN v_delta > 0 THEN 'توريد دفعة: ' || btrim(p_batch_number) ELSE 'تعديل دفعة: ' || btrim(p_batch_number) END,
      'COMPANY'::public.owner_type,
      NULL,
      CASE WHEN v_delta > 0 THEN 'purchase'::public.movement_type ELSE 'adjustment'::public.movement_type END
    );
  END IF;

  RETURN v_id;
END $$;


--
-- Name: search_products(text, uuid, uuid, uuid, uuid, boolean, boolean, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_products(p_query text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_brand_id uuid DEFAULT NULL::uuid, p_unit_id uuid DEFAULT NULL::uuid, p_origin_id uuid DEFAULT NULL::uuid, p_active boolean DEFAULT NULL::boolean, p_low_stock boolean DEFAULT NULL::boolean, p_sort_key text DEFAULT 'created_at'::text, p_sort_dir text DEFAULT 'desc'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, name text, name_ar text, sku text, barcode text, sale_price numeric, cost_price numeric, tax_rate numeric, min_stock numeric, shelf_location text, origin_id uuid, quality_grade_id uuid, is_active boolean, category_id uuid, brand_id uuid, unit_id uuid, created_at timestamp with time zone, category_name text, category_name_ar text, brand_name text, brand_name_ar text, unit_short_name text, unit_name_ar text, stock_qty numeric, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH filtered AS (
    SELECT
      p.id, p.name, p.name_ar, p.sku, p.barcode,
      p.sale_price, p.cost_price, p.tax_rate, p.min_stock, p.shelf_location,
      p.origin_id, p.quality_grade_id, p.is_active,
      p.category_id, p.brand_id, p.unit_id, p.created_at,
      c.name    AS category_name,
      c.name_ar AS category_name_ar,
      b.name    AS brand_name,
      b.name_ar AS brand_name_ar,
      u.short_name AS unit_short_name,
      u.name_ar    AS unit_name_ar,
      COALESCE((
        SELECT sum(i.quantity) FROM public.inventory i WHERE i.product_id = p.id
      ), 0) AS stock_qty
    FROM public.products p
    LEFT JOIN public.categories c ON c.id = p.category_id
    LEFT JOIN public.brands     b ON b.id = p.brand_id
    LEFT JOIN public.units      u ON u.id = p.unit_id
    WHERE
      -- Fuzzy-ish text search: case-insensitive substring across the identity
      -- fields. Uses simple LIKE so it works on any Postgres without extensions.
      (
        p_query IS NULL
        OR btrim(p_query) = ''
        OR p.name        ILIKE '%' || btrim(p_query) || '%'
        OR p.name_ar     ILIKE '%' || btrim(p_query) || '%'
        OR p.sku         ILIKE '%' || btrim(p_query) || '%'
        OR p.barcode     ILIKE '%' || btrim(p_query) || '%'
        OR p.shelf_location ILIKE '%' || btrim(p_query) || '%'
      )
      AND (p_category_id IS NULL OR p.category_id = p_category_id)
      AND (p_brand_id    IS NULL OR p.brand_id    = p_brand_id)
      AND (p_unit_id     IS NULL OR p.unit_id     = p_unit_id)
      AND (p_origin_id   IS NULL OR p.origin_id   = p_origin_id)
      AND (p_active      IS NULL OR p.is_active   = p_active)
  ),
  counted AS (
    SELECT *, count(*) OVER () AS total_count FROM filtered
  )
  SELECT
    id, name, name_ar, sku, barcode,
    sale_price, cost_price, tax_rate, min_stock, shelf_location,
    origin_id, quality_grade_id, is_active,
    category_id, brand_id, unit_id, created_at,
    category_name, category_name_ar, brand_name, brand_name_ar,
    unit_short_name, unit_name_ar,
    stock_qty, total_count
  FROM counted
  WHERE
    p_low_stock IS NULL
    OR (p_low_stock = true  AND stock_qty <= min_stock)
    OR (p_low_stock = false AND stock_qty >  min_stock)
  ORDER BY
    CASE WHEN p_sort_key = 'name'       AND p_sort_dir = 'asc'  THEN COALESCE(name_ar, name) END ASC NULLS LAST,
    CASE WHEN p_sort_key = 'name'       AND p_sort_dir = 'desc' THEN COALESCE(name_ar, name) END DESC NULLS LAST,
    CASE WHEN p_sort_key = 'sku'        AND p_sort_dir = 'asc'  THEN sku END ASC NULLS LAST,
    CASE WHEN p_sort_key = 'sku'        AND p_sort_dir = 'desc' THEN sku END DESC NULLS LAST,
    CASE WHEN p_sort_key = 'sale_price' AND p_sort_dir = 'asc'  THEN sale_price END ASC NULLS LAST,
    CASE WHEN p_sort_key = 'sale_price' AND p_sort_dir = 'desc' THEN sale_price END DESC NULLS LAST,
    CASE WHEN p_sort_key = 'cost_price' AND p_sort_dir = 'asc'  THEN cost_price END ASC NULLS LAST,
    CASE WHEN p_sort_key = 'cost_price' AND p_sort_dir = 'desc' THEN cost_price END DESC NULLS LAST,
    CASE WHEN p_sort_key = 'stock'      AND p_sort_dir = 'asc'  THEN stock_qty END ASC NULLS LAST,
    CASE WHEN p_sort_key = 'stock'      AND p_sort_dir = 'desc' THEN stock_qty END DESC NULLS LAST,
    CASE WHEN p_sort_key = 'created_at' AND p_sort_dir = 'asc'  THEN created_at END ASC NULLS LAST,
    CASE WHEN p_sort_key = 'created_at' AND p_sort_dir = 'desc' THEN created_at END DESC NULLS LAST,
    created_at DESC
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 50), 200))
  OFFSET GREATEST(0, COALESCE(p_offset, 0));
$$;


--
-- Name: set_company_costing_method(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_company_costing_method(_method text, _source text, _notes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_old  public.costing_method;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN
    RAISE EXCEPTION 'Only an owner or manager can change the company costing method';
  END IF;
  -- ⚠️ _method قد تكون NULL (أو بأحرف صغيرة من الواجهة). التحقق القديم
  --    `_method NOT IN (...)` يقبل NULL بصمت لأن NULL NOT IN (...) = NULL،
  --    ثم يُدرج NULL في costing_policy_history.costing_method (NOT NULL)
  --    فيرمي 23502 بدل رسالة واضحة. الآن يُرفض null/farغ صراحةً ويُطبَّع الحرف.
  _method := upper(btrim(coalesce(_method, '')));
  IF _method IS NULL OR _method = '' THEN
    RAISE EXCEPTION 'Costing method is required (MOVING_AVERAGE or STANDARD)'
      USING ERRCODE = '22023';
  END IF;
  IF _method NOT IN ('MOVING_AVERAGE', 'STANDARD') THEN
    RAISE EXCEPTION 'Costing method must be MOVING_AVERAGE or STANDARD (got %)', _method
      USING ERRCODE = '22023';
  END IF;

  SELECT costing_method INTO v_old FROM public.company_costing_settings WHERE id = 1 FOR UPDATE;
  IF v_old = _method::public.costing_method THEN
    RETURN;  -- idempotent: re-selecting the same method is not a change
  END IF;

  UPDATE public.company_costing_settings
     SET costing_method = _method::public.costing_method,
         standard_cost_source = coalesce(_source, standard_cost_source),
         effective_from    = CURRENT_DATE,
         updated_by        = v_user,
         updated_at        = now(),
         notes             = nullif(btrim(coalesce(_notes, '')), '')
   WHERE id = 1;

  INSERT INTO public.costing_policy_history (costing_method, previous_method, reason, changed_by)
  VALUES (_method::public.costing_method, v_old, nullif(btrim(coalesce(_notes, '')), ''), v_user);
END $$;


--
-- Name: set_company_item_policy(uuid, public.inventory_policy, public.costing_method, numeric, numeric, numeric, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_company_item_policy(_item_id uuid, _inventory_policy public.inventory_policy DEFAULT NULL::public.inventory_policy, _costing_method public.costing_method DEFAULT NULL::public.costing_method, _default_cost numeric DEFAULT NULL::numeric, _default_sale_price numeric DEFAULT NULL::numeric, _tax_rate numeric DEFAULT NULL::numeric, _is_active boolean DEFAULT true, _company_id integer DEFAULT 1) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user    uuid := auth.uid();
  v_id      uuid;
  v_before  jsonb;
  v_after   jsonb;
  v_nature  public.item_nature;
  v_balance numeric;
  v_existing public.company_items%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN
    RAISE EXCEPTION 'Only an owner or manager may change a company item policy';
  END IF;

  SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = _item_id;
  IF v_nature IS NULL THEN
    RAISE EXCEPTION 'Item % does not exist', _item_id;
  END IF;

  IF v_nature = 'SERVICE' AND _inventory_policy IS NOT NULL AND _inventory_policy <> 'UNTRACKED' THEN
    RAISE EXCEPTION 'A SERVICE can only be UNTRACKED in any company';
  END IF;

  IF _default_cost IS NOT NULL AND _default_cost < 0 THEN
    RAISE EXCEPTION 'Default cost cannot be negative';
  END IF;
  IF _default_sale_price IS NOT NULL AND _default_sale_price < 0 THEN
    RAISE EXCEPTION 'Default sale price cannot be negative';
  END IF;
  IF _tax_rate IS NOT NULL AND (_tax_rate < 0 OR _tax_rate > 100) THEN
    RAISE EXCEPTION 'Tax rate must be between 0 and 100';
  END IF;

  SELECT * INTO v_existing
  FROM public.company_items
  WHERE company_id = _company_id AND item_id = _item_id
  FOR UPDATE;

  -- Refuse to strand stock by turning tracking off for a company that holds it.
  IF _inventory_policy IS NOT NULL AND _inventory_policy <> 'TRACKED' THEN
    SELECT coalesce(sum(i.quantity), 0) INTO v_balance
    FROM public.inventory i
    WHERE i.product_id = _item_id
      AND i.owner_type = 'COMPANY'
      AND i.owner_id IS NULL;

    IF v_balance <> 0
       AND coalesce(v_existing.inventory_policy, (SELECT p.inventory_policy FROM public.products p WHERE p.id = _item_id)) = 'TRACKED' THEN
      RAISE EXCEPTION
        'Company % still holds % units of item %. Clear the balance before leaving TRACKED.',
        _company_id, v_balance, _item_id;
    END IF;
  END IF;

  v_before := CASE WHEN v_existing.id IS NULL THEN NULL ELSE
    jsonb_build_object(
      'inventory_policy', v_existing.inventory_policy,
      'costing_method', v_existing.costing_method,
      'default_cost', v_existing.default_cost,
      'default_sale_price', v_existing.default_sale_price,
      'tax_rate', v_existing.tax_rate,
      'is_active', v_existing.is_active
    ) END;

  INSERT INTO public.company_items (
    company_id, item_id, inventory_policy, costing_method,
    default_cost, default_sale_price, tax_rate, is_active
  )
  VALUES (
    _company_id, _item_id, _inventory_policy, _costing_method,
    _default_cost, _default_sale_price, _tax_rate, coalesce(_is_active, true)
  )
  ON CONFLICT (company_id, item_id) DO UPDATE
  SET inventory_policy   = COALESCE(EXCLUDED.inventory_policy,   public.company_items.inventory_policy),
      costing_method     = COALESCE(EXCLUDED.costing_method,     public.company_items.costing_method),
      default_cost       = COALESCE(EXCLUDED.default_cost,       public.company_items.default_cost),
      default_sale_price = COALESCE(EXCLUDED.default_sale_price, public.company_items.default_sale_price),
      tax_rate           = COALESCE(EXCLUDED.tax_rate,           public.company_items.tax_rate),
      is_active          = EXCLUDED.is_active,
      updated_at         = now()
  RETURNING id INTO v_id;

  SELECT jsonb_build_object(
           'inventory_policy', ci.inventory_policy,
           'costing_method', ci.costing_method,
           'default_cost', ci.default_cost,
           'default_sale_price', ci.default_sale_price,
           'tax_rate', ci.tax_rate,
           'is_active', ci.is_active
         )
    INTO v_after
  FROM public.company_items ci WHERE ci.id = v_id;

  PERFORM public.audit_item_policy_snapshot(
    _item_id,
    'company_item_policy.changed',
    coalesce(v_before, '{}'::jsonb),
    v_after,
    'company:' || _company_id
  );

  RETURN v_id;
END $$;


--
-- Name: set_period_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_period_status(p_period_id uuid, p_status text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_period record;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (public.has_role(v_user, 'owner')
          OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may change fiscal period status';
  END IF;

  IF p_status NOT IN ('OPEN', 'CLOSED') THEN
    RAISE EXCEPTION 'Status must be OPEN or CLOSED';
  END IF;

  SELECT * INTO v_period FROM public.fiscal_periods WHERE id = p_period_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fiscal period not found';
  END IF;

  UPDATE public.fiscal_periods
     SET status = p_status,
         closed_at = CASE WHEN p_status = 'CLOSED' THEN now() ELSE NULL END,
         closed_by = CASE WHEN p_status = 'CLOSED' THEN v_user ELSE NULL END
   WHERE id = p_period_id;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'fiscal_period.status_changed', 'fiscal_period', p_period_id,
          jsonb_build_object('code', v_period.code, 'old_status', v_period.status, 'new_status', p_status));

  RETURN true;
END $$;


--
-- Name: FUNCTION set_period_status(p_period_id uuid, p_status text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_period_status(p_period_id uuid, p_status text) IS 'T-19: تغيير حالة الفترة المالية بين OPEN و CLOSED مع فحص الصلاحيات وتسجيل التدقيق.';


--
-- Name: set_standard_costs(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_standard_costs(_costs jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_n    integer := 0;
  e      jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')) THEN
    RAISE EXCEPTION 'Only an owner or manager may set standard costs';
  END IF;
  IF _costs IS NULL OR jsonb_array_length(_costs) = 0 THEN
    RAISE EXCEPTION 'No standards supplied';
  END IF;

  FOR e IN SELECT * FROM jsonb_array_elements(_costs)
  LOOP
    IF coalesce((e->>'standard_cost')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION 'Standard cost must be greater than zero for product %', e->>'product_id';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.products p
                    WHERE p.id = (e->>'product_id')::uuid
                      AND p.item_nature = 'GOOD' AND p.inventory_policy = 'TRACKED') THEN
      RAISE EXCEPTION 'Product % is not a tracked good', e->>'product_id';
    END IF;

    UPDATE public.products
       SET standard_cost = (e->>'standard_cost')::numeric
     WHERE id = (e->>'product_id')::uuid;

    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
    VALUES (v_user, 'product.standard_cost_set', 'product', (e->>'product_id')::uuid,
            jsonb_build_object('standard_cost', (e->>'standard_cost')::numeric,
                               'implied', (e->>'implied_standard')::numeric,
                               'note', nullif(btrim(coalesce(e->>'note','')), '')));
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END $$;


--
-- Name: settle_tax_period(date, date, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_tax_period(p_start_date date, p_end_date date, p_period_number text, p_settlement_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user          uuid := auth.uid();
  v_decl          jsonb;
  v_output_tax    numeric(18,2);
  v_input_tax     numeric(18,2);
  v_net_tax       numeric(18,2);
  v_sales         numeric(18,2);
  v_purch         numeric(18,2);
  v_lines         jsonb := '[]'::jsonb;
  v_entry_id      uuid;
  v_settle_id     uuid;
  v_memo          text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- نطاق وسياق إلزاميان: بدونهما كان يُنشأ قيد تسوية بقيمة صفر (أثر كاذب).
  IF p_start_date IS NULL OR p_end_date IS NULL
     OR nullif(btrim(coalesce(p_period_number, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Tax settlement requires start_date, end_date and period_number'
      USING ERRCODE = '22023';
  END IF;
  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'Tax settlement end_date (%) is before start_date (%)', p_end_date, p_start_date
      USING ERRCODE = '22023';
  END IF;

  IF NOT (public.has_role(v_user, 'owner')
          OR public.has_role(v_user, 'manager')
          OR public.has_role(v_user, 'accountant')) THEN
    RAISE EXCEPTION 'Only an owner, manager or accountant may settle taxes'
      USING ERRCODE = '42501';
  END IF;

  PERFORM public.assert_period_open(p_settlement_date);

  IF EXISTS (
    SELECT 1 FROM public.tax_settlement_periods
     WHERE period_number = p_period_number
  ) THEN
    RAISE EXCEPTION 'Tax period % already exists or settled', p_period_number;
  END IF;

  -- قراءة أرقام الإقرار (النسخة السليمة)
  v_decl := public.generate_tax_declaration(p_start_date, p_end_date);
  v_sales      := (v_decl->>'taxable_sales')::numeric;
  v_output_tax := (v_decl->>'output_tax')::numeric;
  v_purch      := (v_decl->>'taxable_purchases')::numeric;
  v_input_tax  := (v_decl->>'input_tax')::numeric;
  v_net_tax    := (v_decl->>'net_tax_payable')::numeric;

  IF coalesce(v_output_tax, 0) = 0 AND coalesce(v_input_tax, 0) = 0 THEN
    RAISE EXCEPTION 'لا توجد حركات ضريبية مرحّلة للفترة المحددة لتسويتها'
      USING ERRCODE = '22023';
  END IF;

  -- بناء قيد التسوية المتوازن:
  IF v_output_tax > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', '2311', 'debit', v_output_tax, 'credit', 0,
        'memo', 'تسوية ضريبة المخرجات للفترة ' || p_period_number
      )
    );
  END IF;

  IF v_input_tax > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', '1316', 'debit', 0, 'credit', v_input_tax,
        'memo', 'تسوية ضريبة المدخلات للفترة ' || p_period_number
      )
    );
  END IF;

  IF v_net_tax > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', '2321', 'debit', 0, 'credit', v_net_tax,
        'memo', 'صافي ضريبة القيمة المضافة المستحقة للدفع — ' || p_period_number
      )
    );
  ELSIF v_net_tax < 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'account_code', '2321', 'debit', -v_net_tax, 'credit', 0,
        'memo', 'رصيد ضريبة مدخلات فائض مسترد/مرحل — ' || p_period_number
      )
    );
  END IF;

  v_memo := 'قيد التسوية والإقرار الضريبي للفترة ' || p_period_number ||
            ' (' || to_char(p_start_date, 'YYYY-MM-DD') || ' إلى ' || to_char(p_end_date, 'YYYY-MM-DD') || ')';

  v_entry_id := public.create_journal_entry(
    v_memo, p_settlement_date, 'tax_settlement', NULL, true, v_lines, false
  );

  INSERT INTO public.tax_settlement_periods (
    period_number, start_date, end_date, total_taxable_sales,
    output_tax_amount, total_taxable_purchases, input_tax_amount,
    net_tax_payable, status, journal_entry_id, settled_at, settled_by
  )
  VALUES (
    btrim(p_period_number), p_start_date, p_end_date, v_sales,
    v_output_tax, v_purch, v_input_tax,
    v_net_tax, 'SETTLED', v_entry_id, now(), v_user
  )
  RETURNING id INTO v_settle_id;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'tax.settled', 'tax_settlement', v_settle_id,
          jsonb_build_object('period_number', p_period_number, 'net_tax', v_net_tax, 'entry_id', v_entry_id));

  RETURN v_settle_id;
END $$;


--
-- Name: FUNCTION settle_tax_period(p_start_date date, p_end_date date, p_period_number text, p_settlement_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.settle_tax_period(p_start_date date, p_end_date date, p_period_number text, p_settlement_date date) IS 'T-23: قيد تسوية 2311/1316 والفرق إلى 2321. يرفض النطاق الفارغ والتسوية الصفرية.';


--
-- Name: smart_manufacture(uuid, uuid, numeric, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.smart_manufacture(_warehouse_id uuid, _grain_item_id uuid, _grain_qty numeric, _outputs jsonb, _notes text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_ref text;
  v_doc_id uuid := gen_random_uuid();
  v_output_value numeric := 0;
  v_grain_cost numeric;
  v_total_input_cost numeric;
  v_total_output_qty numeric := 0;
  v_waste_qty numeric := 0;
  v_waste_cost numeric := 0;
  v_allocatable_cost numeric := 0;
  v_total_allocated numeric := 0;
  v_line_allocated numeric;
  v_line_idx int := 0;
  v_outputs_count int;
  r record;
  v_last_out numeric;
  v_journal_lines jsonb := '[]'::jsonb;
  v_acct_code text;
  v_item_name text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.can_operate_milling() THEN
    RAISE EXCEPTION 'You are not permitted to run smart manufacture';
  END IF;
  IF _warehouse_id IS NULL OR _grain_item_id IS NULL THEN
    RAISE EXCEPTION 'Warehouse and grain item are required';
  END IF;
  IF coalesce(_grain_qty, 0) <= 0 THEN
    RAISE EXCEPTION 'Grain quantity must be positive';
  END IF;
  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN
    RAISE EXCEPTION 'At least one output line is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.products
    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active
  ) THEN
    RAISE EXCEPTION 'Input must be an active RAW_MATERIAL grain';
  END IF;

  v_outputs_count := jsonb_array_length(_outputs);

  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)
  LOOP
    IF r.item_id IS NULL OR coalesce(r.qty, 0) <= 0 THEN
      RAISE EXCEPTION 'Every output line needs an item and a positive quantity';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.products
      WHERE id = r.item_id AND item_class IN ('FINISHED_GOOD', 'BY_PRODUCT') AND is_active
    ) THEN
      RAISE EXCEPTION 'Outputs must be FINISHED_GOOD or BY_PRODUCT items';
    END IF;

    SELECT coalesce(r.qty, 0) * coalesce(sale_price, 0) INTO v_last_out
    FROM public.products WHERE id = r.item_id;

    v_output_value := v_output_value + coalesce(v_last_out, 0);
    v_total_output_qty := v_total_output_qty + coalesce(r.qty, 0);
  END LOOP;

  IF v_output_value <= 0 THEN
    RAISE EXCEPTION 'Outputs must have sale prices to allocate cost by relative value';
  END IF;

  IF v_total_output_qty > _grain_qty THEN
    RAISE EXCEPTION 'Total output weight (%) cannot exceed input grain weight (%)',
      v_total_output_qty, _grain_qty;
  END IF;

  -- تكلفة القمح من طبقات التكلفة الفعلية أو كتالوج التكلفة
  SELECT coalesce(
    (SELECT sum(cl.quantity * cl.last_unit_cost) / nullif(sum(cl.quantity), 0)
       FROM public.item_cost_layers cl
      WHERE cl.product_id = _grain_item_id AND cl.quantity > 0
        AND cl.owner_type = 'COMPANY'),
    (SELECT cost_price FROM public.products WHERE id = _grain_item_id),
    0
  ) INTO v_grain_cost;

  v_total_input_cost := round(coalesce(_grain_qty, 0) * coalesce(v_grain_cost, 0), 2);
  v_ref := 'SM-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');

  v_waste_qty := greatest(0, coalesce(_grain_qty, 0) - v_total_output_qty);
  IF v_waste_qty > 0 AND v_grain_cost > 0 THEN
    v_waste_cost := round(v_waste_qty * v_grain_cost, 2);
  ELSE
    v_waste_cost := 0;
  END IF;

  v_allocatable_cost := greatest(0, v_total_input_cost - v_waste_cost);

  -- 1) صادر القمح (ينقص المخزون ويقيَّم بنفس المعاملة)
  PERFORM public.post_stock_delta(
    p_product_id => _grain_item_id,
    p_warehouse_id => _warehouse_id,
    p_signed_qty => -coalesce(_grain_qty, 0),
    p_unit_cost => v_grain_cost,
    p_movement_kind => 'PRODUCTION'::public.stock_movement_kind,
    p_source_type => 'smart_manufacture',
    p_source_id => v_doc_id,
    p_note => 'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),
    p_owner_type => 'COMPANY'::public.owner_type,
    p_owner_id => NULL,
    p_movement_type_legacy => 'production_out'::public.movement_type);

  -- 2) وارد النواتج بتكلفة موزعة وبناء أطراف القيد المدين للنواتج
  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)
  LOOP
    DECLARE
      v_line_value numeric;
      v_unit_cost numeric;
      v_item_class text;
    BEGIN
      v_line_idx := v_line_idx + 1;
      SELECT coalesce(r.qty, 0) * coalesce(sale_price, 0), item_class, coalesce(name_ar, name)
        INTO v_line_value, v_item_class, v_item_name
      FROM public.products WHERE id = r.item_id;

      IF v_line_idx = v_outputs_count THEN
        v_line_allocated := v_allocatable_cost - v_total_allocated;
      ELSE
        v_line_allocated := round(v_allocatable_cost * (coalesce(v_line_value, 0) / v_output_value), 2);
        v_total_allocated := v_total_allocated + v_line_allocated;
      END IF;

      v_unit_cost := round(v_line_allocated / nullif(coalesce(r.qty, 0), 0), 4);

      PERFORM public.post_stock_delta(
        p_product_id => r.item_id,
        p_warehouse_id => _warehouse_id,
        p_signed_qty => coalesce(r.qty, 0),
        p_unit_cost => v_unit_cost,
        p_movement_kind => 'PRODUCTION'::public.stock_movement_kind,
        p_source_type => 'smart_manufacture',
        p_source_id => v_doc_id,
        p_note => 'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),
        p_owner_type => 'COMPANY'::public.owner_type,
        p_owner_id => NULL,
        p_movement_type_legacy => 'production_in'::public.movement_type);

      IF v_item_class = 'BY_PRODUCT' THEN
        v_acct_code := '1314';
      ELSE
        v_acct_code := '1313';
      END IF;

      IF v_line_allocated > 0 THEN
        v_journal_lines := v_journal_lines || jsonb_build_object(
          'account_code', v_acct_code,
          'debit', v_line_allocated,
          'credit', 0,
          'memo', 'إنتاج مخزون ' || v_item_name || ' (' || v_ref || ')'
        );
      END IF;
    END;
  END LOOP;

  IF v_waste_cost > 0 THEN
    v_journal_lines := v_journal_lines || jsonb_build_object(
      'account_code', '5921',
      'debit', v_waste_cost,
      'credit', 0,
      'memo', 'فاقد وتلف تشغيلي مطحنة (' || v_ref || ')'
    );
  END IF;

  IF v_total_input_cost > 0 THEN
    v_journal_lines := v_journal_lines || jsonb_build_object(
      'account_code', '1311',
      'debit', 0,
      'credit', v_total_input_cost,
      'memo', 'سحب قمح خام للتصنيع (' || v_ref || ')'
    );

    PERFORM public.create_journal_entry(
      p_memo => 'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),
      p_entry_date => CURRENT_DATE,
      p_source_type => 'smart_manufacture',
      p_source_id => v_doc_id,   -- P0-2: معرّف الدفعة لا معرّف صنف القمح
      p_is_system => true,
      p_lines => v_journal_lines
    );
  END IF;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)
  VALUES (v_user, 'manufacture.smart', 'stock_movements', v_doc_id,
    jsonb_build_object(
      'doc_id', v_doc_id,
      'ref', v_ref,
      'warehouse_id', _warehouse_id,
      'grain_item_id', _grain_item_id,
      'grain_qty', coalesce(_grain_qty, 0),
      'grain_unit_cost', v_grain_cost,
      'waste_qty', v_waste_qty,
      'waste_cost', v_waste_cost,
      'total_cost', v_total_input_cost,
      'outputs', _outputs,
      'allocation', 'RELATIVE_SALES_VALUE'
    ));

  RETURN v_ref;
END $$;


--
-- Name: submit_expense(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_expense(p_entry_id uuid, p_expected_version integer DEFAULT NULL::integer) RETURNS public.expense_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user  uuid := public.expense_actor();
  v_entry public.expense_entries;
  v_from  public.expense_status;
BEGIN
  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';
  END IF;

  v_from := v_entry.status;
  IF v_from NOT IN ('DRAFT', 'REJECTED') THEN
    RAISE EXCEPTION 'Only a draft or a returned expense can be submitted (current: %)', v_from
      USING ERRCODE = '55000';
  END IF;

  IF NOT (v_entry.created_by = v_user OR public.expense_role_rank(v_user) >= 30) THEN
    RAISE EXCEPTION 'Forbidden: you can only submit your own drafts' USING ERRCODE = '42501';
  END IF;
  PERFORM public.expense_assert_capability(v_user, 'expense.submit');

  IF p_expected_version IS NOT NULL AND p_expected_version <> v_entry.version THEN
    RAISE EXCEPTION 'This expense was changed by someone else. Reload it and try again.'
      USING ERRCODE = '40001';
  END IF;

  -- Completeness, in the order an operator would fix it.
  IF v_entry.total_amount <= 0 OR v_entry.line_count = 0 THEN
    RAISE EXCEPTION 'Add at least one line with an amount before submitting'
      USING ERRCODE = '22023';
  END IF;
  IF v_entry.payee_type = 'SUPPLIER' AND v_entry.supplier_id IS NULL THEN
    RAISE EXCEPTION 'Choose the supplier before submitting' USING ERRCODE = '22023';
  END IF;
  IF v_entry.payee_type = 'EMPLOYEE' AND v_entry.employee_id IS NULL THEN
    RAISE EXCEPTION 'Choose the staff member before submitting' USING ERRCODE = '22023';
  END IF;

  UPDATE public.expense_entries
     SET status             = 'SUBMITTED',
         submitted_by       = v_user,
         submitted_at       = now(),
         rejection_reason   = NULL,
         version            = version + 1
   WHERE id = p_entry_id
  RETURNING * INTO v_entry;

  PERFORM public.expense_log_action(p_entry_id, 'submitted', v_from, 'SUBMITTED', NULL, v_user);

  RETURN v_entry;
END $$;


--
-- Name: sync_apply_operation(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_apply_operation(p_idempotency_key text, p_entity_name text, p_operation_type text, p_origin_device_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing RECORD;
  v_result JSONB;
BEGIN
  -- ⚠️ المدخلات إلزامية: بلا هذا الفحص كان NULL يمر إلى idempotency_key
  --    (NOT NULL) فيظهر الخطأ كـ «null value in column ... violates not-null
  --    constraint» ملفوفًا برسالة غير مفهومة بدل رفض واضح للمدخل.
  IF nullif(btrim(coalesce(p_idempotency_key, '')), '') IS NULL
     OR nullif(btrim(coalesce(p_entity_name, '')), '') IS NULL
     OR nullif(btrim(coalesce(p_operation_type, '')), '') IS NULL
     OR nullif(btrim(coalesce(p_origin_device_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Sync operation requires idempotency_key, entity_name, operation_type and origin_device_id'
      USING ERRCODE = '22023';
  END IF;

  -- 1. Check if idempotency key exists
  SELECT * INTO v_existing
  FROM public.sync_idempotency_keys
  WHERE idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.status = 'completed' THEN
      RETURN jsonb_build_object(
        'status', 'DUPLICATE_ACK',
        'idempotency_key', p_idempotency_key,
        'message', 'Operation already processed previously',
        'result', v_existing.response_payload
      );
    ELSIF v_existing.status = 'processing' THEN
      -- In-flight request concurrent lock
      RETURN jsonb_build_object(
        'status', 'IN_FLIGHT',
        'idempotency_key', p_idempotency_key,
        'message', 'Operation is currently being processed by server'
      );
    END IF;
  END IF;

  -- 2. Insert processing lock
  INSERT INTO public.sync_idempotency_keys (
    idempotency_key,
    entity_name,
    operation_type,
    origin_device_id,
    status
  ) VALUES (
    p_idempotency_key,
    p_entity_name,
    p_operation_type,
    p_origin_device_id,
    'processing'
  );

  -- 3. Return success acknowledgment payload template
  v_result := jsonb_build_object(
    'acknowledged', true,
    'entity_name', p_entity_name,
    'operation_type', p_operation_type,
    'processed_at', now()
  );

  -- Mark completed
  UPDATE public.sync_idempotency_keys
  SET status = 'completed',
      response_payload = v_result,
      updated_at = now()
  WHERE idempotency_key = p_idempotency_key;

  RETURN jsonb_build_object(
    'status', 'PROCESSED',
    'idempotency_key', p_idempotency_key,
    'result', v_result
  );

EXCEPTION WHEN OTHERS THEN
  UPDATE public.sync_idempotency_keys
  SET status = 'failed',
      error_message = SQLERRM,
      updated_at = now()
  WHERE idempotency_key = p_idempotency_key;

  RAISE EXCEPTION 'Sync Apply Operation Failed: %', SQLERRM;
END;
$$;


--
-- Name: sync_item_class_from_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_item_class_from_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT'
     OR NEW.item_nature IS DISTINCT FROM OLD.item_nature
     OR NEW.inventory_policy IS DISTINCT FROM OLD.inventory_policy THEN

    -- الطبيعة تحكم أولاً: الخدمة خدمة.
    IF NEW.item_nature = 'SERVICE' THEN
      NEW.item_class := 'SERVICE';

    ELSIF NEW.item_nature = 'GOOD' THEN
      -- الأصناف التي تصنيفها *خاصية جوهرية* لا تُدهَس بالمنتج النهائي:
      -- خام قابل للاستهلاك، ناتج جانبي، وتعبئة تُشترى وتُستهلك.
      IF NEW.item_class IS NULL
         OR NEW.item_class NOT IN ('RAW_MATERIAL', 'BY_PRODUCT', 'PACKAGING') THEN
        NEW.item_class := 'FINISHED_GOOD';
      END IF;
    END IF;

    -- السياسة تحدّ الحالة التي لا تُمسك رصيداً.
    IF NEW.inventory_policy = 'CUSTOMER_OWNED' THEN
      -- أمانات العميل ليست مخزوناً تجارياً؛ تبقى ماديّةً في تصنيفها الأصلي.
      IF NEW.item_class IS NULL THEN
        NEW.item_class := 'NON_STOCK_ITEM';
      END IF;
    ELSIF NEW.inventory_policy = 'UNTRACKED' AND NEW.item_nature = 'GOOD' THEN
      -- صنف مادي غير متتبَّع: لا رصيد له مهما كان نوعه.
      NEW.item_class := 'NON_STOCK_ITEM';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: tg_customer_ledger_system_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_customer_ledger_system_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF coalesce(NEW.debit, 0) - coalesce(NEW.credit, 0) <> 0 AND public.is_system_customer(NEW.customer_id) THEN
    RAISE EXCEPTION
      'The system cash customer can only carry settlement lines, never a credit balance'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: tg_customers_system_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_customers_system_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_system THEN
      RAISE EXCEPTION
        'The system cash customer is a protected system entity and cannot be deleted'
        USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.is_system THEN
    IF NEW.is_system IS DISTINCT FROM true OR NEW.system_key IS DISTINCT FROM OLD.system_key THEN
      RAISE EXCEPTION
        'The system cash customer flag cannot be cleared or re-keyed'
        USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.name IS DISTINCT FROM OLD.name THEN
      RAISE EXCEPTION
        'The system cash customer cannot be renamed'
        USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.is_active IS DISTINCT FROM true THEN
      RAISE EXCEPTION
        'The system cash customer cannot be deactivated'
        USING ERRCODE = 'restrict_violation';
    END IF;
    IF coalesce(NEW.balance, 0) <> 0 THEN
      RAISE EXCEPTION
        'The system cash customer must keep a zero balance (got %)', NEW.balance
        USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NEW.is_system THEN
      RAISE EXCEPTION
        'System entities are provisioned by the seed, not created through the API'
        USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.name IN ('عميل نقدي') THEN
      RAISE EXCEPTION
        'That name is reserved for the system cash customer'
        USING ERRCODE = 'unique_violation';
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: tg_expense_entries_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_expense_entries_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only guard documents that have actually been recognized. A draft is meant
  -- to be edited; a posted document is evidence.
  IF OLD.status NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED', 'REVERSED')
     AND NEW.status NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED', 'REVERSED') THEN
    RETURN NEW;
  END IF;

  -- The exception is the reversal flow, which legitimately links a posted row
  -- to its compensating document; everything else about it stays frozen.
  IF NEW.total_amount  IS DISTINCT FROM OLD.total_amount
     OR NEW.expense_date IS DISTINCT FROM OLD.expense_date
     OR NEW.entry_type   IS DISTINCT FROM OLD.entry_type
     OR NEW.supplier_id  IS DISTINCT FROM OLD.supplier_id
     OR NEW.employee_id  IS DISTINCT FROM OLD.employee_id
     OR NEW.payee_type   IS DISTINCT FROM OLD.payee_type
     OR NEW.currency     IS DISTINCT FROM OLD.currency THEN
    RAISE EXCEPTION
      'Expense % is posted: its financial fields are immutable. Reverse it instead.',
      OLD.reference
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: tg_expense_lines_sync_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_expense_lines_sync_total() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entry_id uuid := COALESCE(NEW.entry_id, OLD.entry_id);
  v_status   public.expense_status;
  v_total    numeric(18,2);
  v_lines    integer;
BEGIN
  SELECT status INTO v_status FROM public.expense_entries WHERE id = v_entry_id;

  -- A posted document's lines are frozen evidence; leave its header alone.
  IF v_status IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED', 'REVERSED') THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(sum(gross_amount), 0)::numeric(18,2), count(*)
    INTO v_total, v_lines
  FROM public.expense_lines
  WHERE entry_id = v_entry_id;

  UPDATE public.expense_entries
     SET total_amount = v_total,
         line_count   = v_lines
   WHERE id = v_entry_id
     AND status NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED', 'REVERSED');

  RETURN NULL;
END $$;


--
-- Name: tg_expense_payments_sync_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_expense_payments_sync_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entry_id uuid := COALESCE(NEW.entry_id, OLD.entry_id);
  v_paid     numeric(18,2);
  v_entry    public.expense_entries;
BEGIN
  SELECT COALESCE(sum(amount), 0)::numeric(18,2)
    INTO v_paid
  FROM public.expense_payments
  -- A reversed payment keeps its row but stops counting toward settlement; the
  -- reversal row itself is subtracted because it carries a positive amount and
  -- a `reversal_of` link, which is expressed on the matching row's `reversed_by`.
  WHERE entry_id = v_entry_id
    AND reversed_by IS NULL
    AND reversal_of IS NULL;

  SELECT * INTO v_entry FROM public.expense_entries WHERE id = v_entry_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  UPDATE public.expense_entries
     SET paid_amount = v_paid,
         status = public.expense_settlement_status(
           CASE WHEN v_entry.status IN ('CLOSED', 'REVERSED') THEN v_entry.status
                ELSE 'POSTED'::public.expense_status END,
           v_paid,
           v_entry.total_amount
         )
   WHERE id = v_entry_id;

  RETURN NULL;
END $$;


--
-- Name: tg_guard_item_policy_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_guard_item_policy_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_allow text := current_setting('app.allow_policy_change', true);
BEGIN
  IF v_allow = 'on' THEN
    RETURN NEW;
  END IF;

  -- Nature and policy changes are both restricted once history exists.
  IF NEW.inventory_policy IS DISTINCT FROM OLD.inventory_policy
     OR NEW.item_nature IS DISTINCT FROM OLD.item_nature
     OR NEW.costing_method IS DISTINCT FROM OLD.costing_method
  THEN
    IF public.item_has_stock_history(OLD.id) THEN
      RAISE EXCEPTION
        'Item % has inventory history; policy changes must go through approve_item_policy_change()',
        OLD.id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Rule 2 enforced again at the transition point: an item with history can
  -- never become a SERVICE, because that would retroactively re-label real
  -- stock movements as a non-stock service.
  IF NEW.item_nature = 'SERVICE' AND OLD.item_nature <> 'SERVICE' THEN
    IF public.item_has_stock_history(OLD.id) THEN
      RAISE EXCEPTION
        'Item % has inventory history and cannot be converted to SERVICE', OLD.id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: tg_journal_entries_no_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_journal_entries_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION
    'Deleting a journal entry is forbidden. Reverse it via reverse_journal_entry instead (entry %).',
    OLD.entry_number
    USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: FUNCTION tg_journal_entries_no_delete(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_journal_entries_no_delete() IS 'T-03: يمنع حذف أي قيد — التصحيح يكون بالعكس فقط.';


--
-- Name: tg_platform_admins_keep_superadmin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_platform_admins_keep_superadmin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_remaining integer;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM public.platform_admins
  WHERE role = 'superadmin' AND is_active;

  IF v_remaining = 0 THEN
    RAISE EXCEPTION 'PLATFORM_LOCKOUT: لا يمكن ترك المنصة بلا سوبر أدمن نشط'
      USING ERRCODE = '23514',
            HINT = 'أضف سوبر أدمن آخر أو فعّل الحساب قبل تعطيل الأخير';
  END IF;

  RETURN NULL;  -- AFTER trigger
END;
$$;


--
-- Name: FUNCTION tg_platform_admins_keep_superadmin(); Type: COMMENT; Schema: public; Owner: -
--

