    payment_method_id text,
    payment_reference text
);


--
-- Name: custody_service_money; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.custody_service_money WITH (security_invoker='true') AS
 SELECT d.id AS custody_entry_id,
    d.customer_id,
    c.name AS customer_name_ar,
    d.document_number AS doc_number,
    d.created_at,
    si.id AS invoice_id,
    si.invoice_number,
    si.status,
    si.subtotal,
    si.tax,
    si.discount,
    si.total,
    si.paid,
    round((si.total - si.paid), 2) AS outstanding
   FROM ((public.milling_service_documents d
     JOIN public.sales_invoices si ON ((si.id = d.sales_invoice_id)))
     LEFT JOIN public.customers c ON ((c.id = d.customer_id)))
UNION ALL
 SELECT l.id AS custody_entry_id,
    l.customer_id,
    c.name AS customer_name_ar,
    l.doc_number,
    l.created_at,
    si.id AS invoice_id,
    si.invoice_number,
    si.status,
    si.subtotal,
    si.tax,
    si.discount,
    si.total,
    si.paid,
    round((si.total - si.paid), 2) AS outstanding
   FROM ((public.custody_ledger l
     JOIN public.sales_invoices si ON ((si.id = l.service_invoice_id)))
     LEFT JOIN public.customers c ON ((c.id = l.customer_id)))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.milling_service_documents d
          WHERE (d.sales_invoice_id = l.service_invoice_id))));


--
-- Name: customer_ledger; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_ledger (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    customer_id uuid NOT NULL,
    entry_type text NOT NULL,
    debit numeric(14,2) DEFAULT 0 NOT NULL,
    credit numeric(14,2) DEFAULT 0 NOT NULL,
    reference_id uuid,
    reference_type text,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    note text,
    source_key text,
    CONSTRAINT customer_ledger_check CHECK ((NOT ((debit > (0)::numeric) AND (credit > (0)::numeric)))),
    CONSTRAINT customer_ledger_check1 CHECK (((debit + credit) > (0)::numeric)),
    CONSTRAINT customer_ledger_credit_check CHECK ((credit >= (0)::numeric)),
    CONSTRAINT customer_ledger_debit_check CHECK ((debit >= (0)::numeric)),
    CONSTRAINT customer_ledger_entry_type_check CHECK ((entry_type = ANY (ARRAY['sale'::text, 'payment'::text, 'return'::text, 'adjustment'::text, 'credit'::text])))
);


--
-- Name: customer_ledger_balances; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.customer_ledger_balances WITH (security_invoker='true') AS
 SELECT c.id AS customer_id,
    c.name,
    round(COALESCE(sum((l.debit - l.credit)), (0)::numeric), 2) AS ledger_balance,
    c.balance AS legacy_balance,
    round((COALESCE(sum((l.debit - l.credit)), (0)::numeric) - c.balance), 2) AS difference
   FROM (public.customers c
     LEFT JOIN public.customer_ledger l ON ((l.customer_id = c.id)))
  GROUP BY c.id, c.name, c.balance;


