    source_type text,
    source_id uuid,
    is_system boolean DEFAULT false NOT NULL,
    reverses_id uuid,
    total_debit numeric(18,2) DEFAULT 0 NOT NULL,
    total_credit numeric(18,2) DEFAULT 0 NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    posted_by uuid,
    posted_at timestamp with time zone,
    CONSTRAINT journal_entries_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'POSTED'::text, 'REVERSED'::text]))),
    CONSTRAINT journal_no_self_reversal CHECK ((reverses_id IS DISTINCT FROM id)),
    CONSTRAINT journal_posted_has_totals CHECK (((status <> 'POSTED'::text) OR ((total_debit > (0)::numeric) AND (total_debit = total_credit))))
);


--
-- Name: invoice_ledger_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.invoice_ledger_status WITH (security_invoker='true') AS
 SELECT si.id AS invoice_id,
    si.invoice_number,
    (si.status)::text AS invoice_status,
    si.total,
    si.paid,
    si.tax,
    (si.payment_method)::text AS payment_method,
    je.id AS journal_entry_id,
    je.entry_number,
        CASE
            WHEN (je.id IS NOT NULL) THEN 'POSTED'::text
            WHEN (si.status = ANY (ARRAY['draft'::public.invoice_status, 'cancelled'::public.invoice_status])) THEN 'NEVER_POSTS'::text
            ELSE 'NOT_POSTED'::text
        END AS ledger_state,
        CASE
            WHEN ((je.id IS NOT NULL) AND (je.total_debit <> je.total_credit)) THEN 'UNBALANCED'::text
            ELSE 'OK'::text
        END AS integrity
   FROM (public.sales_invoices si
     LEFT JOIN public.journal_entries je ON (((je.source_type = 'sales_invoice'::text) AND (je.source_id = si.id) AND (je.status <> 'REVERSED'::text))));


--
-- Name: item_classification_gaps; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.item_classification_gaps WITH (security_invoker='true') AS
 SELECT id,
    sku,
    name_ar,
    item_nature,
    item_class,
    inventory_policy,
        CASE
            WHEN ((sku IS NULL) OR (btrim(sku) = ''::text)) THEN 'بلا رمز صنف — التصنيف الخماسي غير مُتحقَّق منه (نخالة أم دقيق؟) يحتاج تأكيداً يدوياً'::text
            WHEN (item_nature = 'SERVICE'::public.item_nature) THEN 'nature: service, class must be SERVICE'::text
            WHEN (inventory_policy = 'CUSTOMER_OWNED'::public.inventory_policy) THEN 'policy: customer owned, class must be NON_STOCK_ITEM'::text
            WHEN (inventory_policy = 'UNTRACKED'::public.inventory_policy) THEN 'policy: untracked, class must be SERVICE or NON_STOCK_ITEM'::text
            WHEN (sku ~~ 'RM-%'::text) THEN 'sku: raw material prefix, class should be RAW_MATERIAL'::text
            WHEN (sku = 'FG-BRAN-40'::text) THEN 'catalogue: bran is a by-product'::text
            ELSE 'unclassified GOOD+TRACKED item'::text
        END AS reason
   FROM public.products p
  WHERE (is_active AND ((item_class IS NULL) OR ((sku IS NULL) OR (btrim(sku) = ''::text)) OR ((item_nature = 'SERVICE'::public.item_nature) AND (item_class <> 'SERVICE'::public.item_class)) OR ((inventory_policy = 'CUSTOMER_OWNED'::public.inventory_policy) AND (item_class <> 'NON_STOCK_ITEM'::public.item_class)) OR ((inventory_policy = 'UNTRACKED'::public.inventory_policy) AND (item_nature = 'GOOD'::public.item_nature) AND (item_class <> 'NON_STOCK_ITEM'::public.item_class)) OR ((sku ~~ 'RM-%'::text) AND (item_class <> 'RAW_MATERIAL'::public.item_class)) OR ((sku = 'FG-BRAN-40'::text) AND (item_class <> 'BY_PRODUCT'::public.item_class))));


