--
-- Name: milling_inventory_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.milling_inventory_report WITH (security_invoker='true') AS
 SELECT p.item_class,
    p.id AS product_id,
    p.sku,
    p.name_ar,
    COALESCE(i.warehouse_name_ar, '—'::text) AS warehouse,
    COALESCE(i.qty, (0)::numeric) AS on_hand_qty,
    COALESCE(u.name_ar, '—'::text) AS unit,
    COALESCE(v.actual_unit_cost, (0)::numeric) AS unit_cost,
    (COALESCE(i.qty, (0)::numeric) * COALESCE(v.actual_unit_cost, (0)::numeric)) AS valuation,
    COALESCE(v.valuation_basis, 'REFERENCE_ONLY'::text) AS cost_basis
   FROM (((public.products p
     LEFT JOIN LATERAL ( SELECT sp.warehouse_name_ar,
            sp.quantity AS qty
           FROM public.stock_positions sp
          WHERE ((sp.item_id = p.id) AND sp.is_company_owned AND (sp.quantity <> (0)::numeric))
          ORDER BY sp.warehouse_name_ar) i ON (true))
     LEFT JOIN public.units u ON ((u.id = p.base_uom_id)))
     LEFT JOIN public.item_valuation v ON ((v.product_id = p.id)))
  WHERE ((p.item_class = ANY (ARRAY['RAW_MATERIAL'::public.item_class, 'FINISHED_GOOD'::public.item_class, 'BY_PRODUCT'::public.item_class, 'NON_STOCK_ITEM'::public.item_class])) AND p.is_active AND ((COALESCE(i.qty, (0)::numeric) <> (0)::numeric) OR (COALESCE(v.on_hand_qty, (0)::numeric) <> (0)::numeric)));


--
-- Name: sales_invoice_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_invoice_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_id uuid NOT NULL,
    product_id uuid,
    quantity numeric(14,3) NOT NULL,
    unit_price numeric(14,2) NOT NULL,
    discount numeric(14,2) DEFAULT 0 NOT NULL,
    tax numeric(14,2) DEFAULT 0 NOT NULL,
    total numeric(14,2) NOT NULL,
    description text,
    line_type text,
    stock_effect text,
    uom_id uuid,
    batch_id uuid,
    batch_number text,
    CONSTRAINT sales_invoice_items_line_type_valid CHECK (((line_type IS NULL) OR (line_type = ANY (ARRAY['STOCKED_GOOD'::text, 'UNTRACKED_GOOD'::text, 'SERVICE'::text, 'CUSTOMER_OWNED_GOOD'::text, 'AD_HOC_SERVICE'::text])))),
    CONSTRAINT sales_invoice_items_stock_effect_valid CHECK (((stock_effect IS NULL) OR (stock_effect = ANY (ARRAY['STOCK_ISSUE'::text, 'STOCK_RECEIPT'::text, 'NONE'::text]))))
);


--
-- Name: milling_margin_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.milling_margin_report WITH (security_invoker='true') AS
 WITH sold AS (
         SELECT it.product_id,
            sum(it.quantity) AS qty_sold,
            sum(it.total) AS revenue,
            count(DISTINCT si.id) AS invoice_count
           FROM (public.sales_invoice_items it
             JOIN public.sales_invoices si ON ((si.id = it.invoice_id)))
          WHERE (((si.created_at)::date >= (CURRENT_DATE - 365)) AND ((si.created_at)::date <= CURRENT_DATE) AND (si.status <> ALL (ARRAY['draft'::public.invoice_status, 'cancelled'::public.invoice_status])) AND (it.stock_effect = 'STOCK_ISSUE'::text))
          GROUP BY it.product_id
        )
 SELECT p.id AS product_id,
    p.sku,
    p.name_ar,
    p.item_class,
    COALESCE(s.qty_sold, (0)::numeric) AS qty_sold,
    COALESCE(s.revenue, (0)::numeric) AS revenue,
    COALESCE(s.invoice_count, (0)::bigint) AS invoice_count,
    c.unit_cost,
    c.basis,
    round((COALESCE(s.qty_sold, (0)::numeric) * COALESCE(c.unit_cost, (0)::numeric)), 2) AS cost_of_goods,
    round((COALESCE(s.revenue, (0)::numeric) - (COALESCE(s.qty_sold, (0)::numeric) * COALESCE(c.unit_cost, (0)::numeric))), 2) AS margin,
        CASE
            WHEN (COALESCE(s.revenue, (0)::numeric) > (0)::numeric) THEN round((((COALESCE(s.revenue, (0)::numeric) - (COALESCE(s.qty_sold, (0)::numeric) * COALESCE(c.unit_cost, (0)::numeric))) * (100)::numeric) / s.revenue), 2)
            ELSE NULL::numeric
        END AS margin_pct,
        CASE
            WHEN (c.basis = 'ACTUAL'::text) THEN 'ACTUAL'::text
            ELSE 'REFERENCE'::text
        END AS cost_basis
   FROM ((sold s
     JOIN public.products p ON ((p.id = s.product_id)))
     LEFT JOIN LATERAL ( SELECT COALESCE(
                CASE
                    WHEN (l.quantity > (0)::numeric) THEN round((l.total_value / l.quantity), 4)
                    ELSE NULL::numeric
                END, p.cost_price, (0)::numeric) AS unit_cost,
                CASE
                    WHEN ((l.quantity > (0)::numeric) AND (l.total_value > (0)::numeric)) THEN 'ACTUAL'::text
                    ELSE 'REFERENCE'::text
                END AS basis
           FROM (( SELECT 1 AS "?column?") x
             LEFT JOIN LATERAL ( SELECT sum(cl.quantity) AS quantity,
                    sum(cl.total_value) AS total_value
                   FROM public.item_cost_layers cl
                  WHERE ((cl.product_id = p.id) AND (cl.owner_type = 'COMPANY'::public.owner_type))) l ON (true))) c ON (true));


