COPY supabase_migrations.schema_migrations (version, statements, name) FROM stdin;
01	{"-- ============================================================================\r\n-- 01_core_enums_and_helpers.sql\r\n--\r\n-- الأساس: أنواع ENUM + الدوال المساعدة التي تعتمد عليها كل السياسات (is_staff, has_role, is_platform_admin, tg_set_updated_at).\r\n-- لا جداول هنا — كل شيء لاحق يعتمد على هذا الملف.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── ENUMS ──────────────────────────────────────────────────────────────\r\n-- كل نوع هنا يمثّل **مفهومًا واحدًا فقط**. لا تُخلط حالتان في نوع واحد، لأن\r\n-- العمود الواحد لا يحمل قيمتين — فتضيع إحداهما بلا أثر.\r\n\r\n-- نوع الحساب في محاسبة القيد المزدوج.\r\nCREATE TYPE public.account_type AS ENUM (\r\n  'ASSET',       -- أصول\r\n  'LIABILITY',   -- خصوم\r\n  'EQUITY',      -- حقوق ملكية\r\n  'REVENUE',     -- إيرادات\r\n  'EXPENSE'      -- مصروفات\r\n)","-- أدوار النظام. الترتيب هنا لا يحدّد الصلاحية — الرتبة في expense_role_rank().\r\nCREATE TYPE public.app_role AS ENUM (\r\n  'owner',       -- المالك: كل الصلاحيات\r\n  'manager',     -- مدير: التشغيل والاعتماد\r\n  'accountant',  -- محاسب: القيود والتقارير المالية\r\n  'cashier',     -- كاشير: البيع والتحصيل\r\n  'warehouse'    -- أمين مخزن: الاستلام والصرف والجرد\r\n)","-- طريقة تقييم المخزون.\r\n-- NONE ليست طريقة تكلفة بل غيابها، وهي مقصودة للخدمات: الصنف نوعه SERVICE\r\n-- لا يُكلَّف أصلًا. كتابة NONE أوضح للمحاسب من NULL في تقرير التكلفة.\r\nCREATE TYPE public.costing_method AS ENUM (\r\n  'MOVING_AVERAGE',  -- المتوسط المتحرك المرجّح (الافتراضي)\r\n  'FIFO',            -- الوارد أولًا صادر أولًا\r\n  'STANDARD',        -- التكلفة المعيارية\r\n  'NONE'             -- بلا تكلفة — للخدمات\r\n)","CREATE TYPE public.expense_entry_type AS ENUM (\r\n  'DIRECT',\r\n  'EMPLOYEE',\r\n  'SUPPLIER',\r\n  'RECURRING',\r\n  'ADVANCE'\r\n)","CREATE TYPE public.expense_payee_type AS ENUM (\r\n  'NONE',\r\n  'SUPPLIER',\r\n  'EMPLOYEE',\r\n  'OTHER'\r\n)","CREATE TYPE public.expense_source_kind AS ENUM (\r\n  'MANUAL',\r\n  'LEGACY',\r\n  'RECURRING',\r\n  'IMPORT'\r\n)","CREATE TYPE public.expense_status AS ENUM (\r\n  'DRAFT',\r\n  'SUBMITTED',\r\n  'APPROVED',\r\n  'REJECTED',\r\n  'POSTED',\r\n  'PARTIALLY_PAID',\r\n  'PAID',\r\n  'CLOSED',\r\n  'CANCELLED',\r\n  'REVERSED'\r\n)","CREATE TYPE public.expense_tax_mode AS ENUM (\r\n  'NONE',\r\n  'INCLUSIVE',\r\n  'EXCLUSIVE'\r\n)","CREATE TYPE public.inventory_policy AS ENUM (\r\n  'TRACKED',        -- يُتابَع رصيده\r\n  'UNTRACKED',      -- يُباع ولا يُتابَع\r\n  'CUSTOMER_OWNED'  -- ملك عميل (أمانة)\r\n)","-- ── دورة حياة المستند — وحدها ──────────────────────────────────────────────\r\n-- هذا النوع يصف **أين المستند** في دورة حياته، لا كم دُفع منه.\r\n--\r\n-- كان سابقًا يخلط أربعة مفاهيم في نوع واحد: حالة المستند، وحالة السداد،\r\n-- وحالة الإرجاع، ودورة الشراء. والنتيجة أن العمود الواحد لا يحمل قيمتين:\r\n-- فاتورة «مؤكدة» و«مدفوعة جزئيًا» في وقت واحد كان يستحيل تمثيلها، فتضيع\r\n-- إحدى الحالتين. وحالة المستند كانت تُكتب من مبلغ السداد، فتُمحى «مؤكدة».\r\n--\r\n-- اليوم: حالة الدورة هنا، وحالة السداد في payment_status.\r\nCREATE TYPE public.invoice_status AS ENUM (\r\n  'draft',      -- مسودة: قابلة للتعديل، بلا أثر مالي\r\n  'confirmed',  -- مؤكدة: أُصدرت وأصبحت دليلًا\r\n  'cancelled',  -- ملغاة: لم تحدث\r\n  'returned'    -- مُرجَعة: أُعيدت بالكامل\r\n)","-- ── حالة السداد — منفصلة ───────────────────────────────────────────────────\r\n-- تُشتقّ من مبلغ المدفوع مقابل الإجمالي، ولا تُكتب يدويًا.\r\nCREATE TYPE public.payment_status AS ENUM (\r\n  'unpaid',    -- لم يُدفع منه شيء\r\n  'partial',   -- دُفع جزء\r\n  'paid',      -- سُدّد بالكامل\r\n  'overpaid'   -- دُفع أكثر من المستحق (دفعة مقدمة أو إفراط)\r\n)","CREATE TYPE public.item_class AS ENUM (\r\n  'RAW_MATERIAL',\r\n  'FINISHED_GOOD',\r\n  'BY_PRODUCT',\r\n  'SERVICE',\r\n  'NON_STOCK_ITEM',\r\n  'PACKAGING'\r\n)","CREATE TYPE public.item_nature AS ENUM (\r\n  'GOOD',\r\n  'SERVICE'\r\n)","CREATE TYPE public.item_status AS ENUM (\r\n  'ACTIVE',\r\n  'INACTIVE',\r\n  'ARCHIVED'\r\n)","CREATE TYPE public.item_tracking AS ENUM (\r\n  'NONE',\r\n  'BATCH',\r\n  'SERIAL'\r\n)","-- ── نوع حركة المخزون — بلا تكرار ───────────────────────────────────────────\r\n-- كان سابقًا عشرة قيم فيها تكرار فعلي: return_in ≡ sale_return،\r\n-- و return_out ≡ purchase_return. فأي تقرير للمرتجعات كان يجب أن يبحث عن\r\n-- أربع قيم لنفس المفهومين، وإن نسي إحداها نقصت الأرقام بلا رسالة خطأ.\r\n-- اليوم: قيمة واحدة لكل حدث.\r\nCREATE TYPE public.movement_type AS ENUM (\r\n  'purchase',         -- شراء يُدخل بضاعة\r\n  'sale',             -- بيع يُخرج بضاعة\r\n  'adjustment',       -- تسوية جرد\r\n  'transfer_in',      -- وارد تحويل بين مستودعين\r\n  'transfer_out',     -- صادر تحويل\r\n  'sale_return',      -- مرتجع بيع يُدخل البضاعة\r\n  'purchase_return',  -- مرتجع شراء يُخرج البضاعة\r\n  'opening',          -- رصيد أول المدة\r\n  'production_in',    -- ناتج إنتاج يدخل المخزون\r\n  'production_out'    -- مواد تُصرف للإنتاج\r\n)","CREATE TYPE public.owner_type AS ENUM (\r\n  'COMPANY',\r\n  'CUSTOMER',\r\n  'SUPPLIER',\r\n  'OTHER'\r\n)","-- ── طرق الدفع ──────────────────────────────────────────────────────────────\r\n-- cheque أُضيفت لأن الواجهة كانت تترجمها بلا وجود لها في النوع، فكان الشيك\r\n-- يُقيَّد في «النقدية بالصندوق» لأن دالة الترحيل لا تجد له قيمة، فتفترض النقدية.\r\n-- والأثر خطير: شيك بمليون ريال يُظهر صندوقًا فيه مليون غير موجود، ويُفقد\r\n-- البنك حوالة واردة. وميزان المراجعة يبقى متوازنًا لأن الخطأ في أي حساب\r\n-- استُخدم لا في الحساب الرياضي — فلا يُكتشف أبدًا.\r\nCREATE TYPE public.payment_method AS ENUM (\r\n  'cash',           -- نقدًا: يُقيَّد في 1101 الصندوق\r\n  'card',           -- شبكة/بطاقة: تُقيَّد في 1111 البنك\r\n  'bank_transfer',  -- حوالة بنكية: تُقيَّد في 1111 البنك\r\n  'mobile_money',   -- محفظة إلكترونية: تُقيَّد في 1111 البنك\r\n  'cheque',         -- شيك مصرفي: يُقيَّد في 1111 البنك\r\n  'credit',         -- آجل: ذمم، لا نقدية\r\n  'split'           -- مجزّأ: أكثر من وسيلة في سند واحد\r\n)","CREATE TYPE public.stock_movement_kind AS ENUM (\r\n  'RECEIPT',\r\n  'ISSUE',\r\n  'TRANSFER_IN',\r\n  'TRANSFER_OUT',\r\n  'ADJUSTMENT',\r\n  'OPENING',\r\n  'PRODUCTION'\r\n)","-- ── PURE HELPERS ───────────────────────────────────────────────────\r\n-- دوال حسابية بلا جداول ولا اعتماديات. تُعرَّف هنا لتكون متاحة لكل ملف لاحق.\r\n\r\n-- اشتقاق حالة السداد من المدفوع مقابل الإجمالي.\r\n-- المصدر الوحيد للحقيقة: استخدامها في كل دالة تكتب مدفوعة يمنع حالة سداد\r\n-- وُكتبت يدويًا ثم خالفت المبالغ الفعلية.\r\n--\r\n-- الحدود: 0 مدفوع ⇒ unpaid، مساوٍ للإجمالي ⇒ paid، أكثر منه ⇒ overpaid،\r\n-- وما بينهما ⇒ partial. واستخدمت 0.005 كهامش لأن العمليات المالية تُدوَّر\r\n-- إلى منزلتين، وبقايا الهللة يجب ألّا تُبقي فاتورة «جزئية» للأبد.\r\nCREATE OR REPLACE FUNCTION public.derive_payment_status(p_paid numeric, p_total numeric)\r\nRETURNS public.payment_status\r\nLANGUAGE sql\r\nIMMUTABLE\r\nSET search_path = public\r\nAS $function$\r\n  SELECT CASE\r\n    WHEN coalesce(p_total, 0) <= 0            THEN 'unpaid'::public.payment_status\r\n    WHEN coalesce(p_paid, 0) <= 0             THEN 'unpaid'::public.payment_status\r\n    WHEN p_paid >= p_total - 0.005            THEN 'paid'::public.payment_status\r\n    ELSE 'partial'::public.payment_status\r\n  END\r\n$function$","COMMENT ON FUNCTION public.derive_payment_status(numeric, numeric) IS\r\n  'يشتقّ حالة السداد من (المدفوع مقابل الإجمالي). نقطة الحقيقة الواحدة — لا تُكتب الحالة يدويًا.'","-- التقريب المعياري: منزلتان عشريتان، بنوع numeric لا float لتفادي انزلاق\r\n-- الفاصلة العائمة عبر ملايين الصفوف.\r\nCREATE OR REPLACE FUNCTION public.expense_round(p_value numeric)\r\n RETURNS numeric\r\n LANGUAGE sql\r\n IMMUTABLE\r\nAS $function$\r\n  -- numeric لا float: الـ 0.005 يجب أن تُدوَّر كما يتوقّع المحاسب، ومجموع مليون\r\n  -- صف لا يجب أن يراكم انزلاق الفاصلة العائمة.\r\n  SELECT round(coalesce(p_value, 0)::numeric, 2)\r\n$function$","CREATE OR REPLACE FUNCTION public.expense_line_net(p_gross numeric, p_tax_rate numeric, p_mode expense_tax_mode)\r\n RETURNS numeric\r\n LANGUAGE sql\r\n IMMUTABLE\r\nAS $function$\r\n  SELECT CASE\r\n    WHEN p_gross IS NULL THEN NULL\r\n    WHEN p_tax_rate IS NULL OR p_tax_rate <= 0 THEN public.expense_round(p_gross)\r\n    WHEN p_mode = 'EXCLUSIVE' THEN public.expense_round(p_gross)\r\n    ELSE public.expense_round(p_gross / (1 + (p_tax_rate / 100)))\r\n  END\r\n$function$","CREATE OR REPLACE FUNCTION public.expense_line_tax(p_gross numeric, p_tax_rate numeric, p_mode expense_tax_mode)\r\n RETURNS numeric\r\n LANGUAGE sql\r\n IMMUTABLE\r\nAS $function$\r\n  SELECT CASE\r\n    WHEN p_gross IS NULL THEN NULL\r\n    WHEN p_tax_rate IS NULL OR p_tax_rate <= 0 THEN 0::numeric\r\n    ELSE public.expense_round(p_gross - public.expense_line_net(p_gross, p_tax_rate, p_mode))\r\n  END\r\n$function$"}	core_enums_and_helpers
02	{"-- ============================================================================\r\n-- 02_core_identity_and_settings.sql\r\n--\r\n-- الهوية والإعدادات: المستخدمون، الأدوار، إعدادات الشركة، المستودعات، الأجهزة، مفاتيح المزامنة.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── TABLES ────────────────────────────────────────────────────────────────\r\nCREATE TABLE public.profiles (\r\n  id uuid NOT NULL,\r\n  full_name text,\r\n  avatar_url text,\r\n  phone text,\r\n  language text DEFAULT 'en'::text NOT NULL,\r\n  theme text DEFAULT 'dark'::text NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL\r\n)","CREATE TABLE public.user_roles (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  user_id uuid NOT NULL,\r\n  role public.app_role NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.platform_admins (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  user_id uuid NOT NULL,\r\n  role text NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  mfa_required boolean DEFAULT true NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  last_login timestamp with time zone\r\n)","CREATE TABLE public.company_settings (\r\n  id integer DEFAULT 1 NOT NULL,\r\n  name text DEFAULT 'My Company'::text NOT NULL,\r\n  legal_name text,\r\n  tax_number text,\r\n  currency text DEFAULT 'YER'::text NOT NULL,\r\n  currency_symbol text DEFAULT 'ر.ي'::text NOT NULL,\r\n  tax_rate numeric(6,3) DEFAULT 0 NOT NULL,\r\n  logo_url text,\r\n  address text,\r\n  phone text,\r\n  email text,\r\n  invoice_prefix text DEFAULT 'INV-'::text NOT NULL,\r\n  barcode_enabled boolean DEFAULT true NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  enforce_customer_credit_limit boolean DEFAULT false NOT NULL,\r\n  catalog_modules jsonb DEFAULT '{\\"profile\\": \\"spare_parts\\", \\"enableUnits\\": true, \\"enableBrands\\": true, \\"enableOrigins\\": true, \\"enableQualityGrades\\": true, \\"enableMakesAndModels\\": true}'::jsonb NOT NULL,\r\n  purchase_invoice_prefix text DEFAULT 'PO-'::text NOT NULL,\r\n  invoice_number_period text DEFAULT 'year_month'::text NOT NULL,\r\n  invoice_number_digits smallint DEFAULT 4 NOT NULL,\r\n  name_ar text,\r\n  name_en text,\r\n  contact_numbers text,\r\n  footer_contact text,\r\n  footer_text text\r\n)","CREATE TABLE public.company_costing_settings (\r\n  id smallint DEFAULT 1 NOT NULL,\r\n  costing_method public.costing_method DEFAULT 'MOVING_AVERAGE'::costing_method NOT NULL,\r\n  standard_cost_source text DEFAULT 'CATALOGUE'::text NOT NULL,\r\n  effective_from date DEFAULT CURRENT_DATE NOT NULL,\r\n  updated_by uuid,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  notes text\r\n)","CREATE TABLE public.warehouses (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  name text NOT NULL,\r\n  code text,\r\n  address text,\r\n  is_default boolean DEFAULT false NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  name_ar text\r\n)","CREATE TABLE public.device_registrations (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  device_id text NOT NULL,\r\n  device_name text NOT NULL,\r\n  platform text DEFAULT 'browser'::text NOT NULL,\r\n  assigned_warehouse_id uuid,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  last_seen_at timestamp with time zone DEFAULT now(),\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.sync_idempotency_keys (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  idempotency_key text NOT NULL,\r\n  entity_name text NOT NULL,\r\n  operation_type text NOT NULL,\r\n  origin_device_id text NOT NULL,\r\n  status text DEFAULT 'processing'::text NOT NULL,\r\n  response_payload jsonb,\r\n  error_message text,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.backup_logs (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  tenant_id text DEFAULT 'default'::text NOT NULL,\r\n  actor_id uuid,\r\n  actor_name text DEFAULT 'المالك (Owner)'::text NOT NULL,\r\n  action_type text NOT NULL,\r\n  storage_type text NOT NULL,\r\n  status text NOT NULL,\r\n  file_name text NOT NULL,\r\n  file_size_bytes bigint DEFAULT 0 NOT NULL,\r\n  metadata jsonb,\r\n  error_message text,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","-- ── CORE AUTHORIZATION HELPERS ────────────────────────────────────────\r\n-- is_staff / has_role: every RLS policy in this and every later file\r\n-- calls one of these. They read public.user_roles, so they are defined\r\n-- here, immediately after that table.\r\nCREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT\r\n    EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id)\r\n    AND COALESCE((SELECT is_active FROM public.profiles WHERE id = _user_id), false)\r\n$function$","CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role)\r\n$function$","CREATE OR REPLACE FUNCTION public.is_platform_admin(p_user_id uuid)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO ''\r\nAS $function$\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.platform_admins\r\n    WHERE user_id = p_user_id\r\n      AND is_active = true\r\n  );\r\n$function$","CREATE OR REPLACE FUNCTION public.is_platform_superadmin(p_user_id uuid)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO ''\r\nAS $function$\r\n  -- 'superadmin' only — not 'admin'. The table's CHECK constraint allows\r\n  -- exactly two roles, superadmin and support, so a predicate accepting\r\n  -- 'admin' could never be satisfied by a stored row: it was dead code that\r\n  -- read as if a third role existed. 'support' is deliberately excluded —\r\n  -- it is read-only and must not satisfy superadmin-only policies.\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.platform_admins\r\n    WHERE user_id = p_user_id\r\n      AND role = 'superadmin'\r\n      AND is_active = true\r\n  );\r\n$function$","CREATE OR REPLACE FUNCTION public.expense_role_rank(p_user uuid)\r\n RETURNS integer\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT CASE\r\n    WHEN public.has_role(p_user, 'owner')      THEN 50\r\n    WHEN public.has_role(p_user, 'manager')    THEN 40\r\n    WHEN public.has_role(p_user, 'accountant') THEN 30\r\n    WHEN public.has_role(p_user, 'cashier')    THEN 20\r\n    WHEN public.has_role(p_user, 'warehouse')  THEN 10\r\n    ELSE 0\r\n  END\r\n$function$","CREATE OR REPLACE FUNCTION public.can_read_finance(p_user uuid)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT public.is_staff(p_user) AND public.expense_role_rank(p_user) >= 30\r\n$function$","CREATE OR REPLACE FUNCTION public.can_operate_milling()\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT public.is_staff(auth.uid())\r\n     AND EXISTS (\r\n       SELECT 1\r\n       FROM public.user_roles ur\r\n       WHERE ur.user_id = auth.uid()\r\n         AND ur.role IN ('owner', 'manager', 'warehouse', 'cashier')\r\n     );\r\n$function$","CREATE OR REPLACE FUNCTION public.can_view_milling()\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT public.is_staff(auth.uid())\r\n     AND EXISTS (\r\n       SELECT 1\r\n       FROM public.user_roles ur\r\n       WHERE ur.user_id = auth.uid()\r\n         AND ur.role IN ('owner', 'manager', 'accountant', 'warehouse', 'cashier')\r\n     );\r\n$function$","-- ── IDENTITY TRIGGERS ─────────────────────────────────────────────────\r\n-- tg_set_updated_at is attached to nearly every table by later migrations;\r\n-- handle_new_user is the auth trigger that writes to public.profiles, which\r\n-- exists above.\r\n--\r\n-- There is deliberately NO \\"first user becomes owner\\" trigger here. It was\r\n-- removed: it granted a tenant role on a race rather than on a decision, so\r\n-- whoever happened to sign up first — a customer, a typo, an abandoned test\r\n-- account — silently became the owner of the deployment, and the grant could\r\n-- not be withdrawn afterwards because the rule lived in the trigger, not in\r\n-- the data. Roles are now assigned explicitly by someone who already holds\r\n-- authority to assign them. See supabase/seeds/01_system/06_platform_admins.sql\r\n-- for how the initial platform administrators are provisioned instead.\r\nCREATE OR REPLACE FUNCTION public.tg_set_updated_at()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\n SET search_path TO 'public'\r\nAS $function$\r\nBEGIN NEW.updated_at = now(); RETURN NEW; END $function$","CREATE OR REPLACE FUNCTION public.handle_new_user()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  INSERT INTO public.profiles (id, full_name, avatar_url, language, theme)\r\n  VALUES (\r\n    NEW.id,\r\n    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),\r\n    NEW.raw_user_meta_data->>'avatar_url',\r\n    'ar',\r\n    'dark'\r\n  )\r\n  ON CONFLICT (id) DO UPDATE\r\n    SET full_name = COALESCE(EXCLUDED.full_name, public.profiles.full_name);\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$","-- ── CONSTRAINTS ───────────────────────────────────────────────────────────\r\nALTER TABLE public.profiles ADD CONSTRAINT \\"profiles_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.user_roles ADD CONSTRAINT \\"user_roles_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.user_roles ADD CONSTRAINT \\"user_roles_user_id_role_key\\" UNIQUE (user_id, role)","ALTER TABLE public.platform_admins ADD CONSTRAINT \\"platform_admins_role_check\\" CHECK ((role = ANY (ARRAY['superadmin'::text, 'support'::text])))","ALTER TABLE public.platform_admins ADD CONSTRAINT \\"platform_admins_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.platform_admins ADD CONSTRAINT \\"uq_platform_admin_user\\" UNIQUE (user_id)","ALTER TABLE public.company_settings ADD CONSTRAINT \\"company_settings_invoice_number_digits_check\\" CHECK (((invoice_number_digits >= 1) AND (invoice_number_digits <= 8)))","ALTER TABLE public.company_settings ADD CONSTRAINT \\"company_settings_invoice_number_period_check\\" CHECK ((invoice_number_period = ANY (ARRAY['none'::text, 'year'::text, 'year_month'::text])))","ALTER TABLE public.company_settings ADD CONSTRAINT \\"only_one_row\\" CHECK ((id = 1))","ALTER TABLE public.company_settings ADD CONSTRAINT \\"company_settings_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.company_costing_settings ADD CONSTRAINT \\"company_costing_settings_singleton\\" CHECK ((id = 1))","ALTER TABLE public.company_costing_settings ADD CONSTRAINT \\"company_costing_settings_standard_cost_source_check\\" CHECK ((standard_cost_source = ANY (ARRAY['CATALOGUE'::text, 'ROLLING_AVERAGE'::text, 'MANUAL'::text])))","ALTER TABLE public.company_costing_settings ADD CONSTRAINT \\"company_costing_settings_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.warehouses ADD CONSTRAINT \\"warehouses_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.warehouses ADD CONSTRAINT \\"warehouses_code_key\\" UNIQUE (code)","ALTER TABLE public.device_registrations ADD CONSTRAINT \\"device_registrations_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.device_registrations ADD CONSTRAINT \\"device_registrations_device_id_key\\" UNIQUE (device_id)","ALTER TABLE public.sync_idempotency_keys ADD CONSTRAINT \\"sync_idempotency_keys_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.sync_idempotency_keys ADD CONSTRAINT \\"sync_idempotency_keys_idempotency_key_key\\" UNIQUE (idempotency_key)","ALTER TABLE public.backup_logs ADD CONSTRAINT \\"backup_logs_action_type_check\\" CHECK ((action_type = ANY (ARRAY['manual_local'::text, 'manual_cloud'::text, 'auto_scheduled'::text, 'pre_restore_safety'::text])))","ALTER TABLE public.backup_logs ADD CONSTRAINT \\"backup_logs_status_check\\" CHECK ((status = ANY (ARRAY['success'::text, 'failed'::text, 'in_progress'::text, 'pending'::text])))","ALTER TABLE public.backup_logs ADD CONSTRAINT \\"backup_logs_storage_type_check\\" CHECK ((storage_type = ANY (ARRAY['local'::text, 'cloud'::text, 'both'::text])))","ALTER TABLE public.backup_logs ADD CONSTRAINT \\"backup_logs_pkey\\" PRIMARY KEY (id)","-- ── INDEXES ───────────────────────────────────────────────────────────────\r\nCREATE INDEX idx_sync_device_origin ON public.sync_idempotency_keys USING btree (origin_device_id, created_at)","CREATE INDEX idx_sync_idempotency_key ON public.sync_idempotency_keys USING btree (idempotency_key)","CREATE INDEX idx_backup_logs_tenant_created ON public.backup_logs USING btree (tenant_id, created_at DESC)","-- ── FUNCTIONS ─────────────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.normalize_auth_user_token_columns()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO ''\r\nAS $function$\r\nBEGIN\r\n  IF NEW.confirmation_token IS NULL THEN\r\n    NEW.confirmation_token := '';\r\n  END IF;\r\n  IF NEW.recovery_token IS NULL THEN\r\n    NEW.recovery_token := '';\r\n  END IF;\r\n  IF NEW.email_change_token_new IS NULL THEN\r\n    NEW.email_change_token_new := '';\r\n  END IF;\r\n  IF NEW.email_change_token_current IS NULL THEN\r\n    NEW.email_change_token_current := '';\r\n  END IF;\r\n  IF NEW.email_change IS NULL THEN\r\n    NEW.email_change := '';\r\n  END IF;\r\n  RETURN NEW;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.sync_apply_operation(p_idempotency_key text, p_entity_name text, p_operation_type text, p_origin_device_id text, p_payload jsonb)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_existing RECORD;\r\n  v_result JSONB;\r\nBEGIN\r\n  -- ⚠️ المدخلات إلزامية: بلا هذا الفحص كان NULL يمر إلى idempotency_key\r\n  --    (NOT NULL) فيظهر الخطأ كـ «null value in column ... violates not-null\r\n  --    constraint» ملفوفًا برسالة غير مفهومة بدل رفض واضح للمدخل.\r\n  IF nullif(btrim(coalesce(p_idempotency_key, '')), '') IS NULL\r\n     OR nullif(btrim(coalesce(p_entity_name, '')), '') IS NULL\r\n     OR nullif(btrim(coalesce(p_operation_type, '')), '') IS NULL\r\n     OR nullif(btrim(coalesce(p_origin_device_id, '')), '') IS NULL THEN\r\n    RAISE EXCEPTION 'Sync operation requires idempotency_key, entity_name, operation_type and origin_device_id'\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  -- 1. Check if idempotency key exists\r\n  SELECT * INTO v_existing\r\n  FROM public.sync_idempotency_keys\r\n  WHERE idempotency_key = p_idempotency_key;\r\n\r\n  IF FOUND THEN\r\n    IF v_existing.status = 'completed' THEN\r\n      RETURN jsonb_build_object(\r\n        'status', 'DUPLICATE_ACK',\r\n        'idempotency_key', p_idempotency_key,\r\n        'message', 'Operation already processed previously',\r\n        'result', v_existing.response_payload\r\n      );\r\n    ELSIF v_existing.status = 'processing' THEN\r\n      -- In-flight request concurrent lock\r\n      RETURN jsonb_build_object(\r\n        'status', 'IN_FLIGHT',\r\n        'idempotency_key', p_idempotency_key,\r\n        'message', 'Operation is currently being processed by server'\r\n      );\r\n    END IF;\r\n  END IF;\r\n\r\n  -- 2. Insert processing lock\r\n  INSERT INTO public.sync_idempotency_keys (\r\n    idempotency_key,\r\n    entity_name,\r\n    operation_type,\r\n    origin_device_id,\r\n    status\r\n  ) VALUES (\r\n    p_idempotency_key,\r\n    p_entity_name,\r\n    p_operation_type,\r\n    p_origin_device_id,\r\n    'processing'\r\n  );\r\n\r\n  -- 3. Return success acknowledgment payload template\r\n  v_result := jsonb_build_object(\r\n    'acknowledged', true,\r\n    'entity_name', p_entity_name,\r\n    'operation_type', p_operation_type,\r\n    'processed_at', now()\r\n  );\r\n\r\n  -- Mark completed\r\n  UPDATE public.sync_idempotency_keys\r\n  SET status = 'completed',\r\n      response_payload = v_result,\r\n      updated_at = now()\r\n  WHERE idempotency_key = p_idempotency_key;\r\n\r\n  RETURN jsonb_build_object(\r\n    'status', 'PROCESSED',\r\n    'idempotency_key', p_idempotency_key,\r\n    'result', v_result\r\n  );\r\n\r\nEXCEPTION WHEN OTHERS THEN\r\n  UPDATE public.sync_idempotency_keys\r\n  SET status = 'failed',\r\n      error_message = SQLERRM,\r\n      updated_at = now()\r\n  WHERE idempotency_key = p_idempotency_key;\r\n\r\n  RAISE EXCEPTION 'Sync Apply Operation Failed: %', SQLERRM;\r\nEND;\r\n$function$"}	core_identity_and_settings
03	{"-- ============================================================================\r\n-- 03_catalog_reference_data.sql\r\n--\r\n-- بيانات مرجعية للكتالوج: تصنيفات، علامات، وحدات، بلدان منشأ، درجات جودة، طرازات مركبات.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── TABLES ────────────────────────────────────────────────────────────────\r\nCREATE TABLE public.categories (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  name text NOT NULL,\r\n  name_ar text,\r\n  parent_id uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.brands (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  name text NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  name_ar text\r\n)","CREATE TABLE public.units (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  name text NOT NULL,\r\n  short_name text NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  name_ar text\r\n)","CREATE TABLE public.countries_of_origin (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  code char(2) NOT NULL,\r\n  name text NOT NULL,\r\n  name_ar text NOT NULL\r\n)","CREATE TABLE public.quality_grades (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  code text NOT NULL,\r\n  name text NOT NULL,\r\n  name_ar text NOT NULL,\r\n  sort_order integer DEFAULT 0 NOT NULL\r\n)","CREATE TABLE public.vehicle_makes (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  name text NOT NULL,\r\n  name_ar text NOT NULL\r\n)","CREATE TABLE public.vehicle_models (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  make_id uuid NOT NULL,\r\n  name text NOT NULL,\r\n  name_ar text\r\n)","CREATE TABLE public.packaging_types (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  code varchar(20) NOT NULL,\r\n  name_ar varchar(60) NOT NULL,\r\n  name_en varchar(60),\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  sort_order smallint DEFAULT 0 NOT NULL,\r\n  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL\r\n)","-- ── CONSTRAINTS ───────────────────────────────────────────────────────────\r\nALTER TABLE public.categories ADD CONSTRAINT \\"categories_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.brands ADD CONSTRAINT \\"brands_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.units ADD CONSTRAINT \\"units_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.units ADD CONSTRAINT \\"units_name_key\\" UNIQUE (name)","ALTER TABLE public.countries_of_origin ADD CONSTRAINT \\"countries_of_origin_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.countries_of_origin ADD CONSTRAINT \\"countries_of_origin_code_key\\" UNIQUE (code)","ALTER TABLE public.quality_grades ADD CONSTRAINT \\"quality_grades_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.quality_grades ADD CONSTRAINT \\"quality_grades_code_key\\" UNIQUE (code)","ALTER TABLE public.vehicle_makes ADD CONSTRAINT \\"vehicle_makes_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.vehicle_makes ADD CONSTRAINT \\"vehicle_makes_name_key\\" UNIQUE (name)","ALTER TABLE public.vehicle_models ADD CONSTRAINT \\"vehicle_models_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.vehicle_models ADD CONSTRAINT \\"vehicle_models_make_id_name_key\\" UNIQUE (make_id, name)","ALTER TABLE public.packaging_types ADD CONSTRAINT \\"packaging_types_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.packaging_types ADD CONSTRAINT \\"packaging_types_code_key\\" UNIQUE (code)"}	catalog_reference_data
04	{"-- ============================================================================\r\n-- 05_partners_customers_suppliers.sql\r\n--\r\n-- المخزون وحركاته: الأرصدة، الحركات، طبقات التكلفة، الدفعات، التحويلات، الأرصدة الافتتاحية، التسويات.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── TABLES ────────────────────────────────────────────────────────────────\r\nCREATE TABLE public.customers (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  name text NOT NULL,\r\n  phone text,\r\n  email text,\r\n  address text,\r\n  credit_limit numeric(14,2) DEFAULT 0 NOT NULL,\r\n  balance numeric(14,2) DEFAULT 0 NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  loyalty_points numeric DEFAULT 0 NOT NULL,\r\n  -- P1-6: كيان نظامي (العميل النقدي). العلامة أساس الحماية، لا الاسم.\r\n  is_system boolean DEFAULT false NOT NULL,\r\n  system_key text\r\n)","CREATE TABLE public.suppliers (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  name text NOT NULL,\r\n  phone text,\r\n  email text,\r\n  address text,\r\n  balance numeric(14,2) DEFAULT 0 NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  is_system boolean DEFAULT false NOT NULL,\r\n  system_key text\r\n)","CREATE TABLE public.customer_ledger (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  customer_id uuid NOT NULL,\r\n  entry_type text NOT NULL,\r\n  debit numeric(14,2) DEFAULT 0 NOT NULL,\r\n  credit numeric(14,2) DEFAULT 0 NOT NULL,\r\n  reference_id uuid,\r\n  reference_type text,\r\n  occurred_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  created_by uuid,\r\n  note text,\r\n  source_key text\r\n)","CREATE TABLE public.loyalty_transactions (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  customer_id uuid NOT NULL,\r\n  points numeric NOT NULL,\r\n  kind text NOT NULL,\r\n  reference_type text,\r\n  reference_id uuid,\r\n  note text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","-- ── CONSTRAINTS ───────────────────────────────────────────────────────────\r\nALTER TABLE public.customers ADD CONSTRAINT \\"customers_credit_limit_nonnegative\\" CHECK ((credit_limit >= (0)::numeric))","ALTER TABLE public.customers ADD CONSTRAINT \\"customers_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.suppliers ADD CONSTRAINT \\"suppliers_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.customer_ledger ADD CONSTRAINT \\"customer_ledger_check\\" CHECK ((NOT ((debit > (0)::numeric) AND (credit > (0)::numeric))))","ALTER TABLE public.customer_ledger ADD CONSTRAINT \\"customer_ledger_check1\\" CHECK (((debit + credit) > (0)::numeric))","ALTER TABLE public.customer_ledger ADD CONSTRAINT \\"customer_ledger_credit_check\\" CHECK ((credit >= (0)::numeric))","ALTER TABLE public.customer_ledger ADD CONSTRAINT \\"customer_ledger_debit_check\\" CHECK ((debit >= (0)::numeric))","ALTER TABLE public.customer_ledger ADD CONSTRAINT \\"customer_ledger_entry_type_check\\" CHECK ((entry_type = ANY (ARRAY['sale'::text, 'payment'::text, 'return'::text, 'adjustment'::text, 'credit'::text])))","ALTER TABLE public.customer_ledger ADD CONSTRAINT \\"customer_ledger_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.customer_ledger ADD CONSTRAINT \\"customer_ledger_source_key_key\\" UNIQUE (source_key)","ALTER TABLE public.loyalty_transactions ADD CONSTRAINT \\"loyalty_transactions_kind_check\\" CHECK ((kind = ANY (ARRAY['earn'::text, 'redeem'::text, 'adjust'::text])))","ALTER TABLE public.loyalty_transactions ADD CONSTRAINT \\"loyalty_transactions_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.customers ADD CONSTRAINT \\"customers_system_key_unique\\" UNIQUE (system_key)","ALTER TABLE public.suppliers ADD CONSTRAINT \\"suppliers_system_key_unique\\" UNIQUE (system_key)","-- العلامة والمفتاح وجهان لحالة واحدة، فلا صف نظامي بلا مفتاح ولا مفتاح بلا علامة.\r\nALTER TABLE public.customers ADD CONSTRAINT \\"customers_system_flag_shape\\" CHECK (is_system = (system_key IS NOT NULL))","ALTER TABLE public.suppliers ADD CONSTRAINT \\"suppliers_system_flag_shape\\" CHECK (is_system = (system_key IS NOT NULL))","COMMENT ON COLUMN public.customers.is_system IS\r\n  'P1-6: كيان نظامي (العميل النقدي) — اسمه وحالته وحذفه محمية في القاعدة، ومخفي من دليل العملاء.'","COMMENT ON COLUMN public.suppliers.is_system IS\r\n  'P1-6: كيان نظامي (المورد النقدي) — اسمه وحالته وحذفه محمية في القاعدة، ومخفي من دليل الموردين.'","-- ── FUNCTIONS ────────────────────────────────────────────────────────────\r\n-- P1-6 — حراس الكيانات النظامية. العلامة is_system لا تُكتب من الواجهة: أي\r\n-- تعديل يمحوها (حتى من service_role) يُرفض، فلا مخرج للحماية عبر API.\r\nCREATE OR REPLACE FUNCTION public.is_system_customer(p_customer_id uuid)\r\nRETURNS boolean\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\n  SELECT coalesce((SELECT c.is_system FROM public.customers c WHERE c.id = p_customer_id), false);\r\n$function$","CREATE OR REPLACE FUNCTION public.is_system_supplier(p_supplier_id uuid)\r\nRETURNS boolean\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\n  SELECT coalesce((SELECT s.is_system FROM public.suppliers s WHERE s.id = p_supplier_id), false);\r\n$function$","CREATE OR REPLACE FUNCTION public.tg_customers_system_guard()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF TG_OP = 'DELETE' THEN\r\n    IF OLD.is_system THEN\r\n      RAISE EXCEPTION\r\n        'The system cash customer is a protected system entity and cannot be deleted'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    RETURN OLD;\r\n  END IF;\r\n\r\n  IF OLD.is_system THEN\r\n    IF NEW.is_system IS DISTINCT FROM true OR NEW.system_key IS DISTINCT FROM OLD.system_key THEN\r\n      RAISE EXCEPTION\r\n        'The system cash customer flag cannot be cleared or re-keyed'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.name IS DISTINCT FROM OLD.name THEN\r\n      RAISE EXCEPTION\r\n        'The system cash customer cannot be renamed'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.is_active IS DISTINCT FROM true THEN\r\n      RAISE EXCEPTION\r\n        'The system cash customer cannot be deactivated'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF coalesce(NEW.balance, 0) <> 0 THEN\r\n      RAISE EXCEPTION\r\n        'The system cash customer must keep a zero balance (got %)', NEW.balance\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  ELSE\r\n    IF NEW.is_system THEN\r\n      RAISE EXCEPTION\r\n        'System entities are provisioned by the seed, not created through the API'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.name IN ('عميل نقدي') THEN\r\n      RAISE EXCEPTION\r\n        'That name is reserved for the system cash customer'\r\n        USING ERRCODE = 'unique_violation';\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.tg_suppliers_system_guard()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF TG_OP = 'DELETE' THEN\r\n    IF OLD.is_system THEN\r\n      RAISE EXCEPTION\r\n        'The system cash supplier is a protected system entity and cannot be deleted'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    RETURN OLD;\r\n  END IF;\r\n\r\n  IF OLD.is_system THEN\r\n    IF NEW.is_system IS DISTINCT FROM true OR NEW.system_key IS DISTINCT FROM OLD.system_key THEN\r\n      RAISE EXCEPTION\r\n        'The system cash supplier flag cannot be cleared or re-keyed'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.name IS DISTINCT FROM OLD.name THEN\r\n      RAISE EXCEPTION\r\n        'The system cash supplier cannot be renamed'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.is_active IS DISTINCT FROM true THEN\r\n      RAISE EXCEPTION\r\n        'The system cash supplier cannot be deactivated'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF coalesce(NEW.balance, 0) <> 0 THEN\r\n      RAISE EXCEPTION\r\n        'The system cash supplier must keep a zero balance (got %)', NEW.balance\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  ELSE\r\n    IF NEW.is_system THEN\r\n      RAISE EXCEPTION\r\n        'System entities are provisioned by the seed, not created through the API'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.name IN ('مورد نقدي') THEN\r\n      RAISE EXCEPTION\r\n        'That name is reserved for the system cash supplier'\r\n        USING ERRCODE = 'unique_violation';\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND $function$","-- حراس النظاميين على قيود الذمة: لا بيع آجل ولا شراء آجل ولا مرتجع يترك\r\n-- رصيداً على الكيان النقدي. سطر التسوية (صفر الصافي) مسموح.\r\nCREATE OR REPLACE FUNCTION public.tg_customer_ledger_system_guard()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF coalesce(NEW.debit, 0) - coalesce(NEW.credit, 0) <> 0 AND public.is_system_customer(NEW.customer_id) THEN\r\n    RAISE EXCEPTION\r\n      'The system cash customer can only carry settlement lines, never a credit balance'\r\n      USING ERRCODE = 'restrict_violation';\r\n  END IF;\r\n  RETURN NEW;\r\nEND $function$","-- ── TRIGGERS ─────────────────────────────────────────────────────────────\r\nCREATE TRIGGER tg_customers_system_guard\r\n  BEFORE UPDATE OR DELETE ON public.customers\r\n  FOR EACH ROW EXECUTE FUNCTION public.tg_customers_system_guard()","CREATE TRIGGER tg_suppliers_system_guard\r\n  BEFORE UPDATE OR DELETE ON public.suppliers\r\n  FOR EACH ROW EXECUTE FUNCTION public.tg_suppliers_system_guard()","CREATE TRIGGER tg_customer_ledger_system_guard\r\n  BEFORE INSERT ON public.customer_ledger\r\n  FOR EACH ROW EXECUTE FUNCTION public.tg_customer_ledger_system_guard()","-- ── INDEXES ───────────────────────────────────────────────────────────────\r\nCREATE INDEX customer_ledger_customer_date_idx ON public.customer_ledger USING btree (customer_id, occurred_at, id)","CREATE INDEX idx_loyalty_customer ON public.loyalty_transactions USING btree (customer_id, created_at DESC)","-- فهرس جزئي: قائمة العملاء/الموردين العادية تفلتر is_system=false في كل استعلام.\r\nCREATE INDEX idx_customers_is_system ON public.customers USING btree (is_system) WHERE is_system","CREATE INDEX idx_suppliers_is_system ON public.suppliers USING btree (is_system) WHERE is_system","-- ── SEQUENCES ─────────────────────────────────────────────────────────────\r\nCREATE SEQUENCE IF NOT EXISTS public.stock_adjustment_seq START 1","CREATE SEQUENCE IF NOT EXISTS public.stock_opening_seq START 1","CREATE SEQUENCE IF NOT EXISTS public.stock_transfer_seq START 1"}	partners_customers_suppliers
05	{"-- ============================================================================\r\n-- 06_products_and_inventory.sql\r\n--\r\n-- الأطراف: العملاء، الموردون، دفتر العملاء، نقاط الولاء.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── TABLES ────────────────────────────────────────────────────────────────\r\nCREATE TABLE public.products (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  sku text,\r\n  barcode text,\r\n  name text,\r\n  name_ar text NOT NULL,\r\n  description text,\r\n  image_url text,\r\n  category_id uuid,\r\n  brand_id uuid,\r\n  unit_id uuid,\r\n  cost_price numeric(14,2) DEFAULT 0 NOT NULL,\r\n  sale_price numeric(14,2) DEFAULT 0 NOT NULL,\r\n  tax_rate numeric(6,3) DEFAULT 0 NOT NULL,\r\n  min_stock numeric(14,3) DEFAULT 0 NOT NULL,\r\n  track_expiry boolean DEFAULT false NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  shelf_location text,\r\n  is_service boolean DEFAULT false NOT NULL,\r\n  origin_id uuid,\r\n  quality_grade_id uuid,\r\n  item_nature public.item_nature DEFAULT 'GOOD'::item_nature NOT NULL,\r\n  inventory_policy public.inventory_policy DEFAULT 'TRACKED'::inventory_policy NOT NULL,\r\n  tracking public.item_tracking DEFAULT 'NONE'::item_tracking NOT NULL,\r\n  costing_method public.costing_method DEFAULT 'MOVING_AVERAGE'::costing_method NOT NULL,\r\n  is_sellable boolean DEFAULT true NOT NULL,\r\n  is_purchasable boolean DEFAULT true NOT NULL,\r\n  status public.item_status DEFAULT 'ACTIVE'::item_status NOT NULL,\r\n  base_uom_id uuid,\r\n  sales_uom_id uuid,\r\n  purchase_uom_id uuid,\r\n  uom_conversions jsonb DEFAULT '[]'::jsonb NOT NULL,\r\n  item_class public.item_class,\r\n  standard_cost numeric(18,4),\r\n  package_type_id uuid,\r\n  package_weight_kg numeric(10,3)\r\n)","CREATE TABLE public.product_compatibilities (\r\n  product_id uuid NOT NULL,\r\n  vehicle_model_id uuid NOT NULL\r\n)","CREATE TABLE public.company_items (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  company_id integer DEFAULT 1 NOT NULL,\r\n  item_id uuid NOT NULL,\r\n  inventory_policy public.inventory_policy,\r\n  costing_method public.costing_method,\r\n  default_cost numeric(14,2),\r\n  default_sale_price numeric(14,2),\r\n  tax_rate numeric(6,3),\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.item_policy_review_queue (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  reason text NOT NULL,\r\n  detail jsonb DEFAULT '{}'::jsonb NOT NULL,\r\n  resolved_at timestamp with time zone,\r\n  resolved_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.costing_policy_history (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  costing_method public.costing_method NOT NULL,\r\n  previous_method public.costing_method,\r\n  reason text,\r\n  changed_by uuid,\r\n  changed_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.inventory (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  warehouse_id uuid NOT NULL,\r\n  quantity numeric(14,3) DEFAULT 0 NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  owner_type public.owner_type DEFAULT 'COMPANY'::owner_type NOT NULL,\r\n  owner_id uuid\r\n)","CREATE TABLE public.stock_movements (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  warehouse_id uuid NOT NULL,\r\n  movement_type public.movement_type NOT NULL,\r\n  quantity numeric(14,3) NOT NULL,\r\n  unit_cost numeric(14,2),\r\n  reference text,\r\n  note text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  reference_type text,\r\n  reference_id uuid,\r\n  adjustment_reason text,\r\n  movement_kind public.stock_movement_kind,\r\n  source_type text,\r\n  source_id uuid,\r\n  total_cost numeric(14,2),\r\n  owner_type public.owner_type DEFAULT 'COMPANY'::owner_type NOT NULL,\r\n  owner_id uuid\r\n)","CREATE TABLE public.item_cost_layers (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  warehouse_id uuid NOT NULL,\r\n  owner_type public.owner_type DEFAULT 'COMPANY'::owner_type NOT NULL,\r\n  owner_id uuid,\r\n  quantity numeric(18,3) DEFAULT 0 NOT NULL,\r\n  total_value numeric(18,2) DEFAULT 0 NOT NULL,\r\n  valuation_method public.costing_method DEFAULT 'MOVING_AVERAGE'::costing_method NOT NULL,\r\n  last_unit_cost numeric(18,4) DEFAULT 0 NOT NULL,\r\n  last_movement_at timestamp with time zone,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.item_cost_transactions (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  warehouse_id uuid NOT NULL,\r\n  owner_type public.owner_type DEFAULT 'COMPANY'::owner_type NOT NULL,\r\n  owner_id uuid,\r\n  direction text NOT NULL,\r\n  quantity numeric(18,3) NOT NULL,\r\n  unit_cost numeric(18,4) NOT NULL,\r\n  value numeric(18,2) NOT NULL,\r\n  method public.costing_method NOT NULL,\r\n  quantity_before numeric(18,3) NOT NULL,\r\n  value_before numeric(18,2) NOT NULL,\r\n  quantity_after numeric(18,3) NOT NULL,\r\n  value_after numeric(18,2) NOT NULL,\r\n  source_type text,\r\n  source_id uuid,\r\n  note text,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.product_batches (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  warehouse_id uuid NOT NULL,\r\n  batch_number text NOT NULL,\r\n  expiry_date date,\r\n  quantity numeric DEFAULT 0 NOT NULL,\r\n  unit_cost numeric DEFAULT 0 NOT NULL,\r\n  note text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.stock_transfers (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  transfer_number text NOT NULL,\r\n  from_warehouse_id uuid NOT NULL,\r\n  to_warehouse_id uuid NOT NULL,\r\n  status text DEFAULT 'completed'::text NOT NULL,\r\n  note text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.stock_transfer_items (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  transfer_id uuid NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  quantity numeric NOT NULL\r\n)","CREATE TABLE public.stock_openings (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  document_number text NOT NULL,\r\n  warehouse_id uuid NOT NULL,\r\n  effective_date date DEFAULT CURRENT_DATE NOT NULL,\r\n  note text,\r\n  total_value numeric(14,2) DEFAULT 0 NOT NULL,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.stock_opening_items (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  opening_id uuid NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  quantity numeric(14,3) NOT NULL,\r\n  unit_cost numeric(14,2) DEFAULT 0 NOT NULL,\r\n  total_cost numeric(14,2) DEFAULT 0 NOT NULL,\r\n  note text\r\n)","CREATE TABLE public.stock_adjustments (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  document_number text NOT NULL,\r\n  warehouse_id uuid NOT NULL,\r\n  effective_date date DEFAULT CURRENT_DATE NOT NULL,\r\n  reason text NOT NULL,\r\n  note text,\r\n  total_value numeric(14,2) DEFAULT 0 NOT NULL,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.stock_adjustment_items (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  adjustment_id uuid NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  quantity numeric(14,3) NOT NULL,\r\n  unit_cost numeric(14,2) DEFAULT 0 NOT NULL,\r\n  total_cost numeric(14,2) DEFAULT 0 NOT NULL,\r\n  note text\r\n)","-- ── CONSTRAINTS ───────────────────────────────────────────────────────────\r\nALTER TABLE public.products ADD CONSTRAINT \\"products_none_costing_requires_untracked\\" CHECK (((costing_method <> 'NONE'::costing_method) OR (inventory_policy = 'UNTRACKED'::inventory_policy)))","ALTER TABLE public.products ADD CONSTRAINT \\"products_service_cannot_be_tracked\\" CHECK (((item_nature <> 'SERVICE'::item_nature) OR (inventory_policy = 'UNTRACKED'::inventory_policy)))","ALTER TABLE public.products ADD CONSTRAINT \\"products_untracked_has_no_tracking\\" CHECK (((inventory_policy <> 'UNTRACKED'::inventory_policy) OR (tracking = 'NONE'::item_tracking)))","ALTER TABLE public.products ADD CONSTRAINT \\"products_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.products ADD CONSTRAINT \\"products_barcode_key\\" UNIQUE (barcode)","ALTER TABLE public.products ADD CONSTRAINT \\"products_sku_key\\" UNIQUE (sku)","ALTER TABLE public.product_compatibilities ADD CONSTRAINT \\"product_compatibilities_pkey\\" PRIMARY KEY (product_id, vehicle_model_id)","ALTER TABLE public.company_items ADD CONSTRAINT \\"company_items_cost_nonnegative\\" CHECK (((default_cost IS NULL) OR (default_cost >= (0)::numeric)))","ALTER TABLE public.company_items ADD CONSTRAINT \\"company_items_price_nonnegative\\" CHECK (((default_sale_price IS NULL) OR (default_sale_price >= (0)::numeric)))","ALTER TABLE public.company_items ADD CONSTRAINT \\"company_items_tax_valid\\" CHECK (((tax_rate IS NULL) OR ((tax_rate >= (0)::numeric) AND (tax_rate <= (100)::numeric))))","ALTER TABLE public.company_items ADD CONSTRAINT \\"company_items_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.company_items ADD CONSTRAINT \\"company_items_unique\\" UNIQUE (company_id, item_id)","ALTER TABLE public.item_policy_review_queue ADD CONSTRAINT \\"item_policy_review_queue_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.item_policy_review_queue ADD CONSTRAINT \\"item_policy_review_queue_unique\\" UNIQUE (product_id, reason)","ALTER TABLE public.costing_policy_history ADD CONSTRAINT \\"costing_policy_history_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.inventory ADD CONSTRAINT \\"inventory_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.inventory ADD CONSTRAINT \\"inventory_product_id_warehouse_id_key\\" UNIQUE (product_id, warehouse_id)","ALTER TABLE public.stock_movements ADD CONSTRAINT \\"stock_movements_adjustment_reason_required\\" CHECK (((movement_type <> 'adjustment'::movement_type) OR ((adjustment_reason IS NOT NULL) AND (btrim(adjustment_reason) <> ''::text)))) NOT VALID","ALTER TABLE public.stock_movements ADD CONSTRAINT \\"stock_movements_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.item_cost_layers ADD CONSTRAINT \\"item_cost_layers_qty_check\\" CHECK ((quantity >= (0)::numeric))","ALTER TABLE public.item_cost_layers ADD CONSTRAINT \\"item_cost_layers_value_check\\" CHECK ((total_value >= (0)::numeric))","ALTER TABLE public.item_cost_layers ADD CONSTRAINT \\"item_cost_layers_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.item_cost_transactions ADD CONSTRAINT \\"item_cost_transactions_direction_check\\" CHECK ((direction = ANY (ARRAY['IN'::text, 'OUT'::text, 'REVALUE'::text])))","ALTER TABLE public.item_cost_transactions ADD CONSTRAINT \\"item_cost_transactions_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.product_batches ADD CONSTRAINT \\"product_batches_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.product_batches ADD CONSTRAINT \\"product_batches_product_id_warehouse_id_batch_number_key\\" UNIQUE (product_id, warehouse_id, batch_number)","ALTER TABLE public.stock_transfers ADD CONSTRAINT \\"stock_transfers_check\\" CHECK ((from_warehouse_id <> to_warehouse_id))","ALTER TABLE public.stock_transfers ADD CONSTRAINT \\"stock_transfers_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.stock_transfers ADD CONSTRAINT \\"stock_transfers_transfer_number_key\\" UNIQUE (transfer_number)","ALTER TABLE public.stock_transfer_items ADD CONSTRAINT \\"stock_transfer_items_quantity_check\\" CHECK ((quantity > (0)::numeric))","ALTER TABLE public.stock_transfer_items ADD CONSTRAINT \\"stock_transfer_items_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.stock_openings ADD CONSTRAINT \\"stock_openings_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.stock_openings ADD CONSTRAINT \\"stock_openings_document_number_key\\" UNIQUE (document_number)","ALTER TABLE public.stock_opening_items ADD CONSTRAINT \\"stock_opening_items_quantity_check\\" CHECK ((quantity > (0)::numeric))","ALTER TABLE public.stock_opening_items ADD CONSTRAINT \\"stock_opening_items_unit_cost_check\\" CHECK ((unit_cost >= (0)::numeric))","ALTER TABLE public.stock_opening_items ADD CONSTRAINT \\"stock_opening_items_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.stock_adjustments ADD CONSTRAINT \\"stock_adjustments_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.stock_adjustments ADD CONSTRAINT \\"stock_adjustments_document_number_key\\" UNIQUE (document_number)","ALTER TABLE public.stock_adjustment_items ADD CONSTRAINT \\"stock_adjustment_items_quantity_check\\" CHECK ((quantity <> (0)::numeric))","ALTER TABLE public.stock_adjustment_items ADD CONSTRAINT \\"stock_adjustment_items_unit_cost_check\\" CHECK ((unit_cost >= (0)::numeric))","ALTER TABLE public.stock_adjustment_items ADD CONSTRAINT \\"stock_adjustment_items_pkey\\" PRIMARY KEY (id)","-- ── INDEXES ───────────────────────────────────────────────────────────────\r\nCREATE INDEX idx_products_inventory_policy ON public.products USING btree (inventory_policy)","CREATE INDEX idx_products_item_nature ON public.products USING btree (item_nature)","CREATE INDEX idx_products_status ON public.products USING btree (status)","CREATE INDEX products_name_idx ON public.products USING gin (to_tsvector('simple'::regconfig, ((((((COALESCE(name, ''::text) || ' '::text) || COALESCE(name_ar, ''::text)) || ' '::text) || COALESCE(sku, ''::text)) || ' '::text) || COALESCE(barcode, ''::text))))","CREATE INDEX idx_company_items_company ON public.company_items USING btree (company_id)","CREATE INDEX idx_company_items_item ON public.company_items USING btree (item_id)","CREATE INDEX idx_inventory_owner ON public.inventory USING btree (owner_type, owner_id) WHERE (owner_id IS NOT NULL)","CREATE INDEX idx_inventory_product ON public.inventory USING btree (product_id)","CREATE INDEX idx_inventory_warehouse ON public.inventory USING btree (warehouse_id)","CREATE UNIQUE INDEX inventory_product_warehouse_owner_key ON public.inventory USING btree (product_id, warehouse_id, owner_type, owner_id) NULLS NOT DISTINCT","CREATE INDEX idx_stock_movements_kind ON public.stock_movements USING btree (movement_kind)","CREATE INDEX idx_stock_movements_owner ON public.stock_movements USING btree (owner_type, owner_id) WHERE (owner_id IS NOT NULL)","CREATE INDEX idx_stock_movements_product ON public.stock_movements USING btree (product_id)","CREATE INDEX idx_stock_movements_reference ON public.stock_movements USING btree (reference_type, reference_id)","CREATE INDEX idx_stock_movements_source ON public.stock_movements USING btree (source_type, source_id)","CREATE INDEX idx_stock_movements_warehouse ON public.stock_movements USING btree (warehouse_id)","CREATE UNIQUE INDEX ux_item_cost_layers_position ON public.item_cost_layers USING btree (product_id, warehouse_id, owner_type, owner_id) NULLS NOT DISTINCT","CREATE INDEX ix_item_cost_tx_product ON public.item_cost_transactions USING btree (product_id, created_at DESC)","CREATE INDEX idx_batches_expiry ON public.product_batches USING btree (expiry_date) WHERE (expiry_date IS NOT NULL)","CREATE INDEX idx_batches_product ON public.product_batches USING btree (product_id)","CREATE INDEX idx_stock_transfer_items_product ON public.stock_transfer_items USING btree (product_id)","CREATE INDEX idx_stock_opening_items_opening ON public.stock_opening_items USING btree (opening_id)","CREATE INDEX idx_stock_opening_items_product ON public.stock_opening_items USING btree (product_id)","CREATE INDEX idx_stock_adjustment_items_adj ON public.stock_adjustment_items USING btree (adjustment_id)","CREATE INDEX idx_stock_adjustment_items_product ON public.stock_adjustment_items USING btree (product_id)","-- ── FUNCTIONS ─────────────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.adjust_loyalty(_customer uuid, _points numeric, _kind text, _note text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE v_id UUID; v_user UUID := auth.uid();\r\nBEGIN\r\n  IF v_user IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;\r\n  IF NOT public.is_staff(v_user) THEN RAISE EXCEPTION 'Forbidden'; END IF;\r\n  IF _kind NOT IN ('earn','redeem','adjust') THEN RAISE EXCEPTION 'Invalid kind'; END IF;\r\n\r\n  INSERT INTO public.loyalty_transactions(customer_id, points, kind, note, created_by)\r\n  VALUES (_customer, _points, _kind, _note, v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  UPDATE public.customers\r\n    SET loyalty_points = GREATEST(loyalty_points + (CASE WHEN _kind='redeem' THEN -ABS(_points) ELSE ABS(_points) END), 0),\r\n        updated_at = now()\r\n    WHERE id = _customer;\r\n\r\n  RETURN v_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.apply_cost_movement(p_product_id uuid, p_warehouse_id uuid, p_signed_qty numeric, p_incoming_cost numeric DEFAULT NULL::numeric, p_source_type text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_owner_type owner_type DEFAULT 'COMPANY'::owner_type, p_owner_id uuid DEFAULT NULL::uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user     uuid := auth.uid();\r\n  v_method   public.costing_method := public.company_costing_method();\r\n  v_qty0     numeric := 0;\r\n  v_val0     numeric := 0;\r\n  v_in_cost  numeric;\r\n  v_out_cost numeric;\r\n  v_qty1     numeric;\r\n  v_val1     numeric;\r\n  v_standard numeric;\r\n  v_pending  integer;\r\nBEGIN\r\n  IF p_signed_qty IS NULL OR p_signed_qty = 0 THEN\r\n    RETURN;  -- nothing to value; not an error\r\n  END IF;\r\n  IF p_product_id IS NULL OR p_warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Item and location are required to value a movement';\r\n  END IF;\r\n\r\n  SELECT cl.quantity, cl.total_value\r\n    INTO v_qty0, v_val0\r\n    FROM public.item_cost_layers cl\r\n   WHERE cl.product_id   = p_product_id\r\n     AND cl.warehouse_id = p_warehouse_id\r\n     AND cl.owner_type   = p_owner_type\r\n     AND cl.owner_id IS NOT DISTINCT FROM p_owner_id\r\n   FOR UPDATE;\r\n\r\n  v_qty0 := coalesce(v_qty0, 0);\r\n  v_val0 := coalesce(v_val0, 0);\r\n  v_qty1 := round(v_qty0 + p_signed_qty, 3);\r\n\r\n  IF p_signed_qty > 0 THEN\r\n    IF v_method = 'STANDARD' THEN\r\n      SELECT p.standard_cost INTO v_standard\r\n        FROM public.products p WHERE p.id = p_product_id;\r\n\r\n      IF v_standard IS NULL OR v_standard = 0 THEN\r\n        -- Name how many items are blocking, so the operator is not left with\r\n        -- one error per receipt and no idea of the size of the job.\r\n        SELECT count(*)::int INTO v_pending\r\n          FROM public.standard_cost_readiness;\r\n        RAISE EXCEPTION\r\n          'Standard cost is not set for this item (%). % more tracked item(s) also lack one - see standard_cost_readiness.',\r\n          p_product_id, v_pending;\r\n      END IF;\r\n\r\n      v_in_cost := v_standard;\r\n    ELSE\r\n      v_in_cost := coalesce(\r\n        p_incoming_cost,\r\n        CASE WHEN v_qty0 > 0 THEN round(v_val0 / v_qty0, 4) END,\r\n        (SELECT p.cost_price FROM public.products p WHERE p.id = p_product_id),\r\n        0\r\n      );\r\n    END IF;\r\n\r\n    v_val1 := v_val0 + round(p_signed_qty * v_in_cost, 2);\r\n\r\n  ELSE\r\n    IF v_qty0 <= 0 THEN\r\n      v_out_cost := coalesce(\r\n        (SELECT p.standard_cost FROM public.products p\r\n          WHERE p.id = p_product_id AND v_method = 'STANDARD'),\r\n        (SELECT p.cost_price FROM public.products p WHERE p.id = p_product_id),\r\n        0\r\n      );\r\n    ELSE\r\n      v_out_cost := round(v_val0 / v_qty0, 4);\r\n    END IF;\r\n\r\n    v_val1 := v_val0 - round(abs(p_signed_qty) * v_out_cost, 2);\r\n    IF v_qty1 <= 0 OR v_val1 < 0 THEN\r\n      v_val1 := 0;\r\n    END IF;\r\n  END IF;\r\n\r\n  INSERT INTO public.item_cost_layers\r\n    (product_id, warehouse_id, owner_type, owner_id, quantity, total_value,\r\n     valuation_method, last_unit_cost, last_movement_at, updated_at)\r\n  VALUES\r\n    (p_product_id, p_warehouse_id, p_owner_type, p_owner_id, v_qty1, v_val1,\r\n     v_method,\r\n     coalesce(p_incoming_cost, v_in_cost, v_out_cost, 0),\r\n     now(), now())\r\n  ON CONFLICT (product_id, warehouse_id, owner_type, owner_id)\r\n  DO UPDATE SET quantity         = EXCLUDED.quantity,\r\n                total_value      = EXCLUDED.total_value,\r\n                valuation_method = EXCLUDED.valuation_method,\r\n                last_unit_cost   = EXCLUDED.last_unit_cost,\r\n                last_movement_at = now(),\r\n                updated_at       = now();\r\n\r\n  -- The ledger records what was ACTUALLY paid, never the valuation it was\r\n  -- given. Under STANDARD the two differ, and that gap IS the variance the\r\n  -- method exists to expose.\r\n  INSERT INTO public.item_cost_transactions\r\n    (product_id, warehouse_id, owner_type, owner_id, direction, quantity,\r\n     unit_cost, value, method, quantity_before, value_before,\r\n     quantity_after, value_after, source_type, source_id, note)\r\n  VALUES\r\n    (p_product_id, p_warehouse_id, p_owner_type, p_owner_id,\r\n     CASE WHEN p_signed_qty > 0 THEN 'IN' ELSE 'OUT' END,\r\n     abs(p_signed_qty),\r\n     coalesce(p_incoming_cost, 0),\r\n     round(abs(p_signed_qty) * coalesce(p_incoming_cost, 0), 2),\r\n     v_method, v_qty0, v_val0, v_qty1, v_val1,\r\n     p_source_type, p_source_id, p_note);\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'cost.movement_applied', 'product', p_product_id,\r\n    jsonb_build_object(\r\n      'warehouse_id', p_warehouse_id, 'method', v_method,\r\n      'direction', CASE WHEN p_signed_qty > 0 THEN 'IN' ELSE 'OUT' END,\r\n      'quantity', abs(p_signed_qty),\r\n      'actual_cost', coalesce(p_incoming_cost, 0),\r\n      'valuation_cost', coalesce(v_in_cost, v_out_cost, 0),\r\n      'quantity_after', v_qty1, 'value_after', v_val1,\r\n      'source_type', p_source_type, 'source_id', p_source_id));\r\nEND $function$","CREATE OR REPLACE FUNCTION public.approve_item_policy_change(_item_id uuid, _new_nature item_nature, _new_policy inventory_policy, _new_costing costing_method, _new_tracking item_tracking, _reason text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_before  jsonb;\r\n  v_after   jsonb;\r\n  v_product public.products%ROWTYPE;\r\n  v_balance numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN\r\n    RAISE EXCEPTION 'Only an owner or manager may approve an item policy change';\r\n  END IF;\r\n\r\n  IF coalesce(btrim(_reason), '') = '' THEN\r\n    RAISE EXCEPTION 'A written reason is required for every policy change';\r\n  END IF;\r\n\r\n  SELECT * INTO v_product FROM public.products WHERE id = _item_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Item % does not exist', _item_id;\r\n  END IF;\r\n\r\n  -- ------------------------------------------------------------------ rules\r\n  -- Rule 2: a SERVICE is not a way to switch stock off, and it can never hold\r\n  -- a stock balance. Allowing SERVICE + TRACKED would resurrect the exact\r\n  -- workaround this project is removing.\r\n  IF _new_nature = 'SERVICE' AND _new_policy <> 'UNTRACKED' THEN\r\n    RAISE EXCEPTION 'A SERVICE can only be UNTRACKED';\r\n  END IF;\r\n\r\n  IF _new_policy = 'UNTRACKED' AND _new_tracking <> 'NONE' THEN\r\n    RAISE EXCEPTION 'An UNTRACKED item cannot require batch or serial tracking';\r\n  END IF;\r\n\r\n  IF _new_costing = 'NONE' AND _new_policy <> 'UNTRACKED' THEN\r\n    RAISE EXCEPTION 'Costing method NONE is only valid for an UNTRACKED item';\r\n  END IF;\r\n\r\n  -- Moving a good OUT of tracking while it still holds stock would orphan that\r\n  -- stock. The operator must clear the balance first (sell it, adjust it to\r\n  -- zero, or move it to a customer-owned position) so the numbers stay honest.\r\n  SELECT coalesce(sum(i.quantity), 0)\r\n    INTO v_balance\r\n  FROM public.inventory i\r\n  WHERE i.product_id = _item_id\r\n    AND i.owner_type = 'COMPANY'\r\n    AND i.owner_id IS NULL;\r\n\r\n  IF _new_policy <> 'TRACKED'\r\n     AND v_product.inventory_policy = 'TRACKED'\r\n     AND v_balance <> 0 THEN\r\n    RAISE EXCEPTION\r\n      'Item % still holds % units. Clear the balance with an adjustment before leaving TRACKED.',\r\n      _item_id, v_balance;\r\n  END IF;\r\n\r\n  -- A tracked item needs a costing method that can actually value it.\r\n  IF _new_policy = 'TRACKED' AND _new_costing = 'NONE' THEN\r\n    RAISE EXCEPTION 'A TRACKED item requires a costing method other than NONE';\r\n  END IF;\r\n\r\n  v_before := jsonb_build_object(\r\n    'item_nature', v_product.item_nature,\r\n    'inventory_policy', v_product.inventory_policy,\r\n    'costing_method', v_product.costing_method,\r\n    'tracking', v_product.tracking\r\n  );\r\n  v_after := jsonb_build_object(\r\n    'item_nature', _new_nature,\r\n    'inventory_policy', _new_policy,\r\n    'costing_method', _new_costing,\r\n    'tracking', _new_tracking\r\n  );\r\n\r\n  -- Open the guard for this transaction only. set_config(..., true) is\r\n  -- transaction-scoped, so the exemption cannot leak to another statement.\r\n  PERFORM set_config('app.allow_policy_change', 'on', true);\r\n\r\n  UPDATE public.products\r\n  SET item_nature      = _new_nature,\r\n      inventory_policy = _new_policy,\r\n      costing_method   = _new_costing,\r\n      tracking         = _new_tracking,\r\n      updated_at       = now()\r\n  WHERE id = _item_id;\r\n\r\n  -- ⚠️ كان الوسيط الخامس هو نص السبب (btrim(_reason)) بينما توقيع الدالة\r\n  --    p_source text — أي أن \\"المصدر\\" يُكتب داخل payload.source_document\r\n  --    ويضيع السبب. أُصلح ليمرّر السبب في مكانه الصحيح، والمصدر ثابت.\r\n  RETURN public.audit_item_policy_snapshot(\r\n    _item_id,\r\n    'item_policy.changed',\r\n    v_before,\r\n    v_after,\r\n    'approval:' || btrim(_reason)\r\n  );\r\nEND $function$","CREATE OR REPLACE FUNCTION public.audit_item_policy_snapshot(p_item_id uuid, p_action text, p_before jsonb, p_after jsonb, p_source text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id uuid;\r\nBEGIN\r\n  -- ⚠️ audit_logs.action و entity_type هما NOT NULL: تمرير NULL كان يرمي\r\n  --    23502 بدل تسجيل الحدث. نضع قيمًا افتراضية صريحة حتى لو نادت الدالة\r\n  --    دالة جديدة بنفس العقد بلا وسيط.\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (\r\n    auth.uid(),\r\n    coalesce(nullif(btrim(p_action), ''), 'item_policy.updated'),\r\n    'product_policy',\r\n    p_item_id,\r\n    jsonb_build_object(\r\n      'before', p_before,\r\n      'after', p_after,\r\n      'source_document', p_source,\r\n      'recorded_at', now()\r\n    )\r\n  )\r\n  RETURNING id INTO v_id;\r\n\r\n  RETURN v_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.company_costing_method()\r\n RETURNS costing_method\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT coalesce(\r\n    (SELECT costing_method FROM public.company_costing_settings WHERE id = 1),\r\n    'MOVING_AVERAGE'::public.costing_method\r\n  );\r\n$function$","CREATE OR REPLACE FUNCTION public.create_stock_transfer(_from uuid, _to uuid, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id     uuid;\r\n  v_no     text;\r\n  v_user   uuid := auth.uid();\r\n  v_item   jsonb;\r\n  v_p      uuid;\r\n  v_qty    numeric;\r\n  v_stock  numeric;\r\n  v_nature public.item_nature;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF _from = _to THEN\r\n    RAISE EXCEPTION 'Source and destination must differ';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_p   := (v_item ->> 'product_id')::uuid;\r\n    v_qty := (v_item ->> 'quantity')::numeric;\r\n\r\n    IF v_qty IS NULL OR v_qty <= 0 THEN\r\n      RAISE EXCEPTION 'Invalid transfer quantity';\r\n    END IF;\r\n\r\n    SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = v_p;\r\n    IF v_nature = 'SERVICE' THEN\r\n      RAISE EXCEPTION 'Item % is a SERVICE and cannot be transferred', v_p;\r\n    END IF;\r\n    IF public.item_effective_policy(v_p) <> 'TRACKED' THEN\r\n      RAISE EXCEPTION 'Item % is not a tracked item and cannot be transferred between warehouses', v_p;\r\n    END IF;\r\n\r\n    SELECT i.quantity INTO v_stock\r\n    FROM public.inventory i\r\n    WHERE i.product_id = v_p\r\n      AND i.warehouse_id = _from\r\n      AND i.owner_type = 'COMPANY'\r\n      AND i.owner_id IS NULL;\r\n\r\n    IF coalesce(v_stock, 0) < v_qty THEN\r\n      RAISE EXCEPTION 'Insufficient stock for item %', v_p;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  v_no := public.next_transfer_number();\r\n\r\n  INSERT INTO public.stock_transfers (transfer_number, from_warehouse_id, to_warehouse_id, note, created_by)\r\n  VALUES (v_no, _from, _to, nullif(btrim(_note), ''), v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_p   := (v_item ->> 'product_id')::uuid;\r\n    v_qty := (v_item ->> 'quantity')::numeric;\r\n\r\n    INSERT INTO public.stock_transfer_items (transfer_id, product_id, quantity)\r\n    VALUES (v_id, v_p, v_qty);\r\n\r\n    PERFORM public.post_stock_delta(\r\n      v_p, _from, -v_qty, NULL,\r\n      'TRANSFER_OUT'::public.stock_movement_kind, 'stock_transfer', v_id,\r\n      'Transfer out', 'COMPANY'::public.owner_type, NULL,\r\n      'transfer_out'::public.movement_type\r\n    );\r\n\r\n    PERFORM public.post_stock_delta(\r\n      v_p, _to, v_qty, NULL,\r\n      'TRANSFER_IN'::public.stock_movement_kind, 'stock_transfer', v_id,\r\n      'Transfer in', 'COMPANY'::public.owner_type, NULL,\r\n      'transfer_in'::public.movement_type\r\n    );\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'stock_transfer.posted', 'stock_transfer', v_id,\r\n    jsonb_build_object(\r\n      'transfer_number', v_no,\r\n      'from_warehouse_id', _from,\r\n      'to_warehouse_id', _to,\r\n      'line_count', jsonb_array_length(_items)\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.customer_credit_limit_allows(p_customer_id uuid, p_new_due numeric)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO ''\r\nAS $function$\r\n  SELECT EXISTS (\r\n    SELECT 1 FROM public.customers AS c\r\n    CROSS JOIN public.company_settings AS s\r\n    WHERE c.id = p_customer_id\r\n      AND (\r\n        NOT s.enforce_customer_credit_limit\r\n        OR coalesce(c.credit_limit, 0) = 0\r\n        OR coalesce(c.balance, 0) + greatest(coalesce(p_new_due, 0), 0) <= c.credit_limit\r\n      )\r\n  )\r\n$function$","CREATE OR REPLACE FUNCTION public.customer_ledger_balance(p_customer_id uuid)\r\n RETURNS numeric\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO ''\r\nAS $function$\r\n  SELECT round(coalesce(sum(l.debit - l.credit), 0), 2)\r\n  FROM public.customer_ledger AS l\r\n  WHERE l.customer_id = p_customer_id\r\n$function$","CREATE OR REPLACE FUNCTION public.item_effective_policy(p_item_id uuid)\r\n RETURNS inventory_policy\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT COALESCE(ci.inventory_policy, p.inventory_policy)\r\n  FROM public.products p\r\n  LEFT JOIN public.company_items ci\r\n    ON ci.item_id = p.id AND ci.company_id = 1 AND ci.is_active\r\n  WHERE p.id = p_item_id\r\n$function$","CREATE OR REPLACE FUNCTION public.item_has_stock_history(p_item_id uuid)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT EXISTS (SELECT 1 FROM public.stock_movements m WHERE m.product_id = p_item_id)\r\n      OR EXISTS (SELECT 1 FROM public.inventory i WHERE i.product_id = p_item_id AND i.quantity <> 0)\r\n$function$","CREATE OR REPLACE FUNCTION public.item_line_type(p_item_id uuid, p_is_ad_hoc boolean DEFAULT false)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_nature public.item_nature;\r\n  v_policy public.inventory_policy;\r\nBEGIN\r\n  IF p_is_ad_hoc THEN\r\n    RETURN 'AD_HOC_SERVICE';\r\n  END IF;\r\n  IF p_item_id IS NULL THEN\r\n    RETURN 'AD_HOC_SERVICE';\r\n  END IF;\r\n\r\n  SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = p_item_id;\r\n  IF v_nature IS NULL THEN\r\n    RETURN 'AD_HOC_SERVICE';\r\n  END IF;\r\n  IF v_nature = 'SERVICE' THEN\r\n    RETURN 'SERVICE';\r\n  END IF;\r\n\r\n  v_policy := public.item_effective_policy(p_item_id);\r\n  RETURN CASE v_policy\r\n    WHEN 'TRACKED'        THEN 'STOCKED_GOOD'\r\n    WHEN 'CUSTOMER_OWNED' THEN 'CUSTOMER_OWNED_GOOD'\r\n    ELSE 'UNTRACKED_GOOD'\r\n  END;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.item_stock_effect(p_item_id uuid, p_direction text)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_nature public.item_nature;\r\n  v_policy public.inventory_policy;\r\nBEGIN\r\n  SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = p_item_id;\r\n  IF v_nature IS NULL THEN\r\n    RETURN 'NONE';\r\n  END IF;\r\n\r\n  -- A SERVICE never moves company stock, in either direction.\r\n  IF v_nature = 'SERVICE' THEN\r\n    RETURN 'NONE';\r\n  END IF;\r\n\r\n  v_policy := public.item_effective_policy(p_item_id);\r\n\r\n  -- Rule 4 / Rule 5: only TRACKED goods move stock. UNTRACKED goods are sold\r\n  -- and purchased without any inventory effect; CUSTOMER_OWNED material is\r\n  -- never company stock, so a normal sale/purchase never touches it.\r\n  IF v_policy <> 'TRACKED' THEN\r\n    RETURN 'NONE';\r\n  END IF;\r\n\r\n  RETURN CASE WHEN p_direction = 'out' THEN 'STOCK_ISSUE' ELSE 'STOCK_RECEIPT' END;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.next_stock_adjustment_number()\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE n bigint;\r\nBEGIN\r\n  n := nextval('public.stock_adjustment_seq');\r\n  RETURN 'ADJ-' || to_char(now(), 'YYYYMM') || '-' || lpad(n::text, 4, '0');\r\nEND $function$","CREATE OR REPLACE FUNCTION public.next_stock_opening_number()\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE n bigint;\r\nBEGIN\r\n  n := nextval('public.stock_opening_seq');\r\n  RETURN 'OP-' || to_char(now(), 'YYYYMM') || '-' || lpad(n::text, 4, '0');\r\nEND $function$","-- NOTE: next_transfer_number() is defined ONCE, in 14_document_numbering_engine.sql.\r\n-- This file used to define its own copy reading stock_transfer_seq directly. The\r\n-- engine now owns that sequence and the display format, so a second definition\r\n-- here would be dead code whose body could silently drift from the engine's\r\n-- (R-13/R-14). The function name and signature are unchanged, so no caller breaks.\r\n\r\nCREATE OR REPLACE FUNCTION public.post_opening_stock(_warehouse_id uuid, _effective_date date, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user       uuid := auth.uid();\r\n  v_id         uuid;\r\n  v_number     text;\r\n  v_line       record;\r\n  v_policy     public.inventory_policy;\r\n  v_nature     public.item_nature;\r\n  v_total      numeric := 0;\r\n  v_line_total numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'warehouse')\r\n    OR public.has_role(v_user, 'accountant')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to post opening stock';\r\n  END IF;\r\n\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'Opening stock requires at least one item';\r\n  END IF;\r\n\r\n  -- Validate everything BEFORE writing the document header.\r\n  FOR v_line IN\r\n    SELECT (line ->> 'product_id')::uuid                 AS product_id,\r\n           (line ->> 'quantity')::numeric                AS quantity,\r\n           coalesce((line ->> 'unit_cost')::numeric, 0)  AS unit_cost,\r\n           nullif(btrim(coalesce(line ->> 'note', '')), '') AS note\r\n    FROM jsonb_array_elements(_items) AS line\r\n  LOOP\r\n    IF v_line.product_id IS NULL OR v_line.quantity IS NULL OR v_line.quantity <= 0 THEN\r\n      RAISE EXCEPTION 'Every opening line requires an item and a positive quantity';\r\n    END IF;\r\n    IF v_line.unit_cost < 0 THEN\r\n      RAISE EXCEPTION 'Unit cost cannot be negative';\r\n    END IF;\r\n\r\n    SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = v_line.product_id;\r\n    IF v_nature IS NULL THEN\r\n      RAISE EXCEPTION 'Item % does not exist', v_line.product_id;\r\n    END IF;\r\n\r\n    IF v_nature = 'SERVICE' THEN\r\n      -- Rule 2: a service never holds a balance. Do not let a workaround\r\n      -- re-enter through opening stock.\r\n      RAISE EXCEPTION 'Item % is a SERVICE and cannot hold an inventory balance', v_line.product_id;\r\n    END IF;\r\n\r\n    v_policy := public.item_effective_policy(v_line.product_id);\r\n    IF v_policy <> 'TRACKED' THEN\r\n      RAISE EXCEPTION\r\n        'Item % has inventory policy %, so it cannot receive an opening balance (only TRACKED items can)',\r\n        v_line.product_id, v_policy;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  v_number := public.next_stock_opening_number();\r\n\r\n  INSERT INTO public.stock_openings (document_number, warehouse_id, effective_date, note, created_by)\r\n  VALUES (v_number, _warehouse_id, coalesce(_effective_date, current_date),\r\n          nullif(btrim(coalesce(_note, '')), ''), v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR v_line IN\r\n    SELECT (line ->> 'product_id')::uuid                 AS product_id,\r\n           (line ->> 'quantity')::numeric                AS quantity,\r\n           coalesce((line ->> 'unit_cost')::numeric, 0)  AS unit_cost,\r\n           nullif(btrim(coalesce(line ->> 'note', '')), '') AS note\r\n    FROM jsonb_array_elements(_items) AS line\r\n  LOOP\r\n    v_line_total := round(v_line.quantity * v_line.unit_cost, 2);\r\n    v_total := v_total + v_line_total;\r\n\r\n    INSERT INTO public.stock_opening_items (opening_id, product_id, quantity, unit_cost, total_cost, note)\r\n    VALUES (v_id, v_line.product_id, v_line.quantity, v_line.unit_cost, v_line_total, v_line.note);\r\n\r\n    PERFORM public.post_stock_delta(\r\n      v_line.product_id,\r\n      _warehouse_id,\r\n      v_line.quantity,                 -- positive: stock increases\r\n      v_line.unit_cost,\r\n      'OPENING'::public.stock_movement_kind,\r\n      'stock_opening',\r\n      v_id,\r\n      coalesce(v_line.note, 'رصيد أول المدة'),\r\n      'COMPANY'::public.owner_type,\r\n      NULL,\r\n      'opening'::public.movement_type\r\n    );\r\n  END LOOP;\r\n\r\n  UPDATE public.stock_openings SET total_value = v_total WHERE id = v_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'stock_opening.posted', 'stock_opening', v_id,\r\n    jsonb_build_object(\r\n      'document_number', v_number,\r\n      'warehouse_id', _warehouse_id,\r\n      'effective_date', coalesce(_effective_date, current_date),\r\n      'lines', jsonb_array_length(_items),\r\n      'total_value', v_total\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.post_stock_adjustment(_warehouse_id uuid, _reason text, _note text, _effective_date date, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user       uuid := auth.uid();\r\n  v_id         uuid;\r\n  v_number     text;\r\n  v_line       record;\r\n  v_policy     public.inventory_policy;\r\n  v_nature     public.item_nature;\r\n  v_total      numeric := 0;\r\n  v_line_total numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'warehouse')\r\n    OR public.has_role(v_user, 'accountant')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to post stock adjustments';\r\n  END IF;\r\n\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n\r\n  IF coalesce(btrim(_reason), '') = '' THEN\r\n    RAISE EXCEPTION 'A documented reason is required for every stock adjustment';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'A stock adjustment requires at least one item';\r\n  END IF;\r\n\r\n  FOR v_line IN\r\n    SELECT (line ->> 'product_id')::uuid                 AS product_id,\r\n           (line ->> 'quantity')::numeric                AS quantity,\r\n           coalesce((line ->> 'unit_cost')::numeric, 0)  AS unit_cost,\r\n           nullif(btrim(coalesce(line ->> 'note', '')), '') AS note\r\n    FROM jsonb_array_elements(_items) AS line\r\n  LOOP\r\n    IF v_line.product_id IS NULL OR v_line.quantity IS NULL OR v_line.quantity = 0 THEN\r\n      RAISE EXCEPTION 'Every adjustment line requires an item and a non-zero quantity';\r\n    END IF;\r\n\r\n    SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = v_line.product_id;\r\n    IF v_nature IS NULL THEN\r\n      RAISE EXCEPTION 'Item % does not exist', v_line.product_id;\r\n    END IF;\r\n    IF v_nature = 'SERVICE' THEN\r\n      RAISE EXCEPTION 'Item % is a SERVICE and has no inventory to adjust', v_line.product_id;\r\n    END IF;\r\n\r\n    v_policy := public.item_effective_policy(v_line.product_id);\r\n    IF v_policy <> 'TRACKED' THEN\r\n      RAISE EXCEPTION\r\n        'Item % has inventory policy %, so it has no inventory balance to adjust',\r\n        v_line.product_id, v_policy;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  v_number := public.next_stock_adjustment_number();\r\n\r\n  INSERT INTO public.stock_adjustments (document_number, warehouse_id, effective_date, reason, note, created_by)\r\n  VALUES (v_number, _warehouse_id, coalesce(_effective_date, current_date), btrim(_reason),\r\n          nullif(btrim(coalesce(_note, '')), ''), v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR v_line IN\r\n    SELECT (line ->> 'product_id')::uuid                 AS product_id,\r\n           (line ->> 'quantity')::numeric                AS quantity,\r\n           coalesce((line ->> 'unit_cost')::numeric, 0)  AS unit_cost,\r\n           nullif(btrim(coalesce(line ->> 'note', '')), '') AS note\r\n    FROM jsonb_array_elements(_items) AS line\r\n  LOOP\r\n    v_line_total := round(abs(v_line.quantity) * v_line.unit_cost, 2);\r\n    v_total := v_total + v_line_total;\r\n\r\n    INSERT INTO public.stock_adjustment_items (adjustment_id, product_id, quantity, unit_cost, total_cost, note)\r\n    VALUES (v_id, v_line.product_id, v_line.quantity, v_line.unit_cost, v_line_total, v_line.note);\r\n\r\n    -- signed quantity goes straight through: positive adds, negative removes.\r\n    PERFORM public.post_stock_delta(\r\n      v_line.product_id,\r\n      _warehouse_id,\r\n      v_line.quantity,\r\n      v_line.unit_cost,\r\n      'ADJUSTMENT'::public.stock_movement_kind,\r\n      'stock_adjustment',\r\n      v_id,\r\n      coalesce(v_line.note, btrim(_reason)),\r\n      'COMPANY'::public.owner_type,\r\n      NULL,\r\n      'adjustment'::public.movement_type\r\n    );\r\n  END LOOP;\r\n\r\n  -- The DB constraint requires a coded reason on every adjustment movement.\r\n  UPDATE public.stock_movements\r\n  SET adjustment_reason = btrim(_reason)\r\n  WHERE source_type = 'stock_adjustment'\r\n    AND source_id = v_id\r\n    AND movement_kind = 'ADJUSTMENT'\r\n    AND adjustment_reason IS NULL;\r\n\r\n  UPDATE public.stock_adjustments SET total_value = v_total WHERE id = v_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'stock_adjustment.posted', 'stock_adjustment', v_id,\r\n    jsonb_build_object(\r\n      'document_number', v_number,\r\n      'warehouse_id', _warehouse_id,\r\n      'reason', btrim(_reason),\r\n      'effective_date', coalesce(_effective_date, current_date),\r\n      'lines', jsonb_array_length(_items),\r\n      'total_value', v_total\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.post_stock_delta(p_product_id uuid, p_warehouse_id uuid, p_signed_qty numeric, p_unit_cost numeric DEFAULT NULL::numeric, p_movement_kind stock_movement_kind DEFAULT 'ADJUSTMENT'::stock_movement_kind, p_source_type text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_owner_type owner_type DEFAULT 'COMPANY'::owner_type, p_owner_id uuid DEFAULT NULL::uuid, p_movement_type_legacy movement_type DEFAULT NULL::movement_type)\r\n RETURNS numeric\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_existing    numeric;\r\n  v_new_qty     numeric;\r\n  v_total_cost  numeric;\r\n  v_legacy_type public.movement_type;\r\n  v_owner_type  public.owner_type := COALESCE(p_owner_type, 'COMPANY');\r\nBEGIN\r\n  IF p_signed_qty IS NULL OR p_signed_qty = 0 THEN\r\n    RAISE EXCEPTION 'Stock delta must be a non-zero quantity';\r\n  END IF;\r\n\r\n  IF p_product_id IS NULL OR p_warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Item and location are required for a stock movement';\r\n  END IF;\r\n\r\n  -- Lock the exact position being changed.\r\n  SELECT quantity\r\n    INTO v_existing\r\n  FROM public.inventory\r\n  WHERE product_id = p_product_id\r\n    AND warehouse_id = p_warehouse_id\r\n    AND owner_type = v_owner_type\r\n    AND owner_id IS NOT DISTINCT FROM p_owner_id\r\n  FOR UPDATE;\r\n\r\n  v_existing := COALESCE(v_existing, 0);\r\n  v_new_qty  := round(v_existing + p_signed_qty, 3);\r\n\r\n  -- Stock can never go negative, for company stock or for customer-owned stock.\r\n  IF v_new_qty < 0 THEN\r\n    RAISE EXCEPTION\r\n      'Insufficient stock: item %, location %, available %, requested %',\r\n      p_product_id, p_warehouse_id, v_existing, abs(p_signed_qty)\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  INSERT INTO public.inventory (product_id, warehouse_id, quantity, owner_type, owner_id, updated_at)\r\n  VALUES (p_product_id, p_warehouse_id, v_new_qty, v_owner_type, p_owner_id, now())\r\n  ON CONFLICT (product_id, warehouse_id, owner_type, owner_id)\r\n  DO UPDATE SET quantity = v_new_qty, updated_at = now();\r\n\r\n  v_total_cost := CASE\r\n    WHEN p_unit_cost IS NULL THEN NULL\r\n    ELSE round(abs(p_signed_qty) * p_unit_cost, 2)\r\n  END;\r\n\r\n  -- Legacy enum value, so the old reporting paths keep working unchanged.\r\n  v_legacy_type := COALESCE(\r\n    p_movement_type_legacy,\r\n    CASE p_movement_kind\r\n      WHEN 'RECEIPT'      THEN 'purchase'::public.movement_type\r\n      WHEN 'ISSUE'        THEN 'sale'::public.movement_type\r\n      WHEN 'TRANSFER_IN'  THEN 'transfer_in'::public.movement_type\r\n      WHEN 'TRANSFER_OUT' THEN 'transfer_out'::public.movement_type\r\n      WHEN 'OPENING'      THEN 'opening'::public.movement_type\r\n      -- PRODUCTION كان يسقط في ELSE فيُسجّل «adjustment»، وهو خطأ: ناتج الإنتاج\r\n      -- ليس تسوية جرد، وتسجيله كذلك يجعل تقرير الإنتاج يخلو من نواتجه.\r\n      WHEN 'PRODUCTION'   THEN 'production_in'::public.movement_type\r\n      ELSE 'adjustment'::public.movement_type\r\n    END\r\n  );\r\n\r\n  INSERT INTO public.stock_movements (\r\n    product_id, warehouse_id, movement_type, movement_kind,\r\n    quantity, unit_cost, total_cost,\r\n    reference_type, reference_id, source_type, source_id,\r\n    owner_type, owner_id,\r\n    note, created_by\r\n  )\r\n  VALUES (\r\n    p_product_id, p_warehouse_id, v_legacy_type, p_movement_kind,\r\n    abs(p_signed_qty), p_unit_cost, v_total_cost,\r\n    p_source_type, p_source_id, p_source_type, p_source_id,\r\n    v_owner_type, p_owner_id,\r\n    nullif(btrim(COALESCE(p_note, '')), ''), auth.uid()\r\n  );\r\n\r\n  RETURN v_new_qty;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.product_delete_guard(p_product_id uuid)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_counts jsonb;\r\n  v_blocking bigint;\r\nBEGIN\r\n  -- Permission check: only owner/manager may hard-delete a product.\r\n  IF NOT (\r\n    public.has_role(auth.uid(), 'owner')\r\n    OR public.has_role(auth.uid(), 'manager')\r\n    OR public.is_platform_admin(auth.uid())\r\n  ) THEN\r\n    RETURN jsonb_build_object('deleted', false, 'reason', 'forbidden');\r\n  END IF;\r\n\r\n  v_counts   := public.product_reference_counts(p_product_id);\r\n  v_blocking := COALESCE((v_counts ->> 'blocking_total')::bigint, 0);\r\n\r\n  IF v_blocking > 0 THEN\r\n    -- Referenced by history -> never delete. The UI offers deactivation instead.\r\n    RETURN jsonb_build_object(\r\n      'deleted', false,\r\n      'reason',  'referenced',\r\n      'counts',  v_counts\r\n    );\r\n  END IF;\r\n\r\n  -- Not referenced by any document or movement: safe to remove.\r\n  -- Clean the pure-catalog satellites that carry no financial meaning.\r\n  BEGIN\r\n    DELETE FROM public.product_compatibilities WHERE product_id = p_product_id;\r\n  EXCEPTION WHEN undefined_table THEN NULL;\r\n  END;\r\n\r\n  DELETE FROM public.inventory WHERE product_id = p_product_id;\r\n\r\n  DELETE FROM public.products WHERE id = p_product_id;\r\n\r\n  IF NOT FOUND THEN\r\n    RETURN jsonb_build_object('deleted', false, 'reason', 'not_found');\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object(\r\n    'deleted', true,\r\n    'reason',  'deleted',\r\n    'counts',  v_counts\r\n  );\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.product_reference_counts(p_product_id uuid)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_sales_items      bigint := 0;\r\n  v_purchase_items   bigint := 0;\r\n  v_sales_returns    bigint := 0;\r\n  v_purchase_returns bigint := 0;\r\n  v_transfers        bigint := 0;\r\n  v_stock_movements  bigint := 0;\r\n  v_inventory_rows   bigint := 0;\r\n  v_compatibilities  bigint := 0;\r\n  v_blocking         bigint := 0;\r\nBEGIN\r\n  -- Historical / financial documents: these MUST block deletion.\r\n  SELECT count(*) INTO v_sales_items\r\n    FROM public.sales_invoice_items WHERE product_id = p_product_id;\r\n\r\n  SELECT count(*) INTO v_purchase_items\r\n    FROM public.purchase_invoice_items WHERE product_id = p_product_id;\r\n\r\n  -- Returns and transfers are guarded dynamically: some deployments have these\r\n  -- tables, older ones do not. Missing tables count as zero.\r\n  BEGIN\r\n    SELECT count(*) INTO v_sales_returns\r\n      FROM public.sales_return_items WHERE product_id = p_product_id;\r\n  EXCEPTION WHEN undefined_table THEN v_sales_returns := 0;\r\n  END;\r\n\r\n  BEGIN\r\n    SELECT count(*) INTO v_purchase_returns\r\n      FROM public.purchase_return_items WHERE product_id = p_product_id;\r\n  EXCEPTION WHEN undefined_table THEN v_purchase_returns := 0;\r\n  END;\r\n\r\n  BEGIN\r\n    SELECT count(*) INTO v_transfers\r\n      FROM public.stock_transfer_items WHERE product_id = p_product_id;\r\n  EXCEPTION WHEN undefined_table THEN v_transfers := 0;\r\n  END;\r\n\r\n  -- Audit trail: destroying this loses the product's stock history.\r\n  SELECT count(*) INTO v_stock_movements\r\n    FROM public.stock_movements WHERE product_id = p_product_id;\r\n\r\n  SELECT count(*) INTO v_inventory_rows\r\n    FROM public.inventory WHERE product_id = p_product_id;\r\n\r\n  BEGIN\r\n    SELECT count(*) INTO v_compatibilities\r\n      FROM public.product_compatibilities WHERE product_id = p_product_id;\r\n  EXCEPTION WHEN undefined_table THEN v_compatibilities := 0;\r\n  END;\r\n\r\n  v_blocking := v_sales_items + v_purchase_items + v_sales_returns\r\n              + v_purchase_returns + v_transfers + v_stock_movements;\r\n\r\n  RETURN jsonb_build_object(\r\n    'product_id',          p_product_id,\r\n    'sales_items',         v_sales_items,\r\n    'purchase_items',      v_purchase_items,\r\n    'sales_returns',       v_sales_returns,\r\n    'purchase_returns',    v_purchase_returns,\r\n    'transfers',           v_transfers,\r\n    'stock_movements',     v_stock_movements,\r\n    'inventory_rows',      v_inventory_rows,\r\n    'compatibilities',     v_compatibilities,\r\n    'blocking_total',      v_blocking,\r\n    'can_delete',          v_blocking = 0,\r\n    'has_history',         v_stock_movements > 0 OR v_inventory_rows > 0\r\n  );\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.receive_customer_owned_stock(_customer_id uuid, _product_id uuid, _warehouse_id uuid, _quantity numeric, _unit_cost numeric, _note text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user        uuid := auth.uid();\r\n  v_nature      public.item_nature;\r\n  v_movement_id uuid;\r\n  v_new_qty     numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'warehouse')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to receive customer-owned material';\r\n  END IF;\r\n\r\n  IF _customer_id IS NULL OR _product_id IS NULL OR _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Customer, item and location are all required';\r\n  END IF;\r\n\r\n  IF _quantity IS NULL OR _quantity <= 0 THEN\r\n    RAISE EXCEPTION 'Quantity must be positive';\r\n  END IF;\r\n\r\n  -- A service can never be physically received.\r\n  SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = _product_id;\r\n  IF v_nature IS NULL THEN\r\n    RAISE EXCEPTION 'Item % does not exist', _product_id;\r\n  END IF;\r\n  IF v_nature = 'SERVICE' THEN\r\n    RAISE EXCEPTION 'Item % is a SERVICE and cannot be held as physical material', _product_id;\r\n  END IF;\r\n\r\n  IF NOT EXISTS (SELECT 1 FROM public.customers c WHERE c.id = _customer_id) THEN\r\n    RAISE EXCEPTION 'Customer % does not exist', _customer_id;\r\n  END IF;\r\n\r\n  v_new_qty := public.post_stock_delta(\r\n    _product_id,\r\n    _warehouse_id,\r\n    _quantity,\r\n    coalesce(_unit_cost, 0),\r\n    'RECEIPT'::public.stock_movement_kind,\r\n    'customer_owned_receipt',\r\n    NULL,\r\n    coalesce(nullif(btrim(coalesce(_note, '')), ''), 'استلام مادة مملوكة للعميل'),\r\n    'CUSTOMER'::public.owner_type,\r\n    _customer_id,\r\n    'purchase'::public.movement_type\r\n  );\r\n\r\n  SELECT id INTO v_movement_id\r\n  FROM public.stock_movements\r\n  WHERE product_id = _product_id\r\n    AND warehouse_id = _warehouse_id\r\n    AND owner_type = 'CUSTOMER'\r\n    AND owner_id = _customer_id\r\n  ORDER BY created_at DESC\r\n  LIMIT 1;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'customer_owned.received', 'customers', _customer_id,\r\n    jsonb_build_object(\r\n      'product_id', _product_id,\r\n      'warehouse_id', _warehouse_id,\r\n      'quantity', _quantity,\r\n      'unit_cost', coalesce(_unit_cost, 0),\r\n      'resulting_quantity', v_new_qty,\r\n      'movement_id', v_movement_id\r\n    ));\r\n\r\n  RETURN v_movement_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.release_customer_owned_stock(_customer_id uuid, _product_id uuid, _warehouse_id uuid, _quantity numeric, _note text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user        uuid := auth.uid();\r\n  v_movement_id uuid;\r\n  v_new_qty     numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'warehouse')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to release customer-owned material';\r\n  END IF;\r\n\r\n  IF _quantity IS NULL OR _quantity <= 0 THEN\r\n    RAISE EXCEPTION 'Quantity must be positive';\r\n  END IF;\r\n\r\n  v_new_qty := public.post_stock_delta(\r\n    _product_id,\r\n    _warehouse_id,\r\n    -_quantity,                     -- leaving the premises\r\n    0,\r\n    'ISSUE'::public.stock_movement_kind,\r\n    'customer_owned_delivery',\r\n    NULL,\r\n    coalesce(nullif(btrim(coalesce(_note, '')), ''), 'تسليم مادة مملوكة للعميل'),\r\n    'CUSTOMER'::public.owner_type,\r\n    _customer_id,\r\n    'sale'::public.movement_type\r\n  );\r\n\r\n  SELECT id INTO v_movement_id\r\n  FROM public.stock_movements\r\n  WHERE product_id = _product_id\r\n    AND warehouse_id = _warehouse_id\r\n    AND owner_type = 'CUSTOMER'\r\n    AND owner_id = _customer_id\r\n  ORDER BY created_at DESC\r\n  LIMIT 1;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'customer_owned.released', 'customers', _customer_id,\r\n    jsonb_build_object(\r\n      'product_id', _product_id,\r\n      'warehouse_id', _warehouse_id,\r\n      'quantity', _quantity,\r\n      'resulting_quantity', v_new_qty,\r\n      'movement_id', v_movement_id\r\n    ));\r\n\r\n  RETURN v_movement_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.resolve_unit_cost(p_product_id uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_as_of timestamp with time zone DEFAULT NULL::timestamp with time zone)\r\n RETURNS numeric\r\n LANGUAGE plpgsql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_method public.costing_method := public.company_costing_method();\r\n  v_layer  record;\r\n  v_cat    numeric;\r\n  v_standard numeric;\r\nBEGIN\r\n  IF p_product_id IS NULL THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  -- Standard cost is a property of the item, not of the warehouse: the same\r\n  -- standard applies everywhere, and that is what makes it a standard.\r\n  IF v_method = 'STANDARD' THEN\r\n    SELECT p.standard_cost\r\n      INTO v_standard\r\n      FROM public.products p\r\n     WHERE p.id = p_product_id;\r\n\r\n    IF v_standard IS NOT NULL THEN\r\n      RETURN v_standard;\r\n    END IF;\r\n    -- No standard set yet: fall through to the layer, then to the catalogue.\r\n    -- A zero would be worse than a reference, because zero margin hides a\r\n    -- missing configuration instead of reporting it.\r\n  END IF;\r\n\r\n  -- Company-owned layer, optionally at a specific warehouse. Aggregated\r\n  -- across warehouses when none is named, because a valuation belongs to the\r\n  -- company unless the caller is asking about one silo.\r\n  SELECT sum(cl.quantity)                                   AS qty,\r\n         sum(cl.total_value)                                AS val,\r\n         CASE WHEN sum(cl.quantity) <> 0\r\n              THEN round(sum(cl.total_value) / sum(cl.quantity), 4)\r\n              ELSE 0 END                                    AS avg_cost,\r\n         bool_or(cl.valuation_method = 'STANDARD')          AS any_standard\r\n    INTO v_layer\r\n    FROM public.item_cost_layers cl\r\n   WHERE cl.product_id = p_product_id\r\n     AND cl.owner_type = 'COMPANY'::public.owner_type\r\n     AND (p_warehouse_id IS NULL OR cl.warehouse_id = p_warehouse_id)\r\n     AND (p_as_of IS NULL OR cl.updated_at <= p_as_of);\r\n\r\n  IF v_layer.qty IS NOT NULL AND v_layer.qty <> 0 AND NOT v_layer.any_standard THEN\r\n    RETURN v_layer.avg_cost;\r\n  END IF;\r\n\r\n  -- Last resort: the catalogue reference, clearly a reference and not an\r\n  -- actual. Callers that report a margin must say so when this is what they\r\n  -- used, which resolve_unit_cost signals by returning a cost with no\r\n  -- supporting movement.\r\n  SELECT p.cost_price INTO v_cat FROM public.products p WHERE p.id = p_product_id;\r\n  RETURN coalesce(v_cat, 0);\r\nEND $function$","CREATE OR REPLACE FUNCTION public.save_item_policy(_item_id uuid, _item_nature item_nature, _inventory_policy inventory_policy, _costing_method costing_method, _tracking item_tracking, _is_sellable boolean, _is_purchasable boolean, _base_uom_id uuid DEFAULT NULL::uuid, _sales_uom_id uuid DEFAULT NULL::uuid, _purchase_uom_id uuid DEFAULT NULL::uuid, _uom_conversions jsonb DEFAULT NULL::jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_product public.products%ROWTYPE;\r\n  v_before  jsonb;\r\n  v_after   jsonb;\r\n  v_policy_changed boolean;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'warehouse')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to edit item policy';\r\n  END IF;\r\n\r\n  SELECT * INTO v_product FROM public.products WHERE id = _item_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Item % does not exist', _item_id;\r\n  END IF;\r\n\r\n  IF _item_nature = 'SERVICE' AND _inventory_policy <> 'UNTRACKED' THEN\r\n    RAISE EXCEPTION 'A SERVICE can only be UNTRACKED';\r\n  END IF;\r\n  IF _inventory_policy = 'TRACKED' AND _costing_method = 'NONE' THEN\r\n    RAISE EXCEPTION 'A TRACKED item requires a costing method other than NONE';\r\n  END IF;\r\n  IF _inventory_policy = 'UNTRACKED' AND _tracking <> 'NONE' THEN\r\n    RAISE EXCEPTION 'An UNTRACKED item cannot require batch or serial tracking';\r\n  END IF;\r\n  IF NOT _is_sellable AND NOT _is_purchasable THEN\r\n    RAISE EXCEPTION 'An item must be usable for selling, purchasing, or both';\r\n  END IF;\r\n\r\n  IF _uom_conversions IS NOT NULL AND jsonb_typeof(_uom_conversions) <> 'array' THEN\r\n    RAISE EXCEPTION 'UOM conversions must be a JSON array';\r\n  END IF;\r\n\r\n  v_policy_changed :=\r\n    _item_nature      IS DISTINCT FROM v_product.item_nature\r\n    OR _inventory_policy IS DISTINCT FROM v_product.inventory_policy\r\n    OR _costing_method   IS DISTINCT FROM v_product.costing_method\r\n    OR _tracking         IS DISTINCT FROM v_product.tracking;\r\n\r\n  -- When only the commercial flags or units change, no policy transition is\r\n  -- happening and the plain path is enough.\r\n  IF NOT v_policy_changed THEN\r\n    UPDATE public.products\r\n    SET is_sellable      = _is_sellable,\r\n        is_purchasable   = _is_purchasable,\r\n        base_uom_id      = _base_uom_id,\r\n        sales_uom_id     = _sales_uom_id,\r\n        purchase_uom_id  = _purchase_uom_id,\r\n        uom_conversions  = coalesce(_uom_conversions, uom_conversions),\r\n        updated_at       = now()\r\n    WHERE id = _item_id;\r\n\r\n    RETURN _item_id;\r\n  END IF;\r\n\r\n  -- A policy change is a governed transition. If the item has no history yet,\r\n  -- the trigger allows the direct write; if it has history, the owner/manager\r\n  -- rule applies and the change is audited.\r\n  IF public.item_has_stock_history(_item_id) THEN\r\n    IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN\r\n      RAISE EXCEPTION\r\n        'Item % has inventory history; only an owner or manager may change its policy',\r\n        _item_id;\r\n    END IF;\r\n\r\n    v_before := jsonb_build_object(\r\n      'item_nature', v_product.item_nature,\r\n      'inventory_policy', v_product.inventory_policy,\r\n      'costing_method', v_product.costing_method,\r\n      'tracking', v_product.tracking\r\n    );\r\n\r\n    PERFORM set_config('app.allow_policy_change', 'on', true);\r\n  END IF;\r\n\r\n  UPDATE public.products\r\n  SET item_nature      = _item_nature,\r\n      inventory_policy = _inventory_policy,\r\n      costing_method   = _costing_method,\r\n      tracking         = _tracking,\r\n      is_sellable      = _is_sellable,\r\n      is_purchasable   = _is_purchasable,\r\n      base_uom_id      = _base_uom_id,\r\n      sales_uom_id     = _sales_uom_id,\r\n      purchase_uom_id  = _purchase_uom_id,\r\n      uom_conversions  = coalesce(_uom_conversions, uom_conversions),\r\n      updated_at       = now()\r\n  WHERE id = _item_id;\r\n\r\n  IF v_before IS NOT NULL THEN\r\n    v_after := jsonb_build_object(\r\n      'item_nature', _item_nature,\r\n      'inventory_policy', _inventory_policy,\r\n      'costing_method', _costing_method,\r\n      'tracking', _tracking\r\n    );\r\n\r\n    PERFORM public.audit_item_policy_snapshot(\r\n      _item_id,\r\n      'item_policy.changed',\r\n      v_before,\r\n      v_after,\r\n      'item_editor'\r\n    );\r\n  END IF;\r\n\r\n  RETURN _item_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.search_products(p_query text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_brand_id uuid DEFAULT NULL::uuid, p_unit_id uuid DEFAULT NULL::uuid, p_origin_id uuid DEFAULT NULL::uuid, p_active boolean DEFAULT NULL::boolean, p_low_stock boolean DEFAULT NULL::boolean, p_sort_key text DEFAULT 'created_at'::text, p_sort_dir text DEFAULT 'desc'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)\r\n RETURNS TABLE(id uuid, name text, name_ar text, sku text, barcode text, sale_price numeric, cost_price numeric, tax_rate numeric, min_stock numeric, shelf_location text, origin_id uuid, quality_grade_id uuid, is_active boolean, category_id uuid, brand_id uuid, unit_id uuid, created_at timestamp with time zone, category_name text, category_name_ar text, brand_name text, brand_name_ar text, unit_short_name text, unit_name_ar text, stock_qty numeric, total_count bigint)\r\n LANGUAGE sql\r\n STABLE\r\n SET search_path TO 'public'\r\nAS $function$\r\n  WITH filtered AS (\r\n    SELECT\r\n      p.id, p.name, p.name_ar, p.sku, p.barcode,\r\n      p.sale_price, p.cost_price, p.tax_rate, p.min_stock, p.shelf_location,\r\n      p.origin_id, p.quality_grade_id, p.is_active,\r\n      p.category_id, p.brand_id, p.unit_id, p.created_at,\r\n      c.name    AS category_name,\r\n      c.name_ar AS category_name_ar,\r\n      b.name    AS brand_name,\r\n      b.name_ar AS brand_name_ar,\r\n      u.short_name AS unit_short_name,\r\n      u.name_ar    AS unit_name_ar,\r\n      COALESCE((\r\n        SELECT sum(i.quantity) FROM public.inventory i WHERE i.product_id = p.id\r\n      ), 0) AS stock_qty\r\n    FROM public.products p\r\n    LEFT JOIN public.categories c ON c.id = p.category_id\r\n    LEFT JOIN public.brands     b ON b.id = p.brand_id\r\n    LEFT JOIN public.units      u ON u.id = p.unit_id\r\n    WHERE\r\n      -- Fuzzy-ish text search: case-insensitive substring across the identity\r\n      -- fields. Uses simple LIKE so it works on any Postgres without extensions.\r\n      (\r\n        p_query IS NULL\r\n        OR btrim(p_query) = ''\r\n        OR p.name        ILIKE '%' || btrim(p_query) || '%'\r\n        OR p.name_ar     ILIKE '%' || btrim(p_query) || '%'\r\n        OR p.sku         ILIKE '%' || btrim(p_query) || '%'\r\n        OR p.barcode     ILIKE '%' || btrim(p_query) || '%'\r\n        OR p.shelf_location ILIKE '%' || btrim(p_query) || '%'\r\n      )\r\n      AND (p_category_id IS NULL OR p.category_id = p_category_id)\r\n      AND (p_brand_id    IS NULL OR p.brand_id    = p_brand_id)\r\n      AND (p_unit_id     IS NULL OR p.unit_id     = p_unit_id)\r\n      AND (p_origin_id   IS NULL OR p.origin_id   = p_origin_id)\r\n      AND (p_active      IS NULL OR p.is_active   = p_active)\r\n  ),\r\n  counted AS (\r\n    SELECT *, count(*) OVER () AS total_count FROM filtered\r\n  )\r\n  SELECT\r\n    id, name, name_ar, sku, barcode,\r\n    sale_price, cost_price, tax_rate, min_stock, shelf_location,\r\n    origin_id, quality_grade_id, is_active,\r\n    category_id, brand_id, unit_id, created_at,\r\n    category_name, category_name_ar, brand_name, brand_name_ar,\r\n    unit_short_name, unit_name_ar,\r\n    stock_qty, total_count\r\n  FROM counted\r\n  WHERE\r\n    p_low_stock IS NULL\r\n    OR (p_low_stock = true  AND stock_qty <= min_stock)\r\n    OR (p_low_stock = false AND stock_qty >  min_stock)\r\n  ORDER BY\r\n    CASE WHEN p_sort_key = 'name'       AND p_sort_dir = 'asc'  THEN COALESCE(name_ar, name) END ASC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'name'       AND p_sort_dir = 'desc' THEN COALESCE(name_ar, name) END DESC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'sku'        AND p_sort_dir = 'asc'  THEN sku END ASC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'sku'        AND p_sort_dir = 'desc' THEN sku END DESC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'sale_price' AND p_sort_dir = 'asc'  THEN sale_price END ASC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'sale_price' AND p_sort_dir = 'desc' THEN sale_price END DESC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'cost_price' AND p_sort_dir = 'asc'  THEN cost_price END ASC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'cost_price' AND p_sort_dir = 'desc' THEN cost_price END DESC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'stock'      AND p_sort_dir = 'asc'  THEN stock_qty END ASC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'stock'      AND p_sort_dir = 'desc' THEN stock_qty END DESC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'created_at' AND p_sort_dir = 'asc'  THEN created_at END ASC NULLS LAST,\r\n    CASE WHEN p_sort_key = 'created_at' AND p_sort_dir = 'desc' THEN created_at END DESC NULLS LAST,\r\n    created_at DESC\r\n  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 50), 200))\r\n  OFFSET GREATEST(0, COALESCE(p_offset, 0));\r\n$function$","CREATE OR REPLACE FUNCTION public.set_company_costing_method(_method text, _source text, _notes text)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_old  public.costing_method;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN\r\n    RAISE EXCEPTION 'Only an owner or manager can change the company costing method';\r\n  END IF;\r\n  -- ⚠️ _method قد تكون NULL (أو بأحرف صغيرة من الواجهة). التحقق القديم\r\n  --    `_method NOT IN (...)` يقبل NULL بصمت لأن NULL NOT IN (...) = NULL،\r\n  --    ثم يُدرج NULL في costing_policy_history.costing_method (NOT NULL)\r\n  --    فيرمي 23502 بدل رسالة واضحة. الآن يُرفض null/farغ صراحةً ويُطبَّع الحرف.\r\n  _method := upper(btrim(coalesce(_method, '')));\r\n  IF _method IS NULL OR _method = '' THEN\r\n    RAISE EXCEPTION 'Costing method is required (MOVING_AVERAGE or STANDARD)'\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n  IF _method NOT IN ('MOVING_AVERAGE', 'STANDARD') THEN\r\n    RAISE EXCEPTION 'Costing method must be MOVING_AVERAGE or STANDARD (got %)', _method\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  SELECT costing_method INTO v_old FROM public.company_costing_settings WHERE id = 1 FOR UPDATE;\r\n  IF v_old = _method::public.costing_method THEN\r\n    RETURN;  -- idempotent: re-selecting the same method is not a change\r\n  END IF;\r\n\r\n  UPDATE public.company_costing_settings\r\n     SET costing_method = _method::public.costing_method,\r\n         standard_cost_source = coalesce(_source, standard_cost_source),\r\n         effective_from    = CURRENT_DATE,\r\n         updated_by        = v_user,\r\n         updated_at        = now(),\r\n         notes             = nullif(btrim(coalesce(_notes, '')), '')\r\n   WHERE id = 1;\r\n\r\n  INSERT INTO public.costing_policy_history (costing_method, previous_method, reason, changed_by)\r\n  VALUES (_method::public.costing_method, v_old, nullif(btrim(coalesce(_notes, '')), ''), v_user);\r\nEND $function$","CREATE OR REPLACE FUNCTION public.set_company_item_policy(_item_id uuid, _inventory_policy inventory_policy DEFAULT NULL::inventory_policy, _costing_method costing_method DEFAULT NULL::costing_method, _default_cost numeric DEFAULT NULL::numeric, _default_sale_price numeric DEFAULT NULL::numeric, _tax_rate numeric DEFAULT NULL::numeric, _is_active boolean DEFAULT true, _company_id integer DEFAULT 1)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_id      uuid;\r\n  v_before  jsonb;\r\n  v_after   jsonb;\r\n  v_nature  public.item_nature;\r\n  v_balance numeric;\r\n  v_existing public.company_items%ROWTYPE;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN\r\n    RAISE EXCEPTION 'Only an owner or manager may change a company item policy';\r\n  END IF;\r\n\r\n  SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = _item_id;\r\n  IF v_nature IS NULL THEN\r\n    RAISE EXCEPTION 'Item % does not exist', _item_id;\r\n  END IF;\r\n\r\n  IF v_nature = 'SERVICE' AND _inventory_policy IS NOT NULL AND _inventory_policy <> 'UNTRACKED' THEN\r\n    RAISE EXCEPTION 'A SERVICE can only be UNTRACKED in any company';\r\n  END IF;\r\n\r\n  IF _default_cost IS NOT NULL AND _default_cost < 0 THEN\r\n    RAISE EXCEPTION 'Default cost cannot be negative';\r\n  END IF;\r\n  IF _default_sale_price IS NOT NULL AND _default_sale_price < 0 THEN\r\n    RAISE EXCEPTION 'Default sale price cannot be negative';\r\n  END IF;\r\n  IF _tax_rate IS NOT NULL AND (_tax_rate < 0 OR _tax_rate > 100) THEN\r\n    RAISE EXCEPTION 'Tax rate must be between 0 and 100';\r\n  END IF;\r\n\r\n  SELECT * INTO v_existing\r\n  FROM public.company_items\r\n  WHERE company_id = _company_id AND item_id = _item_id\r\n  FOR UPDATE;\r\n\r\n  -- Refuse to strand stock by turning tracking off for a company that holds it.\r\n  IF _inventory_policy IS NOT NULL AND _inventory_policy <> 'TRACKED' THEN\r\n    SELECT coalesce(sum(i.quantity), 0) INTO v_balance\r\n    FROM public.inventory i\r\n    WHERE i.product_id = _item_id\r\n      AND i.owner_type = 'COMPANY'\r\n      AND i.owner_id IS NULL;\r\n\r\n    IF v_balance <> 0\r\n       AND coalesce(v_existing.inventory_policy, (SELECT p.inventory_policy FROM public.products p WHERE p.id = _item_id)) = 'TRACKED' THEN\r\n      RAISE EXCEPTION\r\n        'Company % still holds % units of item %. Clear the balance before leaving TRACKED.',\r\n        _company_id, v_balance, _item_id;\r\n    END IF;\r\n  END IF;\r\n\r\n  v_before := CASE WHEN v_existing.id IS NULL THEN NULL ELSE\r\n    jsonb_build_object(\r\n      'inventory_policy', v_existing.inventory_policy,\r\n      'costing_method', v_existing.costing_method,\r\n      'default_cost', v_existing.default_cost,\r\n      'default_sale_price', v_existing.default_sale_price,\r\n      'tax_rate', v_existing.tax_rate,\r\n      'is_active', v_existing.is_active\r\n    ) END;\r\n\r\n  INSERT INTO public.company_items (\r\n    company_id, item_id, inventory_policy, costing_method,\r\n    default_cost, default_sale_price, tax_rate, is_active\r\n  )\r\n  VALUES (\r\n    _company_id, _item_id, _inventory_policy, _costing_method,\r\n    _default_cost, _default_sale_price, _tax_rate, coalesce(_is_active, true)\r\n  )\r\n  ON CONFLICT (company_id, item_id) DO UPDATE\r\n  SET inventory_policy   = COALESCE(EXCLUDED.inventory_policy,   public.company_items.inventory_policy),\r\n      costing_method     = COALESCE(EXCLUDED.costing_method,     public.company_items.costing_method),\r\n      default_cost       = COALESCE(EXCLUDED.default_cost,       public.company_items.default_cost),\r\n      default_sale_price = COALESCE(EXCLUDED.default_sale_price, public.company_items.default_sale_price),\r\n      tax_rate           = COALESCE(EXCLUDED.tax_rate,           public.company_items.tax_rate),\r\n      is_active          = EXCLUDED.is_active,\r\n      updated_at         = now()\r\n  RETURNING id INTO v_id;\r\n\r\n  SELECT jsonb_build_object(\r\n           'inventory_policy', ci.inventory_policy,\r\n           'costing_method', ci.costing_method,\r\n           'default_cost', ci.default_cost,\r\n           'default_sale_price', ci.default_sale_price,\r\n           'tax_rate', ci.tax_rate,\r\n           'is_active', ci.is_active\r\n         )\r\n    INTO v_after\r\n  FROM public.company_items ci WHERE ci.id = v_id;\r\n\r\n  PERFORM public.audit_item_policy_snapshot(\r\n    _item_id,\r\n    'company_item_policy.changed',\r\n    coalesce(v_before, '{}'::jsonb),\r\n    v_after,\r\n    'company:' || _company_id\r\n  );\r\n\r\n  RETURN v_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.set_standard_costs(_costs jsonb)\r\n RETURNS integer\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_n    integer := 0;\r\n  e      jsonb;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')) THEN\r\n    RAISE EXCEPTION 'Only an owner or manager may set standard costs';\r\n  END IF;\r\n  IF _costs IS NULL OR jsonb_array_length(_costs) = 0 THEN\r\n    RAISE EXCEPTION 'No standards supplied';\r\n  END IF;\r\n\r\n  FOR e IN SELECT * FROM jsonb_array_elements(_costs)\r\n  LOOP\r\n    IF coalesce((e->>'standard_cost')::numeric, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Standard cost must be greater than zero for product %', e->>'product_id';\r\n    END IF;\r\n    IF NOT EXISTS (SELECT 1 FROM public.products p\r\n                    WHERE p.id = (e->>'product_id')::uuid\r\n                      AND p.item_nature = 'GOOD' AND p.inventory_policy = 'TRACKED') THEN\r\n      RAISE EXCEPTION 'Product % is not a tracked good', e->>'product_id';\r\n    END IF;\r\n\r\n    UPDATE public.products\r\n       SET standard_cost = (e->>'standard_cost')::numeric\r\n     WHERE id = (e->>'product_id')::uuid;\r\n\r\n    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n    VALUES (v_user, 'product.standard_cost_set', 'product', (e->>'product_id')::uuid,\r\n            jsonb_build_object('standard_cost', (e->>'standard_cost')::numeric,\r\n                               'implied', (e->>'implied_standard')::numeric,\r\n                               'note', nullif(btrim(coalesce(e->>'note','')), '')));\r\n    v_n := v_n + 1;\r\n  END LOOP;\r\n  RETURN v_n;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.sync_item_class_from_policy()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\n SET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF TG_OP = 'INSERT'\r\n     OR NEW.item_nature IS DISTINCT FROM OLD.item_nature\r\n     OR NEW.inventory_policy IS DISTINCT FROM OLD.inventory_policy THEN\r\n\r\n    -- الطبيعة تحكم أولاً: الخدمة خدمة.\r\n    IF NEW.item_nature = 'SERVICE' THEN\r\n      NEW.item_class := 'SERVICE';\r\n\r\n    ELSIF NEW.item_nature = 'GOOD' THEN\r\n      -- الأصناف التي تصنيفها *خاصية جوهرية* لا تُدهَس بالمنتج النهائي:\r\n      -- خام قابل للاستهلاك، ناتج جانبي، وتعبئة تُشترى وتُستهلك.\r\n      IF NEW.item_class IS NULL\r\n         OR NEW.item_class NOT IN ('RAW_MATERIAL', 'BY_PRODUCT', 'PACKAGING') THEN\r\n        NEW.item_class := 'FINISHED_GOOD';\r\n      END IF;\r\n    END IF;\r\n\r\n    -- السياسة تحدّ الحالة التي لا تُمسك رصيداً.\r\n    IF NEW.inventory_policy = 'CUSTOMER_OWNED' THEN\r\n      -- أمانات العميل ليست مخزوناً تجارياً؛ تبقى ماديّةً في تصنيفها الأصلي.\r\n      IF NEW.item_class IS NULL THEN\r\n        NEW.item_class := 'NON_STOCK_ITEM';\r\n      END IF;\r\n    ELSIF NEW.inventory_policy = 'UNTRACKED' AND NEW.item_nature = 'GOOD' THEN\r\n      -- صنف مادي غير متتبَّع: لا رصيد له مهما كان نوعه.\r\n      NEW.item_class := 'NON_STOCK_ITEM';\r\n    END IF;\r\n  END IF;\r\n  RETURN NEW;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.tg_guard_item_policy_change()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_allow text := current_setting('app.allow_policy_change', true);\r\nBEGIN\r\n  IF v_allow = 'on' THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  -- Nature and policy changes are both restricted once history exists.\r\n  IF NEW.inventory_policy IS DISTINCT FROM OLD.inventory_policy\r\n     OR NEW.item_nature IS DISTINCT FROM OLD.item_nature\r\n     OR NEW.costing_method IS DISTINCT FROM OLD.costing_method\r\n  THEN\r\n    IF public.item_has_stock_history(OLD.id) THEN\r\n      RAISE EXCEPTION\r\n        'Item % has inventory history; policy changes must go through approve_item_policy_change()',\r\n        OLD.id\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  END IF;\r\n\r\n  -- Rule 2 enforced again at the transition point: an item with history can\r\n  -- never become a SERVICE, because that would retroactively re-label real\r\n  -- stock movements as a non-stock service.\r\n  IF NEW.item_nature = 'SERVICE' AND OLD.item_nature <> 'SERVICE' THEN\r\n    IF public.item_has_stock_history(OLD.id) THEN\r\n      RAISE EXCEPTION\r\n        'Item % has inventory history and cannot be converted to SERVICE', OLD.id\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.warehouse_reference_counts(p_warehouse_id uuid)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_inventory  bigint := 0;\r\n  v_movements  bigint := 0;\r\n  v_sales      bigint := 0;\r\n  v_purchases  bigint := 0;\r\n  v_transfers  bigint := 0;\r\n  v_blocking   bigint := 0;\r\nBEGIN\r\n  SELECT count(*) INTO v_inventory FROM public.inventory WHERE warehouse_id = p_warehouse_id;\r\n  SELECT count(*) INTO v_movements FROM public.stock_movements WHERE warehouse_id = p_warehouse_id;\r\n\r\n  BEGIN\r\n    SELECT count(*) INTO v_sales FROM public.sales_invoices WHERE warehouse_id = p_warehouse_id;\r\n  EXCEPTION WHEN undefined_column THEN v_sales := 0;\r\n  END;\r\n\r\n  BEGIN\r\n    SELECT count(*) INTO v_purchases FROM public.purchase_invoices WHERE warehouse_id = p_warehouse_id;\r\n  EXCEPTION WHEN undefined_column THEN v_purchases := 0;\r\n  END;\r\n\r\n  BEGIN\r\n    SELECT count(*) INTO v_transfers FROM public.stock_transfers\r\n      WHERE from_warehouse_id = p_warehouse_id OR to_warehouse_id = p_warehouse_id;\r\n  EXCEPTION WHEN undefined_table THEN v_transfers := 0;\r\n       WHEN undefined_column THEN v_transfers := 0;\r\n  END;\r\n\r\n  v_blocking := v_inventory + v_movements + v_sales + v_purchases + v_transfers;\r\n\r\n  RETURN jsonb_build_object(\r\n    'warehouse_id',   p_warehouse_id,\r\n    'inventory_rows', v_inventory,\r\n    'stock_movements',v_movements,\r\n    'sales_invoices', v_sales,\r\n    'purchase_invoices', v_purchases,\r\n    'transfers',      v_transfers,\r\n    'blocking_total', v_blocking,\r\n    'can_delete',     v_blocking = 0\r\n  );\r\nEND;\r\n$function$"}	products_and_inventory
06	{"-- ============================================================================\r\n-- 07_sales_and_returns.sql\r\n--\r\n-- المبيعات ومرتجعاتها والتحصيلات.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── TABLES ────────────────────────────────────────────────────────────────\r\nCREATE TABLE public.sales_invoices (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  invoice_number text NOT NULL,\r\n  customer_id uuid,\r\n  warehouse_id uuid,\r\n  -- حالة الدورة: مسودة / مؤكدة / ملغاة / مُرجَعة. لا تُكتب من مبلغ السداد.\r\n  status public.invoice_status DEFAULT 'draft'::invoice_status NOT NULL,\r\n  -- حالة السداد: غير مدفوعة / جزئية / مدفوعة / مدفوعة بالزيادة.\r\n  -- منفصلة عن status لأن العمود الواحد لا يحمل قيمتين: فاتورة «مؤكدة»\r\n  -- و«مدفوعة جزئيًا» في وقت واحد يستحيل تمثيلها بعمود واحد.\r\n  -- تُشتقّ من (paid مقابل total) ولا تُكتب يدويًا.\r\n  payment_status public.payment_status DEFAULT 'unpaid'::payment_status NOT NULL,\r\n  subtotal numeric(14,2) DEFAULT 0 NOT NULL,\r\n  discount numeric(14,2) DEFAULT 0 NOT NULL,\r\n  tax numeric(14,2) DEFAULT 0 NOT NULL,\r\n  total numeric(14,2) DEFAULT 0 NOT NULL,\r\n  paid numeric(14,2) DEFAULT 0 NOT NULL,\r\n  payment_method public.payment_method,\r\n  note text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.sales_invoice_items (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  invoice_id uuid NOT NULL,\r\n  product_id uuid,\r\n  quantity numeric(14,3) NOT NULL,\r\n  unit_price numeric(14,2) NOT NULL,\r\n  discount numeric(14,2) DEFAULT 0 NOT NULL,\r\n  tax numeric(14,2) DEFAULT 0 NOT NULL,\r\n  total numeric(14,2) NOT NULL,\r\n  description text,\r\n  line_type text,\r\n  stock_effect text,\r\n  uom_id uuid\r\n)","CREATE TABLE public.ad_hoc_service_lines (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  invoice_id uuid NOT NULL,\r\n  invoice_item_id uuid,\r\n  description text NOT NULL,\r\n  quantity numeric(14,3) NOT NULL,\r\n  unit_price numeric(14,2) NOT NULL,\r\n  discount numeric(14,2) DEFAULT 0 NOT NULL,\r\n  tax numeric(14,2) DEFAULT 0 NOT NULL,\r\n  total numeric(14,2) NOT NULL,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.sales_returns (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  return_number text NOT NULL,\r\n  invoice_id uuid,\r\n  customer_id uuid,\r\n  warehouse_id uuid NOT NULL,\r\n  subtotal numeric DEFAULT 0 NOT NULL,\r\n  tax numeric DEFAULT 0 NOT NULL,\r\n  total numeric DEFAULT 0 NOT NULL,\r\n  refund_method public.payment_method,\r\n  note text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.sales_return_items (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  return_id uuid NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  quantity numeric NOT NULL,\r\n  unit_price numeric NOT NULL,\r\n  tax numeric DEFAULT 0 NOT NULL,\r\n  total numeric DEFAULT 0 NOT NULL,\r\n  line_type text\r\n)","CREATE TABLE public.customer_payments (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  customer_id uuid NOT NULL,\r\n  invoice_id uuid,\r\n  amount numeric(14,2) NOT NULL,\r\n  payment_method public.payment_method DEFAULT 'cash'::payment_method NOT NULL,\r\n  payment_date date DEFAULT CURRENT_DATE NOT NULL,\r\n  note text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.customer_payment_splits (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  customer_id uuid,\r\n  invoice_id uuid,\r\n  payment_id uuid,\r\n  method public.payment_method NOT NULL,\r\n  amount numeric(14,2) NOT NULL,\r\n  occurred_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","-- ── CONSTRAINTS ───────────────────────────────────────────────────────────\r\nALTER TABLE public.sales_invoices ADD CONSTRAINT \\"sales_invoices_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.sales_invoices ADD CONSTRAINT \\"sales_invoices_invoice_number_key\\" UNIQUE (invoice_number)","ALTER TABLE public.sales_invoice_items ADD CONSTRAINT \\"sales_invoice_items_line_type_valid\\" CHECK (((line_type IS NULL) OR (line_type = ANY (ARRAY['STOCKED_GOOD'::text, 'UNTRACKED_GOOD'::text, 'SERVICE'::text, 'CUSTOMER_OWNED_GOOD'::text, 'AD_HOC_SERVICE'::text]))))","ALTER TABLE public.sales_invoice_items ADD CONSTRAINT \\"sales_invoice_items_stock_effect_valid\\" CHECK (((stock_effect IS NULL) OR (stock_effect = ANY (ARRAY['STOCK_ISSUE'::text, 'STOCK_RECEIPT'::text, 'NONE'::text]))))","ALTER TABLE public.sales_invoice_items ADD CONSTRAINT \\"sales_invoice_items_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.ad_hoc_service_lines ADD CONSTRAINT \\"ad_hoc_service_lines_quantity_check\\" CHECK ((quantity > (0)::numeric))","ALTER TABLE public.ad_hoc_service_lines ADD CONSTRAINT \\"ad_hoc_service_lines_unit_price_check\\" CHECK ((unit_price >= (0)::numeric))","ALTER TABLE public.ad_hoc_service_lines ADD CONSTRAINT \\"ad_hoc_service_lines_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.sales_returns ADD CONSTRAINT \\"sales_returns_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.sales_returns ADD CONSTRAINT \\"sales_returns_return_number_key\\" UNIQUE (return_number)","ALTER TABLE public.sales_return_items ADD CONSTRAINT \\"sales_return_items_quantity_check\\" CHECK ((quantity > (0)::numeric))","ALTER TABLE public.sales_return_items ADD CONSTRAINT \\"sales_return_items_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.customer_payments ADD CONSTRAINT \\"customer_payments_amount_check\\" CHECK ((amount > (0)::numeric))","ALTER TABLE public.customer_payments ADD CONSTRAINT \\"customer_payments_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.customer_payment_splits ADD CONSTRAINT \\"customer_payment_splits_amount_check\\" CHECK ((amount > (0)::numeric))","ALTER TABLE public.customer_payment_splits ADD CONSTRAINT \\"customer_payment_splits_pkey\\" PRIMARY KEY (id)","-- ── INDEXES ───────────────────────────────────────────────────────────────\r\nCREATE INDEX idx_sales_invoice_items_product ON public.sales_invoice_items USING btree (product_id)","CREATE INDEX idx_ad_hoc_service_lines_invoice ON public.ad_hoc_service_lines USING btree (invoice_id)","CREATE INDEX idx_sales_return_items_product ON public.sales_return_items USING btree (product_id)","CREATE INDEX idx_customer_payments_customer ON public.customer_payments USING btree (customer_id, payment_date DESC)","CREATE INDEX idx_customer_payments_invoice ON public.customer_payments USING btree (invoice_id)","CREATE INDEX customer_payment_splits_invoice_idx ON public.customer_payment_splits USING btree (invoice_id, occurred_at DESC)","CREATE INDEX customer_payment_splits_occurred_at_idx ON public.customer_payment_splits USING btree (occurred_at DESC)","-- ── FUNCTIONS ─────────────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb, _sale_date date, _payment_splits jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id         uuid;\r\n  v_total              numeric;\r\n  v_paid               numeric;\r\n  v_user               uuid := auth.uid();\r\n  v_split              record;\r\n  v_component_count    integer := 0;\r\n  v_split_total        numeric := 0;\r\n  v_distinct_methods   integer := 0;\r\n  v_single_method      text;\r\n  v_recorded_method    text := _payment_method;\r\nBEGIN\r\n  IF coalesce(jsonb_typeof(_payment_splits), 'jsonb') <> 'array'\r\n     OR coalesce(jsonb_array_length(_payment_splits), 0) = 0 THEN\r\n    -- No breakdown supplied: exact legacy behaviour.\r\n    RETURN public.create_sale(\r\n      _warehouse_id, _customer_id, _payment_method, _paid, _discount, _note, _items, _sale_date\r\n    );\r\n  END IF;\r\n\r\n  FOR v_split IN\r\n    SELECT (part ->> 'method') AS method,\r\n           coalesce((part ->> 'amount')::numeric, 0) AS amount\r\n    FROM jsonb_array_elements(_payment_splits) AS part\r\n  LOOP\r\n    IF v_split.method IS NULL\r\n      OR v_split.method NOT IN ('cash', 'card', 'bank_transfer', 'mobile_money', 'split') THEN\r\n      RAISE EXCEPTION 'Unsupported payment method: %', v_split.method;\r\n    END IF;\r\n    IF v_split.amount <= 0 THEN\r\n      RAISE EXCEPTION 'Every payment tender component requires a positive amount';\r\n    END IF;\r\n\r\n    v_component_count := v_component_count + 1;\r\n    v_split_total := v_split_total + v_split.amount;\r\n  END LOOP;\r\n\r\n  SELECT count(DISTINCT part ->> 'method'), min(part ->> 'method')\r\n    INTO v_distinct_methods, v_single_method\r\n  FROM jsonb_array_elements(_payment_splits) AS part;\r\n\r\n  -- The tender breakdown and the paid amount must agree, otherwise the invoice\r\n  -- and the recorded payments would drift apart.\r\n  IF round(v_split_total, 2) <> round(coalesce(_paid, 0), 2) THEN\r\n    RAISE EXCEPTION\r\n      'Payment breakdown total % does not match the paid amount %',\r\n      round(v_split_total, 2), round(coalesce(_paid, 0), 2);\r\n  END IF;\r\n\r\n  v_recorded_method := CASE\r\n    WHEN v_distinct_methods > 1 THEN 'split'\r\n    ELSE v_single_method\r\n  END;\r\n\r\n  v_invoice_id := public.create_sale(\r\n    _warehouse_id, _customer_id, v_recorded_method, _paid, _discount, _note, _items, _sale_date\r\n  );\r\n\r\n  SELECT total, paid INTO v_total, v_paid FROM public.sales_invoices WHERE id = v_invoice_id;\r\n\r\n  UPDATE public.sales_invoices\r\n  SET payment_method = v_recorded_method::public.payment_method, updated_at = now()\r\n  WHERE id = v_invoice_id\r\n    AND payment_method IS DISTINCT FROM v_recorded_method::public.payment_method;\r\n\r\n  FOR v_split IN\r\n    SELECT (part ->> 'method') AS method,\r\n           coalesce((part ->> 'amount')::numeric, 0) AS amount\r\n    FROM jsonb_array_elements(_payment_splits) AS part\r\n  LOOP\r\n    INSERT INTO public.customer_payment_splits (\r\n      customer_id, invoice_id, method, amount, occurred_at, created_by\r\n    )\r\n    VALUES (\r\n      _customer_id, v_invoice_id, v_split.method::public.payment_method,\r\n      round(v_split.amount, 2),\r\n      coalesce(_sale_date, current_date)::timestamp + localtime,\r\n      v_user\r\n    );\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'sale.tender_breakdown.recorded', 'sales_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'recorded_payment_method', v_recorded_method,\r\n      'components', v_component_count,\r\n      'tender_total', round(v_split_total, 2),\r\n      'total', v_total,\r\n      'paid', v_paid\r\n    ));\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id     uuid;\r\n  v_invoice_number text;\r\n  v_user           uuid := auth.uid();\r\n  v_line           record;\r\n  v_subtotal       numeric := 0;\r\n  v_tax_total      numeric := 0;\r\n  v_discount       numeric := coalesce(_discount, 0);\r\n  v_total          numeric := 0;\r\n  v_paid           numeric := 0;\r\n  v_outstanding    numeric := 0;\r\n  v_price          numeric;\r\n  v_tax_rate       numeric;\r\n  v_cost           numeric;\r\n  v_customer_balance numeric;\r\n  v_credit_limit   numeric;\r\n  v_line_total     numeric;\r\n  v_line_tax       numeric;\r\n  v_effect         text;\r\n  v_line_type      text;\r\n  v_sellable       boolean;\r\n  v_status         public.invoice_status;\r\n  v_last_item_id   uuid;\r\n  v_available      numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to post sales';\r\n  END IF;\r\n\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'Cart is empty';\r\n  END IF;\r\n\r\n  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN\r\n    RAISE EXCEPTION 'Unsupported payment method';\r\n  END IF;\r\n\r\n  IF v_discount < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot be negative';\r\n  END IF;\r\n\r\n  IF coalesce(_paid, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Paid amount cannot be negative';\r\n  END IF;\r\n\r\n  -- ============================================================== VALIDATION\r\n  -- Only lines whose policy is STOCK_ISSUE are stock-checked. Aggregating by\r\n  -- item and locking the inventory row protects against concurrent checkouts.\r\n  FOR v_line IN\r\n    SELECT r.o_product_id AS product_id, sum(r.o_quantity) AS quantity\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n    WHERE r.o_stock_effect = 'STOCK_ISSUE'\r\n    GROUP BY r.o_product_id\r\n    ORDER BY r.o_product_id\r\n  LOOP\r\n    SELECT i.quantity\r\n      INTO v_available\r\n    FROM public.inventory i\r\n    WHERE i.product_id = v_line.product_id\r\n      AND i.warehouse_id = _warehouse_id\r\n      AND i.owner_type = 'COMPANY'\r\n      AND i.owner_id IS NULL\r\n    FOR UPDATE;\r\n\r\n    v_available := coalesce(v_available, 0);\r\n\r\n    IF v_available < v_line.quantity THEN\r\n      RAISE EXCEPTION\r\n        'Insufficient stock for item %: available %, requested %',\r\n        v_line.product_id, v_available, v_line.quantity\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- Totals. Catalogue price wins for a catalogue item; the operator's price is\r\n  -- used only for ad-hoc service lines.\r\n  FOR v_line IN\r\n    SELECT r.o_product_id    AS product_id,\r\n           r.o_quantity      AS quantity,\r\n           r.o_service_name  AS service_name,\r\n           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,\r\n           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n  LOOP\r\n    IF v_line.quantity IS NULL OR v_line.quantity <= 0 THEN\r\n      RAISE EXCEPTION 'Every sale line requires a positive quantity';\r\n    END IF;\r\n\r\n    IF v_line.product_id IS NULL THEN\r\n      IF coalesce(v_line.service_name, '') = '' THEN\r\n        RAISE EXCEPTION 'Every service line requires a description';\r\n      END IF;\r\n      IF v_line.input_price < 0 OR v_line.input_tax < 0 OR v_line.input_tax > 100 THEN\r\n        RAISE EXCEPTION 'Service line \\"%\\" has an invalid price or tax rate', v_line.service_name;\r\n      END IF;\r\n      v_price    := v_line.input_price;\r\n      v_tax_rate := v_line.input_tax;\r\n    ELSE\r\n      SELECT p.sale_price, p.tax_rate, p.is_sellable\r\n        INTO v_price, v_tax_rate, v_sellable\r\n      FROM public.products p\r\n      WHERE p.id = v_line.product_id AND p.is_active = true\r\n      FOR UPDATE;\r\n\r\n      IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Item % is not available for sale', v_line.product_id;\r\n      END IF;\r\n\r\n      IF v_sellable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as sellable', v_line.product_id;\r\n      END IF;\r\n\r\n      IF v_price < 0 OR v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n        RAISE EXCEPTION 'Item % has invalid pricing or tax configuration', v_line.product_id;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := round(v_line.quantity * v_price, 2);\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + round(v_line_total * v_tax_rate / 100, 2);\r\n  END LOOP;\r\n\r\n  v_total := round(v_subtotal + v_tax_total - v_discount, 2);\r\n  IF v_discount > v_subtotal + v_tax_total OR v_total < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot exceed the invoice amount';\r\n  END IF;\r\n\r\n  IF _customer_id IS NOT NULL THEN\r\n    SELECT balance, credit_limit\r\n      INTO v_customer_balance, v_credit_limit\r\n    FROM public.customers\r\n    WHERE id = _customer_id AND is_active = true\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Selected customer is unavailable';\r\n    END IF;\r\n  END IF;\r\n\r\n  -- Tender above the total is change, not revenue and not credit.\r\n  v_paid := least(coalesce(_paid, 0), v_total);\r\n  v_outstanding := round(v_total - v_paid, 2);\r\n\r\n  IF v_outstanding > 0 AND _customer_id IS NULL THEN\r\n    RAISE EXCEPTION 'A customer is required when the sale has an unpaid amount';\r\n  END IF;\r\n  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN\r\n    RAISE EXCEPTION\r\n      'Credit limit exceeded: current balance %, requested debt %, limit %',\r\n      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);\r\n  END IF;\r\n\r\n  -- حالة الدورة: فاتورة أُنشئت وهي مؤكدة (أثرها المالي واقع بعد الإنشاء).\r\n  -- السداد له عمود مستقل فلا يمحو «مؤكدة».\r\n  v_status := 'confirmed'::public.invoice_status;\r\n\r\n  v_invoice_number := public.next_invoice_number();\r\n\r\n  INSERT INTO public.sales_invoices (\r\n    invoice_number, customer_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_invoice_number, _customer_id, _warehouse_id, v_status,\r\n    -- payment_status يُشتقّ من paid مقابل total، ولا يُكتب يدويًا.\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, v_discount, v_tax_total, v_total, v_paid,\r\n    _payment_method::public.payment_method, nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_invoice_id;\r\n\r\n  -- ================================================================== POSTING\r\n  FOR v_line IN\r\n    SELECT r.o_product_id   AS product_id,\r\n           r.o_quantity     AS quantity,\r\n           r.o_stock_effect AS stock_effect,\r\n           r.o_service_name AS service_name,\r\n           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,\r\n           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax,\r\n           nullif(btrim(coalesce(line ->> 'uom_id', '')), '')::uuid AS uom_id\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n  LOOP\r\n    v_cost := NULL;\r\n\r\n    IF v_line.product_id IS NULL THEN\r\n      v_price     := v_line.input_price;\r\n      v_tax_rate  := v_line.input_tax;\r\n      v_line_type := 'AD_HOC_SERVICE';\r\n      v_effect    := 'NONE';\r\n    ELSE\r\n      SELECT p.sale_price, p.tax_rate, p.cost_price\r\n        INTO v_price, v_tax_rate, v_cost\r\n      FROM public.products p WHERE p.id = v_line.product_id;\r\n\r\n      v_line_type := public.item_line_type(v_line.product_id, false);\r\n      -- Re-derive the effect at posting time so a policy change between\r\n      -- validation and posting cannot slip a movement through unannounced.\r\n      v_effect := public.item_stock_effect(v_line.product_id, 'out');\r\n\r\n      IF v_effect = 'STOCK_ISSUE' THEN\r\n        PERFORM public.post_stock_delta(\r\n          v_line.product_id,\r\n          _warehouse_id,\r\n          -v_line.quantity,\r\n          v_cost,\r\n          'ISSUE'::public.stock_movement_kind,\r\n          'sales_invoice',\r\n          v_invoice_id,\r\n          'POS sale',\r\n          'COMPANY'::public.owner_type,\r\n          NULL,\r\n          'sale'::public.movement_type\r\n        );\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := round(v_line.quantity * v_price, 2);\r\n    v_line_tax   := round(v_line_total * v_tax_rate / 100, 2);\r\n\r\n    INSERT INTO public.sales_invoice_items (\r\n      invoice_id, product_id, description, quantity, unit_price, discount, tax, total,\r\n      line_type, stock_effect, uom_id\r\n    )\r\n    VALUES (\r\n      v_invoice_id,\r\n      v_line.product_id,\r\n      CASE WHEN v_line.product_id IS NULL THEN v_line.service_name ELSE NULL END,\r\n      v_line.quantity, v_price, 0, v_line_tax, v_line_total + v_line_tax,\r\n      v_line_type, v_effect, v_line.uom_id\r\n    )\r\n    RETURNING id INTO v_last_item_id;\r\n\r\n    IF v_line_type = 'AD_HOC_SERVICE' THEN\r\n      INSERT INTO public.ad_hoc_service_lines (\r\n        invoice_id, invoice_item_id, description, quantity, unit_price,\r\n        discount, tax, total, created_by\r\n      )\r\n      VALUES (\r\n        v_invoice_id, v_last_item_id, v_line.service_name, v_line.quantity,\r\n        v_price, 0, v_line_tax, v_line_total + v_line_tax, v_user\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF v_outstanding > 0 THEN\r\n    UPDATE public.customers\r\n    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()\r\n    WHERE id = _customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, debit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',\r\n      now(), v_user, 'sale:' || v_invoice_id, 'قيد بيع آجل'\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'sale.posted', 'sales_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_number,\r\n      'warehouse_id', _warehouse_id,\r\n      'customer_id', _customer_id,\r\n      'payment_method', _payment_method,\r\n      'total', v_total,\r\n      'paid', v_paid,\r\n      'outstanding', v_outstanding,\r\n      'line_count', jsonb_array_length(_items)\r\n    ));\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb, _sale_date date)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id uuid;\r\n  v_posted_at  timestamptz;\r\nBEGIN\r\n  IF _sale_date IS NULL THEN\r\n    RAISE EXCEPTION 'Sale date is required';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'Cart is empty';\r\n  END IF;\r\n\r\n  -- All validation, stock movement, ledger posting and auditing happen here.\r\n  v_invoice_id := public.create_sale(\r\n    _warehouse_id, _customer_id, _payment_method, _paid, _discount, _note, _items\r\n  );\r\n\r\n  v_posted_at := _sale_date::timestamp + localtime;\r\n\r\n  UPDATE public.sales_invoices\r\n  SET created_at = v_posted_at, updated_at = now()\r\n  WHERE id = v_invoice_id;\r\n\r\n  UPDATE public.stock_movements\r\n  SET created_at = v_posted_at\r\n  WHERE source_type = 'sales_invoice' AND source_id = v_invoice_id;\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.create_sales_return(_invoice_id uuid, _warehouse_id uuid, _customer_id uuid, _refund_method text, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id        uuid;\r\n  v_no        text;\r\n  v_user      uuid := auth.uid();\r\n  v_item      jsonb;\r\n  v_sub       numeric := 0;\r\n  v_tax       numeric := 0;\r\n  v_tot       numeric := 0;\r\n  v_qty       numeric;\r\n  v_price     numeric;\r\n  v_tr        numeric;\r\n  v_lt        numeric;\r\n  v_ltax      numeric;\r\n  v_p         uuid;\r\n  v_effect    text;\r\n  v_type      text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_qty   := (v_item ->> 'quantity')::numeric;\r\n    v_price := (v_item ->> 'unit_price')::numeric;\r\n    v_tr    := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n    v_lt    := v_qty * v_price;\r\n    v_ltax  := v_lt * v_tr / 100;\r\n    v_sub   := v_sub + v_lt;\r\n    v_tax   := v_tax + v_ltax;\r\n  END LOOP;\r\n  v_tot := v_sub + v_tax;\r\n  v_no  := public.next_sales_return_number();\r\n\r\n  INSERT INTO public.sales_returns (\r\n    return_number, invoice_id, customer_id, warehouse_id,\r\n    subtotal, tax, total, refund_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_no, _invoice_id, _customer_id, _warehouse_id,\r\n    v_sub, v_tax, v_tot, _refund_method::public.payment_method,\r\n    nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_p     := (v_item ->> 'product_id')::uuid;\r\n    v_qty   := (v_item ->> 'quantity')::numeric;\r\n    v_price := (v_item ->> 'unit_price')::numeric;\r\n    v_tr    := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n    v_lt    := v_qty * v_price;\r\n    v_ltax  := v_lt * v_tr / 100;\r\n\r\n    v_type   := public.item_line_type(v_p, false);\r\n    v_effect := public.item_stock_effect(v_p, 'in');\r\n\r\n    INSERT INTO public.sales_return_items (\r\n      return_id, product_id, quantity, unit_price, tax, total, line_type\r\n    )\r\n    VALUES (v_id, v_p, v_qty, v_price, v_ltax, v_lt + v_ltax, v_type);\r\n\r\n    -- Only a tracked good comes back into stock.\r\n    IF v_effect = 'STOCK_RECEIPT' THEN\r\n      PERFORM public.post_stock_delta(\r\n        v_p,\r\n        _warehouse_id,\r\n        v_qty,\r\n        v_price,\r\n        'RECEIPT'::public.stock_movement_kind,\r\n        'sales_return',\r\n        v_id,\r\n        'Sales return',\r\n        'COMPANY'::public.owner_type,\r\n        NULL,\r\n        'sale_return'::public.movement_type\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF _customer_id IS NOT NULL THEN\r\n    UPDATE public.customers\r\n    SET balance = greatest(balance - v_tot, 0), updated_at = now()\r\n    WHERE id = _customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, credit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      _customer_id, 'return', round(v_tot, 2), v_id, 'sales_return',\r\n      now(), v_user, 'return:' || v_id, 'مرتجع مبيعات'\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'sales_return.posted', 'sales_return', v_id,\r\n    jsonb_build_object(\r\n      'return_number', v_no,\r\n      'invoice_id', _invoice_id,\r\n      'customer_id', _customer_id,\r\n      'total', v_tot\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","-- NOTE: next_invoice_number() and next_sales_return_number() are defined ONCE, in\r\n-- 14_document_numbering_engine.sql. This file used to define its own copies\r\n-- reading sales_invoice_seq / sales_return_seq and company_settings' prefix\r\n-- columns — a second, competing numbering design. The engine now owns the\r\n-- numbering table, the sequences and the format, so keeping those bodies here\r\n-- would let the two designs disagree silently (R-13/R-14). Name and signature are\r\n-- unchanged, so no caller breaks.\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- record_customer_payment — سند تحصيل مستحقات.\r\n--\r\n-- ⚠️ مبدأ حاكم: **التحصيل لا يتحوّل إلى دفعة مقدمة بصمت.**\r\n--   الدفعة العادية محدودة بالفاتورة المختارة أو بإجمالي مستحقات العميل. وإن\r\n--   أراد المشغّل دفعة مقدمة حقيقية فهناك دالة صريحة منفصلة\r\n--   `record_customer_advance_payment` تحمل الاسم نفسه وتُنشئ سجلًا مميّزًا.\r\n--   قبل هذا، كان أي فائض يُصنَّف \\"دفعة مقدمة\\" ضمنًا بلا إقرار من أحد — وهو\r\n--   ما يُفسد مطابقة كشف الحساب لأن المستند يقول شيئًا والدفتر يقول آخر.\r\n--\r\n-- ما جاء من origin/main: منطق منع التحوّل الصامت، وفحص الرصيد الكلي قبل\r\n-- التوزيع، والدالة الصريحة للدفعة المقدمة.\r\n-- ما أُبقي من نسختنا الأحدث: اشتقاق payment_status عبر\r\n-- `derive_payment_status` (فلا تُكتب حالة السداد يدويًا)، وحارس طريقة الدفع\r\n-- الموحّد `resolve_writable_payment_method` بدل القائمة الحرفية القديمة،\r\n-- وإبقاء status الدورة على 'confirmed' لأن الدفع لا يغيّرها.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.record_customer_payment(_customer_id uuid, _invoice_id uuid, _amount numeric, _method text, _payment_date date, _note text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id uuid;\r\n  v_user uuid := auth.uid();\r\n  v_invoice record;\r\n  v_customer_balance numeric;\r\n  v_remaining numeric := round(coalesce(_amount, 0), 2);\r\n  v_allocation numeric;\r\n  v_outstanding numeric := 0;\r\n  v_stored_method text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'accountant')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to record customer payments';\r\n  END IF;\r\n\r\n  IF _customer_id IS NULL OR v_remaining <= 0 THEN\r\n    RAISE EXCEPTION 'A customer and a positive amount are required';\r\n  END IF;\r\n\r\n  -- الحارس الموحّد: يطبّع القيمة عبر كتالوج طرق الدفع ويعيد القيمة المخزّنة.\r\n  -- يستبدل القائمة الحرفية القديمة NOT IN ('cash','card',...) التي كانت ترفض\r\n  -- كل طريقة يمنية جديدة (بنك الكريمي، جوالى، جيب...).\r\n  v_stored_method := public.resolve_writable_payment_method(\r\n    _method, 'customer_collection', true\r\n  );\r\n\r\n  -- صف العميل هو قفل التسلسل لكل سندات هذا العميل: يمنع تحصيلين متزامنين من\r\n  -- استهلاك نفس المستحق.\r\n  SELECT balance\r\n    INTO v_customer_balance\r\n  FROM public.customers\r\n  WHERE id = _customer_id\r\n    AND is_active = true\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Customer is unavailable';\r\n  END IF;\r\n\r\n  IF _invoice_id IS NOT NULL THEN\r\n    SELECT id, total, paid, customer_id\r\n      INTO v_invoice\r\n    FROM public.sales_invoices\r\n    WHERE id = _invoice_id\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Invoice not found';\r\n    END IF;\r\n\r\n    IF v_invoice.customer_id IS DISTINCT FROM _customer_id THEN\r\n      RAISE EXCEPTION 'Invoice does not belong to this customer';\r\n    END IF;\r\n\r\n    IF v_invoice.total - v_invoice.paid <= 0 THEN\r\n      RAISE EXCEPTION 'Invoice has no outstanding balance';\r\n    END IF;\r\n\r\n    IF v_remaining > v_invoice.total - v_invoice.paid THEN\r\n      RAISE EXCEPTION 'Payment exceeds the invoice outstanding balance';\r\n    END IF;\r\n\r\n    INSERT INTO public.customer_payments (\r\n      customer_id, invoice_id, amount, payment_method, payment_date, note, created_by\r\n    )\r\n    VALUES (\r\n      _customer_id, _invoice_id, v_remaining, v_stored_method::public.payment_method,\r\n      coalesce(_payment_date, current_date), nullif(trim(_note), ''), v_user\r\n    )\r\n    RETURNING id INTO v_id;\r\n\r\n    INSERT INTO public.customer_ledger(customer_id, entry_type, credit, reference_id, reference_type, occurred_at, created_by, source_key, note)\r\n    VALUES (_customer_id, 'payment', v_remaining, v_id, 'customer_payment', coalesce(_payment_date, current_date)::timestamptz, v_user, 'payment:' || v_id, coalesce(nullif(trim(_note), ''), 'دفعة عميل'))\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n\r\n    UPDATE public.sales_invoices\r\n    SET paid = paid + v_remaining,\r\n        -- حالة الدورة تبقى «مؤكدة» — الدفع لا يغيّرها.\r\n        -- حالة السداد تُحدّث في عمودها المستقل.\r\n        status = 'confirmed'::public.invoice_status,\r\n        payment_status = public.derive_payment_status(paid + v_remaining, total),\r\n        updated_at = now()\r\n    WHERE id = _invoice_id;\r\n  ELSE\r\n    -- لا فاتورة مختارة: تُستهلك أقدم الذمم أولًا. نفحص الإجمالي **قبل**\r\n    -- التوزيع كي لا يتحوّل أي فائض بالخطأ إلى دفعة مقدمة.\r\n    SELECT coalesce(sum(total - paid), 0)\r\n      INTO v_outstanding\r\n    FROM public.sales_invoices\r\n    WHERE customer_id = _customer_id\r\n      AND total > paid\r\n      AND status NOT IN ('cancelled'::public.invoice_status, 'returned'::public.invoice_status);\r\n\r\n    -- عميل قديم قد يكون له رصيد افتتاحي حقيقي بلا فواتير فردية. يبقى قابلًا\r\n    -- للتحصيل حتى ذلك الرصيد، لكن لا يُصنَّف «دفعة مقدمة» ضمنًا أبدًا.\r\n    IF v_outstanding <= 0 AND coalesce(v_customer_balance, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Customer has no outstanding balance. Record an explicit advance payment instead.';\r\n    END IF;\r\n    IF v_outstanding > 0 AND v_remaining > v_outstanding THEN\r\n      RAISE EXCEPTION 'Payment exceeds the customer outstanding balance';\r\n    END IF;\r\n\r\n    IF v_outstanding <= 0 THEN\r\n      IF v_remaining > v_customer_balance THEN\r\n        RAISE EXCEPTION 'Payment exceeds the customer outstanding balance';\r\n      END IF;\r\n\r\n      INSERT INTO public.customer_payments (\r\n        customer_id, invoice_id, amount, payment_method, payment_date, note, created_by\r\n      )\r\n      VALUES (\r\n        _customer_id, NULL, v_remaining, v_stored_method::public.payment_method,\r\n        coalesce(_payment_date, current_date),\r\n        coalesce(nullif(trim(_note), ''), 'سداد رصيد غير مرتبط بفاتورة'), v_user\r\n      )\r\n      RETURNING id INTO v_id;\r\n\r\n      INSERT INTO public.customer_ledger(customer_id, entry_type, credit, reference_id, reference_type, occurred_at, created_by, source_key, note)\r\n      VALUES (_customer_id, 'payment', v_remaining, v_id, 'customer_payment', coalesce(_payment_date, current_date)::timestamptz, v_user, 'payment:' || v_id, coalesce(nullif(trim(_note), ''), 'سداد رصيد غير مرتبط بفاتورة'))\r\n      ON CONFLICT (source_key) DO NOTHING;\r\n\r\n      v_remaining := 0;\r\n    END IF;\r\n\r\n    FOR v_invoice IN\r\n      SELECT id, total, paid\r\n      FROM public.sales_invoices\r\n      WHERE customer_id = _customer_id\r\n        AND total > paid\r\n        AND status NOT IN ('cancelled'::public.invoice_status, 'returned'::public.invoice_status)\r\n      ORDER BY created_at, id\r\n      FOR UPDATE\r\n    LOOP\r\n      EXIT WHEN v_remaining <= 0;\r\n\r\n      v_allocation := least(v_remaining, v_invoice.total - v_invoice.paid);\r\n\r\n      INSERT INTO public.customer_payments (\r\n        customer_id, invoice_id, amount, payment_method, payment_date, note, created_by\r\n      )\r\n      VALUES (\r\n        _customer_id, v_invoice.id, v_allocation, v_stored_method::public.payment_method,\r\n        coalesce(_payment_date, current_date), nullif(trim(_note), ''), v_user\r\n      )\r\n      RETURNING id INTO v_id;\r\n\r\n      INSERT INTO public.customer_ledger(customer_id, entry_type, credit, reference_id, reference_type, occurred_at, created_by, source_key, note)\r\n      VALUES (_customer_id, 'payment', v_allocation, v_id, 'customer_payment', coalesce(_payment_date, current_date)::timestamptz, v_user, 'payment:' || v_id, coalesce(nullif(trim(_note), ''), 'دفعة عميل'))\r\n      ON CONFLICT (source_key) DO NOTHING;\r\n\r\n      UPDATE public.sales_invoices\r\n      SET paid = paid + v_allocation,\r\n          status = 'confirmed'::public.invoice_status,\r\n          payment_status = public.derive_payment_status(paid + v_allocation, total),\r\n          updated_at = now()\r\n      WHERE id = v_invoice.id;\r\n\r\n      v_remaining := v_remaining - v_allocation;\r\n    END LOOP;\r\n  END IF;\r\n\r\n  UPDATE public.customers\r\n  SET balance = round(coalesce(balance, 0) - _amount, 2), updated_at = now()\r\n  WHERE id = _customer_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (\r\n    v_user,\r\n    'customer_payment.recorded',\r\n    'customer',\r\n    _customer_id,\r\n    jsonb_build_object(\r\n      'invoice_id', _invoice_id,\r\n      'amount', _amount,\r\n      'method', v_stored_method,\r\n      'payment_date', coalesce(_payment_date, current_date),\r\n      'allocation', CASE WHEN _invoice_id IS NULL THEN 'oldest_first' ELSE 'selected_invoice' END\r\n    )\r\n  );\r\n\r\n  RETURN v_id;\r\nEND;\r\n$function$","COMMENT ON FUNCTION public.record_customer_payment(uuid, uuid, numeric, text, date, text) IS\r\n  'تحصيل مستحقات فقط: يحدّ المبلغ بالفاتورة أو بإجمالي الذمم، ويوزّع تلقائيًا من أقدم الفواتير، ولا يحوّل الفائض إلى دفعة مقدمة بصمت.'","-- ---------------------------------------------------------------------------\r\n-- record_customer_advance_payment — دفعة مقدمة **صريحة**.\r\n--\r\n-- منفصلة عن سند التحصيل عن قصد: الدفعة المقدمة لا تسدّد فواتير قائمة تلقائيًا،\r\n-- بل تُقيَّد في الدفتر بسجل متميّز (`credit` + `advance-payment:` prefix) ليظهر\r\n-- أثرها في كشف الحساب كرصيد لصالح العميل، لا كسداد.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.record_customer_advance_payment(_customer_id uuid, _amount numeric, _method text, _payment_date date, _note text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id uuid;\r\n  v_user uuid := auth.uid();\r\n  v_stored_method text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'accountant')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to record customer payments';\r\n  END IF;\r\n\r\n  IF _customer_id IS NULL OR coalesce(_amount, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'A customer and a positive advance amount are required';\r\n  END IF;\r\n\r\n  v_stored_method := public.resolve_writable_payment_method(\r\n    _method, 'customer_collection', true\r\n  );\r\n\r\n  PERFORM 1 FROM public.customers\r\n  WHERE id = _customer_id AND is_active = true\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Customer is unavailable';\r\n  END IF;\r\n\r\n  INSERT INTO public.customer_payments (\r\n    customer_id, invoice_id, amount, payment_method, payment_date, note, created_by\r\n  )\r\n  VALUES (\r\n    _customer_id, NULL, round(_amount, 2), v_stored_method::public.payment_method,\r\n    coalesce(_payment_date, current_date),\r\n    coalesce(nullif(trim(_note), ''), 'دفعة مقدمة'), v_user\r\n  )\r\n  RETURNING id INTO v_id;\r\n\r\n  UPDATE public.customers\r\n  SET balance = round(coalesce(balance, 0) - _amount, 2), updated_at = now()\r\n  WHERE id = _customer_id;\r\n\r\n  INSERT INTO public.customer_ledger(customer_id, entry_type, credit, reference_id, reference_type, occurred_at, created_by, source_key, note)\r\n  VALUES (_customer_id, 'credit', round(_amount, 2), v_id, 'customer_payment', coalesce(_payment_date, current_date)::timestamptz, v_user, 'advance-payment:' || v_id, coalesce(nullif(trim(_note), ''), 'دفعة مقدمة'))\r\n  ON CONFLICT (source_key) DO NOTHING;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (\r\n    v_user, 'customer_advance_payment.recorded', 'customer', _customer_id,\r\n    jsonb_build_object('amount', _amount, 'method', v_stored_method, 'payment_date', coalesce(_payment_date, current_date))\r\n  );\r\n\r\n  RETURN v_id;\r\nEND;\r\n$function$","COMMENT ON FUNCTION public.record_customer_advance_payment(uuid, numeric, text, date, text) IS\r\n  'دفعة مقدمة صريحة للعميل؛ لا تسدّد فواتير قائمة تلقائيًا، بل تُقيَّد كرصيد لصالحه في دفتر العملاء.'","CREATE OR REPLACE FUNCTION public.resolve_sale_line(p_line jsonb, OUT o_product_id uuid, OUT o_quantity numeric, OUT o_line_type text, OUT o_stock_effect text, OUT o_service_name text)\r\n RETURNS record\r\n LANGUAGE plpgsql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_is_service_flag boolean := coalesce((p_line ->> 'is_service')::boolean, false);\r\n  v_exists boolean;\r\nBEGIN\r\n  o_product_id   := nullif(btrim(coalesce(p_line ->> 'product_id', '')), '')::uuid;\r\n  o_quantity     := (p_line ->> 'quantity')::numeric;\r\n  o_service_name := nullif(btrim(coalesce(p_line ->> 'name', '')), '');\r\n\r\n  IF o_product_id IS NULL THEN\r\n    -- No product reference at all: this is an ad-hoc service line.\r\n    o_line_type    := 'AD_HOC_SERVICE';\r\n    o_stock_effect := 'NONE';\r\n    RETURN;\r\n  END IF;\r\n\r\n  SELECT true INTO v_exists FROM public.products p WHERE p.id = o_product_id;\r\n\r\n  IF v_exists IS NOT TRUE THEN\r\n    IF v_is_service_flag THEN\r\n      -- Legacy POS sent synthetic ids such as \\"service-<uuid>\\".\r\n      o_product_id   := NULL;\r\n      o_line_type    := 'AD_HOC_SERVICE';\r\n      o_stock_effect := 'NONE';\r\n      RETURN;\r\n    END IF;\r\n    RAISE EXCEPTION 'Item % does not exist', o_product_id;\r\n  END IF;\r\n\r\n  o_line_type    := public.item_line_type(o_product_id, false);\r\n  o_stock_effect := public.item_stock_effect(o_product_id, 'out');\r\nEND $function$","CREATE OR REPLACE FUNCTION public.sales_invoice_tender_breakdown(_invoice_id uuid)\r\n RETURNS TABLE(method text, amount numeric)\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT s.method::text, s.amount\r\n  FROM public.customer_payment_splits AS s\r\n  WHERE s.invoice_id = _invoice_id\r\n  ORDER BY s.amount DESC;\r\n$function$","CREATE OR REPLACE FUNCTION public.sales_line_cost(p_item_id uuid, p_invoice_id uuid, p_quantity numeric, p_line_type text DEFAULT NULL::text)\r\n RETURNS numeric\r\n LANGUAGE plpgsql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_movement_cost numeric;\r\n  v_costing       public.costing_method;\r\n  v_reference     numeric;\r\nBEGIN\r\n  -- A service line carries no inventory cost. That is not a missing value.\r\n  IF p_item_id IS NULL OR p_line_type IN ('SERVICE', 'AD_HOC_SERVICE') THEN\r\n    RETURN 0;\r\n  END IF;\r\n\r\n  -- (a) The real cost of what actually left the warehouse for this invoice.\r\n  SELECT m.unit_cost\r\n    INTO v_movement_cost\r\n  FROM public.stock_movements m\r\n  WHERE m.product_id = p_item_id\r\n    AND m.reference_id = p_invoice_id\r\n    AND m.reference_type = 'sales_invoice'\r\n    AND m.movement_kind = 'ISSUE'\r\n    AND m.unit_cost IS NOT NULL\r\n  ORDER BY m.created_at DESC\r\n  LIMIT 1;\r\n\r\n  IF v_movement_cost IS NOT NULL THEN\r\n    RETURN round(coalesce(p_quantity, 0) * v_movement_cost, 2);\r\n  END IF;\r\n\r\n  -- (b) No movement cost. Only a declared STANDARD cost is a legitimate\r\n  -- fallback, because the business chose that policy explicitly.\r\n  SELECT COALESCE(ci.costing_method, p.costing_method),\r\n         COALESCE(ci.default_cost, p.cost_price)\r\n    INTO v_costing, v_reference\r\n  FROM public.products p\r\n  LEFT JOIN public.company_items ci\r\n    ON ci.item_id = p.id AND ci.company_id = 1 AND ci.is_active\r\n  WHERE p.id = p_item_id;\r\n\r\n  IF v_costing = 'STANDARD' AND v_reference IS NOT NULL THEN\r\n    RETURN round(coalesce(p_quantity, 0) * v_reference, 2);\r\n  END IF;\r\n\r\n  -- (c) Unknown. Deliberately NULL, never a guess.\r\n  RETURN NULL;\r\nEND $function$"}	sales_and_returns
07	{"-- ============================================================================\r\n-- 08_purchasing_and_returns.sql\r\n--\r\n-- المشتريات ومرتجعاتها.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── TABLES ────────────────────────────────────────────────────────────────\r\nCREATE TABLE public.purchase_invoices (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  invoice_number text NOT NULL,\r\n  supplier_id uuid,\r\n  warehouse_id uuid,\r\n  -- حالة الدورة: مسودة / مؤكدة / ملغاة. لا تُكتب من مبلغ السداد.\r\n  status public.invoice_status DEFAULT 'draft'::invoice_status NOT NULL,\r\n  -- حالة السداد، منفصلة، وتُشتقّ من (paid مقابل total).\r\n  payment_status public.payment_status DEFAULT 'unpaid'::payment_status NOT NULL,\r\n  subtotal numeric(14,2) DEFAULT 0 NOT NULL,\r\n  discount numeric(14,2) DEFAULT 0 NOT NULL,\r\n  tax numeric(14,2) DEFAULT 0 NOT NULL,\r\n  total numeric(14,2) DEFAULT 0 NOT NULL,\r\n  paid numeric(14,2) DEFAULT 0 NOT NULL,\r\n  payment_method public.payment_method,\r\n  note text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.purchase_invoice_items (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  invoice_id uuid NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  quantity numeric(14,3) NOT NULL,\r\n  unit_cost numeric(14,2) NOT NULL,\r\n  discount numeric(14,2) DEFAULT 0 NOT NULL,\r\n  tax numeric(14,2) DEFAULT 0 NOT NULL,\r\n  total numeric(14,2) NOT NULL,\r\n  line_type text,\r\n  stock_effect text\r\n)","CREATE TABLE public.purchase_returns (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  return_number text NOT NULL,\r\n  invoice_id uuid,\r\n  supplier_id uuid,\r\n  warehouse_id uuid NOT NULL,\r\n  subtotal numeric DEFAULT 0 NOT NULL,\r\n  tax numeric DEFAULT 0 NOT NULL,\r\n  total numeric DEFAULT 0 NOT NULL,\r\n  refund_method public.payment_method,\r\n  note text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.purchase_return_items (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  return_id uuid NOT NULL,\r\n  product_id uuid NOT NULL,\r\n  quantity numeric NOT NULL,\r\n  unit_cost numeric NOT NULL,\r\n  tax numeric DEFAULT 0 NOT NULL,\r\n  total numeric DEFAULT 0 NOT NULL,\r\n  line_type text\r\n)","-- ── CONSTRAINTS ───────────────────────────────────────────────────────────\r\nALTER TABLE public.purchase_invoices ADD CONSTRAINT \\"purchase_invoices_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.purchase_invoices ADD CONSTRAINT \\"purchase_invoices_invoice_number_key\\" UNIQUE (invoice_number)","ALTER TABLE public.purchase_invoice_items ADD CONSTRAINT \\"purchase_invoice_items_line_type_valid\\" CHECK (((line_type IS NULL) OR (line_type = ANY (ARRAY['STOCKED_GOOD'::text, 'UNTRACKED_GOOD'::text, 'SERVICE'::text, 'CUSTOMER_OWNED_GOOD'::text, 'AD_HOC_SERVICE'::text]))))","ALTER TABLE public.purchase_invoice_items ADD CONSTRAINT \\"purchase_invoice_items_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.purchase_returns ADD CONSTRAINT \\"purchase_returns_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.purchase_returns ADD CONSTRAINT \\"purchase_returns_return_number_key\\" UNIQUE (return_number)","ALTER TABLE public.purchase_return_items ADD CONSTRAINT \\"purchase_return_items_quantity_check\\" CHECK ((quantity > (0)::numeric))","ALTER TABLE public.purchase_return_items ADD CONSTRAINT \\"purchase_return_items_pkey\\" PRIMARY KEY (id)","-- ── INDEXES ───────────────────────────────────────────────────────────────\r\nCREATE INDEX idx_purchase_invoice_items_product ON public.purchase_invoice_items USING btree (product_id)","CREATE INDEX idx_purchase_return_items_product ON public.purchase_return_items USING btree (product_id)","-- ── FUNCTIONS ─────────────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.create_purchase(_warehouse_id uuid, _supplier_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id     uuid;\r\n  v_invoice_no     text;\r\n  v_user           uuid := auth.uid();\r\n  v_item           jsonb;\r\n  v_subtotal       numeric := 0;\r\n  v_tax_total      numeric := 0;\r\n  v_total          numeric := 0;\r\n  v_qty            numeric;\r\n  v_cost           numeric;\r\n  v_tax_rate       numeric;\r\n  v_line_total     numeric;\r\n  v_line_tax       numeric;\r\n  v_product        uuid;\r\n  v_effect         text;\r\n  v_type           text;\r\n  v_purchasable    boolean;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse required';\r\n  END IF;\r\n  IF _supplier_id IS NULL THEN\r\n    RAISE EXCEPTION 'Supplier required';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  ------------------------------------------------------------------ validate\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    IF v_qty IS NULL OR v_qty <= 0 THEN\r\n      RAISE EXCEPTION 'Invalid quantity';\r\n    END IF;\r\n    IF v_cost IS NULL OR v_cost < 0 THEN\r\n      RAISE EXCEPTION 'Invalid unit cost';\r\n    END IF;\r\n    IF v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n      RAISE EXCEPTION 'Invalid tax rate';\r\n    END IF;\r\n    IF (v_item ->> 'product_id') IS NOT NULL THEN\r\n      SELECT p.is_purchasable INTO v_purchasable\r\n      FROM public.products p WHERE p.id = (v_item ->> 'product_id')::uuid;\r\n\r\n      IF v_purchasable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as purchasable', v_item ->> 'product_id';\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + v_line_tax;\r\n  END LOOP;\r\n\r\n  v_total := v_subtotal + v_tax_total - coalesce(_discount, 0);\r\n  v_invoice_no := public.next_purchase_number();\r\n\r\n  INSERT INTO public.purchase_invoices (\r\n    invoice_number, supplier_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_invoice_no, _supplier_id, _warehouse_id,\r\n    -- حالة الدورة: مشتريات أُنشئت مؤكدة — أثرها المخزني والمالي واقع.\r\n    'confirmed'::public.invoice_status,\r\n    -- حالة السداد مشتقّة، لا مكتوبة من مبلغ الدفع مباشرةً.\r\n    public.derive_payment_status(coalesce(_paid, 0), v_total),\r\n    v_subtotal, coalesce(_discount, 0), v_tax_total, v_total, coalesce(_paid, 0),\r\n    _payment_method::public.payment_method, nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_invoice_id;\r\n\r\n  --------------------------------------------------------------------- post\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_product  := (v_item ->> 'product_id')::uuid;\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n\r\n    SELECT r.o_line_type, r.o_stock_effect\r\n      INTO v_type, v_effect\r\n    FROM public.resolve_purchase_line(v_item) AS r;\r\n\r\n    INSERT INTO public.purchase_invoice_items (\r\n      invoice_id, product_id, quantity, unit_cost, discount, tax, total,\r\n      line_type, stock_effect\r\n    )\r\n    VALUES (\r\n      v_invoice_id, v_product, v_qty, v_cost, 0, v_line_tax, v_line_total + v_line_tax,\r\n      v_type, v_effect\r\n    );\r\n\r\n    -- Rule 5: only a TRACKED good increases stock. A service or an untracked\r\n    -- good is a pure expense: it changes no balance and no valuation.\r\n    IF v_effect = 'STOCK_RECEIPT' AND v_product IS NOT NULL THEN\r\n      PERFORM public.post_stock_delta(\r\n        v_product,\r\n        _warehouse_id,\r\n        v_qty,\r\n        v_cost,\r\n        'RECEIPT'::public.stock_movement_kind,\r\n        'purchase_invoice',\r\n        v_invoice_id,\r\n        'Purchase receipt',\r\n        'COMPANY'::public.owner_type,\r\n        NULL,\r\n        'purchase'::public.movement_type\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF coalesce(_paid, 0) < v_total THEN\r\n    UPDATE public.suppliers\r\n    SET balance = balance + (v_total - coalesce(_paid, 0)), updated_at = now()\r\n    WHERE id = _supplier_id;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'purchase.posted', 'purchase_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_no,\r\n      'supplier_id', _supplier_id,\r\n      'warehouse_id', _warehouse_id,\r\n      'total', v_total,\r\n      'paid', coalesce(_paid, 0),\r\n      'line_count', jsonb_array_length(_items)\r\n    ));\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.create_purchase_return(_invoice_id uuid, _warehouse_id uuid, _supplier_id uuid, _refund_method text, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id     uuid;\r\n  v_no     text;\r\n  v_user   uuid := auth.uid();\r\n  v_item   jsonb;\r\n  v_sub    numeric := 0;\r\n  v_tax    numeric := 0;\r\n  v_tot    numeric := 0;\r\n  v_qty    numeric;\r\n  v_cost   numeric;\r\n  v_tr     numeric;\r\n  v_lt     numeric;\r\n  v_ltax   numeric;\r\n  v_p      uuid;\r\n  v_effect text;\r\n  v_type   text;\r\n  v_avail  numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_p    := (v_item ->> 'product_id')::uuid;\r\n    v_qty  := (v_item ->> 'quantity')::numeric;\r\n    v_cost := (v_item ->> 'unit_cost')::numeric;\r\n    v_tr   := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    v_effect := public.item_stock_effect(v_p, 'out');\r\n\r\n    -- Only a tracked good has stock to send back.\r\n    IF v_effect = 'STOCK_ISSUE' THEN\r\n      SELECT i.quantity INTO v_avail\r\n      FROM public.inventory i\r\n      WHERE i.product_id = v_p\r\n        AND i.warehouse_id = _warehouse_id\r\n        AND i.owner_type = 'COMPANY'\r\n        AND i.owner_id IS NULL;\r\n\r\n      IF coalesce(v_avail, 0) < v_qty THEN\r\n        RAISE EXCEPTION 'Insufficient stock for item %', v_p;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_lt   := v_qty * v_cost;\r\n    v_ltax := v_lt * v_tr / 100;\r\n    v_sub  := v_sub + v_lt;\r\n    v_tax  := v_tax + v_ltax;\r\n  END LOOP;\r\n  v_tot := v_sub + v_tax;\r\n  v_no  := public.next_purchase_return_number();\r\n\r\n  INSERT INTO public.purchase_returns (\r\n    return_number, invoice_id, supplier_id, warehouse_id,\r\n    subtotal, tax, total, refund_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_no, _invoice_id, _supplier_id, _warehouse_id,\r\n    v_sub, v_tax, v_tot, _refund_method::public.payment_method,\r\n    nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_p    := (v_item ->> 'product_id')::uuid;\r\n    v_qty  := (v_item ->> 'quantity')::numeric;\r\n    v_cost := (v_item ->> 'unit_cost')::numeric;\r\n    v_tr   := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n    v_lt   := v_qty * v_cost;\r\n    v_ltax := v_lt * v_tr / 100;\r\n\r\n    v_type   := public.item_line_type(v_p, false);\r\n    v_effect := public.item_stock_effect(v_p, 'out');\r\n\r\n    INSERT INTO public.purchase_return_items (\r\n      return_id, product_id, quantity, unit_cost, tax, total, line_type\r\n    )\r\n    VALUES (v_id, v_p, v_qty, v_cost, v_ltax, v_lt + v_ltax, v_type);\r\n\r\n    IF v_effect = 'STOCK_ISSUE' THEN\r\n      PERFORM public.post_stock_delta(\r\n        v_p,\r\n        _warehouse_id,\r\n        -v_qty,\r\n        v_cost,\r\n        'ISSUE'::public.stock_movement_kind,\r\n        'purchase_return',\r\n        v_id,\r\n        'Purchase return',\r\n        'COMPANY'::public.owner_type,\r\n        NULL,\r\n        'purchase_return'::public.movement_type\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF _supplier_id IS NOT NULL THEN\r\n    UPDATE public.suppliers\r\n    SET balance = greatest(balance - v_tot, 0), updated_at = now()\r\n    WHERE id = _supplier_id;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'purchase_return.posted', 'purchase_return', v_id,\r\n    jsonb_build_object(\r\n      'return_number', v_no,\r\n      'invoice_id', _invoice_id,\r\n      'supplier_id', _supplier_id,\r\n      'total', v_tot\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","-- NOTE: next_purchase_number() and next_purchase_return_number() are defined ONCE,\r\n-- in 14_document_numbering_engine.sql. This file used to define its own copies\r\n-- reading purchase_invoice_seq / purchase_return_seq and company_settings' prefix\r\n-- columns — a second, competing numbering design. The engine now owns the\r\n-- numbering table, the sequences and the format, so a second definition here would\r\n-- be dead code whose body could silently drift from the engine's (R-13/R-14). The\r\n-- name and signature are unchanged, so no caller breaks.\r\n\r\nCREATE OR REPLACE FUNCTION public.resolve_purchase_line(p_line jsonb, OUT o_product_id uuid, OUT o_quantity numeric, OUT o_line_type text, OUT o_stock_effect text)\r\n RETURNS record\r\n LANGUAGE plpgsql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_is_service_flag boolean := coalesce((p_line ->> 'is_service')::boolean, false);\r\n  v_nature public.item_nature;\r\nBEGIN\r\n  o_product_id := nullif(btrim(coalesce(p_line ->> 'product_id', '')), '')::uuid;\r\n  o_quantity   := (p_line ->> 'quantity')::numeric;\r\n\r\n  IF o_product_id IS NULL THEN\r\n    o_line_type    := 'AD_HOC_SERVICE';\r\n    o_stock_effect := 'NONE';\r\n    RETURN;\r\n  END IF;\r\n\r\n  SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = o_product_id;\r\n\r\n  IF v_nature IS NULL THEN\r\n    IF v_is_service_flag THEN\r\n      o_product_id   := NULL;\r\n      o_line_type    := 'AD_HOC_SERVICE';\r\n      o_stock_effect := 'NONE';\r\n      RETURN;\r\n    END IF;\r\n    RAISE EXCEPTION 'Item % does not exist', o_product_id;\r\n  END IF;\r\n\r\n  o_line_type    := public.item_line_type(o_product_id, false);\r\n  o_stock_effect := public.item_stock_effect(o_product_id, 'in');\r\nEND $function$"}	purchasing_and_returns
08	{"-- ============================================================================\r\n-- 09_accounting_ledger.sql\r\n--\r\n-- المحاسبة: دليل الحسابات، القيود المزدوجة، الأرصدة الافتتاحية.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\nCREATE SEQUENCE IF NOT EXISTS public.opening_balance_seq START 1","-- ── TABLES ────────────────────────────────────────────────────────────────\r\nCREATE TABLE public.accounts (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  code varchar(20) NOT NULL,\r\n  name_ar text NOT NULL,\r\n  account_type public.account_type NOT NULL,\r\n  parent_id uuid,\r\n  is_system boolean DEFAULT false NOT NULL,\r\n  is_postable boolean DEFAULT true NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  requires_reconciliation boolean DEFAULT false NOT NULL,\r\n  notes text,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.journal_entries (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  entry_number text NOT NULL,\r\n  entry_date date DEFAULT CURRENT_DATE NOT NULL,\r\n  memo text NOT NULL,\r\n  status text DEFAULT 'DRAFT'::text NOT NULL,\r\n  source_type text,\r\n  source_id uuid,\r\n  is_system boolean DEFAULT false NOT NULL,\r\n  reverses_id uuid,\r\n  total_debit numeric(18,2) DEFAULT 0 NOT NULL,\r\n  total_credit numeric(18,2) DEFAULT 0 NOT NULL,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  posted_by uuid,\r\n  posted_at timestamp with time zone\r\n)","CREATE TABLE public.journal_lines (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  entry_id uuid NOT NULL,\r\n  account_id uuid NOT NULL,\r\n  debit numeric(18,2) DEFAULT 0 NOT NULL,\r\n  credit numeric(18,2) DEFAULT 0 NOT NULL,\r\n  memo text,\r\n  partner_type text,\r\n  partner_id uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.opening_balance_documents (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  document_number text NOT NULL,\r\n  effective_date date NOT NULL,\r\n  status text DEFAULT 'DRAFT'::text NOT NULL,\r\n  fiscal_year integer NOT NULL,\r\n  total_assets numeric(18,2) DEFAULT 0 NOT NULL,\r\n  total_liabilities numeric(18,2) DEFAULT 0 NOT NULL,\r\n  capital_required numeric(18,2),\r\n  reverses_document_id uuid,\r\n  notes text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  posted_by uuid,\r\n  posted_at timestamp with time zone\r\n)","CREATE TABLE public.opening_balance_lines (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  document_id uuid NOT NULL,\r\n  section text NOT NULL,\r\n  side text NOT NULL,\r\n  ref_type text,\r\n  ref_id uuid,\r\n  product_id uuid,\r\n  warehouse_id uuid,\r\n  customer_id uuid,\r\n  supplier_id uuid,\r\n  description text NOT NULL,\r\n  quantity numeric(18,3),\r\n  unit_cost numeric(18,4),\r\n  amount numeric(18,2) NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","-- ── CONSTRAINTS ───────────────────────────────────────────────────────────\r\nALTER TABLE public.accounts ADD CONSTRAINT \\"accounts_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.accounts ADD CONSTRAINT \\"accounts_code_key\\" UNIQUE (code)","ALTER TABLE public.journal_entries ADD CONSTRAINT \\"journal_entries_status_check\\" CHECK ((status = ANY (ARRAY['DRAFT'::text, 'POSTED'::text, 'REVERSED'::text])))","ALTER TABLE public.journal_entries ADD CONSTRAINT \\"journal_no_self_reversal\\" CHECK ((reverses_id IS DISTINCT FROM id))","ALTER TABLE public.journal_entries ADD CONSTRAINT \\"journal_posted_has_totals\\" CHECK (((status <> 'POSTED'::text) OR ((total_debit > (0)::numeric) AND (total_debit = total_credit))))","ALTER TABLE public.journal_entries ADD CONSTRAINT \\"journal_entries_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.journal_entries ADD CONSTRAINT \\"journal_entries_entry_number_key\\" UNIQUE (entry_number)","ALTER TABLE public.journal_lines ADD CONSTRAINT \\"journal_lines_credit_check\\" CHECK ((credit >= (0)::numeric))","ALTER TABLE public.journal_lines ADD CONSTRAINT \\"journal_lines_debit_check\\" CHECK ((debit >= (0)::numeric))","ALTER TABLE public.journal_lines ADD CONSTRAINT \\"journal_lines_one_side\\" CHECK ((((debit > (0)::numeric) AND (credit = (0)::numeric)) OR ((credit > (0)::numeric) AND (debit = (0)::numeric))))","ALTER TABLE public.journal_lines ADD CONSTRAINT \\"journal_lines_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.opening_balance_documents ADD CONSTRAINT \\"opening_balance_documents_status_check\\" CHECK ((status = ANY (ARRAY['DRAFT'::text, 'POSTED'::text, 'REVERSED'::text])))","ALTER TABLE public.opening_balance_documents ADD CONSTRAINT \\"opening_balance_posted_has_date\\" CHECK (((status = 'DRAFT'::text) OR (posted_at IS NOT NULL)))","ALTER TABLE public.opening_balance_documents ADD CONSTRAINT \\"opening_balance_documents_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.opening_balance_documents ADD CONSTRAINT \\"opening_balance_documents_document_number_key\\" UNIQUE (document_number)","ALTER TABLE public.opening_balance_lines ADD CONSTRAINT \\"opening_balance_lines_amount_check\\" CHECK ((amount >= (0)::numeric))","ALTER TABLE public.opening_balance_lines ADD CONSTRAINT \\"opening_balance_lines_section_check\\" CHECK ((section = ANY (ARRAY['STOCK'::text, 'RECEIVABLE'::text, 'PAYABLE'::text, 'CASH'::text, 'BANK'::text, 'ASSET'::text, 'LIABILITY'::text, 'CAPITAL'::text])))","ALTER TABLE public.opening_balance_lines ADD CONSTRAINT \\"opening_balance_lines_side_check\\" CHECK ((side = ANY (ARRAY['DEBIT'::text, 'CREDIT'::text])))","ALTER TABLE public.opening_balance_lines ADD CONSTRAINT \\"opening_balance_lines_stock_shape\\" CHECK (((section <> 'STOCK'::text) OR ((product_id IS NOT NULL) AND (warehouse_id IS NOT NULL) AND (quantity IS NOT NULL))))","ALTER TABLE public.opening_balance_lines ADD CONSTRAINT \\"opening_balance_lines_pkey\\" PRIMARY KEY (id)","-- ── INDEXES ───────────────────────────────────────────────────────────────\r\nCREATE INDEX ix_journal_date ON public.journal_entries USING btree (entry_date DESC)","CREATE INDEX ix_journal_source ON public.journal_entries USING btree (source_type, source_id)","CREATE INDEX ix_journal_lines_account ON public.journal_lines USING btree (account_id)","CREATE INDEX ix_journal_lines_entry ON public.journal_lines USING btree (entry_id)","CREATE INDEX ix_opening_lines_doc ON public.opening_balance_lines USING btree (document_id)","CREATE INDEX ix_opening_lines_ref ON public.opening_balance_lines USING btree (ref_type, ref_id)","-- ── SEQUENCES ─────────────────────────────────────────────────────────────\r\nCREATE SEQUENCE IF NOT EXISTS public.sales_invoice_seq START 1","CREATE SEQUENCE IF NOT EXISTS public.sales_return_seq START 1","-- ── FUNCTIONS ─────────────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.create_journal_entry(p_memo text, p_entry_date date DEFAULT CURRENT_DATE, p_source_type text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_is_system boolean DEFAULT false, p_lines jsonb DEFAULT '[]'::jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_id   uuid;\r\n  v_num  text;\r\n  v_d    numeric := 0;\r\n  v_c    numeric := 0;\r\n  src    jsonb;\r\n  v_missing integer;\r\n  v_blocked integer;\r\n  v_sideless text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF p_memo IS NULL OR btrim(p_memo) = '' THEN\r\n    RAISE EXCEPTION 'A journal entry needs a description';\r\n  END IF;\r\n  IF p_lines IS NULL OR jsonb_array_length(p_lines) < 2 THEN\r\n    RAISE EXCEPTION 'A journal entry needs at least two lines - one to debit and one to credit';\r\n  END IF;\r\n\r\n  -- A line must carry exactly one side. Checked up front, before the entry\r\n  -- header is written, so a rejected line never leaves a DRAFT entry behind\r\n  -- in the table for someone to find later and wonder about.\r\n  SELECT string_agg(coalesce(ln->>'account_code', '?'), '، ') INTO v_sideless\r\n    FROM jsonb_array_elements(p_lines) AS ln\r\n   WHERE coalesce((ln->>'debit')::numeric, 0) = 0\r\n     AND coalesce((ln->>'credit')::numeric, 0) = 0;\r\n  IF v_sideless IS NOT NULL THEN\r\n    RAISE EXCEPTION\r\n      'Line(s) % carry neither a debit nor a credit. Every line must have exactly one side.',\r\n      v_sideless;\r\n  END IF;\r\n\r\n  v_num := public.next_journal_number(coalesce(p_entry_date, CURRENT_DATE));\r\n\r\n  INSERT INTO public.journal_entries\r\n    (entry_number, entry_date, memo, source_type, source_id, is_system, created_by)\r\n  VALUES (v_num, coalesce(p_entry_date, CURRENT_DATE), btrim(p_memo),\r\n          p_source_type, p_source_id, p_is_system, v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR src IN SELECT * FROM jsonb_array_elements(p_lines)\r\n  LOOP\r\n    v_d := v_d + coalesce((src->>'debit')::numeric, 0);\r\n    v_c := v_c + coalesce((src->>'credit')::numeric, 0);\r\n  END LOOP;\r\n\r\n  IF v_d <> v_c THEN\r\n    RAISE EXCEPTION\r\n      'Entry does not balance: debits % vs credits % (difference %). An entry that cannot balance is not an entry.',\r\n      round(v_d, 2)::text, round(v_c, 2)::text, round(v_d - v_c, 2)::text;\r\n  END IF;\r\n  IF v_d <= 0 THEN\r\n    RAISE EXCEPTION 'Entry total must be greater than zero';\r\n  END IF;\r\n\r\n  -- The two failure modes are reported separately: \\"code does not exist\\" sends\r\n  -- the operator hunting for a typo when the code was real and simply not\r\n  -- postable, and that misdirection costs more than the extra check.\r\n  SELECT count(*) FILTER (WHERE a.id IS NULL),\r\n         count(*) FILTER (WHERE a.id IS NOT NULL AND NOT a.is_postable)\r\n    INTO v_missing, v_blocked\r\n    FROM jsonb_array_elements(p_lines) AS ln\r\n    LEFT JOIN public.accounts a ON a.code = ln->>'account_code';\r\n\r\n  IF v_missing > 0 THEN\r\n    RAISE EXCEPTION 'One or more account codes do not exist. Check the code before posting.';\r\n  END IF;\r\n  IF v_blocked > 0 THEN\r\n    RAISE EXCEPTION\r\n      'One or more accounts is not postable directly (a contra or clearing account). Post through the account that moves it.';\r\n  END IF;\r\n\r\n  INSERT INTO public.journal_lines (entry_id, account_id, debit, credit, memo, partner_type, partner_id)\r\n  SELECT v_id, a.id,\r\n         coalesce((ln->>'debit')::numeric, 0),\r\n         coalesce((ln->>'credit')::numeric, 0),\r\n         nullif(btrim(coalesce(ln->>'memo','')), ''),\r\n         nullif(btrim(coalesce(ln->>'partner_type','')), ''),\r\n         (ln->>'partner_id')::uuid\r\n    FROM jsonb_array_elements(p_lines) AS ln\r\n    JOIN public.accounts a ON a.code = ln->>'account_code'\r\n   WHERE (ln->>'debit')::numeric IS DISTINCT FROM 0\r\n      OR (ln->>'credit')::numeric IS DISTINCT FROM 0;\r\n\r\n  IF (SELECT count(*) FROM public.journal_lines WHERE entry_id = v_id)\r\n     <> jsonb_array_length(p_lines) THEN\r\n    RAISE EXCEPTION 'One or more lines could not be written';\r\n  END IF;\r\n\r\n  UPDATE public.journal_entries\r\n     SET total_debit = v_d, total_credit = v_c, status = 'POSTED',\r\n         posted_by = v_user, posted_at = now()\r\n   WHERE id = v_id;\r\n\r\n  RETURN v_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.create_opening_balance(_effective_date date, _lines jsonb, _notes text DEFAULT NULL::text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_id   uuid;\r\n  v_num  text;\r\n  l      jsonb;\r\n  v_side text;\r\n  v_section text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')\r\n          OR public.has_role(v_user,'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may open the books';\r\n  END IF;\r\n  IF _effective_date IS NULL THEN\r\n    RAISE EXCEPTION 'Effective date is required';\r\n  END IF;\r\n  IF _lines IS NULL OR jsonb_array_length(_lines) = 0 THEN\r\n    RAISE EXCEPTION 'An opening entry needs at least one line';\r\n  END IF;\r\n\r\n  v_num := 'OB-' || to_char(_effective_date,'YYYYMMDD') || '-' ||\r\n           lpad(nextval('public.opening_balance_seq')::text,3,'0');\r\n\r\n  INSERT INTO public.opening_balance_documents\r\n    (document_number, effective_date, status, fiscal_year, notes, created_by)\r\n  VALUES (v_num, _effective_date, 'DRAFT',\r\n          EXTRACT(YEAR FROM _effective_date)::int,\r\n          nullif(btrim(coalesce(_notes,'')),''), v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR l IN SELECT * FROM jsonb_array_elements(_lines)\r\n  LOOP\r\n    v_section := l->>'section';\r\n    IF v_section NOT IN ('STOCK','RECEIVABLE','PAYABLE','CASH','BANK','ASSET','LIABILITY','CAPITAL') THEN\r\n      RAISE EXCEPTION 'Unknown opening section: %', v_section;\r\n    END IF;\r\n\r\n    -- The side is DERIVED, never supplied. A line that claims to be an asset\r\n    -- on the credit side is the exact error a balance check exists to catch,\r\n    -- and accepting it would defeat the purpose.\r\n    v_side := CASE WHEN v_section IN ('STOCK','RECEIVABLE','CASH','BANK','ASSET')\r\n                   THEN 'DEBIT' ELSE 'CREDIT' END;\r\n\r\n    IF coalesce((l->>'amount')::numeric, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Line amount must be greater than zero (section %)', v_section;\r\n    END IF;\r\n\r\n    INSERT INTO public.opening_balance_lines\r\n      (document_id, section, side, ref_type, ref_id, product_id, warehouse_id,\r\n       customer_id, supplier_id, description, quantity, unit_cost, amount)\r\n    VALUES\r\n      (v_id, v_section, v_side, l->>'ref_type', (l->>'ref_id')::uuid,\r\n       (l->>'product_id')::uuid, (l->>'warehouse_id')::uuid,\r\n       (l->>'customer_id')::uuid, (l->>'supplier_id')::uuid,\r\n       coalesce(nullif(btrim(coalesce(l->>'description','')),''), v_section),\r\n       (l->>'quantity')::numeric, (l->>'unit_cost')::numeric,\r\n       (l->>'amount')::numeric);\r\n  END LOOP;\r\n\r\n  RETURN v_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.next_journal_number(p_date date)\r\n RETURNS text\r\n LANGUAGE sql\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT 'JE-' || to_char(p_date, 'YYYYMMDD') || '-' ||\r\n         lpad((count(*) + 1)::text, 4, '0')\r\n    FROM public.journal_entries\r\n   WHERE entry_date = p_date;\r\n$function$","CREATE OR REPLACE FUNCTION public.post_opening_balance(_document_id uuid)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_doc     record;\r\n  v_debit   numeric;\r\n  v_credit  numeric;\r\n  v_capital numeric;\r\n  l         record;\r\nBEGIN\r\n  SELECT * INTO v_doc FROM public.opening_balance_documents WHERE id = _document_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Opening document not found';\r\n  END IF;\r\n  IF v_doc.status <> 'DRAFT' THEN\r\n    RAISE EXCEPTION 'Document % is already %', v_doc.document_number, v_doc.status;\r\n  END IF;\r\n\r\n  SELECT coalesce(sum(amount) FILTER (WHERE side='DEBIT'), 0),\r\n         coalesce(sum(amount) FILTER (WHERE side='CREDIT'), 0),\r\n         coalesce(sum(amount) FILTER (WHERE section='CAPITAL'), 0)\r\n    INTO v_debit, v_credit, v_capital\r\n    FROM public.opening_balance_lines WHERE document_id = _document_id;\r\n\r\n  IF v_debit <> v_credit THEN\r\n    RAISE EXCEPTION\r\n      'Opening entry does not balance: debits % vs credits % (difference %). Capital required is %. Correct the document before posting.',\r\n      round(v_debit, 2)::text,\r\n      round(v_credit, 2)::text,\r\n      round(v_debit - v_credit, 2)::text,\r\n      round(v_debit - v_credit, 2)::text;\r\n  END IF;\r\n\r\n  UPDATE public.opening_balance_documents\r\n     SET total_assets      = v_debit,\r\n         total_liabilities = v_credit - v_capital,\r\n         capital_required  = v_debit - v_credit + v_capital,\r\n         status            = 'POSTED',\r\n         posted_by         = v_user,\r\n         posted_at         = now()\r\n   WHERE id = _document_id;\r\n\r\n  FOR l IN SELECT * FROM public.opening_balance_lines WHERE document_id = _document_id ORDER BY id\r\n  LOOP\r\n    IF l.section = 'STOCK' THEN\r\n      -- Real stock, through the real engine. Not a disguised purchase.\r\n      -- movement_type_legacy is set explicitly: the default is 'adjustment',\r\n      -- which the stock engine correctly refuses without an adjustment reason,\r\n      -- and which would file an opening entry under adjustments anyway.\r\n      PERFORM public.post_stock_delta(\r\n        p_product_id => l.product_id, p_warehouse_id => l.warehouse_id,\r\n        p_signed_qty => l.quantity, p_unit_cost => coalesce(l.unit_cost, 0),\r\n        p_movement_kind => 'OPENING', p_movement_type_legacy => 'opening',\r\n        p_source_type => 'opening_balance', p_source_id => _document_id,\r\n        p_note => 'رصيد افتتاحي ' || v_doc.document_number,\r\n        p_owner_type => 'COMPANY', p_owner_id => NULL);\r\n\r\n      PERFORM public.apply_cost_movement(\r\n        p_product_id => l.product_id, p_warehouse_id => l.warehouse_id,\r\n        p_signed_qty => l.quantity, p_incoming_cost => l.unit_cost,\r\n        p_source_type => 'opening_balance', p_source_id => _document_id,\r\n        p_note => 'رصيد افتتاحي ' || v_doc.document_number);\r\n\r\n    ELSIF l.section = 'RECEIVABLE' THEN\r\n      IF l.customer_id IS NULL THEN\r\n        RAISE EXCEPTION 'Receivable line \\"%\\" has no customer', l.description;\r\n      END IF;\r\n      -- 'adjustment' is the existing ledger value for a movement that is not a\r\n      -- sale, a payment or a return; reference_type carries the real reason.\r\n      INSERT INTO public.customer_ledger\r\n        (customer_id, entry_type, debit, credit, reference_id, reference_type,\r\n         occurred_at, created_by, note)\r\n      VALUES\r\n        (l.customer_id, 'adjustment', l.amount, 0, _document_id,\r\n         'opening_balance', v_doc.effective_date::timestamptz, v_user,\r\n         'رصيد افتتاحي ' || v_doc.document_number);\r\n\r\n    ELSIF l.section = 'PAYABLE' THEN\r\n      IF l.supplier_id IS NULL THEN\r\n        RAISE EXCEPTION 'Payable line \\"%\\" has no supplier', l.description;\r\n      END IF;\r\n      UPDATE public.suppliers\r\n         SET balance = coalesce(balance, 0) + l.amount\r\n       WHERE id = l.supplier_id;\r\n\r\n    ELSE\r\n      -- CASH, BANK, ASSET, LIABILITY: recorded, not posted. This schema has no\r\n      -- chart of accounts and no cash/bank table, so there is no ledger entry\r\n      -- to make. The line is real, queryable and reversible; pretending\r\n      -- otherwise would be a fiction.\r\n      NULL;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'opening_balance.posted', 'opening_balance', _document_id,\r\n          jsonb_build_object('document_number', v_doc.document_number,\r\n                             'debits', v_debit, 'credits', v_credit));\r\n  RETURN _document_id;\r\nEND $function$","-- NOTE: post_purchase_invoice and post_sales_invoice are defined ONCE, in 16_payment_methods.sql,\r\n-- because their payment-account branch needs the payment_methods catalogue.\r\n\r\nCREATE OR REPLACE FUNCTION public.reverse_journal_entry(p_entry_id uuid, p_reason text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_old  record;\r\n  v_id   uuid;\r\nBEGIN\r\n  IF p_reason IS NULL OR btrim(p_reason) = '' THEN\r\n    RAISE EXCEPTION 'Reversing an entry requires a reason';\r\n  END IF;\r\n\r\n  SELECT * INTO v_old FROM public.journal_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND OR v_old.status <> 'POSTED' THEN\r\n    RAISE EXCEPTION 'Only a posted entry can be reversed';\r\n  END IF;\r\n\r\n  SELECT public.create_journal_entry(\r\n    'عكس القيد ' || v_old.entry_number || ': ' || btrim(p_reason),\r\n    CURRENT_DATE, 'journal_reversal', p_entry_id, v_old.is_system,\r\n    (SELECT coalesce(jsonb_agg(jsonb_build_object(\r\n        'account_code', a.code,\r\n        -- A reversal swaps the sides rather than negating: the credit of the\r\n        -- original becomes the debit of the reversal.\r\n        'debit',  CASE WHEN jl.debit  > 0 THEN 0 ELSE jl.credit END,\r\n        'credit', CASE WHEN jl.debit  > 0 THEN jl.debit  ELSE 0 END,\r\n        'memo',   coalesce(jl.memo, a.name_ar)\r\n      ) ORDER BY jl.id), '[]'::jsonb)\r\n       FROM public.journal_lines jl JOIN public.accounts a ON a.id = jl.account_id\r\n      WHERE jl.entry_id = p_entry_id)\r\n  ) INTO v_id;\r\n\r\n  UPDATE public.journal_entries SET status = 'REVERSED' WHERE id = p_entry_id;\r\n  RETURN v_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.reverse_opening_balance(_document_id uuid, _reason text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_doc  record;\r\n  v_new  uuid;\r\n  v_num  text;\r\n  l      record;\r\nBEGIN\r\n  IF _reason IS NULL OR btrim(_reason) = '' THEN\r\n    RAISE EXCEPTION 'Reversing an opening entry requires a reason';\r\n  END IF;\r\n\r\n  SELECT * INTO v_doc FROM public.opening_balance_documents WHERE id = _document_id FOR UPDATE;\r\n  IF NOT FOUND OR v_doc.status <> 'POSTED' THEN\r\n    RAISE EXCEPTION 'Only a posted opening document can be reversed';\r\n  END IF;\r\n\r\n  v_num := 'OBR-' || v_doc.document_number;\r\n  INSERT INTO public.opening_balance_documents\r\n    (document_number, effective_date, status, fiscal_year, reverses_document_id,\r\n     notes, created_by, posted_at, posted_by)\r\n  VALUES (v_num, v_doc.effective_date, 'POSTED', v_doc.fiscal_year, _document_id,\r\n          'عكس القيد الافتتاحي ' || v_doc.document_number || ': ' || btrim(_reason),\r\n          v_user, now(), v_user)\r\n  RETURNING id INTO v_new;\r\n\r\n  -- Mirrored at the same amount, so the reversal balances by construction\r\n  -- rather than by arithmetic the caller has to get right.\r\n  INSERT INTO public.opening_balance_lines\r\n    (document_id, section, side, ref_type, ref_id, product_id, warehouse_id,\r\n     customer_id, supplier_id, description, quantity, unit_cost, amount)\r\n  SELECT v_new, section,\r\n         CASE WHEN side='DEBIT' THEN 'CREDIT' ELSE 'DEBIT' END,\r\n         ref_type, ref_id, product_id, warehouse_id, customer_id, supplier_id,\r\n         'عكس: ' || description, quantity, unit_cost, amount\r\n    FROM public.opening_balance_lines WHERE document_id = _document_id;\r\n\r\n  FOR l IN SELECT * FROM public.opening_balance_lines WHERE document_id = _document_id\r\n  LOOP\r\n    IF l.section = 'STOCK' THEN\r\n      PERFORM public.post_stock_delta(\r\n        p_product_id => l.product_id, p_warehouse_id => l.warehouse_id,\r\n        p_signed_qty => -l.quantity, p_unit_cost => coalesce(l.unit_cost, 0),\r\n        p_movement_kind => 'ADJUSTMENT', p_movement_type_legacy => 'opening',\r\n        p_source_type => 'opening_balance_reversal', p_source_id => v_new,\r\n        p_note => 'عكس رصيد افتتاحي ' || v_doc.document_number,\r\n        p_owner_type => 'COMPANY', p_owner_id => NULL);\r\n      PERFORM public.apply_cost_movement(\r\n        p_product_id => l.product_id, p_warehouse_id => l.warehouse_id,\r\n        p_signed_qty => -l.quantity, p_incoming_cost => NULL,\r\n        p_source_type => 'opening_balance_reversal', p_source_id => v_new,\r\n        p_note => 'عكس رصيد افتتاحي ' || v_doc.document_number);\r\n    ELSIF l.section = 'RECEIVABLE' THEN\r\n      INSERT INTO public.customer_ledger\r\n        (customer_id, entry_type, debit, credit, reference_id, reference_type,\r\n         occurred_at, created_by, note)\r\n      VALUES (l.customer_id, 'adjustment', 0, l.amount, v_new,\r\n              'opening_balance_reversal', now(), v_user,\r\n              'عكس رصيد افتتاحي ' || v_doc.document_number);\r\n    ELSIF l.section = 'PAYABLE' THEN\r\n      UPDATE public.suppliers SET balance = coalesce(balance,0) - l.amount\r\n       WHERE id = l.supplier_id;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  UPDATE public.opening_balance_documents\r\n     SET status = 'REVERSED'\r\n   WHERE id = _document_id;\r\n\r\n  RETURN v_new;\r\nEND $function$"}	accounting_ledger
09	{"-- ============================================================================\r\n-- 10_expenses.sql\r\n--\r\n-- المصروفات: المستندات، البنود، الدفعات، الموافقات، المرفقات، مراكز التكلفة، المشاريع.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── TABLES ────────────────────────────────────────────────────────────────\r\nCREATE TABLE public.expense_categories (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  name text NOT NULL,\r\n  name_ar text,\r\n  -- الحساب المحاسبي الذي يُرحَّل إليه مصروف هذا التصنيف.\r\n  --\r\n  -- لماذا عمود لا تسمية فقط؟ لأن التصنيف تنظيم إداري («كيف صنّفه المالك»)،\r\n  -- والحساب وجهة محاسبية («إلى أين يذهب في الدفاتر»). فصلهما مقصود:\r\n  --   • تصنيف واحد قد يُرحَّل لأكثر من حساب بحسب السياق (إيجار مصنع ومكتب).\r\n  --   • تعديل شجرة الحسابات يجب ألّا يغيّر تسمية المصروف عند المالك.\r\n  --\r\n  -- لكن بلا ربط، كانت 10 تصنيفات تُدفن في 5 حسابات، فيفقد المالك معرفة\r\n  -- ما صرفه على التسويق مثلًا — لأنه اختلط بالمواصلات في سطر واحد.\r\n  --\r\n  -- NULL مقبول: تصنيف بلا حساب مُعيَّن يقع على الحساب الافتراضي عند الترحيل.\r\n  account_id uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  sort_order integer DEFAULT 100 NOT NULL,\r\n  notes text,\r\n  created_by uuid\r\n)","CREATE TABLE public.expense_cost_centers (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  code text,\r\n  name text NOT NULL,\r\n  name_ar text,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.expense_projects (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  code text,\r\n  name text NOT NULL,\r\n  name_ar text,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  started_on date,\r\n  closed_on date,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.expense_entries (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  reference text NOT NULL,\r\n  entry_type public.expense_entry_type DEFAULT 'DIRECT'::expense_entry_type NOT NULL,\r\n  status public.expense_status DEFAULT 'DRAFT'::expense_status NOT NULL,\r\n  source_kind public.expense_source_kind DEFAULT 'MANUAL'::expense_source_kind NOT NULL,\r\n  payee_type public.expense_payee_type DEFAULT 'NONE'::expense_payee_type NOT NULL,\r\n  payee_name text,\r\n  supplier_id uuid,\r\n  employee_id uuid,\r\n  warehouse_id uuid,\r\n  cost_center_id uuid,\r\n  project_id uuid,\r\n  expense_date date DEFAULT CURRENT_DATE NOT NULL,\r\n  due_date date,\r\n  posting_date date,\r\n  description text,\r\n  note text,\r\n  total_amount numeric(18,2) DEFAULT 0 NOT NULL,\r\n  paid_amount numeric(18,2) DEFAULT 0 NOT NULL,\r\n  remaining_amount numeric(18,2) GENERATED ALWAYS AS ((total_amount - paid_amount)) STORED,\r\n  tax_mode public.expense_tax_mode DEFAULT 'NONE'::expense_tax_mode NOT NULL,\r\n  currency text DEFAULT 'YER'::text NOT NULL,\r\n  currency_symbol text DEFAULT '﷼'::text NOT NULL,\r\n  line_count integer DEFAULT 0 NOT NULL,\r\n  version integer DEFAULT 1 NOT NULL,\r\n  created_by uuid,\r\n  submitted_by uuid,\r\n  submitted_at timestamp with time zone,\r\n  approved_by uuid,\r\n  approved_at timestamp with time zone,\r\n  rejected_by uuid,\r\n  rejected_at timestamp with time zone,\r\n  rejection_reason text,\r\n  posted_by uuid,\r\n  posted_at timestamp with time zone,\r\n  cancelled_by uuid,\r\n  cancelled_at timestamp with time zone,\r\n  cancel_reason text,\r\n  reversal_of uuid,\r\n  reversed_by_id uuid,\r\n  legacy_expense_id uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.expense_lines (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  entry_id uuid NOT NULL,\r\n  line_no integer NOT NULL,\r\n  description text,\r\n  category_id uuid,\r\n  quantity numeric(18,3) DEFAULT 1 NOT NULL,\r\n  unit_price numeric(18,2) DEFAULT 0 NOT NULL,\r\n  net_amount numeric(18,2) DEFAULT 0 NOT NULL,\r\n  tax_rate numeric(5,2) DEFAULT 0 NOT NULL,\r\n  tax_amount numeric(18,2) DEFAULT 0 NOT NULL,\r\n  gross_amount numeric(18,2) DEFAULT 0 NOT NULL,\r\n  cost_center_id uuid,\r\n  project_id uuid,\r\n  note text,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.expense_payments (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  entry_id uuid NOT NULL,\r\n  amount numeric(18,2) NOT NULL,\r\n  payment_date date DEFAULT CURRENT_DATE NOT NULL,\r\n  payment_method public.payment_method DEFAULT 'cash'::payment_method NOT NULL,\r\n  account_label text,\r\n  reference_no text,\r\n  note text,\r\n  idempotency_key text,\r\n  reversed_by uuid,\r\n  reversal_of uuid,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  account_id uuid\r\n)","CREATE TABLE public.expense_approvals (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  entry_id uuid NOT NULL,\r\n  sequence integer NOT NULL,\r\n  action text NOT NULL,\r\n  from_status public.expense_status,\r\n  to_status public.expense_status NOT NULL,\r\n  actor_id uuid,\r\n  reason text,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.expense_attachments (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  entry_id uuid NOT NULL,\r\n  line_id uuid,\r\n  bucket_id text DEFAULT 'expense-attachments'::text NOT NULL,\r\n  storage_path text NOT NULL,\r\n  file_name text NOT NULL,\r\n  mime_type text,\r\n  file_size bigint,\r\n  checksum text,\r\n  uploaded_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.expenses (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  category_id uuid,\r\n  amount numeric NOT NULL,\r\n  payment_method public.payment_method DEFAULT 'cash'::payment_method NOT NULL,\r\n  expense_date date DEFAULT CURRENT_DATE NOT NULL,\r\n  note text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","-- ── CONSTRAINTS ───────────────────────────────────────────────────────────\r\nALTER TABLE public.expense_categories ADD CONSTRAINT \\"expense_categories_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.expense_categories ADD CONSTRAINT \\"expense_categories_name_key\\" UNIQUE (name)","ALTER TABLE public.expense_cost_centers ADD CONSTRAINT \\"expense_cost_centers_name_not_blank\\" CHECK ((btrim(name) <> ''::text))","ALTER TABLE public.expense_cost_centers ADD CONSTRAINT \\"expense_cost_centers_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.expense_projects ADD CONSTRAINT \\"expense_projects_name_not_blank\\" CHECK ((btrim(name) <> ''::text))","ALTER TABLE public.expense_projects ADD CONSTRAINT \\"expense_projects_window_valid\\" CHECK (((closed_on IS NULL) OR (started_on IS NULL) OR (closed_on >= started_on)))","ALTER TABLE public.expense_projects ADD CONSTRAINT \\"expense_projects_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_dates_ordered\\" CHECK (((posting_date IS NULL) OR (posting_date >= (expense_date - 366))))","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_due_after_expense\\" CHECK (((due_date IS NULL) OR (due_date >= expense_date)))","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_paid_non_negative\\" CHECK ((paid_amount >= (0)::numeric))","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_paid_requires_post\\" CHECK (((paid_amount = (0)::numeric) OR (status = ANY (ARRAY['POSTED'::expense_status, 'PARTIALLY_PAID'::expense_status, 'PAID'::expense_status, 'CLOSED'::expense_status, 'REVERSED'::expense_status]))))","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_paid_within_total\\" CHECK ((paid_amount <= (total_amount + 0.005)))","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_payee_consistent\\" CHECK ((((payee_type = 'SUPPLIER'::expense_payee_type) AND (supplier_id IS NOT NULL) AND (employee_id IS NULL)) OR ((payee_type = 'EMPLOYEE'::expense_payee_type) AND (employee_id IS NOT NULL) AND (supplier_id IS NULL)) OR ((payee_type = ANY (ARRAY['NONE'::expense_payee_type, 'OTHER'::expense_payee_type])) AND (supplier_id IS NULL) AND (employee_id IS NULL))))","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_reference_not_blank\\" CHECK ((btrim(reference) <> ''::text))","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_total_non_negative\\" CHECK ((total_amount >= (0)::numeric))","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_amounts_add_up\\" CHECK ((abs(((net_amount + tax_amount) - gross_amount)) <= 0.01))","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_amounts_non_negative\\" CHECK (((net_amount >= (0)::numeric) AND (tax_amount >= (0)::numeric) AND (gross_amount >= (0)::numeric)))","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_line_no_positive\\" CHECK ((line_no > 0))","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_quantity_positive\\" CHECK ((quantity > (0)::numeric))","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_tax_rate_range\\" CHECK (((tax_rate >= (0)::numeric) AND (tax_rate <= (100)::numeric)))","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_unit_price_non_negative\\" CHECK ((unit_price >= (0)::numeric))","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.expense_payments ADD CONSTRAINT \\"expense_payments_amount_positive\\" CHECK ((amount > (0)::numeric))","ALTER TABLE public.expense_payments ADD CONSTRAINT \\"expense_payments_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.expense_approvals ADD CONSTRAINT \\"expense_approvals_action_known\\" CHECK ((action = ANY (ARRAY['created'::text, 'updated'::text, 'submitted'::text, 'approved'::text, 'rejected'::text, 'posted'::text, 'payment'::text, 'cancelled'::text, 'reversed'::text, 'closed'::text, 'reopened'::text])))","ALTER TABLE public.expense_approvals ADD CONSTRAINT \\"expense_approvals_sequence_positive\\" CHECK ((sequence > 0))","ALTER TABLE public.expense_approvals ADD CONSTRAINT \\"expense_approvals_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.expense_attachments ADD CONSTRAINT \\"expense_attachments_size_positive\\" CHECK (((file_size IS NULL) OR (file_size > 0)))","ALTER TABLE public.expense_attachments ADD CONSTRAINT \\"expense_attachments_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.expenses ADD CONSTRAINT \\"expenses_amount_check\\" CHECK ((amount >= (0)::numeric))","ALTER TABLE public.expenses ADD CONSTRAINT \\"expenses_pkey\\" PRIMARY KEY (id)","-- ── INDEXES ───────────────────────────────────────────────────────────────\r\nCREATE INDEX expense_categories_active_order_idx ON public.expense_categories USING btree (is_active, sort_order, name)","CREATE INDEX expense_cost_centers_active_idx ON public.expense_cost_centers USING btree (is_active, name)","CREATE UNIQUE INDEX expense_cost_centers_code_key ON public.expense_cost_centers USING btree (lower(btrim(code))) WHERE ((code IS NOT NULL) AND (btrim(code) <> ''::text))","CREATE INDEX expense_projects_active_idx ON public.expense_projects USING btree (is_active, name)","CREATE UNIQUE INDEX expense_projects_code_key ON public.expense_projects USING btree (lower(btrim(code))) WHERE ((code IS NOT NULL) AND (btrim(code) <> ''::text))","CREATE INDEX expense_entries_cost_center_idx ON public.expense_entries USING btree (cost_center_id, expense_date DESC) WHERE (cost_center_id IS NOT NULL)","CREATE INDEX expense_entries_created_by_idx ON public.expense_entries USING btree (created_by, expense_date DESC) WHERE (created_by IS NOT NULL)","CREATE INDEX expense_entries_created_idx ON public.expense_entries USING btree (created_at DESC, id DESC)","CREATE INDEX expense_entries_date_idx ON public.expense_entries USING btree (expense_date DESC, id DESC)","CREATE INDEX expense_entries_employee_idx ON public.expense_entries USING btree (employee_id, expense_date DESC) WHERE (employee_id IS NOT NULL)","CREATE UNIQUE INDEX expense_entries_legacy_key ON public.expense_entries USING btree (legacy_expense_id) WHERE (legacy_expense_id IS NOT NULL)","CREATE INDEX expense_entries_open_idx ON public.expense_entries USING btree (due_date, expense_date) WHERE (status = ANY (ARRAY['POSTED'::expense_status, 'PARTIALLY_PAID'::expense_status]))","CREATE INDEX expense_entries_pending_idx ON public.expense_entries USING btree (submitted_at) WHERE (status = 'SUBMITTED'::expense_status)","CREATE INDEX expense_entries_project_idx ON public.expense_entries USING btree (project_id, expense_date DESC) WHERE (project_id IS NOT NULL)","CREATE UNIQUE INDEX expense_entries_reference_key ON public.expense_entries USING btree (upper(btrim(reference)))","CREATE INDEX expense_entries_status_date_idx ON public.expense_entries USING btree (status, expense_date DESC, id DESC)","CREATE INDEX expense_entries_supplier_idx ON public.expense_entries USING btree (supplier_id, expense_date DESC) WHERE (supplier_id IS NOT NULL)","CREATE INDEX expense_entries_warehouse_idx ON public.expense_entries USING btree (warehouse_id, expense_date DESC) WHERE (warehouse_id IS NOT NULL)","CREATE INDEX expense_lines_category_idx ON public.expense_lines USING btree (category_id, entry_id)","CREATE INDEX expense_lines_cost_center_idx ON public.expense_lines USING btree (cost_center_id, entry_id) WHERE (cost_center_id IS NOT NULL)","CREATE INDEX expense_lines_entry_idx ON public.expense_lines USING btree (entry_id)","CREATE UNIQUE INDEX expense_lines_entry_line_key ON public.expense_lines USING btree (entry_id, line_no)","CREATE INDEX expense_lines_project_idx ON public.expense_lines USING btree (project_id, entry_id) WHERE (project_id IS NOT NULL)","CREATE INDEX expense_payments_account_id_idx ON public.expense_payments USING btree (account_id) WHERE (account_id IS NOT NULL)","CREATE INDEX expense_payments_date_idx ON public.expense_payments USING btree (payment_date DESC, id DESC)","CREATE INDEX expense_payments_entry_idx ON public.expense_payments USING btree (entry_id, payment_date, id)","CREATE UNIQUE INDEX expense_payments_idempotency_key ON public.expense_payments USING btree (idempotency_key) WHERE (idempotency_key IS NOT NULL)","CREATE INDEX expense_payments_method_idx ON public.expense_payments USING btree (payment_method, payment_date DESC)","CREATE INDEX expense_approvals_entry_idx ON public.expense_approvals USING btree (entry_id, created_at)","CREATE UNIQUE INDEX expense_approvals_entry_sequence_key ON public.expense_approvals USING btree (entry_id, sequence)","CREATE INDEX expense_attachments_entry_idx ON public.expense_attachments USING btree (entry_id, created_at)","CREATE UNIQUE INDEX expense_attachments_path_key ON public.expense_attachments USING btree (bucket_id, storage_path)","-- ── SEQUENCES ─────────────────────────────────────────────────────────────\r\nCREATE SEQUENCE IF NOT EXISTS public.purchase_invoice_seq START 1","CREATE SEQUENCE IF NOT EXISTS public.purchase_return_seq START 1","-- ── FUNCTIONS ─────────────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.can_read_expense_entry(p_entry_id uuid, p_user uuid)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT public.can_read_finance(p_user)\r\n      OR (public.is_staff(p_user) AND EXISTS (\r\n            SELECT 1 FROM public.expense_entries e\r\n            WHERE e.id = p_entry_id AND e.created_by = p_user))\r\n$function$","CREATE OR REPLACE FUNCTION public.cancel_expense(p_entry_id uuid, p_reason text, p_expected_version integer DEFAULT NULL::integer)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user  uuid := public.expense_actor();\r\n  v_entry public.expense_entries;\r\n  v_from  public.expense_status;\r\nBEGIN\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  v_from := v_entry.status;\r\n\r\n  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN\r\n    RAISE EXCEPTION 'A reason is required when cancelling an expense' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  IF v_from IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED', 'REVERSED') THEN\r\n    RAISE EXCEPTION 'A posted expense cannot be cancelled — reverse it instead'\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  IF v_from = 'CANCELLED' THEN\r\n    RETURN v_entry;   -- idempotent\r\n  END IF;\r\n\r\n  IF v_from NOT IN ('DRAFT', 'REJECTED', 'SUBMITTED', 'APPROVED') THEN\r\n    RAISE EXCEPTION 'This expense cannot be cancelled from status %', v_from\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  -- Cancelling someone else's submitted document is a management decision, not\r\n  -- a data-entry correction.\r\n  IF NOT (v_entry.created_by = v_user AND v_from IN ('DRAFT', 'REJECTED')) THEN\r\n    PERFORM public.expense_assert_capability(v_user, 'expense.cancel');\r\n  ELSE\r\n    PERFORM public.expense_assert_capability(v_user, 'expense.edit');\r\n  END IF;\r\n\r\n  IF p_expected_version IS NOT NULL AND p_expected_version <> v_entry.version THEN\r\n    RAISE EXCEPTION 'This expense was changed by someone else. Reload it and try again.'\r\n      USING ERRCODE = '40001';\r\n  END IF;\r\n\r\n  UPDATE public.expense_entries\r\n     SET status        = 'CANCELLED',\r\n         cancelled_by  = v_user,\r\n         cancelled_at  = now(),\r\n         cancel_reason = nullif(btrim(p_reason), ''),\r\n         version       = version + 1\r\n   WHERE id = p_entry_id\r\n  RETURNING * INTO v_entry;\r\n\r\n  PERFORM public.expense_log_action(p_entry_id, 'cancelled', v_from, 'CANCELLED', p_reason, v_user);\r\n\r\n  RETURN v_entry;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.close_expense(p_entry_id uuid)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user  uuid := public.expense_actor();\r\n  v_entry public.expense_entries;\r\nBEGIN\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.post');\r\n\r\n  IF v_entry.status = 'CLOSED' THEN\r\n    RETURN v_entry;\r\n  END IF;\r\n  IF v_entry.status NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID') THEN\r\n    RAISE EXCEPTION 'Only a posted expense can be closed (current: %)', v_entry.status\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n  IF v_entry.remaining_amount > 0.005 THEN\r\n    RAISE EXCEPTION 'This expense still has % outstanding', v_entry.remaining_amount\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  UPDATE public.expense_entries\r\n     SET status = 'CLOSED', version = version + 1\r\n   WHERE id = p_entry_id\r\n  RETURNING * INTO v_entry;\r\n\r\n  PERFORM public.expense_log_action(p_entry_id, 'closed', 'PAID', 'CLOSED', NULL, v_user);\r\n\r\n  RETURN v_entry;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.create_expense(p_lines jsonb, p_expense_date date DEFAULT CURRENT_DATE, p_due_date date DEFAULT NULL::date, p_entry_type expense_entry_type DEFAULT 'DIRECT'::expense_entry_type, p_payee_type expense_payee_type DEFAULT 'NONE'::expense_payee_type, p_payee_name text DEFAULT NULL::text, p_supplier_id uuid DEFAULT NULL::uuid, p_employee_id uuid DEFAULT NULL::uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_tax_mode expense_tax_mode DEFAULT 'NONE'::expense_tax_mode, p_reference text DEFAULT NULL::text, p_submit boolean DEFAULT false)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user   uuid := public.expense_actor();\r\n  v_entry  public.expense_entries;\r\n  v_total  numeric;\r\n  v_count  integer;\r\n  v_ref    text;\r\n  v_status public.expense_status;\r\n  v_currency text;\r\n  v_symbol   text;\r\nBEGIN\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.create');\r\n\r\n  IF p_expense_date IS NULL THEN\r\n    RAISE EXCEPTION 'Expense date is required' USING ERRCODE = '22023';\r\n  END IF;\r\n  -- Plan §10: the three dates are distinct concepts; a due date before the\r\n  -- occurrence would make the ageing report negative from day one.\r\n  IF p_due_date IS NOT NULL AND p_due_date < p_expense_date THEN\r\n    RAISE EXCEPTION 'Due date cannot precede the expense date' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  -- The payee triple is validated in SQL as well as by the table constraint, so\r\n  -- the caller gets a readable message instead of a constraint name.\r\n  IF p_payee_type = 'SUPPLIER' AND p_supplier_id IS NULL THEN\r\n    RAISE EXCEPTION 'A supplier payee requires a supplier' USING ERRCODE = '22023';\r\n  END IF;\r\n  IF p_payee_type = 'EMPLOYEE' AND p_employee_id IS NULL THEN\r\n    RAISE EXCEPTION 'An employee payee requires a staff member' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  -- Currency is snapshotted at creation (Phase 1 rationale): a later change to\r\n  -- the company currency must not re-label a historical voucher.\r\n  SELECT COALESCE(NULLIF(btrim(currency), ''), 'YER'),\r\n         COALESCE(NULLIF(btrim(currency_symbol), ''), '﷼')\r\n    INTO v_currency, v_symbol\r\n  FROM public.company_settings\r\n  ORDER BY id\r\n  LIMIT 1;\r\n  v_currency := COALESCE(v_currency, 'YER');\r\n  v_symbol   := COALESCE(v_symbol, '﷼');\r\n\r\n  -- `submit` is offered as a flag because the common real-world action is\r\n  -- \\"record it and send it for approval\\", and doing that in two round-trips is\r\n  -- how a document ends up stranded in DRAFT.\r\n  v_status := CASE WHEN p_submit THEN 'SUBMITTED'::public.expense_status\r\n                   ELSE 'DRAFT'::public.expense_status END;\r\n\r\n  v_ref := COALESCE(\r\n    NULLIF(btrim(COALESCE(p_reference, '')), ''),\r\n    public.next_expense_reference()\r\n  );\r\n\r\n  INSERT INTO public.expense_entries (\r\n    reference, entry_type, status, source_kind,\r\n    payee_type, payee_name, supplier_id, employee_id,\r\n    warehouse_id, cost_center_id, project_id,\r\n    expense_date, due_date,\r\n    description, note,\r\n    tax_mode, currency, currency_symbol,\r\n    created_by, submitted_by, submitted_at\r\n  )\r\n  VALUES (\r\n    v_ref, p_entry_type, v_status, 'MANUAL',\r\n    p_payee_type,\r\n    nullif(btrim(coalesce(p_payee_name, '')), ''),\r\n    CASE WHEN p_payee_type = 'SUPPLIER' THEN p_supplier_id END,\r\n    CASE WHEN p_payee_type = 'EMPLOYEE' THEN p_employee_id END,\r\n    p_warehouse_id, p_cost_center_id, p_project_id,\r\n    p_expense_date, p_due_date,\r\n    nullif(btrim(coalesce(p_description, '')), ''),\r\n    nullif(btrim(coalesce(p_note, '')), ''),\r\n    p_tax_mode, v_currency, v_symbol,\r\n    v_user,\r\n    CASE WHEN p_submit THEN v_user END,\r\n    CASE WHEN p_submit THEN now() END\r\n  )\r\n  RETURNING * INTO v_entry;\r\n\r\n  SELECT o_total, o_count INTO v_total, v_count\r\n  FROM public.expense_write_lines(v_entry.id, p_lines, p_tax_mode);\r\n\r\n  -- The line trigger already synced these; the assignment is explicit so the\r\n  -- RETURNING value below is correct without a second read.\r\n  UPDATE public.expense_entries\r\n     SET total_amount = v_total,\r\n         line_count   = v_count\r\n   WHERE id = v_entry.id\r\n  RETURNING * INTO v_entry;\r\n\r\n  PERFORM public.expense_log_action(\r\n    v_entry.id, 'created', NULL, v_status,\r\n    CASE WHEN p_submit THEN 'Created and submitted' ELSE 'Created as draft' END, v_user);\r\n\r\n  RETURN v_entry;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.decide_expense(p_entry_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user   uuid := public.expense_actor();\r\n  v_entry  public.expense_entries;\r\n  v_action text := CASE WHEN p_approve THEN 'approve' ELSE 'reject' END;\r\n  v_target public.expense_status := CASE WHEN p_approve\r\n                                          THEN 'APPROVED'::public.expense_status\r\n                                          ELSE 'REJECTED'::public.expense_status END;\r\nBEGIN\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  -- Only a submitted document is awaiting a decision. This is what stops a\r\n  -- double-click — or two approvers acting at the same moment — from producing\r\n  -- two approvals: the second caller finds APPROVED, not SUBMITTED.\r\n  IF v_entry.status <> 'SUBMITTED' THEN\r\n    RAISE EXCEPTION 'This expense is not awaiting approval (current: %)', v_entry.status\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.' || v_action);\r\n\r\n  IF p_expected_version IS NOT NULL AND p_expected_version <> v_entry.version THEN\r\n    RAISE EXCEPTION 'This expense was changed by someone else. Reload it and try again.'\r\n      USING ERRCODE = '40001';\r\n  END IF;\r\n\r\n  -- Plan §17: separation of duties. The person who typed the expense is not the\r\n  -- person who authorises it. An owner is the single documented exception, since\r\n  -- in a one-person company refusing self-approval would make the module\r\n  -- unusable — but the exception is explicit and auditable rather than silent.\r\n  IF v_entry.created_by = v_user AND NOT public.has_role(v_user, 'owner') THEN\r\n    RAISE EXCEPTION 'You cannot approve an expense you created yourself'\r\n      USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  IF v_entry.created_by = v_user AND public.has_role(v_user, 'owner') THEN\r\n    -- Recorded in the trail, not merely allowed: an owner reviewing their own\r\n    -- work should be visible to an auditor.\r\n    p_reason := COALESCE(NULLIF(btrim(COALESCE(p_reason, '')), ''),\r\n                         'Self-approved by owner (no other approver available)');\r\n  END IF;\r\n\r\n  IF NOT p_approve AND NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN\r\n    RAISE EXCEPTION 'A reason is required when rejecting an expense' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  UPDATE public.expense_entries\r\n     SET status      = v_target,\r\n         version     = version + 1,\r\n         approved_by = CASE WHEN p_approve THEN v_user END,\r\n         approved_at = CASE WHEN p_approve THEN now() END,\r\n         rejected_by = CASE WHEN NOT p_approve THEN v_user END,\r\n         rejected_at = CASE WHEN NOT p_approve THEN now() END,\r\n         rejection_reason = CASE WHEN NOT p_approve\r\n                                 THEN nullif(btrim(coalesce(p_reason, '')), '') END\r\n   WHERE id = p_entry_id\r\n  RETURNING * INTO v_entry;\r\n\r\n  PERFORM public.expense_log_action(p_entry_id, v_action, 'SUBMITTED', v_target, p_reason, v_user);\r\n\r\n  RETURN v_entry;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.delete_expense_category(p_id uuid)\r\n RETURNS expense_categories\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user  uuid := public.expense_actor();\r\n  v_used  bigint;\r\n  v_row   public.expense_categories;\r\nBEGIN\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.category.manage');\r\n\r\n  SELECT count(*) INTO v_used FROM public.expense_lines WHERE category_id = p_id;\r\n\r\n  IF v_used > 0 THEN\r\n    UPDATE public.expense_categories SET is_active = false WHERE id = p_id\r\n    RETURNING * INTO v_row;\r\n\r\n    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n    VALUES (v_user, 'expense.category.archived', 'expense_category', p_id,\r\n            jsonb_build_object('reason', 'in_use', 'usage_count', v_used));\r\n  ELSE\r\n    DELETE FROM public.expense_categories WHERE id = p_id\r\n    RETURNING * INTO v_row;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Category not found' USING ERRCODE = 'P0002';\r\n    END IF;\r\n\r\n    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n    VALUES (v_user, 'expense.category.deleted', 'expense_category', p_id,\r\n            jsonb_build_object('name', v_row.name));\r\n  END IF;\r\n\r\n  RETURN v_row;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.expense_actor()\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';\r\n  END IF;\r\n  RETURN v_user;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.expense_assert_capability(p_user uuid, p_capability text)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF NOT public.expense_can(p_user, p_capability) THEN\r\n    RAISE EXCEPTION 'Forbidden: % requires a higher role', p_capability\r\n      USING ERRCODE = '42501';\r\n  END IF;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.expense_can(p_user uuid, p_capability text)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT\r\n    -- Every capability requires an active staff account. `is_staff` fails\r\n    -- closed on a missing profile row, which is the behaviour we want here.\r\n    public.is_staff(p_user)\r\n    AND CASE p_capability\r\n      -- Reading the register is the baseline every operational role needs.\r\n      WHEN 'expense.view'            THEN public.expense_role_rank(p_user)            >= 10\r\n      -- Typing a draft is a cashier/warehouse action: it commits nothing.\r\n      WHEN 'expense.create'          THEN public.expense_role_rank(p_user)            >= 10\r\n      WHEN 'expense.edit'            THEN public.expense_role_rank(p_user)            >= 10\r\n      WHEN 'expense.submit'          THEN public.expense_role_rank(p_user)            >= 10\r\n      -- Approval is a control, not a data-entry step.\r\n      WHEN 'expense.approve'         THEN public.expense_role_rank(p_user)            >= 40\r\n      WHEN 'expense.reject'          THEN public.expense_role_rank(p_user)            >= 40\r\n      WHEN 'expense.post'            THEN public.expense_role_rank(p_user)            >= 30\r\n      -- Money leaving the drawer needs the same bar as posting.\r\n      WHEN 'expense.pay'             THEN public.expense_role_rank(p_user)            >= 20\r\n      WHEN 'expense.reverse'         THEN public.expense_role_rank(p_user)            >= 30\r\n      WHEN 'expense.cancel'          THEN public.expense_role_rank(p_user)            >= 40\r\n      WHEN 'expense.category.manage' THEN public.expense_role_rank(p_user)            >= 40\r\n      WHEN 'expense.dimension.manage' THEN public.expense_role_rank(p_user)           >= 40\r\n      WHEN 'expense.report'          THEN public.expense_role_rank(p_user)            >= 30\r\n      WHEN 'expense.payment.reverse' THEN public.expense_role_rank(p_user)            >= 30\r\n      ELSE false\r\n    END\r\n$function$","CREATE OR REPLACE FUNCTION public.expense_can_write_document(p_entry_id uuid, p_user uuid)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n STABLE SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.expense_entries e\r\n    WHERE e.id = p_entry_id\r\n      AND (\r\n        -- An approver or accountant can act on any document.\r\n        public.expense_role_rank(p_user) >= 30\r\n        -- Everyone else can act only on a document they own, and only while it\r\n        -- is still theirs to change. Posted documents are frozen for all.\r\n        OR (e.created_by = p_user AND e.status IN ('DRAFT', 'REJECTED'))\r\n      )\r\n  )\r\n$function$","CREATE OR REPLACE FUNCTION public.expense_detail(p_entry_id uuid)\r\n RETURNS jsonb\r\n LANGUAGE sql\r\n STABLE\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT jsonb_build_object(\r\n    'entry', to_jsonb(e) || jsonb_build_object(\r\n      'supplier_name',    s.name,\r\n      'employee_name',    pr.full_name,\r\n      'warehouse_name',   w.name,\r\n      'cost_center_name', cc.name,\r\n      'project_name',     pj.name,\r\n      'created_by_name',  cb.full_name,\r\n      'approved_by_name', ab.full_name,\r\n      'posted_by_name',   pb.full_name,\r\n      -- The capability set is computed server-side so the UI does not have to\r\n      -- re-derive the role matrix in JavaScript and drift from the database.\r\n      'can_edit',    (e.status IN ('DRAFT', 'REJECTED'))\r\n                     AND (e.created_by = auth.uid() OR public.expense_role_rank(auth.uid()) >= 30),\r\n      'can_submit',  (e.status IN ('DRAFT', 'REJECTED'))\r\n                     AND (e.created_by = auth.uid() OR public.expense_role_rank(auth.uid()) >= 30),\r\n      'can_approve', (e.status = 'SUBMITTED') AND public.expense_can(auth.uid(), 'expense.approve'),\r\n      'can_post',    (e.status IN ('APPROVED', 'DRAFT')) AND public.expense_can(auth.uid(), 'expense.post'),\r\n      'can_pay',     (e.status IN ('POSTED', 'PARTIALLY_PAID')) AND public.expense_can(auth.uid(), 'expense.pay'),\r\n      'can_cancel',  (e.status IN ('DRAFT', 'REJECTED', 'SUBMITTED', 'APPROVED'))\r\n                     AND public.expense_can(auth.uid(), 'expense.cancel'),\r\n      'can_reverse', (e.status IN ('POSTED', 'PARTIALLY_PAID', 'PAID'))\r\n                     AND public.expense_can(auth.uid(), 'expense.reverse')\r\n    ),\r\n    'lines', COALESCE((\r\n      SELECT jsonb_agg(\r\n        to_jsonb(l) || jsonb_build_object(\r\n          'category_name',    c.name,\r\n          'category_name_ar', c.name_ar,\r\n          'cost_center_name', cc.name,\r\n          'project_name',     pj.name\r\n        ) ORDER BY l.line_no\r\n      )\r\n      FROM public.expense_lines l\r\n      LEFT JOIN public.expense_categories c   ON c.id  = l.category_id\r\n      LEFT JOIN public.expense_cost_centers cc ON cc.id = l.cost_center_id\r\n      LEFT JOIN public.expense_projects pj    ON pj.id = l.project_id\r\n      WHERE l.entry_id = e.id\r\n    ), '[]'::jsonb),\r\n    'payments', COALESCE((\r\n      SELECT jsonb_agg(to_jsonb(p) || jsonb_build_object('created_by_name', pc.full_name)\r\n                       ORDER BY p.payment_date, p.created_at)\r\n      FROM public.expense_payments p\r\n      LEFT JOIN public.profiles pc ON pc.id = p.created_by\r\n      WHERE p.entry_id = e.id\r\n    ), '[]'::jsonb),\r\n    'approvals', COALESCE((\r\n      SELECT jsonb_agg(to_jsonb(a) || jsonb_build_object('actor_name', ac.full_name)\r\n                       ORDER BY a.sequence)\r\n      FROM public.expense_approvals a\r\n      LEFT JOIN public.profiles ac ON ac.id = a.actor_id\r\n      WHERE a.entry_id = e.id\r\n    ), '[]'::jsonb),\r\n    'attachments', COALESCE((\r\n      SELECT jsonb_agg(to_jsonb(t) || jsonb_build_object('uploaded_by_name', tc.full_name)\r\n                       ORDER BY t.created_at)\r\n      FROM public.expense_attachments t\r\n      LEFT JOIN public.profiles tc ON tc.id = t.uploaded_by\r\n      WHERE t.entry_id = e.id\r\n    ), '[]'::jsonb)\r\n  )\r\n  FROM public.expense_entries e\r\n  LEFT JOIN public.suppliers s  ON s.id  = e.supplier_id\r\n  LEFT JOIN public.profiles  pr ON pr.id = e.employee_id\r\n  LEFT JOIN public.profiles  cb ON cb.id = e.created_by\r\n  LEFT JOIN public.profiles  ab ON ab.id = e.approved_by\r\n  LEFT JOIN public.profiles  pb ON pb.id = e.posted_by\r\n  LEFT JOIN public.warehouses w ON w.id  = e.warehouse_id\r\n  LEFT JOIN public.expense_cost_centers cc ON cc.id = e.cost_center_id\r\n  LEFT JOIN public.expense_projects pj      ON pj.id = e.project_id\r\n  WHERE e.id = p_entry_id\r\n$function$","CREATE OR REPLACE FUNCTION public.expense_log_action(p_entry_id uuid, p_action text, p_from expense_status, p_to expense_status, p_reason text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_actor    uuid := COALESCE(p_actor, auth.uid());\r\n  v_sequence integer;\r\nBEGIN\r\n  SELECT COALESCE(max(sequence), 0) + 1\r\n    INTO v_sequence\r\n  FROM public.expense_approvals\r\n  WHERE entry_id = p_entry_id;\r\n\r\n  INSERT INTO public.expense_approvals (\r\n    entry_id, sequence, action, from_status, to_status, actor_id, reason\r\n  )\r\n  VALUES (p_entry_id, v_sequence, p_action, p_from, p_to, v_actor,\r\n          nullif(btrim(coalesce(p_reason, '')), ''));\r\n\r\n  -- The generic audit log keeps the expense trail discoverable from the same\r\n  -- screen an owner already uses for every other module.\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_actor, 'expense.' || p_action, 'expense_entry', p_entry_id,\r\n          jsonb_build_object('from', p_from, 'to', p_to, 'reason', p_reason));\r\nEND $function$","CREATE OR REPLACE FUNCTION public.expense_lookups(p_include_archived boolean DEFAULT false)\r\n RETURNS jsonb\r\n LANGUAGE sql\r\n STABLE\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT jsonb_build_object(\r\n    'categories', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', c.id, 'name', c.name, 'name_ar', c.name_ar,\r\n               'is_active', c.is_active, 'sort_order', c.sort_order,\r\n               'usage_count', (SELECT count(*) FROM public.expense_lines l WHERE l.category_id = c.id)\r\n             ) ORDER BY c.sort_order, c.name)\r\n      FROM public.expense_categories c\r\n      WHERE p_include_archived OR c.is_active\r\n    ), '[]'::jsonb),\r\n    'warehouses', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', w.id, 'name', w.name, 'name_ar', w.name_ar, 'is_default', w.is_default\r\n             ) ORDER BY w.name)\r\n      FROM public.warehouses w\r\n      WHERE w.is_active IS NOT FALSE\r\n    ), '[]'::jsonb),\r\n    'cost_centers', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', cc.id, 'code', cc.code, 'name', cc.name, 'name_ar', cc.name_ar\r\n             ) ORDER BY cc.name)\r\n      FROM public.expense_cost_centers cc\r\n      WHERE cc.is_active\r\n    ), '[]'::jsonb),\r\n    'projects', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', pj.id, 'code', pj.code, 'name', pj.name, 'name_ar', pj.name_ar\r\n             ) ORDER BY pj.name)\r\n      FROM public.expense_projects pj\r\n      WHERE pj.is_active\r\n    ), '[]'::jsonb),\r\n    'suppliers', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name) ORDER BY s.name)\r\n      FROM public.suppliers s\r\n      WHERE s.is_active IS NOT FALSE\r\n    ), '[]'::jsonb),\r\n    'employees', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) ORDER BY p.full_name)\r\n      FROM public.profiles p\r\n      WHERE p.is_active IS NOT FALSE\r\n        AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = p.id)\r\n    ), '[]'::jsonb),\r\n    'financial_accounts', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', a.id, 'code', a.code, 'name_ar', a.name_ar,\r\n               'account_type', a.account_type,\r\n               'requires_reconciliation', a.requires_reconciliation\r\n             ) ORDER BY a.code)\r\n      FROM public.accounts a\r\n      WHERE a.is_active IS NOT FALSE\r\n        AND (a.requires_reconciliation IS TRUE OR a.code LIKE '11%')\r\n    ), '[]'::jsonb)\r\n  )\r\n$function$","CREATE OR REPLACE FUNCTION public.expense_report(p_group_by text DEFAULT 'category'::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_status expense_status[] DEFAULT NULL::expense_status[], p_warehouse_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100)\r\n RETURNS TABLE(group_key text, label text, label_ar text, entry_count bigint, total_amount numeric, paid_amount numeric, outstanding numeric)\r\n LANGUAGE plpgsql\r\n STABLE\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);\r\nBEGIN\r\n  -- Status default: only documents that actually affect the books. A report\r\n  -- that silently included drafts would disagree with the ledger.\r\n  IF p_status IS NULL THEN\r\n    p_status := ARRAY['POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED']::public.expense_status[];\r\n  END IF;\r\n\r\n  IF p_group_by = 'category' THEN\r\n    RETURN QUERY\r\n    SELECT\r\n      COALESCE(l.category_id::text, 'none'),\r\n      COALESCE(c.name, 'Uncategorised'),\r\n      COALESCE(c.name_ar, c.name, 'غير مصنّف'),\r\n      count(DISTINCT e.id),\r\n      COALESCE(sum(l.gross_amount), 0),\r\n      -- Paid is allocated pro-rata by line share, because a payment settles the\r\n      -- document, not a line. Allocating it any other way (e.g. by category\r\n      -- order) would make the report disagree with the header totals.\r\n      COALESCE(sum(l.gross_amount * CASE\r\n        WHEN e.total_amount > 0 THEN e.paid_amount / e.total_amount ELSE 0 END), 0),\r\n      COALESCE(sum(l.gross_amount * CASE\r\n        WHEN e.total_amount > 0 THEN e.remaining_amount / e.total_amount ELSE 0 END), 0)\r\n    FROM public.expense_lines l\r\n    JOIN public.expense_entries e ON e.id = l.entry_id\r\n    LEFT JOIN public.expense_categories c ON c.id = l.category_id\r\n    WHERE e.status = ANY (p_status)\r\n      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)\r\n      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)\r\n      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)\r\n      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)\r\n      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)\r\n    GROUP BY l.category_id, c.name, c.name_ar\r\n    ORDER BY 5 DESC\r\n    LIMIT v_limit;\r\n\r\n  ELSIF p_group_by = 'month' THEN\r\n    RETURN QUERY\r\n    SELECT\r\n      to_char(date_trunc('month', e.expense_date), 'YYYY-MM'),\r\n      to_char(date_trunc('month', e.expense_date), 'YYYY-MM'),\r\n      to_char(date_trunc('month', e.expense_date), 'YYYY-MM'),\r\n      count(*),\r\n      COALESCE(sum(e.total_amount), 0),\r\n      COALESCE(sum(e.paid_amount), 0),\r\n      COALESCE(sum(e.remaining_amount), 0)\r\n    FROM public.expense_entries e\r\n    WHERE e.status = ANY (p_status)\r\n      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)\r\n      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)\r\n      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)\r\n      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)\r\n      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)\r\n    GROUP BY date_trunc('month', e.expense_date)\r\n    -- Oldest first: a trend chart reads left to right, unlike a ranking table.\r\n    ORDER BY 1 ASC\r\n    LIMIT v_limit;\r\n\r\n  ELSIF p_group_by = 'warehouse' THEN\r\n    RETURN QUERY\r\n    SELECT\r\n      COALESCE(e.warehouse_id::text, 'none'),\r\n      COALESCE(w.name, 'Unassigned'),\r\n      COALESCE(w.name_ar, w.name, 'غير محدد'),\r\n      count(*), COALESCE(sum(e.total_amount), 0),\r\n      COALESCE(sum(e.paid_amount), 0), COALESCE(sum(e.remaining_amount), 0)\r\n    FROM public.expense_entries e\r\n    LEFT JOIN public.warehouses w ON w.id = e.warehouse_id\r\n    WHERE e.status = ANY (p_status)\r\n      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)\r\n      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)\r\n      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)\r\n      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)\r\n      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)\r\n    GROUP BY e.warehouse_id, w.name, w.name_ar\r\n    ORDER BY 5 DESC\r\n    LIMIT v_limit;\r\n\r\n  ELSIF p_group_by = 'cost_center' THEN\r\n    RETURN QUERY\r\n    SELECT\r\n      COALESCE(e.cost_center_id::text, 'none'),\r\n      COALESCE(cc.name, 'Unassigned'),\r\n      COALESCE(cc.name_ar, cc.name, 'غير محدد'),\r\n      count(*), COALESCE(sum(e.total_amount), 0),\r\n      COALESCE(sum(e.paid_amount), 0), COALESCE(sum(e.remaining_amount), 0)\r\n    FROM public.expense_entries e\r\n    LEFT JOIN public.expense_cost_centers cc ON cc.id = e.cost_center_id\r\n    WHERE e.status = ANY (p_status)\r\n      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)\r\n      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)\r\n      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)\r\n      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)\r\n      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)\r\n    GROUP BY e.cost_center_id, cc.name, cc.name_ar\r\n    ORDER BY 5 DESC\r\n    LIMIT v_limit;\r\n\r\n  ELSIF p_group_by = 'project' THEN\r\n    RETURN QUERY\r\n    SELECT\r\n      COALESCE(e.project_id::text, 'none'),\r\n      COALESCE(pj.name, 'Unassigned'),\r\n      COALESCE(pj.name_ar, pj.name, 'غير محدد'),\r\n      count(*), COALESCE(sum(e.total_amount), 0),\r\n      COALESCE(sum(e.paid_amount), 0), COALESCE(sum(e.remaining_amount), 0)\r\n    FROM public.expense_entries e\r\n    LEFT JOIN public.expense_projects pj ON pj.id = e.project_id\r\n    WHERE e.status = ANY (p_status)\r\n      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)\r\n      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)\r\n      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)\r\n      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)\r\n      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)\r\n    GROUP BY e.project_id, pj.name, pj.name_ar\r\n    ORDER BY 5 DESC\r\n    LIMIT v_limit;\r\n\r\n  ELSIF p_group_by = 'payee' THEN\r\n    RETURN QUERY\r\n    SELECT\r\n      COALESCE(e.supplier_id::text, e.employee_id::text, e.payee_name, 'none'),\r\n      COALESCE(s.name, pr.full_name, e.payee_name, 'Unnamed payee'),\r\n      COALESCE(s.name, pr.full_name, e.payee_name, 'بدون جهة'),\r\n      count(*), COALESCE(sum(e.total_amount), 0),\r\n      COALESCE(sum(e.paid_amount), 0), COALESCE(sum(e.remaining_amount), 0)\r\n    FROM public.expense_entries e\r\n    LEFT JOIN public.suppliers s ON s.id = e.supplier_id\r\n    LEFT JOIN public.profiles  pr ON pr.id = e.employee_id\r\n    WHERE e.status = ANY (p_status)\r\n      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)\r\n      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)\r\n      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)\r\n      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)\r\n      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)\r\n    GROUP BY e.supplier_id, s.name, e.employee_id, pr.full_name, e.payee_name\r\n    ORDER BY 5 DESC\r\n    LIMIT v_limit;\r\n\r\n  ELSIF p_group_by = 'status' THEN\r\n    RETURN QUERY\r\n    SELECT\r\n      e.status::text, e.status::text, e.status::text,\r\n      count(*), COALESCE(sum(e.total_amount), 0),\r\n      COALESCE(sum(e.paid_amount), 0), COALESCE(sum(e.remaining_amount), 0)\r\n    FROM public.expense_entries e\r\n    WHERE (p_date_from IS NULL OR e.expense_date >= p_date_from)\r\n      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)\r\n      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)\r\n      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)\r\n      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)\r\n      AND (p_status IS NULL OR e.status = ANY (p_status))\r\n    GROUP BY e.status\r\n    ORDER BY 5 DESC\r\n    LIMIT v_limit;\r\n\r\n  ELSE\r\n    RAISE EXCEPTION\r\n      'Unsupported group_by: %. Allowed: category, month, warehouse, cost_center, project, payee, status',\r\n      p_group_by\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.expense_settlement_status(p_current expense_status, p_paid numeric, p_total numeric)\r\n RETURNS expense_status\r\n LANGUAGE sql SET search_path = public\r\n IMMUTABLE\r\nAS $function$\r\n  SELECT CASE\r\n    WHEN p_current NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID') THEN p_current\r\n    WHEN coalesce(p_total, 0) <= 0 THEN p_current\r\n    WHEN coalesce(p_paid, 0) <= 0 THEN 'POSTED'::public.expense_status\r\n    -- Deliberately `>=` on the paid side and `>` on the zero side: a rounding\r\n    -- remainder of less than half a unit must settle as fully paid rather than\r\n    -- leaving a document permanently \\"partially paid\\".\r\n    WHEN coalesce(p_paid, 0) >= coalesce(p_total, 0) - 0.005 THEN 'PAID'::public.expense_status\r\n    ELSE 'PARTIALLY_PAID'::public.expense_status\r\n  END\r\n$function$","CREATE OR REPLACE FUNCTION public.expense_summary(p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_warehouse_id uuid DEFAULT NULL::uuid)\r\n RETURNS jsonb\r\n LANGUAGE sql\r\n STABLE\r\n SET search_path TO 'public'\r\nAS $function$\r\n  WITH scoped AS (\r\n    SELECT e.*\r\n    FROM public.expense_entries e\r\n    WHERE (p_date_from IS NULL OR e.expense_date >= p_date_from)\r\n      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)\r\n      AND (p_warehouse_id IS NULL OR e.warehouse_id = p_warehouse_id)\r\n      AND e.status NOT IN ('CANCELLED', 'REVERSED')\r\n  )\r\n  SELECT jsonb_build_object(\r\n    'period_total',      COALESCE(sum(total_amount), 0),\r\n    'posted_total',      COALESCE(sum(total_amount) FILTER (\r\n                           WHERE status IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED')), 0),\r\n    'paid_total',        COALESCE(sum(paid_amount), 0),\r\n    'outstanding_total', COALESCE(sum(remaining_amount) FILTER (\r\n                           WHERE status IN ('POSTED', 'PARTIALLY_PAID') AND remaining_amount > 0.005), 0),\r\n    'pending_total',     COALESCE(sum(total_amount) FILTER (WHERE status = 'SUBMITTED'), 0),\r\n    'draft_total',       COALESCE(sum(total_amount) FILTER (WHERE status IN ('DRAFT', 'REJECTED')), 0),\r\n    'total_count',       count(*),\r\n    'pending_count',     count(*) FILTER (WHERE status = 'SUBMITTED'),\r\n    'unpaid_count',      count(*) FILTER (WHERE status = 'POSTED'),\r\n    'partial_count',     count(*) FILTER (WHERE status = 'PARTIALLY_PAID'),\r\n    'paid_count',        count(*) FILTER (WHERE status IN ('PAID', 'CLOSED')),\r\n    'draft_count',       count(*) FILTER (WHERE status IN ('DRAFT', 'REJECTED')),\r\n    'overdue_count',     count(*) FILTER (\r\n                           WHERE status IN ('POSTED', 'PARTIALLY_PAID')\r\n                             AND due_date IS NOT NULL\r\n                             AND due_date < CURRENT_DATE\r\n                             AND remaining_amount > 0.005),\r\n    'overdue_total',     COALESCE(sum(remaining_amount) FILTER (\r\n                           WHERE status IN ('POSTED', 'PARTIALLY_PAID')\r\n                             AND due_date IS NOT NULL\r\n                             AND due_date < CURRENT_DATE\r\n                             AND remaining_amount > 0.005), 0)\r\n  )\r\n  FROM scoped$function$","CREATE OR REPLACE FUNCTION public.expense_write_lines(p_entry_id uuid, p_lines jsonb, p_tax_mode expense_tax_mode, OUT o_total numeric, OUT o_count integer)\r\n RETURNS record\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_line        jsonb;\r\n  v_index       integer := 0;\r\n  v_qty         numeric;\r\n  v_price       numeric;\r\n  v_rate        numeric;\r\n  v_gross       numeric;\r\n  v_net         numeric;\r\n  v_tax         numeric;\r\nBEGIN\r\n  o_total := 0;\r\n  o_count := 0;\r\n\r\n  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN\r\n    RAISE EXCEPTION 'At least one expense line is required' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  -- Replacing the whole set is intentional: a partial update would need a line\r\n  -- identity from the client, and clients do not own line identity here.\r\n  DELETE FROM public.expense_lines WHERE entry_id = p_entry_id;\r\n\r\n  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP\r\n    v_index := v_index + 1;\r\n\r\n    v_qty   := COALESCE((v_line ->> 'quantity')::numeric, 1);\r\n    v_price := COALESCE((v_line ->> 'unit_price')::numeric, 0);\r\n    v_rate  := COALESCE((v_line ->> 'tax_rate')::numeric, 0);\r\n\r\n    IF v_qty IS NULL OR v_qty <= 0 THEN\r\n      RAISE EXCEPTION 'Line %: quantity must be greater than zero', v_index USING ERRCODE = '22023';\r\n    END IF;\r\n    IF v_price IS NULL OR v_price < 0 THEN\r\n      RAISE EXCEPTION 'Line %: unit price cannot be negative', v_index USING ERRCODE = '22023';\r\n    END IF;\r\n    IF v_rate < 0 OR v_rate > 100 THEN\r\n      RAISE EXCEPTION 'Line %: tax rate must be between 0 and 100', v_index USING ERRCODE = '22023';\r\n    END IF;\r\n\r\n    -- The client sends what the operator typed — the gross figure on the paper\r\n    -- bill. Net and tax are derived here so the two can never disagree, and so\r\n    -- the arithmetic is identical for a JS client and a future import script.\r\n    v_gross := public.expense_round(v_qty * v_price);\r\n    v_net   := public.expense_line_net(v_gross, v_rate, p_tax_mode);\r\n    v_tax   := public.expense_line_tax(v_gross, v_rate, p_tax_mode);\r\n\r\n    INSERT INTO public.expense_lines (\r\n      entry_id, line_no, description, category_id, quantity, unit_price,\r\n      net_amount, tax_rate, tax_amount, gross_amount,\r\n      cost_center_id, project_id, note\r\n    )\r\n    VALUES (\r\n      p_entry_id,\r\n      v_index,\r\n      nullif(btrim(coalesce(v_line ->> 'description', '')), ''),\r\n      nullif(btrim(coalesce(v_line ->> 'category_id', '')), '')::uuid,\r\n      v_qty,\r\n      v_price,\r\n      v_net,\r\n      v_rate,\r\n      v_tax,\r\n      v_gross,\r\n      nullif(btrim(coalesce(v_line ->> 'cost_center_id', '')), '')::uuid,\r\n      nullif(btrim(coalesce(v_line ->> 'project_id', '')), '')::uuid,\r\n      nullif(btrim(coalesce(v_line ->> 'note', '')), '')\r\n    );\r\n\r\n    o_total := o_total + v_gross;\r\n    o_count := o_count + 1;\r\n  END LOOP;\r\n\r\n  o_total := public.expense_round(o_total);\r\n\r\n  IF o_total <= 0 THEN\r\n    RAISE EXCEPTION 'Expense total must be greater than zero' USING ERRCODE = '22023';\r\n  END IF;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.list_expenses(p_search text DEFAULT NULL::text, p_status expense_status[] DEFAULT NULL::expense_status[], p_category_id uuid DEFAULT NULL::uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_employee_id uuid DEFAULT NULL::uuid, p_payment_state text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_amount_min numeric DEFAULT NULL::numeric, p_amount_max numeric DEFAULT NULL::numeric, p_category_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 50, p_cursor_date date DEFAULT NULL::date, p_cursor_id uuid DEFAULT NULL::uuid)\r\n RETURNS TABLE(id uuid, reference text, status expense_status, entry_type expense_entry_type, payee_type expense_payee_type, payee_name text, supplier_id uuid, supplier_name text, employee_id uuid, employee_name text, warehouse_id uuid, warehouse_name text, cost_center_id uuid, cost_center_name text, project_id uuid, project_name text, expense_date date, due_date date, posting_date date, description text, note text, total_amount numeric, paid_amount numeric, remaining_amount numeric, line_count integer, primary_category text, primary_category_ar text, version integer, created_by uuid, created_by_name text, created_at timestamp with time zone, approved_at timestamp with time zone, posted_at timestamp with time zone, total_count bigint, next_cursor_date date, next_cursor_id uuid)\r\n LANGUAGE sql\r\n STABLE\r\n SET search_path TO 'public'\r\nAS $function$\r\n  WITH filtered AS (\r\n    SELECT\r\n      e.id, e.reference, e.status, e.entry_type, e.payee_type, e.payee_name,\r\n      e.supplier_id, e.employee_id, e.warehouse_id, e.cost_center_id, e.project_id,\r\n      e.expense_date, e.due_date, e.posting_date, e.description, e.note,\r\n      e.total_amount, e.paid_amount, e.remaining_amount, e.line_count,\r\n      e.version, e.created_by, e.created_at, e.approved_at, e.posted_at\r\n    FROM public.expense_entries e\r\n    WHERE\r\n      -- Reference first: it is the identifier an operator actually types.\r\n      (p_search IS NULL OR btrim(p_search) = '' OR\r\n        e.reference ILIKE '%' || btrim(p_search) || '%' OR\r\n        COALESCE(e.description, '') ILIKE '%' || btrim(p_search) || '%' OR\r\n        COALESCE(e.note, '')        ILIKE '%' || btrim(p_search) || '%' OR\r\n        COALESCE(e.payee_name, '')  ILIKE '%' || btrim(p_search) || '%')\r\n      AND (p_status IS NULL OR e.status = ANY (p_status))\r\n      AND (p_warehouse_id   IS NULL OR e.warehouse_id   = p_warehouse_id)\r\n      AND (p_cost_center_id IS NULL OR e.cost_center_id = p_cost_center_id)\r\n      AND (p_project_id     IS NULL OR e.project_id     = p_project_id)\r\n      AND (p_supplier_id    IS NULL OR e.supplier_id    = p_supplier_id)\r\n      AND (p_employee_id    IS NULL OR e.employee_id    = p_employee_id)\r\n      AND (p_date_from IS NULL OR e.expense_date >= p_date_from)\r\n      AND (p_date_to   IS NULL OR e.expense_date <= p_date_to)\r\n      AND (p_amount_min IS NULL OR e.total_amount >= p_amount_min)\r\n      AND (p_amount_max IS NULL OR e.total_amount <= p_amount_max)\r\n      -- Settlement is derived, never stored as a filter column, so the three\r\n      -- buckets are expressed against the real amounts.\r\n      AND (\r\n        p_payment_state IS NULL\r\n        OR (p_payment_state = 'unpaid'  AND e.paid_amount <= 0)\r\n        OR (p_payment_state = 'partial' AND e.paid_amount > 0\r\n                                        AND e.paid_amount < e.total_amount - 0.005)\r\n        OR (p_payment_state = 'paid'    AND e.paid_amount >= e.total_amount - 0.005)\r\n      )\r\n      -- Category lives on the lines, so this is an EXISTS rather than a join:\r\n      -- a join would duplicate the document once per matching line and break\r\n      -- the keyset page size.\r\n      AND (\r\n        p_category_id IS NULL\r\n        OR EXISTS (SELECT 1 FROM public.expense_lines l\r\n                   WHERE l.entry_id = e.id AND l.category_id = p_category_id)\r\n      )\r\n      AND (\r\n        p_category_ids IS NULL OR cardinality(p_category_ids) = 0\r\n        OR EXISTS (SELECT 1 FROM public.expense_lines l\r\n                   WHERE l.entry_id = e.id AND l.category_id = ANY (p_category_ids))\r\n      )\r\n      -- Keyset predicate. Matches the (expense_date DESC, id DESC) index exactly.\r\n      AND (\r\n        p_cursor_date IS NULL\r\n        OR (e.expense_date, e.id) < (p_cursor_date, COALESCE(p_cursor_id, e.id))\r\n      )\r\n    ORDER BY e.expense_date DESC, e.id DESC\r\n    LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200)\r\n  ),\r\n  -- The count is computed over the same predicate but without the page limit,\r\n  -- with a window aggregate so it costs one scan rather than two round-trips.\r\n  counted AS (\r\n    SELECT\r\n      f.*,\r\n      count(*) OVER () AS page_count,\r\n      (SELECT count(*) FROM public.expense_entries e2\r\n       WHERE (p_date_from IS NULL OR e2.expense_date >= p_date_from)\r\n         AND (p_date_to   IS NULL OR e2.expense_date <= p_date_to)\r\n         AND (p_status IS NULL OR e2.status = ANY (p_status))) AS total_count\r\n    FROM filtered f\r\n  )\r\n  SELECT\r\n    c.id, c.reference, c.status, c.entry_type, c.payee_type, c.payee_name,\r\n    c.supplier_id, s.name,\r\n    c.employee_id, pr.full_name,\r\n    c.warehouse_id, w.name,\r\n    c.cost_center_id, cc.name,\r\n    c.project_id, pj.name,\r\n    c.expense_date, c.due_date, c.posting_date, c.description, c.note,\r\n    c.total_amount, c.paid_amount, c.remaining_amount, c.line_count,\r\n    cat.name, cat.name_ar,\r\n    c.version, c.created_by, pr2.full_name, c.created_at, c.approved_at, c.posted_at,\r\n    c.total_count,\r\n    -- The cursor for the next page is the last row of this one. When the page\r\n    -- is the final one these are still populated but the caller is told to stop\r\n    -- by `page_count < p_limit`; returning them keeps the contract uniform.\r\n    c.expense_date,\r\n    c.id\r\n  FROM counted c\r\n  -- LEFT JOINs, deliberately: an expense with no supplier, no cost centre and\r\n  -- no creator must still appear. An INNER JOIN here would make documents\r\n  -- disappear from the register depending on unrelated reference data.\r\n  LEFT JOIN public.suppliers s        ON s.id = c.supplier_id\r\n  LEFT JOIN public.profiles  pr       ON pr.id = c.employee_id\r\n  LEFT JOIN public.profiles  pr2      ON pr2.id = c.created_by\r\n  LEFT JOIN public.warehouses w       ON w.id = c.warehouse_id\r\n  LEFT JOIN public.expense_cost_centers cc ON cc.id = c.cost_center_id\r\n  LEFT JOIN public.expense_projects pj ON pj.id = c.project_id\r\n  -- The \\"primary\\" category is the largest line by gross amount — the one an\r\n  -- operator would name if asked \\"what was this expense for?\\". Deterministic\r\n  -- tie-break on line_no so the same document always shows the same label.\r\n  LEFT JOIN LATERAL (\r\n    SELECT l.category_id\r\n    FROM public.expense_lines l\r\n    WHERE l.entry_id = c.id\r\n    ORDER BY l.gross_amount DESC, l.line_no ASC\r\n    LIMIT 1\r\n  ) prim ON true\r\n  LEFT JOIN public.expense_categories cat ON cat.id = prim.category_id\r\n  ORDER BY c.expense_date DESC, c.id DESC\r\n$function$","CREATE OR REPLACE FUNCTION public.migrate_legacy_expenses(p_mode text DEFAULT 'draft'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_batch_size integer DEFAULT 500, p_dry_run boolean DEFAULT true)\r\n RETURNS TABLE(processed integer, created integer, skipped integer, failed integer)\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user       uuid := public.expense_actor();\r\n  v_row        record;\r\n  v_entry_id   uuid;\r\n  v_processed  integer := 0;\r\n  v_created    integer := 0;\r\n  v_skipped    integer := 0;\r\n  v_failed     integer := 0;\r\n  v_status     public.expense_status;\r\n  v_payment    public.payment_method;\r\n  v_batch      integer := LEAST(GREATEST(COALESCE(p_batch_size, 500), 1), 5000);\r\nBEGIN\r\n  -- A data migration is an owner/manager action. `expense.post` is the closest\r\n  -- existing capability in weight: it decides whether a number reaches the books.\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.post');\r\n\r\n  IF p_mode NOT IN ('draft', 'unpaid', 'paid') THEN\r\n    RAISE EXCEPTION 'mode must be draft, unpaid or paid (got %)', p_mode\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  v_status := CASE p_mode\r\n                WHEN 'draft'  THEN 'DRAFT'::public.expense_status\r\n                ELSE 'POSTED'::public.expense_status\r\n              END;\r\n\r\n  FOR v_row IN\r\n    SELECT x.*\r\n    FROM public.expenses x\r\n    -- The NOT EXISTS is the idempotency guard and it is the reason a re-run is\r\n    -- free: an already-bridged row is never revisited, so its document is never\r\n    -- duplicated and its approval history is never rewritten.\r\n    WHERE NOT EXISTS (\r\n      SELECT 1 FROM public.expense_entries e WHERE e.legacy_expense_id = x.id\r\n    )\r\n      AND (p_from IS NULL OR x.expense_date >= p_from)\r\n      AND (p_to   IS NULL OR x.expense_date <= p_to)\r\n    ORDER BY x.expense_date, x.created_at\r\n    LIMIT v_batch\r\n  LOOP\r\n    v_processed := v_processed + 1;\r\n\r\n    BEGIN\r\n      -- A zero-amount legacy row cannot become a valid document (the foundation\r\n      -- requires a positive total) and carries no information. Counted rather\r\n      -- than silently dropped, so the operator sees the number and can decide.\r\n      IF COALESCE(v_row.amount, 0) <= 0 THEN\r\n        v_skipped := v_skipped + 1;\r\n        CONTINUE;\r\n      END IF;\r\n\r\n      INSERT INTO public.expense_entries (\r\n        reference, entry_type, status, source_kind,\r\n        payee_type, expense_date,\r\n        description, note,\r\n        total_amount, tax_mode, currency, currency_symbol,\r\n        created_by, legacy_expense_id,\r\n        posting_date, posted_by, posted_at\r\n      )\r\n      VALUES (\r\n        -- The legacy row keeps its own id in the reference, so an operator can\r\n        -- still find a document in the new register using the number they have\r\n        -- always quoted: EXP-LEG-<first 8 of the legacy uuid>.\r\n        'EXP-LEG-' || upper(left(replace(v_row.id::text, '-', ''), 8)),\r\n        'DIRECT',\r\n        v_status,\r\n        'LEGACY',\r\n        'NONE',\r\n        v_row.expense_date,\r\n        COALESCE(\r\n          NULLIF(btrim(COALESCE(v_row.note, '')), ''),\r\n          (SELECT COALESCE(c.name_ar, c.name) FROM public.expense_categories c\r\n            WHERE c.id = v_row.category_id),\r\n          'Migrated expense'\r\n        ),\r\n        v_row.note,\r\n        public.expense_round(v_row.amount),\r\n        'NONE',\r\n        COALESCE((SELECT NULLIF(btrim(currency), '') FROM public.company_settings ORDER BY id LIMIT 1), 'YER'),\r\n        COALESCE((SELECT NULLIF(btrim(currency_symbol), '') FROM public.company_settings ORDER BY id LIMIT 1), '﷼'),\r\n        -- `created_by` is deliberately NOT taken from the legacy row: the\r\n        -- original author may have been deleted, and a null creator is honest.\r\n        -- The actor performing the migration is recorded in the audit trail\r\n        -- instead, which is where attribution for a migration belongs.\r\n        NULL,\r\n        v_row.id,\r\n        CASE WHEN v_status = 'POSTED' THEN v_row.expense_date END,\r\n        CASE WHEN v_status = 'POSTED' THEN v_user END,\r\n        CASE WHEN v_status = 'POSTED' THEN now() END\r\n      )\r\n      RETURNING id INTO v_entry_id;\r\n\r\n      -- One line per legacy row: the old model could only express one amount,\r\n      -- so inventing a split would be fabricating structure that was never\r\n      -- there. What it DID record — the amount, the category and the note — is\r\n      -- preserved exactly.\r\n      INSERT INTO public.expense_lines (\r\n        entry_id, line_no, description, category_id, quantity, unit_price,\r\n        net_amount, tax_rate, tax_amount, gross_amount\r\n      )\r\n      VALUES (\r\n        v_entry_id, 1,\r\n        NULLIF(btrim(COALESCE(v_row.note, '')), ''),\r\n        v_row.category_id, 1, public.expense_round(v_row.amount),\r\n        public.expense_round(v_row.amount), 0, 0,\r\n        public.expense_round(v_row.amount)\r\n      );\r\n\r\n      -- `credit` is the one legacy value that unambiguously means \\"not settled\\",\r\n      -- so it overrides the 'paid' mode rather than being overruled by it.\r\n      IF p_mode = 'paid' AND v_row.payment_method IS DISTINCT FROM 'credit' THEN\r\n        v_payment := COALESCE(v_row.payment_method, 'cash');\r\n\r\n        INSERT INTO public.expense_payments (\r\n          entry_id, amount, payment_date, payment_method, note,\r\n          idempotency_key, created_by\r\n        )\r\n        VALUES (\r\n          v_entry_id, public.expense_round(v_row.amount),\r\n          -- The legacy table records when the row was typed, not when it was\r\n          -- paid; used as the closest available evidence and labelled as such.\r\n          v_row.expense_date,\r\n          v_payment,\r\n          'Migrated from legacy expense ' || v_row.id::text,\r\n          'legacy:' || v_row.id::text,\r\n          v_user\r\n        )\r\n        ON CONFLICT DO NOTHING;\r\n      END IF;\r\n\r\n      INSERT INTO public.expense_approvals (\r\n        entry_id, sequence, action, from_status, to_status, actor_id, reason\r\n      )\r\n      VALUES (\r\n        v_entry_id, 1,\r\n        CASE WHEN v_status = 'POSTED' THEN 'posted' ELSE 'created' END,\r\n        NULL, v_status, v_user,\r\n        'Migrated from legacy expense ' || v_row.id::text || ' (mode: ' || p_mode || ')'\r\n      );\r\n\r\n      v_created := v_created + 1;\r\n    EXCEPTION WHEN OTHERS THEN\r\n      -- One bad row must not abort the batch. The failure is counted and the\r\n      -- message is raised as a notice so it reaches the operator's log without\r\n      -- rolling back the rows that succeeded.\r\n      v_failed := v_failed + 1;\r\n      RAISE WARNING 'legacy expense % could not be migrated: %', v_row.id, SQLERRM;\r\n    END;\r\n  END LOOP;\r\n\r\n  -- A dry run performs identical work and then throws it away. That is the\r\n  -- point: the validation, the reference generation and the line arithmetic are\r\n  -- exercised exactly as they would be for real, so a dry run actually proves\r\n  -- something. The exception below is caught by the caller, not an error path.\r\n  IF p_dry_run THEN\r\n    RAISE EXCEPTION 'DRY RUN: % processed, % would be created, % skipped, % failed — nothing was written',\r\n      v_processed, v_created, v_skipped, v_failed\r\n      USING ERRCODE = 'P0001';\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, payload)\r\n  VALUES (v_user, 'expense.legacy.migrated', 'expense_entry',\r\n          jsonb_build_object(\r\n            'mode', p_mode, 'processed', v_processed, 'created', v_created,\r\n            'skipped', v_skipped, 'failed', v_failed,\r\n            'from', p_from, 'to', p_to));\r\n\r\n  RETURN QUERY SELECT v_processed, v_created, v_skipped, v_failed;\r\nEND $function$","-- ── مرجع المصروف ──────────────────────────────────────────────────────\r\n-- تُنفَّذ فوق محرّك الترقيم المركزي (الترحيل 14).\r\n--\r\n-- كانت تقرأ بادئة المصروف من عمود `company_settings.expense_prefix`.\r\n-- **وذلك العمود غير موجود في الجدول** (الموجود: invoice_prefix و\r\n-- purchase_invoice_prefix فقط)، فكانت الدالة تفشل دائمًا بـ\r\n-- «column expense_prefix does not exist» عند أول مصروف في أي قاعدة جديدة.\r\n--\r\n-- ولم يكشفه شيء قبل الآن لأن أحدًا لم ينشئ مصروفًا على قاعدة مبنيّة من الصفر.\r\n--\r\n-- والعلاج ليس إضافة العمود: البادئة صارت خاصية إعداد لكل نوع مستند في\r\n-- document_numbering، في مكان واحد لكل الأنواع بدل عمود لكل نوع في\r\n-- company_settings. وهذا هو الاتجاه الصحيح بعد دمج المحرّك.\r\nCREATE OR REPLACE FUNCTION public.next_expense_reference()\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  RETURN public.fn_next_document_number('expense');\r\nEND $function$","CREATE OR REPLACE FUNCTION public.post_expense(p_entry_id uuid, p_expected_version integer DEFAULT NULL::integer, p_pay_now boolean DEFAULT false, p_payment_method payment_method DEFAULT 'cash'::payment_method, p_account_label text DEFAULT NULL::text, p_payment_date date DEFAULT NULL::date, p_idempotency_key text DEFAULT NULL::text)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  RETURN public.post_expense(\r\n    p_entry_id, p_expected_version, p_pay_now, p_payment_method,\r\n    p_account_label, p_payment_date, p_idempotency_key, NULL\r\n  );\r\nEND $function$","CREATE OR REPLACE FUNCTION public.post_expense(p_entry_id uuid, p_expected_version integer DEFAULT NULL::integer, p_pay_now boolean DEFAULT false, p_payment_method payment_method DEFAULT 'cash'::payment_method, p_account_label text DEFAULT NULL::text, p_payment_date date DEFAULT NULL::date, p_idempotency_key text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user  uuid := public.expense_actor();\r\n  v_entry public.expense_entries;\r\n  v_from  public.expense_status;\r\nBEGIN\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  v_from := v_entry.status;\r\n\r\n  IF v_from = 'POSTED' THEN\r\n    RETURN v_entry;\r\n  END IF;\r\n\r\n  IF v_from NOT IN ('APPROVED', 'DRAFT') THEN\r\n    RAISE EXCEPTION 'This expense cannot be posted from status %', v_from\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.post');\r\n\r\n  IF p_expected_version IS NOT NULL AND p_expected_version <> v_entry.version THEN\r\n    RAISE EXCEPTION 'This expense was changed by someone else. Reload it and try again.'\r\n      USING ERRCODE = '40001';\r\n  END IF;\r\n\r\n  IF v_entry.total_amount <= 0 OR v_entry.line_count = 0 THEN\r\n    RAISE EXCEPTION 'Cannot post an expense with no lines' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  IF v_from = 'DRAFT' AND NOT public.expense_can(v_user, 'expense.approve') THEN\r\n    RAISE EXCEPTION 'Submit this expense for approval before posting it'\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  UPDATE public.expense_entries\r\n     SET status       = 'POSTED',\r\n         posting_date = COALESCE(posting_date, CURRENT_DATE),\r\n         posted_by    = v_user,\r\n         posted_at    = now(),\r\n         version      = version + 1\r\n   WHERE id = p_entry_id\r\n  RETURNING * INTO v_entry;\r\n\r\n  PERFORM public.expense_log_action(p_entry_id, 'posted', v_from, 'POSTED', NULL, v_user);\r\n\r\n  IF p_pay_now THEN\r\n    SELECT * INTO v_entry FROM public.record_expense_payment(\r\n      p_entry_id,\r\n      v_entry.total_amount,\r\n      COALESCE(p_payment_date, CURRENT_DATE),\r\n      p_payment_method,\r\n      p_account_label,\r\n      NULL,\r\n      'Settled at posting',\r\n      COALESCE(p_idempotency_key, 'post:' || p_entry_id::text),\r\n      p_account_id\r\n    );\r\n  END IF;\r\n\r\n  RETURN v_entry;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.record_expense_payment(p_entry_id uuid, p_amount numeric, p_payment_date date DEFAULT CURRENT_DATE, p_payment_method payment_method DEFAULT 'cash'::payment_method, p_account_label text DEFAULT NULL::text, p_reference_no text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  RETURN public.record_expense_payment(\r\n    p_entry_id, p_amount, p_payment_date, p_payment_method,\r\n    p_account_label, p_reference_no, p_note, p_idempotency_key, NULL\r\n  );\r\nEND $function$","CREATE OR REPLACE FUNCTION public.record_expense_payment(p_entry_id uuid, p_amount numeric, p_payment_date date DEFAULT CURRENT_DATE, p_payment_method payment_method DEFAULT 'cash'::payment_method, p_account_label text DEFAULT NULL::text, p_reference_no text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user      uuid := public.expense_actor();\r\n  v_entry     public.expense_entries;\r\n  v_amount    numeric(18,2);\r\n  v_existing  public.expense_payments;\r\n  v_label     text := nullif(btrim(coalesce(p_account_label, '')), '');\r\nBEGIN\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.pay');\r\n\r\n  IF v_entry.status NOT IN ('POSTED', 'PARTIALLY_PAID') THEN\r\n    RAISE EXCEPTION 'Payments can only be recorded against posted expenses (current: %)', v_entry.status\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  v_amount := public.expense_round(p_amount);\r\n  IF v_amount <= 0 THEN\r\n    RAISE EXCEPTION 'Payment amount must be greater than zero' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  IF v_amount > v_entry.remaining_amount + 0.005 THEN\r\n    RAISE EXCEPTION 'Payment (%) exceeds remaining amount (%)', v_amount, v_entry.remaining_amount\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  -- If financial account provided, fetch label default if label is empty\r\n  IF p_account_id IS NOT NULL AND v_label IS NULL AND to_regclass('public.accounts') IS NOT NULL THEN\r\n    SELECT name_ar INTO v_label FROM public.accounts WHERE id = p_account_id;\r\n  END IF;\r\n\r\n  IF p_idempotency_key IS NOT NULL THEN\r\n    SELECT * INTO v_existing FROM public.expense_payments\r\n     WHERE idempotency_key = btrim(p_idempotency_key);\r\n    IF FOUND THEN\r\n      RETURN v_entry;\r\n    END IF;\r\n  END IF;\r\n\r\n  INSERT INTO public.expense_payments (\r\n    entry_id, amount, payment_date, payment_method,\r\n    account_label, reference_no, note, idempotency_key, created_by,\r\n    account_id\r\n  )\r\n  VALUES (\r\n    p_entry_id, v_amount, COALESCE(p_payment_date, CURRENT_DATE),\r\n    COALESCE(p_payment_method, 'cash'),\r\n    v_label,\r\n    nullif(btrim(coalesce(p_reference_no, '')), ''),\r\n    nullif(btrim(coalesce(p_note, '')), ''),\r\n    nullif(btrim(coalesce(p_idempotency_key, '')), ''),\r\n    v_user,\r\n    p_account_id\r\n  );\r\n\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id;\r\n\r\n  PERFORM public.expense_log_action(\r\n    p_entry_id, 'payment', v_entry.status, v_entry.status,\r\n    'Payment of ' || v_amount::text || ' ' || v_entry.currency_symbol || ' recorded',\r\n    v_user\r\n  );\r\n\r\n  RETURN v_entry;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.reverse_expense(p_entry_id uuid, p_reason text DEFAULT NULL::text)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user     uuid := public.expense_actor();\r\n  v_entry    public.expense_entries;\r\n  v_reversal public.expense_entries;\r\nBEGIN\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.reverse');\r\n\r\n  IF v_entry.status = 'REVERSED' THEN\r\n    RETURN v_entry;   -- idempotent: reversing twice is a no-op, not an error\r\n  END IF;\r\n  IF v_entry.status NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID') THEN\r\n    RAISE EXCEPTION 'Only a posted expense can be reversed (current: %)', v_entry.status\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n  -- Money already sitting in the drawer has to be dealt with through the\r\n  -- payment record, not by erasing the document that produced it.\r\n  IF v_entry.paid_amount > 0 THEN\r\n    RAISE EXCEPTION 'Reverse the recorded payments first (paid: %)', v_entry.paid_amount\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  INSERT INTO public.expense_entries (\r\n    reference, entry_type, status, source_kind,\r\n    payee_type, payee_name, supplier_id, employee_id,\r\n    warehouse_id, cost_center_id, project_id,\r\n    expense_date, posting_date, description, note,\r\n    tax_mode, currency, currency_symbol,\r\n    reversal_of, created_by, posted_by, posted_at\r\n  )\r\n  VALUES (\r\n    v_entry.reference || '-R',\r\n    v_entry.entry_type,\r\n    -- The reversal is itself posted: it is a recognised, immutable correction.\r\n    'POSTED',\r\n    v_entry.source_kind,\r\n    v_entry.payee_type, v_entry.payee_name, v_entry.supplier_id, v_entry.employee_id,\r\n    v_entry.warehouse_id, v_entry.cost_center_id, v_entry.project_id,\r\n    CURRENT_DATE, CURRENT_DATE,\r\n    'Reversal of ' || v_entry.reference,\r\n    nullif(btrim(coalesce(p_reason, '')), ''),\r\n    v_entry.tax_mode, v_entry.currency, v_entry.currency_symbol,\r\n    v_entry.id, v_user, v_user, now()\r\n  )\r\n  RETURNING * INTO v_reversal;\r\n\r\n  -- Mirror the lines so the reversal is a real, reportable document rather than\r\n  -- an amount with no category — otherwise the reversal would vanish from the\r\n  -- by-category report and leave that report showing an expense that no longer\r\n  -- exists.\r\n  INSERT INTO public.expense_lines (\r\n    entry_id, line_no, description, category_id, quantity, unit_price,\r\n    net_amount, tax_rate, tax_amount, gross_amount,\r\n    cost_center_id, project_id, note\r\n  )\r\n  SELECT\r\n    v_reversal.id, line_no, description, category_id, quantity, unit_price,\r\n    net_amount, tax_rate, tax_amount, gross_amount,\r\n    cost_center_id, project_id, note\r\n  FROM public.expense_lines\r\n  WHERE entry_id = p_entry_id\r\n  ORDER BY line_no;\r\n\r\n  UPDATE public.expense_entries\r\n     SET total_amount = v_entry.total_amount,\r\n         line_count   = v_entry.line_count\r\n   WHERE id = v_reversal.id\r\n  RETURNING * INTO v_reversal;\r\n\r\n  UPDATE public.expense_entries\r\n     SET status         = 'REVERSED',\r\n         reversed_by_id = v_reversal.id,\r\n         version        = version + 1\r\n   WHERE id = p_entry_id\r\n  RETURNING * INTO v_entry;\r\n\r\n  PERFORM public.expense_log_action(\r\n    p_entry_id, 'reversed', 'POSTED', 'REVERSED',\r\n    COALESCE(NULLIF(btrim(COALESCE(p_reason, '')), ''), 'Reversed'), v_user);\r\n\r\n  RETURN v_entry;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.reverse_expense_payment(p_payment_id uuid, p_reason text DEFAULT NULL::text)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user    uuid := public.expense_actor();\r\n  v_payment public.expense_payments;\r\n  v_entry   public.expense_entries;\r\n  v_reversal_id uuid;\r\nBEGIN\r\n  SELECT * INTO v_payment FROM public.expense_payments WHERE id = p_payment_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Payment not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.payment.reverse');\r\n\r\n  IF v_payment.reversed_by IS NOT NULL THEN\r\n    SELECT * INTO v_entry FROM public.expense_entries WHERE id = v_payment.entry_id;\r\n    RETURN v_entry;   -- idempotent\r\n  END IF;\r\n  IF v_payment.reversal_of IS NOT NULL THEN\r\n    RAISE EXCEPTION 'A reversal row cannot itself be reversed' USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = v_payment.entry_id FOR UPDATE;\r\n\r\n  INSERT INTO public.expense_payments (\r\n    entry_id, amount, payment_date, payment_method,\r\n    account_label, reference_no, note, reversal_of, created_by\r\n  )\r\n  VALUES (\r\n    v_payment.entry_id, v_payment.amount, CURRENT_DATE, v_payment.payment_method,\r\n    v_payment.account_label, v_payment.reference_no,\r\n    COALESCE(NULLIF(btrim(COALESCE(p_reason, '')), ''), 'Reversal of payment'),\r\n    v_payment.id, v_user\r\n  )\r\n  RETURNING id INTO v_reversal_id;\r\n\r\n  UPDATE public.expense_payments\r\n     SET reversed_by = v_reversal_id\r\n   WHERE id = p_payment_id;\r\n\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = v_payment.entry_id;\r\n\r\n  PERFORM public.expense_log_action(\r\n    v_payment.entry_id, 'payment', v_entry.status, v_entry.status,\r\n    'Payment reversed', v_user);\r\n\r\n  RETURN v_entry;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.save_expense_category(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_name_ar text DEFAULT NULL::text, p_sort_order integer DEFAULT NULL::integer, p_notes text DEFAULT NULL::text, p_is_active boolean DEFAULT NULL::boolean)\r\n RETURNS expense_categories\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user     uuid := public.expense_actor();\r\n  v_category public.expense_categories;\r\n  v_name     text := nullif(btrim(coalesce(p_name, '')), '');\r\nBEGIN\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.category.manage');\r\n\r\n  IF p_id IS NULL THEN\r\n    IF v_name IS NULL THEN\r\n      RAISE EXCEPTION 'A category needs a name' USING ERRCODE = '22023';\r\n    END IF;\r\n\r\n    INSERT INTO public.expense_categories (name, name_ar, sort_order, notes, created_by, is_active)\r\n    VALUES (\r\n      v_name,\r\n      nullif(btrim(coalesce(p_name_ar, '')), ''),\r\n      COALESCE(p_sort_order, 100),\r\n      nullif(btrim(coalesce(p_notes, '')), ''),\r\n      v_user,\r\n      COALESCE(p_is_active, true)\r\n    )\r\n    RETURNING * INTO v_category;\r\n\r\n    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n    VALUES (v_user, 'expense.category.created', 'expense_category', v_category.id,\r\n            jsonb_build_object('name', v_category.name));\r\n  ELSE\r\n    -- The UNIQUE(name) constraint from the original migration would raise a raw\r\n    -- 23505 the operator cannot read; checked explicitly so the message is\r\n    -- usable and names the clash.\r\n    IF v_name IS NOT NULL AND EXISTS (\r\n      SELECT 1 FROM public.expense_categories c\r\n      WHERE upper(btrim(c.name)) = upper(v_name) AND c.id <> p_id\r\n    ) THEN\r\n      RAISE EXCEPTION 'A category named \\"%\\" already exists', v_name USING ERRCODE = '23505';\r\n    END IF;\r\n\r\n    UPDATE public.expense_categories\r\n       SET name       = COALESCE(v_name, name),\r\n           name_ar    = CASE WHEN p_name_ar IS NULL THEN name_ar\r\n                             ELSE nullif(btrim(p_name_ar), '') END,\r\n           sort_order = COALESCE(p_sort_order, sort_order),\r\n           notes      = CASE WHEN p_notes IS NULL THEN notes\r\n                             ELSE nullif(btrim(p_notes), '') END,\r\n           is_active  = COALESCE(p_is_active, is_active)\r\n     WHERE id = p_id\r\n    RETURNING * INTO v_category;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Category not found' USING ERRCODE = 'P0002';\r\n    END IF;\r\n\r\n    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n    VALUES (v_user, 'expense.category.updated', 'expense_category', v_category.id,\r\n            jsonb_build_object('name', v_category.name, 'is_active', v_category.is_active));\r\n  END IF;\r\n\r\n  RETURN v_category;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.save_expense_dimension(p_kind text, p_id uuid DEFAULT NULL::uuid, p_code text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_name_ar text DEFAULT NULL::text, p_is_active boolean DEFAULT NULL::boolean)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := public.expense_actor();\r\n  v_name text := nullif(btrim(coalesce(p_name, '')), '');\r\n  v_code text := nullif(btrim(coalesce(p_code, '')), '');\r\n  v_row  jsonb;\r\nBEGIN\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.dimension.manage');\r\n\r\n  IF p_kind NOT IN ('cost_center', 'project') THEN\r\n    RAISE EXCEPTION 'Unknown dimension kind: %', p_kind USING ERRCODE = '22023';\r\n  END IF;\r\n  IF p_id IS NULL AND v_name IS NULL THEN\r\n    RAISE EXCEPTION 'A name is required' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  IF p_kind = 'cost_center' THEN\r\n    IF p_id IS NULL THEN\r\n      INSERT INTO public.expense_cost_centers (code, name, name_ar, is_active, created_by)\r\n      VALUES (v_code, v_name, nullif(btrim(coalesce(p_name_ar, '')), ''),\r\n              COALESCE(p_is_active, true), v_user)\r\n      RETURNING to_jsonb(expense_cost_centers.*) INTO v_row;\r\n    ELSE\r\n      UPDATE public.expense_cost_centers\r\n         SET code      = CASE WHEN p_code IS NULL THEN code ELSE v_code END,\r\n             name      = COALESCE(v_name, name),\r\n             name_ar   = CASE WHEN p_name_ar IS NULL THEN name_ar\r\n                              ELSE nullif(btrim(p_name_ar), '') END,\r\n             is_active = COALESCE(p_is_active, is_active)\r\n       WHERE id = p_id\r\n      RETURNING to_jsonb(expense_cost_centers.*) INTO v_row;\r\n\r\n      IF v_row IS NULL THEN\r\n        RAISE EXCEPTION 'Cost centre not found' USING ERRCODE = 'P0002';\r\n      END IF;\r\n    END IF;\r\n  ELSE\r\n    IF p_id IS NULL THEN\r\n      INSERT INTO public.expense_projects (code, name, name_ar, is_active, created_by)\r\n      VALUES (v_code, v_name, nullif(btrim(coalesce(p_name_ar, '')), ''),\r\n              COALESCE(p_is_active, true), v_user)\r\n      RETURNING to_jsonb(expense_projects.*) INTO v_row;\r\n    ELSE\r\n      UPDATE public.expense_projects\r\n         SET code      = CASE WHEN p_code IS NULL THEN code ELSE v_code END,\r\n             name      = COALESCE(v_name, name),\r\n             name_ar   = CASE WHEN p_name_ar IS NULL THEN name_ar\r\n                              ELSE nullif(btrim(p_name_ar), '') END,\r\n             is_active = COALESCE(p_is_active, is_active)\r\n       WHERE id = p_id\r\n      RETURNING to_jsonb(expense_projects.*) INTO v_row;\r\n\r\n      IF v_row IS NULL THEN\r\n        RAISE EXCEPTION 'Project not found' USING ERRCODE = 'P0002';\r\n      END IF;\r\n    END IF;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'expense.' || p_kind || '.' || CASE WHEN p_id IS NULL THEN 'created' ELSE 'updated' END,\r\n          'expense_' || p_kind, (v_row ->> 'id')::uuid, v_row);\r\n\r\n  RETURN v_row;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.submit_expense(p_entry_id uuid, p_expected_version integer DEFAULT NULL::integer)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user  uuid := public.expense_actor();\r\n  v_entry public.expense_entries;\r\n  v_from  public.expense_status;\r\nBEGIN\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  v_from := v_entry.status;\r\n  IF v_from NOT IN ('DRAFT', 'REJECTED') THEN\r\n    RAISE EXCEPTION 'Only a draft or a returned expense can be submitted (current: %)', v_from\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  IF NOT (v_entry.created_by = v_user OR public.expense_role_rank(v_user) >= 30) THEN\r\n    RAISE EXCEPTION 'Forbidden: you can only submit your own drafts' USING ERRCODE = '42501';\r\n  END IF;\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.submit');\r\n\r\n  IF p_expected_version IS NOT NULL AND p_expected_version <> v_entry.version THEN\r\n    RAISE EXCEPTION 'This expense was changed by someone else. Reload it and try again.'\r\n      USING ERRCODE = '40001';\r\n  END IF;\r\n\r\n  -- Completeness, in the order an operator would fix it.\r\n  IF v_entry.total_amount <= 0 OR v_entry.line_count = 0 THEN\r\n    RAISE EXCEPTION 'Add at least one line with an amount before submitting'\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n  IF v_entry.payee_type = 'SUPPLIER' AND v_entry.supplier_id IS NULL THEN\r\n    RAISE EXCEPTION 'Choose the supplier before submitting' USING ERRCODE = '22023';\r\n  END IF;\r\n  IF v_entry.payee_type = 'EMPLOYEE' AND v_entry.employee_id IS NULL THEN\r\n    RAISE EXCEPTION 'Choose the staff member before submitting' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  UPDATE public.expense_entries\r\n     SET status             = 'SUBMITTED',\r\n         submitted_by       = v_user,\r\n         submitted_at       = now(),\r\n         rejection_reason   = NULL,\r\n         version            = version + 1\r\n   WHERE id = p_entry_id\r\n  RETURNING * INTO v_entry;\r\n\r\n  PERFORM public.expense_log_action(p_entry_id, 'submitted', v_from, 'SUBMITTED', NULL, v_user);\r\n\r\n  RETURN v_entry;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.tg_expense_entries_guard()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  -- Only guard documents that have actually been recognized. A draft is meant\r\n  -- to be edited; a posted document is evidence.\r\n  IF OLD.status NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED', 'REVERSED')\r\n     AND NEW.status NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED', 'REVERSED') THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  -- The exception is the reversal flow, which legitimately links a posted row\r\n  -- to its compensating document; everything else about it stays frozen.\r\n  IF NEW.total_amount  IS DISTINCT FROM OLD.total_amount\r\n     OR NEW.expense_date IS DISTINCT FROM OLD.expense_date\r\n     OR NEW.entry_type   IS DISTINCT FROM OLD.entry_type\r\n     OR NEW.supplier_id  IS DISTINCT FROM OLD.supplier_id\r\n     OR NEW.employee_id  IS DISTINCT FROM OLD.employee_id\r\n     OR NEW.payee_type   IS DISTINCT FROM OLD.payee_type\r\n     OR NEW.currency     IS DISTINCT FROM OLD.currency THEN\r\n    RAISE EXCEPTION\r\n      'Expense % is posted: its financial fields are immutable. Reverse it instead.',\r\n      OLD.reference\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.tg_expense_lines_sync_total()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_entry_id uuid := COALESCE(NEW.entry_id, OLD.entry_id);\r\n  v_status   public.expense_status;\r\n  v_total    numeric(18,2);\r\n  v_lines    integer;\r\nBEGIN\r\n  SELECT status INTO v_status FROM public.expense_entries WHERE id = v_entry_id;\r\n\r\n  -- A posted document's lines are frozen evidence; leave its header alone.\r\n  IF v_status IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED', 'REVERSED') THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  SELECT COALESCE(sum(gross_amount), 0)::numeric(18,2), count(*)\r\n    INTO v_total, v_lines\r\n  FROM public.expense_lines\r\n  WHERE entry_id = v_entry_id;\r\n\r\n  UPDATE public.expense_entries\r\n     SET total_amount = v_total,\r\n         line_count   = v_lines\r\n   WHERE id = v_entry_id\r\n     AND status NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID', 'CLOSED', 'REVERSED');\r\n\r\n  RETURN NULL;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.tg_expense_payments_sync_entry()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_entry_id uuid := COALESCE(NEW.entry_id, OLD.entry_id);\r\n  v_paid     numeric(18,2);\r\n  v_entry    public.expense_entries;\r\nBEGIN\r\n  SELECT COALESCE(sum(amount), 0)::numeric(18,2)\r\n    INTO v_paid\r\n  FROM public.expense_payments\r\n  -- A reversed payment keeps its row but stops counting toward settlement; the\r\n  -- reversal row itself is subtracted because it carries a positive amount and\r\n  -- a `reversal_of` link, which is expressed on the matching row's `reversed_by`.\r\n  WHERE entry_id = v_entry_id\r\n    AND reversed_by IS NULL\r\n    AND reversal_of IS NULL;\r\n\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = v_entry_id;\r\n  IF NOT FOUND THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  UPDATE public.expense_entries\r\n     SET paid_amount = v_paid,\r\n         status = public.expense_settlement_status(\r\n           CASE WHEN v_entry.status IN ('CLOSED', 'REVERSED') THEN v_entry.status\r\n                ELSE 'POSTED'::public.expense_status END,\r\n           v_paid,\r\n           v_entry.total_amount\r\n         )\r\n   WHERE id = v_entry_id;\r\n\r\n  RETURN NULL;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.update_expense(p_entry_id uuid, p_expected_version integer, p_lines jsonb, p_expense_date date DEFAULT NULL::date, p_due_date date DEFAULT NULL::date, p_entry_type expense_entry_type DEFAULT NULL::expense_entry_type, p_payee_type expense_payee_type DEFAULT NULL::expense_payee_type, p_payee_name text DEFAULT NULL::text, p_supplier_id uuid DEFAULT NULL::uuid, p_employee_id uuid DEFAULT NULL::uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_tax_mode expense_tax_mode DEFAULT NULL::expense_tax_mode)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user      uuid := public.expense_actor();\r\n  v_entry     public.expense_entries;\r\n  v_total     numeric;\r\n  v_count     integer;\r\n  v_tax_mode  public.expense_tax_mode;\r\n  v_payee     public.expense_payee_type;\r\n  v_from      public.expense_status;\r\nBEGIN\r\n  -- `FOR UPDATE` is what makes the version check meaningful: without the row\r\n  -- lock, two concurrent updates could both read version 3, both pass the\r\n  -- check, and the second would silently overwrite the first.\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  v_from := v_entry.status;\r\n\r\n  IF v_from NOT IN ('DRAFT', 'REJECTED') THEN\r\n    RAISE EXCEPTION 'Only a draft or a returned expense can be edited (current: %)', v_from\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  -- Ownership or an accounting-and-above role. A cashier must not be able to\r\n  -- rewrite a colleague's draft.\r\n  IF NOT (v_entry.created_by = v_user OR public.expense_role_rank(v_user) >= 30) THEN\r\n    RAISE EXCEPTION 'Forbidden: you can only edit your own drafts' USING ERRCODE = '42501';\r\n  END IF;\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.edit');\r\n\r\n  IF p_expected_version IS NOT NULL AND p_expected_version <> v_entry.version THEN\r\n    RAISE EXCEPTION 'This expense was changed by someone else. Reload it and try again.'\r\n      USING ERRCODE = '40001';\r\n  END IF;\r\n\r\n  v_tax_mode := COALESCE(p_tax_mode, v_entry.tax_mode);\r\n  v_payee    := COALESCE(p_payee_type, v_entry.payee_type);\r\n\r\n  IF v_payee = 'SUPPLIER' AND COALESCE(p_supplier_id, v_entry.supplier_id) IS NULL THEN\r\n    RAISE EXCEPTION 'A supplier payee requires a supplier' USING ERRCODE = '22023';\r\n  END IF;\r\n  IF v_payee = 'EMPLOYEE' AND COALESCE(p_employee_id, v_entry.employee_id) IS NULL THEN\r\n    RAISE EXCEPTION 'An employee payee requires a staff member' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  UPDATE public.expense_entries\r\n     SET expense_date   = COALESCE(p_expense_date, expense_date),\r\n         due_date       = p_due_date,\r\n         entry_type     = COALESCE(p_entry_type, entry_type),\r\n         payee_type     = v_payee,\r\n         payee_name     = nullif(btrim(coalesce(p_payee_name, '')), ''),\r\n         supplier_id    = CASE WHEN v_payee = 'SUPPLIER' THEN p_supplier_id END,\r\n         employee_id    = CASE WHEN v_payee = 'EMPLOYEE' THEN p_employee_id END,\r\n         warehouse_id   = p_warehouse_id,\r\n         cost_center_id = p_cost_center_id,\r\n         project_id     = p_project_id,\r\n         description    = nullif(btrim(coalesce(p_description, '')), ''),\r\n         note           = nullif(btrim(coalesce(p_note, '')), ''),\r\n         tax_mode       = v_tax_mode,\r\n         -- A rejected document that is edited becomes a draft again: it must\r\n         -- re-earn its approval rather than inheriting the old decision.\r\n         status         = 'DRAFT'::public.expense_status,\r\n         rejection_reason = NULL,\r\n         version        = version + 1\r\n   WHERE id = p_entry_id\r\n  RETURNING * INTO v_entry;\r\n\r\n  SELECT o_total, o_count INTO v_total, v_count\r\n  FROM public.expense_write_lines(p_entry_id, p_lines, v_tax_mode);\r\n\r\n  UPDATE public.expense_entries\r\n     SET total_amount = v_total,\r\n         line_count   = v_count\r\n   WHERE id = p_entry_id\r\n  RETURNING * INTO v_entry;\r\n\r\n  PERFORM public.expense_log_action(\r\n    p_entry_id, 'updated', v_from, 'DRAFT', 'Draft edited', v_user);\r\n\r\n  RETURN v_entry;\r\nEND $function$"}	expenses
10	{"-- ============================================================================\r\n-- 10_milling_custody.sql\r\n--\r\n-- طبقة الأمانات المبسطة: جدول واحد custody_ledger — سطر لكل حركة، والرصيد مشتق.\r\n--\r\n-- التصميم المعتمد: docs/milling/00_خطة_التبسيط_المعتمدة.md\r\n--   - لا أوامر طحن، لا فاقد مدخل، لا صوامع، لا أوزان عبوات، لا عقود.\r\n--   - حبوب العميل أمانة: صفر أثر على مخزون المطحنة (بلا حركات مخزون إطلاقاً).\r\n--   - الرصيد = sum(bags_in - bags_out) / sum(kg_in - kg_out) — لا رصيد مخزَّن.\r\n--   - الكتابة عبر RPC فقط (R-23). راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── TYPES ─────────────────────────────────────────────────────────────────\r\nDO $$ BEGIN\r\n  CREATE TYPE public.custody_entry_type AS ENUM ('INTAKE', 'MILLING', 'DELIVERY', 'ADJUSTMENT');\r\nEXCEPTION\r\n  WHEN duplicate_object THEN null;\r\nEND $$","-- ── SEQUENCES ─────────────────────────────────────────────────────────────\r\n-- أرقام المستندات. مملوكة هنا (أُزيلت من 11 و14 حتى لا تتكرر — R-13).\r\nCREATE SEQUENCE IF NOT EXISTS public.milling_intake_seq   START 1","CREATE SEQUENCE IF NOT EXISTS public.milling_service_seq  START 1","CREATE SEQUENCE IF NOT EXISTS public.milling_delivery_seq START 1","CREATE SEQUENCE IF NOT EXISTS public.milling_document_seq START 1","-- ── TABLES ────────────────────────────────────────────────────────────────\r\n-- رأس مستند خدمة خفيف: يجمع أمانة العميل والفاتورة الرسمية تحت عملية واحدة.\r\n-- ليس أمر إنتاج، ولا يحتفظ برصيد أو فاقد أو تكلفة تصنيع.\r\nCREATE TABLE public.milling_service_documents (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  document_number varchar(50) NOT NULL,\r\n  customer_id uuid NOT NULL,\r\n  warehouse_id uuid NOT NULL,\r\n  sales_invoice_id uuid NOT NULL,\r\n  status varchar(20) DEFAULT 'RECEIVED' NOT NULL,\r\n  received_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,\r\n  processed_at timestamp with time zone,\r\n  delivered_at timestamp with time zone,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,\r\n  CONSTRAINT milling_service_documents_pkey PRIMARY KEY (id),\r\n  CONSTRAINT milling_service_documents_number_key UNIQUE (document_number),\r\n  CONSTRAINT milling_service_documents_invoice_key UNIQUE (sales_invoice_id),\r\n  CONSTRAINT milling_service_documents_status_check CHECK (\r\n    status IN ('RECEIVED', 'PROCESSED', 'DELIVERED')\r\n  )\r\n)","CREATE TABLE public.custody_ledger (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  customer_id uuid NOT NULL,\r\n  warehouse_id uuid NOT NULL,\r\n  entry_type public.custody_entry_type NOT NULL,\r\n  item_id uuid NOT NULL,\r\n  doc_number varchar(50),\r\n  bags_in numeric(12,3) DEFAULT 0 NOT NULL,\r\n  bags_out numeric(12,3) DEFAULT 0 NOT NULL,\r\n  kg_in numeric(12,3) DEFAULT 0 NOT NULL,\r\n  kg_out numeric(12,3) DEFAULT 0 NOT NULL,\r\n  unit_price numeric(14,2) DEFAULT 0 NOT NULL,\r\n  amount numeric(14,2) DEFAULT 0 NOT NULL,\r\n  -- رابط اختياري للرأس الموحد؛ تبقى الحركات التاريخية القديمة قابلة للقراءة.\r\n  milling_document_id uuid,\r\n  service_invoice_id uuid,\r\n  notes text,\r\n  created_by uuid,\r\n  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,\r\n  CONSTRAINT custody_ledger_pkey PRIMARY KEY (id),\r\n  CONSTRAINT custody_ledger_quantities_check CHECK (\r\n    bags_in >= 0 AND bags_out >= 0 AND kg_in >= 0 AND kg_out >= 0\r\n  ),\r\n  CONSTRAINT custody_ledger_movement_check CHECK (\r\n    (bags_in + bags_out + kg_in + kg_out) > 0\r\n  ),\r\n  CONSTRAINT custody_ledger_one_side_check CHECK (\r\n    (bags_in = 0 OR bags_out = 0) AND (kg_in = 0 OR kg_out = 0)\r\n  ),\r\n  CONSTRAINT custody_ledger_invoice_only_money_check CHECK (\r\n    service_invoice_id IS NULL OR (unit_price = 0 AND amount = 0)\r\n  )\r\n)","-- ── INDEXES ───────────────────────────────────────────────────────────────\r\nCREATE INDEX idx_custody_customer_item ON public.custody_ledger USING btree (customer_id, item_id)","CREATE INDEX idx_custody_warehouse ON public.custody_ledger USING btree (warehouse_id, created_at DESC)","CREATE INDEX idx_custody_invoice ON public.custody_ledger USING btree (service_invoice_id) WHERE (service_invoice_id IS NOT NULL)","CREATE INDEX idx_custody_entry_type ON public.custody_ledger USING btree (entry_type, created_at DESC)","CREATE INDEX idx_custody_milling_document ON public.custody_ledger USING btree (milling_document_id, created_at DESC) WHERE (milling_document_id IS NOT NULL)","CREATE INDEX idx_milling_service_documents_customer ON public.milling_service_documents USING btree (customer_id, received_at DESC)","-- ── VIEW: الأرصدة — مشتقة دائماً، لا رصيد مخزَّن ─────────────────────────\r\nCREATE OR REPLACE VIEW public.custody_balances AS\r\n SELECT l.customer_id,\r\n    l.warehouse_id,\r\n    l.item_id,\r\n    p.sku,\r\n    p.name_ar,\r\n    p.item_class,\r\n    sum((l.bags_in - l.bags_out)) AS bags_balance,\r\n    sum((l.kg_in - l.kg_out)) AS kg_balance\r\n   FROM (public.custody_ledger l\r\n     JOIN public.products p ON ((p.id = l.item_id)))\r\n  GROUP BY l.customer_id, l.warehouse_id, l.item_id, p.sku, p.name_ar, p.item_class","-- ── FUNCTIONS ─────────────────────────────────────────────────────────────\r\n-- مساعد داخلي: رصيد العميل (أكياس، كجم) لصنف ومخزن — يُقرأ دائماً من السجل.\r\nCREATE OR REPLACE FUNCTION public.custody_balance(_customer_id uuid, _warehouse_id uuid, _item_id uuid)\r\n RETURNS TABLE(bags numeric, kg numeric)\r\n LANGUAGE sql\r\n STABLE\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT coalesce(sum(bags_in - bags_out), 0) AS bags,\r\n         coalesce(sum(kg_in - kg_out), 0) AS kg\r\n  FROM public.custody_ledger\r\n  WHERE customer_id = _customer_id\r\n    AND warehouse_id = _warehouse_id\r\n    AND item_id = _item_id\r\n$function$","-- ── 0. كاونتر المطحنة: استلام + فاتورة أجور رسمية في معاملة واحدة ───────\r\n-- حبوب العميل تبقى أمانة بلا أثر مخزني، أما الأجرة فهي فاتورة مبيعات فعلية.\r\nCREATE OR REPLACE FUNCTION public.create_milling_service_document(\r\n  _customer_id uuid,\r\n  _warehouse_id uuid,\r\n  _grain_item_id uuid,\r\n  _bags numeric,\r\n  _kg numeric,\r\n  _service_item_id uuid,\r\n  _service_unit_price numeric,\r\n  _discount numeric,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _notes text\r\n)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_document_id uuid;\r\n  v_document_number text;\r\n  v_invoice_id uuid;\r\n  v_invoice_number text;\r\n  v_subtotal numeric;\r\n  v_total numeric;\r\n  v_paid numeric;\r\n  v_outstanding numeric;\r\n  v_customer_balance numeric;\r\n  v_credit_limit numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  -- إصدار الفاتورة عمل نقدي؛ لا يُفتح لمستخدم مستودع فقط.\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to create milling service documents';\r\n  END IF;\r\n  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _grain_item_id IS NULL\r\n     OR _service_item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Customer, warehouse, grain and service are required';\r\n  END IF;\r\n  IF coalesce(_bags, 0) <= 0 AND coalesce(_kg, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'Record at least one bag or a positive weight';\r\n  END IF;\r\n  IF coalesce(_bags, 0) < 0 OR coalesce(_kg, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Quantities cannot be negative';\r\n  END IF;\r\n  IF coalesce(_service_unit_price, 0) < 0 OR coalesce(_discount, 0) < 0\r\n     OR coalesce(_paid, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Service price, discount and paid amount cannot be negative';\r\n  END IF;\r\n  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN\r\n    RAISE EXCEPTION 'Unsupported payment method';\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active\r\n  ) THEN\r\n    RAISE EXCEPTION 'Intake item must be an active RAW_MATERIAL grain';\r\n  END IF;\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _service_item_id AND item_class = 'SERVICE' AND is_active AND is_sellable\r\n  ) THEN\r\n    RAISE EXCEPTION 'Milling fee item must be an active sellable SERVICE';\r\n  END IF;\r\n\r\n  SELECT balance, credit_limit\r\n    INTO v_customer_balance, v_credit_limit\r\n  FROM public.customers\r\n  WHERE id = _customer_id AND is_active = true\r\n  FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Selected customer is unavailable';\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = _warehouse_id AND is_active) THEN\r\n    RAISE EXCEPTION 'Selected warehouse is unavailable';\r\n  END IF;\r\n\r\n  v_subtotal := round(coalesce(_service_unit_price, 0), 2);\r\n  v_total := round(v_subtotal - coalesce(_discount, 0), 2);\r\n  IF v_total < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot exceed the service fee';\r\n  END IF;\r\n  v_paid := least(round(coalesce(_paid, 0), 2), v_total);\r\n  v_outstanding := round(v_total - v_paid, 2);\r\n  IF _payment_method = 'credit' AND v_paid <> 0 THEN\r\n    RAISE EXCEPTION 'Credit payment method requires zero paid amount';\r\n  END IF;\r\n  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN\r\n    RAISE EXCEPTION\r\n      'Credit limit exceeded: current balance %, requested debt %, limit %',\r\n      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);\r\n  END IF;\r\n\r\n  v_invoice_number := public.next_invoice_number();\r\n  INSERT INTO public.sales_invoices (\r\n    invoice_number, customer_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  ) VALUES (\r\n    v_invoice_number, _customer_id, _warehouse_id, 'confirmed',\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, round(coalesce(_discount, 0), 2), 0, v_total, v_paid,\r\n    _payment_method::public.payment_method, nullif(btrim(_notes), ''), v_user\r\n  ) RETURNING id INTO v_invoice_id;\r\n\r\n  INSERT INTO public.sales_invoice_items (\r\n    invoice_id, product_id, description, quantity, unit_price, discount, tax, total,\r\n    line_type, stock_effect\r\n  ) VALUES (\r\n    v_invoice_id, _service_item_id, 'أجور طحن وتجهيز', 1, v_subtotal,\r\n    0, 0, v_subtotal, 'SERVICE', 'NONE'\r\n  );\r\n\r\n  IF v_outstanding > 0 THEN\r\n    UPDATE public.customers\r\n    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()\r\n    WHERE id = _customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, debit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    ) VALUES (\r\n      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',\r\n      now(), v_user, 'sale:' || v_invoice_id, 'قيد أجور طحن آجل'\r\n    ) ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  v_document_number := 'MT-' || to_char(now(), 'YYYYMM') || '-' ||\r\n    lpad(nextval('public.milling_document_seq')::text, 4, '0');\r\n  INSERT INTO public.milling_service_documents (\r\n    document_number, customer_id, warehouse_id, sales_invoice_id, created_by\r\n  ) VALUES (\r\n    v_document_number, _customer_id, _warehouse_id, v_invoice_id, v_user\r\n  ) RETURNING id INTO v_document_id;\r\n\r\n  INSERT INTO public.custody_ledger (\r\n    customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n    bags_in, kg_in, milling_document_id, notes, created_by\r\n  ) VALUES (\r\n    _customer_id, _warehouse_id, 'INTAKE', _grain_item_id, v_document_number,\r\n    coalesce(_bags, 0), coalesce(_kg, 0), v_document_id, _notes, v_user\r\n  );\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'milling.service_document.created', 'milling_service_documents', v_document_id,\r\n    jsonb_build_object(\r\n      'document_number', v_document_number,\r\n      'invoice_id', v_invoice_id,\r\n      'invoice_number', v_invoice_number,\r\n      'customer_id', _customer_id,\r\n      'grain_item_id', _grain_item_id,\r\n      'bags', coalesce(_bags, 0),\r\n      'kg', coalesce(_kg, 0),\r\n      'service_total', v_total,\r\n      'paid', v_paid,\r\n      'outstanding', v_outstanding,\r\n      'stock_impact', 'NONE — customer custody'\r\n    ));\r\n\r\n  RETURN jsonb_build_object(\r\n    'document_id', v_document_id,\r\n    'document_number', v_document_number,\r\n    'invoice_id', v_invoice_id,\r\n    'invoice_number', v_invoice_number\r\n  );\r\nEND $function$","-- ── 1. الاستلام ───────────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.custody_intake(_customer_id uuid, _warehouse_id uuid, _item_id uuid, _bags numeric, _kg numeric, _notes text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_id uuid;\r\n  v_doc text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to record custody intakes';\r\n  END IF;\r\n  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Customer, warehouse and item are required';\r\n  END IF;\r\n  IF coalesce(_bags, 0) <= 0 AND coalesce(_kg, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'Record at least one bag or a positive weight';\r\n  END IF;\r\n  IF coalesce(_bags, 0) < 0 OR coalesce(_kg, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Quantities cannot be negative';\r\n  END IF;\r\n\r\n  -- صنف الاستلام حبوب خام فقط — من القاعدة لا من الواجهة.\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _item_id AND item_class = 'RAW_MATERIAL' AND is_active\r\n  ) THEN\r\n    RAISE EXCEPTION 'Intake item must be an active RAW_MATERIAL grain';\r\n  END IF;\r\n\r\n  v_doc := 'CI-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_intake_seq')::text, 4, '0');\r\n\r\n  INSERT INTO public.custody_ledger\r\n    (customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n     bags_in, kg_in, notes, created_by)\r\n  VALUES\r\n    (_customer_id, _warehouse_id, 'INTAKE', _item_id, v_doc,\r\n     coalesce(_bags, 0), coalesce(_kg, 0), _notes, v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'custody.intake', 'custody_ledger', v_id,\r\n    jsonb_build_object(\r\n      'doc_number', v_doc,\r\n      'customer_id', _customer_id,\r\n      'item_id', _item_id,\r\n      'bags', coalesce(_bags, 0),\r\n      'kg', coalesce(_kg, 0),\r\n      'stock_impact', 'NONE — customer custody'\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","-- ── 2. الطحن ──────────────────────────────────────────────────────────────\r\n-- سطر صادر حبوب + سطر وارد لكل ناتج، في معاملة واحدة.\r\n-- الفاقد لا يُدخل: هو الفرق الذي يظهر تلقائياً في الكشف.\r\nCREATE OR REPLACE FUNCTION public.custody_milling(_customer_id uuid, _warehouse_id uuid, _grain_item_id uuid, _bags_out numeric, _kg_out numeric, _outputs jsonb, _notes text)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_doc text;\r\n  v_balance_bags numeric;\r\n  v_balance_kg numeric;\r\n  v_total_out_bags numeric := 0;\r\n  v_total_out_kg numeric := 0;\r\n  r record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to record custody milling';\r\n  END IF;\r\n  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _grain_item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Customer, warehouse and grain item are required';\r\n  END IF;\r\n  IF coalesce(_bags_out, 0) <= 0 AND coalesce(_kg_out, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'Milling must consume at least one bag or a positive weight of grain';\r\n  END IF;\r\n  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN\r\n    RAISE EXCEPTION 'At least one output line is required';\r\n  END IF;\r\n\r\n  -- صنف الحبوب خام، وأصناف النواتج منتجات/نواتج جانبية — من القاعدة.\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active\r\n  ) THEN\r\n    RAISE EXCEPTION 'Milling input must be an active RAW_MATERIAL grain';\r\n  END IF;\r\n\r\n  SELECT * FROM public.custody_balance(_customer_id, _warehouse_id, _grain_item_id)\r\n    INTO v_balance_bags, v_balance_kg;\r\n\r\n  IF coalesce(_bags_out, 0) > v_balance_bags THEN\r\n    RAISE EXCEPTION 'Grain bags balance (%) is less than the requested milling amount (%)',\r\n      v_balance_bags, coalesce(_bags_out, 0);\r\n  END IF;\r\n  IF coalesce(_kg_out, 0) > v_balance_kg THEN\r\n    RAISE EXCEPTION 'Grain kg balance (%) is less than the requested milling amount (%)',\r\n      v_balance_kg, coalesce(_kg_out, 0);\r\n  END IF;\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs)\r\n             AS o(item_id uuid, bags numeric, kg numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL THEN\r\n      RAISE EXCEPTION 'Every output line needs an item';\r\n    END IF;\r\n    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every output line needs bags or a positive weight';\r\n    END IF;\r\n    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN\r\n      RAISE EXCEPTION 'Output quantities cannot be negative';\r\n    END IF;\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM public.products\r\n      WHERE id = r.item_id AND item_class IN ('FINISHED_GOOD', 'BY_PRODUCT') AND is_active\r\n    ) THEN\r\n      RAISE EXCEPTION 'Milling outputs must be FINISHED_GOOD or BY_PRODUCT items';\r\n    END IF;\r\n    v_total_out_bags := v_total_out_bags + coalesce(r.bags, 0);\r\n    v_total_out_kg   := v_total_out_kg + coalesce(r.kg, 0);\r\n  END LOOP;\r\n\r\n  v_doc := 'CM-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\r\n\r\n  -- صادر الحبوب\r\n  INSERT INTO public.custody_ledger\r\n    (customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n     bags_out, kg_out, notes, created_by)\r\n  VALUES\r\n    (_customer_id, _warehouse_id, 'MILLING', _grain_item_id, v_doc,\r\n     coalesce(_bags_out, 0), coalesce(_kg_out, 0), _notes, v_user);\r\n\r\n  -- وارد النواتج: سطر لكل ناتج\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs)\r\n             AS o(item_id uuid, bags numeric, kg numeric)\r\n  LOOP\r\n    INSERT INTO public.custody_ledger\r\n      (customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n       bags_in, kg_in, notes, created_by)\r\n    VALUES\r\n      (_customer_id, _warehouse_id, 'MILLING', r.item_id, v_doc,\r\n       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'custody.milling', 'custody_ledger', _customer_id,\r\n    jsonb_build_object(\r\n      'doc_number', v_doc,\r\n      'grain_item_id', _grain_item_id,\r\n      'grain_bags', coalesce(_bags_out, 0),\r\n      'grain_kg', coalesce(_kg_out, 0),\r\n      'outputs', _outputs,\r\n      'stock_impact', 'NONE — customer custody'\r\n    ));\r\n\r\n  RETURN v_doc;\r\nEND $function$","-- ── 3. التسليم ────────────────────────────────────────────────────────────\r\n-- لا يُسلَّم أكثر مما تبقى عندنا باسم العميل.\r\nCREATE OR REPLACE FUNCTION public.custody_delivery(_customer_id uuid, _warehouse_id uuid, _lines jsonb, _notes text)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_doc text;\r\n  v_balance_bags numeric;\r\n  v_balance_kg numeric;\r\n  v_batch_bags numeric;\r\n  v_batch_kg numeric;\r\n  r record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to record custody deliveries';\r\n  END IF;\r\n  IF _customer_id IS NULL OR _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Customer and warehouse are required';\r\n  END IF;\r\n  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN\r\n    RAISE EXCEPTION 'At least one delivery line is required';\r\n  END IF;\r\n\r\n  -- تحقق مسبق لكل صنف: الرصيد بعد الدفعة كاملة ≥ 0.\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_lines)\r\n             AS l(item_id uuid, bags numeric, kg numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL THEN\r\n      RAISE EXCEPTION 'Every delivery line needs an item';\r\n    END IF;\r\n    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every delivery line needs bags or a positive weight';\r\n    END IF;\r\n    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN\r\n      RAISE EXCEPTION 'Delivery quantities cannot be negative';\r\n    END IF;\r\n\r\n    SELECT * FROM public.custody_balance(_customer_id, _warehouse_id, r.item_id)\r\n      INTO v_balance_bags, v_balance_kg;\r\n\r\n    SELECT coalesce(sum(bags), 0), coalesce(sum(kg), 0)\r\n      INTO v_batch_bags, v_batch_kg\r\n    FROM jsonb_to_recordset(_lines) AS l2(item_id uuid, bags numeric, kg numeric)\r\n    WHERE l2.item_id = r.item_id;\r\n\r\n    IF coalesce(r.bags, 0) + (v_batch_bags - coalesce(r.bags, 0)) > v_balance_bags\r\n       OR coalesce(r.bags, 0) > v_balance_bags THEN\r\n      RAISE EXCEPTION 'Bags balance (%) for this item is less than the delivery (%)',\r\n        v_balance_bags, v_batch_bags;\r\n    END IF;\r\n    IF coalesce(r.kg, 0) + (v_batch_kg - coalesce(r.kg, 0)) > v_balance_kg\r\n       OR coalesce(r.kg, 0) > v_balance_kg THEN\r\n      RAISE EXCEPTION 'Kg balance (%) for this item is less than the delivery (%)',\r\n        v_balance_kg, v_batch_kg;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  v_doc := 'CD-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_delivery_seq')::text, 4, '0');\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_lines)\r\n             AS l(item_id uuid, bags numeric, kg numeric)\r\n  LOOP\r\n    INSERT INTO public.custody_ledger\r\n      (customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n       bags_out, kg_out, notes, created_by)\r\n    VALUES\r\n      (_customer_id, _warehouse_id, 'DELIVERY', r.item_id, v_doc,\r\n       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'custody.delivery', 'custody_ledger', _customer_id,\r\n    jsonb_build_object(\r\n      'doc_number', v_doc,\r\n      'lines', _lines,\r\n      'stock_impact', 'NONE — customer custody'\r\n    ));\r\n\r\n  RETURN v_doc;\r\nEND $function$","-- ── 3ب. تسجيل النواتج من نفس مستند خدمة الطحن ────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.milling_document_process(\r\n  _document_id uuid,\r\n  _grain_item_id uuid,\r\n  _bags_out numeric,\r\n  _kg_out numeric,\r\n  _outputs jsonb,\r\n  _notes text\r\n)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_customer_id uuid;\r\n  v_warehouse_id uuid;\r\n  v_status text;\r\n  v_doc text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to process milling documents';\r\n  END IF;\r\n  SELECT customer_id, warehouse_id, status\r\n    INTO v_customer_id, v_warehouse_id, v_status\r\n  FROM public.milling_service_documents\r\n  WHERE id = _document_id\r\n  FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Milling service document does not exist';\r\n  END IF;\r\n  IF v_status = 'DELIVERED' THEN\r\n    RAISE EXCEPTION 'Delivered milling service documents cannot be processed';\r\n  END IF;\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.custody_ledger\r\n    WHERE milling_document_id = _document_id AND item_id = _grain_item_id\r\n    GROUP BY item_id\r\n    HAVING sum(bags_in - bags_out) >= coalesce(_bags_out, 0)\r\n       AND sum(kg_in - kg_out) >= coalesce(_kg_out, 0)\r\n  ) THEN\r\n    RAISE EXCEPTION 'The selected grain quantity is not available on this milling document';\r\n  END IF;\r\n\r\n  v_doc := public.custody_milling(\r\n    v_customer_id, v_warehouse_id, _grain_item_id, _bags_out, _kg_out, _outputs, _notes\r\n  );\r\n  UPDATE public.custody_ledger\r\n  SET milling_document_id = _document_id\r\n  WHERE doc_number = v_doc AND entry_type = 'MILLING';\r\n  UPDATE public.milling_service_documents\r\n  SET status = 'PROCESSED', processed_at = coalesce(processed_at, now())\r\n  WHERE id = _document_id;\r\n\r\n  RETURN v_doc;\r\nEND $function$","-- ── 3ج. تسليم من المستند نفسه ─────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.milling_document_delivery(\r\n  _document_id uuid,\r\n  _lines jsonb,\r\n  _notes text\r\n)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_customer_id uuid;\r\n  v_warehouse_id uuid;\r\n  v_status text;\r\n  v_doc text;\r\n  v_has_remaining boolean;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to deliver milling documents';\r\n  END IF;\r\n  SELECT customer_id, warehouse_id, status\r\n    INTO v_customer_id, v_warehouse_id, v_status\r\n  FROM public.milling_service_documents\r\n  WHERE id = _document_id\r\n  FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Milling service document does not exist';\r\n  END IF;\r\n  IF v_status <> 'PROCESSED' THEN\r\n    RAISE EXCEPTION 'Record milling outputs before delivery';\r\n  END IF;\r\n  IF EXISTS (\r\n    SELECT 1\r\n    FROM jsonb_to_recordset(coalesce(_lines, '[]'::jsonb)) AS r(item_id uuid, bags numeric, kg numeric)\r\n    LEFT JOIN LATERAL (\r\n      SELECT sum(bags_in - bags_out) AS bags_balance, sum(kg_in - kg_out) AS kg_balance\r\n      FROM public.custody_ledger\r\n      WHERE milling_document_id = _document_id AND item_id = r.item_id\r\n    ) b ON true\r\n    WHERE coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0\r\n       OR coalesce(b.bags_balance, 0) < coalesce(r.bags, 0)\r\n       OR coalesce(b.kg_balance, 0) < coalesce(r.kg, 0)\r\n  ) THEN\r\n    RAISE EXCEPTION 'Delivery quantity is not available on this milling document';\r\n  END IF;\r\n\r\n  v_doc := public.custody_delivery(v_customer_id, v_warehouse_id, _lines, _notes);\r\n  UPDATE public.custody_ledger\r\n  SET milling_document_id = _document_id\r\n  WHERE doc_number = v_doc AND entry_type = 'DELIVERY';\r\n\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.custody_ledger\r\n    WHERE milling_document_id = _document_id\r\n    GROUP BY item_id\r\n    HAVING sum(bags_in - bags_out) > 0 OR sum(kg_in - kg_out) > 0\r\n  ) INTO v_has_remaining;\r\n\r\n  IF NOT v_has_remaining THEN\r\n    UPDATE public.milling_service_documents\r\n    SET status = 'DELIVERED', delivered_at = now()\r\n    WHERE id = _document_id;\r\n  END IF;\r\n  RETURN v_doc;\r\nEND $function$","-- ── 4. التعديل الجردي ─────────────────────────────────────────────────────\r\n-- سبب إلزامي. الفرق الموجب وارد والسالب صادر.\r\nCREATE OR REPLACE FUNCTION public.custody_adjustment(_customer_id uuid, _warehouse_id uuid, _item_id uuid, _bags_delta numeric, _kg_delta numeric, _reason text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_id uuid;\r\n  v_doc text;\r\n  v_balance_bags numeric;\r\n  v_balance_kg numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to record custody adjustments';\r\n  END IF;\r\n  IF nullif(btrim(coalesce(_reason, '')), '') IS NULL THEN\r\n    RAISE EXCEPTION 'A reason is required for a custody adjustment';\r\n  END IF;\r\n  IF coalesce(_bags_delta, 0) = 0 AND coalesce(_kg_delta, 0) = 0 THEN\r\n    RAISE EXCEPTION 'An adjustment needs a non-zero bags or kg change';\r\n  END IF;\r\n\r\n  SELECT * FROM public.custody_balance(_customer_id, _warehouse_id, _item_id)\r\n    INTO v_balance_bags, v_balance_kg;\r\n\r\n  IF coalesce(_bags_delta, 0) < 0 AND abs(_bags_delta) > v_balance_bags THEN\r\n    RAISE EXCEPTION 'Bags balance (%) cannot go below zero', v_balance_bags;\r\n  END IF;\r\n  IF coalesce(_kg_delta, 0) < 0 AND abs(_kg_delta) > v_balance_kg THEN\r\n    RAISE EXCEPTION 'Kg balance (%) cannot go below zero', v_balance_kg;\r\n  END IF;\r\n\r\n  v_doc := 'CA-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\r\n\r\n  INSERT INTO public.custody_ledger\r\n    (customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n     bags_in, bags_out, kg_in, kg_out,\r\n     notes, created_by)\r\n  VALUES\r\n    (_customer_id, _warehouse_id, 'ADJUSTMENT', _item_id, v_doc,\r\n     CASE WHEN coalesce(_bags_delta, 0) > 0 THEN _bags_delta ELSE 0 END,\r\n     CASE WHEN coalesce(_bags_delta, 0) < 0 THEN abs(_bags_delta) ELSE 0 END,\r\n     CASE WHEN coalesce(_kg_delta, 0) > 0 THEN _kg_delta ELSE 0 END,\r\n     CASE WHEN coalesce(_kg_delta, 0) < 0 THEN abs(_kg_delta) ELSE 0 END,\r\n     'سبب التعديل: ' || btrim(_reason), v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'custody.adjustment', 'custody_ledger', v_id,\r\n    jsonb_build_object(\r\n      'doc_number', v_doc,\r\n      'bags_delta', coalesce(_bags_delta, 0),\r\n      'kg_delta', coalesce(_kg_delta, 0),\r\n      'reason', btrim(_reason),\r\n      'stock_impact', 'NONE — customer custody'\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","-- ── 5. فاتورة الأجور: ربط سطر الأمانة بالفاتورة ───────────────────────────\r\n-- الفاتورة نفسها فاتورة مبيعات عادية ببند خدمي واحد (سعره من المنتج).\r\n-- هذه الدالة لا تنشئ الفاتورة — تُنشئها مسارات المبيعات القياسية، ثم يُربط\r\n-- سطر الأمانة المالي بها هنا ليظهر في التبويب المالي للكشف.\r\nCREATE OR REPLACE FUNCTION public.custody_link_invoice(_custody_entry_id uuid, _invoice_id uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to link custody invoices';\r\n  END IF;\r\n  IF _custody_entry_id IS NULL OR _invoice_id IS NULL THEN\r\n    RAISE EXCEPTION 'Custody entry and invoice are required';\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM public.sales_invoices WHERE id = _invoice_id) THEN\r\n    RAISE EXCEPTION 'Invoice does not exist';\r\n  END IF;\r\n  IF EXISTS (\r\n    SELECT 1 FROM public.custody_ledger\r\n    WHERE service_invoice_id = _invoice_id AND id <> _custody_entry_id\r\n  ) THEN\r\n    RAISE EXCEPTION 'This invoice is already linked to another custody entry';\r\n  END IF;\r\n\r\n  UPDATE public.custody_ledger\r\n     SET service_invoice_id = _invoice_id\r\n   WHERE id = _custody_entry_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'custody.invoice_linked', 'custody_ledger', _custody_entry_id,\r\n    jsonb_build_object('invoice_id', _invoice_id, 'stock_impact', 'NONE'));\r\nEND $function$","-- ═════════════\r\n-- زر التصنيع الذكي (خطوة 7): من مخزوننا — وارد قمح يُنقص، صادر نواتج تزيد.\r\n-- التكلفة توزّع على النواتج حسب أسعار البيع النسبية (لا نسبة يدوية) حتى لا\r\n-- تُباع بضاعة بربح وهمي وخسارة حقيقية.\r\n-- يُنفَّذ عبر post_stock_delta — بلا أي منظومة إنتاج (ق8).\r\n-- ═════════════════════\r\nCREATE OR REPLACE FUNCTION public.smart_manufacture(_warehouse_id uuid, _grain_item_id uuid, _grain_qty numeric, _outputs jsonb, _notes text)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_ref text;\r\n  v_output_value numeric := 0;\r\n  v_grain_cost numeric;\r\n  v_total_input_cost numeric;\r\n  v_total_allocated numeric := 0;\r\n  v_line_allocated numeric;\r\n  v_line_idx int := 0;\r\n  v_outputs_count int;\r\n  r record;\r\n  v_last_out numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to run smart manufacture';\r\n  END IF;\r\n  IF _warehouse_id IS NULL OR _grain_item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse and grain item are required';\r\n  END IF;\r\n  IF coalesce(_grain_qty, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'Grain quantity must be positive';\r\n  END IF;\r\n  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN\r\n    RAISE EXCEPTION 'At least one output line is required';\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active\r\n  ) THEN\r\n    RAISE EXCEPTION 'Input must be an active RAW_MATERIAL grain';\r\n  END IF;\r\n\r\n  v_outputs_count := jsonb_array_length(_outputs);\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL OR coalesce(r.qty, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every output line needs an item and a positive quantity';\r\n    END IF;\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM public.products\r\n      WHERE id = r.item_id AND item_class IN ('FINISHED_GOOD', 'BY_PRODUCT') AND is_active\r\n    ) THEN\r\n      RAISE EXCEPTION 'Outputs must be FINISHED_GOOD or BY_PRODUCT items';\r\n    END IF;\r\n    -- قيمة الناتج بسعر البيع = أساس التوزيع النسبي.\r\n    SELECT coalesce(r.qty, 0) * coalesce(sale_price, 0)\r\n      INTO v_last_out\r\n    FROM public.products WHERE id = r.item_id;\r\n    v_output_value := v_output_value + coalesce(v_last_out, 0);\r\n  END LOOP;\r\n\r\n  IF v_output_value <= 0 THEN\r\n    RAISE EXCEPTION 'Outputs must have sale prices to allocate cost by relative value';\r\n  END IF;\r\n\r\n  -- تكلفة القمح من طبقات التكلفة الفعلية، وإلا من كتالوج التكلفة.\r\n  SELECT coalesce(\r\n    (SELECT sum(cl.quantity * cl.unit_cost) / nullif(sum(cl.quantity), 0)\r\n       FROM public.item_cost_layers cl\r\n      WHERE cl.product_id = _grain_item_id AND cl.quantity > 0\r\n        AND cl.owner_type = 'COMPANY'),\r\n    (SELECT cost_price FROM public.products WHERE id = _grain_item_id),\r\n    0\r\n  ) INTO v_grain_cost;\r\n\r\n  v_total_input_cost := round(coalesce(_grain_qty, 0) * coalesce(v_grain_cost, 0), 2);\r\n  v_ref := 'SM-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\r\n\r\n  -- 1) صادر القمح (ينقص المخزون — المحرك يرفض لو الرصيد لا يكفي).\r\n  PERFORM public.post_stock_delta(\r\n    _grain_item_id, _warehouse_id, -coalesce(_grain_qty, 0), v_grain_cost,\r\n    'ISSUE'::public.stock_movement_kind, 'smart_manufacture', _grain_item_id,\r\n    'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n    'COMPANY'::public.owner_type, NULL, 'production_out'::public.movement_type);\r\n\r\n  -- 2) وارد النواتج بتكلفة موزّعة حسب أسعار البيع النسبية (ح4: تصحيح التراكم).\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)\r\n  LOOP\r\n    DECLARE\r\n      v_line_value numeric;\r\n      v_unit_cost numeric;\r\n    BEGIN\r\n      v_line_idx := v_line_idx + 1;\r\n      SELECT coalesce(r.qty, 0) * coalesce(sale_price, 0) INTO v_line_value\r\n      FROM public.products WHERE id = r.item_id;\r\n\r\n      IF v_line_idx = v_outputs_count THEN\r\n        -- آخر ناتج يحمل المتبقي بالضبط لتطابق إجمالي التكلفة\r\n        v_line_allocated := v_total_input_cost - v_total_allocated;\r\n      ELSE\r\n        v_line_allocated := round(v_total_input_cost * (coalesce(v_line_value, 0) / v_output_value), 2);\r\n        v_total_allocated := v_total_allocated + v_line_allocated;\r\n      END IF;\r\n\r\n      v_unit_cost := round(v_line_allocated / coalesce(r.qty, 0), 4);\r\n\r\n      PERFORM public.post_stock_delta(\r\n        r.item_id, _warehouse_id, coalesce(r.qty, 0), v_unit_cost,\r\n        'RECEIPT'::public.stock_movement_kind, 'smart_manufacture', _grain_item_id,\r\n        'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n        'COMPANY'::public.owner_type, NULL, 'production_in'::public.movement_type);\r\n    END;\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'manufacture.smart', 'stock_movements', _grain_item_id,\r\n    jsonb_build_object(\r\n      'ref', v_ref,\r\n      'warehouse_id', _warehouse_id,\r\n      'grain_item_id', _grain_item_id,\r\n      'grain_qty', coalesce(_grain_qty, 0),\r\n      'grain_unit_cost', v_grain_cost,\r\n      'outputs', _outputs,\r\n      'allocation', 'RELATIVE_SALES_VALUE'\r\n    ));\r\n\r\n  RETURN v_ref;\r\nEND $function$","-- ═════════════════════\r\n-- فاتورة صرف مستهلكات داخلي (خطوة 7 — ق4): تُنقص كميات المستهلكات من مخزن\r\n-- المستهلكات بدقة — نفس أدوات المخزون القياسية، بلا جدول مستهلكات خاص.\r\n-- ═════════════════════\r\nCREATE OR REPLACE FUNCTION public.consume_internal_supplies(_warehouse_id uuid, _lines jsonb, _notes text)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_ref text;\r\n  r record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to issue internal consumables';\r\n  END IF;\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN\r\n    RAISE EXCEPTION 'At least one consumable line is required';\r\n  END IF;\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, qty numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL OR coalesce(r.qty, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every line needs an item and a positive quantity';\r\n    END IF;\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM public.products\r\n      WHERE id = r.item_id AND item_class IN ('NON_STOCK_ITEM', 'PACKAGING') AND is_active\r\n    ) THEN\r\n      RAISE EXCEPTION 'Only consumable (NON_STOCK_ITEM / PACKAGING) items may be issued here';\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- م2: استخدام بادئة CS- (Consumables Supply) لتمييز صرف المستهلكات عن استلام الأمانات CI-\r\n  v_ref := 'CS-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, qty numeric)\r\n  LOOP\r\n    PERFORM public.post_stock_delta(\r\n      r.item_id, _warehouse_id, -coalesce(r.qty, 0), NULL,\r\n      'ISSUE'::public.stock_movement_kind, 'internal_consumables', _warehouse_id,\r\n      'صرف مستهلكات داخلي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n      'COMPANY'::public.owner_type, NULL, 'adjustment'::public.movement_type);\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'consumables.issued', 'stock_movements', _warehouse_id,\r\n    jsonb_build_object(\r\n      'ref', v_ref,\r\n      'warehouse_id', _warehouse_id,\r\n      'lines', _lines,\r\n      'notes', _notes\r\n    ));\r\n\r\n  RETURN v_ref;\r\nEND $function$","-- ── RLS ───────────────────────────────────────────────────────────────────\r\nALTER TABLE public.custody_ledger ENABLE ROW LEVEL SECURITY","ALTER TABLE public.milling_service_documents ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"milling_service_documents_read\\" ON public.milling_service_documents\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_view_milling())","CREATE POLICY \\"milling_service_documents_service_all\\" ON public.milling_service_documents\r\n  FOR ALL TO service_role\r\n  USING (true)\r\n  WITH CHECK (true)","CREATE POLICY \\"custody_ledger_read\\" ON public.custody_ledger\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_view_milling())","CREATE POLICY \\"custody_ledger_service_all\\" ON public.custody_ledger\r\n  FOR ALL TO service_role\r\n  USING (true)\r\n  WITH CHECK (true)","-- الكتابة عبر RPC فقط (R-23): ممنوع INSERT/UPDATE/DELETE من العميل.\r\nREVOKE INSERT, UPDATE, DELETE ON public.custody_ledger FROM authenticated","REVOKE INSERT, UPDATE, DELETE ON public.custody_ledger FROM anon","REVOKE INSERT, UPDATE, DELETE ON public.milling_service_documents FROM authenticated","REVOKE INSERT, UPDATE, DELETE ON public.milling_service_documents FROM anon","REVOKE ALL ON SEQUENCE public.milling_intake_seq, public.milling_service_seq, public.milling_delivery_seq, public.milling_document_seq FROM PUBLIC, anon, authenticated","GRANT USAGE ON SEQUENCE public.milling_intake_seq, public.milling_service_seq, public.milling_delivery_seq, public.milling_document_seq TO service_role","GRANT SELECT ON public.custody_balances TO authenticated","GRANT SELECT ON public.custody_balances TO service_role","GRANT SELECT ON public.milling_service_documents TO authenticated","GRANT SELECT ON public.milling_service_documents TO service_role","GRANT EXECUTE ON FUNCTION public.custody_balance(uuid, uuid, uuid) TO authenticated","GRANT EXECUTE ON FUNCTION public.custody_balance(uuid, uuid, uuid) TO service_role","GRANT EXECUTE ON FUNCTION public.create_milling_service_document(uuid, uuid, uuid, numeric, numeric, uuid, numeric, numeric, text, numeric, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.create_milling_service_document(uuid, uuid, uuid, numeric, numeric, uuid, numeric, numeric, text, numeric, text) TO service_role","GRANT EXECUTE ON FUNCTION public.custody_intake(uuid, uuid, uuid, numeric, numeric, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.custody_intake(uuid, uuid, uuid, numeric, numeric, text) TO service_role","GRANT EXECUTE ON FUNCTION public.custody_milling(uuid, uuid, uuid, numeric, numeric, jsonb, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.custody_milling(uuid, uuid, uuid, numeric, numeric, jsonb, text) TO service_role","GRANT EXECUTE ON FUNCTION public.custody_delivery(uuid, uuid, jsonb, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.custody_delivery(uuid, uuid, jsonb, text) TO service_role","GRANT EXECUTE ON FUNCTION public.milling_document_process(uuid, uuid, numeric, numeric, jsonb, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.milling_document_process(uuid, uuid, numeric, numeric, jsonb, text) TO service_role","GRANT EXECUTE ON FUNCTION public.milling_document_delivery(uuid, jsonb, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.milling_document_delivery(uuid, jsonb, text) TO service_role","GRANT EXECUTE ON FUNCTION public.custody_adjustment(uuid, uuid, uuid, numeric, numeric, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.custody_adjustment(uuid, uuid, uuid, numeric, numeric, text) TO service_role","REVOKE EXECUTE ON FUNCTION public.custody_link_invoice(uuid, uuid) FROM authenticated","GRANT EXECUTE ON FUNCTION public.custody_link_invoice(uuid, uuid) TO service_role","GRANT EXECUTE ON FUNCTION public.smart_manufacture(uuid, uuid, numeric, jsonb, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.smart_manufacture(uuid, uuid, numeric, jsonb, text) TO service_role","GRANT EXECUTE ON FUNCTION public.consume_internal_supplies(uuid, jsonb, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.consume_internal_supplies(uuid, jsonb, text) TO service_role","-- ============================================================================\r\n-- ROLLBACK:\r\n--   DROP VIEW public.custody_balances;\r\n--   DROP FUNCTION public.custody_intake, custody_milling, custody_delivery,\r\n--                custody_adjustment, custody_link_invoice, custody_balance,\r\n--                smart_manufacture, consume_internal_supplies;\r\n--   DROP TABLE public.milling_service_documents, public.custody_ledger;\r\n--   DROP TYPE public.custody_entry_type;\r\n--   DROP SEQUENCE milling_intake_seq, milling_service_seq, milling_delivery_seq, milling_document_seq;\r\n-- ============================================================================"}	milling_custody
11	{"-- ============================================================================\r\n-- 12_platform_and_audit.sql\r\n--\r\n-- المنصة والاشتراكات وسجل التدقيق.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── TABLES ────────────────────────────────────────────────────────────────\r\nCREATE TABLE public.platform_modules (\r\n  id text NOT NULL,\r\n  name jsonb NOT NULL,\r\n  description jsonb,\r\n  category text NOT NULL,\r\n  dependencies text[] DEFAULT '{}'::text[] NOT NULL,\r\n  nav_items text[] DEFAULT '{}'::text[] NOT NULL,\r\n  routes text[] DEFAULT '{}'::text[] NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.platform_plans (\r\n  id text NOT NULL,\r\n  name jsonb NOT NULL,\r\n  description jsonb,\r\n  modules text[] DEFAULT '{}'::text[] NOT NULL,\r\n  max_users integer DEFAULT 1 NOT NULL,\r\n  max_warehouses integer DEFAULT 1 NOT NULL,\r\n  max_products integer,\r\n  price_monthly numeric(10,2) DEFAULT 0 NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.tenant_subscriptions (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  tenant_id text DEFAULT 'default'::text NOT NULL,\r\n  plan_id text NOT NULL,\r\n  extra_modules text[] DEFAULT '{}'::text[] NOT NULL,\r\n  disabled_modules text[] DEFAULT '{}'::text[] NOT NULL,\r\n  status text DEFAULT 'active'::text NOT NULL,\r\n  started_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  expires_at timestamp with time zone,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\r\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.platform_audit_logs (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  admin_id uuid,\r\n  user_id uuid,\r\n  action text NOT NULL,\r\n  target_tenant_id text,\r\n  payload jsonb,\r\n  ip_address text,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","CREATE TABLE public.audit_logs (\r\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\r\n  actor_id uuid,\r\n  action text NOT NULL,\r\n  entity_type text NOT NULL,\r\n  entity_id uuid,\r\n  payload jsonb,\r\n  created_at timestamp with time zone DEFAULT now() NOT NULL\r\n)","-- ── CONSTRAINTS ───────────────────────────────────────────────────────────\r\nALTER TABLE public.platform_modules ADD CONSTRAINT \\"platform_modules_category_check\\" CHECK ((category = ANY (ARRAY['core'::text, 'module'::text, 'addon'::text, 'enterprise'::text])))","ALTER TABLE public.platform_modules ADD CONSTRAINT \\"platform_modules_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.platform_plans ADD CONSTRAINT \\"platform_plans_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.tenant_subscriptions ADD CONSTRAINT \\"tenant_subscriptions_status_check\\" CHECK ((status = ANY (ARRAY['active'::text, 'trialing'::text, 'past_due'::text, 'canceled'::text])))","ALTER TABLE public.tenant_subscriptions ADD CONSTRAINT \\"tenant_subscriptions_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.tenant_subscriptions ADD CONSTRAINT \\"uq_tenant_subscription\\" UNIQUE (tenant_id)","ALTER TABLE public.platform_audit_logs ADD CONSTRAINT \\"platform_audit_logs_pkey\\" PRIMARY KEY (id)","ALTER TABLE public.audit_logs ADD CONSTRAINT \\"audit_logs_pkey\\" PRIMARY KEY (id)","-- ── INDEXES ───────────────────────────────────────────────────────────────\r\nCREATE INDEX idx_audit_created ON public.audit_logs USING btree (created_at DESC)","CREATE INDEX idx_audit_entity ON public.audit_logs USING btree (entity_type, entity_id)","-- ── SEQUENCES ─────────────────────────────────────────────────────────────\r\nCREATE SEQUENCE IF NOT EXISTS public.expense_reference_seq START 1"}	platform_and_audit
12	{"-- ============================================================================\r\n-- 13_reporting_views.sql\r\n--\r\n-- العروض (Views): ميزان المراجعة، تقييم المخزون، أرصدة العملاء، حالات الترحيل.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\nCREATE OR REPLACE VIEW public.customer_ledger_balances AS\r\n SELECT c.id AS customer_id,\r\n    c.name,\r\n    round(COALESCE(sum((l.debit - l.credit)), (0)::numeric), 2) AS ledger_balance,\r\n    c.balance AS legacy_balance,\r\n    round((COALESCE(sum((l.debit - l.credit)), (0)::numeric) - c.balance), 2) AS difference\r\n   FROM (customers c\r\n     LEFT JOIN customer_ledger l ON ((l.customer_id = c.id)))\r\n  GROUP BY c.id, c.name, c.balance","CREATE OR REPLACE VIEW public.expense_legacy_reconciliation AS\r\n SELECT count(*) AS legacy_rows,\r\n    count(*) FILTER (WHERE (l.id IS NULL)) AS not_yet_migrated,\r\n    count(*) FILTER (WHERE (l.id IS NOT NULL)) AS already_migrated,\r\n    COALESCE(sum(x.amount), (0)::numeric) AS legacy_total,\r\n    COALESCE(sum(b.gross_amount), (0)::numeric) AS migrated_total,\r\n    COALESCE(min(x.expense_date), CURRENT_DATE) AS first_date,\r\n    COALESCE(max(x.expense_date), CURRENT_DATE) AS last_date,\r\n    count(*) FILTER (WHERE (x.category_id IS NULL)) AS uncategorised_rows,\r\n    count(*) FILTER (WHERE (x.payment_method = 'credit'::payment_method)) AS credit_method_rows\r\n   FROM ((expenses x\r\n     LEFT JOIN expense_entries l ON ((l.legacy_expense_id = x.id)))\r\n     LEFT JOIN expense_lines b ON ((b.entry_id = l.id)))\r\n  GROUP BY ()","CREATE OR REPLACE VIEW public.invoice_ledger_status AS\r\n SELECT si.id AS invoice_id,\r\n    si.invoice_number,\r\n    (si.status)::text AS invoice_status,\r\n    si.total,\r\n    si.paid,\r\n    si.tax,\r\n    (si.payment_method)::text AS payment_method,\r\n    je.id AS journal_entry_id,\r\n    je.entry_number,\r\n        CASE\r\n            WHEN (je.id IS NOT NULL) THEN 'POSTED'::text\r\n            WHEN (si.status = ANY (ARRAY['draft'::invoice_status, 'cancelled'::invoice_status])) THEN 'NEVER_POSTS'::text\r\n            ELSE 'NOT_POSTED'::text\r\n        END AS ledger_state,\r\n        CASE\r\n            WHEN ((je.id IS NOT NULL) AND (je.total_debit <> je.total_credit)) THEN 'UNBALANCED'::text\r\n            ELSE 'OK'::text\r\n        END AS integrity\r\n   FROM (sales_invoices si\r\n     LEFT JOIN journal_entries je ON (((je.source_type = 'sales_invoice'::text) AND (je.source_id = si.id) AND (je.status <> 'REVERSED'::text))))","CREATE OR REPLACE VIEW public.item_classification_gaps AS\r\n SELECT id,\r\n    sku,\r\n    name_ar,\r\n    item_nature,\r\n    item_class,\r\n    inventory_policy,\r\n        CASE\r\n            WHEN ((sku IS NULL) OR (btrim(sku) = ''::text)) THEN 'بلا رمز صنف — التصنيف الخماسي غير مُتحقَّق منه (نخالة أم دقيق؟) يحتاج تأكيداً يدوياً'::text\r\n            WHEN (item_nature = 'SERVICE'::item_nature) THEN 'nature: service, class must be SERVICE'::text\r\n            WHEN (inventory_policy = 'CUSTOMER_OWNED'::inventory_policy) THEN 'policy: customer owned, class must be NON_STOCK_ITEM'::text\r\n            WHEN (inventory_policy = 'UNTRACKED'::inventory_policy) THEN 'policy: untracked, class must be SERVICE or NON_STOCK_ITEM'::text\r\n            WHEN (sku ~~ 'RM-%'::text) THEN 'sku: raw material prefix, class should be RAW_MATERIAL'::text\r\n            WHEN (sku = 'FG-BRAN-40'::text) THEN 'catalogue: bran is a by-product'::text\r\n            ELSE 'unclassified GOOD+TRACKED item'::text\r\n        END AS reason\r\n   FROM products p\r\n  WHERE (is_active AND ((item_class IS NULL) OR ((sku IS NULL) OR (btrim(sku) = ''::text)) OR ((item_nature = 'SERVICE'::item_nature) AND (item_class <> 'SERVICE'::item_class)) OR ((inventory_policy = 'CUSTOMER_OWNED'::inventory_policy) AND (item_class <> 'NON_STOCK_ITEM'::item_class)) OR ((inventory_policy = 'UNTRACKED'::inventory_policy) AND (item_nature = 'GOOD'::item_nature) AND (item_class <> 'NON_STOCK_ITEM'::item_class)) OR ((sku ~~ 'RM-%'::text) AND (item_class <> 'RAW_MATERIAL'::item_class)) OR ((sku = 'FG-BRAN-40'::text) AND (item_class <> 'BY_PRODUCT'::item_class))))","CREATE OR REPLACE VIEW public.item_valuation AS\r\n WITH qty AS (\r\n         SELECT inventory.product_id,\r\n            sum(inventory.quantity) AS on_hand_qty\r\n           FROM inventory\r\n          WHERE (inventory.owner_type = 'COMPANY'::owner_type)\r\n          GROUP BY inventory.product_id\r\n        ), val AS (\r\n         SELECT cl.product_id,\r\n            sum(cl.total_value) AS valuation,\r\n            count(*) FILTER (WHERE (cl.total_value > (0)::numeric)) AS valued_layers\r\n           FROM item_cost_layers cl\r\n          WHERE (cl.owner_type = 'COMPANY'::owner_type)\r\n          GROUP BY cl.product_id\r\n        )\r\n SELECT p.id AS product_id,\r\n    p.sku,\r\n    p.name_ar,\r\n    p.item_class,\r\n    COALESCE(q.on_hand_qty, (0)::numeric) AS on_hand_qty,\r\n    COALESCE(v.valuation, (0)::numeric) AS valuation,\r\n        CASE\r\n            WHEN (COALESCE(q.on_hand_qty, (0)::numeric) <> (0)::numeric) THEN round((COALESCE(v.valuation, (0)::numeric) / q.on_hand_qty), 4)\r\n            ELSE (0)::numeric\r\n        END AS actual_unit_cost,\r\n        CASE\r\n            WHEN ((v.valued_layers IS NULL) OR (v.valued_layers = 0)) THEN 'REFERENCE_ONLY'::text\r\n            ELSE 'ACTUAL'::text\r\n        END AS valuation_basis,\r\n    p.cost_price AS catalogue_cost,\r\n    p.standard_cost\r\n   FROM ((products p\r\n     LEFT JOIN qty q ON ((q.product_id = p.id)))\r\n     LEFT JOIN val v ON ((v.product_id = p.id)))","-- ── أمانات المطحنة: طبقة المطابقة — كل الرصيد مشتق من custody_ledger ─────\r\n-- كشف العميل: المستلم، المطحون، المسلَّم، المتبقي — لكل عميل/صنف/مخزن.\r\nCREATE OR REPLACE VIEW public.custody_customer_statement AS\r\n SELECT l.customer_id,\r\n    c.name AS customer_name_ar,\r\n    l.warehouse_id,\r\n    w.name_ar AS warehouse_name_ar,\r\n    l.item_id,\r\n    p.sku,\r\n    p.name_ar AS item_name_ar,\r\n    p.item_class,\r\n    sum(l.bags_in) AS received_bags,\r\n    sum(l.kg_in) AS received_kg,\r\n    sum(l.bags_out) AS issued_bags,\r\n    sum(l.kg_out) AS issued_kg,\r\n    sum((l.bags_in - l.bags_out)) AS remaining_bags,\r\n    sum((l.kg_in - l.kg_out)) AS remaining_kg,\r\n    max(l.created_at) AS last_movement_at\r\n   FROM (((public.custody_ledger l\r\n     JOIN public.products p ON ((p.id = l.item_id)))\r\n     LEFT JOIN public.customers c ON ((c.id = l.customer_id)))\r\n     LEFT JOIN public.warehouses w ON ((w.id = l.warehouse_id)))\r\n  GROUP BY l.customer_id, c.name, l.warehouse_id, w.name_ar, l.item_id, p.sku, p.name_ar, p.item_class","-- التبويب المالي: المستند الموحد هو المصدر للفواتير الجديدة. الجزء الثاني\r\n-- يبقي فواتير الربط اليدوي التاريخية قابلة للقراءة فقط أثناء الانتقال.\r\nCREATE OR REPLACE VIEW public.custody_service_money AS\r\n SELECT d.id AS custody_entry_id,\r\n    d.customer_id,\r\n    c.name AS customer_name_ar,\r\n    d.document_number AS doc_number,\r\n    d.created_at,\r\n    si.id AS invoice_id,\r\n    si.invoice_number,\r\n    si.status,\r\n    si.subtotal,\r\n    si.tax,\r\n    si.discount,\r\n    si.total,\r\n    si.paid,\r\n    round((si.total - si.paid), 2) AS outstanding\r\n   FROM ((public.milling_service_documents d\r\n     JOIN public.sales_invoices si ON ((si.id = d.sales_invoice_id)))\r\n     LEFT JOIN public.customers c ON ((c.id = d.customer_id)))\r\n UNION ALL\r\n SELECT l.id AS custody_entry_id,\r\n    l.customer_id,\r\n    c.name AS customer_name_ar,\r\n    l.doc_number,\r\n    l.created_at,\r\n    si.id AS invoice_id,\r\n    si.invoice_number,\r\n    si.status,\r\n    si.subtotal,\r\n    si.tax,\r\n    si.discount,\r\n    si.total,\r\n    si.paid,\r\n    round((si.total - si.paid), 2) AS outstanding\r\n   FROM ((public.custody_ledger l\r\n     JOIN public.sales_invoices si ON ((si.id = l.service_invoice_id)))\r\n     LEFT JOIN public.customers c ON ((c.id = l.customer_id)))\r\n  WHERE NOT EXISTS (\r\n    SELECT 1 FROM public.milling_service_documents d\r\n    WHERE d.sales_invoice_id = l.service_invoice_id\r\n  )","-- الفاقد المكتشف: صادر الحبوب − وارد النواتج لكل عملية طحن (مستند/سند).\r\n-- لا حقل إدخال للفاقد؛ التنبيه استدلالي لمراقبة التوازن التشغيلي (ح2).\r\nCREATE OR REPLACE VIEW public.custody_detected_loss AS\r\n WITH grain_flow AS (\r\n         SELECT l.customer_id,\r\n            l.warehouse_id,\r\n            l.item_id,\r\n            coalesce(l.milling_document_id::text, l.doc_number) AS operation_key,\r\n            p.name_ar AS grain_name_ar,\r\n            sum(l.kg_out) AS milled_kg,\r\n            sum(l.bags_out) AS milled_bags\r\n           FROM (public.custody_ledger l\r\n             JOIN public.products p ON ((p.id = l.item_id)))\r\n          WHERE ((l.entry_type = 'MILLING'::custody_entry_type) AND (p.item_class = 'RAW_MATERIAL'::item_class))\r\n          GROUP BY l.customer_id, l.warehouse_id, l.item_id, coalesce(l.milling_document_id::text, l.doc_number), p.name_ar\r\n        ), output_flow AS (\r\n         SELECT l.customer_id,\r\n            l.warehouse_id,\r\n            coalesce(l.milling_document_id::text, l.doc_number) AS operation_key,\r\n            sum(l.kg_in) AS produced_kg,\r\n            sum(l.bags_in) AS produced_bags\r\n           FROM (public.custody_ledger l\r\n             JOIN public.products p ON ((p.id = l.item_id)))\r\n          WHERE ((l.entry_type = 'MILLING'::custody_entry_type) AND (p.item_class = ANY (ARRAY['FINISHED_GOOD'::item_class, 'BY_PRODUCT'::item_class])))\r\n          GROUP BY l.customer_id, l.warehouse_id, coalesce(l.milling_document_id::text, l.doc_number)\r\n        )\r\n SELECT g.customer_id,\r\n    c.name AS customer_name_ar,\r\n    g.warehouse_id,\r\n    w.name_ar AS warehouse_name_ar,\r\n    g.item_id,\r\n    g.grain_name_ar,\r\n    g.operation_key,\r\n    g.milled_bags,\r\n    g.milled_kg,\r\n    COALESCE(o.produced_bags, (0)::numeric) AS produced_bags,\r\n    COALESCE(o.produced_kg, (0)::numeric) AS produced_kg,\r\n    round((g.milled_kg - COALESCE(o.produced_kg, (0)::numeric)), 3) AS detected_loss_kg,\r\n        CASE\r\n            WHEN ((g.milled_kg > (0)::numeric) AND ((g.milled_kg - COALESCE(o.produced_kg, (0)::numeric)) > (g.milled_kg * (0.05)::numeric))) THEN 'REVIEW'::text\r\n            ELSE 'OK'::text\r\n        END AS loss_status\r\n   FROM (((grain_flow g\r\n     LEFT JOIN output_flow o ON (((o.customer_id = g.customer_id) AND (o.warehouse_id = g.warehouse_id) AND (o.operation_key = g.operation_key))))\r\n     LEFT JOIN public.customers c ON ((c.id = g.customer_id)))\r\n     LEFT JOIN public.warehouses w ON ((w.id = g.warehouse_id)))","CREATE OR REPLACE VIEW public.milling_margin_report AS\r\n WITH sold AS (\r\n         SELECT it.product_id,\r\n            sum(it.quantity) AS qty_sold,\r\n            sum(it.total) AS revenue,\r\n            count(DISTINCT si.id) AS invoice_count\r\n           FROM (sales_invoice_items it\r\n             JOIN sales_invoices si ON ((si.id = it.invoice_id)))\r\n          WHERE ((((si.created_at)::date >= (CURRENT_DATE - 365)) AND ((si.created_at)::date <= CURRENT_DATE)) AND (si.status <> ALL (ARRAY['draft'::invoice_status, 'cancelled'::invoice_status])) AND (it.stock_effect = 'STOCK_ISSUE'::text))\r\n          GROUP BY it.product_id\r\n        )\r\n SELECT p.id AS product_id,\r\n    p.sku,\r\n    p.name_ar,\r\n    p.item_class,\r\n    COALESCE(s.qty_sold, (0)::numeric) AS qty_sold,\r\n    COALESCE(s.revenue, (0)::numeric) AS revenue,\r\n    COALESCE(s.invoice_count, (0)::bigint) AS invoice_count,\r\n    c.unit_cost,\r\n    c.basis,\r\n    round((COALESCE(s.qty_sold, (0)::numeric) * COALESCE(c.unit_cost, (0)::numeric)), 2) AS cost_of_goods,\r\n    round((COALESCE(s.revenue, (0)::numeric) - (COALESCE(s.qty_sold, (0)::numeric) * COALESCE(c.unit_cost, (0)::numeric))), 2) AS margin,\r\n        CASE\r\n            WHEN (COALESCE(s.revenue, (0)::numeric) > (0)::numeric) THEN round((((COALESCE(s.revenue, (0)::numeric) - (COALESCE(s.qty_sold, (0)::numeric) * COALESCE(c.unit_cost, (0)::numeric))) * (100)::numeric) / s.revenue), 2)\r\n            ELSE NULL::numeric\r\n        END AS margin_pct,\r\n        CASE\r\n            WHEN (c.basis = 'ACTUAL'::text) THEN 'ACTUAL'::text\r\n            ELSE 'REFERENCE'::text\r\n        END AS cost_basis\r\n   FROM ((sold s\r\n     JOIN products p ON ((p.id = s.product_id)))\r\n     LEFT JOIN LATERAL ( SELECT COALESCE(\r\n                CASE\r\n                    WHEN (l.quantity > (0)::numeric) THEN round((l.total_value / l.quantity), 4)\r\n                    ELSE NULL::numeric\r\n                END, p.cost_price, (0)::numeric) AS unit_cost,\r\n                CASE\r\n                    WHEN ((l.quantity > (0)::numeric) AND (l.total_value > (0)::numeric)) THEN 'ACTUAL'::text\r\n                    ELSE 'REFERENCE'::text\r\n                END AS basis\r\n           FROM (( SELECT 1 AS \\"?column?\\") x\r\n             LEFT JOIN LATERAL ( SELECT sum(cl.quantity) AS quantity,\r\n                    sum(cl.total_value) AS total_value\r\n                   FROM item_cost_layers cl\r\n                  WHERE ((cl.product_id = p.id) AND (cl.owner_type = 'COMPANY'::owner_type))) l ON (true))) c ON (true))","CREATE OR REPLACE VIEW public.opening_balance_summary AS\r\n SELECT d.id,\r\n    d.document_number,\r\n    d.effective_date,\r\n    d.status,\r\n    d.fiscal_year,\r\n    d.total_assets,\r\n    d.total_liabilities,\r\n    d.capital_required,\r\n    d.notes,\r\n    COALESCE(s.stock_amount, (0)::numeric) AS stock_amount,\r\n    COALESCE(s.receivable_amount, (0)::numeric) AS receivable_amount,\r\n    COALESCE(s.payable_amount, (0)::numeric) AS payable_amount,\r\n    COALESCE(s.cash_amount, (0)::numeric) AS cash_amount,\r\n    COALESCE(s.bank_amount, (0)::numeric) AS bank_amount,\r\n    COALESCE(s.asset_amount, (0)::numeric) AS asset_amount,\r\n    COALESCE(s.liability_amount, (0)::numeric) AS liability_amount,\r\n    COALESCE(s.capital_amount, (0)::numeric) AS capital_amount,\r\n    COALESCE(s.debit, (0)::numeric) AS total_debits,\r\n    COALESCE(s.credit, (0)::numeric) AS total_credits,\r\n    round((COALESCE(s.debit, (0)::numeric) - COALESCE(s.credit, (0)::numeric)), 2) AS capital_required_now,\r\n    (COALESCE(s.debit, (0)::numeric) = COALESCE(s.credit, (0)::numeric)) AS is_balanced\r\n   FROM (opening_balance_documents d\r\n     LEFT JOIN LATERAL ( SELECT sum(l.amount) FILTER (WHERE (l.side = 'DEBIT'::text)) AS debit,\r\n            sum(l.amount) FILTER (WHERE (l.side = 'CREDIT'::text)) AS credit,\r\n            sum(l.amount) FILTER (WHERE (l.section = 'STOCK'::text)) AS stock_amount,\r\n            sum(l.amount) FILTER (WHERE (l.section = 'RECEIVABLE'::text)) AS receivable_amount,\r\n            sum(l.amount) FILTER (WHERE (l.section = 'PAYABLE'::text)) AS payable_amount,\r\n            sum(l.amount) FILTER (WHERE (l.section = 'CASH'::text)) AS cash_amount,\r\n            sum(l.amount) FILTER (WHERE (l.section = 'BANK'::text)) AS bank_amount,\r\n            sum(l.amount) FILTER (WHERE (l.section = 'ASSET'::text)) AS asset_amount,\r\n            sum(l.amount) FILTER (WHERE (l.section = 'LIABILITY'::text)) AS liability_amount,\r\n            sum(l.amount) FILTER (WHERE (l.section = 'CAPITAL'::text)) AS capital_amount\r\n           FROM opening_balance_lines l\r\n          WHERE (l.document_id = d.id)) s ON (true))","CREATE OR REPLACE VIEW public.purchase_ledger_status AS\r\n SELECT pi.id AS invoice_id,\r\n    pi.invoice_number,\r\n    (pi.status)::text AS invoice_status,\r\n    pi.total,\r\n    pi.paid,\r\n    (pi.payment_method)::text AS payment_method,\r\n    je.id AS journal_entry_id,\r\n    je.entry_number,\r\n        CASE\r\n            WHEN (je.id IS NOT NULL) THEN 'POSTED'::text\r\n            WHEN (pi.status = ANY (ARRAY['draft'::invoice_status, 'cancelled'::invoice_status])) THEN 'NEVER_POSTS'::text\r\n            ELSE 'NOT_POSTED'::text\r\n        END AS ledger_state\r\n   FROM (purchase_invoices pi\r\n     LEFT JOIN journal_entries je ON (((je.source_type = 'purchase_invoice'::text) AND (je.source_id = pi.id) AND (je.status <> 'REVERSED'::text))))","CREATE OR REPLACE VIEW public.purchase_register AS\r\n SELECT i.id AS purchase_item_id,\r\n    i.invoice_id,\r\n    s.invoice_number,\r\n    s.created_at,\r\n    s.supplier_id,\r\n    s.status,\r\n    i.product_id,\r\n    p.name AS item_name,\r\n    p.name_ar AS item_name_ar,\r\n    p.sku,\r\n    i.quantity,\r\n    i.unit_cost,\r\n    i.discount,\r\n    i.tax,\r\n    i.total,\r\n    COALESCE(i.line_type,\r\n        CASE\r\n            WHEN (i.product_id IS NULL) THEN 'AD_HOC_SERVICE'::text\r\n            ELSE item_line_type(i.product_id, false)\r\n        END) AS line_type,\r\n    COALESCE(i.stock_effect, 'NONE'::text) AS stock_effect,\r\n    (COALESCE(i.stock_effect, 'NONE'::text) = 'STOCK_RECEIPT'::text) AS increases_inventory\r\n   FROM ((purchase_invoice_items i\r\n     JOIN purchase_invoices s ON ((s.id = i.invoice_id)))\r\n     LEFT JOIN products p ON ((p.id = i.product_id)))","CREATE OR REPLACE VIEW public.sales_register AS\r\n SELECT i.id AS invoice_item_id,\r\n    i.invoice_id,\r\n    s.invoice_number,\r\n    s.created_at,\r\n    s.customer_id,\r\n    s.status,\r\n    s.payment_method,\r\n    i.product_id,\r\n    i.description,\r\n    p.name AS item_name,\r\n    p.name_ar AS item_name_ar,\r\n    p.sku,\r\n    i.quantity,\r\n    i.unit_price,\r\n    i.discount,\r\n    i.tax,\r\n    i.total,\r\n    COALESCE(i.line_type,\r\n        CASE\r\n            WHEN (i.product_id IS NULL) THEN 'AD_HOC_SERVICE'::text\r\n            ELSE item_line_type(i.product_id, false)\r\n        END) AS line_type,\r\n    COALESCE(i.stock_effect, 'NONE'::text) AS stock_effect,\r\n    i.uom_id,\r\n    sales_line_cost(i.product_id, i.invoice_id, i.quantity, i.line_type) AS line_cost\r\n   FROM ((sales_invoice_items i\r\n     JOIN sales_invoices s ON ((s.id = i.invoice_id)))\r\n     LEFT JOIN products p ON ((p.id = i.product_id)))","CREATE OR REPLACE VIEW public.service_revenue AS\r\n SELECT invoice_id,\r\n    invoice_number,\r\n    created_at,\r\n    customer_id,\r\n    line_type,\r\n    description,\r\n    quantity,\r\n    unit_price,\r\n    total,\r\n    false AS affects_inventory\r\n   FROM sales_register r\r\n  WHERE ((line_type = ANY (ARRAY['SERVICE'::text, 'AD_HOC_SERVICE'::text])) AND (status <> ALL (ARRAY['draft'::invoice_status, 'cancelled'::invoice_status, 'returned'::invoice_status])))","CREATE OR REPLACE VIEW public.standard_cost_readiness AS\r\n SELECT p.id AS product_id,\r\n    p.sku,\r\n    p.name_ar,\r\n    p.item_class,\r\n    p.unit_id,\r\n    p.cost_price AS catalogue_cost,\r\n    p.standard_cost,\r\n        CASE\r\n            WHEN (cl.quantity > (0)::numeric) THEN round((cl.total_value / cl.quantity), 4)\r\n            ELSE NULL::numeric\r\n        END AS implied_standard,\r\n    COALESCE(cl.quantity, (0)::numeric) AS on_hand_qty,\r\n        CASE\r\n            WHEN (p.standard_cost IS NOT NULL) THEN 'READY'::text\r\n            WHEN (cl.quantity > (0)::numeric) THEN 'NEEDS_DECISION'::text\r\n            ELSE 'NO_HISTORY'::text\r\n        END AS readiness,\r\n        CASE\r\n            WHEN (p.standard_cost IS NOT NULL) THEN 'معيار معتمد'::text\r\n            WHEN (cl.quantity > (0)::numeric) THEN 'لا يوجد معيار — رشح القيمة القائمة، أو أدخل ميزانية'::text\r\n            ELSE 'لا يوجد معيار ولا حركات — أدخل الميزانية يدوياً'::text\r\n        END AS note\r\n   FROM (products p\r\n     LEFT JOIN LATERAL ( SELECT sum(c.quantity) AS quantity,\r\n            sum(c.total_value) AS total_value\r\n           FROM item_cost_layers c\r\n          WHERE ((c.product_id = p.id) AND (c.owner_type = 'COMPANY'::owner_type))) cl ON (true))\r\n  WHERE (p.is_active AND (p.item_nature = 'GOOD'::item_nature) AND (p.inventory_policy = 'TRACKED'::inventory_policy) AND (p.item_class <> 'SERVICE'::item_class) AND (p.standard_cost IS NULL))","CREATE OR REPLACE VIEW public.stock_positions AS\r\n SELECT i.product_id AS item_id,\r\n    i.warehouse_id,\r\n    i.owner_type,\r\n    i.owner_id,\r\n    i.quantity,\r\n    p.item_nature,\r\n    COALESCE(ci.inventory_policy, p.inventory_policy) AS inventory_policy,\r\n    p.costing_method,\r\n    COALESCE(ci.default_cost, p.cost_price, (0)::numeric) AS reference_unit_cost,\r\n        CASE\r\n            WHEN ((i.owner_type = 'COMPANY'::owner_type) AND (COALESCE(ci.inventory_policy, p.inventory_policy) = 'TRACKED'::inventory_policy)) THEN round((i.quantity * COALESCE(ci.default_cost, p.cost_price, (0)::numeric)), 2)\r\n            ELSE (0)::numeric\r\n        END AS reference_valuation,\r\n    (i.owner_type = 'COMPANY'::owner_type) AS is_company_owned,\r\n    w.name AS warehouse_name,\r\n    w.name_ar AS warehouse_name_ar,\r\n    p.name AS item_name,\r\n    p.name_ar AS item_name_ar,\r\n    p.sku\r\n   FROM (((inventory i\r\n     JOIN products p ON ((p.id = i.product_id)))\r\n     JOIN warehouses w ON ((w.id = i.warehouse_id)))\r\n     LEFT JOIN company_items ci ON (((ci.item_id = p.id) AND (ci.company_id = 1) AND ci.is_active)))","CREATE OR REPLACE VIEW public.trial_balance AS\r\n WITH posted AS (\r\n         SELECT jl.account_id,\r\n            jl.debit,\r\n            jl.credit\r\n           FROM (journal_lines jl\r\n             JOIN journal_entries je ON ((je.id = jl.entry_id)))\r\n          WHERE (je.status = ANY (ARRAY['POSTED'::text, 'REVERSED'::text]))\r\n        )\r\n SELECT a.code,\r\n    a.name_ar,\r\n    a.account_type,\r\n    round(COALESCE(sum(p.debit), (0)::numeric), 2) AS total_debit,\r\n    round(COALESCE(sum(p.credit), (0)::numeric), 2) AS total_credit,\r\n    round(COALESCE(sum((p.debit - p.credit)), (0)::numeric), 2) AS balance,\r\n    round((COALESCE(sum((p.debit - p.credit)), (0)::numeric) * (\r\n        CASE\r\n            WHEN (a.account_type = ANY (ARRAY['ASSET'::account_type, 'EXPENSE'::account_type])) THEN 1\r\n            ELSE '-1'::integer\r\n        END)::numeric), 2) AS natural_balance\r\n   FROM (accounts a\r\n     LEFT JOIN posted p ON ((p.account_id = a.id)))\r\n  WHERE a.is_active\r\n  GROUP BY a.id, a.code, a.name_ar, a.account_type\r\n HAVING ((COALESCE(sum(p.debit), (0)::numeric) > (0)::numeric) OR (COALESCE(sum(p.credit), (0)::numeric) > (0)::numeric))","CREATE OR REPLACE VIEW public.company_stock_positions AS\r\n SELECT item_id,\r\n    warehouse_id,\r\n    owner_type,\r\n    owner_id,\r\n    quantity,\r\n    item_nature,\r\n    inventory_policy,\r\n    costing_method,\r\n    reference_unit_cost,\r\n    reference_valuation,\r\n    is_company_owned,\r\n    warehouse_name,\r\n    warehouse_name_ar,\r\n    item_name,\r\n    item_name_ar,\r\n    sku\r\n   FROM stock_positions\r\n  WHERE ((owner_type = 'COMPANY'::owner_type) AND (inventory_policy = 'TRACKED'::inventory_policy))","CREATE OR REPLACE VIEW public.customer_balance_reconciliation AS\r\n SELECT customer_id,\r\n    name,\r\n    ledger_balance,\r\n    legacy_balance,\r\n    difference\r\n   FROM customer_ledger_balances\r\n  WHERE (difference <> (0)::numeric)","CREATE OR REPLACE VIEW public.customer_owned_positions AS\r\n SELECT item_id,\r\n    warehouse_id,\r\n    owner_type,\r\n    owner_id,\r\n    quantity,\r\n    item_nature,\r\n    inventory_policy,\r\n    costing_method,\r\n    reference_unit_cost,\r\n    reference_valuation,\r\n    is_company_owned,\r\n    warehouse_name,\r\n    warehouse_name_ar,\r\n    item_name,\r\n    item_name_ar,\r\n    sku\r\n   FROM stock_positions\r\n  WHERE (owner_type <> 'COMPANY'::owner_type)","CREATE OR REPLACE VIEW public.inventory_valuation AS\r\n SELECT item_id,\r\n    item_name,\r\n    item_name_ar,\r\n    sku,\r\n    warehouse_id,\r\n    warehouse_name,\r\n    warehouse_name_ar,\r\n    quantity,\r\n    costing_method,\r\n    reference_unit_cost,\r\n    reference_valuation,\r\n    (costing_method <> 'STANDARD'::costing_method) AS valuation_is_reference_based\r\n   FROM company_stock_positions p\r\n  WHERE (quantity <> (0)::numeric)","CREATE OR REPLACE VIEW public.milling_inventory_report AS\r\n SELECT p.item_class,\r\n    p.id AS product_id,\r\n    p.sku,\r\n    p.name_ar,\r\n    COALESCE(i.warehouse_name_ar, '—'::text) AS warehouse,\r\n    COALESCE(i.qty, (0)::numeric) AS on_hand_qty,\r\n    COALESCE(u.name_ar, '—'::text) AS unit,\r\n    COALESCE(v.actual_unit_cost, (0)::numeric) AS unit_cost,\r\n    (COALESCE(i.qty, (0)::numeric) * COALESCE(v.actual_unit_cost, (0)::numeric)) AS valuation,\r\n    COALESCE(v.valuation_basis, 'REFERENCE_ONLY'::text) AS cost_basis\r\n   FROM (((products p\r\n     LEFT JOIN LATERAL ( SELECT sp.warehouse_name_ar,\r\n            sp.quantity AS qty\r\n           FROM stock_positions sp\r\n          WHERE ((sp.item_id = p.id) AND sp.is_company_owned AND (sp.quantity <> (0)::numeric))\r\n          ORDER BY sp.warehouse_name_ar) i ON (true))\r\n     LEFT JOIN units u ON ((u.id = p.base_uom_id)))\r\n     LEFT JOIN item_valuation v ON ((v.product_id = p.id)))\r\n  WHERE ((p.item_class = ANY (ARRAY['RAW_MATERIAL'::item_class, 'FINISHED_GOOD'::item_class, 'BY_PRODUCT'::item_class, 'NON_STOCK_ITEM'::item_class])) AND p.is_active AND ((COALESCE(i.qty, (0)::numeric) <> (0)::numeric) OR (COALESCE(v.on_hand_qty, (0)::numeric) <> (0)::numeric)))"}	reporting_views
13	{"-- ============================================================================\r\n-- 14_foreign_keys_and_grants.sql\r\n--\r\n-- الصلاحيات (GRANT/REVOKE) والتحقق النهائي.\r\n--\r\n-- مُستخرج من الحالة النهائية الحقيقية لقاعدة البيانات، لا من تاريخ الملفات.\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\n-- ── FOREIGN KEYS ───────────────────────────────────────────────────────\r\n-- Every reference, added after all tables exist. See the note in the\r\n-- domain files: the schema has mutual references across modules, so no\r\n-- table order lets all of these resolve in one pass.\r\n\r\nALTER TABLE public.accounts ADD CONSTRAINT \\"accounts_parent_id_fkey\\" FOREIGN KEY (parent_id) REFERENCES accounts(id) ON DELETE RESTRICT","ALTER TABLE public.ad_hoc_service_lines ADD CONSTRAINT \\"ad_hoc_service_lines_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.ad_hoc_service_lines ADD CONSTRAINT \\"ad_hoc_service_lines_invoice_id_fkey\\" FOREIGN KEY (invoice_id) REFERENCES sales_invoices(id) ON DELETE CASCADE","ALTER TABLE public.ad_hoc_service_lines ADD CONSTRAINT \\"ad_hoc_service_lines_invoice_item_id_fkey\\" FOREIGN KEY (invoice_item_id) REFERENCES sales_invoice_items(id) ON DELETE SET NULL","ALTER TABLE public.audit_logs ADD CONSTRAINT \\"audit_logs_actor_id_fkey\\" FOREIGN KEY (actor_id) REFERENCES auth.users(id)","ALTER TABLE public.backup_logs ADD CONSTRAINT \\"backup_logs_actor_id_fkey\\" FOREIGN KEY (actor_id) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.categories ADD CONSTRAINT \\"categories_parent_id_fkey\\" FOREIGN KEY (parent_id) REFERENCES categories(id) ON DELETE SET NULL","ALTER TABLE public.company_costing_settings ADD CONSTRAINT \\"company_costing_settings_updated_by_fkey\\" FOREIGN KEY (updated_by) REFERENCES auth.users(id)","ALTER TABLE public.company_items ADD CONSTRAINT \\"company_items_company_id_fkey\\" FOREIGN KEY (company_id) REFERENCES company_settings(id) ON DELETE CASCADE","ALTER TABLE public.company_items ADD CONSTRAINT \\"company_items_item_id_fkey\\" FOREIGN KEY (item_id) REFERENCES products(id) ON DELETE CASCADE","ALTER TABLE public.costing_policy_history ADD CONSTRAINT \\"costing_policy_history_changed_by_fkey\\" FOREIGN KEY (changed_by) REFERENCES auth.users(id)","ALTER TABLE public.customer_ledger ADD CONSTRAINT \\"customer_ledger_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.customer_ledger ADD CONSTRAINT \\"customer_ledger_customer_id_fkey\\" FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE","ALTER TABLE public.customer_payment_splits ADD CONSTRAINT \\"customer_payment_splits_customer_id_fkey\\" FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE","ALTER TABLE public.customer_payment_splits ADD CONSTRAINT \\"customer_payment_splits_invoice_id_fkey\\" FOREIGN KEY (invoice_id) REFERENCES sales_invoices(id) ON DELETE CASCADE","ALTER TABLE public.customer_payment_splits ADD CONSTRAINT \\"customer_payment_splits_payment_id_fkey\\" FOREIGN KEY (payment_id) REFERENCES customer_payments(id) ON DELETE CASCADE","ALTER TABLE public.customer_payments ADD CONSTRAINT \\"customer_payments_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.customer_payments ADD CONSTRAINT \\"customer_payments_customer_id_fkey\\" FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE","ALTER TABLE public.customer_payments ADD CONSTRAINT \\"customer_payments_invoice_id_fkey\\" FOREIGN KEY (invoice_id) REFERENCES sales_invoices(id) ON DELETE SET NULL","ALTER TABLE public.device_registrations ADD CONSTRAINT \\"device_registrations_assigned_warehouse_id_fkey\\" FOREIGN KEY (assigned_warehouse_id) REFERENCES warehouses(id) ON DELETE SET NULL","ALTER TABLE public.expense_approvals ADD CONSTRAINT \\"expense_approvals_actor_id_fkey\\" FOREIGN KEY (actor_id) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_approvals ADD CONSTRAINT \\"expense_approvals_entry_id_fkey\\" FOREIGN KEY (entry_id) REFERENCES expense_entries(id) ON DELETE CASCADE","ALTER TABLE public.expense_attachments ADD CONSTRAINT \\"expense_attachments_entry_id_fkey\\" FOREIGN KEY (entry_id) REFERENCES expense_entries(id) ON DELETE CASCADE","ALTER TABLE public.expense_attachments ADD CONSTRAINT \\"expense_attachments_line_id_fkey\\" FOREIGN KEY (line_id) REFERENCES expense_lines(id) ON DELETE CASCADE","ALTER TABLE public.expense_attachments ADD CONSTRAINT \\"expense_attachments_uploaded_by_fkey\\" FOREIGN KEY (uploaded_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_categories ADD CONSTRAINT \\"expense_categories_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","-- الحساب المحاسبي للتصنيف. ON DELETE SET NULL لا CASCADE: حذف حساب لا يجوز\r\n-- أن يحذف التصنيف — يُفرغ رابطه فقط، فيقع على الحساب الافتراضي.\r\nALTER TABLE public.expense_categories ADD CONSTRAINT \\"expense_categories_account_id_fkey\\" FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE SET NULL","ALTER TABLE public.expense_cost_centers ADD CONSTRAINT \\"expense_cost_centers_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_approved_by_fkey\\" FOREIGN KEY (approved_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_cancelled_by_fkey\\" FOREIGN KEY (cancelled_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_cost_center_id_fkey\\" FOREIGN KEY (cost_center_id) REFERENCES expense_cost_centers(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_employee_id_fkey\\" FOREIGN KEY (employee_id) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_posted_by_fkey\\" FOREIGN KEY (posted_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_project_id_fkey\\" FOREIGN KEY (project_id) REFERENCES expense_projects(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_rejected_by_fkey\\" FOREIGN KEY (rejected_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_reversal_of_fkey\\" FOREIGN KEY (reversal_of) REFERENCES expense_entries(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_reversed_by_id_fkey\\" FOREIGN KEY (reversed_by_id) REFERENCES expense_entries(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_submitted_by_fkey\\" FOREIGN KEY (submitted_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_supplier_id_fkey\\" FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL","ALTER TABLE public.expense_entries ADD CONSTRAINT \\"expense_entries_warehouse_id_fkey\\" FOREIGN KEY (warehouse_id) REFERENCES warehouses(id) ON DELETE SET NULL","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_category_id_fkey\\" FOREIGN KEY (category_id) REFERENCES expense_categories(id) ON DELETE SET NULL","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_cost_center_id_fkey\\" FOREIGN KEY (cost_center_id) REFERENCES expense_cost_centers(id) ON DELETE SET NULL","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_entry_id_fkey\\" FOREIGN KEY (entry_id) REFERENCES expense_entries(id) ON DELETE CASCADE","ALTER TABLE public.expense_lines ADD CONSTRAINT \\"expense_lines_project_id_fkey\\" FOREIGN KEY (project_id) REFERENCES expense_projects(id) ON DELETE SET NULL","ALTER TABLE public.expense_payments ADD CONSTRAINT \\"expense_payments_account_id_fkey\\" FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE SET NULL","ALTER TABLE public.expense_payments ADD CONSTRAINT \\"expense_payments_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expense_payments ADD CONSTRAINT \\"expense_payments_entry_id_fkey\\" FOREIGN KEY (entry_id) REFERENCES expense_entries(id) ON DELETE RESTRICT","ALTER TABLE public.expense_payments ADD CONSTRAINT \\"expense_payments_reversal_of_fkey\\" FOREIGN KEY (reversal_of) REFERENCES expense_payments(id) ON DELETE SET NULL","ALTER TABLE public.expense_payments ADD CONSTRAINT \\"expense_payments_reversed_by_fkey\\" FOREIGN KEY (reversed_by) REFERENCES expense_payments(id) ON DELETE SET NULL","ALTER TABLE public.expense_projects ADD CONSTRAINT \\"expense_projects_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.expenses ADD CONSTRAINT \\"expenses_category_id_fkey\\" FOREIGN KEY (category_id) REFERENCES expense_categories(id) ON DELETE SET NULL","ALTER TABLE public.expenses ADD CONSTRAINT \\"expenses_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.inventory ADD CONSTRAINT \\"inventory_product_id_fkey\\" FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE","ALTER TABLE public.inventory ADD CONSTRAINT \\"inventory_warehouse_id_fkey\\" FOREIGN KEY (warehouse_id) REFERENCES warehouses(id) ON DELETE CASCADE","ALTER TABLE public.item_cost_layers ADD CONSTRAINT \\"item_cost_layers_product_id_fkey\\" FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE","ALTER