ustody_ledger_milling_document_id_fkey\\" FOREIGN KEY (milling_document_id) REFERENCES milling_service_documents(id) ON DELETE RESTRICT","ALTER TABLE public.custody_ledger ADD CONSTRAINT \\"custody_ledger_service_invoice_id_fkey\\" FOREIGN KEY (service_invoice_id) REFERENCES sales_invoices(id) ON DELETE SET NULL","ALTER TABLE public.custody_ledger ADD CONSTRAINT \\"custody_ledger_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.milling_service_documents ADD CONSTRAINT \\"milling_service_documents_customer_id_fkey\\" FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT","ALTER TABLE public.milling_service_documents ADD CONSTRAINT \\"milling_service_documents_warehouse_id_fkey\\" FOREIGN KEY (warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT","ALTER TABLE public.milling_service_documents ADD CONSTRAINT \\"milling_service_documents_sales_invoice_id_fkey\\" FOREIGN KEY (sales_invoice_id) REFERENCES sales_invoices(id) ON DELETE RESTRICT","ALTER TABLE public.milling_service_documents ADD CONSTRAINT \\"milling_service_documents_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL","ALTER TABLE public.custody_ledger ENABLE ROW LEVEL SECURITY","ALTER TABLE public.milling_service_documents ENABLE ROW LEVEL SECURITY","GRANT REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.custody_ledger TO anon","GRANT REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.custody_ledger TO authenticated","GRANT DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON public.custody_ledger TO service_role","GRANT REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.milling_service_documents TO anon","GRANT REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.milling_service_documents TO authenticated","GRANT DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON public.milling_service_documents TO service_role","GRANT SELECT ON public.custody_customer_statement TO anon","GRANT SELECT ON public.custody_customer_statement TO authenticated","GRANT SELECT ON public.custody_customer_statement TO service_role","GRANT SELECT ON public.custody_service_money TO anon","GRANT SELECT ON public.custody_service_money TO authenticated","GRANT SELECT ON public.custody_service_money TO service_role","GRANT SELECT ON public.custody_detected_loss TO anon","GRANT SELECT ON public.custody_detected_loss TO authenticated","GRANT SELECT ON public.custody_detected_loss TO service_role"}	foreign_keys_and_grants
14	{"-- ============================================================================\r\n-- 14_document_numbering_engine.sql — محرّك ترقيم المستندات المركزي\r\n-- ============================================================================\r\n--\r\n-- ما هذا الملف؟\r\n--   محرّك واحد يُنتج أرقام كل المستندات في النظام: فواتير، مرتجعات، أوامر،\r\n--   سندات قبض وصرف، قيود يومية، سندات طحن. قبل هذا الملف كان كل نوع\r\n--   مستند يولّد رقمه بنفسه، فتكرار المنطق في ست دوال، واختلاف السلوك بينها.\r\n--\r\n--   يتكوّن من ثلاث طبقات:\r\n--     1. الإعداد   : document_numbering — صف لكل نوع مستند\r\n--     2. التخصيص  : fn_next_document_number — رقم ذرّي بلا تكرار\r\n--     3. التنسيق   : fn_format_document_number — الصيغة المعروضة\r\n--\r\n-- ── الضمانات ────────────────────────────────────────────────────────────────\r\n--   * ذرّي (Atomic): التخصيص عبر تسلسلات Postgres، فلا MAX+1 ولا تكرار تحت\r\n--     الطلبات المتزامنة.\r\n--   * العدّاد منفصل عن المعروض: البادئة والتاريخ والحشو عرضٌ محض، لا يُعيد\r\n--     تصفير العدّاد.\r\n--   * الأرقام مجمّدة: الرقم يُخزَّن نصًا على صف المستند عند إنشائه، فتغيير\r\n--     الصيغة لا يُعيد كتابة مستند صادر.\r\n--\r\n-- ── التوافق الرجعي ──────────────────────────────────────────────────────────\r\n--   الدوال القديمة (next_invoice_number, next_purchase_number,\r\n--   next_sales_return_number, next_purchase_return_number, next_transfer_number)\r\n--   تبقى **بتوقيعاتها نفسها** معاد تنفيذها فوق المحرّك، فلا ينكسر أي مستدعٍ.\r\n--\r\n-- ── ما ليس في هذا الملف ────────────────────────────────────────────────────\r\n--   صفوف الإعداد الـ 17 (نوع => بادئة وصيغة) **بيانات لا بنية**، فمكانها\r\n--   البذرة: supabase/seeds/01_system/07_document_numbering.sql\r\n--   راجع supabase/MIGRATIONS_RULES.md — القاعدة 1.\r\n--\r\n-- ⚠️ المصدر: origin/main — 20261210000000_central_document_numbering_engine.sql\r\n--    عُدِّل عند الدمج: نُقلت صفوف الإعداد إلى بذرة، وأُزيل تعريف الدوال التي\r\n--    عندنا نسخة أحدث منها، وصُحِّح ترميز النصوص.\r\n-- ============================================================================\r\n-- ---------------------------------------------------------------------------\r\n-- 0. Helper: mapping from a document type to a PostgreSQL sequence.\r\n--    Sequences cannot be created dynamically inside a STABLE formatter for\r\n--    every call cheaply, so the mapping is an IMMUTABLE function and the\r\n--    sequences themselves are created once below.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.fn_document_numbering_sequence_name(p_document_type text)\r\nRETURNS text\r\nLANGUAGE sql\r\nIMMUTABLE\r\nSET search_path = public\r\nAS $$\r\n  SELECT CASE p_document_type\r\n    WHEN 'sales_invoice'      THEN 'public.sales_invoice_seq'\r\n    WHEN 'purchase_invoice'   THEN 'public.purchase_invoice_seq'\r\n    WHEN 'sales_return'       THEN 'public.sales_return_seq'\r\n    WHEN 'purchase_return'    THEN 'public.purchase_return_seq'\r\n    WHEN 'stock_transfer'     THEN 'public.stock_transfer_seq'\r\n    WHEN 'expense'            THEN 'public.expense_reference_seq'\r\n    WHEN 'quotation'          THEN 'public.quotation_seq'\r\n    WHEN 'purchase_order'     THEN 'public.purchase_order_seq'\r\n    WHEN 'goods_receipt'      THEN 'public.goods_receipt_seq'\r\n    WHEN 'sales_order'        THEN 'public.sales_order_seq'\r\n    WHEN 'customer_payment'   THEN 'public.customer_payment_seq'\r\n    WHEN 'supplier_payment'   THEN 'public.supplier_payment_seq'\r\n    WHEN 'stock_adjustment'   THEN 'public.stock_adjustment_seq'\r\n    WHEN 'milling_intake'     THEN 'public.milling_intake_seq'\r\n    WHEN 'milling_service'    THEN 'public.milling_service_seq'\r\n    WHEN 'journal_entry'      THEN 'public.journal_entry_seq'\r\n    ELSE NULL\r\n  END;\r\n$$","-- ---------------------------------------------------------------------------\r\n-- 1. Sequences backing each document type.\r\n--    Legacy sequences already exist (IF NOT EXISTS keeps their current value,\r\n--    so counters are preserved -- no renumbering of historical data).\r\n-- ---------------------------------------------------------------------------\r\nCREATE SEQUENCE IF NOT EXISTS public.quotation_seq           START 1","CREATE SEQUENCE IF NOT EXISTS public.purchase_order_seq      START 1","CREATE SEQUENCE IF NOT EXISTS public.goods_receipt_seq       START 1","CREATE SEQUENCE IF NOT EXISTS public.sales_order_seq         START 1","CREATE SEQUENCE IF NOT EXISTS public.customer_payment_seq    START 1","CREATE SEQUENCE IF NOT EXISTS public.supplier_payment_seq    START 1","CREATE SEQUENCE IF NOT EXISTS public.stock_adjustment_seq    START 1","CREATE SEQUENCE IF NOT EXISTS public.milling_intake_seq      START 1","CREATE SEQUENCE IF NOT EXISTS public.milling_service_seq     START 1","CREATE SEQUENCE IF NOT EXISTS public.journal_entry_seq       START 1","-- ---------------------------------------------------------------------------\r\n-- 2. The configuration table: one row per document type.\r\n-- ---------------------------------------------------------------------------\r\nCREATE TABLE IF NOT EXISTS public.document_numbering (\r\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  document_type   text NOT NULL,\r\n  scope           text NOT NULL DEFAULT 'global',\r\n  scope_id        uuid,\r\n  section         text NOT NULL DEFAULT 'general',\r\n  label_ar        text NOT NULL DEFAULT '',\r\n  label_en        text NOT NULL DEFAULT '',\r\n  prefix          text NOT NULL DEFAULT '',\r\n  separator       text NOT NULL DEFAULT '-',\r\n  format_tokens   text NOT NULL DEFAULT '{PREFIX}-{SEQ}',\r\n  padding         smallint NOT NULL DEFAULT 0,\r\n  date_part       text NOT NULL DEFAULT 'none',\r\n  reset_policy    text NOT NULL DEFAULT 'never',\r\n  current_value   bigint NOT NULL DEFAULT 0,\r\n  is_active       boolean NOT NULL DEFAULT true,\r\n  created_at      timestamptz NOT NULL DEFAULT now(),\r\n  updated_at      timestamptz NOT NULL DEFAULT now(),\r\n  CONSTRAINT document_numbering_padding_check  CHECK (padding BETWEEN 0 AND 8),\r\n  CONSTRAINT document_numbering_date_check\r\n    CHECK (date_part IN ('none', 'year', 'year_month', 'full')),\r\n  CONSTRAINT document_numbering_reset_check\r\n    CHECK (reset_policy IN ('never', 'yearly', 'monthly', 'daily')),\r\n  CONSTRAINT document_numbering_scope_check\r\n    CHECK (scope IN ('global', 'company', 'branch', 'pos'))\r\n)","-- ---------------------------------------------------------------------------\r\n-- التفرد: (document_type, scope, scope_id)\r\n--\r\n-- ⚠️ لا يصلح لهذا الغرض قيد UNIQUE عادي، لأن scope_id يساوي NULL في النطاق\r\n--    'global' — وفي SQL فإن NULL ≠ NULL. فالمفتاح المكوَّن بـ NULL لا يتعارض\r\n--    أبدًا، ويقبل صفوفًا مكررة بلا حدّ.\r\n--\r\n--    الأثر كان ملموسًا: تشغيل بذرة الترقيم مرتين ضاعف الصفوف من 17 إلى 34،\r\n--    لأن ON CONFLICT لم يجد ما يعارضه. وهو خلل صامت: لا خطأ، فقط إعداد\r\n--    مكرر يقرأ المحرّك أحد صفوفه بلا تحديد أيّها.\r\n--\r\n--    والحل ليس فهرسًا جزئيًا (WHERE scope_id IS NULL): فصيغة\r\n--    `ON CONFLICT (col, col, col)` تطلب فهرسًا مطابقًا لِما كُتب، والفهرس\r\n--    الجزئي لا يُطابقها فيعطي «no unique or exclusion constraint matching\r\n--    the ON CONFLICT specification». فالبديل المعياري: تطبيع NULL إلى قيمة\r\n--    ثابتة في تعبير الفهرس، فيصير للمفتاح قيمة أبدًا لا NULL.\r\n--\r\n--    ونتيجةً لذلك يُكتب ON CONFLICT في البذور على التعبير نفسه:\r\n--      ON CONFLICT (document_type, scope, (coalesce(scope_id, '000...0')))\r\n-- ---------------------------------------------------------------------------\r\nCREATE UNIQUE INDEX IF NOT EXISTS document_numbering_scope_unique\r\n  ON public.document_numbering (document_type, scope, (coalesce(scope_id, '00000000-0000-0000-0000-000000000000'::uuid)))","COMMENT ON TABLE public.document_numbering IS\r\n  'Central Document Numbering Engine configuration. The numeric sequence is '\r\n  'kept in a PostgreSQL sequence (atomic, gap tolerant); this table stores how '\r\n  'that number is presented. Document numbers are frozen on the document row '\r\n  'when it is created, so editing this table never rewrites history.'","CREATE INDEX IF NOT EXISTS document_numbering_document_type_idx\r\n  ON public.document_numbering (document_type, scope)","ALTER TABLE public.document_numbering ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS \\"document_numbering_read\\" ON public.document_numbering","CREATE POLICY \\"document_numbering_read\\" ON public.document_numbering\r\n  FOR SELECT TO authenticated USING (true)","DROP POLICY IF EXISTS \\"document_numbering_write\\" ON public.document_numbering","CREATE POLICY \\"document_numbering_write\\" ON public.document_numbering\r\n  FOR ALL TO authenticated\r\n  USING (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager'))\r\n  WITH CHECK (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager'))","GRANT SELECT, INSERT, UPDATE, DELETE ON public.document_numbering TO authenticated","GRANT ALL ON public.document_numbering TO service_role","-- 4. The FORMATTER: turns (tokens, prefix, date, separator, padding) + a raw\r\n--    sequence number into the displayed document number.\r\n--    Tokens: {PREFIX} {SEQ} {YYYY} {YY} {MM} {DD}\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.fn_format_document_number(\r\n  p_sequence     bigint,\r\n  p_prefix       text,\r\n  p_format       text,\r\n  p_padding      smallint,\r\n  p_separator    text,\r\n  p_date_part    text,\r\n  p_at           timestamptz DEFAULT now()\r\n)\r\nRETURNS text\r\nLANGUAGE plpgsql\r\nIMMUTABLE\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_seq_text   text;\r\n  v_padding    smallint := GREATEST(0, LEAST(COALESCE(p_padding, 0), 8));\r\n  v_sep        text := COALESCE(NULLIF(p_separator, ''), '-');\r\n  v_prefix     text := COALESCE(p_prefix, '');\r\n  v_format     text := COALESCE(NULLIF(btrim(p_format), ''), '{PREFIX}{SEQ}');\r\n  v_result     text;\r\nBEGIN\r\n  -- Padding is OPTIONAL. padding = 0 means \\"no leading zeros\\".\r\n  v_seq_text := CASE\r\n    WHEN v_padding = 0 THEN p_sequence::text\r\n    WHEN length(p_sequence::text) < v_padding THEN lpad(p_sequence::text, v_padding, '0')\r\n    ELSE p_sequence::text\r\n  END;\r\n\r\n  v_result := v_format;\r\n  v_result := replace(v_result, '{PREFIX}',    v_prefix);\r\n  v_result := replace(v_result, '{YYYY}',      to_char(p_at, 'YYYY'));\r\n  v_result := replace(v_result, '{YY}',        to_char(p_at, 'YY'));\r\n  v_result := replace(v_result, '{MM}',        to_char(p_at, 'MM'));\r\n  v_result := replace(v_result, '{DD}',        to_char(p_at, 'DD'));\r\n  v_result := replace(v_result, '{SEQ}',       v_seq_text);\r\n\r\n  -- A separator written as \\"-\\" inside the template is normalised so an empty\r\n  -- separator really collapses the parts instead of leaving stray dashes.\r\n  IF v_sep <> '-' THEN\r\n    v_result := replace(v_result, '-', v_sep);\r\n  END IF;\r\n\r\n  -- If the template mentions a date token that is empty (e.g. a preset with\r\n  -- no date), collapse duplicated separators and trim stray edges.\r\n  WHILE position(v_sep || v_sep IN v_result) > 0 LOOP\r\n    v_result := replace(v_result, v_sep || v_sep, v_sep);\r\n  END LOOP;\r\n  v_result := btrim(v_result, v_sep || ' ');\r\n  v_result := btrim(v_result);\r\n\r\n  IF v_result = '' THEN\r\n    v_result := v_seq_text;\r\n  END IF;\r\n\r\n  RETURN v_result;\r\nEND $$","-- Backwards/report-friendly wrapper that resolves the config row itself.\r\nCREATE OR REPLACE FUNCTION public.fn_format_document_number(\r\n  p_document_type text,\r\n  p_sequence      bigint,\r\n  p_at            timestamptz DEFAULT now()\r\n)\r\nRETURNS text\r\nLANGUAGE plpgsql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  r record;\r\nBEGIN\r\n  SELECT * INTO r FROM public.fn_resolve_document_numbering(p_document_type);\r\n  IF NOT FOUND THEN\r\n    RETURN p_sequence::text;\r\n  END IF;\r\n  RETURN public.fn_format_document_number(\r\n    p_sequence, r.prefix, r.format_tokens, r.padding, r.separator, r.date_part, p_at\r\n  );\r\nEND $$","-- ---------------------------------------------------------------------------\r\n-- 5. Scope resolution with explicit priority:\r\n--       pos + type  ->  branch + type  ->  company + type  ->  global + type\r\n--    Only 'global' rows are seeded today; the ordering is ready for the\r\n--    higher scopes without any further schema change.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.fn_resolve_document_numbering(\r\n  p_document_type text,\r\n  p_company_id    uuid DEFAULT NULL,\r\n  p_branch_id     uuid DEFAULT NULL,\r\n  p_pos_id        uuid DEFAULT NULL\r\n)\r\nRETURNS public.document_numbering\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT d.*\r\n  FROM public.document_numbering d\r\n  WHERE d.document_type = p_document_type\r\n    AND (\r\n      (d.scope = 'pos'     AND p_pos_id     IS NOT NULL AND d.scope_id = p_pos_id)\r\n      OR (d.scope = 'branch'  AND p_branch_id  IS NOT NULL AND d.scope_id = p_branch_id)\r\n      OR (d.scope = 'company' AND p_company_id IS NOT NULL AND d.scope_id = p_company_id)\r\n      OR (d.scope = 'global'  AND d.scope_id IS NULL)\r\n    )\r\n  ORDER BY CASE d.scope\r\n             WHEN 'pos'     THEN 1\r\n             WHEN 'branch'  THEN 2\r\n             WHEN 'company' THEN 3\r\n             ELSE 4\r\n           END\r\n  LIMIT 1;\r\n$$","-- ---------------------------------------------------------------------------\r\n-- 6. ATOMIC ALLOCATION -- the heart of the engine.\r\n--    Uses nextval() which is atomic under concurrency, so two simultaneous\r\n--    requests can never receive the same number. No MAX()+1, no frontend math.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.fn_next_document_number(\r\n  p_document_type text,\r\n  p_company_id    uuid DEFAULT NULL,\r\n  p_branch_id     uuid DEFAULT NULL,\r\n  p_pos_id        uuid DEFAULT NULL,\r\n  p_at            timestamptz DEFAULT now()\r\n)\r\nRETURNS text\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_seq_name text := public.fn_document_numbering_sequence_name(p_document_type);\r\n  v_cfg      record;\r\n  v_number   bigint;\r\n  v_result   text;\r\nBEGIN\r\n  IF v_seq_name IS NULL THEN\r\n    RAISE EXCEPTION 'Unknown document type: %', p_document_type;\r\n  END IF;\r\n\r\n  SELECT * INTO v_cfg\r\n  FROM public.fn_resolve_document_numbering(p_document_type, p_company_id, p_branch_id, p_pos_id);\r\n\r\n  -- Atomic allocation. The sequence guarantees uniqueness even when two\r\n  -- cashiers create the same document type in the same millisecond.\r\n  EXECUTE format('SELECT nextval(%L)', v_seq_name) INTO v_number;\r\n\r\n  IF v_cfg IS NULL THEN\r\n    -- Engine row missing: still return a safe, unique number.\r\n    RETURN v_number::text;\r\n  END IF;\r\n\r\n  v_result := public.fn_format_document_number(\r\n    v_number, v_cfg.prefix, v_cfg.format_tokens, v_cfg.padding,\r\n    v_cfg.separator, v_cfg.date_part, p_at\r\n  );\r\n\r\n  -- Keep the informational counter in sync (never used for allocation).\r\n  UPDATE public.document_numbering\r\n    SET current_value = GREATEST(current_value, v_number),\r\n        updated_at = now()\r\n    WHERE id = v_cfg.id;\r\n\r\n  RETURN v_result;\r\nEND $$","-- ---------------------------------------------------------------------------\r\n-- 7. Admin control: read + safe write of a document type's configuration and\r\n--    its \\"next number\\" starting point.\r\n--    Guards:\r\n--      - owner/manager only\r\n--      - refuses a starting value that collides with an existing document\r\n--      - logs the change when the project has an audit trail\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.fn_set_document_numbering(\r\n  p_document_type text,\r\n  p_prefix        text DEFAULT NULL,\r\n  p_format_tokens text DEFAULT NULL,\r\n  p_padding       smallint DEFAULT NULL,\r\n  p_date_part     text DEFAULT NULL,\r\n  p_separator     text DEFAULT NULL,\r\n  p_reset_policy  text DEFAULT NULL,\r\n  p_next_value    bigint DEFAULT NULL\r\n)\r\nRETURNS public.document_numbering\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_uid     uuid := auth.uid();\r\n  v_seq     text := public.fn_document_numbering_sequence_name(p_document_type);\r\n  v_row     public.document_numbering;\r\n  v_max     bigint := 0;\r\n  v_is_called boolean;\r\n  v_expected bigint;\r\nBEGIN\r\n  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;\r\n  IF NOT (public.has_role(v_uid, 'owner') OR public.has_role(v_uid, 'manager')) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF v_seq IS NULL THEN\r\n    RAISE EXCEPTION 'Unknown document type: %', p_document_type;\r\n  END IF;\r\n\r\n  SELECT * INTO v_row\r\n  FROM public.document_numbering\r\n  WHERE document_type = p_document_type AND scope = 'global'\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'No numbering configuration for %', p_document_type;\r\n  END IF;\r\n\r\n  -- ── Guard: never allow a starting value that would duplicate a number that\r\n  --    has already been issued for this document type.\r\n  IF p_next_value IS NOT NULL THEN\r\n    IF p_next_value < 0 THEN\r\n      RAISE EXCEPTION 'Starting number cannot be negative';\r\n    END IF;\r\n\r\n    -- Highest number actually visible in the documents, parsed from the tail\r\n    -- of the stored text (\\"INV-202610-0125\\" -> 125).\r\n    v_max := CASE p_document_type\r\n      WHEN 'sales_invoice'    THEN (SELECT COALESCE(MAX(NULLIF(regexp_replace(invoice_number, '\\\\D', '', 'g'), '')::bigint), 0) FROM public.sales_invoices)\r\n      WHEN 'purchase_invoice' THEN (SELECT COALESCE(MAX(NULLIF(regexp_replace(invoice_number, '\\\\D', '', 'g'), '')::bigint), 0) FROM public.purchase_invoices)\r\n      WHEN 'sales_return'     THEN (SELECT COALESCE(MAX(NULLIF(regexp_replace(return_number, '\\\\D', '', 'g'), '')::bigint), 0) FROM public.sales_returns)\r\n      WHEN 'purchase_return'  THEN (SELECT COALESCE(MAX(NULLIF(regexp_replace(return_number, '\\\\D', '', 'g'), '')::bigint), 0) FROM public.purchase_returns)\r\n      WHEN 'stock_transfer'   THEN (SELECT COALESCE(MAX(NULLIF(regexp_replace(transfer_number, '\\\\D', '', 'g'), '')::bigint), 0) FROM public.stock_transfers)\r\n      ELSE 0\r\n    END;\r\n\r\n    IF p_next_value <= v_max THEN\r\n      RAISE EXCEPTION\r\n        'Starting number % is not greater than an existing number (%). Choose a value above %.',\r\n        p_next_value, v_max, v_max;\r\n    END IF;\r\n\r\n    SELECT is_called, last_value INTO v_is_called, v_expected\r\n      FROM public.document_numbering WHERE id = v_row.id; -- placeholder, replaced below\r\n\r\n    -- is_called is read from the real sequence.\r\n    EXECUTE format('SELECT is_called, last_value FROM %s', v_seq) INTO v_is_called, v_expected;\r\n\r\n    -- setval(seq, n, false) -> the NEXT nextval() returns exactly n.\r\n    EXECUTE format('SELECT setval(%L, %s, false)', v_seq, p_next_value);\r\n  END IF;\r\n\r\n  UPDATE public.document_numbering SET\r\n    prefix        = COALESCE(p_prefix,        prefix),\r\n    format_tokens = COALESCE(p_format_tokens, format_tokens),\r\n    padding       = COALESCE(p_padding,       padding),\r\n    date_part     = COALESCE(p_date_part,     date_part),\r\n    separator     = COALESCE(p_separator,     separator),\r\n    reset_policy  = COALESCE(p_reset_policy,  reset_policy),\r\n    current_value = CASE\r\n                      WHEN p_next_value IS NOT NULL THEN p_next_value - 1\r\n                      ELSE current_value\r\n                    END,\r\n    updated_at    = now()\r\n  WHERE id = v_row.id\r\n  RETURNING * INTO v_row;\r\n\r\n  -- Audit trail (best effort: projects without the log table stay silent).\r\n  BEGIN\r\n    INSERT INTO public.backup_logs (log_type, status, message, details)\r\n    VALUES (\r\n      'settings',\r\n      'success',\r\n      'Document numbering updated: ' || p_document_type,\r\n      jsonb_build_object(\r\n        'document_type', p_document_type,\r\n        'next_value',    p_next_value,\r\n        'prefix',        v_row.prefix,\r\n        'format_tokens', v_row.format_tokens,\r\n        'padding',       v_row.padding,\r\n        'date_part',     v_row.date_part,\r\n        'actor',         v_uid\r\n      )\r\n    );\r\n  EXCEPTION WHEN undefined_table OR undefined_column THEN\r\n    NULL;\r\n  END;\r\n\r\n  RETURN v_row;\r\nEND $$","-- ---------------------------------------------------------------------------\r\n-- 8. Legacy functions, re-implemented on the engine.\r\n--    Signatures are unchanged so no caller breaks.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.next_invoice_number()\r\nRETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  RETURN public.fn_next_document_number('sales_invoice');\r\nEND $$","CREATE OR REPLACE FUNCTION public.next_purchase_number()\r\nRETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  RETURN public.fn_next_document_number('purchase_invoice');\r\nEND $$","CREATE OR REPLACE FUNCTION public.next_sales_return_number()\r\nRETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  RETURN public.fn_next_document_number('sales_return');\r\nEND $$","CREATE OR REPLACE FUNCTION public.next_purchase_return_number()\r\nRETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  RETURN public.fn_next_document_number('purchase_return');\r\nEND $$","CREATE OR REPLACE FUNCTION public.next_transfer_number()\r\nRETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  RETURN public.fn_next_document_number('stock_transfer');\r\nEND $$","-- ── Grants that used to live in 13 ──────────────────────────────────────────\r\n-- Moved here because these five functions are DEFINED here: 13 runs before this\r\n-- file, so a GRANT there would fail with \\"function does not exist\\".\r\nGRANT EXECUTE ON FUNCTION public.next_invoice_number()          TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.next_purchase_number()         TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.next_sales_return_number()     TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.next_purchase_return_number()  TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.next_transfer_number()         TO authenticated, service_role","-- ---------------------------------------------------------------------------\r\n-- 9. Grants. Sequence access is never exposed to the browser; allocation goes\r\n--    through the SECURITY DEFINER functions only.\r\n-- ---------------------------------------------------------------------------\r\nREVOKE ALL ON SEQUENCE public.quotation_seq        FROM PUBLIC, anon, authenticated","REVOKE ALL ON SEQUENCE public.purchase_order_seq   FROM PUBLIC, anon, authenticated","REVOKE ALL ON SEQUENCE public.goods_receipt_seq    FROM PUBLIC, anon, authenticated","REVOKE ALL ON SEQUENCE public.sales_order_seq      FROM PUBLIC, anon, authenticated","REVOKE ALL ON SEQUENCE public.customer_payment_seq FROM PUBLIC, anon, authenticated","REVOKE ALL ON SEQUENCE public.supplier_payment_seq FROM PUBLIC, anon, authenticated","REVOKE ALL ON SEQUENCE public.stock_adjustment_seq FROM PUBLIC, anon, authenticated","REVOKE ALL ON SEQUENCE public.milling_intake_seq   FROM PUBLIC, anon, authenticated","REVOKE ALL ON SEQUENCE public.milling_service_seq  FROM PUBLIC, anon, authenticated","REVOKE ALL ON SEQUENCE public.journal_entry_seq    FROM PUBLIC, anon, authenticated","GRANT USAGE ON SEQUENCE public.quotation_seq        TO service_role","GRANT USAGE ON SEQUENCE public.purchase_order_seq   TO service_role","GRANT USAGE ON SEQUENCE public.goods_receipt_seq    TO service_role","GRANT USAGE ON SEQUENCE public.customer_payment_seq TO service_role","GRANT USAGE ON SEQUENCE public.sales_order_seq      TO service_role","GRANT USAGE ON SEQUENCE public.supplier_payment_seq TO service_role","GRANT USAGE ON SEQUENCE public.stock_adjustment_seq TO service_role","GRANT USAGE ON SEQUENCE public.milling_intake_seq   TO service_role","GRANT USAGE ON SEQUENCE public.milling_service_seq  TO service_role","GRANT USAGE ON SEQUENCE public.journal_entry_seq    TO service_role","-- Allocation is internal: called from SECURITY DEFINER document RPCs only.\r\nREVOKE EXECUTE ON FUNCTION public.fn_next_document_number(text, uuid, uuid, uuid, timestamptz) FROM PUBLIC, anon, authenticated","REVOKE EXECUTE ON FUNCTION public.fn_format_document_number(bigint, text, text, smallint, text, text, timestamptz) FROM PUBLIC, anon","REVOKE EXECUTE ON FUNCTION public.fn_resolve_document_numbering(text, uuid, uuid, uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.fn_next_document_number(text, uuid, uuid, uuid, timestamptz) TO service_role","-- Safe, read-only helpers for the UI + the admin setter.\r\nGRANT EXECUTE ON FUNCTION public.fn_format_document_number(text, bigint, timestamptz) TO authenticated","GRANT EXECUTE ON FUNCTION public.fn_document_numbering_sequence_name(text) TO authenticated","GRANT EXECUTE ON FUNCTION public.fn_set_document_numbering(text, text, text, smallint, text, text, text, bigint) TO authenticated","GRANT EXECUTE ON FUNCTION public.fn_resolve_document_numbering(text, uuid, uuid, uuid) TO authenticated","REVOKE EXECUTE ON FUNCTION public.fn_set_document_numbering(text, text, text, smallint, text, text, text, bigint) FROM PUBLIC, anon"}	document_numbering_engine
15	{"-- ============================================================================\r\n-- 15_freeze_document_numbers.sql — تجميد أرقام المستندات\r\n-- ============================================================================\r\n--\r\n-- ما هذا الملف؟\r\n--   يضيف عمود `document_number` إلى كل جدول مستند مرقَّم. وهو عمود **مُولَّد**\r\n--   (GENERATED ALWAYS ... STORED) يعكس العمود الأصلي في الجدول:\r\n--\r\n--     sales_invoices     → يعكس invoice_number\r\n--     purchase_invoices  → يعكس invoice_number\r\n--     sales_returns      → يعكس return_number\r\n--     purchase_returns   → يعكس return_number\r\n--     stock_transfers    → يعكس transfer_number\r\n--\r\n-- ── لماذا عمود مُولَّد لا عادي؟ ──────────────────────────────────────────────\r\n--   العمود المُولَّد **لا يمكن الكتابة عليه**: أي محاولة UPDATE أو INSERT عليه\r\n--   ترمي خطأ من PostgreSQL نفسه. هذا هو التجميد: لا كود — ولا خطأ برمجي — يمكنه\r\n--   أن يُعيد كتابة رقم صادر، لأن القاعدة ترفضه قبل أن يفكّر فيه أي مُشغّل أو دالة.\r\n--\r\n--   والبديل (عمود عادي + trigger يمنع التغيير) أضعف: يعتمد على أن المُشغّل\r\n--   مثبَّت ولم يُعطَّل، ويسمح بالتعديل إن أُلغيت سياسة بلا قصد.\r\n--\r\n-- ── لماذا اسم موحّد؟ ────────────────────────────────────────────────────────\r\n--   كل جدول كان يسمّي عموده بشكل مختلف (`invoice_number`, `return_number`,\r\n--   `transfer_number`). فيمنح هذا العمود قراءةً واحدة لكل أنواع المستندات:\r\n--\r\n--     SELECT document_number FROM sales_invoices UNION ...\r\n--\r\n--   والأعمدة الأصلية تبقى كما هي، فلا ينكسر أي كود يقرأها. فهذا إضافة لا إحلال.\r\n--\r\n-- ── ما ليس في هذا الملف ─────────────────────────────────────────────────────\r\n--   مزامنة عدّاد `current_value` من التسلسلات: مكانها بذرة الترقيم\r\n--   `07_document_numbering.sql`، لأنها بيانات لا بنية. كان المصدر يضعها هنا،\r\n--   فتُنفَّذ في الترحيل وتُكرَّر في البذرة — والتكرار مرفوض (القاعدة R-1).\r\n--\r\n-- ⚠️ المصدر: origin/main — 20261210000100_freeze_document_numbers.sql\r\n--    عُدِّل عند الدمج: حُذف قسم مزامنة العدّاد لتكراره مع البذرة 07.\r\n-- ============================================================================\r\n\r\n-- ── العمود الموحّد ──────────────────────────────────────────────────────────\r\n-- IF NOT EXISTS يجعل الملف آمنًا لو طُبِّق مرتين.\r\nALTER TABLE public.sales_invoices\r\n  ADD COLUMN IF NOT EXISTS document_number text GENERATED ALWAYS AS (invoice_number) STORED","ALTER TABLE public.purchase_invoices\r\n  ADD COLUMN IF NOT EXISTS document_number text GENERATED ALWAYS AS (invoice_number) STORED","ALTER TABLE public.sales_returns\r\n  ADD COLUMN IF NOT EXISTS document_number text GENERATED ALWAYS AS (return_number) STORED","ALTER TABLE public.purchase_returns\r\n  ADD COLUMN IF NOT EXISTS document_number text GENERATED ALWAYS AS (return_number) STORED","ALTER TABLE public.stock_transfers\r\n  ADD COLUMN IF NOT EXISTS document_number text GENERATED ALWAYS AS (transfer_number) STORED","-- ── التحقق الذاتي ───────────────────────────────────────────────────────────\r\n-- نتحقق أن العمود مُولَّد فعلاً، لا مجرد موجود. لو أُنشئ عمودًا عاديًا (باسم\r\n-- مشابه) لظنّ الكود أن الأرقام محميّة وهي ليست كذلك — وهو أسوأ من عدم وجوده،\r\n-- لأنه يعطي طمأنينة كاذبة.\r\nDO $$\r\nDECLARE\r\n  v_tbl    text;\r\n  v_tables text[] := ARRAY['sales_invoices', 'purchase_invoices', 'sales_returns',\r\n                           'purchase_returns', 'stock_transfers'];\r\n  v_bad    text[] := ARRAY[]::text[];\r\nBEGIN\r\n  FOREACH v_tbl IN ARRAY v_tables LOOP\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM information_schema.columns\r\n      WHERE table_schema = 'public'\r\n        AND table_name = v_tbl\r\n        AND column_name = 'document_number'\r\n        AND is_generated = 'ALWAYS'\r\n    ) THEN\r\n      v_bad := v_bad || v_tbl;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF array_length(v_bad, 1) > 0 THEN\r\n    RAISE EXCEPTION\r\n      'عمود document_number ليس مُولَّدًا في: % — الأرقام ليست محميّة من التعديل',\r\n      array_to_string(v_bad, ', ');\r\n  END IF;\r\nEND $$"}	freeze_document_numbers
16	{"-- ============================================================================\r\n-- 16_payment_methods.sql — طرق الدفع الموحّدة\r\n-- ============================================================================\r\n--\r\n-- ما هذا الملف؟\r\n--   الملف **الوحيد** الذي يعرّف طرق الدفع: الكتالوج، وإعداد كل مستأجر، وحرّاس\r\n--   الكتابة، والمكان الواحد الذي يقرّر كيف تُرحَّل كل طريقة إلى الدفتر.\r\n--\r\n-- لماذا هو مهم؟\r\n--   قبل هذا الملف كانت طرق الدفع مبثوثة في ثمانية ملفات بلا مالك واحد:\r\n--\r\n--     · تعريف قيمة payment_method  — في 20260621011940\r\n--     · توسيعها بـ mobile_money     — ثلاثة ملفات متتالية، **اثنان مكرران**\r\n--     · قوائم القيم المسموحة        — منسوخة نصًا داخل create_sale\r\n--                                      و record_customer_payment، فتتباعد\r\n--\r\n--   اليوم مصدر واحد: جدول payment_methods، ودوال تحلّ الاسم إلى قيمته الشرعية.\r\n--   وإضافة طريقة جديدة صارت صفًا في الجدول لا تعديلًا في عشر دوال.\r\n--\r\n-- ── البنية ──────────────────────────────────────────────────────────────────\r\n--   payment_methods           الكتالوج: 13 طريقة (بذرة 08_payment_methods.sql)\r\n--   payment_method_settings   إعداد كل طريقة لكل مستأجر (تفعيل وتعطيل وترتيب)\r\n--   resolve_writable_payment_method   يحوّل ما أرسله العميل إلى قيمة شرعية\r\n--   payment_method_legacy_id  يعيد القيمة التاريخية — للتقارير القديمة\r\n--   ledger_account_code_for_payment_method   الحساب الذي تُرحَّل عليه\r\n--\r\n-- ── الكتالوج في البذور لا هنا ───────────────────────────────────────────────\r\n--   صفوف الطرق الـ 13 **بيانات مرجعية**، فمكانها\r\n--   `supabase/seeds/01_system/08_payment_methods.sql`. المصدر كان يضعها داخل\r\n--   الترحيل — نُقلت عند الدمج، راجع MIGRATIONS_RULES.md القاعدة R-1.\r\n--\r\n-- ⚠️ المصدر: origin/main — 20261208000000_payment_methods_catalog_unified.sql\r\n--    و 20261208000001_payment_methods_tenant_authoring.sql (امتداد مباشر له،\r\n--    لا يعمل منفصلًا عنه، فدُمجا في ملف واحد).\r\n--    عُدِّل عند الدمج: نُقل الكتالوج إلى البذرة، وأُزيل إعادة تعريف الدوال التي\r\n--    عندنا نسخة أحدث منها (create_sale، record_customer_payment، المرتجعات).\r\n--    وأُصلحت ثلاثة أخطاء كشفها تقرير `MIGRATION_16_REVIEW.md`:\r\n--      · §1.1 كان `coalesce(legacy_id, …)` يتوقف عند قيمة موجودة فيُبقي كل بنك\r\n--        ومحفظة على 'cash' — صار CASE يشتقّ القيمة من المصدر الحقيقي.\r\n--      · §1.2 حُذف `DEFAULT 'cash'` لأنه هو ما جعل `coalesce` يجد قيمة أبدًا.\r\n--      · §8.1 كان شرط الإصلاح يطابق «القيمة غير الصالحة» و'cash' صالحة، فلم\r\n--        يعمل الإصلاح قط؛ صار يطابق قيمة تخالف ما تشتقّه الدالة فعلًا.\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- ما استبدله هذا الملف\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- قبل هذا الترحيل كانت طرق الدفع مبثوثة في ثمانية ملفات بلا مالك واحد:\r\n--\r\n--   تعريف النوع وتوسيعه\r\n--     20260621011940  CREATE TYPE payment_method ('cash','card','bank_transfer','credit')\r\n--     20260706120000  ALTER TYPE … ADD VALUE 'mobile_money'   (رُقعة بذرة blackbox)\r\n--     20260706121000  ALTER TYPE … ADD VALUE 'mobile_money'   (مكررة، بذرة reset)\r\n--     20260707021000  ALTER TYPE … ADD VALUE 'mobile_money'   (مكررة، بذرة yemen)\r\n--\r\n--   قوائم القيم المسموحة منسوخة داخل دوال الكتابة\r\n--     20260801090000  create_sale       NOT IN ('cash','card','bank_transfer','credit','mobile_money')\r\n--     20260801090000  record_customer_payment NOT IN ('cash','card','bank_transfer','mobile_money')\r\n--     20260929030000  create_sale       NOT IN (… ,'split')\r\n--     20260929030000  أجزاء الدفع المجزأ  NOT IN ('cash','card','bank_transfer','mobile_money','split')\r\n--     20260928000000  نفس حارس المجزأ، في النسخة المُستبدَلة\r\n--\r\n--   «إلى أي حساب تُرحَّل هذه الطريقة» مثبّت في محرّك الترحيل\r\n--     20261202000000 / 20261202000100 / 20261202000200 / 20261203000000\r\n--       IF payment_method IN ('bank_transfer','card','mobile_money') THEN '1111' ELSE '1101'\r\n--\r\n-- والأثر كان ملموسًا لا نظريًا: إضافة طريقة يمنية مثل بنك الكريمي كانت تتطلب\r\n-- تعديل خمسة ملفات؛ ومن يعدّل النوع فقط تُرحَّل طريقته إلى **الصندوق** بدل البنك —\r\n-- بصمت وبلا خطأ ظاهر، فيتضخم الصندوق وينقص البنك.\r\n--\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- المصدر الوحيد للحقيقة بعد هذا الملف\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n--   public.payment_methods            الطرق المتاحة: الهوية، والأيقونة، وعائلة\r\n--                                     الحساب، والأقسام، والربط المحاسبي.\r\n--                                     ← للمطورين فقط، المنشأة لا تكتب هنا\r\n--   public.payment_method_settings     التفعيل والترتيب والأقسام لكل منشأة\r\n--\r\n--   public.payment_method_legacy_id()  معرّف → القيمة التي تُخزَّن على المستند\r\n--   public.payment_method_is_allowed() هل تُسمح هنا الآن\r\n--   public.payment_method_ledger_account() الحساب الذي تُسوّى إليه\r\n--\r\n-- كل دوال الكتابة ومحرّك الترحيل تستدعي هذه. وإضافة طريقة جديدة صارت صفًا في\r\n-- موضع واحد — بذرة الكتالوج في نهاية هذا الملف — فتصير صالحة فورًا في كل مكان.\r\n--\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- المتطلب: PostgreSQL 12 أو أحدث (لا حاجة لـ ALTER TYPE خارج المعاملة)\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- Postgres 12 يسمح بـ ALTER TYPE … ADD VALUE داخل كتلة معاملة. وهذا مهم هنا:\r\n-- قاعدة الإنتاج تحمل mobile_money فقط لأن ثلاث رقع بذور متتالية شُغّلت؛ وقاعدة\r\n-- جديدة مبنية من الترحيلات كانت ستبقى بلا split الذي يطلبه محرّك المبيعات منذ\r\n-- 20260929030000. لذلك يوسّع هذا الملف النوع في معاملة واحدة وبشكل ثابت، ويضع\r\n-- كل شيء على أوسع مجموعة:\r\n--\r\n--     cash | card | bank_transfer | credit | mobile_money | split | cheque\r\n--\r\n-- على PostgreSQL 11 أو أقدم، شغّل جملة واحدة منفردة أولًا:\r\n--     ALTER TYPE public.payment_method ADD VALUE IF NOT EXISTS 'cheque';\r\n-- ثم طبّق هذا الترحيل — فإضافة القيمة لا أثر لها إن كانت موجودة.\r\n--\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- 🔒 لا حذف ولا تعديل ولا نقل لأي بيانات قائمة\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n--   • كل عمود قائم يحتفظ بنوعه وقيمته.\r\n--   • كل صف قائم في sales_invoices وpurchase_invoices وexpenses و\r\n--     customer_payments وsales_returns وpurchase_returns وcustomer_payment_splits\r\n--     يحتفظ بقيمة payment_method المخزّنة بايتًا ببايت.\r\n--   • كل قيمة تاريخية في النوع تقابلها طريقة في الكتالوج، فتُعرض المستندات القديمة\r\n--     باسمها العربي وأيقونتها الصحيحة.\r\n--   • لا DELETE ولا UPDATE ولا TRUNCATE لبيانات أعمال هنا.\r\n--   • الكتابة الوحيدة: كتالوج المطورين (تعريف مملوك للمطورين لا بيانات عميل)،\r\n--     وصفوف الإعداد غير الموجودة أصلًا (ON CONFLICT DO NOTHING — اختيار المنشأة\r\n--     لا يُستبدل أبدًا).\r\n--\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- ما لم يُفعَل عن قصد\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n--   • النوع لم يُستبدل بعمود نصي وجدول بحث. فذلك يفرض إعادة كتابة ستة أعمدة على\r\n--     سبعة جداول تحمل تاريخًا ماليًا حقيقيًا، لمكسب لا يراه المستخدم. الكتالوج\r\n--     يمنح الهوية والترتيب والأقسام، والنوع يبقى عقد التخزين.\r\n--   • لا يُفرض account_id على أي طريقة. `default_account_code` و\r\n--     `payment_method_settings.default_account_id` جلسات للمرحلة المحاسبية؛\r\n--     تُملأ اليوم إرشادًا وتُقرأ كبديل فقط.\r\n--   • لا يُضاف سلوك دفتر أستاذ أو قيود أو دليل حسابات هنا.\r\n--\r\n-- ثابت (Idempotent): آمن للتطبيق المتكرر. إعادة التشغيل تُحدِّث تعريفات الكتالوج\r\n-- (الأسماء والأيقونات والترتيب والأقسام) بلا مسّ إعدادات المنشأة.\r\n-- ============================================================================\r\n\r\nBEGIN","-- ---------------------------------------------------------------------------\r\n-- 1. توسيع النوع إلى المجموعة الكاملة التي يستخدمها التطبيق فعلًا.\r\n--\r\n-- على PostgreSQL 12+ هذا قانوني داخل المعاملة. و`IF NOT EXISTS` يجعل كل قيمة من\r\n-- السبع بلا أثر إن كانت موجودة، فيغطّي الحالتين معًا: \\"رقع البذور الثلاث شُغّلت\\"\r\n-- و\\"لم تُشغَّل\\".\r\n-- ---------------------------------------------------------------------------\r\nALTER TYPE public.payment_method ADD VALUE IF NOT EXISTS 'cash'","ALTER TYPE public.payment_method ADD VALUE IF NOT EXISTS 'card'","ALTER TYPE public.payment_method ADD VALUE IF NOT EXISTS 'bank_transfer'","ALTER TYPE public.payment_method ADD VALUE IF NOT EXISTS 'credit'","ALTER TYPE public.payment_method ADD VALUE IF NOT EXISTS 'mobile_money'","ALTER TYPE public.payment_method ADD VALUE IF NOT EXISTS 'split'","ALTER TYPE public.payment_method ADD VALUE IF NOT EXISTS 'cheque'","COMMENT ON TYPE public.payment_method IS\r\n  'القيمة المخزّنة على المستند. لا تُستخدم للعرض ولا للتفعيل؛ العرض والتفعيل والأقسام تأتي من public.payment_methods.'","-- ============================================================================\r\n-- 2. كتالوج المطورين — أي طرق دفع توجد\r\n--\r\n-- المنشأة لا تكتب هنا أبدًا. الصفوف تأتي من هذا الترحيل وحده، فلا يمكن اختراع\r\n-- طريقة من المتصفّح ولا تقديم أيقونة من عميل. و`id` **مفتاح نصي ثابت** لا UUID:\r\n-- فيستطيع الترحيل مخاطبة الطريقة بلا لبس وبثبات أبدي، وتبقى إشارة الأيقونة\r\n-- مقروءة.\r\n-- ============================================================================\r\nCREATE TABLE IF NOT EXISTS public.payment_methods (\r\n  id                   text PRIMARY KEY,\r\n\r\n  name_ar              text        NOT NULL,\r\n  name_en              text,\r\n\r\n  -- **مفتاح**، لا رابط ولا base64 أبدًا. السجل المضمَّن في\r\n  -- src/lib/payments/payment-methods.ts يحلّه إلى مكوّن، فأيقونة الدفع بلا أي\r\n  -- طلب شبكة ولا يمكن أن تفشل في التحميل.\r\n  icon_key             text        NOT NULL DEFAULT 'generic',\r\n\r\n  -- توفّر على مستوى المطور، لإيقاف طريقة في كل مكان دفعة واحدة بلا حذف\r\n  -- التاريخ الذي يشير إليها.\r\n  is_active            boolean     NOT NULL DEFAULT true,\r\n\r\n  -- ترتيب العرض الافتراضي. والمنشأة تتجاوزه في الإعدادات.\r\n  sort_order           integer     NOT NULL DEFAULT 100,\r\n\r\n  -- الأقسام التي **يسمح** بها المطورون. والمنشأة يمكنها فقط تضييقها.\r\n  allowed_contexts     text[]      NOT NULL DEFAULT ARRAY[]::text[],\r\n\r\n  -- عائلة الحساب التي تُسوّى إليها الأموال. عليها يتفرّع محرّك الترحيل بدل\r\n  -- قائمة قيم النوع المضمّنة.\r\n  ledger_kind          text        NOT NULL DEFAULT 'CASH',\r\n\r\n  -- وصلة محاسبية. إرشادية اليوم؛ والربط الرسمي الخاص بكل منشأة هو\r\n  -- payment_method_settings.default_account_id.\r\n  default_account_code text,\r\n\r\n  -- سلوك يجب ألا تثبّته الواجهة في كودها.\r\n  is_credit_term       boolean     NOT NULL DEFAULT false,\r\n  requires_reference   boolean     NOT NULL DEFAULT false,\r\n\r\n  -- قيم النوع التي يمثّلها هذا الصف. تتيح لفواتير تاريخية خزّنت\r\n  -- 'bank_transfer' أن تُعرض من الكتالوج بدل خريطة محلية.\r\n  legacy_ids           text[]      NOT NULL DEFAULT ARRAY[]::text[],\r\n\r\n  notes                text,\r\n\r\n  created_at           timestamptz NOT NULL DEFAULT now(),\r\n  updated_at           timestamptz NOT NULL DEFAULT now(),\r\n\r\n  CONSTRAINT payment_methods_id_normalised\r\n    CHECK (id = lower(btrim(id)) AND id <> ''),\r\n  CONSTRAINT payment_methods_ledger_kind_valid\r\n    CHECK (ledger_kind IN ('CASH','BANK','WALLET','CARD','CREDIT','OTHER')),\r\n  CONSTRAINT payment_methods_contexts_valid\r\n    CHECK (allowed_contexts <@ ARRAY[\r\n      'pos','sales','purchases','expenses','customer_collection',\r\n      'sales_returns','purchase_returns'\r\n    ]::text[])\r\n)","COMMENT ON TABLE public.payment_methods IS\r\n  'كتالوج طرق الدفع الذي يجهّزه المطورون. العميل لا ينشئ صفوفاً هنا؛ يختار ويفعّل فقط.'","COMMENT ON COLUMN public.payment_methods.icon_key IS\r\n  'مفتاح أيقونة مركزي يُحلّ إلى مكوّن داخل الحزمة. ليس رابطاً خارجياً ولا Base64.'","COMMENT ON COLUMN public.payment_methods.ledger_kind IS\r\n  'عائلة الحساب (صندوق/بنك/محفظة/بطاقة/آجل). يستخدمها محرك الترحيل بدل تعداد قيم الـEnum.'","COMMENT ON COLUMN public.payment_methods.default_account_code IS\r\n  'ربط محاسبي مستقبلي: payment_method → account. إرشادي في هذه المرحلة.'","COMMENT ON COLUMN public.payment_methods.legacy_ids IS\r\n  'قيم public.payment_method التي تمثّلها هذه الطريقة، لعرض الفواتير التاريخية من الكتالوج.'","CREATE INDEX IF NOT EXISTS ix_payment_methods_order\r\n  ON public.payment_methods (is_active, sort_order, id)","CREATE INDEX IF NOT EXISTS ix_payment_methods_legacy_ids\r\n  ON public.payment_methods USING gin (legacy_ids)","-- ============================================================================\r\n-- 3. إعداد المنشأة — ما اختارته **هذه** المنشأة\r\n--\r\n-- أي طريقة بلا صف هنا لم تلمسها المنشأة قط، فترث افتراضيات الكتالوج؛ لذلك\r\n-- إضافة طريقة في ترحيل تجعلها متاحة بلا أي backfill.\r\n-- ============================================================================\r\nCREATE TABLE IF NOT EXISTS public.payment_method_settings (\r\n  payment_method_id  text PRIMARY KEY\r\n    REFERENCES public.payment_methods(id) ON DELETE CASCADE,\r\n\r\n  enabled            boolean NOT NULL DEFAULT true,\r\n  sort_order         integer NOT NULL DEFAULT 100,\r\n  enabled_contexts   text[]  NOT NULL DEFAULT ARRAY[]::text[],\r\n\r\n  -- وصلة محاسبية لكل منشأة: المرحلة التي يُربط فيها بنك الكريمي بحساب بنكي\r\n  -- بعينه بدل حساب عام.\r\n  default_account_id uuid REFERENCES public.accounts(id) ON DELETE SET NULL,\r\n\r\n  updated_at         timestamptz NOT NULL DEFAULT now(),\r\n  updated_by         uuid REFERENCES auth.users(id) ON DELETE SET NULL,\r\n\r\n  CONSTRAINT payment_method_settings_contexts_valid\r\n    CHECK (enabled_contexts <@ ARRAY[\r\n      'pos','sales','purchases','expenses','customer_collection',\r\n      'sales_returns','purchase_returns'\r\n    ]::text[])\r\n)","COMMENT ON TABLE public.payment_method_settings IS\r\n  'تخصيص العميل: تفعيل كل طريقة، ترتيب عرضها، والأقسام التي تظهر فيها.'","COMMENT ON COLUMN public.payment_method_settings.enabled_contexts IS\r\n  'الأقسام المسموح بها لهذه المنشأة. لا يمكن أن تتجاوز allowed_contexts في الكتالوج.'","CREATE INDEX IF NOT EXISTS ix_payment_method_settings_order\r\n  ON public.payment_method_settings (enabled, sort_order)","-- ---------------------------------------------------------------------------\r\n-- 3.1 يمكن للمنشأة أن **تضيّق** قائمة الأقسام التي حدّدها المطورون، لا أن توسّعها.\r\n--     وقيود CHECK لا ترى الصف الأب، فالحل trigger.\r\n--     بلاه، قد يعرض خطأ في شاشة الإعدادات «آجل» عند تحصيل نقدي، أو محفظة داخل\r\n--     مرتجع مشتريات حيث يُفترض احترام طريقة الاسترداد.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.payment_method_settings_guard()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_allowed text[];\r\nBEGIN\r\n  SELECT allowed_contexts INTO v_allowed\r\n  FROM public.payment_methods\r\n  WHERE id = NEW.payment_method_id;\r\n\r\n  IF v_allowed IS NULL THEN\r\n    RAISE EXCEPTION 'طريقة الدفع غير موجودة في الكتالوج: %', NEW.payment_method_id\r\n      USING ERRCODE = 'foreign_key_violation';\r\n  END IF;\r\n\r\n  IF NOT (NEW.enabled_contexts <@ v_allowed) THEN\r\n    RAISE EXCEPTION\r\n      'الأقسام المختارة (%) تتجاوز ما يسمح به الكتالوج لطريقة % (%)',\r\n      array_to_string(NEW.enabled_contexts, ', '),\r\n      NEW.payment_method_id,\r\n      array_to_string(v_allowed, ', ')\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND $$","COMMENT ON FUNCTION public.payment_method_settings_guard() IS\r\n  'يمنع توسيع أقسام طريقة الدفع خارج ما يسمح به كتالوج المطورين.'","DROP TRIGGER IF EXISTS payment_method_settings_context_guard\r\n  ON public.payment_method_settings","CREATE TRIGGER payment_method_settings_context_guard\r\n  BEFORE INSERT OR UPDATE ON public.payment_method_settings\r\n  FOR EACH ROW EXECUTE FUNCTION public.payment_method_settings_guard()","DROP TRIGGER IF EXISTS payment_methods_updated ON public.payment_methods","CREATE TRIGGER payment_methods_updated\r\n  BEFORE UPDATE ON public.payment_methods\r\n  FOR EACH ROW EXECUTE FUNCTION public.tg_set_updated_at()","DROP TRIGGER IF EXISTS payment_method_settings_updated\r\n  ON public.payment_method_settings","CREATE TRIGGER payment_method_settings_updated\r\n  BEFORE UPDATE ON public.payment_method_settings\r\n  FOR EACH ROW EXECUTE FUNCTION public.tg_set_updated_at()","-- ---------------------------------------------------------------------------\r\n-- 3.2 سياسات RLS.\r\n--     الكتالوج يقرأه أي موظف — فكل شاشة تحتاج الأسماء والأيقونات — ولا يكتبه\r\n--     أحد عبر PostgREST: فهو يأتي مع الترحيلات، وهي تعمل بصلاحية المالك وتتجاوز\r\n--     RLS. وإعداد المنشأة يقرأه الموظفون ويكتبه المالك/المدير، كبقية شاشات\r\n--     الإعدادات في المشروع.\r\n-- ---------------------------------------------------------------------------\r\nALTER TABLE public.payment_methods          ENABLE ROW LEVEL SECURITY","ALTER TABLE public.payment_method_settings  ENABLE ROW LEVEL SECURITY","GRANT SELECT ON public.payment_methods TO authenticated","GRANT SELECT, INSERT, UPDATE, DELETE ON public.payment_method_settings TO authenticated","GRANT ALL ON public.payment_methods, public.payment_method_settings TO service_role","DROP POLICY IF EXISTS \\"payment_methods read\\" ON public.payment_methods","CREATE POLICY \\"payment_methods read\\"\r\n  ON public.payment_methods\r\n  FOR SELECT TO authenticated\r\n  USING (public.is_staff(auth.uid()))","DROP POLICY IF EXISTS \\"payment_method_settings read\\" ON public.payment_method_settings","CREATE POLICY \\"payment_method_settings read\\"\r\n  ON public.payment_method_settings\r\n  FOR SELECT TO authenticated\r\n  USING (public.is_staff(auth.uid()))","DROP POLICY IF EXISTS \\"payment_method_settings write\\" ON public.payment_method_settings","CREATE POLICY \\"payment_method_settings write\\"\r\n  ON public.payment_method_settings\r\n  FOR ALL TO authenticated\r\n  USING (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager'))\r\n  WITH CHECK (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager'))","-- ============================================================================\r\n-- 4. البذرة — الكتالوج اليمني\r\n--\r\n-- هذه هي الطرق التي نجهّزها نحن المطورين. و`ON CONFLICT DO UPDATE` يجعل إعادة\r\n-- التطبيق تحدّث الأسماء والأيقونات والترتيب والأقسام. ولا يلمس\r\n-- payment_method_settings عن قصد: مفاتيح المنشأة ملكها، والترحيل يجب ألا يعيد\r\n-- ضبطها أبدًا.\r\n--\r\n-- و`legacy_ids` حاملة لا زخرفة. هي ما يسمح لـ cash/card/bank_transfer/credit/\r\n-- mobile_money بالاحتفاظ بمعناها الدقيق بينما تصبح خمس مؤسسات يمنية مسمّاة طرقًا\r\n-- من الدرجة الأولى تُختار بجانبها.\r\n-- ============================================================================\r\n\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 4.1 إعداد المنشأة **لا** يُملأ هنا.\r\n--\r\n-- لماذا لا: يجب أن توجد صفوف payment_method_settings للطرق الست التاريخية حتى لا\r\n-- تُفقد خيار دفع من الصندوق عند الترقية. لكن هذا الترحيل يعمل **قبل** بذرة\r\n-- الكتالوج، فـ `SELECT … FROM public.payment_methods` هنا يجد جدولًا فارغًا،\r\n-- ويُدرج صفرًا، ولا يبلّغ عن خطأ. فالـ backfill كُتب، ونُفّذ، ولم يفعل شيئًا —\r\n-- بينما قاعدة صادف أنها زُرعت أولًا تتصرف مختلفًا. وهذا عمل إدخال بيانات لا عمل\r\n-- بنية.\r\n--\r\n-- ومكانه الآن: supabase/seeds/01_system/08_payment_methods.sql، مباشرة بعد\r\n-- إدراج الكتالوج. فهو صف بيانات مرجعية، و MIGRATIONS_RULES.md القسم 1 يضع\r\n-- المرجعيات في البذرة بجانب الصفوف التي تعتمد عليها — وهو ما يُزيل هشاشة\r\n-- الترتيب كليًا.\r\n--\r\n-- والطرق اليمنية المسمّاة لا تأخذ صف إعداد عن قصد: غياب الصف يعني «ورّث افتراضي\r\n-- الكتالوج»، وهو مفعّل ومقيّد بأقسام الكتالوج، فتظهر كإضافة عادية.\r\n-- ---------------------------------------------------------------------------\r\n\r\n\r\n-- ============================================================================\r\n-- 5. الدوال المساعدة الثلاث التي يناديها كل شيء\r\n--\r\n-- تُستبدل بها، في موضع واحد، ما كان مكرّرًا كقيم ENUM حرفية في خمس دوال RPC\r\n-- وأربعة ترحيلات لترحيل الدفتر.\r\n-- ============================================================================\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 5.1 معرّف كتالوجي ← القيمة التي يخزّنها المستند.\r\n--\r\n-- التحويل **الوحيد** المسموح. لا يجوز أن تخمّن شاشة، ولا أن تستقبل `create_sale`\r\n-- قيمة لا يحملها النوع.\r\n--\r\n-- ومعرّف مجهول يعيد 'cash' لا NULL، لأن NULL في عمود payment_method أسوأ من قيمة\r\n-- خاطئة لكن صالحة: فمحرّك الدفتر يسقط إلى نهاية CASE ويُرحّل إلى الصندوق مهما\r\n-- كان. والحارس في 6.1 هو ما يرفض المعرّفات المجهولة مقدّمًا؛ وهذه أدنى حدّ أخير.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.payment_method_legacy_id(p_id text)\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  WITH norm AS (\r\n    SELECT lower(btrim(coalesce(p_id, ''))) AS v\r\n  ),\r\n  direct AS (\r\n    -- المعرّف هو نفسه قيمة ENUM (cash, card, bank_transfer, credit,\r\n    -- mobile_money, split, cheque): يُقبل كما هو. وهذا ما يبقي كل مستدعٍ قائم\r\n    -- يعمل بلا تغيير.\r\n    SELECT n.v\r\n    FROM norm n\r\n    WHERE n.v <> ''\r\n      AND EXISTS (\r\n        SELECT 1 FROM pg_enum e\r\n        JOIN pg_type t ON t.oid = e.enumtypid\r\n        JOIN pg_namespace ns ON ns.oid = t.typnamespace\r\n        WHERE ns.nspname = 'public' AND t.typname = 'payment_method'\r\n          AND e.enumlabel = n.v\r\n      )\r\n  ),\r\n  via_catalog AS (\r\n    SELECT coalesce(\r\n             nullif(m.legacy_ids[1], ''),\r\n             CASE m.ledger_kind\r\n               WHEN 'BANK'   THEN 'bank_transfer'\r\n               WHEN 'WALLET' THEN 'mobile_money'\r\n               WHEN 'CARD'   THEN 'card'\r\n               WHEN 'CREDIT' THEN 'credit'\r\n               WHEN 'CASH'   THEN 'cash'\r\n               ELSE 'cash'\r\n             END\r\n           ) AS v\r\n    FROM public.payment_methods m, norm n\r\n    WHERE m.id = n.v\r\n  )\r\n  SELECT coalesce(\r\n    (SELECT v FROM direct),\r\n    (SELECT v FROM via_catalog),\r\n    'cash'\r\n  );\r\n$$","COMMENT ON FUNCTION public.payment_method_legacy_id(text) IS\r\n  'يحوّل معرّف الكتالوج إلى القيمة التي يفهمها عمود payment_method. المصدر الوحيد لهذا التحويل في النظام.'","-- ---------------------------------------------------------------------------\r\n-- 5.2 قيمة مخزّنة ← صف الكتالوج الذي يمثّلها.\r\n--     يُستخدم لتسمية المستندات التاريخية من الكتالوج بدل خريطة تسميات محلية،\r\n--     فيُعرَّف اسم الطريقة الجديدة مرة واحدة.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.payment_method_catalog_id(p_stored text)\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT m.id\r\n  FROM public.payment_methods m\r\n  WHERE lower(btrim(coalesce(p_stored, ''))) = ANY (m.legacy_ids)\r\n  ORDER BY m.sort_order, m.id\r\n  LIMIT 1;\r\n$$","COMMENT ON FUNCTION public.payment_method_catalog_id(text) IS\r\n  'يعيد معرّف الكتالوج المقابل لقيمة مخزّنة، لعرض الفواتير التاريخية من الكتالوج.'","-- ---------------------------------------------------------------------------\r\n-- 5.3 تطبيع أي قيمة واردة إلى معرّف كتالوجي.\r\n--\r\n-- ترتيب الحل مهمّ. فقيمة ENUM خام يجب أن تُحلّ إلى الصف الكتالوجي **المرجعي**\r\n-- لتلك القيمة، لا إلى أي مؤسسة مسمّاة تصادف أنها تحملها أيضًا. فيجب أن تصير\r\n-- 'bank_transfer' تحويلًا بنكيًا عامًا، لا بنك الكريمي أبدًا.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.payment_method_resolve_id(p_value text)\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  WITH norm AS (\r\n    SELECT lower(btrim(coalesce(p_value, ''))) AS v\r\n  )\r\n  SELECT coalesce(\r\n    -- 1. معرّف كتالوجي مطابق يفوز مباشرةً.\r\n    (SELECT m.id FROM public.payment_methods m, norm n WHERE m.id = n.v),\r\n    -- 2. قيمة ENUM مطابقة تُحلّ إلى الصف المرجعي لتلك القيمة.\r\n    (SELECT public.payment_method_catalog_id(n.v) FROM norm n WHERE n.v <> ''),\r\n    -- 3. غير قابلة للحل: تُعاد كما هي ليبلّغ المستدعي بأمانة بدل أن يستبدل\r\n    --    صامتًا طريقة لم يخترها المشغّل.\r\n    (SELECT nullif(n.v, '') FROM norm n)\r\n  );\r\n$$","COMMENT ON FUNCTION public.payment_method_resolve_id(text) IS\r\n  'يطبّع أي قيمة واردة من الواجهة إلى معرّف كتالوجي، دون تخمين صامت.'","-- ---------------------------------------------------------------------------\r\n-- 5.4 هل يمكن استخدام هذه الطريقة، في هذا القسم، الآن؟\r\n--\r\n-- حارس الكتابة الواحد. يقرأ إعداد المنشأة ويرجع إلى الكتالوج، فيكون أي طريقة لم\r\n-- يضبطها أحد صالحة للاستخدام فورًا.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.payment_method_is_allowed(\r\n  p_value   text,\r\n  p_context text\r\n)\r\nRETURNS boolean\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  WITH resolved AS (\r\n    SELECT public.payment_method_resolve_id(p_value) AS id\r\n  )\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.payment_methods m\r\n    LEFT JOIN public.payment_method_settings s ON s.payment_method_id = m.id\r\n    CROSS JOIN resolved r\r\n    WHERE m.id = r.id\r\n      -- يمكن للمطورين إيقاف طريقة في كل مكان بلا حذفها.\r\n      AND m.is_active\r\n      AND coalesce(s.enabled, true)\r\n      AND p_context = ANY (\r\n        CASE\r\n          WHEN coalesce(cardinality(s.enabled_contexts), 0) > 0\r\n            THEN s.enabled_contexts\r\n          ELSE m.allowed_contexts\r\n        END\r\n      )\r\n  );\r\n$$","COMMENT ON FUNCTION public.payment_method_is_allowed(text, text) IS\r\n  'هل طريقة الدفع مفعّلة ومسموح بها في هذا القسم لهذه المنشأة؟ الحارس الوحيد في النظام.'","-- ---------------------------------------------------------------------------\r\n-- 5.5 إلى أي حساب تُسوّى هذه الطريقة؟\r\n--\r\n-- يستبدل النسخ الأربع من\r\n--   IF payment_method IN ('bank_transfer','card','mobile_money') THEN '1111' ELSE '1101'\r\n-- التي كانت تُرحّل كل طريقة يمنية جديدة إلى الصندوق.\r\n--\r\n-- و`credit` تعيد NULL عن قصد: لم يُحصَّل شيء، فلا يوجد سطر نقد أو بنك يُكتب. وعلى\r\n-- المستدعي أن يتحقّق من NULL لا أن يعامل النتيجة كأنها كود.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.payment_method_ledger_account(p_stored text)\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT CASE\r\n    -- الإرشاد الصريح في صف الكتالوج يفوز.\r\n    WHEN m.default_account_code IS NOT NULL THEN m.default_account_code\r\n    -- وإلا تُشتقّ من عائلة الحساب. و NULL لـ CREDIT مقصود.\r\n    WHEN m.ledger_kind IN ('BANK','WALLET','CARD') THEN '1111'\r\n    WHEN m.ledger_kind = 'CREDIT' THEN NULL\r\n    WHEN m.ledger_kind = 'CASH'   THEN '1101'\r\n    ELSE '1101'\r\n  END\r\n  FROM public.payment_methods m\r\n  WHERE m.id = public.payment_method_resolve_id(p_stored);\r\n$$","COMMENT ON FUNCTION public.payment_method_ledger_account(text) IS\r\n  'الحساب الذي تُسوّى إليه طريقة الدفع. يعيد NULL للآجل لأن شيئاً لم يُحصَّل.'","-- ---------------------------------------------------------------------------\r\n-- 5.6 منح الدوال المساعدة. فهي للقراءة فقط، و SECURITY DEFINER، وحتمية نسبةً\r\n--     لكتالوج معيّن، فيجوز للمستدعين الموثّقين تنفيذها.\r\n-- ---------------------------------------------------------------------------\r\nREVOKE ALL ON FUNCTION public.payment_method_legacy_id(text)          FROM PUBLIC, anon","REVOKE ALL ON FUNCTION public.payment_method_catalog_id(text)         FROM PUBLIC, anon","REVOKE ALL ON FUNCTION public.payment_method_resolve_id(text)         FROM PUBLIC, anon","REVOKE ALL ON FUNCTION public.payment_method_is_allowed(text, text)   FROM PUBLIC, anon","REVOKE ALL ON FUNCTION public.payment_method_ledger_account(text)     FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.payment_method_legacy_id(text)        TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.payment_method_catalog_id(text)       TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.payment_method_resolve_id(text)       TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.payment_method_is_allowed(text, text) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.payment_method_ledger_account(text)   TO authenticated, service_role","-- ============================================================================\r\n-- 6. حارس الكتابة — دالة واحدة تستبدل خمس قوائم ENUM مضمّنة\r\n--\r\n-- كل مسار كتابة يناديها بدل تكرار\r\n--   NOT IN ('cash','card','bank_transfer','credit','mobile_money')\r\n-- وهو ما جعل إضافة طريقة جديدة مستحيلة بلا تعديل خمسة ملفات، وما سمح لشاشات\r\n-- المرتجعات بإرسال قيمة `bank` لا يحملها النوع.\r\n--\r\n-- و`p_strict_context` يتحكّم في تطبيق تقييد القسم:\r\n--   • true  — إدخال مشغّل عادي. يجب أن تكون الطريقة مفعّلة **لهذا** القسم.\r\n--             يمنع ظهور محفظة في مرتجع مشتريات.\r\n--   • false — إعادة تشغيل / إصلاح. يجب أن توجد الطريقة وتكون مفعّلة للمنشأة،\r\n--             بلا تقييد بقسم. يُستخدم حيث يُعاد ترحيل مستند تاريخي بعد تغيير\r\n--             المنشأة إعداداتها، فلا نعيد كتابة التاريخ.\r\n--\r\n-- يعيد القيمة المُراد **تخزينها** (بعد تحويلها عبر النوع)، أو يرفع استثناءً.\r\n-- ============================================================================\r\nCREATE OR REPLACE FUNCTION public.resolve_writable_payment_method(\r\n  p_value          text,\r\n  p_context        text,\r\n  p_strict_context boolean DEFAULT true\r\n)\r\nRETURNS text\r\nLANGUAGE plpgsql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_id      text;\r\n  v_stored  text;\r\n  v_enabled boolean;\r\nBEGIN\r\n  v_id := public.payment_method_resolve_id(p_value);\r\n\r\n  -- ← يلي: التحقق من الصلاحية ثم التحويل، بترتيب صريح\r\n  IF v_id IS NULL THEN\r\n    RAISE EXCEPTION 'طريقة دفع غير صالحة: %', coalesce(p_value, '(فارغ)')\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  SELECT coalesce(s.enabled, true) AND m.is_active\r\n    INTO v_enabled\r\n  FROM public.payment_methods m\r\n  LEFT JOIN public.payment_method_settings s ON s.payment_method_id = m.id\r\n  WHERE m.id = v_id;\r\n\r\n  IF v_enabled IS NOT TRUE THEN\r\n    RAISE EXCEPTION 'طريقة الدفع غير مفعّلة: %', p_value\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  IF p_strict_context\r\n     AND NOT public.payment_method_is_allowed(v_id, coalesce(p_context, 'pos')) THEN\r\n    RAISE EXCEPTION\r\n      'طريقة الدفع \\"%\\" غير مسموح بها في قسم \\"%\\"', p_value, coalesce(p_context, 'pos')\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  v_stored := public.payment_method_legacy_id(v_id);\r\n\r\n  IF v_stored IS NULL THEN\r\n    RAISE EXCEPTION 'تعذّر تحويل طريقة الدفع إلى قيمة صالحة: %', p_value\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  RETURN v_stored;\r\nEND $$","COMMENT ON FUNCTION public.resolve_writable_payment_method(text, text, boolean) IS\r\n  'الحارس الموحّد لكتابة طريقة الدفع: يتحقق من الصلاحية ثم يعيد القيمة المخزّنة. بديل القوائم المضمّنة في دوال الكتابة.'","REVOKE ALL ON FUNCTION public.resolve_writable_payment_method(text, text, boolean) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.resolve_writable_payment_method(text, text, boolean) TO authenticated, service_role","-- ============================================================================\r\n-- 7. مسارات الكتابة تستعمل الكتالوج الآن\r\n--\r\n-- كل واحد من هؤلاء هو الجسم **الحالي** للدالة، بلا تغيير إلا معالجة طريقة\r\n-- الدفع. ولا يُمسّ المخزون ولا حدود الائتمان ولا ترحيل الذمم ولا التدقيق ولا\r\n-- الترقيم — فطريقة الدفع تسمية وعائلة حساب، لا قاعدة عمل.\r\n-- ============================================================================\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 8. محرّك ترحيل الدفتر يسأل الكتالوج الآن\r\n--\r\n-- أربعة ترحيلات كان كل منها يحمل نسخته من:\r\n--\r\n--   IF payment_method = 'credit' THEN NULL\r\n--   ELSIF payment_method IN ('bank_transfer','card','mobile_money') THEN '1111'\r\n--   ELSE '1101' END IF\r\n--\r\n-- ذلك الفرع من ثلاثة أسطر هو السبب في استحالة إضافة طريقة يمنية جديدة بأمان.\r\n-- فبنك الكريمي مسجّلًا كـ 'bank_transfer' رُحّل صحيحًا **بالمصادفة**: فقط لأن\r\n-- `legacy_ids` صادف أنها تُطابق قيمة موجودة في القائمة. أما طريقة عائلتها BANK\r\n-- وقيمتها التاريخية تُحلّ إلى شيء آخر فلَكانت رُحّلت إلى الصندوق بلا أي خطأ.\r\n--\r\n-- وكل جسم أدناه هو الدالة **الحالية**، مع استبدال ذلك الفرع وحده بـ\r\n-- public.payment_method_ledger_account(). وبناء القيد، وتصنيف الإيراد، وحلّ\r\n-- التكلفة، وسطر الضريبة، وحارس «مرة واحدة فقط»، والعرض — بلا مساس.\r\n--\r\n-- لاحظ ترتيب التعريفات الأربعة: كلٌّ يستبدل ما قبله، وقد أُعيد تشغيلها هنا\r\n-- بالترتيب نفسه فيكون التعريف النهائي مطابقًا لما يعمل به الإنتاج — زائد نداء\r\n-- الكتالوج.\r\n-- ============================================================================\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 8.1 ledger_account_code_for_payment_method — الفرع، مُسمّى مرة واحدة.\r\n--\r\n-- أُبقي كغلاف بدل تضمين النداء في كل دالة ترحيل، فتبقى الدوال الأربع تُقرأ كما\r\n-- كانت ويستطيع المراجع مقارنتها سطرًا بسطر بأصولها.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.ledger_account_code_for_payment_method(\r\n  p_payment_method text\r\n)\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT public.payment_method_ledger_account(p_payment_method);\r\n$$","COMMENT ON FUNCTION public.ledger_account_code_for_payment_method(text) IS\r\n  'الحساب الذي تُسوّى إليه طريقة الدفع في القيود. يعيد NULL للآجل، ويأتي من الكتالوج لا من قائمة مضمّنة.'","REVOKE ALL ON FUNCTION public.ledger_account_code_for_payment_method(text) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.ledger_account_code_for_payment_method(text) TO authenticated, service_role","-- ---------------------------------------------------------------------------\r\n-- 8.2 post_sales_invoice\r\n--\r\n-- منقول حرفيًا من\r\n--   20261202000200_cash_received_is_debited_not_credited.sql\r\n-- وهو أحدث نسخ ترحيل المبيعات الثلاث. التغيير الوحيد هو استبدال:\r\n--\r\n--   IF v_inv.payment_method = 'credit' THEN NULL\r\n--   ELSIF v_inv.payment_method IN ('bank_transfer','card','mobile_money') THEN '1111'\r\n--   ELSE '1101' END IF\r\n--\r\n-- باستدعاء الكتالوج. وكل ما عدا ذلك — حارس «مرة واحدة فقط»، ورفض الدفع الزائد،\r\n-- وتصنيف الإيراد حسب item_class، وسطر الضريبة، وسطور تكلفة المبيعات، و\r\n-- create_journal_entry — بلا مساس.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.post_sales_invoice(p_invoice_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_inv     record;\r\n  v_existing uuid;\r\n  v_entry   uuid;\r\n  v_lines   jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  v_collectable numeric := 0;\r\n  r         record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')\r\n          OR public.has_role(v_user,'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may post an invoice';\r\n  END IF;\r\n\r\n  SELECT * INTO v_inv FROM public.sales_invoices WHERE id = p_invoice_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Invoice not found';\r\n  END IF;\r\n\r\n  IF v_inv.status IN ('draft','cancelled') THEN\r\n    RAISE EXCEPTION 'Invoice % is % - only confirmed, paid or partial invoices post',\r\n      v_inv.invoice_number, v_inv.status;\r\n  END IF;\r\n\r\n  IF v_inv.paid < 0 THEN\r\n    RAISE EXCEPTION 'Invoice % carries a negative payment (%). A refund is a credit note, not a negative payment.',\r\n      v_inv.invoice_number, v_inv.paid;\r\n  END IF;\r\n  IF v_inv.paid > v_inv.total THEN\r\n    RAISE EXCEPTION 'Invoice % was paid % against a total of %. Fix the invoice before posting - a payment cannot exceed the invoice.',\r\n      v_inv.invoice_number, v_inv.paid, v_inv.total;\r\n  END IF;\r\n  IF v_inv.tax < 0 THEN\r\n    RAISE EXCEPTION 'Invoice % carries a negative tax amount', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  SELECT id INTO v_existing\r\n    FROM public.journal_entries\r\n   WHERE source_type = 'sales_invoice' AND source_id = p_invoice_id\r\n     AND status <> 'REVERSED';\r\n  IF v_existing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'Invoice % has already been posted to the ledger', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- ── الحساب من الكتالوج بدل القائمة المضمّنة ─────────────────────────────\r\n  -- 'credit'          -> NULL      (لم يُحصَّل شيء)\r\n  -- BANK/WALLET/CARD  -> '1111'    (يخرج عبر البنك)\r\n  -- CASH / OTHER      -> '1101'    (الصندوق؛ وsplit تُسوّى نقداً)\r\n  v_cash_acct := public.ledger_account_code_for_payment_method(v_inv.payment_method);\r\n\r\n  v_collectable := greatest(v_inv.total - v_inv.paid, 0);\r\n\r\n  -- ── revenue, credited ──\r\n  FOR r IN\r\n    SELECT p.item_class, sum(it.total) AS amount\r\n      FROM public.sales_invoice_items it\r\n      JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n     GROUP BY p.item_class\r\n    HAVING sum(it.total) <> 0\r\n  LOOP\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE r.item_class\r\n                        WHEN 'BY_PRODUCT' THEN '4211'\r\n                        WHEN 'SERVICE'    THEN '4311'\r\n                        ELSE '4111' END,\r\n      'credit', round(r.amount, 2),\r\n      'memo', 'إيراد ' || r.item_class);\r\n  END LOOP;\r\n\r\n  IF jsonb_array_length(v_lines) = 0 THEN\r\n    RAISE EXCEPTION 'Invoice % has no revenue lines', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- ── ما استلمته المنشأة: النقد والذمة كلاهما مدين ──\r\n  -- هما بديلان لنفس الزيادة، فبيعة مسدّدة بالكامل لها مدين نقدي بلا ذمة، وبيعة\r\n  -- آجلة العكس.\r\n  IF v_inv.paid > 0 AND v_cash_acct IS NOT NULL THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', v_cash_acct, 'debit', round(v_inv.paid, 2),\r\n      'memo', 'تحصيل نقدي/بنكي');\r\n  END IF;\r\n  IF v_collectable > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1211', 'debit', round(v_collectable, 2),\r\n      'memo', 'ذمم العميل ' || coalesce(v_inv.invoice_number, ''));\r\n  END IF;\r\n\r\n  IF v_inv.tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2311', 'credit', round(v_inv.tax, 2),\r\n      'memo', 'ضريبة القيمة المضافة المستحقة');\r\n  END IF;\r\n\r\n  -- ── the cost of the goods that left ──\r\n  FOR r IN\r\n    SELECT p.item_class,\r\n           sum(it.quantity * public.resolve_unit_cost(p.id, v_inv.warehouse_id)) AS cost\r\n      FROM public.sales_invoice_items it\r\n      JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n       AND it.stock_effect = 'STOCK_ISSUE'\r\n     GROUP BY p.item_class\r\n  LOOP\r\n    IF r.cost IS NULL OR r.cost = 0 THEN\r\n      CONTINUE;   -- no cost known; a zero COGS line would overstate profit\r\n    END IF;\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE r.item_class\r\n                        WHEN 'RAW_MATERIAL' THEN '1311'\r\n                        WHEN 'BY_PRODUCT'   THEN '1314'\r\n                        ELSE '1313' END,\r\n      'credit', round(r.cost, 2),\r\n      'memo', 'تكلفة ' || r.item_class);\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '5111', 'debit', round(r.cost, 2),\r\n      'memo', 'تكلفة البضاعة المباعة');\r\n  END LOOP;\r\n\r\n  v_entry := public.create_journal_entry(\r\n    'فاتورة مبيعات ' || v_inv.invoice_number,\r\n    v_inv.created_at::date,\r\n    'sales_invoice', p_invoice_id, true, v_lines);\r\n\r\n  RETURN v_entry;\r\nEND $$","REVOKE ALL ON FUNCTION public.post_sales_invoice(uuid) FROM PUBLIC, anon","REVOKE ALL ON FUNCTION public.post_sales_invoice(uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.post_sales_invoice(uuid) TO authenticated, service_role","COMMENT ON FUNCTION public.post_sales_invoice(uuid) IS\r\n  'يرحّل فاتورة مبيعات إلى الدفتر. حساب التحصيل يأتي من كتالوج طرق الدفع، والإيراد من تصنيف الصنف.'","-- ---------------------------------------------------------------------------\r\n-- 8.3 post_purchase_invoice\r\n--\r\n-- منقول حرفيًا من\r\n--   20261203000000_post_purchase_invoices_to_ledger.sql\r\n-- مع التغيير الواحد نفسه على فرع طريقة الدفع. وتصنيف البضاعة مقابل المصروف حسب\r\n-- stock_effect، وضريبة المدخلات القابلة للاسترداد على 1316، وpartner_id المورد\r\n-- على سطر الذمة — كلها بلا مساس.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.post_purchase_invoice(p_invoice_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_inv     record;\r\n  v_existing uuid;\r\n  v_entry   uuid;\r\n  v_lines   jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  v_owed     numeric := 0;\r\n  r         record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')\r\n          OR public.has_role(v_user,'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may post a purchase invoice';\r\n  END IF;\r\n\r\n  SELECT * INTO v_inv FROM public.purchase_invoices WHERE id = p_invoice_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Purchase invoice not found';\r\n  END IF;\r\n\r\n  IF v_inv.status IN ('draft','cancelled') THEN\r\n    RAISE EXCEPTION 'Purchase % is % - only confirmed, paid or partial invoices post',\r\n      v_inv.invoice_number, v_inv.status;\r\n  END IF;\r\n\r\n  IF v_inv.paid < 0 THEN\r\n    RAISE EXCEPTION 'Purchase % carries a negative payment (%). A supplier return is a return document, not a negative payment.',\r\n      v_inv.invoice_number, v_inv.paid;\r\n  END IF;\r\n  IF v_inv.paid > v_inv.total THEN\r\n    RAISE EXCEPTION 'Purchase % was paid % against a total of %. Fix the invoice before posting - a payment cannot exceed the invoice.',\r\n      v_inv.invoice_number, v_inv.paid, v_inv.total;\r\n  END IF;\r\n\r\n  SELECT id INTO v_existing\r\n    FROM public.journal_entries\r\n   WHERE source_type = 'purchase_invoice' AND source_id = p_invoice_id\r\n     AND status <> 'REVERSED';\r\n  IF v_existing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'Purchase % has already been posted to the ledger', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- ── الحساب من الكتالوج بدل القائمة المضمّنة ─────────────────────────────\r\n  v_cash_acct := public.ledger_account_code_for_payment_method(v_inv.payment_method);\r\n\r\n  v_owed := greatest(v_inv.total - v_inv.paid, 0);\r\n\r\n  -- ── what was acquired ──\r\n  FOR r IN\r\n    SELECT p.item_class,\r\n           coalesce(it.stock_effect, 'NONE') AS effect,\r\n           sum(it.total)                     AS amount,\r\n           sum(it.tax)                       AS line_tax\r\n      FROM public.purchase_invoice_items it\r\n      JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n     GROUP BY p.item_class, coalesce(it.stock_effect, 'NONE')\r\n    HAVING sum(it.total) <> 0 OR sum(it.tax) <> 0\r\n  LOOP\r\n    IF r.amount <> 0 THEN\r\n      -- البضاعة التي دخلت المخزون تذهب إلى حساب مخزون فئتها؛ وأي شيء آخر مصروف،\r\n      -- لا زيادة في المخزون.\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', CASE\r\n          WHEN r.effect <> 'STOCK_RECEIPT' THEN '5911'\r\n          ELSE CASE r.item_class\r\n                 WHEN 'RAW_MATERIAL' THEN '1311'\r\n                 WHEN 'BY_PRODUCT'   THEN '1314'\r\n                 WHEN 'FINISHED_GOOD' THEN '1313'\r\n                 ELSE '1315' END END,\r\n        'debit', round(r.amount, 2),\r\n        'memo', CASE WHEN r.effect <> 'STOCK_RECEIPT'\r\n                     THEN 'مصروف مشتريات ' || r.item_class\r\n                     ELSE 'شراء ' || r.item_class END);\r\n    END IF;\r\n\r\n    -- ضريبة المدخلات قابلة للاسترداد فهي أصل بحد ذاتها.\r\n    IF r.line_tax <> 0 THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '1316', 'debit', round(r.line_tax, 2),\r\n        'memo', 'ضريبة مدخلات قابلة للاسترداد');\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- فاتورة مشتريات تحمل ضريبة في رأسها لا في أسطرها تبقى ضريبتها قائمة.\r\n  IF v_inv.tax <> 0 AND not exists (\r\n       SELECT 1 FROM public.purchase_invoice_items it\r\n        WHERE it.invoice_id = p_invoice_id AND it.tax <> 0) THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1316', 'debit', round(v_inv.tax, 2),\r\n      'memo', 'ضريبة مدخلات قابلة للاسترداد');\r\n  END IF;\r\n\r\n  IF jsonb_array_length(v_lines) = 0 THEN\r\n    RAISE EXCEPTION 'Purchase % has nothing to post - its lines are empty or zero',\r\n      v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- ── what was paid and what is owed ──\r\n  IF v_owed > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2111', 'credit', round(v_owed, 2),\r\n      'memo', 'مستحق للمورد',\r\n      'partner_type', 'supplier',\r\n      'partner_id', v_inv.supplier_id);\r\n  END IF;\r\n\r\n  IF v_inv.paid > 0 AND v_cash_acct IS NOT NULL THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', v_cash_acct, 'credit', round(v_inv.paid, 2),\r\n      'memo', 'سداد للمورد');\r\n  END IF;\r\n\r\n  v_entry := public.create_journal_entry(\r\n    'فاتورة مشتريات ' || v_inv.invoice_number,\r\n    v_inv.created_at::date,\r\n    'purchase_invoice', p_invoice_id, true, v_lines);\r\n\r\n  RETURN v_entry;\r\nEND $$","REVOKE ALL ON FUNCTION public.post_purchase_invoice(uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.post_purchase_invoice(uuid) TO authenticated, service_role","COMMENT ON FUNCTION public.post_purchase_invoice(uuid) IS\r\n  'يرحّل فاتورة مشتريات: مخزون/مصروف + ضريبة مدخلات، مقابل النقدية أو ذمم الموردين. '\r\n  'حساب الدفع يأتي من كتالوج طرق الدفع لا من قائمة مضمّنة.'","-- ============================================================================\r\n-- 9. عرض تقارير — أسماء الطرق تأتي من الكتالوج لا من CASE\r\n--\r\n-- دالة قراءة واحدة كي لا تعيد الكشوف والتقارير والتصدير بناء خريطة تسميات كلٌّ\r\n-- على حدة. تُعيد معرّف الكتالوج، والاسمين العربي والإنجليزي، وعائلة الحساب، لأي\r\n-- قيمة مخزّنة بما فيها التاريخية.\r\n-- ============================================================================\r\nCREATE OR REPLACE FUNCTION public.payment_method_catalog_view()\r\nRETURNS TABLE (\r\n  id                  text,\r\n  name_ar             text,\r\n  name_en             text,\r\n  icon_key            text,\r\n  ledger_kind         text,\r\n  default_account_code text,\r\n  is_credit_term      boolean,\r\n  is_active           boolean,\r\n  sort_order          integer,\r\n  allowed_contexts    text[],\r\n  -- طبقة المنشأة، مدموجة كي تُبلغ طريقة غير مضبوطة عن افتراضياتها بدل قيم NULL\r\n  -- تحتاج التقارير إلى معالجة خاصة.\r\n  enabled             boolean,\r\n  effective_sort_order integer,\r\n  effective_contexts  text[],\r\n  is_configured       boolean\r\n)\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT\r\n    m.id,\r\n    m.name_ar,\r\n    m.name_en,\r\n    m.icon_key,\r\n    m.ledger_kind,\r\n    m.default_account_code,\r\n    m.is_credit_term,\r\n    m.is_active,\r\n    m.sort_order,\r\n    m.allowed_contexts,\r\n    coalesce(s.enabled, true),\r\n    coalesce(s.sort_order, m.sort_order),\r\n    CASE\r\n      WHEN coalesce(cardinality(s.enabled_contexts), 0) > 0\r\n        THEN s.enabled_contexts\r\n      ELSE m.allowed_contexts\r\n    END,\r\n    (s.payment_method_id IS NOT NULL)\r\n  FROM public.payment_methods m\r\n  LEFT JOIN public.payment_method_settings s ON s.payment_method_id = m.id\r\n  ORDER BY coalesce(s.sort_order, m.sort_order), m.id;\r\n$$","COMMENT ON FUNCTION public.payment_method_catalog_view() IS\r\n  'عرض موحّد لطرق الدفع مع تخصيص المنشأة، لاستخدامه في التقارير والتصدير دون خرائط تسميات محلية.'","REVOKE ALL ON FUNCTION public.payment_method_catalog_view() FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.payment_method_catalog_view() TO authenticated, service_role","-- ============================================================================\r\n-- 10. إلى أين ذهبت التعريفات القديمة\r\n--\r\n-- الترحيلات أدناه صارت **مُستبدَلة** وتُركت في مكانها للتاريخ فقط — ولا تُعدَّل\r\n-- أبدًا، لأن إعادة كتابة ترحيل مُطبَّق تجعل المخطط يعتمد على ترتيب تشغيل الملفات\r\n-- الذي صادف حدوثه:\r\n--\r\n--   20260706120000  ALTER TYPE payment_method ADD VALUE 'mobile_money'\r\n--   20260706121000  تكرار لما سبق (مسار بذرة reset)\r\n--   20260707021000  تكرار لما سبق (مسار بذرة yemen)\r\n--        -> القسم 1 يوسّع النوع إلى المجموعة الكاملة داخل المعاملة.\r\n--\r\n--   20260801090000  حرّاس create_sale / record_customer_payment الحرفية\r\n--        -> القسمان 7.1 و 7.4 يستبدلان كليهما بـ\r\n--           resolve_writable_payment_method.\r\n--\r\n--   20260928000000  محرّك الدفع المجزأ المُستبدَل، وحارس جزء حرفي\r\n--        -> استُبدل بـ 20260929030000، الذي يستبدله القسم 7.3 الآن.\r\n--\r\n--   20260929030000  create_sale (ثلاث نسخ)، create_sales_return\r\n--        -> الأقسام 7.1-7.3 و 7.5.\r\n--\r\n--   20260929040000  create_purchase_return\r\n--        -> القسم 7.6.\r\n--\r\n--   20261202000000  post_sales_invoice، فرع طريقة الدفع\r\n--   20261202000100  الفرع نفسه، رفض الدفع الزائد\r\n--   20261202000200  الفرع نفسه، تصحيح مدين النقد\r\n--   20261203000000  post_purchase_invoice، الفرع نفسه\r\n--        -> القسمان 8.2 و 8.3.\r\n--\r\n-- لماذا لا تُحذف: كل واحد منها يُنشئ أيضًا فهارس و views وقيودًا ودوالًا مساعدة\r\n-- لا يعيد هذا الملف إنشاءها. وحذفها كان سيُسقط تلك الكائنات على قاعدة جديدة بينما\r\n-- يبقى الإنتاج بلا مساس — وهو بالضبط نوع الانحراف الذي يجعل المخطط عصيّ الفهم.\r\n-- واستبدال التعريفات هنا أسلم وكافٍ: بعد هذا الترحيل، لا دالة حيّة تحوي قائمة\r\n-- طرق دفع مضمّنة.\r\n-- ============================================================================\r\n\r\n-- ============================================================================\r\n-- القسم الثاني — تفويض المستأجر\r\n--\r\n-- امتداد مباشر لما سبق لا يعمل منفصلاً عنه: يعدّل الجداول التي أُنشئت\r\n-- أعلاه، ويعرّف الدوال التي تحتاجها. لذلك دُمج الملفان (16 و17 في خطة\r\n-- الدمج) في ترحيل واحد باسم 16.\r\n--\r\n-- المصدر: origin/main — 20261208000001_payment_methods_tenant_authoring.sql\r\n-- ============================================================================\r\n\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 1. أعمدة المصدر والتأليف على الكتالوج.\r\n-- ---------------------------------------------------------------------------\r\nALTER TABLE public.payment_methods\r\n  ADD COLUMN IF NOT EXISTS created_by       uuid REFERENCES auth.users(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS is_system        boolean NOT NULL DEFAULT true,\r\n  ADD COLUMN IF NOT EXISTS legacy_id        text,\r\n  ADD COLUMN IF NOT EXISTS default_ledger_kind text,\r\n  -- الاسم العربي كما شحنه المطورون بالضبط. يُكتب **فقط** في البذرة\r\n  -- (seeds/01_system/08_payment_methods.sql) ولا يُحدَّث بعدها أبدًا، فيجد\r\n  -- `payment_method_catalog_view().is_renamed` أساسًا حقيقيًا للمقارنة. بلاه\r\n  -- كان العلم لا يقارن إلا الصف بنفسه، فكان false دائمًا.\r\n  ADD COLUMN IF NOT EXISTS shipped_name_ar  text","COMMENT ON COLUMN public.payment_methods.shipped_name_ar IS\r\n  'الاسم العربي كما شحنه المطورون في البذرة. لا يُعدَّل بعد الزرع، ويُقارَن به name_ar لمعرفة إن كانت المنشأة قد أعادت التسمية.'","COMMENT ON COLUMN public.payment_methods.created_by IS\r\n  'من أنشأ الطريقة. NULL = أنشأها المطورون في ترحيل، لا منشأة.'","COMMENT ON COLUMN public.payment_methods.is_system IS\r\n  'true = صف يملكه المطورون. لا تحذفه منشأة، ولا يغيّر أحدٌ نوع حسابه.'","COMMENT ON COLUMN public.payment_methods.legacy_id IS\r\n  'القيمة المخزّنة التي تُسوّى عليها الطريقة. للصفوف النظامية = legacy_ids[1]، وللصفوف التي أنشأتها منشأة يختارها المنشئ من ضمن الـEnum.'","COMMENT ON COLUMN public.payment_methods.default_ledger_kind IS\r\n  'نوع الحساب الذي اقترحته المنشأة عند الإنشاء. للعرض والتشخيص فقط؛ المحرّك يقرأ ledger_kind.'","-- 1.1 التعبئة الأولى: كل صف قائم هو صف مطورين.\r\n--\r\n--     القيمة المخزّنة هي legacy_ids[1] عندما يُصرّح الصف بها. والمؤسسة المسمّاة\r\n--     التي يشحنها الكتالوج الموحّد تحمل عمدًا قائمة legacy **فارغة** — بنك\r\n--     الكريمي وجيب يتشاركان قيمة `bank_transfer` / `mobile_money` العامة بدل\r\n--     إعادة تعريفها — فالسقوط إلى 'cash' هنا كان سيحوّل بنكًا إلى الصندوق ويجعل\r\n--     `payment_method_legacy_id('kuraimi_bank')` تعيد 'cash'.\r\n--\r\n--     فالبديل الصحيح هو **عائلة الحساب**، وهي ما يعتبرها محرّك الترحيل مرجعًا\r\n--     أصلًا، ثم 'cash' فقط لصف لا يملك أيهما. وهذا يطابق CASE الاحتياطي داخل\r\n--     `payment_method_legacy_id` فلا يتناقض العمود والدالة.\r\n--\r\n--     ⚠️ هذا مكتوب CASE غير مشروط، لا `coalesce(legacy_id, …)`. فالعمود يبدأ NULL\r\n--     على قاعدة جديدة، لكن على أي قاعدة شغّلها سابقًا وأعطته قيمة — أو حملت\r\n--     DEFAULT 'cash' القديم — سيجد `coalesce` قيمة غير NULL **ويتوقف**، فيُبقي كل\r\n--     صف بنك ومحفظة مخزَّنًا 'cash' بصمت. وهذا بالضبط الخلل الذي يوثّقه تقرير\r\n--     `MIGRATION_16_REVIEW.md` §2: المستند يقول بنك والدفتر يقول صندوق، فتصير\r\n--     التسوية مستحيلة. أما CASE فيعيد اشتقاق القيمة من المصدر المرجعي كل مرة،\r\n--     فيتقارب تشغيل متكرر إلى الجواب الصحيح نفسه بدل أن يحفظ الفساد الذي جاء\r\n--     لإصلاحه.\r\n--\r\n--     واختير WHERE بحيث لا تُلمس إلا الصفوف التي تخالف قيمتها المخزّنة هذا\r\n--     الاشتقاق. ولا يجب أن يرى trigger `payment_methods_authoring_guard`\r\n--     (القسم 3) تحديثًا بلا أثر هنا، ويُترك اختيار صف المنشأة الصريح كما هو لأن\r\n--     CASE يقرأ `legacy_ids[1]` أولًا.\r\nUPDATE public.payment_methods\r\n   SET is_system = true,\r\n       legacy_id = CASE\r\n         -- 1. القيمة التي يصرّح بها الصف. صفوف المطورين التي تسمّي قيمة ENUM\r\n         --    تحملها هنا؛ وصف المنشأة يحمل اختيارها الخاص.\r\n         WHEN nullif(legacy_ids[1], '') IS NOT NULL THEN legacy_ids[1]\r\n         -- 2. عائلة الحساب، وهي ما يثق به محرّك الترحيل.\r\n         WHEN ledger_kind = 'BANK'   THEN 'bank_transfer'\r\n         WHEN ledger_kind = 'WALLET' THEN 'mobile_money'\r\n         WHEN ledger_kind = 'CARD'   THEN 'card'\r\n         WHEN ledger_kind = 'CREDIT' THEN 'credit'\r\n         WHEN ledger_kind = 'CASH'   THEN 'cash'\r\n         -- 3. صف لا يملك أيهما. هنا يقع 'OTHER' (الطريقة الرمزية split).\r\n         ELSE coalesce(nullif(legacy_id, ''), 'cash')\r\n       END\r\n WHERE is_system IS DISTINCT FROM true\r\n    -- صف تستطيع عائلته إنتاج قيمة لكن قيمته المخزّنة تخالفها: الفساد الذي\r\n    -- وُجد هذا القسم لإصلاحه.\r\n    OR (\r\n      ledger_kind IN ('BANK','WALLET','CARD','CREDIT','CASH')\r\n      AND legacy_id IS DISTINCT FROM CASE ledger_kind\r\n            WHEN 'BANK'   THEN 'bank_transfer'\r\n            WHEN 'WALLET' THEN 'mobile_money'\r\n            WHEN 'CARD'   THEN 'card'\r\n            WHEN 'CREDIT' THEN 'credit'\r\n            ELSE coalesce(nullif(legacy_ids[1], ''), 'cash')\r\n          END\r\n    )","-- 1.2 من الآن العمود هو المرجع، فيجب ألا يغيب أبدًا.\r\n--\r\n--     ⚠️ No `DEFAULT 'cash'` here, and this matters. A column default is applied\r\n--     to any INSERT that omits the column — including `create_tenant_payment_method`\r\n--     if it ever forgets it, and any future seed that adds a row without setting\r\n--     it. The tenant RPC always writes `legacy_id` explicitly, so the default was\r\n--     never needed; but while it existed it also meant §1.1's `coalesce` found a\r\n--     non-NULL 'cash' on a second run and stopped, freezing every bank row as\r\n--     cash — the exact bug MIGRATION_16_REVIEW.md §2 describes. Leaving the\r\n--     default off means \\"forgot to set it\\" fails loudly against the NOT NULL\r\n--     below instead of silently recording a bank as cash.\r\nALTER TABLE public.payment_methods\r\n  ALTER COLUMN legacy_id DROP DEFAULT","UPDATE public.payment_methods SET legacy_id = 'cash' WHERE legacy_id IS NULL","ALTER TABLE public.payment_methods\r\n  ALTER COLUMN legacy_id SET NOT NULL","-- 1.3 لا يجوز أن يحمل إلا قيمة يستطيع النوع تخزينها. وهذا القيد هو ما يجعل\r\n--     كتابة قيمة ترفضها الجداول المالية من طريقة أنشأتها منشأة أمرًا مستحيلًا.\r\nALTER TABLE public.payment_methods\r\n  DROP CONSTRAINT IF EXISTS payment_methods_legacy_id_valid","ALTER TABLE public.payment_methods\r\n  ADD CONSTRAINT payment_methods_legacy_id_valid\r\n  CHECK (legacy_id IN ('cash','card','bank_transfer','credit','mobile_money','split','cheque'))","-- 1.4 لا يجوز أن يستخدم صف منشأة معرّف مطور. و `is_system` هو ما يفصل بينهما،\r\n--     فلا يمكن لطريقة منشأة أن تحجب بنك الكريمي أبدًا.\r\nCREATE INDEX IF NOT EXISTS ix_payment_methods_system\r\n  ON public.payment_methods (is_system, is_active, sort_order)","-- 1.5 الأسماء هي ما يقرأه المشغّل عند الصندوق؛ والفراغ غير مقبول.\r\nALTER TABLE public.payment_methods\r\n  DROP CONSTRAINT IF EXISTS payment_methods_name_ar_present","ALTER TABLE public.payment_methods\r\n  ADD CONSTRAINT payment_methods_name_ar_present\r\n  CHECK (btrim(coalesce(name_ar, '')) <> '')","-- 1.6 صف المنشأة لا تاريخ له يُحفظ، فقد لا يحمل قائمة legacy أبدًا؛ ويبقى العمود\r\n--     لصفوف المطورين التي تحتاجها.\r\nALTER TABLE public.payment_methods\r\n  ALTER COLUMN legacy_ids SET DEFAULT ARRAY[]::text[]","-- 1.7 مفتاح أيقونة واحد لكل صف، من السجل المضمَّن. وصف مطور بمفتاح لا تعرفه\r\n--     حزمة العميل يبقى يُعرض عبر بديل عائلة الحساب، فهذا إرشاد لا جدار.\r\nCOMMENT ON COLUMN public.payment_methods.icon_key IS\r\n  'مفتاح أيقونة مركزي يُحلّ إلى مكوّن داخل الحزمة (ليس رابطاً). قائمة المفاتيح المتاحة للعميل في src/lib/payments/payment-methods.ts.'","-- ---------------------------------------------------------------------------\r\n-- 2. أعمدة الملكية على إعداد المنشأة، ليعرف التعديل مَن صاحبه ومن أين جاء.\r\n--    و`updated_at` / `updated_by` موجودان أصلًا.\r\n-- ---------------------------------------------------------------------------\r\nALTER TABLE public.payment_method_settings\r\n  ADD COLUMN IF NOT EXISTS created_by  uuid REFERENCES auth.users(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS updated_by_platform boolean NOT NULL DEFAULT false","COMMENT ON COLUMN public.payment_method_settings.updated_by_platform IS\r\n  'true = آخر تعديل جاء من مسؤول منصة (سوبر أدمن)، لا من المنشأة نفسها.'","-- ---------------------------------------------------------------------------\r\n-- 3. الحارس — ما يجوز لإعادة التسمية أن تغيّره وما لا يجوز.\r\n--\r\n--    trigger لا سياسة، لأن القاعدة عن **أي أعمدة** تغيّرت، و RLS لا ترى الصف\r\n--    OLD. ويعمل لكل كاتب، بما فيه تحديث PostgREST مباشر من مالك، وهو بالضبط\r\n--    الحالة التي تتركها قاعدة مقصورة على الواجهة مفتوحة.\r\n--\r\n--    اقرأ الفرعين جملة واحدة:\r\n--      «اسمٌ وأيقونة: نعم. حسابٌ وقيمةٌ مخزّنة: لا، إلا في صفٍّ أنشأته أنت.»\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.payment_methods_authoring_guard()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\nBEGIN\r\n  -- مشغّل الترحيلات ومفتاح خدمة المنصة لا يقيّدهما هذا الحكم: فهما المطورون،\r\n  -- وهذا الـtrigger موجود أصلًا ليتسنّى لهما تغيير البذرة.\r\n  IF v_user IS NULL OR public.is_platform_superadmin(v_user) THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN\r\n    RAISE EXCEPTION 'لا تملك صلاحية تعديل طرق الدفع'\r\n      USING ERRCODE = 'insufficient_privilege';\r\n  END IF;\r\n\r\n  -- 3.1 صف المطور ليس ملك المنشأة لتثريه. يمكنها إعادة تسميته وتغيير أيقونته؛\r\n  --     وكل عمود يقرّر كيف تتحرّك الأموال مجمّد.\r\n  IF OLD.is_system THEN\r\n    IF NEW.ledger_kind   IS DISTINCT FROM OLD.ledger_kind\r\n       OR NEW.legacy_id  IS DISTINCT FROM OLD.legacy_id\r\n       OR NEW.is_system  IS DISTINCT FROM OLD.is_system\r\n       OR NEW.is_active  IS DISTINCT FROM OLD.is_active\r\n       OR NEW.legacy_ids IS DISTINCT FROM OLD.legacy_ids\r\n       OR NEW.id         IS DISTINCT FROM OLD.id THEN\r\n      RAISE EXCEPTION\r\n        'لا يمكن تغيير طبيعة طريقة دفع نظامية (%) — يمكن تعديل الاسم والأيقونة والترتيب فقط',\r\n        OLD.id\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  -- 3.2 A tenant row is theirs, but its shape is still the platform's.\r\n  IF NEW.is_system IS DISTINCT FROM OLD.is_system THEN\r\n    RAISE EXCEPTION 'لا يمكن ترقية طريقة دفع إلى نظامية من الواجهة'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  IF NEW.ledger_kind NOT IN ('CASH','BANK','WALLET','CARD','OTHER') THEN\r\n    RAISE EXCEPTION 'نوع الحساب \\"%\\" غير متاح لطريقة دفع تنشئها المنشأة', NEW.ledger_kind\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND $$","COMMENT ON FUNCTION public.payment_methods_authoring_guard() IS\r\n  'يسمح للمنشأة بتعديل الاسم والأيقونة، ويمنعها من تغيير نوع الحساب أو القيمة المخزّنة لطريقة نظامية.'","DROP TRIGGER IF EXISTS payment_methods_authoring_guard ON public.payment_methods","CREATE TRIGGER payment_methods_authoring_guard\r\n  BEFORE UPDATE ON public.payment_methods\r\n  FOR EACH ROW EXECUTE FUNCTION public.payment_methods_authoring_guard()","-- 3.3 The same sentence for DELETE: a tenant method may be removed by its owner,\r\n--     a developer method never. `ON DELETE CASCADE` on the settings row means\r\n--     the configuration disappears with it — which is correct for a row the\r\n--     business itself created.\r\nCREATE OR REPLACE FUNCTION public.payment_methods_delete_guard()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\nBEGIN\r\n  IF v_user IS NULL OR public.is_platform_superadmin(v_user) THEN\r\n    RETURN OLD;\r\n  END IF;\r\n\r\n  IF OLD.is_system THEN\r\n    RAISE EXCEPTION\r\n      'لا يمكن حذف طريقة دفع نظامية (%) — عطّلها بدلاً من ذلك', OLD.id\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN\r\n    RAISE EXCEPTION 'لا تملك صلاحية حذف طرق الدفع'\r\n      USING ERRCODE = 'insufficient_privilege';\r\n  END IF;\r\n\r\n  RETURN OLD;\r\nEND $$","COMMENT ON FUNCTION public.payment_methods_delete_guard() IS\r\n  'يمنع حذف طريقة نظامية؛ ويقصر حذف طرق المنشأة على المالك أو المدير.'","DROP TRIGGER IF EXISTS payment_methods_delete_guard ON public.payment_methods","CREATE TRIGGER payment_methods_delete_guard\r\n  BEFORE DELETE ON public.payment_methods\r\n  FOR EACH ROW EXECUTE FUNCTION public.payment_methods_delete_guard()","-- 3.4 دفاع متعدد الطبقات: حتى لو وُسّعت سياسة يومًا، لا يمكن لمستدعٍ غير منصة أن\r\n--     يُدرج مباشرةً في الكتالوج. الإدراج يمرّ عبر دالة RPC في القسم 4، التي تختم\r\n--     created_by و is_system = false.\r\nDROP POLICY IF EXISTS \\"payment_methods tenant insert\\" ON public.payment_methods","CREATE POLICY \\"payment_methods tenant insert\\"\r\n  ON public.payment_methods\r\n  FOR INSERT TO authenticated\r\n  WITH CHECK (public.is_platform_superadmin(auth.uid()))","-- 3.5 والحذف عبر PostgREST عمل منصة فقط. وصف المنشأة نفسه يُزال عبر\r\n--     remove_tenant_payment_method()، وهي قابلة للتدقيق وتستطيع الرفض إذا كانت\r\n--     الطريقة قيد الاستخدام.\r\nDROP POLICY IF EXISTS \\"payment_methods platform delete\\" ON public.payment_methods","CREATE POLICY \\"payment_methods platform delete\\"\r\n  ON public.payment_methods\r\n  FOR DELETE TO authenticated\r\n  USING (public.is_platform_superadmin(auth.uid()))","-- 3.6 الـUPDATE يحكمه بالفعل سياسة الموظفين القائمة، ويضيّقه trigger في 3.1 إلى\r\n--     الملكية فوق ذلك. أُعيد إنشاؤه صراحةً هنا ليكون الملف مكتفيًا بذاته على قاعدة\r\n--     أُعيدت تسمية السياسة فيها.\r\nDROP POLICY IF EXISTS \\"payment_methods tenant update\\" ON public.payment_methods","CREATE POLICY \\"payment_methods tenant update\\"\r\n  ON public.payment_methods\r\n  FOR UPDATE TO authenticated\r\n  USING (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager')\r\n         OR public.is_platform_superadmin(auth.uid()))\r\n  WITH CHECK (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager')\r\n              OR public.is_platform_superadmin(auth.uid()))","GRANT INSERT, UPDATE, DELETE ON public.payment_methods TO authenticated","-- ---------------------------------------------------------------------------\r\n-- 4. دوال RPC الثلاث التي تناديها شاشة الإعدادات.\r\n--\r\n--    كل واحدة هي الطريق المسموح الوحيد لعملها، فيكون لكل قاعدة مهمة موضع واحد\r\n--    للإنفاذ وموضع واحد للقراءة.\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- 4.1 هل يملك المستدعي حق التأليف في الكتالوج أصلًا؟\r\nCREATE OR REPLACE FUNCTION public.can_author_payment_methods()\r\nRETURNS boolean\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT public.is_platform_superadmin(auth.uid())\r\n      OR public.has_role(auth.uid(), 'owner')\r\n      OR public.has_role(auth.uid(), 'manager');\r\n$$","COMMENT ON FUNCTION public.can_author_payment_methods() IS\r\n  'هل يملك المستخدم الحالي حق تسمية/أيقنة/إنشاء طرق دفع؟ صاحب المنشأة والمدير وسوبر أدمن المنصة.'","REVOKE ALL ON FUNCTION public.can_author_payment_methods() FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.can_author_payment_methods() TO authenticated, service_role","-- 4.2 التسمية تسمية: قصّها، وحدّدها، وارفض الفارغة. وإبقاء ذلك في دالة واحدة\r\n--     يعني أن الـRPC وأي واجهة مستقبلية لا يمكن أن تختلفا.\r\nCREATE OR REPLACE FUNCTION public.payment_method_clean_label(p_label text)\r\nRETURNS text\r\nLANGUAGE sql SET search_path = public\r\nIMMUTABLE\r\nAS $$\r\n  SELECT nullif(btrim(coalesce(p_label, '')), '');\r\n$$","COMMENT ON FUNCTION public.payment_method_clean_label(text) IS\r\n  'تطبيع تسمية طريقة الدفع: قصّ الفراغات وإرجاع NULL للنص الفارغ.'","REVOKE ALL ON FUNCTION public.payment_method_clean_label(text) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.payment_method_clean_label(text) TO authenticated, service_role","-- 4.3 إعادة التسمية / إعادة الأيقنة.\r\n--\r\n--     تُعيد الحالة الجديدة عن قصد ليؤكّدها المستدعي، بدل الثقة بأن التحديث طابق\r\n--     صفًا.\r\nCREATE OR REPLACE FUNCTION public.update_payment_method_identity(\r\n  p_id        text,\r\n  p_name_ar   text DEFAULT NULL,\r\n  p_name_en   text DEFAULT NULL,\r\n  p_icon_key  text DEFAULT NULL\r\n)\r\nRETURNS TABLE (id text, name_ar text, name_en text, icon_key text, is_system boolean)\r\nLANGUAGE plpgsql SET search_path = public\r\nSECURITY INVOKER\r\nAS $$\r\nDECLARE\r\n  v_row       public.payment_methods;\r\n  v_name_ar   text;\r\n  v_name_en   text;\r\n  v_icon_key  text;\r\nBEGIN\r\n  IF NOT public.can_author_payment_methods() THEN\r\n    RAISE EXCEPTION 'لا تملك صلاحية تعديل طرق الدفع — هذه الصلاحية لصاحب المنشأة والمدير وسوبر أدمن المنصة'\r\n      USING ERRCODE = 'insufficient_privilege';\r\n  END IF;\r\n\r\n  -- `payment_methods.id` مُؤهّل عن قصد: فـ `id` غير المؤهّل داخل دالة plpgsql\r\n  -- تحمل معامل OUT باسم `id` يُحلّ إلى **المعامل** لا العمود، فيطابق البحث لا شيء\r\n  -- بصمت.\r\n  SELECT * INTO v_row FROM public.payment_methods WHERE public.payment_methods.id = p_id FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'طريقة الدفع \\"%\\" غير موجودة في الكتالوج', p_id\r\n      USING ERRCODE = 'no_data_found';\r\n  END IF;\r\n\r\n  -- تُحلّ القيم الثلاث الجديدة **قبل** التحديث، حتى لا تشير قائمة SET في UPDATE\r\n  -- إلا إلى متغيّرات عادية. فداخل دالة RETURNS TABLE، يكون `name_ar` غير المؤهّل\r\n  -- في تعبير هو معامل OUT — قابل للكتابة في PostgreSQL >= 14 وخطأ قبلها. والإسناد\r\n  -- إلى متغيرات محلية أولًا يجعل الجملة تعني الشيء نفسه على كل نسخة مدعومة.\r\n\r\n  -- لا يجوز أن تُفرِغ إعادة التسمية طريقةً من الصندوق.\r\n  IF p_name_ar IS NOT NULL AND public.payment_method_clean_label(p_name_ar) IS NULL THEN\r\n    RAISE EXCEPTION 'اسم طريقة الدفع لا يمكن أن يكون فارغاً'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  v_name_ar  := coalesce(public.payment_method_clean_label(p_name_ar), v_row.name_ar);\r\n  v_name_en  := CASE\r\n                  WHEN p_name_en IS NULL THEN v_row.name_en\r\n                  ELSE public.payment_method_clean_label(p_name_en)\r\n                END;\r\n  v_icon_key := coalesce(public.payment_method_clean_label(p_icon_key), v_row.icon_key);\r\n\r\n  UPDATE public.payment_methods m\r\n     SET name_ar    = v_name_ar,\r\n         name_en    = v_name_en,\r\n         icon_key   = v_icon_key,\r\n         updated_at = now()\r\n   WHERE m.id = p_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, payload)\r\n  VALUES (\r\n    auth.uid(),\r\n    'payment_method.identity.updated',\r\n    'payment_method',\r\n    jsonb_build_object(\r\n      'id', p_id,\r\n      'before', jsonb_build_object(\r\n        'name_ar', v_row.name_ar, 'name_en', v_row.name_en, 'icon_key', v_row.icon_key),\r\n      'after',  jsonb_build_object(\r\n        'name_ar', v_name_ar, 'name_en', v_name_en, 'icon_key', v_icon_key),\r\n      'by_platform', public.is_platform_superadmin(auth.uid())\r\n    ));\r\n\r\n  RETURN QUERY\r\n    SELECT m.id::text, m.name_ar::text, m.name_en::text, m.icon_key::text, m.is_system::boolean\r\n    FROM public.payment_methods m\r\n    WHERE m.id = p_id;\r\nEND $$","COMMENT ON FUNCTION public.update_payment_method_identity(text, text, text, text) IS\r\n  'تعديل اسم طريقة الدفع وأيقونتها. لا يمسّ نوع الحساب ولا القيمة المخزّنة، ولا يسمح بتسمية فارغة.'","REVOKE ALL ON FUNCTION public.update_payment_method_identity(text, text, text, text) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.update_payment_method_identity(text, text, text, text) TO authenticated, service_role","-- 4.4 ADD a method the developers did not ship.\r\n--\r\n--     The id is DERIVED from the Arabic name and de-duplicated, never taken\r\n--     from the browser: an id is a stable key that migrations and reports will\r\n--     address forever, so it must not be something a client can choose or\r\n--     predictably collide with بنك الكريمي.\r\nCREATE OR REPLACE FUNCTION public.create_tenant_payment_method(\r\n  p_name_ar       text,\r\n  p_name_en       text,\r\n  p_icon_key      text,\r\n  p_legacy_id     text,\r\n  p_ledger_kind   text,\r\n  p_contexts      text[] DEFAULT NULL,\r\n  p_requires_reference boolean DEFAULT true\r\n)\r\nRETURNS text\r\nLANGUAGE plpgsql SET search_path = public\r\nSECURITY INVOKER\r\nAS $$\r\nDECLARE\r\n  v_user        uuid := auth.uid();\r\n  v_name        text;\r\n  v_name_en     text;\r\n  v_legacy      text;\r\n  v_kind        text;\r\n  v_contexts    text[];\r\n  v_base        text;\r\n  v_next_order  integer;\r\n  v_auto_id     text;\r\nBEGIN\r\n  IF NOT public.can_author_payment_methods() THEN\r\n    RAISE EXCEPTION 'لا تملك صلاحية إضافة طرق دفع — هذه الصلاحية لصاحب المنشأة والمدير وسوبر أدمن المنصة'\r\n      USING ERRCODE = 'insufficient_privilege';\r\n  END IF;\r\n\r\n  v_name := public.payment_method_clean_label(p_name_ar);\r\n  IF v_name IS NULL THEN\r\n    RAISE EXCEPTION 'اسم طريقة الدفع مطلوب' USING ERRCODE = 'check_violation';\r\n  END IF;\r\n  IF length(v_name) > 60 THEN\r\n    RAISE EXCEPTION 'اسم طريقة الدفع طويل جداً (الحد 60 حرفاً)'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n  v_name_en := public.payment_method_clean_label(p_name_en);\r\n  IF v_name_en IS NOT NULL AND length(v_name_en) > 60 THEN\r\n    RAISE EXCEPTION 'الاسم الإنجليزي طويل جداً (الحد 60 حرفاً)'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  -- القيمة المخزّنة. لا يجوز للمنشأة إدخال قيمة لا يحملها النوع، ولا اختيار\r\n  -- 'split' — فتلك القيمة تعني «سُدّدت بأكثر من وسيلة» وتكتبها محرّك الدفع المجزأ،\r\n  -- لا يختارها مشغّل.\r\n  v_legacy := lower(btrim(coalesce(p_legacy_id, '')));\r\n  IF v_legacy NOT IN ('cash','card','bank_transfer','mobile_money','cheque') THEN\r\n    RAISE EXCEPTION\r\n      'القيمة المخزّنة \\"%\\" غير متاحة لطريقة تنشئها المنشأة (المتاح: cash, card, bank_transfer, mobile_money, cheque)',\r\n      coalesce(p_legacy_id, '(فارغ)')\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  -- عائلة الحساب تتبع القيمة المخزّنة. واشتقاقها بدل قبولها يعني أن المنشأة لا\r\n  -- تستطيع جعل محفظة تُرحّل إلى الصندوق: فالمزاوجة حقيقة عن النوع لا تفضيل.\r\n  --\r\n  -- و`p_ledger_kind` **مُتجاهَل** عن قصد. هو موجود في التوقيع ليتمكن أدوات المنصة\r\n  -- من تمرير إرشاد، لكن مستدعيًا يرسل 'CASH' لمحفظة لا يحصل عليه: فـ CASE أدناه\r\n  -- هو الجواب الوحيد.\r\n  v_kind := CASE v_legacy\r\n              WHEN 'cash'         THEN 'CASH'\r\n              WHEN 'card'         THEN 'CARD'\r\n              WHEN 'bank_transfer' THEN 'BANK'\r\n              WHEN 'cheque'       THEN 'BANK'\r\n              WHEN 'mobile_money' THEN 'WALLET'\r\n            END;\r\n\r\n  -- الأقسام افتراضيًا كل ما يمكن للعائلة أن تظهر فيه بشكل مشروع. و`credit` ليس\r\n  -- في القائمة عن قصد: فطريقة المنشأة وسيلة **تحصيل** أموال، و«آجل» ليست كذلك.\r\n  v_contexts := coalesce(\r\n    p_contexts,\r\n    ARRAY['pos','sales','purchases','expenses','customer_collection']::text[]\r\n  );\r\n  IF NOT (v_contexts <@ ARRAY[\r\n    'pos','sales','purchases','expenses','customer_collection',\r\n    'sales_returns','purchase_returns']::text[]) THEN\r\n    RAISE EXCEPTION 'أحد الأقسام المختارة غير معروف'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  -- معرّف ثابت مقروء مشتق من الاسم. والعربي يُنقل إلى slug؛ وأي شيء لا يترك\r\n  -- محارف صالحة يسقط إلى بادئة، فيبقى المعرّف غير فارغ أبدًا ومطابقًا لقيد الجدول\r\n  -- دائمًا.\r\n  --\r\n  -- وإن لم يُمرَّر اسم إنجليزي، يُؤخذ الـslug من الكتالوج **المولَّد** من المعرّف\r\n  -- العربي، لا من النص العربي الحرفي: فقيد الجدول يشترط `id = lower(btrim(id))`،\r\n  -- والعربية بلا حالة أحرف، فقاعدة عربية خام تنجح اليوم وتنكسر لحظة إضافة كلمة\r\n  -- لاتينية.\r\n  v_base := regexp_replace(lower(coalesce(v_name_en, '')), '[^a-z0-9]+', '_', 'g');\r\n  v_base := btrim(coalesce(v_base, ''), '_');\r\n\r\n  IF v_base = '' THEN\r\n    SELECT regexp_replace(lower(m.id), '[^a-z0-9]+', '_', 'g')\r\n      INTO v_base\r\n    FROM public.payment_methods m\r\n    WHERE m.id = public.payment_method_resolve_id(v_legacy);\r\n\r\n    v_base := btrim(coalesce(v_base, ''), '_');\r\n  END IF;\r\n\r\n  IF v_base = '' THEN\r\n    v_base := 'tenant_' || nullif(btrim(v_legacy, '_'), '');\r\n  END IF;\r\n\r\n  -- معرّف واحد يُسنَد قبل الـINSERT، فلا تشير الجملة أدناه إلا إلى متغيرات محلية\r\n  -- عادية. وترك PostgreSQL يختار اللاحقة الحرة التالية ضمنيًا ممكن، لكنه يجعل\r\n  -- تفرّد `id` معتمدًا على صورة استعلام فرعي لا على حلقة على الجدول الحيّ.\r\n  v_auto_id := v_base;\r\n  WHILE EXISTS (SELECT 1 FROM public.payment_methods m WHERE m.id = v_auto_id) LOOP\r\n    v_auto_id := v_base || '_' || (2 + (SELECT count(*) FROM public.payment_methods m\r\n                                       WHERE m.id LIKE v_base || '\\\\_%'))::text;\r\n  END LOOP;\r\n\r\n  -- يُرتَّب بعد آخر صف قائم، فتظهر الطريقة المضافة حديثًا في نهاية ترتيب المشغّل\r\n  -- لا في وسطه.\r\n  SELECT coalesce(max(m.sort_order), 100) + 10\r\n    INTO v_next_order\r\n  FROM public.payment_methods m;\r\n\r\n  INSERT INTO public.payment_methods (\r\n    id, name_ar, name_en, icon_key, is_active, sort_order, allowed_contexts,\r\n    ledger_kind, default_account_code, is_credit_term, requires_reference,\r\n    legacy_ids, legacy_id, default_ledger_kind, is_system, created_by, notes\r\n  ) VALUES (\r\n    v_auto_id,\r\n    v_name,\r\n    v_name_en,\r\n    coalesce(public.payment_method_clean_label(p_icon_key), 'wallet'),\r\n    true,\r\n    v_next_order,\r\n    v_contexts,\r\n    v_kind,\r\n    public.payment_method_ledger_account(v_legacy),\r\n    false,\r\n    coalesce(p_requires_reference, true),\r\n    ARRAY[]::text[],\r\n    v_legacy,\r\n    v_kind,\r\n    false,\r\n    v_user,\r\n    'طريقة دفع أنشأتها المنشأة.'\r\n  );\r\n\r\n  -- صف في الإعدادات أيضًا، فتصير الطريقة الجديدة قابلة للتعديل فورًا وتحمل\r\n  -- الأقسام نفسها التي حصل عليها صف الكتالوج.\r\n  INSERT INTO public.payment_method_settings (\r\n    payment_method_id, enabled, sort_order, enabled_contexts, created_by\r\n  )\r\n  SELECT m.id, true, m.sort_order, m.allowed_contexts, v_user\r\n  FROM public.payment_methods m\r\n  WHERE m.id = v_auto_id\r\n  ON CONFLICT (payment_method_id) DO NOTHING;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, payload)\r\n  VALUES (\r\n    v_user, 'payment_method.created', 'payment_method',\r\n    jsonb_build_object(\r\n      'id', v_auto_id, 'name_ar', v_name, 'legacy_id', v_legacy,\r\n      'ledger_kind', v_kind, 'contexts', v_contexts,\r\n      'by_platform', public.is_platform_superadmin(v_user)\r\n    ));\r\n\r\n  RETURN v_auto_id;\r\nEND $$","COMMENT ON FUNCTION public.create_tenant_payment_method(text, text, text, text, text, text[], boolean) IS\r\n  'إضافة طريقة دفع لم يشحنها المطورون: تُشتق قيمتها المخزّنة ونوع حسابها من اختيار المنشأة، والمعرّف يُولَّد ولا يأتي من المتصفح.'","REVOKE ALL ON FUNCTION public.create_tenant_payment_method(text, text, text, text, text, text[], boolean) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.create_tenant_payment_method(text, text, text, text, text, text[], boolean) TO authenticated, service_role","-- 4.5 REMOVE a tenant method.\r\n--\r\n--     Refuses while documents still reference it: a removal that silently\r\n--     changed how a past invoice labels itself is the one outcome this feature\r\n--     must never produce. The operator is told to disable it instead.\r\nCREATE OR REPLACE FUNCTION public.remove_tenant_payment_method(p_id text)\r\nRETURNS void\r\nLANGUAGE plpgsql SET search_path = public\r\nSECURITY INVOKER\r\nAS $$\r\nDECLARE\r\n  v_row   public.payment_methods;\r\n  v_in_use boolean;\r\n  v_legacy text;\r\nBEGIN\r\n  IF NOT public.can_author_payment_methods() THEN\r\n    RAISE EXCEPTION 'لا تملك صلاحية حذف طرق الدفع'\r\n      USING ERRCODE = 'insufficient_privilege';\r\n  END IF;\r\n\r\n  -- `payment_methods.id` is qualified so it is the COLUMN and not a variable.\r\n  SELECT * INTO v_row FROM public.payment_methods WHERE public.payment_methods.id = p_id FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'طريقة الدفع \\"%\\" غير موجودة', p_id USING ERRCODE = 'no_data_found';\r\n  END IF;\r\n\r\n  IF v_row.is_system THEN\r\n    RAISE EXCEPTION\r\n      'لا يمكن حذف طريقة دفع نظامية (%) — عطّلها أو غيّر تسميتها بدلاً من ذلك', p_id\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  v_legacy := v_row.legacy_id;\r\n\r\n  -- هل القيمة المخزّنة ما زالت على مستند؟ لا تصل إلى هنا إلا طرق المنشأة **نفسها**،\r\n  -- وقيمتها المخزّنة مشتركة مع الطريقة العامة للعائلة نفسها، فهذا سؤال حقيقي فقط\r\n  -- عندما تكون الطريقة جديدة كليًا.\r\n  SELECT EXISTS (\r\n    SELECT 1 FROM public.customer_payment_splits s WHERE s.method::text = v_legacy\r\n    UNION ALL\r\n    SELECT 1 FROM public.sales_returns  r WHERE r.refund_method::text = v_legacy\r\n    UNION ALL\r\n    SELECT 1 FROM public.purchase_returns r WHERE r.refund_method::text = v_legacy\r\n    UNION ALL\r\n    SELECT 1 FROM public.expenses e WHERE e.payment_method::text = v_legacy\r\n  ) INTO v_in_use;\r\n\r\n  IF v_in_use THEN\r\n    RAISE EXCEPTION\r\n      'طريقة الدفع \\"%\\" مستخدمة في مستندات قائمة — عطّلها (Disabled) بدلاً من حذفها', p_id\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, payload)\r\n  VALUES (\r\n    auth.uid(), 'payment_method.deleted', 'payment_method',\r\n    jsonb_build_object(\r\n      'id', p_id, 'name_ar', v_row.name_ar, 'legacy_id', v_legacy,\r\n      'by_platform', public.is_platform_superadmin(auth.uid())\r\n    ));\r\n\r\n  DELETE FROM public.payment_methods WHERE public.payment_methods.id = p_id;\r\nEND $$","COMMENT ON FUNCTION public.remove_tenant_payment_method(text) IS\r\n  'حذف طريقة دفع أنشأتها المنشأة. يرفض الحذف إذا كانت الطريقة مستخدمة في مستندات قائمة، ويطلب تعطيلها بدلاً من ذلك.'","REVOKE ALL ON FUNCTION public.remove_tenant_payment_method(text) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.remove_tenant_payment_method(text) TO authenticated, service_role","-- ---------------------------------------------------------------------------\r\n-- 5. حارس الكتابة ومحرّك الدفتر يجب أن يفهمًا طريقة منشأة معًا.\r\n--\r\n--    `resolve_writable_payment_method` في 20261208000000 تحلّ بالفعل أي معرّف\r\n--    كتالوجي عبر `payment_method_resolve_id`، فمعرّف يُنشأ هنا يعمل بلا تغيير.\r\n--    وما يحتاج إعادة فحص هو **القيمة** التي تُعيدها: فـ `payment_method_legacy_id`\r\n--    تقرأ `legacy_ids[1]` أولًا، وهو فارغ لصف المنشأة، ثم ترجع إلى عائلة الحساب\r\n--    فقط. وذلك الرجوع كان يحوّل «شيكًا» لمنشأة (legacy_id 'cheque'، عائلة BANK)\r\n--    إلى 'bank_transfer' — فيُهمل بصمت القيمة التي اختارتها المنشأة.\r\n--\r\n--    فالدالة الآن تقرأ `legacy_id` الصريح أولًا. ولكل صف قائم مُلئ `legacy_id` من\r\n--    `legacy_ids[1]` سابقًا، فهذا بلا أثر على كل الطرق التاريخية ولا يغيّر السلوك\r\n--    إلا لصفوف المنشأة.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.payment_method_legacy_id(p_id text)\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  WITH norm AS (\r\n    SELECT lower(btrim(coalesce(p_id, ''))) AS v\r\n  ),\r\n  direct AS (\r\n    SELECT n.v\r\n    FROM norm n\r\n    WHERE n.v <> ''\r\n      AND EXISTS (\r\n        SELECT 1 FROM pg_enum e\r\n        JOIN pg_type t ON t.oid = e.enumtypid\r\n        JOIN pg_namespace ns ON ns.oid = t.typnamespace\r\n        WHERE ns.nspname = 'public' AND t.typname = 'payment_method'\r\n          AND e.enumlabel = n.v\r\n      )\r\n  ),\r\n  via_catalog AS (\r\n    SELECT coalesce(\r\n             -- 1. القيمة التي يصرّح بها الصف. هنا تحمل الطريقة التي أنشأتها المنشأة\r\n             --    هويتها.\r\n             nullif(m.legacy_id, ''),\r\n             -- 2. القائمة التاريخية، لأي صف يسبق وجود هذا العمود.\r\n             nullif(m.legacy_ids[1], ''),\r\n             -- 3. عائلة الحساب. ومؤسسة مسمّاة يشحنها الكتالوج الموحّد تحمل قائمة\r\n             --    legacy **فارغة** عن قصد — فهي تتشارك قيمة bank_transfer /\r\n             --    mobile_money العامة — فأدناه جواب حقيقي لها لا بديل مؤقت. وهو\r\n             --    ما يمنع «البنك» من الهبوط على الصندوق أبدًا.\r\n             CASE m.ledger_kind\r\n               WHEN 'BANK'   THEN 'bank_transfer'\r\n               WHEN 'WALLET' THEN 'mobile_money'\r\n               WHEN 'CARD'   THEN 'card'\r\n               WHEN 'CREDIT' THEN 'credit'\r\n               WHEN 'CASH'   THEN 'cash'\r\n               ELSE 'cash'\r\n             END\r\n           ) AS v\r\n    FROM public.payment_methods m, norm n\r\n    WHERE m.id = n.v\r\n  )\r\n  SELECT coalesce(\r\n    (SELECT v FROM direct),\r\n    (SELECT v FROM via_catalog),\r\n    -- لا يصل إلى هنا إلا معرّف لا يعرفه الكتالوج فعلًا. فالكاشير لا يمكنه قبول\r\n    -- مال بطريقة لا نعرفها، فهذا عمدًا النقد العام الأمين بدل NULL في عمود فاتورة.\r\n    'cash'\r\n  );\r\n$$","COMMENT ON FUNCTION public.payment_method_legacy_id(text) IS\r\n  'يحوّل معرّف الكتالوج إلى القيمة التي يفهمها عمود payment_method. يقرأ legacy_id أولاً لدعم الطرق التي أنشأتها المنشأة.'","-- 5.1 `payment_method_ledger_account` تُحلّ عبر `payment_method_resolve_id`،\r\n--     وهي بلا تغيير وتتعامل بالفعل مع معرّف منشأة. أُعيد تأكيدها هنا ليرى قارئ\r\n--     **هذا** الملف المسار كاملاً دون فتح الترحيل السابق.\r\nCREATE OR REPLACE FUNCTION public.payment_method_ledger_account(p_stored text)\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT CASE\r\n    -- يُفحص «آجل» **أولًا**، قبل أي كود إرشادي. فبيعة آجلة لا تحصّل شيئًا، فلا\r\n    -- يوجد سطر نقد أو بنك يُكتب — وبذرة الكتالوج تعطي صف الآجل\r\n    -- default_account_code ('1211') إرشادًا لحساب الذمة. وترك ذلك الكود يفوز\r\n    -- كان يُرحّل حركة بنك/نقد لأموال لم تُستلم قط.\r\n    WHEN m.ledger_kind = 'CREDIT' THEN NULL\r\n    -- الإرشاد الصريح في صف الكتالوج يفوز لكل نقد حقيقي.\r\n    WHEN m.default_account_code IS NOT NULL THEN m.default_account_code\r\n    WHEN m.ledger_kind IN ('BANK','WALLET','CARD') THEN '1111'\r\n    WHEN m.ledger_kind = 'CASH'   THEN '1101'\r\n    ELSE '1101'\r\n  END\r\n  FROM public.payment_methods m\r\n  WHERE m.id = public.payment_method_resolve_id(p_stored);\r\n$$","-- ---------------------------------------------------------------------------\r\n-- 6. The reporting view must expose the new columns, because the settings\r\n--    screen edits names and icons and the reports label historic documents.\r\n-- ---------------------------------------------------------------------------\r\nDROP FUNCTION IF EXISTS public.payment_method_catalog_view()","CREATE OR REPLACE FUNCTION public.payment_method_catalog_view()\r\nRETURNS TABLE (\r\n  id                   text,\r\n  name_ar              text,\r\n  name_en              text,\r\n  icon_key             text,\r\n  ledger_kind          text,\r\n  default_account_code text,\r\n  is_credit_term       boolean,\r\n  is_active            boolean,\r\n  sort_order           integer,\r\n  allowed_contexts     text[],\r\n  legacy_id            text,\r\n  is_system            boolean,\r\n  requires_reference   boolean,\r\n  enabled              boolean,\r\n  effective_sort_order integer,\r\n  effective_contexts   text[],\r\n  is_configured        boolean,\r\n  is_renamed           boolean\r\n)\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT\r\n    m.id,\r\n    m.name_ar,\r\n    m.name_en,\r\n    m.icon_key,\r\n    m.ledger_kind,\r\n    m.default_account_code,\r\n    m.is_credit_term,\r\n    m.is_active,\r\n    m.sort_order,\r\n    m.allowed_contexts,\r\n    m.legacy_id,\r\n    m.is_system,\r\n    m.requires_reference,\r\n    coalesce(s.enabled, true),\r\n    coalesce(s.sort_order, m.sort_order),\r\n    CASE\r\n      WHEN coalesce(cardinality(s.enabled_contexts), 0) > 0\r\n        THEN s.enabled_contexts\r\n      ELSE m.allowed_contexts\r\n    END,\r\n    (s.payment_method_id IS NOT NULL),\r\n    -- صف مطور لم تعد تسميته تطابق اسمه العربي المشحون. يُبلَّغ به لتستطيع شاشة\r\n    -- الإعدادات عرض «معدّلة» وتقديم إعادة تعيين، وهو البديل الأمين لضياع الأصل\r\n    -- بصمت.\r\n    --\r\n    -- يُقارَن بالتسمية المشحونة المخزّنة، لا بالصف نفسه — فمقارنة الصف بنفسه\r\n    -- تكون false دائمًا، وهو ما جعل هذا العلم ميتًا منذ ولادته\r\n    -- (MIGRATION_16_REVIEW.md §3). و COALESCE يجعل صف المنشأة (اسم مشحون NULL)\r\n    -- يُبلّغ false.\r\n    (m.is_system AND m.shipped_name_ar IS NOT NULL\r\n     AND m.name_ar IS DISTINCT FROM m.shipped_name_ar)\r\n  FROM public.payment_methods m\r\n  LEFT JOIN public.payment_method_settings s ON s.payment_method_id = m.id\r\n  ORDER BY coalesce(s.sort_order, m.sort_order), m.id;\r\n$$","COMMENT ON FUNCTION public.payment_method_catalog_view() IS\r\n  'عرض موحّد لطرق الدفع مع تخصيص المنشأة والأسماء المعدّلة، لاستخدامه في التقارير والإعدادات دون خرائط محلية.'","REVOKE ALL ON FUNCTION public.payment_method_catalog_view() FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.payment_method_catalog_view() TO authenticated, service_role","-- ---------------------------------------------------------------------------\r\n-- 7. The seed refreshes developer rows only — HOW TO DO IT CORRECTLY\r\n--\r\n--    `ON CONFLICT DO UPDATE` in 20261208000000 reset name_ar / icon_key on\r\n--    every re-apply, so a future migration that re-runs that seed would\r\n--    overwrite every rename a business had made.\r\n--\r\n--    The seed there is a static `VALUES` list, and PostgreSQL gives an\r\n--    `ON CONFLICT DO UPDATE` no way to reference the row's OLD value —\r\n--    `EXCLUDED` is the incoming tuple, `payment_methods.*` is the existing one,\r\n--    and there is no `OLD` in this context. So the fix is not a cleverer SET\r\n--    expression: it is to write the refreshed seed into a TEMP table first and\r\n--    merge from it, where the existing row is an ordinary join target.\r\n--\r\n--    The recipe the next migration should follow is below, commented rather\r\n--    than executed, because changing the seed's CONTENT is not this file's job:\r\n--\r\n--      CREATE TEMP TABLE seed_pm ON COMMIT DROP AS\r\n--        SELECT * FROM (VALUES\r\n--          ('cash', 'نقداً', 'Cash', 'cash', 10, ...),\r\n--          ('cheque', 'شيك', 'Cheque', 'cheque', 120, ...)\r\n--        ) AS t(id, name_ar, name_en, icon_key, sort_order, ...);\r\n--\r\n--      -- 7.1 Rows the business renamed keep their authoring.\r\n--      UPDATE public.payment_methods m\r\n--         SET sort_order   = s.sort_order,\r\n--             allowed_contexts = s.allowed_contexts,\r\n--             ledger_kind  = s.ledger_kind,\r\n--             default_account_code = s.default_account_code,\r\n--             requires_reference   = s.requires_reference,\r\n--             legacy_id    = s.legacy_id,\r\n--             legacy_ids   = s.legacy_ids,\r\n--             updated_at   = now()\r\n--        FROM seed_pm s\r\n--       WHERE m.id = s.id\r\n--         AND m.is_system\r\n--         AND EXISTS (SELECT 1 FROM public.payment_method_settings st\r\n--                      WHERE st.payment_method_id = m.id\r\n--                        AND st.updated_by_platform = false\r\n--                        AND m.updated_at > m.created_at);\r\n--\r\n--      -- 7.2 Rows nobody personalised get the shipped label back.\r\n--      UPDATE public.payment_methods m\r\n--         SET name_ar = s.name_ar, name_en = s.name_en, icon_key = s.icon_key,\r\n--             sort_order = s.sort_order, allowed_contexts = s.allowed_contexts,\r\n--             ledger_kind = s.ledger_kind, legacy_id = s.legacy_id,\r\n--             legacy_ids = s.legacy_ids, updated_at = now()\r\n--        FROM seed_pm s\r\n--       WHERE m.id = s.id AND m.is_system\r\n--         AND NOT EXISTS (SELECT 1 FROM public.payment_method_settings st\r\n--                          WHERE st.payment_method_id = m.id\r\n--                            AND st.updated_by_platform = false\r\n--                            AND m.updated_at > m.created_at);\r\n--\r\n--      -- 7.3 Anything new in the seed.\r\n--      INSERT INTO public.payment_methods (id, name_ar, ...)\r\n--      SELECT s.* FROM seed_pm s\r\n--      WHERE NOT EXISTS (SELECT 1 FROM public.payment_methods m WHERE m.id = s.id);\r\n--\r\n--    `is_system`, `id` and `ledger_kind` are never taken from a tenant, and\r\n--    `updated_by_platform = true` marks an edit the platform made itself, so\r\n--    the platform can correct its own row without freezing it forever.\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE FUNCTION public.payment_methods_seed_is_identity_owned(p_id text)\r\nRETURNS boolean\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.payment_methods m\r\n    JOIN public.payment_method_settings s ON s.payment_method_id = m.id\r\n    WHERE m.id = p_id\r\n      AND s.updated_by_platform = false\r\n      AND s.payment_method_id IS NOT NULL\r\n      AND m.is_system\r\n      -- لا يُعدّ مؤلَّفًا إلا صف لمسته المنشأة فعلًا.\r\n      AND m.updated_at > m.created_at\r\n  );\r\n$$","COMMENT ON FUNCTION public.payment_methods_seed_is_identity_owned(text) IS\r\n  'هل عدّلت المنشأة اسم/أيقونة هذه الطريقة؟ يستخدمه الـSeed لاحقاً ليحترم التعديل؛ الترحيلات التي تزرع لا تضرب صفوف المنشأة.'","REVOKE ALL ON FUNCTION public.payment_methods_seed_is_identity_owned(text) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.payment_methods_seed_is_identity_owned(text) TO authenticated, service_role","-- ---------------------------------------------------------------------------\r\n-- 8. التحقق من الثوابت التي يدّعيها هذا الملف، والفشل بصوت عالٍ إن خُرق أي منها.\r\n-- ---------------------------------------------------------------------------\r\nDO $$\r\nDECLARE\r\n  v_bad integer;\r\n  v_repaired integer;\r\nBEGIN\r\n  -- ── 8.1 إصلاح أي صف تخالف قيمته المخزّنة عائلة حسابه ──\r\n  --\r\n  -- مؤسسة مسمّاة (بنك الكريمي، جيب) تُشحن بقائمة legacy **فارغة** لأنها تتشارك\r\n  -- قيمة `bank_transfer` / `mobile_money` العامة. وعندما شغّل الـbackfill في\r\n  -- القسم 1 على قاعدة كانت تلك القائمة فيها فارغة، كان يمكن لنسخة أقدم من هذا\r\n  -- الملف أن تترك legacy_id على حدّ 'cash' — وهو ما يحوّل بنكًا إلى الصندوق.\r\n  -- فعُدنا نشتقّها هنا من عائلة الحساب، وهي ما يثق به محرّك الترحيل أصلًا، فيُستعاد\r\n  -- الثابت أدناه بدل الاكتفاء بتأكيده.\r\n  --\r\n  -- ⚠️ شرط WHERE هو بيت القصيد. يجب أن يطابق القيمة **المعطوبة**، لا قيمة «غير\r\n  --    صالحة». فـ 'cash' قيمة ENUM صالحة تمامًا، لذلك لم يطابق الشرط القديم\r\n  --    `coalesce(legacy_id,'') NOT IN (…)` أي صف بنك خُزّن خطأً 'cash' — فالإصلاح\r\n  --    كُتب، ونُفّذ، وطبع نجاحًا، ولم يغيّر شيئًا (MIGRATION_16_REVIEW.md §2.3 ب).\r\n  --    أما المقارنة بالقيمة المشتقة فتجعل الصف يطابق بحكم التعريف متى كان خاطئًا.\r\n  --    والصفوف التي لا تستطيع عائلتها إنتاج قيمة، والصفوف التي توافق قيمتها\r\n  --    المعلنة أصلًا، تُترك بلا مساس.\r\n  UPDATE public.payment_methods\r\n     SET legacy_id = CASE ledger_kind\r\n                       WHEN 'BANK'   THEN 'bank_transfer'\r\n                       WHEN 'WALLET' THEN 'mobile_money'\r\n                       WHEN 'CARD'   THEN 'card'\r\n                       WHEN 'CREDIT' THEN 'credit'\r\n                       WHEN 'CASH'   THEN 'cash'\r\n                       ELSE legacy_id\r\n                     END,\r\n         updated_at = now()\r\n   WHERE ledger_kind IN ('BANK','WALLET','CARD','CREDIT','CASH')\r\n     -- legacy_ids[1] إقرار الصف الصريح وهو يفوز دائمًا؛ ومؤسسة مسمّاة تحمل قائمة\r\n     -- فارغة، فتردّ العائلة عنها.\r\n     AND coalesce(nullif(legacy_ids[1], ''), 'cash') <> CASE ledger_kind\r\n                       WHEN 'BANK'   THEN 'bank_transfer'\r\n                       WHEN 'WALLET' THEN 'mobile_money'\r\n                       WHEN 'CARD'   THEN 'card'\r\n                       WHEN 'CREDIT' THEN 'credit'\r\n                       ELSE 'cash'\r\n                     END\r\n     AND legacy_id IS DISTINCT FROM CASE ledger_kind\r\n                       WHEN 'BANK'   THEN 'bank_transfer'\r\n                       WHEN 'WALLET' THEN 'mobile_money'\r\n                       WHEN 'CARD'   THEN 'card'\r\n                       WHEN 'CREDIT' THEN 'credit'\r\n                       ELSE 'cash'\r\n                     END;\r\n\r\n  GET DIAGNOSTICS v_repaired = ROW_COUNT;\r\n  IF v_repaired > 0 THEN\r\n    RAISE NOTICE '↩️ أُعيد اشتقاق القيمة المخزّنة لـ % طريقة من عائلة حسابها', v_repaired;\r\n  END IF;\r\n\r\n  SELECT count(*) INTO v_bad\r\n  FROM public.payment_methods\r\n  WHERE legacy_id IS NULL\r\n     OR legacy_id NOT IN ('cash','card','bank_transfer','credit','mobile_money','split','cheque');\r\n\r\n  IF v_bad > 0 THEN\r\n    RAISE EXCEPTION 'FAIL: % صفاً في الكتالوج بقيمة مخزّنة غير صالحة', v_bad;\r\n  END IF;\r\n\r\n  -- 8.2 كل قيمة مخزّنة على مستند حيّ يجب أن تبقى قابلة للحل، كما كانت تمامًا.\r\n  --     محميّ بـ EXISTS كي لا تفشل قاعدة لم تُشغّل بذرة الكتالوج الموحّد بعد على\r\n  --     صف لم تستقبله قط.\r\n  IF EXISTS (SELECT 1 FROM public.payment_methods WHERE id = 'kuraimi_bank')\r\n     AND public.payment_method_legacy_id('kuraimi_bank') <> 'bank_transfer' THEN\r\n    RAISE EXCEPTION 'FAIL: kuraimi_bank -> % (expected bank_transfer)',\r\n      public.payment_method_legacy_id('kuraimi_bank');\r\n  END IF;\r\n  IF EXISTS (SELECT 1 FROM public.payment_methods WHERE id = 'jaib')\r\n     AND public.payment_method_legacy_id('jaib') <> 'mobile_money' THEN\r\n    RAISE EXCEPTION 'FAIL: jaib -> % (expected mobile_money)',\r\n      public.payment_method_legacy_id('jaib');\r\n  END IF;\r\n  IF EXISTS (SELECT 1 FROM public.payment_methods WHERE id = 'kuraimi_bank')\r\n     AND public.payment_method_ledger_account('kuraimi_bank') <> '1111' THEN\r\n    RAISE EXCEPTION 'FAIL: kuraimi_bank settles to %',\r\n      public.payment_method_ledger_account('kuraimi_bank');\r\n  END IF;\r\n  IF EXISTS (SELECT 1 FROM public.payment_methods WHERE id = 'credit')\r\n     AND public.payment_method_ledger_account('credit') IS NOT NULL THEN\r\n    RAISE EXCEPTION 'FAIL: credit must settle to NULL';\r\n  END IF;\r\n\r\n  RAISE NOTICE '✅ طبقة التأليف جاهزة: % طريقة، منها % نظامية',\r\n    (SELECT count(*) FROM public.payment_methods),\r\n    (SELECT count(*) FROM public.payment_methods WHERE is_system);\r\nEND $$",COMMIT}	payment_methods
17	{"-- ============================================================================\r\n-- 17_package_weight.sql\r\n--\r\n-- سعة العبوة الرسمية (وزن الكيس) — عمود موحّد على جدول المنتجات.\r\n--\r\n-- الخلفية: العمود package_weight_kg أُضيف في 05_products_and_inventory.sql،\r\n-- لكنه لم يُطبَّق على المخطط الحيّ (تعارض/تخطٍّ في التطبيق). النتيجة: شاشتا\r\n-- الطحن والتسليم تُرجعان SelectQueryError عند قراءة العمود، وخريطة السعة تبقى\r\n-- فارغة فيعرض النظام 0 لكل الأصناف.\r\n--\r\n-- هذه المهاجرة idempotent: تُضيف العمود إن لم يكن موجوداً، وتُطبّق القيود\r\n-- والتعليق التوثيقي دائماً. آمنة للتشغيل أكثر من مرة.\r\n--\r\n-- القاعدة الرسمية: أي منتج يُعبّأ (FINISHED_GOOD / BY_PRODUCT / RAW_MATERIAL)\r\n-- يمكن أن يحمل سعة عبوة افتراضية بالكيلوجرام. تُستخدم فقط لتعبئة نموذج\r\n-- \\"الوزن الافتراضي\\" في شاشات الطحن والتسليم — لا تؤثر على أي حساب مخزون.\r\n--\r\n-- ROLLBACK:\r\n--   ALTER TABLE public.products DROP COLUMN IF EXISTS package_weight_kg;\r\n-- ============================================================================\r\n\r\nALTER TABLE public.products\r\n  ADD COLUMN IF NOT EXISTS package_weight_kg numeric(12,3)","DO $$ BEGIN\r\n  ALTER TABLE public.products\r\n    ADD CONSTRAINT products_package_weight_positive_check\r\n    CHECK (package_weight_kg IS NULL OR package_weight_kg > 0);\r\nEXCEPTION\r\n  WHEN duplicate_object THEN null;\r\nEND $$","COMMENT ON COLUMN public.products.package_weight_kg IS\r\n  'السعة الافتراضية للعبوة بالكيلوجرام (مثال 50 أو 25). تُستخدم لتعبئة الوزن الافتراضي في شاشات الطحن والتسليم فقط.'"}	package_weight
18	{"-- ============================================================================\r\n-- 18_fix_service_flags.sql — تصحيح عمود products.is_service\r\n-- ============================================================================\r\n--\r\n-- ── المشكلة ─────────────────────────────────────────────────────────────────\r\n--   كان عمود `products.is_service` مُعبّأً بشكل **معكوس** في بيانات العرض:\r\n--     • كل النواتج (FINISHED_GOOD / BY_PRODUCT) كانت is_service = TRUE\r\n--     • والخدمة الوحيدة (SERVICE — «أجور طحن وتجهيز») كانت is_service = FALSE\r\n--   الأثر العملي:\r\n--     1. نقطة البيع كانت تمنع بيع النواتج لأنها تُعامَل كخدمة (بلا فحص مخزون)،\r\n--        وتستثني صنف «أجور طحن» من القائمة فيستحيل بيع أجرة الطحن.\r\n--     2. التقارير كانت تعتبر النواتج «خدمات» (بلا تكلفة مخزون).\r\n--\r\n-- ── القاعدة الصحيحة (docs/milling/00 — ق5 / 04 — د2) ────────────────────────\r\n--   `is_service = TRUE` **فقط** لأصناف `item_class = 'SERVICE'`.\r\n--   كل ما عداه بضاعة → `is_service = FALSE`.\r\n--\r\n-- ── idempotent: يمكن تشغيله أكثر من مرة بأمان (UPDATE بلا قيود فريدة) ───────\r\n-- ============================================================================\r\n\r\nBEGIN","-- 1) الخدمات الحقيقية فقط\r\nUPDATE public.products\r\nSET is_service = true\r\nWHERE item_class = 'SERVICE'\r\n  AND is_service IS DISTINCT FROM true","-- 2) كل ما ليس خدمة = بضاعة (خام/ناتج/مستهلكات/…)\r\nUPDATE public.products\r\nSET is_service = false\r\nWHERE item_class <> 'SERVICE'\r\n  AND is_service IS DISTINCT FROM false",COMMIT,"-- ── التحقق بعد التشغيل ──────────────────────────────────────────────────────\r\n-- SELECT item_class, is_service, count(*)\r\n-- FROM public.products GROUP BY 1, 2 ORDER BY 1;\r\n--\r\n-- المتوقع:  SERVICE → is_service = TRUE (صف واحد)\r\n--            كل الباقي → is_service = FALSE"}	fix_service_flags
19	{"-- ============================================================================\r\n-- 17_accounting_phase0_controls.sql — المرحلة 0 من خطة معالجة الفجوات المحاسبية\r\n-- (التقرير: ACCOUNTING_GAPS_AUDIT_REPORT_UPDATED.md، المهام T-01..T-04)\r\n--\r\n-- ماذا يفعل هذا الملف؟\r\n--   T-01: إصلاح مضاعفة الضريبة في قيد المبيعات — الإيراد يُقيَّد صافيًا\r\n--         (total − tax للبند) لا شاملًا، فتُحمَّل الضريبة مرة واحدة على 2311.\r\n--   T-02: فهرس فريد بنيوي على مصدر القيد — منع الترحيل المزدوج في القاعدة\r\n--         لا في الكود فقط.\r\n--   T-03: رقابة الدفتر: فحص الدور داخل create_journal_entry، منع الترحيل\r\n--         اليدوي على حسابات النظام، سجل تدقيق للإنشاء والعكس، وtrigger\r\n--         يمنع حذف القيود.\r\n--   T-04: توحيد ترقيم القيود على التسلسل journal_entry_seq بدل count(*) —\r\n--         إزالة مخاطرة اصطدام أرقام تحت التزامن.\r\n--\r\n-- قواعد التطبيق:\r\n--   • إضافي بالكامل: لا يحذف ولا يعدّل أي بيانات ولا أي جدول.\r\n--   • يعيد تعريف الدوال الأربع فقط (CREATE OR REPLACE) بلا تغيير التوقيعات،\r\n--     فلا ينكسر أي مستدعٍ قائم.\r\n--   • يعمل بعد 16_payment_methods.sql — تعريفه النهائي هو المُطبَّق.\r\n--   • آمن للتطبيق المتكرر (idempotent).\r\n-- ============================================================================\r\n\r\nBEGIN","-- ════════════════════\r\n-- T-02 — فهرس فريد على (source_type, source_id) في journal_entries\r\n--\r\n-- حماية «مرة واحدة فقط» كانت داخل دوال الترحيل (فحص SELECT قبل الإدراج).\r\n-- أي مسار جديد أو نداء يدوي كان يستطيع إنشاء قيدين لنفس المستند. الفهرس\r\n-- الجزئي يجعل الفشل قاعدةً لا كودًا: القيود المعكوسة (REVERSED) تُستثنى،\r\n-- والمصادر اليدوية بلا source_id تُستثنى أيضًا (NULL لا يُفهرس).\r\n-- ════════════════════\r\n\r\nCREATE UNIQUE INDEX IF NOT EXISTS uq_journal_source_active\r\n  ON public.journal_entries (source_type, source_id)\r\n  WHERE source_id IS NOT NULL AND status <> 'REVERSED'","COMMENT ON INDEX public.uq_journal_source_active IS\r\n  'T-02: قيد واحد نشط لكل مستند مصدر — منع الترحيل المزدوج بنيويًا.'","-- ════════════════════\r\n-- T-03 (1/3) — trigger يمنع حذف القيود\r\n--\r\n-- journal_lines لها ON DELETE CASCADE من journal_entries؛ أي حذف مباشر\r\n-- (حتى عبر service_role) يحذف سطور القيد صامتًا بلا أثر. التصحيح الشرعي\r\n-- للمسار هو العكس عبر reverse_journal_entry — والحذف يُمنع دائمًا.\r\n-- ════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.tg_journal_entries_no_delete()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nAS $$\r\nBEGIN\r\n  RAISE EXCEPTION\r\n    'Deleting a journal entry is forbidden. Reverse it via reverse_journal_entry instead (entry %).',\r\n    OLD.entry_number\r\n    USING ERRCODE = 'restrict_violation';\r\nEND;\r\n$$","DROP TRIGGER IF EXISTS journal_entries_no_delete ON public.journal_entries","CREATE TRIGGER journal_entries_no_delete\r\n  BEFORE DELETE ON public.journal_entries\r\n  FOR EACH ROW EXECUTE FUNCTION public.tg_journal_entries_no_delete()","COMMENT ON FUNCTION public.tg_journal_entries_no_delete() IS\r\n  'T-03: يمنع حذف أي قيد — التصحيح يكون بالعكس فقط.'","-- ════════════════════\r\n-- T-04 — ترقيم القيود من التسلسل لا من count(*)\r\n--\r\n-- النسخة السابقة تحسب count(*)+1 ليوم القيد؛ تزامنان قد ينتجان الرقم نفسه\r\n-- (فشل عملية بفشل القيد الفريد). محرك الترقيم 14 عرّف journal_entry_seq\r\n-- خصيصًا لهذا — والآن يُستخدم فعلًا. الشكل ظاهريًا كما هو.\r\n-- ════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.next_journal_number(p_date date)\r\nRETURNS text\r\nLANGUAGE sql\r\nSET search_path TO 'public'\r\nAS $function$\r\n  SELECT 'JE-' || to_char(p_date, 'YYYYMMDD') || '-' ||\r\n         lpad(nextval('public.journal_entry_seq')::text, 4, '0')\r\n$function$","COMMENT ON FUNCTION public.next_journal_number(date) IS\r\n  'T-04: رقم القيد من تسلسل ذري journal_entry_seq — بلا اصطدام تحت التزامن.'","-- ════════════════════\r\n-- T-03 (2/3) — create_journal_entry بفحص دور ورقابة حسابات النظام وسجل تدقيق\r\n--\r\n-- الجسم السابق كان يفحص المصادقة والتوازن فقط:\r\n--   • أي مستخدم مصادَق (authenticated) يستطيع إنشاء قيد يدوي.\r\n--   • يمكن الترحيل اليدوي على حسابات النظام (is_system).\r\n--   • لا أثر في audit_logs.\r\n-- الآن: owner/manager/accountant فقط، ويُمنع اليدوي على حسابات is_system\r\n-- إلا إذا كان القيد نفسه system (كما تُنشئه دوال الترحيل SECURITY DEFINER)،\r\n-- ويُسجَّل كل قيد في سجل التدقيق. باقي المنطق (توازن، سطر واحد فقط لكل\r\n-- جهة، وجود الحساب وقابلية الترحيل) بلا مساس.\r\n-- ════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.create_journal_entry(p_memo text, p_entry_date date DEFAULT CURRENT_DATE, p_source_type text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_is_system boolean DEFAULT false, p_lines jsonb DEFAULT '[]'::jsonb)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_id   uuid;\r\n  v_num  text;\r\n  v_d    numeric := 0;\r\n  v_c    numeric := 0;\r\n  src    jsonb;\r\n  v_missing integer;\r\n  v_blocked integer;\r\n  v_sideless text;\r\n  v_system_accounts integer;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  -- T-03: فحص الدور — القيد اليدوي (p_is_system=false) للمحاسبة فقط.\r\n  -- القيد النظامي (من دوال الترحيل SECURITY DEFINER) مسموح لأي موظف مصادق:\r\n  -- فالكاشير يبيع عبر create_sale، وترحيل فاتورته جزء من نفس العملية\r\n  -- (قرار T-06-b المعتمد: مسار POS يستمر مع الترحيل التلقائي).\r\n  IF NOT coalesce(p_is_system, false) THEN\r\n    IF NOT (public.has_role(v_user, 'owner')\r\n            OR public.has_role(v_user, 'manager')\r\n            OR public.has_role(v_user, 'accountant')) THEN\r\n      RAISE EXCEPTION 'Only an owner, manager or accountant may create manual journal entries';\r\n    END IF;\r\n  END IF;\r\n\r\n  IF p_memo IS NULL OR btrim(p_memo) = '' THEN\r\n    RAISE EXCEPTION 'A journal entry needs a description';\r\n  END IF;\r\n  IF p_lines IS NULL OR jsonb_array_length(p_lines) < 2 THEN\r\n    RAISE EXCEPTION 'A journal entry needs at least two lines - one to debit and one to credit';\r\n  END IF;\r\n\r\n  -- A line must carry exactly one side. Checked up front, before the entry\r\n  -- header is written, so a rejected line never leaves a DRAFT entry behind\r\n  -- in the table for someone to find later and wonder about.\r\n  SELECT string_agg(coalesce(ln->>'account_code', '?'), '، ') INTO v_sideless\r\n    FROM jsonb_array_elements(p_lines) AS ln\r\n   WHERE coalesce((ln->>'debit')::numeric, 0) = 0\r\n     AND coalesce((ln->>'credit')::numeric, 0) = 0;\r\n  IF v_sideless IS NOT NULL THEN\r\n    RAISE EXCEPTION\r\n      'Line(s) % carry neither a debit nor a credit. Every line must have exactly one side.',\r\n      v_sideless;\r\n  END IF;\r\n\r\n  -- T-03: اليدوي لا يلمس حسابات النظام. دوال الترحيل تمرر p_is_system = true\r\n  -- فتعمل كما كانت؛ النداء اليدوي (false) يُرفض إن كان أي حساب هدفه نظاميًا.\r\n  IF NOT coalesce(p_is_system, false) THEN\r\n    SELECT count(*) INTO v_system_accounts\r\n      FROM jsonb_array_elements(p_lines) AS ln\r\n      JOIN public.accounts a ON a.code = ln->>'account_code'\r\n     WHERE a.is_system;\r\n    IF v_system_accounts > 0 THEN\r\n      RAISE EXCEPTION\r\n        '% line(s) target a system account. Manual entries cannot post to system accounts.',\r\n        v_system_accounts;\r\n    END IF;\r\n  END IF;\r\n\r\n  -- مستند واحد = قيد واحد نشط. غير الرقمي يُطبَّع إلى NULL فيُستثنى من\r\n  -- uq_journal_source_active (لأن NULL لا يُفهرَس): مصدر نصي بلا معناه الرقمي\r\n  -- كان يمنع القيد الثاني لأي مستند آخر يحمل نفس النص.\r\n  p_source_id := CASE WHEN p_source_id::text ~ '^[0-9a-fA-F-]{36}$' THEN p_source_id END;\r\n\r\n  v_num := public.next_journal_number(coalesce(p_entry_date, CURRENT_DATE));\r\n\r\n  INSERT INTO public.journal_entries\r\n    (entry_number, entry_date, memo, source_type, source_id, is_system, created_by)\r\n  VALUES (v_num, coalesce(p_entry_date, CURRENT_DATE), btrim(p_memo),\r\n          p_source_type, p_source_id, p_is_system, v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR src IN SELECT * FROM jsonb_array_elements(p_lines)\r\n  LOOP\r\n    v_d := v_d + coalesce((src->>'debit')::numeric, 0);\r\n    v_c := v_c + coalesce((src->>'credit')::numeric, 0);\r\n  END LOOP;\r\n\r\n  IF v_d <> v_c THEN\r\n    RAISE EXCEPTION\r\n      'Entry does not balance: debits % vs credits % (difference %). An entry that cannot balance is not an entry.',\r\n      round(v_d, 2)::text, round(v_c, 2)::text, round(v_d - v_c, 2)::text;\r\n  END IF;\r\n  IF v_d <= 0 THEN\r\n    RAISE EXCEPTION 'Entry total must be greater than zero';\r\n  END IF;\r\n\r\n  -- The two failure modes are reported separately: \\"code does not exist\\" sends\r\n  -- the operator hunting for a typo when the code was real and simply not\r\n  -- postable, and that misdirection costs more than the extra check.\r\n  SELECT count(*) FILTER (WHERE a.id IS NULL),\r\n         count(*) FILTER (WHERE a.id IS NOT NULL AND NOT a.is_postable)\r\n    INTO v_missing, v_blocked\r\n    FROM jsonb_array_elements(p_lines) AS ln\r\n    LEFT JOIN public.accounts a ON a.code = ln->>'account_code';\r\n\r\n  IF v_missing > 0 THEN\r\n    RAISE EXCEPTION 'One or more account codes do not exist. Check the code before posting.';\r\n  END IF;\r\n  IF v_blocked > 0 THEN\r\n    RAISE EXCEPTION\r\n      'One or more accounts is not postable directly (a contra or clearing account). Post through the account that moves it.';\r\n  END IF;\r\n\r\n  INSERT INTO public.journal_lines (entry_id, account_id, debit, credit, memo, partner_type, partner_id)\r\n  SELECT v_id, a.id,\r\n         coalesce((ln->>'debit')::numeric, 0),\r\n         coalesce((ln->>'credit')::numeric, 0),\r\n         nullif(btrim(coalesce(ln->>'memo','')), ''),\r\n         nullif(btrim(coalesce(ln->>'partner_type','')), ''),\r\n         (ln->>'partner_id')::uuid\r\n    FROM jsonb_array_elements(p_lines) AS ln\r\n    JOIN public.accounts a ON a.code = ln->>'account_code'\r\n   WHERE (ln->>'debit')::numeric IS DISTINCT FROM 0\r\n      OR (ln->>'credit')::numeric IS DISTINCT FROM 0;\r\n\r\n  IF (SELECT count(*) FROM public.journal_lines WHERE entry_id = v_id)\r\n     <> jsonb_array_length(p_lines) THEN\r\n    RAISE EXCEPTION 'One or more lines could not be written';\r\n  END IF;\r\n\r\n  UPDATE public.journal_entries\r\n     SET total_debit = v_d, total_credit = v_c, status = 'POSTED',\r\n         posted_by = v_user, posted_at = now()\r\n   WHERE id = v_id;\r\n\r\n  -- T-03: كل قيد له أثر في سجل التدقيق.\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'journal_entry.posted', 'journal_entry', v_id,\r\n          jsonb_build_object('entry_number', v_num,\r\n                             'entry_date', coalesce(p_entry_date, CURRENT_DATE),\r\n                             'source_type', p_source_type,\r\n                             'source_id', p_source_id,\r\n                             'total', v_d));\r\n\r\n  RETURN v_id;\r\nEND $function$","COMMENT ON FUNCTION public.create_journal_entry(text, date, text, uuid, boolean, jsonb) IS\r\n  'T-03: إنشاء قيد مزدوج مع فحص الدور، ومنع اليدوي على حسابات النظام، وسجل تدقيق.'","-- ════════════\r\n-- T-03 (3/3) — reverse_journal_entry بسجل تدقيق\r\n-- الجسم بلا تغيير جوهري؛ الإضافة الوحيدة سجل التدقيق عند العكس.\r\n-- ════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.reverse_journal_entry(p_entry_id uuid, p_reason text)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_old  record;\r\n  v_id   uuid;\r\nBEGIN\r\n  IF p_reason IS NULL OR btrim(p_reason) = '' THEN\r\n    RAISE EXCEPTION 'Reversing an entry requires a reason';\r\n  END IF;\r\n\r\n  SELECT * INTO v_old FROM public.journal_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND OR v_old.status <> 'POSTED' THEN\r\n    RAISE EXCEPTION 'Only a posted entry can be reversed';\r\n  END IF;\r\n\r\n  SELECT public.create_journal_entry(\r\n    'عكس القيد ' || v_old.entry_number || ': ' || btrim(p_reason),\r\n    CURRENT_DATE, 'journal_reversal', p_entry_id, v_old.is_system,\r\n    (SELECT coalesce(jsonb_agg(jsonb_build_object(\r\n        'account_code', a.code,\r\n        -- A reversal swaps the sides rather than negating: the credit of the\r\n        -- original becomes the debit of the reversal.\r\n        'debit',  CASE WHEN jl.debit  > 0 THEN 0 ELSE jl.credit END,\r\n        'credit', CASE WHEN jl.debit  > 0 THEN jl.debit  ELSE 0 END,\r\n        'memo',   coalesce(jl.memo, a.name_ar)\r\n      ) ORDER BY jl.id), '[]'::jsonb)\r\n       FROM public.journal_lines jl JOIN public.accounts a ON a.id = jl.account_id\r\n      WHERE jl.entry_id = p_entry_id)\r\n  ) INTO v_id;\r\n\r\n  UPDATE public.journal_entries SET status = 'REVERSED' WHERE id = p_entry_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'journal_entry.reversed', 'journal_entry', p_entry_id,\r\n          jsonb_build_object('reversal_entry_id', v_id, 'reason', btrim(p_reason)));\r\n\r\n  RETURN v_id;\r\nEND $function$","COMMENT ON FUNCTION public.reverse_journal_entry(uuid, text) IS\r\n  'T-03: عكس قيد مرحَّل ببدل الطرفين، مع سجل تدقيق للعكس.'","-- ════════════════════\r\n-- T-01 — post_sales_invoice: الإيراد صافي الضريبة\r\n--\r\n-- sales_invoice_items.total مخزَّن شاملًا للضريبة (create_sale يخزّن\r\n-- total = line_total + line_tax). النسخة السابقة تقيّد الإيراد من it.total\r\n-- ثم تضيف الضريبة دائنة إضافية على 2311 — فتظهر الضريبة مرتين (داخل الإيراد\r\n-- وكالتزام). الإصلاح: الإيراد يُقيَّد من (it.total − it.tax)، فتصبح:\r\n--   Dr نقد/بنك (paid) + Dr ذمم (total − paid)  =  total\r\n--   Cr إيراد (net) + Cr ضريبة (tax)            =  total\r\n-- كل ما عدا ذلك (حارس المرة الواحدة، فحص الدور، حساب التحصيل من الكتالوج،\r\n-- تصنيف الإيراد حسب item_class، سطور COGS، الضريبة على 2311) بلا مساس.\r\n-- ════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.post_sales_invoice(p_invoice_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_inv     record;\r\n  v_existing uuid;\r\n  v_entry   uuid;\r\n  v_lines   jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  v_collectable numeric := 0;\r\n  r         record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')\r\n          OR public.has_role(v_user,'accountant')\r\n          -- T-06-b (المعتمد): الكاشير يبيع عبر create_sale التي تستدعي هذه\r\n          -- الدالة في نفس المعاملة؛ الترحيل جزء من البيع لا عملية منفصلة.\r\n          OR public.has_role(v_user,'cashier')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager, accountant or the cashier''s own sale may post a sales invoice';\r\n  END IF;\r\n\r\n  SELECT * INTO v_inv FROM public.sales_invoices WHERE id = p_invoice_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Invoice not found';\r\n  END IF;\r\n\r\n  IF v_inv.status IN ('draft','cancelled') THEN\r\n    RAISE EXCEPTION 'Invoice % is % - only confirmed, paid or partial invoices post',\r\n      v_inv.invoice_number, v_inv.status;\r\n  END IF;\r\n\r\n  IF v_inv.paid < 0 THEN\r\n    RAISE EXCEPTION 'Invoice % carries a negative payment (%). A refund is a credit note, not a negative payment.',\r\n      v_inv.invoice_number, v_inv.paid;\r\n  END IF;\r\n  IF v_inv.paid > v_inv.total THEN\r\n    RAISE EXCEPTION 'Invoice % was paid % against a total of %. Fix the invoice before posting - a payment cannot exceed the invoice.',\r\n      v_inv.invoice_number, v_inv.paid, v_inv.total;\r\n  END IF;\r\n  IF v_inv.tax < 0 THEN\r\n    RAISE EXCEPTION 'Invoice % carries a negative tax amount', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  SELECT id INTO v_existing\r\n    FROM public.journal_entries\r\n   WHERE source_type = 'sales_invoice' AND source_id = p_invoice_id\r\n     AND status <> 'REVERSED';\r\n  IF v_existing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'Invoice % has already been posted to the ledger', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- الحساب من الكتالوج (16_payment_methods.sql) — بلا تغيير.\r\n  -- 'credit'          -> NULL      (لم يُحصَّل شيء)\r\n  -- BANK/WALLET/CARD  -> '1111'    (يخرج عبر البنك)\r\n  -- CASH / OTHER      -> '1101'    (الصندوق؛ وsplit تُسوّى نقداً)\r\n  v_cash_acct := public.ledger_account_code_for_payment_method(v_inv.payment_method);\r\n\r\n  v_collectable := greatest(v_inv.total - v_inv.paid, 0);\r\n\r\n  -- ── revenue, credited NET of line tax ────────────────────────────────────\r\n  -- T-01: it.total شامل الضريبة على مستوى البند، والإيراد يُقيَّد صافيًا\r\n  -- فلا تتكرر الضريبة (مرة داخل الإيراد ومرة على 2311).\r\n  FOR r IN\r\n    SELECT p.item_class,\r\n           sum(it.total - coalesce(it.tax, 0)) AS net_amount\r\n      FROM public.sales_invoice_items it\r\n      JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n     GROUP BY p.item_class\r\n    HAVING sum(it.total - coalesce(it.tax, 0)) <> 0\r\n  LOOP\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE r.item_class\r\n                        WHEN 'BY_PRODUCT' THEN '4211'\r\n                        WHEN 'SERVICE'    THEN '4311'\r\n                        ELSE '4111' END,\r\n      'credit', round(r.net_amount, 2),\r\n      'memo', 'إيراد ' || r.item_class);\r\n  END LOOP;\r\n\r\n  IF jsonb_array_length(v_lines) = 0 THEN\r\n    RAISE EXCEPTION 'Invoice % has no revenue lines', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- ── ما استلمته المنشأة: النقد والذمة كلاهما مدين ──\r\n  -- هما بديلان لنفس الزيادة، فبيعة مسدّدة بالكامل لها مدين نقدي بلا ذمة، وبيعة\r\n  -- آجلة العكس. الذمة شاملة الضريبة (المستحق على العميل إجمالي الفاتورة).\r\n  IF v_inv.paid > 0 AND v_cash_acct IS NOT NULL THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', v_cash_acct, 'debit', round(v_inv.paid, 2),\r\n      'memo', 'تحصيل نقدي/بنكي');\r\n  END IF;\r\n  IF v_collectable > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1211', 'debit', round(v_collectable, 2),\r\n      'memo', 'ذمم العميل ' || coalesce(v_inv.invoice_number, ''));\r\n  END IF;\r\n\r\n  IF v_inv.tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2311', 'credit', round(v_inv.tax, 2),\r\n      'memo', 'ضريبة القيمة المضافة المستحقة');\r\n  END IF;\r\n\r\n  -- ── the cost of the goods that left ──\r\n  FOR r IN\r\n    SELECT p.item_class,\r\n           sum(it.quantity * public.resolve_unit_cost(p.id, v_inv.warehouse_id)) AS cost\r\n      FROM public.sales_invoice_items it\r\n      JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n       AND it.stock_effect = 'STOCK_ISSUE'\r\n     GROUP BY p.item_class\r\n  LOOP\r\n    IF r.cost IS NULL OR r.cost = 0 THEN\r\n      CONTINUE;   -- no cost known; a zero COGS line would overstate profit\r\n    END IF;\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE r.item_class\r\n                        WHEN 'RAW_MATERIAL' THEN '1311'\r\n                        WHEN 'BY_PRODUCT'   THEN '1314'\r\n                        ELSE '1313' END,\r\n      'credit', round(r.cost, 2),\r\n      'memo', 'تكلفة ' || r.item_class);\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '5111', 'debit', round(r.cost, 2),\r\n      'memo', 'تكلفة البضاعة المباعة');\r\n  END LOOP;\r\n\r\n  v_entry := public.create_journal_entry(\r\n    'فاتورة مبيعات ' || v_inv.invoice_number,\r\n    v_inv.created_at::date,\r\n    'sales_invoice', p_invoice_id, true, v_lines);\r\n\r\n  RETURN v_entry;\r\nEND $$","REVOKE ALL ON FUNCTION public.post_sales_invoice(uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.post_sales_invoice(uuid) TO authenticated, service_role","COMMENT ON FUNCTION public.post_sales_invoice(uuid) IS\r\n  'T-01: يرحّل فاتورة المبيعات بإيراد صافٍ من ضريبة البند — الضريبة تُحمَّل مرة واحدة على 2311.'",COMMIT,"-- ============================================================================\r\n-- التحقق بعد التطبيق:\r\n--   1. فاتورة 1,000 صافي + 50 ضريبة، آجلة بالكامل:\r\n--      Dr 1211 بـ 1,050 / Cr 4111 بـ 1,000 / Cr 2311 بـ 50 — والميزان متوازن.\r\n--   2. ترحيل الفاتورة نفسها مرة ثانية يفشل في القاعدة (uq_journal_source_active)\r\n--      حتى قبل فحص الدالة.\r\n--   3. أي DELETE على journal_entries يفشل دائمًا.\r\n--   4. مستخدم بلا دور (cashier/warehouse) يستدعي create_journal_entry يُرفض.\r\n--   5. نداء يدوي على حساب is_system (مثل 1491) يُرفض.\r\n--   6. كل قيد جديد له صف في audit_logs بـ action = 'journal_entry.posted'.\r\n-- ============================================================================"}	accounting_phase0_controls
20	{"-- ============================================================================\r\n-- 18_accounting_phase1_close_the_loop.sql — المرحلة 1: إغلاق مسار الترحيل\r\n-- (التقرير: ACCOUNTING_GAPS_AUDIT_REPORT_UPDATED.md — المهام T-06, T-07, T-08, T-09, T-10, T-12)\r\n--\r\n-- ماذا يفعل هذا الملف؟\r\n--   يجعل كل حدث مالي له قيد في دفتر الأستاذ، بلا تغيير أي سلوك تشغيلي:\r\n--\r\n--   T-06  ترحيل الفواتير تلقائيًا: post_sales_invoice / post_purchase_invoice\r\n--         تُستدعيان داخل create_sale / create_purchase بعد إنشاء الفاتورة.\r\n--         الفشل في الترحيل **يرجع العملية كلها** (نفس المعاملة) — فلا فاتورة\r\n--         مؤكدة بلا قيد، ولا قيد بلا فاتورة.\r\n--   T-07  قيد المصروف: post_expense يقيّد المصروف على حساب التصنيف\r\n--         (expense_categories.account_id) أو 5911 افتراضيًا، والضريبة على\r\n--         2311 (المستحقة علينا لأن المصروف دائن). record_expense_payment\r\n--         يقيّد الدفع على حساب الطريقة من الكتالوج (payment_method_ledger_account)\r\n--         أو expense_payments.account_id، وعكس المصروف وعكس الدفعة يعكسان القيد.\r\n--   T-08  قيدا المرتجعين: create_sales_return يعكس الإيراد/الضريبة/الذم،\r\n--         create_purchase_return يعكس المخزون/الضريبة/ذمم المورد.\r\n--   T-09  قيد تسوية المخزون: post_stock_adjustment — النقص مصروف 5921\r\n--         (فاقد وتلف)، والفائض إيراد/تسوية على 5911؟ لا — الفائض يُقيَّد\r\n--         مخزون مدين مقابل 5911 (مصروفات متنوعة الائتمان؟) — راجع القرار أدناه.\r\n--   T-10  قيد التحصيل: record_customer_payment و record_customer_advance_payment\r\n--         يقيّدان على حساب الطريقة من الكتالوج مقابل ذمم العميل.\r\n--   T-12  إيقاف greatest(balance - X, 0) في المرتجعين: الرصيد يُحدَّث فعليًا\r\n--         ويمكن أن يصير سالبًا (رصيد دائن مشروع)، مع قيد دفتر يقابله دائمًا.\r\n--\r\n-- ── قرار محاسبي في T-09 (توثيق مقصود) ───────────────────────────────────────\r\n--   النقص: Dr 5921 فاقد وتلف / Cr المخزون — الخسارة تظهر في قائمة الدخل.\r\n--   الفائض: Dr المخزون / Cr 5911 مصروفات متنوعة (تخفيض مصروف). اختيار 5911\r\n--   لأن دليل الحسابات لا يحوي حساب «فائض جرد»، و5911 هو الحساب المخصص للتسويات\r\n--   (ملاحظة البذرة: «قيم التسويات»). إن أراد المحاسب حسابًا مستقلًا يُضاف لاحقًا.\r\n--\r\n-- ── قرار محاسبي في T-08 (توثيق مقصود) ───────────────────────────────────────\r\n--   مرتجع المبيعات: Dr 2311 (ضريبة عكسية) + Dr 4111/4211/4311 (إيراد عكسي صافي)\r\n--     / Cr المخزون (COGS عكسي) + Cr 1211 (ذمة عكسية). كل الحسابات نفسها في\r\n--   قيد الفاتورة الأصلية بالأطراف المقلوبة، فصافي الفاتورة بعد مرتجعها الكامل صفر.\r\n--   مرتجع المشتريات: Dr 2111 (ذمة مورد عكسية) + Dr المخزون عكسيًا\r\n--     / Cr 1316 (ضريبة مدخلات عكسية) + Cr حساب المشتريات الأصلي.\r\n--\r\n-- ── قواعد التطبيق ───────────────────────────────────────────────────────────\r\n--   • لا يحذف ولا يعدّل أي بيانات ولا أي جدول ولا أعمدة.\r\n--   • يعيد تعريف دوال قائمة بلا تغيير التوقيعات — لا ينكسر أي مستدعٍ.\r\n--   • كل قيد يمر عبر create_journal_entry (فحص التوازن والترقيم والتدقيق\r\n--     من المرحلة 0) — بلا استثناء.\r\n--   • الترحيل التلقائي p_is_system = true كما في دوال الترحيل الأصلية، لكن\r\n--     الدوال ذاتها ترفض غير owner/manager/accountant — فالبيع كاشير؟\r\n--     **قرار مقصود**: create_sale للكاشير يظل يعمل ككتابة مستند، لكن ترحيله\r\n--     للأستاذ يحدث عبر EXCEPTION داخل المعاملة فقط إن كان المستدعي محاسبًا؛\r\n--     وحتى لا يُعطّل بيع الكاشير، فالترحيل التلقائي هنا يُنفَّذ بحرص:\r\n--     إن فشل الترحيل لغياب الصلاحية، تُرفع العملية كلها (المعاملة) — والكاشير\r\n--     لا يمكنه إنشاء فاتورة أصلاً إذا لم يُرحَّل. هذا مقصود: **أولوية إغلاق\r\n--     المسار أعلى من تمكين الكاشير**، ومن يريد كاشيرًا بلا ترحيل يرفع دوره\r\n--     إلى accountant أو يستخدم الترحيل اليدوي اللاحق. (موثّق، قابل للتغيير\r\n--     بقرار المطور في T-06-b إن ظهر الحاجة.)\r\n--   • آمن للتطبيق المتكرر (idempotent).\r\n-- ============================================================================\r\n\r\nBEGIN","-- ════════════════════\r\n-- T-06 — الترحيل التلقائي للفواتير داخل create_sale / create_purchase\r\n-- ════════════════════\r\n\r\n-- الدالة الجذرية الثلاثية: نهايتها فقط تتغير — إضافة استدعاء post_sales_invoice\r\n-- بعد كتابة سجل التدقيق وقبل RETURN. كل ما قبلها بلا حرف واحد.\r\nCREATE OR REPLACE FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id     uuid;\r\n  v_invoice_number text;\r\n  v_user           uuid := auth.uid();\r\n  v_line           record;\r\n  v_subtotal       numeric := 0;\r\n  v_tax_total      numeric := 0;\r\n  v_discount       numeric := coalesce(_discount, 0);\r\n  v_total          numeric := 0;\r\n  v_paid           numeric := 0;\r\n  v_outstanding    numeric := 0;\r\n  v_price          numeric;\r\n  v_tax_rate       numeric;\r\n  v_cost           numeric;\r\n  v_customer_balance numeric;\r\n  v_credit_limit   numeric;\r\n  v_line_total     numeric;\r\n  v_line_tax       numeric;\r\n  v_effect         text;\r\n  v_line_type      text;\r\n  v_sellable       boolean;\r\n  v_status         public.invoice_status;\r\n  v_last_item_id   uuid;\r\n  v_available      numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to post sales';\r\n  END IF;\r\n\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'Cart is empty';\r\n  END IF;\r\n\r\n  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN\r\n    RAISE EXCEPTION 'Unsupported payment method';\r\n  END IF;\r\n\r\n  IF v_discount < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot be negative';\r\n  END IF;\r\n\r\n  IF coalesce(_paid, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Paid amount cannot be negative';\r\n  END IF;\r\n\r\n  -- ============================================================== VALIDATION\r\n  -- Only lines whose policy is STOCK_ISSUE are stock-checked. Aggregating by\r\n  -- item and locking the inventory row protects against concurrent checkouts.\r\n  FOR v_line IN\r\n    SELECT r.o_product_id AS product_id, sum(r.o_quantity) AS quantity\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n    WHERE r.o_stock_effect = 'STOCK_ISSUE'\r\n    GROUP BY r.o_product_id\r\n    ORDER BY r.o_product_id\r\n  LOOP\r\n    SELECT i.quantity\r\n      INTO v_available\r\n    FROM public.inventory i\r\n    WHERE i.product_id = v_line.product_id\r\n      AND i.warehouse_id = _warehouse_id\r\n      AND i.owner_type = 'COMPANY'\r\n      AND i.owner_id IS NULL\r\n    FOR UPDATE;\r\n\r\n    v_available := coalesce(v_available, 0);\r\n\r\n    IF v_available < v_line.quantity THEN\r\n      RAISE EXCEPTION\r\n        'Insufficient stock for item %: available %, requested %',\r\n        v_line.product_id, v_available, v_line.quantity\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- Totals. Catalogue price wins for a catalogue item; the operator's price is\r\n  -- used only for ad-hoc service lines.\r\n  FOR v_line IN\r\n    SELECT r.o_product_id    AS product_id,\r\n           r.o_quantity      AS quantity,\r\n           r.o_service_name  AS service_name,\r\n           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,\r\n           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n  LOOP\r\n    IF v_line.quantity IS NULL OR v_line.quantity <= 0 THEN\r\n      RAISE EXCEPTION 'Every sale line requires a positive quantity';\r\n    END IF;\r\n\r\n    IF v_line.product_id IS NULL THEN\r\n      IF coalesce(v_line.service_name, '') = '' THEN\r\n        RAISE EXCEPTION 'Every service line requires a description';\r\n      END IF;\r\n      IF v_line.input_price < 0 OR v_line.input_tax < 0 OR v_line.input_tax > 100 THEN\r\n        RAISE EXCEPTION 'Service line \\"%\\" has an invalid price or tax rate', v_line.service_name;\r\n      END IF;\r\n      v_price    := v_line.input_price;\r\n      v_tax_rate := v_line.input_tax;\r\n    ELSE\r\n      SELECT p.sale_price, p.tax_rate, p.is_sellable\r\n        INTO v_price, v_tax_rate, v_sellable\r\n      FROM public.products p\r\n      WHERE p.id = v_line.product_id AND p.is_active = true\r\n      FOR UPDATE;\r\n\r\n      IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Item % is not available for sale', v_line.product_id;\r\n      END IF;\r\n\r\n      IF v_sellable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as sellable', v_line.product_id;\r\n      END IF;\r\n\r\n      IF v_price < 0 OR v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n        RAISE EXCEPTION 'Item % has invalid pricing or tax configuration', v_line.product_id;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := round(v_line.quantity * v_price, 2);\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + round(v_line_total * v_tax_rate / 100, 2);\r\n  END LOOP;\r\n\r\n  v_total := round(v_subtotal + v_tax_total - v_discount, 2);\r\n  IF v_discount > v_subtotal + v_tax_total OR v_total < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot exceed the invoice amount';\r\n  END IF;\r\n\r\n  IF _customer_id IS NOT NULL THEN\r\n    SELECT balance, credit_limit\r\n      INTO v_customer_balance, v_credit_limit\r\n    FROM public.customers\r\n    WHERE id = _customer_id AND is_active = true\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Selected customer is unavailable';\r\n    END IF;\r\n  END IF;\r\n\r\n  -- Tender above the total is change, not revenue and not credit.\r\n  v_paid := least(coalesce(_paid, 0), v_total);\r\n  v_outstanding := round(v_total - v_paid, 2);\r\n\r\n  IF v_outstanding > 0 AND _customer_id IS NULL THEN\r\n    RAISE EXCEPTION 'A customer is required when the sale has an unpaid amount';\r\n  END IF;\r\n  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN\r\n    RAISE EXCEPTION\r\n      'Credit limit exceeded: current balance %, requested debt %, limit %',\r\n      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);\r\n  END IF;\r\n\r\n  -- حالة الدورة: فاتورة أُنشئت وهي مؤكدة (أثرها المالي واقع بعد الإنشاء).\r\n  -- السداد له عمود مستقل فلا يمحو «مؤكدة».\r\n  v_status := 'confirmed'::public.invoice_status;\r\n\r\n  v_invoice_number := public.next_invoice_number();\r\n\r\n  INSERT INTO public.sales_invoices (\r\n    invoice_number, customer_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_invoice_number, _customer_id, _warehouse_id, v_status,\r\n    -- payment_status يُشتقّ من paid مقابل total، ولا يُكتب يدويًا.\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, v_discount, v_tax_total, v_total, v_paid,\r\n    _payment_method::public.payment_method, nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_invoice_id;\r\n\r\n  -- ================================================================== POSTING\r\n  FOR v_line IN\r\n    SELECT r.o_product_id   AS product_id,\r\n           r.o_quantity     AS quantity,\r\n           r.o_stock_effect AS stock_effect,\r\n           r.o_service_name AS service_name,\r\n           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,\r\n           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax,\r\n           nullif(btrim(coalesce(line ->> 'uom_id', '')), '')::uuid AS uom_id\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n  LOOP\r\n    v_cost := NULL;\r\n\r\n    IF v_line.product_id IS NULL THEN\r\n      v_price     := v_line.input_price;\r\n      v_tax_rate  := v_line.input_tax;\r\n      v_line_type := 'AD_HOC_SERVICE';\r\n      v_effect    := 'NONE';\r\n    ELSE\r\n      SELECT p.sale_price, p.tax_rate, p.cost_price\r\n        INTO v_price, v_tax_rate, v_cost\r\n      FROM public.products p WHERE p.id = v_line.product_id;\r\n\r\n      v_line_type := public.item_line_type(v_line.product_id, false);\r\n      -- Re-derive the effect at posting time so a policy change between\r\n      -- validation and posting cannot slip a movement through unannounced.\r\n      v_effect := public.item_stock_effect(v_line.product_id, 'out');\r\n\r\n      IF v_effect = 'STOCK_ISSUE' THEN\r\n        PERFORM public.post_stock_delta(\r\n          v_line.product_id,\r\n          _warehouse_id,\r\n          -v_line.quantity,\r\n          v_cost,\r\n          'ISSUE'::public.stock_movement_kind,\r\n          'sales_invoice',\r\n          v_invoice_id,\r\n          'POS sale',\r\n          'COMPANY'::public.owner_type,\r\n          NULL,\r\n          'sale'::public.movement_type\r\n        );\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := round(v_line.quantity * v_price, 2);\r\n    v_line_tax   := round(v_line_total * v_tax_rate / 100, 2);\r\n\r\n    INSERT INTO public.sales_invoice_items (\r\n      invoice_id, product_id, description, quantity, unit_price, discount, tax, total,\r\n      line_type, stock_effect, uom_id\r\n    )\r\n    VALUES (\r\n      v_invoice_id,\r\n      v_line.product_id,\r\n      CASE WHEN v_line.product_id IS NULL THEN v_line.service_name ELSE NULL END,\r\n      v_line.quantity, v_price, 0, v_line_tax, v_line_total + v_line_tax,\r\n      v_line_type, v_effect, v_line.uom_id\r\n    )\r\n    RETURNING id INTO v_last_item_id;\r\n\r\n    IF v_line_type = 'AD_HOC_SERVICE' THEN\r\n      INSERT INTO public.ad_hoc_service_lines (\r\n        invoice_id, invoice_item_id, description, quantity, unit_price,\r\n        discount, tax, total, created_by\r\n      )\r\n      VALUES (\r\n        v_invoice_id, v_last_item_id, v_line.service_name, v_line.quantity,\r\n        v_price, 0, v_line_tax, v_line_total + v_line_tax, v_user\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF v_outstanding > 0 THEN\r\n    UPDATE public.customers\r\n    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()\r\n    WHERE id = _customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, debit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',\r\n      now(), v_user, 'sale:' || v_invoice_id, 'قيد بيع آجل'\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'sale.posted', 'sales_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_number,\r\n      'warehouse_id', _warehouse_id,\r\n      'customer_id', _customer_id,\r\n      'payment_method', _payment_method,\r\n      'total', v_total,\r\n      'paid', v_paid,\r\n      'outstanding', v_outstanding,\r\n      'line_count', jsonb_array_length(_items)\r\n    ));\r\n\r\n  -- ── T-06: الترحيل التلقائي للأستاذ ────────────────────────────────────────\r\n  -- نفس المعاملة: إن فشل الترحيل (ميزان، حساب ناقص، صلاحية) تُلغى الفاتورة\r\n  -- وحركات المخزون وقيد الدفتر معها — لا فاتورة مؤكدة بلا قيد أبدًا.\r\n  -- post_sales_invoice تتحقق بنفسها من owner/manager/accountant، وترفض\r\n  -- الترحيل المزدوج عبر فهرس القاعدة (T-02) وفحصها الداخلي.\r\n  PERFORM public.post_sales_invoice(v_invoice_id);\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","COMMENT ON FUNCTION public.create_sale(uuid, uuid, text, numeric, numeric, text, jsonb) IS\r\n  'T-06: إنشاء فاتورة مبيعات وترحيلها تلقائيًا للأستاذ في نفس المعاملة.'","-- ════════════════════\r\n-- T-06 — الترحيل التلقائي للمشتريات داخل create_purchase\r\n-- ════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.create_purchase(_warehouse_id uuid, _supplier_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id     uuid;\r\n  v_invoice_no     text;\r\n  v_user           uuid := auth.uid();\r\n  v_item           jsonb;\r\n  v_subtotal       numeric := 0;\r\n  v_tax_total      numeric := 0;\r\n  v_total          numeric := 0;\r\n  v_qty            numeric;\r\n  v_cost           numeric;\r\n  v_tax_rate       numeric;\r\n  v_line_total     numeric;\r\n  v_line_tax       numeric;\r\n  v_product        uuid;\r\n  v_effect         text;\r\n  v_type           text;\r\n  v_purchasable    boolean;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse required';\r\n  END IF;\r\n  IF _supplier_id IS NULL THEN\r\n    RAISE EXCEPTION 'Supplier required';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  ------------------------------------------------------------------ validate\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    IF v_qty IS NULL OR v_qty <= 0 THEN\r\n      RAISE EXCEPTION 'Invalid quantity';\r\n    END IF;\r\n    IF v_cost IS NULL OR v_cost < 0 THEN\r\n      RAISE EXCEPTION 'Invalid unit cost';\r\n    END IF;\r\n    IF v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n      RAISE EXCEPTION 'Invalid tax rate';\r\n    END IF;\r\n    IF (v_item ->> 'product_id') IS NOT NULL THEN\r\n      SELECT p.is_purchasable INTO v_purchasable\r\n      FROM public.products p WHERE p.id = (v_item ->> 'product_id')::uuid;\r\n\r\n      IF v_purchasable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as purchasable', v_item ->> 'product_id';\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + v_line_tax;\r\n  END LOOP;\r\n\r\n  v_total := v_subtotal + v_tax_total - coalesce(_discount, 0);\r\n  v_invoice_no := public.next_purchase_number();\r\n\r\n  INSERT INTO public.purchase_invoices (\r\n    invoice_number, supplier_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_invoice_no, _supplier_id, _warehouse_id,\r\n    -- حالة الدورة: مشتريات أُنشئت مؤكدة — أثرها المخزني والمالي واقع.\r\n    'confirmed'::public.invoice_status,\r\n    -- حالة السداد مشتقّة، لا مكتوبة من مبلغ الدفع مباشرةً.\r\n    public.derive_payment_status(coalesce(_paid, 0), v_total),\r\n    v_subtotal, coalesce(_discount, 0), v_tax_total, v_total, coalesce(_paid, 0),\r\n    _payment_method::public.payment_method, nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_invoice_id;\r\n\r\n  --------------------------------------------------------------------- post\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_product  := (v_item ->> 'product_id')::uuid;\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n\r\n    SELECT r.o_line_type, r.o_stock_effect\r\n      INTO v_type, v_effect\r\n    FROM public.resolve_purchase_line(v_item) AS r;\r\n\r\n    INSERT INTO public.purchase_invoice_items (\r\n      invoice_id, product_id, quantity, unit_cost, discount, tax, total,\r\n      line_type, stock_effect\r\n    )\r\n    VALUES (\r\n      v_invoice_id, v_product, v_qty, v_cost, 0, v_line_tax, v_line_total + v_line_tax,\r\n      v_type, v_effect\r\n    );\r\n\r\n    -- Rule 5: only a TRACKED good increases stock. A service or an untracked\r\n    -- good is a pure expense: it changes no balance and no valuation.\r\n    IF v_effect = 'STOCK_RECEIPT' AND v_product IS NOT NULL THEN\r\n      PERFORM public.post_stock_delta(\r\n        v_product,\r\n        _warehouse_id,\r\n        v_qty,\r\n        v_cost,\r\n        'RECEIPT'::public.stock_movement_kind,\r\n        'purchase_invoice',\r\n        v_invoice_id,\r\n        'Purchase receipt',\r\n        'COMPANY'::public.owner_type,\r\n        NULL,\r\n        'purchase'::public.movement_type\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF coalesce(_paid, 0) < v_total THEN\r\n    UPDATE public.suppliers\r\n    SET balance = balance + (v_total - coalesce(_paid, 0)), updated_at = now()\r\n    WHERE id = _supplier_id;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'purchase.posted', 'purchase_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_no,\r\n      'supplier_id', _supplier_id,\r\n      'warehouse_id', _warehouse_id,\r\n      'total', v_total,\r\n      'paid', coalesce(_paid, 0),\r\n      'line_count', jsonb_array_length(_items)\r\n    ));\r\n\r\n  -- ── T-06: الترحيل التلقائي للأستاذ في نفس المعاملة ────────────────────────\r\n  PERFORM public.post_purchase_invoice(v_invoice_id);\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","COMMENT ON FUNCTION public.create_purchase(uuid, uuid, text, numeric, numeric, text, jsonb) IS\r\n  'T-06: إنشاء فاتورة مشتريات وترحيلها تلقائيًا للأستاذ في نفس المعاملة.'","-- ════════════════════\r\n-- T-08 + T-12 — قيد مرتجع المبيعات + إيقاف greatest(...,0)\r\n-- ════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.create_sales_return(_invoice_id uuid, _warehouse_id uuid, _customer_id uuid, _refund_method text, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id        uuid;\r\n  v_no        text;\r\n  v_user      uuid := auth.uid();\r\n  v_item      jsonb;\r\n  v_sub       numeric := 0;\r\n  v_tax       numeric := 0;\r\n  v_tot       numeric := 0;\r\n  v_qty       numeric;\r\n  v_price     numeric;\r\n  v_tr        numeric;\r\n  v_lt        numeric;\r\n  v_ltax      numeric;\r\n  v_p         uuid;\r\n  v_effect    text;\r\n  v_type      text;\r\n  v_entry     uuid;\r\n  v_lines     jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  r           record;\r\n  v_debits    numeric := 0;\r\n  v_credits   numeric := 0;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_qty   := (v_item ->> 'quantity')::numeric;\r\n    v_price := (v_item ->> 'unit_price')::numeric;\r\n    v_tr    := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n    v_lt    := v_qty * v_price;\r\n    v_ltax  := v_lt * v_tr / 100;\r\n    v_sub   := v_sub + v_lt;\r\n    v_tax   := v_tax + v_ltax;\r\n  END LOOP;\r\n  v_tot := v_sub + v_tax;\r\n  v_no  := public.next_sales_return_number();\r\n\r\n  INSERT INTO public.sales_returns (\r\n    return_number, invoice_id, customer_id, warehouse_id,\r\n    subtotal, tax, total, refund_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_no, _invoice_id, _customer_id, _warehouse_id,\r\n    v_sub, v_tax, v_tot, _refund_method::public.payment_method,\r\n    nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_p     := (v_item ->> 'product_id')::uuid;\r\n    v_qty   := (v_item ->> 'quantity')::numeric;\r\n    v_price := (v_item ->> 'unit_price')::numeric;\r\n    v_tr    := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n    v_lt    := v_qty * v_price;\r\n    v_ltax  := v_lt * v_tr / 100;\r\n\r\n    v_type   := public.item_line_type(v_p, false);\r\n    v_effect := public.item_stock_effect(v_p, 'in');\r\n\r\n    INSERT INTO public.sales_return_items (\r\n      return_id, product_id, quantity, unit_price, tax, total, line_type\r\n    )\r\n    VALUES (v_id, v_p, v_qty, v_price, v_ltax, v_lt + v_ltax, v_type);\r\n\r\n    -- Only a tracked good comes back into stock.\r\n    IF v_effect = 'STOCK_RECEIPT' THEN\r\n      PERFORM public.post_stock_delta(\r\n        v_p,\r\n        _warehouse_id,\r\n        v_qty,\r\n        v_price,\r\n        'RECEIPT'::public.stock_movement_kind,\r\n        'sales_return',\r\n        v_id,\r\n        'Sales return',\r\n        'COMPANY'::public.owner_type,\r\n        NULL,\r\n        'sale_return'::public.movement_type\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- T-12: الرصيد يتغير فعليًا. مرتجع أكبر من الرصيد يجعل الرصيد سالبًا\r\n  -- (دائنًا للعميل — التزام علينا) بدل إخفاء الفرق بـ greatest(...,0).\r\n  -- الدفتر أدناه يقيّد نفس المبلغ، فالرصيد والدفتر يبقيان متطابقين.\r\n  IF _customer_id IS NOT NULL THEN\r\n    UPDATE public.customers\r\n    SET balance = round(coalesce(balance, 0) - v_tot, 2), updated_at = now()\r\n    WHERE id = _customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, credit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      _customer_id, 'return', round(v_tot, 2), v_id, 'sales_return',\r\n      now(), v_user, 'return:' || v_id, 'مرتجع مبيعات'\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  -- ── T-08: قيد المرتجع في الأستاذ — أطراف قيد البيع المقلوبة ───────────────\r\n  -- إيراد عكسي (صافي ضريبة البند) + ضريبة عكسية على 2311، مقابل ذمة/نقد\r\n  -- ومخزون/COGS عكسي. لو استُرجعت فاتورة مرحَّلة كاملة صار صافي قيودها صفرًا.\r\n  IF _customer_id IS NOT NULL AND v_tot <> 0 THEN\r\n    -- الإيراد العكسي مجمّعًا حسب item_class، صافيًا من ضريبة البند.\r\n    FOR r IN\r\n      SELECT p.item_class,\r\n             sum(ri.total - coalesce(ri.tax, 0)) AS net_amount\r\n        FROM public.sales_return_items ri\r\n        LEFT JOIN public.products p ON p.id = ri.product_id\r\n       WHERE ri.return_id = v_id\r\n       GROUP BY p.item_class\r\n      HAVING sum(ri.total - coalesce(ri.tax, 0)) <> 0\r\n    LOOP\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', CASE r.item_class\r\n                          WHEN 'BY_PRODUCT' THEN '4211'\r\n                          WHEN 'SERVICE'    THEN '4311'\r\n                          ELSE '4111' END,\r\n        'debit', round(r.net_amount, 2),\r\n        'memo', 'مرتجع إيراد ' || coalesce(r.item_class, 'SALE'));\r\n    END LOOP;\r\n\r\n    IF v_tax <> 0 THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '2311', 'debit', round(v_tax, 2),\r\n        'memo', 'عكس ضريبة القيمة المضافة');\r\n    END IF;\r\n\r\n    -- الطرف المقابل: إن كان المرتجع مستردًا نقدًا/بنكًا فالخارج نقدًا،\r\n    -- وإلا فالخارج عكس الذمة (دائن للعميل).\r\n    v_cash_acct := public.payment_method_ledger_account(_refund_method);\r\n    IF v_cash_acct IS NOT NULL THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', v_cash_acct, 'credit', round(v_tot, 2),\r\n        'memo', 'استرداد للعميل');\r\n    ELSE\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '1211', 'credit', round(v_tot, 2),\r\n        'memo', 'عكس ذم العميل');\r\n    END IF;\r\n\r\n    -- عكس COGS للبضاعة التي عادت: مخزون مدين مقابل تكلفة مبيعات دائنة.\r\n    FOR r IN\r\n      SELECT p.item_class,\r\n             sum(ri.quantity * public.resolve_unit_cost(ri.product_id, _warehouse_id)) AS cost\r\n        FROM public.sales_return_items ri\r\n        JOIN public.products p ON p.id = ri.product_id\r\n       WHERE ri.return_id = v_id\r\n         AND public.item_stock_effect(ri.product_id, 'in') = 'STOCK_RECEIPT'\r\n       GROUP BY p.item_class\r\n    LOOP\r\n      IF r.cost IS NULL OR r.cost = 0 THEN\r\n        CONTINUE;\r\n      END IF;\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', CASE r.item_class\r\n                          WHEN 'RAW_MATERIAL' THEN '1311'\r\n                          WHEN 'BY_PRODUCT'   THEN '1314'\r\n                          ELSE '1313' END,\r\n        'debit', round(r.cost, 2),\r\n        'memo', 'مرتجع مخزون ' || r.item_class);\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '5111', 'credit', round(r.cost, 2),\r\n        'memo', 'عكس تكلفة البضاعة المباعة');\r\n    END LOOP;\r\n\r\n    -- التوازن النهائي وتسجيل القيد: balance_and_post_return يحسب المدين/الدائن\r\n    -- ويكتب فرق الهامش (سعر البيع مقابل التكلفة) على 5911 ثم يسجّل القيد.\r\n    SELECT coalesce(sum((ln->>'debit')::numeric), 0)\r\n      INTO v_debits\r\n      FROM jsonb_array_elements(v_lines) AS ln;\r\n    SELECT coalesce(sum((ln->>'credit')::numeric), 0)\r\n      INTO v_credits\r\n      FROM jsonb_array_elements(v_lines) AS ln;\r\n  END IF;\r\n\r\n  IF v_debits IS NOT NULL AND v_credits IS NOT NULL\r\n     AND (v_debits > 0 OR v_credits > 0) THEN\r\n    v_entry := public.balance_and_post_return(\r\n      'مرتجع مبيعات ' || v_no, CURRENT_DATE, 'sales_return', v_id, v_lines);\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'sales_return.posted', 'sales_return', v_id,\r\n    jsonb_build_object(\r\n      'return_number', v_no,\r\n      'invoice_id', _invoice_id,\r\n      'customer_id', _customer_id,\r\n      'total', v_tot,\r\n      'journal_entry_id', v_entry\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","-- ════════════════════\r\n-- دالة مساعدة: توازن سطور قيد مرتجع وتسجيله (تستخدمها المرتجعان)\r\n-- ════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.balance_and_post_return(p_memo text, p_date date, p_source_type text, p_source_id uuid, p_lines jsonb)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_d numeric := 0;\r\n  v_c numeric := 0;\r\n  v_diff numeric;\r\n  r jsonb;\r\n  v_lines jsonb := p_lines;\r\nBEGIN\r\n  FOR r IN SELECT * FROM jsonb_array_elements(v_lines) LOOP\r\n    v_d := v_d + coalesce((r->>'debit')::numeric, 0);\r\n    v_c := v_c + coalesce((r->>'credit')::numeric, 0);\r\n  END LOOP;\r\n\r\n  v_diff := round(v_d - v_c, 2);\r\n  IF v_diff <> 0 THEN\r\n    -- فرق الهامش (سعر البيع مقابل التكلفة) في المرتجع. يُكتب على 5911 —\r\n    -- الحساب المخصص للتسويات في الدليل — فيظهر في ميزان المراجعة ولا يُخفى.\r\n    IF v_diff > 0 THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '5911', 'credit', v_diff, 'memo', 'فارق قيمة المرتجع');\r\n    ELSE\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '5911', 'debit', -v_diff, 'memo', 'فارق قيمة المرتجع');\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN public.create_journal_entry(p_memo, p_date, p_source_type, p_source_id, true, v_lines);\r\nEND $$","COMMENT ON FUNCTION public.balance_and_post_return(text, date, text, uuid, jsonb) IS\r\n  'توازن سطور قيد مرتجع (يكتب فرق الهامش على 5911) ثم يسجّل قيدًا مزدوجًا.'",COMMIT,"-- ============================================================================\r\n-- التحقق بعد التطبيق:\r\n--   1. فاتورة مبيعات إنشاؤها عبر create_sale تُنتج صفًا في journal_entries\r\n--      (source_type='sales_invoice') مباشرة — بلا استدعاء يدوي.\r\n--   2. مرتجع مبيعات كامل لفاتورة مرحَّلة يجعل صافي أثر الحسابات المعنية صفرًا\r\n--      في trial_balance (إيراد عكسي + ضريبة عكسية + ذمة عكسية + COGS عكسي)\r\n--      باستثناء 5911 (فرق الهامش) إن وجد.\r\n--   3. مرتجع أكبر من رصيد العميل يجعل customers.balance سالبًا (دائن) —\r\n--      ولا يُخفى الفرق، والدفتر يطابق الرصيد.\r\n--   4. كل قيد جديد له صف في audit_logs بـ action='journal_entry.posted'،\r\n--      والمرتجع نفسه له 'sales_return.posted' مع journal_entry_id.\r\n-- ============================================================================"}	accounting_phase1_close_the_loop
21	{"-- ============================================================================\r\n-- 19_accounting_phase1b_returns_expenses_adjustments.sql\r\n-- المرحلة 1 (تكملة): T-07, T-08(مشتريات), T-09, T-10\r\n-- ══════════════\r\n-- يعتمد على 18 (دالة balance_and_post_return) وعلى المرحلة 0 (T-01..T-04).\r\n-- ── القرارات المحاسبية الموثّقة ──\r\n-- T-07 مصروف: Dr حساب التصنيف (أو 5911) صافيًا + Dr 1316 ضريبة مدخلات إن وجدت\r\n--            / Cr 2111 إن كان مورّدًا أو Cr حساب الطريقة (نقد/بنك) إن سُدّد.\r\n-- T-09 تسوية مخزون: النقص Dr 5921 / Cr المخزون؛ الفائض Dr المخزون / Cr 5911.\r\n-- T-10 تحصيل/دفعة مقدمة: Dr نقد/بنك (حسب الطريقة) / Cr 1211 ذم العميل.\r\n-- ══════════════════════\r\n\r\nBEGIN","-- ════════════════════\r\n-- T-08(ب) — قيد مرتجع المشتريات + إيقاف greatest(...,0) على رصيد المورد\r\n-- ════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.create_purchase_return(_invoice_id uuid, _warehouse_id uuid, _supplier_id uuid, _refund_method text, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id     uuid;\r\n  v_no     text;\r\n  v_user   uuid := auth.uid();\r\n  v_item   jsonb;\r\n  v_sub    numeric := 0;\r\n  v_tax    numeric := 0;\r\n  v_tot    numeric := 0;\r\n  v_qty    numeric;\r\n  v_cost   numeric;\r\n  v_tr     numeric;\r\n  v_lt     numeric;\r\n  v_ltax   numeric;\r\n  v_p      uuid;\r\n  v_effect text;\r\n  v_type   text;\r\n  v_avail  numeric;\r\n  v_entry  uuid;\r\n  v_lines  jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  r        record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_p    := (v_item ->> 'product_id')::uuid;\r\n    v_qty  := (v_item ->> 'quantity')::numeric;\r\n    v_cost := (v_item ->> 'unit_cost')::numeric;\r\n    v_tr   := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    v_effect := public.item_stock_effect(v_p, 'out');\r\n\r\n    -- Only a tracked good has stock to send back.\r\n    IF v_effect = 'STOCK_ISSUE' THEN\r\n      SELECT i.quantity INTO v_avail\r\n      FROM public.inventory i\r\n      WHERE i.product_id = v_p\r\n        AND i.warehouse_id = _warehouse_id\r\n        AND i.owner_type = 'COMPANY'\r\n        AND i.owner_id IS NULL;\r\n\r\n      IF coalesce(v_avail, 0) < v_qty THEN\r\n        RAISE EXCEPTION 'Insufficient stock for item %', v_p;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_lt   := v_qty * v_cost;\r\n    v_ltax := v_lt * v_tr / 100;\r\n    v_sub  := v_sub + v_lt;\r\n    v_tax  := v_tax + v_ltax;\r\n  END LOOP;\r\n  v_tot := v_sub + v_tax;\r\n  v_no  := public.next_purchase_return_number();\r\n\r\n  INSERT INTO public.purchase_returns (\r\n    return_number, invoice_id, supplier_id, warehouse_id,\r\n    subtotal, tax, total, refund_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_no, _invoice_id, _supplier_id, _warehouse_id,\r\n    v_sub, v_tax, v_tot, _refund_method::public.payment_method,\r\n    nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_p    := (v_item ->> 'product_id')::uuid;\r\n    v_qty  := (v_item ->> 'quantity')::numeric;\r\n    v_cost := (v_item ->> 'unit_cost')::numeric;\r\n    v_tr   := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n    v_lt   := v_qty * v_cost;\r\n    v_ltax := v_lt * v_tr / 100;\r\n\r\n    v_type   := public.item_line_type(v_p, false);\r\n    v_effect := public.item_stock_effect(v_p, 'out');\r\n\r\n    INSERT INTO public.purchase_return_items (\r\n      return_id, product_id, quantity, unit_cost, tax, total, line_type\r\n    )\r\n    VALUES (v_id, v_p, v_qty, v_cost, v_ltax, v_lt + v_ltax, v_type);\r\n\r\n    IF v_effect = 'STOCK_ISSUE' THEN\r\n      PERFORM public.post_stock_delta(\r\n        v_p,\r\n        _warehouse_id,\r\n        -v_qty,\r\n        v_cost,\r\n        'ISSUE'::public.stock_movement_kind,\r\n        'purchase_return',\r\n        v_id,\r\n        'Purchase return',\r\n        'COMPANY'::public.owner_type,\r\n        NULL,\r\n        'purchase_return'::public.movement_type\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- T-12: رصيد المورد يتغير فعليًا ويمكن أن يصير سالبًا (دائنًا لنا —\r\n  -- مبلغ مسترد مستحق) بدل إخفاء الفرق بـ greatest(...,0).\r\n  IF _supplier_id IS NOT NULL THEN\r\n    UPDATE public.suppliers\r\n    SET balance = round(coalesce(balance, 0) - v_tot, 2), updated_at = now()\r\n    WHERE id = _supplier_id;\r\n  END IF;\r\n\r\n  -- ── T-08(ب): قيد المرتجع — أطراف قيد المشتريات المقلوبة ──────────────────\r\n  IF v_tot <> 0 THEN\r\n    -- عكس المخزون/مصروف المشتريات (صافي ضريبة البند)، مجمّعًا حسب النوع.\r\n    FOR r IN\r\n      SELECT p.item_class,\r\n             sum(ri.total - coalesce(ri.tax, 0)) AS net_amount\r\n        FROM public.purchase_return_items ri\r\n        LEFT JOIN public.products p ON p.id = ri.product_id\r\n       WHERE ri.return_id = v_id\r\n       GROUP BY p.item_class\r\n      HAVING sum(ri.total - coalesce(ri.tax, 0)) <> 0\r\n    LOOP\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', CASE r.item_class\r\n                          WHEN 'RAW_MATERIAL' THEN '1311'\r\n                          WHEN 'BY_PRODUCT'   THEN '1314'\r\n                          WHEN 'SERVICE'      THEN '5911'\r\n                          ELSE '1313' END,\r\n        'credit', round(r.net_amount, 2),\r\n        'memo', 'مرتجع مشتريات ' || coalesce(r.item_class, 'GOOD'));\r\n    END LOOP;\r\n\r\n    IF v_tax <> 0 THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '1316', 'credit', round(v_tax, 2),\r\n        'memo', 'عكس ضريبة المدخلات');\r\n    END IF;\r\n\r\n    -- الطرف المدين: إن كان الاسترداد نقدًا/بنكًا فهو مدين نقدًا (استرِدّ فعلاً)،\r\n    -- وإلا فهو عكس ذمة المورد (مدين على 2111).\r\n    v_cash_acct := public.payment_method_ledger_account(_refund_method);\r\n    IF v_cash_acct IS NOT NULL THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', v_cash_acct, 'debit', round(v_tot, 2),\r\n        'memo', 'استرداد من المورد');\r\n    ELSE\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '2111', 'debit', round(v_tot, 2),\r\n        'memo', 'عكس ذمة المورد');\r\n    END IF;\r\n\r\n    v_entry := public.balance_and_post_return(\r\n      'مرتجع مشتريات ' || v_no, CURRENT_DATE, 'purchase_return', v_id, v_lines);\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'purchase_return.posted', 'purchase_return', v_id,\r\n    jsonb_build_object(\r\n      'return_number', v_no,\r\n      'invoice_id', _invoice_id,\r\n      'supplier_id', _supplier_id,\r\n      'total', v_tot,\r\n      'journal_entry_id', v_entry\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","COMMENT ON FUNCTION public.create_purchase_return(uuid, uuid, uuid, text, text, jsonb) IS\r\n  'T-08/T-12: مرتجع مشتريات بقيد أستاذ عكسي ورصيد مورد فعلي (قد يكون سالبًا).'","-- ════════════\r\n-- T-07 — قيد المصروف عند الترحيل + قيد الدفعة وعكسهما\r\n-- ════════════════════\r\n\r\n-- حاسم كود حساب التصنيف (أو الافتراضي 5911) وضريبة المصروف مجمعتين.\r\nCREATE OR REPLACE FUNCTION public.expense_ledger_summary(p_entry_id uuid, OUT o_net numeric, OUT o_tax numeric, OUT o_account_code text)\r\nRETURNS record\r\nLANGUAGE sql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT\r\n    round(COALESCE(sum(l.net_amount), 0), 2) AS o_net,\r\n    round(COALESCE(sum(l.tax_amount), 0), 2) AS o_tax,\r\n    COALESCE((SELECT a.code\r\n                FROM public.expense_categories c\r\n                JOIN public.accounts a ON a.id = c.account_id\r\n               WHERE c.id = (SELECT category_id\r\n                               FROM public.expense_lines\r\n                              WHERE entry_id = p_entry_id\r\n                              ORDER BY line_no LIMIT 1)\r\n                 AND c.account_id IS NOT NULL), '5911') AS o_account_code\r\n  FROM public.expense_lines l\r\n  WHERE l.entry_id = p_entry_id;\r\n$$","COMMENT ON FUNCTION public.expense_ledger_summary(uuid) IS\r\n  'T-07: صافي المصروف وضريبته وحسابه من التصنيف — مصدر وحيد لقيد المصروف.'","CREATE OR REPLACE FUNCTION public.post_expense(p_entry_id uuid, p_expected_version integer DEFAULT NULL::integer, p_pay_now boolean DEFAULT false, p_payment_method payment_method DEFAULT 'cash'::payment_method, p_account_label text DEFAULT NULL::text, p_payment_date date DEFAULT NULL::date, p_idempotency_key text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user  uuid := public.expense_actor();\r\n  v_entry public.expense_entries;\r\n  v_from  public.expense_status;\r\n  v_led   record;\r\n  v_entry_journal uuid;\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\nBEGIN\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  v_from := v_entry.status;\r\n\r\n  IF v_from = 'POSTED' THEN\r\n    RETURN v_entry;\r\n  END IF;\r\n\r\n  IF v_from NOT IN ('APPROVED', 'DRAFT') THEN\r\n    RAISE EXCEPTION 'This expense cannot be posted from status %', v_from\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.post');\r\n\r\n  IF p_expected_version IS NOT NULL AND p_expected_version <> v_entry.version THEN\r\n    RAISE EXCEPTION 'This expense was changed by someone else. Reload it and try again.'\r\n      USING ERRCODE = '40001';\r\n  END IF;\r\n\r\n  IF v_entry.total_amount <= 0 OR v_entry.line_count = 0 THEN\r\n    RAISE EXCEPTION 'Cannot post an expense with no lines' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  IF v_from = 'DRAFT' AND NOT public.expense_can(v_user, 'expense.approve') THEN\r\n    RAISE EXCEPTION 'Submit this expense for approval before posting it'\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  UPDATE public.expense_entries\r\n     SET status       = 'POSTED',\r\n         posting_date = COALESCE(posting_date, CURRENT_DATE),\r\n         posted_by    = v_user,\r\n         posted_at    = now(),\r\n         version      = version + 1\r\n   WHERE id = p_entry_id\r\n  RETURNING * INTO v_entry;\r\n\r\n  PERFORM public.expense_log_action(p_entry_id, 'posted', v_from, 'POSTED', NULL, v_user);\r\n\r\n  -- ── T-07: قيد المصروف في الأستاذ ──────────────────────────────────────────\r\n  -- Dr حساب المصروف (من التصنيف) صافيًا + Dr 1316 ضريبة مدخلات إن وجدت\r\n  -- / Cr الطرف: مورّد → 2111، وإلا → حساب طريقة الدفع (نقد/بنك) إذا سُدّد فورًا\r\n  -- أو 2221 مصروفات مستحقة إذا لم يُسدَّد بعد.\r\n  SELECT * INTO v_led FROM public.expense_ledger_summary(p_entry_id);\r\n\r\n  v_lines := v_lines || jsonb_build_object(\r\n    'account_code', v_led.o_account_code, 'debit', v_led.o_net,\r\n    'memo', 'مصروف ' || v_entry.reference);\r\n  IF v_led.o_tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1316', 'debit', v_led.o_tax,\r\n      'memo', 'ضريبة مدخلات على مصروف');\r\n  END IF;\r\n\r\n  v_cash_acct := public.payment_method_ledger_account(p_payment_method);\r\n  IF v_entry.payee_type = 'SUPPLIER' AND v_entry.supplier_id IS NOT NULL\r\n     AND NOT coalesce(p_pay_now, false) THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2111', 'credit', round(v_entry.total_amount, 2),\r\n      'memo', 'ذمة مورد — مصروف ' || v_entry.reference);\r\n  ELSIF coalesce(p_pay_now, false) AND v_cash_acct IS NOT NULL THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', v_cash_acct, 'credit', round(v_entry.total_amount, 2),\r\n      'memo', 'دفع مصروف ' || v_entry.reference);\r\n  ELSE\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2221', 'credit', round(v_entry.total_amount, 2),\r\n      'memo', 'مصروف مستحق الدفع');\r\n  END IF;\r\n\r\n  v_entry_journal := public.create_journal_entry(\r\n    'مصروف ' || v_entry.reference,\r\n    COALESCE(v_entry.expense_date, CURRENT_DATE),\r\n    'expense', p_entry_id, true, v_lines);\r\n\r\n  IF p_pay_now THEN\r\n    SELECT * INTO v_entry FROM public.record_expense_payment(\r\n      p_entry_id,\r\n      v_entry.total_amount,\r\n      COALESCE(p_payment_date, CURRENT_DATE),\r\n      p_payment_method,\r\n      p_account_label,\r\n      NULL,\r\n      'Settled at posting',\r\n      COALESCE(p_idempotency_key, 'post:' || p_entry_id::text),\r\n      p_account_id\r\n    );\r\n  END IF;\r\n\r\n  RETURN v_entry;\r\nEND $function$","COMMENT ON FUNCTION public.post_expense(uuid, integer, boolean, payment_method, text, date, text, uuid) IS\r\n  'T-07: ترحيل المصروف للاستحقاق مع قيد أستاذ مزدوج (مصروف+ضريبة مقابل ذمة/نقد/مستحق).'","-- قيد الدفعة: Dr نقد/بنك (من الكتالوج أو p_account_id) / Cr 2111 أو 2221\r\n-- (الطرف الائتماني نفسه الذي ورد في قيد الترحيل). التحديد: الدفعة تسدّد\r\n-- ذمة موجودة؛ بمعرفة payee_type نحدد الحساب الائتماني نفسه.\r\nCREATE OR REPLACE FUNCTION public.record_expense_payment(p_entry_id uuid, p_amount numeric, p_payment_date date DEFAULT CURRENT_DATE, p_payment_method payment_method DEFAULT 'cash'::payment_method, p_account_label text DEFAULT NULL::text, p_reference_no text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user      uuid := public.expense_actor();\r\n  v_entry     public.expense_entries;\r\n  v_amount    numeric(18,2);\r\n  v_existing  public.expense_payments;\r\n  v_label     text := nullif(btrim(coalesce(p_account_label, '')), '');\r\n  v_cash_acct text;\r\n  v_lines     jsonb := '[]'::jsonb;\r\n  v_entry_journal uuid;\r\n  v_credit_acct text;\r\nBEGIN\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.pay');\r\n\r\n  IF v_entry.status NOT IN ('POSTED', 'PARTIALLY_PAID') THEN\r\n    RAISE EXCEPTION 'Payments can only be recorded against posted expenses (current: %)', v_entry.status\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  v_amount := public.expense_round(p_amount);\r\n  IF v_amount <= 0 THEN\r\n    RAISE EXCEPTION 'Payment amount must be greater than zero' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  IF v_amount > v_entry.remaining_amount + 0.005 THEN\r\n    RAISE EXCEPTION 'Payment (%) exceeds remaining amount (%)', v_amount, v_entry.remaining_amount\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  -- If financial account provided, fetch label default if label is empty\r\n  IF p_account_id IS NOT NULL AND v_label IS NULL AND to_regclass('public.accounts') IS NOT NULL THEN\r\n    SELECT name_ar INTO v_label FROM public.accounts WHERE id = p_account_id;\r\n  END IF;\r\n\r\n  IF p_idempotency_key IS NOT NULL THEN\r\n    SELECT * INTO v_existing FROM public.expense_payments\r\n     WHERE idempotency_key = btrim(p_idempotency_key);\r\n    IF FOUND THEN\r\n      RETURN v_entry;\r\n    END IF;\r\n  END IF;\r\n\r\n  INSERT INTO public.expense_payments (\r\n    entry_id, amount, payment_date, payment_method,\r\n    account_label, reference_no, note, idempotency_key, created_by,\r\n    account_id\r\n  )\r\n  VALUES (\r\n    p_entry_id, v_amount, COALESCE(p_payment_date, CURRENT_DATE),\r\n    COALESCE(p_payment_method, 'cash'),\r\n    v_label,\r\n    nullif(btrim(coalesce(p_reference_no, '')), ''),\r\n    nullif(btrim(coalesce(p_note, '')), ''),\r\n    nullif(btrim(coalesce(p_idempotency_key, '')), ''),\r\n    v_user,\r\n    p_account_id\r\n  );\r\n\r\n  -- ── T-07: قيد الدفعة ─────────────────────────────────────────────────────\r\n  -- Dr حساب النقد/البنك (من p_account_id إن وُجد وإلا الكتالوج)\r\n  -- / Cr الحساب الائتماني نفسه (2111 للمورد، 2221 لمستحق عام).\r\n  IF p_account_id IS NOT NULL THEN\r\n    SELECT code INTO v_cash_acct FROM public.accounts WHERE id = p_account_id;\r\n  END IF;\r\n  IF v_cash_acct IS NULL THEN\r\n    v_cash_acct := public.payment_method_ledger_account(\r\n      COALESCE(p_payment_method::text, 'cash'));\r\n  END IF;\r\n  v_credit_acct := CASE\r\n    WHEN v_entry.payee_type = 'SUPPLIER' AND v_entry.supplier_id IS NOT NULL THEN '2111'\r\n    ELSE '2221' END;\r\n\r\n  v_lines := v_lines\r\n    || jsonb_build_object('account_code', v_cash_acct, 'debit', v_amount,\r\n                          'memo', 'سداد مصروف ' || v_entry.reference)\r\n    || jsonb_build_object('account_code', v_credit_acct, 'credit', v_amount,\r\n                          'memo', 'سداد مصروف ' || v_entry.reference);\r\n\r\n  v_entry_journal := public.create_journal_entry(\r\n    'سداد مصروف ' || v_entry.reference,\r\n    COALESCE(p_payment_date, CURRENT_DATE),\r\n    'expense_payment', (SELECT id FROM public.expense_payments\r\n                         WHERE entry_id = p_entry_id\r\n                         ORDER BY created_at DESC LIMIT 1), true, v_lines);\r\n\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id;\r\n\r\n  PERFORM public.expense_log_action(\r\n    p_entry_id, 'payment', v_entry.status, v_entry.status,\r\n    'Payment of ' || v_amount::text || ' ' || v_entry.currency_symbol || ' recorded',\r\n    v_user\r\n  );\r\n\r\n  RETURN v_entry;\r\nEND $function$","COMMENT ON FUNCTION public.record_expense_payment(uuid, numeric, date, payment_method, text, text, text, text, uuid) IS\r\n  'T-07: دفعة مصروف بقيد أستاذ (نقد/بنك مدين مقابل الذمة الائتمانية).'","-- عكس المصروف يعكس قيده في الأستاذ.\r\nCREATE OR REPLACE FUNCTION public.reverse_expense(p_entry_id uuid, p_reason text DEFAULT NULL::text)\r\n RETURNS expense_entries\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user     uuid := public.expense_actor();\r\n  v_entry    public.expense_entries;\r\n  v_reversal public.expense_entries;\r\n  v_original uuid;\r\nBEGIN\r\n  SELECT * INTO v_entry FROM public.expense_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Expense not found' USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  PERFORM public.expense_assert_capability(v_user, 'expense.reverse');\r\n\r\n  IF v_entry.status = 'REVERSED' THEN\r\n    RETURN v_entry;   -- idempotent: reversing twice is a no-op, not an error\r\n  END IF;\r\n  IF v_entry.status NOT IN ('POSTED', 'PARTIALLY_PAID', 'PAID') THEN\r\n    RAISE EXCEPTION 'Only a posted expense can be reversed (current: %)', v_entry.status\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n  -- Money already sitting in the drawer has to be dealt with through the\r\n  -- payment record, not by erasing the document that produced it.\r\n  IF v_entry.paid_amount > 0 THEN\r\n    RAISE EXCEPTION 'Reverse the recorded payments first (paid: %)', v_entry.paid_amount\r\n      USING ERRCODE = '55000';\r\n  END IF;\r\n\r\n  -- T-07: عكس قيد المصروف في الأستاذ قبل إنشاء المستند العكسي.\r\n  SELECT je.id INTO v_original\r\n    FROM public.journal_entries je\r\n   WHERE je.source_type = 'expense' AND je.source_id = p_entry_id\r\n     AND je.status <> 'REVERSED';\r\n  IF v_original IS NOT NULL THEN\r\n    PERFORM public.reverse_journal_entry(v_original,\r\n      COALESCE(NULLIF(btrim(COALESCE(p_reason, '')), ''), 'عكس المصروف'));\r\n  END IF;\r\n\r\n  INSERT INTO public.expense_entries (\r\n    reference, entry_type, status, source_kind,\r\n    payee_type, payee_name, supplier_id, employee_id,\r\n    warehouse_id, cost_center_id, project_id,\r\n    expense_date, posting_date, description, note,\r\n    tax_mode, currency, currency_symbol,\r\n    reversal_of, created_by, posted_by, posted_at\r\n  )\r\n  VALUES (\r\n    v_entry.reference || '-R',\r\n    v_entry.entry_type,\r\n    -- The reversal is itself posted: it is a recognised, immutable correction.\r\n    'POSTED',\r\n    v_entry.source_kind,\r\n    v_entry.payee_type, v_entry.payee_name, v_entry.supplier_id, v_entry.employee_id,\r\n    v_entry.warehouse_id, v_entry.cost_center_id, v_entry.project_id,\r\n    CURRENT_DATE, CURRENT_DATE,\r\n    'Reversal of ' || v_entry.reference,\r\n    nullif(btrim(coalesce(p_reason, '')), ''),\r\n    v_entry.tax_mode, v_entry.currency, v_entry.currency_symbol,\r\n    v_entry.id, v_user, v_user, now()\r\n  )\r\n  RETURNING * INTO v_reversal;\r\n\r\n  -- Mirror the lines so the reversal is a real, reportable document rather than\r\n  -- an amount with no category — otherwise the reversal would vanish from the\r\n  -- by-category report and leave that report showing an expense that no longer\r\n  -- exists.\r\n  INSERT INTO public.expense_lines (\r\n    entry_id, line_no, description, category_id, quantity, unit_price,\r\n    net_amount, tax_rate, tax_amount, gross_amount,\r\n    cost_center_id, project_id, note\r\n  )\r\n  SELECT\r\n    v_reversal.id, line_no, description, category_id, quantity, unit_price,\r\n    net_amount, tax_rate, tax_amount, gross_amount,\r\n    cost_center_id, project_id, note\r\n  FROM public.expense_lines\r\n  WHERE entry_id = p_entry_id\r\n  ORDER BY line_no;\r\n\r\n  UPDATE public.expense_entries\r\n     SET total_amount = v_entry.total_amount,\r\n         line_count   = v_entry.line_count\r\n   WHERE id = v_reversal.id\r\n  RETURNING * INTO v_reversal;\r\n\r\n  UPDATE public.expense_entries\r\n     SET status         = 'REVERSED',\r\n         reversed_by_id = v_reversal.id,\r\n         version        = version + 1\r\n   WHERE id = p_entry_id\r\n  RETURNING * INTO v_entry;\r\n\r\n  PERFORM public.expense_log_action(\r\n    p_entry_id, 'reversed', 'POSTED', 'REVERSED',\r\n    COALESCE(NULLIF(btrim(COALESCE(p_reason, '')), ''), 'Reversed'), v_user);\r\n\r\n  RETURN v_entry;\r\nEND $function$","COMMENT ON FUNCTION public.reverse_expense(uuid, text) IS\r\n  'T-07: عكس مصروف يعكس قيده في الأستاذ (reverse_journal_entry) قبل إنشاء المستند العكسي.'","-- ════════════════════\r\n-- T-09 — قيد تسوية المخزون\r\n-- ════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.post_stock_adjustment(_warehouse_id uuid, _reason text, _note text, _effective_date date, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user       uuid := auth.uid();\r\n  v_id         uuid;\r\n  v_number     text;\r\n  v_line       record;\r\n  v_policy     public.inventory_policy;\r\n  v_nature     public.item_nature;\r\n  v_total      numeric := 0;\r\n  v_line_total numeric;\r\n  v_entry      uuid;\r\n  v_stock_code text;\r\n  v_lines      jsonb := '[]'::jsonb;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'warehouse')\r\n    OR public.has_role(v_user, 'accountant')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to post stock adjustments';\r\n  END IF;\r\n\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n\r\n  IF coalesce(btrim(_reason), '') = '' THEN\r\n    RAISE EXCEPTION 'A documented reason is required for every stock adjustment';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'A stock adjustment requires at least one item';\r\n  END IF;\r\n\r\n  FOR v_line IN\r\n    SELECT (line ->> 'product_id')::uuid                 AS product_id,\r\n           (line ->> 'quantity')::numeric                AS quantity,\r\n           coalesce((line ->> 'unit_cost')::numeric, 0)  AS unit_cost,\r\n           nullif(btrim(coalesce(line ->> 'note', '')), '') AS note\r\n    FROM jsonb_array_elements(_items) AS line\r\n  LOOP\r\n    IF v_line.product_id IS NULL OR v_line.quantity IS NULL OR v_line.quantity = 0 THEN\r\n      RAISE EXCEPTION 'Every adjustment line requires an item and a non-zero quantity';\r\n    END IF;\r\n\r\n    SELECT p.item_nature INTO v_nature FROM public.products p WHERE p.id = v_line.product_id;\r\n    IF v_nature IS NULL THEN\r\n      RAISE EXCEPTION 'Item % does not exist', v_line.product_id;\r\n    END IF;\r\n    IF v_nature = 'SERVICE' THEN\r\n      RAISE EXCEPTION 'Item % is a SERVICE and has no inventory to adjust', v_line.product_id;\r\n    END IF;\r\n\r\n    v_policy := public.item_effective_policy(v_line.product_id);\r\n    IF v_policy <> 'TRACKED' THEN\r\n      RAISE EXCEPTION\r\n        'Item % has inventory policy %, so it has no inventory balance to adjust',\r\n        v_line.product_id, v_policy;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  v_number := public.next_stock_adjustment_number();\r\n\r\n  INSERT INTO public.stock_adjustments (document_number, warehouse_id, effective_date, reason, note, created_by)\r\n  VALUES (v_number, _warehouse_id, coalesce(_effective_date, current_date), btrim(_reason),\r\n          nullif(btrim(coalesce(_note, '')), ''), v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR v_line IN\r\n    SELECT (line ->> 'product_id')::uuid                 AS product_id,\r\n           (line ->> 'quantity')::numeric                AS quantity,\r\n           coalesce((line ->> 'unit_cost')::numeric, 0)  AS unit_cost,\r\n           nullif(btrim(coalesce(line ->> 'note', '')), '') AS note\r\n    FROM jsonb_array_elements(_items) AS line\r\n  LOOP\r\n    v_line_total := round(abs(v_line.quantity) * v_line.unit_cost, 2);\r\n    v_total := v_total + v_line_total;\r\n\r\n    -- حساب المخزون حسب item_class للقيد.\r\n    SELECT CASE p.item_class\r\n             WHEN 'RAW_MATERIAL' THEN '1311'\r\n             WHEN 'BY_PRODUCT'   THEN '1314'\r\n             ELSE '1313' END\r\n      INTO v_stock_code\r\n    FROM public.products p WHERE p.id = v_line.product_id;\r\n\r\n    INSERT INTO public.stock_adjustment_items (adjustment_id, product_id, quantity, unit_cost, total_cost, note)\r\n    VALUES (v_id, v_line.product_id, v_line.quantity, v_line.unit_cost, v_line_total, v_line.note);\r\n\r\n    -- signed quantity goes straight through: positive adds, negative removes.\r\n    PERFORM public.post_stock_delta(\r\n      v_line.product_id,\r\n      _warehouse_id,\r\n      v_line.quantity,\r\n      v_line.unit_cost,\r\n      'ADJUSTMENT'::public.stock_movement_kind,\r\n      'stock_adjustment',\r\n      v_id,\r\n      coalesce(v_line.note, btrim(_reason)),\r\n      'COMPANY'::public.owner_type,\r\n      NULL,\r\n      'adjustment'::public.movement_type\r\n    );\r\n\r\n    -- ── T-09: سطر القيد لهذا الصنف ──────────────────────────────────────\r\n    IF v_line.quantity < 0 THEN\r\n      v_lines := v_lines\r\n        || jsonb_build_object('account_code', '5921', 'debit', v_line_total,\r\n                              'memo', 'نقص جرد — ' || btrim(_reason))\r\n        || jsonb_build_object('account_code', v_stock_code, 'credit', v_line_total,\r\n                              'memo', 'مخزون');\r\n    ELSE\r\n      v_lines := v_lines\r\n        || jsonb_build_object('account_code', v_stock_code, 'debit', v_line_total,\r\n                              'memo', 'فائض جرد')\r\n        || jsonb_build_object('account_code', '5911', 'credit', v_line_total,\r\n                              'memo', 'فائض جرد — ' || btrim(_reason));\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- The DB constraint requires a coded reason on every adjustment movement.\r\n  UPDATE public.stock_movements\r\n  SET adjustment_reason = btrim(_reason)\r\n  WHERE source_type = 'stock_adjustment'\r\n    AND source_id = v_id\r\n    AND movement_kind = 'ADJUSTMENT'\r\n    AND adjustment_reason IS NULL;\r\n\r\n  UPDATE public.stock_adjustments SET total_value = v_total WHERE id = v_id;\r\n\r\n  -- ── T-09: قيد التسوية في الأستاذ ──────────────────────────────────────\r\n  IF v_total > 0 AND jsonb_array_length(v_lines) >= 2 THEN\r\n    v_entry := public.create_journal_entry(\r\n      'تسوية مخزون ' || v_number, coalesce(_effective_date, current_date),\r\n      'stock_adjustment', v_id, true, v_lines);\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'stock_adjustment.posted', 'stock_adjustment', v_id,\r\n    jsonb_build_object(\r\n      'document_number', v_number,\r\n      'warehouse_id', _warehouse_id,\r\n      'reason', btrim(_reason),\r\n      'effective_date', coalesce(_effective_date, current_date),\r\n      'lines', jsonb_array_length(_items),\r\n      'total_value', v_total,\r\n      'journal_entry_id', v_entry\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","COMMENT ON FUNCTION public.post_stock_adjustment(uuid, text, text, date, jsonb) IS\r\n  'T-09: تسوية مخزون بقيد أستاذ — نقص Dr 5921/Cr مخزون، فائض Dr مخزون/Cr 5911. (التوقيع والسلوك التشغيلي بلا تغيير — القيد إضافة).'","-- ════════════════════\r\n-- T-10 — قيد التحصيل والدفعة المقدمة\r\n-- ════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.record_customer_payment(_customer_id uuid, _invoice_id uuid, _amount numeric, _method text, _payment_date date, _note text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id uuid;\r\n  v_user uuid := auth.uid();\r\n  v_invoice record;\r\n  v_customer_balance numeric;\r\n  v_remaining numeric := round(coalesce(_amount, 0), 2);\r\n  v_allocation numeric;\r\n  v_outstanding numeric := 0;\r\n  v_stored_method text;\r\n  v_cash_acct text;\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_journal uuid;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'accountant')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to record customer payments';\r\n  END IF;\r\n\r\n  IF _customer_id IS NULL OR v_remaining <= 0 THEN\r\n    RAISE EXCEPTION 'A customer and a positive amount are required';\r\n  END IF;\r\n\r\n  -- الحارس الموحّد: يطبّع القيمة عبر كتالوج طرق الدفع ويعيد القيمة المخزّنة.\r\n  v_stored_method := public.resolve_writable_payment_method(\r\n    _method, 'customer_collection', true\r\n  );\r\n\r\n  -- صف العميل هو قفل التسلسل لكل سندات هذا العميل.\r\n  SELECT balance\r\n    INTO v_customer_balance\r\n  FROM public.customers\r\n  WHERE id = _customer_id\r\n    AND is_active = true\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Customer is unavailable';\r\n  END IF;\r\n\r\n  v_cash_acct := public.payment_method_ledger_account(v_stored_method);\r\n\r\n  IF _invoice_id IS NOT NULL THEN\r\n    SELECT id, total, paid, customer_id\r\n      INTO v_invoice\r\n    FROM public.sales_invoices\r\n    WHERE id = _invoice_id\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Invoice not found';\r\n    END IF;\r\n\r\n    IF v_invoice.customer_id IS DISTINCT FROM _customer_id THEN\r\n      RAISE EXCEPTION 'Invoice does not belong to this customer';\r\n    END IF;\r\n\r\n    IF v_invoice.total - v_invoice.paid <= 0 THEN\r\n      RAISE EXCEPTION 'Invoice has no outstanding balance';\r\n    END IF;\r\n\r\n    IF v_remaining > v_invoice.total - v_invoice.paid THEN\r\n      RAISE EXCEPTION 'Payment exceeds the invoice outstanding balance';\r\n    END IF;\r\n\r\n    INSERT INTO public.customer_payments (\r\n      customer_id, invoice_id, amount, payment_method, payment_date, note, created_by\r\n    )\r\n    VALUES (\r\n      _customer_id, _invoice_id, v_remaining, v_stored_method::public.payment_method,\r\n      coalesce(_payment_date, current_date), nullif(trim(_note), ''), v_user\r\n    )\r\n    RETURNING id INTO v_id;\r\n\r\n    INSERT INTO public.customer_ledger(customer_id, entry_type, credit, reference_id, reference_type, occurred_at, created_by, source_key, note)\r\n    VALUES (_customer_id, 'payment', v_remaining, v_id, 'customer_payment', coalesce(_payment_date, current_date)::timestamptz, v_user, 'payment:' || v_id, coalesce(nullif(trim(_note), ''), 'دفعة عميل'))\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n\r\n    UPDATE public.sales_invoices\r\n    SET paid = paid + v_remaining,\r\n        -- حالة الدورة تبقى «مؤكدة» — الدفع لا يغيّرها.\r\n        -- حالة السداد تُحدّث في عمودها المستقل.\r\n        status = 'confirmed'::public.invoice_status,\r\n        payment_status = public.derive_payment_status(paid + v_remaining, total),\r\n        updated_at = now()\r\n    WHERE id = _invoice_id;\r\n\r\n    -- ── T-10: قيد التحصيل ─────────────────────────────────────────────────\r\n    IF v_cash_acct IS NOT NULL THEN\r\n      v_lines := v_lines\r\n        || jsonb_build_object('account_code', v_cash_acct, 'debit', v_remaining,\r\n                              'memo', 'تحصيل من عميل')\r\n        || jsonb_build_object('account_code', '1211', 'credit', v_remaining,\r\n                              'memo', 'تحصيل من عميل');\r\n      v_journal := public.create_journal_entry(\r\n        'تحصيل من عميل — ' || coalesce(nullif(trim(_note), ''), ''),\r\n        COALESCE(_payment_date, CURRENT_DATE),\r\n        'customer_payment', v_id, true, v_lines);\r\n    END IF;\r\n\r\n  ELSE\r\n    -- لا فاتورة مختارة: تُستهلك أقدم الذمم أولًا.\r\n    SELECT coalesce(sum(total - paid), 0)\r\n      INTO v_outstanding\r\n    FROM public.sales_invoices\r\n    WHERE customer_id = _customer_id\r\n      AND total > paid\r\n      AND status NOT IN ('cancelled'::public.invoice_status, 'returned'::public.invoice_status);\r\n\r\n    IF v_outstanding <= 0 AND coalesce(v_customer_balance, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Customer has no outstanding balance. Record an explicit advance payment instead.';\r\n    END IF;\r\n    IF v_outstanding > 0 AND v_remaining > v_outstanding THEN\r\n      RAISE EXCEPTION 'Payment exceeds the customer outstanding balance';\r\n    END IF;\r\n\r\n    IF v_outstanding <= 0 THEN\r\n      IF v_remaining > v_customer_balance THEN\r\n        RAISE EXCEPTION 'Payment exceeds the customer outstanding balance';\r\n      END IF;\r\n\r\n      INSERT INTO public.customer_payments (\r\n        customer_id, invoice_id, amount, payment_method, payment_date, note, created_by\r\n      )\r\n      VALUES (\r\n        _customer_id, NULL, v_remaining, v_stored_method::public.payment_method,\r\n        coalesce(_payment_date, current_date),\r\n        coalesce(nullif(trim(_note), ''), 'سداد رصيد غير مرتبط بفاتورة'), v_user\r\n      )\r\n      RETURNING id INTO v_id;\r\n\r\n      INSERT INTO public.customer_ledger(customer_id, entry_type, credit, reference_id, reference_type, occurred_at, created_by, source_key, note)\r\n      VALUES (_customer_id, 'payment', v_remaining, v_id, 'customer_payment', coalesce(_payment_date, current_date)::timestamptz, v_user, 'payment:' || v_id, coalesce(nullif(trim(_note), ''), 'سداد رصيد غير مرتبط بفاتورة'))\r\n      ON CONFLICT (source_key) DO NOTHING;\r\n\r\n      -- ── T-10: قيد التحصيل ───────────────────────────────────────────────\r\n      IF v_cash_acct IS NOT NULL THEN\r\n        v_lines := v_lines\r\n          || jsonb_build_object('account_code', v_cash_acct, 'debit', v_remaining,\r\n                                'memo', 'تحصيل من عميل')\r\n          || jsonb_build_object('account_code', '1211', 'credit', v_remaining,\r\n                                'memo', 'تحصيل من عميل');\r\n        v_journal := public.create_journal_entry(\r\n          'تحصيل من عميل', COALESCE(_payment_date, CURRENT_DATE),\r\n          'customer_payment', v_id, true, v_lines);\r\n      END IF;\r\n\r\n      v_remaining := 0;\r\n    END IF;\r\n\r\n    FOR v_invoice IN\r\n      SELECT id, total, paid\r\n      FROM public.sales_invoices\r\n      WHERE customer_id = _customer_id\r\n        AND total > paid\r\n        AND status NOT IN ('cancelled'::public.invoice_status, 'returned'::public.invoice_status)\r\n      ORDER BY created_at, id\r\n      FOR UPDATE\r\n    LOOP\r\n      EXIT WHEN v_remaining <= 0;\r\n\r\n      v_allocation := least(v_remaining, v_invoice.total - v_invoice.paid);\r\n\r\n      INSERT INTO public.customer_payments (\r\n        customer_id, invoice_id, amount, payment_method, payment_date, note, created_by\r\n      )\r\n      VALUES (\r\n        _customer_id, v_invoice.id, v_allocation, v_stored_method::public.payment_method,\r\n        coalesce(_payment_date, current_date), nullif(trim(_note), ''), v_user\r\n      )\r\n      RETURNING id INTO v_id;\r\n\r\n      INSERT INTO public.customer_ledger(customer_id, entry_type, credit, reference_id, reference_type, occurred_at, created_by, source_key, note)\r\n      VALUES (_customer_id, 'payment', v_allocation, v_id, 'customer_payment', coalesce(_payment_date, current_date)::timestamptz, v_user, 'payment:' || v_id, coalesce(nullif(trim(_note), ''), 'دفعة عميل'))\r\n      ON CONFLICT (source_key) DO NOTHING;\r\n\r\n      UPDATE public.sales_invoices\r\n      SET paid = paid + v_allocation,\r\n          status = 'confirmed'::public.invoice_status,\r\n          payment_status = public.derive_payment_status(paid + v_allocation, total),\r\n          updated_at = now()\r\n      WHERE id = v_invoice.id;\r\n\r\n      -- ── T-10: قيد التحصيل لكل سند ────────────────────────────────────────\r\n      IF v_cash_acct IS NOT NULL THEN\r\n        v_lines := v_lines\r\n          || jsonb_build_object('account_code', v_cash_acct, 'debit', v_allocation,\r\n                                'memo', 'تحصيل من عميل')\r\n          || jsonb_build_object('account_code', '1211', 'credit', v_allocation,\r\n                                'memo', 'تحصيل من عميل');\r\n        v_journal := public.create_journal_entry(\r\n          'تحصيل من عميل', COALESCE(_payment_date, CURRENT_DATE),\r\n          'customer_payment', v_id, true, v_lines);\r\n        v_lines := '[]'::jsonb;\r\n      END IF;\r\n\r\n      v_remaining := v_remaining - v_allocation;\r\n    END LOOP;\r\n  END IF;\r\n\r\n  UPDATE public.customers\r\n  SET balance = round(coalesce(balance, 0) - _amount, 2), updated_at = now()\r\n  WHERE id = _customer_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (\r\n    v_user,\r\n    'customer_payment.recorded',\r\n    'customer',\r\n    _customer_id,\r\n    jsonb_build_object(\r\n      'invoice_id', _invoice_id,\r\n      'amount', _amount,\r\n      'method', v_stored_method,\r\n      'payment_date', coalesce(_payment_date, current_date),\r\n      'allocation', CASE WHEN _invoice_id IS NULL THEN 'oldest_first' ELSE 'selected_invoice' END,\r\n      'journal_entry_id', v_journal\r\n    )\r\n  );\r\n\r\n  RETURN v_id;\r\nEND;\r\n$function$","COMMENT ON FUNCTION public.record_customer_payment(uuid, uuid, numeric, text, date, text) IS\r\n  'T-10: تحصيل بقيد أستاذ (نقد/بنك مدين مقابل ذمم) — التوزيع على الأقدم بلا تغيير.'","-- الدفعة المقدمة الصريحة: قيدها Dr نقد/بنك / Cr 1211 (ذمة عكسية — عميل دائن).\r\nCREATE OR REPLACE FUNCTION public.record_customer_advance_payment(_customer_id uuid, _amount numeric, _method text, _payment_date date, _note text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id uuid;\r\n  v_user uuid := auth.uid();\r\n  v_stored_method text;\r\n  v_cash_acct text;\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_journal uuid;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'accountant')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to record customer payments';\r\n  END IF;\r\n\r\n  IF _customer_id IS NULL OR coalesce(_amount, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'A customer and a positive advance amount are required';\r\n  END IF;\r\n\r\n  v_stored_method := public.resolve_writable_payment_method(\r\n    _method, 'customer_collection', true\r\n  );\r\n\r\n  PERFORM 1 FROM public.customers\r\n  WHERE id = _customer_id AND is_active = true\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Customer is unavailable';\r\n  END IF;\r\n\r\n  INSERT INTO public.customer_payments (\r\n    customer_id, invoice_id, amount, payment_method, payment_date, note, created_by\r\n  )\r\n  VALUES (\r\n    _customer_id, NULL, round(_amount, 2), v_stored_method::public.payment_method,\r\n    coalesce(_payment_date, current_date),\r\n    coalesce(nullif(trim(_note), ''), 'دفعة مقدمة'), v_user\r\n  )\r\n  RETURNING id INTO v_id;\r\n\r\n  UPDATE public.customers\r\n  SET balance = round(coalesce(balance, 0) - _amount, 2), updated_at = now()\r\n  WHERE id = _customer_id;\r\n\r\n  INSERT INTO public.customer_ledger(customer_id, entry_type, credit, reference_id, reference_type, occurred_at, created_by, source_key, note)\r\n  VALUES (_customer_id, 'credit', round(_amount, 2), v_id, 'customer_payment', coalesce(_payment_date, current_date)::timestamptz, v_user, 'advance-payment:' || v_id, coalesce(nullif(trim(_note), ''), 'دفعة مقدمة'))\r\n  ON CONFLICT (source_key) DO NOTHING;\r\n\r\n  -- ── T-10: قيد الدفعة المقدمة — نقد مدين مقابل ذمة عكسية للعميل ──────────\r\n  v_cash_acct := public.payment_method_ledger_account(v_stored_method);\r\n  IF v_cash_acct IS NOT NULL THEN\r\n    v_lines := v_lines\r\n      || jsonb_build_object('account_code', v_cash_acct, 'debit', round(_amount, 2),\r\n                            'memo', 'دفعة مقدمة من عميل')\r\n      || jsonb_build_object('account_code', '1211', 'credit', round(_amount, 2),\r\n                            'memo', 'رصيد دائن للعميل — دفعة مقدمة');\r\n    v_journal := public.create_journal_entry(\r\n      'دفعة مقدمة من عميل', COALESCE(_payment_date, CURRENT_DATE),\r\n      'customer_advance_payment', v_id, true, v_lines);\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (\r\n    v_user, 'customer_advance_payment.recorded', 'customer', _customer_id,\r\n    jsonb_build_object('amount', _amount, 'method', v_stored_method,\r\n                       'payment_date', coalesce(_payment_date, current_date),\r\n                       'journal_entry_id', v_journal)\r\n  );\r\n\r\n  RETURN v_id;\r\nEND;\r\n$function$","COMMENT ON FUNCTION public.record_customer_advance_payment(uuid, numeric, text, date, text) IS\r\n  'T-10: دفعة مقدمة صريحة بقيد أستاذ (نقد مدين مقابل رصيد دائن للعميل على 1211).'",COMMIT,"-- ============================================================================\r\n-- التحقق بعد التطبيق:\r\n--   1. مرتجع مشتريات: قيد عكسي متوازن + رصيد مورد قد يصير سالبًا والدفتر يطابقه.\r\n--   2. مصروف POSTED: له قيد (مصروف + ضريبة مقابل ذمة/نقد/مستحق) وكل دفعة قيد.\r\n--   3. عكس مصروف مدفوع بالكامل يفشل (كما كان)، وعكس غير مدفوع يعكس القيد.\r\n--   4. تسوية نقص تُنتج مصروف 5921 في trial_balance، وفائض يُقيَّد Cr 5911.\r\n--   5. تحصيل ودفعة مقدمة تُنتج قيودًا متوازنة على حساب الطريقة من الكتالوج.\r\n--   6. لا قيد غير متوازن يمر (create_journal_entry يرفض، والمرتجعان يستعملان\r\n--      balance_and_post_return لفرق الهامش).\r\n-- =========================================================================="}	accounting_phase1b_returns_expenses_adjustments
22	{"-- ============================================================================\r\n-- 20_accounting_phase2_opening_balances.sql — المرحلة 2 (T-11)\r\n-- ترحيل الأقسام غير المرحَّلة في الأرصدة الافتتاحية للأستاذ.\r\n--\r\n--   CASH      → Dr 1101 (الصندوق)\r\n--   BANK      → Dr حساب من payment_method_ledger_account؟ لا — البنوك\r\n--               في الأرصدة الافتتاحية تُحدَّد بحساب البذرة: 1111 الافتراضي،\r\n--               أو payment_method_settings.default_account_id عند وجوده.\r\n--               البساطة والقرار: CASH وBANK كلاهما إلى 1101/1111 ثابتين\r\n--               (1111 للبنك) — تخصيص كل بنك لعائله ممكن لاحقًا عبر الشاشة.\r\n--   ASSET     → Dr حساب الأصول: لا معلومة نوع الأصل في سطر الافتتاح، فتُرحَّل\r\n--               إلى 1411 (آلات ومعدات) الافتراضي إن لم يُحدَّد account_id\r\n--               في السطر. (open_balance_lines لا يحمل account_id — راجع 08.)\r\n--   LIABILITY → Cr 2111 (ذم موردين عامة) الافتراضي.\r\n--   CAPITAL   → Cr 3111 (رأس المال) — هذا أهم سطر: الميزانية كانت عمياء عنه.\r\n--\r\n-- مع تقرير التوازن: post_opening_balance كان يرفض فحص التوازن على كل الأسطر\r\n-- ثم يترك غير المرحَّل بلا أثر — الآن يفحص التوازن ثم يرحّل **كل** الأقسام،\r\n-- فالتوازن الحسابي ينتقل إلى دفتر الأستاذ كاملًا.\r\n-- ════════════════════\r\n\r\nBEGIN","-- أولاً: عمود اختياري لتوجيه الحساب في سطر الافتتاح (اختياري لاحقًا عبر شاشة).\r\n-- إضافة آمنة: عمود جديد فقط، ولا يجري تغيير أي عمود قائم.\r\nALTER TABLE public.opening_balance_lines\r\n  ADD COLUMN IF NOT EXISTS ledger_account_code text","COMMENT ON COLUMN public.opening_balance_lines.ledger_account_code IS\r\n  'T-11: توجيه اختياري لحساب الترحيل. عند غيابه تُشتق من القسم (CASH→1101، BANK→1111، ASSET→1411، LIABILITY→2111، CAPITAL→3111).'","CREATE OR REPLACE FUNCTION public.post_opening_balance(_document_id uuid)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_doc     record;\r\n  v_debit   numeric;\r\n  v_credit  numeric;\r\n  v_capital numeric;\r\n  l         record;\r\n  v_lines   jsonb := '[]'::jsonb;\r\n  v_journal uuid;\r\n  v_acct    text;\r\n  v_section text;\r\nBEGIN\r\n  SELECT * INTO v_doc FROM public.opening_balance_documents WHERE id = _document_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Opening document not found';\r\n  END IF;\r\n  IF v_doc.status <> 'DRAFT' THEN\r\n    RAISE EXCEPTION 'Document % is already %', v_doc.document_number, v_doc.status;\r\n  END IF;\r\n\r\n  SELECT coalesce(sum(amount) FILTER (WHERE side='DEBIT'), 0),\r\n         coalesce(sum(amount) FILTER (WHERE side='CREDIT'), 0),\r\n         coalesce(sum(amount) FILTER (WHERE section='CAPITAL'), 0)\r\n    INTO v_debit, v_credit, v_capital\r\n    FROM public.opening_balance_lines WHERE document_id = _document_id;\r\n\r\n  IF v_debit <> v_credit THEN\r\n    RAISE EXCEPTION\r\n      'Opening entry does not balance: debits % vs credits % (difference %). Capital required is %. Correct the document before posting.',\r\n      round(v_debit, 2)::text,\r\n      round(v_credit, 2)::text,\r\n      round(v_debit - v_credit, 2)::text,\r\n      round(v_debit - v_credit, 2)::text;\r\n  END IF;\r\n\r\n  UPDATE public.opening_balance_documents\r\n     SET total_assets      = v_debit,\r\n         total_liabilities = v_credit - v_capital,\r\n         capital_required  = v_debit - v_credit + v_capital,\r\n         status            = 'POSTED',\r\n         posted_by         = v_user,\r\n         posted_at         = now()\r\n   WHERE id = _document_id;\r\n\r\n  FOR l IN SELECT * FROM public.opening_balance_lines WHERE document_id = _document_id ORDER BY id\r\n  LOOP\r\n    v_section := l.section;\r\n\r\n    IF l.section = 'STOCK' THEN\r\n      -- Real stock, through the real engine. Not a disguised purchase.\r\n      -- movement_type_legacy is set explicitly: the default is 'adjustment',\r\n      -- which the stock engine correctly refuses without an adjustment reason,\r\n      -- and which would file an opening entry under adjustments anyway.\r\n      PERFORM public.post_stock_delta(\r\n        p_product_id => l.product_id, p_warehouse_id => l.warehouse_id,\r\n        p_signed_qty => l.quantity, p_unit_cost => coalesce(l.unit_cost, 0),\r\n        p_movement_kind => 'OPENING', p_movement_type_legacy => 'opening',\r\n        p_source_type => 'opening_balance', p_source_id => _document_id,\r\n        p_note => 'رصيد افتتاحي ' || v_doc.document_number,\r\n        p_owner_type => 'COMPANY', p_owner_id => NULL);\r\n\r\n      PERFORM public.apply_cost_movement(\r\n        p_product_id => l.product_id, p_warehouse_id => l.warehouse_id,\r\n        p_signed_qty => l.quantity, p_incoming_cost => l.unit_cost,\r\n        p_source_type => 'opening_balance', p_source_id => _document_id,\r\n        p_note => 'رصيد افتتاحي ' || v_doc.document_number);\r\n\r\n      -- سطر المخزون في القيد (توجيه اختياري وإلا فحسب item_class).\r\n      SELECT COALESCE(l.ledger_account_code,\r\n                      CASE p.item_class\r\n                        WHEN 'RAW_MATERIAL' THEN '1311'\r\n                        WHEN 'BY_PRODUCT'   THEN '1314'\r\n                        ELSE '1313' END)\r\n        INTO v_acct\r\n      FROM public.products p WHERE p.id = l.product_id;\r\n\r\n      IF l.side = 'DEBIT' THEN\r\n        v_lines := v_lines || jsonb_build_object('account_code', v_acct,\r\n          'debit', round(l.amount, 2), 'memo', 'رصيد افتتاحي — ' || l.description);\r\n      END IF;\r\n\r\n    ELSIF l.section = 'RECEIVABLE' THEN\r\n      IF l.customer_id IS NULL THEN\r\n        RAISE EXCEPTION 'Receivable line \\"%\\" has no customer', l.description;\r\n      END IF;\r\n      -- 'adjustment' is the existing ledger value for a movement that is not a\r\n      -- sale, a payment or a return; reference_type carries the real reason.\r\n      INSERT INTO public.customer_ledger\r\n        (customer_id, entry_type, debit, credit, reference_id, reference_type,\r\n         occurred_at, created_by, note)\r\n      VALUES\r\n        (l.customer_id, 'adjustment', l.amount, 0, _document_id,\r\n         'opening_balance', v_doc.effective_date::timestamptz, v_user,\r\n         'رصيد افتتاحي ' || v_doc.document_number);\r\n\r\n      v_lines := v_lines || jsonb_build_object('account_code',\r\n        COALESCE(l.ledger_account_code, '1211'),\r\n        'debit', round(l.amount, 2), 'memo', 'رصيد افتتاحي — ' || l.description);\r\n\r\n    ELSIF l.section = 'PAYABLE' THEN\r\n      IF l.supplier_id IS NULL THEN\r\n        RAISE EXCEPTION 'Payable line \\"%\\" has no supplier', l.description;\r\n      END IF;\r\n      UPDATE public.suppliers\r\n         SET balance = coalesce(balance, 0) + l.amount\r\n       WHERE id = l.supplier_id;\r\n\r\n      v_lines := v_lines || jsonb_build_object('account_code',\r\n        COALESCE(l.ledger_account_code, '2111'),\r\n        'credit', round(l.amount, 2), 'memo', 'رصيد افتتاحي — ' || l.description);\r\n\r\n    ELSE\r\n      -- ── T-11: الأقسام المتبقية تُرحَّل إلى الأستاذ الآن (كانت NULL) ────────\r\n      v_acct := COALESCE(l.ledger_account_code,\r\n        CASE l.section\r\n          WHEN 'CASH'      THEN '1101'  -- الصندوق\r\n          WHEN 'BANK'      THEN '1111'  -- البنك الافتراضي\r\n          WHEN 'ASSET'     THEN '1411'  -- أصول ثابتة (افتراضي: آلات ومعدات)\r\n          WHEN 'LIABILITY' THEN '2111'  -- التزامات عامة (ذمم موردين)\r\n          WHEN 'CAPITAL'   THEN '3111'  -- رأس المال — أهم سطر\r\n          ELSE NULL END);\r\n\r\n      IF v_acct IS NULL THEN\r\n        RAISE EXCEPTION 'Opening section % has no ledger account mapping', l.section;\r\n      END IF;\r\n\r\n      v_lines := v_lines || jsonb_build_object('account_code', v_acct,\r\n        CASE WHEN l.side = 'DEBIT' THEN 'debit' ELSE 'credit' END,\r\n        round(l.amount, 2),\r\n        'memo', 'رصيد افتتاحي — ' || l.description);\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- ── T-11: قيد الأستاذ للرصيد الافتتاحي كاملًا ────────────────────────────\r\n  IF jsonb_array_length(v_lines) >= 2 THEN\r\n    v_journal := public.create_journal_entry(\r\n      'رصيد افتتاحي ' || v_doc.document_number,\r\n      v_doc.effective_date,\r\n      'opening_balance', _document_id, true, v_lines);\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'opening_balance.posted', 'opening_balance', _document_id,\r\n          jsonb_build_object('document_number', v_doc.document_number,\r\n                             'debits', v_debit, 'credits', v_credit,\r\n                             'journal_entry_id', v_journal));\r\n  RETURN _document_id;\r\nEND $function$","COMMENT ON FUNCTION public.post_opening_balance(uuid) IS\r\n  'T-11: ترحيل الأرصدة الافتتاحية كاملةً للأستاذ — النقدية والبنوك والأصول والالتزامات ورأس المال لم تعد بلا أثر.'",COMMIT,"-- ============================================================================\r\n-- التحقق بعد التطبيق:\r\n--   1. مستند افتتاحي «نقدية 50م / رأس مال 50م»: بعد الترحيل يظهر في\r\n--      trial_balance رصيد 1101 مدين 50,000,000 ورصيد 3111 دائن 50,000,000.\r\n--   2. العكس (reverse_opening_balance) يعكس القيد الأستاذي أيضًا — راجع تحديثه\r\n--      أدناه إن لزم (بقي قائمًا كما هو؛ العكس عبر reverse_journal_entry\r\n--      ممكن يدويًا على القيد المُنشأ).\r\n--   3. مستند متوازن على الورق يمر، ومتوزّن على الأستاذ يمر أيضًا — والميزانية\r\n--      ترى رأس المال لأول مرة.\r\n-- =========================================================================="}	accounting_phase2_opening_balances
23	{"-- ============================================================================\r\n-- 21_accounting_phase3_fiscal_periods.sql\r\n--\r\n-- المرحلة 3 من خطة معالجة الفجوات المحاسبية: الفترات المالية والإقفال السنوي.\r\n--\r\n--   T-19  جدول fiscal_periods (OPEN/CLOSED) + فحص التاريخ داخل create_journal_entry\r\n--   T-20  close_fiscal_year (ترحيل 4xxx/5xxx إلى 3911) + open_fiscal_year (أرصدة مشتقة)\r\n--\r\n-- لماذا هذا ضروري\r\n-- ---------------\r\n-- بلا فترات مالية لا فصل بين السنوات: قيد بتاريخ 2023 يمكن أن يُرحَّل اليوم\r\n-- ويغيّر أرباح سنة أُقفلت وطُبعت تقاريرها. ولا حماية من الترحيل الرجعي.\r\n-- و3911 (أرباح محتجزة) كان حسابًا بلا كاتب: لا شيء يقفل الإيرادات والمصروفات\r\n-- في نهاية السنة، فتبقى أرصدة 4xxx/5xxx متراكمة أبد الدهر.\r\n--\r\n-- قرارات التصميم\r\n-- --------------\r\n-- * الفترة مقفلة تعني: لا قيد جديد بتاريخها. القيود العكسية (REVERSED) تبقى\r\n--   مسموحة لأنها لا تنشئ رقمًا جديدًا — هي تُلغي رقمًا قائمًا، ومنعُها يترك\r\n--   خطأً لا يمكن تصحيحه. لذلك فحص التاريخ يرفض القيد العادي فقط، ويسمح\r\n--   بالعكس عبر علم p_is_reversal.\r\n--\r\n-- * لا تُقفل فترة قبل إقفال سنتها: إقفال السنة يكتب قيدًا بتاريخ 31/12، وهو\r\n--   قيد داخل الفترة. لو أُقفلت الفترة قبل الإقفال لاستحال الإقفال نفسه.\r\n--   الترتيب الإلزامي: (1) أنشئ فترات السنة، (2) اقفل السنة، (3) اقفل الفترات.\r\n--\r\n-- * ترحيل الإقفال يُلغي أرصدة 4xxx/5xxx في 3911. الإيرادات مدينة، المصروفات\r\n--   دائنة، والفرق إلى 3911. النتيجة: ميزان المراجعة يبدأ السنة الجديدة\r\n--   بأرصدة 1xxx/2xxx/3xxx فقط، كما تفعل الدفاتر الحقيقية.\r\n--\r\n-- * open_fiscal_year لا يكتب أي قيد: الأرصدة الافتتاحية للسنة الجديدة هي\r\n--   نتاج القيود القائمة، تمامًا كما في trial_balance. كتابة قيد افتتاحي\r\n--   ثانٍ تعني مصدرًا ثانيًا للحقيقة يمكن أن يخالف القيود.\r\n--\r\n-- NON-DESTRUCTIVE: جدول جديد + دالتان جديدتان + إعادة تعريف create_journal_entry\r\n-- بتوقيع أوسع (مع توافق خلفي للنُسخ القديمة). لا حذف ولا تعديل لأي بيانات قائمة.\r\n--\r\n-- معايير القبول المغطاة:\r\n--   - إقفال سنة 2025 بفترة مقفلة: 4xxx/5xxx تصبح صفرًا، 3911 يحمل صافي الربح.\r\n--   - قيد يدوي بتاريخ سنة مقفلة يُرفض في القاعدة.\r\n--   - قيد عكسي بتاريخ مقفول يُقبل (تصحيح خطأ في سنة مقفلة).\r\n--   - السنة الجديدة تبدأ بأرصدة 1xxx/2xxx/3xxx من القيود، بلا قيد افتتاحي مصطنع.\r\n-- ============================================================================\r\n\r\n-- ── 1. جدول الفترات المالية ─────────────────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS public.fiscal_periods (\r\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  code        text NOT NULL UNIQUE,                 -- مثل '2025-01'\r\n  fiscal_year integer NOT NULL,\r\n  period_no   integer NOT NULL CHECK (period_no BETWEEN 1 AND 12),\r\n  start_date  date NOT NULL,\r\n  end_date    date NOT NULL,\r\n  status      text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','CLOSED')),\r\n  closed_at   timestamptz,\r\n  closed_by   uuid REFERENCES auth.users(id),\r\n  notes       text,\r\n  created_at  timestamptz NOT NULL DEFAULT now(),\r\n  CONSTRAINT fiscal_period_dates_ordered CHECK (end_date >= start_date),\r\n  CONSTRAINT fiscal_period_unique_span UNIQUE (start_date, end_date)\r\n)","CREATE INDEX IF NOT EXISTS ix_fiscal_periods_dates\r\n  ON public.fiscal_periods (start_date, end_date)","CREATE INDEX IF NOT EXISTS ix_fiscal_periods_year\r\n  ON public.fiscal_periods (fiscal_year, period_no)","COMMENT ON TABLE public.fiscal_periods IS\r\n  'T-19: الفترات المالية. فترة مقفلة تمنع أي قيد جديد بتاريخها، وتُقفل بعد إقفال سنتها لا قبلها.'","-- تمنع الفترات المتداخلة: تداخل فترتين يعني أن التاريخ يقع في فترتين،\r\n-- وأيهما يحكم قرار الإقفال يصبح سؤالًا بلا جواب.\r\nDO $$\r\nBEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM pg_constraint WHERE conname = 'fiscal_period_no_overlap'\r\n  ) THEN\r\n    ALTER TABLE public.fiscal_periods\r\n      ADD CONSTRAINT fiscal_period_no_overlap\r\n      EXCLUDE USING gist (\r\n        daterange(start_date, end_date, '[]') WITH &&\r\n      );\r\n  END IF;\r\nEND $$","-- ── 2. بذر السنة الحالية (غير مقفلة) ────────────────────────────────────────\r\n-- 12 فترة شهرية للسنة الجارية، OPEN، آمنة لإعادة التطبيق.\r\nINSERT INTO public.fiscal_periods (code, fiscal_year, period_no, start_date, end_date, status)\r\nSELECT\r\n  to_char(d, 'YYYY-MM'),\r\n  EXTRACT(YEAR FROM d)::integer,\r\n  EXTRACT(MONTH FROM d)::integer,\r\n  d,\r\n  (date_trunc('month', d) + interval '1 month - 1 day')::date,\r\n  'OPEN'\r\nFROM generate_series(\r\n       date_trunc('year', CURRENT_DATE),\r\n       date_trunc('year', CURRENT_DATE) + interval '11 months',\r\n       interval '1 month'\r\n     ) AS g(d)\r\nON CONFLICT (code) DO NOTHING","-- ── 3. دالة فحص الفترة (OPEN فقط يسمح بالترحيل) ─────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.assert_period_open(p_date date)\r\nRETURNS void\r\nLANGUAGE plpgsql\r\nSTABLE\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_status text;\r\nBEGIN\r\n  IF p_date IS NULL THEN\r\n    RETURN;\r\n  END IF;\r\n\r\n  SELECT status INTO v_status\r\n    FROM public.fiscal_periods\r\n   WHERE p_date BETWEEN start_date AND end_date\r\n   LIMIT 1;\r\n\r\n  -- تاريخ خارج أي فترة مُعرَّفة: يُسمح به (فترة غير مفتوحة بعد). القفل يُطبَّق\r\n  -- على الفترات المُعرَّفة والمقفلة فقط، لا على تاريخ لا تنظيم له.\r\n  IF v_status IS NULL THEN\r\n    RETURN;\r\n  END IF;\r\n\r\n  IF v_status = 'CLOSED' THEN\r\n    RAISE EXCEPTION\r\n      'الفترة المالية المحتوية على % مقفلة. لا يمكن الترحيل بتاريخ مقفول.',\r\n      to_char(p_date, 'YYYY-MM-DD');\r\n  END IF;\r\nEND $$","REVOKE ALL ON FUNCTION public.assert_period_open(date) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.assert_period_open(date) TO authenticated, service_role","COMMENT ON FUNCTION public.assert_period_open(date) IS\r\n  'T-19: يرفض الترحيل داخل فترة مقفلة. التواريخ خارج الفترات المُعرَّفة تُسمح.'","-- ── 4. create_journal_entry مع فحص الفترة وعلم العكس ────────────────────────\r\n-- التوقيع القديم (6 وسائط) محفوظ كغلاف (wrapper) يفوّض إلى التوقيع الجديد\r\n-- (7 وسائط)، فيبقى كل نداء قديم صالحًا كما هو.\r\nCREATE OR REPLACE FUNCTION public.create_journal_entry(\r\n  p_memo          text,\r\n  p_entry_date    date DEFAULT CURRENT_DATE,\r\n  p_source_type   text DEFAULT NULL,\r\n  p_source_id     uuid DEFAULT NULL,\r\n  p_is_system     boolean DEFAULT false,\r\n  p_lines         jsonb DEFAULT '[]'::jsonb,\r\n  p_is_reversal   boolean DEFAULT false\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_id   uuid;\r\n  v_num  text;\r\n  v_d    numeric := 0;\r\n  v_c    numeric := 0;\r\n  src    jsonb;\r\n  v_missing integer;\r\n  v_blocked integer;\r\n  v_sideless text;\r\n  v_system_accounts integer;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  -- T-03: فحص الدور — القيد اليدوي (p_is_system=false) للمحاسبة فقط.\r\n  -- القيد النظامي (من دوال الترحيل SECURITY DEFINER) مسموح لأي موظف مصادق:\r\n  -- فالكاشير يبيع عبر create_sale، وترحيل فاتورته جزء من نفس العملية\r\n  -- (قرار T-06-b المعتمد: مسار POS يستمر مع الترحيل التلقائي).\r\n  IF NOT coalesce(p_is_system, false) THEN\r\n    IF NOT (public.has_role(v_user, 'owner')\r\n            OR public.has_role(v_user, 'manager')\r\n            OR public.has_role(v_user, 'accountant')) THEN\r\n      RAISE EXCEPTION 'Only an owner, manager or accountant may create manual journal entries';\r\n    END IF;\r\n  END IF;\r\n\r\n  IF p_memo IS NULL OR btrim(p_memo) = '' THEN\r\n    RAISE EXCEPTION 'A journal entry needs a description';\r\n  END IF;\r\n  IF p_lines IS NULL OR jsonb_array_length(p_lines) < 2 THEN\r\n    RAISE EXCEPTION 'A journal entry needs at least two lines - one to debit and one to credit';\r\n  END IF;\r\n\r\n  -- A line must carry exactly one side. Checked up front, before the entry\r\n  -- header is written, so a rejected line never leaves a DRAFT entry behind\r\n  -- in the table for someone to find later and wonder about.\r\n  SELECT string_agg(coalesce(ln->>'account_code', '?'), '، ') INTO v_sideless\r\n    FROM jsonb_array_elements(p_lines) AS ln\r\n   WHERE coalesce((ln->>'debit')::numeric, 0) = 0\r\n     AND coalesce((ln->>'credit')::numeric, 0) = 0;\r\n  IF v_sideless IS NOT NULL THEN\r\n    RAISE EXCEPTION\r\n      'Line(s) % carry neither a debit nor a credit. Every line must have exactly one side.',\r\n      v_sideless;\r\n  END IF;\r\n\r\n  -- T-03: اليدوي لا يلمس حسابات النظام. دوال الترحيل تمرر p_is_system = true\r\n  -- فتعمل كما كانت؛ النداء اليدوي (false) يُرفض إن كان أي حساب هدفه نظاميًا.\r\n  IF NOT coalesce(p_is_system, false) THEN\r\n    SELECT count(*) INTO v_system_accounts\r\n      FROM jsonb_array_elements(p_lines) AS ln\r\n      JOIN public.accounts a ON a.code = ln->>'account_code'\r\n     WHERE a.is_system;\r\n    IF v_system_accounts > 0 THEN\r\n      RAISE EXCEPTION\r\n        '% line(s) target a system account. Manual entries cannot post to system accounts.',\r\n        v_system_accounts;\r\n    END IF;\r\n  END IF;\r\n\r\n  -- T-19: لا قيد جديد بتاريخ فترة مقفلة. القيد العكسي مستثنى: هو يُلغي قيدًا\r\n  -- قائمًا ولا ينشئ رقمًا جديدًا، ومنعُه يترك خطأً لا يمكن تصحيحه.\r\n  IF NOT coalesce(p_is_reversal, false) THEN\r\n    PERFORM public.assert_period_open(coalesce(p_entry_date, CURRENT_DATE));\r\n  END IF;\r\n\r\n  v_num := public.next_journal_number(coalesce(p_entry_date, CURRENT_DATE));\r\n\r\n  INSERT INTO public.journal_entries\r\n    (entry_number, entry_date, memo, source_type, source_id, is_system, created_by)\r\n  VALUES (v_num, coalesce(p_entry_date, CURRENT_DATE), btrim(p_memo),\r\n          p_source_type, p_source_id, p_is_system, v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR src IN SELECT * FROM jsonb_array_elements(p_lines)\r\n  LOOP\r\n    v_d := v_d + coalesce((src->>'debit')::numeric, 0);\r\n    v_c := v_c + coalesce((src->>'credit')::numeric, 0);\r\n  END LOOP;\r\n\r\n  IF v_d <> v_c THEN\r\n    RAISE EXCEPTION\r\n      'Entry does not balance: debits % vs credits % (difference %). An entry that cannot balance is not an entry.',\r\n      round(v_d, 2)::text, round(v_c, 2)::text, round(v_d - v_c, 2)::text;\r\n  END IF;\r\n  IF v_d <= 0 THEN\r\n    RAISE EXCEPTION 'Entry total must be greater than zero';\r\n  END IF;\r\n\r\n  -- The two failure modes are reported separately: \\"code does not exist\\" sends\r\n  -- the operator hunting for a typo when the code was real and simply not\r\n  -- postable, and that misdirection costs more than the extra check.\r\n  SELECT count(*) FILTER (WHERE a.id IS NULL),\r\n         count(*) FILTER (WHERE a.id IS NOT NULL AND NOT a.is_postable)\r\n    INTO v_missing, v_blocked\r\n    FROM jsonb_array_elements(p_lines) AS ln\r\n    LEFT JOIN public.accounts a ON a.code = ln->>'account_code';\r\n\r\n  IF v_missing > 0 THEN\r\n    RAISE EXCEPTION 'One or more account codes do not exist. Check the code before posting.';\r\n  END IF;\r\n  IF v_blocked > 0 THEN\r\n    RAISE EXCEPTION\r\n      'One or more accounts is not postable directly (a contra or clearing account). Post through the account that moves it.';\r\n  END IF;\r\n\r\n  INSERT INTO public.journal_lines (entry_id, account_id, debit, credit, memo, partner_type, partner_id)\r\n  SELECT v_id, a.id,\r\n         coalesce((ln->>'debit')::numeric, 0),\r\n         coalesce((ln->>'credit')::numeric, 0),\r\n         nullif(btrim(coalesce(ln->>'memo','')), ''),\r\n         nullif(btrim(coalesce(ln->>'partner_type','')), ''),\r\n         (ln->>'partner_id')::uuid\r\n    FROM jsonb_array_elements(p_lines) AS ln\r\n    JOIN public.accounts a ON a.code = ln->>'account_code'\r\n   WHERE (ln->>'debit')::numeric IS DISTINCT FROM 0\r\n      OR (ln->>'credit')::numeric IS DISTINCT FROM 0;\r\n\r\n  IF (SELECT count(*) FROM public.journal_lines WHERE entry_id = v_id)\r\n     <> jsonb_array_length(p_lines) THEN\r\n    RAISE EXCEPTION 'One or more lines could not be written';\r\n  END IF;\r\n\r\n  UPDATE public.journal_entries\r\n     SET total_debit = v_d, total_credit = v_c, status = 'POSTED',\r\n         posted_by = v_user, posted_at = now()\r\n   WHERE id = v_id;\r\n\r\n  -- T-03: كل قيد له أثر في سجل التدقيق.\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'journal_entry.posted', 'journal_entry', v_id,\r\n          jsonb_build_object('entry_number', v_num,\r\n                             'entry_date', coalesce(p_entry_date, CURRENT_DATE),\r\n                             'source_type', p_source_type,\r\n                             'source_id', p_source_id,\r\n                             'total', v_d,\r\n                             'is_reversal', coalesce(p_is_reversal, false)));\r\n\r\n  RETURN v_id;\r\nEND $function$","COMMENT ON FUNCTION public.create_journal_entry(text, date, text, uuid, boolean, jsonb, boolean) IS\r\n  'T-03/T-19: إنشاء قيد مزدوج مع فحص الدور، ومنع اليدوي على حسابات النظام، وسجل تدقيق، ومنع الترحيل في فترة مقفلة.'","-- الغلاف الخلفي: التوقيع القديم 6 وسائط → 7 وسائط.\r\nDROP FUNCTION IF EXISTS public.create_journal_entry(text, date, text, uuid, boolean, jsonb)","CREATE OR REPLACE FUNCTION public.create_journal_entry(\r\n  p_memo          text,\r\n  p_entry_date    date,\r\n  p_source_type   text,\r\n  p_source_id     uuid,\r\n  p_is_system     boolean,\r\n  p_lines         jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE sql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT public.create_journal_entry(\r\n    p_memo, p_entry_date, p_source_type, p_source_id, p_is_system, p_lines, false\r\n  );\r\n$$","COMMENT ON FUNCTION public.create_journal_entry(text, date, text, uuid, boolean, jsonb) IS\r\n  'غلاف خلفي للتوافق مع النداءات القديمة (6 وسائط) → التوقيع الجديد مع فحص الفترة.'","REVOKE ALL ON FUNCTION public.create_journal_entry(text, date, text, uuid, boolean, jsonb, boolean) FROM PUBLIC, anon","REVOKE ALL ON FUNCTION public.create_journal_entry(text, date, text, uuid, boolean, jsonb) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.create_journal_entry(text, date, text, uuid, boolean, jsonb, boolean)\r\n  TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.create_journal_entry(text, date, text, uuid, boolean, jsonb)\r\n  TO authenticated, service_role","-- ── 5. reverse_journal_entry يمرّر علم العكس ─────────────────────────────────\r\n-- يعاد تعريفها لتستدعي التوقيع الجديد بـ p_is_reversal = true، فتُقبل حتى\r\n-- داخل فترة مقفلة (تصحيح خطأ سنة مقفلة بلا فتحها).\r\nCREATE OR REPLACE FUNCTION public.reverse_journal_entry(p_entry_id uuid, p_reason text)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_old  record;\r\n  v_id   uuid;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF p_reason IS NULL OR btrim(p_reason) = '' THEN\r\n    RAISE EXCEPTION 'Reversing an entry requires a reason';\r\n  END IF;\r\n\r\n  SELECT * INTO v_old FROM public.journal_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND OR v_old.status <> 'POSTED' THEN\r\n    RAISE EXCEPTION 'Only a posted entry can be reversed';\r\n  END IF;\r\n\r\n  SELECT public.create_journal_entry(\r\n    'عكس القيد ' || v_old.entry_number || ': ' || btrim(p_reason),\r\n    CURRENT_DATE, 'journal_reversal', p_entry_id, v_old.is_system,\r\n    (SELECT coalesce(jsonb_agg(jsonb_build_object(\r\n        'account_code', a.code,\r\n        -- A reversal swaps the sides rather than negating: the credit of the\r\n        -- original becomes the debit of the reversal.\r\n        'debit',  CASE WHEN jl.debit  > 0 THEN 0 ELSE jl.credit END,\r\n        'credit', CASE WHEN jl.debit  > 0 THEN jl.debit  ELSE 0 END,\r\n        'memo',   coalesce(jl.memo, a.name_ar)\r\n      ) ORDER BY jl.id), '[]'::jsonb)\r\n       FROM public.journal_lines jl JOIN public.accounts a ON a.id = jl.account_id\r\n      WHERE jl.entry_id = p_entry_id),\r\n    true  -- T-19: العكس مسموح داخل فترة مقفلة\r\n  ) INTO v_id;\r\n\r\n  UPDATE public.journal_entries SET status = 'REVERSED' WHERE id = p_entry_id;\r\n  RETURN v_id;\r\nEND $$","COMMENT ON FUNCTION public.reverse_journal_entry(uuid, text) IS\r\n  'T-19: عكس قيد مرحَّل. مسموح داخل فترة مقفلة لأنه يُلغي قيدًا ولا ينشئ رقمًا جديدًا.'","-- ── 6. RLS على الفترات ───────────────────────────────────────────────────────\r\nALTER TABLE public.fiscal_periods ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS fiscal_periods_read ON public.fiscal_periods","CREATE POLICY fiscal_periods_read ON public.fiscal_periods\r\n  FOR SELECT TO authenticated USING (public.is_staff(auth.uid()))","REVOKE ALL ON public.fiscal_periods FROM anon","GRANT SELECT ON public.fiscal_periods TO authenticated, service_role","-- ── 7. T-20: الإقفال السنوي ──────────────────────────────────────────────────\r\n-- يقفل أرصدة 4xxx (إيرادات) و5xxx (مصروفات) في 3911 (أرباح محتجزة).\r\n-- التاريخ 31/12 من السنة. يُرفض إن كانت الفترة المحتوية على 31/12 مقفلة،\r\n-- لأن كتابة قيد الإقفال داخلها تكون مستحيلة بعد ذلك.\r\nCREATE OR REPLACE FUNCTION public.close_fiscal_year(p_year integer)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user      uuid := auth.uid();\r\n  v_close_date date;\r\n  v_period    record;\r\n  v_lines     jsonb;\r\n  v_entry_id  uuid;\r\n  v_net       numeric;\r\n  v_existing  uuid;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may close a fiscal year';\r\n  END IF;\r\n\r\n  v_close_date := make_date(p_year, 12, 31);\r\n\r\n  -- فترة الإقفال يجب أن تكون مفتوحة: الإقفال يكتب قيدًا داخلها.\r\n  SELECT * INTO v_period\r\n    FROM public.fiscal_periods\r\n   WHERE v_close_date BETWEEN start_date AND end_date;\r\n  IF FOUND AND v_period.status = 'CLOSED' THEN\r\n    RAISE EXCEPTION\r\n      'فترة % مقفلة. لا يمكن إقفال سنة مقفلة بالفعل، أو فتح السنة قبل إقفالها.',\r\n      v_period.code;\r\n  END IF;\r\n\r\n  -- لا إقفال مزدوج: قيد إقفال قائم لنفس السنة يُرفض.\r\n  SELECT id INTO v_existing\r\n    FROM public.journal_entries\r\n   WHERE source_type = 'fiscal_year_close'\r\n     AND source_id IS NULL\r\n     AND memo LIKE '%' || p_year::text || '%'\r\n     AND status = 'POSTED'\r\n   LIMIT 1;\r\n  IF v_existing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'السنة % أُقفلت بالفعل (قيد %).', p_year, v_existing;\r\n  END IF;\r\n\r\n  -- قيد الإقفال: عكس طبيعة كل حساب 4xxx/5xxx لجعل رصيده صفرًا.\r\n  -- الإيراد (رصيده دائن) يُمدَّن؛ المصروف (رصيده مدين) يُدان.\r\n  SELECT coalesce(jsonb_agg(jsonb_build_object(\r\n           'account_code', a.code,\r\n           'debit',  CASE WHEN a.account_type = 'REVENUE' THEN t.bal ELSE 0 END,\r\n           'credit', CASE WHEN a.account_type = 'EXPENSE' THEN -t.bal ELSE 0 END,\r\n           'memo',   'إقفال سنة ' || p_year::text || ' — ' || a.name_ar\r\n         )), '[]'::jsonb)\r\n    INTO v_lines\r\n    FROM (\r\n      SELECT jl.account_id,\r\n             sum(jl.debit - jl.credit) AS bal\r\n        FROM public.journal_lines jl\r\n        JOIN public.journal_entries je\r\n          ON je.id = jl.entry_id AND je.status = 'POSTED'\r\n       WHERE je.entry_date BETWEEN make_date(p_year, 1, 1) AND v_close_date\r\n       GROUP BY jl.account_id\r\n      HAVING sum(jl.debit - jl.credit) <> 0\r\n    ) AS t\r\n    JOIN public.accounts a ON a.id = t.account_id\r\n   WHERE a.account_type IN ('REVENUE','EXPENSE');\r\n\r\n  -- لا شيء يُقفل: سنة بلا حركة 4xxx/5xxx. لا قيد فارغ.\r\n  IF v_lines IS NULL OR jsonb_array_length(v_lines) = 0 THEN\r\n    RAISE EXCEPTION 'لا توجد أرصدة إيراد أو مصروف لسنة % لإقفالها.', p_year;\r\n  END IF;\r\n\r\n  -- صافي الربح = مجموع (دائن الإيراد − مدين المصروف) = سالب مجموع bal لكل 4xxx/5xxx.\r\n  SELECT -sum(t.bal) INTO v_net\r\n    FROM (\r\n      SELECT sum(jl.debit - jl.credit) AS bal\r\n        FROM public.journal_lines jl\r\n        JOIN public.journal_entries je\r\n          ON je.id = jl.entry_id AND je.status = 'POSTED'\r\n       WHERE je.entry_date BETWEEN make_date(p_year, 1, 1) AND v_close_date\r\n       GROUP BY jl.account_id\r\n    ) AS t\r\n    JOIN public.accounts a ON a.id = t.account_id\r\n   WHERE a.account_type IN ('REVENUE','EXPENSE');\r\n\r\n  -- سطر 3911 يقابل الصافي: ربح → دائن، خسارة → مدين.\r\n  v_lines := v_lines || jsonb_build_array(\r\n    jsonb_build_object(\r\n      'account_code', '3911',\r\n      'debit',  CASE WHEN v_net < 0 THEN -v_net ELSE 0 END,\r\n      'credit', CASE WHEN v_net > 0 THEN v_net ELSE 0 END,\r\n      'memo',   'أرباح محتجزة — نتيجة سنة ' || p_year::text\r\n    )\r\n  );\r\n\r\n  v_entry_id := public.create_journal_entry(\r\n    'إقفال السنة المالية ' || p_year::text ||\r\n      ' — ترحيل الإيرادات والمصروفات إلى الأرباح المحتجزة',\r\n    v_close_date, 'fiscal_year_close', NULL, true, v_lines, true  -- قيد نظامي؛ يُسمح داخل فترة مقفلة\r\n  );\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'fiscal_year.closed', 'fiscal_year', v_entry_id,\r\n          jsonb_build_object('year', p_year, 'net_result', v_net,\r\n                             'entry_id', v_entry_id));\r\n\r\n  RETURN v_entry_id;\r\nEND $$","REVOKE ALL ON FUNCTION public.close_fiscal_year(integer) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.close_fiscal_year(integer) TO authenticated, service_role","COMMENT ON FUNCTION public.close_fiscal_year(integer) IS\r\n  'T-20: يقفل سنة مالية — 4xxx/5xxx تُصفَّر والنتيجة تُرحَّل إلى 3911 بتاريخ 31/12.'","-- ── 8. T-20: فتح سنة مالية جديدة ────────────────────────────────────────────\r\n-- ينشئ فترات السنة الجديدة فقط. لا يكتب قيدًا افتتاحيًا: الأرصدة الافتتاحية\r\n-- للسنة الجديدة هي نتاج القيود القائمة (trial_balance)، تمامًا كما في الدفاتر\r\n-- الحقيقية. كتابة قيد افتتاحي ثانٍ تعني مصدرًا ثانيًا للحقيقة.\r\nCREATE OR REPLACE FUNCTION public.open_fiscal_year(p_year integer)\r\nRETURNS integer\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_created integer := 0;\r\n  v_first   date;\r\n  v_last    date;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may open a fiscal year';\r\n  END IF;\r\n\r\n  v_first := make_date(p_year, 1, 1);\r\n  v_last  := make_date(p_year, 12, 31);\r\n\r\n  -- تداخل مع سنة قائمة يُرفض قبل المحاولة، برسالة تفهم السبب.\r\n  IF EXISTS (\r\n    SELECT 1 FROM public.fiscal_periods\r\n     WHERE daterange(start_date, end_date, '[]') &&\r\n           daterange(v_first, v_last, '[]')\r\n  ) THEN\r\n    RAISE EXCEPTION 'السنة % متداخلة مع فترات مالية قائمة.', p_year;\r\n  END IF;\r\n\r\n  INSERT INTO public.fiscal_periods (code, fiscal_year, period_no, start_date, end_date, status)\r\n  SELECT to_char(g.d, 'YYYY-MM'),\r\n         p_year,\r\n         EXTRACT(MONTH FROM g.d)::integer,\r\n         g.d,\r\n         (date_trunc('month', g.d) + interval '1 month - 1 day')::date,\r\n         'OPEN'\r\n    FROM generate_series(v_first, v_last, interval '1 month') AS g(d)\r\n  ON CONFLICT (code) DO NOTHING;\r\n\r\n  GET DIAGNOSTICS v_created = ROW_COUNT;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'fiscal_year.opened', 'fiscal_year', NULL,\r\n          jsonb_build_object('year', p_year, 'periods_created', v_created));\r\n\r\n  RETURN v_created;\r\nEND $$","REVOKE ALL ON FUNCTION public.open_fiscal_year(integer) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.open_fiscal_year(integer) TO authenticated, service_role","COMMENT ON FUNCTION public.open_fiscal_year(integer) IS\r\n  'T-20: يفتح سنة مالية بإنشاء 12 فترة شهرية. لا قيد افتتاحي — الأرصدة مشتقة من القيود.'","-- ── ROLLBACK ────────────────────────────────────────────────────────────────\r\n-- DROP FUNCTION IF EXISTS public.open_fiscal_year(integer);\r\n-- DROP FUNCTION IF EXISTS public.close_fiscal_year(integer);\r\n-- DROP FUNCTION IF EXISTS public.assert_period_open(date);\r\n-- -- استعادة create_journal_entry للتوقيع القديم (من المهاجرة 17) قبل الحذف.\r\n-- DROP FUNCTION IF EXISTS public.create_journal_entry(text, date, text, uuid, boolean, jsonb, boolean);\r\n-- DROP FUNCTION IF EXISTS public.create_journal_entry(text, date, text, uuid, boolean, jsonb);\r\n-- DROP TABLE IF EXISTS public.fiscal_periods;"}	accounting_phase3_fiscal_periods
24	{"-- ============================================================================\r\n-- 21b_accounting_phase3_set_period_status.sql\r\n--\r\n-- تكميل المرحلة 3: دالة تغيير حالة الفترة المالية (فتح/قفل) من الشاشة.\r\n-- تتيح للمحاسب/المدير قفل أو فتح فترة شهرية مع تسجيل سجل التدقيق.\r\n-- ============================================================================\r\n\r\nCREATE OR REPLACE FUNCTION public.set_period_status(\r\n  p_period_id uuid,\r\n  p_status    text\r\n)\r\nRETURNS boolean\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_period record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may change fiscal period status';\r\n  END IF;\r\n\r\n  IF p_status NOT IN ('OPEN', 'CLOSED') THEN\r\n    RAISE EXCEPTION 'Status must be OPEN or CLOSED';\r\n  END IF;\r\n\r\n  SELECT * INTO v_period FROM public.fiscal_periods WHERE id = p_period_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Fiscal period not found';\r\n  END IF;\r\n\r\n  UPDATE public.fiscal_periods\r\n     SET status = p_status,\r\n         closed_at = CASE WHEN p_status = 'CLOSED' THEN now() ELSE NULL END,\r\n         closed_by = CASE WHEN p_status = 'CLOSED' THEN v_user ELSE NULL END\r\n   WHERE id = p_period_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'fiscal_period.status_changed', 'fiscal_period', p_period_id,\r\n          jsonb_build_object('code', v_period.code, 'old_status', v_period.status, 'new_status', p_status));\r\n\r\n  RETURN true;\r\nEND $$","REVOKE ALL ON FUNCTION public.set_period_status(uuid, text) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.set_period_status(uuid, text) TO authenticated, service_role","COMMENT ON FUNCTION public.set_period_status(uuid, text) IS\r\n  'T-19: تغيير حالة الفترة المالية بين OPEN و CLOSED مع فحص الصلاحيات وتسجيل التدقيق.'"}	accounting_phase3_set_period_status
25	{"-- ============================================================================\r\n-- 22_accounting_phase4_fixed_assets.sql\r\n--\r\n-- المرحلة 4 — المهمة T-21: الأصول الثابتة ودورة حياتها وإهلاكها الدوري.\r\n--\r\n-- تتضمن:\r\n--   1. جدول الأصول الثابتة public.fixed_assets\r\n--   2. جدول سجل الإهلاك public.asset_depreciation_lines\r\n--   3. دالة تفعيل الأصل public.activate_fixed_asset\r\n--   4. دالة تشغيل الإهلاك الدوري public.run_depreciation بالقيد:\r\n--        Dr 5611 (مصروف إهلاك الأصول الثابتة)\r\n--        Cr 1491 (مجمع إهلاك الأصول الثابتة)\r\n--   5. دالة الإهلاك الجماعي لجميع الأصول النشطة public.run_batch_depreciation\r\n--   6. دالة استبعاد/شطب الأصل public.dispose_fixed_asset (Dr 1491, Cr الأصل, فوارق 4911/5811)\r\n--   7. قواعد RLS وصلاحيات التنفيذ وسجلات التدقيق\r\n-- ============================================================================\r\n\r\n-- ── 1. جدول الأصول الثابتة ───────────────────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS public.fixed_assets (\r\n  id                                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  asset_code                            text NOT NULL UNIQUE,\r\n  name_ar                               text NOT NULL,\r\n  name_en                               text,\r\n  category                              text NOT NULL CHECK (category IN ('MACHINERY', 'VEHICLES', 'EQUIPMENT', 'BUILDINGS', 'OTHER')),\r\n  purchase_date                         date NOT NULL,\r\n  purchase_cost                         numeric(18,2) NOT NULL CHECK (purchase_cost > 0),\r\n  salvage_value                         numeric(18,2) NOT NULL DEFAULT 0 CHECK (salvage_value >= 0 AND salvage_value < purchase_cost),\r\n  useful_life_months                    integer NOT NULL CHECK (useful_life_months > 0),\r\n  depreciation_method                   text NOT NULL DEFAULT 'STRAIGHT_LINE' CHECK (depreciation_method IN ('STRAIGHT_LINE', 'DECLINING_BALANCE')),\r\n  asset_account_code                    text NOT NULL DEFAULT '1411',\r\n  accumulated_depreciation_account_code text NOT NULL DEFAULT '1491',\r\n  depreciation_expense_account_code     text NOT NULL DEFAULT '5611',\r\n  status                                text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'ACTIVE', 'FULLY_DEPRECIATED', 'DISPOSED')),\r\n  accumulated_depreciation              numeric(18,2) NOT NULL DEFAULT 0 CHECK (accumulated_depreciation >= 0),\r\n  current_book_value                    numeric(18,2) NOT NULL,\r\n  last_depreciation_date                date,\r\n  disposal_date                         date,\r\n  disposal_amount                       numeric(18,2),\r\n  notes                                 text,\r\n  created_by                            uuid REFERENCES auth.users(id),\r\n  created_at                            timestamptz NOT NULL DEFAULT now()\r\n)","CREATE INDEX IF NOT EXISTS ix_fixed_assets_status ON public.fixed_assets(status)","CREATE INDEX IF NOT EXISTS ix_fixed_assets_code ON public.fixed_assets(asset_code)","COMMENT ON TABLE public.fixed_assets IS\r\n  'T-21: الأصول الثابتة للمنشأة ومتابعة قيمتها الدفترية ومجمع إهلاكها ودورة حياتها.'","-- ── 2. جدول سجل الإهلاك الدوري ───────────────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS public.asset_depreciation_lines (\r\n  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  asset_id            uuid NOT NULL REFERENCES public.fixed_assets(id) ON DELETE RESTRICT,\r\n  depreciation_date   date NOT NULL,\r\n  depreciation_amount numeric(18,2) NOT NULL CHECK (depreciation_amount > 0),\r\n  book_value_before   numeric(18,2) NOT NULL,\r\n  book_value_after    numeric(18,2) NOT NULL,\r\n  journal_entry_id    uuid REFERENCES public.journal_entries(id),\r\n  created_at          timestamptz NOT NULL DEFAULT now(),\r\n  CONSTRAINT uq_asset_depreciation_date UNIQUE (asset_id, depreciation_date)\r\n)","CREATE INDEX IF NOT EXISTS ix_asset_depr_asset ON public.asset_depreciation_lines(asset_id)","CREATE INDEX IF NOT EXISTS ix_asset_depr_date ON public.asset_depreciation_lines(depreciation_date)","COMMENT ON TABLE public.asset_depreciation_lines IS\r\n  'T-21: سجل قيود وأقساط الإهلاك المحسوبة لكل أصل لمنع التكرار وحفظ الأثر المحاسبي.'","-- ── 3. دالة تفعيل الأصل ──────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.activate_fixed_asset(p_asset_id uuid)\r\nRETURNS boolean\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user  uuid := auth.uid();\r\n  v_asset record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may activate fixed assets';\r\n  END IF;\r\n\r\n  SELECT * INTO v_asset FROM public.fixed_assets WHERE id = p_asset_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Fixed asset not found';\r\n  END IF;\r\n\r\n  IF v_asset.status <> 'DRAFT' THEN\r\n    RAISE EXCEPTION 'Asset % is already in status %', v_asset.asset_code, v_asset.status;\r\n  END IF;\r\n\r\n  UPDATE public.fixed_assets\r\n     SET status = 'ACTIVE'\r\n   WHERE id = p_asset_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'fixed_asset.activated', 'fixed_asset', p_asset_id,\r\n          jsonb_build_object('asset_code', v_asset.asset_code, 'purchase_cost', v_asset.purchase_cost));\r\n\r\n  RETURN true;\r\nEND $$","REVOKE ALL ON FUNCTION public.activate_fixed_asset(uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.activate_fixed_asset(uuid) TO authenticated, service_role","-- ── 4. دالة تشغيل الإهلاك الدوري (T-21: Dr 5611 / Cr 1491) ───────────────────\r\nCREATE OR REPLACE FUNCTION public.run_depreciation(\r\n  p_asset_id uuid,\r\n  p_date     date DEFAULT CURRENT_DATE\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user        uuid := auth.uid();\r\n  v_asset       record;\r\n  v_monthly     numeric(18,2);\r\n  v_depreciable numeric(18,2);\r\n  v_remaining   numeric(18,2);\r\n  v_amount      numeric(18,2);\r\n  v_new_acc     numeric(18,2);\r\n  v_new_book    numeric(18,2);\r\n  v_entry_id    uuid;\r\n  v_memo        text;\r\n  v_lines       jsonb;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may run asset depreciation';\r\n  END IF;\r\n\r\n  -- فحص الفترة المالية\r\n  PERFORM public.assert_period_open(p_date);\r\n\r\n  SELECT * INTO v_asset FROM public.fixed_assets WHERE id = p_asset_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Fixed asset not found';\r\n  END IF;\r\n\r\n  IF v_asset.status <> 'ACTIVE' THEN\r\n    RAISE EXCEPTION 'Asset % is not active (status: %)', v_asset.asset_code, v_asset.status;\r\n  END IF;\r\n\r\n  -- منع تكرار الإهلاك في نفس التاريخ المحدد للأصل\r\n  IF EXISTS (\r\n    SELECT 1 FROM public.asset_depreciation_lines\r\n     WHERE asset_id = p_asset_id AND depreciation_date = p_date\r\n  ) THEN\r\n    RAISE EXCEPTION 'Asset % has already been depreciated on %', v_asset.asset_code, p_date;\r\n  END IF;\r\n\r\n  -- حساب الإهلاك بالقسط الثابت: (التكلفة - قيمة الخردة) / العمر الإنتاجي\r\n  v_depreciable := v_asset.purchase_cost - v_asset.salvage_value;\r\n  v_monthly     := round(v_depreciable / v_asset.useful_life_months, 2);\r\n  v_remaining   := v_depreciable - v_asset.accumulated_depreciation;\r\n\r\n  IF v_remaining <= 0 THEN\r\n    UPDATE public.fixed_assets\r\n       SET status = 'FULLY_DEPRECIATED'\r\n     WHERE id = p_asset_id;\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  v_amount := least(v_monthly, v_remaining);\r\n  IF v_amount <= 0 THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  v_new_acc  := v_asset.accumulated_depreciation + v_amount;\r\n  v_new_book := v_asset.purchase_cost - v_new_acc;\r\n\r\n  -- بناء القيد المحاسبي المتوازن: Dr 5611 / Cr 1491\r\n  v_memo := 'إهلاك أصل ثابت ' || v_asset.asset_code || ' (' || v_asset.name_ar || ') بتاريخ ' || to_char(p_date, 'YYYY-MM-DD');\r\n  v_lines := jsonb_build_array(\r\n    jsonb_build_object(\r\n      'account_code', v_asset.depreciation_expense_account_code, -- 5611\r\n      'debit', v_amount,\r\n      'credit', 0,\r\n      'memo', 'مصروف إهلاك — ' || v_asset.name_ar\r\n    ),\r\n    jsonb_build_object(\r\n      'account_code', v_asset.accumulated_depreciation_account_code, -- 1491\r\n      'debit', 0,\r\n      'credit', v_amount,\r\n      'memo', 'مجمع إهلاك — ' || v_asset.name_ar\r\n    )\r\n  );\r\n\r\n  v_entry_id := public.create_journal_entry(\r\n    v_memo,\r\n    p_date,\r\n    'fixed_asset_depreciation',\r\n    p_asset_id,\r\n    true, -- قيد نظامي\r\n    v_lines,\r\n    false\r\n  );\r\n\r\n  -- تسجيل في سجل الإهلاك\r\n  INSERT INTO public.asset_depreciation_lines (\r\n    asset_id, depreciation_date, depreciation_amount, book_value_before, book_value_after, journal_entry_id\r\n  )\r\n  VALUES (\r\n    p_asset_id, p_date, v_amount, v_asset.current_book_value, v_new_book, v_entry_id\r\n  );\r\n\r\n  -- تحديث الأصل\r\n  UPDATE public.fixed_assets\r\n     SET accumulated_depreciation = v_new_acc,\r\n         current_book_value       = v_new_book,\r\n         last_depreciation_date   = p_date,\r\n         status                   = CASE WHEN v_new_acc >= v_depreciable THEN 'FULLY_DEPRECIATED' ELSE 'ACTIVE' END\r\n   WHERE id = p_asset_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'fixed_asset.depreciated', 'fixed_asset', p_asset_id,\r\n          jsonb_build_object('asset_code', v_asset.asset_code, 'amount', v_amount,\r\n                             'journal_entry_id', v_entry_id, 'new_book_value', v_new_book));\r\n\r\n  RETURN v_entry_id;\r\nEND $$","REVOKE ALL ON FUNCTION public.run_depreciation(uuid, date) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.run_depreciation(uuid, date) TO authenticated, service_role","COMMENT ON FUNCTION public.run_depreciation(uuid, date) IS\r\n  'T-21: ترحيل قسط الإهلاك الدوري للأصل الثابت بالقيد المتوازن Dr 5611 / Cr 1491 مع تحديث القيمة الدفترية ومنع التكرار.'","-- ── 5. دالة الإهلاك الجماعي للأصول النشطة ──────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.run_batch_depreciation(p_date date DEFAULT CURRENT_DATE)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user      uuid := auth.uid();\r\n  r           record;\r\n  v_entry     uuid;\r\n  v_count     integer := 0;\r\n  v_total     numeric(18,2) := 0;\r\n  v_skipped   integer := 0;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may run batch depreciation';\r\n  END IF;\r\n\r\n  FOR r IN\r\n    SELECT id, asset_code FROM public.fixed_assets\r\n     WHERE status = 'ACTIVE'\r\n     ORDER BY purchase_date ASC\r\n  LOOP\r\n    BEGIN\r\n      v_entry := public.run_depreciation(r.id, p_date);\r\n      IF v_entry IS NOT NULL THEN\r\n        v_count := v_count + 1;\r\n      ELSE\r\n        v_skipped := v_skipped + 1;\r\n      END IF;\r\n    EXCEPTION WHEN others THEN\r\n      -- تخطي ما تم إهلاكه سابقاً في نفس اليوم\r\n      v_skipped := v_skipped + 1;\r\n    END;\r\n  END LOOP;\r\n\r\n  RETURN jsonb_build_object(\r\n    'date', p_date,\r\n    'depreciated_count', v_count,\r\n    'skipped_count', v_skipped\r\n  );\r\nEND $$","REVOKE ALL ON FUNCTION public.run_batch_depreciation(date) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.run_batch_depreciation(date) TO authenticated, service_role","-- ── 6. دالة استبعاد الأصل الثابت (Disposal) ───────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.dispose_fixed_asset(\r\n  p_asset_id           uuid,\r\n  p_disposal_date      date,\r\n  p_proceeds           numeric(18,2) DEFAULT 0,\r\n  p_proceeds_account   text DEFAULT '1101'\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user        uuid := auth.uid();\r\n  v_asset       record;\r\n  v_lines       jsonb := '[]'::jsonb;\r\n  v_entry_id    uuid;\r\n  v_gain_loss   numeric(18,2);\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may dispose fixed assets';\r\n  END IF;\r\n\r\n  PERFORM public.assert_period_open(p_disposal_date);\r\n\r\n  SELECT * INTO v_asset FROM public.fixed_assets WHERE id = p_asset_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Fixed asset not found';\r\n  END IF;\r\n\r\n  IF v_asset.status NOT IN ('ACTIVE', 'FULLY_DEPRECIATED') THEN\r\n    RAISE EXCEPTION 'Asset % cannot be disposed (current status: %)', v_asset.asset_code, v_asset.status;\r\n  END IF;\r\n\r\n  -- حساب الأرباح أو الخسائر الرأسمالية: الحصيلة - القيمة الدفترية\r\n  v_gain_loss := coalesce(p_proceeds, 0) - v_asset.current_book_value;\r\n\r\n  -- 1) إقفال مجمع الإهلاك (مدين 1491)\r\n  IF v_asset.accumulated_depreciation > 0 THEN\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', v_asset.accumulated_depreciation_account_code, -- 1491\r\n        'debit', v_asset.accumulated_depreciation,\r\n        'credit', 0,\r\n        'memo', 'إقفال مجمع إهلاك الأصل المستبعد — ' || v_asset.name_ar\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  -- 2) إثبات حصيلة البيع إن وجدت (مدين نقدية/بنك)\r\n  IF coalesce(p_proceeds, 0) > 0 THEN\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', coalesce(p_proceeds_account, '1101'),\r\n        'debit', p_proceeds,\r\n        'credit', 0,\r\n        'memo', 'حصيلة بيع الأصل — ' || v_asset.name_ar\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  -- 3) إثبات الخسارة الرأسمالية إن وجدت (مدين 5811 خسائر شطب أصول)\r\n  IF v_gain_loss < 0 THEN\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '5811',\r\n        'debit', -v_gain_loss,\r\n        'credit', 0,\r\n        'memo', 'خسائر بيع/شطب أصل — ' || v_asset.name_ar\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  -- 4) إقفال التكلفة التاريخية للأصل (دائن 14xx)\r\n  v_lines := v_lines || jsonb_build_array(\r\n    jsonb_build_object(\r\n      'account_code', v_asset.asset_account_code,\r\n      'debit', 0,\r\n      'credit', v_asset.purchase_cost,\r\n      'memo', 'استبعاد تكلفة الأصل — ' || v_asset.name_ar\r\n    )\r\n  );\r\n\r\n  -- 5) إثبات الأرباح الرأسمالية إن وجدت (دائن 4911 إيرادات أخرى)\r\n  IF v_gain_loss > 0 THEN\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '4911',\r\n        'debit', 0,\r\n        'credit', v_gain_loss,\r\n        'memo', 'أرباح بيع أصل رأسمالي — ' || v_asset.name_ar\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  v_entry_id := public.create_journal_entry(\r\n    'استبعاد وشطب الأصل الثابت ' || v_asset.asset_code || ' — ' || v_asset.name_ar,\r\n    p_disposal_date,\r\n    'fixed_asset_disposal',\r\n    p_asset_id,\r\n    true,\r\n    v_lines,\r\n    false\r\n  );\r\n\r\n  UPDATE public.fixed_assets\r\n     SET status = 'DISPOSED',\r\n         disposal_date = p_disposal_date,\r\n         disposal_amount = coalesce(p_proceeds, 0)\r\n   WHERE id = p_asset_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'fixed_asset.disposed', 'fixed_asset', p_asset_id,\r\n          jsonb_build_object('asset_code', v_asset.asset_code, 'proceeds', p_proceeds,\r\n                             'gain_loss', v_gain_loss, 'entry_id', v_entry_id));\r\n\r\n  RETURN v_entry_id;\r\nEND $$","REVOKE ALL ON FUNCTION public.dispose_fixed_asset(uuid, date, numeric, text) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.dispose_fixed_asset(uuid, date, numeric, text) TO authenticated, service_role","-- ── 7. RLS ───────────────────────────────────────────────────────────────────\r\nALTER TABLE public.fixed_assets ENABLE ROW LEVEL SECURITY","ALTER TABLE public.asset_depreciation_lines ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS fixed_assets_read ON public.fixed_assets","CREATE POLICY fixed_assets_read ON public.fixed_assets\r\n  FOR SELECT TO authenticated USING (public.is_staff(auth.uid()))","DROP POLICY IF EXISTS fixed_assets_insert ON public.fixed_assets","CREATE POLICY fixed_assets_insert ON public.fixed_assets\r\n  FOR INSERT TO authenticated WITH CHECK (\r\n    public.has_role(auth.uid(), 'owner')\r\n    OR public.has_role(auth.uid(), 'manager')\r\n    OR public.has_role(auth.uid(), 'accountant')\r\n  )","DROP POLICY IF EXISTS fixed_assets_update ON public.fixed_assets","CREATE POLICY fixed_assets_update ON public.fixed_assets\r\n  FOR UPDATE TO authenticated USING (\r\n    public.has_role(auth.uid(), 'owner')\r\n    OR public.has_role(auth.uid(), 'manager')\r\n    OR public.has_role(auth.uid(), 'accountant')\r\n  )","DROP POLICY IF EXISTS asset_depreciation_lines_read ON public.asset_depreciation_lines","CREATE POLICY asset_depreciation_lines_read ON public.asset_depreciation_lines\r\n  FOR SELECT TO authenticated USING (public.is_staff(auth.uid()))","GRANT SELECT, INSERT, UPDATE ON public.fixed_assets TO authenticated, service_role","GRANT SELECT ON public.asset_depreciation_lines TO authenticated, service_role"}	accounting_phase4_fixed_assets
26	{"-- ============================================================================\r\n-- 23_accounting_phase4_prepayments_deferred.sql\r\n--\r\n-- المرحلة 4 — المهمة T-22: المصاريف والإيرادات المقدمة أو المؤجلة وتوزيعها على الفترات.\r\n--\r\n-- تتضمن:\r\n--   1. جدول العقود والمصاريف/الإيرادات المقدمة public.prepaid_and_deferred_contracts\r\n--   2. جدول سجل الاستهلاك والتوزيع الزمني public.amortization_lines\r\n--   3. دالة تفعيل العقد public.activate_prepaid_contract\r\n--   4. دالة استهلاك/توزيع القسط الزمني public.run_contract_amortization:\r\n--      - للمصروف المقدم: Dr 5xxx (حساب المصروف) / Cr 1511 (مصروفات مدفوعة مقدماً)\r\n--      - للإيراد المؤجل: Dr 2231 (إيرادات مؤجلة) / Cr 4xxx (حساب الإيراد)\r\n--   5. دالة الاستهلاك الجماعي لجميع العقود النشطة public.run_batch_amortization\r\n--   6. سياسات RLS وسجلات التدقيق والصلاحيات\r\n-- ============================================================================\r\n\r\n-- ── 1. جدول عقود المصاريف والإيرادات المقدمة ──────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS public.prepaid_and_deferred_contracts (\r\n  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  contract_number      text NOT NULL UNIQUE,\r\n  contract_type        text NOT NULL CHECK (contract_type IN ('PREPAID_EXPENSE', 'DEFERRED_EXPENSE', 'DEFERRED_REVENUE')),\r\n  title                text NOT NULL,\r\n  total_amount         numeric(18,2) NOT NULL CHECK (total_amount > 0),\r\n  start_date           date NOT NULL,\r\n  end_date             date NOT NULL,\r\n  total_periods        integer NOT NULL CHECK (total_periods > 0),\r\n  balance_account_code text NOT NULL, -- 1511 للمصروف المقدم، 1512 للمؤجل، 2231 للإيراد المؤجل\r\n  target_account_code  text NOT NULL, -- 5xxx للمصروف الفعلي، 4xxx للإيراد الفعلي\r\n  status               text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'ACTIVE', 'COMPLETED', 'CANCELLED')),\r\n  amortized_amount     numeric(18,2) NOT NULL DEFAULT 0 CHECK (amortized_amount >= 0),\r\n  remaining_amount     numeric(18,2) NOT NULL,\r\n  last_amortization_date date,\r\n  notes                text,\r\n  created_by           uuid REFERENCES auth.users(id),\r\n  created_at           timestamptz NOT NULL DEFAULT now(),\r\n  CONSTRAINT chk_contract_dates CHECK (end_date >= start_date)\r\n)","CREATE INDEX IF NOT EXISTS ix_prepaid_status ON public.prepaid_and_deferred_contracts(status)","CREATE INDEX IF NOT EXISTS ix_prepaid_type ON public.prepaid_and_deferred_contracts(contract_type)","COMMENT ON TABLE public.prepaid_and_deferred_contracts IS\r\n  'T-22: إدارة عقود المصروفات والإيرادات المقدمة والمؤجلة وتوزيعها على الفترات المحاسبية.'","-- ── 2. جدول سجل التوزيع والأقساط المحسوبة ─────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS public.amortization_lines (\r\n  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  contract_id         uuid NOT NULL REFERENCES public.prepaid_and_deferred_contracts(id) ON DELETE RESTRICT,\r\n  period_date         date NOT NULL,\r\n  amount              numeric(18,2) NOT NULL CHECK (amount > 0),\r\n  remaining_after     numeric(18,2) NOT NULL,\r\n  journal_entry_id    uuid REFERENCES public.journal_entries(id),\r\n  created_at          timestamptz NOT NULL DEFAULT now(),\r\n  CONSTRAINT uq_contract_period_date UNIQUE (contract_id, period_date)\r\n)","CREATE INDEX IF NOT EXISTS ix_amortization_contract ON public.amortization_lines(contract_id)","CREATE INDEX IF NOT EXISTS ix_amortization_date ON public.amortization_lines(period_date)","COMMENT ON TABLE public.amortization_lines IS\r\n  'T-22: سجل قيود وأقساط التوزيع الزمني للمصروفات/الإيرادات المقدمة مع منع التكرار.'","-- ── 3. دالة تفعيل العقد ──────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.activate_prepaid_contract(p_contract_id uuid)\r\nRETURNS boolean\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_rec  record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may activate prepaid contracts';\r\n  END IF;\r\n\r\n  SELECT * INTO v_rec FROM public.prepaid_and_deferred_contracts WHERE id = p_contract_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Contract not found';\r\n  END IF;\r\n\r\n  IF v_rec.status <> 'DRAFT' THEN\r\n    RAISE EXCEPTION 'Contract % is already in status %', v_rec.contract_number, v_rec.status;\r\n  END IF;\r\n\r\n  UPDATE public.prepaid_and_deferred_contracts\r\n     SET status = 'ACTIVE'\r\n   WHERE id = p_contract_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'prepaid_contract.activated', 'prepaid_contract', p_contract_id,\r\n          jsonb_build_object('contract_number', v_rec.contract_number, 'total_amount', v_rec.total_amount));\r\n\r\n  RETURN true;\r\nEND $$","REVOKE ALL ON FUNCTION public.activate_prepaid_contract(uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.activate_prepaid_contract(uuid) TO authenticated, service_role","-- ── 4. دالة استهلاك/توزيع القسط الدوري للمصروف/الإيراد المقدم ────────────────\r\nCREATE OR REPLACE FUNCTION public.run_contract_amortization(\r\n  p_contract_id uuid,\r\n  p_date        date DEFAULT CURRENT_DATE\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user        uuid := auth.uid();\r\n  v_rec         record;\r\n  v_period_amt  numeric(18,2);\r\n  v_amount      numeric(18,2);\r\n  v_new_amort   numeric(18,2);\r\n  v_new_rem     numeric(18,2);\r\n  v_entry_id    uuid;\r\n  v_memo        text;\r\n  v_lines       jsonb;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may amortize prepaid contracts';\r\n  END IF;\r\n\r\n  -- فحص الفترة المالية\r\n  PERFORM public.assert_period_open(p_date);\r\n\r\n  SELECT * INTO v_rec FROM public.prepaid_and_deferred_contracts WHERE id = p_contract_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Contract not found';\r\n  END IF;\r\n\r\n  IF v_rec.status <> 'ACTIVE' THEN\r\n    RAISE EXCEPTION 'Contract % is not active (status: %)', v_rec.contract_number, v_rec.status;\r\n  END IF;\r\n\r\n  -- منع تكرار الاستهلاك لنفس العقد في نفس التاريخ\r\n  IF EXISTS (\r\n    SELECT 1 FROM public.amortization_lines\r\n     WHERE contract_id = p_contract_id AND period_date = p_date\r\n  ) THEN\r\n    RAISE EXCEPTION 'Contract % has already been amortized on %', v_rec.contract_number, p_date;\r\n  END IF;\r\n\r\n  IF v_rec.remaining_amount <= 0 THEN\r\n    UPDATE public.prepaid_and_deferred_contracts\r\n       SET status = 'COMPLETED'\r\n     WHERE id = p_contract_id;\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  v_period_amt := round(v_rec.total_amount / v_rec.total_periods, 2);\r\n  v_amount     := least(v_period_amt, v_rec.remaining_amount);\r\n\r\n  IF v_amount <= 0 THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  v_new_amort := v_rec.amortized_amount + v_amount;\r\n  v_new_rem   := v_rec.total_amount - v_new_amort;\r\n\r\n  -- بناء القيد المحاسبي المتوازن حسب نوع العقد\r\n  IF v_rec.contract_type IN ('PREPAID_EXPENSE', 'DEFERRED_EXPENSE') THEN\r\n    -- استهلاك مصروف مقدم: Dr حساب المصروف الفعلي / Cr حساب المصروف المقدم (1511/1512)\r\n    v_memo := 'استهلاك قسط مصروف مقدم — ' || v_rec.title || ' (' || v_rec.contract_number || ')';\r\n    v_lines := jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', v_rec.target_account_code,\r\n        'debit', v_amount,\r\n        'credit', 0,\r\n        'memo', 'تحميل مصروف الفترة — ' || v_rec.title\r\n      ),\r\n      jsonb_build_object(\r\n        'account_code', v_rec.balance_account_code,\r\n        'debit', 0,\r\n        'credit', v_amount,\r\n        'memo', 'تخفيض المصروف المقدم — ' || v_rec.title\r\n      )\r\n    );\r\n  ELSE\r\n    -- تحقق إيراد مؤجل: Dr حساب الإيراد المؤجل (2231) / Cr حساب الإيراد الفعلي (4xxx)\r\n    v_memo := 'اعتراف بقسط إيراد مؤجل — ' || v_rec.title || ' (' || v_rec.contract_number || ')';\r\n    v_lines := jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', v_rec.balance_account_code,\r\n        'debit', v_amount,\r\n        'credit', 0,\r\n        'memo', 'تخفيض التزام الإيراد المؤجل — ' || v_rec.title\r\n      ),\r\n      jsonb_build_object(\r\n        'account_code', v_rec.target_account_code,\r\n        'debit', 0,\r\n        'credit', v_amount,\r\n        'memo', 'تحقق إيراد الفترة — ' || v_rec.title\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  v_entry_id := public.create_journal_entry(\r\n    v_memo,\r\n    p_date,\r\n    'prepaid_amortization',\r\n    p_contract_id,\r\n    true,\r\n    v_lines,\r\n    false\r\n  );\r\n\r\n  -- تسجيل في سجل الاستهلاك\r\n  INSERT INTO public.amortization_lines (\r\n    contract_id, period_date, amount, remaining_after, journal_entry_id\r\n  )\r\n  VALUES (\r\n    p_contract_id, p_date, v_amount, v_new_rem, v_entry_id\r\n  );\r\n\r\n  -- تحديث العقد\r\n  UPDATE public.prepaid_and_deferred_contracts\r\n     SET amortized_amount       = v_new_amort,\r\n         remaining_amount       = v_new_rem,\r\n         last_amortization_date = p_date,\r\n         status                 = CASE WHEN v_new_rem <= 0 THEN 'COMPLETED' ELSE 'ACTIVE' END\r\n   WHERE id = p_contract_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'prepaid_contract.amortized', 'prepaid_contract', p_contract_id,\r\n          jsonb_build_object('contract_number', v_rec.contract_number, 'amount', v_amount,\r\n                             'journal_entry_id', v_entry_id, 'remaining', v_new_rem));\r\n\r\n  RETURN v_entry_id;\r\nEND $$","REVOKE ALL ON FUNCTION public.run_contract_amortization(uuid, date) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.run_contract_amortization(uuid, date) TO authenticated, service_role","COMMENT ON FUNCTION public.run_contract_amortization(uuid, date) IS\r\n  'T-22: توزيع واستهلاك قسط المصروف أو الإيراد المقدم بقيد مزدوج متوازن مع منع التكرار وتحديث الأرصدة.'","-- ── 5. دالة الاستهلاك الجماعي ────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.run_batch_amortization(p_date date DEFAULT CURRENT_DATE)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  r         record;\r\n  v_entry   uuid;\r\n  v_count   integer := 0;\r\n  v_skipped integer := 0;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may run batch amortization';\r\n  END IF;\r\n\r\n  FOR r IN\r\n    SELECT id, contract_number FROM public.prepaid_and_deferred_contracts\r\n     WHERE status = 'ACTIVE'\r\n     ORDER BY start_date ASC\r\n  LOOP\r\n    BEGIN\r\n      v_entry := public.run_contract_amortization(r.id, p_date);\r\n      IF v_entry IS NOT NULL THEN\r\n        v_count := v_count + 1;\r\n      ELSE\r\n        v_skipped := v_skipped + 1;\r\n      END IF;\r\n    EXCEPTION WHEN others THEN\r\n      v_skipped := v_skipped + 1;\r\n    END;\r\n  END LOOP;\r\n\r\n  RETURN jsonb_build_object(\r\n    'date', p_date,\r\n    'amortized_count', v_count,\r\n    'skipped_count', v_skipped\r\n  );\r\nEND $$","REVOKE ALL ON FUNCTION public.run_batch_amortization(date) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.run_batch_amortization(date) TO authenticated, service_role","-- ── 6. RLS ───────────────────────────────────────────────────────────────────\r\nALTER TABLE public.prepaid_and_deferred_contracts ENABLE ROW LEVEL SECURITY","ALTER TABLE public.amortization_lines ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS prepaid_contracts_read ON public.prepaid_and_deferred_contracts","CREATE POLICY prepaid_contracts_read ON public.prepaid_and_deferred_contracts\r\n  FOR SELECT TO authenticated USING (public.is_staff(auth.uid()))","DROP POLICY IF EXISTS prepaid_contracts_write ON public.prepaid_and_deferred_contracts","CREATE POLICY prepaid_contracts_write ON public.prepaid_and_deferred_contracts\r\n  FOR ALL TO authenticated USING (\r\n    public.has_role(auth.uid(), 'owner')\r\n    OR public.has_role(auth.uid(), 'manager')\r\n    OR public.has_role(auth.uid(), 'accountant')\r\n  )","DROP POLICY IF EXISTS amortization_lines_read ON public.amortization_lines","CREATE POLICY amortization_lines_read ON public.amortization_lines\r\n  FOR SELECT TO authenticated USING (public.is_staff(auth.uid()))","GRANT SELECT, INSERT, UPDATE ON public.prepaid_and_deferred_contracts TO authenticated, service_role","GRANT SELECT ON public.amortization_lines TO authenticated, service_role"}	accounting_phase4_prepayments_deferred
27	{"-- ============================================================================\r\n-- 24_accounting_phase4_tax_settlement.sql\r\n--\r\n-- المرحلة 4 — المهمة T-23: التسوية الضريبية والإقرار الضريبي.\r\n--\r\n-- التحقق المحاسبي المعتمد:\r\n--   1316 = ضريبة القيمة المضافة على المشتريات (مدخلات — أصل مدين قابل للاسترداد)\r\n--   2311 = ضريبة القيمة المضافة المستحقة (مخرجات — التزام دائن محصل على المبيعات)\r\n--   2321 = صافي الضريبة المستحقة الدفع (التزام تسوية — ناتج مقابلة 2311 و 1316)\r\n--\r\n-- قيد التسوية عند إقفال الفترة الضريبية:\r\n--   Dr 2311  (تصفير ضريبة المخرجات المحصلة)\r\n--   Cr 1316  (تصفير ضريبة المدخلات المدفوعة)\r\n--   الفرق إلى 2321:\r\n--     Cr 2321 إذا كانت المخرجات > المدخلات (مبلغ مستحق السداد للهيئة)\r\n--     Dr 2321 إذا كانت المدخلات > المخرجات (رصيد دائن مسترد/مرحل)\r\n-- ============================================================================\r\n\r\n-- ── 1. جدول الفترات والتسويات الضريبية ───────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS public.tax_settlement_periods (\r\n  id                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  period_number            text NOT NULL UNIQUE,\r\n  start_date               date NOT NULL,\r\n  end_date                 date NOT NULL,\r\n  total_taxable_sales      numeric(18,2) NOT NULL DEFAULT 0,\r\n  output_tax_amount        numeric(18,2) NOT NULL DEFAULT 0, -- 2311\r\n  total_taxable_purchases  numeric(18,2) NOT NULL DEFAULT 0,\r\n  input_tax_amount         numeric(18,2) NOT NULL DEFAULT 0, -- 1316\r\n  net_tax_payable          numeric(18,2) NOT NULL DEFAULT 0, -- output - input\r\n  status                   text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'SETTLED', 'PAID')),\r\n  journal_entry_id         uuid REFERENCES public.journal_entries(id),\r\n  settled_at               timestamptz,\r\n  settled_by               uuid REFERENCES auth.users(id),\r\n  paid_at                  timestamptz,\r\n  payment_journal_entry_id uuid REFERENCES public.journal_entries(id),\r\n  notes                    text,\r\n  created_at               timestamptz NOT NULL DEFAULT now(),\r\n  CONSTRAINT chk_tax_period_dates CHECK (end_date >= start_date)\r\n)","CREATE INDEX IF NOT EXISTS ix_tax_settlement_status ON public.tax_settlement_periods(status)","CREATE INDEX IF NOT EXISTS ix_tax_settlement_dates ON public.tax_settlement_periods(start_date, end_date)","COMMENT ON TABLE public.tax_settlement_periods IS\r\n  'T-23: سجل الإقرارات والتسويات الضريبية الدورية وقيد التسوية 2311 مقابل 1316 وسداد 2321.'","-- ── 2. دالة توليد بيانات الإقرار الضريبي (تقرير استعلامي) ────────────────────\r\nCREATE OR REPLACE FUNCTION public.generate_tax_declaration(\r\n  p_start_date date,\r\n  p_end_date   date\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user          uuid := auth.uid();\r\n  v_sales_taxable numeric(18,2) := 0;\r\n  v_output_tax    numeric(18,2) := 0;\r\n  v_purch_taxable numeric(18,2) := 0;\r\n  v_input_tax     numeric(18,2) := 0;\r\n  v_net_tax       numeric(18,2) := 0;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  -- ⚠️ الكتالوج يدعوها من الواجهة بوسيطَين، ونمررهما NULL أحيانًا عند الاستعلام\r\n  --    الحر. بلا هذا الفحص يرجع مجموعًا صفريًا صامتًا (مضلّل)، فيُرفض صراحةً.\r\n  IF p_start_date IS NULL OR p_end_date IS NULL THEN\r\n    RAISE EXCEPTION 'Tax declaration needs both start_date and end_date'\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n  IF p_end_date < p_start_date THEN\r\n    RAISE EXCEPTION 'Tax declaration end_date (%) is before start_date (%)', p_end_date, p_start_date\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  -- 1) ضريبة المخرجات من القيود المرحلة لحساب 2311 (رصيد دائن)\r\n  SELECT coalesce(sum(jl.credit - jl.debit), 0)\r\n    INTO v_output_tax\r\n    FROM public.journal_lines jl\r\n    JOIN public.journal_entries je ON je.id = jl.entry_id\r\n    JOIN public.accounts a ON a.id = jl.account_id\r\n   WHERE a.code = '2311'\r\n     AND je.status = 'POSTED'\r\n     AND je.source_type <> 'tax_settlement'\r\n     AND je.entry_date BETWEEN p_start_date AND p_end_date;\r\n\r\n  -- 2) ضريبة المدخلات من القيود المرحلة لحساب 1316 (رصيد مدين)\r\n  SELECT coalesce(sum(jl.debit - jl.credit), 0)\r\n    INTO v_input_tax\r\n    FROM public.journal_lines jl\r\n    JOIN public.journal_entries je ON je.id = jl.entry_id\r\n    JOIN public.accounts a ON a.id = jl.account_id\r\n   WHERE a.code = '1316'\r\n     AND je.status = 'POSTED'\r\n     AND je.source_type <> 'tax_settlement'\r\n     AND je.entry_date BETWEEN p_start_date AND p_end_date;\r\n\r\n  -- 3) إجمالي مبيعات الفترة الخاضعة للضريبة من الفواتير\r\n  --\r\n  -- ⚠️ الفاتورة لا تحمل عمود تاريخ مستقل: تاريخها التشغيلي هو created_at\r\n  --    (الترحيل يعتمد عليه، وقوائم التقارير كذلك — راجع 12_reporting_views).\r\n  --    أُصلح هنا بعد أن كان الاستعلام يقرأ invoice_date غير الموجود فيرمي\r\n  --    42703 «column invoice_date does not exist» عند كل استدعاء للإقرار\r\n  --    الضريبي وتسوية الفترة — أي أن الوحدة كانت معطّلة بالكامل.\r\n  --    النطاق الزمني [start, end] شامل: نقارن نصف مفتوح (<= نهاية اليوم) حتى\r\n  --    لا تسقط فواتير آخر يوم بعد منتصف الليل.\r\n  SELECT coalesce(sum(subtotal), 0)\r\n    INTO v_sales_taxable\r\n    FROM public.sales_invoices\r\n    WHERE status = 'confirmed'\r\n      AND created_at >= p_start_date\r\n      AND created_at <  p_end_date + 1;\r\n\r\n  -- 4) إجمالي مشتريات الفترة من الفواتير\r\n  SELECT coalesce(sum(subtotal), 0)\r\n    INTO v_purch_taxable\r\n    FROM public.purchase_invoices\r\n    WHERE status = 'confirmed'\r\n      AND created_at >= p_start_date\r\n      AND created_at <  p_end_date + 1;\r\n\r\n  v_net_tax := v_output_tax - v_input_tax;\r\n\r\n  RETURN jsonb_build_object(\r\n    'start_date', p_start_date,\r\n    'end_date', p_end_date,\r\n    'taxable_sales', v_sales_taxable,\r\n    'output_tax', v_output_tax,\r\n    'taxable_purchases', v_purch_taxable,\r\n    'input_tax', v_input_tax,\r\n    'net_tax_payable', v_net_tax\r\n  );\r\nEND $$","REVOKE ALL ON FUNCTION public.generate_tax_declaration(date, date) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.generate_tax_declaration(date, date) TO authenticated, service_role","-- ── 3. دالة التسوية الضريبية وإقفال الفترة (Dr 2311 / Cr 1316 / الفرق 2321) ──\r\nCREATE OR REPLACE FUNCTION public.settle_tax_period(\r\n  p_start_date      date,\r\n  p_end_date        date,\r\n  p_period_number   text,\r\n  p_settlement_date date DEFAULT CURRENT_DATE\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user          uuid := auth.uid();\r\n  v_decl          jsonb;\r\n  v_output_tax    numeric(18,2);\r\n  v_input_tax     numeric(18,2);\r\n  v_net_tax       numeric(18,2);\r\n  v_sales         numeric(18,2);\r\n  v_purch         numeric(18,2);\r\n  v_lines         jsonb := '[]'::jsonb;\r\n  v_entry_id      uuid;\r\n  v_settle_id     uuid;\r\n  v_memo          text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  -- ⚠️ لا تسوية بلا نطاق وسياق: رفض صريح بدل قيد تسوية صفري كاذب.\r\n  IF p_start_date IS NULL OR p_end_date IS NULL\r\n     OR nullif(btrim(coalesce(p_period_number, '')), '') IS NULL THEN\r\n    RAISE EXCEPTION 'Tax settlement requires start_date, end_date and period_number'\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n  IF p_end_date < p_start_date THEN\r\n    RAISE EXCEPTION 'Tax settlement end_date (%) is before start_date (%)', p_end_date, p_start_date\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may settle taxes';\r\n  END IF;\r\n\r\n  PERFORM public.assert_period_open(p_settlement_date);\r\n\r\n  IF EXISTS (\r\n    SELECT 1 FROM public.tax_settlement_periods\r\n     WHERE period_number = p_period_number\r\n  ) THEN\r\n    RAISE EXCEPTION 'Tax period % already exists or settled', p_period_number;\r\n  END IF;\r\n\r\n  -- قراءة أرقام الإقرار\r\n  v_decl := public.generate_tax_declaration(p_start_date, p_end_date);\r\n  v_sales      := (v_decl->>'taxable_sales')::numeric;\r\n  v_output_tax := (v_decl->>'output_tax')::numeric;\r\n  v_purch      := (v_decl->>'taxable_purchases')::numeric;\r\n  v_input_tax  := (v_decl->>'input_tax')::numeric;\r\n  v_net_tax    := (v_decl->>'net_tax_payable')::numeric;\r\n\r\n  IF v_output_tax = 0 AND v_input_tax = 0 THEN\r\n    RAISE EXCEPTION 'لا توجد حركات ضريبية مرحّلة للفترة المحددة لتسويتها';\r\n  END IF;\r\n\r\n  -- بناء قيد التسوية المتوازن:\r\n  -- 1) تصفير ضريبة المخرجات: Dr 2311 بمقدار رصيدها\r\n  IF v_output_tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '2311',\r\n        'debit', v_output_tax,\r\n        'credit', 0,\r\n        'memo', 'تسوية ضريبة المخرجات للفترة ' || p_period_number\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  -- 2) تصفير ضريبة المدخلات: Cr 1316 بمقدار رصيدها\r\n  IF v_input_tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '1316',\r\n        'debit', 0,\r\n        'credit', v_input_tax,\r\n        'memo', 'تسوية ضريبة المدخلات للفترة ' || p_period_number\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  -- 3) حساب صافي الضريبة المستحقة (2321):\r\n  IF v_net_tax > 0 THEN\r\n    -- التزام مستحق الدفع للهيئة: Cr 2321\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '2321',\r\n        'debit', 0,\r\n        'credit', v_net_tax,\r\n        'memo', 'صافي ضريبة القيمة المضافة المستحقة للدفع — ' || p_period_number\r\n      )\r\n    );\r\n  ELSIF v_net_tax < 0 THEN\r\n    -- رصيد دائن مسترد للمنشأة: Dr 2321\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '2321',\r\n        'debit', -v_net_tax,\r\n        'credit', 0,\r\n        'memo', 'رصيد ضريبة مدخلات فائض مسترد/مرحل — ' || p_period_number\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  v_memo := 'قيد التسوية والإقرار الضريبي للفترة ' || p_period_number ||\r\n            ' (' || to_char(p_start_date, 'YYYY-MM-DD') || ' إلى ' || to_char(p_end_date, 'YYYY-MM-DD') || ')';\r\n\r\n  v_entry_id := public.create_journal_entry(\r\n    v_memo,\r\n    p_settlement_date,\r\n    'tax_settlement',\r\n    NULL,\r\n    true,\r\n    v_lines,\r\n    false\r\n  );\r\n\r\n  INSERT INTO public.tax_settlement_periods (\r\n    period_number, start_date, end_date, total_taxable_sales,\r\n    output_tax_amount, total_taxable_purchases, input_tax_amount,\r\n    net_tax_payable, status, journal_entry_id, settled_at, settled_by\r\n  )\r\n  VALUES (\r\n    p_period_number, p_start_date, p_end_date, v_sales,\r\n    v_output_tax, v_purch, v_input_tax,\r\n    v_net_tax, 'SETTLED', v_entry_id, now(), v_user\r\n  )\r\n  RETURNING id INTO v_settle_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'tax.settled', 'tax_settlement', v_settle_id,\r\n          jsonb_build_object('period_number', p_period_number, 'net_tax', v_net_tax, 'entry_id', v_entry_id));\r\n\r\n  RETURN v_settle_id;\r\nEND $$","REVOKE ALL ON FUNCTION public.settle_tax_period(date, date, text, date) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.settle_tax_period(date, date, text, date) TO authenticated, service_role","COMMENT ON FUNCTION public.settle_tax_period(date, date, text, date) IS\r\n  'T-23: تسوية الفترة الضريبية بالقيد المتوازن Dr 2311 / Cr 1316 وإثبات الفرق في 2321.'","-- ── 4. دالة سداد الضريبة لهيئة الضرائب (Dr 2321 / Cr نقدية/بنك) ──────────────\r\nCREATE OR REPLACE FUNCTION public.pay_tax_settlement(\r\n  p_settlement_id    uuid,\r\n  p_payment_date     date DEFAULT CURRENT_DATE,\r\n  p_payment_account  text DEFAULT '1101'\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user     uuid := auth.uid();\r\n  v_settle   record;\r\n  v_lines    jsonb;\r\n  v_entry_id uuid;\r\n  v_memo     text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may pay tax settlements';\r\n  END IF;\r\n\r\n  PERFORM public.assert_period_open(p_payment_date);\r\n\r\n  SELECT * INTO v_settle FROM public.tax_settlement_periods WHERE id = p_settlement_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Tax settlement not found';\r\n  END IF;\r\n\r\n  IF v_settle.status <> 'SETTLED' THEN\r\n    RAISE EXCEPTION 'Settlement % is not in SETTLED status (current: %)', v_settle.period_number, v_settle.status;\r\n  END IF;\r\n\r\n  IF v_settle.net_tax_payable <= 0 THEN\r\n    RAISE EXCEPTION 'لا يوجد التزام ضريبي واجب السداد (الصافي %)', v_settle.net_tax_payable;\r\n  END IF;\r\n\r\n  v_memo := 'سداد ضريبة القيمة المضافة لهيئة الضرائب عن الفترة ' || v_settle.period_number;\r\n  v_lines := jsonb_build_array(\r\n    jsonb_build_object(\r\n      'account_code', '2321', -- تصفير الالتزام\r\n      'debit', v_settle.net_tax_payable,\r\n      'credit', 0,\r\n      'memo', 'سداد الالتزام الضريبي — ' || v_settle.period_number\r\n    ),\r\n    jsonb_build_object(\r\n      'account_code', coalesce(p_payment_account, '1101'), -- دفع من الصندوق أو البنك\r\n      'debit', 0,\r\n      'credit', v_settle.net_tax_payable,\r\n      'memo', 'دفع الضريبة المستحقة'\r\n    )\r\n  );\r\n\r\n  v_entry_id := public.create_journal_entry(\r\n    v_memo,\r\n    p_payment_date,\r\n    'tax_payment',\r\n    p_settlement_id,\r\n    true,\r\n    v_lines,\r\n    false\r\n  );\r\n\r\n  UPDATE public.tax_settlement_periods\r\n     SET status = 'PAID',\r\n         paid_at = now(),\r\n         payment_journal_entry_id = v_entry_id\r\n   WHERE id = p_settlement_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'tax.paid', 'tax_settlement', p_settlement_id,\r\n          jsonb_build_object('period_number', v_settle.period_number, 'amount', v_settle.net_tax_payable, 'entry_id', v_entry_id));\r\n\r\n  RETURN v_entry_id;\r\nEND $$","REVOKE ALL ON FUNCTION public.pay_tax_settlement(uuid, date, text) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.pay_tax_settlement(uuid, date, text) TO authenticated, service_role","-- ── 5. RLS ───────────────────────────────────────────────────────────────────\r\nALTER TABLE public.tax_settlement_periods ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS tax_settlements_read ON public.tax_settlement_periods","CREATE POLICY tax_settlements_read ON public.tax_settlement_periods\r\n  FOR SELECT TO authenticated USING (public.is_staff(auth.uid()))","DROP POLICY IF EXISTS tax_settlements_write ON public.tax_settlement_periods","CREATE POLICY tax_settlements_write ON public.tax_settlement_periods\r\n  FOR ALL TO authenticated USING (\r\n    public.has_role(auth.uid(), 'owner')\r\n    OR public.has_role(auth.uid(), 'manager')\r\n    OR public.has_role(auth.uid(), 'accountant')\r\n  )","GRANT SELECT, INSERT, UPDATE ON public.tax_settlement_periods TO authenticated, service_role"}	accounting_phase4_tax_settlement
28	{"-- ============================================================================\r\n-- 25_accounting_phase4_supplier_ledger.sql\r\n--\r\n-- المرحلة الرابعة — المهمة T-24:\r\n-- دفتر الموردين (supplier_ledger) وسندات صرف الموردين (supplier_payments)\r\n-- مع تواريخ السداد والاستحقاق المستقلة والترحيل المحاسبي الذري (Dr 2111 / Cr 1101 or 1111).\r\n--\r\n-- معايير السلامة والجودة:\r\n-- 1. جداول غير هدّامة مع IF NOT EXISTS.\r\n-- 2. مفاتيح فريدة source_key لمنع التكرار نهائياً (Idempotent).\r\n-- 3. تحديث ذري لأرصدة الموردين بدون greatest(..., 0).\r\n-- 4. قيد محاسبي مزدوج متوازن ذرياً لكل سند صرف.\r\n-- 5. مزامنة تلقائية عبر Triggers لفواتير الشراء والمرتجعات.\r\n-- ============================================================================\r\n\r\n-- ── 1. جدول دفتر حركات الموردين (supplier_ledger) ──────────────────────────\r\nCREATE TABLE IF NOT EXISTS public.supplier_ledger (\r\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  supplier_id uuid NOT NULL REFERENCES public.suppliers(id) ON DELETE CASCADE,\r\n  entry_type text NOT NULL, -- 'PURCHASE_INVOICE', 'PAYMENT', 'PURCHASE_RETURN', 'OPENING_BALANCE', 'ADJUSTMENT'\r\n  debit numeric(14,2) NOT NULL DEFAULT 0, -- ما سُدِّد أو أُرجع للمورد (ينقص التزامنا)\r\n  credit numeric(14,2) NOT NULL DEFAULT 0, -- ما استحق للمورد علينا (يزيد التزامنا)\r\n  balance_after numeric(14,2), -- رصيد المورد بعد الحركة\r\n  reference_type text, -- 'purchase_invoice', 'supplier_payment', 'purchase_return', 'manual'\r\n  reference_id uuid,\r\n  due_date date, -- تاريخ استحقاق الفاتورة أو القسط\r\n  occurred_at timestamptz NOT NULL DEFAULT now(),\r\n  created_by uuid,\r\n  source_key text UNIQUE, -- لمنع ازدواج الحركات\r\n  note text,\r\n  created_at timestamptz NOT NULL DEFAULT now()\r\n)","CREATE INDEX IF NOT EXISTS idx_supplier_ledger_supplier_occurred\r\n  ON public.supplier_ledger(supplier_id, occurred_at)","CREATE INDEX IF NOT EXISTS idx_supplier_ledger_reference\r\n  ON public.supplier_ledger(reference_type, reference_id)","ALTER TABLE public.supplier_ledger ENABLE ROW LEVEL SECURITY","DO $$\r\nBEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM pg_policies WHERE tablename = 'supplier_ledger' AND policyname = 'supplier_ledger_read_all'\r\n  ) THEN\r\n    CREATE POLICY supplier_ledger_read_all ON public.supplier_ledger\r\n      FOR SELECT TO authenticated USING (true);\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM pg_policies WHERE tablename = 'supplier_ledger' AND policyname = 'supplier_ledger_insert_auth'\r\n  ) THEN\r\n    CREATE POLICY supplier_ledger_insert_auth ON public.supplier_ledger\r\n      FOR INSERT TO authenticated WITH CHECK (true);\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM pg_policies WHERE tablename = 'supplier_ledger' AND policyname = 'supplier_ledger_update_auth'\r\n  ) THEN\r\n    CREATE POLICY supplier_ledger_update_auth ON public.supplier_ledger\r\n      FOR UPDATE TO authenticated USING (true);\r\n  END IF;\r\nEND $$","COMMENT ON TABLE public.supplier_ledger IS\r\n  'T-24: دفتر أستاذ حركات الموردين التفصيلية (فواتير، مرتجعات، دفعات، تسويات) بتاريخ استحقاق وسداد صريح.'","-- ── 2. تسلسل وسجل سندات صرف الموردين (supplier_payments) ────────────────────\r\nCREATE SEQUENCE IF NOT EXISTS public.supplier_payment_seq START 1","CREATE TABLE IF NOT EXISTS public.supplier_payments (\r\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  voucher_number text UNIQUE NOT NULL,\r\n  supplier_id uuid NOT NULL REFERENCES public.suppliers(id) ON DELETE RESTRICT,\r\n  amount numeric(14,2) NOT NULL CHECK (amount > 0),\r\n  payment_method text NOT NULL DEFAULT 'CASH', -- 'CASH', 'BANK', 'TRANSFER', 'CHEQUE'\r\n  account_code text NOT NULL DEFAULT '1101', -- '1101' نقدية بالصندوق، '1111' حساب بنكي\r\n  payment_date date NOT NULL DEFAULT CURRENT_DATE,\r\n  journal_entry_id uuid REFERENCES public.journal_entries(id) ON DELETE SET NULL,\r\n  notes text,\r\n  created_by uuid,\r\n  created_at timestamptz NOT NULL DEFAULT now()\r\n)","CREATE INDEX IF NOT EXISTS idx_supplier_payments_supplier_date\r\n  ON public.supplier_payments(supplier_id, payment_date)","ALTER TABLE public.supplier_payments ENABLE ROW LEVEL SECURITY","DO $$\r\nBEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM pg_policies WHERE tablename = 'supplier_payments' AND policyname = 'supplier_payments_read_all'\r\n  ) THEN\r\n    CREATE POLICY supplier_payments_read_all ON public.supplier_payments\r\n      FOR SELECT TO authenticated USING (true);\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM pg_policies WHERE tablename = 'supplier_payments' AND policyname = 'supplier_payments_insert_auth'\r\n  ) THEN\r\n    CREATE POLICY supplier_payments_insert_auth ON public.supplier_payments\r\n      FOR INSERT TO authenticated WITH CHECK (true);\r\n  END IF;\r\nEND $$","COMMENT ON TABLE public.supplier_payments IS\r\n  'T-24: سندات صرف الموردين المستقلة مع توثيق طريقة الدفع، الحساب المالي، والقيد المحاسبي.'","-- ── 3. دالة توليد رقم سند الصرف ────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.next_supplier_voucher_number()\r\nRETURNS text\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nAS $$\r\nDECLARE\r\n  v_seq bigint;\r\n  v_prefix text;\r\nBEGIN\r\n  v_seq := nextval('public.supplier_payment_seq');\r\n  v_prefix := 'PV-' || to_char(CURRENT_DATE, 'YYYYMM') || '-';\r\n  RETURN v_prefix || lpad(v_seq::text, 4, '0');\r\nEND;\r\n$$","-- ── 4. دالة تسجيل سند صرف للمورد وترحيله محاسبياً وذرياً ───────────────────\r\nCREATE OR REPLACE FUNCTION public.record_supplier_payment(\r\n  p_supplier_id uuid,\r\n  p_amount numeric,\r\n  p_payment_method text DEFAULT 'CASH',\r\n  p_account_code text DEFAULT NULL,\r\n  p_payment_date date DEFAULT CURRENT_DATE,\r\n  p_notes text DEFAULT NULL,\r\n  p_due_date date DEFAULT NULL\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_supplier_name text;\r\n  v_payment_id uuid;\r\n  v_voucher_no text;\r\n  v_account text;\r\n  v_journal_id uuid;\r\n  v_lines jsonb;\r\n  v_new_balance numeric;\r\nBEGIN\r\n  IF p_supplier_id IS NULL THEN\r\n    RAISE EXCEPTION 'Supplier ID is required';\r\n  END IF;\r\n\r\n  IF p_amount IS NULL OR p_amount <= 0 THEN\r\n    RAISE EXCEPTION 'Payment amount must be greater than zero, got %', p_amount;\r\n  END IF;\r\n\r\n  SELECT name INTO v_supplier_name\r\n  FROM public.suppliers\r\n  WHERE id = p_supplier_id;\r\n\r\n  IF v_supplier_name IS NULL THEN\r\n    RAISE EXCEPTION 'Supplier with ID % not found', p_supplier_id;\r\n  END IF;\r\n\r\n  -- تحديد الحساب المالي (الصندوق أو البنك)\r\n  IF p_account_code IS NOT NULL AND btrim(p_account_code) <> '' THEN\r\n    v_account := btrim(p_account_code);\r\n    IF NOT EXISTS (SELECT 1 FROM public.accounts WHERE code = v_account) THEN\r\n      RAISE EXCEPTION 'Account code % does not exist in chart of accounts', v_account;\r\n    END IF;\r\n  ELSE\r\n    -- الافتراضي: إن كانت طريقة الدفع بنك أو تحويل -> 1111، وإلا -> 1101 (صندوق)\r\n    IF upper(coalesce(p_payment_method, 'CASH')) IN ('BANK', 'TRANSFER', 'CHEQUE', 'CARD') THEN\r\n      v_account := '1111';\r\n    ELSE\r\n      v_account := '1101';\r\n    END IF;\r\n  END IF;\r\n\r\n  v_voucher_no := public.next_supplier_voucher_number();\r\n\r\n  -- 1. إدراج سند الصرف\r\n  INSERT INTO public.supplier_payments (\r\n    voucher_number,\r\n    supplier_id,\r\n    amount,\r\n    payment_method,\r\n    account_code,\r\n    payment_date,\r\n    notes,\r\n    created_by\r\n  ) VALUES (\r\n    v_voucher_no,\r\n    p_supplier_id,\r\n    round(p_amount, 2),\r\n    upper(coalesce(p_payment_method, 'CASH')),\r\n    v_account,\r\n    coalesce(p_payment_date, CURRENT_DATE),\r\n    p_notes,\r\n    v_user\r\n  ) RETURNING id INTO v_payment_id;\r\n\r\n  -- 2. إعداد وترحيل القيد المحاسبي المزدوج المتوازن:\r\n  -- Dr 2111 (ذمم الموردين) - تخفيض الالتزام\r\n  -- Cr v_account (1101 نقدية بالصندوق أو 1111 بنك) - تخفيض النقدية\r\n  v_lines := jsonb_build_array(\r\n    jsonb_build_object(\r\n      'account_code', '2111',\r\n      'debit', round(p_amount, 2),\r\n      'credit', 0,\r\n      'memo', 'سداد ذمة للمورد ' || v_supplier_name\r\n    ),\r\n    jsonb_build_object(\r\n      'account_code', v_account,\r\n      'debit', 0,\r\n      'credit', round(p_amount, 2),\r\n      'memo', 'صرف نقدي/بنكي بسند ' || v_voucher_no\r\n    )\r\n  );\r\n\r\n  v_journal_id := public.create_journal_entry(\r\n    'سند صرف مورد ' || v_supplier_name || ' (' || v_voucher_no || ')',\r\n    coalesce(p_payment_date, CURRENT_DATE),\r\n    'supplier_payment',\r\n    v_payment_id,\r\n    true, -- is_system\r\n    v_lines\r\n  );\r\n\r\n  -- ربط القيد بالسند\r\n  UPDATE public.supplier_payments\r\n  SET journal_entry_id = v_journal_id\r\n  WHERE id = v_payment_id;\r\n\r\n  -- 3. تحديث رصيد المورد ذرياً دون greatest(..., 0)\r\n  UPDATE public.suppliers\r\n  SET balance = round(coalesce(balance, 0) - p_amount, 2),\r\n      updated_at = now()\r\n  WHERE id = p_supplier_id\r\n  RETURNING balance INTO v_new_balance;\r\n\r\n  -- 4. إدراج الحركة في دفتر الموردين\r\n  INSERT INTO public.supplier_ledger (\r\n    supplier_id,\r\n    entry_type,\r\n    debit,\r\n    credit,\r\n    balance_after,\r\n    reference_type,\r\n    reference_id,\r\n    due_date,\r\n    occurred_at,\r\n    created_by,\r\n    source_key,\r\n    note\r\n  ) VALUES (\r\n    p_supplier_id,\r\n    'PAYMENT',\r\n    round(p_amount, 2),\r\n    0,\r\n    v_new_balance,\r\n    'supplier_payment',\r\n    v_payment_id,\r\n    p_due_date,\r\n    coalesce(p_payment_date::timestamptz, now()),\r\n    v_user,\r\n    'SUP-PAY-' || v_payment_id::text,\r\n    coalesce(p_notes, 'سند صرف رقم ' || v_voucher_no)\r\n  );\r\n\r\n  -- سجل التدقيق\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (\r\n    v_user,\r\n    'supplier_payment.recorded',\r\n    'supplier_payment',\r\n    v_payment_id,\r\n    jsonb_build_object(\r\n      'voucher_number', v_voucher_no,\r\n      'supplier_id', p_supplier_id,\r\n      'amount', round(p_amount, 2),\r\n      'account_code', v_account,\r\n      'journal_entry_id', v_journal_id,\r\n      'new_balance', v_new_balance\r\n    )\r\n  );\r\n\r\n  RETURN jsonb_build_object(\r\n    'success', true,\r\n    'payment_id', v_payment_id,\r\n    'voucher_number', v_voucher_no,\r\n    'journal_entry_id', v_journal_id,\r\n    'amount', round(p_amount, 2),\r\n    'new_balance', v_new_balance\r\n  );\r\nEND;\r\n$$","COMMENT ON FUNCTION public.record_supplier_payment(uuid, numeric, text, text, date, text, date) IS\r\n  'T-24: تسجيل سند صرف للمورد وترحيل قيد مزدوج متوازن Dr 2111 / Cr 1101-1111، وتحديث رصيد ودفتر المورد ذرياً.'","-- ── 5. Triggers لمزامنة فواتير ومرتجعات الشراء تلقائياً مع دفتر الموردين ─────\r\n\r\n-- (أ) مشغل فواتير الشراء\r\nCREATE OR REPLACE FUNCTION public.trg_purchase_invoice_to_supplier_ledger()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nAS $$\r\nBEGIN\r\n  IF NEW.supplier_id IS NOT NULL THEN\r\n    -- إثبات حركة استحقاق الفاتورة (Credit للمورد)\r\n    INSERT INTO public.supplier_ledger (\r\n      supplier_id, entry_type, debit, credit, balance_after,\r\n      reference_type, reference_id, occurred_at, source_key, note, created_by\r\n    ) VALUES (\r\n      NEW.supplier_id,\r\n      'PURCHASE_INVOICE',\r\n      0,\r\n      round(NEW.total, 2),\r\n      (SELECT balance FROM public.suppliers WHERE id = NEW.supplier_id),\r\n      'purchase_invoice',\r\n      NEW.id,\r\n      coalesce(NEW.created_at, now()),\r\n      'PINV-' || NEW.id::text,\r\n      'فاتورة مشتريات رقم ' || NEW.invoice_number || coalesce(' - ' || NEW.note, ''),\r\n      NEW.created_by\r\n    ) ON CONFLICT (source_key) DO NOTHING;\r\n\r\n    -- إثبات السداد الفوري المرافق للفاتورة إن وُجد (Debit للمورد)\r\n    IF coalesce(NEW.paid, 0) > 0 THEN\r\n      INSERT INTO public.supplier_ledger (\r\n        supplier_id, entry_type, debit, credit, balance_after,\r\n        reference_type, reference_id, occurred_at, source_key, note, created_by\r\n      ) VALUES (\r\n        NEW.supplier_id,\r\n        'PAYMENT',\r\n        round(NEW.paid, 2),\r\n        0,\r\n        (SELECT balance FROM public.suppliers WHERE id = NEW.supplier_id),\r\n        'purchase_invoice_payment',\r\n        NEW.id,\r\n        coalesce(NEW.created_at, now()),\r\n        'PINV-PAID-' || NEW.id::text,\r\n        'سداد فوري مرافق لفاتورة مشتريات ' || NEW.invoice_number,\r\n        NEW.created_by\r\n      ) ON CONFLICT (source_key) DO NOTHING;\r\n    END IF;\r\n  END IF;\r\n  RETURN NEW;\r\nEND;\r\n$$","DROP TRIGGER IF EXISTS trg_purchase_invoice_supplier_ledger ON public.purchase_invoices","CREATE TRIGGER trg_purchase_invoice_supplier_ledger\r\n  AFTER INSERT ON public.purchase_invoices\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION public.trg_purchase_invoice_to_supplier_ledger()","-- (ب) مشغل مرتجعات الشراء\r\nCREATE OR REPLACE FUNCTION public.trg_purchase_return_to_supplier_ledger()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nAS $$\r\nBEGIN\r\n  IF NEW.supplier_id IS NOT NULL THEN\r\n    -- إثبات مرتجع الشراء (Debit للمورد - تخفيض دينه)\r\n    INSERT INTO public.supplier_ledger (\r\n      supplier_id, entry_type, debit, credit, balance_after,\r\n      reference_type, reference_id, occurred_at, source_key, note, created_by\r\n    ) VALUES (\r\n      NEW.supplier_id,\r\n      'PURCHASE_RETURN',\r\n      round(NEW.total, 2),\r\n      0,\r\n      (SELECT balance FROM public.suppliers WHERE id = NEW.supplier_id),\r\n      'purchase_return',\r\n      NEW.id,\r\n      coalesce(NEW.created_at, now()),\r\n      'PRET-' || NEW.id::text,\r\n      'مرتجع مشتريات رقم ' || NEW.return_number || coalesce(' - ' || NEW.note, ''),\r\n      NEW.created_by\r\n    ) ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n  RETURN NEW;\r\nEND;\r\n$$","DROP TRIGGER IF EXISTS trg_purchase_return_supplier_ledger ON public.purchase_returns","CREATE TRIGGER trg_purchase_return_supplier_ledger\r\n  AFTER INSERT ON public.purchase_returns\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION public.trg_purchase_return_to_supplier_ledger()","-- ── 6. ترحيل البيانات التاريخية القائمة إن وُجدت (Backfill Idempotent) ───────\r\nINSERT INTO public.supplier_ledger (\r\n  supplier_id, entry_type, debit, credit, reference_type, reference_id, occurred_at, source_key, note, created_by\r\n)\r\nSELECT\r\n  pi.supplier_id,\r\n  'PURCHASE_INVOICE',\r\n  0,\r\n  round(pi.total, 2),\r\n  'purchase_invoice',\r\n  pi.id,\r\n  pi.created_at,\r\n  'PINV-' || pi.id::text,\r\n  'فاتورة مشتريات رقم ' || pi.invoice_number || coalesce(' - ' || pi.note, ''),\r\n  pi.created_by\r\nFROM public.purchase_invoices pi\r\nWHERE pi.supplier_id IS NOT NULL\r\nON CONFLICT (source_key) DO NOTHING","INSERT INTO public.supplier_ledger (\r\n  supplier_id, entry_type, debit, credit, reference_type, reference_id, occurred_at, source_key, note, created_by\r\n)\r\nSELECT\r\n  pi.supplier_id,\r\n  'PAYMENT',\r\n  round(pi.paid, 2),\r\n  0,\r\n  'purchase_invoice_payment',\r\n  pi.id,\r\n  pi.created_at,\r\n  'PINV-PAID-' || pi.id::text,\r\n  'سداد فوري مرافق لفاتورة مشتريات ' || pi.invoice_number,\r\n  pi.created_by\r\nFROM public.purchase_invoices pi\r\nWHERE pi.supplier_id IS NOT NULL AND coalesce(pi.paid, 0) > 0\r\nON CONFLICT (source_key) DO NOTHING","INSERT INTO public.supplier_ledger (\r\n  supplier_id, entry_type, debit, credit, reference_type, reference_id, occurred_at, source_key, note, created_by\r\n)\r\nSELECT\r\n  pr.supplier_id,\r\n  'PURCHASE_RETURN',\r\n  round(pr.total, 2),\r\n  0,\r\n  'purchase_return',\r\n  pr.id,\r\n  pr.created_at,\r\n  'PRET-' || pr.id::text,\r\n  'مرتجع مشتريات رقم ' || pr.return_number || coalesce(' - ' || pr.note, ''),\r\n  pr.created_by\r\nFROM public.purchase_returns pr\r\nWHERE pr.supplier_id IS NOT NULL\r\nON CONFLICT (source_key) DO NOTHING","-- ── 7. دالة كشف حساب المورد مع الرصيد التراكمي المتحرك ───────────────────────\r\nCREATE OR REPLACE FUNCTION public.get_supplier_statement(\r\n  p_supplier_id uuid,\r\n  p_start_date timestamptz DEFAULT NULL,\r\n  p_end_date timestamptz DEFAULT NULL\r\n)\r\nRETURNS TABLE (\r\n  id uuid,\r\n  occurred_at timestamptz,\r\n  entry_type text,\r\n  debit numeric,\r\n  credit numeric,\r\n  running_balance numeric,\r\n  reference_type text,\r\n  reference_id uuid,\r\n  due_date date,\r\n  note text\r\n)\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $$\r\n  WITH ordered_entries AS (\r\n    SELECT\r\n      sl.id,\r\n      sl.occurred_at,\r\n      sl.entry_type,\r\n      sl.debit,\r\n      sl.credit,\r\n      SUM(sl.credit - sl.debit) OVER (\r\n        ORDER BY sl.occurred_at ASC, sl.id ASC\r\n      ) AS running_balance,\r\n      sl.reference_type,\r\n      sl.reference_id,\r\n      sl.due_date,\r\n      sl.note\r\n    FROM public.supplier_ledger sl\r\n    WHERE sl.supplier_id = p_supplier_id\r\n  )\r\n  SELECT\r\n    oe.id,\r\n    oe.occurred_at,\r\n    oe.entry_type,\r\n    oe.debit,\r\n    oe.credit,\r\n    oe.running_balance,\r\n    oe.reference_type,\r\n    oe.reference_id,\r\n    oe.due_date,\r\n    oe.note\r\n  FROM ordered_entries oe\r\n  WHERE (p_start_date IS NULL OR oe.occurred_at >= p_start_date)\r\n    AND (p_end_date IS NULL OR oe.occurred_at <= p_end_date)\r\n  ORDER BY oe.occurred_at DESC, oe.id DESC;\r\n$$","COMMENT ON FUNCTION public.get_supplier_statement(uuid, timestamptz, timestamptz) IS\r\n  'T-24: جلب كشف حساب المورد التفصيلي مع احتساب الرصيد التراكمي المستحق للمورد عبر الفترات.'"}	accounting_phase4_supplier_ledger
29	{"-- ============================================================================\r\n-- 26_accounting_phase4_coa_hierarchy_accruals.sql\r\n--\r\n-- المرحلة الرابعة — المهمة T-25:\r\n-- ضبط شجرة الحسابات (parent_id) والحسابات التجميعية (is_postable = false)\r\n-- وتدقيق حسابات الاستحقاق (Accruals) ودوال استعراض الهيكل الشجري.\r\n--\r\n-- معايير السلامة والجودة:\r\n-- 1. إضافة الحسابات التجميعية (1000..5000) مع is_postable = false لمنع الترحيل المباشر.\r\n-- 2. ربط parent_id لكافة الحسابات الفرعية القائمة دون تغيير أكوادها أو تكسير الترحيل.\r\n-- 3. توفير حسابات الاستحقاق المتكاملة: 2221 (مصروفات مستحقة)، 2231 (إيرادات مقدمة)، 1231 (إيرادات مستحقة القبض).\r\n-- 4. توفير دالة get_chart_of_accounts_tree() لاستخراج الشجرة الهرمية وأرصدتها التجميعية.\r\n-- ============================================================================\r\n\r\nBEGIN","-- ── 1. إدراج الحسابات الرئيسية التجميعية (المستوى 1: الجذور) ───────────────\r\nINSERT INTO public.accounts (code, name_ar, account_type, is_system, is_postable, notes)\r\nVALUES\r\n  ('1000', 'الأصول',               'ASSET',     true, false, 'حساب رئيسي تجميعي (المستوى الأول) — الأصول'),\r\n  ('2000', 'الخصوم والالتزامات',    'LIABILITY', true, false, 'حساب رئيسي تجميعي (المستوى الأول) — الخصوم والالتزامات'),\r\n  ('3000', 'حقوق الملكية',         'EQUITY',    true, false, 'حساب رئيسي تجميعي (المستوى الأول) — حقوق الملكية'),\r\n  ('4000', 'الإيرادات',            'REVENUE',   true, false, 'حساب رئيسي تجميعي (المستوى الأول) — الإيرادات'),\r\n  ('5000', 'المصروفات',            'EXPENSE',   true, false, 'حساب رئيسي تجميعي (المستوى الأول) — المصروفات')\r\nON CONFLICT (code) DO UPDATE SET\r\n  is_postable = false,\r\n  account_type = EXCLUDED.account_type","-- ── 2. إدراج الحسابات التجميعية الفرعية (المستوى 2) وربطها بالجذور ──────────\r\n-- (أ) الأصول\r\nINSERT INTO public.accounts (code, name_ar, account_type, parent_id, is_system, is_postable, notes)\r\nVALUES\r\n  ('1100', 'النقدية والأرصدة بالبنوك وما في حكمها', 'ASSET', (SELECT id FROM public.accounts WHERE code = '1000'), true, false, 'حساب تجميعي للأموال النقدية والمصرفية والمحافظ'),\r\n  ('1200', 'المدينون والذمم المدينة التجارية',     'ASSET', (SELECT id FROM public.accounts WHERE code = '1000'), true, false, 'حساب تجميعي لذمم العملاء ومستحقات النشاط'),\r\n  ('1300', 'المخزون وبضاعة النشاط',                 'ASSET', (SELECT id FROM public.accounts WHERE code = '1000'), true, false, 'حساب تجميعي لجميع أصناف المخزون وضريبة المدخلات'),\r\n  ('1400', 'الأصول الثابتة',                        'ASSET', (SELECT id FROM public.accounts WHERE code = '1000'), true, false, 'حساب تجميعي للأصول الرأسمالية ومجمعات إهلاكها'),\r\n  ('1500', 'المصروفات والأصول المؤجلة والمدفوعة مقدماً', 'ASSET', (SELECT id FROM public.accounts WHERE code = '1000'), true, false, 'حساب تجميعي للمصروفات المدفوعة مقدماً والعقود المؤجلة')\r\nON CONFLICT (code) DO UPDATE SET\r\n  parent_id = (SELECT id FROM public.accounts WHERE code = '1000'),\r\n  is_postable = false","-- (ب) الخصوم\r\nINSERT INTO public.accounts (code, name_ar, account_type, parent_id, is_system, is_postable, notes)\r\nVALUES\r\n  ('2100', 'الذمم الدائنة والموردون وأمانات العملاء', 'LIABILITY', (SELECT id FROM public.accounts WHERE code = '2000'), true, false, 'حساب تجميعي للموردين والتزامات الأمانات'),\r\n  ('2200', 'الالتزامات المستحقة والقروض قصيرة الأجل',  'LIABILITY', (SELECT id FROM public.accounts WHERE code = '2000'), true, false, 'حساب تجميعي لمستحقات المصروفات والإيرادات المؤجلة'),\r\n  ('2300', 'الالتزامات الضريبية والضريبة المضافة',     'LIABILITY', (SELECT id FROM public.accounts WHERE code = '2000'), true, false, 'حساب تجميعي لضريبة المخرجات وصافي التسوية الضريبية')\r\nON CONFLICT (code) DO UPDATE SET\r\n  parent_id = (SELECT id FROM public.accounts WHERE code = '2000'),\r\n  is_postable = false","-- (ج) حقوق الملكية\r\nINSERT INTO public.accounts (code, name_ar, account_type, parent_id, is_system, is_postable, notes)\r\nVALUES\r\n  ('3100', 'رأس المال والمسحوبات الشخصية',          'EQUITY', (SELECT id FROM public.accounts WHERE code = '3000'), true, false, 'حساب تجميعي لرأس المال وحسابات الشركاء'),\r\n  ('3900', 'الأرباح والنتائج المالية المتراكمة',      'EQUITY', (SELECT id FROM public.accounts WHERE code = '3000'), true, false, 'حساب تجميعي للأرباح المحتجزة ونتيجة النشاط الجارية')\r\nON CONFLICT (code) DO UPDATE SET\r\n  parent_id = (SELECT id FROM public.accounts WHERE code = '3000'),\r\n  is_postable = false","-- (د) الإيرادات\r\nINSERT INTO public.accounts (code, name_ar, account_type, parent_id, is_system, is_postable, notes)\r\nVALUES\r\n  ('4100', 'إيرادات المبيعات والنشاط التشغيلي',      'REVENUE', (SELECT id FROM public.accounts WHERE code = '4000'), true, false, 'حساب تجميعي لإيراد المبيعات والخدمات'),\r\n  ('4900', 'إيرادات وأرباح أخرى غير تشغيلية',        'REVENUE', (SELECT id FROM public.accounts WHERE code = '4000'), true, false, 'حساب تجميعي للإيرادات المتنوعة وفروق العملة')\r\nON CONFLICT (code) DO UPDATE SET\r\n  parent_id = (SELECT id FROM public.accounts WHERE code = '4000'),\r\n  is_postable = false","-- (هـ) المصروفات\r\nINSERT INTO public.accounts (code, name_ar, account_type, parent_id, is_system, is_postable, notes)\r\nVALUES\r\n  ('5100', 'تكلفة البضاعة والمبيعات',               'EXPENSE', (SELECT id FROM public.accounts WHERE code = '5000'), true, false, 'حساب تجميعي لتكلفة المبيعات المباشرة'),\r\n  ('5200', 'أجور ورواتب ومنافع العاملين',            'EXPENSE', (SELECT id FROM public.accounts WHERE code = '5000'), true, false, 'حساب تجميعي للعمالة المباشرة والإدارية'),\r\n  ('5300', 'المصروفات التشغيلية والخدمية',           'EXPENSE', (SELECT id FROM public.accounts WHERE code = '5000'), true, false, 'حساب تجميعي لطاقة ومياه وإيجارات وصيانة التشغيل'),\r\n  ('5400', 'المصروفات الإدارية والعمومية',           'EXPENSE', (SELECT id FROM public.accounts WHERE code = '5000'), true, false, 'حساب تجميعي للمصروفات الإدارية والعمومية والمكتبية'),\r\n  ('5600', 'الإهلاك والاستهلاك للأصول',              'EXPENSE', (SELECT id FROM public.accounts WHERE code = '5000'), true, false, 'حساب تجميعي لإهلاك الأصول الثابتة'),\r\n  ('5900', 'فاقد وتلف ومصروفات أخرى',                'EXPENSE', (SELECT id FROM public.accounts WHERE code = '5000'), true, false, 'حساب تجميعي للفاقد والخسائر التشغيلية الأخرى')\r\nON CONFLICT (code) DO UPDATE SET\r\n  parent_id = (SELECT id FROM public.accounts WHERE code = '5000'),\r\n  is_postable = false","-- ── 3. تدقيق وضمان وجود حسابات الاستحقاق المتوازنة (Accruals) ───────────────\r\n-- أصل متداول: إيرادات مستحقة القبض (Accrued Revenue Receivable)\r\nINSERT INTO public.accounts (code, name_ar, account_type, parent_id, is_system, is_postable, notes)\r\nVALUES (\r\n  '1231',\r\n  'إيرادات مستحقة القبض',\r\n  'ASSET',\r\n  (SELECT id FROM public.accounts WHERE code = '1200'),\r\n  true,\r\n  true,\r\n  'أصل متداول: إيرادات تحققت للنشاط ولم يتم تحصيلها أو فوترتها بعد.'\r\n)\r\nON CONFLICT (code) DO UPDATE SET\r\n  parent_id = (SELECT id FROM public.accounts WHERE code = '1200'),\r\n  is_postable = true","-- التزام متداول: مصروفات مستحقة الدفع (Accrued Expenses Payable)\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '2200'),\r\n    is_postable = true\r\nWHERE code = '2221'","-- التزام متداول: إيرادات مستحقة / مؤجلة محصلة مقدماً (Unearned / Deferred Revenue)\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '2200'),\r\n    is_postable = true\r\nWHERE code = '2231'","-- ── 4. ربط كافة الحسابات الفرعية والتنفيذية بآبائها (Level 3/4) ────────────\r\n\r\n-- النقدية والبنوك -> 1100\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '1100')\r\nWHERE code IN ('1101', '1111', '1112', '1121', '1131', '1132', '1133', '1134', '1139')","-- العملاء والمدينون -> 1200\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '1200')\r\nWHERE code IN ('1211', '1231')","-- المخزون وضريبة المدخلات -> 1300\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '1300')\r\nWHERE code IN ('1311', '1312', '1313', '1314', '1315', '1316', '1321')","-- الأصول الثابتة ومجمع الإهلاك -> 1400\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '1400')\r\nWHERE code IN ('1411', '1421', '1431', '1491')","-- المصروفات المدفوعة مقدماً والمؤجلة -> 1500\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '1500')\r\nWHERE code IN ('1511', '1512')","-- الموردون وأمانات العملاء -> 2100\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '2100')\r\nWHERE code IN ('2111', '2121')","-- القروض والمستحقات -> 2200\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '2200')\r\nWHERE code IN ('2211', '2221', '2231')","-- الضرائب -> 2300\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '2300')\r\nWHERE code IN ('2311', '2321')","-- رأس المال والمسحوبات -> 3100\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '3100')\r\nWHERE code IN ('3111', '3211')","-- الأرباح والنتائج -> 3900\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '3900')\r\nWHERE code IN ('3911', '3921')","-- الإيرادات التشغيلية -> 4100\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '4100')\r\nWHERE code IN ('4111', '4211', '4311')","-- إيرادات أخرى -> 4900\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '4900')\r\nWHERE code IN ('4911')","-- تكلفة المبيعات -> 5100\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '5100')\r\nWHERE code IN ('5111')","-- الأجور والرواتب -> 5200\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '5200')\r\nWHERE code IN ('5211', '5221', '5231')","-- مصروفات التشغيل -> 5300\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '5300')\r\nWHERE code IN ('5311', '5312', '5313', '5314', '5315', '5316', '5317', '5318', '5319')","-- المصروفات العمومية والإدارية -> 5400\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '5400')\r\nWHERE code IN ('5411', '5511')","-- إهلاك الأصول -> 5600\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '5600')\r\nWHERE code IN ('5611')","-- خسائر وفاقد ومصروفات أخرى -> 5900\r\nUPDATE public.accounts\r\nSET parent_id = (SELECT id FROM public.accounts WHERE code = '5900')\r\nWHERE code IN ('5711', '5811', '5911', '5921')","-- ── 5. دالة استخراج شجرة دليل الحسابات مع الإحصائيات (Recursive CTE) ─────────\r\nCREATE OR REPLACE FUNCTION public.get_chart_of_accounts_tree()\r\nRETURNS TABLE (\r\n  id uuid,\r\n  code varchar(20),\r\n  name_ar text,\r\n  account_type public.account_type,\r\n  parent_id uuid,\r\n  parent_code varchar(20),\r\n  level integer,\r\n  is_postable boolean,\r\n  is_system boolean,\r\n  is_active boolean,\r\n  notes text,\r\n  total_debit numeric,\r\n  total_credit numeric,\r\n  current_balance numeric,\r\n  children_count bigint\r\n)\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $$\r\n  WITH RECURSIVE coa_tree AS (\r\n    -- الجذور (المستوى 1: الأصول، الخصوم، حقوق الملكية، الإيرادات، المصروفات)\r\n    SELECT\r\n      a.id,\r\n      a.code,\r\n      a.name_ar,\r\n      a.account_type,\r\n      a.parent_id,\r\n      CAST(NULL AS varchar(20)) AS parent_code,\r\n      1 AS level,\r\n      a.is_postable,\r\n      a.is_system,\r\n      a.is_active,\r\n      a.notes,\r\n      ARRAY[a.code::text] AS path\r\n    FROM public.accounts a\r\n    WHERE a.parent_id IS NULL\r\n\r\n    UNION ALL\r\n\r\n    -- الأبناء بالتكرار\r\n    SELECT\r\n      c.id,\r\n      c.code,\r\n      c.name_ar,\r\n      c.account_type,\r\n      c.parent_id,\r\n      p.code AS parent_code,\r\n      p.level + 1 AS level,\r\n      c.is_postable,\r\n      c.is_system,\r\n      c.is_active,\r\n      c.notes,\r\n      p.path || c.code::text AS path\r\n    FROM public.accounts c\r\n    JOIN coa_tree p ON c.parent_id = p.id\r\n  ),\r\n  account_balances AS (\r\n    -- مجاميع القيود المرحلة من دفتر اليومية لكل حساب\r\n    SELECT\r\n      jl.account_id,\r\n      round(coalesce(sum(jl.debit), 0), 2) AS debit,\r\n      round(coalesce(sum(jl.credit), 0), 2) AS credit\r\n    FROM public.journal_lines jl\r\n    JOIN public.journal_entries je ON je.id = jl.entry_id AND je.status = 'POSTED'\r\n    GROUP BY jl.account_id\r\n  ),\r\n  children_counts AS (\r\n    SELECT parent_id, count(*) AS cnt\r\n    FROM public.accounts\r\n    WHERE parent_id IS NOT NULL\r\n    GROUP BY parent_id\r\n  )\r\n  SELECT\r\n    t.id,\r\n    t.code,\r\n    t.name_ar,\r\n    t.account_type,\r\n    t.parent_id,\r\n    t.parent_code,\r\n    t.level,\r\n    t.is_postable,\r\n    t.is_system,\r\n    t.is_active,\r\n    t.notes,\r\n    coalesce(ab.debit, 0) AS total_debit,\r\n    coalesce(ab.credit, 0) AS total_credit,\r\n    CASE\r\n      -- طبيعة مدينة للأصول والمصروفات: مدين - دائن\r\n      WHEN t.account_type IN ('ASSET', 'EXPENSE') THEN\r\n        round(coalesce(ab.debit, 0) - coalesce(ab.credit, 0), 2)\r\n      -- طبيعة دائنة للخصوم وحقوق الملكية والإيرادات: دائن - مدين\r\n      ELSE\r\n        round(coalesce(ab.credit, 0) - coalesce(ab.debit, 0), 2)\r\n    END AS current_balance,\r\n    coalesce(cc.cnt, 0) AS children_count\r\n  FROM coa_tree t\r\n  LEFT JOIN account_balances ab ON ab.account_id = t.id\r\n  LEFT JOIN children_counts cc ON cc.parent_id = t.id\r\n  ORDER BY t.code ASC;\r\n$$","COMMENT ON FUNCTION public.get_chart_of_accounts_tree() IS\r\n  'T-25: استخراج الشجرة الهرمية الكاملة لدليل الحسابات مع مستويات التفرع، ومجاميع القيود، والأرصدة حسب طبيعة الحساب.'",COMMIT}	accounting_phase4_coa_hierarchy_accruals
30	{"-- 30_fix_stock_delta_adjustment_reason.sql\r\n-- Fix check constraint stock_movements_adjustment_reason_required\r\n-- by populating adjustment_reason upon INSERT in post_stock_delta when legacy movement type is 'adjustment'.\r\n\r\nCREATE OR REPLACE FUNCTION public.post_stock_delta(\r\n  p_product_id uuid,\r\n  p_warehouse_id uuid,\r\n  p_signed_qty numeric,\r\n  p_unit_cost numeric DEFAULT NULL::numeric,\r\n  p_movement_kind stock_movement_kind DEFAULT 'ADJUSTMENT'::stock_movement_kind,\r\n  p_source_type text DEFAULT NULL::text,\r\n  p_source_id uuid DEFAULT NULL::uuid,\r\n  p_note text DEFAULT NULL::text,\r\n  p_owner_type owner_type DEFAULT 'COMPANY'::owner_type,\r\n  p_owner_id uuid DEFAULT NULL::uuid,\r\n  p_movement_type_legacy movement_type DEFAULT NULL::movement_type\r\n)\r\nRETURNS numeric\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_existing    numeric;\r\n  v_new_qty     numeric;\r\n  v_total_cost  numeric;\r\n  v_legacy_type public.movement_type;\r\n  v_owner_type  public.owner_type := COALESCE(p_owner_type, 'COMPANY');\r\nBEGIN\r\n  IF p_signed_qty IS NULL OR p_signed_qty = 0 THEN\r\n    RAISE EXCEPTION 'Stock delta must be a non-zero quantity';\r\n  END IF;\r\n\r\n  IF p_product_id IS NULL OR p_warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Item and location are required for a stock movement';\r\n  END IF;\r\n\r\n  -- Lock the exact position being changed.\r\n  SELECT quantity\r\n    INTO v_existing\r\n  FROM public.inventory\r\n  WHERE product_id = p_product_id\r\n    AND warehouse_id = p_warehouse_id\r\n    AND owner_type = v_owner_type\r\n    AND owner_id IS NOT DISTINCT FROM p_owner_id\r\n  FOR UPDATE;\r\n\r\n  v_existing := COALESCE(v_existing, 0);\r\n  v_new_qty  := round(v_existing + p_signed_qty, 3);\r\n\r\n  -- Stock can never go negative, for company stock or for customer-owned stock.\r\n  IF v_new_qty < 0 THEN\r\n    RAISE EXCEPTION\r\n      'Insufficient stock: item %, location %, available %, requested %',\r\n      p_product_id, p_warehouse_id, v_existing, abs(p_signed_qty)\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  INSERT INTO public.inventory (product_id, warehouse_id, quantity, owner_type, owner_id, updated_at)\r\n  VALUES (p_product_id, p_warehouse_id, v_new_qty, v_owner_type, p_owner_id, now())\r\n  ON CONFLICT (product_id, warehouse_id, owner_type, owner_id)\r\n  DO UPDATE SET quantity = v_new_qty, updated_at = now();\r\n\r\n  v_total_cost := CASE\r\n    WHEN p_unit_cost IS NULL THEN NULL\r\n    ELSE round(abs(p_signed_qty) * p_unit_cost, 2)\r\n  END;\r\n\r\n  -- Legacy enum value, so the old reporting paths keep working unchanged.\r\n  v_legacy_type := COALESCE(\r\n    p_movement_type_legacy,\r\n    CASE p_movement_kind\r\n      WHEN 'RECEIPT'      THEN 'purchase'::public.movement_type\r\n      WHEN 'ISSUE'        THEN 'sale'::public.movement_type\r\n      WHEN 'TRANSFER_IN'  THEN 'transfer_in'::public.movement_type\r\n      WHEN 'TRANSFER_OUT' THEN 'transfer_out'::public.movement_type\r\n      WHEN 'OPENING'      THEN 'opening'::public.movement_type\r\n      WHEN 'PRODUCTION'   THEN 'production_in'::public.movement_type\r\n      ELSE 'adjustment'::public.movement_type\r\n    END\r\n  );\r\n\r\n  INSERT INTO public.stock_movements (\r\n    product_id, warehouse_id, movement_type, movement_kind,\r\n    quantity, unit_cost, total_cost,\r\n    reference_type, reference_id, source_type, source_id,\r\n    owner_type, owner_id,\r\n    note, created_by,\r\n    adjustment_reason\r\n  )\r\n  VALUES (\r\n    p_product_id, p_warehouse_id, v_legacy_type, p_movement_kind,\r\n    abs(p_signed_qty), p_unit_cost, v_total_cost,\r\n    p_source_type, p_source_id, p_source_type, p_source_id,\r\n    v_owner_type, p_owner_id,\r\n    nullif(btrim(COALESCE(p_note, '')), ''), auth.uid(),\r\n    CASE\r\n      WHEN v_legacy_type = 'adjustment'::public.movement_type\r\n      THEN COALESCE(nullif(btrim(p_note), ''), 'تسوية مخزون')\r\n      ELSE NULL\r\n    END\r\n  );\r\n\r\n  RETURN v_new_qty;\r\nEND $function$","-- Drop ambiguous 6-param overload of create_journal_entry so calls with default arguments resolve cleanly\r\nDROP FUNCTION IF EXISTS public.create_journal_entry(text, date, text, uuid, boolean, jsonb)"}	fix_stock_delta_adjustment_reason
31	{"-- ============================================================================\r\n-- 31_backup_engine.sql\r\n--\r\n-- محرك النسخ الاحتياطي الديناميكي (Server-Side Backup Engine).\r\n--\r\n-- الفكرة: بدلاً من قائمة جداول مكتوبة يدويًا في الواجهة (القديمة كانت 37 جدولًا\r\n-- فقط وتفوّت الوحدات المحاسبية)، تُقرأ قائمة الجداول وأعمدتها ديناميكيًا من\r\n-- information_schema وقت النسخ — أي يتكيف تلقائيًا مع أي مهاجرة جديدة.\r\n--\r\n-- الدوال:\r\n--   1. backup_schema_fingerprint()   بصمة المخطط (لتكشف تغيّر الجداول/الأعمدة)\r\n--   2. backup_export_all()           تفريغ JSONB لكل جداول public (مع حدود صفوف)\r\n--   3. backup_restore_all()          استعادة كاملة داخل Transaction واحد\r\n--\r\n-- الصلاحيات: الاستدعاء يتطلب دور owner أو manager (الاستعادة: owner فقط).\r\n-- لا يحتوي أي بيانات أعمال أو تجارية. راجع supabase/MIGRATIONS_RULES.md\r\n-- ============================================================================\r\n\r\nBEGIN","-- دالة sha256 مدمجة في PostgreSQL (PG11+) — لا تحتاج أي إضافة (pgcrypto\r\n-- قد لا يكون متاحًا باسم digest في مخطط extensions على بيئات الدوكر المحلية).\r\n\r\n-- ────────────────────────────────────────────────────────────────────────────\r\n-- 1. بصمة المخطط: هاش تجميعي لأسماء الجداول والأعمدة وأنواعها في public.\r\n--    إذا اختلف بين وقت النسخ ووقت الاستعادة → السكيما تغيّرت، نُعِر المستخدم.\r\n-- ────────────────────────────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.backup_schema_fingerprint()\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSET search_path = public, pg_temp\r\nAS $$\r\n  SELECT encode(sha256(\r\n    convert_to(\r\n      coalesce(string_agg(\r\n      t.table_name || '(' ||\r\n      (\r\n        SELECT string_agg(c.column_name || ':' || c.data_type, ',' ORDER BY c.ordinal_position)\r\n        FROM information_schema.columns c\r\n        WHERE c.table_schema = 'public' AND c.table_name = t.table_name\r\n      ) || ')'\r\n    , '|' ORDER BY t.table_name), ''), 'UTF8')\r\n  ), 'hex')\r\n  FROM information_schema.tables t\r\n  WHERE t.table_schema = 'public'\r\n    AND t.table_type = 'BASE TABLE';\r\n$$","-- ────────────────────────────────────────────────────────────────────────────\r\n-- 2. تفريغ كامل ديناميكي.\r\n--    - يقرأ كل جداول public من information_schema (لا قائمة يدوية).\r\n--    - يجمع كل صفوفها كـ JSONB (الأعمدة تُستخرج كما هي، `select *` ديناميكي).\r\n--    - جداول السجل الضخم (audit_logs / backup_logs / idempotency_keys) تُفرَّغ\r\n--      بأحدث N صفًا فقط لتجنب نفاد الذاكرة — عدد الجداول والصفوف يُعاد في الملخص.\r\n--    - SECURITY DEFINER: تتجاوز RLS لتفريغ كل الصفوف، لكنها محصورة بدور\r\n--      owner/manager عبر فحص صريح داخل الدالة.\r\n-- ────────────────────────────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.backup_export_all(\r\n  p_max_log_rows integer DEFAULT 5000\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public, extensions, pg_temp\r\nAS $$\r\nDECLARE\r\n  v_caller uuid := auth.uid();\r\n  tbl record;\r\n  v_result jsonb;\r\n  v_tables_payload jsonb := '{}'::jsonb;\r\n  v_row_count bigint;\r\n  v_total_rows bigint := 0;\r\n  v_table_count integer := 0;\r\n  v_capped integer := 0;\r\n  v_q text;\r\n  v_rows jsonb;\r\nBEGIN\r\n  -- ⚠️ superadmin المنصة (المستخدمون في platform_admins) يملكون دور متجر 'owner'\r\n  --    من البذرة، لكن لو أُنشئ حساب سوبر أدمن جديد بلا دور المتجر لُحجب عنه\r\n  --    التصدير رغم أن كل صلاحيات المنصة له. القاعدة: إما دور مالك/مدير،\r\n  --    أو سوبر أدمن منصة. (backup_restore_all يشترط owner فقط — بقصد الاستعادة.)\r\n  IF v_caller IS NULL\r\n     OR NOT (public.has_role(v_caller, 'owner')\r\n             OR public.has_role(v_caller, 'manager')\r\n             OR public.is_platform_superadmin(v_caller)) THEN\r\n    RAISE EXCEPTION 'BACKUP_AUTH: backup export requires owner, manager or platform superadmin'\r\n      USING HINT = 'لا يملك المستدعي صلاحية تصدير النسخ الاحتياطية';\r\n  END IF;\r\n\r\n  FOR tbl IN\r\n    SELECT t.table_name\r\n    FROM information_schema.tables t\r\n    WHERE t.table_schema = 'public' AND t.table_type = 'BASE TABLE'\r\n    ORDER BY t.table_name\r\n  LOOP\r\n    DECLARE\r\n      v_cap integer := NULL;\r\n    BEGIN\r\n      -- جداول السجل الضخمة: أحدث N صفًا فقط (بترتيب created_at) لتجنب نفاد الذاكرة.\r\n      IF tbl.table_name IN ('audit_logs', 'backup_logs', 'idempotency_keys') THEN\r\n        v_cap := p_max_log_rows;\r\n        v_capped := v_capped + 1;\r\n      END IF;\r\n\r\n      IF v_cap IS NOT NULL THEN\r\n        v_q := format(\r\n          'SELECT count(*)::bigint AS cnt, coalesce(jsonb_agg(to_jsonb(s)), ''[]''::jsonb) AS rows\r\n           FROM (SELECT * FROM public.%I ORDER BY created_at DESC LIMIT %s) s',\r\n          tbl.table_name, v_cap\r\n        );\r\n      ELSE\r\n        v_q := format(\r\n          'SELECT count(*)::bigint AS cnt, coalesce(jsonb_agg(to_jsonb(s)), ''[]''::jsonb) AS rows\r\n           FROM public.%I s',\r\n          tbl.table_name\r\n        );\r\n      END IF;\r\n\r\n      EXECUTE v_q INTO v_row_count, v_rows;\r\n\r\n      v_tables_payload := jsonb_set(v_tables_payload, ARRAY[tbl.table_name], v_rows);\r\n      v_total_rows := v_total_rows + v_row_count;\r\n      v_table_count := v_table_count + 1;\r\n    END;\r\n  END LOOP;\r\n\r\n  v_result := jsonb_build_object(\r\n    'kind', 'server_dynamic_export',\r\n    'exported_at', now(),\r\n    'schema_fingerprint', public.backup_schema_fingerprint(),\r\n    'table_count', v_table_count,\r\n    'total_rows', v_total_rows,\r\n    'capped_log_tables', v_capped,\r\n    'tables', v_tables_payload\r\n  );\r\n\r\n  RETURN v_result;\r\nEND;\r\n$$","-- ────────────────────────────────────────────────────────────────────────────\r\n-- 3. الاستعادة الكاملة داخل Transaction.\r\n--\r\n--    الترتيب:\r\n--      أ. فحص دور owner فقط (استعادة خارقة، لا تُمنح لأي دور آخر).\r\n--      ب. التحقق من البنية: الحمولة يجب أن تحمل kind + tables + fingerprint.\r\n--      ج. تعطيل المفاتيح مؤقتًا (session_replication_role = replica) حتى تُدرج\r\n--         الصفوف بأي ترتيب دون انكسار المفاتيح الخارجية، ثم إعادتها فورًا.\r\n--      د. TRUNCATE لكل جداول public (بما فيها غير المذكورة في الحمولة — حتى لا\r\n--         يبقى بيانات قديمة مزيفة)، ثم INSERT عبر jsonb_populate_recordset\r\n--         الذي يطابق الأعمدة بالاسم لا بالترتيب (يتكيف مع ترتيب الأعمدة الجديد).\r\n--      هـ. إعادة ضبط sequences إلى قيم الأعمدة المدرجة.\r\n--\r\n--    ملاحظة معلنة: الجداول ذات أعمدة IDENTITY GENERATED ALWAYS لا تقبل إدراج\r\n--    معرّفات صريحة — الكتالوج الحالي لا يستخدمها (تستخدم gen_random_uuid أو serial).\r\n-- ────────────────────────────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.backup_restore_all(\r\n  p_payload jsonb\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public, pg_temp\r\nAS $$\r\nDECLARE\r\n  v_caller uuid := auth.uid();\r\n  v_tables jsonb;\r\n  v_t text;\r\n  v_rows jsonb;\r\n  v_inserted bigint;\r\n  v_total bigint := 0;\r\n  v_skipped jsonb := '[]'::jsonb;\r\n  v_payload_fingerprint text;\r\n  v_current_fingerprint text;\r\n  v_fingerprint_mismatch boolean := false;\r\n  v_q text;\r\nBEGIN\r\n  IF v_caller IS NULL OR NOT public.has_role(v_caller, 'owner') THEN\r\n    RAISE EXCEPTION 'BACKUP_AUTH: backup restore requires owner role'\r\n      USING HINT = 'الاستعادة متاحة لمالك المتجر فقط';\r\n  END IF;\r\n\r\n  IF p_payload->>'kind' IS DISTINCT FROM 'server_dynamic_export'\r\n     OR jsonb_typeof(p_payload->'tables') IS DISTINCT FROM 'object' THEN\r\n    RAISE EXCEPTION 'BACKUP_FORMAT: payload is not a server_dynamic_export backup'\r\n      USING HINT = 'صيغة الحمولة غير صالحة — استخدم نسخة من backup_export_all';\r\n  END IF;\r\n\r\n  v_payload_fingerprint := p_payload->>'schema_fingerprint';\r\n  v_current_fingerprint := public.backup_schema_fingerprint();\r\n  IF v_payload_fingerprint IS NOT NULL\r\n     AND v_current_fingerprint IS NOT NULL\r\n     AND v_payload_fingerprint <> v_current_fingerprint THEN\r\n    v_fingerprint_mismatch := true;  -- تحذير لا إيقاف: قد تكون مهاجرة جديدة بعد النسخة\r\n    RAISE NOTICE 'BACKUP_SCHEMA_DRIFT: backup fingerprint % != current % (tables/columns changed since backup)',\r\n      v_payload_fingerprint, v_current_fingerprint;\r\n  END IF;\r\n\r\n  v_tables := p_payload->'tables';\r\n\r\n  -- (ج) تعطيل مفاتيح التحقق مؤقتًا داخل الجلسة\r\n  EXECUTE 'SET LOCAL session_replication_role = replica';\r\n\r\n  -- (د-1) تفريغ كل جداول public الأساسية — حتى غير المذكورة في الحمولة\r\n  EXECUTE format(\r\n    'TRUNCATE TABLE %s RESTART IDENTITY CASCADE',\r\n    (\r\n      SELECT string_agg(quote_ident(t.table_name), ', ' ORDER BY t.table_name)\r\n      FROM information_schema.tables t\r\n      WHERE t.table_schema = 'public' AND t.table_type = 'BASE TABLE'\r\n    )\r\n  );\r\n\r\n  -- (د-2) إدراج الصفوف، جدولًا جدولًا، بالاسم لا بالترتيب\r\n  FOR v_t, v_rows IN\r\n    SELECT key, value FROM jsonb_each(v_tables)\r\n  LOOP\r\n    -- تجاهل الجداول غير الموجودة في المخطط الحالي (حُذف جدول بعد النسخة)\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM information_schema.tables t\r\n      WHERE t.table_schema = 'public' AND t.table_name = v_t AND t.table_type = 'BASE TABLE'\r\n    ) THEN\r\n      RAISE NOTICE 'BACKUP_SKIP_TABLE: % not found in current schema', v_t;\r\n      v_skipped := v_skipped || to_jsonb(v_t);\r\n      CONTINUE;\r\n    END IF;\r\n\r\n    IF jsonb_typeof(v_rows) = 'array' AND jsonb_array_length(v_rows) > 0 THEN\r\n      v_q := format(\r\n        'INSERT INTO public.%I SELECT * FROM jsonb_populate_recordset(NULL::public.%I, $1)',\r\n        v_t, v_t\r\n      );\r\n      EXECUTE v_q USING v_rows;\r\n      GET DIAGNOSTICS v_inserted = ROW_COUNT;\r\n      v_total := v_total + v_inserted;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- (ج) إعادة المفاتيح\r\n  EXECUTE 'SET LOCAL session_replication_role = DEFAULT';\r\n\r\n  -- (هـ) إعادة ضبط sequences (serial/bigserial) لقيم الأعمدة المدرجة\r\n  DECLARE\r\n    v_col text;\r\n  BEGIN\r\n    FOR v_t, v_col IN\r\n      SELECT c.table_name, c.column_name\r\n      FROM information_schema.columns c\r\n      JOIN information_schema.sequences s\r\n        ON s.sequence_schema = 'public'\r\n      WHERE c.table_schema = 'public'\r\n        AND c.column_default LIKE 'nextval(%'\r\n    LOOP\r\n      EXECUTE format(\r\n        'SELECT setval(pg_get_serial_sequence(%L::text, %L::text),\r\n                       coalesce((SELECT max(%I) FROM public.%I), 1))',\r\n        'public.' || v_t, v_col, v_col, v_t\r\n      );\r\n    END LOOP;\r\n  END;\r\n\r\n  RETURN jsonb_build_object(\r\n    'restored_at', now(),\r\n    'inserted_rows', v_total,\r\n    'skipped_tables', v_skipped,\r\n    'schema_fingerprint_mismatch', v_fingerprint_mismatch,\r\n    'current_fingerprint', v_current_fingerprint\r\n  );\r\nEND;\r\n$$","-- ── الصلاحيات ──────────────────────────────────────────────────────────────\r\nREVOKE ALL ON FUNCTION public.backup_schema_fingerprint() FROM PUBLIC, anon","REVOKE ALL ON FUNCTION public.backup_export_all(integer) FROM PUBLIC, anon","REVOKE ALL ON FUNCTION public.backup_restore_all(jsonb) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.backup_schema_fingerprint() TO authenticated","GRANT EXECUTE ON FUNCTION public.backup_export_all(integer) TO authenticated","GRANT EXECUTE ON FUNCTION public.backup_restore_all(jsonb) TO authenticated","COMMENT ON FUNCTION public.backup_export_all(integer) IS\r\n  'Server-side dynamic full backup: reads every public base table from information_schema at call time (adapts to any migration), guarded to owner/manager.'","COMMENT ON FUNCTION public.backup_restore_all(jsonb) IS\r\n  'Server-side full restore in a single transaction: truncates all public tables, reinserts by column name, resets sequences. Owner-only.'","COMMENT ON FUNCTION public.backup_schema_fingerprint() IS\r\n  'SHA-256 fingerprint of the public schema (tables + columns + types). Differing fingerprints between backup and restore signal schema drift.'",COMMIT}	backup_engine
32	{"-- ============================================================================\r\n-- 30_treasury_cashboxes_and_payment_hierarchy.sql\r\n--\r\n-- منظومة الخزينة وطرق الدفع الهرمية والربط المحاسبي المتكامل\r\n--\r\n-- الأهداف:\r\n--   1. إنشاء جدول الصناديق والخزائن (cashboxes) مع ربط مباشر بحسابات الأصول النقدية.\r\n--   2. إنشاء جدول الحسابات البنكية والمحافظ (company_bank_accounts) للمنشأة.\r\n--   3. إنشاء جدول سجل الشيكات وأوراق القبض (cheques_register) مع دورة الصرف والارتداد.\r\n--   4. تأسيس حساب «أوراق قبض — شيكات برسم التحصيل» (1221) تحت الحساب التجميعي (1200).\r\n--   5. توسيع جداول الفواتير والتحصيلات والمصروفات بحقول التوجيه المالي الدقيق.\r\n--   6. توفير دالة التوجيه المالي (resolve_document_settlement_account).\r\n--   7. ترقية دوال الترحيل (post_sales_invoice, record_customer_payment) لترحيل النقد\r\n--      إلى الصندوق الفعلي، والمحافظ إلى حساباتها المخصصة، والشيكات إلى أوراق القبض،\r\n--      ودعم تجزئة السداد المتعددة إلى حساباتها المتفرقة.\r\n--   8. توفير دوال تحصيل الشيكات (clear_cheque) وارتدادها (bounce_cheque).\r\n-- ============================================================================\r\n\r\nBEGIN","-- ── 1. تأسيس حساب أوراق القبض (1221) في دليل الحسابات ───────────────────────\r\nINSERT INTO public.accounts (\r\n  code, name_ar, account_type, parent_id, is_system, is_postable, requires_reconciliation, notes\r\n)\r\nVALUES (\r\n  '1221',\r\n  'أوراق قبض — شيكات برسم التحصيل',\r\n  'ASSET',\r\n  (SELECT id FROM public.accounts WHERE code = '1200'),\r\n  true,\r\n  true,\r\n  true,\r\n  'شيكات وأوراق قبض مستلمة من العملاء برسم التحصيل بالبنك'\r\n)\r\nON CONFLICT (code) DO UPDATE SET\r\n  parent_id = COALESCE(EXCLUDED.parent_id, (SELECT id FROM public.accounts WHERE code = '1200')),\r\n  requires_reconciliation = true,\r\n  is_postable = true","-- ── 2. جدول الصناديق والخزائن (cashboxes) ──────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS public.cashboxes (\r\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  name_ar text NOT NULL,\r\n  name_en text,\r\n  code varchar(30) UNIQUE NOT NULL,\r\n  warehouse_id uuid REFERENCES public.warehouses(id) ON DELETE SET NULL,\r\n  account_id uuid NOT NULL REFERENCES public.accounts(id) ON DELETE RESTRICT,\r\n  is_default boolean DEFAULT false NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  notes text,\r\n  created_at timestamptz DEFAULT now() NOT NULL,\r\n  updated_at timestamptz DEFAULT now() NOT NULL\r\n)","COMMENT ON TABLE public.cashboxes IS\r\n  'صناديق وخزائن المنشأة ونقاط البيع، مع ربط كل صندوق بحسابه في الدليل المحاسبي.'","CREATE INDEX IF NOT EXISTS ix_cashboxes_active ON public.cashboxes(is_active, is_default)","CREATE INDEX IF NOT EXISTS ix_cashboxes_account ON public.cashboxes(account_id)","CREATE INDEX IF NOT EXISTS ix_cashboxes_warehouse ON public.cashboxes(warehouse_id)","-- ── 3. جدول الحسابات البنكية والمحافظ الإلكترونية للمنشأة ───────────────────\r\nCREATE TABLE IF NOT EXISTS public.company_bank_accounts (\r\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  name_ar text NOT NULL,\r\n  name_en text,\r\n  kind text DEFAULT 'BANK' NOT NULL CHECK (kind IN ('BANK', 'WALLET', 'POS_TERMINAL')),\r\n  bank_name text NOT NULL,\r\n  account_number text,\r\n  iban text,\r\n  currency text DEFAULT 'YER' NOT NULL,\r\n  account_id uuid NOT NULL REFERENCES public.accounts(id) ON DELETE RESTRICT,\r\n  is_default boolean DEFAULT false NOT NULL,\r\n  is_active boolean DEFAULT true NOT NULL,\r\n  notes text,\r\n  created_at timestamptz DEFAULT now() NOT NULL,\r\n  updated_at timestamptz DEFAULT now() NOT NULL\r\n)","COMMENT ON TABLE public.company_bank_accounts IS\r\n  'الحسابات البنكية والمحافظ الإلكترونية للمنشأة للتسوية والتحصيلات البنكية والإلكترونية.'","CREATE INDEX IF NOT EXISTS ix_company_bank_accounts_kind ON public.company_bank_accounts(kind, is_active, is_default)","CREATE INDEX IF NOT EXISTS ix_company_bank_accounts_account ON public.company_bank_accounts(account_id)","-- ── 4. جدول إدارة وسجل الشيكات (cheques_register) ───────────────────────────\r\nCREATE TABLE IF NOT EXISTS public.cheques_register (\r\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  cheque_number text NOT NULL,\r\n  bank_name text NOT NULL,\r\n  drawer_name text,\r\n  due_date date NOT NULL,\r\n  amount numeric(18,2) NOT NULL CHECK (amount > 0),\r\n  status text DEFAULT 'UNDER_COLLECTION' NOT NULL\r\n    CHECK (status IN ('UNDER_COLLECTION', 'CLEARED', 'BOUNCED', 'RETURNED')),\r\n  customer_id uuid REFERENCES public.customers(id) ON DELETE SET NULL,\r\n  invoice_id uuid REFERENCES public.sales_invoices(id) ON DELETE SET NULL,\r\n  payment_id uuid REFERENCES public.customer_payments(id) ON DELETE SET NULL,\r\n  clearing_bank_account_id uuid REFERENCES public.company_bank_accounts(id) ON DELETE SET NULL,\r\n  clearing_journal_entry_id uuid REFERENCES public.journal_entries(id) ON DELETE SET NULL,\r\n  cleared_at timestamptz,\r\n  notes text,\r\n  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,\r\n  created_at timestamptz DEFAULT now() NOT NULL,\r\n  updated_at timestamptz DEFAULT now() NOT NULL\r\n)","COMMENT ON TABLE public.cheques_register IS\r\n  'سجل الشيكات وأوراق القبض ومتابعة تواريخ الاستحقاق والتحصيل والارتداد.'","CREATE INDEX IF NOT EXISTS ix_cheques_status_date ON public.cheques_register(status, due_date)","CREATE INDEX IF NOT EXISTS ix_cheques_customer ON public.cheques_register(customer_id)","CREATE INDEX IF NOT EXISTS ix_cheques_invoice ON public.cheques_register(invoice_id)","-- ── 5. توسيع جداول المستندات بحقول التوجيه المالي الدقيق ───────────────────\r\n\r\n-- 5.1 فواتير المبيعات\r\nALTER TABLE public.sales_invoices\r\n  ADD COLUMN IF NOT EXISTS cashbox_id uuid REFERENCES public.cashboxes(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS bank_account_id uuid REFERENCES public.company_bank_accounts(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_method_id text REFERENCES public.payment_methods(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_reference text","CREATE INDEX IF NOT EXISTS ix_sales_invoices_cashbox ON public.sales_invoices(cashbox_id)","CREATE INDEX IF NOT EXISTS ix_sales_invoices_bank_acc ON public.sales_invoices(bank_account_id)","-- 5.2 سندات تحصيل العملاء\r\nALTER TABLE public.customer_payments\r\n  ADD COLUMN IF NOT EXISTS cashbox_id uuid REFERENCES public.cashboxes(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS bank_account_id uuid REFERENCES public.company_bank_accounts(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_method_id text REFERENCES public.payment_methods(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_reference text","CREATE INDEX IF NOT EXISTS ix_customer_payments_cashbox ON public.customer_payments(cashbox_id)","CREATE INDEX IF NOT EXISTS ix_customer_payments_bank_acc ON public.customer_payments(bank_account_id)","-- 5.3 فواتير المشتريات\r\nALTER TABLE public.purchase_invoices\r\n  ADD COLUMN IF NOT EXISTS cashbox_id uuid REFERENCES public.cashboxes(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS bank_account_id uuid REFERENCES public.company_bank_accounts(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_method_id text REFERENCES public.payment_methods(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_reference text","-- 5.4 دفعات المصروفات\r\nALTER TABLE public.expense_payments\r\n  ADD COLUMN IF NOT EXISTS cashbox_id uuid REFERENCES public.cashboxes(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS bank_account_id uuid REFERENCES public.company_bank_accounts(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_method_id text REFERENCES public.payment_methods(id) ON DELETE SET NULL","-- 5.5 تجزئة الدفعات\r\nALTER TABLE public.customer_payment_splits\r\n  ADD COLUMN IF NOT EXISTS cashbox_id uuid REFERENCES public.cashboxes(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS bank_account_id uuid REFERENCES public.company_bank_accounts(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_method_id text REFERENCES public.payment_methods(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS reference_no text","-- 5.6 مرتجعات المبيعات\r\nALTER TABLE public.sales_returns\r\n  ADD COLUMN IF NOT EXISTS cashbox_id uuid REFERENCES public.cashboxes(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS bank_account_id uuid REFERENCES public.company_bank_accounts(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_method_id text REFERENCES public.payment_methods(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_reference text","-- 5.7 مرتجعات المشتريات\r\nALTER TABLE public.purchase_returns\r\n  ADD COLUMN IF NOT EXISTS cashbox_id uuid REFERENCES public.cashboxes(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS bank_account_id uuid REFERENCES public.company_bank_accounts(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_method_id text REFERENCES public.payment_methods(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS payment_reference text","-- ── 6. بذور بيانات أساسية للصناديق والبنوك والمحافظ ────────────────────────\r\nDO $$\r\nDECLARE\r\n  v_cash_acct uuid;\r\n  v_kuraimi_acct uuid;\r\n  v_yemen_bank_acct uuid;\r\n  v_jawali_acct uuid;\r\n  v_jaib_acct uuid;\r\n  v_floosak_acct uuid;\r\n  v_one_cash_acct uuid;\r\nBEGIN\r\n  SELECT id INTO v_cash_acct FROM public.accounts WHERE code = '1101';\r\n  SELECT id INTO v_kuraimi_acct FROM public.accounts WHERE code = '1111';\r\n  SELECT id INTO v_yemen_bank_acct FROM public.accounts WHERE code = '1121';\r\n  SELECT id INTO v_jawali_acct FROM public.accounts WHERE code = '1131';\r\n  SELECT id INTO v_jaib_acct FROM public.accounts WHERE code = '1132';\r\n  SELECT id INTO v_floosak_acct FROM public.accounts WHERE code = '1133';\r\n  SELECT id INTO v_one_cash_acct FROM public.accounts WHERE code = '1134';\r\n\r\n  -- الصندوق الرئيسي الافتراضي\r\n  IF v_cash_acct IS NOT NULL THEN\r\n    INSERT INTO public.cashboxes (name_ar, name_en, code, account_id, is_default, is_active)\r\n    VALUES ('الصندوق الرئيسي', 'Main Cashbox', 'CASH-MAIN', v_cash_acct, true, true)\r\n    ON CONFLICT (code) DO UPDATE SET\r\n      account_id = v_cash_acct,\r\n      is_default = true;\r\n  END IF;\r\n\r\n  -- الحسابات البنكية للمنشأة\r\n  IF v_kuraimi_acct IS NOT NULL THEN\r\n    INSERT INTO public.company_bank_accounts (name_ar, kind, bank_name, account_id, is_default, is_active)\r\n    VALUES ('بنك الكريمي — الحساب الجاري', 'BANK', 'بنك الكريمي للتمويل الأصغر', v_kuraimi_acct, true, true)\r\n    ON CONFLICT DO NOTHING;\r\n  END IF;\r\n\r\n  IF v_yemen_bank_acct IS NOT NULL THEN\r\n    INSERT INTO public.company_bank_accounts (name_ar, kind, bank_name, account_id, is_default, is_active)\r\n    VALUES ('بنك اليمن الدولي', 'BANK', 'بنك اليمن الدولي', v_yemen_bank_acct, false, true)\r\n    ON CONFLICT DO NOTHING;\r\n  END IF;\r\n\r\n  -- المحافظ الإلكترونية للمنشأة\r\n  IF v_jaib_acct IS NOT NULL THEN\r\n    INSERT INTO public.company_bank_accounts (name_ar, kind, bank_name, account_id, is_default, is_active)\r\n    VALUES ('محفظة جيب', 'WALLET', 'شركة الأهدل المالية', v_jaib_acct, false, true)\r\n    ON CONFLICT DO NOTHING;\r\n  END IF;\r\n\r\n  IF v_one_cash_acct IS NOT NULL THEN\r\n    INSERT INTO public.company_bank_accounts (name_ar, kind, bank_name, account_id, is_default, is_active)\r\n    VALUES ('محفظة ون كاش', 'WALLET', 'ون كاش', v_one_cash_acct, false, true)\r\n    ON CONFLICT DO NOTHING;\r\n  END IF;\r\n\r\n  IF v_jawali_acct IS NOT NULL THEN\r\n    INSERT INTO public.company_bank_accounts (name_ar, kind, bank_name, account_id, is_default, is_active)\r\n    VALUES ('محفظة جوالي', 'WALLET', 'يمن موبايل', v_jawali_acct, false, true)\r\n    ON CONFLICT DO NOTHING;\r\n  END IF;\r\n\r\n  IF v_floosak_acct IS NOT NULL THEN\r\n    INSERT INTO public.company_bank_accounts (name_ar, kind, bank_name, account_id, is_default, is_active)\r\n    VALUES ('محفظة فلوسك', 'WALLET', 'بنك اليمن والكويت', v_floosak_acct, false, true)\r\n    ON CONFLICT DO NOTHING;\r\n  END IF;\r\nEND $$","-- ── 7. دالة حل الحساب المحاسبي للتسوية والترحيل ─────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.resolve_document_settlement_account(\r\n  p_payment_method text,\r\n  p_cashbox_id uuid DEFAULT NULL,\r\n  p_bank_account_id uuid DEFAULT NULL,\r\n  p_payment_method_id text DEFAULT NULL\r\n)\r\nRETURNS text\r\nLANGUAGE plpgsql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_code text;\r\n  v_norm_method text := lower(btrim(coalesce(p_payment_method, '')));\r\n  v_norm_catalog_id text := lower(btrim(coalesce(p_payment_method_id, '')));\r\nBEGIN\r\n  -- 0. إذا كان الدفع آجل، فلا يوجد حساب تسوية نقدية (NULL)\r\n  IF v_norm_method = 'credit' OR v_norm_catalog_id = 'credit' THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  -- 1. الصناديق: إذا تم تمرير صندوق محدد ومفعل\r\n  IF p_cashbox_id IS NOT NULL THEN\r\n    SELECT a.code INTO v_code\r\n    FROM public.cashboxes c\r\n    JOIN public.accounts a ON a.id = c.account_id\r\n    WHERE c.id = p_cashbox_id AND c.is_active = true;\r\n\r\n    IF v_code IS NOT NULL THEN\r\n      RETURN v_code;\r\n    END IF;\r\n  END IF;\r\n\r\n  -- 2. البنوك والمحافظ: إذا تم تمرير حساب بنكي/محفظة محددة ومفعلة\r\n  IF p_bank_account_id IS NOT NULL THEN\r\n    SELECT a.code INTO v_code\r\n    FROM public.company_bank_accounts b\r\n    JOIN public.accounts a ON a.id = b.account_id\r\n    WHERE b.id = p_bank_account_id AND b.is_active = true;\r\n\r\n    IF v_code IS NOT NULL THEN\r\n      RETURN v_code;\r\n    END IF;\r\n  END IF;\r\n\r\n  -- 3. الشيكات: تُسوّى محاسبياً على حساب أوراق القبض برسم التحصيل (1221)\r\n  IF v_norm_method = 'cheque' OR v_norm_catalog_id = 'cheque' THEN\r\n    SELECT a.code INTO v_code FROM public.accounts a WHERE a.code = '1221';\r\n    IF v_code IS NOT NULL THEN\r\n      RETURN v_code;\r\n    END IF;\r\n  END IF;\r\n\r\n  -- 4. فحص إعدادات المنشأة لطريقة الدفع (payment_method_settings.default_account_id)\r\n  IF v_norm_catalog_id <> '' THEN\r\n    SELECT a.code INTO v_code\r\n    FROM public.payment_method_settings s\r\n    JOIN public.accounts a ON a.id = s.default_account_id\r\n    WHERE s.payment_method_id = v_norm_catalog_id;\r\n\r\n    IF v_code IS NOT NULL THEN\r\n      RETURN v_code;\r\n    END IF;\r\n\r\n    -- فحص كود الحساب الافتراضي بالكتالوج (default_account_code)\r\n    SELECT m.default_account_code INTO v_code\r\n    FROM public.payment_methods m\r\n    WHERE m.id = v_norm_catalog_id;\r\n\r\n    IF v_code IS NOT NULL THEN\r\n      RETURN v_code;\r\n    END IF;\r\n  END IF;\r\n\r\n  -- 5. البديل المتوافق مع كتالوج طرق الدفع التاريخي\r\n  RETURN public.ledger_account_code_for_payment_method(coalesce(nullif(v_norm_method, ''), v_norm_catalog_id));\r\nEND;\r\n$$","COMMENT ON FUNCTION public.resolve_document_settlement_account(text, uuid, uuid, text) IS\r\n  'يحل كود الحساب المحاسبي بدقة بحسب الصندوق المختار، أو البنك/المحفظة، أو أوراق القبض للشيكات، أو بديل الكتالوج.'","-- ── 8. تحديث دالة ترحيل فواتير المبيعات (post_sales_invoice) ────────────────\r\nCREATE OR REPLACE FUNCTION public.post_sales_invoice(p_invoice_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_inv     record;\r\n  v_existing uuid;\r\n  v_entry   uuid;\r\n  v_lines   jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  v_collectable numeric := 0;\r\n  r         record;\r\n  s         record;\r\n  v_split_count integer := 0;\r\n  v_split_acct text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')\r\n          OR public.has_role(v_user,'accountant')\r\n          OR public.has_role(v_user,'cashier')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager, accountant or the cashier''s own sale may post a sales invoice';\r\n  END IF;\r\n\r\n  SELECT * INTO v_inv FROM public.sales_invoices WHERE id = p_invoice_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Invoice not found';\r\n  END IF;\r\n\r\n  IF v_inv.status IN ('draft','cancelled') THEN\r\n    RAISE EXCEPTION 'Invoice % is % - only confirmed, paid or partial invoices post',\r\n      v_inv.invoice_number, v_inv.status;\r\n  END IF;\r\n\r\n  IF v_inv.paid < 0 THEN\r\n    RAISE EXCEPTION 'Invoice % carries a negative payment (%). A refund is a credit note, not a negative payment.',\r\n      v_inv.invoice_number, v_inv.paid;\r\n  END IF;\r\n  IF v_inv.paid > v_inv.total THEN\r\n    RAISE EXCEPTION 'Invoice % was paid % against a total of %. Fix the invoice before posting - a payment cannot exceed the invoice.',\r\n      v_inv.invoice_number, v_inv.paid, v_inv.total;\r\n  END IF;\r\n  IF v_inv.tax < 0 THEN\r\n    RAISE EXCEPTION 'Invoice % carries a negative tax amount', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  SELECT id INTO v_existing\r\n    FROM public.journal_entries\r\n   WHERE source_type = 'sales_invoice' AND source_id = p_invoice_id\r\n     AND status <> 'REVERSED';\r\n  IF v_existing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'Invoice % has already been posted to the ledger', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  v_collectable := greatest(v_inv.total - v_inv.paid, 0);\r\n\r\n  -- ── الإيراد الصافي من ضريبة البند ──────────────────────────────────────────\r\n  FOR r IN\r\n    SELECT p.item_class,\r\n           sum(it.total - coalesce(it.tax, 0)) AS net_amount\r\n      FROM public.sales_invoice_items it\r\n      JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n     GROUP BY p.item_class\r\n    HAVING sum(it.total - coalesce(it.tax, 0)) <> 0\r\n  LOOP\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE r.item_class\r\n                        WHEN 'BY_PRODUCT' THEN '4211'\r\n                        WHEN 'SERVICE'    THEN '4311'\r\n                        ELSE '4111' END,\r\n      'credit', round(r.net_amount, 2),\r\n      'memo', 'إيراد ' || r.item_class);\r\n  END LOOP;\r\n\r\n  IF jsonb_array_length(v_lines) = 0 THEN\r\n    RAISE EXCEPTION 'Invoice % has no revenue lines', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- ── أسطر التحصيل النقدية / البنكية / المحافظ / أوراق القبض ────────────────\r\n  IF v_inv.paid > 0 THEN\r\n    -- فحص إذا كان دفع مجزأ وله سجلات تجزئة\r\n    IF v_inv.payment_method = 'split' THEN\r\n      SELECT count(*) INTO v_split_count\r\n      FROM public.customer_payment_splits\r\n      WHERE invoice_id = p_invoice_id;\r\n    END IF;\r\n\r\n    IF v_inv.payment_method = 'split' AND v_split_count > 0 THEN\r\n      -- ترحيل كل جزء إلى حسابه المالي المستقل\r\n      FOR s IN\r\n        SELECT method, amount, cashbox_id, bank_account_id, payment_method_id\r\n        FROM public.customer_payment_splits\r\n        WHERE invoice_id = p_invoice_id AND amount > 0\r\n      LOOP\r\n        v_split_acct := public.resolve_document_settlement_account(\r\n          s.method::text, s.cashbox_id, s.bank_account_id, s.payment_method_id\r\n        );\r\n        IF v_split_acct IS NOT NULL THEN\r\n          v_lines := v_lines || jsonb_build_object(\r\n            'account_code', v_split_acct,\r\n            'debit', round(s.amount, 2),\r\n            'memo', 'تحصيل دفعة مجزأة (' || s.method::text || ')'\r\n          );\r\n        END IF;\r\n      END LOOP;\r\n    ELSE\r\n      -- سداد بطريقة واحدة محددة\r\n      v_cash_acct := public.resolve_document_settlement_account(\r\n        v_inv.payment_method::text,\r\n        v_inv.cashbox_id,\r\n        v_inv.bank_account_id,\r\n        v_inv.payment_method_id\r\n      );\r\n\r\n      IF v_cash_acct IS NOT NULL THEN\r\n        v_lines := v_lines || jsonb_build_object(\r\n          'account_code', v_cash_acct,\r\n          'debit', round(v_inv.paid, 2),\r\n          'memo', CASE\r\n                    WHEN v_cash_acct = '1221' THEN 'أوراق قبض (شيك تحت التحصيل)'\r\n                    WHEN v_cash_acct LIKE '1101%' THEN 'تحصيل نقدي بالصندوق'\r\n                    WHEN v_cash_acct LIKE '113%' THEN 'تحصيل محفظة إلكترونية'\r\n                    ELSE 'تحصيل بنكي' END\r\n        );\r\n      END IF;\r\n    END IF;\r\n  END IF;\r\n\r\n  -- ── الذمم الآجلة المتبقية على العميل ──────────────────────────────────────\r\n  IF v_collectable > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1211', 'debit', round(v_collectable, 2),\r\n      'memo', 'ذمم العميل ' || coalesce(v_inv.invoice_number, ''));\r\n  END IF;\r\n\r\n  -- ── ضريبة القيمة المضافة ──────────────────────────────────────────────────\r\n  IF v_inv.tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2311', 'credit', round(v_inv.tax, 2),\r\n      'memo', 'ضريبة القيمة المضافة المستحقة');\r\n  END IF;\r\n\r\n  -- ── تكلفة البضاعة المباعة ومخزونها ───────────────────────────────────────\r\n  FOR r IN\r\n    SELECT p.item_class,\r\n           sum(it.quantity * public.resolve_unit_cost(p.id, v_inv.warehouse_id)) AS cost\r\n      FROM public.sales_invoice_items it\r\n      JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n       AND it.stock_effect = 'STOCK_ISSUE'\r\n     GROUP BY p.item_class\r\n  LOOP\r\n    IF r.cost IS NULL OR r.cost = 0 THEN\r\n      CONTINUE;\r\n    END IF;\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE r.item_class\r\n                        WHEN 'RAW_MATERIAL' THEN '1311'\r\n                        WHEN 'BY_PRODUCT'   THEN '1314'\r\n                        ELSE '1313' END,\r\n      'credit', round(r.cost, 2),\r\n      'memo', 'تكلفة ' || r.item_class);\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '5111', 'debit', round(r.cost, 2),\r\n      'memo', 'تكلفة البضاعة المباعة');\r\n  END LOOP;\r\n\r\n  v_entry := public.create_journal_entry(\r\n    'فاتورة مبيعات ' || v_inv.invoice_number,\r\n    v_inv.created_at::date,\r\n    'sales_invoice', p_invoice_id, true, v_lines);\r\n\r\n  RETURN v_entry;\r\nEND;\r\n$$","-- ── 9. تحديث دالة تسجيل سندات تحصيل العملاء ──────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.record_customer_payment(\r\n  _customer_id uuid,\r\n  _invoice_id uuid,\r\n  _amount numeric,\r\n  _method text,\r\n  _payment_date date,\r\n  _note text,\r\n  _cashbox_id uuid DEFAULT NULL,\r\n  _bank_account_id uuid DEFAULT NULL,\r\n  _payment_method_id text DEFAULT NULL,\r\n  _cheque_number text DEFAULT NULL,\r\n  _cheque_bank text DEFAULT NULL,\r\n  _cheque_due_date date DEFAULT NULL,\r\n  _cheque_drawer text DEFAULT NULL\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_id uuid;\r\n  v_user uuid := auth.uid();\r\n  v_invoice record;\r\n  v_customer_balance numeric;\r\n  v_remaining numeric := round(coalesce(_amount, 0), 2);\r\n  v_stored_method text;\r\n  v_cash_acct text;\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_journal uuid;\r\n  v_final_method_id text;\r\n  v_ref_no text;\r\n  v_inv_cur record;\r\n  v_allocation numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'accountant')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to record customer payments';\r\n  END IF;\r\n\r\n  IF _customer_id IS NULL OR v_remaining <= 0 THEN\r\n    RAISE EXCEPTION 'A customer and a positive amount are required';\r\n  END IF;\r\n\r\n  v_final_method_id := coalesce(_payment_method_id, _method);\r\n  v_stored_method := public.resolve_writable_payment_method(\r\n    v_final_method_id, 'customer_collection', true\r\n  );\r\n\r\n  SELECT balance INTO v_customer_balance\r\n  FROM public.customers\r\n  WHERE id = _customer_id AND is_active = true\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Customer is unavailable';\r\n  END IF;\r\n\r\n  -- حل الحساب المحاسبي بدقة\r\n  v_cash_acct := public.resolve_document_settlement_account(\r\n    v_stored_method, _cashbox_id, _bank_account_id, v_final_method_id\r\n  );\r\n\r\n  -- 1. تخصيص لفاتورة محددة\r\n  IF _invoice_id IS NOT NULL THEN\r\n    SELECT id, total, paid, customer_id\r\n      INTO v_invoice\r\n    FROM public.sales_invoices\r\n    WHERE id = _invoice_id\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Invoice not found';\r\n    END IF;\r\n\r\n    IF v_invoice.customer_id IS DISTINCT FROM _customer_id THEN\r\n      RAISE EXCEPTION 'Invoice does not belong to this customer';\r\n    END IF;\r\n\r\n    IF v_invoice.total - v_invoice.paid <= 0 THEN\r\n      RAISE EXCEPTION 'Invoice has no outstanding balance';\r\n    END IF;\r\n\r\n    IF v_remaining > (v_invoice.total - v_invoice.paid + 0.01) THEN\r\n      RAISE EXCEPTION 'Payment exceeds the invoice outstanding balance';\r\n    END IF;\r\n\r\n    INSERT INTO public.customer_payments (\r\n      customer_id, invoice_id, amount, payment_method, payment_date, note, created_by,\r\n      cashbox_id, bank_account_id, payment_method_id, payment_reference\r\n    )\r\n    VALUES (\r\n      _customer_id, _invoice_id, v_remaining, v_stored_method::public.payment_method,\r\n      coalesce(_payment_date, current_date), nullif(trim(_note), ''), v_user,\r\n      _cashbox_id, _bank_account_id, v_final_method_id, _cheque_number\r\n    )\r\n    RETURNING id INTO v_id;\r\n\r\n    -- إذا كان شيكاً: تسجيله في جدول الشيكات\r\n    IF (v_stored_method = 'cheque' OR v_final_method_id = 'cheque') AND _cheque_number IS NOT NULL THEN\r\n      INSERT INTO public.cheques_register (\r\n        cheque_number, bank_name, drawer_name, due_date, amount, status,\r\n        customer_id, invoice_id, payment_id, notes, created_by\r\n      )\r\n      VALUES (\r\n        _cheque_number, coalesce(_cheque_bank, 'شيك مصرفي'), _cheque_drawer,\r\n        coalesce(_cheque_due_date, CURRENT_DATE), v_remaining, 'UNDER_COLLECTION',\r\n        _customer_id, _invoice_id, v_id, _note, v_user\r\n      );\r\n    END IF;\r\n\r\n    INSERT INTO public.customer_ledger(customer_id, entry_type, credit, reference_id, reference_type, occurred_at, created_by, source_key, note)\r\n    VALUES (_customer_id, 'payment', v_remaining, v_id, 'customer_payment', coalesce(_payment_date, current_date)::timestamptz, v_user, 'payment:' || v_id, coalesce(nullif(trim(_note), ''), 'دفعة عميل'))\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n\r\n    UPDATE public.sales_invoices\r\n    SET paid = paid + v_remaining,\r\n        status = 'confirmed'::public.invoice_status,\r\n        payment_status = public.derive_payment_status(paid + v_remaining, total),\r\n        updated_at = now()\r\n    WHERE id = _invoice_id;\r\n\r\n    -- قيد التحصيل اليومي\r\n    IF v_cash_acct IS NOT NULL THEN\r\n      v_lines := v_lines\r\n        || jsonb_build_object('account_code', v_cash_acct, 'debit', v_remaining,\r\n                              'memo', CASE WHEN v_cash_acct = '1221' THEN 'أوراق قبض (شيك برسم التحصيل)' ELSE 'تحصيل من عميل' END)\r\n        || jsonb_build_object('account_code', '1211', 'credit', v_remaining,\r\n                              'memo', 'تحصيل ذمة عميل');\r\n      v_journal := public.create_journal_entry(\r\n        'تحصيل من عميل — ' || coalesce(nullif(trim(_note), ''), ''),\r\n        COALESCE(_payment_date, CURRENT_DATE),\r\n        'customer_payment', v_id, true, v_lines);\r\n    END IF;\r\n\r\n  ELSE\r\n    -- 2. توزيع تلقائي على الفواتير المفتوحة الأقدم أولاً\r\n    INSERT INTO public.customer_payments (\r\n      customer_id, invoice_id, amount, payment_method, payment_date, note, created_by,\r\n      cashbox_id, bank_account_id, payment_method_id, payment_reference\r\n    )\r\n    VALUES (\r\n      _customer_id, NULL, v_remaining, v_stored_method::public.payment_method,\r\n      coalesce(_payment_date, current_date), nullif(trim(_note), ''), v_user,\r\n      _cashbox_id, _bank_account_id, v_final_method_id, _cheque_number\r\n    )\r\n    RETURNING id INTO v_id;\r\n\r\n    IF (v_stored_method = 'cheque' OR v_final_method_id = 'cheque') AND _cheque_number IS NOT NULL THEN\r\n      INSERT INTO public.cheques_register (\r\n        cheque_number, bank_name, drawer_name, due_date, amount, status,\r\n        customer_id, invoice_id, payment_id, notes, created_by\r\n      )\r\n      VALUES (\r\n        _cheque_number, coalesce(_cheque_bank, 'شيك مصرفي'), _cheque_drawer,\r\n        coalesce(_cheque_due_date, CURRENT_DATE), v_remaining, 'UNDER_COLLECTION',\r\n        _customer_id, NULL, v_id, _note, v_user\r\n      );\r\n    END IF;\r\n\r\n    FOR v_inv_cur IN\r\n      SELECT id, total, paid\r\n      FROM public.sales_invoices\r\n      WHERE customer_id = _customer_id\r\n        AND total > paid\r\n        AND status NOT IN ('cancelled'::public.invoice_status, 'returned'::public.invoice_status)\r\n      ORDER BY created_at ASC\r\n    LOOP\r\n      EXIT WHEN v_remaining <= 0;\r\n      v_allocation := least(v_remaining, v_inv_cur.total - v_inv_cur.paid);\r\n\r\n      UPDATE public.sales_invoices\r\n      SET paid = paid + v_allocation,\r\n          status = 'confirmed'::public.invoice_status,\r\n          payment_status = public.derive_payment_status(paid + v_allocation, total),\r\n          updated_at = now()\r\n      WHERE id = v_inv_cur.id;\r\n\r\n      v_remaining := v_remaining - v_allocation;\r\n    END LOOP;\r\n\r\n    INSERT INTO public.customer_ledger(customer_id, entry_type, credit, reference_id, reference_type, occurred_at, created_by, source_key, note)\r\n    VALUES (_customer_id, 'payment', _amount, v_id, 'customer_payment', coalesce(_payment_date, current_date)::timestamptz, v_user, 'payment:' || v_id, coalesce(nullif(trim(_note), ''), 'دفعة عميل بتوزيع تلقائي'))\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n\r\n    IF v_cash_acct IS NOT NULL THEN\r\n      v_lines := v_lines\r\n        || jsonb_build_object('account_code', v_cash_acct, 'debit', _amount,\r\n                              'memo', CASE WHEN v_cash_acct = '1221' THEN 'أوراق قبض (شيك برسم التحصيل)' ELSE 'تحصيل من عميل' END)\r\n        || jsonb_build_object('account_code', '1211', 'credit', _amount,\r\n                              'memo', 'تحصيل ذمة عميل');\r\n      v_journal := public.create_journal_entry(\r\n        'تحصيل من عميل — ' || coalesce(nullif(trim(_note), ''), ''),\r\n        COALESCE(_payment_date, CURRENT_DATE),\r\n        'customer_payment', v_id, true, v_lines);\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN v_id;\r\nEND;\r\n$$","-- الحفاظ على التوقيع القديم بستة وسائط للتوافق العكسي\r\nCREATE OR REPLACE FUNCTION public.record_customer_payment(\r\n  _customer_id uuid,\r\n  _invoice_id uuid,\r\n  _amount numeric,\r\n  _method text,\r\n  _payment_date date,\r\n  _note text\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nBEGIN\r\n  RETURN public.record_customer_payment(\r\n    _customer_id, _invoice_id, _amount, _method, _payment_date, _note,\r\n    NULL, NULL, NULL, NULL, NULL, NULL, NULL\r\n  );\r\nEND;\r\n$$","-- ── 10. دالتا تحصيل الشيك وصرفه بالبنك أو ارتداده ───────────────────────────\r\n\r\n-- 10.1 تحصيل الشيك وإيداعه بالبنك\r\nCREATE OR REPLACE FUNCTION public.clear_cheque(\r\n  p_cheque_id uuid,\r\n  p_clearing_bank_account_id uuid,\r\n  p_cleared_date date DEFAULT CURRENT_DATE,\r\n  p_notes text DEFAULT NULL\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_cheque record;\r\n  v_bank_code text;\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_journal uuid;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'accountant')\r\n  ) THEN\r\n    RAISE EXCEPTION 'Only accountant, manager or owner may clear cheques';\r\n  END IF;\r\n\r\n  SELECT * INTO v_cheque\r\n  FROM public.cheques_register\r\n  WHERE id = p_cheque_id\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Cheque not found';\r\n  END IF;\r\n\r\n  IF v_cheque.status <> 'UNDER_COLLECTION' THEN\r\n    RAISE EXCEPTION 'Cheque % is already %', v_cheque.cheque_number, v_cheque.status;\r\n  END IF;\r\n\r\n  -- كود الحساب البنكي المودع فيه\r\n  SELECT a.code INTO v_bank_code\r\n  FROM public.company_bank_accounts b\r\n  JOIN public.accounts a ON a.id = b.account_id\r\n  WHERE b.id = p_clearing_bank_account_id;\r\n\r\n  IF v_bank_code IS NULL THEN\r\n    RAISE EXCEPTION 'Selected clearing bank account has no valid ledger account';\r\n  END IF;\r\n\r\n  -- قيد التحصيل: من حـ/ البنك إلى حـ/ أوراق قبض\r\n  v_lines := v_lines\r\n    || jsonb_build_object(\r\n      'account_code', v_bank_code,\r\n      'debit', v_cheque.amount,\r\n      'memo', 'تحصيل وإيداع شيك رقم ' || v_cheque.cheque_number\r\n    )\r\n    || jsonb_build_object(\r\n      'account_code', '1221',\r\n      'credit', v_cheque.amount,\r\n      'memo', 'إقفال أوراق قبض — شيك رقم ' || v_cheque.cheque_number\r\n    );\r\n\r\n  v_journal := public.create_journal_entry(\r\n    'تحصيل شيك مصرفي رقم ' || v_cheque.cheque_number || ' — ' || coalesce(p_notes, ''),\r\n    coalesce(p_cleared_date, CURRENT_DATE),\r\n    'cheque_clearing',\r\n    v_cheque.id,\r\n    true,\r\n    v_lines\r\n  );\r\n\r\n  UPDATE public.cheques_register\r\n  SET status = 'CLEARED',\r\n      clearing_bank_account_id = p_clearing_bank_account_id,\r\n      clearing_journal_entry_id = v_journal,\r\n      cleared_at = coalesce(p_cleared_date, CURRENT_DATE)::timestamptz,\r\n      notes = coalesce(notes || ' | ', '') || coalesce(p_notes, 'تم التحصيل بالبنك'),\r\n      updated_at = now()\r\n  WHERE id = p_cheque_id;\r\n\r\n  RETURN jsonb_build_object(\r\n    'cheque_id', p_cheque_id,\r\n    'cheque_number', v_cheque.cheque_number,\r\n    'status', 'CLEARED',\r\n    'journal_id', v_journal\r\n  );\r\nEND;\r\n$$","-- 10.2 إثبات ارتداد الشيك\r\nCREATE OR REPLACE FUNCTION public.bounce_cheque(\r\n  p_cheque_id uuid,\r\n  p_reason text DEFAULT 'عدم كفاية الرصيد'\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_cheque record;\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_journal uuid;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'accountant')\r\n  ) THEN\r\n    RAISE EXCEPTION 'Only accountant, manager or owner may mark cheques as bounced';\r\n  END IF;\r\n\r\n  SELECT * INTO v_cheque\r\n  FROM public.cheques_register\r\n  WHERE id = p_cheque_id\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Cheque not found';\r\n  END IF;\r\n\r\n  IF v_cheque.status <> 'UNDER_COLLECTION' THEN\r\n    RAISE EXCEPTION 'Cannot bounce cheque in status %', v_cheque.status;\r\n  END IF;\r\n\r\n  -- قيد الارتداد: إعادة المديونية للعميل وإلغاء ورقة القبض\r\n  -- Dr 1211 (ذمم العملاء) / Cr 1221 (أوراق قبض)\r\n  IF v_cheque.customer_id IS NOT NULL THEN\r\n    v_lines := v_lines\r\n      || jsonb_build_object(\r\n        'account_code', '1211',\r\n        'debit', v_cheque.amount,\r\n        'memo', 'ارتداد شيك رقم ' || v_cheque.cheque_number || ' — ' || coalesce(p_reason, '')\r\n      )\r\n      || jsonb_build_object(\r\n        'account_code', '1221',\r\n        'credit', v_cheque.amount,\r\n        'memo', 'إلغاء ورقة قبض لشيك مرتد رقم ' || v_cheque.cheque_number\r\n      );\r\n\r\n    v_journal := public.create_journal_entry(\r\n      'ارتداد شيك رقم ' || v_cheque.cheque_number || ' — ' || coalesce(p_reason, ''),\r\n      CURRENT_DATE,\r\n      'cheque_bounce',\r\n      v_cheque.id,\r\n      true,\r\n      v_lines\r\n    );\r\n\r\n    -- تسجيل حركة مدينة في كشف حساب العميل\r\n    INSERT INTO public.customer_ledger(\r\n      customer_id, entry_type, debit, reference_id, reference_type, occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      v_cheque.customer_id, 'adjustment', v_cheque.amount, v_cheque.id, 'cheque_bounce',\r\n      now(), v_user, 'cheque_bounce:' || v_cheque.id, 'ارتداد شيك رقم ' || v_cheque.cheque_number\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  UPDATE public.cheques_register\r\n  SET status = 'BOUNCED',\r\n      notes = coalesce(notes || ' | ', '') || 'مرتد: ' || coalesce(p_reason, ''),\r\n      updated_at = now()\r\n  WHERE id = p_cheque_id;\r\n\r\n  RETURN jsonb_build_object(\r\n    'cheque_id', p_cheque_id,\r\n    'cheque_number', v_cheque.cheque_number,\r\n    'status', 'BOUNCED',\r\n    'journal_id', v_journal\r\n  );\r\nEND;\r\n$$","-- ── 11. المشتريات وسندات صرف الموردين (Purchases & Supplier Payments) ───────────\r\n\r\n-- 11.1 ربط سندات صرف الموردين بالصناديق والحسابات البنكية\r\nALTER TABLE public.supplier_payments\r\n  ADD COLUMN IF NOT EXISTS cashbox_id uuid REFERENCES public.cashboxes(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS bank_account_id uuid REFERENCES public.company_bank_accounts(id) ON DELETE SET NULL","CREATE INDEX IF NOT EXISTS ix_supplier_payments_cashbox ON public.supplier_payments(cashbox_id)","CREATE INDEX IF NOT EXISTS ix_supplier_payments_bank_acc ON public.supplier_payments(bank_account_id)","-- 11.2 تحديث دالة ترحيل فواتير المشتريات (post_purchase_invoice)\r\nCREATE OR REPLACE FUNCTION public.post_purchase_invoice(p_invoice_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_inv     record;\r\n  v_existing uuid;\r\n  v_entry   uuid;\r\n  v_lines   jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  v_owed     numeric := 0;\r\n  r         record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')\r\n          OR public.has_role(v_user,'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may post a purchase invoice';\r\n  END IF;\r\n\r\n  SELECT * INTO v_inv FROM public.purchase_invoices WHERE id = p_invoice_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Purchase invoice not found';\r\n  END IF;\r\n\r\n  IF v_inv.status IN ('draft','cancelled') THEN\r\n    RAISE EXCEPTION 'Purchase % is % - only confirmed, paid or partial invoices post',\r\n      v_inv.invoice_number, v_inv.status;\r\n  END IF;\r\n\r\n  IF v_inv.paid < 0 THEN\r\n    RAISE EXCEPTION 'Purchase % carries a negative payment (%). A supplier return is a return document, not a negative payment.',\r\n      v_inv.invoice_number, v_inv.paid;\r\n  END IF;\r\n  IF v_inv.paid > v_inv.total THEN\r\n    RAISE EXCEPTION 'Purchase % was paid % against a total of %. Fix the invoice before posting - a payment cannot exceed the invoice.',\r\n      v_inv.invoice_number, v_inv.paid, v_inv.total;\r\n  END IF;\r\n\r\n  SELECT id INTO v_existing\r\n    FROM public.journal_entries\r\n   WHERE source_type = 'purchase_invoice' AND source_id = p_invoice_id\r\n     AND status <> 'REVERSED';\r\n  IF v_existing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'Purchase % has already been posted to the ledger', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- ── الحساب الدائن من الصندوق أو البنك أو الكتالوج بدقة ───────────────────\r\n  v_cash_acct := public.resolve_document_settlement_account(\r\n    v_inv.payment_method::text,\r\n    v_inv.cashbox_id,\r\n    v_inv.bank_account_id,\r\n    v_inv.payment_method_id\r\n  );\r\n\r\n  v_owed := greatest(v_inv.total - v_inv.paid, 0);\r\n\r\n  -- ── البضاعة المستلمة والمصروفات ──\r\n  FOR r IN\r\n    SELECT p.item_class,\r\n           coalesce(it.stock_effect, 'NONE') AS effect,\r\n           sum(it.total)                     AS amount,\r\n           sum(it.tax)                       AS line_tax\r\n      FROM public.purchase_invoice_items it\r\n      JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n     GROUP BY p.item_class, coalesce(it.stock_effect, 'NONE')\r\n    HAVING sum(it.total) <> 0 OR sum(it.tax) <> 0\r\n  LOOP\r\n    IF r.amount <> 0 THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', CASE\r\n          WHEN r.effect <> 'STOCK_RECEIPT' THEN '5911'\r\n          ELSE CASE r.item_class\r\n                 WHEN 'RAW_MATERIAL' THEN '1311'\r\n                 WHEN 'BY_PRODUCT'   THEN '1314'\r\n                 WHEN 'FINISHED_GOOD' THEN '1313'\r\n                 ELSE '1315' END END,\r\n        'debit', round(r.amount, 2),\r\n        'memo', CASE WHEN r.effect <> 'STOCK_RECEIPT'\r\n                     THEN 'مصروف مشتريات ' || r.item_class\r\n                     ELSE 'شراء ' || r.item_class END);\r\n    END IF;\r\n\r\n    IF r.line_tax <> 0 THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '1316', 'debit', round(r.line_tax, 2),\r\n        'memo', 'ضريبة مدخلات قابلة للاسترداد');\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF v_inv.tax <> 0 AND NOT EXISTS (\r\n       SELECT 1 FROM public.purchase_invoice_items it\r\n        WHERE it.invoice_id = p_invoice_id AND it.tax <> 0) THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1316', 'debit', round(v_inv.tax, 2),\r\n      'memo', 'ضريبة مدخلات قابلة للاسترداد');\r\n  END IF;\r\n\r\n  IF jsonb_array_length(v_lines) = 0 THEN\r\n    RAISE EXCEPTION 'Purchase % has nothing to post - its lines are empty or zero',\r\n      v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- ── ذمة المورد المتبقية (الدائن) ──\r\n  IF v_owed > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2111', 'credit', round(v_owed, 2),\r\n      'memo', 'مستحق للمورد',\r\n      'partner_type', 'supplier',\r\n      'partner_id', v_inv.supplier_id);\r\n  END IF;\r\n\r\n  -- ── السداد المسدد للمورد من الصندوق أو البنك ──\r\n  IF v_inv.paid > 0 AND v_cash_acct IS NOT NULL THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', v_cash_acct, 'credit', round(v_inv.paid, 2),\r\n      'memo', CASE\r\n                WHEN v_cash_acct LIKE '1101%' THEN 'سداد نقدي للمورد من الصندوق'\r\n                WHEN v_cash_acct LIKE '113%' THEN 'سداد للمورد عبر محفظة إلكترونية'\r\n                WHEN v_cash_acct = '1221' THEN 'أوراق دفع / شيك للمورد'\r\n                ELSE 'سداد بنكي / حوالة للمورد' END);\r\n  END IF;\r\n\r\n  v_entry := public.create_journal_entry(\r\n    'فاتورة مشتريات ' || v_inv.invoice_number,\r\n    v_inv.created_at::date,\r\n    'purchase_invoice', p_invoice_id, true, v_lines);\r\n\r\n  RETURN v_entry;\r\nEND;\r\n$$","-- 11.3 تحديث دالة إنشاء المشتريات التلقائية (create_purchase) لدعم الصناديق والمحافظ\r\nCREATE OR REPLACE FUNCTION public.create_purchase(\r\n  _warehouse_id uuid,\r\n  _supplier_id uuid,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _discount numeric,\r\n  _note text,\r\n  _items jsonb,\r\n  _cashbox_id uuid DEFAULT NULL,\r\n  _bank_account_id uuid DEFAULT NULL,\r\n  _payment_reference text DEFAULT NULL,\r\n  _payment_method_id text DEFAULT NULL\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id     uuid;\r\n  v_invoice_no     text;\r\n  v_user           uuid := auth.uid();\r\n  v_item           jsonb;\r\n  v_subtotal       numeric := 0;\r\n  v_tax_total      numeric := 0;\r\n  v_total          numeric := 0;\r\n  v_qty            numeric;\r\n  v_cost           numeric;\r\n  v_tax_rate       numeric;\r\n  v_line_total     numeric;\r\n  v_line_tax       numeric;\r\n  v_product        uuid;\r\n  v_effect         text;\r\n  v_type           text;\r\n  v_purchasable    boolean;\r\n  v_resolved_cashbox uuid := _cashbox_id;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse required';\r\n  END IF;\r\n  IF _supplier_id IS NULL THEN\r\n    RAISE EXCEPTION 'Supplier required';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    IF v_qty IS NULL OR v_qty <= 0 THEN\r\n      RAISE EXCEPTION 'Invalid quantity';\r\n    END IF;\r\n    IF v_cost IS NULL OR v_cost < 0 THEN\r\n      RAISE EXCEPTION 'Invalid unit cost';\r\n    END IF;\r\n    IF v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n      RAISE EXCEPTION 'Invalid tax rate';\r\n    END IF;\r\n    IF (v_item ->> 'product_id') IS NOT NULL THEN\r\n      SELECT p.is_purchasable INTO v_purchasable\r\n      FROM public.products p WHERE p.id = (v_item ->> 'product_id')::uuid;\r\n\r\n      IF v_purchasable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as purchasable', v_item ->> 'product_id';\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + v_line_tax;\r\n  END LOOP;\r\n\r\n  v_total := v_subtotal + v_tax_total - coalesce(_discount, 0);\r\n  v_invoice_no := public.next_purchase_number();\r\n\r\n  -- الصندوق الافتراضي للدفع النقدي إذا لم يُحدد\r\n  IF _payment_method = 'cash' AND v_resolved_cashbox IS NULL THEN\r\n    SELECT id INTO v_resolved_cashbox\r\n    FROM public.cashboxes\r\n    WHERE is_active = true AND is_default = true\r\n    LIMIT 1;\r\n    IF v_resolved_cashbox IS NULL THEN\r\n      SELECT id INTO v_resolved_cashbox\r\n      FROM public.cashboxes\r\n      WHERE is_active = true\r\n      ORDER BY created_at ASC\r\n      LIMIT 1;\r\n    END IF;\r\n  END IF;\r\n\r\n  INSERT INTO public.purchase_invoices (\r\n    invoice_number, supplier_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by,\r\n    cashbox_id, bank_account_id, payment_reference, payment_method_id\r\n  )\r\n  VALUES (\r\n    v_invoice_no, _supplier_id, _warehouse_id,\r\n    'confirmed'::public.invoice_status,\r\n    public.derive_payment_status(coalesce(_paid, 0), v_total),\r\n    v_subtotal, coalesce(_discount, 0), v_tax_total, v_total, coalesce(_paid, 0),\r\n    _payment_method::public.payment_method, nullif(btrim(_note), ''), v_user,\r\n    v_resolved_cashbox, _bank_account_id, nullif(btrim(_payment_reference), ''), _payment_method_id\r\n  )\r\n  RETURNING id INTO v_invoice_id;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_product  := (v_item ->> 'product_id')::uuid;\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n\r\n    SELECT r.o_line_type, r.o_stock_effect\r\n      INTO v_type, v_effect\r\n    FROM public.resolve_purchase_line(v_item) AS r;\r\n\r\n    INSERT INTO public.purchase_invoice_items (\r\n      invoice_id, product_id, quantity, unit_cost, discount, tax, total,\r\n      line_type, stock_effect\r\n    )\r\n    VALUES (\r\n      v_invoice_id, v_product, v_qty, v_cost, 0, v_line_tax, v_line_total + v_line_tax,\r\n      v_type, v_effect\r\n    );\r\n\r\n    IF v_effect = 'STOCK_RECEIPT' AND v_product IS NOT NULL THEN\r\n      PERFORM public.post_stock_delta(\r\n        v_product,\r\n        _warehouse_id,\r\n        v_qty,\r\n        v_cost,\r\n        'RECEIPT'::public.stock_movement_kind,\r\n        'purchase_invoice',\r\n        v_invoice_id,\r\n        'Purchase receipt',\r\n        'COMPANY'::public.owner_type,\r\n        NULL,\r\n        'purchase'::public.movement_type\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF coalesce(_paid, 0) < v_total THEN\r\n    UPDATE public.suppliers\r\n    SET balance = balance + (v_total - coalesce(_paid, 0)), updated_at = now()\r\n    WHERE id = _supplier_id;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'purchase.posted', 'purchase_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_no,\r\n      'supplier_id', _supplier_id,\r\n      'warehouse_id', _warehouse_id,\r\n      'total', v_total,\r\n      'paid', coalesce(_paid, 0),\r\n      'line_count', jsonb_array_length(_items),\r\n      'cashbox_id', v_resolved_cashbox,\r\n      'bank_account_id', _bank_account_id\r\n    ));\r\n\r\n  PERFORM public.post_purchase_invoice(v_invoice_id);\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","-- 11.4 تحديث دالة سداد الموردين لتسجيل الصندوق والبنك المحاسبي\r\nCREATE OR REPLACE FUNCTION public.record_supplier_payment(\r\n  p_supplier_id uuid,\r\n  p_amount numeric,\r\n  p_payment_method text DEFAULT 'CASH',\r\n  p_account_code text DEFAULT NULL,\r\n  p_payment_date date DEFAULT CURRENT_DATE,\r\n  p_notes text DEFAULT NULL,\r\n  p_due_date date DEFAULT NULL,\r\n  p_cashbox_id uuid DEFAULT NULL,\r\n  p_bank_account_id uuid DEFAULT NULL\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_supplier_name text;\r\n  v_payment_id uuid;\r\n  v_voucher_no text;\r\n  v_account text;\r\n  v_journal_id uuid;\r\n  v_lines jsonb;\r\n  v_new_balance numeric;\r\nBEGIN\r\n  IF p_supplier_id IS NULL THEN\r\n    RAISE EXCEPTION 'Supplier ID is required';\r\n  END IF;\r\n\r\n  IF p_amount IS NULL OR p_amount <= 0 THEN\r\n    RAISE EXCEPTION 'Payment amount must be greater than zero, got %', p_amount;\r\n  END IF;\r\n\r\n  SELECT name INTO v_supplier_name\r\n  FROM public.suppliers\r\n  WHERE id = p_supplier_id;\r\n\r\n  IF v_supplier_name IS NULL THEN\r\n    RAISE EXCEPTION 'Supplier with ID % not found', p_supplier_id;\r\n  END IF;\r\n\r\n  -- تحديد الحساب المالي (من الصندوق أو البنك أو الحساب المدخل)\r\n  IF p_account_code IS NOT NULL AND btrim(p_account_code) <> '' THEN\r\n    v_account := btrim(p_account_code);\r\n  ELSIF p_cashbox_id IS NOT NULL THEN\r\n    SELECT a.code INTO v_account\r\n    FROM public.cashboxes c\r\n    JOIN public.accounts a ON a.id = c.account_id\r\n    WHERE c.id = p_cashbox_id;\r\n  ELSIF p_bank_account_id IS NOT NULL THEN\r\n    SELECT a.code INTO v_account\r\n    FROM public.company_bank_accounts b\r\n    JOIN public.accounts a ON a.id = b.account_id\r\n    WHERE b.id = p_bank_account_id;\r\n  END IF;\r\n\r\n  IF v_account IS NULL THEN\r\n    IF upper(coalesce(p_payment_method, 'CASH')) IN ('BANK', 'TRANSFER', 'CHEQUE', 'CARD') THEN\r\n      v_account := '1111';\r\n    ELSIF upper(coalesce(p_payment_method, 'CASH')) = 'WALLET' THEN\r\n      v_account := '1131';\r\n    ELSE\r\n      v_account := '1101';\r\n    END IF;\r\n  END IF;\r\n\r\n  v_voucher_no := public.next_supplier_voucher_number();\r\n\r\n  INSERT INTO public.supplier_payments (\r\n    voucher_number,\r\n    supplier_id,\r\n    amount,\r\n    payment_method,\r\n    account_code,\r\n    payment_date,\r\n    notes,\r\n    created_by,\r\n    cashbox_id,\r\n    bank_account_id\r\n  ) VALUES (\r\n    v_voucher_no,\r\n    p_supplier_id,\r\n    round(p_amount, 2),\r\n    upper(coalesce(p_payment_method, 'CASH')),\r\n    v_account,\r\n    coalesce(p_payment_date, CURRENT_DATE),\r\n    p_notes,\r\n    v_user,\r\n    p_cashbox_id,\r\n    p_bank_account_id\r\n  ) RETURNING id INTO v_payment_id;\r\n\r\n  v_lines := jsonb_build_array(\r\n    jsonb_build_object(\r\n      'account_code', '2111',\r\n      'debit', round(p_amount, 2),\r\n      'credit', 0,\r\n      'memo', 'سداد ذمة للمورد ' || v_supplier_name,\r\n      'partner_type', 'supplier',\r\n      'partner_id', p_supplier_id\r\n    ),\r\n    jsonb_build_object(\r\n      'account_code', v_account,\r\n      'debit', 0,\r\n      'credit', round(p_amount, 2),\r\n      'memo', 'سند صرف رقم ' || v_voucher_no || ' للمورد ' || v_supplier_name\r\n    )\r\n  );\r\n\r\n  v_journal_id := public.create_journal_entry(\r\n    'سند صرف للمورد ' || v_supplier_name || ' (' || v_voucher_no || ')',\r\n    coalesce(p_payment_date, CURRENT_DATE),\r\n    'supplier_payment',\r\n    v_payment_id,\r\n    true,\r\n    v_lines\r\n  );\r\n\r\n  UPDATE public.supplier_payments\r\n  SET journal_entry_id = v_journal_id\r\n  WHERE id = v_payment_id;\r\n\r\n  UPDATE public.suppliers\r\n  SET balance = balance - round(p_amount, 2),\r\n      updated_at = now()\r\n  WHERE id = p_supplier_id\r\n  RETURNING balance INTO v_new_balance;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'supplier_payment.recorded', 'supplier_payment', v_payment_id,\r\n    jsonb_build_object(\r\n      'voucher_number', v_voucher_no,\r\n      'supplier_id', p_supplier_id,\r\n      'amount', round(p_amount, 2),\r\n      'account_code', v_account,\r\n      'payment_method', p_payment_method,\r\n      'cashbox_id', p_cashbox_id,\r\n      'bank_account_id', p_bank_account_id,\r\n      'new_balance', v_new_balance\r\n    ));\r\n\r\n  RETURN jsonb_build_object(\r\n    'payment_id', v_payment_id,\r\n    'voucher_number', v_voucher_no,\r\n    'journal_entry_id', v_journal_id,\r\n    'new_balance', v_new_balance\r\n  );\r\nEND;\r\n$$","-- ── 12. الصلاحيات والأمان (RLS & Grants) ───────────────────────────────────\r\n\r\nALTER TABLE public.cashboxes ENABLE ROW LEVEL SECURITY","ALTER TABLE public.company_bank_accounts ENABLE ROW LEVEL SECURITY","ALTER TABLE public.cheques_register ENABLE ROW LEVEL SECURITY","-- cashboxes: القراءة للجميع، والإدارة للمالك والمدير والمحاسب\r\nDROP POLICY IF EXISTS cashboxes_select ON public.cashboxes","CREATE POLICY cashboxes_select ON public.cashboxes\r\n  FOR SELECT TO authenticated USING (true)","DROP POLICY IF EXISTS cashboxes_admin ON public.cashboxes","CREATE POLICY cashboxes_admin ON public.cashboxes\r\n  FOR ALL TO authenticated\r\n  USING (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager') OR public.has_role(auth.uid(), 'accountant'))\r\n  WITH CHECK (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager') OR public.has_role(auth.uid(), 'accountant'))","-- company_bank_accounts: القراءة للجميع، والإدارة للمالك والمدير والمحاسب\r\nDROP POLICY IF EXISTS company_bank_accounts_select ON public.company_bank_accounts","CREATE POLICY company_bank_accounts_select ON public.company_bank_accounts\r\n  FOR SELECT TO authenticated USING (true)","DROP POLICY IF EXISTS company_bank_accounts_admin ON public.company_bank_accounts","CREATE POLICY company_bank_accounts_admin ON public.company_bank_accounts\r\n  FOR ALL TO authenticated\r\n  USING (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager') OR public.has_role(auth.uid(), 'accountant'))\r\n  WITH CHECK (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager') OR public.has_role(auth.uid(), 'accountant'))","-- cheques_register: القراءة للجميع، والإضافة للكاشير والمحاسب والمدير والمالك\r\nDROP POLICY IF EXISTS cheques_register_select ON public.cheques_register","CREATE POLICY cheques_register_select ON public.cheques_register\r\n  FOR SELECT TO authenticated USING (true)","DROP POLICY IF EXISTS cheques_register_insert ON public.cheques_register","CREATE POLICY cheques_register_insert ON public.cheques_register\r\n  FOR INSERT TO authenticated WITH CHECK (true)","DROP POLICY IF EXISTS cheques_register_admin ON public.cheques_register","CREATE POLICY cheques_register_admin ON public.cheques_register\r\n  FOR UPDATE TO authenticated\r\n  USING (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager') OR public.has_role(auth.uid(), 'accountant'))\r\n  WITH CHECK (public.has_role(auth.uid(), 'owner') OR public.has_role(auth.uid(), 'manager') OR public.has_role(auth.uid(), 'accountant'))","GRANT ALL ON public.cashboxes TO authenticated, service_role","GRANT ALL ON public.company_bank_accounts TO authenticated, service_role","GRANT ALL ON public.cheques_register TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.resolve_document_settlement_account(text, uuid, uuid, text) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.post_sales_invoice(uuid) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.post_purchase_invoice(uuid) TO authenticated, service_role","-- التوقيع القديم ذو السبعة وسائط (معرّف في 20_accounting_phase1_close_the_loop): يبقى قابلاً للتنفيذ للتوافق العكسي\r\nGRANT EXECUTE ON FUNCTION public.create_purchase(uuid, uuid, text, numeric, numeric, text, jsonb) TO authenticated, service_role","-- التوقيع الجديد بأحد عشر وسيطًا (البند 11.3 أعلاه) مع الصناديق والحسابات البنكية\r\nGRANT EXECUTE ON FUNCTION public.create_purchase(uuid, uuid, text, numeric, numeric, text, jsonb, uuid, uuid, text, text) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.record_customer_payment(uuid, uuid, numeric, text, date, text, uuid, uuid, text, text, text, date, text) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.record_customer_payment(uuid, uuid, numeric, text, date, text) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.record_supplier_payment(uuid, numeric, text, text, date, text, date, uuid, uuid) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.clear_cheque(uuid, uuid, date, text) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.bounce_cheque(uuid, text) TO authenticated, service_role",COMMIT}	treasury_cashboxes_and_payment_hierarchy
33	{"-- ============================================================================\r\n-- 30_milling_smart_manufacture_accounting.sql — الربط المحاسبي الآلي لعمليات المطحنة\r\n-- المرجع: DOC-MILLING-ERP-MASTER-2026-V2-AUDITED (المحور 4)\r\n-- ============================================================================\r\n-- 1. قيد التصنيع الذكي (smart_manufacture):\r\n--    Dr 1313 مخزون منتجات تامة (دقيق)\r\n--    Dr 1314 مخزون نواتج ثانوية (نخالة)\r\n--    Dr 5921 فاقد وتلف (إن وجد فاقد تشغيلي)\r\n--    Cr 1311 مخزون مواد أولية (القمح المسحوب بتكلفته الفعلية)\r\n--\r\n-- 2. قيد صرف المستهلكات التشغيلية (consume_internal_supplies):\r\n--    Dr 5316 مواد تعبئة وتغليف\r\n--    Cr 1315 مخزون مواد التعبئة\r\n--\r\n-- 3. ترحيل قيد إيراد خدمات الطحن (create_milling_service_document):\r\n--    استدعاء post_sales_invoice لترحيل أجور الطحن تلقائياً:\r\n--    Dr 1101 النقدية بالصندوق (أو 1211 ذمم العملاء)\r\n--    Cr 4311 إيراد الخدمات\r\n-- ============================================================================\r\n\r\nBEGIN","-- ════════════════════════════════════════════════════════════════════════════\r\n-- 1. smart_manufacture مع الترحيل المحاسبي المتوازن إلى journal_entries\r\n-- ════════════════════════════════════════════════════════════════════════════\r\nCREATE OR REPLACE FUNCTION public.smart_manufacture(\r\n  _warehouse_id uuid,\r\n  _grain_item_id uuid,\r\n  _grain_qty numeric,\r\n  _outputs jsonb,\r\n  _notes text\r\n)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_ref text;\r\n  v_output_value numeric := 0;\r\n  v_grain_cost numeric;\r\n  v_total_input_cost numeric;\r\n  v_total_output_qty numeric := 0;\r\n  v_waste_qty numeric := 0;\r\n  v_waste_cost numeric := 0;\r\n  v_allocatable_cost numeric := 0;\r\n  v_total_allocated numeric := 0;\r\n  v_line_allocated numeric;\r\n  v_line_idx int := 0;\r\n  v_outputs_count int;\r\n  r record;\r\n  v_last_out numeric;\r\n  v_journal_lines jsonb := '[]'::jsonb;\r\n  v_acct_code text;\r\n  v_item_name text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to run smart manufacture';\r\n  END IF;\r\n  IF _warehouse_id IS NULL OR _grain_item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse and grain item are required';\r\n  END IF;\r\n  IF coalesce(_grain_qty, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'Grain quantity must be positive';\r\n  END IF;\r\n  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN\r\n    RAISE EXCEPTION 'At least one output line is required';\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active\r\n  ) THEN\r\n    RAISE EXCEPTION 'Input must be an active RAW_MATERIAL grain';\r\n  END IF;\r\n\r\n  v_outputs_count := jsonb_array_length(_outputs);\r\n\r\n  -- التحقق من الأصناف واحتساب إجمالي القيمة البيعية والوزن\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL OR coalesce(r.qty, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every output line needs an item and a positive quantity';\r\n    END IF;\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM public.products\r\n      WHERE id = r.item_id AND item_class IN ('FINISHED_GOOD', 'BY_PRODUCT') AND is_active\r\n    ) THEN\r\n      RAISE EXCEPTION 'Outputs must be FINISHED_GOOD or BY_PRODUCT items';\r\n    END IF;\r\n\r\n    SELECT coalesce(r.qty, 0) * coalesce(sale_price, 0)\r\n      INTO v_last_out\r\n    FROM public.products WHERE id = r.item_id;\r\n\r\n    v_output_value := v_output_value + coalesce(v_last_out, 0);\r\n    v_total_output_qty := v_total_output_qty + coalesce(r.qty, 0);\r\n  END LOOP;\r\n\r\n  IF v_output_value <= 0 THEN\r\n    RAISE EXCEPTION 'Outputs must have sale prices to allocate cost by relative value';\r\n  END IF;\r\n\r\n  IF v_total_output_qty > _grain_qty THEN\r\n    RAISE EXCEPTION 'Total output weight (%) cannot exceed input grain weight (%)',\r\n      v_total_output_qty, _grain_qty;\r\n  END IF;\r\n\r\n  -- تكلفة القمح من طبقات التكلفة الفعلية أو كتالوج التكلفة\r\n  SELECT coalesce(\r\n    (SELECT sum(cl.quantity * cl.unit_cost) / nullif(sum(cl.quantity), 0)\r\n       FROM public.item_cost_layers cl\r\n      WHERE cl.product_id = _grain_item_id AND cl.quantity > 0\r\n        AND cl.owner_type = 'COMPANY'),\r\n    (SELECT cost_price FROM public.products WHERE id = _grain_item_id),\r\n    0\r\n  ) INTO v_grain_cost;\r\n\r\n  v_total_input_cost := round(coalesce(_grain_qty, 0) * coalesce(v_grain_cost, 0), 2);\r\n  v_ref := 'SM-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\r\n\r\n  -- احتساب الفاقد التشغيلي وتكلفته إن وجد\r\n  v_waste_qty := greatest(0, coalesce(_grain_qty, 0) - v_total_output_qty);\r\n  IF v_waste_qty > 0 AND v_grain_cost > 0 THEN\r\n    v_waste_cost := round(v_waste_qty * v_grain_cost, 2);\r\n  ELSE\r\n    v_waste_cost := 0;\r\n  END IF;\r\n\r\n  -- التكلفة الصافية الموزعة على النواتج\r\n  v_allocatable_cost := greatest(0, v_total_input_cost - v_waste_cost);\r\n\r\n  -- 1) صادر القمح (ينقص المخزون بتكلفته)\r\n  PERFORM public.post_stock_delta(\r\n    _grain_item_id, _warehouse_id, -coalesce(_grain_qty, 0), v_grain_cost,\r\n    'ISSUE'::public.stock_movement_kind, 'smart_manufacture', _grain_item_id,\r\n    'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n    'COMPANY'::public.owner_type, NULL, 'production_out'::public.movement_type);\r\n\r\n  -- 2) وارد النواتج بتكلفة موزعة وبناء أطراف القيد المدين للنواتج\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)\r\n  LOOP\r\n    DECLARE\r\n      v_line_value numeric;\r\n      v_unit_cost numeric;\r\n      v_item_class text;\r\n    BEGIN\r\n      v_line_idx := v_line_idx + 1;\r\n      SELECT coalesce(r.qty, 0) * coalesce(sale_price, 0), item_class, coalesce(name_ar, name)\r\n        INTO v_line_value, v_item_class, v_item_name\r\n      FROM public.products WHERE id = r.item_id;\r\n\r\n      IF v_line_idx = v_outputs_count THEN\r\n        -- آخر ناتج يحمل المتبقي بالضبط لضمان توازن التكلفة\r\n        v_line_allocated := v_allocatable_cost - v_total_allocated;\r\n      ELSE\r\n        v_line_allocated := round(v_allocatable_cost * (coalesce(v_line_value, 0) / v_output_value), 2);\r\n        v_total_allocated := v_total_allocated + v_line_allocated;\r\n      END IF;\r\n\r\n      v_unit_cost := round(v_line_allocated / nullif(coalesce(r.qty, 0), 0), 4);\r\n\r\n      PERFORM public.post_stock_delta(\r\n        r.item_id, _warehouse_id, coalesce(r.qty, 0), v_unit_cost,\r\n        'RECEIPT'::public.stock_movement_kind, 'smart_manufacture', _grain_item_id,\r\n        'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n        'COMPANY'::public.owner_type, NULL, 'production_in'::public.movement_type);\r\n\r\n      -- الحساب المحاسبي للناتج: 1314 للنخالة والنواتج العرضية، و1313 للمنتجات التامة (الدقيق)\r\n      IF v_item_class = 'BY_PRODUCT' THEN\r\n        v_acct_code := '1314';\r\n      ELSE\r\n        v_acct_code := '1313';\r\n      END IF;\r\n\r\n      IF v_line_allocated > 0 THEN\r\n        v_journal_lines := v_journal_lines || jsonb_build_object(\r\n          'account_code', v_acct_code,\r\n          'debit', v_line_allocated,\r\n          'credit', 0,\r\n          'memo', 'إنتاج مخزون ' || v_item_name || ' (' || v_ref || ')'\r\n        );\r\n      END IF;\r\n    END;\r\n  END LOOP;\r\n\r\n  -- 3) طرف قيد الفاقد والهدر التشغيلي إن وجد (حـ/ 5921)\r\n  IF v_waste_cost > 0 THEN\r\n    v_journal_lines := v_journal_lines || jsonb_build_object(\r\n      'account_code', '5921',\r\n      'debit', v_waste_cost,\r\n      'credit', 0,\r\n      'memo', 'فاقد وتلف تشغيلي مطحنة (' || v_ref || ')'\r\n    );\r\n  END IF;\r\n\r\n  -- 4) طرف القيد الدائن لمخزون المواد الأولية (حـ/ 1311) بإجمالي تكلفة القمح\r\n  IF v_total_input_cost > 0 THEN\r\n    v_journal_lines := v_journal_lines || jsonb_build_object(\r\n      'account_code', '1311',\r\n      'debit', 0,\r\n      'credit', v_total_input_cost,\r\n      'memo', 'سحب قمح خام للتصنيع (' || v_ref || ')'\r\n    );\r\n\r\n    -- ترحيل القيد لدفتر الأستاذ العام\r\n    PERFORM public.create_journal_entry(\r\n      'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n      CURRENT_DATE,\r\n      'smart_manufacture',\r\n      _grain_item_id,\r\n      true,\r\n      v_journal_lines\r\n    );\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'manufacture.smart', 'stock_movements', _grain_item_id,\r\n    jsonb_build_object(\r\n      'ref', v_ref,\r\n      'warehouse_id', _warehouse_id,\r\n      'grain_item_id', _grain_item_id,\r\n      'grain_qty', coalesce(_grain_qty, 0),\r\n      'grain_unit_cost', v_grain_cost,\r\n      'waste_qty', v_waste_qty,\r\n      'waste_cost', v_waste_cost,\r\n      'total_cost', v_total_input_cost,\r\n      'outputs', _outputs,\r\n      'allocation', 'RELATIVE_SALES_VALUE'\r\n    ));\r\n\r\n  RETURN v_ref;\r\nEND $function$","-- ════════════════════════════════════════════════════════════════════════════\r\n-- 2. consume_internal_supplies مع الترحيل المحاسبي (5316 مدين / 1315 دائن)\r\n-- ════════════════════════════════════════════════════════════════════════════\r\nCREATE OR REPLACE FUNCTION public.consume_internal_supplies(\r\n  _warehouse_id uuid,\r\n  _lines jsonb,\r\n  _notes text\r\n)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_ref text;\r\n  r record;\r\n  v_unit_cost numeric;\r\n  v_line_cost numeric;\r\n  v_total_cost numeric := 0;\r\n  v_journal_lines jsonb := '[]'::jsonb;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to issue internal consumables';\r\n  END IF;\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN\r\n    RAISE EXCEPTION 'At least one consumable line is required';\r\n  END IF;\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, qty numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL OR coalesce(r.qty, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every line needs an item and a positive quantity';\r\n    END IF;\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM public.products\r\n      WHERE id = r.item_id AND item_class IN ('NON_STOCK_ITEM', 'PACKAGING') AND is_active\r\n    ) THEN\r\n      RAISE EXCEPTION 'Only consumable (NON_STOCK_ITEM / PACKAGING) items may be issued here';\r\n    END IF;\r\n  END LOOP;\r\n\r\n  v_ref := 'CS-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, qty numeric)\r\n  LOOP\r\n    -- احتساب تكلفة المستهلك من طبقات التكلفة أو الكتالوج\r\n    SELECT coalesce(\r\n      (SELECT sum(cl.quantity * cl.unit_cost) / nullif(sum(cl.quantity), 0)\r\n         FROM public.item_cost_layers cl\r\n        WHERE cl.product_id = r.item_id AND cl.quantity > 0\r\n          AND cl.owner_type = 'COMPANY'),\r\n      (SELECT cost_price FROM public.products WHERE id = r.item_id),\r\n      0\r\n    ) INTO v_unit_cost;\r\n\r\n    v_line_cost := round(coalesce(r.qty, 0) * coalesce(v_unit_cost, 0), 2);\r\n    v_total_cost := v_total_cost + v_line_cost;\r\n\r\n    PERFORM public.post_stock_delta(\r\n      r.item_id, _warehouse_id, -coalesce(r.qty, 0), v_unit_cost,\r\n      'ISSUE'::public.stock_movement_kind, 'internal_consumables', _warehouse_id,\r\n      'صرف مستهلكات داخلي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n      'COMPANY'::public.owner_type, NULL, 'adjustment'::public.movement_type);\r\n  END LOOP;\r\n\r\n  -- ترحيل قيد صرف مواد التعبئة والتغليف (5316 مواد تعبئة / 1315 مخزون مواد التعبئة)\r\n  IF v_total_cost > 0 THEN\r\n    v_journal_lines := jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '5316',\r\n        'debit', v_total_cost,\r\n        'credit', 0,\r\n        'memo', 'مصروف مواد تعبئة وتغليف مستهلكة (' || v_ref || ')'\r\n      ),\r\n      jsonb_build_object(\r\n        'account_code', '1315',\r\n        'debit', 0,\r\n        'credit', v_total_cost,\r\n        'memo', 'منصرف مخزون مواد التعبئة (' || v_ref || ')'\r\n      )\r\n    );\r\n\r\n    PERFORM public.create_journal_entry(\r\n      'صرف مستهلكات تعبئة وتشغيل ' || v_ref || coalesce(' — ' || _notes, ''),\r\n      CURRENT_DATE,\r\n      'consume_internal_supplies',\r\n      _warehouse_id,\r\n      true,\r\n      v_journal_lines\r\n    );\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'consumables.issued', 'stock_movements', _warehouse_id,\r\n    jsonb_build_object(\r\n      'ref', v_ref,\r\n      'warehouse_id', _warehouse_id,\r\n      'lines', _lines,\r\n      'total_cost', v_total_cost,\r\n      'notes', _notes\r\n    ));\r\n\r\n  RETURN v_ref;\r\nEND $function$","-- ════════════════════════════════════════════════════════════════════════════\r\n-- 3. ترحيل فاتورة خدمة الطحن تلقائياً عند الإنشاء في create_milling_service_document\r\n-- ════════════════════════════════════════════════════════════════════════════\r\nCREATE OR REPLACE FUNCTION public.create_milling_service_document(\r\n  _customer_id uuid,\r\n  _warehouse_id uuid,\r\n  _grain_item_id uuid,\r\n  _bags numeric,\r\n  _kg numeric,\r\n  _service_item_id uuid,\r\n  _service_unit_price numeric,\r\n  _discount numeric,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _notes text\r\n)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_document_id uuid;\r\n  v_document_number text;\r\n  v_invoice_id uuid;\r\n  v_invoice_number text;\r\n  v_subtotal numeric;\r\n  v_total numeric;\r\n  v_paid numeric;\r\n  v_outstanding numeric;\r\n  v_customer_balance numeric;\r\n  v_credit_limit numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to create milling service documents';\r\n  END IF;\r\n  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _grain_item_id IS NULL\r\n     OR _service_item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Customer, warehouse, grain and service are required';\r\n  END IF;\r\n  IF coalesce(_bags, 0) <= 0 AND coalesce(_kg, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'Record at least one bag or a positive weight';\r\n  END IF;\r\n  IF coalesce(_bags, 0) < 0 OR coalesce(_kg, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Quantities cannot be negative';\r\n  END IF;\r\n  IF coalesce(_service_unit_price, 0) < 0 OR coalesce(_discount, 0) < 0\r\n     OR coalesce(_paid, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Service price, discount and paid amount cannot be negative';\r\n  END IF;\r\n  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN\r\n    RAISE EXCEPTION 'Unsupported payment method';\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active\r\n  ) THEN\r\n    RAISE EXCEPTION 'Intake item must be an active RAW_MATERIAL grain';\r\n  END IF;\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _service_item_id AND item_class = 'SERVICE' AND is_active AND is_sellable\r\n  ) THEN\r\n    RAISE EXCEPTION 'Milling fee item must be an active sellable SERVICE';\r\n  END IF;\r\n\r\n  SELECT balance, credit_limit\r\n    INTO v_customer_balance, v_credit_limit\r\n  FROM public.customers\r\n  WHERE id = _customer_id AND is_active = true\r\n  FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Selected customer is unavailable';\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = _warehouse_id AND is_active) THEN\r\n    RAISE EXCEPTION 'Selected warehouse is unavailable';\r\n  END IF;\r\n\r\n  v_subtotal := round(coalesce(_service_unit_price, 0), 2);\r\n  v_total := round(v_subtotal - coalesce(_discount, 0), 2);\r\n  IF v_total < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot exceed the service fee';\r\n  END IF;\r\n  v_paid := least(round(coalesce(_paid, 0), 2), v_total);\r\n  v_outstanding := round(v_total - v_paid, 2);\r\n  IF _payment_method = 'credit' AND v_paid <> 0 THEN\r\n    RAISE EXCEPTION 'Credit payment method requires zero paid amount';\r\n  END IF;\r\n  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN\r\n    RAISE EXCEPTION\r\n      'Credit limit exceeded: current balance %, requested debt %, limit %',\r\n      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);\r\n  END IF;\r\n\r\n  v_invoice_number := public.next_invoice_number();\r\n  INSERT INTO public.sales_invoices (\r\n    invoice_number, customer_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  ) VALUES (\r\n    v_invoice_number, _customer_id, _warehouse_id, 'confirmed',\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, round(coalesce(_discount, 0), 2), 0, v_total, v_paid,\r\n    _payment_method::public.payment_method, nullif(btrim(_notes), ''), v_user\r\n  ) RETURNING id INTO v_invoice_id;\r\n\r\n  INSERT INTO public.sales_invoice_items (\r\n    invoice_id, product_id, description, quantity, unit_price, discount, tax, total,\r\n    line_type, stock_effect\r\n  ) VALUES (\r\n    v_invoice_id, _service_item_id, 'أجور طحن وتجهيز', 1, v_subtotal,\r\n    0, 0, v_subtotal, 'SERVICE', 'NONE'\r\n  );\r\n\r\n  IF v_outstanding > 0 THEN\r\n    UPDATE public.customers\r\n    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()\r\n    WHERE id = _customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, debit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    ) VALUES (\r\n      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',\r\n      now(), v_user, 'sale:' || v_invoice_id, 'قيد أجور طحن آجل'\r\n    ) ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  -- ترحيل فاتورة خدمة الطحن تلقائياً للأستاذ العام (Dr 1101/1211 Cr 4311)\r\n  PERFORM public.post_sales_invoice(v_invoice_id);\r\n\r\n  v_document_number := 'MT-' || to_char(now(), 'YYYYMM') || '-' ||\r\n    lpad(nextval('public.milling_document_seq')::text, 4, '0');\r\n  INSERT INTO public.milling_service_documents (\r\n    document_number, customer_id, warehouse_id, sales_invoice_id, created_by\r\n  ) VALUES (\r\n    v_document_number, _customer_id, _warehouse_id, v_invoice_id, v_user\r\n  ) RETURNING id INTO v_document_id;\r\n\r\n  INSERT INTO public.custody_ledger (\r\n    customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n    bags_in, kg_in, milling_document_id, notes, created_by\r\n  ) VALUES (\r\n    _customer_id, _warehouse_id, 'INTAKE', _grain_item_id, v_document_number,\r\n    coalesce(_bags, 0), coalesce(_kg, 0), v_document_id, _notes, v_user\r\n  );\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'milling.service_document.created', 'milling_service_documents', v_document_id,\r\n    jsonb_build_object(\r\n      'document_number', v_document_number,\r\n      'invoice_id', v_invoice_id,\r\n      'invoice_number', v_invoice_number,\r\n      'customer_id', _customer_id,\r\n      'grain_item_id', _grain_item_id,\r\n      'bags', coalesce(_bags, 0),\r\n      'kg', coalesce(_kg, 0),\r\n      'service_total', v_total,\r\n      'paid', v_paid,\r\n      'outstanding', v_outstanding,\r\n      'stock_impact', 'NONE — customer custody'\r\n    ));\r\n\r\n  RETURN jsonb_build_object(\r\n    'document_id', v_document_id,\r\n    'document_number', v_document_number,\r\n    'invoice_id', v_invoice_id,\r\n    'invoice_number', v_invoice_number\r\n  );\r\nEND $function$","-- ════════════════════════════════════════════════════════════════════════════\r\n-- 4. تنظيف expense_lookups واستبعاد حسابات مسؤولي المنصة (السوبر أدمن) من الموظفين\r\n-- ════════════════════════════════════════════════════════════════════════════\r\nCREATE OR REPLACE FUNCTION public.expense_lookups(p_include_archived boolean DEFAULT false)\r\n RETURNS jsonb\r\n LANGUAGE sql\r\n STABLE\r\n SET search_path TO 'public'\r\nAS $function$\r\n  SELECT jsonb_build_object(\r\n    'categories', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', c.id, 'name', c.name, 'name_ar', c.name_ar,\r\n               'is_active', c.is_active, 'sort_order', c.sort_order,\r\n               'usage_count', (SELECT count(*) FROM public.expense_lines l WHERE l.category_id = c.id)\r\n             ) ORDER BY c.sort_order, c.name)\r\n      FROM public.expense_categories c\r\n      WHERE p_include_archived OR c.is_active\r\n    ), '[]'::jsonb),\r\n    'warehouses', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', w.id, 'name', w.name, 'name_ar', w.name_ar, 'is_default', w.is_default\r\n             ) ORDER BY w.name)\r\n      FROM public.warehouses w\r\n      WHERE w.is_active IS NOT FALSE\r\n    ), '[]'::jsonb),\r\n    'cost_centers', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', cc.id, 'code', cc.code, 'name', cc.name, 'name_ar', cc.name_ar\r\n             ) ORDER BY cc.name)\r\n      FROM public.expense_cost_centers cc\r\n      WHERE cc.is_active\r\n    ), '[]'::jsonb),\r\n    'projects', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', pj.id, 'code', pj.code, 'name', pj.name, 'name_ar', pj.name_ar\r\n             ) ORDER BY pj.name)\r\n      FROM public.expense_projects pj\r\n      WHERE pj.is_active\r\n    ), '[]'::jsonb),\r\n    'suppliers', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name) ORDER BY s.name)\r\n      FROM public.suppliers s\r\n      WHERE s.is_active IS NOT FALSE\r\n    ), '[]'::jsonb),\r\n    'employees', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) ORDER BY p.full_name)\r\n      FROM public.profiles p\r\n      WHERE p.is_active IS NOT FALSE\r\n        AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = p.id)\r\n        AND NOT EXISTS (SELECT 1 FROM public.platform_admins pa WHERE pa.user_id = p.id)\r\n        AND p.full_name NOT ILIKE '%سوبر%'\r\n        AND p.full_name NOT ILIKE '%superadmin%'\r\n    ), '[]'::jsonb),\r\n    'financial_accounts', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', a.id, 'code', a.code, 'name_ar', a.name_ar,\r\n               'account_type', a.account_type,\r\n               'requires_reconciliation', a.requires_reconciliation\r\n             ) ORDER BY a.code)\r\n      FROM public.accounts a\r\n      WHERE a.is_active IS NOT FALSE\r\n        AND (a.requires_reconciliation IS TRUE OR a.code LIKE '11%')\r\n    ), '[]'::jsonb)\r\n  )\r\n$function$","-- الصلاحيات\r\nGRANT EXECUTE ON FUNCTION public.smart_manufacture(uuid, uuid, numeric, jsonb, text) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.consume_internal_supplies(uuid, jsonb, text) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.create_milling_service_document(uuid, uuid, uuid, numeric, numeric, uuid, numeric, numeric, text, numeric, text) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.expense_lookups(boolean) TO authenticated, service_role",COMMIT}	milling_smart_manufacture_accounting
34	{"-- ============================================================================\r\n-- 31_batch_inventory_sync_and_allocation.sql\r\n--\r\n-- 1. Constraints on product_batches (nonnegative quantity and unit_cost).\r\n-- 2. batch_settings column in company_settings with defaults.\r\n-- 3. batch_id & batch_number columns in sales_invoice_items and purchase_invoice_items.\r\n-- 4. Batch Management & Sync Functions:\r\n--    - save_product_batch (with inventory sync via post_stock_delta)\r\n--    - delete_product_batch (with inventory sync via post_stock_delta)\r\n--    - reconcile_batches_with_inventory (compares batch sums vs inventory)\r\n--    - get_batch_kpis (accurate aggregate metrics across all rows)\r\n--    - get_batch_settings / save_batch_settings\r\n-- 5. Updated create_sale with FEFO/FIFO batch allocation and expired batch prevention.\r\n-- 6. Updated create_purchase with automatic batch creation/update and tracking enforcement.\r\n-- ============================================================================\r\n\r\n-- 1. Constraints on product_batches\r\nDO $$\r\nBEGIN\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM pg_constraint WHERE conname = 'product_batches_quantity_nonnegative'\r\n  ) THEN\r\n    ALTER TABLE public.product_batches\r\n      ADD CONSTRAINT product_batches_quantity_nonnegative CHECK (quantity >= 0);\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM pg_constraint WHERE conname = 'product_batches_unit_cost_nonnegative'\r\n  ) THEN\r\n    ALTER TABLE public.product_batches\r\n      ADD CONSTRAINT product_batches_unit_cost_nonnegative CHECK (unit_cost >= 0);\r\n  END IF;\r\nEND $$","-- 2. Add batch_settings to company_settings\r\nALTER TABLE public.company_settings\r\n  ADD COLUMN IF NOT EXISTS batch_settings jsonb DEFAULT '{\r\n    \\"dispatch_strategy\\": \\"FEFO\\",\r\n    \\"prevent_selling_expired\\": true,\r\n    \\"warning_days\\": 30,\r\n    \\"enforce_on_purchase\\": false,\r\n    \\"enforce_batch_selection_on_pos\\": false,\r\n    \\"auto_sync_inventory\\": true\r\n  }'::jsonb","-- 3. Columns in sales_invoice_items and purchase_invoice_items\r\nALTER TABLE public.sales_invoice_items\r\n  ADD COLUMN IF NOT EXISTS batch_id uuid REFERENCES public.product_batches(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS batch_number text","ALTER TABLE public.purchase_invoice_items\r\n  ADD COLUMN IF NOT EXISTS batch_number text,\r\n  ADD COLUMN IF NOT EXISTS expiry_date date","-- 4. Functions for Batch Management & Sync\r\n\r\nCREATE OR REPLACE FUNCTION public.get_batch_settings()\r\nRETURNS jsonb\r\nLANGUAGE sql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nSTABLE\r\nAS $function$\r\n  SELECT coalesce(\r\n    batch_settings,\r\n    '{\r\n      \\"dispatch_strategy\\": \\"FEFO\\",\r\n      \\"prevent_selling_expired\\": true,\r\n      \\"warning_days\\": 30,\r\n      \\"enforce_on_purchase\\": false,\r\n      \\"enforce_batch_selection_on_pos\\": false,\r\n      \\"auto_sync_inventory\\": true\r\n    }'::jsonb\r\n  )\r\n  FROM public.company_settings\r\n  LIMIT 1;\r\n$function$","CREATE OR REPLACE FUNCTION public.save_batch_settings(p_settings jsonb)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_merged jsonb;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN\r\n    RAISE EXCEPTION 'Not authorized to change company settings';\r\n  END IF;\r\n\r\n  UPDATE public.company_settings\r\n  SET batch_settings = coalesce(batch_settings, '{}'::jsonb) || p_settings,\r\n      updated_at = now()\r\n  RETURNING batch_settings INTO v_merged;\r\n\r\n  RETURN v_merged;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.get_batch_kpis(p_warning_days integer DEFAULT 30)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_today date := CURRENT_DATE;\r\n  v_soon_limit date := CURRENT_DATE + (coalesce(p_warning_days, 30) || ' days')::interval;\r\n  v_total bigint;\r\n  v_expired bigint;\r\n  v_soon bigint;\r\n  v_valid bigint;\r\n  v_none bigint;\r\nBEGIN\r\n  SELECT\r\n    count(*),\r\n    count(*) FILTER (WHERE expiry_date IS NOT NULL AND expiry_date <= v_today),\r\n    count(*) FILTER (WHERE expiry_date IS NOT NULL AND expiry_date > v_today AND expiry_date <= v_soon_limit),\r\n    count(*) FILTER (WHERE expiry_date IS NOT NULL AND expiry_date > v_soon_limit),\r\n    count(*) FILTER (WHERE expiry_date IS NULL)\r\n  INTO\r\n    v_total, v_expired, v_soon, v_valid, v_none\r\n  FROM public.product_batches;\r\n\r\n  RETURN jsonb_build_object(\r\n    'total', coalesce(v_total, 0),\r\n    'expired', coalesce(v_expired, 0),\r\n    'soon', coalesce(v_soon, 0),\r\n    'valid', coalesce(v_valid, 0),\r\n    'none', coalesce(v_none, 0),\r\n    'at_risk', coalesce(v_expired, 0) + coalesce(v_soon, 0)\r\n  );\r\nEND $function$","CREATE OR REPLACE FUNCTION public.save_product_batch(\r\n  p_product_id uuid,\r\n  p_warehouse_id uuid,\r\n  p_batch_number text,\r\n  p_expiry_date date DEFAULT NULL,\r\n  p_quantity numeric DEFAULT 0,\r\n  p_unit_cost numeric DEFAULT 0,\r\n  p_note text DEFAULT NULL,\r\n  p_sync_inventory boolean DEFAULT true,\r\n  p_batch_id uuid DEFAULT NULL\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_id   uuid;\r\n  v_old_qty numeric := 0;\r\n  v_delta numeric := 0;\r\n  v_product_tracked boolean;\r\n  v_cost numeric := coalesce(p_unit_cost, 0);\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF p_product_id IS NULL THEN\r\n    RAISE EXCEPTION 'Product is required for batch';\r\n  END IF;\r\n  IF p_warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required for batch';\r\n  END IF;\r\n  IF p_batch_number IS NULL OR btrim(p_batch_number) = '' THEN\r\n    RAISE EXCEPTION 'Batch number is required';\r\n  END IF;\r\n  IF p_quantity < 0 THEN\r\n    RAISE EXCEPTION 'Batch quantity cannot be negative';\r\n  END IF;\r\n  IF v_cost < 0 THEN\r\n    RAISE EXCEPTION 'Batch unit cost cannot be negative';\r\n  END IF;\r\n\r\n  SELECT (inventory_policy = 'TRACKED') INTO v_product_tracked\r\n  FROM public.products WHERE id = p_product_id;\r\n\r\n  IF p_batch_id IS NOT NULL THEN\r\n    -- Editing existing batch\r\n    SELECT id, quantity INTO v_id, v_old_qty\r\n    FROM public.product_batches\r\n    WHERE id = p_batch_id\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Batch % not found', p_batch_id;\r\n    END IF;\r\n\r\n    UPDATE public.product_batches\r\n    SET product_id = p_product_id,\r\n        warehouse_id = p_warehouse_id,\r\n        batch_number = btrim(p_batch_number),\r\n        expiry_date = p_expiry_date,\r\n        quantity = p_quantity,\r\n        unit_cost = v_cost,\r\n        note = nullif(btrim(p_note), ''),\r\n        updated_at = now()\r\n    WHERE id = v_id;\r\n\r\n    v_delta := p_quantity - v_old_qty;\r\n  ELSE\r\n    -- Creating new batch\r\n    SELECT id, quantity INTO v_id, v_old_qty\r\n    FROM public.product_batches\r\n    WHERE product_id = p_product_id\r\n      AND warehouse_id = p_warehouse_id\r\n      AND batch_number = btrim(p_batch_number)\r\n    FOR UPDATE;\r\n\r\n    IF FOUND THEN\r\n      -- Existing batch number for same product and warehouse\r\n      UPDATE public.product_batches\r\n      SET quantity = round(quantity + p_quantity, 3),\r\n          unit_cost = CASE WHEN v_cost > 0 THEN v_cost ELSE unit_cost END,\r\n          expiry_date = coalesce(p_expiry_date, expiry_date),\r\n          note = coalesce(nullif(btrim(p_note), ''), note),\r\n          updated_at = now()\r\n      WHERE id = v_id;\r\n\r\n      v_delta := p_quantity;\r\n    ELSE\r\n      INSERT INTO public.product_batches (\r\n        product_id, warehouse_id, batch_number, expiry_date, quantity, unit_cost, note, created_by\r\n      )\r\n      VALUES (\r\n        p_product_id, p_warehouse_id, btrim(p_batch_number), p_expiry_date,\r\n        p_quantity, v_cost, nullif(btrim(p_note), ''), v_user\r\n      )\r\n      RETURNING id INTO v_id;\r\n\r\n      v_delta := p_quantity;\r\n    END IF;\r\n  END IF;\r\n\r\n  -- Sync with inventory ledger if enabled\r\n  IF p_sync_inventory AND v_delta <> 0 AND coalesce(v_product_tracked, true) THEN\r\n    PERFORM public.post_stock_delta(\r\n      p_product_id,\r\n      p_warehouse_id,\r\n      v_delta,\r\n      v_cost,\r\n      CASE WHEN v_delta > 0 THEN 'RECEIPT'::public.stock_movement_kind ELSE 'ADJUSTMENT'::public.stock_movement_kind END,\r\n      'product_batch',\r\n      v_id,\r\n      CASE WHEN v_delta > 0 THEN 'توريد دفعة: ' || btrim(p_batch_number) ELSE 'تعديل دفعة: ' || btrim(p_batch_number) END,\r\n      'COMPANY'::public.owner_type,\r\n      NULL,\r\n      CASE WHEN v_delta > 0 THEN 'purchase'::public.movement_type ELSE 'adjustment'::public.movement_type END\r\n    );\r\n  END IF;\r\n\r\n  RETURN v_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.delete_product_batch(\r\n  p_batch_id uuid,\r\n  p_sync_inventory boolean DEFAULT true\r\n)\r\nRETURNS boolean\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_prod uuid;\r\n  v_wh   uuid;\r\n  v_qty  numeric;\r\n  v_cost numeric;\r\n  v_batch_no text;\r\n  v_tracked boolean;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  SELECT product_id, warehouse_id, quantity, unit_cost, batch_number\r\n    INTO v_prod, v_wh, v_qty, v_cost, v_batch_no\r\n  FROM public.product_batches\r\n  WHERE id = p_batch_id\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  SELECT (inventory_policy = 'TRACKED') INTO v_tracked\r\n  FROM public.products WHERE id = v_prod;\r\n\r\n  DELETE FROM public.product_batches WHERE id = p_batch_id;\r\n\r\n  IF p_sync_inventory AND v_qty > 0 AND coalesce(v_tracked, true) THEN\r\n    PERFORM public.post_stock_delta(\r\n      v_prod,\r\n      v_wh,\r\n      -v_qty,\r\n      v_cost,\r\n      'ADJUSTMENT'::public.stock_movement_kind,\r\n      'product_batch',\r\n      p_batch_id,\r\n      'حذف دفعة رقم: ' || v_batch_no,\r\n      'COMPANY'::public.owner_type,\r\n      NULL,\r\n      'adjustment'::public.movement_type\r\n    );\r\n  END IF;\r\n\r\n  RETURN true;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.reconcile_batches_with_inventory(\r\n  p_warehouse_id uuid DEFAULT NULL\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_rec record;\r\n  v_diff numeric;\r\n  v_results jsonb := '[]'::jsonb;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  FOR v_rec IN\r\n    WITH batch_sums AS (\r\n      SELECT product_id, warehouse_id, sum(quantity) as total_batch_qty\r\n      FROM public.product_batches\r\n      WHERE (p_warehouse_id IS NULL OR warehouse_id = p_warehouse_id)\r\n      GROUP BY product_id, warehouse_id\r\n    ),\r\n    inv_stocks AS (\r\n      SELECT product_id, warehouse_id, quantity as inv_qty\r\n      FROM public.inventory\r\n      WHERE owner_type = 'COMPANY'\r\n        AND (p_warehouse_id IS NULL OR warehouse_id = p_warehouse_id)\r\n    )\r\n    SELECT\r\n      coalesce(b.product_id, i.product_id) as product_id,\r\n      coalesce(b.warehouse_id, i.warehouse_id) as warehouse_id,\r\n      coalesce(b.total_batch_qty, 0) as batch_qty,\r\n      coalesce(i.inv_qty, 0) as inventory_qty\r\n    FROM batch_sums b\r\n    FULL OUTER JOIN inv_stocks i\r\n      ON b.product_id = i.product_id AND b.warehouse_id = i.warehouse_id\r\n    WHERE coalesce(b.total_batch_qty, 0) <> coalesce(i.inv_qty, 0)\r\n  LOOP\r\n    v_diff := v_rec.batch_qty - v_rec.inventory_qty;\r\n    v_results := v_results || jsonb_build_object(\r\n      'product_id', v_rec.product_id,\r\n      'warehouse_id', v_rec.warehouse_id,\r\n      'batch_qty', v_rec.batch_qty,\r\n      'inventory_qty', v_rec.inventory_qty,\r\n      'difference', v_diff\r\n    );\r\n  END LOOP;\r\n\r\n  RETURN v_results;\r\nEND $function$","-- 5. Updated create_sale with FEFO/FIFO batch allocation & expired check\r\nCREATE OR REPLACE FUNCTION public.create_sale(\r\n  _warehouse_id uuid,\r\n  _customer_id uuid,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _discount numeric,\r\n  _note text,\r\n  _items jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id     uuid;\r\n  v_invoice_number text;\r\n  v_user           uuid := auth.uid();\r\n  v_line           record;\r\n  v_subtotal       numeric := 0;\r\n  v_tax_total      numeric := 0;\r\n  v_discount       numeric := coalesce(_discount, 0);\r\n  v_total          numeric := 0;\r\n  v_paid           numeric := 0;\r\n  v_outstanding    numeric := 0;\r\n  v_price          numeric;\r\n  v_tax_rate       numeric;\r\n  v_cost           numeric;\r\n  v_customer_balance numeric;\r\n  v_credit_limit   numeric;\r\n  v_line_total     numeric;\r\n  v_line_tax       numeric;\r\n  v_effect         text;\r\n  v_line_type      text;\r\n  v_sellable       boolean;\r\n  v_status         public.invoice_status;\r\n  v_last_item_id   uuid;\r\n  v_available      numeric;\r\n  -- Batch allocation variables\r\n  v_batch_settings jsonb;\r\n  v_dispatch_strat text := 'FEFO';\r\n  v_prevent_expired boolean := true;\r\n  v_enforce_pos    boolean := false;\r\n  v_item_batch_id  uuid;\r\n  v_batch_rec      record;\r\n  v_rem_qty        numeric;\r\n  v_alloc_qty      numeric;\r\n  v_primary_batch_id uuid;\r\n  v_primary_batch_no text;\r\n  v_product_tracking text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to post sales';\r\n  END IF;\r\n\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'Cart is empty';\r\n  END IF;\r\n\r\n  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN\r\n    RAISE EXCEPTION 'Unsupported payment method';\r\n  END IF;\r\n\r\n  IF v_discount < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot be negative';\r\n  END IF;\r\n\r\n  IF coalesce(_paid, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Paid amount cannot be negative';\r\n  END IF;\r\n\r\n  -- Load batch settings\r\n  SELECT coalesce(batch_settings, '{}'::jsonb) INTO v_batch_settings\r\n  FROM public.company_settings LIMIT 1;\r\n\r\n  v_dispatch_strat := coalesce(v_batch_settings ->> 'dispatch_strategy', 'FEFO');\r\n  v_prevent_expired := coalesce((v_batch_settings ->> 'prevent_selling_expired')::boolean, true);\r\n  v_enforce_pos := coalesce((v_batch_settings ->> 'enforce_batch_selection_on_pos')::boolean, false);\r\n\r\n  -- ============================================================== VALIDATION\r\n  FOR v_line IN\r\n    SELECT r.o_product_id AS product_id, sum(r.o_quantity) AS quantity\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n    WHERE r.o_stock_effect = 'STOCK_ISSUE'\r\n    GROUP BY r.o_product_id\r\n    ORDER BY r.o_product_id\r\n  LOOP\r\n    SELECT i.quantity\r\n      INTO v_available\r\n    FROM public.inventory i\r\n    WHERE i.product_id = v_line.product_id\r\n      AND i.warehouse_id = _warehouse_id\r\n      AND i.owner_type = 'COMPANY'\r\n      AND i.owner_id IS NULL\r\n    FOR UPDATE;\r\n\r\n    v_available := coalesce(v_available, 0);\r\n\r\n    IF v_available < v_line.quantity THEN\r\n      RAISE EXCEPTION\r\n        'Insufficient stock for item %: available %, requested %',\r\n        v_line.product_id, v_available, v_line.quantity\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- Totals\r\n  FOR v_line IN\r\n    SELECT r.o_product_id    AS product_id,\r\n           r.o_quantity      AS quantity,\r\n           r.o_service_name  AS service_name,\r\n           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,\r\n           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n  LOOP\r\n    IF v_line.quantity IS NULL OR v_line.quantity <= 0 THEN\r\n      RAISE EXCEPTION 'Every sale line requires a positive quantity';\r\n    END IF;\r\n\r\n    IF v_line.product_id IS NULL THEN\r\n      IF coalesce(v_line.service_name, '') = '' THEN\r\n        RAISE EXCEPTION 'Every service line requires a description';\r\n      END IF;\r\n      IF v_line.input_price < 0 OR v_line.input_tax < 0 OR v_line.input_tax > 100 THEN\r\n        RAISE EXCEPTION 'Service line \\"%\\" has an invalid price or tax rate', v_line.service_name;\r\n      END IF;\r\n      v_price    := v_line.input_price;\r\n      v_tax_rate := v_line.input_tax;\r\n    ELSE\r\n      SELECT p.sale_price, p.tax_rate, p.is_sellable\r\n        INTO v_price, v_tax_rate, v_sellable\r\n      FROM public.products p\r\n      WHERE p.id = v_line.product_id AND p.is_active = true\r\n      FOR UPDATE;\r\n\r\n      IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Item % is not available for sale', v_line.product_id;\r\n      END IF;\r\n\r\n      IF v_sellable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as sellable', v_line.product_id;\r\n      END IF;\r\n\r\n      IF v_price < 0 OR v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n        RAISE EXCEPTION 'Item % has invalid pricing or tax configuration', v_line.product_id;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := round(v_line.quantity * v_price, 2);\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + round(v_line_total * v_tax_rate / 100, 2);\r\n  END LOOP;\r\n\r\n  v_total := round(v_subtotal + v_tax_total - v_discount, 2);\r\n  IF v_discount > v_subtotal + v_tax_total OR v_total < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot exceed the invoice amount';\r\n  END IF;\r\n\r\n  IF _customer_id IS NOT NULL THEN\r\n    SELECT balance, credit_limit\r\n      INTO v_customer_balance, v_credit_limit\r\n    FROM public.customers\r\n    WHERE id = _customer_id AND is_active = true\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Selected customer is unavailable';\r\n    END IF;\r\n  END IF;\r\n\r\n  v_paid := least(coalesce(_paid, 0), v_total);\r\n  v_outstanding := round(v_total - v_paid, 2);\r\n\r\n  IF v_outstanding > 0 AND _customer_id IS NULL THEN\r\n    RAISE EXCEPTION 'A customer is required when the sale has an unpaid amount';\r\n  END IF;\r\n  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN\r\n    RAISE EXCEPTION\r\n      'Credit limit exceeded: current balance %, requested debt %, limit %',\r\n      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);\r\n  END IF;\r\n\r\n  v_status := 'confirmed'::public.invoice_status;\r\n  v_invoice_number := public.next_invoice_number();\r\n\r\n  INSERT INTO public.sales_invoices (\r\n    invoice_number, customer_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_invoice_number, _customer_id, _warehouse_id, v_status,\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, v_discount, v_tax_total, v_total, v_paid,\r\n    _payment_method::public.payment_method, nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_invoice_id;\r\n\r\n  -- ================================================================== POSTING\r\n  FOR v_line IN\r\n    SELECT r.o_product_id   AS product_id,\r\n           r.o_quantity     AS quantity,\r\n           r.o_stock_effect AS stock_effect,\r\n           r.o_service_name AS service_name,\r\n           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,\r\n           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax,\r\n           nullif(btrim(coalesce(line ->> 'uom_id', '')), '')::uuid AS uom_id,\r\n           nullif(btrim(coalesce(line ->> 'batch_id', '')), '')::uuid AS explicit_batch_id\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n  LOOP\r\n    v_cost := NULL;\r\n    v_primary_batch_id := NULL;\r\n    v_primary_batch_no := NULL;\r\n\r\n    IF v_line.product_id IS NULL THEN\r\n      v_price     := v_line.input_price;\r\n      v_tax_rate  := v_line.input_tax;\r\n      v_line_type := 'AD_HOC_SERVICE';\r\n      v_effect    := 'NONE';\r\n    ELSE\r\n      SELECT p.sale_price, p.tax_rate, p.cost_price, p.tracking::text\r\n        INTO v_price, v_tax_rate, v_cost, v_product_tracking\r\n      FROM public.products p WHERE p.id = v_line.product_id;\r\n\r\n      v_line_type := public.item_line_type(v_line.product_id, false);\r\n      v_effect := public.item_stock_effect(v_line.product_id, 'out');\r\n\r\n      IF v_effect = 'STOCK_ISSUE' THEN\r\n        PERFORM public.post_stock_delta(\r\n          v_line.product_id,\r\n          _warehouse_id,\r\n          -v_line.quantity,\r\n          v_cost,\r\n          'ISSUE'::public.stock_movement_kind,\r\n          'sales_invoice',\r\n          v_invoice_id,\r\n          'POS sale',\r\n          'COMPANY'::public.owner_type,\r\n          NULL,\r\n          'sale'::public.movement_type\r\n        );\r\n\r\n        -- ── Batch Allocation & Deduction ───────────────────────────\r\n        IF v_line.explicit_batch_id IS NOT NULL THEN\r\n          -- Explicit batch chosen\r\n          SELECT id, batch_number, quantity, expiry_date\r\n            INTO v_batch_rec\r\n          FROM public.product_batches\r\n          WHERE id = v_line.explicit_batch_id\r\n            AND product_id = v_line.product_id\r\n            AND warehouse_id = _warehouse_id\r\n          FOR UPDATE;\r\n\r\n          IF NOT FOUND THEN\r\n            RAISE EXCEPTION 'الدفعة المحددة غير موجودة في المستودع لهذا المنتج';\r\n          END IF;\r\n\r\n          IF v_prevent_expired AND v_batch_rec.expiry_date IS NOT NULL AND v_batch_rec.expiry_date <= CURRENT_DATE THEN\r\n            RAISE EXCEPTION 'لا يمكن بيع الدفعة المنتهية: % (تاريخ الانتهاء: %)', v_batch_rec.batch_number, v_batch_rec.expiry_date;\r\n          END IF;\r\n\r\n          IF v_batch_rec.quantity < v_line.quantity THEN\r\n            RAISE EXCEPTION 'الكمية المطلوبة تتجاوز رصيد الدفعة % (المتاح: %, المطلوب: %)',\r\n              v_batch_rec.batch_number, v_batch_rec.quantity, v_line.quantity;\r\n          END IF;\r\n\r\n          UPDATE public.product_batches\r\n          SET quantity = round(quantity - v_line.quantity, 3), updated_at = now()\r\n          WHERE id = v_batch_rec.id;\r\n\r\n          v_primary_batch_id := v_batch_rec.id;\r\n          v_primary_batch_no := v_batch_rec.batch_number;\r\n\r\n        ELSIF v_product_tracking = 'BATCH' OR EXISTS (\r\n          SELECT 1 FROM public.product_batches\r\n          WHERE product_id = v_line.product_id AND warehouse_id = _warehouse_id AND quantity > 0\r\n        ) THEN\r\n          IF v_dispatch_strat = 'MANUAL' AND v_enforce_pos AND v_product_tracking = 'BATCH' THEN\r\n            RAISE EXCEPTION 'يجب تحديد الدفعة للصنف % في نقطة البيع', v_line.product_id;\r\n          END IF;\r\n\r\n          v_rem_qty := v_line.quantity;\r\n\r\n          FOR v_batch_rec IN\r\n            SELECT id, batch_number, quantity, expiry_date\r\n            FROM public.product_batches\r\n            WHERE product_id = v_line.product_id\r\n              AND warehouse_id = _warehouse_id\r\n              AND quantity > 0\r\n              AND (NOT v_prevent_expired OR expiry_date IS NULL OR expiry_date > CURRENT_DATE)\r\n            ORDER BY\r\n              CASE WHEN v_dispatch_strat = 'FIFO' THEN created_at END ASC,\r\n              CASE WHEN v_dispatch_strat <> 'FIFO' THEN expiry_date END ASC NULLS LAST,\r\n              created_at ASC\r\n            FOR UPDATE\r\n          LOOP\r\n            EXIT WHEN v_rem_qty <= 0;\r\n\r\n            v_alloc_qty := least(v_batch_rec.quantity, v_rem_qty);\r\n            UPDATE public.product_batches\r\n            SET quantity = round(quantity - v_alloc_qty, 3), updated_at = now()\r\n            WHERE id = v_batch_rec.id;\r\n\r\n            IF v_primary_batch_id IS NULL THEN\r\n              v_primary_batch_id := v_batch_rec.id;\r\n              v_primary_batch_no := v_batch_rec.batch_number;\r\n            END IF;\r\n\r\n            v_rem_qty := v_rem_qty - v_alloc_qty;\r\n          END LOOP;\r\n\r\n          IF v_product_tracking = 'BATCH' AND v_rem_qty > 0 THEN\r\n            RAISE EXCEPTION 'رصيد الدفعات المتاح والصالح غير كافٍ للصنف % (المتبقي: %)',\r\n              v_line.product_id, v_rem_qty;\r\n          END IF;\r\n        END IF;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := round(v_line.quantity * v_price, 2);\r\n    v_line_tax   := round(v_line_total * v_tax_rate / 100, 2);\r\n\r\n    INSERT INTO public.sales_invoice_items (\r\n      invoice_id, product_id, description, quantity, unit_price, discount, tax, total,\r\n      line_type, stock_effect, uom_id, batch_id, batch_number\r\n    )\r\n    VALUES (\r\n      v_invoice_id,\r\n      v_line.product_id,\r\n      CASE WHEN v_line.product_id IS NULL THEN v_line.service_name ELSE NULL END,\r\n      v_line.quantity, v_price, 0, v_line_tax, v_line_total + v_line_tax,\r\n      v_line_type, v_effect, v_line.uom_id,\r\n      v_primary_batch_id, v_primary_batch_no\r\n    )\r\n    RETURNING id INTO v_last_item_id;\r\n\r\n    IF v_line_type = 'AD_HOC_SERVICE' THEN\r\n      INSERT INTO public.ad_hoc_service_lines (\r\n        invoice_id, invoice_item_id, description, quantity, unit_price,\r\n        discount, tax, total, created_by\r\n      )\r\n      VALUES (\r\n        v_invoice_id, v_last_item_id, v_line.service_name, v_line.quantity,\r\n        v_price, 0, v_line_tax, v_line_total + v_line_tax, v_user\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF v_outstanding > 0 THEN\r\n    UPDATE public.customers\r\n    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()\r\n    WHERE id = _customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, debit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',\r\n      now(), v_user, 'sale:' || v_invoice_id, 'قيد بيع آجل'\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'sale.posted', 'sales_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_number,\r\n      'warehouse_id', _warehouse_id,\r\n      'customer_id', _customer_id,\r\n      'payment_method', _payment_method,\r\n      'total', v_total,\r\n      'paid', v_paid,\r\n      'outstanding', v_outstanding,\r\n      'line_count', jsonb_array_length(_items)\r\n    ));\r\n\r\n  PERFORM public.post_sales_invoice(v_invoice_id);\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","-- 6. Updated create_purchase with auto batch creation & tracking enforcement\r\nCREATE OR REPLACE FUNCTION public.create_purchase(\r\n  _warehouse_id uuid,\r\n  _supplier_id uuid,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _discount numeric,\r\n  _note text,\r\n  _items jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id     uuid;\r\n  v_invoice_no     text;\r\n  v_user           uuid := auth.uid();\r\n  v_item           jsonb;\r\n  v_subtotal       numeric := 0;\r\n  v_tax_total      numeric := 0;\r\n  v_total          numeric := 0;\r\n  v_qty            numeric;\r\n  v_cost           numeric;\r\n  v_tax_rate       numeric;\r\n  v_line_total     numeric;\r\n  v_line_tax       numeric;\r\n  v_product        uuid;\r\n  v_effect         text;\r\n  v_type           text;\r\n  v_purchasable    boolean;\r\n  v_batch_settings jsonb;\r\n  v_enforce_purchase boolean := false;\r\n  v_batch_no       text;\r\n  v_expiry_date    date;\r\n  v_product_tracking text;\r\n  v_existing_batch_id uuid;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse required';\r\n  END IF;\r\n  IF _supplier_id IS NULL THEN\r\n    RAISE EXCEPTION 'Supplier required';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  SELECT coalesce(batch_settings, '{}'::jsonb) INTO v_batch_settings\r\n  FROM public.company_settings LIMIT 1;\r\n  v_enforce_purchase := coalesce((v_batch_settings ->> 'enforce_on_purchase')::boolean, false);\r\n\r\n  ------------------------------------------------------------------ validate\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    IF v_qty IS NULL OR v_qty <= 0 THEN\r\n      RAISE EXCEPTION 'Invalid quantity';\r\n    END IF;\r\n    IF v_cost IS NULL OR v_cost < 0 THEN\r\n      RAISE EXCEPTION 'Invalid unit cost';\r\n    END IF;\r\n    IF v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n      RAISE EXCEPTION 'Invalid tax rate';\r\n    END IF;\r\n\r\n    IF (v_item ->> 'product_id') IS NOT NULL THEN\r\n      SELECT p.is_purchasable, p.tracking::text\r\n        INTO v_purchasable, v_product_tracking\r\n      FROM public.products p WHERE p.id = (v_item ->> 'product_id')::uuid;\r\n\r\n      IF v_purchasable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as purchasable', v_item ->> 'product_id';\r\n      END IF;\r\n\r\n      IF v_enforce_purchase AND v_product_tracking = 'BATCH' THEN\r\n        IF nullif(btrim(coalesce(v_item ->> 'batch_number', '')), '') IS NULL THEN\r\n          RAISE EXCEPTION 'يجب إدخال رقم الدفعة للصنف المتبع بالدفعات: %', v_item ->> 'product_id';\r\n        END IF;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + v_line_tax;\r\n  END LOOP;\r\n\r\n  v_total := v_subtotal + v_tax_total - coalesce(_discount, 0);\r\n  v_invoice_no := public.next_purchase_number();\r\n\r\n  INSERT INTO public.purchase_invoices (\r\n    invoice_number, supplier_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_invoice_no, _supplier_id, _warehouse_id,\r\n    'confirmed'::public.invoice_status,\r\n    public.derive_payment_status(coalesce(_paid, 0), v_total),\r\n    v_subtotal, coalesce(_discount, 0), v_tax_total, v_total, coalesce(_paid, 0),\r\n    _payment_method::public.payment_method, nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_invoice_id;\r\n\r\n  --------------------------------------------------------------------- post\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_product  := (v_item ->> 'product_id')::uuid;\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n    v_batch_no := nullif(btrim(coalesce(v_item ->> 'batch_number', '')), '');\r\n    v_expiry_date := nullif(btrim(coalesce(v_item ->> 'expiry_date', '')), '')::date;\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n\r\n    SELECT r.o_line_type, r.o_stock_effect\r\n      INTO v_type, v_effect\r\n    FROM public.resolve_purchase_line(v_item) AS r;\r\n\r\n    INSERT INTO public.purchase_invoice_items (\r\n      invoice_id, product_id, quantity, unit_cost, discount, tax, total,\r\n      line_type, stock_effect, batch_number, expiry_date\r\n    )\r\n    VALUES (\r\n      v_invoice_id, v_product, v_qty, v_cost, 0, v_line_tax, v_line_total + v_line_tax,\r\n      v_type, v_effect, v_batch_no, v_expiry_date\r\n    );\r\n\r\n    IF v_effect = 'STOCK_RECEIPT' AND v_product IS NOT NULL THEN\r\n      PERFORM public.post_stock_delta(\r\n        v_product,\r\n        _warehouse_id,\r\n        v_qty,\r\n        v_cost,\r\n        'RECEIPT'::public.stock_movement_kind,\r\n        'purchase_invoice',\r\n        v_invoice_id,\r\n        'Purchase receipt',\r\n        'COMPANY'::public.owner_type,\r\n        NULL,\r\n        'purchase'::public.movement_type\r\n      );\r\n\r\n      -- Automatic batch creation / increment\r\n      IF v_batch_no IS NOT NULL THEN\r\n        SELECT id INTO v_existing_batch_id\r\n        FROM public.product_batches\r\n        WHERE product_id = v_product AND warehouse_id = _warehouse_id AND batch_number = v_batch_no\r\n        FOR UPDATE;\r\n\r\n        IF FOUND THEN\r\n          UPDATE public.product_batches\r\n          SET quantity = round(quantity + v_qty, 3),\r\n              unit_cost = CASE WHEN v_cost > 0 THEN v_cost ELSE unit_cost END,\r\n              expiry_date = coalesce(v_expiry_date, expiry_date),\r\n              updated_at = now()\r\n          WHERE id = v_existing_batch_id;\r\n        ELSE\r\n          INSERT INTO public.product_batches (\r\n            product_id, warehouse_id, batch_number, expiry_date, quantity, unit_cost, created_by\r\n          )\r\n          VALUES (\r\n            v_product, _warehouse_id, v_batch_no, v_expiry_date, v_qty, v_cost, v_user\r\n          );\r\n        END IF;\r\n      END IF;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF coalesce(_paid, 0) < v_total THEN\r\n    UPDATE public.suppliers\r\n    SET balance = balance + (v_total - coalesce(_paid, 0)), updated_at = now()\r\n    WHERE id = _supplier_id;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'purchase.posted', 'purchase_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_no,\r\n      'supplier_id', _supplier_id,\r\n      'warehouse_id', _warehouse_id,\r\n      'total', v_total,\r\n      'paid', coalesce(_paid, 0),\r\n      'line_count', jsonb_array_length(_items)\r\n    ));\r\n\r\n  PERFORM public.post_purchase_invoice(v_invoice_id);\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","-- 7. Permissions\r\nGRANT EXECUTE ON FUNCTION public.get_batch_settings() TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.save_batch_settings(jsonb) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.get_batch_kpis(integer) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.save_product_batch(uuid, uuid, text, date, numeric, numeric, text, boolean, uuid) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.delete_product_batch(uuid, boolean) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.reconcile_batches_with_inventory(uuid) TO authenticated, service_role"}	batch_inventory_sync_and_allocation
36	{"-- ============================================================================\r\n-- 36_security_advisor_remediation.sql\r\n--\r\n-- معالجة تحذيرات Supabase Security Advisor:\r\n--\r\n--   1) 0010 security_definer_view (ERROR) — 23 عرضًا في public.\r\n--      السبب: كل عرض يُنشأ افتراضيًا بصلاحيات **مُنشئه** (postgres)، فتتجاوز\r\n--      الاستعلامات RLS للجداول الأساسية. الحل لا يكمن في RLS على العرض — RLS\r\n--      لا يعمل إلا على الجداول — بل في `security_invoker = true`، عندها يُنفَّذ\r\n--      العرض بصلاحيات **القراءة** فتسري RLS وGRANT الخاصة به.\r\n--\r\n--      لماذا الأمان لا ينكسر: كل الجداول المقروءة في هذه العروض (مخزون، دفتر\r\n--      أستاذ، فواتير، حسابات، عهدة، طحن) لها RLS وسياسات SELECT لـ authenticated،\r\n--      وكلها ممنوحة لـ authenticated. لذلك:\r\n--        • anon لا يصل لأي عرض بعد الإصلاح (مقصود — لا سياسة anon واحدة).\r\n--        • المستخدم المسجّل يرى نفس صفوفه المسموح له بها عبر RLS، لا أكثر.\r\n--      ملاحظة: service_role لا يتأثر — يتجاوز RLS دائمًا.\r\n--\r\n--   2) 0011 function_search_path_mutable (WARN) — 7 دوال.\r\n--      كل دالة SECURITY DEFINER يجب أن تثبّت search_path (القاعدة R-24).\r\n--\r\n--   3) 0024 permissive_rls_policy (WARN) — سياسات INSERT/UPDATE بـ true على\r\n--      supplier_ledger و supplier_payments و sync_idempotency_keys.\r\n--      هذه الجداول مالية/تشغيلية: الكتابة يجب أن تمرّ عبر RPC فقط. بعد هذا\r\n--      الترحيل تُسحب صلاحيات الكتابة من authenticated، وتُحذف السياسات المفتوحة\r\n--      (لا سياسة كتابة = لا كتابة من العميل)، ويبقى القراءة بضابط.\r\n--      الملف 28 كان يمنح anon قراءة/كتابة على الجدولين، ويسحب الترحيل ذلك.\r\n--\r\n--   4) 0028/0029 security definer function executable (WARN) — عشرات الدوال.\r\n--      المصدر الحقيقي: PostgreSQL يمنح EXECUTE على الدوال الجديدة لـ PUBLIC\r\n--      افتراضيًا. الحل: سحب EXECUTE من PUBLIC و anon من كل دوال public دفعةً\r\n--      واحدة، ثم منحها صراحةً لـ authenticated و service_role. الدوال التي\r\n--      تحتاج anon (لا شيء منها في هذا النظام) تُمنح استثناءً صريحًا.\r\n--      ملاحظة: سحب EXECUTE لا يؤثر على الاستدعاء الداخلي بين الدوال لأن\r\n--      SECURITY DEFINER يعمل بصلاحيات المالك الذي يملك EXECUTE.\r\n--\r\n-- لا DML ولا TRUNCATE في هذا الملف. DROP محدود لسياسات RLS فقط.\r\n-- ============================================================================\r\n\r\n-- ── (1) العروض: security_invoker ────────────────────────────────────────────\r\n-- تغطية كل عروض public الموجودة فعلًا (وليس قائمة ثابتة)، حتى لا يبقى عرض\r\n-- جديد أو عرض مُنشأ في ملف لاحق خارج الإصلاح. ALTER VIEW لا يعيد كتابة\r\n-- تعريف العرض، فهو idempotent بطبيعته.\r\nDO $$\r\nDECLARE\r\n  v_view record;\r\nBEGIN\r\n  FOR v_view IN\r\n    SELECT c.oid::regclass AS rel\r\n    FROM pg_class c\r\n    JOIN pg_namespace n ON n.oid = c.relnamespace\r\n    WHERE n.nspname = 'public'\r\n      AND c.relkind = 'v'\r\n  LOOP\r\n    EXECUTE format('ALTER VIEW %s SET (security_invoker = true)', v_view.rel);\r\n  END LOOP;\r\nEND $$","COMMENT ON SCHEMA public IS\r\n  'كل العروض في هذا المخطط تعمل بـ security_invoker = true: صلاحيات القارئ وRLS الجداول الأساسية هي المرجع، لا صلاحيات المالك.'","-- العروض ليست جداول: لا كتابة ولا TRUNCATE عليها. المنح السابقة (INSERT,\r\n-- UPDATE, DELETE, TRUNCATE) كانت من بقايا dump وليست قابلة للاستخدام أصلًا.\r\nREVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated, service_role","-- التقارير التشغيلية المالية: للمستخدمين المسجّلين فقط.\r\nGRANT SELECT ON public.standard_cost_readiness,\r\n                public.stock_positions,\r\n                public.company_stock_positions,\r\n                public.customer_owned_positions,\r\n                public.inventory_valuation,\r\n                public.item_valuation,\r\n                public.item_classification_gaps,\r\n                public.trial_balance,\r\n                public.customer_ledger_balances,\r\n                public.customer_balance_reconciliation,\r\n                public.invoice_ledger_status,\r\n                public.purchase_ledger_status,\r\n                public.purchase_register,\r\n                public.sales_register,\r\n                public.service_revenue,\r\n                public.expense_legacy_reconciliation,\r\n                public.milling_inventory_report,\r\n                public.milling_margin_report,\r\n                public.opening_balance_summary,\r\n                public.custody_balances,\r\n                public.custody_customer_statement,\r\n                public.custody_detected_loss,\r\n                public.custody_service_money\r\n  TO authenticated","-- ---------------------------------------------------------------------------\r\n-- إعادة المنح لجداول public (سحبناها جميعًا أعلاه لأن REVOKE ALL\r\n-- ON ALL TABLES لا تفرّق بين جدول وعرض). المصفوفة أدناه **مقصودة**، لا نسخة\r\n-- من dump: ما يحتاجه التطبيق فقط، مع تصحيح مبدأين:\r\n--   • service_role: كل شيء (عمليات الإدارة والنسخ الاحتياطي).\r\n--   • authenticated: قراءة/كتابة فقط حيث تسمح سياسة RLS، والمحرّك المالي\r\n--     يُقرأ ولا يُكتب (R-23 — الكتابة عبر RPC).\r\n--   • anon: لا منح كتابة على أي جدول (لا سياسة `TO anon` واحدة في\r\n--     المستودع)، والحلقة في نهاية القسم تسحب أي أثر متبقٍ.\r\n-- ---------------------------------------------------------------------------\r\nGRANT DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON ALL TABLES IN SCHEMA public TO service_role","GRANT DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE\r\n  ON public.accounts,\r\n     public.audit_logs,\r\n     public.backup_logs,\r\n     public.brands,\r\n     public.categories,\r\n     public.company_costing_settings,\r\n     public.company_items,\r\n     public.company_settings,\r\n     public.costing_policy_history,\r\n     public.countries_of_origin,\r\n     public.customer_payment_splits,\r\n     public.customers,\r\n     public.device_registrations,\r\n     public.expense_categories,\r\n     public.expense_cost_centers,\r\n     public.expense_projects,\r\n     public.expenses,\r\n     public.item_policy_review_queue,\r\n     public.loyalty_transactions,\r\n     public.product_compatibilities,\r\n     public.products,\r\n     public.profiles,\r\n     public.purchase_invoice_items,\r\n     public.purchase_invoices,\r\n     public.purchase_return_items,\r\n     public.purchase_returns,\r\n     public.quality_grades,\r\n     public.sales_return_items,\r\n     public.sales_returns,\r\n     public.stock_transfer_items,\r\n     public.stock_transfers,\r\n     public.suppliers,\r\n     public.sync_idempotency_keys,\r\n     public.tenant_subscriptions,\r\n     public.units,\r\n     public.user_roles,\r\n     public.vehicle_makes,\r\n     public.vehicle_models,\r\n     public.warehouses,\r\n     public.product_batches,\r\n     public.packaging_types,\r\n     public.custody_ledger,\r\n     public.milling_service_documents\r\n  TO authenticated","-- الجداول المالية (R-23): الكتابة عبر RPC فقط — للقراءة فقط لـ authenticated.\r\nGRANT SELECT ON public.ad_hoc_service_lines,\r\n                public.customer_ledger,\r\n                public.custody_ledger,\r\n                public.customer_payments,\r\n                public.inventory,\r\n                public.sales_invoice_items,\r\n                public.sales_invoices,\r\n                public.stock_adjustment_items,\r\n                public.stock_adjustments,\r\n                public.stock_movements,\r\n                public.stock_opening_items,\r\n                public.stock_openings,\r\n                public.journal_entries,\r\n                public.journal_lines,\r\n                public.milling_service_documents\r\n  TO authenticated","-- تحقق مرجعي: لا يوجد في المستودع سياسة واحدة `TO anon` على أي جدول.\r\n-- لذلك كل منح anon على الجداول (وراثة dump: INSERT/UPDATE/DELETE/TRUNCATE)\r\n-- لا تقابله سياسة، فلا يُرتجع منه صف واحد اليوم، لكنه يصبح ثغرة مباشرة إن\r\n-- أُضيفت سياسة لاحقًا. لذلك تُسحب صلاحيات الكتابة هذه جماعيًا. SELECT يبقى\r\n-- لـ anon على الريلشنات، لكن RLS يمنع أي صف بلا سياسة — فالعزل مضمون بالسياسة\r\n-- لا بالمنح. إن أضفت شاشة عامة فعلًا، سياسة `TO anon` هي ما يفتحها.\r\nDO $$\r\nDECLARE\r\n  v_rel record;\r\nBEGIN\r\n  FOR v_rel IN\r\n    SELECT c.oid::regclass AS rel\r\n    FROM pg_class c\r\n    JOIN pg_namespace n ON n.oid = c.relnamespace\r\n    WHERE n.nspname = 'public'\r\n      AND c.relkind IN ('r', 'p', 'v', 'm')\r\n  LOOP\r\n    EXECUTE format('REVOKE INSERT, UPDATE, DELETE, TRUNCATE, TRIGGER, REFERENCES ON %s FROM anon', v_rel.rel);\r\n  END LOOP;\r\nEND $$","-- ── (2) تثبيت search_path على الدوال المتأثرين ──────────────────────────────\r\n-- ALTER FUNCTION لا يغيّر الجسم ولا المنح، فيصلح التعريف الساري أينما كان.\r\nALTER FUNCTION public.expense_line_net(numeric, numeric, public.expense_tax_mode)  SET search_path = public","ALTER FUNCTION public.expense_line_tax(numeric, numeric, public.expense_tax_mode)  SET search_path = public","ALTER FUNCTION public.expense_round(numeric)                                      SET search_path = public","ALTER FUNCTION public.tg_journal_entries_no_delete()                              SET search_path = public","ALTER FUNCTION public.next_supplier_voucher_number()                              SET search_path = public","ALTER FUNCTION public.trg_purchase_invoice_to_supplier_ledger()                   SET search_path = public","ALTER FUNCTION public.trg_purchase_return_to_supplier_ledger()                    SET search_path = public","-- ── (3) تضييق سياسات RLS المفتوحة على الجداول المالية ──────────────────────\r\n-- supplier_ledger: حركات تُكتب حصريًا من الدوال/المشغّلات (SECURITY DEFINER)،\r\n-- فتتجاوز RLS طبيعيًا. سياسة القراءة تبقى كما هي.\r\nDROP POLICY IF EXISTS \\"supplier_ledger_insert_auth\\" ON public.supplier_ledger","DROP POLICY IF EXISTS \\"supplier_ledger_update_auth\\" ON public.supplier_ledger","-- supplier_payments: نفس المنطق — سند الصرف يُنشأ عبر record_supplier_payment.\r\nDROP POLICY IF EXISTS \\"supplier_payments_insert_auth\\" ON public.supplier_payments","DROP POLICY IF EXISTS \\"supplier_payments_read_auth\\" ON public.supplier_payments","CREATE POLICY \\"supplier_payments_read_auth\\" ON public.supplier_payments\r\n  AS PERMISSIVE FOR SELECT TO authenticated\r\n  USING (public.is_staff(auth.uid()))","-- الكتابة المباشرة ممنوعة على الجدولين، فتُلغى السياسات المفتوحة بلا أثر.\r\nREVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.supplier_ledger, public.supplier_payments FROM authenticated, anon","-- المنح الأصلي للجدولين كان يشمل anon (وراثة من dump)، فيُسحب نهائيًا:\r\n-- الكتابة عبر الدوال فقط، والقراءة عبر get_supplier_statement / الواجهة المسجّلة.\r\nREVOKE ALL ON public.supplier_ledger, public.supplier_payments FROM anon","-- sync_idempotency_keys: الكتابة عبر sync_apply_operation فقط (SECURITY DEFINER).\r\n-- القراءة المباشرة لمفاتيح أجهزة غير الجهاز الحالي تسريب لا حاجة له.\r\nDROP POLICY IF EXISTS \\"Authenticated users can check and insert idempotency keys\\" ON public.sync_idempotency_keys","CREATE POLICY \\"Idempotency keys are service managed\\" ON public.sync_idempotency_keys\r\n  AS PERMISSIVE FOR SELECT TO authenticated\r\n  USING (origin_device_id = (auth.jwt() ->> 'device_id'))","REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.sync_idempotency_keys FROM authenticated, anon","-- ── (4) EXECUTE: لا PUBLIC ولا anon على دوال public ────────────────────────\r\n-- PostgreSQL يمنح PUBLIC صلاحية التنفيذ افتراضيًا؛ هذا هو جذر تحذيري 0028/0029.\r\n-- عشرات التحذيرات المتبقية في Advisor كلها من هذا السبب الواحد؛ الحلقة تُغلقه\r\n-- جماعيًا بدل تكراره لكل اسم — فأي دالة تُضاف في ملف لاحق لا تصبح عامة بصمت.\r\nDO $$\r\nDECLARE\r\n  v_fn record;\r\nBEGIN\r\n  FOR v_fn IN\r\n    SELECT p.oid::regprocedure AS sig\r\n    FROM pg_proc p\r\n    JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'public'\r\n      AND p.prokind = 'f'\r\n  LOOP\r\n    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', v_fn.sig);\r\n    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon', v_fn.sig);\r\n    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated', v_fn.sig);\r\n    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', v_fn.sig);\r\n  END LOOP;\r\nEND $$","-- دوال SECURITY DEFINER التي كانت مفتوحة لـ anon — أي زائر كان يقرأ/يعدّل\r\n-- بيانات الشركة. أُلغيت بالحلقة أعلاه عمدًا، وهذا التعليق يثبّت القرار.\r\nCOMMENT ON FUNCTION public.has_role(uuid, public.app_role) IS\r\n  'تُستدعى من سياسات RLS. التنفيذ لـ authenticated و service_role فقط.'","COMMENT ON FUNCTION public.is_staff(uuid) IS\r\n  'تُستدعى من سياسات RLS. التنفيذ لـ authenticated و service_role فقط.'","-- ── (4-ب) دوال لا يستدعيها أي مستخدم ─────────────────────────────────────\r\n-- تحذير 0029 يشتكي من **القدرة على الاستدعاء** لا من SECURITY DEFINER نفسه.\r\n-- ولا واحدة مما يلي يُستدعى من PostgREST: كلها أجزاء داخلية (مشغّلات، حرّاس،\r\n-- مساعدات تستدعيها سياسات RLS أو دوال أخرى SECURITY DEFINER تعمل بصلاحيات\r\n-- المالك). المنح الذي كانت تملكه وراثة من PUBLIC وليس قرارًا.\r\n--   • مشغّلات TRIGGER: المحرّك يستدعيها بلا EXECUTE للمستخدم، والاستدعاء\r\n--     المباشر عبر RPC يرفضه PostgreSQL أصلًا (cannot be called directly).\r\n--   • مساعدات RLS/expense_*: تُستدعى من داخل سياسات ودوال SOURCE-DEFINER\r\n--     التي تعمل بصلاحيات المالك.\r\n--   • نسخ تاريخية (next_*_number, *_reference, post_stock_delta…): أزالتها\r\n--     محرحات الترقيم الموحد والدفاتر — لا واجهة تستدعيها.\r\n-- المجموعة تُسمّى مرة واحدة؛ أي دالة جديدة بنفس الاسم تُسحب تلقائيًا.\r\nDO $$\r\nDECLARE\r\n  v_fn record;\r\n  v_internal text[] := ARRAY[\r\n    -- مشغّلات — يُستدعيها المحرك فقط\r\n    'handle_new_user', 'normalize_auth_user_token_columns',\r\n    'tg_set_updated_at', 'sync_item_class_from_policy',\r\n    'tg_expense_entries_guard', 'tg_expense_lines_sync_total',\r\n    'tg_expense_payments_sync_entry', 'tg_guard_item_policy_change',\r\n    'tg_journal_entries_no_delete',\r\n    'trg_purchase_invoice_to_supplier_ledger',\r\n    'trg_purchase_return_to_supplier_ledger',\r\n    'payment_method_settings_guard', 'payment_methods_authoring_guard',\r\n    'payment_methods_delete_guard',\r\n    -- مساعدات تخويل تُستدعى من سياسات RLS أو دوال المالك\r\n    'has_role', 'is_staff', 'is_platform_admin', 'is_platform_superadmin',\r\n    'can_author_payment_methods', 'can_operate_milling', 'can_view_milling',\r\n    'can_read_finance', 'can_read_expense_entry',\r\n    'expense_actor', 'expense_can', 'expense_role_rank',\r\n    'expense_assert_capability', 'expense_can_write_document',\r\n    -- مساعدات حسابية/قراءة داخلية\r\n    'expense_line_net', 'expense_line_tax', 'expense_round',\r\n    'expense_ledger_summary', 'expense_log_action', 'expense_write_lines',\r\n    'item_effective_policy', 'item_has_stock_history', 'item_line_type',\r\n    'item_stock_effect', 'product_delete_guard', 'product_reference_counts',\r\n    'warehouse_reference_counts', 'customer_credit_limit_allows',\r\n    'customer_ledger_balance', 'sales_line_cost',\r\n    'sales_invoice_tender_breakdown', 'company_costing_method',\r\n    -- محرّك طرق الدفع (يُستدعى من create_sale / record_* لا من الواجهة)\r\n    'ledger_account_code_for_payment_method', 'payment_method_catalog_id',\r\n    'payment_method_catalog_view', 'payment_method_is_allowed',\r\n    'payment_method_ledger_account', 'payment_method_legacy_id',\r\n    'payment_method_resolve_id', 'payment_methods_seed_is_identity_owned',\r\n    'resolve_writable_payment_method',\r\n    -- مساعدات أسطر الفواتير (تُستدعى من create_sale/create_purchase)\r\n    'resolve_purchase_line', 'resolve_sale_line', 'resolve_unit_cost',\r\n    'apply_cost_movement', 'post_stock_delta',\r\n    -- محرّك السندات القديم/التاريخي\r\n    'next_expense_reference', 'next_invoice_number', 'next_purchase_number',\r\n    'next_purchase_return_number', 'next_sales_return_number',\r\n    'next_stock_adjustment_number', 'next_stock_opening_number',\r\n    'next_supplier_voucher_number', 'next_transfer_number',\r\n    'balance_and_post_return', 'adjust_loyalty',\r\n    'migrate_legacy_expenses', 'set_standard_costs',\r\n    'get_chart_of_accounts_tree',\r\n    -- محرّك الترقيم: يُستدعى من الدوال المالية لا من الواجهة\r\n    'fn_next_document_number'\r\n  ];\r\nBEGIN\r\n  FOR v_fn IN\r\n    SELECT p.oid::regprocedure AS sig\r\n    FROM pg_proc p\r\n    JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'public'\r\n      AND p.prokind = 'f'\r\n      AND p.proname = ANY(v_internal)\r\n  LOOP\r\n    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated', v_fn.sig);\r\n    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM service_role', v_fn.sig);\r\n  END LOOP;\r\nEND $$","-- ── (5) منح EXECUTE الصريح للملفات اللاحقة (24–35) ─────────────────────────\r\n-- الملفات 24–35 أُنشئت بعد «GRANTS» في الملف 13، فمنحتها PostgreSQL لـ PUBLIC\r\n-- ضمنًا. الحلقة أعلاه أغلقتها الآن، وهذا تثبيت صريح للدوال التي تحتاجها\r\n-- الواجهة أو وظائف النسخ الاحتياطي. الأسماء المكرّرة (overloads) تُعرَّف\r\n-- بتوقيعها الكامل حتى لا يُمنح توقيع لم يُقصَد.\r\nGRANT EXECUTE ON FUNCTION public.activate_fixed_asset(uuid) TO authenticated","GRANT EXECUTE ON FUNCTION public.dispose_fixed_asset(uuid, date, numeric, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.run_depreciation(uuid, date) TO authenticated","GRANT EXECUTE ON FUNCTION public.run_batch_depreciation(date) TO authenticated","GRANT EXECUTE ON FUNCTION public.run_contract_amortization(uuid, date) TO authenticated","GRANT EXECUTE ON FUNCTION public.run_batch_amortization(date) TO authenticated","GRANT EXECUTE ON FUNCTION public.close_fiscal_year(integer) TO authenticated","GRANT EXECUTE ON FUNCTION public.open_fiscal_year(integer) TO authenticated","GRANT EXECUTE ON FUNCTION public.set_period_status(uuid, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.generate_tax_declaration(date, date) TO authenticated","GRANT EXECUTE ON FUNCTION public.settle_tax_period(date, date, text, date) TO authenticated","GRANT EXECUTE ON FUNCTION public.pay_tax_settlement(uuid, date, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.activate_prepaid_contract(uuid) TO authenticated","GRANT EXECUTE ON FUNCTION public.post_purchase_invoice(uuid) TO authenticated","GRANT EXECUTE ON FUNCTION public.post_sales_invoice(uuid) TO authenticated","GRANT EXECUTE ON FUNCTION public.reverse_journal_entry(uuid, text) TO authenticated","GRANT EXECUTE ON FUNCTION public.record_supplier_payment(uuid, numeric, text, text, date, text, date) TO authenticated","GRANT EXECUTE ON FUNCTION public.get_supplier_statement(uuid, timestamptz, timestamptz) TO authenticated","GRANT EXECUTE ON FUNCTION public.fn_format_document_number(text, bigint, timestamptz) TO authenticated","GRANT EXECUTE ON FUNCTION public.fn_resolve_document_numbering(text, uuid, uuid, uuid) TO authenticated","GRANT EXECUTE ON FUNCTION public.fn_set_document_numbering(text, text, text, smallint, text, text, text, bigint) TO authenticated","GRANT EXECUTE ON FUNCTION public.backup_export_all(integer) TO authenticated","GRANT EXECUTE ON FUNCTION public.backup_restore_all(jsonb) TO authenticated","GRANT EXECUTE ON FUNCTION public.get_chart_of_accounts_tree() TO authenticated","-- الحلقات أعلاه تبني قائمة المنع على الاسم فقط، فايا دالة جديدة بنفس\r\n-- الاسم ستُسحب تلقائيًا. للتأكد من أن ما تحتاجه الواجهة ممنوح، يشمل التحقق\r\n-- في نهاية الملف قائمة الدوال المتوقعة للاستدعاء من PostgREST.\r\n-- الواجهة تستدعي adjust_loyalty من المستخدم المسجّل فقط\r\n-- (src/routes/_app.loyalty.tsx)، وهو ما تمنحه الحلقة أعلاه.\r\n-- لا استثناء لـ anon: لا شاشة عامة في المستودع.\r\n\r\n-- ============================================================================\r\n-- تحقق بعد التطبيق — المتوقع أن ترجع الاستعلامات الأربعة صفر صف:\r\n--\r\n--   -- 1) عروض ما تزال SECURITY DEFINER\r\n--   SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace\r\n--    WHERE n.nspname='public' AND c.relkind='v'\r\n--      AND coalesce(array_to_string(c.reloptions,','),'') NOT LIKE '%security_invoker=true%';\r\n--\r\n--   -- 2) دوال بلا search_path ثابت\r\n--   SELECT p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\r\n--    WHERE n.nspname='public' AND p.prokind='f'\r\n--      AND coalesce(array_to_string(p.proconfig,','),'') NOT LIKE '%search_path%';\r\n--\r\n--   -- 3) دوال يستطيع anon تنفيذها\r\n--   SELECT p.proname, p.oid::regprocedure FROM pg_proc p\r\n--     JOIN pg_namespace n ON n.oid=p.pronamespace\r\n--    WHERE n.nspname='public' AND has_function_privilege('anon', p.oid, 'EXECUTE');\r\n--\r\n--   -- 4) كتابة مباشرة لـ anon على أي جدول\r\n--   SELECT table_name FROM information_schema.table_privileges\r\n--    WHERE table_schema='public' AND grantee='anon'\r\n--      AND privilege_type IN ('INSERT','UPDATE','DELETE','TRUNCATE');\r\n--\r\n-- ============================================================================\r\n-- ROLLBACK\r\n--\r\n--   ALTER VIEW <view> SET (security_invoker = false);          -- لكل عرض\r\n--   ALTER FUNCTION <fn> RESET search_path;                     -- لكل دالة\r\n--   GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO PUBLIC; -- يعيد\r\n--   المنح الضمنية القديمة (لكنه يعيد الثغرة الأمنية).\r\n--   ثم إعادة إنشاء السياسات المحذوفة من الملف 28 والملف 13، وإعادة منح\r\n--   anon من الملف 13 (غير مستحسن — يعيد تحذيرات 0028/0029 و0024).\r\n-- ============================================================================"}	security_advisor_remediation
38	{"-- ============================================================================\r\n-- 38_permissions_self_check_and_rpc_contract.sql\r\n--\r\n-- الغاية: أن يحمل **المستودع نفسه** ضمانة أن أي بناء جديد (db reset / مشروع\r\n-- سحابي جديد / استعادة نسخة) يخرج بصلاحيات صحيحة ودوال قابلة للاستدعاء من\r\n-- الواجهة — لا أن تُكتشف الأخطاء يدويًا بعد كل نشر.\r\n--\r\n-- ما عولج في هذا الملف (كل بند كان عطلًا فعليًا في السحابة):\r\n--\r\n--   1) RPC الواجهة بلا EXECUTE:\r\n--      الملف 36 سحب EXECUTE من PUBLIC و anon ثم منحه لـ authenticated في حلقة،\r\n--      ثم سحبه مرة أخرى عن مجموعة أسماء داخلية — ومنها عائلة expense_*\r\n--      العامة (expense_detail / expense_lookups / list_expenses / expense_summary\r\n--      / expense_report). النتيجة: كل شاشات المصروفات ترجع 42501 «permission\r\n--      denied for function …» رغم أن RLS يسمح، لأن المنح يسبق RLS في القرار.\r\n--      القاعدة هنا: الدوال التي تستدعيها الواجهة تُنصّ صراحةً بقائمة عقد\r\n--      (CONTRACT) تُمنح بعد كل عملية سحب، فلا يمحوها ملف لاحق.\r\n--\r\n--   2) is_platform_admin بلا EXECUTE لـ authenticated:\r\n--      سُحبت في 36 ثم لم تُعد. أي واجهة تحتاج «هل أنا مسؤول منصة؟» تفشل.\r\n--\r\n--   3) الدوال التي أعاد الملفان 24–35 تعريفها (CREATE OR REPLACE) بعد المنح\r\n--      كانت ستُرث PUBLIC مرة أخرى لو لم تكن 36 قد سحبته. الآن خط الدفاع محلي:\r\n--      كل دوال public تُسحب من PUBLIC و anon، والمنح الصريح يُعاد تطبيقه.\r\n--\r\n--   4) حارس الأعمدة المعروف: generate_tax_declaration كان يقرأ invoice_date\r\n--      غير الموجود — أُصلح في 27؛ وهنا فحص بنيوي يفشل البناء إن عاد.\r\n--\r\n--   5) تحقق ذاتي شامل في نهاية الملف: أي نقص يوقف الهجرة (RAISE) بدل الصمت.\r\n--\r\n-- المرجع: supabase/MIGRATIONS_RULES.md — R-19 (idempotent) و R-24 (search_path).\r\n-- لا DML ولا TRUNCATE هنا.\r\n-- ============================================================================\r\n\r\nBEGIN","-- ── (1) الأساس: لا PUBLIC ولا anon على أي دالة في public ─────────────────────\r\n-- فحص DC2 في الملف 36 كان يُطبق على مثيل البناء حينها؛ إعادته هنا تجعله\r\n-- آخر كلمة في سلسلة الهجرات، فلا يستطيع ملف لاحق أن يفتحها بصمت.\r\nDO $$\r\nDECLARE\r\n  v_fn record;\r\nBEGIN\r\n  FOR v_fn IN\r\n    SELECT p.oid::regprocedure AS sig\r\n    FROM pg_proc p\r\n    JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'public' AND p.prokind = 'f'\r\n  LOOP\r\n    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', v_fn.sig);\r\n    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon', v_fn.sig);\r\n  END LOOP;\r\nEND $$","-- ── (2) دوال الخدمة (service_role): كل الدوال ────────────────────────────────\r\nDO $$\r\nDECLARE\r\n  v_fn record;\r\nBEGIN\r\n  FOR v_fn IN\r\n    SELECT p.oid::regprocedure AS sig\r\n    FROM pg_proc p\r\n    JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'public' AND p.prokind = 'f'\r\n  LOOP\r\n    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', v_fn.sig);\r\n  END LOOP;\r\nEND $$","-- ── (3) دوال المستخدم المسجّل: كل شيء إلا المحرّكات الداخلية ─────────────────\r\n-- المنطق: أي دالة في public يجب أن تكون قابلة للاستدعاء من authenticated\r\n-- **إلا** ما هو أداة داخلية لا يجوز أن تصلها الواجهة (محرّكات الترقيم\r\n-- التاريخية، مساعدات الحساب، حُرّاس الحذف). الخيار الافتراضي في هذه النسخة\r\n-- هو «مسموح» لأن المجموعة الضيقة في 36 سحبت من الواجهة دوالًا عامة بالخطأ،\r\n-- ولأن RLS داخل كل SECURITY DEFINER هو خط الحماية الحقيقي لا المنح.\r\n--\r\n-- ⚠️ مراجعة أمنية: ما يمنع المستخدم من فعل شيء ليس منح EXECUTE بل:\r\n--   • auth.uid() داخل كل دالة (كل هذه الدوال تتحقق من المستدعي ودوره)،\r\n--   • وفحص has_role / is_platform_superadmin قبل أي كتابة.\r\n-- أي دالة داخلية جديدة لا تتحقق من المستدعي يجب ألّا تبقى مكشوفة؛ أضف اسمها\r\n-- إلى القائمة أدناه في نفس الهجرة التي تنشئها.\r\nDO $$\r\nDECLARE\r\n  v_fn record;\r\n  v_internal text[] := ARRAY[\r\n    -- محرّكات ترقيم تاريخية تُستدعى من دوال أخرى فقط\r\n    'next_expense_reference', 'next_invoice_number', 'next_purchase_number',\r\n    'next_purchase_return_number', 'next_sales_return_number',\r\n    'next_stock_adjustment_number', 'next_stock_opening_number',\r\n    'next_supplier_voucher_number', 'next_transfer_number',\r\n    'fn_document_numbering_sequence_name',\r\n    -- حُرّاس الحذف — تُستدعى من مشغّلات، ورسائلها للمطوّر لا للمستخدم.\r\n    -- (product_reference_counts / warehouse_reference_counts ليست هنا: الواجهة\r\n    --  تستدعيها لعرض سبب منع الحذف قبل المحاولة.)\r\n    'product_delete_guard',\r\n    -- مساعدات حسابية داخلية\r\n    'expense_actor', 'expense_assert_capability',\r\n    'expense_can_write_document', 'expense_log_action',\r\n    'payment_method_seed_is_identity_owned',\r\n    'audit_item_policy_snapshot'\r\n  ];\r\nBEGIN\r\n  FOR v_fn IN\r\n    SELECT p.oid::regprocedure AS sig, p.proname\r\n    FROM pg_proc p\r\n    JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'public' AND p.prokind = 'f'\r\n  LOOP\r\n    IF v_fn.proname = ANY(v_internal) THEN\r\n      EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated', v_fn.sig);\r\n    ELSE\r\n      EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated', v_fn.sig);\r\n    END IF;\r\n  END LOOP;\r\nEND $$","-- ── (4) عقد RPC الواجهة (CONTRACT) ───────────────────────────────────────────\r\n-- هذه أسماء يستدعيها src/ عبر supabase.rpc(). تُمنح هنا مرة أخيرة صريحة حتى\r\n-- يبقى العقد مقروءًا بلا قراءة الكود، ولتصحيح أي سحب سابق.\r\nDO $$\r\nDECLARE\r\n  v_name text;\r\n  v_contract text[] := ARRAY[\r\n    -- المصروفات (كل شاشات expense_*)\r\n    'create_expense', 'update_expense', 'submit_expense', 'decide_expense',\r\n    'post_expense', 'close_expense', 'cancel_expense', 'reverse_expense',\r\n    'record_expense_payment', 'reverse_expense_payment',\r\n    'list_expenses', 'expense_detail', 'expense_summary', 'expense_report',\r\n    'expense_lookups', 'save_expense_category', 'delete_expense_category',\r\n    -- البيع والشراء والمخزون\r\n    'create_sale', 'create_sales_return', 'create_purchase',\r\n    'create_purchase_return', 'create_stock_transfer',\r\n    'post_sales_invoice', 'post_purchase_invoice',\r\n    'record_supplier_payment', 'get_supplier_statement',\r\n    'record_customer_payment', 'adjust_loyalty',\r\n    -- المحاسبة والأصول والضرائب\r\n    'create_journal_entry', 'reverse_journal_entry',\r\n    'activate_fixed_asset', 'dispose_fixed_asset',\r\n    'run_depreciation', 'run_batch_depreciation',\r\n    'run_contract_amortization', 'run_batch_amortization',\r\n    'close_fiscal_year', 'open_fiscal_year', 'set_period_status',\r\n    'generate_tax_declaration', 'settle_tax_period', 'pay_tax_settlement',\r\n    'get_chart_of_accounts_tree',\r\n    -- طرق الدفع (كتالوج المستأجر)\r\n    'create_tenant_payment_method', 'update_payment_method_identity',\r\n    'remove_tenant_payment_method',\r\n    -- البحث والنسخ الاحتياطي والترقيم\r\n    'search_products', 'backup_export_all', 'backup_restore_all',\r\n    'backup_schema_fingerprint',\r\n    'fn_next_document_number', 'fn_format_document_number',\r\n    'fn_resolve_document_numbering', 'fn_set_document_numbering',\r\n    -- مساعدات التخويل التي تستدعيها الواجهة مباشرة\r\n    'has_role', 'is_staff', 'is_platform_admin', 'is_platform_superadmin',\r\n    'can_author_payment_methods', 'can_read_finance',\r\n    'can_read_expense_entry', 'can_operate_milling', 'can_view_milling'\r\n  ];\r\n  v_fn record;\r\nBEGIN\r\n  FOREACH v_name IN ARRAY v_contract LOOP\r\n    FOR v_fn IN\r\n      SELECT p.oid::regprocedure AS sig\r\n      FROM pg_proc p\r\n      JOIN pg_namespace n ON n.oid = p.pronamespace\r\n      WHERE n.nspname = 'public' AND p.prokind = 'f' AND p.proname = v_name\r\n    LOOP\r\n      EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated', v_fn.sig);\r\n    END LOOP;\r\n  END LOOP;\r\nEND $$","-- ── (5) مساعدات تُستدعى من سياسات RLS ────────────────────────────────────────\r\n-- سياسة RLS تُنفَّذ بصلاحيات المستدعي، لذلك الدالة المستخدمة داخل USING يجب\r\n-- أن تكون قابلة للتنفيذ له — ولهذا has_role/is_staff تحمل SECURITY DEFINER\r\n-- لتقرأ user_roles رغم RLS. نؤكد المنح هنا لأن سحبه يعطّل السياسة بصمت\r\n-- (ترجع 42501 بدل صفوف) — وهو أسوأ أنواع الأعطال لأنه يشبه «لا بيانات».\r\nGRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated","GRANT EXECUTE ON FUNCTION public.is_staff(uuid) TO authenticated","GRANT EXECUTE ON FUNCTION public.is_platform_admin(uuid) TO authenticated","GRANT EXECUTE ON FUNCTION public.is_platform_superadmin(uuid) TO authenticated","-- ── (6) فحص بنيوي: لا دالة SECURITY DEFINER بلا search_path ─────────────────\r\nDO $$\r\nDECLARE\r\n  v_bad text;\r\nBEGIN\r\n  SELECT string_agg(p.proname, ', ' ORDER BY p.proname) INTO v_bad\r\n  FROM pg_proc p\r\n  JOIN pg_namespace n ON n.oid = p.pronamespace\r\n  WHERE n.nspname = 'public'\r\n    AND p.prokind = 'f'\r\n    AND p.prosecdef\r\n    AND (p.proconfig IS NULL\r\n         OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%'));\r\n\r\n  IF v_bad IS NOT NULL THEN\r\n    RAISE EXCEPTION 'SECURITY DEFINER بلا search_path ثابت: %', v_bad;\r\n  END IF;\r\nEND $$","-- ── (7) فحص بنيوي: الأعمدة التي تقرأها دوال الإقرار الضريبي موجودة ──────────\r\n-- يمنع تكرار عطل invoice_date إن أُعيد تعريف الدالة لاحقًا من نسخة قديمة.\r\n-- ⚠️ نفحص **جسم الدالة** لا تعريفها الكامل: التعليق التوثيقي في 27 يذكر\r\n--    الكلمة invoice_date شرحًا للعطل، ففحص النص كاملًا يُنتج إيجابية كاذبة\r\n--    توقف الهجرة الصحيحة. نقتطع ما بعد AS $...$ ونتجاهل أسطر التعليق.\r\nDO $$\r\nDECLARE\r\n  v_body text;\r\nBEGIN\r\n  IF to_regprocedure('public.generate_tax_declaration(date,date)') IS NULL THEN\r\n    RETURN;\r\n  END IF;\r\n\r\n  SELECT substring(pg_get_functiondef('public.generate_tax_declaration(date,date)'::regprocedure)\r\n                   FROM 'AS \\\\$[a-z]*\\\\$(.*\\\\$[a-z]*\\\\$)\\\\s*$')\r\n    INTO v_body;\r\n\r\n  v_body := regexp_replace(coalesce(v_body, ''), '--[^\\\\n]*', '', 'g');   -- أسطر التعليق\r\n  v_body := regexp_replace(v_body, '/\\\\*.*?\\\\*/', '', 'gs');               -- تعليقات كتلية\r\n\r\n  IF position('invoice_date' IN v_body) > 0\r\n     AND NOT EXISTS (\r\n       SELECT 1 FROM information_schema.columns\r\n       WHERE table_schema = 'public' AND column_name = 'invoice_date'\r\n     ) THEN\r\n    RAISE EXCEPTION\r\n      'generate_tax_declaration يقرأ invoice_date غير الموجود — أصلح تعريف الدالة (راجع 27)';\r\n  END IF;\r\nEND $$","-- ── (8) تحقق ذاتي نهائي ──────────────────────────────────────────────────────\r\nDO $$\r\nDECLARE\r\n  v_missing text;\r\n  v_anon text;\r\nBEGIN\r\n  -- 8-أ) كل دوال public قابلة للتنفيذ من authenticated إلا الداخلية\r\n  SELECT string_agg(p.proname, ', ' ORDER BY p.proname) INTO v_missing\r\n  FROM pg_proc p\r\n  JOIN pg_namespace n ON n.oid = p.pronamespace\r\n  WHERE n.nspname = 'public'\r\n    AND p.prokind = 'f'\r\n    AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')\r\n    AND p.proname NOT IN (\r\n      'next_expense_reference', 'next_invoice_number', 'next_purchase_number',\r\n      'next_purchase_return_number', 'next_sales_return_number',\r\n      'next_stock_adjustment_number', 'next_stock_opening_number',\r\n      'next_supplier_voucher_number', 'next_transfer_number',\r\n      'fn_document_numbering_sequence_name',\r\n      'product_delete_guard',\r\n      'expense_actor', 'expense_assert_capability',\r\n      'expense_can_write_document', 'expense_log_action',\r\n      'payment_method_seed_is_identity_owned',\r\n      'audit_item_policy_snapshot'\r\n    );\r\n\r\n  IF v_missing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'دوال غير قابلة للتنفيذ من authenticated: %', v_missing;\r\n  END IF;\r\n\r\n  -- 8-ب) لا دالة واحدة قابلة للتنفيذ من anon\r\n  SELECT string_agg(p.proname, ', ' ORDER BY p.proname) INTO v_anon\r\n  FROM pg_proc p\r\n  JOIN pg_namespace n ON n.oid = p.pronamespace\r\n  WHERE n.nspname = 'public'\r\n    AND p.prokind = 'f'\r\n    AND has_function_privilege('anon', p.oid, 'EXECUTE');\r\n\r\n  IF v_anon IS NOT NULL THEN\r\n    RAISE EXCEPTION 'دوال قابلة للتنفيذ من anon (يجب أن يكون صفرًا): %', v_anon;\r\n  END IF;\r\nEND $$",COMMIT,"-- ============================================================================\r\n-- التحقق اليدوي بعد التطبيق (كلها يجب أن ترجع صفر صفوف):\r\n--\r\n--   SELECT p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\r\n--    WHERE n.nspname='public' AND p.prokind='f'\r\n--      AND has_function_privilege('anon', p.oid,'EXECUTE');\r\n--\r\n--   SELECT p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\r\n--    WHERE n.nspname='public' AND p.prokind='f'\r\n--      AND NOT has_function_privilege('authenticated', p.oid,'EXECUTE')\r\n--      AND p.proname NOT LIKE 'next\\\\_%';\r\n--\r\n-- ROLLBACK: لا شيء يُعكس تلقائيًا — أعد تشغيل الهجرات السابقة، لكن ذلك يعيد\r\n--           الأعطال التي أُصلحت. لا تستخدمه إلا في بيئة تطوير.\r\n-- ============================================================================"}	permissions_self_check_and_rpc_contract
39	{"-- ============================================================================\r\n-- 39_platform_admin_repair_and_data_guard.sql\r\n--\r\n-- لماذا هجرة لا بذرة؟\r\n--   البذرة (seeds) بيانات تُشغَّل يدويًا، وهي المرجع عند **البناء الجديد**.\r\n--   لكن قاعدة موجودة (السحابة) لن تنال إصلاحًا في 06_platform_admins.sql\r\n--   بمجرد تعديل الملف. الهجرة هنا تُطبَّق تلقائيًا على كل قاعدة (db push)\r\n--   وتصلح الحالة القائمة، وتظل البذرة المرجع للبناء التالي.\r\n--\r\n-- ما تُصلحه:\r\n--   1) المستخدم الرابع (أحمد الهتار — a000…004) أُدرج في auth.users في البذرة\r\n--      لكن **بقية صفوفه ناقصة**: auth.identities (بريد + هاتف)، profiles،\r\n--      platform_admins، user_roles. النتيجة: يستطيع الدخول بكلمة المرور لكن\r\n--      لا هوية بريد/هاتف صحيحة، ولا ملف شخصي (is_staff=false)، ولا دور منصة،\r\n--      ولا دور متجر → كل الشاشات فارغة.\r\n--\r\n--   2) أي سوبر أدمن آخر ناقص الصف في platform_admins / user_roles / profiles\r\n--      يُكمَّل هنا بصلاحية واحدة: إذا كان في auth.users وبريده معروف فهو\r\n--      «حساب منصة» يجب أن يكون كاملًا.\r\n--\r\n--   3) حارس دائم: لم نعد نثق بأن البذرة تُشغَّل. أي صف في auth.users يحمل\r\n--      بريدًا من قائمة مسؤولي المنصة ولا يوجد له صف في الجداول الأربعة\r\n--      يُكتشف، ويُبنى تلقائيًا (بأقل صلاحية صحيحة: owner + superadmin فقط\r\n--      للحسابات المعروفة).\r\n--\r\n--   4) الهاتف يُخزَّن بلا \\"+\\" في auth.users (كما يكتبه GoTrue)، وفي profiles\r\n--      بصيغة + — وهذا هو ما تفعله البذرة بالضبط فنتابعه.\r\n--\r\n-- الصلاحيات: هذا الملف يكتب في auth.* و public.*، فتشغيله يحتاج postgres\r\n-- (service role / db push). لا يعمل من العميل أبدًا.\r\n--\r\n-- ثابت: كل إدراج ON CONFLICT DO NOTHING / DO UPDATE.\r\n-- ============================================================================\r\n\r\nBEGIN","-- ── (1) المستخدمون المعروفون (نفس أرقام البذرة حرفيًا) ──────────────────────\r\n-- نُعرّفهم هنا CTE مرة واحدة؛ يُستخدم في كل عبارة أدناه.\r\n-- ملاحظة: لا نُعيد كتابة كلمات المرور هنا — البذرة تفعل ذلك عند البناء.\r\n-- الحساب الموجود تبقى كلمة مروره كما هي؛ هذا الملف يُكمل **البنيان** فقط،\r\n-- فلا يستطيع إعادة تعيين كلمة مرور لأحد عرضًا.\r\nWITH known(user_id, email, phone, full_name, platform_role) AS (VALUES\r\n  ('a0000000-0000-4000-a000-000000000001'::uuid, 'mousa.mc13@gmail.com',     '+967772217218', 'موسى العواضي',  'superadmin'),\r\n  ('a0000000-0000-4000-a000-000000000002'::uuid, 'shoeabvv@gmail.com',       '+967772317950', 'يونس العفيف',   'superadmin'),\r\n  ('a0000000-0000-4000-a000-000000000003'::uuid, 'emadfasill2001@gmail.com', '+967784795104', 'عماد الجماعي',  'support'),\r\n  ('a0000000-0000-4000-a000-000000000004'::uuid, 'ahmedhetar15@gmail.com',   '+967779121636', 'أحمد الهتار',   'superadmin')\r\n)\r\n-- 1-أ) الهوية المفقودة: يُكمل auth.users لو غاب صفه أصلًا (بذرة لم تُشغَّل).\r\nINSERT INTO auth.users (\r\n  id, instance_id, aud, role, email, phone, encrypted_password,\r\n  email_confirmed_at, phone_confirmed_at,\r\n  raw_app_meta_data, raw_user_meta_data,\r\n  confirmation_token, recovery_token, email_change, email_change_token_new,\r\n  created_at, updated_at\r\n)\r\nSELECT\r\n  k.user_id,\r\n  '00000000-0000-0000-0000-000000000000'::uuid,\r\n  'authenticated', 'authenticated',\r\n  k.email, replace(k.phone, '+', ''),\r\n  -- بلا كلمة مرور قابلة للدخول: NULL يُرفض عند الدخول، فيُنشئ المالك كلمة\r\n  -- مرور عبر «نسيت كلمة المرور» بدل كلمة سر مكتوبة في المستودع.\r\n  NULL, now(), now(),\r\n  jsonb_build_object('provider', 'email', 'providers', jsonb_build_array('email', 'phone')),\r\n  jsonb_build_object('full_name', k.full_name),\r\n  '', '', '', '', now(), now()\r\nFROM known k\r\nWHERE NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = k.user_id)\r\n  AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE lower(u.email) = lower(k.email))","-- ── (2) الهويات: بريد وهاتف لكل حساب معروف ───────────────────────────────────\r\nWITH known(user_id, email, phone) AS (VALUES\r\n  ('a0000000-0000-4000-a000-000000000001'::uuid, 'mousa.mc13@gmail.com',     '+967772217218'),\r\n  ('a0000000-0000-4000-a000-000000000002'::uuid, 'shoeabvv@gmail.com',       '+967772317950'),\r\n  ('a0000000-0000-4000-a000-000000000003'::uuid, 'emadfasill2001@gmail.com', '+967784795104'),\r\n  ('a0000000-0000-4000-a000-000000000004'::uuid, 'ahmedhetar15@gmail.com',   '+967779121636')\r\n)\r\nINSERT INTO auth.identities (id, user_id, provider_id, provider, identity_data, created_at, updated_at, last_sign_in_at)\r\nSELECT gen_random_uuid(), k.user_id, k.user_id::text, 'email',\r\n       jsonb_build_object(\r\n         'sub', k.user_id::text, 'email', k.email,\r\n         'email_verified', true, 'phone_verified', true, 'phone', k.phone\r\n       ),\r\n       now(), now(), NULL\r\nFROM known k\r\nWHERE EXISTS (SELECT 1 FROM auth.users u WHERE u.id = k.user_id)\r\nON CONFLICT (provider, provider_id) DO NOTHING","WITH known(user_id, phone) AS (VALUES\r\n  ('a0000000-0000-4000-a000-000000000001'::uuid, '+967772217218'),\r\n  ('a0000000-0000-4000-a000-000000000002'::uuid, '+967772317950'),\r\n  ('a0000000-0000-4000-a000-000000000003'::uuid, '+967784795104'),\r\n  ('a0000000-0000-4000-a000-000000000004'::uuid, '+967779121636')\r\n)\r\nINSERT INTO auth.identities (id, user_id, provider_id, provider, identity_data, created_at, updated_at, last_sign_in_at)\r\nSELECT gen_random_uuid(), k.user_id, k.user_id::text, 'phone',\r\n       jsonb_build_object(\r\n         'sub', k.user_id::text,\r\n         'email_verified', false,\r\n         'phone_verified', true,\r\n         -- الرقم إلزامي في identity_data: بلا هذا الحقل لا يجد GoTrue شيئًا\r\n         -- يطابقه عند الدخول بالهاتف فيعيد invalid_credentials رغم صحة\r\n         -- الرقم وكلمة المرور (نفس إصلاح البذرة 2026-10-21).\r\n         'phone', k.phone\r\n       ),\r\n       now(), now(), NULL\r\nFROM known k\r\nWHERE EXISTS (SELECT 1 FROM auth.users u WHERE u.id = k.user_id)\r\nON CONFLICT (provider, provider_id) DO UPDATE\r\n  SET identity_data = EXCLUDED.identity_data,\r\n      updated_at    = now()","-- ⚠️ هوية هاتف قديمة موجودة مسبقًا (زرعتها نسخة أقدم بلا حقل phone في\r\n-- identity_data)? ON CONFLICT أعلاه يصلحها. وهذا التحديث الإضافي يعالج\r\n-- هوية هاتف بـ provider_id مختلف (تصميم أقدم) لم يطابق القيد:\r\nWITH known(user_id, phone) AS (VALUES\r\n  ('a0000000-0000-4000-a000-000000000001'::uuid, '+967772217218'),\r\n  ('a0000000-0000-4000-a000-000000000002'::uuid, '+967772317950'),\r\n  ('a0000000-0000-4000-a000-000000000003'::uuid, '+967784795104'),\r\n  ('a0000000-0000-4000-a000-000000000004'::uuid, '+967779121636')\r\n)\r\nUPDATE auth.identities i\r\nSET identity_data = jsonb_build_object(\r\n      'sub', k.user_id::text,\r\n      'email_verified', false,\r\n      'phone_verified', true,\r\n      'phone', k.phone\r\n    ),\r\n    updated_at = now()\r\nFROM known k\r\nWHERE i.user_id = k.user_id\r\n  AND i.provider = 'phone'\r\n  AND NOT (i.identity_data ? 'phone')","-- ملاحظة: القيد UNIQUE (provider, provider_id) يمنع صفين لنفس (user, provider).\r\n--   حسابًا قديمًا قد يحمل هوية هاتف بـ provider_id مختلف (تصميم أقدم) —\r\n--   التحديث الإضافي أعلاه يصحّح identity_data فيه بدل إدراج صف ثانٍ.\r\n\r\n-- ── (3) profiles: الملف الشخصي لكل حساب في auth.users ينتمي للمنصة ────────\r\nWITH known(user_id, full_name, phone) AS (VALUES\r\n  ('a0000000-0000-4000-a000-000000000001'::uuid, 'موسى العواضي',  '+967772217218'),\r\n  ('a0000000-0000-4000-a000-000000000002'::uuid, 'يونس العفيف',   '+967772317950'),\r\n  ('a0000000-0000-4000-a000-000000000003'::uuid, 'عماد الجماعي', '+967784795104'),\r\n  ('a0000000-0000-4000-a000-000000000004'::uuid, 'أحمد الهتار',   '+967779121636')\r\n)\r\nINSERT INTO public.profiles (id, full_name, phone, language, theme, is_active)\r\nSELECT k.user_id, k.full_name, k.phone, 'ar', 'dark', true\r\nFROM known k\r\nWHERE EXISTS (SELECT 1 FROM auth.users u WHERE u.id = k.user_id)\r\nON CONFLICT (id) DO UPDATE\r\n  SET full_name = EXCLUDED.full_name,\r\n      phone     = EXCLUDED.phone,\r\n      -- لا نغيّر is_active لحساب أوقفه المالك عن قصد: الإصلاح يُكمل الناقص،\r\n      -- لا يعيد تفعيل حساب موقوف.\r\n      is_active = COALESCE(public.profiles.is_active, true),\r\n      updated_at = now()","-- ── (4) platform_admins ─────────────────────────────────────────────────────\r\nWITH known(user_id, platform_role) AS (VALUES\r\n  ('a0000000-0000-4000-a000-000000000001'::uuid, 'superadmin'),\r\n  ('a0000000-0000-4000-a000-000000000002'::uuid, 'superadmin'),\r\n  ('a0000000-0000-4000-a000-000000000003'::uuid, 'support'),\r\n  ('a0000000-0000-4000-a000-000000000004'::uuid, 'superadmin')\r\n)\r\nINSERT INTO public.platform_admins (user_id, role, is_active, mfa_required)\r\nSELECT k.user_id, k.platform_role, true, false\r\nFROM known k\r\nWHERE EXISTS (SELECT 1 FROM auth.users u WHERE u.id = k.user_id)\r\nON CONFLICT (user_id) DO NOTHING","-- لا نرقّي/نخفّض دورًا قائمًا بقرار إداري\r\n\r\n-- ── (5) user_roles: دور المتجر (بدونه RLS يُخفي كل شيء) ─────────────────────\r\nWITH known(user_id) AS (VALUES\r\n  ('a0000000-0000-4000-a000-000000000001'::uuid),\r\n  ('a0000000-0000-4000-a000-000000000002'::uuid),\r\n  ('a0000000-0000-4000-a000-000000000003'::uuid),\r\n  ('a0000000-0000-4000-a000-000000000004'::uuid)\r\n)\r\nINSERT INTO public.user_roles (user_id, role)\r\nSELECT k.user_id, 'owner'::public.app_role\r\nFROM known k\r\nWHERE EXISTS (SELECT 1 FROM auth.users u WHERE u.id = k.user_id)\r\n  AND NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = k.user_id)\r\nON CONFLICT DO NOTHING","-- ── (6) حارس: كل صف في platform_admins يجب أن يراه is_platform_superadmin\r\n--         أو is_platform_admin كما ينص دوره، وكل سوبر أدمن له دور متجر ──────\r\nDO $$\r\nDECLARE\r\n  v_bad text;\r\nBEGIN\r\n  -- 6-أ) صف سوبر أدمن نشط لا تحقّقه الدالة\r\n  SELECT string_agg(pa.user_id::text, ', ') INTO v_bad\r\n  FROM public.platform_admins pa\r\n  WHERE pa.role = 'superadmin' AND pa.is_active\r\n    AND NOT public.is_platform_superadmin(pa.user_id);\r\n  IF v_bad IS NOT NULL THEN\r\n    RAISE EXCEPTION 'صف سوبر أدمن لا تحقّقه is_platform_superadmin: %', v_bad;\r\n  END IF;\r\n\r\n  -- 6-ب) حساب دعم يمرّ كسوبر أدمن (تسرّب صلاحيات)\r\n  SELECT string_agg(pa.user_id::text, ', ') INTO v_bad\r\n  FROM public.platform_admins pa\r\n  WHERE pa.role = 'support' AND public.is_platform_superadmin(pa.user_id);\r\n  IF v_bad IS NOT NULL THEN\r\n    RAISE EXCEPTION 'حساب دعم يحقّق is_platform_superadmin: %', v_bad;\r\n  END IF;\r\n\r\n  -- 6-ج) سوبر أدمن بلا دور متجر ولا ملف شخصي = حساب يدخل ولا يرى شيئًا\r\n  SELECT string_agg(pa.user_id::text, ', ') INTO v_bad\r\n  FROM public.platform_admins pa\r\n  WHERE NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = pa.user_id)\r\n     OR NOT EXISTS (SELECT 1 FROM public.profiles  p WHERE p.id     = pa.user_id);\r\n  IF v_bad IS NOT NULL THEN\r\n    RAISE EXCEPTION 'مسؤول منصة بلا دور متجر أو ملف شخصي: %', v_bad;\r\n  END IF;\r\nEND $$",COMMIT,"-- ============================================================================\r\n-- التحقق (المتوقع: أربعة صفوف، كل عمود true):\r\n--\r\n--   SELECT u.email,\r\n--          (SELECT count(*) FROM auth.identities i WHERE i.user_id=u.id)          AS identities,\r\n--          EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=u.id)               AS has_profile,\r\n--          EXISTS (SELECT 1 FROM public.platform_admins pa WHERE pa.user_id=u.id) AS has_platform,\r\n--          EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=u.id)        AS has_store_role,\r\n--          public.is_platform_superadmin(u.id)                                     AS is_super\r\n--     FROM auth.users u\r\n--    WHERE u.id IN ('a0000000-0000-4000-a000-000000000001','a0000000-0000-4000-a000-000000000002',\r\n--                   'a0000000-0000-4000-a000-000000000003','a0000000-0000-4000-a000-000000000004')\r\n--    ORDER BY u.email;\r\n-- ============================================================================"}	platform_admin_repair_and_data_guard
40	{"-- ============================================================================\r\n-- 40_restore_platform_admin_privileges.sql\r\n--\r\n-- إصلاح أعمق مما فعلته 38: 38 مُنحت للدور authenticated، لكن **السياسات**\r\n-- المشكوك فيها هي التي تخفي الصفوف. هذا الملف يعيد بناء نموذج الصلاحيات\r\n-- الخاص بمستخدمي المنصة من الأساس، حتى لا يعتمد سوبر أدمن على «صدفة» أن\r\n-- له دور متجر owner.\r\n--\r\n-- ما يُصلحه:\r\n--\r\n--   1) platform_admins: سياسة الإدارة كانت USING (is_platform_superadmin)\r\n--      للكتابة، و FOR ALL تشمل SELECT — أي أن سوبر أدمن لا يستطيع قراءة\r\n--      صفوف سوبر أدمن **آخرين**، ولا رؤية نفسه إن أُوقف أو غيّر دوره (لأن\r\n--      is_platform_superadmin يشترط is_active و role='superadmin').\r\n--      النتيجة العملية: شاشة «مسؤولو المنصة» تبدو فارغة للمستخدم الرابع\r\n--      قبل أن يُضاف صفه، ولو أُوقف حساب لأصبح غير مرئي ولا يمكن إصلاحه من\r\n--      الواجهة. السياسات هنا صريحة منفصلة: قراءة لمسؤول المنصة النشط، كتابة\r\n--      لسوبر أدمن نشط فقط، وقراءة ذاتية دائمًا.\r\n--\r\n--   2) profiles: لا سياسة قراءة لمسؤول المنصة على ملفات الآخرين، فيحتاج\r\n--      عرض «من الذي أنشأ القيد» إلى service_role. نضيف قراءة لمسؤول المنصة.\r\n--\r\n--   3) user_roles: نفس الفكرة — مسؤول المنصة يحتاج معرفة أدوار المنازل\r\n--      لأغراض الدعم. القراءة فقط، والكتابة تبقى لمالك المتجر.\r\n--\r\n--   4) حماية من القفل الذاتي: منع أي عملية تجعل عدد السوبر أدمن النشطين\r\n--      صفرًا (حذف/تعطيل/تخفيض الدور) — وهو أسوأ عطل ممكن في نظام متعدد\r\n--      المستأجرين، لأنه لا يوجد من يصلحه من الواجهة.\r\n--\r\n-- ثابت: كل عبارة CREATE POLICY مسبوقة بـ DROP IF EXISTS.\r\n-- ============================================================================\r\n\r\nBEGIN","-- ── (1) platform_admins ─────────────────────────────────────────────────────\r\nDROP POLICY IF EXISTS \\"platform_admins_manage\\"    ON public.platform_admins","DROP POLICY IF EXISTS \\"platform_admins_select\\"    ON public.platform_admins","DROP POLICY IF EXISTS \\"platform_admins_self_read\\" ON public.platform_admins","-- قراءة: أي مسؤول منصة نشط يرى القائمة كاملة (الكتابة تبقى محصورة).\r\nCREATE POLICY \\"platform_admins_read\\" ON public.platform_admins\r\n  AS PERMISSIVE FOR SELECT TO authenticated\r\n  USING (public.is_platform_admin(auth.uid()))","-- قراءة ذاتية دائمة: صاحب الصف يرى دوره حتى لو أُوقف (ليعرف السبب).\r\nCREATE POLICY \\"platform_admins_self_read\\" ON public.platform_admins\r\n  AS PERMISSIVE FOR SELECT TO authenticated\r\n  USING (user_id = auth.uid())","-- إدارة: سوبر أدمن نشط فقط.\r\nCREATE POLICY \\"platform_admins_insert\\" ON public.platform_admins\r\n  AS PERMISSIVE FOR INSERT TO authenticated\r\n  WITH CHECK (public.is_platform_superadmin(auth.uid()))","CREATE POLICY \\"platform_admins_update\\" ON public.platform_admins\r\n  AS PERMISSIVE FOR UPDATE TO authenticated\r\n  USING (public.is_platform_superadmin(auth.uid()))\r\n  WITH CHECK (public.is_platform_superadmin(auth.uid()))","CREATE POLICY \\"platform_admins_delete\\" ON public.platform_admins\r\n  AS PERMISSIVE FOR DELETE TO authenticated\r\n  USING (public.is_platform_superadmin(auth.uid()))","-- ── (2) profiles: قراءة إدارية لمسؤول المنصة ────────────────────────────────\r\n-- (السياسة القائمة \\"profiles read own\\" تبقى كما هي؛ هذه إضافة لا استبدال.)\r\nDROP POLICY IF EXISTS \\"platform admin reads profiles\\" ON public.profiles","CREATE POLICY \\"platform admin reads profiles\\" ON public.profiles\r\n  AS PERMISSIVE FOR SELECT TO authenticated\r\n  USING (public.is_platform_admin(auth.uid()))","-- ── (3) user_roles: قراءة إدارية لمسؤول المنصة ──────────────────────────────\r\nDROP POLICY IF EXISTS \\"platform admin reads user_roles\\" ON public.user_roles","CREATE POLICY \\"platform admin reads user_roles\\" ON public.user_roles\r\n  AS PERMISSIVE FOR SELECT TO authenticated\r\n  USING (public.is_platform_admin(auth.uid()))","-- ── (4) حماية القفل الذاتي: لا صفر سوبر أدمن ────────────────────────────────\r\n-- تُنفّذ كـ CONSTRAINT TRIGGER مؤجّل إلى نهاية المعاملة: تقدر سوبر أدمن\r\n-- واحدًا ثم تضيف آخر في نفس المعاملة (عملية استبدال مشروعة)، وترفض\r\n-- المعاملة كلها إن انتهت بصفر سوبر أدمن.\r\nCREATE OR REPLACE FUNCTION public.tg_platform_admins_keep_superadmin()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public, pg_temp\r\nAS $$\r\nDECLARE\r\n  v_remaining integer;\r\nBEGIN\r\n  SELECT count(*) INTO v_remaining\r\n  FROM public.platform_admins\r\n  WHERE role = 'superadmin' AND is_active;\r\n\r\n  IF v_remaining = 0 THEN\r\n    RAISE EXCEPTION 'PLATFORM_LOCKOUT: لا يمكن ترك المنصة بلا سوبر أدمن نشط'\r\n      USING ERRCODE = '23514',\r\n            HINT = 'أضف سوبر أدمن آخر أو فعّل الحساب قبل تعطيل الأخير';\r\n  END IF;\r\n\r\n  RETURN NULL;  -- AFTER trigger\r\nEND;\r\n$$","COMMENT ON FUNCTION public.tg_platform_admins_keep_superadmin() IS\r\n  'R-40: يمنع ترك platform_admins بلا سوبر أدمن نشط — لا يوجد من يصلحه من الواجهة إن وقع.'","REVOKE ALL ON FUNCTION public.tg_platform_admins_keep_superadmin() FROM PUBLIC, anon, authenticated","DROP TRIGGER IF EXISTS trg_platform_admins_keep_superadmin ON public.platform_admins","CREATE CONSTRAINT TRIGGER trg_platform_admins_keep_superadmin\r\n  AFTER INSERT OR UPDATE OR DELETE ON public.platform_admins\r\n  DEFERRABLE INITIALLY DEFERRED\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION public.tg_platform_admins_keep_superadmin()","-- ⚠️ ملاحظة على UPDATE/DELETE من داخل الجدول نفسه: المشغّل لا يمنع بذرة\r\n--    كاملة تُفرّغ الجدول ثم تملؤه في نفس المعاملة — وهذا هو المقصود (البذرة\r\n--    القانونية الوحيدة). ما يمنعه هو إنهاء معاملة بحالة صفر.\r\n\r\n-- ── (5) منح القراءة على الجداول الإدارية ─────────────────────────────────────\r\n-- سياسة RLS لا تعمل بلا GRANT. كان المنح موجودًا؛ نؤكده لأن 36 سحب ALL على\r\n-- كل الجداول ثم أعاد قائمة صريحة — ولم يكن platform_audit_logs فيها.\r\nGRANT SELECT, INSERT ON public.platform_audit_logs TO authenticated","GRANT SELECT ON public.platform_admins, public.platform_modules, public.platform_plans TO authenticated","GRANT SELECT, INSERT, UPDATE, DELETE ON public.platform_admins TO authenticated","-- ── (6) التحقق ──────────────────────────────────────────────────────────────\r\nDO $$\r\nBEGIN\r\n  IF (SELECT count(*) FROM public.platform_admins WHERE role = 'superadmin' AND is_active) = 0 THEN\r\n    RAISE EXCEPTION 'PLATFORM_LOCKOUT: قاعدة البيانات بلا سوبر أدمن نشط عند تطبيق 40';\r\n  END IF;\r\nEND $$",COMMIT}	restore_platform_admin_privileges
41	{"-- ============================================================================\r\n-- 41_fix_tax_declaration_and_admin_completeness.sql\r\n--\r\n-- مكمّل لـ 39/40. 39 تُصلح **البيانات** و 40 تُصلح **السياسات**، لكن قاعدة\r\n-- قائمة لا تنال تصحيحًا في 27 (تعريف الدالة) بمجرد تعديل ملف هجرة قديم.\r\n-- لذلك هذا الملف يعيد تعريف الدالة بإصداره الصحيح، ثم يفرض اكتمال حسابات\r\n-- المنصة بفحص أعمق من 39.\r\n--\r\n--   1) generate_tax_declaration: إعادة تعريف بالعمود الصحيح (created_at).\r\n--      الحالة المكتشفة: الدالة على السحابة ما تزال تقرأ sales_invoices.\r\n--      invoice_date (غير موجود) → 42703 عند كل استدعاء، فتسقط معها\r\n--      settle_tax_period أيضًا (تستدعيها داخليًا).\r\n--\r\n--   2) settle_tax_period: يعاد تعريفه بنفس فحوص 27 المصححة، ليستحيل أن\r\n--      تنتج تسوية صفرية صامتة من نطاق فارغ.\r\n--\r\n--   3) حسابات المنصة: إكمال فوري لأي صف في auth.users يملك بريدًا من قائمة\r\n--      المنصة لكنه ناقص identities/profiles/platform_admins/user_roles —\r\n--      بما في ذلك الحساب الرابع (a000…004) و أي حساب أضافه المالك لاحقًا.\r\n--\r\n--   4) دالة فحص دائمة platform_admin_audit() ترجع تقريرًا بكل نقص — يستدعيها\r\n--      الـ CLI وسكربت CI، ويمكن استدعاؤها يدويًا بعد أي نشر.\r\n--\r\n-- ثابت، ولا يغيّر كلمات المرور ولا يُفعّل حسابًا أوقفه المالك.\r\n-- ============================================================================\r\n\r\nBEGIN","-- ── (1) الإقرار الضريبي: التعريف الصحيح ─────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.generate_tax_declaration(\r\n  p_start_date date,\r\n  p_end_date   date\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user          uuid := auth.uid();\r\n  v_sales_taxable numeric(18,2) := 0;\r\n  v_output_tax    numeric(18,2) := 0;\r\n  v_purch_taxable numeric(18,2) := 0;\r\n  v_input_tax     numeric(18,2) := 0;\r\n  v_net_tax       numeric(18,2) := 0;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  IF p_start_date IS NULL OR p_end_date IS NULL THEN\r\n    RAISE EXCEPTION 'Tax declaration needs both start_date and end_date'\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n  IF p_end_date < p_start_date THEN\r\n    RAISE EXCEPTION 'Tax declaration end_date (%) is before start_date (%)', p_end_date, p_start_date\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  -- 1) ضريبة المخرجات من القيود المرحلة لحساب 2311 (رصيد دائن)\r\n  SELECT coalesce(sum(jl.credit - jl.debit), 0)\r\n    INTO v_output_tax\r\n    FROM public.journal_lines jl\r\n    JOIN public.journal_entries je ON je.id = jl.entry_id\r\n    JOIN public.accounts a ON a.id = jl.account_id\r\n   WHERE a.code = '2311'\r\n     AND je.status = 'POSTED'\r\n     AND je.source_type <> 'tax_settlement'\r\n     AND je.entry_date BETWEEN p_start_date AND p_end_date;\r\n\r\n  -- 2) ضريبة المدخلات من القيود المرحلة لحساب 1316 (رصيد مدين)\r\n  SELECT coalesce(sum(jl.debit - jl.credit), 0)\r\n    INTO v_input_tax\r\n    FROM public.journal_lines jl\r\n    JOIN public.journal_entries je ON je.id = jl.entry_id\r\n    JOIN public.accounts a ON a.id = jl.account_id\r\n   WHERE a.code = '1316'\r\n     AND je.status = 'POSTED'\r\n     AND je.source_type <> 'tax_settlement'\r\n     AND je.entry_date BETWEEN p_start_date AND p_end_date;\r\n\r\n  -- 3) إجمالي المبيعات الخاضعة للضريبة.\r\n  --    ⚠️ sales_invoices ليس فيها invoice_date. التاريخ التشغيلي هو created_at\r\n  --    (نفس ما تعتمده تقارير 12 ويومية الترحيل). المقارنة نصف مفتوحة كي لا\r\n  --    تسقط فواتير آخر يوم في الفترة.\r\n  SELECT coalesce(sum(subtotal), 0)\r\n    INTO v_sales_taxable\r\n    FROM public.sales_invoices\r\n   WHERE status = 'confirmed'\r\n     AND created_at >= p_start_date::timestamptz\r\n     AND created_at <  (p_end_date + 1)::timestamptz;\r\n\r\n  -- 4) إجمالي المشتريات في الفترة\r\n  SELECT coalesce(sum(subtotal), 0)\r\n    INTO v_purch_taxable\r\n    FROM public.purchase_invoices\r\n   WHERE status = 'confirmed'\r\n     AND created_at >= p_start_date::timestamptz\r\n     AND created_at <  (p_end_date + 1)::timestamptz;\r\n\r\n  v_net_tax := v_output_tax - v_input_tax;\r\n\r\n  RETURN jsonb_build_object(\r\n    'start_date', p_start_date,\r\n    'end_date', p_end_date,\r\n    'taxable_sales', v_sales_taxable,\r\n    'output_tax', v_output_tax,\r\n    'taxable_purchases', v_purch_taxable,\r\n    'input_tax', v_input_tax,\r\n    'net_tax_payable', v_net_tax\r\n  );\r\nEND $$","REVOKE ALL ON FUNCTION public.generate_tax_declaration(date, date) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.generate_tax_declaration(date, date) TO authenticated, service_role","COMMENT ON FUNCTION public.generate_tax_declaration(date, date) IS\r\n  'T-23: أرقام الإقرار الضريبي للفترة. تاريخ الفواتير = created_at (لا يوجد invoice_date في المخطط).'","-- ── (2) settle_tax_period: إعادة تعريف كاملة ─────────────────────────────────\r\n-- لماذا كاملة لا «فحص ثم رجاء»: الدالة SECURITY DEFINER تستدعي\r\n-- generate_tax_declaration داخليًا. لو بقيت نسخة قديمة على قاعدة قائمة\r\n-- لبقيت التسوية معطلة، ولو تركناها لفحص نصي هشّ لتعطّل البناء عند أي\r\n-- تنسيق مختلف. التعريف الكامل أدناه قطعي: نفس منطق 27 المصحح + رفض النطاق\r\n-- الفارغ + رفض التسوية الصفرية.\r\nCREATE OR REPLACE FUNCTION public.settle_tax_period(\r\n  p_start_date      date,\r\n  p_end_date        date,\r\n  p_period_number   text,\r\n  p_settlement_date date DEFAULT CURRENT_DATE\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user          uuid := auth.uid();\r\n  v_decl          jsonb;\r\n  v_output_tax    numeric(18,2);\r\n  v_input_tax     numeric(18,2);\r\n  v_net_tax       numeric(18,2);\r\n  v_sales         numeric(18,2);\r\n  v_purch         numeric(18,2);\r\n  v_lines         jsonb := '[]'::jsonb;\r\n  v_entry_id      uuid;\r\n  v_settle_id     uuid;\r\n  v_memo          text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  -- نطاق وسياق إلزاميان: بدونهما كان يُنشأ قيد تسوية بقيمة صفر (أثر كاذب).\r\n  IF p_start_date IS NULL OR p_end_date IS NULL\r\n     OR nullif(btrim(coalesce(p_period_number, '')), '') IS NULL THEN\r\n    RAISE EXCEPTION 'Tax settlement requires start_date, end_date and period_number'\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n  IF p_end_date < p_start_date THEN\r\n    RAISE EXCEPTION 'Tax settlement end_date (%) is before start_date (%)', p_end_date, p_start_date\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  IF NOT (public.has_role(v_user, 'owner')\r\n          OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may settle taxes'\r\n      USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  PERFORM public.assert_period_open(p_settlement_date);\r\n\r\n  IF EXISTS (\r\n    SELECT 1 FROM public.tax_settlement_periods\r\n     WHERE period_number = p_period_number\r\n  ) THEN\r\n    RAISE EXCEPTION 'Tax period % already exists or settled', p_period_number;\r\n  END IF;\r\n\r\n  -- قراءة أرقام الإقرار (النسخة السليمة)\r\n  v_decl := public.generate_tax_declaration(p_start_date, p_end_date);\r\n  v_sales      := (v_decl->>'taxable_sales')::numeric;\r\n  v_output_tax := (v_decl->>'output_tax')::numeric;\r\n  v_purch      := (v_decl->>'taxable_purchases')::numeric;\r\n  v_input_tax  := (v_decl->>'input_tax')::numeric;\r\n  v_net_tax    := (v_decl->>'net_tax_payable')::numeric;\r\n\r\n  IF coalesce(v_output_tax, 0) = 0 AND coalesce(v_input_tax, 0) = 0 THEN\r\n    RAISE EXCEPTION 'لا توجد حركات ضريبية مرحّلة للفترة المحددة لتسويتها'\r\n      USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  -- بناء قيد التسوية المتوازن:\r\n  IF v_output_tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '2311', 'debit', v_output_tax, 'credit', 0,\r\n        'memo', 'تسوية ضريبة المخرجات للفترة ' || p_period_number\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  IF v_input_tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '1316', 'debit', 0, 'credit', v_input_tax,\r\n        'memo', 'تسوية ضريبة المدخلات للفترة ' || p_period_number\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  IF v_net_tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '2321', 'debit', 0, 'credit', v_net_tax,\r\n        'memo', 'صافي ضريبة القيمة المضافة المستحقة للدفع — ' || p_period_number\r\n      )\r\n    );\r\n  ELSIF v_net_tax < 0 THEN\r\n    v_lines := v_lines || jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '2321', 'debit', -v_net_tax, 'credit', 0,\r\n        'memo', 'رصيد ضريبة مدخلات فائض مسترد/مرحل — ' || p_period_number\r\n      )\r\n    );\r\n  END IF;\r\n\r\n  v_memo := 'قيد التسوية والإقرار الضريبي للفترة ' || p_period_number ||\r\n            ' (' || to_char(p_start_date, 'YYYY-MM-DD') || ' إلى ' || to_char(p_end_date, 'YYYY-MM-DD') || ')';\r\n\r\n  v_entry_id := public.create_journal_entry(\r\n    v_memo, p_settlement_date, 'tax_settlement', NULL, true, v_lines, false\r\n  );\r\n\r\n  INSERT INTO public.tax_settlement_periods (\r\n    period_number, start_date, end_date, total_taxable_sales,\r\n    output_tax_amount, total_taxable_purchases, input_tax_amount,\r\n    net_tax_payable, status, journal_entry_id, settled_at, settled_by\r\n  )\r\n  VALUES (\r\n    btrim(p_period_number), p_start_date, p_end_date, v_sales,\r\n    v_output_tax, v_purch, v_input_tax,\r\n    v_net_tax, 'SETTLED', v_entry_id, now(), v_user\r\n  )\r\n  RETURNING id INTO v_settle_id;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'tax.settled', 'tax_settlement', v_settle_id,\r\n          jsonb_build_object('period_number', p_period_number, 'net_tax', v_net_tax, 'entry_id', v_entry_id));\r\n\r\n  RETURN v_settle_id;\r\nEND $$","REVOKE ALL ON FUNCTION public.settle_tax_period(date, date, text, date) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.settle_tax_period(date, date, text, date) TO authenticated, service_role","COMMENT ON FUNCTION public.settle_tax_period(date, date, text, date) IS\r\n  'T-23: قيد تسوية 2311/1316 والفرق إلى 2321. يرفض النطاق الفارغ والتسوية الصفرية.'","-- ── (3) إكمال حسابات المنصة الموجودة مسبقًا في auth.users ──────────────────\r\n-- قائمة المنصة الحقيقية: صفوف platform_admins **أو** بريد معروف. الاجتماع\r\n-- بين الشرطين يسمح بإضافة سوبر أدمن جديد من الواجهة (شاشة المنصة) ثم\r\n-- تكتمل صفوفه تلقائيًا عند أول هجرة لاحقة، بلا لمس البذرة.\r\nWITH admins AS (\r\n  SELECT u.id AS user_id,\r\n         coalesce(nullif(btrim(p.full_name), ''), split_part(u.email, '@', 1)) AS full_name,\r\n         p.phone AS phone\r\n  FROM auth.users u\r\n  LEFT JOIN public.profiles p ON p.id = u.id\r\n  WHERE u.deleted_at IS NULL\r\n    AND (\r\n      EXISTS (SELECT 1 FROM public.platform_admins pa WHERE pa.user_id = u.id)\r\n      OR lower(u.email) IN (\r\n        'mousa.mc13@gmail.com', 'shoeabvv@gmail.com',\r\n        'emadfasill2001@gmail.com', 'ahmedhetar15@gmail.com'\r\n      )\r\n    )\r\n)\r\nINSERT INTO public.profiles (id, full_name, phone, language, theme, is_active)\r\nSELECT a.user_id, a.full_name, a.phone, 'ar', 'dark', true\r\nFROM admins a\r\nON CONFLICT (id) DO UPDATE\r\n  SET full_name = COALESCE(NULLIF(btrim(public.profiles.full_name), ''), EXCLUDED.full_name),\r\n      phone     = COALESCE(public.profiles.phone, EXCLUDED.phone),\r\n      updated_at = now()","-- الهوية: بريد\r\nWITH admins AS (\r\n  SELECT u.id AS user_id, u.email\r\n  FROM auth.users u\r\n  WHERE u.deleted_at IS NULL\r\n    AND (\r\n      EXISTS (SELECT 1 FROM public.platform_admins pa WHERE pa.user_id = u.id)\r\n      OR lower(u.email) IN (\r\n        'mousa.mc13@gmail.com', 'shoeabvv@gmail.com',\r\n        'emadfasill2001@gmail.com', 'ahmedhetar15@gmail.com'\r\n      )\r\n    )\r\n)\r\nINSERT INTO auth.identities (id, user_id, provider_id, provider, identity_data, created_at, updated_at, last_sign_in_at)\r\nSELECT gen_random_uuid(), a.user_id, a.user_id::text, 'email',\r\n       jsonb_build_object('sub', a.user_id::text, 'email', a.email,\r\n                          'email_verified', true, 'phone_verified', true),\r\n       now(), now(), NULL\r\nFROM admins a\r\nON CONFLICT (provider, provider_id) DO NOTHING","-- الهوية: هاتف (فقط لمن له رقم وكلمة مرور/هوية بريد — لا هوية هاتف بلا رقم)\r\nWITH admins AS (\r\n  SELECT u.id AS user_id, u.phone\r\n  FROM auth.users u\r\n  WHERE u.deleted_at IS NULL\r\n    AND nullif(btrim(coalesce(u.phone, '')), '') IS NOT NULL\r\n    AND (\r\n      EXISTS (SELECT 1 FROM public.platform_admins pa WHERE pa.user_id = u.id)\r\n      OR lower(u.email) IN (\r\n        'mousa.mc13@gmail.com', 'shoeabvv@gmail.com',\r\n        'emadfasill2001@gmail.com', 'ahmedhetar15@gmail.com'\r\n      )\r\n    )\r\n)\r\nINSERT INTO auth.identities (id, user_id, provider_id, provider, identity_data, created_at, updated_at, last_sign_in_at)\r\nSELECT gen_random_uuid(), a.user_id, a.user_id::text, 'phone',\r\n       jsonb_build_object('sub', a.user_id::text, 'email_verified', false, 'phone_verified', true),\r\n       now(), now(), NULL\r\nFROM admins a\r\nWHERE NOT EXISTS (\r\n  SELECT 1 FROM auth.identities i\r\n  WHERE i.user_id = a.user_id AND i.provider = 'phone'\r\n)","-- دور المتجر: owner لكل مسؤول منصة (الكود يعتمد على has_role في كل سياسة)\r\nINSERT INTO public.user_roles (user_id, role)\r\nSELECT pa.user_id, 'owner'::public.app_role\r\nFROM public.platform_admins pa\r\nWHERE NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = pa.user_id)\r\nON CONFLICT DO NOTHING","-- صف المنصة: من هو مسؤول منصة **بالكود** ولم يُدرج صفه، يُدرج كـ support\r\n-- (أقل صلاحية) لا superadmin — الترقية قرار بشري من الواجهة.\r\nINSERT INTO public.platform_admins (user_id, role, is_active, mfa_required)\r\nSELECT u.id, 'support', true, false\r\nFROM auth.users u\r\nWHERE u.deleted_at IS NULL\r\n  AND lower(u.email) IN (\r\n    'mousa.mc13@gmail.com', 'shoeabvv@gmail.com',\r\n    'emadfasill2001@gmail.com', 'ahmedhetar15@gmail.com'\r\n  )\r\n  AND NOT EXISTS (SELECT 1 FROM public.platform_admins pa WHERE pa.user_id = u.id)\r\nON CONFLICT (user_id) DO NOTHING","-- ── (4) دالة الفحص الدائمة ──────────────────────────────────────────────────\r\n-- تقرير واحد يجيب: ما الذي ينقص حسابات المنصة الآن؟\r\nCREATE OR REPLACE FUNCTION public.platform_admin_audit()\r\nRETURNS TABLE (\r\n  user_id        uuid,\r\n  email          text,\r\n  platform_role  text,\r\n  is_active      boolean,\r\n  has_email_id   boolean,\r\n  has_phone_id   boolean,\r\n  has_profile    boolean,\r\n  has_store_role boolean,\r\n  is_superadmin  boolean,\r\n  problems       text[]\r\n)\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public, pg_temp\r\nAS $$\r\n  SELECT\r\n    pa.user_id,\r\n    u.email::text,\r\n    pa.role,\r\n    pa.is_active,\r\n    EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = pa.user_id AND i.provider = 'email'),\r\n    EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = pa.user_id AND i.provider = 'phone'),\r\n    EXISTS (SELECT 1 FROM public.profiles p       WHERE p.id      = pa.user_id),\r\n    EXISTS (SELECT 1 FROM public.user_roles r     WHERE r.user_id = pa.user_id),\r\n    public.is_platform_superadmin(pa.user_id),\r\n    array_remove(ARRAY[\r\n      CASE WHEN u.id IS NULL                    THEN 'missing auth.users'                END,\r\n      CASE WHEN u.deleted_at IS NOT NULL         THEN 'auth user deleted'                 END,\r\n      CASE WHEN u.email_confirmed_at IS NULL     THEN 'email not confirmed'                END,\r\n      CASE WHEN u.banned_until > now()           THEN 'auth user banned'                  END,\r\n      CASE WHEN NOT EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = pa.user_id AND i.provider = 'email')\r\n                                                 THEN 'missing email identity'            END,\r\n      CASE WHEN NOT EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = pa.user_id AND i.provider = 'phone')\r\n                                                 THEN 'missing phone identity'            END,\r\n      CASE WHEN NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = pa.user_id)\r\n                                                 THEN 'missing profile'                   END,\r\n      CASE WHEN NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = pa.user_id AND p.is_active)\r\n                                                 THEN 'profile inactive (is_staff = false)' END,\r\n      CASE WHEN NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = pa.user_id)\r\n                                                 THEN 'missing store role (RLS hides everything)' END,\r\n      CASE WHEN pa.role = 'superadmin' AND NOT public.is_platform_superadmin(pa.user_id)\r\n                                                 THEN 'superadmin row does not satisfy the predicate' END,\r\n      CASE WHEN pa.role = 'support' AND public.is_platform_superadmin(pa.user_id)\r\n                                                 THEN 'support account satisfies superadmin predicate' END\r\n    ], NULL) AS problems\r\n  FROM public.platform_admins pa\r\n  LEFT JOIN auth.users u ON u.id = pa.user_id\r\n  ORDER BY pa.role DESC, u.email;\r\n$$","COMMENT ON FUNCTION public.platform_admin_audit() IS\r\n  'تقرير اكتمال حسابات المنصة: أي مشكلة في الهوية أو الملف أو الأدوار أو تعارض الدالة. يعيد صفوفًا بلا مشاكل أيضًا (problems = {}).'","REVOKE ALL ON FUNCTION public.platform_admin_audit() FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.platform_admin_audit() TO authenticated, service_role","-- ── (5) التحقق النهائي ──────────────────────────────────────────────────────\r\nDO $$\r\nDECLARE\r\n  v_bad text;\r\nBEGIN\r\n  -- لا حساب منصة بنقص في أي عمود (عدا is_active لحساب أوقفه المالك)\r\n  SELECT string_agg(a.email || ' → ' || array_to_string(a.problems, ' | '), E'\\\\n')\r\n    INTO v_bad\r\n  FROM public.platform_admin_audit() a\r\n  WHERE a.problems <> '{}'::text[]\r\n    AND NOT ('profile inactive (is_staff = false)' = ANY (a.problems) AND a.is_active = false);\r\n  IF v_bad IS NOT NULL THEN\r\n    RAISE EXCEPTION 'حسابات منصة ناقصة بعد الإصلاح: %', E'\\\\n' || v_bad;\r\n  END IF;\r\n\r\n  -- الأربعة المعروفون: يجب أن يكونوا موجودين فعليًا\r\n  IF (SELECT count(*) FROM public.platform_admins\r\n       WHERE user_id IN ('a0000000-0000-4000-a000-000000000001',\r\n                         'a0000000-0000-4000-a000-000000000002',\r\n                         'a0000000-0000-4000-a000-000000000003',\r\n                         'a0000000-0000-4000-a000-000000000004')) < 4 THEN\r\n    RAISE EXCEPTION 'الملفات الأربعة لحسابات المنصة غير مكتملة في platform_admins';\r\n  END IF;\r\n\r\n  -- الدالة الضريبية السارية لا تقرأ عمودًا غير موجود\r\n  IF position('invoice_date' IN regexp_replace(\r\n       pg_get_functiondef('public.generate_tax_declaration(date,date)'::regprocedure),\r\n       '--[^\\\\n]*', '', 'g')) > 0 THEN\r\n    RAISE EXCEPTION 'generate_tax_declaration ما يزال يقرأ invoice_date بعد الإصلاح';\r\n  END IF;\r\nEND $$",COMMIT}	fix_tax_declaration_and_admin_completeness
43	{"-- ============================================================================\r\n-- 43_audit_remediation_delivery_blockers.sql\r\n--\r\n-- إغلاق ملاحظات تقرير ما قبل التسليم\r\n--   docs/audits/2026-10-20_vortex-erp-delivery-audit-ar.md\r\n--\r\n-- P0-1  مرتجع المبيعات مربوط بالفاتورة الأصلية: الفاتورة والحالة والعملة\r\n--       والمستودع، وبنود مقفولة، والسعر/الضريبة مشتقّان من البند، والمتبقي\r\n--       القابل للمرتجع محسوب بعد خصم المرتجعات السابقة. القيد يُنشأ لكل\r\n--       مرتجع بما فيه النقدي (بلا عميل).\r\n-- P0-2  معرّف مستند فريد لكل دفعة تصنيع/صرف مستهلكات بدل grain_item_id\r\n--       و warehouse_id، فلا يتصادم uq_journal_source_active.\r\n-- P0-3  حركة الكمية والقيمة في معاملة واحدة: apply_cost_movement يُستدعى من\r\n--       post_stock_delta نفسه، والبيع يُقيَّد بالتكلفة الفعلية لا بمرجع الصنف.\r\n-- P0-4  الخدمة الحرة (AD_HOC_SERVICE) وبند بلا item_class لا يختفيان من قيد\r\n--       الإيراد.\r\n-- P1-1  بند فاتورة أجور الطحن يحمل أساس التسعير: الكمية والسعر الوحدوي،\r\n--       والفترة المالية للاستلام (MM-YYYY) ليمكن طبع «20 كيس × 1,000».\r\n-- P1-6  العميل/المورد النقدي كيان نظامي بعلامة قاعدية: لا يظهران في الأدلة،\r\n--       ولا يُعاد تسميتهما/تعطيلهما/حذفهما، ولا تُسجَّل عليهما ذمة.\r\n-- P1-7  سطور قيود الذمم تحمل partner_type/partner_id.\r\n-- P1-8  صلاحيات دوال public: قائمة سماح صريحة بدل منح كل الدوال.\r\n--\r\n-- ملاحظات التطبيق:\r\n--   • كل الدوال مُعرَّفة هنا بالتعريف النهائي الكامل (لا تغيير توقيعات API\r\n--     خارجية)، فترتيب الهجرات اللاحق لا يعيد إدخال الأخطاء.\r\n--   • إضافي بالكامل: لا حذف لأي بيانات مالية، والـ triggers على الحركات\r\n--     مباشرة تُمنع بنفس رسائل المحرّك (post_stock_delta فقط يحرّك).\r\n-- ============================================================================\r\n\r\nBEGIN","-- ── أعمدة الكيانات النظامية ────────────────────────────────────────────────\r\nALTER TABLE public.customers\r\n  ADD COLUMN IF NOT EXISTS is_system boolean NOT NULL DEFAULT false,\r\n  ADD COLUMN IF NOT EXISTS system_key text","ALTER TABLE public.suppliers\r\n  ADD COLUMN IF NOT EXISTS is_system boolean NOT NULL DEFAULT false,\r\n  ADD COLUMN IF NOT EXISTS system_key text","-- توسيم الكيانين المزروعين فعلاً. المطابقة بالاسم مرة واحدة فقط (هجرة تثبيت)،\r\n-- وبعدها الحماية تعتمد على العلامة لا على الاسم.\r\nUPDATE public.customers\r\n   SET is_system = true, system_key = 'CASH_CUSTOMER'\r\n WHERE id = (SELECT c.id FROM public.customers c\r\n              WHERE c.name = 'عميل نقدي' OR c.system_key = 'CASH_CUSTOMER'\r\n              ORDER BY (c.system_key = 'CASH_CUSTOMER') DESC, c.created_at\r\n              LIMIT 1)\r\n   AND (system_key IS NULL OR system_key = 'CASH_CUSTOMER')","UPDATE public.suppliers\r\n   SET is_system = true, system_key = 'CASH_SUPPLIER'\r\n WHERE id = (SELECT s.id FROM public.suppliers s\r\n              WHERE s.name = 'مورد نقدي' OR s.system_key = 'CASH_SUPPLIER'\r\n              ORDER BY (s.system_key = 'CASH_SUPPLIER') DESC, s.created_at\r\n              LIMIT 1)\r\n   AND (system_key IS NULL OR system_key = 'CASH_SUPPLIER')","-- كيان نظامي واحد لكل مفتاح، ومفتاح واحد لكل صف نظامي.\r\nDO $$\r\nBEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'customers_system_key_unique') THEN\r\n    ALTER TABLE public.customers\r\n      ADD CONSTRAINT customers_system_key_unique UNIQUE (system_key);\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'suppliers_system_key_unique') THEN\r\n    ALTER TABLE public.suppliers\r\n      ADD CONSTRAINT suppliers_system_key_unique UNIQUE (system_key);\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'customers_system_flag_shape') THEN\r\n    ALTER TABLE public.customers\r\n      ADD CONSTRAINT customers_system_flag_shape CHECK (is_system = (system_key IS NOT NULL));\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'suppliers_system_flag_shape') THEN\r\n    ALTER TABLE public.suppliers\r\n      ADD CONSTRAINT suppliers_system_flag_shape CHECK (is_system = (system_key IS NOT NULL));\r\n  END IF;\r\nEND $$","CREATE INDEX IF NOT EXISTS idx_customers_is_system ON public.customers (is_system) WHERE is_system","CREATE INDEX IF NOT EXISTS idx_suppliers_is_system ON public.suppliers (is_system) WHERE is_system","COMMENT ON COLUMN public.customers.is_system IS\r\n  'P1-6: كيان نظامي (العميل النقدي) — اسمه وحالته وحذفه محمية في القاعدة، ومخفي من دليل العملاء.'","COMMENT ON COLUMN public.suppliers.is_system IS\r\n  'P1-6: كيان نظامي (المورد النقدي) — اسمه وحالته وحذفه محمية في القاعدة، ومخفي من دليل الموردين.'","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P1-6 — guards على الكيانين النظاميين\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- العلامة is_system لا تُكتب من الواجهة: أي تعديل يضعها false على صف نظامي\r\n-- (حتى من service_role) يُرفض، فلا توجد طريقة لإلغاء الحماية عبر API.\r\nCREATE OR REPLACE FUNCTION public.tg_customers_system_guard()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF TG_OP = 'DELETE' THEN\r\n    IF OLD.is_system THEN\r\n      RAISE EXCEPTION\r\n        'The system cash customer is a protected system entity and cannot be deleted'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    RETURN OLD;\r\n  END IF;\r\n\r\n  IF OLD.is_system THEN\r\n    IF NEW.is_system IS DISTINCT FROM true OR NEW.system_key IS DISTINCT FROM OLD.system_key THEN\r\n      RAISE EXCEPTION\r\n        'The system cash customer flag cannot be cleared or re-keyed'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.name IS DISTINCT FROM OLD.name THEN\r\n      RAISE EXCEPTION\r\n        'The system cash customer cannot be renamed'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.is_active IS DISTINCT FROM true THEN\r\n      RAISE EXCEPTION\r\n        'The system cash customer cannot be deactivated'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF coalesce(NEW.balance, 0) <> 0 THEN\r\n      RAISE EXCEPTION\r\n        'The system cash customer must keep a zero balance (got %)', NEW.balance\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  ELSE\r\n    IF NEW.is_system THEN\r\n      RAISE EXCEPTION\r\n        'System entities are provisioned by the seed, not created through the API'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.name IN ('عميل نقدي') THEN\r\n      RAISE EXCEPTION\r\n        'That name is reserved for the system cash customer'\r\n        USING ERRCODE = 'unique_violation';\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND $function$","DROP TRIGGER IF EXISTS tg_customers_system_guard ON public.customers","CREATE TRIGGER tg_customers_system_guard\r\n  BEFORE UPDATE OR DELETE ON public.customers\r\n  FOR EACH ROW EXECUTE FUNCTION public.tg_customers_system_guard()","CREATE OR REPLACE FUNCTION public.tg_suppliers_system_guard()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF TG_OP = 'DELETE' THEN\r\n    IF OLD.is_system THEN\r\n      RAISE EXCEPTION\r\n        'The system cash supplier is a protected system entity and cannot be deleted'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    RETURN OLD;\r\n  END IF;\r\n\r\n  IF OLD.is_system THEN\r\n    IF NEW.is_system IS DISTINCT FROM true OR NEW.system_key IS DISTINCT FROM OLD.system_key THEN\r\n      RAISE EXCEPTION\r\n        'The system cash supplier flag cannot be cleared or re-keyed'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.name IS DISTINCT FROM OLD.name THEN\r\n      RAISE EXCEPTION\r\n        'The system cash supplier cannot be renamed'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.is_active IS DISTINCT FROM true THEN\r\n      RAISE EXCEPTION\r\n        'The system cash supplier cannot be deactivated'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF coalesce(NEW.balance, 0) <> 0 THEN\r\n      RAISE EXCEPTION\r\n        'The system cash supplier must keep a zero balance (got %)', NEW.balance\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  ELSE\r\n    IF NEW.is_system THEN\r\n      RAISE EXCEPTION\r\n        'System entities are provisioned by the seed, not created through the API'\r\n        USING ERRCODE = 'restrict_violation';\r\n    END IF;\r\n    IF NEW.name IN ('مورد نقدي') THEN\r\n      RAISE EXCEPTION\r\n        'That name is reserved for the system cash supplier'\r\n        USING ERRCODE = 'unique_violation';\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND $function$","DROP TRIGGER IF EXISTS tg_suppliers_system_guard ON public.suppliers","CREATE TRIGGER tg_suppliers_system_guard\r\n  BEFORE UPDATE OR DELETE ON public.suppliers\r\n  FOR EACH ROW EXECUTE FUNCTION public.tg_suppliers_system_guard()","-- أدلة الواجهة: هل الطرف كيان نظامي؟\r\nCREATE OR REPLACE FUNCTION public.is_system_customer(p_customer_id uuid)\r\nRETURNS boolean\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\n  SELECT coalesce((SELECT c.is_system FROM public.customers c WHERE c.id = p_customer_id), false);\r\n$function$","CREATE OR REPLACE FUNCTION public.is_system_supplier(p_supplier_id uuid)\r\nRETURNS boolean\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\n  SELECT coalesce((SELECT s.is_system FROM public.suppliers s WHERE s.id = p_supplier_id), false);\r\n$function$","-- حراس النظاميين أيضاً على قيود الذمة: لا بيع آجل ولا شراء آجل ولا مرتجع\r\n-- يمكن أن يترك رصيداً عليهما.\r\nCREATE OR REPLACE FUNCTION public.tg_customer_ledger_system_guard()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF coalesce(NEW.debit, 0) - coalesce(NEW.credit, 0) <> 0 AND public.is_system_customer(NEW.customer_id) THEN\r\n    RAISE EXCEPTION\r\n      'The system cash customer can only carry settlement lines, never a credit balance'\r\n      USING ERRCODE = 'restrict_violation';\r\n  END IF;\r\n  RETURN NEW;\r\nEND $function$","DROP TRIGGER IF EXISTS tg_customer_ledger_system_guard ON public.customer_ledger","CREATE TRIGGER tg_customer_ledger_system_guard\r\n  BEFORE INSERT ON public.customer_ledger\r\n  FOR EACH ROW EXECUTE FUNCTION public.tg_customer_ledger_system_guard()","-- ════════════════════════════════════════════════════════════════════════════\r\n-- الدوال الحالية التي كانت تنادي المحرّك بلا اسم وسائط صريحة تبقى صحيحة\r\n-- (أسماء المعاملات هنا هي نفسها في القاعدة المتصلة).\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n\r\nCOMMENT ON FUNCTION public.post_stock_delta(uuid, uuid, numeric, numeric, public.stock_movement_kind, text, uuid, text, public.owner_type, uuid, public.movement_type) IS\r\n  'P0-3: المسار الوحيد لحركة المخزون — الكمية والقيمة في معاملة واحدة.'","-- المفتاح يُفتح داخل المحرّك. نضيفه إلى النسخة أعلاه بإعادة تعريف مختصرة:\r\nDROP FUNCTION IF EXISTS public.post_stock_delta(uuid, uuid, numeric, numeric, public.stock_movement_kind, text, uuid, text, public.owner_type, uuid, public.movement_type)","CREATE OR REPLACE FUNCTION public.post_stock_delta(\r\n  p_product_id uuid,\r\n  p_warehouse_id uuid,\r\n  p_signed_qty numeric,\r\n  p_unit_cost numeric DEFAULT NULL::numeric,\r\n  p_movement_kind public.stock_movement_kind DEFAULT 'ADJUSTMENT'::public.stock_movement_kind,\r\n  p_source_type text DEFAULT NULL::text,\r\n  p_source_id uuid DEFAULT NULL::uuid,\r\n  p_note text DEFAULT NULL::text,\r\n  p_owner_type public.owner_type DEFAULT 'COMPANY'::public.owner_type,\r\n  p_owner_id uuid DEFAULT NULL::uuid,\r\n  p_movement_type_legacy public.movement_type DEFAULT NULL::public.movement_type\r\n)\r\nRETURNS void\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user   uuid := auth.uid();\r\n  v_mt     public.movement_type;\r\n  v_policy public.inventory_policy;\r\n  v_nature public.item_nature;\r\n  v_before numeric;\r\n  v_after  numeric;\r\nBEGIN\r\n  -- من يستطيع تحريك المخزون: موظف مسجّل، أو سياق داخلي موثوق (auth.uid() فارغ\r\n  -- في المهام الخلفية). المحرّك نفسه لا يتحقق من الأدوار.\r\n  IF v_user IS NOT NULL AND NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n\r\n  IF p_signed_qty IS NULL OR p_signed_qty = 0 THEN\r\n    RETURN;\r\n  END IF;\r\n  IF p_product_id IS NULL OR p_warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Item and warehouse are required for a stock movement';\r\n  END IF;\r\n\r\n  v_mt := coalesce(\r\n    p_movement_type_legacy,\r\n    CASE p_movement_kind\r\n      WHEN 'RECEIPT'      THEN 'purchase'::public.movement_type\r\n      WHEN 'ISSUE'        THEN 'sale'::public.movement_type\r\n      WHEN 'TRANSFER_IN'  THEN 'transfer_in'::public.movement_type\r\n      WHEN 'TRANSFER_OUT' THEN 'transfer_out'::public.movement_type\r\n      ELSE 'adjustment'::public.movement_type\r\n    END\r\n  );\r\n\r\n  SELECT p.item_nature, public.item_effective_policy(p.id)\r\n    INTO v_nature, v_policy\r\n  FROM public.products p WHERE p.id = p_product_id;\r\n\r\n  IF v_nature = 'SERVICE' OR v_policy <> 'TRACKED' THEN\r\n    RAISE EXCEPTION\r\n      'Item % does not hold company stock (nature %, policy %)',\r\n      p_product_id, coalesce(v_nature::text, '?'), coalesce(v_policy::text, '?');\r\n  END IF;\r\n\r\n  SELECT i.quantity INTO v_before\r\n  FROM public.inventory i\r\n  WHERE i.product_id = p_product_id\r\n    AND i.warehouse_id = p_warehouse_id\r\n    AND i.owner_type = p_owner_type\r\n    AND i.owner_id IS NOT DISTINCT FROM p_owner_id\r\n  FOR UPDATE;\r\n\r\n  v_before := coalesce(v_before, 0);\r\n  v_after  := round(v_before + p_signed_qty, 3);\r\n\r\n  IF v_after < 0 AND p_owner_type = 'COMPANY' THEN\r\n    RAISE EXCEPTION\r\n      'Insufficient stock for item % in warehouse %: available %, requested %',\r\n      p_product_id, p_warehouse_id, v_before, abs(p_signed_qty)\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  INSERT INTO public.inventory\r\n    (product_id, warehouse_id, owner_type, owner_id, quantity)\r\n  VALUES\r\n    (p_product_id, p_warehouse_id, p_owner_type, p_owner_id, v_after)\r\n  ON CONFLICT (product_id, warehouse_id, owner_type, owner_id)\r\n  DO UPDATE SET quantity = EXCLUDED.quantity, updated_at = now();\r\n\r\n  PERFORM set_config('app.stock_engine', 'on', true);\r\n\r\n  INSERT INTO public.stock_movements\r\n    (product_id, warehouse_id, movement_type, quantity, unit_cost, reference,\r\n     note, created_by, movement_kind, source_type, source_id, owner_type, owner_id,\r\n     adjustment_reason)\r\n  VALUES\r\n    (p_product_id, p_warehouse_id, v_mt, p_signed_qty, p_unit_cost,\r\n     coalesce(p_source_type, '') || coalesce(':' || p_source_id::text, ''),\r\n     p_note, v_user, p_movement_kind, p_source_type, p_source_id, p_owner_type,\r\n     p_owner_id,\r\n     -- الشرط يقرأ movement_type (لا movement_kind): أي حركة adjustment تحتاج سبباً.\r\n     CASE WHEN v_mt = 'adjustment'::public.movement_type\r\n          THEN coalesce(nullif(btrim(p_note), ''), nullif(btrim(p_source_type), ''), 'Stock adjustment')\r\n          ELSE NULL END);\r\n\r\n  -- P0-3: التقييم في نفس المعاملة وبنفس المصدر — لا حركة كمية بلا قيمة.\r\n  PERFORM public.apply_cost_movement(\r\n    p_product_id => p_product_id,\r\n    p_warehouse_id => p_warehouse_id,\r\n    p_signed_qty => p_signed_qty,\r\n    p_incoming_cost => p_unit_cost,\r\n    p_source_type => p_source_type,\r\n    p_source_id => p_source_id,\r\n    p_note => p_note,\r\n    p_owner_type => p_owner_type,\r\n    p_owner_id => p_owner_id);\r\n\r\n  PERFORM set_config('app.stock_engine', 'off', true);\r\nEND $function$","DROP TRIGGER IF EXISTS tg_stock_movements_engine_only ON public.stock_movements","CREATE OR REPLACE FUNCTION public.tg_stock_movements_engine_only()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF coalesce(current_setting('app.stock_engine', true), '') = 'on' THEN\r\n    RETURN NEW;\r\n  END IF;\r\n  RAISE EXCEPTION\r\n    'Stock movements must be posted through post_stock_delta so quantity and cost stay in step'\r\n    USING ERRCODE = 'restrict_violation';\r\nEND $function$","CREATE TRIGGER tg_stock_movements_engine_only\r\n  BEFORE INSERT OR UPDATE OR DELETE ON public.stock_movements\r\n  FOR EACH ROW EXECUTE FUNCTION public.tg_stock_movements_engine_only()","-- الدوال الحالية التي كان المحرّك القديم يتحقق فيها من توفر المخزون بنفسه\r\n-- تحتاج تحديد كمّية الشركة المقفلة، والحرجة هنا: تسمية muted تُبقي التوقيع.\r\n\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- P0-3 — تكلفة البيع من الطبقة الفعلية\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- كان create_sale يمرّر products.cost_price كتكلفة الحركة، ثم يقيّد COGS بـ\r\n-- resolve_unit_cost لاحقاً. الآن: المحرّك يقيّم الحركة بالقيمة الفعلية، والحركة\r\n-- تحمل total_cost، والقيد يقرأ منه — مصدر واحد للرقم.\r\nCREATE OR REPLACE FUNCTION public.sale_line_unit_cost(p_product_id uuid, p_warehouse_id uuid)\r\nRETURNS numeric\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\n  SELECT coalesce(\r\n    public.resolve_unit_cost(p_product_id, p_warehouse_id),\r\n    (SELECT p.cost_price FROM public.products p WHERE p.id = p_product_id),\r\n    0\r\n  );\r\n$function$","-- الدالة الجذرية للبيع: نفس منطق 20 مع تعديلين —\r\n--   1) لا يُمرَّر cost_price كتكلفة للحركة (المحرّك يقيّمها بنفسه).\r\n--   2) الترحيل عبر post_sales_invoice للدوال الأخرى يبقى كما هو.\r\nCREATE OR REPLACE FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id     uuid;\r\n  v_invoice_number text;\r\n  v_user           uuid := auth.uid();\r\n  v_line           record;\r\n  v_subtotal       numeric := 0;\r\n  v_tax_total      numeric := 0;\r\n  v_discount       numeric := coalesce(_discount, 0);\r\n  v_total          numeric := 0;\r\n  v_paid           numeric := 0;\r\n  v_outstanding    numeric := 0;\r\n  v_price          numeric;\r\n  v_tax_rate       numeric;\r\n  v_customer_balance numeric;\r\n  v_credit_limit   numeric;\r\n  v_line_total     numeric;\r\n  v_line_tax       numeric;\r\n  v_effect         text;\r\n  v_line_type      text;\r\n  v_sellable       boolean;\r\n  v_status         public.invoice_status;\r\n  v_last_item_id   uuid;\r\n  v_available      numeric;\r\n  v_system         boolean := false;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to post sales';\r\n  END IF;\r\n\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'Cart is empty';\r\n  END IF;\r\n\r\n  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN\r\n    RAISE EXCEPTION 'Unsupported payment method';\r\n  END IF;\r\n\r\n  IF v_discount < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot be negative';\r\n  END IF;\r\n\r\n  IF coalesce(_paid, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Paid amount cannot be negative';\r\n  END IF;\r\n\r\n  -- ============================================================== VALIDATION\r\n  FOR v_line IN\r\n    SELECT r.o_product_id AS product_id, sum(r.o_quantity) AS quantity\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n    WHERE r.o_stock_effect = 'STOCK_ISSUE'\r\n    GROUP BY r.o_product_id\r\n    ORDER BY r.o_product_id\r\n  LOOP\r\n    SELECT i.quantity INTO v_available\r\n    FROM public.inventory i\r\n    WHERE i.product_id = v_line.product_id\r\n      AND i.warehouse_id = _warehouse_id\r\n      AND i.owner_type = 'COMPANY'\r\n      AND i.owner_id IS NULL\r\n    FOR UPDATE;\r\n\r\n    v_available := coalesce(v_available, 0);\r\n\r\n    IF v_available < v_line.quantity THEN\r\n      RAISE EXCEPTION\r\n        'Insufficient stock for item %: available %, requested %',\r\n        v_line.product_id, v_available, v_line.quantity\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  END LOOP;\r\n\r\n  FOR v_line IN\r\n    SELECT r.o_product_id    AS product_id,\r\n           r.o_quantity      AS quantity,\r\n           r.o_service_name  AS service_name,\r\n           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,\r\n           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n  LOOP\r\n    IF v_line.quantity IS NULL OR v_line.quantity <= 0 THEN\r\n      RAISE EXCEPTION 'Every sale line requires a positive quantity';\r\n    END IF;\r\n\r\n    IF v_line.product_id IS NULL THEN\r\n      IF coalesce(v_line.service_name, '') = '' THEN\r\n        RAISE EXCEPTION 'Every service line requires a description';\r\n      END IF;\r\n      IF v_line.input_price < 0 OR v_line.input_tax < 0 OR v_line.input_tax > 100 THEN\r\n        RAISE EXCEPTION 'Service line \\"%\\" has an invalid price or tax rate', v_line.service_name;\r\n      END IF;\r\n      v_price    := v_line.input_price;\r\n      v_tax_rate := v_line.input_tax;\r\n    ELSE\r\n      SELECT p.sale_price, p.tax_rate, p.is_sellable\r\n        INTO v_price, v_tax_rate, v_sellable\r\n      FROM public.products p\r\n      WHERE p.id = v_line.product_id AND p.is_active = true\r\n      FOR UPDATE;\r\n\r\n      IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Item % is not available for sale', v_line.product_id;\r\n      END IF;\r\n\r\n      IF v_sellable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as sellable', v_line.product_id;\r\n      END IF;\r\n\r\n      IF v_price < 0 OR v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n        RAISE EXCEPTION 'Item % has invalid pricing or tax configuration', v_line.product_id;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := round(v_line.quantity * v_price, 2);\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + round(v_line_total * v_tax_rate / 100, 2);\r\n  END LOOP;\r\n\r\n  v_total := round(v_subtotal + v_tax_total - v_discount, 2);\r\n  IF v_discount > v_subtotal + v_tax_total OR v_total < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot exceed the invoice amount';\r\n  END IF;\r\n\r\n  IF _customer_id IS NOT NULL THEN\r\n    SELECT balance, credit_limit, is_system\r\n      INTO v_customer_balance, v_credit_limit, v_system\r\n    FROM public.customers\r\n    WHERE id = _customer_id AND is_active = true\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Selected customer is unavailable';\r\n    END IF;\r\n  END IF;\r\n\r\n  -- Tender above the total is change, not revenue and not credit.\r\n  v_paid := least(coalesce(_paid, 0), v_total);\r\n  v_outstanding := round(v_total - v_paid, 2);\r\n\r\n  IF v_outstanding > 0 AND _customer_id IS NULL THEN\r\n    RAISE EXCEPTION 'A customer is required when the sale has an unpaid amount';\r\n  END IF;\r\n  -- P1-6: العميل النقدي لا يحمل ذمة أبداً.\r\n  IF v_outstanding > 0 AND v_system THEN\r\n    RAISE EXCEPTION\r\n      'The system cash customer cannot carry credit — select a real customer for a deferred sale'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN\r\n    RAISE EXCEPTION\r\n      'Credit limit exceeded: current balance %, requested debt %, limit %',\r\n      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);\r\n  END IF;\r\n\r\n  v_status := 'confirmed'::public.invoice_status;\r\n  v_invoice_number := public.next_invoice_number();\r\n\r\n  INSERT INTO public.sales_invoices (\r\n    invoice_number, customer_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_invoice_number, _customer_id, _warehouse_id, v_status,\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, v_discount, v_tax_total, v_total, v_paid,\r\n    _payment_method::public.payment_method, nullif(btrim(_note), ''), v_user\r\n  )\r\n    RETURNING id INTO v_invoice_id;\r\n\r\n    -- ================================================================== POSTING\r\n    FOR v_line IN\r\n      SELECT r.o_product_id   AS product_id,\r\n             r.o_quantity     AS quantity,\r\n             r.o_stock_effect AS stock_effect,\r\n             r.o_service_name AS service_name,\r\n             coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,\r\n             coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax,\r\n             nullif(btrim(coalesce(line ->> 'uom_id', '')), '')::uuid AS uom_id\r\n      FROM jsonb_array_elements(_items) AS line\r\n      CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n    LOOP\r\n      IF v_line.product_id IS NULL THEN\r\n        v_price     := v_line.input_price;\r\n        v_tax_rate  := v_line.input_tax;\r\n        v_line_type := 'AD_HOC_SERVICE';\r\n        v_effect    := 'NONE';\r\n      ELSE\r\n        SELECT p.sale_price, p.tax_rate\r\n          INTO v_price, v_tax_rate\r\n        FROM public.products p WHERE p.id = v_line.product_id;\r\n\r\n        v_line_type := public.item_line_type(v_line.product_id, false);\r\n        v_effect    := public.item_stock_effect(v_line.product_id, 'out');\r\n\r\n        IF v_effect = 'STOCK_ISSUE' THEN\r\n          PERFORM public.post_stock_delta(\r\n            p_product_id => v_line.product_id,\r\n            p_warehouse_id => _warehouse_id,\r\n            p_signed_qty => -v_line.quantity,\r\n            p_unit_cost => NULL,        -- P0-3: المحرّك يقيّم من الطبقة الفعلية\r\n            p_movement_kind => 'ISSUE'::public.stock_movement_kind,\r\n            p_source_type => 'sales_invoice',\r\n            p_source_id => v_invoice_id,\r\n            p_note => 'POS sale',\r\n            p_owner_type => 'COMPANY'::public.owner_type,\r\n            p_owner_id => NULL,\r\n            p_movement_type_legacy => 'sale'::public.movement_type\r\n          );\r\n        END IF;\r\n      END IF;\r\n\r\n      v_line_total := round(v_line.quantity * v_price, 2);\r\n      v_line_tax   := round(v_line_total * v_tax_rate / 100, 2);\r\n\r\n      INSERT INTO public.sales_invoice_items (\r\n        invoice_id, product_id, description, quantity, unit_price, discount, tax, total,\r\n        line_type, stock_effect, uom_id\r\n      )\r\n      VALUES (\r\n        v_invoice_id,\r\n        v_line.product_id,\r\n        CASE WHEN v_line.product_id IS NULL THEN v_line.service_name ELSE NULL END,\r\n        v_line.quantity, v_price, 0, v_line_tax, v_line_total + v_line_tax,\r\n        v_line_type, v_effect, v_line.uom_id\r\n      )\r\n      RETURNING id INTO v_last_item_id;\r\n\r\n      IF v_line_type = 'AD_HOC_SERVICE' THEN\r\n        INSERT INTO public.ad_hoc_service_lines (\r\n          invoice_id, invoice_item_id, description, quantity, unit_price,\r\n          discount, tax, total, created_by\r\n        )\r\n        VALUES (\r\n          v_invoice_id, v_last_item_id, v_line.service_name, v_line.quantity,\r\n          v_price, 0, v_line_tax, v_line_total + v_line_tax, v_user\r\n        );\r\n      END IF;\r\n    END LOOP;\r\n\r\n    IF v_outstanding > 0 THEN\r\n      UPDATE public.customers\r\n      SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()\r\n      WHERE id = _customer_id;\r\n\r\n      INSERT INTO public.customer_ledger (\r\n        customer_id, entry_type, debit, reference_id, reference_type,\r\n        occurred_at, created_by, source_key, note\r\n      )\r\n      VALUES (\r\n        _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',\r\n        now(), v_user, 'sale:' || v_invoice_id, 'قيد بيع آجل'\r\n      )\r\n      ON CONFLICT (source_key) DO NOTHING;\r\n    END IF;\r\n\r\n    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n    VALUES (v_user, 'sale.posted', 'sales_invoice', v_invoice_id,\r\n      jsonb_build_object(\r\n        'invoice_number', v_invoice_number,\r\n        'warehouse_id', _warehouse_id,\r\n        'customer_id', _customer_id,\r\n        'payment_method', _payment_method,\r\n        'total', v_total,\r\n        'paid', v_paid,\r\n        'outstanding', v_outstanding,\r\n        'line_count', jsonb_array_length(_items)\r\n      ));\r\n\r\n    -- الترحيل التلقائي في نفس المعاملة: لا فاتورة مؤكدة بلا قيد.\r\n    PERFORM public.post_sales_invoice(v_invoice_id);\r\n\r\n    RETURN v_invoice_id;\r\n  END $function$","COMMENT ON FUNCTION public.create_sale(uuid, uuid, text, numeric, numeric, text, jsonb) IS\r\n    'T-06 + P0-3: إنشاء فاتورة مبيعات وتقييم مخزونها وترحيلها للأستاذ في نفس المعاملة.'","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P0-4 — قيد إيراد المبيعات: لا يختفي بند خدمة\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- أسماء الوسائط في القاعدة المتصلة هي p_memo/p_entry_date/p_source_type/\r\n-- p_source_id/p_is_system/p_system_lines (أو p_lines حسب النسخة)، ووسيط الغلاف\r\n-- p_payment_method؛ لذلك كل النداءات أدناه تمرّر الوسائط بالاسم بدل الموضع.\r\n\r\nCREATE OR REPLACE FUNCTION public.ledger_account_code_for_payment_method(p_payment_method text)\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT public.payment_method_ledger_account($1);\r\n$$","COMMENT ON FUNCTION public.ledger_account_code_for_payment_method(text) IS\r\n  'الحساب الذي تُسوّى إليه طريقة الدفع في القيود. يعيد NULL للآجل، ويأتي من الكتالوج لا من قائمة مضمّنة.'","-- JOIN products كان يستبعد البند الحر (product_id = NULL) وبند الصنف الذي لم\r\n-- يُصنَّف (item_class = NULL)، فيفشل الترحيل أو يخرج بلا إيراد. الآن:\r\n--   • الخدمة الحرة تُجمع من ad_hoc_service_lines على حساب الخدمات 4311.\r\n--   • البند بلا تصنيف يذهب إلى 4111 (إيراد مبيعات) بدل أن يسقط.\r\n--   • COGS يقرأ total_cost من الحركة (P0-3) بدل resolve_unit_cost.\r\n--   • سطور الذمم تحمل partner_type/partner_id (P1-7).\r\nCREATE OR REPLACE FUNCTION public.ledger_account_code_for_payment_method(p_payment_method text)\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT public.payment_method_ledger_account($1);\r\n$$","CREATE OR REPLACE FUNCTION public.post_sales_invoice(p_invoice_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_inv     record;\r\n  v_existing uuid;\r\n  v_entry   uuid;\r\n  v_lines   jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  v_collectable numeric := 0;\r\n  v_service_total numeric := 0;\r\n  v_cost    record;\r\n  r         record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')\r\n          OR public.has_role(v_user,'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may post an invoice';\r\n  END IF;\r\n\r\n  SELECT * INTO v_inv FROM public.sales_invoices WHERE id = p_invoice_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Invoice not found';\r\n  END IF;\r\n\r\n  IF v_inv.status IN ('draft','cancelled') THEN\r\n    RAISE EXCEPTION 'Invoice % is % - only confirmed, paid or partial invoices post',\r\n      v_inv.invoice_number, v_inv.status;\r\n  END IF;\r\n\r\n  IF v_inv.paid < 0 THEN\r\n    RAISE EXCEPTION 'Invoice % carries a negative payment (%). A refund is a credit note, not a negative payment.',\r\n      v_inv.invoice_number, v_inv.paid;\r\n  END IF;\r\n  IF v_inv.paid > v_inv.total THEN\r\n    RAISE EXCEPTION 'Invoice % was paid % against a total of %. Fix the invoice before posting - a payment cannot exceed the invoice.',\r\n      v_inv.invoice_number, v_inv.paid, v_inv.total;\r\n  END IF;\r\n  IF v_inv.tax < 0 THEN\r\n    RAISE EXCEPTION 'Invoice % carries a negative tax amount', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  SELECT id INTO v_existing\r\n    FROM public.journal_entries\r\n   WHERE source_type = 'sales_invoice' AND source_id = p_invoice_id\r\n     AND status <> 'REVERSED';\r\n  IF v_existing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'Invoice % has already been posted to the ledger', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- نداء بتحويل نوع صريح: يمنع التباس اسم العمود payment_method مع الوسيط.\r\n  v_cash_acct := public.payment_method_ledger_account(v_inv.payment_method::text);\r\n  v_collectable := greatest(v_inv.total - v_inv.paid, 0);\r\n\r\n  -- ── الإيراد دائن: بند مُصنَّف حسب item_class ──\r\n  FOR r IN\r\n    SELECT coalesce(p.item_class::text, 'UNCLASSIFIED') AS bucket, sum(it.total) AS amount\r\n      FROM public.sales_invoice_items it\r\n      LEFT JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n       AND it.product_id IS NOT NULL\r\n     GROUP BY coalesce(p.item_class::text, 'UNCLASSIFIED')\r\n    HAVING sum(it.total) <> 0\r\n  LOOP\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE r.bucket\r\n                        WHEN 'BY_PRODUCT' THEN '4211'\r\n                        WHEN 'SERVICE'    THEN '4311'\r\n                        ELSE '4111' END,\r\n      'credit', round(r.amount, 2),\r\n      'memo', 'إيراد ' || r.bucket);\r\n  END LOOP;\r\n\r\n  -- ── الإيراد دائن: الخدمة الحرة (بند بلا صنف) ──\r\n  SELECT coalesce(sum(l.total), 0) INTO v_service_total\r\n    FROM public.ad_hoc_service_lines l\r\n   WHERE l.invoice_id = p_invoice_id;\r\n  IF v_service_total <> 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '4311',\r\n      'credit', round(v_service_total, 2),\r\n      'memo', 'إيراد خدمة حرة (AD_HOC_SERVICE)');\r\n  END IF;\r\n\r\n  IF jsonb_array_length(v_lines) = 0 THEN\r\n    RAISE EXCEPTION 'Invoice % has no revenue lines', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  IF v_inv.paid > 0 AND v_cash_acct IS NOT NULL THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', v_cash_acct, 'debit', round(v_inv.paid, 2),\r\n      'memo', 'تحصيل نقدي/بنكي');\r\n  END IF;\r\n  IF v_collectable > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1211', 'debit', round(v_collectable, 2),\r\n      'partner_type', 'customer', 'partner_id', v_inv.customer_id,\r\n      'memo', 'ذمم العميل ' || coalesce(v_inv.invoice_number, ''));\r\n  END IF;\r\n\r\n  IF v_inv.tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2311', 'credit', round(v_inv.tax, 2),\r\n      'memo', 'ضريبة القيمة المضافة المستحقة');\r\n  END IF;\r\n\r\n  -- ── تكلفة البضاعة التي خرجت: القيمة الفعلية من حركة المخزون نفسها ──\r\n  FOR v_cost IN\r\n    SELECT p.item_class,\r\n           sum(coalesce(m.total_cost,\r\n                        it.quantity * public.resolve_unit_cost(p.id, v_inv.warehouse_id))) AS cost\r\n      FROM public.sales_invoice_items it\r\n      JOIN public.products p ON p.id = it.product_id\r\n      LEFT JOIN LATERAL (\r\n        SELECT sm.total_cost\r\n          FROM public.stock_movements sm\r\n         WHERE sm.product_id = it.product_id\r\n           AND sm.warehouse_id = v_inv.warehouse_id\r\n           AND sm.source_type = 'sales_invoice'\r\n           AND sm.source_id = p_invoice_id\r\n           AND sm.owner_type = 'COMPANY'\r\n           AND sm.owner_id IS NULL\r\n         ORDER BY sm.created_at DESC\r\n         LIMIT 1\r\n      ) m ON true\r\n     WHERE it.invoice_id = p_invoice_id\r\n       AND it.stock_effect = 'STOCK_ISSUE'\r\n     GROUP BY p.item_class\r\n  LOOP\r\n    IF v_cost.cost IS NULL OR v_cost.cost = 0 THEN\r\n      CONTINUE;\r\n    END IF;\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE v_cost.item_class\r\n                        WHEN 'RAW_MATERIAL' THEN '1311'\r\n                        WHEN 'BY_PRODUCT'   THEN '1314'\r\n                        ELSE '1313' END,\r\n      'credit', round(v_cost.cost, 2),\r\n      'memo', 'تكلفة ' || coalesce(v_cost.item_class::text, 'UNCLASSIFIED'));\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '5111', 'debit', round(v_cost.cost, 2),\r\n      'memo', 'تكلفة البضاعة المباعة');\r\n  END LOOP;\r\n\r\n  v_entry := public.create_journal_entry(\r\n    p_memo => 'فاتورة مبيعات ' || v_inv.invoice_number,\r\n    p_entry_date => v_inv.created_at::date,\r\n    p_source_type => 'sales_invoice',\r\n    p_source_id => p_invoice_id,\r\n    p_is_system => true,\r\n    p_lines => v_lines);\r\n\r\n  RETURN v_entry;\r\nEND $$","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P0-3 — مشتريات: التكلفة الفعلية تصل للمحرّك بدل تكلفة الكرت\r\n-- ════════════════════════════════════════════════════════════════════════════\r\nCREATE OR REPLACE FUNCTION public.create_purchase(_warehouse_id uuid, _supplier_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id     uuid;\r\n  v_invoice_no     text;\r\n  v_user           uuid := auth.uid();\r\n  v_item           jsonb;\r\n  v_subtotal       numeric := 0;\r\n  v_tax_total      numeric := 0;\r\n  v_total          numeric := 0;\r\n  v_qty            numeric;\r\n  v_cost           numeric;\r\n  v_tax_rate       numeric;\r\n  v_line_total     numeric;\r\n  v_line_tax       numeric;\r\n  v_product        uuid;\r\n  v_effect         text;\r\n  v_type           text;\r\n  v_purchasable    boolean;\r\n  v_system         boolean := false;\r\n  v_supplier_balance numeric;\r\n  v_paid           numeric;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse required';\r\n  END IF;\r\n  IF _supplier_id IS NULL THEN\r\n    RAISE EXCEPTION 'Supplier required';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  ------------------------------------------------------------------ validate\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    IF v_qty IS NULL OR v_qty <= 0 THEN\r\n      RAISE EXCEPTION 'Invalid quantity';\r\n    END IF;\r\n    IF v_cost IS NULL OR v_cost < 0 THEN\r\n      RAISE EXCEPTION 'Invalid unit cost';\r\n    END IF;\r\n    IF v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n      RAISE EXCEPTION 'Invalid tax rate';\r\n    END IF;\r\n    IF (v_item ->> 'product_id') IS NOT NULL THEN\r\n      SELECT p.is_purchasable INTO v_purchasable\r\n      FROM public.products p WHERE p.id = (v_item ->> 'product_id')::uuid;\r\n\r\n      IF v_purchasable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as purchasable', v_item ->> 'product_id';\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + v_line_tax;\r\n  END LOOP;\r\n\r\n  v_total := v_subtotal + v_tax_total - coalesce(_discount, 0);\r\n  v_invoice_no := public.next_purchase_number();\r\n\r\n  SELECT balance, is_system INTO v_supplier_balance, v_system\r\n    FROM public.suppliers WHERE id = _supplier_id\r\n   FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Selected supplier is unavailable';\r\n  END IF;\r\n  IF coalesce(_paid, 0) < v_total AND v_system THEN\r\n    RAISE EXCEPTION\r\n      'The system cash supplier cannot carry a payable balance — record a paid purchase or choose a real supplier'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  v_paid := least(coalesce(_paid, 0), v_total);\r\n\r\n  INSERT INTO public.purchase_invoices (\r\n    invoice_number, supplier_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_invoice_no, _supplier_id, _warehouse_id,\r\n    'confirmed'::public.invoice_status,\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, coalesce(_discount, 0), v_tax_total, v_total, v_paid,\r\n    _payment_method::public.payment_method, nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_invoice_id;\r\n\r\n  --------------------------------------------------------------------- post\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_product  := (v_item ->> 'product_id')::uuid;\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n\r\n    SELECT r.o_line_type, r.o_stock_effect\r\n      INTO v_type, v_effect\r\n    FROM public.resolve_purchase_line(v_item) AS r;\r\n\r\n    INSERT INTO public.purchase_invoice_items (\r\n      invoice_id, product_id, quantity, unit_cost, discount, tax, total,\r\n      line_type, stock_effect\r\n    )\r\n    VALUES (\r\n      v_invoice_id, v_product, v_qty, v_cost, 0, v_line_tax, v_line_total + v_line_tax,\r\n      v_type, v_effect\r\n    );\r\n\r\n    IF v_effect = 'STOCK_RECEIPT' AND v_product IS NOT NULL THEN\r\n      PERFORM public.post_stock_delta(\r\n        p_product_id => v_product,\r\n        p_warehouse_id => _warehouse_id,\r\n        p_signed_qty => v_qty,\r\n        p_unit_cost => v_cost,\r\n        p_movement_kind => 'RECEIPT'::public.stock_movement_kind,\r\n        p_source_type => 'purchase_invoice',\r\n        p_source_id => v_invoice_id,\r\n        p_note => 'Purchase receipt',\r\n        p_owner_type => 'COMPANY'::public.owner_type,\r\n        p_owner_id => NULL,\r\n        p_movement_type_legacy => 'purchase'::public.movement_type\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF v_total - v_paid > 0 THEN\r\n    UPDATE public.suppliers\r\n    SET balance = balance + (v_total - v_paid), updated_at = now()\r\n    WHERE id = _supplier_id;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'purchase.posted', 'purchase_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_no,\r\n      'supplier_id', _supplier_id,\r\n      'warehouse_id', _warehouse_id,\r\n      'total', v_total,\r\n      'paid', v_paid,\r\n      'line_count', jsonb_array_length(_items)\r\n    ));\r\n\r\n  -- الترحيل التلقائي للأستاذ في نفس المعاملة.\r\n  PERFORM public.post_purchase_invoice(v_invoice_id);\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P0-1 — مرتجع المبيعات مربوط بالفاتورة الأصلية\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- قبل: الدالة تأخذ الصنف والكمية والسعر من الطلب مباشرة، فكان المرتجع يصنع\r\n-- مخزوناً وإيراداً من الهواء. الآن:\r\n--   • الفاتورة إلزامية وموجودة ومؤكدة (لا مرتجع على مسودة/ملغاة).\r\n--   • العميل والمستودع يُشتقان من الفاتورة، ويُرفض أي اختلاف في الطلب.\r\n--   • البنود تُقفل، والسعر والضريبة يُشتقان من بند الفاتورة.\r\n--   • الكمية المرتجعة ≤ (المبيع − المرتجعات السابقة) لكل بند، مجمّعة.\r\n--   • القيد يُنشأ دائماً — بما فيه البيع النقدي بلا عميل (الطرف النقدي).\r\nCREATE OR REPLACE FUNCTION public.create_sales_return(\r\n  _invoice_id uuid,\r\n  _warehouse_id uuid,\r\n  _customer_id uuid,\r\n  _refund_method text,\r\n  _note text,\r\n  _items jsonb\r\n)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_id        uuid;\r\n  v_no        text;\r\n  v_user      uuid := auth.uid();\r\n  v_item      jsonb;\r\n  v_sub       numeric := 0;\r\n  v_tax       numeric := 0;\r\n  v_tot       numeric := 0;\r\n  v_qty       numeric;\r\n  v_price     numeric;\r\n  v_tr        numeric;\r\n  v_lt        numeric;\r\n  v_ltax      numeric;\r\n  v_p         uuid;\r\n  v_effect    text;\r\n  v_type      text;\r\n  v_entry     uuid;\r\n  v_lines     jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  r           record;\r\n  v_debits    numeric := 0;\r\n  v_credits   numeric := 0;\r\n  v_inv       record;\r\n  v_sold      numeric;\r\n  v_returned  numeric;\r\n  v_bad       record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF _invoice_id IS NULL THEN\r\n    RAISE EXCEPTION 'A sales return must be linked to its original invoice';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n  IF _refund_method IS NULL\r\n     OR NOT (_refund_method::public.payment_method = ANY (ARRAY['cash','card','bank_transfer','mobile_money','split']::public.payment_method[])) THEN\r\n    RAISE EXCEPTION 'A return refund method cannot be credit — pick the account the money leaves from';\r\n  END IF;\r\n\r\n  -- ── الفاتورة الأصلية: مقفولة، مؤكدة، وبطرفيها ───────────────────────────\r\n  SELECT * INTO v_inv FROM public.sales_invoices WHERE id = _invoice_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Original invoice % does not exist', _invoice_id;\r\n  END IF;\r\n  IF v_inv.status IN ('draft', 'cancelled') THEN\r\n    RAISE EXCEPTION 'Invoice % is % - a return needs a confirmed sale', v_inv.invoice_number, v_inv.status;\r\n  END IF;\r\n  IF _customer_id IS NOT NULL AND v_inv.customer_id IS DISTINCT FROM _customer_id THEN\r\n    RAISE EXCEPTION 'The return customer does not match the invoice customer';\r\n  END IF;\r\n  IF _warehouse_id IS NOT NULL AND v_inv.warehouse_id IS DISTINCT FROM _warehouse_id THEN\r\n    RAISE EXCEPTION 'A return must go back to the invoice warehouse (%)', v_inv.warehouse_id;\r\n  END IF;\r\n\r\n  -- ── السعر والضريبة من بند الفاتورة، والكمية ضد المتبقي القابل للمرتجع ───\r\n  FOR r IN\r\n    SELECT (src.item ->> 'product_id')::uuid AS product_id,\r\n           sum(coalesce((src.item ->> 'quantity')::numeric, 0)) AS quantity\r\n      FROM jsonb_array_elements(_items) AS src(item)\r\n     GROUP BY (src.item ->> 'product_id')::uuid\r\n  LOOP\r\n    IF r.product_id IS NULL THEN\r\n      RAISE EXCEPTION 'A sales return line must reference a catalogue item';\r\n    END IF;\r\n    IF coalesce(r.quantity, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every returned line needs a positive quantity';\r\n    END IF;\r\n\r\n    SELECT coalesce(sum(it.quantity), 0) INTO v_sold\r\n      FROM public.sales_invoice_items it\r\n     WHERE it.invoice_id = _invoice_id AND it.product_id = r.product_id;\r\n\r\n    IF v_sold <= 0 THEN\r\n      RAISE EXCEPTION 'Item % is not on invoice %', r.product_id, v_inv.invoice_number;\r\n    END IF;\r\n\r\n    SELECT coalesce(sum(ri.quantity), 0) INTO v_returned\r\n      FROM public.sales_return_items ri\r\n      JOIN public.sales_returns sr ON sr.id = ri.return_id\r\n     WHERE sr.invoice_id = _invoice_id AND ri.product_id = r.product_id;\r\n\r\n    IF v_returned + r.quantity > v_sold THEN\r\n      RAISE EXCEPTION\r\n        'Return exceeds what was sold for item %: sold %, already returned %, requested %',\r\n        r.product_id, v_sold, v_returned, r.quantity\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- ── المجاميع من بنود الفاتورة، لا من الطلب ─────────────────────────────\r\n  FOR r IN\r\n    WITH req AS (\r\n      SELECT (src.item ->> 'product_id')::uuid AS product_id,\r\n             sum(coalesce((src.item ->> 'quantity')::numeric, 0)) AS quantity\r\n        FROM jsonb_array_elements(_items) AS src(item)\r\n       GROUP BY (src.item ->> 'product_id')::uuid\r\n    ),\r\n    sold AS (\r\n      SELECT sit.product_id,\r\n             sum(sit.unit_price * sit.quantity) / nullif(sum(sit.quantity), 0) AS unit_price,\r\n             sum(sit.tax) / nullif(sum(sit.quantity), 0) AS unit_tax\r\n        FROM public.sales_invoice_items sit\r\n       WHERE sit.invoice_id = _invoice_id\r\n       GROUP BY sit.product_id\r\n    )\r\n    SELECT req.product_id, req.quantity, sold.unit_price, sold.unit_tax\r\n      FROM req LEFT JOIN sold ON sold.product_id = req.product_id\r\n  LOOP\r\n    v_sub := v_sub + round(coalesce(r.unit_price, 0) * r.quantity, 2);\r\n    v_tax := v_tax + round(coalesce(r.unit_tax, 0) * r.quantity, 2);\r\n  END LOOP;\r\n\r\n  -- خصم الفاتورة موزّعاً بنسبة قيمة المرتجع، فلا يعود العميل مديناً بخصم لم يُعَد.\r\n  IF coalesce(v_inv.subtotal, 0) > 0 AND coalesce(v_inv.discount, 0) > 0 THEN\r\n    v_tot := round(v_sub * (1 - least(1, v_inv.discount / v_inv.subtotal)) + v_tax, 2);\r\n  ELSE\r\n    v_tot := round(v_sub + v_tax, 2);\r\n  END IF;\r\n  IF v_tot <= 0 THEN\r\n    RAISE EXCEPTION 'The return value must be greater than zero';\r\n  END IF;\r\n\r\n  v_no := public.next_sales_return_number();\r\n\r\n  INSERT INTO public.sales_returns (\r\n    return_number, invoice_id, customer_id, warehouse_id,\r\n    subtotal, tax, total, refund_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_no, _invoice_id, coalesce(_customer_id, v_inv.customer_id), v_inv.warehouse_id,\r\n    round(v_sub, 2), round(v_tax, 2), v_tot, _refund_method::public.payment_method,\r\n    nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR r IN\r\n    SELECT (src.item ->> 'product_id')::uuid AS product_id,\r\n           sum(coalesce((src.item ->> 'quantity')::numeric, 0)) AS quantity\r\n      FROM jsonb_array_elements(_items) AS src(item)\r\n     GROUP BY (src.item ->> 'product_id')::uuid\r\n  LOOP\r\n    v_p   := r.product_id;\r\n    v_qty := r.quantity;\r\n\r\n    SELECT sum(it.unit_price * it.quantity) / nullif(sum(it.quantity), 0),\r\n           sum(it.tax) / nullif(sum(it.quantity), 0)\r\n      INTO v_price, v_ltax\r\n      FROM public.sales_invoice_items it\r\n     WHERE it.invoice_id = _invoice_id AND it.product_id = v_p;\r\n\r\n    v_price := round(coalesce(v_price, 0), 2);\r\n    v_lt    := round(v_qty * v_price, 2);\r\n    v_ltax  := round(coalesce(v_ltax, 0) * v_qty, 2);\r\n\r\n    v_type   := public.item_line_type(v_p, false);\r\n    v_effect := public.item_stock_effect(v_p, 'in');\r\n\r\n    INSERT INTO public.sales_return_items (\r\n      return_id, product_id, quantity, unit_price, tax, total, line_type\r\n    )\r\n    VALUES (v_id, v_p, v_qty, v_price, v_ltax, v_lt + v_ltax, v_type);\r\n\r\n    IF v_effect = 'STOCK_RECEIPT' THEN\r\n      PERFORM public.post_stock_delta(\r\n        p_product_id => v_p,\r\n        p_warehouse_id => v_inv.warehouse_id,\r\n        p_signed_qty => v_qty,\r\n        p_unit_cost => NULL,   -- التقييم بمتوسط الطبقة (P0-3)\r\n        p_movement_kind => 'RECEIPT'::public.stock_movement_kind,\r\n        p_source_type => 'sales_return',\r\n        p_source_id => v_id,\r\n        p_note => 'Sales return ' || v_no,\r\n        p_owner_type => 'COMPANY'::public.owner_type,\r\n        p_owner_id => NULL,\r\n        p_movement_type_legacy => 'sale_return'::public.movement_type\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- العميل فقط إن كان للفاتورة عميل. النقدي يُسوّى على الصندوق/البنك في القيد.\r\n  IF v_inv.customer_id IS NOT NULL THEN\r\n    UPDATE public.customers\r\n    SET balance = round(coalesce(balance, 0) - v_tot, 2), updated_at = now()\r\n    WHERE id = v_inv.customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, credit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      v_inv.customer_id, 'return', round(v_tot, 2), v_id, 'sales_return',\r\n      now(), v_user, 'return:' || v_id, 'مرتجع مبيعات'\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  -- ── القيد: يعكس إيراد البيع وضريبته وCOGS، وللفاتورة النقدية يخرج نقداً ──\r\n  FOR r IN\r\n    SELECT coalesce(p.item_class::text, 'UNCLASSIFIED') AS bucket,\r\n           sum(ri.total - coalesce(ri.tax, 0)) AS net_amount\r\n      FROM public.sales_return_items ri\r\n      LEFT JOIN public.products p ON p.id = ri.product_id\r\n     WHERE ri.return_id = v_id\r\n     GROUP BY coalesce(p.item_class::text, 'UNCLASSIFIED')\r\n    HAVING sum(ri.total - coalesce(ri.tax, 0)) <> 0\r\n  LOOP\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE r.bucket\r\n                        WHEN 'BY_PRODUCT' THEN '4211'\r\n                        WHEN 'SERVICE'    THEN '4311'\r\n                        ELSE '4111' END,\r\n      'debit', round(r.net_amount, 2),\r\n      'memo', 'مرتجع إيراد ' || r.bucket);\r\n  END LOOP;\r\n\r\n  IF v_tax <> 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2311', 'debit', round(v_tax, 2),\r\n      'memo', 'عكس ضريبة القيمة المضافة');\r\n  END IF;\r\n\r\n  v_cash_acct := public.payment_method_ledger_account(_refund_method::text);\r\n  IF v_cash_acct IS NOT NULL THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', v_cash_acct, 'credit', round(v_tot, 2),\r\n      'memo', 'استرداد للعميل');\r\n  ELSE\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1211', 'credit', round(v_tot, 2),\r\n      'partner_type', 'customer', 'partner_id', v_inv.customer_id,\r\n      'memo', 'عكس ذم العميل');\r\n  END IF;\r\n\r\n  -- عكس COGS بقيمة الحركة الفعلية التي أعادتها post_stock_delta.\r\n  FOR r IN\r\n    SELECT p.item_class,\r\n           sum(coalesce(sm.total_cost, 0)) AS cost\r\n      FROM public.sales_return_items ri\r\n      JOIN public.products p ON p.id = ri.product_id\r\n      LEFT JOIN public.stock_movements sm\r\n        ON sm.product_id = ri.product_id\r\n       AND sm.source_type = 'sales_return'\r\n       AND sm.source_id = v_id\r\n       AND sm.warehouse_id = v_inv.warehouse_id\r\n     WHERE ri.return_id = v_id\r\n       AND public.item_stock_effect(ri.product_id, 'in') = 'STOCK_RECEIPT'\r\n     GROUP BY p.item_class\r\n  LOOP\r\n    IF r.cost IS NULL OR r.cost = 0 THEN\r\n      CONTINUE;\r\n    END IF;\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE r.item_class\r\n                        WHEN 'RAW_MATERIAL' THEN '1311'\r\n                        WHEN 'BY_PRODUCT'   THEN '1314'\r\n                        ELSE '1313' END,\r\n      'debit', round(r.cost, 2),\r\n      'memo', 'مرتجع مخزون ' || r.item_class);\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '5111', 'credit', round(r.cost, 2),\r\n      'memo', 'عكس تكلفة البضاعة المباعة');\r\n  END LOOP;\r\n\r\n  SELECT coalesce(sum((ln->>'debit')::numeric), 0),\r\n         coalesce(sum((ln->>'credit')::numeric), 0)\r\n    INTO v_debits, v_credits\r\n    FROM jsonb_array_elements(v_lines) AS ln;\r\n\r\n  IF v_debits > 0 OR v_credits > 0 THEN\r\n    v_entry := public.balance_and_post_return(\r\n      p_memo => 'مرتجع مبيعات ' || v_no,\r\n      p_date => CURRENT_DATE,\r\n      p_source_type => 'sales_return',\r\n      p_source_id => v_id,\r\n      p_lines => v_lines);\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'sales_return.posted', 'sales_return', v_id,\r\n    jsonb_build_object(\r\n      'return_number', v_no,\r\n      'invoice_id', _invoice_id,\r\n      'customer_id', v_inv.customer_id,\r\n      'total', v_tot,\r\n      'journal_entry_id', v_entry\r\n    ));\r\n\r\n  RETURN v_id;\r\nEND $function$","COMMENT ON FUNCTION public.create_sales_return(uuid, uuid, uuid, text, text, jsonb) IS\r\n  'P0-1: مرتجع مبيعات مربوط بفاتورته الأصلية — بنود مقفولة، كميات مرتجعة محسوبة، وسعر وضريبة من الفاتورة.'","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P0-2 — مصدر فريد لكل دفعة تصنيع وكل عملية صرف مستهلكات\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- كان القيد يُنسب إلى grain_item_id (التصنيع) أو warehouse_id (الصرف)،\r\n-- فيمنع uq_journal_source_active الدفعة الثانية لنفس القمح أو ثاني صرف من نفس\r\n-- المستودع. الآن كل عملية تحمل معرّف مستند خاصاً بها (v_doc_id)، وهو نفسه\r\n-- source_id لحركات المخزون والقيد، والمرجع النصي الظاهر يبقى في الملاحظة\r\n-- وفي payload سجل التدقيق.\r\nCREATE OR REPLACE FUNCTION public.smart_manufacture(\r\n  _warehouse_id uuid,\r\n  _grain_item_id uuid,\r\n  _grain_qty numeric,\r\n  _outputs jsonb,\r\n  _notes text\r\n)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_ref text;\r\n  v_doc_id uuid := gen_random_uuid();\r\n  v_output_value numeric := 0;\r\n  v_grain_cost numeric;\r\n  v_total_input_cost numeric;\r\n  v_total_output_qty numeric := 0;\r\n  v_waste_qty numeric := 0;\r\n  v_waste_cost numeric := 0;\r\n  v_allocatable_cost numeric := 0;\r\n  v_total_allocated numeric := 0;\r\n  v_line_allocated numeric;\r\n  v_line_idx int := 0;\r\n  v_outputs_count int;\r\n  r record;\r\n  v_last_out numeric;\r\n  v_journal_lines jsonb := '[]'::jsonb;\r\n  v_acct_code text;\r\n  v_item_name text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to run smart manufacture';\r\n  END IF;\r\n  IF _warehouse_id IS NULL OR _grain_item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse and grain item are required';\r\n  END IF;\r\n  IF coalesce(_grain_qty, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'Grain quantity must be positive';\r\n  END IF;\r\n  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN\r\n    RAISE EXCEPTION 'At least one output line is required';\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active\r\n  ) THEN\r\n    RAISE EXCEPTION 'Input must be an active RAW_MATERIAL grain';\r\n  END IF;\r\n\r\n  v_outputs_count := jsonb_array_length(_outputs);\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL OR coalesce(r.qty, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every output line needs an item and a positive quantity';\r\n    END IF;\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM public.products\r\n      WHERE id = r.item_id AND item_class IN ('FINISHED_GOOD', 'BY_PRODUCT') AND is_active\r\n    ) THEN\r\n      RAISE EXCEPTION 'Outputs must be FINISHED_GOOD or BY_PRODUCT items';\r\n    END IF;\r\n\r\n    SELECT coalesce(r.qty, 0) * coalesce(sale_price, 0) INTO v_last_out\r\n    FROM public.products WHERE id = r.item_id;\r\n\r\n    v_output_value := v_output_value + coalesce(v_last_out, 0);\r\n    v_total_output_qty := v_total_output_qty + coalesce(r.qty, 0);\r\n  END LOOP;\r\n\r\n  IF v_output_value <= 0 THEN\r\n    RAISE EXCEPTION 'Outputs must have sale prices to allocate cost by relative value';\r\n  END IF;\r\n\r\n  IF v_total_output_qty > _grain_qty THEN\r\n    RAISE EXCEPTION 'Total output weight (%) cannot exceed input grain weight (%)',\r\n      v_total_output_qty, _grain_qty;\r\n  END IF;\r\n\r\n  -- تكلفة القمح من طبقات التكلفة الفعلية أو كتالوج التكلفة\r\n  SELECT coalesce(\r\n    (SELECT sum(cl.quantity * cl.last_unit_cost) / nullif(sum(cl.quantity), 0)\r\n       FROM public.item_cost_layers cl\r\n      WHERE cl.product_id = _grain_item_id AND cl.quantity > 0\r\n        AND cl.owner_type = 'COMPANY'),\r\n    (SELECT cost_price FROM public.products WHERE id = _grain_item_id),\r\n    0\r\n  ) INTO v_grain_cost;\r\n\r\n  v_total_input_cost := round(coalesce(_grain_qty, 0) * coalesce(v_grain_cost, 0), 2);\r\n  v_ref := 'SM-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\r\n\r\n  v_waste_qty := greatest(0, coalesce(_grain_qty, 0) - v_total_output_qty);\r\n  IF v_waste_qty > 0 AND v_grain_cost > 0 THEN\r\n    v_waste_cost := round(v_waste_qty * v_grain_cost, 2);\r\n  ELSE\r\n    v_waste_cost := 0;\r\n  END IF;\r\n\r\n  v_allocatable_cost := greatest(0, v_total_input_cost - v_waste_cost);\r\n\r\n  -- 1) صادر القمح (ينقص المخزون ويقيَّم بنفس المعاملة)\r\n  PERFORM public.post_stock_delta(\r\n    p_product_id => _grain_item_id,\r\n    p_warehouse_id => _warehouse_id,\r\n    p_signed_qty => -coalesce(_grain_qty, 0),\r\n    p_unit_cost => v_grain_cost,\r\n    p_movement_kind => 'PRODUCTION'::public.stock_movement_kind,\r\n    p_source_type => 'smart_manufacture',\r\n    p_source_id => v_doc_id,\r\n    p_note => 'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n    p_owner_type => 'COMPANY'::public.owner_type,\r\n    p_owner_id => NULL,\r\n    p_movement_type_legacy => 'production_out'::public.movement_type);\r\n\r\n  -- 2) وارد النواتج بتكلفة موزعة وبناء أطراف القيد المدين للنواتج\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)\r\n  LOOP\r\n    DECLARE\r\n      v_line_value numeric;\r\n      v_unit_cost numeric;\r\n      v_item_class text;\r\n    BEGIN\r\n      v_line_idx := v_line_idx + 1;\r\n      SELECT coalesce(r.qty, 0) * coalesce(sale_price, 0), item_class, coalesce(name_ar, name)\r\n        INTO v_line_value, v_item_class, v_item_name\r\n      FROM public.products WHERE id = r.item_id;\r\n\r\n      IF v_line_idx = v_outputs_count THEN\r\n        v_line_allocated := v_allocatable_cost - v_total_allocated;\r\n      ELSE\r\n        v_line_allocated := round(v_allocatable_cost * (coalesce(v_line_value, 0) / v_output_value), 2);\r\n        v_total_allocated := v_total_allocated + v_line_allocated;\r\n      END IF;\r\n\r\n      v_unit_cost := round(v_line_allocated / nullif(coalesce(r.qty, 0), 0), 4);\r\n\r\n      PERFORM public.post_stock_delta(\r\n        p_product_id => r.item_id,\r\n        p_warehouse_id => _warehouse_id,\r\n        p_signed_qty => coalesce(r.qty, 0),\r\n        p_unit_cost => v_unit_cost,\r\n        p_movement_kind => 'PRODUCTION'::public.stock_movement_kind,\r\n        p_source_type => 'smart_manufacture',\r\n        p_source_id => v_doc_id,\r\n        p_note => 'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n        p_owner_type => 'COMPANY'::public.owner_type,\r\n        p_owner_id => NULL,\r\n        p_movement_type_legacy => 'production_in'::public.movement_type);\r\n\r\n      IF v_item_class = 'BY_PRODUCT' THEN\r\n        v_acct_code := '1314';\r\n      ELSE\r\n        v_acct_code := '1313';\r\n      END IF;\r\n\r\n      IF v_line_allocated > 0 THEN\r\n        v_journal_lines := v_journal_lines || jsonb_build_object(\r\n          'account_code', v_acct_code,\r\n          'debit', v_line_allocated,\r\n          'credit', 0,\r\n          'memo', 'إنتاج مخزون ' || v_item_name || ' (' || v_ref || ')'\r\n        );\r\n      END IF;\r\n    END;\r\n  END LOOP;\r\n\r\n  IF v_waste_cost > 0 THEN\r\n    v_journal_lines := v_journal_lines || jsonb_build_object(\r\n      'account_code', '5921',\r\n      'debit', v_waste_cost,\r\n      'credit', 0,\r\n      'memo', 'فاقد وتلف تشغيلي مطحنة (' || v_ref || ')'\r\n    );\r\n  END IF;\r\n\r\n  IF v_total_input_cost > 0 THEN\r\n    v_journal_lines := v_journal_lines || jsonb_build_object(\r\n      'account_code', '1311',\r\n      'debit', 0,\r\n      'credit', v_total_input_cost,\r\n      'memo', 'سحب قمح خام للتصنيع (' || v_ref || ')'\r\n    );\r\n\r\n    PERFORM public.create_journal_entry(\r\n      p_memo => 'تصنيع ذكي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n      p_entry_date => CURRENT_DATE,\r\n      p_source_type => 'smart_manufacture',\r\n      p_source_id => v_doc_id,   -- P0-2: معرّف الدفعة لا معرّف صنف القمح\r\n      p_is_system => true,\r\n      p_lines => v_journal_lines\r\n    );\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'manufacture.smart', 'stock_movements', v_doc_id,\r\n    jsonb_build_object(\r\n      'doc_id', v_doc_id,\r\n      'ref', v_ref,\r\n      'warehouse_id', _warehouse_id,\r\n      'grain_item_id', _grain_item_id,\r\n      'grain_qty', coalesce(_grain_qty, 0),\r\n      'grain_unit_cost', v_grain_cost,\r\n      'waste_qty', v_waste_qty,\r\n      'waste_cost', v_waste_cost,\r\n      'total_cost', v_total_input_cost,\r\n      'outputs', _outputs,\r\n      'allocation', 'RELATIVE_SALES_VALUE'\r\n    ));\r\n\r\n  RETURN v_ref;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.consume_internal_supplies(\r\n  _warehouse_id uuid,\r\n  _lines jsonb,\r\n  _notes text\r\n)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_ref text;\r\n  v_doc_id uuid := gen_random_uuid();\r\n  r record;\r\n  v_unit_cost numeric;\r\n  v_line_cost numeric;\r\n  v_total_cost numeric := 0;\r\n  v_journal_lines jsonb := '[]'::jsonb;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to issue internal consumables';\r\n  END IF;\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN\r\n    RAISE EXCEPTION 'At least one consumable line is required';\r\n  END IF;\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, qty numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL OR coalesce(r.qty, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every line needs an item and a positive quantity';\r\n    END IF;\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM public.products\r\n      WHERE id = r.item_id AND item_class IN ('NON_STOCK_ITEM', 'PACKAGING') AND is_active\r\n    ) THEN\r\n      RAISE EXCEPTION 'Only consumable (NON_STOCK_ITEM / PACKAGING) items may be issued here';\r\n    END IF;\r\n  END LOOP;\r\n\r\n  v_ref := 'CS-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, qty numeric)\r\n  LOOP\r\n    SELECT coalesce(\r\n      (SELECT sum(cl.quantity * cl.last_unit_cost) / nullif(sum(cl.quantity), 0)\r\n         FROM public.item_cost_layers cl\r\n        WHERE cl.product_id = r.item_id AND cl.quantity > 0\r\n          AND cl.owner_type = 'COMPANY'),\r\n      (SELECT cost_price FROM public.products WHERE id = r.item_id),\r\n      0\r\n    ) INTO v_unit_cost;\r\n\r\n    v_line_cost := round(coalesce(r.qty, 0) * coalesce(v_unit_cost, 0), 2);\r\n    v_total_cost := v_total_cost + v_line_cost;\r\n\r\n    PERFORM public.post_stock_delta(\r\n      p_product_id => r.item_id,\r\n      p_warehouse_id => _warehouse_id,\r\n      p_signed_qty => -coalesce(r.qty, 0),\r\n      p_unit_cost => v_unit_cost,\r\n      p_movement_kind => 'ISSUE'::public.stock_movement_kind,\r\n      p_source_type => 'internal_consumables',\r\n      p_source_id => v_doc_id,\r\n      p_note => 'صرف مستهلكات داخلي ' || v_ref || coalesce(' — ' || _notes, ''),\r\n      p_owner_type => 'COMPANY'::public.owner_type,\r\n      p_owner_id => NULL,\r\n      p_movement_type_legacy => 'adjustment'::public.movement_type);\r\n    -- شرط stock_movements_adjustment_reason_required: سبب الحركة إلزامي.\r\n    UPDATE public.stock_movements\r\n       SET adjustment_reason = coalesce(adjustment_reason, 'Internal consumables ' || v_ref)\r\n     WHERE source_type = 'internal_consumables' AND source_id = v_doc_id\r\n       AND adjustment_reason IS NULL;\r\n  END LOOP;\r\n\r\n  IF v_total_cost > 0 THEN\r\n    v_journal_lines := jsonb_build_array(\r\n      jsonb_build_object(\r\n        'account_code', '5316',\r\n        'debit', v_total_cost,\r\n        'credit', 0,\r\n        'memo', 'مصروف مواد تعبئة وتغليف مستهلكة (' || v_ref || ')'\r\n      ),\r\n      jsonb_build_object(\r\n        'account_code', '1315',\r\n        'debit', 0,\r\n        'credit', v_total_cost,\r\n        'memo', 'منصرف مخزون مواد التعبئة (' || v_ref || ')'\r\n      )\r\n    );\r\n\r\n    PERFORM public.create_journal_entry(\r\n      p_memo => 'صرف مستهلكات تعبئة وتشغيل ' || v_ref || coalesce(' — ' || _notes, ''),\r\n      p_entry_date => CURRENT_DATE,\r\n      p_source_type => 'consume_internal_supplies',\r\n      p_source_id => v_doc_id,  -- P0-2: معرّف العملية لا معرّف المستودع\r\n      p_is_system => true,\r\n      p_lines => v_journal_lines\r\n    );\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'consumables.issued', 'stock_movement', v_doc_id,\r\n    jsonb_build_object(\r\n      'doc_id', v_doc_id,\r\n      'ref', v_ref,\r\n      'warehouse_id', _warehouse_id,\r\n      'lines', _lines,\r\n      'total_cost', v_total_cost,\r\n      'notes', _notes\r\n    ));\r\n\r\n  RETURN v_ref;\r\nEND $function$","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P1-1 — أساس التسعير في فاتورة أجور الطحن\r\n-- ════════════════════════════════════════════════════════════════════════════\r\nALTER TABLE public.milling_service_documents\r\n  ADD COLUMN IF NOT EXISTS billing_basis text,\r\n  ADD COLUMN IF NOT EXISTS fee_per_unit numeric(14,2),\r\n  ADD COLUMN IF NOT EXISTS fee_quantity numeric(14,3)","COMMENT ON COLUMN public.milling_service_documents.billing_basis IS\r\n  'P1-1: أساس التسعير — PER_BAG (أجرة الكيس × عدد الأكياس) أو PER_KG (أجرة الكيلو × الوزن).'","COMMENT ON COLUMN public.milling_service_documents.fee_per_unit IS\r\n  'P1-1: سعر الوحدة المتعاقد عليه (للكيس أو للكيلو) في هذا المستند.'","COMMENT ON COLUMN public.milling_service_documents.fee_quantity IS\r\n  'P1-1: الكمية المسعّرة (عدد الأكياس أو الكيلوجرامات) التي ضُربت في fee_per_unit.'","-- بند الفاتورة يحمل نفس الأساس، فتظهر «20 كيس × 1,000» في أي قالب طباعة.\r\nCREATE OR REPLACE FUNCTION public.create_milling_service_document(\r\n  _customer_id uuid,\r\n  _warehouse_id uuid,\r\n  _grain_item_id uuid,\r\n  _bags numeric,\r\n  _kg numeric,\r\n  _service_item_id uuid,\r\n  _service_unit_price numeric,\r\n  _discount numeric,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _notes text\r\n)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_document_id uuid;\r\n  v_document_number text;\r\n  v_invoice_id uuid;\r\n  v_invoice_number text;\r\n  v_subtotal numeric;\r\n  v_total numeric;\r\n  v_paid numeric;\r\n  v_outstanding numeric;\r\n  v_customer_balance numeric;\r\n  v_credit_limit numeric;\r\n  v_period text := to_char(coalesce(current_date, now()::date), 'MM-YYYY');\r\n  v_basis text;\r\n  v_fee_qty numeric;\r\n  v_fee_per_unit numeric;\r\n  v_description text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to create milling service documents';\r\n  END IF;\r\n  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _grain_item_id IS NULL\r\n     OR _service_item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Customer, warehouse, grain and service are required';\r\n  END IF;\r\n  IF coalesce(_bags, 0) <= 0 AND coalesce(_kg, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'Record at least one bag or a positive weight';\r\n  END IF;\r\n  IF coalesce(_bags, 0) < 0 OR coalesce(_kg, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Quantities cannot be negative';\r\n  END IF;\r\n  IF coalesce(_service_unit_price, 0) < 0 OR coalesce(_discount, 0) < 0\r\n     OR coalesce(_paid, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Service price, discount and paid amount cannot be negative';\r\n  END IF;\r\n  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN\r\n    RAISE EXCEPTION 'Unsupported payment method';\r\n  END IF;\r\n\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active\r\n  ) THEN\r\n    RAISE EXCEPTION 'Intake item must be an active RAW_MATERIAL grain';\r\n  END IF;\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _service_item_id AND item_class = 'SERVICE' AND is_active AND is_sellable\r\n  ) THEN\r\n    RAISE EXCEPTION 'Milling fee item must be an active sellable SERVICE';\r\n  END IF;\r\n\r\n  SELECT balance, credit_limit\r\n    INTO v_customer_balance, v_credit_limit\r\n  FROM public.customers\r\n  WHERE id = _customer_id AND is_active = true\r\n  FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Selected customer is unavailable';\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = _warehouse_id AND is_active) THEN\r\n    RAISE EXCEPTION 'Selected warehouse is unavailable';\r\n  END IF;\r\n\r\n  v_subtotal := round(coalesce(_service_unit_price, 0), 2);\r\n  v_total := round(v_subtotal - coalesce(_discount, 0), 2);\r\n  IF v_total < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot exceed the service fee';\r\n  END IF;\r\n  v_paid := least(round(coalesce(_paid, 0), 2), v_total);\r\n  v_outstanding := round(v_total - v_paid, 2);\r\n  IF _payment_method = 'credit' AND v_paid <> 0 THEN\r\n    RAISE EXCEPTION 'Credit payment method requires zero paid amount';\r\n  END IF;\r\n  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN\r\n    RAISE EXCEPTION\r\n      'Credit limit exceeded: current balance %, requested debt %, limit %',\r\n      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);\r\n  END IF;\r\n\r\n  -- P1-1: أساس التسعير يُخزَّن بدل دفنه في كمية 1 وسعر إجمالي.\r\n  IF coalesce(_bags, 0) > 0 THEN\r\n    v_basis       := 'PER_BAG';\r\n    v_fee_qty     := round(_bags, 3);\r\n    v_fee_per_unit := round(v_subtotal / _bags, 2);\r\n    v_description := format(\r\n      'أجور طحن وتجهيز — %s كيس × %s (فترة الاستلام %s)',\r\n      trim(to_char(_bags, 'FM999999990.###')),\r\n      trim(to_char(v_fee_per_unit, 'FM999999990.00')),\r\n      v_period);\r\n  ELSE\r\n    v_basis       := 'PER_KG';\r\n    v_fee_qty     := round(_kg, 3);\r\n    v_fee_per_unit := round(v_subtotal / nullif(_kg, 0), 2);\r\n    v_description := format(\r\n      'أجور طحن وتجهيز — %s كجم × %s (فترة الاستلام %s)',\r\n      trim(to_char(_kg, 'FM999999990.###')),\r\n      trim(to_char(v_fee_per_unit, 'FM999999990.00')),\r\n      v_period);\r\n  END IF;\r\n\r\n  v_invoice_number := public.next_invoice_number();\r\n  INSERT INTO public.sales_invoices (\r\n    invoice_number, customer_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  ) VALUES (\r\n    v_invoice_number, _customer_id, _warehouse_id, 'confirmed',\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, round(coalesce(_discount, 0), 2), 0, v_total, v_paid,\r\n    _payment_method::public.payment_method, nullif(btrim(_notes), ''), v_user\r\n  ) RETURNING id INTO v_invoice_id;\r\n\r\n  INSERT INTO public.sales_invoice_items (\r\n    invoice_id, product_id, description, quantity, unit_price, discount, tax, total,\r\n    line_type, stock_effect\r\n  ) VALUES (\r\n    v_invoice_id, _service_item_id, v_description, v_fee_qty, v_fee_per_unit,\r\n    0, 0, v_subtotal, 'SERVICE', 'NONE'\r\n  );\r\n\r\n  IF v_outstanding > 0 THEN\r\n    UPDATE public.customers\r\n    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()\r\n    WHERE id = _customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, debit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    ) VALUES (\r\n      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',\r\n      now(), v_user, 'sale:' || v_invoice_id, 'قيد أجور طحن آجل'\r\n    ) ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  PERFORM public.post_sales_invoice(v_invoice_id);\r\n\r\n  v_document_number := 'MT-' || to_char(now(), 'YYYYMM') || '-' ||\r\n    lpad(nextval('public.milling_document_seq')::text, 4, '0');\r\n  INSERT INTO public.milling_service_documents (\r\n    document_number, customer_id, warehouse_id, sales_invoice_id, created_by,\r\n    billing_basis, fee_per_unit, fee_quantity\r\n  ) VALUES (\r\n    v_document_number, _customer_id, _warehouse_id, v_invoice_id, v_user,\r\n    v_basis, v_fee_per_unit, v_fee_qty\r\n  ) RETURNING id INTO v_document_id;\r\n\r\n  INSERT INTO public.custody_ledger (\r\n    customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n    bags_in, kg_in, milling_document_id, notes, created_by\r\n  ) VALUES (\r\n    _customer_id, _warehouse_id, 'INTAKE', _grain_item_id, v_document_number,\r\n    coalesce(_bags, 0), coalesce(_kg, 0), v_document_id, _notes, v_user\r\n  );\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'milling.service_document.created', 'milling_service_documents', v_document_id,\r\n    jsonb_build_object(\r\n      'document_number', v_document_number,\r\n      'invoice_id', v_invoice_id,\r\n      'invoice_number', v_invoice_number,\r\n      'customer_id', _customer_id,\r\n      'grain_item_id', _grain_item_id,\r\n      'bags', coalesce(_bags, 0),\r\n      'kg', coalesce(_kg, 0),\r\n      'billing_basis', v_basis,\r\n      'fee_per_unit', v_fee_per_unit,\r\n      'fee_quantity', v_fee_qty,\r\n      'service_total', v_total,\r\n      'paid', v_paid,\r\n      'outstanding', v_outstanding,\r\n      'stock_impact', 'NONE — customer custody'\r\n    ));\r\n\r\n  RETURN jsonb_build_object(\r\n    'document_id', v_document_id,\r\n    'document_number', v_document_number,\r\n    'invoice_id', v_invoice_id,\r\n    'invoice_number', v_invoice_number,\r\n    'billing_basis', v_basis,\r\n    'fee_per_unit', v_fee_per_unit,\r\n    'fee_quantity', v_fee_qty\r\n  );\r\nEND $function$","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P1-8 — صلاحيات دوال public: قائمة سماح صريحة\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- كان 38 يمنح authenticated تنفيذ *كل* دوال public إلا قائمة استثناءات قصيرة،\r\n-- فكان أي محرّك داخلي جديد يُفتح بالخطأ (post_stock_delta و apply_cost_movement\r\n-- نفساهما كانا في هذه المجموعة قبل سحبهما يدوياً).\r\n-- هنا القاعدة معكوسة: لا تنفيذ ل authenticated إلا لما في القائمة أدناه.\r\n-- أي RPC جديد للواجهة يُضاف هنا في نفس الهجرة التي ينشئه.\r\nDO $$\r\nDECLARE\r\n  v_allowed text[] := ARRAY[\r\n    -- بيع وشراء ومخزون\r\n    'create_sale', 'create_sales_return', 'create_purchase', 'create_purchase_return',\r\n    'create_stock_transfer', 'post_sales_invoice', 'post_purchase_invoice',\r\n    'search_products', 'item_line_type', 'item_stock_effect', 'item_effective_policy',\r\n    'item_has_stock_history', 'resolve_unit_cost', 'receive_stock',\r\n    -- دفعات وذمم\r\n    'record_customer_payment', 'record_supplier_payment', 'get_supplier_statement',\r\n    'adjust_loyalty', 'customer_credit_limit_allows',\r\n    -- أمانات المطحنة (تستدعيها واجهة الكاونتر مباشرة)\r\n    'custody_intake', 'custody_milling', 'custody_deliver', 'custody_adjust',\r\n    'custody_balances', 'custody_link_invoice',\r\n    -- تقييم الحركات: internal engine تُستدعى من شاشات التوريد والتسوية بنفسها\r\n    'post_stock_delta',\r\n    -- مطحنة وأمانات\r\n    'create_milling_service_document', 'smart_manufacture', 'consume_internal_supplies',\r\n    'milling_custody_intake', 'milling_custody_issue_milling', 'milling_custody_deliver',\r\n    'milling_custody_adjust', 'can_operate_milling', 'can_view_milling',\r\n    -- محاسبة وأصول وضرائب\r\n    'create_journal_entry', 'reverse_journal_entry', 'get_chart_of_accounts_tree',\r\n    'activate_fixed_asset', 'dispose_fixed_asset', 'run_depreciation',\r\n    'run_batch_depreciation', 'run_contract_amortization', 'run_batch_amortization',\r\n    'close_fiscal_year', 'open_fiscal_year', 'set_period_status',\r\n    'generate_tax_declaration', 'settle_tax_period', 'pay_tax_settlement',\r\n    -- مصروفات\r\n    'create_expense', 'update_expense', 'submit_expense', 'decide_expense',\r\n    'post_expense', 'close_expense', 'cancel_expense', 'reverse_expense',\r\n    'record_expense_payment', 'reverse_expense_payment',\r\n    'list_expenses', 'expense_detail', 'expense_summary', 'expense_report',\r\n    'expense_lookups', 'save_expense_category', 'delete_expense_category',\r\n    -- طرق الدفع والأطراف\r\n    'create_tenant_payment_method', 'update_payment_method_identity',\r\n    'remove_tenant_payment_method', 'can_author_payment_methods',\r\n    'payment_method_ledger_account', 'ledger_account_code_for_payment_method',\r\n    'is_system_customer', 'is_system_supplier',\r\n    -- نسخ احتياطي وترقيم ومساعدات\r\n    'backup_export_all', 'backup_restore_all', 'backup_schema_fingerprint',\r\n    'fn_next_document_number', 'fn_format_document_number',\r\n    'fn_resolve_document_numbering', 'fn_set_document_numbering',\r\n    'has_role', 'is_staff', 'is_platform_admin', 'is_platform_superadmin',\r\n    'can_read_finance', 'can_read_expense_entry',\r\n    'product_reference_counts', 'warehouse_reference_counts'\r\n  ];\r\n  v_name text;\r\nBEGIN\r\n  -- سحب شامل أولاً، ثم منح القائمة فقط. نستبعد أيضاً صلاحية PUBLIC الافتراضية\r\n  -- لأن كل دور جديد يرثها، فلا يكفي سحبها من authenticated وحده.\r\n  FOR v_name IN\r\n    SELECT p.oid::regprocedure::text\r\n    FROM pg_proc p\r\n    JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'public' AND p.prokind = 'f'\r\n  LOOP\r\n    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, authenticated', v_name);\r\n  END LOOP;\r\n\r\n  FOR v_name IN\r\n    SELECT p.oid::regprocedure::text\r\n    FROM pg_proc p\r\n    JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'public' AND p.prokind = 'f' AND p.proname = ANY (v_allowed)\r\n  LOOP\r\n    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated', v_name);\r\n  END LOOP;\r\nEND $$","-- فحص ذاتي: المحرّكات الداخلية يجب أن تبقى غير قابلة للاستدعاء من الواجهة.\r\n-- ملاحظة: proacl فارغ = صلاحية PUBLIC الافتراضية في PostgreSQL، وهي لا تمنح\r\n-- شيئاً هنا لأن كل مستدعي المحرّك SECURITY DEFINER يعمل بصلاحيات المالك.\r\n-- post_stock_delta مسموحة عمداً: شاشتا التوريد والتسوية تنادينها مباشرة\r\n-- (توقّف الكتابة المباشرة على inventory/stock_movements).\r\nDO $$\r\nDECLARE\r\n  v_leak text;\r\nBEGIN\r\n  SELECT string_agg(p.proname, ', ' ORDER BY p.proname) INTO v_leak\r\n  FROM pg_proc p\r\n  JOIN pg_namespace n ON n.oid = p.pronamespace\r\n  WHERE n.nspname = 'public'\r\n    AND p.prokind = 'f'\r\n    AND has_function_privilege('authenticated', p.oid, 'EXECUTE')\r\n    AND p.proname IN (\r\n      'apply_cost_movement', 'next_invoice_number',\r\n      'next_journal_number', 'product_delete_guard',\r\n      'tg_stock_movements_engine_only', 'tg_customers_system_guard',\r\n      'tg_suppliers_system_guard', 'tg_customer_ledger_system_guard'\r\n    );\r\n\r\n  IF v_leak IS NOT NULL THEN\r\n    RAISE EXCEPTION 'محرّكات داخلية مكشوفة للمستخدم المسجّل: %', v_leak;\r\n  END IF;\r\n\r\nEND $$",COMMIT,"-- ════════════════════════════════════════════════════════════════════════════\r\n-- تصحيح النداءات على دالة حساب طريقة الدفع\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- ⚠️ لا نعيد تعريف payment_method_ledger_account هنا: هي دالة قائمة وسليمة،\r\n-- وإعادة تعريفها من هذا الملف كانت ستستبدلها بنسخة مُخمَّنة. التصحيح المطلوب\r\n-- هو فقط التأكد من أن كل المستدعيين ينادونها موضعياً، وقد تم ذلك أعلاه.\r\n\r\n-- نُسقط الغلاف ونعيده بنفس التوقيع، فيدخل التغيير على وظيفة جديدة بدل\r\n-- تعديل جسم قديم محفوظ في الذاكرة المؤقتة.\r\nDO $$\r\nDECLARE\r\n  v_sig text;\r\nBEGIN\r\n  FOR v_sig IN\r\n    SELECT p.oid::regprocedure::text\r\n    FROM pg_proc p\r\n    WHERE p.pronamespace = 'public'::regnamespace\r\n      AND p.proname = 'ledger_account_code_for_payment_method'\r\n  LOOP\r\n    EXECUTE format('DROP FUNCTION IF EXISTS %s', v_sig);\r\n  END LOOP;\r\nEND $$","CREATE OR REPLACE FUNCTION public.ledger_account_code_for_payment_method(p_payment_method text)\r\nRETURNS text\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\n  SELECT public.payment_method_ledger_account($1);\r\n$$","CREATE OR REPLACE FUNCTION public.post_purchase_invoice(p_invoice_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_inv     record;\r\n  v_existing uuid;\r\n  v_entry   uuid;\r\n  v_lines   jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  v_owed     numeric := 0;\r\n  r         record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')\r\n          OR public.has_role(v_user,'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may post a purchase invoice';\r\n  END IF;\r\n\r\n  SELECT * INTO v_inv FROM public.purchase_invoices WHERE id = p_invoice_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Purchase invoice not found';\r\n  END IF;\r\n\r\n  IF v_inv.status IN ('draft','cancelled') THEN\r\n    RAISE EXCEPTION 'Purchase % is % - only confirmed, paid or partial invoices post',\r\n      v_inv.invoice_number, v_inv.status;\r\n  END IF;\r\n\r\n  IF v_inv.paid < 0 THEN\r\n    RAISE EXCEPTION 'Purchase % carries a negative payment (%). A supplier return is a return document, not a negative payment.',\r\n      v_inv.invoice_number, v_inv.paid;\r\n  END IF;\r\n  IF v_inv.paid > v_inv.total THEN\r\n    RAISE EXCEPTION 'Purchase % was paid % against a total of %. Fix the invoice before posting - a payment cannot exceed the invoice.',\r\n      v_inv.invoice_number, v_inv.paid, v_inv.total;\r\n  END IF;\r\n\r\n  SELECT id INTO v_existing\r\n    FROM public.journal_entries\r\n   WHERE source_type = 'purchase_invoice' AND source_id = p_invoice_id\r\n     AND status <> 'REVERSED';\r\n  IF v_existing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'Purchase % has already been posted to the ledger', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- P0: نداء موضعي على المصدر مباشرة، فلا يتأثر بأي اسم وسيط.\r\n  v_cash_acct := public.payment_method_ledger_account(v_inv.payment_method::text);\r\n  v_owed := greatest(v_inv.total - v_inv.paid, 0);\r\n\r\n  FOR r IN\r\n    SELECT coalesce(p.item_class::text, 'UNCLASSIFIED') AS item_class,\r\n           coalesce(it.stock_effect, 'NONE') AS effect,\r\n           sum(it.total)                     AS amount,\r\n           sum(it.tax)                       AS line_tax\r\n      FROM public.purchase_invoice_items it\r\n      LEFT JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n     GROUP BY coalesce(p.item_class::text, 'UNCLASSIFIED'), coalesce(it.stock_effect, 'NONE')\r\n    HAVING sum(it.total) <> 0 OR sum(it.tax) <> 0\r\n  LOOP\r\n    IF r.amount <> 0 THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', CASE\r\n          WHEN r.effect <> 'STOCK_RECEIPT' THEN '5911'\r\n          ELSE CASE r.item_class\r\n                 WHEN 'RAW_MATERIAL'  THEN '1311'\r\n                 WHEN 'BY_PRODUCT'    THEN '1314'\r\n                 WHEN 'FINISHED_GOOD' THEN '1313'\r\n                 ELSE '1315' END END,\r\n        'debit', round(r.amount, 2),\r\n        'memo', CASE WHEN r.effect <> 'STOCK_RECEIPT'\r\n                     THEN 'مصروف مشتريات ' || r.item_class\r\n                     ELSE 'شراء ' || r.item_class END);\r\n    END IF;\r\n\r\n    IF r.line_tax <> 0 THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '1316', 'debit', round(r.line_tax, 2),\r\n        'memo', 'ضريبة مدخلات قابلة للاسترداد');\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF v_inv.tax <> 0 AND NOT EXISTS (\r\n       SELECT 1 FROM public.purchase_invoice_items it\r\n        WHERE it.invoice_id = p_invoice_id AND it.tax <> 0) THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1316', 'debit', round(v_inv.tax, 2),\r\n      'memo', 'ضريبة مدخلات قابلة للاسترداد');\r\n  END IF;\r\n\r\n  IF jsonb_array_length(v_lines) = 0 THEN\r\n    RAISE EXCEPTION 'Purchase % has nothing to post - its lines are empty or zero',\r\n      v_inv.invoice_number;\r\n  END IF;\r\n\r\n  IF v_owed > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2111', 'credit', round(v_owed, 2),\r\n      'memo', 'مستحق للمورد',\r\n      'partner_type', 'supplier',\r\n      'partner_id', v_inv.supplier_id);\r\n  END IF;\r\n\r\n  IF v_inv.paid > 0 AND v_cash_acct IS NOT NULL THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', v_cash_acct, 'credit', round(v_inv.paid, 2),\r\n      'memo', 'سداد للمورد');\r\n  END IF;\r\n\r\n  v_entry := public.create_journal_entry(\r\n    p_memo => 'فاتورة مشتريات ' || v_inv.invoice_number,\r\n    p_entry_date => v_inv.created_at::date,\r\n    p_source_type => 'purchase_invoice',\r\n    p_source_id => p_invoice_id,\r\n    p_is_system => true,\r\n    p_lines => v_lines);\r\n\r\n  RETURN v_entry;\r\nEND $$","-- ════════════════════════════════════════════════════════════════════════════\r\n-- نسخة create_sale(date) — نفس الجسم، مع الحفاظ على تاريخ البيع\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- هذه النسخة كانت تحتفظ بجسم قديم يشير إلى payment_method_ledger_account\r\n-- باسم وسيط غير موجود. نعيد تعريفها لتستدعي النسخة الجذرية ثم تضبط التاريخ.\r\nCREATE OR REPLACE FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb, _sale_date date)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id uuid;\r\n  v_posted_at  timestamptz;\r\nBEGIN\r\n  IF _sale_date IS NULL THEN\r\n    RAISE EXCEPTION 'Sale date is required';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'Cart is empty';\r\n  END IF;\r\n\r\n  v_invoice_id := public.create_sale(\r\n    _warehouse_id, _customer_id, _payment_method, _paid, _discount, _note, _items\r\n  );\r\n\r\n  v_posted_at := _sale_date::timestamp + localtime;\r\n\r\n  UPDATE public.sales_invoices\r\n  SET created_at = v_posted_at, updated_at = now()\r\n  WHERE id = v_invoice_id;\r\n\r\n  UPDATE public.stock_movements\r\n  SET created_at = v_posted_at\r\n  WHERE source_type = 'sales_invoice' AND source_id = v_invoice_id;\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$"}	audit_remediation_delivery_blockers
44	{"-- ============================================================================\r\n-- 44_form_fix_forward.sql\r\n--\r\n-- لماذا هجرة جديدة بدل تعديل 38–43؟\r\n--\r\n--   `supabase db push` رفض التطبيق:\r\n--     \\"Found local migration files to be inserted before the last migration on\r\n--      remote database.\\"\r\n--   أي أن البعيد يحمل هجرة لا توجد محليًا، وتطبيق 38–43 بترتيبها الزمني كان\r\n--   سيُقحم تاريخًا في وسط تاريخ البعيد. والحل المطلوب في هذه الحالة هو هجرة\r\n--   **لاحقة** تُصلح ما تحتاج إصلاحه على حالة البعيد — لا --include-all فوق\r\n--   تاريخ متعارض.\r\n--\r\n-- ما يُصلحه هذا الملف (كل بند كان عطلًا فعليًا، لا تحسينًا):\r\n--\r\n--   P0-1  كمية المرتجع كانت تُقاس على مجموع الفاتورة للصنف كله (SUM over\r\n--         product_id)، فلا يمكن رد جزئي لبند معين حين يتكرر الصنف، ويُخلط\r\n--         السعر بين بنود مختلفة. الآن العمود invoice_item_id يُحدد البند،\r\n--         فيمكن النشر التدريجي (يُقبل NULL للمرتجعات القديمة).\r\n--\r\n--   P0-2  مسار صرف المستهلكات كان يسجّل حركة بـ movement_type = 'adjustment'\r\n--         ثم يعتمد على UPDATE لاحق لملء adjustment_reason؛ ولو فات ذلك\r\n--         رفضها القيد stock_movements_adjustment_reason_required. الآن السبب\r\n--         يُكتب في نفس الإدراج داخل post_stock_delta، وكل حركة جديدة\r\n--         تحمل total_cost (وهو ما يقرأه تقييد COGS). لا اعتماد على مُستدعٍ\r\n--         لتصحيح الحركة بعدها.\r\n--\r\n--   P0-3  apply_cost_movement يقيّم الحركة بالاكتساب/الطبقة، لكن المسار\r\n--         كان يترك stock_movements.total_cost فارغًا. post_sales_invoice يقرأ\r\n--         sm.total_cost لتقييد COGS، فتنزل الفاتورة بلا تكلفة والهامش يظهر\r\n--         100٪. الآن total_cost يُكتب على الحركة في نفس المعاملة.\r\n--\r\n--   P1-7  platform_admin_audit() كانت SECURITY DEFINER وتمنح authenticated\r\n--         قراءة auth.users للجميع. تُقيَّد الآن بمسؤول منصة نشط، وتُسحب من\r\n--         authenticated، ويُضاف غلاف platform_admin_audit_self() للواجهة.\r\n--\r\n--   P1-8  دوال الحُرّاس والمحروّكات الداخلية بلا EXECUTE لـ authenticated.\r\n--\r\n-- ثابت: idempotent، لا بيانات، ولا حذف. كل كائن يعتمد على كائن قد لا يكون\r\n-- موجودًا على البعيد (أصلًا من 38–43) يُنفَّذ داخل IF to_regprocedure.\r\n-- ============================================================================\r\n\r\nBEGIN","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P0-3 — القيمة الفعلية على حركة المخزون (مصدر قيود COGS)\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- apply_cost_movement يحسب out_cost داخليًا ثم لا يصدّره. أفضل ما يمكن فعله\r\n-- داخل post_stock_delta دون نسخة ثانية من محرّك التقييم هو قياس الطبقة نفسها\r\n-- بفرق (before − after): الحساب مركزي في apply_cost_movement، والقراءة هنا\r\n-- للتحقق لا للتقييم.\r\nCREATE OR REPLACE FUNCTION public.post_stock_delta(\r\n  p_product_id uuid,\r\n  p_warehouse_id uuid,\r\n  p_signed_qty numeric,\r\n  p_unit_cost numeric DEFAULT NULL::numeric,\r\n  p_movement_kind public.stock_movement_kind DEFAULT 'ADJUSTMENT'::public.stock_movement_kind,\r\n  p_source_type text DEFAULT NULL::text,\r\n  p_source_id uuid DEFAULT NULL::uuid,\r\n  p_note text DEFAULT NULL::text,\r\n  p_owner_type public.owner_type DEFAULT 'COMPANY'::public.owner_type,\r\n  p_owner_id uuid DEFAULT NULL::uuid,\r\n  p_movement_type_legacy public.movement_type DEFAULT NULL::public.movement_type\r\n)\r\nRETURNS void\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_mt      public.movement_type;\r\n  v_policy  public.inventory_policy;\r\n  v_nature  public.item_nature;\r\n  v_before  numeric;\r\n  v_after   numeric;\r\n  v_val0    numeric;\r\n  v_val1    numeric;\r\n  v_value   numeric;\r\n  v_movement_id uuid;\r\nBEGIN\r\n  IF v_user IS NOT NULL AND NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n\r\n  IF p_signed_qty IS NULL OR p_signed_qty = 0 THEN\r\n    RETURN;\r\n  END IF;\r\n  IF p_product_id IS NULL OR p_warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Item and warehouse are required for a stock movement';\r\n  END IF;\r\n\r\n  v_mt := coalesce(\r\n    p_movement_type_legacy,\r\n    CASE p_movement_kind\r\n      WHEN 'RECEIPT'      THEN 'purchase'::public.movement_type\r\n      WHEN 'ISSUE'        THEN 'sale'::public.movement_type\r\n      WHEN 'TRANSFER_IN'  THEN 'transfer_in'::public.movement_type\r\n      WHEN 'TRANSFER_OUT' THEN 'transfer_out'::public.movement_type\r\n      ELSE 'adjustment'::public.movement_type\r\n    END\r\n  );\r\n\r\n  SELECT p.item_nature, public.item_effective_policy(p.id)\r\n    INTO v_nature, v_policy\r\n  FROM public.products p WHERE p.id = p_product_id;\r\n\r\n  IF v_nature = 'SERVICE' OR v_policy <> 'TRACKED' THEN\r\n    RAISE EXCEPTION\r\n      'Item % does not hold company stock (nature %, policy %)',\r\n      p_product_id, coalesce(v_nature::text, '?'), coalesce(v_policy::text, '?');\r\n  END IF;\r\n\r\n  SELECT i.quantity INTO v_before\r\n  FROM public.inventory i\r\n  WHERE i.product_id = p_product_id\r\n    AND i.warehouse_id = p_warehouse_id\r\n    AND i.owner_type = p_owner_type\r\n    AND i.owner_id IS NOT DISTINCT FROM p_owner_id\r\n  FOR UPDATE;\r\n\r\n  v_before := coalesce(v_before, 0);\r\n  v_after  := round(v_before + p_signed_qty, 3);\r\n\r\n  IF v_after < 0 AND p_owner_type = 'COMPANY' THEN\r\n    RAISE EXCEPTION\r\n      'Insufficient stock for item % in warehouse %: available %, requested %',\r\n      p_product_id, p_warehouse_id, v_before, abs(p_signed_qty)\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  INSERT INTO public.inventory\r\n    (product_id, warehouse_id, owner_type, owner_id, quantity)\r\n  VALUES\r\n    (p_product_id, p_warehouse_id, p_owner_type, p_owner_id, v_after)\r\n  ON CONFLICT (product_id, warehouse_id, owner_type, owner_id)\r\n  DO UPDATE SET quantity = EXCLUDED.quantity, updated_at = now();\r\n\r\n  -- قيمة الطبقة قبل الحركة (للقراءة فقط؛ القيمة التي ستُكتب تأتي من المحرّك)\r\n  SELECT cl.total_value INTO v_val0\r\n  FROM public.item_cost_layers cl\r\n  WHERE cl.product_id = p_product_id\r\n    AND cl.warehouse_id = p_warehouse_id\r\n    AND cl.owner_type = p_owner_type\r\n    AND cl.owner_id IS NOT DISTINCT FROM p_owner_id;\r\n\r\n  v_val0 := coalesce(v_val0, 0);\r\n\r\n  PERFORM set_config('app.stock_engine', 'on', true);\r\n\r\n  INSERT INTO public.stock_movements\r\n    (product_id, warehouse_id, movement_type, quantity, unit_cost, reference,\r\n     note, created_by, movement_kind, source_type, source_id, owner_type, owner_id,\r\n     adjustment_reason)\r\n  VALUES\r\n    (p_product_id, p_warehouse_id, v_mt, p_signed_qty, p_unit_cost,\r\n     coalesce(p_source_type, '') || coalesce(':' || p_source_id::text, ''),\r\n     p_note, v_user, p_movement_kind, p_source_type, p_source_id, p_owner_type,\r\n     p_owner_id,\r\n     CASE WHEN v_mt = 'adjustment'::public.movement_type\r\n          THEN coalesce(nullif(btrim(p_note), ''), nullif(btrim(p_source_type), ''), 'Stock adjustment')\r\n          ELSE NULL END)\r\n  RETURNING id INTO v_movement_id;\r\n\r\n  -- التقييم في نفس المعاملة — الكمية والقيمة لا تنفصلان.\r\n  PERFORM public.apply_cost_movement(\r\n    p_product_id => p_product_id,\r\n    p_warehouse_id => p_warehouse_id,\r\n    p_signed_qty => p_signed_qty,\r\n    p_incoming_cost => p_unit_cost,\r\n    p_source_type => p_source_type,\r\n    p_source_id => p_source_id,\r\n    p_note => p_note,\r\n    p_owner_type => p_owner_type,\r\n    p_owner_id => p_owner_id);\r\n\r\n  -- P0-3: القيمة الفعلية للحركة تُكتب على الصف نفسه. الوارد يأخذ تكلفته\r\n  -- الممرَّرة؛ الصادر يأخذ ما نقصت به الطبقة فعلاً (لا سعر الكرت).\r\n  SELECT cl.total_value INTO v_val1\r\n  FROM public.item_cost_layers cl\r\n  WHERE cl.product_id = p_product_id\r\n    AND cl.warehouse_id = p_warehouse_id\r\n    AND cl.owner_type = p_owner_type\r\n    AND cl.owner_id IS NOT DISTINCT FROM p_owner_id;\r\n\r\n  v_val1 := coalesce(v_val1, 0);\r\n\r\n  IF p_signed_qty > 0 AND p_unit_cost IS NOT NULL THEN\r\n    v_value := round(p_signed_qty * p_unit_cost, 2);\r\n  ELSE\r\n    v_value := round(greatest(v_val0 - v_val1, 0), 2);\r\n  END IF;\r\n\r\n  -- الصف بالمعرّف الذي أعاده الإدراج نفسه — لا بحث «آخر حركة» ولا نافذة زمنية.\r\n  UPDATE public.stock_movements\r\n     SET total_cost = v_value,\r\n         unit_cost  = CASE\r\n                        WHEN p_signed_qty <> 0 AND v_value IS NOT NULL\r\n                        THEN round(v_value / abs(p_signed_qty), 4)\r\n                        ELSE unit_cost END\r\n   WHERE id = v_movement_id;\r\n\r\n  PERFORM set_config('app.stock_engine', 'off', true);\r\nEND $function$","COMMENT ON FUNCTION public.post_stock_delta(uuid, uuid, numeric, numeric, public.stock_movement_kind, text, uuid, text, public.owner_type, uuid, public.movement_type) IS\r\n  'P0-3: المسار الوحيد لحركة المخزون — الكمية والقيمة في معاملة واحدة، وtotal_cost مكتوب على الحركة.'","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P0-2 — المستهلكات: السبب في نفس الإدراج\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- صادر المستهلكات يُسجَّل كـ movement_type = 'adjustment'، والقيد على الجدول\r\n-- stock_movements_adjustment_reason_required يرفضه بلا سبب. post_stock_delta\r\n-- أعلاه يكتب السبب من الملاحظة داخل نفس INSERT، فلا يعتمد المسار على UPDATE\r\n-- لاحق يقوم به المُستدعي (وقد لا يقوم). لا شيء يُضاف هنا؛ الإصلاح داخل الدالة.\r\n\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- P0-1 — مرتجع المبيعات: مطابقة البند + قيمة المرتجع الفعلية\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- sales_return_items تحتفظ بـ product_id فقط. نضيف invoice_item_id ليكون\r\n-- المرتجع الجزئي لبندٍ بعينه محددًا، ونتركه NULL للمرتجع القديم (التوافق).\r\nALTER TABLE public.sales_return_items\r\n  ADD COLUMN IF NOT EXISTS invoice_item_id uuid","COMMENT ON COLUMN public.sales_return_items.invoice_item_id IS\r\n  'P0-1: بند الفاتورة الأصلية الذي يُرجع منه. NULL يعني «أي بند لنفس الصنف» (توافق مع المرتجعات القديمة).'","CREATE INDEX IF NOT EXISTS idx_sales_return_items_invoice_item\r\n  ON public.sales_return_items (invoice_item_id)\r\n  WHERE invoice_item_id IS NOT NULL","-- ⚠️ لا يُضاف مفتاح أجنبي هنا: المفاتيح كلها في 13 (القرار 1 في README)،\r\n-- وإضافتها في هجرة لاحقة تُخفيها عن خريطة المفاتيح. العمود والفهرس يكفيان\r\n-- للربط، والتحقق من وجود البند يتم داخل create_sales_return قبل الإدراج.\r\n\r\n-- فهرس الربط: كل نداء يُقيّم حركة يقرأ حركاتها بمصدرها (COGS، عكس المرتجع،\r\n-- تقرير التصنيع). بلا هذا الفهرس يفك كل استعلام مسحًا كاملًا للجدول.\r\nCREATE INDEX IF NOT EXISTS idx_stock_movements_source\r\n  ON public.stock_movements (source_type, source_id)\r\n  WHERE source_id IS NOT NULL","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P1-7 — platform_admin_audit: بيانات auth.users ليست لكل موظف\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- الدالة تقرأ auth.users و auth.identities وهي SECURITY DEFINER، فيكفيها\r\n-- EXECUTE من authenticated لتُعرض لموظف عادي. التعريف التالي يرفض غير مسؤول\r\n-- المنصة، ويُعاد تعريف تعريفها الحالي كغلاف إن وُجد بلا هذا الفحص.\r\n--\r\n-- (الاسم والتوقيع كما هما، فلا يتغير أي مستدعٍ.)\r\nDO $$\r\nBEGIN\r\n  IF to_regprocedure('public.platform_admin_audit()') IS NOT NULL THEN\r\n    EXECUTE $fn$\r\n      CREATE OR REPLACE FUNCTION public.platform_admin_audit()\r\n      RETURNS TABLE (\r\n        user_id uuid, email text, platform_role text, is_active boolean,\r\n        has_email_id boolean, has_phone_id boolean, has_profile boolean,\r\n        has_store_role boolean, is_superadmin boolean, problems text[]\r\n      )\r\n      LANGUAGE sql\r\n      STABLE\r\n      SECURITY DEFINER\r\n      SET search_path = public, pg_temp\r\n      AS $body$\r\n        SELECT\r\n          pa.user_id,\r\n          u.email::text,\r\n          pa.role,\r\n          pa.is_active,\r\n          EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = pa.user_id AND i.provider = 'email'),\r\n          EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = pa.user_id AND i.provider = 'phone'),\r\n          EXISTS (SELECT 1 FROM public.profiles p       WHERE p.id      = pa.user_id),\r\n          EXISTS (SELECT 1 FROM public.user_roles r     WHERE r.user_id = pa.user_id),\r\n          public.is_platform_superadmin(pa.user_id),\r\n          array_remove(ARRAY[\r\n            CASE WHEN u.id IS NULL                THEN 'missing auth.users'                END,\r\n            CASE WHEN u.deleted_at IS NOT NULL     THEN 'auth user deleted'                 END,\r\n            CASE WHEN u.email_confirmed_at IS NULL THEN 'email not confirmed'                END,\r\n            CASE WHEN u.banned_until > now()       THEN 'auth user banned'                  END,\r\n            CASE WHEN NOT EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = pa.user_id AND i.provider = 'email')\r\n                                                   THEN 'missing email identity'            END,\r\n            CASE WHEN NOT EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = pa.user_id AND i.provider = 'phone')\r\n                                                   THEN 'missing phone identity'            END,\r\n            CASE WHEN NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = pa.user_id)\r\n                                                   THEN 'missing profile'                   END,\r\n            CASE WHEN NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = pa.user_id AND p.is_active)\r\n                                                   THEN 'profile inactive (is_staff = false)' END,\r\n            CASE WHEN NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = pa.user_id)\r\n                                                   THEN 'missing store role (RLS hides everything)' END,\r\n            CASE WHEN pa.role = 'superadmin' AND NOT public.is_platform_superadmin(pa.user_id)\r\n                                                   THEN 'superadmin row does not satisfy the predicate' END,\r\n            CASE WHEN pa.role = 'support' AND public.is_platform_superadmin(pa.user_id)\r\n                                                   THEN 'support account satisfies superadmin predicate' END\r\n          ], NULL) AS problems\r\n        FROM public.platform_admins pa\r\n        LEFT JOIN auth.users u ON u.id = pa.user_id\r\n        -- P1-7: صلاحية القراءة داخل الدالة، لا بالاعتماد على منحة EXECUTE.\r\n        WHERE public.is_platform_admin(auth.uid())\r\n        ORDER BY pa.role DESC, u.email\r\n      $body$;\r\n    $fn$;\r\n  END IF;\r\nEND $$","-- وسحب التنفيذ العام: يبقى لـ service_role (CI / CLI) ولمسؤول المنصة عبر\r\n-- الدالة نفسها، بلا منح authenticated أعمى.\r\nDO $$\r\nBEGIN\r\n  IF to_regprocedure('public.platform_admin_audit()') IS NOT NULL THEN\r\n    REVOKE ALL ON FUNCTION public.platform_admin_audit() FROM PUBLIC, anon, authenticated;\r\n    GRANT EXECUTE ON FUNCTION public.platform_admin_audit() TO service_role;\r\n    -- المسؤول يحتاجها من الواجهة: يحصل عليها عبر غلاف يتحقق أولاً.\r\n    EXECUTE $fn$\r\n      CREATE OR REPLACE FUNCTION public.platform_admin_audit_self()\r\n      RETURNS TABLE (\r\n        user_id uuid, email text, platform_role text, is_active boolean,\r\n        has_email_id boolean, has_phone_id boolean, has_profile boolean,\r\n        has_store_role boolean, is_superadmin boolean, problems text[]\r\n      )\r\n      LANGUAGE sql\r\n      STABLE\r\n      SECURITY DEFINER\r\n      SET search_path = public, pg_temp\r\n      AS $body$\r\n        SELECT * FROM public.platform_admin_audit()\r\n        WHERE public.is_platform_admin(auth.uid())\r\n      $body$;\r\n    $fn$;\r\n    REVOKE ALL ON FUNCTION public.platform_admin_audit_self() FROM PUBLIC, anon;\r\n    GRANT EXECUTE ON FUNCTION public.platform_admin_audit_self() TO authenticated, service_role;\r\n  END IF;\r\nEND $$","COMMENT ON FUNCTION public.platform_admin_audit() IS\r\n  'تقرير اكتمال حسابات المنصة — service_role فقط (يقرأ auth.users). للواجهة استخدم platform_admin_audit_self().'","-- ════════════════════════════════════════════════════════════════════════════\r\n-- P1-8 (تكملة) — المحرّكات الداخلية الجديدة لا تُمنح\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- 43 عكس القاعدة إلى قائمة سماح. أي دالة أُنشئت بعده أو عُرّفت هنا تحتاج\r\n-- إسقاط المنح احتياطًا (الدوال المساعدة الداخلية فقط، لا RPC الواجهة).\r\nDO $$\r\nDECLARE\r\n  v_fn record;\r\nBEGIN\r\n  FOR v_fn IN\r\n    SELECT p.oid::regprocedure AS sig\r\n    FROM pg_proc p\r\n    JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'public'\r\n      AND p.prokind = 'f'\r\n      AND p.proname IN ('tg_customers_system_guard', 'tg_suppliers_system_guard',\r\n                        'tg_stock_movements_engine_only', 'tg_customer_ledger_system_guard',\r\n                        'apply_cost_movement', 'balance_and_post_return')\r\n  LOOP\r\n    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated', v_fn.sig);\r\n  END LOOP;\r\nEND $$","-- طبيعتان متعمدتان في هذا الملف:\r\n--   • NO_DATA على الصفوف القائمة: قاعدة حيّة قد تحمل صفوفًا موضوعها قديم قبل\r\n--     هذا الإصلاح؛ قصر الملف على البنية الجديدة يمنع توقف النشر. النشر الصحيح\r\n--     لا يترك تسويات بلا سبب ولا حركات بلا قيمة، والاستعلامات أعلاه للتحقق.\r\n--   • من الناحية البنيوية كل ما يمكن التعريف هنا يُعرَّف، وكل ما يعتمد على\r\n--     كائن قد لا يكون موجودًا على البعيد (POSTGRES_FUNCTIONS الأخرى في 43/46)\r\n--     يُنفّذ داخل IF to_regprocedure/IF NOT EXISTS، فلا تتوقف السلسلة.\r\n\r\n-- قيد إثبات مكاني: لا يمس أي صف، ويتحقق أن post_stock_delta السارية تحمل\r\n-- إصلاح P0-3 (نص total_cost في تعريفها)، فلا يُطبع «تم» على نسخة قديمة.\r\nDO $$\r\nBEGIN\r\n  IF to_regprocedure('public.post_stock_delta(uuid,uuid,numeric,numeric,public.stock_movement_kind,text,uuid,text,public.owner_type,uuid,public.movement_type)') IS NULL THEN\r\n    RAISE EXCEPTION 'post_stock_delta غير موجود بهذا التوقيع بعد 44';\r\n  END IF;\r\n\r\n  IF position('total_cost' IN pg_get_functiondef(\r\n       'public.post_stock_delta(uuid,uuid,numeric,numeric,public.stock_movement_kind,text,uuid,text,public.owner_type,uuid,public.movement_type)'::regprocedure)) = 0 THEN\r\n    RAISE EXCEPTION 'post_stock_delta ما زال لا يكتب total_cost — 44 لم تُطبَّق فعليًا';\r\n  END IF;\r\nEND $$",COMMIT,"-- ============================================================================\r\n-- التحقق بعد التطبيق (كلها يجب أن ترجع صفرًا على قاعدة سليمة):\r\n--\r\n--   1) حركة قيمة بلا total_cost:\r\n--      SELECT count(*) FROM public.stock_movements\r\n--       WHERE movement_kind IN ('ISSUE','RECEIPT','PRODUCTION') AND total_cost IS NULL;\r\n--\r\n--   2) تسوية بلا سبب:\r\n--      SELECT count(*) FROM public.stock_movements\r\n--       WHERE movement_type = 'adjustment' AND coalesce(btrim(adjustment_reason),'') = '';\r\n--\r\n--   3) coworker calling platform_admin_audit() → يجب أن يُرفض بلا صلاحية،\r\n--      و platform_admin_audit_self() يعيد صفرًا لغير مسؤول المنصة.\r\n--\r\n-- ROLLBACK: هذا الملف يعيد تعريف دوال ويزيد عمودًا. الإرجاع اليدوي:\r\n--   ALTER TABLE public.sales_return_items DROP COLUMN IF EXISTS invoice_item_id;\r\n--   DROP INDEX IF EXISTS public.idx_stock_movements_source;\r\n--   وإعادة تعريف post_stock_delta من 43. لا تُرجِع على قاعدة إنتاج حيّة.\r\n-- ============================================================================"}	form_fix_forward
45	{"-- ============================================================================\r\n-- 45_rpc_allowlist_and_exposure_contract.sql\r\n--\r\n-- إغلاق تحذيرات Security Advisor 0028/0029 في مكانها الصحيح: مصدرها هو **منح\r\n-- EXECUTE** على دوال public، لا تعريف الدوال. لهذا لا يُغيّر هذا الملف أي جسم\r\n-- دالة، ولا يمس أي جدول أو أي صف، ولا بيانات افتراضية. يغيّر من يُنفّذ فقط.\r\n--\r\n-- لماذا الآن؟\r\n--   36 و38 و43 منحت authenticated تنفيذ كل الدوال (بقائمة استثناء قصيرة أو\r\n--   قائمة سماح لا تغطي ما أنشأته الهجرات 14/16/20–31)، فبقيت عشرات الدوال\r\n--   SECURITY DEFINER مكشوفة للواجهة عبر /rest/v1/rpc — بعضها:\r\n--     • ledger_account_code_for_payment_method — وهذا الأخطر: كانت **أيضًا**\r\n--       قابلة للتنفيذ من anon (تحذير 0028 الوحيد).\r\n--     • apply_cost_movement / محرّكات الترقيم — أدوات داخلية تكتب الدفاتر.\r\n--     • has_role / is_staff / is_platform_superadmin — تقبل user_id عشوائيًا،\r\n--       فيمكن لأي مستخدم مسجّل استنطاق صلاحيات أي عضو في المتجر.\r\n--\r\n-- القاعدة هنا — عكس الافتراضي:\r\n--   • DEFAULT: لا EXECUTE لـ authenticated إلا ما في rpc_allowlist() أدناه.\r\n--   • دوال تحتاجها سياسات RLS تُمنح لـ authenticated (policy_runtime_functions)،\r\n--     لأن السياسة تُنفّذ بصلاحيات المستدعي؛ سحب EXECUTE يحوّل جدولًا سليمًا إلى\r\n--     «لا صفوف» بصمت — أسوأ عطل لأنه يُشبه قاعدة فارغة.\r\n--   • أي RPC واجهة جديد يُضاف إلى القائمة في نفس الهجرة التي ينشئه.\r\n--   • لا شيء في public يُمنح لـ anon — لا RPC ولا دالة سياسة.\r\n--\r\n-- ⚠️ لماذا تُبنى الأسماء بـ quote_ident لا format('%s') ؟\r\n--   بلا quote_ident كان format ينتج منحًا على دالة باسم مقصوص:\r\n--     GRANT EXECUTE ON FUNCTION public.\\"has_role(uuid,app_role)\\" ...\r\n-- هذا الملف يتحقق في النهاية أن كل اسم في القائمة إما وُجد أو طُبع باسمه كتحذير.\r\n-- ============================================================================\r\n\r\nBEGIN","-- ════════════════════════════════════════════════════════════════════════════\r\n-- (1) قائمة السماح: كل ما تستدعيه الواجهة عبر supabase.rpc()\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- المجموعة مشتقة من src/ (كل نداء .rpc في الواجهة) + دوال الفحص التي تحتاجها\r\n-- شاشات الصلاحيات. ما ليس هنا ليس RPC.\r\nCREATE OR REPLACE FUNCTION public.rpc_allowlist()\r\nRETURNS text[]\r\nLANGUAGE sql\r\nIMMUTABLE\r\nSET search_path = public\r\nAS $$\r\n  SELECT ARRAY[\r\n    -- ── البيع والشراء والمخزون ──\r\n    'create_sale', 'create_sales_return', 'create_purchase',\r\n    'create_purchase_return', 'create_stock_transfer',\r\n    'post_sales_invoice', 'post_purchase_invoice',\r\n    'post_stock_delta',                    -- شاشتا التوريد والتسوية\r\n    'post_stock_settlement',               -- معالج التسوية الجردية (46)\r\n    'post_stock_adjustment',               -- تسويات المخزون مع قيود الأستاذ\r\n    'post_opening_stock',                  -- رصيد افتتاحي للمخزون\r\n    'receive_customer_owned_stock', 'release_customer_owned_stock',\r\n    'create_opening_balance', 'post_opening_balance', 'reverse_opening_balance',\r\n    'search_products',\r\n    'item_line_type', 'item_stock_effect', 'item_effective_policy',\r\n    'item_has_stock_history', 'resolve_unit_cost',\r\n    'product_reference_counts', 'warehouse_reference_counts',\r\n    'save_item_policy', 'approve_item_policy_change',\r\n    -- ── الدفعات والشيكات والتشغيل المالي (فريق العمل) ──\r\n    'clear_cheque', 'bounce_cheque',\r\n    -- ── إدارة الدفعات / التشغيلات (فريق العمل - 31) ──\r\n    'reconcile_batches_with_inventory', 'save_product_batch',\r\n    'get_batch_kpis', 'delete_product_batch', 'save_batch_settings',\r\n    -- ── الذمم والمدفوعات ──\r\n    'record_customer_payment', 'record_supplier_payment', 'get_supplier_statement',\r\n    'adjust_loyalty', 'customer_credit_limit_allows',\r\n    -- ── أمانات المطحنة (واجهة الكاونتر) ──\r\n    'custody_intake', 'custody_milling', 'custody_deliver', 'custody_adjust',\r\n    'custody_balances', 'custody_link_invoice',\r\n    'create_milling_service_document', 'smart_manufacture', 'consume_internal_supplies',\r\n    'milling_custody_intake', 'milling_custody_issue_milling', 'milling_custody_deliver',\r\n    'milling_custody_adjust',\r\n    -- ── المحاسبة والأصول والضرائب ──\r\n    'create_journal_entry', 'reverse_journal_entry', 'get_chart_of_accounts_tree',\r\n    'activate_fixed_asset', 'dispose_fixed_asset',\r\n    'run_depreciation', 'run_batch_depreciation',\r\n    'run_contract_amortization', 'run_batch_amortization',\r\n    'close_fiscal_year', 'open_fiscal_year', 'set_period_status',\r\n    'generate_tax_declaration', 'settle_tax_period', 'pay_tax_settlement',\r\n    -- ── المصروفات ──\r\n    'create_expense', 'update_expense', 'submit_expense', 'decide_expense',\r\n    'post_expense', 'close_expense', 'cancel_expense', 'reverse_expense',\r\n    'record_expense_payment', 'reverse_expense_payment',\r\n    'list_expenses', 'expense_detail', 'expense_summary', 'expense_report',\r\n    'expense_lookups', 'save_expense_category', 'delete_expense_category',\r\n    -- ── طرق الدفع والأطراف ──\r\n    'create_tenant_payment_method', 'update_payment_method_identity',\r\n    'remove_tenant_payment_method',\r\n    'is_system_customer', 'is_system_supplier',\r\n    -- ── الترقيم: قراءة الصيغة فقط (التخصيص يمر عبر fn_set_document_numbering) ──\r\n    'fn_format_document_number', 'fn_resolve_document_numbering',\r\n    'fn_set_document_numbering', 'fn_document_numbering_sequence_name',\r\n    -- ── النسخ الاحتياطي ──\r\n    'backup_export_all', 'backup_restore_all', 'backup_schema_fingerprint',\r\n    -- ── مساعدات الفحص التي تستدعيها شاشات الصلاحيات والمنصة ──\r\n    'has_role', 'is_staff', 'is_platform_admin', 'is_platform_superadmin',\r\n    'can_read_finance', 'can_read_expense_entry', 'can_author_payment_methods',\r\n    'can_operate_milling', 'can_view_milling',\r\n    'platform_admin_audit_self'\r\n  ];\r\n$$","COMMENT ON FUNCTION public.rpc_allowlist() IS\r\n  'عقد RPC الواجهة: كل دالة هنا ممنوحة لـ authenticated، وكل ما ليس هنا لا يُنفَّذ من /rest/v1/rpc. لا شيء في public ممنوح لـ anon.'","REVOKE ALL ON FUNCTION public.rpc_allowlist() FROM PUBLIC, anon, authenticated, service_role","-- ════════════════════════════════════════════════════════════════════════════\r\n-- (2) دوال السياسات (RLS): تبقى ممنوحة — وإلا صارت كل سياسة «لا صفوف»\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- هذه الدوال تُستدعى داخل USING/WITH CHECK بصلاحيات المستدعي (authenticated أو\r\n-- anon على المسارات العامة). أمنها من الدالة نفسها: تتحقق من auth.uid()، ومعظمها\r\n-- SECURITY DEFINER لقراءة user_roles رغم RLS. سحب EXECUTE يعطّل السياسة بصمت.\r\n--\r\n-- الاسم غير الموجود هنا ليس خطأ: تُطابق الأسماء الموجودة فعلًا فقط، وهذه هي\r\n-- دوال التقييم التي تُشترط وجودها. بعضها (has_any_role / can_read_milling /\r\n-- expense_can_read) قد لا يوجد في نسخة معينة، فلا يُعبأ بمنحة.\r\n-- ⚠️ قائمة rpc_allowlist() عهد كتابة/تعريف فقط: لا تمنح أحدًا حق expect\r\n--    (لا SELECT). لا تُضف إلى هذه المجموعة إلا دالة SECURITY INVOKER تحتاج\r\n--    جدولًا داخليًا لا تصل إليه الواجهة. كل دوال الكتابة هنا SECURITY DEFINER\r\n--    تتحقق من الاستدعاء بنفسها.\r\nCREATE OR REPLACE FUNCTION public.policy_runtime_functions()\r\nRETURNS text[]\r\nLANGUAGE sql\r\nIMMUTABLE\r\nSET search_path = public\r\nAS $$\r\n  SELECT ARRAY[\r\n    'is_staff', 'has_role', 'has_any_role',\r\n    'is_platform_admin', 'is_platform_superadmin',\r\n    'can_read_finance', 'can_read_expense_entry', 'can_read_milling',\r\n    'can_view_milling', 'can_operate_milling', 'can_author_payment_methods',\r\n    'expense_role_rank', 'expense_actor',\r\n    'expense_assert_capability', 'expense_can_write_document',\r\n    'is_system_customer', 'is_system_supplier'\r\n  ];\r\n$$","COMMENT ON FUNCTION public.policy_runtime_functions() IS\r\n  'دوال تُستدعى داخل سياسات RLS أو مشغّلاتها، فتجب أن تبقى قابلة للتنفيذ من مستخدم السياسة. لا تُعاد تسمية دون مراجعة كل سياسة.'","REVOKE ALL ON FUNCTION public.policy_runtime_functions() FROM PUBLIC, anon, authenticated, service_role","-- ════════════════════════════════════════════════════════════════════════════\r\n-- (3) العقد: سحب شامل ثم منح صريح — بأسماء صحيحة (quote_ident)\r\n-- ════════════════════════════════════════════════════════════════════════════\r\n-- ⚠️ عمليات DDL (GRANT/REVOKE/ALTER) لا تُنفَّذ داخل دالة SQL (STABLE/INMUTABLE):\r\n--    لهذا يبقى المنطق في DO (PL/pgSQL) كما هو أعلاه — القائمتان تُقرآن منه\r\n--    فقط، ولا تُنفَّذ أي ALTER داخل تعريفهما.\r\nDO $$\r\nDECLARE\r\n  v_fn record;\r\n  v_allowed text[] := public.rpc_allowlist();\r\n  v_policy  text[] := public.policy_runtime_functions();\r\nBEGIN\r\n  FOR v_fn IN\r\n    SELECT p.oid::regprocedure AS sig,\r\n           p.proname,\r\n           n.nspname,\r\n           pg_get_function_identity_arguments(p.oid) AS argtypes\r\n    FROM pg_proc p\r\n    JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'public' AND p.prokind = 'f'\r\n  LOOP\r\n    -- 3-أ) لا شيء لأي أحد: يمنع تراكم صلاحيات PUBLIC الافتراضية.\r\n    EXECUTE format('REVOKE ALL ON FUNCTION %I.%I(%s) FROM PUBLIC, anon, authenticated, service_role',\r\n                   v_fn.nspname, v_fn.proname, v_fn.argtypes);\r\n\r\n    -- 3-ب) خدمة الخلفية: كل الدوال (CI، المهام، صيانة).\r\n    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.%I(%s) TO service_role',\r\n                   v_fn.nspname, v_fn.proname, v_fn.argtypes);\r\n\r\n    -- 3-ج) الدوال الداخلية: service_role فقط — لا تمر، فلا شيء بعد هذا السطر.\r\n    IF v_fn.proname IN ('apply_cost_movement', 'fn_next_document_number',\r\n                        'next_journal_number', 'next_invoice_number') THEN\r\n      CONTINUE;\r\n    END IF;\r\n\r\n    -- 3-د) RPC الواجهة أو دالة سياسة → authenticated.\r\n    IF v_fn.proname = ANY(v_allowed) OR v_fn.proname = ANY(v_policy) THEN\r\n      EXECUTE format('GRANT EXECUTE ON FUNCTION %I.%I(%s) TO authenticated',\r\n                     v_fn.nspname, v_fn.proname, v_fn.argtypes);\r\n    END IF;\r\n\r\n    -- 3-هـ) ⚠️ لا منح anon هنا إطلاقًا. التحذير 0028 الوحيد كان دالة\r\n    --      SECURITY DEFINER ممنوحة لـ anon، وهو بالضبط ما يغلقه هذا السطر\r\n    --      بإغفاله: السياسات التي تعمل تحت anon تستخدم سياسات TO anon\r\n    --      وتقارن auth.uid()، لا تنادي دوال مساعدة.\r\n  END LOOP;\r\nEND $$","-- ════════════════════════════════════════════════════════════════════════════\r\n-- (4) تحقق: لا SECURITY DEFINER مكشوف لـ anon، ولا اسم مفقود في القائمة\r\n-- ════════════════════════════════════════════════════════════════════════════\r\nDO $$\r\nDECLARE\r\n  v_leak   text;\r\n  v_missed text;\r\nBEGIN\r\n  -- 4-أ) تحذير 0028 الوحيد كان ledger_account_code_for_payment_method؛ يجب\r\n  --      ألا يبقى أي SECURITY DEFINER قابلًا للتنفيذ من anon.\r\n  SELECT string_agg(p.proname, ', ' ORDER BY p.proname) INTO v_leak\r\n  FROM pg_proc p\r\n  JOIN pg_namespace n ON n.oid = p.pronamespace\r\n  WHERE n.nspname = 'public'\r\n    AND p.prokind = 'f'\r\n    AND p.prosecdef\r\n    AND has_function_privilege('anon', p.oid, 'EXECUTE');\r\n\r\n  IF v_leak IS NOT NULL THEN\r\n    RAISE EXCEPTION 'SECURITY DEFINER مكشوف لـ anon بعد 45: %', v_leak;\r\n  END IF;\r\n\r\n  -- 4-ب) كل اسم في قائمة السماح يجب أن يطابق دالة واحدة على الأقل. اسم لا\r\n  --      يطابق شيئًا = RPC مكسور في الواجهة (وهذا ما كشفه فحص quote_ident).\r\n  --      النقص لا يوقف النشر (قد يكون RPC لم يُنشأ في هذا الفرع بعد) لكنه\r\n  --      يُطبع تحذيرًا واضحًا يُرى في ناتج db push، فلا يمر صامتًا.\r\n  SELECT string_agg(a, ', ' ORDER BY a) INTO v_missed\r\n  FROM unnest(public.rpc_allowlist()) AS a\r\n  WHERE NOT EXISTS (\r\n    SELECT 1 FROM pg_proc p\r\n    JOIN pg_namespace n ON n.oid = p.pronamespace\r\n    WHERE n.nspname = 'public' AND p.prokind = 'f' AND p.proname = a\r\n  );\r\n\r\n  IF v_missed IS NOT NULL THEN\r\n    RAISE WARNING 'أسماء في عقد RPC لا تطابق أي دالة في هذه القاعدة: %', v_missed;\r\n  END IF;\r\nEND $$",COMMIT,"-- ============================================================================\r\n-- التحقق بعد التطبيق:\r\n--\r\n--   -- صفر: لا دالة SECURITY DEFINER قابلة لتنفيذ anon\r\n--   SELECT p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\r\n--    WHERE n.nspname = 'public' AND p.prokind = 'f' AND p.prosecdef\r\n--      AND has_function_privilege('anon', p.oid, 'EXECUTE');\r\n--\r\n--   -- عقد الواجهة كما يُنفَّذ فعليًا\r\n--   SELECT p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\r\n--    WHERE n.nspname = 'public' AND p.prokind = 'f'\r\n--      AND has_function_privilege('authenticated', p.oid, 'EXECUTE')\r\n--    ORDER BY 1;\r\n--\r\n--   -- تحذيرات 0029 المتبقية في Advisor يجب أن تكون دوال سياسة أو RPC متعمّد،\r\n--   -- وكلها تتحقق من auth.uid() ودور المستدعي في أول جسمها.\r\n--\r\n-- ROLLBACK: لا شيء — هذا الملف يغيّر المنح فقط. للإرجاع: أعد تطبيق 43.\r\n-- ============================================================================"}	rpc_allowlist_and_exposure_contract
46	{"-- POS split-payment follow-up: accept the already-supported cheque ENUM and\r\n-- reject a tender total above the posted invoice total.\r\n-- This is additive and leaves the single-method create_sale overload unchanged.\r\n\r\nBEGIN","CREATE OR REPLACE FUNCTION public.create_sale(\r\n  _warehouse_id uuid,\r\n  _customer_id uuid,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _discount numeric,\r\n  _note text,\r\n  _items jsonb,\r\n  _sale_date date,\r\n  _payment_splits jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id uuid;\r\n  v_total numeric;\r\n  v_paid numeric;\r\n  v_user uuid := auth.uid();\r\n  v_split record;\r\n  v_component_count integer := 0;\r\n  v_split_total numeric := 0;\r\n  v_distinct_methods integer := 0;\r\n  v_single_method text;\r\n  v_recorded_method text := _payment_method;\r\n  v_create_method text;\r\nBEGIN\r\n  IF coalesce(jsonb_typeof(_payment_splits), 'jsonb') <> 'array'\r\n     OR coalesce(jsonb_array_length(_payment_splits), 0) = 0 THEN\r\n    RETURN public.create_sale(\r\n      _warehouse_id, _customer_id, _payment_method, _paid, _discount, _note, _items, _sale_date\r\n    );\r\n  END IF;\r\n\r\n  FOR v_split IN\r\n    SELECT part ->> 'method' AS method,\r\n           coalesce((part ->> 'amount')::numeric, 0) AS amount\r\n    FROM jsonb_array_elements(_payment_splits) AS part\r\n  LOOP\r\n    IF v_split.method IS NULL\r\n      OR v_split.method NOT IN ('cash', 'card', 'bank_transfer', 'mobile_money', 'cheque') THEN\r\n      RAISE EXCEPTION 'Unsupported payment method: %', v_split.method;\r\n    END IF;\r\n    IF v_split.amount <= 0 THEN\r\n      RAISE EXCEPTION 'Every payment tender component requires a positive amount';\r\n    END IF;\r\n\r\n    v_component_count := v_component_count + 1;\r\n    v_split_total := v_split_total + v_split.amount;\r\n  END LOOP;\r\n\r\n  SELECT count(DISTINCT part ->> 'method'), min(part ->> 'method')\r\n    INTO v_distinct_methods, v_single_method\r\n  FROM jsonb_array_elements(_payment_splits) AS part;\r\n\r\n  -- The invoice's original journal is posted inside the legacy create_sale\r\n  -- overload before tender rows can be inserted. Until post_sales_invoice is\r\n  -- upgraded to debit every tender's own ledger account, a true multi-method\r\n  -- split would be reported correctly but posted to one account. Refuse it\r\n  -- transactionally rather than write a misleading journal.\r\n  IF v_distinct_methods > 1 THEN\r\n    RAISE EXCEPTION 'Multi-method payment requires split-aware ledger posting';\r\n  END IF;\r\n\r\n  IF v_component_count <> v_distinct_methods THEN\r\n    RAISE EXCEPTION 'A payment method may only be included once in a split';\r\n  END IF;\r\n\r\n  IF round(v_split_total, 2) <> round(coalesce(_paid, 0), 2) THEN\r\n    RAISE EXCEPTION\r\n      'Payment breakdown total % does not match the paid amount %',\r\n      round(v_split_total, 2), round(coalesce(_paid, 0), 2);\r\n  END IF;\r\n\r\n  v_recorded_method := CASE\r\n    WHEN v_distinct_methods > 1 THEN 'split'\r\n    ELSE v_single_method\r\n  END;\r\n\r\n  -- The legacy single-method function's allow-list predates cheque and split.\r\n  -- Use a ledger-safe single method to create the invoice, then restore its\r\n  -- tender identity after creation. For a cheque-only tender the canonical\r\n  -- ledger family is bank; for a multi-method invoice the posting is the\r\n  -- existing split/cash-settlement path and the tender rows remain authoritative.\r\n  v_create_method := CASE\r\n    WHEN v_recorded_method = 'cheque' THEN 'bank_transfer'\r\n    WHEN v_recorded_method = 'split' THEN 'cash'\r\n    ELSE v_recorded_method\r\n  END;\r\n\r\n  v_invoice_id := public.create_sale(\r\n    _warehouse_id, _customer_id, v_create_method, _paid, _discount, _note, _items, _sale_date\r\n  );\r\n\r\n  SELECT total, paid INTO v_total, v_paid\r\n  FROM public.sales_invoices\r\n  WHERE id = v_invoice_id\r\n  FOR UPDATE;\r\n\r\n  IF round(v_split_total, 2) > round(v_total, 2) THEN\r\n    RAISE EXCEPTION 'Payment breakdown cannot exceed the invoice total';\r\n  END IF;\r\n\r\n  IF round(v_split_total, 2) <> round(v_paid, 2) THEN\r\n    RAISE EXCEPTION 'Tender breakdown does not match the recorded paid amount';\r\n  END IF;\r\n\r\n  UPDATE public.sales_invoices\r\n  SET payment_method = v_recorded_method::public.payment_method,\r\n      updated_at = now()\r\n  WHERE id = v_invoice_id\r\n    AND payment_method IS DISTINCT FROM v_recorded_method::public.payment_method;\r\n\r\n  FOR v_split IN\r\n    SELECT part ->> 'method' AS method,\r\n           coalesce((part ->> 'amount')::numeric, 0) AS amount\r\n    FROM jsonb_array_elements(_payment_splits) AS part\r\n  LOOP\r\n    INSERT INTO public.customer_payment_splits (\r\n      customer_id, invoice_id, method, amount, occurred_at, created_by\r\n    )\r\n    VALUES (\r\n      _customer_id,\r\n      v_invoice_id,\r\n      v_split.method::public.payment_method,\r\n      round(v_split.amount, 2),\r\n      coalesce(_sale_date, current_date)::timestamp + localtime,\r\n      v_user\r\n    );\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (\r\n    v_user,\r\n    'sale.tender_breakdown.recorded',\r\n    'sales_invoice',\r\n    v_invoice_id,\r\n    jsonb_build_object(\r\n      'recorded_payment_method', v_recorded_method,\r\n      'components', v_component_count,\r\n      'tender_total', round(v_split_total, 2),\r\n      'total', v_total,\r\n      'paid', v_paid\r\n    )\r\n  );\r\n\r\n  RETURN v_invoice_id;\r\nEND;\r\n$function$",COMMIT}	pos_split_cheque_and_total_guard
47	{"-- ============================================================================\r\n-- 47_stock_settlement_rpc.sql\r\n--\r\n-- إغلاق آخر مسار يكتب المخزون من المتصفح مباشرة.\r\n--\r\n-- المشكلة:\r\n--   src/components/stock/settlement-wizard-sheet.tsx كانت تفعل:\r\n--     supabase.from(\\"inventory\\").upsert({ quantity: actual }, ...)\r\n--     supabase.from(\\"stock_movements\\").insert({ movement_type: \\"adjustment\\", ... })\r\n--   بعد 43 (tg_stock_movements_engine_only) الكتابة المباشرة على الحركات\r\n--   مرفوضة، ومعها:\r\n--     • القيمة لا تُقيَّد: صف inventory يُكتب بكمية جديدة بلا apply_cost_movement،\r\n--       فتنفصل الكمية عن التكلفة ويختل تقييم المخزون بصمت.\r\n--     • الحركة لا تحمل movement_kind ولا source، فلا يمكن ربطها بمستند ولا\r\n--       معرفة من اعتمدها وبأي سبب.\r\n--     • التحديثان منفصلان (inventory ثم stock_movements) وليسا معاملة واحدة:\r\n--       انقطاع الشبكة في المنتصف يترك كمية جديدة وحركة مفقودة.\r\n--\r\n-- الحل: دالة واحدة SECURITY DEFINER تعتمد التسوية كاملة في معاملة واحدة،\r\n-- وتستخدم **نفس المحرك** post_stock_delta (كمية + قيمة)، وتوثّق مستندًا في\r\n-- stock_adjustments / stock_adjustment_items (جدولان موجودان ولا يكتب فيهما\r\n-- أحد)، وسجل تدقيق.\r\n--\r\n-- الأمان:\r\n--   • المستدعي موظف نشط + مالك أو مدير (التسوية تعدّل رصيدًا محاسبيًا).\r\n--   • السبب إلزامي، والفرق لا يكون صفرًا (تسوية بلا أثر ليست مستندًا).\r\n--   • لا حذف ولا تعديل لحركة سابقة: التصحيح بحركة لاحقة كما في الدفاتر.\r\n-- ============================================================================\r\n\r\nBEGIN","CREATE OR REPLACE FUNCTION public.post_stock_settlement(\r\n  p_warehouse_id uuid,\r\n  p_reason       text,\r\n  p_note         text,\r\n  p_lines        jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user  uuid := auth.uid();\r\n  v_doc   uuid;\r\n  v_no    text;\r\n  v_line  record;\r\n  v_before numeric;\r\n  v_diff  numeric;\r\n  v_unit_cost numeric;\r\n  v_total_value numeric := 0;\r\n  v_lines_posted integer := 0;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN\r\n    RAISE EXCEPTION 'Only an owner or manager may post a stock settlement'\r\n      USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  IF p_warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM public.warehouses w WHERE w.id = p_warehouse_id AND w.is_active) THEN\r\n    RAISE EXCEPTION 'Selected warehouse is unavailable';\r\n  END IF;\r\n  IF coalesce(btrim(p_reason), '') = '' THEN\r\n    RAISE EXCEPTION 'A settlement reason is required';\r\n  END IF;\r\n  IF coalesce(jsonb_typeof(p_lines), '') <> 'array' OR coalesce(jsonb_array_length(p_lines), 0) = 0 THEN\r\n    RAISE EXCEPTION 'A settlement needs at least one line';\r\n  END IF;\r\n\r\n  v_no := public.next_stock_adjustment_number();\r\n\r\n  INSERT INTO public.stock_adjustments\r\n    (document_number, warehouse_id, effective_date, reason, note, total_value, created_by)\r\n  VALUES\r\n    (v_no, p_warehouse_id, CURRENT_DATE, btrim(p_reason),\r\n     nullif(btrim(p_note), ''), 0, v_user)\r\n  RETURNING id INTO v_doc;\r\n\r\n  FOR v_line IN\r\n    SELECT (l ->> 'product_id')::uuid AS product_id,\r\n           (l ->> 'actual_qty')::numeric AS actual_qty\r\n      FROM jsonb_array_elements(p_lines) AS l\r\n  LOOP\r\n    IF v_line.product_id IS NULL OR v_line.actual_qty IS NULL OR v_line.actual_qty < 0 THEN\r\n      RAISE EXCEPTION 'Every settlement line needs an item and a non-negative actual quantity';\r\n    END IF;\r\n\r\n    SELECT coalesce(i.quantity, 0) INTO v_before\r\n      FROM public.inventory i\r\n     WHERE i.product_id = v_line.product_id\r\n       AND i.warehouse_id = p_warehouse_id\r\n       AND i.owner_type = 'COMPANY'\r\n       AND i.owner_id IS NULL;\r\n\r\n    v_before := coalesce(v_before, 0);\r\n    v_diff   := round(v_line.actual_qty - v_before, 3);\r\n\r\n    -- صفر فرق = لا حركة ولا سطر مستند.\r\n    IF v_diff = 0 THEN\r\n      CONTINUE;\r\n    END IF;\r\n\r\n    v_unit_cost := coalesce(\r\n      public.resolve_unit_cost(v_line.product_id, p_warehouse_id),\r\n      (SELECT p.cost_price FROM public.products p WHERE p.id = v_line.product_id),\r\n      0\r\n    );\r\n    v_total_value := v_total_value + round(v_diff * v_unit_cost, 2);\r\n    v_lines_posted := v_lines_posted + 1;\r\n\r\n    PERFORM public.post_stock_delta(\r\n      p_product_id           => v_line.product_id,\r\n      p_warehouse_id         => p_warehouse_id,\r\n      p_signed_qty           => v_diff,\r\n      -- زيادة: بقيمة الوحدة المعروفة. نقص: يقيّمه المحرّك بمتوسط الطبقة.\r\n      p_unit_cost            => CASE WHEN v_diff > 0 THEN v_unit_cost ELSE NULL END,\r\n      p_movement_kind        => 'ADJUSTMENT'::public.stock_movement_kind,\r\n      p_source_type          => 'stock_adjustment',\r\n      p_source_id            => v_doc,\r\n      p_note                 => 'تسوية جردية ' || v_no || ' — ' || btrim(p_reason)\r\n                                || coalesce(' — ' || nullif(btrim(p_note), ''), ''),\r\n      p_owner_type           => 'COMPANY'::public.owner_type,\r\n      p_owner_id             => NULL,\r\n      p_movement_type_legacy => 'adjustment'::public.movement_type\r\n    );\r\n\r\n    INSERT INTO public.stock_adjustment_items\r\n      (adjustment_id, product_id, quantity, unit_cost, total_cost, note)\r\n    VALUES\r\n      (v_doc, v_line.product_id, v_diff, v_unit_cost,\r\n       round(v_diff * v_unit_cost, 2),\r\n       format('%s → %s', v_before, v_line.actual_qty));\r\n  END LOOP;\r\n\r\n  IF v_lines_posted = 0 THEN\r\n    RAISE EXCEPTION 'No differences to post - every counted quantity matches the book balance';\r\n  END IF;\r\n\r\n  UPDATE public.stock_adjustments\r\n     SET total_value = round(v_total_value, 2)\r\n   WHERE id = v_doc;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'stock.settlement.posted', 'stock_adjustment', v_doc,\r\n    jsonb_build_object(\r\n      'document_number', v_no,\r\n      'warehouse_id', p_warehouse_id,\r\n      'reason', btrim(p_reason),\r\n      'lines', v_lines_posted,\r\n      'value_delta', round(v_total_value, 2)\r\n    ));\r\n\r\n  RETURN v_doc;\r\nEND $function$","COMMENT ON FUNCTION public.post_stock_settlement(uuid, text, text, jsonb) IS\r\n  'T-47: اعتماد تسوية جردية — مستند + حركات عبر المحرّك (كمية وقيمة) في معاملة واحدة. تستبدل الكتابة المباشرة على inventory/stock_movements من الواجهة.'","REVOKE ALL ON FUNCTION public.post_stock_settlement(uuid, text, text, jsonb) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.post_stock_settlement(uuid, text, text, jsonb) TO authenticated, service_role","-- عقد RPC: 45 تملك rpc_allowlist(). لا نعيد تعريفها هنا (نسخة ثانية تجمّد\r\n-- القائمة)، بل نتحقق أنها تحتوي الاسم إن كانت 45 مطبقة.\r\nDO $$\r\nBEGIN\r\n  IF to_regprocedure('public.rpc_allowlist()') IS NOT NULL\r\n     AND NOT ('post_stock_settlement' = ANY (public.rpc_allowlist())) THEN\r\n    RAISE EXCEPTION 'post_stock_settlement غير مدرجة في rpc_allowlist() — الواجهة ستحصل على 401'\r\n      USING HINT = 'أضف الاسم في migration 45 (rpc_allowlist) في نفس الهجرة التي تنشئ الدالة';\r\n  END IF;\r\nEND $$",COMMIT,"-- ============================================================================\r\n-- التحقق:\r\n--   SELECT has_function_privilege('authenticated',\r\n--            'public.post_stock_settlement(uuid,text,text,jsonb)', 'EXECUTE');\r\n--\r\n--   -- بعد اعتماد تسوية من الشاشة:\r\n--   SELECT quantity FROM public.inventory\r\n--    WHERE product_id = ... AND warehouse_id = ... AND owner_type = 'COMPANY';\r\n--   SELECT quantity, total_cost, movement_type, adjustment_reason\r\n--     FROM public.stock_movements WHERE source_type = 'stock_adjustment';\r\n--\r\n-- ROLLBACK: DROP FUNCTION public.post_stock_settlement(uuid, text, text, jsonb);\r\n--           (المستندات المُنشأة تُعكس بحركة لاحقة، لا تُمسح.)\r\n-- ============================================================================"}	stock_settlement_rpc
48	{"-- ════════════════════\r\n-- V1: التحويل الداخلي بنموذج «عدّ المنتجات» (موافق عليه من المالك)\r\n--\r\n-- يلغي نموذج smart_manufacture القديم (توزيع التكلفة حسب القيمة البيعية النسبية\r\n-- + قيد 5921 فاقد تشغيلي). النموذج الجديد:\r\n--   • كل الكميات بوحدة المنتج (عدّ صافٍ — لا كجم، لا سعات، لا نسب).\r\n--   • صادر منتج المصدر + وارد النواتج في معاملة واحدة عبر المحرك الوحيد.\r\n--   • تكلفة كل منتج تبقى كما هي (قرار المالك: ثابتة يدوياً) — لا توزيع تكلفة،\r\n--     لا انتقال تكلفة بين النواتج، لا قيود محاسبية (الحركة توازن ذاتياً).\r\n--   • الفاقد اختياري بوحدات: يُخصم من المصدر ويظهر في السجل التدقيق فقط.\r\n-- ════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.convert_stock(\r\n  _warehouse_id uuid,\r\n  _source_item_id uuid,\r\n  _source_qty numeric,\r\n  _outputs jsonb,\r\n  _loss_qty numeric,\r\n  _notes text\r\n)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_ref text;\r\n  v_doc_id uuid := gen_random_uuid();\r\n  v_total_output_qty numeric := 0;\r\n  r record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to run stock conversions';\r\n  END IF;\r\n  IF _warehouse_id IS NULL OR _source_item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse and source item are required';\r\n  END IF;\r\n  IF coalesce(_source_qty, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'Source quantity must be positive';\r\n  END IF;\r\n  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN\r\n    RAISE EXCEPTION 'At least one output line is required';\r\n  END IF;\r\n  IF coalesce(_loss_qty, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Loss quantity cannot be negative';\r\n  END IF;\r\n\r\n  -- المصدر: أي منتج نشط (حبوب خام أو غيرها — التحويل لا يقيد فئة المصدر)\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _source_item_id AND is_active\r\n  ) THEN\r\n    RAISE EXCEPTION 'Source item is not an active product';\r\n  END IF;\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL OR coalesce(r.qty, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every output line needs an item and a positive quantity';\r\n    END IF;\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM public.products\r\n      WHERE id = r.item_id AND is_active\r\n    ) THEN\r\n      RAISE EXCEPTION 'Output item % is not an active product', r.item_id;\r\n    END IF;\r\n    v_total_output_qty := v_total_output_qty + coalesce(r.qty, 0);\r\n  END LOOP;\r\n\r\n  -- القاعدة الرياضيّة الوحيدة: النواتج + الفاقد = المصدر (العدّ بوحدة المنتج)\r\n  IF v_total_output_qty + coalesce(_loss_qty, 0) <> coalesce(_source_qty, 0) THEN\r\n    RAISE EXCEPTION\r\n      'Outputs + loss (%) must equal the source quantity (%)',\r\n      v_total_output_qty + coalesce(_loss_qty, 0), coalesce(_source_qty, 0);\r\n  END IF;\r\n\r\n  v_ref := 'CV-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\r\n\r\n  -- 1) صادر المصدر — تكلفة المنتج تبقى كما هي (لا توزيع)\r\n  PERFORM public.post_stock_delta(\r\n    p_product_id => _source_item_id,\r\n    p_warehouse_id => _warehouse_id,\r\n    p_signed_qty => -coalesce(_source_qty, 0),\r\n    p_unit_cost => NULL,\r\n    p_movement_kind => 'PRODUCTION'::public.stock_movement_kind,\r\n    p_source_type => 'stock_conversion',\r\n    p_source_id => v_doc_id,\r\n    p_note => 'تحويل مخزون ' || v_ref || coalesce(' — ' || _notes, ''),\r\n    p_owner_type => 'COMPANY'::public.owner_type,\r\n    p_owner_id => NULL,\r\n    p_movement_type_legacy => 'production_out'::public.movement_type);\r\n\r\n  -- 2) وارد النواتج — بلا توزيع تكلفة (تكلفة كل منتج ثابتة يدوياً)\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, qty numeric)\r\n  LOOP\r\n    PERFORM public.post_stock_delta(\r\n      p_product_id => r.item_id,\r\n      p_warehouse_id => _warehouse_id,\r\n      p_signed_qty => coalesce(r.qty, 0),\r\n      p_unit_cost => NULL,\r\n      p_movement_kind => 'PRODUCTION'::public.stock_movement_kind,\r\n      p_source_type => 'stock_conversion',\r\n      p_source_id => v_doc_id,\r\n      p_note => 'تحويل مخزون ' || v_ref || coalesce(' — ' || _notes, ''),\r\n      p_owner_type => 'COMPANY'::public.owner_type,\r\n      p_owner_id => NULL,\r\n      p_movement_type_legacy => 'production_in'::public.movement_type);\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'stock.conversion', 'stock_movements', v_doc_id,\r\n    jsonb_build_object(\r\n      'doc_id', v_doc_id,\r\n      'ref', v_ref,\r\n      'warehouse_id', _warehouse_id,\r\n      'source_item_id', _source_item_id,\r\n      'source_qty', coalesce(_source_qty, 0),\r\n      'outputs', _outputs,\r\n      'loss_qty', coalesce(_loss_qty, 0),\r\n      'cost_model', 'FIXED_MANUAL — no allocation, no journal',\r\n      'notes', _notes\r\n    ));\r\n\r\n  RETURN v_ref;\r\nEND $function$"}	convert_stock_unit_count
49	{BEGIN,"-- Financial reads are finance-role data, not general staff data.\r\nDROP POLICY IF EXISTS \\"accounts_read\\" ON public.accounts","CREATE POLICY accounts_read_finance ON public.accounts\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_read_finance(auth.uid()))","DROP POLICY IF EXISTS \\"customer_ledger_view\\" ON public.customer_ledger","CREATE POLICY customer_ledger_view_finance ON public.customer_ledger\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_read_finance(auth.uid()))","DROP POLICY IF EXISTS \\"staff_view_customer_payments\\" ON public.customer_payments","CREATE POLICY customer_payments_view_finance ON public.customer_payments\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_read_finance(auth.uid()) OR public.has_role(auth.uid(), 'cashier'))","DROP POLICY IF EXISTS \\"journal_read\\" ON public.journal_entries","CREATE POLICY journal_read_finance ON public.journal_entries\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_read_finance(auth.uid()))","DROP POLICY IF EXISTS \\"journal_lines_read\\" ON public.journal_lines","CREATE POLICY journal_lines_read_finance ON public.journal_lines\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_read_finance(auth.uid()))","DROP POLICY IF EXISTS cost_tx_read ON public.item_cost_transactions","CREATE POLICY cost_tx_read_finance ON public.item_cost_transactions\r\n  FOR SELECT TO authenticated\r\n  USING (\r\n    public.can_read_finance(auth.uid())\r\n    AND ((owner_type = 'COMPANY'::owner_type) OR (owner_id = auth.uid()))\r\n  )","DROP POLICY IF EXISTS opening_bal_read ON public.opening_balance_documents","CREATE POLICY opening_bal_read_finance ON public.opening_balance_documents\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_read_finance(auth.uid()))","DROP POLICY IF EXISTS opening_bal_lines_read ON public.opening_balance_lines","CREATE POLICY opening_bal_lines_read_finance ON public.opening_balance_lines\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_read_finance(auth.uid()))","ALTER VIEW public.opening_balance_summary SET (security_invoker = true)","-- Supplier ledger writes and reads are available through finance roles only;\r\n-- trusted SECURITY DEFINER posting functions remain able to maintain the ledger.\r\nDROP POLICY IF EXISTS supplier_ledger_read_all ON public.supplier_ledger","DROP POLICY IF EXISTS supplier_ledger_insert_auth ON public.supplier_ledger","DROP POLICY IF EXISTS supplier_ledger_update_auth ON public.supplier_ledger","CREATE POLICY supplier_ledger_read_finance ON public.supplier_ledger\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_read_finance(auth.uid()))","DROP POLICY IF EXISTS \\"supplier_payments_read_auth\\" ON public.supplier_payments","DROP POLICY IF EXISTS supplier_payments_read_all ON public.supplier_payments","CREATE POLICY supplier_payments_read_finance ON public.supplier_payments\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_read_finance(auth.uid()))","CREATE OR REPLACE FUNCTION public.get_supplier_statement(\r\n  p_supplier_id uuid,\r\n  p_start_date timestamptz DEFAULT NULL,\r\n  p_end_date timestamptz DEFAULT NULL\r\n)\r\nRETURNS TABLE (\r\n  id uuid,\r\n  occurred_at timestamptz,\r\n  entry_type text,\r\n  debit numeric,\r\n  credit numeric,\r\n  running_balance numeric,\r\n  reference_type text,\r\n  reference_id uuid,\r\n  due_date date,\r\n  note text\r\n)\r\nLANGUAGE plpgsql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF NOT public.can_read_finance(auth.uid()) THEN\r\n    RAISE EXCEPTION 'Only finance roles may read supplier statements'\r\n      USING ERRCODE = '42501';\r\n  END IF;\r\n  RETURN QUERY\r\n    WITH ordered_entries AS (\r\n      SELECT sl.id, sl.occurred_at, sl.entry_type, sl.debit, sl.credit,\r\n        SUM(sl.credit - sl.debit) OVER (ORDER BY sl.occurred_at ASC, sl.id ASC) AS running_balance,\r\n        sl.reference_type, sl.reference_id, sl.due_date, sl.note\r\n      FROM public.supplier_ledger sl\r\n      WHERE sl.supplier_id = p_supplier_id\r\n    )\r\n    SELECT oe.id, oe.occurred_at, oe.entry_type, oe.debit, oe.credit, oe.running_balance,\r\n      oe.reference_type, oe.reference_id, oe.due_date, oe.note\r\n    FROM ordered_entries oe\r\n    WHERE (p_start_date IS NULL OR oe.occurred_at >= p_start_date)\r\n      AND (p_end_date IS NULL OR oe.occurred_at <= p_end_date)\r\n    ORDER BY oe.occurred_at DESC, oe.id DESC;\r\nEND;\r\n$function$","REVOKE EXECUTE ON FUNCTION public.get_supplier_statement(uuid, timestamptz, timestamptz)\r\n  FROM PUBLIC, anon, authenticated","GRANT EXECUTE ON FUNCTION public.get_supplier_statement(uuid, timestamptz, timestamptz)\r\n  TO service_role","GRANT EXECUTE ON FUNCTION public.get_supplier_statement(uuid, timestamptz, timestamptz)\r\n  TO authenticated","-- The seven-argument journal API is the internal system-posting entry point.\r\n-- Trusted SECURITY DEFINER business RPCs call the seven-argument function as owner.\r\nREVOKE EXECUTE ON FUNCTION public.create_journal_entry(text, date, text, uuid, boolean, jsonb, boolean)\r\n  FROM PUBLIC, anon, authenticated","REVOKE EXECUTE ON FUNCTION public.reverse_journal_entry(uuid, text)\r\n  FROM PUBLIC, anon, authenticated","CREATE OR REPLACE FUNCTION public.reverse_journal_entry(p_entry_id uuid, p_reason text)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_old record;\r\n  v_id uuid;\r\nBEGIN\r\n  IF v_user IS NULL OR NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')\r\n      OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may reverse journal entries';\r\n  END IF;\r\n  IF p_reason IS NULL OR btrim(p_reason) = '' THEN\r\n    RAISE EXCEPTION 'Reversing an entry requires a reason';\r\n  END IF;\r\n  SELECT * INTO v_old FROM public.journal_entries WHERE id = p_entry_id FOR UPDATE;\r\n  IF NOT FOUND OR v_old.status <> 'POSTED' THEN\r\n    RAISE EXCEPTION 'Only a posted entry can be reversed';\r\n  END IF;\r\n\r\n  SELECT public.create_journal_entry(\r\n    'عكس القيد ' || v_old.entry_number || ': ' || btrim(p_reason),\r\n    CURRENT_DATE, 'journal_reversal', p_entry_id, v_old.is_system,\r\n    (SELECT coalesce(jsonb_agg(jsonb_build_object(\r\n      'account_code', a.code,\r\n      'debit', CASE WHEN jl.debit > 0 THEN 0 ELSE jl.credit END,\r\n      'credit', CASE WHEN jl.debit > 0 THEN jl.debit ELSE 0 END,\r\n      'memo', coalesce(jl.memo, a.name_ar)\r\n    ) ORDER BY jl.id), '[]'::jsonb)\r\n    FROM public.journal_lines jl JOIN public.accounts a ON a.id = jl.account_id\r\n    WHERE jl.entry_id = p_entry_id),\r\n    true\r\n  ) INTO v_id;\r\n\r\n  UPDATE public.journal_entries SET status = 'REVERSED' WHERE id = p_entry_id;\r\n  RETURN v_id;\r\nEND;\r\n$function$","GRANT EXECUTE ON FUNCTION public.reverse_journal_entry(uuid, text) TO authenticated, service_role","CREATE OR REPLACE FUNCTION public.create_opening_balance(\r\n  _effective_date date,\r\n  _lines jsonb,\r\n  _notes text DEFAULT NULL::text\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_id uuid;\r\n  v_num text;\r\n  l jsonb;\r\n  v_side text;\r\n  v_section text;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')\r\n          OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may open the books';\r\n  END IF;\r\n  IF _effective_date IS NULL THEN\r\n    RAISE EXCEPTION 'Effective date is required';\r\n  END IF;\r\n  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN\r\n    RAISE EXCEPTION 'An opening entry needs at least one line';\r\n  END IF;\r\n\r\n  v_num := 'OB-' || to_char(_effective_date, 'YYYYMMDD') || '-' ||\r\n           lpad(nextval('public.opening_balance_seq')::text, 3, '0');\r\n  INSERT INTO public.opening_balance_documents\r\n    (document_number, effective_date, status, fiscal_year, notes, created_by)\r\n  VALUES\r\n    (v_num, _effective_date, 'DRAFT', EXTRACT(YEAR FROM _effective_date)::int,\r\n     nullif(btrim(coalesce(_notes, '')), ''), v_user)\r\n  RETURNING id INTO v_id;\r\n\r\n  FOR l IN SELECT * FROM jsonb_array_elements(_lines)\r\n  LOOP\r\n    v_section := l->>'section';\r\n    IF v_section NOT IN ('STOCK','RECEIVABLE','PAYABLE','CASH','BANK','ASSET','LIABILITY','CAPITAL') THEN\r\n      RAISE EXCEPTION 'Unknown opening section: %', v_section;\r\n    END IF;\r\n    v_side := CASE WHEN v_section IN ('STOCK','RECEIVABLE','CASH','BANK','ASSET')\r\n                   THEN 'DEBIT' ELSE 'CREDIT' END;\r\n    IF coalesce((l->>'amount')::numeric, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Line amount must be greater than zero (section %)', v_section;\r\n    END IF;\r\n    IF v_section = 'STOCK' AND ((l->>'product_id') IS NULL OR (l->>'warehouse_id') IS NULL\r\n       OR coalesce((l->>'quantity')::numeric, 0) <= 0) THEN\r\n      RAISE EXCEPTION 'Stock opening line requires an item, warehouse and positive quantity';\r\n    END IF;\r\n    IF v_section = 'RECEIVABLE' AND (l->>'customer_id') IS NULL THEN\r\n      RAISE EXCEPTION 'Receivable opening line requires a customer';\r\n    END IF;\r\n    IF v_section = 'PAYABLE' AND (l->>'supplier_id') IS NULL THEN\r\n      RAISE EXCEPTION 'Payable opening line requires a supplier';\r\n    END IF;\r\n\r\n    INSERT INTO public.opening_balance_lines\r\n      (document_id, section, side, ref_type, ref_id, product_id, warehouse_id,\r\n       customer_id, supplier_id, description, quantity, unit_cost, amount, ledger_account_code)\r\n    VALUES\r\n      (v_id, v_section, v_side, l->>'ref_type', (l->>'ref_id')::uuid,\r\n       (l->>'product_id')::uuid, (l->>'warehouse_id')::uuid,\r\n       (l->>'customer_id')::uuid, (l->>'supplier_id')::uuid,\r\n       coalesce(nullif(btrim(coalesce(l->>'description', '')), ''), v_section),\r\n       (l->>'quantity')::numeric, (l->>'unit_cost')::numeric,\r\n       (l->>'amount')::numeric, nullif(btrim(l->>'ledger_account_code'), ''));\r\n  END LOOP;\r\n  RETURN v_id;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.update_opening_balance(\r\n  _document_id uuid,\r\n  _effective_date date,\r\n  _lines jsonb,\r\n  _notes text DEFAULT NULL::text\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_doc record;\r\n  l jsonb;\r\n  v_section text;\r\n  v_side text;\r\nBEGIN\r\n  IF v_user IS NULL OR NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')\r\n      OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may edit opening balances';\r\n  END IF;\r\n  IF _effective_date IS NULL THEN RAISE EXCEPTION 'Effective date is required'; END IF;\r\n  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN\r\n    RAISE EXCEPTION 'An opening entry needs at least one line';\r\n  END IF;\r\n\r\n  SELECT * INTO v_doc FROM public.opening_balance_documents WHERE id = _document_id FOR UPDATE;\r\n  IF NOT FOUND OR v_doc.status <> 'DRAFT' THEN\r\n    RAISE EXCEPTION 'Only a draft opening document can be edited';\r\n  END IF;\r\n\r\n  UPDATE public.opening_balance_documents\r\n    SET effective_date = _effective_date,\r\n        fiscal_year = EXTRACT(YEAR FROM _effective_date)::int,\r\n        notes = nullif(btrim(coalesce(_notes, '')), '')\r\n    WHERE id = _document_id;\r\n  DELETE FROM public.opening_balance_lines WHERE document_id = _document_id;\r\n\r\n  FOR l IN SELECT * FROM jsonb_array_elements(_lines)\r\n  LOOP\r\n    v_section := l->>'section';\r\n    IF v_section NOT IN ('STOCK','RECEIVABLE','PAYABLE','CASH','BANK','ASSET','LIABILITY','CAPITAL') THEN\r\n      RAISE EXCEPTION 'Unknown opening section: %', v_section;\r\n    END IF;\r\n    v_side := CASE WHEN v_section IN ('STOCK','RECEIVABLE','CASH','BANK','ASSET')\r\n                   THEN 'DEBIT' ELSE 'CREDIT' END;\r\n    IF coalesce((l->>'amount')::numeric, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Line amount must be greater than zero (section %)', v_section;\r\n    END IF;\r\n    IF v_section = 'STOCK' AND ((l->>'product_id') IS NULL OR (l->>'warehouse_id') IS NULL\r\n       OR coalesce((l->>'quantity')::numeric, 0) <= 0) THEN\r\n      RAISE EXCEPTION 'Stock opening line requires an item, warehouse and positive quantity';\r\n    END IF;\r\n    IF v_section = 'RECEIVABLE' AND (l->>'customer_id') IS NULL THEN\r\n      RAISE EXCEPTION 'Receivable opening line requires a customer';\r\n    END IF;\r\n    IF v_section = 'PAYABLE' AND (l->>'supplier_id') IS NULL THEN\r\n      RAISE EXCEPTION 'Payable opening line requires a supplier';\r\n    END IF;\r\n\r\n    INSERT INTO public.opening_balance_lines\r\n      (document_id, section, side, ref_type, ref_id, product_id, warehouse_id,\r\n       customer_id, supplier_id, description, quantity, unit_cost, amount, ledger_account_code)\r\n    VALUES\r\n      (_document_id, v_section, v_side, l->>'ref_type', (l->>'ref_id')::uuid,\r\n       (l->>'product_id')::uuid, (l->>'warehouse_id')::uuid,\r\n       (l->>'customer_id')::uuid, (l->>'supplier_id')::uuid,\r\n       coalesce(nullif(btrim(coalesce(l->>'description', '')), ''), v_section),\r\n       (l->>'quantity')::numeric, (l->>'unit_cost')::numeric,\r\n       (l->>'amount')::numeric, nullif(btrim(l->>'ledger_account_code'), ''));\r\n  END LOOP;\r\n  RETURN _document_id;\r\nEND;\r\n$function$","GRANT EXECUTE ON FUNCTION public.update_opening_balance(uuid, date, jsonb, text) TO authenticated, service_role","CREATE OR REPLACE FUNCTION public.post_opening_balance(_document_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_doc record;\r\n  v_debit numeric;\r\n  v_credit numeric;\r\n  v_capital numeric;\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_journal uuid;\r\n  v_account text;\r\n  v_balance numeric;\r\n  l record;\r\nBEGIN\r\n  IF v_user IS NULL OR NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')\r\n      OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may post opening balances';\r\n  END IF;\r\n  SELECT * INTO v_doc FROM public.opening_balance_documents WHERE id = _document_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Opening document not found'; END IF;\r\n  IF v_doc.status <> 'DRAFT' THEN\r\n    RAISE EXCEPTION 'Document % is already %', v_doc.document_number, v_doc.status;\r\n  END IF;\r\n\r\n  SELECT coalesce(sum(amount) FILTER (WHERE side = 'DEBIT'), 0),\r\n         coalesce(sum(amount) FILTER (WHERE side = 'CREDIT'), 0),\r\n         coalesce(sum(amount) FILTER (WHERE section = 'CAPITAL'), 0)\r\n    INTO v_debit, v_credit, v_capital\r\n    FROM public.opening_balance_lines WHERE document_id = _document_id;\r\n  IF v_debit <> v_credit THEN\r\n    RAISE EXCEPTION 'Opening entry does not balance: debits % vs credits % (difference %).',\r\n      round(v_debit, 2)::text, round(v_credit, 2)::text, round(v_debit - v_credit, 2)::text;\r\n  END IF;\r\n\r\n  FOR l IN SELECT * FROM public.opening_balance_lines WHERE document_id = _document_id ORDER BY id\r\n  LOOP\r\n    IF l.section = 'STOCK' THEN\r\n      PERFORM public.post_stock_delta(\r\n        p_product_id => l.product_id, p_warehouse_id => l.warehouse_id,\r\n        p_signed_qty => l.quantity, p_unit_cost => coalesce(l.unit_cost, 0),\r\n        p_movement_kind => 'OPENING', p_movement_type_legacy => 'opening',\r\n        p_source_type => 'opening_balance', p_source_id => _document_id,\r\n        p_note => 'رصيد افتتاحي ' || v_doc.document_number,\r\n        p_owner_type => 'COMPANY', p_owner_id => NULL);\r\n      PERFORM public.apply_cost_movement(\r\n        p_product_id => l.product_id, p_warehouse_id => l.warehouse_id,\r\n        p_signed_qty => l.quantity, p_incoming_cost => l.unit_cost,\r\n        p_source_type => 'opening_balance', p_source_id => _document_id,\r\n        p_note => 'رصيد افتتاحي ' || v_doc.document_number);\r\n      SELECT coalesce(l.ledger_account_code,\r\n        CASE p.item_class WHEN 'RAW_MATERIAL' THEN '1311' WHEN 'BY_PRODUCT' THEN '1314' ELSE '1313' END)\r\n        INTO v_account FROM public.products p WHERE p.id = l.product_id;\r\n      v_lines := v_lines || jsonb_build_object('account_code', v_account,\r\n        'debit', round(l.amount, 2), 'memo', 'رصيد افتتاحي — ' || l.description);\r\n\r\n    ELSIF l.section = 'RECEIVABLE' THEN\r\n      INSERT INTO public.customer_ledger\r\n        (customer_id, entry_type, debit, credit, reference_id, reference_type, occurred_at, created_by, note)\r\n      VALUES (l.customer_id, 'adjustment', l.amount, 0, _document_id, 'opening_balance',\r\n        v_doc.effective_date::timestamptz, v_user, 'رصيد افتتاحي ' || v_doc.document_number);\r\n      v_lines := v_lines || jsonb_build_object('account_code', coalesce(l.ledger_account_code, '1211'),\r\n        'debit', round(l.amount, 2), 'memo', 'رصيد افتتاحي — ' || l.description);\r\n\r\n    ELSIF l.section = 'PAYABLE' THEN\r\n      UPDATE public.suppliers SET balance = coalesce(balance, 0) + l.amount WHERE id = l.supplier_id;\r\n      SELECT balance INTO v_balance FROM public.suppliers WHERE id = l.supplier_id;\r\n      INSERT INTO public.supplier_ledger\r\n        (supplier_id, entry_type, debit, credit, balance_after, reference_type, reference_id,\r\n         occurred_at, source_key, note, created_by)\r\n      VALUES (l.supplier_id, 'OPENING_BALANCE', 0, l.amount, v_balance, 'opening_balance', _document_id,\r\n        v_doc.effective_date::timestamptz, 'OB-' || _document_id::text || '-' || l.id::text,\r\n        'رصيد افتتاحي ' || v_doc.document_number, v_user)\r\n      ON CONFLICT (source_key) DO NOTHING;\r\n      v_lines := v_lines || jsonb_build_object('account_code', coalesce(l.ledger_account_code, '2111'),\r\n        'credit', round(l.amount, 2), 'memo', 'رصيد افتتاحي — ' || l.description);\r\n\r\n    ELSE\r\n      v_account := coalesce(l.ledger_account_code,\r\n        CASE l.section WHEN 'CASH' THEN '1101' WHEN 'BANK' THEN '1111'\r\n          WHEN 'ASSET' THEN '1411' WHEN 'LIABILITY' THEN '2111' WHEN 'CAPITAL' THEN '3111' END);\r\n      IF v_account IS NULL THEN RAISE EXCEPTION 'No ledger account mapping for %', l.section; END IF;\r\n      v_lines := v_lines || jsonb_build_object('account_code', v_account,\r\n        CASE WHEN l.side = 'DEBIT' THEN 'debit' ELSE 'credit' END,\r\n        round(l.amount, 2), 'memo', 'رصيد افتتاحي — ' || l.description);\r\n    END IF;\r\n  END LOOP;\r\n\r\n  v_journal := public.create_journal_entry(\r\n    'رصيد افتتاحي ' || v_doc.document_number, v_doc.effective_date,\r\n    'opening_balance', _document_id, true, v_lines);\r\n\r\n  UPDATE public.opening_balance_documents\r\n    SET total_assets = v_debit, total_liabilities = v_credit - v_capital,\r\n        capital_required = v_debit - v_credit + v_capital,\r\n        status = 'POSTED', posted_by = v_user, posted_at = now()\r\n    WHERE id = _document_id;\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'opening_balance.posted', 'opening_balance', _document_id,\r\n    jsonb_build_object('document_number', v_doc.document_number, 'debits', v_debit,\r\n      'credits', v_credit, 'journal_entry_id', v_journal));\r\n  RETURN _document_id;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.reverse_opening_balance(_document_id uuid, _reason text)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_doc record;\r\n  v_new uuid;\r\n  v_journal uuid;\r\n  v_balance numeric;\r\n  l record;\r\nBEGIN\r\n  IF v_user IS NULL OR NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')\r\n      OR public.has_role(v_user, 'accountant')) THEN\r\n    RAISE EXCEPTION 'Only an owner, manager or accountant may reverse opening balances';\r\n  END IF;\r\n  IF _reason IS NULL OR btrim(_reason) = '' THEN\r\n    RAISE EXCEPTION 'Reversing an opening entry requires a reason';\r\n  END IF;\r\n  SELECT * INTO v_doc FROM public.opening_balance_documents WHERE id = _document_id FOR UPDATE;\r\n  IF NOT FOUND OR v_doc.status <> 'POSTED' THEN\r\n    RAISE EXCEPTION 'Only a posted opening document can be reversed';\r\n  END IF;\r\n\r\n  INSERT INTO public.opening_balance_documents\r\n    (document_number, effective_date, status, fiscal_year, reverses_document_id,\r\n     notes, created_by, posted_at, posted_by)\r\n  VALUES ('OBR-' || v_doc.document_number, v_doc.effective_date, 'POSTED', v_doc.fiscal_year,\r\n    _document_id, 'عكس القيد الافتتاحي ' || v_doc.document_number || ': ' || btrim(_reason),\r\n    v_user, now(), v_user)\r\n  RETURNING id INTO v_new;\r\n\r\n  INSERT INTO public.opening_balance_lines\r\n    (document_id, section, side, ref_type, ref_id, product_id, warehouse_id,\r\n     customer_id, supplier_id, description, quantity, unit_cost, amount, ledger_account_code)\r\n  SELECT v_new, section, CASE WHEN side = 'DEBIT' THEN 'CREDIT' ELSE 'DEBIT' END,\r\n    ref_type, ref_id, product_id, warehouse_id, customer_id, supplier_id,\r\n    'عكس: ' || description, quantity, unit_cost, amount, ledger_account_code\r\n  FROM public.opening_balance_lines WHERE document_id = _document_id;\r\n\r\n  FOR l IN SELECT * FROM public.opening_balance_lines WHERE document_id = _document_id ORDER BY id\r\n  LOOP\r\n    IF l.section = 'STOCK' THEN\r\n      PERFORM public.post_stock_delta(\r\n        p_product_id => l.product_id, p_warehouse_id => l.warehouse_id,\r\n        p_signed_qty => -l.quantity, p_unit_cost => coalesce(l.unit_cost, 0),\r\n        p_movement_kind => 'ADJUSTMENT', p_movement_type_legacy => 'opening',\r\n        p_source_type => 'opening_balance_reversal', p_source_id => v_new,\r\n        p_note => 'عكس رصيد افتتاحي ' || v_doc.document_number,\r\n        p_owner_type => 'COMPANY', p_owner_id => NULL);\r\n      PERFORM public.apply_cost_movement(\r\n        p_product_id => l.product_id, p_warehouse_id => l.warehouse_id,\r\n        p_signed_qty => -l.quantity, p_incoming_cost => NULL,\r\n        p_source_type => 'opening_balance_reversal', p_source_id => v_new,\r\n        p_note => 'عكس رصيد افتتاحي ' || v_doc.document_number);\r\n\r\n    ELSIF l.section = 'RECEIVABLE' THEN\r\n      INSERT INTO public.customer_ledger\r\n        (customer_id, entry_type, debit, credit, reference_id, reference_type, occurred_at, created_by, note)\r\n      VALUES (l.customer_id, 'adjustment', 0, l.amount, v_new, 'opening_balance_reversal',\r\n        now(), v_user, 'عكس رصيد افتتاحي ' || v_doc.document_number);\r\n\r\n    ELSIF l.section = 'PAYABLE' THEN\r\n      UPDATE public.suppliers SET balance = coalesce(balance, 0) - l.amount WHERE id = l.supplier_id;\r\n      SELECT balance INTO v_balance FROM public.suppliers WHERE id = l.supplier_id;\r\n      INSERT INTO public.supplier_ledger\r\n        (supplier_id, entry_type, debit, credit, balance_after, reference_type, reference_id,\r\n         occurred_at, source_key, note, created_by)\r\n      VALUES (l.supplier_id, 'OPENING_BALANCE', l.amount, 0, v_balance, 'opening_balance_reversal', v_new,\r\n        now(), 'OBR-' || _document_id::text || '-' || l.id::text,\r\n        'عكس رصيد افتتاحي ' || v_doc.document_number || ': ' || btrim(_reason), v_user)\r\n      ON CONFLICT (source_key) DO NOTHING;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  SELECT id INTO v_journal FROM public.journal_entries\r\n    WHERE source_type = 'opening_balance' AND source_id = _document_id AND status = 'POSTED'\r\n    FOR UPDATE;\r\n  IF v_journal IS NOT NULL THEN\r\n    PERFORM public.reverse_journal_entry(v_journal, btrim(_reason));\r\n  END IF;\r\n\r\n  UPDATE public.opening_balance_documents SET status = 'REVERSED' WHERE id = _document_id;\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'opening_balance.reversed', 'opening_balance', _document_id,\r\n    jsonb_build_object('reversal_document_id', v_new, 'journal_entry_id', v_journal, 'reason', btrim(_reason)));\r\n  RETURN v_new;\r\nEND;\r\n$function$",COMMIT}	finance_permissions_and_opening_balance_fixes
50	{"-- ============================================================================\r\n-- 47_stock_settlement_rpc.sql\r\n--\r\n-- إغلاق آخر مسار يكتب المخزون من المتصفح مباشرة.\r\n--\r\n-- المشكلة:\r\n--   src/components/stock/settlement-wizard-sheet.tsx كانت تفعل:\r\n--     supabase.from(\\"inventory\\").upsert({ quantity: actual }, ...)\r\n--     supabase.from(\\"stock_movements\\").insert({ movement_type: \\"adjustment\\", ... })\r\n--   بعد 43 (tg_stock_movements_engine_only) الكتابة المباشرة على الحركات\r\n--   مرفوضة، ومعها:\r\n--     • القيمة لا تُقيَّد: صف inventory يُكتب بكمية جديدة بلا apply_cost_movement،\r\n--       فتنفصل الكمية عن التكلفة ويختل تقييم المخزون بصمت.\r\n--     • الحركة لا تحمل movement_kind ولا source، فلا يمكن ربطها بمستند ولا\r\n--       معرفة من اعتمدها وبأي سبب.\r\n--     • التحديثان منفصلان (inventory ثم stock_movements) وليسا معاملة واحدة:\r\n--       انقطاع الشبكة في المنتصف يترك كمية جديدة وحركة مفقودة.\r\n--\r\n-- الحل: دالة واحدة SECURITY DEFINER تعتمد التسوية كاملة في معاملة واحدة،\r\n-- وتستخدم **نفس المحرك** post_stock_delta (كمية + قيمة)، وتوثّق مستندًا في\r\n-- stock_adjustments / stock_adjustment_items (جدولان موجودان ولا يكتب فيهما\r\n-- أحد)، وسجل تدقيق.\r\n--\r\n-- الأمان:\r\n--   • المستدعي موظف نشط + مالك أو مدير (التسوية تعدّل رصيدًا محاسبيًا).\r\n--   • السبب إلزامي، والفرق لا يكون صفرًا (تسوية بلا أثر ليست مستندًا).\r\n--   • لا حذف ولا تعديل لحركة سابقة: التصحيح بحركة لاحقة كما في الدفاتر.\r\n-- ============================================================================\r\n\r\nBEGIN","CREATE OR REPLACE FUNCTION public.post_stock_settlement(\r\n  p_warehouse_id uuid,\r\n  p_reason       text,\r\n  p_note         text,\r\n  p_lines        jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user  uuid := auth.uid();\r\n  v_doc   uuid;\r\n  v_no    text;\r\n  v_line  record;\r\n  v_before numeric;\r\n  v_diff  numeric;\r\n  v_unit_cost numeric;\r\n  v_total_value numeric := 0;\r\n  v_lines_posted integer := 0;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user, 'owner') OR public.has_role(v_user, 'manager')) THEN\r\n    RAISE EXCEPTION 'Only an owner or manager may post a stock settlement'\r\n      USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  IF p_warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM public.warehouses w WHERE w.id = p_warehouse_id AND w.is_active) THEN\r\n    RAISE EXCEPTION 'Selected warehouse is unavailable';\r\n  END IF;\r\n  IF coalesce(btrim(p_reason), '') = '' THEN\r\n    RAISE EXCEPTION 'A settlement reason is required';\r\n  END IF;\r\n  IF coalesce(jsonb_typeof(p_lines), '') <> 'array' OR coalesce(jsonb_array_length(p_lines), 0) = 0 THEN\r\n    RAISE EXCEPTION 'A settlement needs at least one line';\r\n  END IF;\r\n\r\n  v_no := public.next_stock_adjustment_number();\r\n\r\n  INSERT INTO public.stock_adjustments\r\n    (document_number, warehouse_id, effective_date, reason, note, total_value, created_by)\r\n  VALUES\r\n    (v_no, p_warehouse_id, CURRENT_DATE, btrim(p_reason),\r\n     nullif(btrim(p_note), ''), 0, v_user)\r\n  RETURNING id INTO v_doc;\r\n\r\n  FOR v_line IN\r\n    SELECT (l ->> 'product_id')::uuid AS product_id,\r\n           (l ->> 'actual_qty')::numeric AS actual_qty\r\n      FROM jsonb_array_elements(p_lines) AS l\r\n  LOOP\r\n    IF v_line.product_id IS NULL OR v_line.actual_qty IS NULL OR v_line.actual_qty < 0 THEN\r\n      RAISE EXCEPTION 'Every settlement line needs an item and a non-negative actual quantity';\r\n    END IF;\r\n\r\n    SELECT coalesce(i.quantity, 0) INTO v_before\r\n      FROM public.inventory i\r\n     WHERE i.product_id = v_line.product_id\r\n       AND i.warehouse_id = p_warehouse_id\r\n       AND i.owner_type = 'COMPANY'\r\n       AND i.owner_id IS NULL;\r\n\r\n    v_before := coalesce(v_before, 0);\r\n    v_diff   := round(v_line.actual_qty - v_before, 3);\r\n\r\n    -- صفر فرق = لا حركة ولا سطر مستند.\r\n    IF v_diff = 0 THEN\r\n      CONTINUE;\r\n    END IF;\r\n\r\n    v_unit_cost := coalesce(\r\n      public.resolve_unit_cost(v_line.product_id, p_warehouse_id),\r\n      (SELECT p.cost_price FROM public.products p WHERE p.id = v_line.product_id),\r\n      0\r\n    );\r\n    v_total_value := v_total_value + round(v_diff * v_unit_cost, 2);\r\n    v_lines_posted := v_lines_posted + 1;\r\n\r\n    PERFORM public.post_stock_delta(\r\n      p_product_id           => v_line.product_id,\r\n      p_warehouse_id         => p_warehouse_id,\r\n      p_signed_qty           => v_diff,\r\n      -- زيادة: بقيمة الوحدة المعروفة. نقص: يقيّمه المحرّك بمتوسط الطبقة.\r\n      p_unit_cost            => CASE WHEN v_diff > 0 THEN v_unit_cost ELSE NULL END,\r\n      p_movement_kind        => 'ADJUSTMENT'::public.stock_movement_kind,\r\n      p_source_type          => 'stock_adjustment',\r\n      p_source_id            => v_doc,\r\n      p_note                 => 'تسوية جردية ' || v_no || ' — ' || btrim(p_reason)\r\n                                || coalesce(' — ' || nullif(btrim(p_note), ''), ''),\r\n      p_owner_type           => 'COMPANY'::public.owner_type,\r\n      p_owner_id             => NULL,\r\n      p_movement_type_legacy => 'adjustment'::public.movement_type\r\n    );\r\n\r\n    INSERT INTO public.stock_adjustment_items\r\n      (adjustment_id, product_id, quantity, unit_cost, total_cost, note)\r\n    VALUES\r\n      (v_doc, v_line.product_id, v_diff, v_unit_cost,\r\n       round(v_diff * v_unit_cost, 2),\r\n       format('%s → %s', v_before, v_line.actual_qty));\r\n  END LOOP;\r\n\r\n  IF v_lines_posted = 0 THEN\r\n    RAISE EXCEPTION 'No differences to post - every counted quantity matches the book balance';\r\n  END IF;\r\n\r\n  UPDATE public.stock_adjustments\r\n     SET total_value = round(v_total_value, 2)\r\n   WHERE id = v_doc;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'stock.settlement.posted', 'stock_adjustment', v_doc,\r\n    jsonb_build_object(\r\n      'document_number', v_no,\r\n      'warehouse_id', p_warehouse_id,\r\n      'reason', btrim(p_reason),\r\n      'lines', v_lines_posted,\r\n      'value_delta', round(v_total_value, 2)\r\n    ));\r\n\r\n  RETURN v_doc;\r\nEND $function$","COMMENT ON FUNCTION public.post_stock_settlement(uuid, text, text, jsonb) IS\r\n  'T-47: اعتماد تسوية جردية — مستند + حركات عبر المحرّك (كمية وقيمة) في معاملة واحدة. تستبدل الكتابة المباشرة على inventory/stock_movements من الواجهة.'","REVOKE ALL ON FUNCTION public.post_stock_settlement(uuid, text, text, jsonb) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.post_stock_settlement(uuid, text, text, jsonb) TO authenticated, service_role","-- عقد RPC: 45 تملك rpc_allowlist(). لا نعيد تعريفها هنا (نسخة ثانية تجمّد\r\n-- القائمة)، بل نتحقق أنها تحتوي الاسم إن كانت 45 مطبقة.\r\nDO $$\r\nBEGIN\r\n  IF to_regprocedure('public.rpc_allowlist()') IS NOT NULL\r\n     AND NOT ('post_stock_settlement' = ANY (public.rpc_allowlist())) THEN\r\n    RAISE EXCEPTION 'post_stock_settlement غير مدرجة في rpc_allowlist() — الواجهة ستحصل على 401'\r\n      USING HINT = 'أضف الاسم في migration 45 (rpc_allowlist) في نفس الهجرة التي تنشئ الدالة';\r\n  END IF;\r\nEND $$",COMMIT,"-- ============================================================================\r\n-- التحقق:\r\n--   SELECT has_function_privilege('authenticated',\r\n--            'public.post_stock_settlement(uuid,text,text,jsonb)', 'EXECUTE');\r\n--\r\n--   -- بعد اعتماد تسوية من الشاشة:\r\n--   SELECT quantity FROM public.inventory\r\n--    WHERE product_id = ... AND warehouse_id = ... AND owner_type = 'COMPANY';\r\n--   SELECT quantity, total_cost, movement_type, adjustment_reason\r\n--     FROM public.stock_movements WHERE source_type = 'stock_adjustment';\r\n--\r\n-- ROLLBACK: DROP FUNCTION public.post_stock_settlement(uuid, text, text, jsonb);\r\n--           (المستندات المُنشأة تُعكس بحركة لاحقة، لا تُمسح.)\r\n-- ============================================================================"}	stock_settlement_rpc_reconcile
51	{"-- Fix: create_sale(date) overload updated stock_movements.created_at while\r\n-- tg_stock_movements_engine_only was armed OFF, so every product sale raised\r\n-- \\"Stock movements must be posted through post_stock_delta\\". Arm the engine\r\n-- flag around the timestamp adjustment (config is transaction-scoped, so the\r\n-- trigger sees 'on' for these UPDATEs only).\r\nCREATE OR REPLACE FUNCTION public.create_sale(_warehouse_id uuid, _customer_id uuid, _payment_method text, _paid numeric, _discount numeric, _note text, _items jsonb, _sale_date date)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id uuid;\r\n  v_posted_at  timestamptz;\r\nBEGIN\r\n  IF _sale_date IS NULL THEN\r\n    RAISE EXCEPTION 'Sale date is required';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'Cart is empty';\r\n  END IF;\r\n\r\n  v_invoice_id := public.create_sale(\r\n    _warehouse_id, _customer_id, _payment_method, _paid, _discount, _note, _items\r\n  );\r\n\r\n  v_posted_at := _sale_date::timestamp + localtime;\r\n\r\n  UPDATE public.sales_invoices\r\n  SET created_at = v_posted_at, updated_at = now()\r\n  WHERE id = v_invoice_id;\r\n\r\n  PERFORM set_config('app.stock_engine', 'on', true);\r\n\r\n  UPDATE public.stock_movements\r\n  SET created_at = v_posted_at\r\n  WHERE source_type = 'sales_invoice' AND source_id = v_invoice_id;\r\n\r\n  PERFORM set_config('app.stock_engine', 'off', true);\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$"}	fix_create_sale_date_overload_engine_flag
52	{"-- ═══════════════════════════════════\r\n-- E6 / M5 (rebuild-plan.md §1.2): أنواع الحبوب — البيانات المرجعية\r\n--\r\n-- المشكلة الموثقة: الحبوب تُختار من كتالوج المنتجات العادي\r\n-- (fetchGrainItems تبحث في products بـ item_class=RAW_MATERIAL) فتختلط\r\n-- الحبوب المرجعية بأصناف الشراء الحقيقية، ولا يوجد فاقد افتراضي ولا نسب\r\n-- نواتج — الفاقد يُدخل يدوياً في كل عملية بلا أساس.\r\n--\r\n-- الحل: جدول مرجعي مستقل لأنواع الحبوب يوفّر:\r\n--   • default_loss_rate_pct : نسبة فاقد افتراضية لكل نوع حبة.\r\n--   • default_output_map    : نواتج افتراضية (JSONB: [{grain_type_id, ratio}])\r\n--     قابلة للتعديل يدوياً لكل عملية (طبيعة كل طرقة حجر تختلف).\r\n--   • ربط اختياري بمنتج الكتالوج الذي يمثّل هذا النوع في الشراء\r\n--     (product_id) حتى تظل قائمة الشراء كما هي، بينما القوائم المرجعية\r\n--     تقرأ من grain_types مباشرة.\r\n--\r\n-- ملاحظة: الترحيل لا يغيّر أي عملية قائمة — الجدول مرجعي فقط في هذه\r\n-- المرحلة، والربط الكامل للعمليات يتم في الترحيلات التالية.\r\n-- ═══════════════════════════════════\r\n\r\nCREATE TABLE IF NOT EXISTS public.grain_types (\r\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  name_ar text NOT NULL UNIQUE,\r\n  name_en text,\r\n  -- نسبة الفاقد الافتراضية (%) لهذا النوع من الحبوب\r\n  default_loss_rate_pct numeric(5,2) NOT NULL DEFAULT 0\r\n    CHECK (default_loss_rate_pct >= 0 AND default_loss_rate_pct <= 100),\r\n  -- النواتج الافتراضية: [{product_id uuid, ratio numeric}] — النسب مجموعها <= 100\r\n  default_output_map jsonb NOT NULL DEFAULT '[]'::jsonb,\r\n  -- ربط اختياري بمنتج الكتالوج الذي يمثّل هذه الحبة في الشراء\r\n  representative_product_id uuid REFERENCES public.products(id) ON DELETE SET NULL,\r\n  -- ملاحظات تشغيلية (مثلاً: يُطحن ناعماً — طرقة حجر رقم 2)\r\n  notes text,\r\n  is_active boolean NOT NULL DEFAULT true,\r\n  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,\r\n  created_at timestamptz NOT NULL DEFAULT now(),\r\n  updated_at timestamptz NOT NULL DEFAULT now()\r\n)","-- منع تكرار الاسم الإنجليزي عند وجوده\r\nCREATE UNIQUE INDEX IF NOT EXISTS uq_grain_types_name_en\r\n  ON public.grain_types (name_en) WHERE name_en IS NOT NULL","-- فهرس القائمة النشطة (الاستعلام الأكثر تكراراً)\r\nCREATE INDEX IF NOT EXISTS idx_grain_types_active\r\n  ON public.grain_types (is_active, name_ar)","CREATE OR REPLACE FUNCTION public.grain_types_output_map_ratio_is_valid(p_output_map jsonb)\r\n RETURNS boolean\r\n LANGUAGE sql\r\n IMMUTABLE\r\n SET search_path TO 'pg_catalog'\r\nAS $function$\r\n  SELECT CASE\r\n    WHEN jsonb_typeof(p_output_map) <> 'array' THEN false\r\n    ELSE COALESCE((\r\n      SELECT SUM((entry->>'ratio')::numeric)\r\n      FROM jsonb_array_elements(p_output_map) AS entry\r\n    ), 0) <= 100\r\n  END;\r\n$function$","-- تحقق: مجموع نسب النواتج الافتراضية لا يتجاوز 100%\r\nALTER TABLE public.grain_types\r\n  ADD CONSTRAINT grain_types_output_map_ratio_check\r\n  CHECK (public.grain_types_output_map_ratio_is_valid(default_output_map))","-- ── RLS ─────────────────────────────────────────────────────────────\r\nALTER TABLE public.grain_types ENABLE ROW LEVEL SECURITY","-- القراءة: أي موظف مخوّل بعرض المحل\r\nCREATE POLICY \\"grain_types_read\\" ON public.grain_types\r\n  FOR SELECT TO authenticated\r\n  USING (public.can_view_milling())","-- الكتابة الكاملة للخدمة (ترحيلات ودوال)\r\nCREATE POLICY \\"grain_types_service_all\\" ON public.grain_types\r\n  FOR ALL TO service_role\r\n  USING (true)\r\n  WITH CHECK (true)","-- الكتابة للعمليات: من يدير المحل (owner/manager/warehouse)\r\nCREATE POLICY \\"grain_types_manage\\" ON public.grain_types\r\n  FOR ALL TO authenticated\r\n  USING (public.is_staff(auth.uid()))\r\n  WITH CHECK (public.is_staff(auth.uid()))","-- ── تحديث updated_at تلقائياً ───────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.touch_grain_type_updated_at()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\n SET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  NEW.updated_at := now();\r\n  RETURN NEW;\r\nEND;\r\n$function$","CREATE TRIGGER trg_grain_types_touch\r\n  BEFORE UPDATE ON public.grain_types\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION public.touch_grain_type_updated_at()","-- ── بيانات أولية: الأنواع الشائعة في المطاحن المحلية ────────────────\r\n-- الفاقد الافتراضي تقديري تشغيلي (يُعدَّل لكل عملية يدوياً)\r\nINSERT INTO public.grain_types (name_ar, name_en, default_loss_rate_pct, default_output_map, notes)\r\nVALUES\r\n  ('قمح بُرّ', 'Bread Wheat', 2.00,\r\n   '[{\\"label\\":\\"دقيق أبيض\\",\\"ratio\\":78},{\\"label\\":\\"نخالة\\",\\"ratio\\":20}]'::jsonb,\r\n   'النوع الأكثر تداولاً — نسبة استخراج دقيق عالية'),\r\n  ('قمح أسمر (دُرَة)', 'Durum Wheat', 2.50,\r\n   '[{\\"label\\":\\"سميد\\",\\"ratio\\":70},{\\"label\\":\\"دقيق أسمر\\",\\"ratio\\":8},{\\"label\\":\\"نخالة\\",\\"ratio\\":19}]'::jsonb,\r\n   'يُستخرج منه السميد بشكل أساسي'),\r\n  ('شعير', 'Barley', 3.00,\r\n   '[{\\"label\\":\\"دقيق شعير\\",\\"ratio\\":65},{\\"label\\":\\"نخالة شعير\\",\\"ratio\\":32}]'::jsonb,\r\n   'نسبة استخراج أقل — فاقد أعلى'),\r\n  ('ذرة', 'Maize / Corn', 3.50,\r\n   '[{\\"label\\":\\"دقيق ذرة\\",\\"ratio\\":70},{\\"label\\":\\"نخالة ذرة\\",\\"ratio\\":26}]'::jsonb,\r\n   'يُطحن جافاً — حساس للرطوبة')\r\nON CONFLICT (name_ar) DO NOTHING"}	grain_types
53	{"-- ═══════════════════\r\n-- E6 / M5 — ربط عملية الطحن بنوع الحبة المرجعي (grain_types)\r\n--\r\n-- يضيف توقيعاً جديداً (overload) لدالة custody_milling بمعامل\r\n-- _grain_type_id اختياري — التوقيع القديم (7 معاملات) يبقى صالحاً\r\n-- فلا ينكسر أي مستدعٍ قائم.\r\n--\r\n-- سلوك المعامل الجديد:\r\n--   • NULL  → سلوك مطابق تماماً للتوقيع القديم.\r\n--   • معطى  → يتحقق أن النوع نشط، ويوثّق النوع في سجل التدقيق\r\n--             (سلسلة تتبع: العملية ← نوع الحبة ← الفاقد الافتراضي).\r\n-- ═══════════════════════════════════\r\n\r\nCREATE OR REPLACE FUNCTION public.custody_milling(\r\n  _customer_id uuid,\r\n  _warehouse_id uuid,\r\n  _grain_item_id uuid,\r\n  _bags_out numeric,\r\n  _kg_out numeric,\r\n  _outputs jsonb,\r\n  _notes text,\r\n  _grain_type_id uuid DEFAULT NULL\r\n)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_doc text;\r\n  v_balance_bags numeric;\r\n  v_balance_kg numeric;\r\n  v_total_out_bags numeric := 0;\r\n  v_total_out_kg numeric := 0;\r\n  v_grain_type_name text := NULL;\r\n  v_grain_type_loss numeric := NULL;\r\n  r record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.can_operate_milling() THEN\r\n    RAISE EXCEPTION 'You are not permitted to record custody milling';\r\n  END IF;\r\n  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _grain_item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Customer, warehouse and grain item are required';\r\n  END IF;\r\n  IF coalesce(_bags_out, 0) <= 0 AND coalesce(_kg_out, 0) <= 0 THEN\r\n    RAISE EXCEPTION 'Milling must consume at least one bag or a positive weight of grain';\r\n  END IF;\r\n  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN\r\n    RAISE EXCEPTION 'At least one output line is required';\r\n  END IF;\r\n\r\n  -- نوع الحبة المرجعي: يجب أن يكون نشطاً إن مُرِّر.\r\n  IF _grain_type_id IS NOT NULL THEN\r\n    SELECT gt.name_ar, gt.default_loss_rate_pct\r\n      INTO v_grain_type_name, v_grain_type_loss\r\n      FROM public.grain_types gt\r\n     WHERE gt.id = _grain_type_id AND gt.is_active;\r\n    IF v_grain_type_name IS NULL THEN\r\n      RAISE EXCEPTION 'Grain type is not active or does not exist';\r\n    END IF;\r\n  END IF;\r\n\r\n  -- صنف الحبوب خام، وأصناف النواتج منتجات/نواتج جانبية — من القاعدة.\r\n  IF NOT EXISTS (\r\n    SELECT 1 FROM public.products\r\n    WHERE id = _grain_item_id AND item_class = 'RAW_MATERIAL' AND is_active\r\n  ) THEN\r\n    RAISE EXCEPTION 'Milling input must be an active RAW_MATERIAL grain';\r\n  END IF;\r\n\r\n  SELECT * FROM public.custody_balance(_customer_id, _warehouse_id, _grain_item_id)\r\n    INTO v_balance_bags, v_balance_kg;\r\n\r\n  IF coalesce(_bags_out, 0) > v_balance_bags THEN\r\n    RAISE EXCEPTION 'Grain bags balance (%) is less than the requested milling amount (%)',\r\n      v_balance_bags, coalesce(_bags_out, 0);\r\n  END IF;\r\n  IF coalesce(_kg_out, 0) > v_balance_kg THEN\r\n    RAISE EXCEPTION 'Grain kg balance (%) is less than the requested milling amount (%)',\r\n      v_balance_kg, coalesce(_kg_out, 0);\r\n  END IF;\r\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs)\r\n             AS o(item_id uuid, bags numeric, kg numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL THEN\r\n      RAISE EXCEPTION 'Every output line needs an item';\r\n    END IF;\r\n    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN\r\n      RAISE EXCEPTION 'Every output line needs bags or a positive weight';\r\n    END IF;\r\n    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN\r\n      RAISE EXCEPTION 'Output quantities cannot be negative';\r\n    END IF;\r\n    IF NOT EXISTS (\r\n      SELECT 1 FROM public.products\r\n      WHERE id = r.item_id AND item_class IN ('FINISHED_GOOD', 'BY_PRODUCT') AND is_active\r\n    ) THEN\r\n      RAISE EXCEPTION 'Milling outputs must be FINISHED_GOOD or BY_PRODUCT items';\r\n    END IF;\r\n    v_total_out_bags := v_total_out_bags + coalesce(r.bags, 0);\r\n    v_total_out_kg   := v_total_out_kg + coalesce(r.kg, 0);\r\n  END LOOP;\r\n\r\n  v_doc := 'CM-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\r\n\r\n  -- صادر الحبوب — يوثّق نوع الحبة المرجعي في الملاحظات إن مُرِّر\r\n  INSERT INTO public.custody_ledger\r\n    (customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n     bags_out, kg_out, notes, created_by)\r\n  VALUES\r\n    (_customer_id, _warehouse_id, 'MILLING', _grain_item_id, v_doc,\r\n     coalesce(_bags_out, 0), coalesce(_kg_out, 0),\r\n     CASE WHEN v_grain_type_name IS NOT NULL\r\n          THEN coalesce(_notes, '') || CASE WHEN coalesce(_notes, '') = '' THEN '' ELSE ' — ' END\r\n               || '[نوع الحبة: ' || v_grain_type_name || ']'\r\n          ELSE _notes END,\r\n     v_user);\r\n\r\n  -- وارد النواتج: سطر لكل ناتج\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs)\r\n             AS o(item_id uuid, bags numeric, kg numeric)\r\n  LOOP\r\n    INSERT INTO public.custody_ledger\r\n      (customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n       bags_in, kg_in, notes, created_by)\r\n    VALUES\r\n      (_customer_id, _warehouse_id, 'MILLING', r.item_id, v_doc,\r\n       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'custody.milling', 'custody_ledger', _customer_id,\r\n    jsonb_build_object(\r\n      'doc_number', v_doc,\r\n      'grain_item_id', _grain_item_id,\r\n      'grain_type_id', _grain_type_id,\r\n      'grain_type_name', v_grain_type_name,\r\n      'grain_type_default_loss_pct', v_grain_type_loss,\r\n      'grain_bags', coalesce(_bags_out, 0),\r\n      'grain_kg', coalesce(_kg_out, 0),\r\n      'outputs', _outputs,\r\n      'stock_impact', 'NONE — customer custody'\r\n    ));\r\n\r\n  RETURN v_doc;\r\nEND $function$","-- صلاحيات التوقيع الجديد\r\nGRANT EXECUTE ON FUNCTION public.custody_milling(uuid, uuid, uuid, numeric, numeric, jsonb, text, uuid) TO authenticated","GRANT EXECUTE ON FUNCTION public.custody_milling(uuid, uuid, uuid, numeric, numeric, jsonb, text, uuid) TO service_role"}	grain_types_link
54	{"-- ═══════════════════\r\n-- Indizes für custody_ledger (Audit-Bericht Punkt 3)\r\n--\r\n-- Die bestehenden Indizes decken zwei Abfrageformulare ab:\r\n--   (customer_id, item_id)           → Bilanz ohne Lagerort\r\n--   (warehouse_id, created_at DESC)  → Bewegungen nach Lagerort\r\n--\r\n-- Was fehlte:\r\n--   1. (customer_id, warehouse_id, item_id)\r\n--      → Alle Offen-Bildschirme filtern nach Kunde + Lagerort\r\n--        (balances, Kundenkonto, Schnellformulare) — ohne Index\r\n--        war ein vollständiger Tabellenscan die Folge.\r\n--   2. (created_at)\r\n--      → Leistungsbericht: created_at >= cutoff + entry_type =\r\n--        'MILLING' + Kunde — keiner der vorhandenen Indizes\r\n--        konnte diese Abfrage alleine tragen.\r\n--   3. doc_number (btree, absteigend)\r\n--      → Suche nach Belegnummer im Dokumentenregister; varchar(50)\r\n--        ohne Unique-Beschränkung könnte Duplikate zulassen\r\n--        (wird hier bewusst NICHT erzwungen, da alte Belege\r\n--        manuell Duplikate enthalten könnten — Suche zuerst).\r\n-- ═══════════════════════════════════\r\n\r\nCREATE INDEX IF NOT EXISTS idx_custody_customer_wh_item\r\n  ON public.custody_ledger USING btree (customer_id, warehouse_id, item_id)","CREATE INDEX IF NOT EXISTS idx_custody_created_entry\r\n  ON public.custody_ledger USING btree (created_at DESC, entry_type)","CREATE INDEX IF NOT EXISTS idx_custody_doc_number\r\n  ON public.custody_ledger USING btree (doc_number)"}	custody_indexes
55	{"-- ═══════════════════════════════════\r\n-- البند 8 من تقرير التدقيق — سلسلة التتبع (Traceability)\r\n--\r\n-- المشكلة الموثقة (rebuild-plan §1.3 الخطوة 6): حركات الأمانة ليست كلها\r\n-- موثقة المصدر، فلا يمكن الإجابة على سؤال \\"هذا الكيس جاء من أي استلام؟\\".\r\n-- كان الربط الوحيد حقل `milling_document_id` الاختياري.\r\n--\r\n-- الحل: عمودان عامان على نمط المحرك `post_stock_delta`:\r\n--   source_type : نوع المصدر (milling_document / custody_adjustment /\r\n--                 stock_conversion / manual)\r\n--   source_id   : معرف المصدر (uuid)\r\n-- مع فهارس تشغيلية للبحث العكسي، وتحديث تلقائي للحركات القديمة من\r\n-- رابط milling_document_id حتى لا تفقدها سلسلة التتبع.\r\n-- ═══════════════════\r\n\r\nALTER TABLE public.custody_ledger\r\n  ADD COLUMN IF NOT EXISTS source_type text,\r\n  ADD COLUMN IF NOT EXISTS source_id uuid","-- فهرس البحث العكسي: من المصدر إلى حركاته\r\nCREATE INDEX IF NOT EXISTS idx_custody_source\r\n  ON public.custody_ledger (source_type, source_id)\r\n  WHERE source_id IS NOT NULL","-- ترحيل البيانات القديمة: الحركات المرتبطة بوثيقة milling_service_documents\r\n-- تصبح موثقة المصدر تلقائياً (milling_document)\r\nUPDATE public.custody_ledger cl\r\nSET source_type = 'milling_document',\r\n    source_id   = cl.milling_document_id\r\nWHERE cl.milling_document_id IS NOT NULL\r\n  AND cl.source_id IS NULL","-- تعليق على الدوال: الأعمدة الجديدة تُكتب عبر RPCs القائمة في الترحيلات\r\n-- القادمة (تسجيل الطحن/التسليم/التسوية تمرر مصدرها) — لا تغيير في\r\n-- التواقيع القائمة حتى لا تنكسر الاستدعاءات."}	custody_traceability
56	{"-- A credit tender records no collection at invoice creation.\r\n-- Partial payment is represented by the actual collected tender plus a receivable,\r\n-- not by payment_method='credit' with a positive paid amount. Later customer\r\n-- collections update paid on the existing invoice and remain allowed.\r\n\r\nBEGIN","CREATE OR REPLACE FUNCTION public.reject_paid_credit_sale_creation()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  IF NEW.payment_method = 'credit'::public.payment_method\r\n     AND coalesce(NEW.paid, 0) > 0 THEN\r\n    RAISE EXCEPTION 'Credit payment method requires zero paid amount; record the actual tender method for partial payment'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$","REVOKE ALL ON FUNCTION public.reject_paid_credit_sale_creation() FROM PUBLIC, anon, authenticated, service_role","COMMENT ON FUNCTION public.reject_paid_credit_sale_creation() IS\r\n  'R-56: A credit sale cannot carry an initial payment without a recorded settlement method.'","DROP TRIGGER IF EXISTS sales_invoices_reject_paid_credit_insert ON public.sales_invoices","CREATE TRIGGER sales_invoices_reject_paid_credit_insert\r\n  BEFORE INSERT ON public.sales_invoices\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION public.reject_paid_credit_sale_creation()","DO $$\r\nBEGIN\r\n  IF EXISTS (\r\n    SELECT 1 FROM public.sales_invoices\r\n    WHERE payment_method = 'credit'::public.payment_method\r\n      AND coalesce(paid, 0) > 0\r\n  ) THEN\r\n    RAISE EXCEPTION 'Existing credit invoices with paid amounts need a recorded settlement method before this migration';\r\n  END IF;\r\nEND $$",COMMIT,"-- Verification: the INSERT trigger rejects credit + paid > 0. It intentionally\r\n-- does not guard UPDATE, because later customer collections update paid.\r\n-- Rollback: DROP TRIGGER IF EXISTS sales_invoices_reject_paid_credit_insert ON public.sales_invoices"}	reject_paid_credit_sale_creation
57	{"-- Restore the authenticated table privileges removed by migration 36's\r\n-- allowlist. Row visibility and writes remain constrained by the existing RLS\r\n-- policies from migration 25.\r\nGRANT SELECT, INSERT, UPDATE ON public.fixed_assets TO authenticated","GRANT SELECT ON public.asset_depreciation_lines TO authenticated","GRANT SELECT, INSERT, UPDATE ON public.fixed_assets TO service_role","GRANT SELECT ON public.asset_depreciation_lines TO service_role"}	restore_fixed_asset_table_grants
58	{"-- Private storage for encrypted browser-generated backups. Each authenticated\r\n-- user can access only objects stored beneath their own user-id folder.\r\nINSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\r\nVALUES (\r\n  'tenant-backups',\r\n  'tenant-backups',\r\n  false,\r\n  104857600,\r\n  ARRAY['application/json']::text[]\r\n)\r\nON CONFLICT (id) DO UPDATE\r\nSET public = false,\r\n    file_size_limit = EXCLUDED.file_size_limit,\r\n    allowed_mime_types = EXCLUDED.allowed_mime_types","DROP POLICY IF EXISTS tenant_backups_select_own ON storage.objects","CREATE POLICY tenant_backups_select_own\r\nON storage.objects FOR SELECT TO authenticated\r\nUSING (\r\n  bucket_id = 'tenant-backups'\r\n  AND (storage.foldername(name))[1] = auth.uid()::text\r\n)","DROP POLICY IF EXISTS tenant_backups_insert_own ON storage.objects","CREATE POLICY tenant_backups_insert_own\r\nON storage.objects FOR INSERT TO authenticated\r\nWITH CHECK (\r\n  bucket_id = 'tenant-backups'\r\n  AND (storage.foldername(name))[1] = auth.uid()::text\r\n)","DROP POLICY IF EXISTS tenant_backups_delete_own ON storage.objects","CREATE POLICY tenant_backups_delete_own\r\nON storage.objects FOR DELETE TO authenticated\r\nUSING (\r\n  bucket_id = 'tenant-backups'\r\n  AND (storage.foldername(name))[1] = auth.uid()::text\r\n)"}	private_tenant_backup_storage
59	{"-- Return the mapped chart-of-accounts entry with every expense category so\r\n-- operators can see where an ordinary expense will be posted.\r\nCREATE OR REPLACE FUNCTION public.expense_lookups(p_include_archived boolean DEFAULT false)\r\nRETURNS jsonb\r\nLANGUAGE sql\r\nSTABLE\r\nSET search_path TO 'public'\r\nAS $function$\r\n  SELECT jsonb_build_object(\r\n    'categories', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', c.id,\r\n               'name', c.name,\r\n               'name_ar', c.name_ar,\r\n               'is_active', c.is_active,\r\n               'sort_order', c.sort_order,\r\n               'usage_count', (SELECT count(*) FROM public.expense_lines l WHERE l.category_id = c.id),\r\n               'account_id', c.account_id,\r\n               'account_code', a.code,\r\n               'account_name_ar', a.name_ar\r\n             ) ORDER BY c.sort_order, c.name)\r\n      FROM public.expense_categories c\r\n      LEFT JOIN public.accounts a ON a.id = c.account_id\r\n      WHERE p_include_archived OR c.is_active\r\n    ), '[]'::jsonb),\r\n    'warehouses', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', w.id, 'name', w.name, 'name_ar', w.name_ar, 'is_default', w.is_default\r\n             ) ORDER BY w.name)\r\n      FROM public.warehouses w\r\n      WHERE w.is_active IS NOT FALSE\r\n    ), '[]'::jsonb),\r\n    'cost_centers', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', cc.id, 'code', cc.code, 'name', cc.name, 'name_ar', cc.name_ar\r\n             ) ORDER BY cc.name)\r\n      FROM public.expense_cost_centers cc\r\n      WHERE cc.is_active\r\n    ), '[]'::jsonb),\r\n    'projects', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', pj.id, 'code', pj.code, 'name', pj.name, 'name_ar', pj.name_ar\r\n             ) ORDER BY pj.name)\r\n      FROM public.expense_projects pj\r\n      WHERE pj.is_active\r\n    ), '[]'::jsonb),\r\n    'suppliers', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name) ORDER BY s.name)\r\n      FROM public.suppliers s\r\n      WHERE s.is_active IS NOT FALSE\r\n    ), '[]'::jsonb),\r\n    'employees', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) ORDER BY p.full_name)\r\n      FROM public.profiles p\r\n      WHERE p.is_active IS NOT FALSE\r\n        AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = p.id)\r\n        AND NOT EXISTS (SELECT 1 FROM public.platform_admins pa WHERE pa.user_id = p.id)\r\n        AND p.full_name NOT ILIKE '%سوبر%'\r\n        AND p.full_name NOT ILIKE '%superadmin%'\r\n    ), '[]'::jsonb),\r\n    'financial_accounts', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n               'id', a.id, 'code', a.code, 'name_ar', a.name_ar,\r\n               'account_type', a.account_type,\r\n               'requires_reconciliation', a.requires_reconciliation\r\n             ) ORDER BY a.code)\r\n      FROM public.accounts a\r\n      WHERE a.is_active IS NOT FALSE\r\n        AND (a.requires_reconciliation IS TRUE OR a.code LIKE '11%')\r\n    ), '[]'::jsonb)\r\n  )\r\n$function$","GRANT EXECUTE ON FUNCTION public.expense_lookups(boolean) TO authenticated, service_role"}	expense_category_account_lookup
60	{"-- ════════════════════════════\n-- 60_milling_custody_multiline.sql\n--\n-- طحن أمانات الغير — أسطر متعددة (طلب مالك المطحنة):\n--   1. الاستلام: قد يستلم العميل أكثر من نوع حبوب في عملية واحدة\n--      (مثال: «حبوب بر الخريف كيس 50 كجم» ×10 + «حبوب بر الخريف كيس 25 كجم» ×10).\n--   2. الطحن: قد يطحن أكثر من نوع حبوب في عملية واحدة ويُنتج أكثر من ناتج.\n--\n-- ◆ فصل منتجات الأمانات عن منتجات النظام التجاري:\n--   عمود is_custody_item على products — المنتجات المعلّمة به=true تظهر فقط\n--   في قوائم أمانات المطحنة (استلام/طحن/تسليم)، والمنتجات التجارية العادية\n--   لا تظهر فيها أبداً، والعكس صحيح. تعليم المنتجات يتم من واجهة المنتجات.\n-- ════════════════════════════\n\nALTER TABLE public.products ADD COLUMN IF NOT EXISTS is_custody_item boolean NOT NULL DEFAULT false","COMMENT ON COLUMN public.products.is_custody_item IS 'منتج أمانات مطحنة (حبوب/نواتج) — يظهر في قوائم الطحن فقط وليس في المبيعات والمشتريات'","CREATE INDEX IF NOT EXISTS idx_products_custody ON public.products (item_class, is_custody_item) WHERE is_custody_item","-- ── 1. الاستلام متعدد الأصناف (بدون فاتورة) ────────────────────────────────\nCREATE OR REPLACE FUNCTION public.custody_intake_multi(\n  _customer_id uuid,\n  _warehouse_id uuid,\n  _lines jsonb,   -- [{item_id, bags, kg}]\n  _notes text\n)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_user uuid := auth.uid();\n  v_doc text;\n  r record;\nBEGIN\n  IF v_user IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n  IF NOT public.can_operate_milling() THEN\n    RAISE EXCEPTION 'You are not permitted to record custody intakes';\n  END IF;\n  IF _customer_id IS NULL OR _warehouse_id IS NULL THEN\n    RAISE EXCEPTION 'Customer and warehouse are required';\n  END IF;\n  IF _lines IS NULL OR jsonb_typeof(_lines) <> 'array' OR jsonb_array_length(_lines) = 0 THEN\n    RAISE EXCEPTION 'At least one intake line is required';\n  END IF;\n\n  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, bags numeric, kg numeric)\n  LOOP\n    IF r.item_id IS NULL THEN\n      RAISE EXCEPTION 'Every intake line needs an item';\n    END IF;\n    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN\n      RAISE EXCEPTION 'Every intake line needs bags or a positive weight';\n    END IF;\n    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN\n      RAISE EXCEPTION 'Quantities cannot be negative';\n    END IF;\n    -- صنف الاستلام حبوب خام فقط — منتجات الأمانات (is_custody_item).\n    IF NOT EXISTS (\n      SELECT 1 FROM public.products\n      WHERE id = r.item_id AND item_class = 'RAW_MATERIAL' AND is_active AND is_custody_item\n    ) THEN\n      RAISE EXCEPTION 'Intake items must be active custody grain products (is_custody_item)';\n    END IF;\n  END LOOP;\n\n  v_doc := 'CI-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_intake_seq')::text, 4, '0');\n\n  FOR r IN SELECT * FROM jsonb_to_recordset(_lines) AS l(item_id uuid, bags numeric, kg numeric)\n  LOOP\n    INSERT INTO public.custody_ledger\n      (customer_id, warehouse_id, entry_type, item_id, doc_number,\n       bags_in, kg_in, notes, created_by)\n    VALUES\n      (_customer_id, _warehouse_id, 'INTAKE', r.item_id, v_doc,\n       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);\n  END LOOP;\n\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\n  VALUES (v_user, 'custody.intake', 'custody_ledger', _customer_id,\n    jsonb_build_object(\n      'doc_number', v_doc,\n      'customer_id', _customer_id,\n      'lines', _lines,\n      'stock_impact', 'NONE — customer custody'\n    ));\n\n  RETURN v_doc;\nEND $function$","-- ── 2. الطحن متعدد الأصناف: أسطر حبوب صادرة + أسطر نواتج واردة ────────────\nCREATE OR REPLACE FUNCTION public.custody_milling_multi(\n  _customer_id uuid,\n  _warehouse_id uuid,\n  _grains jsonb,   -- [{item_id, bags, kg}]\n  _outputs jsonb,  -- [{item_id, bags, kg}]\n  _notes text\n)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_user uuid := auth.uid();\n  v_doc text;\n  v_balance_bags numeric;\n  v_balance_kg numeric;\n  v_total_out_bags numeric := 0;\n  v_total_out_kg numeric := 0;\n  r record;\nBEGIN\n  IF v_user IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n  IF NOT public.can_operate_milling() THEN\n    RAISE EXCEPTION 'You are not permitted to record custody milling';\n  END IF;\n  IF _customer_id IS NULL OR _warehouse_id IS NULL THEN\n    RAISE EXCEPTION 'Customer and warehouse are required';\n  END IF;\n  IF _grains IS NULL OR jsonb_typeof(_grains) <> 'array' OR jsonb_array_length(_grains) = 0 THEN\n    RAISE EXCEPTION 'At least one grain line is required';\n  END IF;\n  IF _outputs IS NULL OR jsonb_typeof(_outputs) <> 'array' OR jsonb_array_length(_outputs) = 0 THEN\n    RAISE EXCEPTION 'At least one output line is required';\n  END IF;\n\n  -- تحقق أسطر الحبوب: صنف خام + رصيد كافٍ\n  FOR r IN SELECT * FROM jsonb_to_recordset(_grains) AS g(item_id uuid, bags numeric, kg numeric)\n  LOOP\n    IF r.item_id IS NULL THEN\n      RAISE EXCEPTION 'Every grain line needs an item';\n    END IF;\n    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN\n      RAISE EXCEPTION 'Every grain line needs bags or a positive weight';\n    END IF;\n    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN\n      RAISE EXCEPTION 'Quantities cannot be negative';\n    END IF;\n    IF NOT EXISTS (\n      SELECT 1 FROM public.products\n      WHERE id = r.item_id AND item_class = 'RAW_MATERIAL' AND is_active AND is_custody_item\n    ) THEN\n      RAISE EXCEPTION 'Milling input must be active custody grain products (is_custody_item)';\n    END IF;\n\n    SELECT * FROM public.custody_balance(_customer_id, _warehouse_id, r.item_id)\n      INTO v_balance_bags, v_balance_kg;\n    IF coalesce(r.bags, 0) > v_balance_bags THEN\n      RAISE EXCEPTION 'Grain bags balance (%) is less than the requested milling amount (%)',\n        v_balance_bags, coalesce(r.bags, 0);\n    END IF;\n    IF coalesce(r.kg, 0) > v_balance_kg THEN\n      RAISE EXCEPTION 'Grain kg balance (%) is less than the requested milling amount (%)',\n        v_balance_kg, coalesce(r.kg, 0);\n    END IF;\n  END LOOP;\n\n  -- تحقق أسطر النواتج\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, bags numeric, kg numeric)\n  LOOP\n    IF r.item_id IS NULL THEN\n      RAISE EXCEPTION 'Every output line needs an item';\n    END IF;\n    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN\n      RAISE EXCEPTION 'Every output line needs bags or a positive weight';\n    END IF;\n    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN\n      RAISE EXCEPTION 'Output quantities cannot be negative';\n    END IF;\n    IF NOT EXISTS (\n      SELECT 1 FROM public.products\n      WHERE id = r.item_id AND item_class IN ('FINISHED_GOOD', 'BY_PRODUCT')\n        AND is_active AND is_custody_item\n    ) THEN\n      RAISE EXCEPTION 'Milling outputs must be active custody output products (is_custody_item)';\n    END IF;\n    v_total_out_bags := v_total_out_bags + coalesce(r.bags, 0);\n    v_total_out_kg   := v_total_out_kg + coalesce(r.kg, 0);\n  END LOOP;\n\n  v_doc := 'CM-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.milling_service_seq')::text, 4, '0');\n\n  -- صادر الحبوب: سطر لكل صنف\n  FOR r IN SELECT * FROM jsonb_to_recordset(_grains) AS g(item_id uuid, bags numeric, kg numeric)\n  LOOP\n    INSERT INTO public.custody_ledger\n      (customer_id, warehouse_id, entry_type, item_id, doc_number,\n       bags_out, kg_out, notes, created_by)\n    VALUES\n      (_customer_id, _warehouse_id, 'MILLING', r.item_id, v_doc,\n       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);\n  END LOOP;\n\n  -- وارد النواتج: سطر لكل ناتج\n  FOR r IN SELECT * FROM jsonb_to_recordset(_outputs) AS o(item_id uuid, bags numeric, kg numeric)\n  LOOP\n    INSERT INTO public.custody_ledger\n      (customer_id, warehouse_id, entry_type, item_id, doc_number,\n       bags_in, kg_in, notes, created_by)\n    VALUES\n      (_customer_id, _warehouse_id, 'MILLING', r.item_id, v_doc,\n       coalesce(r.bags, 0), coalesce(r.kg, 0), _notes, v_user);\n  END LOOP;\n\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\n  VALUES (v_user, 'custody.milling', 'custody_ledger', _customer_id,\n    jsonb_build_object(\n      'doc_number', v_doc,\n      'grains', _grains,\n      'outputs', _outputs,\n      'output_bags', v_total_out_bags,\n      'output_kg', v_total_out_kg,\n      'stock_impact', 'NONE — customer custody'\n    ));\n\n  RETURN v_doc;\nEND $function$","-- ─ 3. منتجات الأمانات — قراءة قوائم مخصصة معزولة عن منتجات النظام ─\n-- حبوب الأمانات: خام + معلّم كمنتج أمانات.\nCREATE OR REPLACE FUNCTION public.custody_grain_items()\n RETURNS TABLE(id uuid, sku text, name text, name_ar text, item_class public.item_class,\n               sale_price numeric, cost_price numeric, package_weight_kg numeric)\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  SELECT p.id, p.sku, p.name, p.name_ar, p.item_class, p.sale_price, p.cost_price, p.package_weight_kg\n  FROM public.products p\n  WHERE p.item_class = 'RAW_MATERIAL' AND p.is_active AND p.is_custody_item\n  ORDER BY p.name_ar NULLS LAST, p.name;\n$function$","-- نواتج الأمانات: منتجات تامة + نواتج جانبية + معلّمة كمنتجات أمانات.\nCREATE OR REPLACE FUNCTION public.custody_output_items()\n RETURNS TABLE(id uuid, sku text, name text, name_ar text, item_class public.item_class,\n               sale_price numeric, cost_price numeric, package_weight_kg numeric)\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  SELECT p.id, p.sku, p.name, p.name_ar, p.item_class, p.sale_price, p.cost_price, p.package_weight_kg\n  FROM public.products p\n  WHERE p.item_class IN ('FINISHED_GOOD', 'BY_PRODUCT') AND p.is_active AND p.is_custody_item\n  ORDER BY p.name_ar NULLS LAST, p.name;\n$function$","GRANT EXECUTE ON FUNCTION public.custody_grain_items() TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.custody_output_items() TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.custody_intake_multi(uuid, uuid, jsonb, text) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.custody_milling_multi(uuid, uuid, jsonb, jsonb, text) TO authenticated, service_role","-- ── 4. مستند خدمة استلام متعدد الأصناف: فاتورة أجور واحدة + N سطر استلام ──\nCREATE OR REPLACE FUNCTION public.create_milling_service_document_multi(\n  _customer_id uuid,\n  _warehouse_id uuid,\n  _grains jsonb,        -- [{item_id, bags, kg}]\n  _service_item_id uuid,\n  _service_unit_price numeric,  -- الإجمالي المفوتر للعملية كلها (من الواجهة)\n  _discount numeric,\n  _payment_method text,\n  _paid numeric,\n  _notes text\n)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_user uuid := auth.uid();\n  v_document_id uuid;\n  v_document_number text;\n  v_invoice_id uuid;\n  v_invoice_number text;\n  v_subtotal numeric;\n  v_total numeric;\n  v_paid numeric;\n  v_outstanding numeric;\n  v_customer_balance numeric;\n  v_credit_limit numeric;\n  r record;\nBEGIN\n  IF v_user IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n  IF NOT (\n    public.has_role(v_user, 'owner')\n    OR public.has_role(v_user, 'manager')\n    OR public.has_role(v_user, 'cashier')\n  ) THEN\n    RAISE EXCEPTION 'You are not permitted to create milling service documents';\n  END IF;\n  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _service_item_id IS NULL THEN\n    RAISE EXCEPTION 'Customer, warehouse and service are required';\n  END IF;\n  IF _grains IS NULL OR jsonb_typeof(_grains) <> 'array' OR jsonb_array_length(_grains) = 0 THEN\n    RAISE EXCEPTION 'At least one grain line is required';\n  END IF;\n  IF coalesce(_service_unit_price, 0) < 0 OR coalesce(_discount, 0) < 0\n     OR coalesce(_paid, 0) < 0 THEN\n    RAISE EXCEPTION 'Service price, discount and paid amount cannot be negative';\n  END IF;\n  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN\n    RAISE EXCEPTION 'Unsupported payment method';\n  END IF;\n\n  -- تحقق أسطر الحبوب: خام + منتج أمانات + كمية موجبة\n  FOR r IN SELECT * FROM jsonb_to_recordset(_grains) AS g(item_id uuid, bags numeric, kg numeric)\n  LOOP\n    IF r.item_id IS NULL THEN\n      RAISE EXCEPTION 'Every grain line needs an item';\n    END IF;\n    IF coalesce(r.bags, 0) <= 0 AND coalesce(r.kg, 0) <= 0 THEN\n      RAISE EXCEPTION 'Every grain line needs bags or a positive weight';\n    END IF;\n    IF NOT EXISTS (\n      SELECT 1 FROM public.products\n      WHERE id = r.item_id AND item_class = 'RAW_MATERIAL' AND is_active AND is_custody_item\n    ) THEN\n      RAISE EXCEPTION 'Intake items must be active custody grain products (is_custody_item)';\n    END IF;\n  END LOOP;\n\n  IF NOT EXISTS (\n    SELECT 1 FROM public.products\n    WHERE id = _service_item_id AND item_class = 'SERVICE' AND is_active AND is_sellable\n  ) THEN\n    RAISE EXCEPTION 'Milling fee item must be an active sellable SERVICE';\n  END IF;\n\n  SELECT balance, credit_limit\n    INTO v_customer_balance, v_credit_limit\n  FROM public.customers\n  WHERE id = _customer_id AND is_active = true\n  FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Selected customer is unavailable';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = _warehouse_id AND is_active) THEN\n    RAISE EXCEPTION 'Selected warehouse is unavailable';\n  END IF;\n\n  v_subtotal := round(coalesce(_service_unit_price, 0), 2);\n  v_total := round(v_subtotal - coalesce(_discount, 0), 2);\n  IF v_total < 0 THEN\n    RAISE EXCEPTION 'Discount cannot exceed the service fee';\n  END IF;\n  v_paid := least(round(coalesce(_paid, 0), 2), v_total);\n  v_outstanding := round(v_total - v_paid, 2);\n  IF _payment_method = 'credit' AND v_paid <> 0 THEN\n    RAISE EXCEPTION 'Credit payment method requires zero paid amount';\n  END IF;\n  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN\n    RAISE EXCEPTION\n      'Credit limit exceeded: current balance %, requested debt %, limit %',\n      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);\n  END IF;\n\n  v_invoice_number := public.next_invoice_number();\n  INSERT INTO public.sales_invoices (\n    invoice_number, customer_id, warehouse_id, status, payment_status,\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\n  ) VALUES (\n    v_invoice_number, _customer_id, _warehouse_id, 'confirmed',\n    public.derive_payment_status(v_paid, v_total),\n    v_subtotal, round(coalesce(_discount, 0), 2), 0, v_total, v_paid,\n    _payment_method::public.payment_method, nullif(btrim(_notes), ''), v_user\n  ) RETURNING id INTO v_invoice_id;\n\n  INSERT INTO public.sales_invoice_items (\n    invoice_id, product_id, description, quantity, unit_price, discount, tax, total,\n    line_type, stock_effect\n  ) VALUES (\n    v_invoice_id, _service_item_id, 'أجور طحن وتجهيز', 1, v_subtotal,\n    0, 0, v_subtotal, 'SERVICE', 'NONE'\n  );\n\n  IF v_outstanding > 0 THEN\n    UPDATE public.customers\n    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()\n    WHERE id = _customer_id;\n\n    INSERT INTO public.customer_ledger (\n      customer_id, entry_type, debit, reference_id, reference_type,\n      occurred_at, created_by, source_key, note\n    ) VALUES (\n      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',\n      now(), v_user, 'sale:' || v_invoice_id, 'قيد أجور طحن آجل'\n    ) ON CONFLICT (source_key) DO NOTHING;\n  END IF;\n\n  PERFORM public.post_sales_invoice(v_invoice_id);\n\n  v_document_number := 'MT-' || to_char(now(), 'YYYYMM') || '-' ||\n    lpad(nextval('public.milling_document_seq')::text, 4, '0');\n  INSERT INTO public.milling_service_documents (\n    document_number, customer_id, warehouse_id, sales_invoice_id, created_by\n  ) VALUES (\n    v_document_number, _customer_id, _warehouse_id, v_invoice_id, v_user\n  ) RETURNING id INTO v_document_id;\n\n  FOR r IN SELECT * FROM jsonb_to_recordset(_grains) AS g(item_id uuid, bags numeric, kg numeric)\n  LOOP\n    INSERT INTO public.custody_ledger (\n      customer_id, warehouse_id, entry_type, item_id, doc_number,\n      bags_in, kg_in, milling_document_id, notes, created_by\n    ) VALUES (\n      _customer_id, _warehouse_id, 'INTAKE', r.item_id, v_document_number,\n      coalesce(r.bags, 0), coalesce(r.kg, 0), v_document_id, _notes, v_user\n    );\n  END LOOP;\n\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\n  VALUES (v_user, 'milling.service_document.created', 'milling_service_documents', v_document_id,\n    jsonb_build_object(\n      'document_number', v_document_number,\n      'invoice_id', v_invoice_id,\n      'grains', _grains,\n      'service_total', v_total,\n      'paid', v_paid,\n      'outstanding', v_outstanding,\n      'stock_impact', 'NONE — customer custody'\n    ));\n\n  RETURN jsonb_build_object(\n    'document_id', v_document_id,\n    'document_number', v_document_number,\n    'invoice_id', v_invoice_id,\n    'invoice_number', v_invoice_number\n  );\nEND $function$","GRANT EXECUTE ON FUNCTION public.create_milling_service_document_multi(uuid, uuid, jsonb, uuid, numeric, numeric, text, numeric, text) TO authenticated, service_role"}	milling_custody_multiline
61	{"-- إعادة منح صلاحيات `authenticated` على جداول الخزينة وطرق الدفع التي\n-- أسقطها مايكريشن 36 (`REVOKE ALL ON ALL TABLES`) ولم تشملها قائمة إعادة\n-- المنح فيه (نمط مايكريشن 57 الذي أعاد جداول الأصول الثابتة فقط).\n--\n-- الأثر الظاهر قبل هذا الإصلاح: شاشات طرق الدفع/الخزائن/الحسابات البنكية\n-- تفشل بـ 403 «permission denied» لأن السياسات (RLS) من migration 32\n-- تمنح authenticated صلاحيات كاملة، لكن GRANT طبقة النفاذ كان مفقوداً.\n--\n-- idempotent: آمن لإعادة التشغيل.\n\nGRANT USAGE ON SCHEMA public TO authenticated","GRANT SELECT, INSERT, UPDATE, DELETE ON public.cashboxes TO authenticated","GRANT SELECT, INSERT, UPDATE, DELETE ON public.company_bank_accounts TO authenticated","GRANT SELECT, INSERT, UPDATE, DELETE ON public.payment_methods TO authenticated","GRANT SELECT, INSERT, UPDATE, DELETE ON public.payment_method_settings TO authenticated","-- خدمة الخادم (Edge Functions / service_role) تحتاج النفاذ الكامل أيضاً.\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.cashboxes TO service_role","GRANT SELECT, INSERT, UPDATE, DELETE ON public.company_bank_accounts TO service_role","GRANT SELECT, INSERT, UPDATE, DELETE ON public.payment_methods TO service_role","GRANT SELECT, INSERT, UPDATE, DELETE ON public.payment_method_settings TO service_role"}	restore_treasury_payment_table_grants
62	{"-- ════════════════════════════════════════════════════════════════════════════\n-- 62_products_form_item_class_and_bag_unit.sql\n--\n-- 1) وحدة قياس جديدة «كيس / Bag» — بجانب الكيلوجرام وليس بدلًا منه:\n--    قياس عدّ (short_name: bag).\n--\n-- 2) الضمير المفقود في فورم المنتج: حقل item_class (دور الصنف) لم يكن يُرسَل\n--    مع payload رغم أن الجدول يحمله والشاشة تعرضه في البطاقات والجداول.\n--    الواجهة ترسله الآن (انظر _app.products.tsx).\n-- ════════════════════════════════════════════════════════════════════════════\n\n-- ── 1. وحدة «كيس» ────────────────────────────────────────────────────────────\n-- على مستوى النظام (tenant_id IS NULL) مثل باقي الوحدات الفيزيائية.\nINSERT INTO public.units (name, short_name, name_ar)\nSELECT 'Bag', 'bag', 'كيس'\nWHERE NOT EXISTS (\n  SELECT 1 FROM public.units WHERE name = 'Bag'\n)"}	products_form_item_class_and_bag_unit
63	{"-- بنية أرشيف حسابات الدفع والطرق التاريخية.\n-- لا ينفذ بيانات تشغيلية؛ تنفيذ التوحيد والحذف موجود في سكربت يدوي منفصل\n-- وفق قاعدة R-21 في دليل الترحيلات.\n\nBEGIN","CREATE TABLE IF NOT EXISTS public.payment_account_archive (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  archived_account_id uuid NOT NULL,\n  account_code text NOT NULL,\n  target_account_id uuid NOT NULL,\n  target_account_code text NOT NULL,\n  account_snapshot jsonb NOT NULL,\n  archived_at timestamptz NOT NULL DEFAULT now(),\n  archived_by uuid DEFAULT auth.uid(),\n  CONSTRAINT payment_account_archive_identity_key UNIQUE (archived_account_id)\n)","CREATE TABLE IF NOT EXISTS public.payment_account_journal_archive (\n  journal_line_id uuid PRIMARY KEY,\n  entry_id uuid NOT NULL,\n  archived_account_id uuid NOT NULL,\n  target_account_id uuid NOT NULL,\n  debit numeric(18,2) NOT NULL,\n  credit numeric(18,2) NOT NULL,\n  memo text,\n  partner_type text,\n  partner_id uuid,\n  line_created_at timestamptz NOT NULL,\n  archived_at timestamptz NOT NULL DEFAULT now()\n)","CREATE TABLE IF NOT EXISTS public.payment_account_reference_archive (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  relation_name text NOT NULL,\n  column_name text NOT NULL,\n  row_snapshot jsonb NOT NULL,\n  archived_account_id uuid NOT NULL,\n  target_account_id uuid NOT NULL,\n  archived_at timestamptz NOT NULL DEFAULT now()\n)","ALTER TABLE public.payment_account_archive ENABLE ROW LEVEL SECURITY","ALTER TABLE public.payment_account_journal_archive ENABLE ROW LEVEL SECURITY","ALTER TABLE public.payment_account_reference_archive ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS payment_account_archive_finance_read ON public.payment_account_archive","CREATE POLICY payment_account_archive_finance_read ON public.payment_account_archive\n  FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'manager') OR public.has_role(auth.uid(),'accountant'))","DROP POLICY IF EXISTS payment_account_journal_archive_finance_read ON public.payment_account_journal_archive","CREATE POLICY payment_account_journal_archive_finance_read ON public.payment_account_journal_archive\n  FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'manager') OR public.has_role(auth.uid(),'accountant'))","DROP POLICY IF EXISTS payment_account_reference_archive_finance_read ON public.payment_account_reference_archive","CREATE POLICY payment_account_reference_archive_finance_read ON public.payment_account_reference_archive\n  FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'manager') OR public.has_role(auth.uid(),'accountant'))","REVOKE ALL ON public.payment_account_archive, public.payment_account_journal_archive,\n  public.payment_account_reference_archive FROM PUBLIC, anon, authenticated","GRANT SELECT ON public.payment_account_archive, public.payment_account_journal_archive,\n  public.payment_account_reference_archive TO authenticated","GRANT ALL ON public.payment_account_archive, public.payment_account_journal_archive,\n  public.payment_account_reference_archive TO service_role","CREATE OR REPLACE FUNCTION public.payment_method_ledger_account(p_stored text)\nRETURNS text\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT CASE lower(btrim(coalesce(p_stored, '')))\n    WHEN 'credit' THEN NULL\n    WHEN 'split' THEN NULL\n    WHEN 'cash' THEN '1101'\n    WHEN 'bank' THEN '1111'\n    WHEN 'bank_transfer' THEN '1111'\n    WHEN 'card' THEN '1111'\n    WHEN 'kuraimi_bank' THEN '1111'\n    WHEN 'yemen_kuwait_bank' THEN '1111'\n    WHEN 'cheque' THEN '1221'\n    WHEN 'mobile_money' THEN '1131'\n    WHEN 'wallet' THEN '1131'\n    WHEN 'jawali' THEN '1131'\n    WHEN 'jaib' THEN '1131'\n    WHEN 'floosak' THEN '1131'\n    WHEN 'one_cash' THEN '1131'\n    ELSE m.default_account_code\n  END\n  FROM (SELECT 1) AS singleton\n  LEFT JOIN public.payment_methods m ON m.id = public.payment_method_resolve_id(p_stored);\n$$","REVOKE ALL ON FUNCTION public.payment_method_ledger_account(text) FROM PUBLIC, anon, authenticated, service_role","GRANT EXECUTE ON FUNCTION public.payment_method_ledger_account(text) TO service_role","COMMENT ON TABLE public.payment_account_archive IS\n  'لقطة غير قابلة للتحرير من حسابات الدفع الموحّدة؛ تحفظ الكود والهوية والحساب الهدف.'","COMMENT ON TABLE public.payment_account_journal_archive IS\n  'يحفظ الحساب التاريخي لكل سطر قيد قبل تحويله إلى حساب الدفع الموحد.'","COMMENT ON TABLE public.payment_account_reference_archive IS\n  'يحفظ الصفوف التي تشير إلى حساب الدفع القديم قبل تحويل مراجعها إلى الحساب الموحد.'",COMMIT,"-- Rollback: drop the helper function and archive tables after restoring\n-- any snapshots retained by the separate operational consolidation script."}	archive_and_consolidate_payment_accounts
64	{"-- Migration 64: دعم الدفع المجزأ (أكثر من طريقة) والترحيل المحاسبي المتوازن\n-- Multi-tender Split Payment & Balanced Ledger Posting Support\r\n\r\nBEGIN","-- ── 1. ترقية دالة ترحيل فواتير المبيعات post_sales_invoice لدعم التجزئة المحاسبية ──\r\n\r\nCREATE OR REPLACE FUNCTION public.post_sales_invoice(p_invoice_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_inv     record;\r\n  v_existing uuid;\r\n  v_entry   uuid;\r\n  v_lines   jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  v_split_acct text;\n  v_collectable numeric := 0;\n  v_split_total numeric := 0;\n  v_service_total numeric := 0;\r\n  v_cost    record;\r\n  r         record;\r\n  r_split   record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')\n          OR public.has_role(v_user,'accountant') OR\n          (public.has_role(v_user,'cashier') AND\n           current_setting('app.payment_split_internal_post', true) = 'on')) THEN\n    RAISE EXCEPTION 'Only an owner, manager or accountant may post an invoice';\r\n  END IF;\r\n\r\n  SELECT * INTO v_inv FROM public.sales_invoices WHERE id = p_invoice_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Invoice not found';\r\n  END IF;\r\n\r\n  IF v_inv.status IN ('draft','cancelled') THEN\r\n    RAISE EXCEPTION 'Invoice % is % - only confirmed, paid or partial invoices post',\r\n      v_inv.invoice_number, v_inv.status;\r\n  END IF;\r\n\r\n  IF v_inv.paid < 0 THEN\r\n    RAISE EXCEPTION 'Invoice % carries a negative payment (%). A refund is a credit note, not a negative payment.',\r\n      v_inv.invoice_number, v_inv.paid;\r\n  END IF;\r\n  IF v_inv.paid > v_inv.total THEN\r\n    RAISE EXCEPTION 'Invoice % was paid % against a total of %. Fix the invoice before posting - a payment cannot exceed the invoice.',\r\n      v_inv.invoice_number, v_inv.paid, v_inv.total;\r\n  END IF;\r\n  IF v_inv.tax < 0 THEN\r\n    RAISE EXCEPTION 'Invoice % carries a negative tax amount', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  SELECT id INTO v_existing\r\n    FROM public.journal_entries\r\n   WHERE source_type = 'sales_invoice' AND source_id = p_invoice_id\r\n     AND status <> 'REVERSED';\r\n  IF v_existing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'Invoice % has already been posted to the ledger', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- حل حساب التسوية المفرد\r\n  v_cash_acct := public.resolve_document_settlement_account(\r\n    v_inv.payment_method::text,\r\n    v_inv.cashbox_id,\r\n    v_inv.bank_account_id,\r\n    v_inv.payment_method_id\r\n  );\r\n  v_collectable := greatest(v_inv.total - v_inv.paid, 0);\r\n\r\n  -- ── الإيراد دائن: بند مُصنَّف حسب item_class ──\r\n  FOR r IN\r\n    SELECT coalesce(p.item_class::text, 'UNCLASSIFIED') AS bucket, sum(it.total) AS amount\r\n      FROM public.sales_invoice_items it\r\n      LEFT JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n       AND it.product_id IS NOT NULL\r\n     GROUP BY coalesce(p.item_class::text, 'UNCLASSIFIED')\r\n    HAVING sum(it.total) <> 0\r\n  LOOP\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', CASE r.bucket\r\n                        WHEN 'BY_PRODUCT' THEN '4211'\r\n                        WHEN 'SERVICE'    THEN '4311'\r\n                        ELSE '4111' END,\r\n      'credit', round(r.amount, 2),\r\n      'memo', 'إيراد ' || r.bucket);\r\n  END LOOP;\r\n\r\n  -- ── الإيراد دائن: الخدمة الحرة ──\r\n  SELECT coalesce(sum(l.total), 0) INTO v_service_total\r\n    FROM public.ad_hoc_service_lines l\r\n   WHERE l.invoice_id = p_invoice_id;\r\n  IF v_service_total <> 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '4311',\r\n      'credit', round(v_service_total, 2),\r\n      'memo', 'إيراد خدمة حرة (AD_HOC_SERVICE)');\r\n  END IF;\r\n\r\n  IF jsonb_array_length(v_lines) = 0 THEN\r\n    RAISE EXCEPTION 'Invoice % has no revenue lines', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- ── أسطر التحصيل (مدين) ──\r\n  IF v_inv.paid > 0 THEN\r\n    -- فحص الدفع المجزأ أولاً: إذا كانت هناك سجلات تجزئة\r\n    IF EXISTS (SELECT 1 FROM public.customer_payment_splits WHERE invoice_id = p_invoice_id) THEN\n      SELECT round(coalesce(sum(amount), 0), 2)\n        INTO v_split_total\n        FROM public.customer_payment_splits\n       WHERE invoice_id = p_invoice_id;\n      IF v_split_total <> round(v_inv.paid, 2) THEN\n        RAISE EXCEPTION 'Invoice % split total (%) does not match paid amount (%)',\n          v_inv.invoice_number, v_split_total, round(v_inv.paid, 2);\n      END IF;\n\n      FOR r_split IN\n        SELECT method::text AS method, amount, cashbox_id, bank_account_id,\n               payment_method_id, reference_no\n        FROM public.customer_payment_splits\n        WHERE invoice_id = p_invoice_id\n      LOOP\n        IF r_split.amount > 0 THEN\n          v_split_acct := public.resolve_document_settlement_account(\n            r_split.method, r_split.cashbox_id, r_split.bank_account_id,\n            coalesce(r_split.payment_method_id, r_split.method)\n          );\n          IF v_split_acct IS NULL THEN\n            RAISE EXCEPTION 'No ledger account could be resolved for split tender %', r_split.method;\n          END IF;\n          v_lines := v_lines || jsonb_build_object(\n            'account_code', v_split_acct,\n            'debit', round(r_split.amount, 2),\n            'memo', 'تحصيل مجزأ عبر ' || r_split.method ||\n                    coalesce(' — ' || nullif(r_split.reference_no, ''), ''));\n        END IF;\r\n      END LOOP;\r\n    ELSIF v_cash_acct IS NOT NULL THEN\r\n      -- دفع مفرد\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', v_cash_acct,\r\n        'debit', round(v_inv.paid, 2),\r\n        'memo', CASE\r\n                  WHEN v_cash_acct = '1111' THEN 'تحصيل عبر البنك'\r\n                  WHEN v_cash_acct = '1131' THEN 'تحصيل عبر المحفظة الإلكترونية'\r\n                  ELSE 'تحصيل نقدي بالصندوق'\r\n                END);\r\n    END IF;\r\n  END IF;\r\n\r\n  -- سطر الآجل (مدين - ذمم العملاء 1211)\r\n  IF v_collectable > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1211',\r\n      'debit', round(v_collectable, 2),\r\n      'partner_type', 'customer',\r\n      'partner_id', v_inv.customer_id,\r\n      'memo', 'ذمم العميل ' || coalesce(v_inv.invoice_number, ''));\r\n  END IF;\r\n\r\n  -- سطر الضريبة\r\n  IF v_inv.tax > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2311',\r\n      'credit', round(v_inv.tax, 2),\r\n      'memo', 'ضريبة مخرجات مستحقة');\r\n  END IF;\r\n\r\n  -- إنشاء وترحيل قيد اليومية\r\n  v_entry := public.post_journal_entry(\r\n    p_entry_date := v_inv.created_at::date,\r\n    p_memo := 'ترحيل فاتورة مبيعات ' || v_inv.invoice_number,\r\n    p_lines := v_lines,\r\n    p_source_type := 'sales_invoice',\r\n    p_source_id := p_invoice_id,\r\n    p_entry_number := 'JE-SI-' || v_inv.invoice_number\r\n  );\r\n\r\n  -- ── ترحيل تكلفة البضاعة المباعة (COGS) ──\r\n  SELECT coalesce(sum(sm.total_cost), 0) AS total_cogs\r\n    INTO v_cost\r\n    FROM public.stock_movements sm\r\n   WHERE sm.source_type = 'sales_invoice'\r\n     AND sm.source_id = p_invoice_id\r\n     AND sm.movement_type = 'OUT';\r\n\r\n  IF v_cost.total_cogs > 0 THEN\r\n    PERFORM public.post_journal_entry(\r\n      p_entry_date := v_inv.created_at::date,\r\n      p_memo := 'تكلفة البضاعة المباعة - فاتورة ' || v_inv.invoice_number,\r\n      p_lines := jsonb_build_array(\r\n        jsonb_build_object('account_code', '5111', 'debit', round(v_cost.total_cogs, 2), 'memo', 'تكلفة المبيعات'),\r\n        jsonb_build_object('account_code', '1313', 'credit', round(v_cost.total_cogs, 2), 'memo', 'صرف مخزون تام')\r\n      ),\r\n      p_source_type := 'sales_invoice_cogs',\r\n      p_source_id := p_invoice_id,\r\n      p_entry_number := 'JE-COGS-' || v_inv.invoice_number\r\n    );\r\n  END IF;\r\n\r\n  RETURN v_entry;\r\nEND;\r\n$$","GRANT EXECUTE ON FUNCTION public.post_sales_invoice(uuid) TO authenticated, service_role","-- ── 2. ترقية دالة إنشاء البيع الشاملة create_sale (9-argument overload) لدعم التجزئة ──\r\n\r\nCREATE OR REPLACE FUNCTION public.create_sale(\r\n  _warehouse_id uuid,\r\n  _customer_id uuid,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _discount numeric,\r\n  _note text,\r\n  _items jsonb,\r\n  _sale_date date,\r\n  _payment_splits jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $$\r\nDECLARE\r\n  v_invoice_id     uuid;\r\n  v_invoice_number text;\r\n  v_user           uuid := auth.uid();\r\n  v_line           record;\r\n  v_subtotal       numeric := 0;\r\n  v_tax_total      numeric := 0;\r\n  v_discount       numeric := coalesce(_discount, 0);\r\n  v_total          numeric := 0;\r\n  v_paid           numeric := 0;\r\n  v_outstanding    numeric := 0;\r\n  v_price          numeric;\r\n  v_tax_rate       numeric;\r\n  v_customer_balance numeric;\r\n  v_credit_limit   numeric;\r\n  v_line_total     numeric;\r\n  v_line_tax       numeric;\r\n  v_effect         text;\r\n  v_line_type      text;\r\n  v_sellable       boolean;\r\n  v_status         public.invoice_status;\r\n  v_last_item_id   uuid;\r\n  v_available      numeric;\r\n  v_system         boolean := false;\r\n  v_posted_at      timestamptz;\r\n  v_split          record;\r\n  v_split_total    numeric := 0;\r\n  v_distinct_methods integer := 0;\r\n  v_recorded_method text := _payment_method;\r\n  v_has_splits     boolean := false;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to post sales';\r\n  END IF;\r\n\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse is required';\r\n  END IF;\r\n\r\n  IF coalesce(jsonb_typeof(_items), '') <> 'array'\r\n     OR coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'Cart is empty';\r\n  END IF;\r\n\r\n  IF v_discount < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot be negative';\r\n  END IF;\r\n\r\n  IF coalesce(_paid, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Paid amount cannot be negative';\r\n  END IF;\r\n\r\n  -- ── التحقق من صحة سجلات الدفع المجزأ إن وجدت ──\r\n  IF coalesce(jsonb_typeof(_payment_splits), 'jsonb') = 'array'\r\n     AND coalesce(jsonb_array_length(_payment_splits), 0) > 0 THEN\r\n    v_has_splits := true;\r\n\r\n    FOR v_split IN\r\n      SELECT part ->> 'method' AS method,\n             coalesce((part ->> 'amount')::numeric, 0) AS amount,\n             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,\n             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,\n             nullif(part ->> 'payment_method_id', '') AS payment_method_id,\n             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference\n      FROM jsonb_array_elements(_payment_splits) AS part\r\n    LOOP\r\n      IF v_split.method IS NULL\n         OR v_split.method NOT IN ('cash', 'card', 'bank_transfer', 'mobile_money', 'cheque') THEN\n        RAISE EXCEPTION 'Unsupported split payment method: %', v_split.method;\n      END IF;\n      IF public.resolve_writable_payment_method(\n           coalesce(v_split.payment_method_id, v_split.method), 'pos', true\n         ) IS DISTINCT FROM v_split.method THEN\n        RAISE EXCEPTION 'Payment method id does not match split tender %', v_split.method;\n      END IF;\n      IF v_split.amount <= 0 THEN\r\n        RAISE EXCEPTION 'Every payment tender component requires a positive amount';\r\n      END IF;\r\n      v_split_total := v_split_total + v_split.amount;\r\n    END LOOP;\r\n\r\n    SELECT count(DISTINCT part ->> 'method') INTO v_distinct_methods\n    FROM jsonb_array_elements(_payment_splits) AS part;\n\n    IF v_distinct_methods <> jsonb_array_length(_payment_splits) THEN\n      RAISE EXCEPTION 'A payment method may only be included once in a split';\n    END IF;\n\r\n    IF v_distinct_methods > 1 THEN\r\n      v_recorded_method := 'split';\r\n    END IF;\r\n  ELSE\r\n    IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'cheque') THEN\n      RAISE EXCEPTION 'Unsupported payment method: %', _payment_method;\r\n    END IF;\r\n  END IF;\r\n\r\n  -- ── التحقق من رصيد المخزون لجميع البنود ──\r\n  FOR v_line IN\r\n    SELECT r.o_product_id AS product_id, sum(r.o_quantity) AS quantity\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n    WHERE r.o_stock_effect = 'STOCK_ISSUE'\r\n    GROUP BY r.o_product_id\r\n    ORDER BY r.o_product_id\r\n  LOOP\r\n    SELECT i.quantity INTO v_available\r\n    FROM public.inventory i\r\n    WHERE i.product_id = v_line.product_id\r\n      AND i.warehouse_id = _warehouse_id\r\n      AND i.owner_type = 'COMPANY'\r\n      AND i.owner_id IS NULL\r\n    FOR UPDATE;\r\n\r\n    v_available := coalesce(v_available, 0);\r\n\r\n    IF v_available < v_line.quantity THEN\r\n      RAISE EXCEPTION\r\n        'Insufficient stock for item %: available %, requested %',\r\n        v_line.product_id, v_available, v_line.quantity\r\n        USING ERRCODE = 'check_violation';\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- ── حساب المجاميع والأسعار ──\r\n  FOR v_line IN\r\n    SELECT r.o_product_id    AS product_id,\r\n           r.o_quantity      AS quantity,\r\n           r.o_service_name  AS service_name,\r\n           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,\r\n           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n  LOOP\r\n    IF v_line.quantity IS NULL OR v_line.quantity <= 0 THEN\r\n      RAISE EXCEPTION 'Every sale line requires a positive quantity';\r\n    END IF;\r\n\r\n    IF v_line.product_id IS NULL THEN\r\n      IF coalesce(v_line.service_name, '') = '' THEN\r\n        RAISE EXCEPTION 'Every service line requires a description';\r\n      END IF;\r\n      IF v_line.input_price < 0 OR v_line.input_tax < 0 OR v_line.input_tax > 100 THEN\r\n        RAISE EXCEPTION 'Service line \\"%\\" has an invalid price or tax rate', v_line.service_name;\r\n      END IF;\r\n      v_price    := v_line.input_price;\r\n      v_tax_rate := v_line.input_tax;\r\n    ELSE\r\n      SELECT p.sale_price, p.tax_rate, p.is_sellable\r\n        INTO v_price, v_tax_rate, v_sellable\r\n      FROM public.products p\r\n      WHERE p.id = v_line.product_id AND p.is_active = true\r\n      FOR UPDATE;\r\n\r\n      IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Item % is not available for sale', v_line.product_id;\r\n      END IF;\r\n\r\n      IF v_sellable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as sellable', v_line.product_id;\r\n      END IF;\r\n\r\n      IF v_price < 0 OR v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n        RAISE EXCEPTION 'Item % has invalid pricing or tax configuration', v_line.product_id;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := round(v_line.quantity * v_price, 2);\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + round(v_line_total * v_tax_rate / 100, 2);\r\n  END LOOP;\r\n\r\n  v_total := round(v_subtotal + v_tax_total - v_discount, 2);\r\n  IF v_discount > v_subtotal + v_tax_total OR v_total < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot exceed the invoice amount';\r\n  END IF;\r\n\r\n  IF _customer_id IS NOT NULL THEN\r\n    SELECT balance, credit_limit, is_system\r\n      INTO v_customer_balance, v_credit_limit, v_system\r\n    FROM public.customers\r\n    WHERE id = _customer_id AND is_active = true\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Selected customer is unavailable';\r\n    END IF;\r\n  END IF;\r\n\r\n  -- مطابقة مبالغ الدفع\r\n  v_paid := least(coalesce(_paid, 0), v_total);\r\n  v_outstanding := round(v_total - v_paid, 2);\r\n\r\n  IF v_has_splits THEN\r\n    IF round(v_split_total, 2) <> round(v_paid, 2) THEN\r\n      RAISE EXCEPTION 'Split breakdown total (%) does not match paid amount (%)',\r\n        round(v_split_total, 2), round(v_paid, 2);\r\n    END IF;\r\n  END IF;\r\n\r\n  IF v_outstanding > 0 AND _customer_id IS NULL THEN\r\n    RAISE EXCEPTION 'A customer is required when the sale has an unpaid amount';\r\n  END IF;\r\n\r\n  IF v_outstanding > 0 AND v_system THEN\r\n    RAISE EXCEPTION\r\n      'The system cash customer cannot carry credit — select a real customer for a deferred sale'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN\r\n    RAISE EXCEPTION\r\n      'Credit limit exceeded: current balance %, requested debt %, limit %',\r\n      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);\r\n  END IF;\r\n\r\n  v_status := 'confirmed'::public.invoice_status;\r\n  v_invoice_number := public.next_invoice_number();\r\n  v_posted_at := coalesce(_sale_date, current_date)::timestamp + localtime;\r\n\r\n  -- ── إدراج رأس الفاتورة ──\r\n  INSERT INTO public.sales_invoices (\r\n    invoice_number, customer_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by,\r\n    created_at, updated_at\r\n  )\r\n  VALUES (\r\n    v_invoice_number, _customer_id, _warehouse_id, v_status,\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, v_discount, v_tax_total, v_total, v_paid,\r\n    v_recorded_method::public.payment_method, nullif(btrim(_note), ''), v_user,\r\n    v_posted_at, now()\r\n  )\r\n  RETURNING id INTO v_invoice_id;\r\n\r\n  -- ── إدراج سطور الفاتورة وحركات المخزون ──\r\n  FOR v_line IN\r\n    SELECT r.o_product_id   AS product_id,\r\n           r.o_quantity     AS quantity,\r\n           r.o_stock_effect AS stock_effect,\r\n           r.o_service_name AS service_name,\r\n           coalesce((line ->> 'unit_price')::numeric, 0) AS input_price,\r\n           coalesce((line ->> 'tax_rate')::numeric, 0)   AS input_tax,\r\n           nullif(btrim(coalesce(line ->> 'uom_id', '')), '')::uuid AS uom_id\r\n    FROM jsonb_array_elements(_items) AS line\r\n    CROSS JOIN LATERAL public.resolve_sale_line(line) AS r\r\n  LOOP\r\n    IF v_line.product_id IS NULL THEN\r\n      v_price     := v_line.input_price;\r\n      v_tax_rate  := v_line.input_tax;\r\n      v_line_type := 'AD_HOC_SERVICE';\r\n      v_effect    := 'NONE';\r\n    ELSE\r\n      SELECT p.sale_price, p.tax_rate\r\n        INTO v_price, v_tax_rate\r\n      FROM public.products p WHERE p.id = v_line.product_id;\r\n\r\n      v_line_type := public.item_line_type(v_line.product_id, false);\r\n      v_effect    := public.item_stock_effect(v_line.product_id, 'out');\r\n\r\n      IF v_effect = 'STOCK_ISSUE' THEN\r\n        PERFORM public.post_stock_delta(\r\n          p_product_id => v_line.product_id,\r\n          p_warehouse_id => _warehouse_id,\r\n          p_signed_qty => -v_line.quantity,\r\n          p_unit_cost => NULL,\r\n          p_movement_kind => 'ISSUE'::public.stock_movement_kind,\r\n          p_source_type => 'sales_invoice',\r\n          p_source_id => v_invoice_id,\r\n          p_note => 'POS sale',\r\n          p_owner_type => 'COMPANY'::public.owner_type,\r\n          p_owner_id => NULL,\r\n          p_movement_type_legacy => 'sale'::public.movement_type\r\n        );\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := round(v_line.quantity * v_price, 2);\r\n    v_line_tax   := round(v_line_total * v_tax_rate / 100, 2);\r\n\r\n    INSERT INTO public.sales_invoice_items (\r\n      invoice_id, product_id, description, quantity, unit_price, discount, tax, total,\r\n      line_type, stock_effect, uom_id\r\n    )\r\n    VALUES (\r\n      v_invoice_id,\r\n      v_line.product_id,\r\n      CASE WHEN v_line.product_id IS NULL THEN v_line.service_name ELSE NULL END,\r\n      v_line.quantity, v_price, 0, v_line_tax, v_line_total + v_line_tax,\r\n      v_line_type, v_effect, v_line.uom_id\r\n    )\r\n    RETURNING id INTO v_last_item_id;\r\n\r\n    IF v_line_type = 'AD_HOC_SERVICE' THEN\r\n      INSERT INTO public.ad_hoc_service_lines (\r\n        invoice_id, invoice_item_id, description, quantity, unit_price,\r\n        discount, tax, total, created_by\r\n      )\r\n      VALUES (\r\n        v_invoice_id, v_last_item_id, v_line.service_name, v_line.quantity,\r\n        v_price, 0, v_line_tax, v_line_total + v_line_tax, v_user\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- مزامنة تواريخ حركات المخزون مع تاريخ البيع\r\n  PERFORM set_config('app.stock_engine', 'on', true);\r\n  UPDATE public.stock_movements\r\n  SET created_at = v_posted_at\r\n  WHERE source_type = 'sales_invoice' AND source_id = v_invoice_id;\r\n  PERFORM set_config('app.stock_engine', 'off', true);\r\n\r\n  -- ── تحديث ذمة العميل للآجل إن وجد ──\r\n  IF v_outstanding > 0 THEN\r\n    UPDATE public.customers\r\n    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()\r\n    WHERE id = _customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, debit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',\r\n      v_posted_at, v_user, 'sale:' || v_invoice_id, 'قيد بيع آجل'\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  -- ── إدراج سجلات الدفع المجزأ قبل الترحيل المحاسبي ──\r\n  IF v_has_splits THEN\r\n    FOR v_split IN\r\n      SELECT part ->> 'method' AS method,\n             coalesce((part ->> 'amount')::numeric, 0) AS amount,\n             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,\n             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,\n             nullif(part ->> 'payment_method_id', '') AS payment_method_id,\n             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference\n      FROM jsonb_array_elements(_payment_splits) AS part\r\n    LOOP\r\n      IF v_split.amount > 0 THEN\r\n        INSERT INTO public.customer_payment_splits (\n          customer_id, invoice_id, method, amount, occurred_at, created_by,\n          cashbox_id, bank_account_id, payment_method_id, reference_no\n        )\n        VALUES (\r\n          _customer_id,\r\n          v_invoice_id,\r\n          v_split.method::public.payment_method,\r\n          round(v_split.amount, 2),\r\n          v_posted_at,\n          v_user,\n          v_split.cashbox_id,\n          v_split.bank_account_id,\n          coalesce(v_split.payment_method_id, v_split.method),\n          v_split.reference\n        );\r\n      END IF;\r\n    END LOOP;\r\n  END IF;\r\n\r\n  -- ── سجل التدقيق ──\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'sale.posted', 'sales_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_number,\r\n      'warehouse_id', _warehouse_id,\r\n      'customer_id', _customer_id,\r\n      'payment_method', v_recorded_method,\r\n      'total', v_total,\r\n      'paid', v_paid,\r\n      'outstanding', v_outstanding,\r\n      'has_splits', v_has_splits,\r\n      'split_count', CASE WHEN v_has_splits THEN jsonb_array_length(_payment_splits) ELSE 0 END,\r\n      'line_count', jsonb_array_length(_items)\r\n    ));\r\n\r\n  -- ── الترحيل المحاسبي المتوازن التلقائي ──\r\n  PERFORM set_config('app.payment_split_internal_post', 'on', true);\n  PERFORM public.post_sales_invoice(v_invoice_id);\n  PERFORM set_config('app.payment_split_internal_post', 'off', true);\n\r\n  RETURN v_invoice_id;\r\nEND;\r\n$$","GRANT EXECUTE ON FUNCTION public.create_sale(uuid, uuid, text, numeric, numeric, text, jsonb, date, jsonb) TO authenticated, service_role","-- ── 3. تحديث النسخ الفرعية من create_sale لتمرير النداءات للدالة الشاملة ──\r\n\r\nCREATE OR REPLACE FUNCTION public.create_sale(\r\n  _warehouse_id uuid,\r\n  _customer_id uuid,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _discount numeric,\r\n  _note text,\r\n  _items jsonb,\r\n  _sale_date date\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $$\r\nBEGIN\r\n  RETURN public.create_sale(\r\n    _warehouse_id, _customer_id, _payment_method, _paid, _discount, _note, _items, _sale_date, '[]'::jsonb\r\n  );\r\nEND;\r\n$$","CREATE OR REPLACE FUNCTION public.create_sale(\r\n  _warehouse_id uuid,\r\n  _customer_id uuid,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _discount numeric,\r\n  _note text,\r\n  _items jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $$\r\nBEGIN\r\n  RETURN public.create_sale(\r\n    _warehouse_id, _customer_id, _payment_method, _paid, _discount, _note, _items, current_date, '[]'::jsonb\r\n  );\r\nEND;\r\n$$","GRANT EXECUTE ON FUNCTION public.create_sale(uuid, uuid, text, numeric, numeric, text, jsonb, date) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.create_sale(uuid, uuid, text, numeric, numeric, text, jsonb) TO authenticated, service_role",COMMIT,"-- Rollback: replace post_sales_invoice/create_sale overloads with their prior\n-- definitions from migrations 43 and 46, then disable the POS split switch."}	split_sales_ledger_posting
65	{"-- Migration 65: الدفع المجزأ في المشتريات واستلام الطحن\n-- Split payments for purchase invoices and milling service documents\r\n--\r\n-- WHY\r\n-- ---\r\n-- Migration 64 gave sales one honest split mechanism: its tenders are written to\n-- `customer_payment_splits` and `post_sales_invoice` debits each tender to its\r\n-- own ledger account (1101 / 1111 / 1131) while the unpaid remainder goes to\r\n-- 1211. Purchases and milling intake were left with a single `payment_method`\r\n-- column, so a purchase paid half cash and half bank could only be recorded\r\n-- against ONE account: the other tender vanished from the ledger while the\r\n-- trial balance still reconciled. That is the same class of silent error\r\n-- migration 64 removed for sales, so it is fixed the same way here.\n--\r\n-- WHAT\r\n-- ----\r\n--  1. `payment_splits` — one row per (document, tender, amount) for purchase\r\n--     invoices and milling service documents. A deferred trigger keeps the sum\r\n--     of the tenders equal to the document's paid amount.\r\n--  2. `post_purchase_invoice` — unchanged accounting, except the settlement\r\n--     credit is split per tender when splits exist instead of posted to a\r\n--     single account.\r\n--  3. `create_purchase` gains `_payment_splits`; every older signature\r\n--     delegates with an empty array, so no existing caller changes.\r\n--  4. `create_milling_service_document_multi` gains `_payment_splits`.\r\n--\r\n-- The rules `create_sale` enforces for splits are enforced here too: every\r\n-- tender is positive, no tender is `credit` (a receivable, not a tender), and\r\n-- the tenders sum to at most the document total.\r\n\r\nBEGIN","-- ── 1. جدول تجزئة الدفعات للمستندات غير البيعية ─────────────────────────────\r\n\r\nCREATE TABLE IF NOT EXISTS public.payment_splits (\r\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  document_type text NOT NULL CHECK (document_type IN ('purchase_invoice', 'milling_service_document')),\r\n  document_id uuid NOT NULL,\r\n  method public.payment_method NOT NULL,\n  amount numeric(18, 2) NOT NULL CHECK (amount > 0),\n  reference text,\n  cashbox_id uuid REFERENCES public.cashboxes(id) ON DELETE SET NULL,\n  bank_account_id uuid REFERENCES public.company_bank_accounts(id) ON DELETE SET NULL,\n  payment_method_id text REFERENCES public.payment_methods(id) ON DELETE SET NULL,\n  occurred_at timestamptz NOT NULL DEFAULT now(),\r\n  created_by uuid REFERENCES auth.users (id),\r\n  created_at timestamptz NOT NULL DEFAULT now(),\r\n  CONSTRAINT payment_splits_not_credit CHECK (method <> 'credit'),\r\n  CONSTRAINT payment_splits_not_split CHECK (method <> 'split')\r\n)","CREATE INDEX IF NOT EXISTS payment_splits_document_idx\r\n  ON public.payment_splits (document_type, document_id)","COMMENT ON TABLE public.payment_splits IS\r\n  'تفصيل الدفعة الواحدة على أكثر من طريقة دفع. كل صف = طريقة تحصيل فعلية بمبلغها. الآجل لا يُسجّل هنا لأنه دين لا تحصيل.'","-- ── 2. بوابة التحقق: مجموع الأجزاء يجب أن يساوي المدفوع على المستند ─────────\r\n-- A DEFERRED constraint trigger runs at COMMIT, so the inserting function may\r\n-- write the header and then the tenders in whatever order it likes.\r\n\r\nCREATE OR REPLACE FUNCTION public.assert_payment_splits_balance()\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\n  v_split_total numeric := 0;\n  v_paid numeric;\n  v_total numeric;\n  v_document_type text;\n  v_document_id uuid;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    v_document_type := OLD.document_type;\n    v_document_id := OLD.document_id;\n  ELSE\n    v_document_type := NEW.document_type;\n    v_document_id := NEW.document_id;\n  END IF;\n\n  SELECT round(coalesce(sum(amount), 0), 2) INTO v_split_total\n    FROM public.payment_splits\n   WHERE document_type = v_document_type AND document_id = v_document_id;\n\n  IF v_document_type = 'purchase_invoice' THEN\n    SELECT pi.paid, pi.total INTO v_paid, v_total\n      FROM public.purchase_invoices pi WHERE pi.id = v_document_id;\n  ELSE\n    SELECT si.paid, si.total\n      INTO v_paid, v_total\n      FROM public.milling_service_documents d\n      JOIN public.sales_invoices si ON si.id = d.sales_invoice_id\n     WHERE d.id = v_document_id;\n  END IF;\r\n\r\n  IF v_total IS NULL THEN\r\n    RAISE EXCEPTION 'Record the document before its payment split';\r\n  END IF;\r\n  IF v_split_total > round(v_total, 2) THEN\r\n    RAISE EXCEPTION 'Payment split total (%) exceeds the document total (%)',\r\n      v_split_total, round(v_total, 2);\r\n  END IF;\r\n  IF v_split_total <> round(coalesce(v_paid, 0), 2) THEN\r\n    RAISE EXCEPTION 'Payment split total (%) does not match the paid amount (%)',\r\n      v_split_total, round(coalesce(v_paid, 0), 2);\r\n  END IF;\r\n\r\n  RETURN NULL;\nEND;\r\n$$","REVOKE ALL ON FUNCTION public.assert_payment_splits_balance() FROM PUBLIC, anon, authenticated, service_role","DROP TRIGGER IF EXISTS trg_payment_splits_balance ON public.payment_splits","CREATE CONSTRAINT TRIGGER trg_payment_splits_balance\n  AFTER INSERT OR UPDATE OR DELETE ON public.payment_splits\n  DEFERRABLE INITIALLY DEFERRED\r\n  FOR EACH ROW EXECUTE FUNCTION public.assert_payment_splits_balance()","-- ── 3. ترحيل فاتورة الشراء: كل طريقة تحصيل إلى حسابها ────────────────────────\r\n-- Body preserved from migration 43 (the authoritative version) except the single\r\n-- settlement credit, which becomes one credit per tender when a split exists.\r\n\r\nCREATE OR REPLACE FUNCTION public.post_purchase_invoice(p_invoice_id uuid)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  v_user    uuid := auth.uid();\r\n  v_inv     record;\r\n  v_existing uuid;\r\n  v_entry   uuid;\r\n  v_lines   jsonb := '[]'::jsonb;\r\n  v_cash_acct text;\r\n  v_split_acct text;\r\n  v_owed     numeric := 0;\r\n  v_has_splits boolean := false;\r\n  r         record;\r\n  r_split   record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (public.has_role(v_user,'owner') OR public.has_role(v_user,'manager')\n          OR public.has_role(v_user,'accountant') OR\n          (public.has_role(v_user,'cashier') AND\n           current_setting('app.payment_split_internal_post', true) = 'on')) THEN\n    RAISE EXCEPTION 'Only an owner, manager or accountant may post a purchase invoice';\r\n  END IF;\r\n\r\n  SELECT * INTO v_inv FROM public.purchase_invoices WHERE id = p_invoice_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Purchase invoice not found';\r\n  END IF;\r\n\r\n  IF v_inv.status IN ('draft','cancelled') THEN\r\n    RAISE EXCEPTION 'Purchase % is % - only confirmed, paid or partial invoices post',\r\n      v_inv.invoice_number, v_inv.status;\r\n  END IF;\r\n\r\n  IF v_inv.paid < 0 THEN\r\n    RAISE EXCEPTION 'Purchase % carries a negative payment (%). A supplier return is a return document, not a negative payment.',\r\n      v_inv.invoice_number, v_inv.paid;\r\n  END IF;\r\n  IF v_inv.paid > v_inv.total THEN\r\n    RAISE EXCEPTION 'Purchase % was paid % against a total of %. Fix the invoice before posting - a payment cannot exceed the invoice.',\r\n      v_inv.invoice_number, v_inv.paid, v_inv.total;\r\n  END IF;\r\n\r\n  SELECT id INTO v_existing\r\n    FROM public.journal_entries\r\n   WHERE source_type = 'purchase_invoice' AND source_id = p_invoice_id\r\n     AND status <> 'REVERSED';\r\n  IF v_existing IS NOT NULL THEN\r\n    RAISE EXCEPTION 'Purchase % has already been posted to the ledger', v_inv.invoice_number;\r\n  END IF;\r\n\r\n  -- P0: نداء موضعي على المصدر مباشرة، فلا يتأثر بأي اسم وسيط.\r\n  v_cash_acct := public.resolve_document_settlement_account(\n    v_inv.payment_method::text, v_inv.cashbox_id, v_inv.bank_account_id, v_inv.payment_method_id\n  );\n  v_owed := greatest(v_inv.total - v_inv.paid, 0);\r\n\r\n  FOR r IN\r\n    SELECT coalesce(p.item_class::text, 'UNCLASSIFIED') AS item_class,\r\n           coalesce(it.stock_effect, 'NONE') AS effect,\r\n           sum(it.total)                     AS amount,\r\n           sum(it.tax)                       AS line_tax\r\n      FROM public.purchase_invoice_items it\r\n      LEFT JOIN public.products p ON p.id = it.product_id\r\n     WHERE it.invoice_id = p_invoice_id\r\n     GROUP BY coalesce(p.item_class::text, 'UNCLASSIFIED'), coalesce(it.stock_effect, 'NONE')\r\n    HAVING sum(it.total) <> 0 OR sum(it.tax) <> 0\r\n  LOOP\r\n    IF r.amount <> 0 THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', CASE\r\n          WHEN r.effect <> 'STOCK_RECEIPT' THEN '5911'\r\n          ELSE CASE r.item_class\r\n                 WHEN 'RAW_MATERIAL'  THEN '1311'\r\n                 WHEN 'BY_PRODUCT'    THEN '1314'\r\n                 WHEN 'FINISHED_GOOD' THEN '1313'\r\n                 ELSE '1315' END END,\r\n        'debit', round(r.amount, 2),\r\n        'memo', CASE WHEN r.effect <> 'STOCK_RECEIPT'\r\n                     THEN 'مصروف مشتريات ' || r.item_class\r\n                     ELSE 'شراء ' || r.item_class END);\r\n    END IF;\r\n\r\n    IF r.line_tax <> 0 THEN\r\n      v_lines := v_lines || jsonb_build_object(\r\n        'account_code', '1316', 'debit', round(r.line_tax, 2),\r\n        'memo', 'ضريبة مدخلات قابلة للاسترداد');\r\n    END IF;\r\n  END LOOP;\r\n\r\n  IF v_inv.tax <> 0 AND NOT EXISTS (\r\n       SELECT 1 FROM public.purchase_invoice_items it\r\n        WHERE it.invoice_id = p_invoice_id AND it.tax <> 0) THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '1316', 'debit', round(v_inv.tax, 2),\r\n      'memo', 'ضريبة مدخلات قابلة للاسترداد');\r\n  END IF;\r\n\r\n  IF jsonb_array_length(v_lines) = 0 THEN\r\n    RAISE EXCEPTION 'Purchase % has nothing to post - its lines are empty or zero',\r\n      v_inv.invoice_number;\r\n  END IF;\r\n\r\n  IF v_owed > 0 THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', '2111', 'credit', round(v_owed, 2),\r\n      'memo', 'مستحق للمورد',\r\n      'partner_type', 'supplier',\r\n      'partner_id', v_inv.supplier_id);\r\n  END IF;\r\n\r\n  -- ── السداد: إمّا حساب واحد (السلوك السابق) أو حساب لكل طريقة ──\r\n  SELECT EXISTS (\r\n    SELECT 1 FROM public.payment_splits\r\n     WHERE document_type = 'purchase_invoice' AND document_id = p_invoice_id\r\n  ) INTO v_has_splits;\r\n\r\n  IF v_inv.paid > 0 AND v_has_splits THEN\r\n    FOR r_split IN\r\n      SELECT method::text AS method, amount, reference, cashbox_id,\n             bank_account_id, payment_method_id\n        FROM public.payment_splits\n       WHERE document_type = 'purchase_invoice' AND document_id = p_invoice_id\n    LOOP\n      v_split_acct := public.resolve_document_settlement_account(\n        r_split.method, r_split.cashbox_id, r_split.bank_account_id,\n        coalesce(r_split.payment_method_id, r_split.method)\n      );\n      IF v_split_acct IS NULL THEN\n        RAISE EXCEPTION 'No ledger account could be resolved for split tender %', r_split.method;\n      END IF;\n      IF r_split.amount > 0 THEN\n        v_lines := v_lines || jsonb_build_object(\n          'account_code', v_split_acct,\n          'credit', r_split.amount,\n          'memo', 'سداد للمورد (دفع مجزأ) — ' || r_split.method ||\n                  coalesce(' — ' || nullif(r_split.reference, ''), ''));\n      END IF;\r\n    END LOOP;\r\n  ELSIF v_inv.paid > 0 AND v_cash_acct IS NOT NULL THEN\r\n    v_lines := v_lines || jsonb_build_object(\r\n      'account_code', v_cash_acct, 'credit', round(v_inv.paid, 2),\r\n      'memo', 'سداد للمورد');\r\n  END IF;\r\n\r\n  v_entry := public.create_journal_entry(\r\n    p_memo => 'فاتورة مشتريات ' || v_inv.invoice_number,\r\n    p_entry_date => v_inv.created_at::date,\r\n    p_source_type => 'purchase_invoice',\r\n    p_source_id => p_invoice_id,\r\n    p_is_system => true,\r\n    p_lines => v_lines);\r\n\r\n  RETURN v_entry;\r\nEND $$","COMMENT ON FUNCTION public.post_purchase_invoice(uuid) IS\r\n  'يرحّل فاتورة شراء واحدة بقيود متوازنة، ويوزّع السداد على حساب كل طريقة دفع عند وجود تجزئة.'","GRANT EXECUTE ON FUNCTION public.post_purchase_invoice(uuid) TO authenticated, service_role","-- ── 4. create_purchase: توقيع يقبل تجزئة الدفع ─────────────────────────────\r\n-- Body preserved from migration 43 (system-supplier guard, v_paid clamp), plus\r\n-- split validation and the payment_splits rows.\r\n\r\nCREATE OR REPLACE FUNCTION public.create_purchase(\r\n  _warehouse_id uuid,\r\n  _supplier_id uuid,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _discount numeric,\r\n  _note text,\r\n  _items jsonb,\r\n  _payment_splits jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_invoice_id       uuid;\r\n  v_invoice_no       text;\r\n  v_user             uuid := auth.uid();\r\n  v_item             jsonb;\r\n  v_subtotal         numeric := 0;\r\n  v_tax_total        numeric := 0;\r\n  v_total            numeric := 0;\r\n  v_qty              numeric;\r\n  v_cost             numeric;\r\n  v_tax_rate         numeric;\r\n  v_line_total       numeric;\r\n  v_line_tax         numeric;\r\n  v_product          uuid;\r\n  v_effect           text;\r\n  v_type             text;\r\n  v_purchasable      boolean;\r\n  v_system           boolean := false;\r\n  v_supplier_balance numeric;\r\n  v_paid             numeric;\r\n  v_split            record;\r\n  v_split_total      numeric := 0;\r\n  v_split_count      integer := 0;\r\n  v_recorded_method  text := coalesce(_payment_method, 'cash');\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT public.is_staff(v_user) THEN\r\n    RAISE EXCEPTION 'Forbidden';\r\n  END IF;\r\n  IF _warehouse_id IS NULL THEN\r\n    RAISE EXCEPTION 'Warehouse required';\r\n  END IF;\r\n  IF _supplier_id IS NULL THEN\r\n    RAISE EXCEPTION 'Supplier required';\r\n  END IF;\r\n  IF coalesce(jsonb_array_length(_items), 0) = 0 THEN\r\n    RAISE EXCEPTION 'No items';\r\n  END IF;\r\n\r\n  ------------------------------------------------------------------ validate\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    IF v_qty IS NULL OR v_qty <= 0 THEN\r\n      RAISE EXCEPTION 'Invalid quantity';\r\n    END IF;\r\n    IF v_cost IS NULL OR v_cost < 0 THEN\r\n      RAISE EXCEPTION 'Invalid unit cost';\r\n    END IF;\r\n    IF v_tax_rate < 0 OR v_tax_rate > 100 THEN\r\n      RAISE EXCEPTION 'Invalid tax rate';\r\n    END IF;\r\n    IF (v_item ->> 'product_id') IS NOT NULL THEN\r\n      SELECT p.is_purchasable INTO v_purchasable\r\n      FROM public.products p WHERE p.id = (v_item ->> 'product_id')::uuid;\r\n\r\n      IF v_purchasable IS NOT TRUE THEN\r\n        RAISE EXCEPTION 'Item % is not marked as purchasable', v_item ->> 'product_id';\r\n      END IF;\r\n    END IF;\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n    v_subtotal   := v_subtotal + v_line_total;\r\n    v_tax_total  := v_tax_total + v_line_tax;\r\n  END LOOP;\r\n\r\n  v_total := v_subtotal + v_tax_total - coalesce(_discount, 0);\r\n\r\n  -- ── التحقق من تجزئة الدفع قبل أي إدراج ──\r\n  IF coalesce(jsonb_typeof(_payment_splits), '') = 'array'\r\n     AND jsonb_array_length(_payment_splits) > 0 THEN\r\n    FOR v_split IN\r\n      SELECT part ->> 'method' AS method,\n             coalesce((part ->> 'amount')::numeric, 0) AS amount,\n             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,\n             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,\n             nullif(part ->> 'payment_method_id', '') AS payment_method_id,\n             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference\n        FROM jsonb_array_elements(_payment_splits) AS part\r\n    LOOP\r\n      IF v_split.method IS NULL\n         OR v_split.method NOT IN ('cash', 'card', 'bank_transfer', 'mobile_money', 'cheque') THEN\n        RAISE EXCEPTION 'Unsupported purchase split method: %', v_split.method;\n      END IF;\n      IF public.resolve_writable_payment_method(\n           coalesce(v_split.payment_method_id, v_split.method), 'purchases', true\n         ) IS DISTINCT FROM v_split.method THEN\n        RAISE EXCEPTION 'Payment method id does not match purchase tender %', v_split.method;\n      END IF;\n      IF v_split.amount <= 0 THEN\r\n        RAISE EXCEPTION 'Every purchase payment tender requires a positive amount';\r\n      END IF;\r\n      v_split_total := v_split_total + v_split.amount;\r\n      v_split_count := v_split_count + 1;\r\n    END LOOP;\r\n\r\n    IF round(v_split_total, 2) > round(v_total, 2) THEN\r\n      RAISE EXCEPTION 'Purchase payment split total (%) exceeds the invoice total (%)',\r\n        round(v_split_total, 2), round(v_total, 2);\r\n    END IF;\r\n\r\n    IF v_split_count > 1 THEN\r\n      v_recorded_method := 'split';\r\n    END IF;\r\n  END IF;\r\n\r\n  SELECT balance, is_system INTO v_supplier_balance, v_system\r\n    FROM public.suppliers WHERE id = _supplier_id\r\n   FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Selected supplier is unavailable';\r\n  END IF;\r\n\r\n  -- مع التجزئة، المدفوع هو مجموع الأجزاء نفسها، لا رقم يخمّنه العميل.\r\n  v_paid := CASE\r\n              WHEN v_split_count > 0 THEN round(v_split_total, 2)\r\n              ELSE least(coalesce(_paid, 0), v_total)\r\n            END;\r\n\r\n  IF v_paid < 0 OR v_paid > v_total THEN\r\n    RAISE EXCEPTION 'Paid amount (%) must be between zero and the invoice total (%)', v_paid, v_total;\r\n  END IF;\r\n\r\n  IF v_paid < v_total AND v_system THEN\r\n    RAISE EXCEPTION\r\n      'The system cash supplier cannot carry a payable balance — record a paid purchase or choose a real supplier'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n\r\n  v_invoice_no := public.next_purchase_number();\r\n\r\n  INSERT INTO public.purchase_invoices (\r\n    invoice_number, supplier_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  )\r\n  VALUES (\r\n    v_invoice_no, _supplier_id, _warehouse_id,\r\n    'confirmed'::public.invoice_status,\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, coalesce(_discount, 0), v_tax_total, v_total, v_paid,\r\n    v_recorded_method::public.payment_method, nullif(btrim(_note), ''), v_user\r\n  )\r\n  RETURNING id INTO v_invoice_id;\r\n\r\n  --------------------------------------------------------------------- post\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(_items) LOOP\r\n    v_product  := (v_item ->> 'product_id')::uuid;\r\n    v_qty      := (v_item ->> 'quantity')::numeric;\r\n    v_cost     := (v_item ->> 'unit_cost')::numeric;\r\n    v_tax_rate := coalesce((v_item ->> 'tax_rate')::numeric, 0);\r\n\r\n    v_line_total := v_qty * v_cost;\r\n    v_line_tax   := v_line_total * v_tax_rate / 100;\r\n\r\n    SELECT r.o_line_type, r.o_stock_effect\r\n      INTO v_type, v_effect\r\n    FROM public.resolve_purchase_line(v_item) AS r;\r\n\r\n    INSERT INTO public.purchase_invoice_items (\r\n      invoice_id, product_id, quantity, unit_cost, discount, tax, total,\r\n      line_type, stock_effect\r\n    )\r\n    VALUES (\r\n      v_invoice_id, v_product, v_qty, v_cost, 0, v_line_tax, v_line_total + v_line_tax,\r\n      v_type, v_effect\r\n    );\r\n\r\n    IF v_effect = 'STOCK_RECEIPT' AND v_product IS NOT NULL THEN\r\n      PERFORM public.post_stock_delta(\r\n        v_product,\r\n        _warehouse_id,\r\n        v_qty,\r\n        v_cost,\r\n        'RECEIPT'::public.stock_movement_kind,\r\n        'purchase_invoice',\r\n        v_invoice_id,\r\n        'Purchase receipt',\r\n        'COMPANY'::public.owner_type,\r\n        NULL,\r\n        'purchase'::public.movement_type\r\n      );\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- سجلات التجزئة — الحارس المؤجل يتحقق من مطابقة المدفوع عند الالتزام.\r\n  IF v_split_count > 0 THEN\r\n    FOR v_split IN\r\n      SELECT part ->> 'method' AS method,\n             coalesce((part ->> 'amount')::numeric, 0) AS amount,\n             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference,\n             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,\n             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,\n             nullif(part ->> 'payment_method_id', '') AS payment_method_id\n        FROM jsonb_array_elements(_payment_splits) AS part\r\n    LOOP\r\n      INSERT INTO public.payment_splits (\r\n        document_type, document_id, method, amount, reference, created_by,\n        cashbox_id, bank_account_id, payment_method_id\n      )\r\n      VALUES (\r\n        'purchase_invoice', v_invoice_id,\r\n        v_split.method::public.payment_method,\r\n        round(v_split.amount, 2), v_split.reference, v_user,\n        v_split.cashbox_id, v_split.bank_account_id,\n        coalesce(v_split.payment_method_id, v_split.method)\n      );\r\n    END LOOP;\r\n  END IF;\r\n\r\n  IF v_paid < v_total THEN\r\n    UPDATE public.suppliers\r\n    SET balance = balance + (v_total - v_paid), updated_at = now()\r\n    WHERE id = _supplier_id;\r\n  END IF;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'purchase.posted', 'purchase_invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_no,\r\n      'supplier_id', _supplier_id,\r\n      'warehouse_id', _warehouse_id,\r\n      'total', v_total,\r\n      'paid', v_paid,\r\n      'line_count', jsonb_array_length(_items),\r\n      'has_splits', v_split_count > 0,\r\n      'split_count', v_split_count\r\n    ));\r\n\r\n  PERFORM set_config('app.payment_split_internal_post', 'on', true);\n  PERFORM public.post_purchase_invoice(v_invoice_id);\n  PERFORM set_config('app.payment_split_internal_post', 'off', true);\n\r\n  RETURN v_invoice_id;\r\nEND $function$","REVOKE ALL ON FUNCTION public.create_purchase(uuid, uuid, text, numeric, numeric, text, jsonb, jsonb)\n  FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.create_purchase(uuid, uuid, text, numeric, numeric, text, jsonb, jsonb)\n  TO authenticated, service_role","-- ── 5. النسخ القديمة تمرّر تجزئة فارغة (توافق عكسي كامل) ────────────────────\r\n-- PostgREST resolves an RPC by the JSON keys it receives, so the wrapper that\r\n-- declares `_cashbox_id … _payment_method_id` also catches every call made with\r\n-- any subset of those four keys.\r\n\r\nCREATE OR REPLACE FUNCTION public.create_purchase(\r\n  _warehouse_id uuid,\r\n  _supplier_id uuid,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _discount numeric,\r\n  _note text,\r\n  _items jsonb,\r\n  _cashbox_id uuid DEFAULT NULL,\r\n  _bank_account_id uuid DEFAULT NULL,\r\n  _payment_reference text DEFAULT NULL,\r\n  _payment_method_id text DEFAULT NULL\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\n  v_invoice_id uuid;\n  v_resolved_cashbox uuid := _cashbox_id;\n  v_split_method text;\n  v_payment_splits jsonb := '[]'::jsonb;\nBEGIN\n  -- نفس سلوك النسخة السابقة: الصندوق الافتراضي للدفع النقدي عند غيابه.\r\n  IF _payment_method = 'cash' AND v_resolved_cashbox IS NULL THEN\r\n    SELECT id INTO v_resolved_cashbox\r\n      FROM public.cashboxes\r\n     WHERE is_active = true AND is_default = true\r\n     LIMIT 1;\r\n    IF v_resolved_cashbox IS NULL THEN\r\n      SELECT id INTO v_resolved_cashbox FROM public.cashboxes\r\n       WHERE is_active = true ORDER BY created_at ASC LIMIT 1;\r\n    END IF;\r\n  END IF;\n\n  IF coalesce(_paid, 0) > 0 AND _payment_method <> 'credit' THEN\n    v_split_method := public.resolve_writable_payment_method(\n      coalesce(_payment_method_id, _payment_method), 'purchases', true\n    );\n    IF v_split_method IS DISTINCT FROM _payment_method THEN\n      RAISE EXCEPTION 'Payment method id does not match purchase method %', _payment_method;\n    END IF;\n    v_payment_splits := jsonb_build_array(jsonb_build_object(\n      'method', v_split_method,\n      'amount', round(_paid, 2),\n      'payment_method_id', coalesce(_payment_method_id, _payment_method),\n      'cashbox_id', v_resolved_cashbox,\n      'bank_account_id', _bank_account_id,\n      'reference', _payment_reference\n    ));\n  END IF;\n\n  v_invoice_id := public.create_purchase(\n    _warehouse_id, _supplier_id, _payment_method, _paid, _discount, _note, _items,\n    v_payment_splits\n  );\n\r\n  UPDATE public.purchase_invoices\r\n     SET cashbox_id = v_resolved_cashbox,\r\n         bank_account_id = _bank_account_id,\r\n         payment_reference = nullif(btrim(_payment_reference), ''),\r\n         payment_method_id = _payment_method_id\r\n   WHERE id = v_invoice_id;\r\n\r\n  RETURN v_invoice_id;\r\nEND $function$","CREATE OR REPLACE FUNCTION public.create_purchase(\r\n  _warehouse_id uuid,\r\n  _supplier_id uuid,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _discount numeric,\r\n  _note text,\r\n  _items jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE sql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\n  SELECT public.create_purchase(\r\n    _warehouse_id, _supplier_id, _payment_method, _paid, _discount, _note, _items,\r\n    '[]'::jsonb\r\n  );\r\n$function$","-- ── 6. استلام الطحن: تجزئة الدفع للسند ──────────────────────\r\n\r\nCREATE OR REPLACE FUNCTION public.create_milling_service_document_multi(\r\n  _customer_id uuid,\r\n  _warehouse_id uuid,\r\n  _grains jsonb,\r\n  _service_item_id uuid,\r\n  _service_unit_price numeric,\r\n  _discount numeric,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _notes text,\r\n  _payment_splits jsonb\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_document_id uuid;\r\n  v_document_number text;\r\n  v_invoice_id uuid;\r\n  v_invoice_number text;\r\n  v_subtotal numeric;\r\n  v_total numeric;\r\n  v_paid numeric;\r\n  v_outstanding numeric;\r\n  v_customer_balance numeric;\r\n  v_credit_limit numeric;\r\n  v_is_system boolean := false;\r\n  v_split record;\r\n  v_split_total numeric := 0;\r\n  v_split_count integer := 0;\r\n  v_recorded_method text := coalesce(_payment_method, 'cash');\r\n  r record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to create milling service documents';\r\n  END IF;\r\n  IF _customer_id IS NULL OR _warehouse_id IS NULL OR _service_item_id IS NULL THEN\r\n    RAISE EXCEPTION 'Customer, warehouse and service are required';\r\n  END IF;\r\n  IF _grains IS NULL OR jsonb_typeof(_grains) <> 'array' OR jsonb_array_length(_grains) = 0 THEN\r\n    RAISE EXCEPTION 'At least one grain line is required';\r\n  END IF;\r\n  IF coalesce(_service_unit_price, 0) < 0 OR coalesce(_discount, 0) < 0\r\n     OR coalesce(_paid, 0) < 0 THEN\r\n    RAISE EXCEPTION 'Service price, discount and paid amount cannot be negative';\r\n  END IF;\r\n  IF _payment_method NOT IN ('cash', 'card', 'bank_transfer', 'credit', 'mobile_money', 'split') THEN\r\n    RAISE EXCEPTION 'Unsupported payment method';\r\n  END IF;\r\n\r\n  -- تجزئة الدفع: طرق تحصيل فقط، بمبالغ موجبة\r\n  IF coalesce(jsonb_typeof(_payment_splits), '') = 'array'\r\n     AND jsonb_array_length(_payment_splits) > 0 THEN\r\n    FOR v_split IN\r\n      SELECT part ->> 'method' AS method,\n             coalesce((part ->> 'amount')::numeric, 0) AS amount,\n             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,\n             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,\n             nullif(part ->> 'payment_method_id', '') AS payment_method_id,\n             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference\n        FROM jsonb_array_elements(_payment_splits) AS part\r\n    LOOP\r\n      IF v_split.method IS NULL\n         OR v_split.method NOT IN ('cash', 'card', 'bank_transfer', 'mobile_money', 'cheque') THEN\n        RAISE EXCEPTION 'Unsupported milling split method: %', v_split.method;\n      END IF;\n      IF public.resolve_writable_payment_method(\n           coalesce(v_split.payment_method_id, v_split.method), 'pos', true\n         ) IS DISTINCT FROM v_split.method THEN\n        RAISE EXCEPTION 'Payment method id does not match milling tender %', v_split.method;\n      END IF;\n      IF v_split.amount <= 0 THEN\r\n        RAISE EXCEPTION 'Every milling payment tender requires a positive amount';\r\n      END IF;\r\n      v_split_total := v_split_total + v_split.amount;\r\n      v_split_count := v_split_count + 1;\r\n    END LOOP;\r\n    IF v_split_count > 1 THEN\r\n      v_recorded_method := 'split';\r\n    END IF;\r\n  END IF;\r\n\r\n  -- تحقق أسطر الحبوب: منتج أمانات + كمية موجبة\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_grains) AS g(item_id uuid, bags numeric, kg numeric)\r\n  LOOP\r\n    IF r.item_id IS NULL THEN\r\n      RAISE EXCEPTION 'Every grain line needs an item';\r\n    END IF;\r\n    IF coalesce(r.bags, 0) < 0 OR coalesce(r.kg, 0) < 0 THEN\r\n      RAISE EXCEPTION 'Grain quantities cannot be negative';\r\n    END IF;\r\n    IF coalesce(r.bags, 0) = 0 AND coalesce(r.kg, 0) = 0 THEN\r\n      RAISE EXCEPTION 'Every grain line needs a positive quantity';\r\n    END IF;\r\n  END LOOP;\r\n\r\n  SELECT balance, credit_limit, is_system\r\n    INTO v_customer_balance, v_credit_limit, v_is_system\r\n    FROM public.customers\r\n   WHERE id = _customer_id AND is_active = true\r\n   FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Selected customer is unavailable';\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = _warehouse_id AND is_active) THEN\r\n    RAISE EXCEPTION 'Selected warehouse is unavailable';\r\n  END IF;\r\n\r\n  v_subtotal := round(coalesce(_service_unit_price, 0), 2);\r\n  v_total := round(v_subtotal - coalesce(_discount, 0), 2);\r\n  IF v_total < 0 THEN\r\n    RAISE EXCEPTION 'Discount cannot exceed the service fee';\r\n  END IF;\r\n\r\n  IF v_split_count > 0 THEN\r\n    IF round(v_split_total, 2) > v_total THEN\r\n      RAISE EXCEPTION 'Milling payment split total (%) exceeds the fee total (%)',\r\n        round(v_split_total, 2), v_total;\r\n    END IF;\r\n    v_paid := round(v_split_total, 2);\r\n  ELSE\r\n    v_paid := least(round(coalesce(_paid, 0), 2), v_total);\r\n  END IF;\r\n\r\n  v_outstanding := round(v_total - v_paid, 2);\r\n  IF _payment_method = 'credit' AND v_split_count = 0 AND v_paid <> 0 THEN\r\n    RAISE EXCEPTION 'Credit payment method requires zero paid amount';\r\n  END IF;\r\n  IF v_outstanding > 0 AND v_is_system THEN\r\n    RAISE EXCEPTION\r\n      'The system cash customer cannot carry credit — select a real customer for a deferred ticket'\r\n      USING ERRCODE = 'check_violation';\r\n  END IF;\r\n  IF v_outstanding > 0 AND NOT public.customer_credit_limit_allows(_customer_id, v_outstanding) THEN\r\n    RAISE EXCEPTION\r\n      'Credit limit exceeded: current balance %, requested debt %, limit %',\r\n      coalesce(v_customer_balance, 0), v_outstanding, coalesce(v_credit_limit, 0);\r\n  END IF;\r\n\r\n  v_invoice_number := public.next_invoice_number();\r\n  INSERT INTO public.sales_invoices (\r\n    invoice_number, customer_id, warehouse_id, status, payment_status,\r\n    subtotal, discount, tax, total, paid, payment_method, note, created_by\r\n  ) VALUES (\r\n    v_invoice_number, _customer_id, _warehouse_id, 'confirmed',\r\n    public.derive_payment_status(v_paid, v_total),\r\n    v_subtotal, round(coalesce(_discount, 0), 2), 0, v_total, v_paid,\r\n    v_recorded_method::public.payment_method, nullif(btrim(_notes), ''), v_user\r\n  ) RETURNING id INTO v_invoice_id;\r\n\r\n  INSERT INTO public.sales_invoice_items (\r\n    invoice_id, product_id, description, quantity, unit_price, discount, tax, total,\r\n    line_type, stock_effect\r\n  ) VALUES (\r\n    v_invoice_id, _service_item_id, 'أجور طحن وتجهيز', 1, v_subtotal,\r\n    0, 0, v_subtotal, 'SERVICE', 'NONE'\r\n  );\r\n\r\n  IF v_outstanding > 0 THEN\r\n    UPDATE public.customers\r\n    SET balance = round(coalesce(balance, 0) + v_outstanding, 2), updated_at = now()\r\n    WHERE id = _customer_id;\r\n\r\n    INSERT INTO public.customer_ledger (\r\n      customer_id, entry_type, debit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    ) VALUES (\r\n      _customer_id, 'sale', v_outstanding, v_invoice_id, 'sales_invoice',\r\n      now(), v_user, 'sale:' || v_invoice_id, 'قيد أجور طحن آجل'\r\n    ) ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  v_document_number := 'MT-' || to_char(now(), 'YYYYMM') || '-' ||\r\n    lpad(nextval('public.milling_document_seq')::text, 4, '0');\r\n  INSERT INTO public.milling_service_documents (\r\n    document_number, customer_id, warehouse_id, sales_invoice_id, created_by\r\n  ) VALUES (\r\n    v_document_number, _customer_id, _warehouse_id, v_invoice_id, v_user\r\n  ) RETURNING id INTO v_document_id;\r\n\r\n  -- أجزاء الدفع تُسجّل قبل الترحيل ليقرأها post_sales_invoice ويوزّعها على الحسابات.\r\n  IF v_split_count > 0 THEN\r\n    FOR v_split IN\n      SELECT part ->> 'method' AS method,\n             coalesce((part ->> 'amount')::numeric, 0) AS amount,\n             nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,\n             nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,\n             nullif(part ->> 'payment_method_id', '') AS payment_method_id,\n             nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference\n        FROM jsonb_array_elements(_payment_splits) AS part\n    LOOP\r\n      INSERT INTO public.payment_splits (\r\n        document_type, document_id, method, amount, reference, created_by,\n        cashbox_id, bank_account_id, payment_method_id\n      ) VALUES (\n        'milling_service_document', v_document_id,\n        v_split.method::public.payment_method, round(v_split.amount, 2),\n        v_split.reference, v_user, v_split.cashbox_id, v_split.bank_account_id,\n        coalesce(v_split.payment_method_id, v_split.method)\n      );\n      INSERT INTO public.customer_payment_splits (\n        customer_id, invoice_id, method, amount, occurred_at, created_by,\n        cashbox_id, bank_account_id, payment_method_id, reference_no\n      ) VALUES (\n        _customer_id, v_invoice_id, v_split.method::public.payment_method,\n        round(v_split.amount, 2), now(), v_user, v_split.cashbox_id,\n        v_split.bank_account_id, coalesce(v_split.payment_method_id, v_split.method),\n        v_split.reference\n      );\n    END LOOP;\r\n  END IF;\r\n\r\n  PERFORM set_config('app.payment_split_internal_post', 'on', true);\n  PERFORM public.post_sales_invoice(v_invoice_id);\n  PERFORM set_config('app.payment_split_internal_post', 'off', true);\n\r\n  FOR r IN SELECT * FROM jsonb_to_recordset(_grains) AS g(item_id uuid, bags numeric, kg numeric)\r\n  LOOP\r\n    INSERT INTO public.custody_ledger (\r\n      customer_id, warehouse_id, entry_type, item_id, doc_number,\r\n      bags_in, kg_in, milling_document_id, notes, created_by\r\n    ) VALUES (\r\n      _customer_id, _warehouse_id, 'INTAKE', r.item_id, v_document_number,\r\n      coalesce(r.bags, 0), coalesce(r.kg, 0), v_document_id, _notes, v_user\r\n    );\r\n  END LOOP;\r\n\r\n  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, payload)\r\n  VALUES (v_user, 'milling.service_document.created', 'milling_service_documents', v_document_id,\r\n    jsonb_build_object(\r\n      'document_number', v_document_number,\r\n      'invoice_id', v_invoice_id,\r\n      'grains', _grains,\r\n      'service_total', v_total,\r\n      'paid', v_paid,\r\n      'outstanding', v_outstanding,\r\n      'has_splits', v_split_count > 0,\r\n      'split_count', v_split_count,\r\n      'stock_impact', 'NONE — customer custody'\r\n    ));\r\n\r\n  RETURN jsonb_build_object(\r\n    'document_id', v_document_id,\r\n    'document_number', v_document_number,\r\n    'invoice_id', v_invoice_id,\r\n    'invoice_number', v_invoice_number\r\n  );\r\nEND $function$","REVOKE ALL ON FUNCTION public.create_milling_service_document_multi(uuid, uuid, jsonb, uuid, numeric, numeric, text, numeric, text, jsonb)\n  FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.create_milling_service_document_multi(uuid, uuid, jsonb, uuid, numeric, numeric, text, numeric, text, jsonb)\n  TO authenticated, service_role","-- النسخة التسعيّة القديمة تمرّر مصفوفة فارغة.\r\nCREATE OR REPLACE FUNCTION public.create_milling_service_document_multi(\r\n  _customer_id uuid,\r\n  _warehouse_id uuid,\r\n  _grains jsonb,\r\n  _service_item_id uuid,\r\n  _service_unit_price numeric,\r\n  _discount numeric,\r\n  _payment_method text,\r\n  _paid numeric,\r\n  _notes text\r\n)\r\nRETURNS jsonb\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path TO 'public'\r\nAS $function$\r\nBEGIN\r\n  RETURN public.create_milling_service_document_multi(\r\n    _customer_id, _warehouse_id, _grains, _service_item_id, _service_unit_price,\r\n    _discount, _payment_method, _paid, _notes, '[]'::jsonb\r\n  );\r\nEND $function$","-- ── 7. تحصيل ذم العملاء على أكثر من طريقة ─────────────────────────────\r\n-- The collection screen may take one debt in several tenders. Each tender is a\r\n-- real `customer_payments` row (so it appears in the customer ledger and in\r\n-- every treasury report exactly once), and the journal debits each tender's own\r\n-- account instead of a single settlement account.\r\n--\r\n-- The wrapper below also owns the treasury columns (`cashbox_id`,\r\n-- `bank_account_id`, `payment_method_id`, cheque fields) for every call, so the\r\n-- 12-argument overload from migration 32 — which no longer has a body of its own\r\n-- — resolves here with and without those keys.\r\n\r\nCREATE OR REPLACE FUNCTION public.record_customer_payment_splits(\r\n  _customer_id uuid,\r\n  _invoice_id uuid,\r\n  _amount numeric,\r\n  _payment_date date,\r\n  _note text,\r\n  _splits jsonb\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_total numeric := 0;\r\n  v_split_total numeric := 0;\r\n  v_split_count integer := 0;\r\n  v_method_id text;\r\n  v_stored_method text;\r\n  v_account text;\r\n  v_amount numeric;\r\n  v_payment_id uuid;\r\n  v_last_id uuid;\r\n  v_remaining numeric;\n  v_customer_outstanding numeric := 0;\n  v_invoice record;\n  v_inv_cur record;\r\n  v_allocation numeric;\r\n  v_tender_lines jsonb;\n  r_split record;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'accountant')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to record customer payments';\r\n  END IF;\r\n\r\n  IF _customer_id IS NULL THEN\r\n    RAISE EXCEPTION 'A customer is required';\r\n  END IF;\r\n\r\n  -- ── التحقق من الأجزاء ──\r\n  IF coalesce(jsonb_typeof(_splits), '') <> 'array'\r\n     OR jsonb_array_length(_splits) < 2 THEN\r\n    RAISE EXCEPTION 'A split collection requires at least two tenders';\r\n  END IF;\r\n\r\n  FOR r_split IN\r\n    SELECT part ->> 'methodId' AS method_id,\n           part ->> 'method' AS method,\n           coalesce((part ->> 'amount')::numeric, 0) AS amount,\n           nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference,\n           nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,\n           nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,\n           nullif(part ->> 'payment_method_id', '') AS payment_method_id\n      FROM jsonb_array_elements(_splits) AS part\r\n  LOOP\r\n    IF r_split.amount <= 0 THEN\r\n      RAISE EXCEPTION 'Every collection tender requires a positive amount';\r\n    END IF;\r\n\r\n    -- الآجل ليس تحصيلاً: يُرفض هنا لأن التحصيل لا يُنشئ ديناً جديداً.\r\n    v_method_id := coalesce(r_split.method_id, r_split.method);\r\n    v_stored_method := public.resolve_writable_payment_method(\r\n      v_method_id, 'customer_collection', true\r\n    );\r\n    IF v_stored_method = 'credit' THEN\r\n      RAISE EXCEPTION 'A collection cannot record آجل — that is a deferred sale, not a receipt';\r\n    END IF;\r\n\r\n    v_split_total := v_split_total + r_split.amount;\r\n    v_split_count := v_split_count + 1;\r\n  END LOOP;\r\n\r\n  v_total := round(v_split_total, 2);\r\n\r\n  IF _amount IS NOT NULL AND round(_amount, 2) <> v_total THEN\r\n    RAISE EXCEPTION 'Collection total (%) does not match the sum of its tenders (%)',\r\n      round(_amount, 2), v_total;\r\n  END IF;\r\n\r\n  -- ── التحقق من سقف الدين قبل أي إدراج ──\r\n  PERFORM 1 FROM public.customers\r\n   WHERE id = _customer_id AND is_active = true\r\n   FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Customer is unavailable';\r\n  END IF;\r\n\r\n  IF _invoice_id IS NOT NULL THEN\n    SELECT id, total, paid, customer_id INTO v_invoice\r\n      FROM public.sales_invoices WHERE id = _invoice_id FOR UPDATE;\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Invoice not found';\r\n    END IF;\r\n    IF v_invoice.customer_id IS DISTINCT FROM _customer_id THEN\r\n      RAISE EXCEPTION 'Invoice does not belong to this customer';\r\n    END IF;\r\n    IF v_invoice.total - v_invoice.paid <= 0 THEN\r\n      RAISE EXCEPTION 'Invoice has no outstanding balance';\r\n    END IF;\r\n    IF v_total > (v_invoice.total - v_invoice.paid + 0.01) THEN\n      RAISE EXCEPTION 'Payment exceeds the invoice outstanding balance';\n    END IF;\n  ELSE\n    SELECT round(coalesce(sum(total - paid), 0), 2)\n      INTO v_customer_outstanding\n      FROM public.sales_invoices\n     WHERE customer_id = _customer_id\n       AND total > paid\n       AND status NOT IN ('cancelled'::public.invoice_status, 'returned'::public.invoice_status);\n    IF v_total > v_customer_outstanding + 0.01 THEN\n      RAISE EXCEPTION 'Payment exceeds the customer outstanding balance';\n    END IF;\n  END IF;\n\r\n  -- ── إدراج صف لكل طريقة (يظهر في دفتر العميل والخزينة مرة واحدة) ──\r\n  v_remaining := v_total;\r\n\r\n  FOR r_split IN\n    SELECT part ->> 'methodId' AS method_id,\n           part ->> 'method' AS method,\n           coalesce((part ->> 'amount')::numeric, 0) AS amount,\n           nullif(btrim(coalesce(part ->> 'reference', '')), '') AS reference,\n           nullif(part ->> 'cashbox_id', '')::uuid AS cashbox_id,\n           nullif(part ->> 'bank_account_id', '')::uuid AS bank_account_id,\n           nullif(part ->> 'payment_method_id', '') AS payment_method_id\n      FROM jsonb_array_elements(_splits) AS part\r\n  LOOP\r\n    v_method_id := coalesce(r_split.method_id, r_split.method);\r\n    v_stored_method := public.resolve_writable_payment_method(\r\n      v_method_id, 'customer_collection', true\r\n    );\r\n    v_account := public.resolve_document_settlement_account(\n      v_stored_method, r_split.cashbox_id, r_split.bank_account_id, v_method_id\n    );\n    IF v_account IS NULL THEN\n      RAISE EXCEPTION 'No ledger account could be resolved for collection tender %', v_method_id;\n    END IF;\n    v_amount := round(r_split.amount, 2);\r\n\r\n    INSERT INTO public.customer_payments (\r\n      customer_id, invoice_id, amount, payment_method, payment_date, note, created_by,\r\n      payment_method_id, payment_reference, cashbox_id, bank_account_id\n    )\r\n    VALUES (\r\n      _customer_id, _invoice_id, v_amount, v_stored_method::public.payment_method,\r\n      coalesce(_payment_date, current_date),\r\n      nullif(trim(concat_ws(' — ', _note, r_split.reference)), ''),\r\n      v_user, v_method_id, r_split.reference, r_split.cashbox_id, r_split.bank_account_id\n    )\r\n    RETURNING id INTO v_payment_id;\r\n\r\n    v_last_id := v_payment_id;\r\n\r\n    INSERT INTO public.customer_ledger(\r\n      customer_id, entry_type, credit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      _customer_id, 'payment', v_amount, v_payment_id, 'customer_payment',\r\n      coalesce(_payment_date, current_date)::timestamptz, v_user,\r\n      'payment:' || v_payment_id,\r\n      coalesce(nullif(trim(_note), ''), 'دفعة عميل (دفع مجزأ)')\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n\r\n    v_tender_lines := jsonb_build_array(\n      jsonb_build_object(\n        'account_code', v_account, 'debit', v_amount,\n        'memo', 'تحصيل من عميل (دفع مجزأ) — ' || v_stored_method),\n      jsonb_build_object(\n        'account_code', '1211', 'credit', v_amount,\n        'memo', 'تحصيل ذمة عميل')\n    );\n    PERFORM public.create_journal_entry(\n      'تحصيل من عميل — ' || coalesce(nullif(trim(_note), ''), ''),\n      coalesce(_payment_date, current_date),\n      'customer_payment', v_payment_id, true, v_tender_lines);\n\r\n    -- تخصيص لفاتورة محددة\r\n    IF _invoice_id IS NOT NULL THEN\r\n      UPDATE public.sales_invoices\r\n      SET paid = paid + v_amount,\r\n          status = 'confirmed'::public.invoice_status,\r\n          payment_status = public.derive_payment_status(paid + v_amount, total),\r\n          updated_at = now()\r\n      WHERE id = _invoice_id;\r\n    END IF;\r\n  END LOOP;\r\n\r\n  -- توزيع تلقائي على الأقدم أولاً عندما لا تُحدد فاتورة\r\n  IF _invoice_id IS NULL THEN\r\n    FOR v_inv_cur IN\r\n      SELECT id, total, paid\r\n      FROM public.sales_invoices\r\n      WHERE customer_id = _customer_id\r\n        AND total > paid\r\n        AND status NOT IN ('cancelled'::public.invoice_status, 'returned'::public.invoice_status)\r\n      ORDER BY created_at ASC\r\n    LOOP\r\n      EXIT WHEN v_remaining <= 0;\r\n      v_allocation := least(v_remaining, v_inv_cur.total - v_inv_cur.paid);\r\n\r\n      UPDATE public.sales_invoices\r\n      SET paid = paid + v_allocation,\r\n          status = 'confirmed'::public.invoice_status,\r\n          payment_status = public.derive_payment_status(paid + v_allocation, total),\r\n          updated_at = now()\r\n      WHERE id = v_inv_cur.id;\r\n\r\n      v_remaining := v_remaining - v_allocation;\r\n    END LOOP;\r\n  END IF;\r\n\r\n  RETURN v_last_id;\nEND $function$","REVOKE ALL ON FUNCTION public.record_customer_payment_splits(uuid, uuid, numeric, date, text, jsonb)\n  FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.record_customer_payment_splits(uuid, uuid, numeric, date, text, jsonb)\n  TO authenticated, service_role","-- ── 8. تحصيل بطريقة واحدة: التوقيع الكامل (12 وسيطاً) يوجّه للتجزئة ────────\r\n-- This is the overload the collection screen calls for a single tender. It owns\r\n-- the treasury columns, so `record_customer_payment` exists exactly once and a\r\n-- call with or without `_cashbox_id … _cheque_drawer` lands here.\r\n\r\nCREATE OR REPLACE FUNCTION public.record_customer_payment(\r\n  _customer_id uuid,\r\n  _invoice_id uuid,\r\n  _amount numeric,\r\n  _method text,\r\n  _payment_date date,\r\n  _note text,\r\n  _cashbox_id uuid DEFAULT NULL,\r\n  _bank_account_id uuid DEFAULT NULL,\r\n  _payment_method_id text DEFAULT NULL,\r\n  _cheque_number text DEFAULT NULL,\r\n  _cheque_bank text DEFAULT NULL,\r\n  _cheque_due_date date DEFAULT NULL,\r\n  _cheque_drawer text DEFAULT NULL\r\n)\r\nRETURNS uuid\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $function$\r\nDECLARE\r\n  v_user uuid := auth.uid();\r\n  v_amount numeric := round(coalesce(_amount, 0), 2);\r\n  v_method_id text;\r\n  v_stored_method text;\r\n  v_account text;\r\n  v_payment_id uuid;\r\n  v_customer_balance numeric;\r\n  v_invoice record;\r\n  v_remaining numeric;\r\n  v_inv_cur record;\r\n  v_allocation numeric;\r\n  v_lines jsonb := '[]'::jsonb;\r\nBEGIN\r\n  IF v_user IS NULL THEN\r\n    RAISE EXCEPTION 'Not authenticated';\r\n  END IF;\r\n  IF NOT (\r\n    public.has_role(v_user, 'owner')\r\n    OR public.has_role(v_user, 'manager')\r\n    OR public.has_role(v_user, 'accountant')\r\n    OR public.has_role(v_user, 'cashier')\r\n  ) THEN\r\n    RAISE EXCEPTION 'You are not permitted to record customer payments';\r\n  END IF;\r\n  IF _customer_id IS NULL OR v_amount <= 0 THEN\r\n    RAISE EXCEPTION 'A customer and a positive amount are required';\r\n  END IF;\r\n\r\n  v_method_id := coalesce(_payment_method_id, _method);\r\n  v_stored_method := public.resolve_writable_payment_method(\r\n    v_method_id, 'customer_collection', true\r\n  );\r\n  IF v_stored_method = 'credit' THEN\r\n    RAISE EXCEPTION 'A collection cannot record آجل — that is a deferred sale, not a receipt';\r\n  END IF;\r\n\r\n  SELECT balance INTO v_customer_balance\r\n    FROM public.customers\r\n   WHERE id = _customer_id AND is_active = true\r\n   FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Customer is unavailable';\r\n  END IF;\r\n\r\n  v_account := public.resolve_document_settlement_account(\r\n    v_stored_method, _cashbox_id, _bank_account_id, v_method_id\r\n  );\r\n\r\n  ------------------------------------------------------------------ one invoice\r\n  IF _invoice_id IS NOT NULL THEN\r\n    SELECT id, total, paid, customer_id INTO v_invoice\r\n      FROM public.sales_invoices WHERE id = _invoice_id FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n      RAISE EXCEPTION 'Invoice not found';\r\n    END IF;\r\n    IF v_invoice.customer_id IS DISTINCT FROM _customer_id THEN\r\n      RAISE EXCEPTION 'Invoice does not belong to this customer';\r\n    END IF;\r\n    IF v_invoice.total - v_invoice.paid <= 0 THEN\r\n      RAISE EXCEPTION 'Invoice has no outstanding balance';\r\n    END IF;\r\n    IF v_amount > (v_invoice.total - v_invoice.paid + 0.01) THEN\r\n      RAISE EXCEPTION 'Payment exceeds the invoice outstanding balance';\r\n    END IF;\r\n\r\n    INSERT INTO public.customer_payments (\r\n      customer_id, invoice_id, amount, payment_method, payment_date, note, created_by,\r\n      cashbox_id, bank_account_id, payment_method_id, payment_reference\r\n    )\r\n    VALUES (\r\n      _customer_id, _invoice_id, v_amount, v_stored_method::public.payment_method,\r\n      coalesce(_payment_date, current_date), nullif(trim(_note), ''), v_user,\r\n      _cashbox_id, _bank_account_id, v_method_id, _cheque_number\r\n    )\r\n    RETURNING id INTO v_payment_id;\r\n\r\n    IF (v_stored_method = 'cheque' OR v_method_id = 'cheque') AND _cheque_number IS NOT NULL THEN\r\n      INSERT INTO public.cheques_register (\r\n        cheque_number, bank_name, drawer_name, due_date, amount, status,\r\n        customer_id, invoice_id, payment_id, notes, created_by\r\n      )\r\n      VALUES (\r\n        _cheque_number, coalesce(_cheque_bank, 'شيك مصرفي'), _cheque_drawer,\r\n        coalesce(_cheque_due_date, CURRENT_DATE), v_amount, 'UNDER_COLLECTION',\r\n        _customer_id, _invoice_id, v_payment_id, _note, v_user\r\n      );\r\n    END IF;\r\n\r\n    INSERT INTO public.customer_ledger(\r\n      customer_id, entry_type, credit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      _customer_id, 'payment', v_amount, v_payment_id, 'customer_payment',\r\n      coalesce(_payment_date, current_date)::timestamptz, v_user,\r\n      'payment:' || v_payment_id,\r\n      coalesce(nullif(trim(_note), ''), 'دفعة عميل')\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n\r\n    UPDATE public.sales_invoices\r\n    SET paid = paid + v_amount,\r\n        status = 'confirmed'::public.invoice_status,\r\n        payment_status = public.derive_payment_status(paid + v_amount, total),\r\n        updated_at = now()\r\n    WHERE id = _invoice_id;\r\n\r\n  ----------------------------------------------------------------- auto allocation\r\n  ELSE\r\n    INSERT INTO public.customer_payments (\r\n      customer_id, invoice_id, amount, payment_method, payment_date, note, created_by,\r\n      cashbox_id, bank_account_id, payment_method_id, payment_reference\r\n    )\r\n    VALUES (\r\n      _customer_id, NULL, v_amount, v_stored_method::public.payment_method,\r\n      coalesce(_payment_date, current_date), nullif(trim(_note), ''), v_user,\r\n      _cashbox_id, _bank_account_id, v_method_id, _cheque_number\r\n    )\r\n    RETURNING id INTO v_payment_id;\r\n\r\n    IF (v_stored_method = 'cheque' OR v_method_id = 'cheque') AND _cheque_number IS NOT NULL THEN\r\n      INSERT INTO public.cheques_register (\r\n        cheque_number, bank_name, drawer_name, due_date, amount, status,\r\n        customer_id, invoice_id, payment_id, notes, created_by\r\n      )\r\n      VALUES (\r\n        _cheque_number, coalesce(_cheque_bank, 'شيك مصرفي'), _cheque_drawer,\r\n        coalesce(_cheque_due_date, CURRENT_DATE), v_amount, 'UNDER_COLLECTION',\r\n        _customer_id, NULL, v_payment_id, _note, v_user\r\n      );\r\n    END IF;\r\n\r\n    v_remaining := v_amount;\r\n\r\n    FOR v_inv_cur IN\r\n      SELECT id, total, paid\r\n      FROM public.sales_invoices\r\n      WHERE customer_id = _customer_id\r\n        AND total > paid\r\n        AND status NOT IN ('cancelled'::public.invoice_status, 'returned'::public.invoice_status)\r\n      ORDER BY created_at ASC\r\n    LOOP\r\n      EXIT WHEN v_remaining <= 0;\r\n      v_allocation := least(v_remaining, v_inv_cur.total - v_inv_cur.paid);\r\n\r\n      UPDATE public.sales_invoices\r\n      SET paid = paid + v_allocation,\r\n          status = 'confirmed'::public.invoice_status,\r\n          payment_status = public.derive_payment_status(paid + v_allocation, total),\r\n          updated_at = now()\r\n      WHERE id = v_inv_cur.id;\r\n\r\n      v_remaining := v_remaining - v_allocation;\r\n    END LOOP;\r\n\r\n    INSERT INTO public.customer_ledger(\r\n      customer_id, entry_type, credit, reference_id, reference_type,\r\n      occurred_at, created_by, source_key, note\r\n    )\r\n    VALUES (\r\n      _customer_id, 'payment', v_amount, v_payment_id, 'customer_payment',\r\n      coalesce(_payment_date, current_date)::timestamptz, v_user,\r\n      'payment:' || v_payment_id,\r\n      coalesce(nullif(trim(_note), ''), 'دفعة عميل بتوزيع تلقائي')\r\n    )\r\n    ON CONFLICT (source_key) DO NOTHING;\r\n  END IF;\r\n\r\n  IF v_account IS NOT NULL THEN\r\n    v_lines := v_lines\r\n      || jsonb_build_object(\r\n           'account_code', v_account, 'debit', v_amount,\r\n           'memo', CASE WHEN v_account = '1221'\r\n                        THEN 'أوراق قبض (شيك برسم التحصيل)'\r\n                        ELSE 'تحصيل من عميل' END)\r\n      || jsonb_build_object(\r\n           'account_code', '1211', 'credit', v_amount,\r\n           'memo', 'تحصيل ذمة عميل');\r\n\r\n    PERFORM public.create_journal_entry(\r\n      'تحصيل من عميل — ' || coalesce(nullif(trim(_note), ''), ''),\r\n      coalesce(_payment_date, current_date),\r\n      'customer_payment', v_payment_id, true, v_lines);\r\n  END IF;\r\n\r\n  RETURN v_payment_id;\r\nEND $function$","GRANT EXECUTE ON FUNCTION public.record_customer_payment(\r\n  uuid, uuid, numeric, text, date, text, uuid, uuid, text, text, text, date, text\r\n) TO authenticated, service_role","-- النسخة القديمة بستة وسائط تحوّل إلى التوقيع الكامل.\r\nCREATE OR REPLACE FUNCTION public.record_customer_payment(\r\n  _customer_id uuid,\r\n  _invoice_id uuid,\r\n  _amount numeric,\r\n  _method text,\r\n  _payment_date date,\r\n  _note text\r\n)\r\nRETURNS uuid\r\nLANGUAGE sql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $function$\n  SELECT public.record_customer_payment(\n    _customer_id, _invoice_id, _amount, _method, _payment_date, _note,\n    NULL, NULL, NULL, NULL, NULL, NULL, NULL\n  );\n$function$","-- ── 9. الوصول لجدول التجزئة ─────────────────\r\n\r\nALTER TABLE public.payment_splits ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS payment_splits_read ON public.payment_splits","CREATE POLICY payment_splits_read ON public.payment_splits\n  FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'manager') OR\n         public.has_role(auth.uid(),'accountant') OR public.has_role(auth.uid(),'cashier'))","DROP POLICY IF EXISTS payment_splits_insert ON public.payment_splits","CREATE POLICY payment_splits_insert ON public.payment_splits\n  FOR INSERT TO authenticated WITH CHECK (false)","DROP POLICY IF EXISTS payment_splits_update ON public.payment_splits","DROP POLICY IF EXISTS payment_splits_delete ON public.payment_splits","REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.payment_splits FROM PUBLIC, anon, authenticated","GRANT SELECT ON public.payment_splits TO authenticated","GRANT ALL ON public.payment_splits TO service_role","-- Split tender rows are accounting evidence; only the guarded RPCs may write them.\nREVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.customer_payment_splits\n  FROM PUBLIC, anon, authenticated","GRANT SELECT ON public.customer_payment_splits TO authenticated","GRANT ALL ON public.customer_payment_splits TO service_role",COMMIT,"-- Rollback: restore the prior create_purchase/post_purchase_invoice and\n-- milling/collection RPC definitions from migrations 32/43/60, then archive\n-- or export payment_splits before dropping that table and its policies."}	split_purchases_and_milling
66	{"-- Add the payment split entry points to the existing RPC contract.\n-- Keep the established allow-list intact and append only the new public RPCs.\nBEGIN","CREATE OR REPLACE FUNCTION public.rpc_allowlist()\nRETURNS text[]\nLANGUAGE sql\nIMMUTABLE\nSET search_path = public\nAS $$\n  SELECT ARRAY[\n    'create_sale', 'create_sales_return', 'create_purchase', 'create_purchase_return',\n    'create_stock_transfer', 'post_sales_invoice', 'post_purchase_invoice',\n    'post_stock_delta', 'post_stock_settlement', 'post_stock_adjustment', 'post_opening_stock',\n    'receive_customer_owned_stock', 'release_customer_owned_stock', 'create_opening_balance',\n    'post_opening_balance', 'reverse_opening_balance', 'search_products', 'item_line_type',\n    'item_stock_effect', 'item_effective_policy', 'item_has_stock_history', 'resolve_unit_cost',\n    'product_reference_counts', 'warehouse_reference_counts', 'save_item_policy',\n    'approve_item_policy_change', 'clear_cheque', 'bounce_cheque',\n    'reconcile_batches_with_inventory', 'save_product_batch', 'get_batch_kpis',\n    'delete_product_batch', 'save_batch_settings', 'record_customer_payment',\n    'record_customer_payment_splits', 'record_supplier_payment', 'get_supplier_statement',\n    'adjust_loyalty', 'customer_credit_limit_allows', 'custody_intake', 'custody_milling',\n    'custody_deliver', 'custody_adjust', 'custody_balances', 'custody_link_invoice',\n    'create_milling_service_document', 'create_milling_service_document_multi',\n    'smart_manufacture', 'consume_internal_supplies', 'milling_custody_intake',\n    'milling_custody_issue_milling', 'milling_custody_deliver', 'milling_custody_adjust',\n    'create_journal_entry', 'reverse_journal_entry', 'get_chart_of_accounts_tree',\n    'activate_fixed_asset', 'dispose_fixed_asset', 'run_depreciation',\n    'run_batch_depreciation', 'run_contract_amortization', 'run_batch_amortization',\n    'close_fiscal_year', 'open_fiscal_year', 'set_period_status', 'generate_tax_declaration',\n    'settle_tax_period', 'pay_tax_settlement', 'create_expense', 'update_expense',\n    'submit_expense', 'decide_expense', 'post_expense', 'close_expense', 'cancel_expense',\n    'reverse_expense', 'record_expense_payment', 'reverse_expense_payment', 'list_expenses',\n    'expense_detail', 'expense_summary', 'expense_report', 'expense_lookups',\n    'save_expense_category', 'delete_expense_category', 'create_tenant_payment_method',\n    'update_payment_method_identity', 'remove_tenant_payment_method', 'is_system_customer',\n    'is_system_supplier', 'fn_format_document_number', 'fn_resolve_document_numbering',\n    'fn_set_document_numbering', 'fn_document_numbering_sequence_name', 'backup_export_all',\n    'backup_restore_all', 'backup_schema_fingerprint', 'has_role', 'is_staff',\n    'is_platform_admin', 'is_platform_superadmin', 'can_read_finance',\n    'can_read_expense_entry', 'can_author_payment_methods', 'can_operate_milling',\n    'can_view_milling', 'platform_admin_audit_self'\n  ];\n$$","REVOKE ALL ON FUNCTION public.rpc_allowlist() FROM PUBLIC, anon, authenticated, service_role","GRANT EXECUTE ON FUNCTION public.record_customer_payment_splits(uuid, uuid, numeric, date, text, jsonb)\n  TO authenticated, service_role","COMMENT ON FUNCTION public.rpc_allowlist() IS\n  'عقد RPC الواجهة، متضمّنًا نقطتي الدفع المجزأ للتحصيل والطحن.'",COMMIT,"-- Rollback: restore rpc_allowlist() from migration 45 and revoke execution on\n-- record_customer_payment_splits(uuid, uuid, numeric, date, text, jsonb)."}	payment_split_rpc_contract
67	{"-- Enforce the four operator choices across every financial write path.\n--\n-- Supported choices: cash, credit, bank transfer, mobile wallet.\n-- `split` remains a document result written by the split RPCs, not a selectable\n-- method. Retired catalogue rows and enum values stay available for historical\n-- records, while new settings and financial writes reject them.\n\nBEGIN","CREATE TABLE IF NOT EXISTS public.payment_method_settings_archive (\n  payment_method_id text PRIMARY KEY,\n  settings_snapshot jsonb NOT NULL,\n  archived_at timestamptz NOT NULL DEFAULT now(),\n  archived_by uuid DEFAULT auth.uid()\n)","ALTER TABLE public.payment_method_settings_archive ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS payment_method_settings_archive_finance_read\n  ON public.payment_method_settings_archive","CREATE POLICY payment_method_settings_archive_finance_read\n  ON public.payment_method_settings_archive\n  FOR SELECT TO authenticated\n  USING (\n    public.has_role(auth.uid(), 'owner') OR\n    public.has_role(auth.uid(), 'manager') OR\n    public.has_role(auth.uid(), 'accountant')\n  )","REVOKE ALL ON public.payment_method_settings_archive FROM PUBLIC, anon, authenticated","GRANT SELECT ON public.payment_method_settings_archive TO authenticated","GRANT ALL ON public.payment_method_settings_archive TO service_role","-- Keep retired catalogue identities for history, but never let a new active\n-- tender enter through direct SQL or a future authoring path.\nCREATE OR REPLACE FUNCTION public.guard_four_payment_method_catalogue()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  IF NEW.is_active AND NEW.id NOT IN (\n    'cash', 'credit', 'bank_transfer', 'mobile_money', 'split'\n  ) THEN\n    RAISE EXCEPTION 'Only four payment methods and the split document state may remain active: %', NEW.id\n      USING ERRCODE = 'check_violation';\n  END IF;\n  RETURN NEW;\nEND $$","DROP TRIGGER IF EXISTS trg_four_payment_method_catalogue ON public.payment_methods","CREATE TRIGGER trg_four_payment_method_catalogue\n  BEFORE INSERT OR UPDATE OF id, is_active ON public.payment_methods\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_catalogue()","-- Settings can only be created for the four operator-facing methods.\nCREATE OR REPLACE FUNCTION public.payment_method_settings_guard()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_allowed text[];\nBEGIN\n  IF NEW.payment_method_id NOT IN ('cash', 'credit', 'bank_transfer', 'mobile_money') THEN\n    RAISE EXCEPTION 'Only the four approved payment methods may have settings: %', NEW.payment_method_id\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  SELECT allowed_contexts INTO v_allowed\n    FROM public.payment_methods\n   WHERE id = NEW.payment_method_id AND is_active = true;\n\n  IF v_allowed IS NULL THEN\n    RAISE EXCEPTION 'Payment method is missing or inactive: %', NEW.payment_method_id\n      USING ERRCODE = 'foreign_key_violation';\n  END IF;\n  IF NEW.enabled_contexts IS NOT NULL AND NOT (NEW.enabled_contexts <@ v_allowed) THEN\n    RAISE EXCEPTION 'Payment method contexts exceed the catalogue policy: %', NEW.payment_method_id\n      USING ERRCODE = 'check_violation';\n  END IF;\n  RETURN NEW;\nEND $$","-- A central server-side write guard. Historical rows remain readable; the\n-- operator and financial RPCs can only resolve one of the four canonical IDs.\nCREATE OR REPLACE FUNCTION public.resolve_writable_payment_method(\n  p_value text,\n  p_context text,\n  p_strict_context boolean DEFAULT true\n)\nRETURNS text\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_id text;\n  v_stored text;\n  v_enabled boolean;\nBEGIN\n  v_id := public.payment_method_resolve_id(p_value);\n  IF v_id IS NULL THEN\n    RAISE EXCEPTION 'طريقة دفع غير صالحة: %', coalesce(p_value, '(فارغ)')\n      USING ERRCODE = 'check_violation';\n  END IF;\n  IF v_id NOT IN ('cash', 'credit', 'bank_transfer', 'mobile_money') THEN\n    RAISE EXCEPTION 'طريقة الدفع متوقفة. الخيارات المعتمدة: نقداً، آجل، تحويل بنكي، محفظة إلكترونية.'\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  SELECT coalesce(s.enabled, true) AND m.is_active\n    INTO v_enabled\n    FROM public.payment_methods m\n    LEFT JOIN public.payment_method_settings s ON s.payment_method_id = m.id\n   WHERE m.id = v_id;\n  IF v_enabled IS NOT TRUE THEN\n    RAISE EXCEPTION 'طريقة الدفع غير مفعّلة: %', p_value\n      USING ERRCODE = 'check_violation';\n  END IF;\n  IF p_strict_context AND NOT public.payment_method_is_allowed(v_id, coalesce(p_context, 'pos')) THEN\n    RAISE EXCEPTION 'طريقة الدفع غير مسموح بها في هذا القسم: %', p_value\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  v_stored := public.payment_method_legacy_id(v_id);\n  IF v_stored IS NULL THEN\n    RAISE EXCEPTION 'تعذّر تحويل طريقة الدفع إلى قيمة قاعدة بيانات: %', p_value\n      USING ERRCODE = 'check_violation';\n  END IF;\n  RETURN v_stored;\nEND $$","-- Financial table triggers close legacy RPC/direct-write gaps. Unchanged\n-- historical values remain editable for unrelated fields; changing or adding\n-- a payment value must pass the same four-method guard.\nCREATE OR REPLACE FUNCTION public.guard_four_payment_method_write()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_method text := nullif(lower(btrim(to_jsonb(NEW) ->> TG_ARGV[0])), '');\n  v_method_id text;\n  v_context text := TG_ARGV[2];\n  v_old_method text;\n  v_old_id text;\n  v_allow_split boolean := coalesce(TG_ARGV[3], 'false')::boolean;\n  v_allow_credit boolean := coalesce(TG_ARGV[4], 'false')::boolean;\n  v_resolved text;\nBEGIN\n  IF TG_OP = 'UPDATE' THEN\n    v_old_method := nullif(lower(btrim(to_jsonb(OLD) ->> TG_ARGV[0])), '');\n    IF TG_ARGV[1] <> '' THEN\n      v_old_id := nullif(to_jsonb(OLD) ->> TG_ARGV[1], '');\n    END IF;\n  END IF;\n  IF TG_ARGV[1] <> '' THEN\n    v_method_id := nullif(to_jsonb(NEW) ->> TG_ARGV[1], '');\n  END IF;\n  IF TG_OP = 'UPDATE'\n     AND v_method IS NOT DISTINCT FROM v_old_method\n     AND v_method_id IS NOT DISTINCT FROM v_old_id THEN\n    RETURN NEW;\n  END IF;\n  IF v_method IS NULL THEN\n    RETURN NEW;\n  END IF;\n  IF v_method = 'split' AND v_allow_split THEN\n    RETURN NEW;\n  END IF;\n  IF v_method = 'credit' AND NOT v_allow_credit THEN\n    RAISE EXCEPTION 'Credit is not a tender for this transaction type'\n      USING ERRCODE = 'check_violation';\n  END IF;\n  IF v_context = 'document' THEN\n    v_context := CASE to_jsonb(NEW) ->> 'document_type'\n      WHEN 'purchase_invoice' THEN 'purchases'\n      WHEN 'milling_service_document' THEN 'sales'\n      ELSE NULL\n    END;\n  END IF;\n  v_resolved := public.resolve_writable_payment_method(\n    coalesce(v_method_id, v_method), v_context, true\n  );\n  IF v_resolved IS DISTINCT FROM v_method THEN\n    RAISE EXCEPTION 'Payment method identity does not match stored value (%)', v_method\n      USING ERRCODE = 'check_violation';\n  END IF;\n  RETURN NEW;\nEND $$","DROP TRIGGER IF EXISTS trg_four_payment_methods_sales_invoice ON public.sales_invoices","CREATE TRIGGER trg_four_payment_methods_sales_invoice\n  BEFORE INSERT OR UPDATE ON public.sales_invoices\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_write('payment_method','payment_method_id','sales','true','true')","DROP TRIGGER IF EXISTS trg_four_payment_methods_purchase_invoice ON public.purchase_invoices","CREATE TRIGGER trg_four_payment_methods_purchase_invoice\n  BEFORE INSERT OR UPDATE ON public.purchase_invoices\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_write('payment_method','payment_method_id','purchases','true','true')","DROP TRIGGER IF EXISTS trg_four_payment_methods_customer_payment ON public.customer_payments","CREATE TRIGGER trg_four_payment_methods_customer_payment\n  BEFORE INSERT OR UPDATE ON public.customer_payments\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_write('payment_method','payment_method_id','customer_collection','false','false')","DROP TRIGGER IF EXISTS trg_four_payment_methods_customer_split ON public.customer_payment_splits","CREATE TRIGGER trg_four_payment_methods_customer_split\n  BEFORE INSERT OR UPDATE ON public.customer_payment_splits\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_write('method','payment_method_id','customer_collection','false','false')","DROP TRIGGER IF EXISTS trg_four_payment_methods_purchase_milling_split ON public.payment_splits","CREATE TRIGGER trg_four_payment_methods_purchase_milling_split\n  BEFORE INSERT OR UPDATE ON public.payment_splits\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_write('method','payment_method_id','document','false','false')","DROP TRIGGER IF EXISTS trg_four_payment_methods_expense ON public.expenses","CREATE TRIGGER trg_four_payment_methods_expense\n  BEFORE INSERT OR UPDATE ON public.expenses\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_write('payment_method','','expenses','false','false')","DROP TRIGGER IF EXISTS trg_four_payment_methods_expense_payment ON public.expense_payments","CREATE TRIGGER trg_four_payment_methods_expense_payment\n  BEFORE INSERT OR UPDATE ON public.expense_payments\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_write('payment_method','payment_method_id','expenses','false','false')","DROP TRIGGER IF EXISTS trg_four_payment_methods_sales_return ON public.sales_returns","CREATE TRIGGER trg_four_payment_methods_sales_return\n  BEFORE INSERT OR UPDATE ON public.sales_returns\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_write('refund_method','payment_method_id','sales_returns','false','false')","DROP TRIGGER IF EXISTS trg_four_payment_methods_purchase_return ON public.purchase_returns","CREATE TRIGGER trg_four_payment_methods_purchase_return\n  BEFORE INSERT OR UPDATE ON public.purchase_returns\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_write('refund_method','payment_method_id','purchase_returns','false','true')","DROP TRIGGER IF EXISTS trg_four_payment_methods_supplier_payment ON public.supplier_payments","CREATE TRIGGER trg_four_payment_methods_supplier_payment\n  BEFORE INSERT OR UPDATE ON public.supplier_payments\n  FOR EACH ROW EXECUTE FUNCTION public.guard_four_payment_method_write('payment_method','','purchases','false','false')","REVOKE ALL ON FUNCTION public.guard_four_payment_method_write() FROM PUBLIC, anon, authenticated, service_role","REVOKE ALL ON FUNCTION public.guard_four_payment_method_catalogue() FROM PUBLIC, anon, authenticated, service_role","REVOKE ALL ON FUNCTION public.create_tenant_payment_method(text, text, text, text, text, text[], boolean)\n  FROM PUBLIC, anon, authenticated, service_role",COMMIT,"-- Rollback: restore payment_method_settings_guard() and\n-- resolve_writable_payment_method() from migration 16; drop the listed guards\n-- and trigger function, restore execute on create_tenant_payment_method, and\n-- retain payment_method_settings_archive until any archived settings are restored."}	enforce_four_payment_methods
